if test "${1:-}" = "--source-only"; then
    _E131_SOURCE_ONLY=1
    case $- in *e*) _E131_CALLER_ERREXIT=1 ;; *) _E131_CALLER_ERREXIT=0 ;; esac
    _E131_CALLER_SET_STATE="$(set +o)"
    if test "$_E131_CALLER_ERREXIT" = 1; then _E131_CALLER_SET_STATE="$_E131_CALLER_SET_STATE; set -o errexit"; fi
