        _compile_kernel_mainline_legacy_e53 "${1:-bbr3}";
    fi
}
# EEX3-FUNCTION core _compile_kernel_mainline_legacy_e53
_compile_kernel_mainline_legacy_e53() {
    error '旧“最新主线+在线可变补丁”入口无法做提交/摘要双重固定，E204已失败闭锁。';
