# EEX3-FUNCTION core _ring_parse_value_e52
_ring_parse_value_e52() {
    local section="$1" key="$2" iface="$3";
    ethtool -g "$iface" 2> /dev/null | awk -v section="$section" -v key="$key" '
        $0 ~ section {flag=1; next}
        flag && $0 ~ /^[[:space:]]*[A-Za-z ]+:/ {
            gsub(/^[[:space:]]+|[[:space:]]+$/, "", $1)
            if ($1 == key ":" && $2 ~ /^[0-9]+$/) {print $2; exit}
        }
    '
}
# EEX3-FUNCTION core _safe_jq_write
_safe_jq_write() {
    test -s "$CONFIG" || { 
        error "未找到配置文件：$CONFIG";
        return 1
    };
    command -v jq > /dev/null 2>&1 || { 
        error "缺少 jq。";
        return 1
    };
    local tmp err bdir;
    tmp=$(_e118_mktemp safejq.json) || return 1;
    err=$(_e118_mktemp safejq.err) || return 1;
    if ! jq "$@" "$CONFIG" > "$tmp" 2> "$err"; then
        error "jq 修改失败，当前配置未改变。";
        sed 's/^/    /' "$err" 2> /dev/null | tail -n 80 || true;
        return 1;
    fi;
    test -s "$tmp" && jq empty "$tmp" > /dev/null 2>&1 || { 
        error "jq 产物为空或不是合法 JSON。";
        return 1
    };
    _e118_xray_test_config "$tmp" 1 || return 1;
    bdir=$(_e116_backup_state "before_safe_jq") || { 
        error "无法创建提交前快照，拒绝写入。";
        return 1
    };
    if _e118_commit_config "$tmp" "$bdir" preserve; then
        info "配置事务提交通过；快照：$bdir";
        return 0;
    fi;
    return 1
}
# EEX3-FUNCTION core _select_ss_method
_select_ss_method() {
