apply_ring_max_adaptive_default() {
    local iface oldrx oldtx rc=0 tx p;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    oldrx=$(_ring_cur_rx_e52 "$iface" 2> /dev/null || true);
    oldtx=$(_ring_cur_tx_e52 "$iface" 2> /dev/null || true);
    _e137_prepare || return 1;
    tx="$E137_BACKUP_DIR/ring-$(date +%Y%m%d_%H%M%S)-$$";
    mkdir -p "$tx" || return 1;
    for p in "$E137_RING_SCRIPT" "$E137_RING_SERVICE" "$E137_RING_TIMER";
    do
        _e135_snapshot_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || return 1;
    done;
    _e137_ring_apply_base || rc=1;
    if test "$rc" -ne 0; then
        if [[ "$oldrx" =~ ^[0-9]+$ && "$oldtx" =~ ^[0-9]+$ ]]; then
            ethtool -G "$iface" rx "$oldrx" tx "$oldtx" > /dev/null 2>&1 || true;
        else
            if [[ "$oldrx" =~ ^[0-9]+$ ]]; then
                ethtool -G "$iface" rx "$oldrx" > /dev/null 2>&1 || true;
            fi;
        fi;
        for p in "$E137_RING_SCRIPT" "$E137_RING_SERVICE" "$E137_RING_TIMER";
        do
            _e135_restore_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || true;
        done;
        systemctl daemon-reload > /dev/null 2>&1 || true;
        return 1;
    fi
}
# EEX3-FUNCTION core apply_safe_turbo_defaults
apply_safe_turbo_defaults() {
    local protect sysbackup network_before="" was_active=0;
    test -s "$CONFIG" || { 
        error "config.json不存在。";
        return 1
    };
    protect=$(_e116_backup_state before_safe_turbo_e159) || return 1;
    _e118_save_core_payload "$protect" || return 1;
    sysbackup=$(_e159_new_tx safe-turbo) || return 1;
    _e140_system_snapshot "$sysbackup" || return 1;
    network_before=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2> /dev/null | tail -n1);
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
    was_active=${was_active:-0};
    if ! _e159_apply_safe_turbo_impl || ! systemctl daemon-reload > /dev/null 2>&1; then
        error "安全系统微操失败，恢复执行前网络、系统与Xray状态。";
        _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true;
        return 1;
    fi;
    if test "$was_active" = 1; then
        if ! systemctl restart xray.service > /dev/null 2>&1 || ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "安全系统微操后Xray运行探针失败，自动回滚。";
            _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true;
            return 1;
        fi;
    else
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            error "安全系统微操意外启动原本停止的Xray，自动回滚。";
            _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true;
            return 1;
        fi;
    fi;
    _e142_prune_transactions "$sysbackup" "$protect" || true;
    _e159_prune_system_tx "$sysbackup";
    info "安全系统微操已通过Xray启停保持与运行态探针。"
}
# EEX3-FUNCTION core apply_txqueue_3000_default
apply_txqueue_3000_default() {
    local IP_CMD IFACE;
    IP_CMD=$(command -v ip || echo "");
    test -n "$IP_CMD" || return 0;
    IFACE=$(ip route get 1.1.1.1 2> /dev/null | awk '{print $5; exit}' || echo "");
    test -n "$IFACE" || return 0;
    $IP_CMD link set "$IFACE" txqueuelen 3000 2> /dev/null || true;
    cat > /etc/systemd/system/txqueue.service <<EOF_TXQ_V38
[Unit]
Description=Set TX Queue Length for Stable Low Latency
After=network.target

[Service]
Type=oneshot
ExecStart=$IP_CMD link set $IFACE txqueuelen 3000
RemainAfterExit=true

[Install]
WantedBy=multi-user.target
EOF_TXQ_V38

    systemctl daemon-reload > /dev/null 2>&1 || true;
    systemctl enable txqueue > /dev/null 2>&1 || true;
    systemctl restart txqueue > /dev/null 2>&1 || true
}
