backup_config() {
    _e118_prepare_dirs || return 1;
    test -s "$CONFIG" || return 0;
    local ts out;
    ts=$(date +%Y%m%d_%H%M%S_%N 2> /dev/null || date +%Y%m%d_%H%M%S);
    out="$BACKUP_DIR/config_${ts}_$$.json";
    install -m 0600 "$CONFIG" "$out" || return 1;
    local -a files=();
    mapfile -t files < <(find "$BACKUP_DIR" -maxdepth 1 -type f -name 'config_*.json' -printf '%T@ %p\n' 2> /dev/null | sort -nr | awk 'NR>20{sub(/^[^ ]+ /,""); print}');
    test "${#files[@]}" -gt 0 && rm -f -- "${files[@]}" 2> /dev/null || true;
    echo "$out"
}
