# EEX3-FUNCTION core check_irq_state
check_irq_state() {
    local CORES=$(nproc 2> /dev/null || echo 1);
    if test "$CORES" -lt 2 2> /dev/null; then
        echo "unsupported";
        return;
    fi;
    local IFACE=$(ip route get 1.1.1.1 2> /dev/null | awk '{print $5; exit}' || echo "");
    if test -z "$IFACE"; then
        echo "false";
        return;
    fi;
    local irq=$(grep "$IFACE" /proc/interrupts 2> /dev/null | head -n 1 | awk '{print $1}' | tr -d ':' || echo "");
    if test -n "$irq"; then
        local want=$(cpu_mask_all "$CORES" | tr 'A-F' 'a-f');
        local got=$(cat "/proc/irq/$irq/smp_affinity" 2> /dev/null | tr -d ',' | tr 'A-F' 'a-f' || echo "");
        if test "$got" = "$want"; then
            echo "true";
        else
            echo "false";
        fi;
    else
        echo "false";
    fi
}
