                else
                    _safe_jq_write '(.inbounds[]? | select(. != null) | select(.protocol=="vless" and .streamSettings?.security=="reality") | .streamSettings.realitySettings.maxTimeDiff) = 60000';
                    systemctl restart xray > /dev/null 2>&1 || true;
                    info "Reality 时间锁已开启。";
                fi;
                _e52_pause
            ;;
            12)
                enable_dnsmasq_cache_safely;
                systemctl restart xray > /dev/null 2>&1 || true;
                _e52_pause
            ;;
            13)
                enable_thp_never_default;
                _e52_pause
            ;;
            14)
                apply_hotupdate_fast_sysctl;
                _e52_pause
            ;;
            15)
                enable_cpu_performance_default;
                _e52_pause
            ;;
            16)
                toggle_ring;
                _e52_pause
            ;;
            17)
                toggle_cake_qdisc;
                update_hw_boot_script;
                _e52_pause
            ;;
            18)
                toggle_cake_flag "ack_filter";
                update_hw_boot_script;
                _e52_pause
            ;;
            19)
                toggle_cake_flag "ecn";
                update_hw_boot_script;
                _e52_pause
            ;;
            20)
                toggle_cake_flag "wash";
                update_hw_boot_script;
                _e52_pause
            ;;
            21)
                toggle_gso;
                _e52_pause
            ;;
            22)
                toggle_irq;
                _e52_pause
            ;;
            23)
                enable_zram_default;
                _e52_pause
            ;;
            24)
                enable_journald_volatile_default;
                _e52_pause
            ;;
            25)
                apply_process_priority_default;
                systemctl restart xray > /dev/null 2>&1 || true;
                _e52_pause
            ;;
            26)
                _turn_on_app;
                systemctl restart xray > /dev/null 2>&1 || true;
                info "应用层 1-11 已幂等激活。";
                _e52_pause
            ;;
            27)
                apply_safe_turbo_defaults;
                systemctl restart xray > /dev/null 2>&1 || true;
                info "安全系统级微操已幂等落地。";
                _e52_pause
            ;;
            28)
                _turn_on_app;
                apply_safe_turbo_defaults;
                systemctl restart xray > /dev/null 2>&1 || true;
                info "极速稳态一键打通完成。";
                _e52_pause
            ;;
            0)
                return
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_bbr_body_replace_menu_e89
do_bbr_body_replace_menu_e89() {
    while true; do
        clear;
        title "V198e105：BBR 本体替换 / 自定义编译中心";
        echo "  自动建议：$(_e89_bbr_detect 2> /dev/null || true)";
        echo "  当前替换路线：$(_e102_bbr_mode_text)";
        echo "";
