        echo "  2) 模块型/自动路由：普通 Linux 主线 BBR v1 → 自定义全部参数 → 替换 bbr";
        echo "  3) 模块型/自动路由：BBR3 / XanMod → 自定义全部参数 → 替换 bbr";
        echo "  4) 查看已备份的原版 BBR / 系统 TCP 设置";
        echo "  5) 无损切换回最近一次编译前 BBR / 或旧内核 GRUB 回滚提示";
        echo "  6) 查看当前拥塞控制 / qdisc / BBR 状态";
        echo "  7) 解释/检查内置型 y 与模块型 m 的区别";
        echo "  8 ) 解释：为什么完整编译会卡在 i40e/iavf/ice";
        echo "  9) 内置型 BBR：完整内核源码补丁编译新内核（1000MB门槛）";
        echo "  0) 返回主菜单";
        read -rp "请选择: " opt || true;
        case "${opt:-}" in 
            1)
                _e89_bbr_detect;
                _e102_pause
            ;;
            2)
                _e102_bbrv1_flow
            ;;
            3)
                _e102_bbr3_flow
            ;;
            4)
                _e89_bbr_show_backups;
                _e102_pause
            ;;
            5)
                _e89_bbr_rollback_latest || warn "如果本次是内置型整内核编译，请通过云厂商 VNC/GRUB 选择旧内核回滚。";
                _e102_pause
            ;;
            6)
                _e89_bbr_status;
                _e102_pause
            ;;
            7)
                _e102_builtin_explain;
                _e102_pause
            ;;
            8)
                if declare -F _e97_why_intel_compile_stuck > /dev/null 2>&1; then
                    _e97_why_intel_compile_stuck;
                else
                    _e102_builtin_explain;
                fi;
                _e102_pause
            ;;
            9)
                _e102_builtin_bbr_full_compile_menu
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_change_dns
do_change_dns() {
    title "系统 DNS 急救：静态 DNS 模式（会停用 Dnsmasq）";
    warn "本功能适合 DNS 已坏、127.0.0.1 无监听、或不想运行本地缓存服务时使用。";
    warn "如果需要本地内存缓存加速，请使用 10→6→12 的 Dnsmasq 稳态模式；两者不会同时启用。";
    echo -e "  1) Cloudflare + Google + OpenDNS  ${cyan}(推荐急救)${none}";
    echo -e "  2) OpenDNS + Google + Cloudflare";
    echo -e "  0) 手动输入一个主 DNS IPv4";
    local sel ns1 ns2 ns3;
    read -rp "请选择 DNS 方案 (默认 1): " sel || true;
    sel=${sel:-1};
    case "$sel" in 
        2)
            ns1="208.67.224.224";
            ns2="8.8.8.8";
            ns3="1.1.1.1"
        ;;
        0)
            while true; do
                read -rp "请输入主 DNS IP (例如 1.1.1.1): " ns1 || true;
                if [[ $ns1 =~ ^([0-9]{1,2}|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\.([0-9]{1,2}|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\.([0-9]{1,2}|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\.([0-9]{1,2}|1[0-9][0-9]|2[0-4][0-9]|25[0-5])$ ]]; then
                    break;
                fi;
                print_red "DNS IP 格式错误，请重新输入。";
            done;
            ns2="1.1.1.1";
            ns3="8.8.8.8"
        ;;
        *)
            ns1="1.1.1.1";
            ns2="8.8.8.8";
            ns3="208.67.224.224"
        ;;
    esac;
    systemctl stop dnsmasq > /dev/null 2>&1 || true;
    systemctl disable dnsmasq > /dev/null 2>&1 || true;
    systemctl stop resolvconf > /dev/null 2>&1 || true;
    systemctl disable resolvconf > /dev/null 2>&1 || true;
    systemctl stop systemd-resolved > /dev/null 2>&1 || true;
    systemctl disable systemd-resolved > /dev/null 2>&1 || true;
    e67_install_static_dns_guard "$ns1" "$ns2" "$ns3";
    if getent hosts api.ipify.org > /dev/null 2>&1 || getent hosts google.com > /dev/null 2>&1; then
        info "静态 DNS 急救模式已生效，并已设置开机恢复。";
    else
        warn "DNS 仍异常；IP 网络若可达，请检查云厂商防火墙、上游 UDP/53 或系统策略。";
    fi;
    info "当前 resolv.conf：";
    sed 's/^/    /' /etc/resolv.conf 2> /dev/null || true
}
