# EEX3-FUNCTION core do_install_xanmod_main_official
do_install_xanmod_main_official() {
    local branch level pkg code confirm tx keytmp keygpg kver installed_before=0 rc=0;
    title "V199e152：XanMod官方APT包安全事务";
    [[ "$(uname -m)" = x86_64 ]] || { 
        error "仅支持x86_64。";
        return 1
    };
    echo "  1) Main  2) LTS  3) RT";
    read -rp "选择分支 (默认2=LTS): " branch || true;
    case "${branch:-2}" in 
        1)
            branch=main
        ;;
        2)
            branch=lts
        ;;
        3)
            branch=rt
        ;;
        *)
            return 1
        ;;
    esac;
    level=$(detect_x86_64_level);
    test "$level" -le 3 || level=3;
    pkg=$(_e131_xanmod_pkg_name "$branch" "$level") || { 
        error "CPU x64v$level没有该分支官方包，拒绝向上尝试更高指令集。";
        return 1
    };
    code=$(_e131_os_codename);
    test -n "$code" || return 1;
    command dpkg-query -W -f='${Status}' "$pkg" 2> /dev/null | grep -q 'install ok installed' && installed_before=1 || true;
    test "$installed_before" = 0 || { 
        error "$pkg 已安装；本入口拒绝覆盖同名包。";
        return 1
    };
    echo "  codename=$code branch=$branch cpu=x64v$level package=$pkg";
    read -rp "输入 INSTALL-XANMOD 确认: " confirm || true;
    test "$confirm" = INSTALL-XANMOD || return 0;
    tx=$(_e152_new_tx xanmod-apt) || return 1;
    _e135_snapshot_file "$E131_XANMOD_KEYRING" "$tx/keyring" || return 1;
    _e135_snapshot_file "$E131_XANMOD_LIST" "$tx/list" || return 1;
    _e135_snapshot_file /etc/apt/sources.list.d/xanmod-kernel.list "$tx/legacy-list" || return 1;
    _e135_snapshot_file /etc/apt/keyrings/xanmod.gpg "$tx/legacy-key" || return 1;
    rm -f -- "$E131_XANMOD_LIST" /etc/apt/sources.list.d/xanmod-kernel.list /etc/apt/keyrings/xanmod.gpg 2> /dev/null || true;
    export DEBIAN_FRONTEND=noninteractive;
    install -d -m 0755 /etc/apt/keyrings || rc=1;
    test "$rc" -ne 0 || apt-get update -o Acquire::Retries=3 || rc=1;
    test "$rc" -ne 0 || apt-get install -y --no-install-recommends ca-certificates curl gnupg lsb-release || rc=1;
    keytmp=$(_e118_mktemp xanmod-archive-e152.key) || rc=1;
    keygpg=$(_e118_mktemp xanmod-archive-e152.gpg) || rc=1;
    test "$rc" -ne 0 || curl --proto '=https' --tlsv1.2 -fL --connect-timeout 10 --max-time 120 https://dl.xanmod.org/archive.key -o "$keytmp" || rc=1;
    test "$rc" -ne 0 || gpg --batch --show-keys "$keytmp" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || gpg --batch --yes --dearmor -o "$keygpg" "$keytmp" || rc=1;
    test "$rc" -ne 0 || install -m 0644 "$keygpg" "$E131_XANMOD_KEYRING" || rc=1;
    test "$rc" -ne 0 || printf 'deb [signed-by=%s] http://deb.xanmod.org %s main\n' "$E131_XANMOD_KEYRING" "$code" | _e131_atomic_text_file "$E131_XANMOD_LIST" 0644 || rc=1;
    test "$rc" -ne 0 || apt-get update -o Acquire::Retries=3 || rc=1;
    test "$rc" -ne 0 || apt-cache show "$pkg" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || apt-get install -y "$pkg" || rc=1;
    if test "$rc" = 0; then
        kver=$(ls -t /boot/vmlinuz-*xanmod* 2> /dev/null | head -n1 | sed 's|.*/vmlinuz-||');
        test -n "$kver" && _kernel_pre_reboot_verify_e52 "$kver" || rc=1;
    fi;
    test "$rc" -ne 0 || update-grub > /dev/null 2>&1 || rc=1;
    if test "$rc" -ne 0; then
        command dpkg-query -W -f='${Status}' "$pkg" 2> /dev/null | grep -q 'install ok installed' && apt-get purge -y "$pkg" > /dev/null 2>&1 || true;
        _e135_restore_file "$E131_XANMOD_KEYRING" "$tx/keyring" || true;
        _e135_restore_file "$E131_XANMOD_LIST" "$tx/list" || true;
        _e135_restore_file /etc/apt/sources.list.d/xanmod-kernel.list "$tx/legacy-list" || true;
        _e135_restore_file /etc/apt/keyrings/xanmod.gpg "$tx/legacy-key" || true;
        apt-get update > /dev/null 2>&1 || true;
        error "XanMod APT事务失败并已尝试恢复仓库及本次新装包。恢复材料：$tx";
        return 1;
    fi;
    info "XanMod官方包已安装并验证：$kver；未改写GRUB_DEFAULT，未自动重启。"
}
# EEX3-FUNCTION core do_ip_connection_audit_menu
