}
# EEX3-FUNCTION core do_json_config_audit_e92
do_json_config_audit_e92() {
    _e92_prepare_dirs;
    title "V198e92：JSON 配置写入审计器";
    if test ! -f "$CONFIG"; then
        error "未找到配置文件：$CONFIG";
        _e92_pause;
        return 1;
    fi;
    echo "配置路径：$CONFIG";
    echo "文件权限：$(stat -c '%a %U:%G' "$CONFIG" 2> /dev/null || echo unknown)";
    echo "文件大小：$(wc -c < "$CONFIG" 2> /dev/null || echo 0) bytes";
    echo "";
    if jq empty "$CONFIG" > /dev/null 2>&1; then
        info "JSON 语法：通过";
    else
        error "JSON 语法：失败";
    fi;
    if _e92_xray_test_config "$CONFIG"; then
        info "Xray 配置测试：通过";
    else
        error "Xray 配置测试：失败";
    fi;
    echo "";
    echo "结构摘要：$(_e92_json_meta_line "$CONFIG")";
    echo "";
    echo "Inbound 概览：";
    jq -r '.inbounds[]? | "  tag=\(.tag // "-") protocol=\(.protocol // "-") listen=\(.listen // "-") port=\(.port // "-")"' "$CONFIG" 2> /dev/null || true;
    echo "";
    echo "Outbound 概览：";
    jq -r '.outbounds[]? | "  tag=\(.tag // "-") protocol=\(.protocol // "-")"' "$CONFIG" 2> /dev/null || true;
    _e92_pause
}
