# EEX3-FUNCTION core do_status_menu
do_status_menu() {
    while true; do
        clear;
        title "主控台: 监控、账单及 IP 审计核心（V198e66）";
        echo "  1) [系统守护] 追踪主线程服务健康率";
        echo "  2) [全网穿透] 检测基础外网及监听位态";
        echo "  3) [总计账单] 调取网卡出入核算账册 (vnstat)";
        echo "  4) [IP审计] 客户端/目标站/单连接/单IP记账与限制中心";
        echo "  5) [底层微操] 人工赋予 Xray 高配内存抢占锁 (Nice)";
        echo "  6) [数据留痕] 翻阅应用层历史指令";
        echo "  7) [故障分析] 获取崩溃回溯报告";
        echo "  8) [灾难规避] 无损拉取快照与覆盖回退";
        echo "  0) 返回中控区";
        hr;
        local s="";
        read -rp "执行指令: " s || true;
        case "${s:-}" in 
            1)
                systemctl status xray --no-pager || true;
                _e52_pause
            ;;
            2)
                echo -e "\n  [公网物理层] IP地址: ${green}$SERVER_IP${none}\n  [解析路由流] nameserver: ";
                grep "^nameserver" /etc/resolv.conf 2> /dev/null || echo "    读取被拒";
                echo -e "  [协议通讯录] 内网穿透口:";
                ss -tlnp 2> /dev/null | grep xray || echo "    进程无响应";
                _e52_pause
            ;;
            3)
                if ! command -v vnstat > /dev/null 2>&1; then
                    warn "未安装 vnstat。";
                    _e52_pause;
                    continue;
                fi;
                clear;
                title "底层网卡流量计费审计中心";
                local m_day;
                m_day=$(grep -E "^[[:space:]]*MonthRotate" /etc/vnstat.conf 2> /dev/null | awk '{print $2}' | head -n 1 | tr -d '\r\n');
                if test -z "$m_day"; then
                    m_day="1 (默认)";
                fi;
                echo -e "  [全局锚定] 结算日：${cyan}自然月 $m_day 号${none}";
                hr;
                ( vnstat -m 3 2> /dev/null || vnstat -m 2> /dev/null || true ) | sed -e 's/estimated/模型预估/ig' -e 's/rx/接收流量/ig' -e 's/tx/出站推送/ig' -e 's/total/并发总计/ig' -e 's/daily/日志按日/ig' -e 's/monthly/汇总按月/ig';
                hr;
                echo "  1) 指定特定日期进行跨月账单裁断 (1-31)";
                echo "  2) 下达历史账单日跑量穿梭溯源 (如 2026-04)";
                echo "  0) 返回主操作台";
                local vn_opt="";
                read -rp "  键入操作码: " vn_opt || true;
                if test "$vn_opt" = "1"; then
                    local d_day="";
                    read -rp "请决定强制切断日 (1-31): " d_day || true;
                    if [[ "$d_day" =~ ^[0-9]+$ ]] && test "$d_day" -ge 1 2> /dev/null && test "$d_day" -le 31 2> /dev/null; then
                        sed -i '/^[#[:space:]]*MonthRotate/d' /etc/vnstat.conf 2> /dev/null || true;
                        echo "MonthRotate $d_day" >> /etc/vnstat.conf;
                        systemctl restart vnstat 2> /dev/null || true;
                        info "计费核心配置更新，流量将于每个月 $d_day 日清空重算。";
                    else
                        error "跨界拦截，数字溢出。";
                    fi;
                    _e52_pause;
                else
                    if test "$vn_opt" = "2"; then
                        local d_month="";
                        read -rp "穿梭位点 (如 $(date +%Y-%m)): " d_month || true;
                        if test -z "$d_month"; then
                            vnstat -d 2> /dev/null | sed -e 's/estimated/预估/ig' -e 's/rx/接收/ig' -e 's/tx/出站/ig' -e 's/total/总计/ig' -e 's/daily/按日/ig' -e 's/monthly/按月/ig' || true;
                        else
                            vnstat -d 2> /dev/null | grep -iE "($d_month| day |estimated|--)" | sed -e 's/estimated/预估/ig' -e 's/rx/接收/ig' -e 's/tx/出站/ig' -e 's/total/总计/ig' -e 's/daily/按日/ig' -e 's/monthly/按月/ig' || true;
                        fi;
                        _e52_pause;
                    fi;
                fi
            ;;
            4)
                do_ip_connection_audit_menu
            ;;
            5)
                while true; do
                    clear;
                    title "强制篡夺 CPU 底层分配表";
                    local limit_file="/etc/systemd/system/xray.service.d/limits.conf";
                    local current_nice="-10";
                    if test -f "$limit_file" && grep -q "^Nice=" "$limit_file" 2> /dev/null; then
                        current_nice=$(awk -F'=' '/^Nice=/ {print $2}' "$limit_file" | head -n 1 || echo "-10");
                    fi;
                    echo -e "  Xray 内核抢占权值定位: ${cyan}${current_nice}${none} (建议域: -10 到 -20)";
                    hr;
                    local new_nice="";
                    read -rp "  写入系统优先级设定 (q 退出): " new_nice || true;
                    if test "$new_nice" = "q" || test "$new_nice" = "Q"; then
                        break;
                    fi;
                    if [[ "$new_nice" =~ ^-[1-2][0-9]$ ]] && test "$new_nice" -ge -20 2> /dev/null && test "$new_nice" -le -10 2> /dev/null; then
                        mkdir -p /etc/systemd/system/xray.service.d 2> /dev/null || true;
                        grep -q '^\[Service\]' "$limit_file" 2> /dev/null || echo '[Service]' > "$limit_file";
                        if grep -q '^Nice=' "$limit_file" 2> /dev/null; then
                            sed -i "s/^Nice=.*/Nice=$new_nice/" "$limit_file";
                        else
                            echo "Nice=$new_nice" >> "$limit_file";
                        fi;
                        systemctl daemon-reload > /dev/null 2>&1 || true;
                        info "指令确认下发，正在重启 Xray 验证...";
                        systemctl restart xray > /dev/null 2>&1 || true;
                        info "权重交接完成。";
                        _e52_pause;
                        break;
                    else
                        error "数据溢出限制门槛！";
                        sleep 2;
                    fi;
                done
            ;;
            6)
                clear;
                title "全局核心通讯日志流";
                tail -n 50 "$LOG_DIR/xray.log" 2> /dev/null || echo "  档案库真空。";
                _e52_pause
            ;;
            7)
                clear;
                title "全系统深空错误异常告警";
                tail -n 30 "$LOG_DIR/error.log" 2> /dev/null || echo "  无异常。";
                _e52_pause
            ;;
            8)
                clear;
                title "高可用与灾难管理快照备份";
                ls -t "$BACKUP_DIR"/config_*.json 2> /dev/null || echo "当前冷备库空白。";
                echo -e "\n  r) 系统反卷引擎：强行以最近正确的冷库替换现网逻辑\n  c) 物理抽帧冷封存：为当下的全局网络环境创建防灾记录\n  0) 取消动作";
                local bopt="";
                read -rp "抉择代码: " bopt || true;
                if test "$bopt" = "r" || test "$bopt" = "R"; then
                    restore_latest_backup;
                fi;
                if test "$bopt" = "c" || test "$bopt" = "C"; then
                    backup_config;
                    info "已生成永久保存副本。";
                    _e52_pause;
                fi
            ;;
            0)
                return
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_summary
do_summary() {
    if test "${E242_SUMMARY_SUPPRESS:-0}" = 1; then
        E242_SUMMARY_PENDING=1;
        E183_SUMMARY_EMITTED=1;
        return 0;
    fi;
    _e242_summary_base "$@"
}
# EEX3-FUNCTION core do_summary_e116_base
do_summary_e116_base() {
    title "V198e79 节点链接与多维信息输出中心";
    local ip;
    ip=$(_get_ip);
    if test "$ip" = "获取失败" || test -z "$ip"; then
        warn "公网 IP 自动探测失败；链接中的地址请手动替换为 VPS 公网 IP。";
        ip="YOUR_SERVER_IP";
    fi;
    if ! e76_config_semantic_ok "$CONFIG" > /dev/null 2>&1; then
        error "当前 config.json 未通过有效节点检查，无法可靠输出。建议 xrv → 1 重新搭建。";
        return 1;
    fi;
    local found=0;
    while IFS= read -r inbound; do
        test -n "$inbound" || continue;
        found=1;
        local tag port uuid flow security email email_u network;
        tag=$(echo "$inbound" | jq -r '.tag // "vless"');
        port=$(echo "$inbound" | jq -r '.port');
        uuid=$(echo "$inbound" | jq -r '.settings.clients[0].id // .settings.users[0].id // empty');
        flow=$(echo "$inbound" | jq -r '.settings.clients[0].flow // .settings.users[0].flow // ""');
        email=$(echo "$inbound" | jq -r '.settings.clients[0].email // .settings.users[0].email // "VLESS"');
        email_u=$(e77_urlencode "$email");
        security=$(echo "$inbound" | jq -r '.streamSettings.security // "none"');
        network=$(echo "$inbound" | jq -r '.streamSettings.network // "tcp"');
        hr;
        if test "$security" = "reality"; then
            local sni pub sid fp link;
            sni=$(echo "$inbound" | jq -r '.streamSettings.realitySettings.serverNames[0] // empty');
            pub=$(cat "$PUBKEY_FILE" 2> /dev/null || true);
            sid=$(echo "$inbound" | jq -r '.streamSettings.realitySettings.shortIds[0] // empty');
            fp="chrome";
            printf "  ${cyan}【VLESS Reality Vision 默认推荐】${none}\n";
            printf "  ${yellow}%-16s${none} %s\n" "XTLS/Vision:" "${flow:-xtls-rprx-vision}";
            printf "  ${yellow}%-16s${none} %s\n" "地址:" "$ip";
            printf "  ${yellow}%-16s${none} %s\n" "端口:" "$port";
            printf "  ${yellow}%-16s${none} %s\n" "UUID:" "$uuid";
            printf "  ${yellow}%-16s${none} %s\n" "SNI:" "$sni";
            printf "  ${yellow}%-16s${none} %s\n" "PublicKey:" "$pub";
            printf "  ${yellow}%-16s${none} %s\n" "ShortId:" "$sid";
            link="vless://${uuid}@${ip}:${port}?encryption=none&flow=${flow:-xtls-rprx-vision}&security=reality&sni=${sni}&fp=${fp}&pbk=${pub}&sid=${sid}&type=tcp#${email_u}";
            echo -e "\n  ${cyan}配置导入链接:${none}\n  $link\n";
            if command -v qrencode > /dev/null 2>&1; then
                qrencode -m 2 -t UTF8 "$link";
            fi;
        else
            local dec enc enc_u link profile_line x_path x_path_u type_part;
            dec=$(echo "$inbound" | jq -r '.settings.decryption // "none"');
            if test "$dec" != "none" && test -n "$dec" && test "$dec" != "null"; then
                enc=$(cat "$E77_VLESSENC_CLIENT_FILE" 2> /dev/null || true);
                profile_line=$(cat "$E79_VLESSENC_MODE_FILE" 2> /dev/null || echo "unknown|未知|${network}|unknown|unknown");
                printf "  ${cyan}【VLESSENC Vision 自选】${none}\n";
                printf "  ${yellow}%-16s${none} %s\n" "模式:" "$profile_line";
                printf "  ${yellow}%-16s${none} %s\n" "传输:" "$network";
                printf "  ${yellow}%-16s${none} %s\n" "地址:" "$ip";
                printf "  ${yellow}%-16s${none} %s\n" "端口:" "$port";
                printf "  ${yellow}%-16s${none} %s\n" "UUID:" "$uuid";
                printf "  ${yellow}%-16s${none} %s\n" "Flow:" "${flow:-xtls-rprx-vision}";
                if test -n "$enc"; then
                    printf "  ${yellow}%-16s${none} %s\n" "Encryption:" "$enc";
                    enc_u=$(e77_urlencode "$enc");
                    if test "$network" = "xhttp"; then
                        x_path=$(echo "$inbound" | jq -r '.streamSettings.xhttpSettings.path // empty');
                        if test -z "$x_path" || test "$x_path" = "null"; then
                            x_path=$(cat "$E79_VLESSENC_XHTTP_PATH_FILE" 2> /dev/null || true);
                        fi;
                        x_path_u=$(e77_urlencode "$x_path");
                        type_part="type=xhttp&path=${x_path_u}&mode=auto";
                        printf "  ${yellow}%-16s${none} %s\n" "XHTTP path:" "$x_path";
                    else
                        type_part="type=tcp";
                    fi;
                    link="vless://${uuid}@${ip}:${port}?encryption=${enc_u}&flow=${flow:-xtls-rprx-vision}&security=none&${type_part}#${email_u}";
                    echo -e "\n  ${cyan}实验导入链接:${none}\n  $link\n";
                    warn "VLESSENC Vision 属于实验项；客户端不支持时请回到 Reality Vision 或 SS2022。";
                    if command -v qrencode > /dev/null 2>&1; then
                        qrencode -m 2 -t UTF8 "$link";
                    fi;
                else
                    warn "未找到 $E77_VLESSENC_CLIENT_FILE，无法输出客户端 encryption。";
                fi;
            fi;
        fi;
    done < <(jq -c '.inbounds[]? | select(.protocol=="vless")' "$CONFIG" 2> /dev/null || true);
    while IFS= read -r ss_inbound; do
        test -n "$ss_inbound" || continue;
        found=1;
        local s_port s_pass s_method b64 link_ss tag_u;
        tag_u=$(e77_urlencode "${REMARK_NAME:-xp-reality}-SS2022");
        s_port=$(echo "$ss_inbound" | jq -r '.port');
        s_pass=$(echo "$ss_inbound" | jq -r '.settings.password // empty');
        s_method=$(echo "$ss_inbound" | jq -r '.settings.method // "2022-blake3-aes-128-gcm"');
        hr;
        printf "  ${cyan}【SS2022 轻量备用】${none}\n";
        printf "  ${yellow}%-16s${none} %s\n" "地址:" "$ip";
        printf "  ${yellow}%-16s${none} %s\n" "端口:" "$s_port";
        printf "  ${yellow}%-16s${none} %s\n" "密码:" "$s_pass";
        printf "  ${yellow}%-16s${none} %s\n" "加密规格:" "$s_method";
        b64=$(printf '%s:%s' "$s_method" "$s_pass" | base64 | tr -d '\n\r' || echo "");
        link_ss="ss://${b64}@${ip}:${s_port}#${tag_u}";
        echo -e "\n  ${cyan}配置导入链接:${none}\n  $link_ss\n";
        if command -v qrencode > /dev/null 2>&1; then
            qrencode -m 2 -t UTF8 "$link_ss";
        fi;
    done < <(jq -c '.inbounds[]? | select(.protocol=="shadowsocks")' "$CONFIG" 2> /dev/null || true);
    if test "$found" -eq 0; then
        warn "未发现可输出的 VLESS / Shadowsocks inbound。";
        return 1;
    fi
}
# EEX3-FUNCTION core do_sys_init_menu
do_sys_init_menu() {
    _e182_advanced_menu
}
# EEX3-FUNCTION core do_tc_bandwidth_menu_e93
do_tc_bandwidth_menu_e93() {
    _e93_install_tc_component || true;
    while true; do
        clear;
        title "V198e93：TC 带宽控制模块（出口上限 / 启停 / 开机自启）";
        local iface qdisc enabled active mbit tenable restore;
        iface="$(_e93_default_iface 2> /dev/null || echo "")";
        qdisc="";
        if test -n "$iface"; then
            qdisc=$(tc qdisc show dev "$iface" 2> /dev/null | head -n 1 || true);
        fi;
        enabled=$(systemctl is-enabled xray-tc-limit-e93.service 2> /dev/null || echo "disabled");
        active=$(systemctl is-active xray-tc-limit-e93.service 2> /dev/null || echo "inactive");
        tenable=$(awk -F= '/^TC_ENABLE=/{gsub(/"/,"",$2); print $2}' "$E93_TC_CONF" 2> /dev/null || echo "0");
        mbit=$(awk -F= '/^TC_EGRESS_MBIT=/{gsub(/"/,"",$2); print $2}' "$E93_TC_CONF" 2> /dev/null || echo "");
        restore=$(awk -F= '/^TC_RESTORE_QDISC=/{gsub(/"/,"",$2); print $2}' "$E93_TC_CONF" 2> /dev/null || echo "fq");
        echo -e "  默认出口网卡: ${cyan}${iface:-未知}${none}";
        echo -e "  当前 root qdisc: ${cyan}${qdisc:-未读取}${none}";
        echo -e "  TC配置启用: ${cyan}${tenable:-0}${none} | 服务: ${cyan}${active}/${enabled}${none}";
        echo -e "  当前出口上限: ${cyan}${mbit:-未设置}${none} Mbit/s | 停用恢复: ${cyan}${restore:-fq}${none}";
        hr;
        echo "  1) 查看 TC / qdisc / class / stats 当前状态";
        echo "  2) 设置出口总上限，并立即开启";
        echo "  3) 只写入出口总上限配置，不立即开启";
        echo "  4) 按当前配置立即开启 TC 限速";
        echo "  5) 立即关闭 TC 限速，恢复默认 fq，并保留配置";
        echo "  6) 开启开机自动启用 TC 限速";
        echo "  7) 关闭开机自动启用 TC 限速";
        echo "  8) 恢复默认：关闭限速 + 禁用开机自启 + 配置改为不启用";
        echo "  9) 删除 e93 TC 组件（服务/脚本/配置）";
        echo "  10) 查看 TC/BBR/fq/cake 关系说明";
        echo "  0) 返回主菜单";
        hr;
        local opt="";
        read -rp "请选择: " opt || true;
        case "${opt:-}" in 
            1)
                "$E93_TC_SCRIPT" status || true;
                _e93_pause
            ;;
            2)
                local bw="";
                read -rp "请输入出口总上限 Mbit/s，例如 80、100、300、800: " bw || true;
                if _e93_tc_write_conf "$bw" 1 "auto" "fq"; then
                    "$E93_TC_SCRIPT" apply || warn "TC 应用失败，请查看：$E93_TC_LOG";
                fi;
                _e93_pause
            ;;
            3)
                local bw="";
                read -rp "请输入出口总上限 Mbit/s，仅写配置不应用: " bw || true;
                _e93_tc_write_conf "$bw" 1 "auto" "fq" || true;
                _e93_pause
            ;;
            4)
                if ! grep -q '^TC_ENABLE=1' "$E93_TC_CONF" 2> /dev/null; then
                    warn "当前 TC_ENABLE 不是 1。将尝试按配置开启；若未设置带宽会失败。";
                    sed -i 's/^TC_ENABLE=.*/TC_ENABLE=1/' "$E93_TC_CONF" 2> /dev/null || true;
                fi;
                "$E93_TC_SCRIPT" apply || warn "TC 应用失败，请检查带宽上限和网卡。";
                _e93_pause
            ;;
            5)
                "$E93_TC_SCRIPT" stop || true;
                sed -i 's/^TC_ENABLE=.*/TC_ENABLE=0/' "$E93_TC_CONF" 2> /dev/null || true;
                info "已关闭当前 TC 限速，配置保留但默认不启用。";
                _e93_pause
            ;;
            6)
                systemctl enable xray-tc-limit-e93.service > /dev/null 2>&1 || true;
                info "已开启开机自动启用 TC 限速。";
                _e93_pause
            ;;
            7)
                systemctl disable xray-tc-limit-e93.service > /dev/null 2>&1 || true;
                info "已关闭开机自动启用 TC 限速。";
                _e93_pause
            ;;
            8)
                systemctl disable --now xray-tc-limit-e93.service > /dev/null 2>&1 || true;
                "$E93_TC_SCRIPT" stop || true;
                _e93_tc_write_conf "" 0 "auto" "fq" || true;
                info "已恢复默认：TC 不启用、不开机自启、root qdisc 尝试恢复 fq。";
                _e93_pause
            ;;
            9)
                systemctl disable --now xray-tc-limit-e93.service > /dev/null 2>&1 || true;
                "$E93_TC_SCRIPT" stop > /dev/null 2>&1 || true;
                rm -f "$E93_TC_SERVICE" "$E93_TC_SCRIPT" "$E93_TC_CONF" 2> /dev/null || true;
                systemctl daemon-reload > /dev/null 2>&1 || true;
                info "已删除 e93 TC 组件。";
                _e93_pause
            ;;
            10)
                cat <<'EOF'
TC 带宽控制说明：

1. 本模块用于限制 VPS 出口总带宽，不是提速器。
2. 启用后，默认出口网卡 root qdisc 会由 HTB 接管。
3. HTB 负责总上限，叶子队列优先挂 fq；fq 能较好配合 BBR pacing。
4. 如果你正在使用 CAKE，启用本模块会与 CAKE root qdisc 冲突。
5. 推荐限速到“晚高峰稳定速度”的 85%-95%，避免跑满端口制造排队和丢包。
6. 关闭时会尝试恢复 fq；“恢复默认”会同时禁用开机自启并把 TC_ENABLE=0。
EOF

                _e93_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。"
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_tc_bandwidth_menu_e94
do_tc_bandwidth_menu_e94() {
    _e94_install_tc_component || true;
    while true; do
        clear;
        title "V198e94：TC 带宽控制模块（出口上限 / 启停 / 开机自启）";
        local iface qdisc enabled active mbit tenable restore conf_iface;
        iface="$(_e94_default_iface 2> /dev/null || echo "")";
        qdisc="";
        if test -n "$iface"; then
            qdisc=$(tc qdisc show dev "$iface" 2> /dev/null | head -n 1 || true);
        fi;
        enabled=$(systemctl is-enabled xray-tc-limit-e94.service 2> /dev/null || echo "disabled");
        active=$(systemctl is-active xray-tc-limit-e94.service 2> /dev/null || echo "inactive");
        tenable="$(_e94_tc_current_conf_value TC_ENABLE)";
        tenable="${tenable:-0}";
        mbit="$(_e94_tc_current_conf_value TC_EGRESS_MBIT)";
        restore="$(_e94_tc_current_conf_value TC_RESTORE_QDISC)";
        restore="${restore:-fq}";
        conf_iface="$(_e94_tc_current_conf_value TC_IFACE)";
        conf_iface="${conf_iface:-auto}";
        echo -e "  默认出口网卡: ${cyan}${iface:-未知}${none}";
        echo -e "  当前 root qdisc: ${cyan}${qdisc:-未读取}${none}";
        echo -e "  TC配置启用: ${cyan}${tenable}${none} | 服务: ${cyan}${active}/${enabled}${none}";
        echo -e "  配置网卡: ${cyan}${conf_iface}${none} | 出口上限: ${cyan}${mbit:-未设置}${none} Mbit/s | 停用恢复: ${cyan}${restore}${none}";
        hr;
        echo "  1) 查看 TC / qdisc / class / stats 当前状态";
        echo "  2) 设置出口总上限，并立即开启";
        echo "  3) 只写入出口总上限配置，不立即开启";
        echo "  4) 按当前配置立即开启 TC 限速";
        echo "  5) 立即关闭 TC 限速，恢复默认 qdisc，并保留配置";
        echo "  6) 开启开机自动启用 TC 限速（要求已有有效上限）";
        echo "  7) 关闭开机自动启用 TC 限速";
        echo "  8) 恢复默认：关闭限速 + 禁用开机自启 + 配置改为不启用";
        echo "  9) 查看 e94 TC 日志";
        echo "  10) 删除 e94 TC 组件（服务/脚本/配置）";
        echo "  11) 查看 TC/BBR/fq/cake 关系说明";
        echo "  0) 返回主菜单";
        hr;
        local opt="";
        read -rp "请选择: " opt || true;
        case "${opt:-}" in 
            1)
                "$E94_TC_SCRIPT" status || true;
                _e94_pause
            ;;
            2)
                if _e94_tc_prompt_conf 1; then
                    "$E94_TC_SCRIPT" apply || warn "TC 应用失败，请查看：$E94_TC_LOG";
                fi;
                _e94_pause
            ;;
            3)
                _e94_tc_prompt_conf 0 || true;
                info "已只写入配置；TC_ENABLE=0，不会立即限速。";
                _e94_pause
            ;;
            4)
                if _e94_tc_enable_config_inplace; then
                    "$E94_TC_SCRIPT" apply || warn "TC 应用失败，请检查带宽上限和网卡。";
                fi;
                _e94_pause
            ;;
            5)
                "$E94_TC_SCRIPT" stop || true;
                sed -i 's/^TC_ENABLE=.*/TC_ENABLE=0/' "$E94_TC_CONF" 2> /dev/null || true;
                info "已关闭当前 TC 限速，配置保留但默认不启用。";
                _e94_pause
            ;;
            6)
                if _e94_tc_enable_config_inplace; then
                    systemctl enable xray-tc-limit-e94.service > /dev/null 2>&1 || true;
                    info "已开启开机自动启用 TC 限速。";
                    warn "注意：开机自启只会在 TC_ENABLE=1 且上限有效时生效。";
                fi;
                _e94_pause
            ;;
            7)
                systemctl disable xray-tc-limit-e94.service > /dev/null 2>&1 || true;
                info "已关闭开机自动启用 TC 限速；当前 qdisc 不会被此操作立即改变。";
                _e94_pause
            ;;
            8)
                systemctl disable --now xray-tc-limit-e94.service > /dev/null 2>&1 || true;
                "$E94_TC_SCRIPT" stop || true;
                _e94_tc_write_conf "" 0 "auto" "fq" || true;
                info "已恢复默认：TC 不启用、不开机自启、root qdisc 尝试恢复 fq。";
                _e94_pause
            ;;
            9)
                tail -n 80 "$E94_TC_LOG" 2> /dev/null || warn "暂无日志：$E94_TC_LOG";
                _e94_pause
            ;;
            10)
                systemctl disable --now xray-tc-limit-e94.service > /dev/null 2>&1 || true;
                "$E94_TC_SCRIPT" stop > /dev/null 2>&1 || true;
                rm -f "$E94_TC_SERVICE" "$E94_TC_SCRIPT" "$E94_TC_CONF" 2> /dev/null || true;
                systemctl daemon-reload > /dev/null 2>&1 || true;
                info "已删除 e94 TC 组件。";
                _e94_pause
            ;;
            11)
                cat <<'EOF'
TC 带宽控制说明：

1. 本模块用于限制 VPS 出口总带宽，不是提速器。
2. 启用后，默认出口网卡 root qdisc 会由 HTB 接管。
3. HTB 负责总上限，叶子队列优先挂 fq；fq 能较好配合 BBR pacing。
4. 如果你正在使用 CAKE，启用本模块会与 CAKE root qdisc 冲突。
5. 推荐限速到“晚高峰稳定速度”的 85%-95%，避免跑满端口制造排队和丢包。
6. 关闭时会按配置尝试恢复 fq/fq_codel/pfifo_fast/cake；“恢复默认”会同时禁用开机自启并把 TC_ENABLE=0。
7. “只写配置不立即开启”会写 TC_ENABLE=0；必须选 4 或 6 才会改为 TC_ENABLE=1。
EOF

                _e94_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。"
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_tc_bandwidth_menu_e95
do_tc_bandwidth_menu_e95() {
    _e95_install_tc_component || true;
    while true; do
        clear;
        title "V198e95：TC 带宽控制模块（统一接管 / 精细上限 / 默认不启用）";
        local iface qdisc enabled active mbit tenable restore conf_iface leaf;
        iface="$(_e95_default_iface 2> /dev/null || echo "")";
        qdisc="$(_e95_root_qdisc_line "$iface")";
        enabled=$(systemctl is-enabled xray-tc-limit-e95.service 2> /dev/null || echo "disabled");
        active=$(systemctl is-active xray-tc-limit-e95.service 2> /dev/null || echo "inactive");
        tenable="$(_e95_tc_current_conf_value TC_ENABLE)";
        tenable="${tenable:-0}";
        mbit="$(_e95_tc_current_conf_value TC_EGRESS_MBIT)";
        restore="$(_e95_tc_current_conf_value TC_RESTORE_QDISC)";
        restore="${restore:-fq}";
        leaf="$(_e95_tc_current_conf_value TC_LEAF_QDISC)";
        leaf="${leaf:-fq}";
        conf_iface="$(_e95_tc_current_conf_value TC_IFACE)";
        conf_iface="${conf_iface:-auto}";
        echo -e "  默认出口网卡: ${cyan}${iface:-未知}${none}";
        echo -e "  当前 root qdisc: ${cyan}${qdisc:-未读取}${none}";
        echo -e "  e95 TC配置启用: ${cyan}${tenable}${none} | e95服务: ${cyan}${active}/${enabled}${none}";
        echo -e "  配置网卡: ${cyan}${conf_iface}${none} | 出口上限: ${cyan}${mbit:-未设置}${none} Mbit/s | leaf/rest: ${cyan}${leaf}/${restore}${none}";
        echo -e "  旧版TC状态: ${yellow}$(_e95_tc_service_state e93) | $(_e95_tc_service_state e94)${none}";
        hr;
        echo "  1) 查看 e95 TC / qdisc / class / stats 当前状态";
        echo "  2) 设置出口总上限，并立即开启";
        echo "  3) 只写入出口总上限配置，不立即开启";
        echo "  4) 按当前配置立即开启 TC 限速";
        echo "  5) 立即关闭 e95 TC 限速，恢复默认 qdisc，并保留配置";
        echo "  6) 开启 e95 开机自动启用 TC 限速（要求已有有效上限）";
        echo "  7) 关闭 e95 开机自动启用 TC 限速";
        echo "  8) 恢复默认：关闭 e95 + 禁用 e93/e94/e95 自启 + 配置改为不启用";
        echo "  9) 统一停用旧版 e93/e94/e95 TC（需要 YES 确认）";
        echo "  10) 查看 e95 TC 日志";
        echo "  11) 删除 e95 TC 组件（服务/脚本/配置）";
        echo "  12) 查看 TC/BBR/fq/cake 关系说明";
        echo "  0) 返回主菜单";
        hr;
        local opt="";
        read -rp "请选择: " opt || true;
        case "${opt:-}" in 
            1)
                "$E95_TC_SCRIPT" status || true;
                _e95_pause
            ;;
            2)
                if _e95_tc_prompt_conf 1; then
                    "$E95_TC_SCRIPT" apply || warn "TC 应用失败，请查看：$E95_TC_LOG";
                fi;
                _e95_pause
            ;;
            3)
                _e95_tc_prompt_conf 0 || true;
                info "已只写入配置；TC_ENABLE=0，不会立即限速，不会开机自动启用。";
                _e95_pause
            ;;
            4)
                if _e95_tc_enable_config_inplace; then
                    "$E95_TC_SCRIPT" apply || warn "TC 应用失败，请检查带宽上限和网卡。";
                fi;
                _e95_pause
            ;;
            5)
                "$E95_TC_SCRIPT" stop || true;
                sed -i 's/^TC_ENABLE=.*/TC_ENABLE=0/' "$E95_TC_CONF" 2> /dev/null || true;
                info "已关闭 e95 当前 TC 限速，配置保留但默认不启用。";
                _e95_pause
            ;;
            6)
                if _e95_tc_enable_config_inplace; then
                    systemctl enable xray-tc-limit-e95.service > /dev/null 2>&1 || true;
                    info "已开启 e95 开机自动启用 TC 限速。";
                    warn "注意：开机自启只会在 TC_ENABLE=1 且上限有效时生效。";
                fi;
                _e95_pause
            ;;
            7)
                systemctl disable xray-tc-limit-e95.service > /dev/null 2>&1 || true;
                info "已关闭 e95 开机自动启用 TC 限速；当前 qdisc 不会被此操作立即改变。";
                _e95_pause
            ;;
            8)
                for v in e95 e94 e93;
                do
                    systemctl disable --now "xray-tc-limit-${v}.service" > /dev/null 2>&1 || true;
                    if test -x "/usr/local/bin/xray-tc-limit-${v}.sh"; then
                        "/usr/local/bin/xray-tc-limit-${v}.sh" stop > /dev/null 2>&1 || true;
                    fi;
                done;
                _e95_tc_write_conf "" 0 "auto" "fq" "fq" || true;
                info "已恢复默认：e93/e94/e95 TC 均不启用、不开机自启，root qdisc 已尝试恢复 fq。";
                _e95_pause
            ;;
            9)
                _e95_stop_legacy_tc_if_confirmed || true;
                _e95_pause
            ;;
            10)
                tail -n 120 "$E95_TC_LOG" 2> /dev/null || warn "暂无日志：$E95_TC_LOG";
                _e95_pause
            ;;
            11)
                systemctl disable --now xray-tc-limit-e95.service > /dev/null 2>&1 || true;
                "$E95_TC_SCRIPT" stop > /dev/null 2>&1 || true;
                rm -f "$E95_TC_SERVICE" "$E95_TC_SCRIPT" "$E95_TC_CONF" 2> /dev/null || true;
                systemctl daemon-reload > /dev/null 2>&1 || true;
                info "已删除 e95 TC 组件。";
                _e95_pause
            ;;
            12)
                cat <<'EOF'
TC 带宽控制说明：

1. 本模块用于限制 VPS 出口总带宽，不是提速器。
2. 启用后，默认出口网卡 root qdisc 会由 HTB 接管；请看“实际 root qdisc”，不要只看 sysctl default_qdisc。
3. HTB 负责总上限，叶子队列可选 fq/fq_codel；fq 通常更适合 BBR pacing。
4. 如果你正在使用 CAKE，启用本模块会与 CAKE root qdisc 冲突。
5. 推荐限速到“晚高峰稳定速度”的 85%-95%，避免跑满端口制造排队和丢包。
6. 只写配置不会开启限速，TC_ENABLE=0；必须选 4 或 6 才会改为 TC_ENABLE=1。
7. e95 菜单会显示 e93/e94 旧版 TC 残留状态；恢复默认会禁用旧版自启，统一停用需要 YES 确认。
EOF

                _e95_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。"
                sleep 1
            ;;
        esac;
    done
}
