# EEX3-FUNCTION core do_traffic_monitor
do_traffic_monitor() {
    _e135_prepare || return 1;
    local iface n list;
    iface=$(_e135_default_iface);
    test -n "$iface" || { 
        error "无法识别默认出口网卡。";
        return 1
    };
    _e135_vnstat_prepare "$iface" || { 
        error "vnStat初始化失败。";
        return 1
    };
    while true; do
        clear;
        title "V199e137：宿主机流量与Xray连接中心";
        echo "  监控网卡: $iface";
        echo "  说明: vnStat统计整台VPS网卡总流量，不等于Xray独占流量。";
        echo "  1) 今日/本月汇总  2) 实时流量  3) 小时  4) 每日  5) 每月";
        echo "  6) Xray连接与入站端口  7) 数据库健康  8) 选择网卡  9) 设置月结日  0) 返回";
        read -rp "操作: " n || true;
        case "$n" in 
            1)
                vnstat -i "$iface";
                _e135_pause
            ;;
            2)
                vnstat -l -i "$iface" || true;
                _e135_pause
            ;;
            3)
                vnstat -h -i "$iface";
                _e135_pause
            ;;
            4)
                vnstat -d -i "$iface";
                _e135_pause
            ;;
            5)
                vnstat -m -i "$iface";
                _e135_pause
            ;;
            6)
                _e135_xray_connections;
                _e135_pause
            ;;
            7)
                echo "vnStat: $(vnstat --version 2> /dev/null | head -n1)";
                systemctl status vnstat.service --no-pager -n 10 2> /dev/null || systemctl status vnstat --no-pager -n 10 2> /dev/null || true;
                vnstat --iflist 2> /dev/null || true;
                _e135_pause
            ;;
            8)
                list=$(find /sys/class/net -mindepth 1 -maxdepth 1 -printf '%f\n' | grep -v '^lo$');
                printf '%s\n' "$list";
                read -rp "输入网卡名: " iface || true;
                test -d "/sys/class/net/$iface" || { 
                    error "网卡不存在。";
                    iface=$(_e135_default_iface);
                    _e135_pause;
                    continue
                };
                printf '%s\n' "$iface" > "$E135_TRAFFIC_IFACE_FILE";
                _e135_vnstat_prepare "$iface" || true
            ;;
            9)
                _e135_set_month_rotate;
                _e135_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_txqueuelen_opt
do_txqueuelen_opt() {
    title "网卡发送队列 (TX Queue) 调优";
    local IP_CMD=$(command -v ip || echo "");
    if test -z "$IP_CMD"; then
        error "系统缺失 iproute2 (ip 命令) 核心组件。";
        local _p="";
        read -rp "按 Enter 返回..." _p || true;
        return 1;
    fi;
    local IFACE=$(ip route get 1.1.1.1 2> /dev/null | awk '{print $5; exit}' || echo "");
    if test -z "$IFACE"; then
        error "无法定位系统默认出口网卡。";
        local _p="";
        read -rp "按 Enter 返回..." _p || true;
        return 1;
    fi;
    info "正在修改 $IFACE 发送队列长度至 3000...";
    $IP_CMD link set "$IFACE" txqueuelen 3000 2> /dev/null || true;
    cat > /etc/systemd/system/txqueue.service <<EOF
[Unit]
Description=Set TX Queue Length for Low Latency
After=network.target

[Service]
Type=oneshot
ExecStart=$IP_CMD link set $IFACE txqueuelen 3000
RemainAfterExit=true

[Install]
WantedBy=multi-user.target
EOF

    systemctl daemon-reload > /dev/null 2>&1 || true;
    systemctl enable txqueue > /dev/null 2>&1 || true;
    systemctl start txqueue > /dev/null 2>&1 || true;
    local CHECK_QLEN=$($IP_CMD link show "$IFACE" 2> /dev/null | grep -o 'qlen [0-9]*' | awk '{print $2}' || echo "");
    if test "$CHECK_QLEN" = "3000"; then
        info "已成功将网卡底层并发队列长度扩容至 3000 级。";
    else
        warn "当前虚拟机或网卡驱动不支持调节 txqueuelen。";
    fi;
    local _p="";
    read -rp "按 Enter 键返回主菜单..." _p || true
}
# EEX3-FUNCTION core do_uninstall
do_uninstall() {
    ( local confirm="" tx archive="" rc=0 restore_rc=0 E204_UNINSTALL_SWAP_KIND=none;
    title 'V199e266：受控卸载 Xray 环境';
    warn '将独立恢复MTU/MSS/小BBR/完整网络/IPv6/WARP，再删除明确属于本脚本的Xray文件；Cloudflare WARP、dnsmasq和用户Swap软件包保留。';
    read -rp '请输入 DELETE-XRAY 确认: ' confirm || true;
    test "$confirm" = DELETE-XRAY || { 
        info '已取消，系统未修改。';
        return 0
    };
    if _e204_legacy_small_bbr_owner > /dev/null 2>&1; then
        error '检测到旧版小BBR；请先用对应旧版脚本退出档位，验证恢复后再卸载。';
        return 1;
    fi;
    _e220_mss_preflight_readonly || { 
        error '存在未恢复的MSS事务；受控卸载不会删除其恢复证据。请先运行 --mss-recover。';
        return 1
    };
    tx=$(_e204_new_tx uninstall) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_service_snapshot fail2ban.service > "$tx/fail2ban.before" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    if ! _e204_ssh_access_preflight; then
        error 'SSH防自锁预检失败，恢复预检可能产生的防火墙变更。';
        if ! _e140_system_restore "$tx/system"; then
            _e204_mark_critical uninstall-preflight "$tx/system" 'SSH preflight rollback failed' || true;
            error "严重：SSH预检回滚失败；快照：$tx/system";
        fi;
        _e204_tx_close "$tx" || true;
        return 1;
    fi;
    archive="/root/xray-before-uninstall-e220-$(date +%Y%m%d_%H%M%S)-$$.tgz";
    if test -d "$CONFIG_DIR"; then
        _e142_create_uninstall_archive "$archive" || { 
            error '卸载前归档未通过读回；未执行删除。';
            _e204_tx_close "$tx" || true;
            return 1
        };
    fi;
    if _e214_mtu_any_state; then
        _e214_mtu_disable force || rc=1;
    fi;
    test "$rc" -ne 0 || ! _e218_mss_any_evidence || _e218_mss_disable || rc=1;
    if _e202_small_bbr_active; then
        _e202_small_bbr_disable force || rc=1;
    fi;
    test "$rc" -ne 0 || _e142_restore_network_baseline || rc=1;
    test "$rc" -ne 0 || _e140_warp_full_disable force || rc=1;
    if test "$rc" -eq 0 && test "$(_e138_state_get route_enabled 0)" = 1; then
        _e138_warp_disable || rc=1;
    fi;
    test "$rc" -ne 0 || _e182_ipv6_uninstall_restore || rc=1;
    test "$rc" -ne 0 || _e182_remove_native_ssh_config || rc=1;
    test "$rc" -ne 0 || _e204_uninstall_managed_swap || rc=1;
    if test "$rc" -eq 0 && test -x "$E95_TC_SCRIPT"; then
        "$E95_TC_SCRIPT" stop > /dev/null 2>&1 || rc=1;
    fi;
    test "$rc" -ne 0 || _e204_uninstall_stop_owned_units || rc=1;
    if test "$rc" -eq 0; then
        systemctl stop xray.service > /dev/null 2>&1 || true;
        systemctl is-active --quiet xray.service 2> /dev/null && rc=1 || true;
        systemctl disable xray.service > /dev/null 2>&1 || true;
    fi;
    if test "$rc" -eq 0; then
        systemctl stop fail2ban.service > /dev/null 2>&1 || true;
    fi;
    test "$rc" -ne 0 || _e204_uninstall_remove_owned_files || rc=1;
    if test "$rc" -eq 0; then
        rm -f -- "$SYMLINK" "$XRAY_BIN" /etc/systemd/system/xray.service || rc=1;
        rm -rf -- "$CONFIG_DIR" "$DAT_DIR" "$SCRIPT_DIR" "$LOG_DIR" || rc=1;
    fi;
    test "$rc" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    if test "$rc" -eq 0 && command -v fail2ban-client > /dev/null 2>&1; then
        fail2ban-client -t > /dev/null 2>&1 || rc=1;
    fi;
    if test "$rc" -eq 0; then
        _e204_services_restore_file "$tx/fail2ban.before" || rc=1;
    fi;
    if test "$rc" -eq 0 && command -v sshd > /dev/null 2>&1; then
        sshd -t > /dev/null 2>&1 || rc=1;
    fi;
    test "$rc" -ne 0 || { 
        test ! -e "$XRAY_BIN" && test ! -e "$CONFIG"
    } || rc=1;
    test "$rc" -ne 0 || ! systemctl is-active --quiet xray.service 2> /dev/null || rc=1;
    if test "$rc" -eq 0 && test "$E204_UNINSTALL_SWAP_KIND" = swapfile; then
        rm -f -- "$E204_SWAPFILE" || rc=1;
    fi;
    if test "$rc" -eq 0; then
        sysctl --system > /dev/null 2>&1 || warn '其它发行版sysctl文件存在错误；卸载恢复事务本身已完成。';
        info "Xray环境已受控卸载；可读回归档：${archive:-未创建}";
        info "事务快照保留：$tx/system";
        _e204_tx_close "$tx";
        return $?;
    fi;
    error 'E220卸载任一阶段未通过，恢复卸载前完整状态。';
    _e140_system_restore "$tx/system" || restore_rc=1;
    _e204_services_restore_file "$tx/fail2ban.before" || restore_rc=1;
    _e204_restore_managed_swap_runtime "$E204_UNINSTALL_SWAP_KIND" || restore_rc=1;
    if test -s "$CONFIG"; then
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1 || restore_rc=1;
        _e118_xray_test_config "$CONFIG" 1 || restore_rc=1;
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || restore_rc=1;
        fi;
    fi;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical uninstall "$tx/system" 'uninstall rollback/readback failed' || true;
        error "严重：卸载回滚未完整通过；快照：$tx/system";
    else
        info "卸载已取消并恢复到原状态；快照：$tx/system";
    fi;
    _e204_tx_close "$tx" || true;
    return 1 )
}
# EEX3-FUNCTION core do_update_core
do_update_core() {
    local go="" installer logf bdir was_active=0 was_enabled=0 failed=0 rollback=0 enabled_now="";
    title "V199e159：Xray Core手动更新 / 联合回滚";
    _e159_prepare || return 1;
    read -rp "是否从XTLS固定哈希官方安装器更新/修复Xray Core？[y/N]: " go || true;
    [[ "$go" =~ ^[yY]$ ]] || { 
        info "已取消；Core自动更新仍保持关闭。";
        return 0
    };
    test -s "$CONFIG" || { 
        error "没有config.json，无法执行兼容性与回滚验证。";
        return 1
    };
    _e118_xray_test_config "$CONFIG" 1 || return 1;
    bdir=$(_e116_backup_state before_core_update_e159) || return 1;
    _e118_save_core_payload "$bdir" || { 
        error "旧Core/DAT/systemd载荷备份或校验失败，拒绝更新。";
        return 1
    };
    _e127_verify_state_snapshot "$bdir" || return 1;
    was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" | head -n1);
    was_active=${was_active:-0};
    was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$bdir/meta.env" | head -n1);
    was_enabled=${was_enabled:-0};
    [[ "$was_active" =~ ^[01]$ && "$was_enabled" =~ ^[01]$ ]] || return 1;
    E159_CORE_TX_BACKUP="$bdir";
    trap '_e159_core_update_signal INT' INT;
    trap '_e159_core_update_signal TERM' TERM;
    trap '_e159_core_update_signal HUP' HUP;
    installer=$(_e118_mktemp xray-update-e159.sh) || { 
        _e159_core_update_restore_traps;
        return 1
    };
    logf=$(_e118_mktemp xray-update-e159.log) || { 
        _e159_core_update_restore_traps;
        return 1
    };
    if ! _e118_download_official_installer "$installer"; then
        _e159_core_update_restore_traps;
        error "XTLS固定提交安装器下载/哈希/语法校验失败，旧Core未动。";
        return 1;
    fi;
    bash "$installer" install > "$logf" 2>&1 || failed=1;
    test "$failed" -ne 0 || { 
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1
    } || failed=1;
    test "$failed" -ne 0 || e76_ensure_xray_service || failed=1;
    test "$failed" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || failed=1;
    test "$failed" -ne 0 || fix_permissions || failed=1;
    test "$failed" -ne 0 || _e118_xray_test_config "$CONFIG" 1 || failed=1;
    if test "$failed" -eq 0; then
        if test "$was_enabled" = 1; then
            systemctl enable xray.service > /dev/null 2>&1 || failed=1;
        else
            systemctl disable xray.service > /dev/null 2>&1 || failed=1;
        fi;
    fi;
    if test "$failed" -eq 0; then
        enabled_now=$(systemctl is-enabled xray.service 2> /dev/null || true);
        if test "$was_enabled" = 1; then
            case "$enabled_now" in 
                enabled | enabled-runtime | linked | linked-runtime)

                ;;
                *)
                    failed=1
                ;;
            esac;
        else
            case "$enabled_now" in 
                enabled | enabled-runtime | linked | linked-runtime)
                    failed=1
                ;;
            esac;
        fi;
    fi;
    if test "$failed" -eq 0 && test "$was_active" = 1; then
        systemctl restart xray.service > /dev/null 2>&1 || failed=1;
        test "$failed" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || failed=1;
    else
        if test "$failed" -eq 0; then
            systemctl stop xray.service > /dev/null 2>&1 || true;
            systemctl is-active --quiet xray.service 2> /dev/null && failed=1 || true;
        fi;
    fi;
    if test "$failed" -ne 0; then
        error "新Core、权限、配置或运行探针失败，执行联合回滚。";
        tail -n 120 "$logf" 2> /dev/null | sed 's/^/    /' || true;
        _e159_restore_core_update "$bdir" || rollback=1;
        _e159_core_update_restore_traps;
        if test "$rollback" -ne 0; then
            { 
                echo "time=$(date -Is 2> /dev/null || date)";
                echo "operation=core-update";
                echo "core_backup=$bdir";
                echo "installer_log=$logf"
            } > "$E159_CRITICAL_MARKER" 2> /dev/null || true;
            error "严重：Core联合回滚未通过，快照：$bdir";
        fi;
        return 1;
    fi;
    _e159_core_update_restore_traps;
    _e105_disable_xray_core_auto_update || warn "Core自动更新禁用复检未完成，请检查systemd定时器。";
    _e127_prune_core_payload_backups;
    info "Core手动更新完成并保持原服务状态：$($XRAY_BIN version 2> /dev/null | head -n1)"
}
# EEX3-FUNCTION core do_update_core_e105_base
do_update_core_e105_base() {
    title "Xray 主心骨环境内核迭代";
    info "强联通官方源更新通道...";
    if bash -c "$(curl -L -s https://raw.githubusercontent.com/XTLS/Xray-install/main/install-release.sh)" @ install > /dev/null 2>&1; then
        if test -x "$XRAY_BIN"; then
            fix_xray_systemd_limits;
            systemctl restart xray > /dev/null 2>&1 || true;
            local cur_ver=$("$XRAY_BIN" version 2> /dev/null | head -n1 | awk '{print $2}' || echo "检索故障");
            info "全流程覆盖结束，当前主线跃迁到: ${cyan}$cur_ver${none}";
            local _p="";
            read -rp "按 Enter 返回..." _p || true;
            return 0;
        fi;
    fi;
    error "遭遇官方源封锁或 IPv6 数据穿透故障，拉取阻隔。";
    local _p="";
    read -rp "Enter..." _p || true;
    return 1
}
# EEX3-FUNCTION core do_user_manager
do_user_manager() {
    if test "${E204_INTERNAL_SELF_TEST:-0}" = 1 || test "${E214_INTERNAL_SELF_TEST:-0}" = 1; then
        _e242_user_manager_base "$@";
        return $?;
    fi;
    _e242_user_manager_transaction "$@"
}
# EEX3-FUNCTION core do_user_manager_e116_base
do_user_manager_e116_base() {
    while true; do
        title "控制面: 账户生命周期管理";
        if test ! -f "$CONFIG"; then
            error "核心环境未就绪。";
            return;
        fi;
        local clients=$(jq -r '.inbounds[]? | select(. != null) | select(.protocol=="vless") | .settings?.clients[]? | .id + "|" + (.email // "未命名")' "$CONFIG" 2> /dev/null || echo "");
        if test -z "$clients" || test "$clients" = "null"; then
            error "未配置任何可修改的 VLESS 权限。";
            local _p="";
            read -rp "按 Enter 返回..." _p || true;
            return;
        fi;
        local tmp_users="/tmp/xray_users_$$.txt";
        echo "$clients" | awk -F'|' '{print NR"|"$1"|"$2}' > "$tmp_users" || true;
        echo -e "已注册持有人列表：";
        while IFS='|' read -r num uid remark; do
            local utime=$(grep "^$uid|" "$USER_TIME_MAP" 2> /dev/null | cut -d'|' -f2 || echo "");
            if test -z "$utime"; then
                utime="外部输入";
            fi;
            echo -e "  $num) 代号: ${cyan}$remark${none} | 录入日: ${gray}$utime${none} | ID: ${yellow}$uid${none}";
        done < "$tmp_users";
        hr;
        echo "  a) 创建底层用户凭证 (自动分配资源)";
        echo "  m) 强制导入外部迁移用户 (补全历史凭据)";
        echo "  s) 为账户重定向专用的高匿面具 (SNI)";
        echo "  d) 永久撤销账户授权";
        echo "  q) 取消并关闭";
        local uopt="";
        read -rp "输入执行命令: " uopt || true;
        local ip=$(_get_ip || echo "获取失败");
        if test "$uopt" = "a" || test "$uopt" = "A"; then
            local nu=$(cat /proc/sys/kernel/random/uuid 2> /dev/null || "$XRAY_BIN" uuid);
            local ns=$(head -c 8 /dev/urandom | xxd -p | tr -d '\n\r' || echo "");
            local ctime=$(date +"%Y-%m-%d %H:%M");
            local u_remark="";
            read -rp "指定账户备注 (直接回车默认 User-$ns): " u_remark || true;
            if test -z "$u_remark"; then
                u_remark="User-${ns}";
            fi;
            cat > /tmp/new_client.json <<EOF
{ "id": "$nu", "flow": "xtls-rprx-vision", "email": "$u_remark" }
EOF

            _safe_jq_write --argjson new_client "$(< /tmp/new_client.json)" '(.inbounds[]? | select(. != null) | select(.protocol == "vless")) |= (.settings.clients += [$new_client])';
            _safe_jq_write --arg sid "$ns" '(.inbounds[]? | select(. != null) | select(.protocol == "vless")) |= (.streamSettings.realitySettings.shortIds += [$sid])';
            rm -f /tmp/new_client.json 2> /dev/null || true;
            echo "$nu|$ctime" >> "$USER_TIME_MAP";
            ensure_xray_is_alive;
            local vless_node=$(jq -c '.inbounds[]? | select(. != null) | select(.protocol=="vless")' "$CONFIG" 2> /dev/null | head -n 1 || echo "");
            local port=$(echo "$vless_node" | jq -r '.port' 2> /dev/null || echo 443);
            local sni=$(echo "$vless_node" | jq -r '.streamSettings.realitySettings.serverNames[0]' 2> /dev/null || echo "");
            local pub=$(echo "$vless_node" | jq -r '.streamSettings.realitySettings.publicKey' 2> /dev/null || echo "");
            info "创建指令已完成。";
            hr;
            print_node_block "VLESS-Reality (Vision)" "$ip" "$port" "$sni" "$pub" "$ns" "chrome" "$nu";
            local link="vless://${nu}@${ip}:${port}?encryption=none&flow=xtls-rprx-vision&security=reality&sni=${sni}&fp=chrome&pbk=${pub}&sid=${ns}&type=tcp#${u_remark}";
            echo -e "\n  ${cyan}专用节点参数已生成:${none}\n  $link\n";
            local _p="";
            read -rp "按 Enter 继续..." _p || true;
        else
            if test "$uopt" = "m" || test "$uopt" = "M"; then
                local m_remark="";
                read -rp "指定输入的用户备注 (默认 Imported): " m_remark || true;
                if test -z "$m_remark"; then
                    m_remark="Imported";
                fi;
                local m_uuid="";
                read -rp "输入该账户的 UUID: " m_uuid || true;
                if test -z "$m_uuid"; then
                    error "UUID 信息缺失。";
                    continue;
                fi;
                local m_sid="";
                read -rp "输入该账户的 ShortId: " m_sid || true;
                if test -z "$m_sid"; then
                    error "ShortId 信息缺失。";
                    continue;
                fi;
                local ctime=$(date +"%Y-%m-%d %H:%M");
                cat > /tmp/new_client.json <<EOF
{ "id": "$m_uuid", "flow": "xtls-rprx-vision", "email": "$m_remark" }
EOF

                _safe_jq_write --argjson new_client "$(< /tmp/new_client.json)" '(.inbounds[]? | select(. != null) | select(.protocol == "vless")) |= (.settings.clients += [$new_client])';
                _safe_jq_write --arg sid "$m_sid" '(.inbounds[]? | select(. != null) | select(.protocol == "vless")) |= (.streamSettings.realitySettings.shortIds += [$sid])';
                rm -f /tmp/new_client.json 2> /dev/null || true;
                echo "$m_uuid|$ctime" >> "$USER_TIME_MAP";
                local m_sni="";
                read -rp "锁定独立伪装 SNI 域 (回车套用主线设定): " m_sni || true;
                if test -n "$m_sni"; then
                    _safe_jq_write --arg sni "$m_sni" '(.inbounds[]? | select(. != null) | select(.protocol == "vless")) |= (.streamSettings.realitySettings.serverNames += [$sni] | .streamSettings.realitySettings.serverNames |= unique)';
                    sed -i "/^$m_uuid|/d" "$USER_SNI_MAP" 2> /dev/null || true;
                    echo "$m_uuid|$m_sni" >> "$USER_SNI_MAP";
                    info "底层伪装锚定成功: $m_sni";
                else
                    m_sni=$(jq -r '.inbounds[]? | select(. != null) | select(.protocol=="vless") | .streamSettings.realitySettings.serverNames[0] // empty' "$CONFIG" 2> /dev/null | head -n 1 || echo "");
                fi;
                ensure_xray_is_alive;
                local vless_node=$(jq -c '.inbounds[]? | select(. != null) | select(.protocol=="vless")' "$CONFIG" 2> /dev/null | head -n 1 || echo "");
                local port=$(echo "$vless_node" | jq -r '.port' 2> /dev/null || echo 443);
                local pub=$(echo "$vless_node" | jq -r '.streamSettings.realitySettings.publicKey' 2> /dev/null || echo "");
                info "历史权限挂载验证完成。";
                hr;
                print_node_block "VLESS-Reality (Vision)" "$ip" "$port" "$m_sni" "$pub" "$m_sid" "chrome" "$m_uuid";
                local link="vless://${m_uuid}@${ip}:${port}?encryption=none&flow=xtls-rprx-vision&security=reality&sni=${m_sni}&fp=chrome&pbk=${pub}&sid=${m_sid}&type=tcp#${m_remark}";
                echo -e "\n  ${cyan}配置重组链:${none}\n  $link\n";
                local _p="";
                read -rp "按 Enter 继续..." _p || true;
            else
                if test "$uopt" = "s" || test "$uopt" = "S"; then
                    local snum="";
                    read -rp "目标序号: " snum || true;
                    local target_uuid=$(awk -F'|' -v id="${snum:-0}" '$1==id {print $2}' "$tmp_users" 2> /dev/null || echo "");
                    local target_remark=$(awk -F'|' -v id="${snum:-0}" '$1==id {print $3}' "$tmp_users" 2> /dev/null || echo "");
                    if test -n "$target_uuid"; then
                        local u_sni="";
                        read -rp "强制重定向 SNI: " u_sni || true;
                        if test -n "$u_sni"; then
                            _safe_jq_write --arg sni "$u_sni" '(.inbounds[]? | select(. != null) | select(.protocol == "vless")) |= (.streamSettings.realitySettings.serverNames += [$sni] | .streamSettings.realitySettings.serverNames |= unique)';
                            sed -i "/^$target_uuid|/d" "$USER_SNI_MAP" 2> /dev/null || true;
                            echo "$target_uuid|$u_sni" >> "$USER_SNI_MAP";
                            ensure_xray_is_alive;
                            info "$target_remark 面具替换完毕，新特征: $u_sni";
                            local vless_node=$(jq -c '.inbounds[]? | select(. != null) | select(.protocol=="vless")' "$CONFIG" 2> /dev/null | head -n 1 || echo "");
                            local port=$(echo "$vless_node" | jq -r '.port' 2> /dev/null || echo 443);
                            local idx=$((${snum:-0} - 1));
                            local sid=$(echo "$vless_node" | jq -r ".streamSettings.realitySettings.shortIds[$idx] // empty" 2> /dev/null || echo "");
                            local pub=$(echo "$vless_node" | jq -r '.streamSettings.realitySettings.publicKey // empty' 2> /dev/null || echo "");
                            local link="vless://${target_uuid}@${ip}:${port}?encryption=none&flow=xtls-rprx-vision&security=reality&sni=${u_sni}&fp=chrome&pbk=${pub}&sid=${sid}&type=tcp#${target_remark}";
                            echo -e "\n  ${cyan}刷新下发链接:${none}\n  $link\n";
                            local _p="";
                            read -rp "按 Enter 继续..." _p || true;
                        fi;
                    else
                        error "无效寻址序号。";
                    fi;
                else
                    if test "$uopt" = "d" || test "$uopt" = "D"; then
                        local dnum="";
                        read -rp "下达强制吊销许可的序号: " dnum || true;
                        local total=$(wc -l < "$tmp_users" 2> /dev/null || echo "0");
                        if test "${total:-0}" -le 1; then
                            error "核心保护规则已触发：您不能注销唯一驻留节点账户！";
                        else
                            local target_uuid=$(awk -F'|' -v id="${dnum:-0}" '$1==id {print $2}' "$tmp_users" 2> /dev/null || echo "");
                            if test -n "$target_uuid"; then
                                local idx=$((${dnum:-0} - 1));
                                _safe_jq_write --arg uid "$target_uuid" --argjson i "$idx" '(.inbounds[]? | select(. != null) | select(.protocol == "vless")) |= (.settings.clients |= map(select(.id != $uid)) | .streamSettings.realitySettings.shortIds |= del(.[$i]))';
                                sed -i "/^$target_uuid|/d" "$USER_SNI_MAP" 2> /dev/null || true;
                                sed -i "/^$target_uuid|/d" "$USER_TIME_MAP" 2> /dev/null || true;
                                ensure_xray_is_alive;
                                info "权限网剥离成功，$target_uuid 所有相关连接口已永久关闭。";
                            fi;
                        fi;
                    else
                        if test "$uopt" = "q" || test "$uopt" = "Q"; then
                            rm -f "$tmp_users" 2> /dev/null || true;
                            break;
                        fi;
                    fi;
                fi;
            fi;
        fi;
    done
}
# EEX3-FUNCTION core do_xray_speed_diag_menu_e93
do_xray_speed_diag_menu_e93() {
    while true; do
        clear;
        title "V198e93：Xray 跨境链路速度诊断中心";
        local iface cc qdisc pid est mtu;
        iface="$(_e93_default_iface 2> /dev/null || echo "")";
        cc=$(sysctl -n net.ipv4.tcp_congestion_control 2> /dev/null || echo "?");
        qdisc=$(sysctl -n net.core.default_qdisc 2> /dev/null || echo "?");
        pid=$(systemctl show -p MainPID --value xray 2> /dev/null || echo 0);
        est=$(ss -Htan state established 2> /dev/null | wc -l 2> /dev/null || echo 0);
        mtu="?";
        test -n "$iface" && mtu=$(cat /sys/class/net/"$iface"/mtu 2> /dev/null || echo "?");
        echo -e "  默认网卡: ${cyan}${iface:-未知}${none} | MTU: ${cyan}${mtu}${none} | cc/qdisc: ${cyan}${cc}/${qdisc}${none}";
        echo -e "  Xray PID: ${cyan}${pid}${none} | ESTABLISHED: ${cyan}${est}${none}";
        hr;
        echo "  1) 生成完整诊断报告（推荐）";
        echo "  2) CPU / 内存 / FD / 连接数检查";
        echo "  3) RTT / 丢包快速测试";
        echo "  4) HTTP DNS/连接/TLS/TTFB 耗时测试";
        echo "  5) BBR / TCP 连接摘要";
        echo "  6) qdisc / MTU / offload / 网卡队列检查";
        echo "  7) conntrack / 防火墙容量检查";
        echo "  8) 诊断结论说明：应该先看哪一层";
        echo "  0) 返回主菜单";
        hr;
        local opt="";
        read -rp "请选择: " opt || true;
        case "${opt:-}" in 
            1)
                do_xray_speed_diag_report_e93;
                _e93_pause
            ;;
            2)
                do_service_radar_e92 2> /dev/null || true;
                _e93_pause
            ;;
            3)
                echo "[ping 1.1.1.1]";
                _e93_ping_summary 1.1.1.1 8;
                echo "[ping 8.8.8.8]";
                _e93_ping_summary 8.8.8.8 8;
                _e93_pause
            ;;
            4)
                echo "[cloudflare]";
                _e93_http_timing https://www.cloudflare.com;
                echo "[microsoft]";
                _e93_http_timing https://www.microsoft.com;
                echo "[apple]";
                _e93_http_timing https://www.apple.com;
                _e93_pause
            ;;
            5)
                ss -tin 2> /dev/null | grep -iE 'bbr|cubic|reno|rtt|bytes_acked|pacing_rate|delivery_rate|retrans' | head -n 60 || true;
                _e93_pause
            ;;
            6)
                e92_hardware_capability_audit 2> /dev/null || true;
                _e93_pause
            ;;
            7)
                sysctl net.netfilter.nf_conntrack_count net.netfilter.nf_conntrack_max 2> /dev/null || warn "未读取到 conntrack sysctl。";
                dmesg 2> /dev/null | grep -i conntrack | tail -n 10 || true;
                _e93_pause
            ;;
            8)
                cat <<'EOF'
诊断顺序建议：

1. 先看线路：RTT、丢包、晚高峰波动。
2. 再看 Xray：CPU、RSS、FD、连接数、日志。
3. 再看 TCP：BBR 状态、重传、rtt、pacing_rate。
4. 再看队列：fq/cake/HTB 是否冲突、qdisc 是否被覆盖。
5. 再看网卡：MTU、offload、RPS/XPS、虚拟化队列。
6. 最后才调 sysctl/BBR 参数；不要一上来堆大缓冲。
EOF

                _e93_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。"
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_xray_speed_diag_menu_e94
do_xray_speed_diag_menu_e94() {
    while true; do
        clear;
        title "V198e94：Xray 跨境链路速度诊断中心";
        local iface cc qdisc pid est mtu rss cpu fd;
        iface="$(_e94_default_iface 2> /dev/null || echo "")";
        cc=$(sysctl -n net.ipv4.tcp_congestion_control 2> /dev/null || echo "?");
        qdisc=$(sysctl -n net.core.default_qdisc 2> /dev/null || echo "?");
        pid="$(_e94_xray_pid)";
        est=$(ss -Htan state established 2> /dev/null | wc -l 2> /dev/null | awk '{print int($1)}' || echo 0);
        mtu="?";
        test -n "$iface" && mtu=$(cat /sys/class/net/"$iface"/mtu 2> /dev/null || echo "?");
        fd="$(_e94_proc_fd "$pid")";
        rss="$(_e94_proc_rss_mb "$pid")";
        cpu="$(_e94_proc_cpu_pct "$pid")";
        echo -e "  默认网卡: ${cyan}${iface:-未知}${none} | MTU: ${cyan}${mtu}${none} | cc/qdisc: ${cyan}${cc}/${qdisc}${none}";
        echo -e "  Xray PID: ${cyan}${pid}${none} | FD/RSS/CPU: ${cyan}${fd}/${rss}/${cpu}${none} | ESTABLISHED: ${cyan}${est}${none}";
        hr;
        echo "  1) 生成完整诊断报告（推荐，已修复 e93 awk 转义问题）";
        echo "  2) CPU / 内存 / FD / 连接数检查";
        echo "  3) RTT / 丢包快速测试";
        echo "  4) HTTP DNS/连接/TLS/TTFB 耗时测试";
        echo "  5) BBR / TCP 连接摘要";
        echo "  6) qdisc / MTU / offload / 网卡队列检查";
        echo "  7) conntrack / 防火墙容量检查";
        echo "  8) 诊断结论说明：应该先看哪一层";
        echo "  0) 返回主菜单";
        hr;
        local opt="";
        read -rp "请选择: " opt || true;
        case "${opt:-}" in 
            1)
                do_xray_speed_diag_report_e94;
                _e94_pause
            ;;
            2)
                echo "Xray 状态：$(systemctl is-active xray 2> /dev/null || echo inactive) / $(systemctl is-enabled xray 2> /dev/null || echo disabled)";
                echo "PID=$pid FD=$fd RSS=$rss CPU=$cpu ESTABLISHED=$est";
                echo "";
                ps -o pid,ppid,stat,%cpu,%mem,rss,etime,cmd -p "$pid" 2> /dev/null || true;
                echo "";
                free -h 2> /dev/null || true;
                echo "";
                uptime 2> /dev/null || true;
                _e94_pause
            ;;
            3)
                echo "[ping 1.1.1.1]";
                _e94_ping_summary 1.1.1.1 8;
                echo "";
                echo "[ping 8.8.8.8]";
                _e94_ping_summary 8.8.8.8 8;
                _e94_pause
            ;;
            4)
                echo "[Cloudflare]";
                _e94_http_timing https://www.cloudflare.com;
                echo "";
                echo "[Microsoft]";
                _e94_http_timing https://www.microsoft.com;
                echo "";
                echo "[Apple]";
                _e94_http_timing https://www.apple.com;
                _e94_pause
            ;;
            5)
                ss -tin 2> /dev/null | grep -iE 'bbr|rtt|pacing_rate|bytes_acked|delivery_rate|retrans' | head -n 80 || true;
                _e94_pause
            ;;
            6)
                echo "iface=${iface:-unknown} mtu=$mtu cc=$cc default_qdisc=$qdisc";
                test -n "$iface" && tc qdisc show dev "$iface" 2> /dev/null || true;
                echo "";
                test -n "$iface" && tc -s qdisc show dev "$iface" 2> /dev/null || true;
                echo "";
                test -n "$iface" && ethtool -k "$iface" 2> /dev/null | sed -n '1,100p' || true;
                echo "";
                test -n "$iface" && find /sys/class/net/"$iface"/queues -maxdepth 2 -type f \( -name rps_cpus -o -name xps_cpus \) -print -exec cat {} \; 2> /dev/null || true;
                _e94_pause
            ;;
            7)
                _e94_conntrack_status || true;
                dmesg 2> /dev/null | grep -i conntrack | tail -n 10 || true;
                iptables -S 2> /dev/null | wc -l | awk '{print "iptables_rules=" int($1)}' || true;
                _e94_pause
            ;;
            8)
                cat <<'EOF'
诊断顺序建议：

1. 先看线路：RTT、丢包、晚高峰波动。
2. 再看 Xray：CPU、RSS、FD、连接数、日志。
3. 再看 TCP：BBR 状态、重传、rtt、pacing_rate。
4. 再看队列：fq/cake/HTB 是否冲突、qdisc 是否被覆盖。
5. 再看网卡：MTU、offload、RPS/XPS、虚拟化队列。
6. 最后才调 sysctl/BBR 参数；不要一上来堆大缓冲。

你这次 e93 的 awk 报错属于“诊断脚本输出层”的问题，不代表 Xray 或 BBR 本身异常。
journal 里的 “Special user nobody configured, this is not safe!” 是 systemd 对 xray.service 的用户配置提醒，
不等于 Xray 启动失败。后续可单独做服务用户 hardening 修复。
EOF

                _e94_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。"
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_xray_speed_diag_menu_e95
do_xray_speed_diag_menu_e95() {
    while true; do
        clear;
        title "V198e95：Xray 跨境链路速度诊断中心";
        local iface cc qdisc_default qdisc_actual pid est mtu rss cpu fd;
        iface="$(_e95_default_iface 2> /dev/null || echo "")";
        cc=$(sysctl -n net.ipv4.tcp_congestion_control 2> /dev/null || echo "?");
        qdisc_default=$(sysctl -n net.core.default_qdisc 2> /dev/null || echo "?");
        qdisc_actual="$(_e95_root_qdisc_line "$iface")";
        pid="$(_e95_xray_pid)";
        est=$(ss -Htan state established 2> /dev/null | wc -l 2> /dev/null | awk '{print int($1)}' || echo 0);
        mtu="?";
        test -n "$iface" && mtu=$(cat /sys/class/net/"$iface"/mtu 2> /dev/null || echo "?");
        fd="$(_e95_proc_fd "$pid")";
        rss="$(_e95_proc_rss_mb "$pid")";
        cpu="$(_e95_proc_cpu_pct "$pid")";
        echo -e "  默认网卡: ${cyan}${iface:-未知}${none} | MTU: ${cyan}${mtu}${none} | cc/sysctl_qdisc: ${cyan}${cc}/${qdisc_default}${none}";
        echo -e "  实际 root qdisc: ${cyan}${qdisc_actual:-未读取}${none}";
        echo -e "  Xray PID: ${cyan}${pid}${none} | FD/RSS/CPU: ${cyan}${fd}/${rss}/${cpu}${none} | ESTABLISHED: ${cyan}${est}${none}";
        hr;
        echo "  1) 生成完整诊断报告（推荐）";
        echo "  2) CPU / 内存 / FD / 连接数检查";
        echo "  3) RTT / 丢包快速测试";
        echo "  4) HTTP DNS/连接/TLS/TTFB 耗时测试";
        echo "  5) BBR / TCP 连接摘要";
        echo "  6) qdisc / MTU / offload / 网卡队列检查";
        echo "  7) conntrack / 防火墙容量检查";
        echo "  8) TC e93/e94/e95 服务状态检查";
        echo "  9) 诊断结论说明：应该先看哪一层";
        echo "  0) 返回主菜单";
        hr;
        local opt="";
        read -rp "请选择: " opt || true;
        case "${opt:-}" in 
            1)
                do_xray_speed_diag_report_e95;
                _e95_pause
            ;;
            2)
                echo "Xray 状态：$(systemctl is-active xray 2> /dev/null || echo inactive) / $(systemctl is-enabled xray 2> /dev/null || echo disabled)";
                echo "PID=$pid FD=$fd RSS=$rss CPU=$cpu ESTABLISHED=$est";
                echo "";
                if [[ "$pid" =~ ^[0-9]+$ ]] && test "$pid" -gt 0 2> /dev/null; then
                    ps -o pid,ppid,stat,%cpu,%mem,rss,etime,cmd -p "$pid" 2> /dev/null || true;
                fi;
                echo "";
                free -h 2> /dev/null || true;
                echo "";
                uptime 2> /dev/null || true;
                _e95_pause
            ;;
            3)
                echo "[ping 1.1.1.1]";
                _e95_ping_summary 1.1.1.1 8;
                echo "";
                echo "[ping 8.8.8.8]";
                _e95_ping_summary 8.8.8.8 8;
                _e95_pause
            ;;
            4)
                echo "[Cloudflare]";
                _e95_http_timing https://www.cloudflare.com;
                echo "";
                echo "[Microsoft]";
                _e95_http_timing https://www.microsoft.com;
                echo "";
                echo "[Apple]";
                _e95_http_timing https://www.apple.com;
                _e95_pause
            ;;
            5)
                ss -tin 2> /dev/null | grep -iE 'bbr|rtt|pacing_rate|bytes_acked|delivery_rate|retrans|cwnd|ssthresh' | head -n 100 || true;
                _e95_pause
            ;;
            6)
                echo "iface=${iface:-unknown} mtu=$mtu cc=$cc default_qdisc_sysctl=$qdisc_default";
                echo "actual_root_qdisc=${qdisc_actual:-unknown}";
                echo "";
                test -n "$iface" && tc qdisc show dev "$iface" 2> /dev/null || true;
                echo "";
                test -n "$iface" && tc -s qdisc show dev "$iface" 2> /dev/null || true;
                echo "";
                test -n "$iface" && tc class show dev "$iface" 2> /dev/null || true;
                echo "";
                test -n "$iface" && ethtool -k "$iface" 2> /dev/null | sed -n '1,120p' || true;
                echo "";
                test -n "$iface" && find /sys/class/net/"$iface"/queues -maxdepth 2 -type f \( -name rps_cpus -o -name xps_cpus \) -print -exec cat {} \; 2> /dev/null || true;
                _e95_pause
            ;;
            7)
                _e95_conntrack_status || true;
                dmesg 2> /dev/null | grep -i conntrack | tail -n 10 || true;
                _e95_pause
            ;;
            8)
                _e95_tc_legacy_status;
                _e95_pause
            ;;
            9)
                cat <<'EOF'
诊断顺序建议：

1. 先看线路：RTT、丢包、晚高峰波动。
2. 再看实际 root qdisc：不要只看 sysctl default_qdisc；启用 TC 后实际 root 可能是 htb。
3. 再看 Xray：CPU、RSS、FD、连接数、日志。
4. 再看 TCP：BBR 状态、重传、rtt、pacing_rate、delivery_rate。
5. 再看队列：fq/cake/HTB 是否冲突，e93/e94/e95 TC 是否残留。
6. 再看网卡：MTU、offload、RPS/XPS、虚拟化队列。
7. 最后才调 sysctl/BBR 参数；不要一上来堆大缓冲。
EOF

                _e95_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。"
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION core do_xray_speed_diag_report_e93
do_xray_speed_diag_report_e93() {
    _e93_prepare_dirs;
    local ts out iface pid cc qdisc mtu;
    ts="$(_e93_ts)";
    out="$E93_SPEED_AUDIT_DIR/xray_speed_diag_$ts.txt";
    iface="$(_e93_default_iface 2> /dev/null || echo "")";
    pid=$(systemctl show -p MainPID --value xray 2> /dev/null || echo 0);
    cc=$(sysctl -n net.ipv4.tcp_congestion_control 2> /dev/null || echo "?");
    qdisc=$(sysctl -n net.core.default_qdisc 2> /dev/null || echo "?");
    mtu="?";
    test -n "$iface" && mtu=$(cat /sys/class/net/"$iface"/mtu 2> /dev/null || echo "?");
    { 
        echo "V198e93 Xray cross-border speed diagnosis";
        echo "time=$(date '+%F %T')";
        echo "kernel=$(uname -r 2> /dev/null || echo unknown)";
        echo "iface=${iface:-unknown}";
        echo "mtu=$mtu cc=$cc default_qdisc=$qdisc";
        echo "xray_active=$(systemctl is-active xray 2> /dev/null || echo inactive)";
        echo "xray_enabled=$(systemctl is-enabled xray 2> /dev/null || echo disabled)";
        echo "xray_pid=$pid";
        if [[ "$pid" =~ ^[0-9]+$ ]] && test "$pid" -gt 0 2> /dev/null; then
            echo "xray_fd=$(ls /proc/$pid/fd 2> /dev/null | wc -l 2> /dev/null || echo 0)";
            echo "xray_rss=$(ps -o rss= -p "$pid" 2> /dev/null | awk '{printf \"%.1fMB\", $1/1024}' || echo '?')";
            echo "xray_cpu=$(ps -o %cpu= -p "$pid" 2> /dev/null | awk '{print $1\"%\"}' || echo '?')";
        fi;
        echo "established=$(ss -Htan state established 2> /dev/null | wc -l 2> /dev/null || echo 0)";
        echo "";
        echo "[ping 1.1.1.1]";
        _e93_ping_summary 1.1.1.1 6;
        echo "";
        echo "[ping 8.8.8.8]";
        _e93_ping_summary 8.8.8.8 6;
        echo "";
        echo "[http timing cloudflare]";
        _e93_http_timing https://www.cloudflare.com;
        echo "";
        echo "[http timing microsoft]";
        _e93_http_timing https://www.microsoft.com;
        echo "";
        echo "[qdisc]";
        test -n "$iface" && tc -s qdisc show dev "$iface" 2> /dev/null || true;
        echo "";
        echo "[ip route]";
        ip route get 1.1.1.1 2> /dev/null || true;
        echo "";
        echo "[offload]";
        test -n "$iface" && ethtool -k "$iface" 2> /dev/null | grep -E 'tcp-segmentation|generic-segmentation|generic-receive|large-receive|rx-gro-hw|tx-udp' || true;
        echo "";
        echo "[tcp sysctl]";
        sysctl net.ipv4.tcp_congestion_control net.core.default_qdisc net.ipv4.tcp_mtu_probing net.ipv4.tcp_notsent_lowat net.ipv4.tcp_limit_output_bytes net.ipv4.tcp_adv_win_scale net.ipv4.tcp_app_win 2> /dev/null || true;
        echo "";
        echo "[conntrack]";
        sysctl net.netfilter.nf_conntrack_count net.netfilter.nf_conntrack_max 2> /dev/null || true;
        dmesg 2> /dev/null | grep -i conntrack | tail -n 5 || true;
        echo "";
        echo "[BBR connections]";
        ss -tin 2> /dev/null | grep -iE 'bbr|rtt|pacing_rate|bytes_acked|delivery_rate|retrans' | head -n 40 || true;
        echo "";
        echo "[top remote ips]";
        ss -Htan state established 2> /dev/null | awk '{print $5}' | sed -E 's/^\[?([^]]+)\]?:[0-9]+$/\1/' | sort | uniq -c | sort -nr | head -n 15 || true;
        echo "";
        echo "[journal xray]";
        journalctl -u xray.service --no-pager -n 20 2> /dev/null || true
    } > "$out";
    info "Xray 跨境链路速度诊断报告：$out";
    sed -n '1,120p' "$out" 2> /dev/null || true
}
