# EEX3-FUNCTION core enable_cpu_performance_default
enable_cpu_performance_default() {
    local touched=0 cpu;
    for cpu in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor;
    do
        if test -f "$cpu"; then
            echo performance > "$cpu" 2> /dev/null || true;
            touched=1;
        fi;
    done;
    if test "$touched" -eq 1; then
        update_hw_boot_script > /dev/null 2>&1 || true;
    fi
}
# EEX3-FUNCTION core enable_dnsmasq_cache_safely
enable_dnsmasq_cache_safely() {
    local tx target snap rc=0 restore_rc=0 immutable=0 preinstalled=0;
    local -a files=(/etc/resolv.conf /etc/dnsmasq.conf "${E67_DNS_MODE_FILE:-$CONFIG_DIR/dns_mode.txt}");
    local -a units=(dnsmasq.service systemd-resolved.service resolvconf.service);
    tx=$(_e204_new_tx dnsmasq) || return 1;
    : > "$tx/services.before" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    lsattr -d /etc/resolv.conf 2> /dev/null | awk '{print $1}' | grep -q i && immutable=1 || true;
    for target in "${files[@]}";
    do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')";
        _e135_snapshot_file "$target" "$snap" || { 
            _e204_tx_close "$tx" || true;
            return 1
        };
    done;
    for target in "${units[@]}";
    do
        _e204_service_snapshot "$target" >> "$tx/services.before" || { 
            _e204_tx_close "$tx" || true;
            return 1
        };
    done;
    dpkg-query -W -f='${Status}' dnsmasq 2> /dev/null | grep -q 'install ok installed' && preinstalled=1 || true;
    _e204_dnsmasq_base || rc=$?;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    chattr -i /etc/resolv.conf > /dev/null 2>&1 || true;
    if test "$preinstalled" -eq 0 && dpkg-query -W -f='${Status}' dnsmasq 2> /dev/null | grep -q 'install ok installed'; then
        DEBIAN_FRONTEND=noninteractive apt-get purge -y dnsmasq > /dev/null 2>&1 || restore_rc=1;
    fi;
    for target in "${files[@]}";
    do
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')";
        _e135_restore_file "$target" "$snap" || restore_rc=1;
    done;
    _e204_services_restore_file "$tx/services.before" || restore_rc=1;
    test "$immutable" -eq 0 || chattr +i /etc/resolv.conf > /dev/null 2>&1 || restore_rc=1;
    test "$restore_rc" -eq 0 || _e204_mark_critical dnsmasq "$tx" 'resolver rollback failed' || true;
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION core enable_journald_volatile_default
enable_journald_volatile_default() {
    _e121_install_log_retention
}
# EEX3-FUNCTION core enable_thp_never_default
enable_thp_never_default() {
    if test -f /sys/kernel/mm/transparent_hugepage/enabled; then
        echo never > /sys/kernel/mm/transparent_hugepage/enabled 2> /dev/null || true;
    fi;
    if test -f /sys/kernel/mm/transparent_hugepage/defrag; then
        echo never > /sys/kernel/mm/transparent_hugepage/defrag 2> /dev/null || true;
    fi;
    update_hw_boot_script > /dev/null 2>&1 || true
}
# EEX3-FUNCTION core enable_zram_default
enable_zram_default() {
    local tx rc=0 restore_rc=0 was_zram=0 was_swap=0 had_swapfile=0;
    tx=$(_e204_new_tx swap-zram) || return 1;
    _e135_snapshot_file /etc/fstab "$tx/fstab" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e135_snapshot_file /etc/sysctl.d/98-xray-swap.conf "$tx/sysctl" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e135_snapshot_file "$E204_ZRAM_SCRIPT" "$tx/zram-script" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e135_snapshot_file "$E204_ZRAM_SERVICE" "$tx/zram-service" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e135_snapshot_file "$E204_ZRAM_STATE" "$tx/zram-state" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_service_snapshot "$E204_ZRAM_UNIT" > "$tx/service.before" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq /dev/zram0 && was_zram=1 || true;
    swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE" && was_swap=1 || true;
    test -e "$E204_SWAPFILE" && had_swapfile=1 || true;
    if _zram_supported; then
        _e204_zram_activate || rc=1;
    else
        _e204_swapfile_activate || rc=1;
    fi;
    if test "$rc" -eq 0 && ! swapon --show=NAME --noheadings 2> /dev/null | grep -q '[^[:space:]]'; then
        error 'ZRAM/Swap入口返回成功，但系统没有任何活动Swap；拒绝假成功。';
        rc=1;
    fi;
    test "$rc" -ne 0 || _write_swap_sysctl_e52 || rc=1;
    if test "$rc" -eq 0; then
        info 'ZRAM/Swap事务通过；原有用户Swap未被关闭或删除。';
        _e204_tx_close "$tx";
        return $?;
    fi;
    if test "$was_zram" -eq 0; then
        swapoff /dev/zram0 > /dev/null 2>&1 || true;
        command -v zramctl > /dev/null 2>&1 && zramctl --reset /dev/zram0 > /dev/null 2>&1 || true;
    fi;
    if test "$was_swap" -eq 0 && swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
        swapoff "$E204_SWAPFILE" > /dev/null 2>&1 || restore_rc=1;
    fi;
    if test "$had_swapfile" -eq 0 && test -e "$E204_SWAPFILE"; then
        rm -f -- "$E204_SWAPFILE" || restore_rc=1;
    fi;
    _e135_restore_file /etc/fstab "$tx/fstab" || restore_rc=1;
    _e135_restore_file /etc/sysctl.d/98-xray-swap.conf "$tx/sysctl" || restore_rc=1;
    _e135_restore_file "$E204_ZRAM_SCRIPT" "$tx/zram-script" || restore_rc=1;
    _e135_restore_file "$E204_ZRAM_SERVICE" "$tx/zram-service" || restore_rc=1;
    _e135_restore_file "$E204_ZRAM_STATE" "$tx/zram-state" || restore_rc=1;
    _e204_services_restore_file "$tx/service.before" || restore_rc=1;
    if test "$was_swap" -eq 1 && ! swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
        swapon -p 10 "$E204_SWAPFILE" > /dev/null 2>&1 || restore_rc=1;
    fi;
    test "$restore_rc" -eq 0 || _e204_mark_critical swap-zram "$tx" 'swap rollback failed' || true;
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION core enforce_swap_cap_1024_e52
enforce_swap_cap_1024_e52() {
    title "检查并执行 Swap 总量上限 1024MB（优先 ZRAM，删除超额文件型 Swap）";
    mkdir -p "$BACKUP_DIR" 2> /dev/null || true;
    cp -a /etc/fstab "$BACKUP_DIR/fstab.swapcap.$(date +%Y%m%d_%H%M%S).bak" 2> /dev/null || true;
    if _zram_supported; then
        info "检测到 ZRAM 支持：启用 /dev/zram0=1024MB，并删除 /swapfile/其它文件型 Swap，避免总 Swap 超过 1GB。";
        _setup_zram_1024_e52;
    else
        warn "ZRAM 不支持：使用 /swapfile=1024MB 作为唯一脚本管理 Swap。";
        systemctl disable xray-zram.service --now > /dev/null 2>&1 || true;
        rm -f /etc/systemd/system/xray-zram.service /usr/local/bin/xray-zram.sh 2> /dev/null || true;
        _setup_swapfile_1024_e52;
    fi;
    _write_swap_sysctl_e52;
    local total nonfile;
    total=$(_swap_total_mb);
    nonfile=$(swapon --show=NAME,TYPE --noheadings 2> /dev/null | awk '$2!="file" && $1 !~ /zram/ {print $1}' | xargs echo 2> /dev/null || true);
    if test "${total:-0}" -gt 1024 2> /dev/null; then
        if test -n "$nonfile"; then
            warn "当前 Swap 总量约 ${total}MB，仍超过 1024MB；检测到非文件型/非ZRAM Swap：$nonfile。为避免误伤磁盘分区，脚本不自动删除它们。";
        else
            warn "当前 Swap 总量约 ${total}MB，仍超过 1024MB；可能是内核统计/旧 swapoff 未完成，请执行 swapon --show 复核。";
        fi;
    else
        info "Swap 总量已控制在 ${total}MB / 1024MB 以内。";
    fi
}
# EEX3-FUNCTION core ensure_public_key_cache
ensure_public_key_cache() {
    if test -s "$PUBKEY_FILE"; then
        chmod 600 "$PUBKEY_FILE" 2> /dev/null || true;
        return 0;
    fi;
    if test ! -f "$CONFIG" || test ! -x "$XRAY_BIN" || ! command -v jq > /dev/null 2>&1; then
        return 0;
    fi;
    local pub priv out;
    pub=$(jq -r '.inbounds[]? | select(.protocol=="vless" and .streamSettings?.security=="reality") | .streamSettings.realitySettings.publicKey // empty' "$CONFIG" 2> /dev/null | head -n 1 || true);
    if test -n "$pub" && test "$pub" != "null"; then
        echo "$pub" > "$PUBKEY_FILE" 2> /dev/null || true;
        chmod 600 "$PUBKEY_FILE" 2> /dev/null || true;
        return 0;
    fi;
    priv=$(jq -r '.inbounds[]? | select(.protocol=="vless" and .streamSettings?.security=="reality") | .streamSettings.realitySettings.privateKey // empty' "$CONFIG" 2> /dev/null | head -n 1 || true);
    if test -n "$priv" && test "$priv" != "null"; then
        out=$("$XRAY_BIN" x25519 -i "$priv" 2> /dev/null || true);
        pub=$(echo "$out" | awk -F': ' 'tolower($1) ~ /public/ {print $2}' | tr -d ' \r\n' | head -n 1);
        if test -n "$pub"; then
            echo "$pub" > "$PUBKEY_FILE" 2> /dev/null || true;
            chmod 600 "$PUBKEY_FILE" 2> /dev/null || true;
        fi;
    fi
}
# EEX3-FUNCTION core ensure_xray_is_alive
ensure_xray_is_alive() {
    info "正在执行 Xray Core/MainPID/入站端口稳定复检。";
    test -s "$CONFIG" || { 
        error "config.json 不存在。";
        return 1
    };
    _e118_xray_test_config "$CONFIG" 1 || return 1;
    systemctl reset-failed xray.service > /dev/null 2>&1 || true;
    if systemctl is-active --quiet xray.service 2> /dev/null; then
        systemctl restart xray.service > /dev/null 2>&1 || true;
    else
        systemctl start xray.service > /dev/null 2>&1 || true;
    fi;
    _e127_verify_xray_runtime "$CONFIG" 12
}
# EEX3-FUNCTION core error
error() {
    echo -e "${red}✗ [ERROR]${none} $*"
}
# EEX3-FUNCTION core finalize
finalize() {
    sync 2> /dev/null || true;
    info "V199e137 收尾完成（不再主动 drop_caches）。"
}
# EEX3-FUNCTION core fix_permissions
fix_permissions() {
    local service_user service_group f;
    service_user=$(systemctl show xray.service -p User --value 2> /dev/null || true);
    service_group=$(systemctl show xray.service -p Group --value 2> /dev/null || true);
    test -n "$service_user" || service_user=root;
    if test "$service_user" = root; then
        install -d -o root -g root -m 0700 "$CONFIG_DIR" || return 1;
        test ! -f "$CONFIG" || { 
            chown root:root "$CONFIG" && chmod 0600 "$CONFIG"
        } || return 1;
    else
        if id "$service_user" > /dev/null 2>&1; then
            test -n "$service_group" || service_group=$(id -gn "$service_user" 2> /dev/null || true);
            getent group "$service_group" > /dev/null 2>&1 || { 
                error "xray.service Group无效：$service_group";
                return 1
            };
            chown root:"$service_group" "$CONFIG_DIR" || return 1;
            chmod 0750 "$CONFIG_DIR" || return 1;
            test ! -f "$CONFIG" || { 
                chown root:"$service_group" "$CONFIG" && chmod 0640 "$CONFIG"
            } || return 1;
        else
            error "xray.service User不存在：$service_user；拒绝以不可验证权限继续。";
            return 1;
        fi;
    fi;
    install -d -m 0755 "$DAT_DIR" || return 1;
    install -d -m 0700 "$BACKUP_DIR" "$E118_DIR" "$E118_BACKUP_DIR" "$E118_AUDIT_DIR" 2> /dev/null || true;
    for f in "$PUBKEY_FILE" "$USER_SNI_MAP" "$USER_TIME_MAP" "${E77_VLESSENC_CLIENT_FILE:-$CONFIG_DIR/vlessenc.client.txt}" "${E77_VLESSENC_SERVER_FILE:-$CONFIG_DIR/vlessenc.server.txt}" "$CONFIG_DIR/node.meta" "$SCRIPT_VERSION_FILE";
    do
        test ! -e "$f" || { 
            chown root:root "$f" && chmod 0600 "$f"
        } || return 1;
    done
}
# EEX3-FUNCTION core fix_xray_systemd_limits
fix_xray_systemd_limits() {
    if test "${EEX7_UNIT_PREPARE_ONLY:-0}" != 1; then
        _eex7_limits_base;
        return $?;
    fi;
    _e135_prepare || return 1;
    local tmp;
    tmp=$(_e118_mktemp eex7-limits) || return 1;
    cat > "$tmp" <<'EEX7_LIMITS'
[Service]
LimitNOFILE=1048576
LimitNPROC=262144
LimitSTACK=8M
TasksMax=infinity
Nice=-20
OOMScoreAdjust=-500
Environment="GOGC=300"
Restart=on-failure
RestartSec=5s
EEX7_LIMITS

    _e214_ensure_parent_dir "$E135_LIMITS_FILE" || return 1;
    install -m 0644 "$tmp" "$E135_LIMITS_FILE" && systemctl daemon-reload
}
