# EEX3-FUNCTION core get_xray_listen_ports
get_xray_listen_ports() {
    local ports="";
    if test -f "$CONFIG" && command -v jq > /dev/null 2>&1; then
        ports=$(jq -r '.inbounds[]? | select(.port != null) | .port' "$CONFIG" 2> /dev/null | awk '/^[0-9]+$/ && $1>=1 && $1<=65535 {print $1}' | sort -n | uniq || true);
    fi;
    if test -z "$ports" && [[ "${LISTEN_PORT:-}" =~ ^[0-9]+$ ]]; then
        ports="$LISTEN_PORT";
    fi;
    if test -z "$ports"; then
        ports="443";
    fi;
    echo "$ports"
}
# EEX3-FUNCTION core harden_xray_reality_profile
harden_xray_reality_profile() {
    test -s "$CONFIG" || return 0;
    _safe_jq_write '
      .log.access="none" | .log.error="none" | .log.loglevel="warning" |
      .routing.domainStrategy="AsIs" | del(.routing.domainMatcher) |
      .routing.rules=((.routing.rules//[]) | map(del(.type))) |
      (.inbounds[]? | select(.protocol=="vless" and (.streamSettings.security//"")=="reality")) |= (
        .settings.decryption="none" |
        .settings.clients |= map(.flow="xtls-rprx-vision") |
        .streamSettings.realitySettings.show=false |
        .streamSettings.realitySettings.maxTimeDiff=60000 |
        .streamSettings.realitySettings.target=(.streamSettings.realitySettings.target // .streamSettings.realitySettings.dest) |
        del(.streamSettings.realitySettings.dest) |
        del(.streamSettings.realitySettings.limitFallbackUpload) |
        del(.streamSettings.realitySettings.limitFallbackDownload) |
        .sniffing.enabled=true | .sniffing.metadataOnly=true | .sniffing.routeOnly=true
      )'
}
