        chmod +x "$SYMLINK" "$SCRIPT_DIR/ex198e76.sh" "$SCRIPT_DIR/ex198e_latest.sh" 2> /dev/null || true;
    fi;
    echo "$SCRIPT_VERSION" > "$SCRIPT_VERSION_FILE" 2> /dev/null || true;
    hash -r 2> /dev/null || true
}
# EEX3-FUNCTION core install_update_dat
install_update_dat() {
