# EEX3-FUNCTION core json_array_from_args
json_array_from_args() {
    if command -v jq > /dev/null 2>&1; then
        jq -nc '$ARGS.positional' --args "$@";
    else
        local out="[" first=1 item;
        for item in "$@";
        do
            item=${item//\\/\\\\};
            item=${item//\"/\\\"};
            if test "$first" -eq 0; then
                out+=",";
            fi;
            out+="\"$item\"";
            first=0;
        done;
        out+="]";
        echo "$out";
    fi
}
