# EEX3-FUNCTION core manual_network_buffer_params_e56
manual_network_buffer_params_e56() {
    title "手动输入网络缓冲参数";
    warn "输入为空则使用当前永久文件值；若当前未写入，则使用 V198e66 默认值。";
    local rd wd rm wm tr tw cur input;
    cur=$(_net_get_perm_value_e56 net.core.rmem_default);
    test "$cur" = "未写入" && cur="7990577";
    read -rp "net.core.rmem_default [$cur]: " input || true;
    rd=${input:-$cur};
    cur=$(_net_get_perm_value_e56 net.core.wmem_default);
    test "$cur" = "未写入" && cur="7990577";
    read -rp "net.core.wmem_default [$cur]: " input || true;
    wd=${input:-$cur};
    cur=$(_net_get_perm_value_e56 net.core.rmem_max);
    test "$cur" = "未写入" && cur="97108868";
    read -rp "net.core.rmem_max [$cur]: " input || true;
    rm=${input:-$cur};
    cur=$(_net_get_perm_value_e56 net.core.wmem_max);
    test "$cur" = "未写入" && cur="97108868";
    read -rp "net.core.wmem_max [$cur]: " input || true;
    wm=${input:-$cur};
    cur=$(_net_get_perm_value_e56 net.ipv4.tcp_rmem);
    test "$cur" = "未写入" && cur="4096 7990577 97108868";
    read -rp "net.ipv4.tcp_rmem [$cur]: " input || true;
    tr=${input:-$cur};
    cur=$(_net_get_perm_value_e56 net.ipv4.tcp_wmem);
    test "$cur" = "未写入" && cur="4096 7990577 97108868";
    read -rp "net.ipv4.tcp_wmem [$cur]: " input || true;
    tw=${input:-$cur};
    if ! _valid_int_e56 "$rd" || ! _valid_int_e56 "$wd" || ! _valid_int_e56 "$rm" || ! _valid_int_e56 "$wm"; then
        error "rmem/wmem default/max 必须是正整数。";
        _e52_pause;
        return 1;
    fi;
    if ! _valid_tcp_triplet_e56 "$tr" || ! _valid_tcp_triplet_e56 "$tw"; then
        error "tcp_rmem/tcp_wmem 必须是三个正整数，例如：4096 7990577 97108868";
        _e52_pause;
        return 1;
    fi;
    _write_network_buffer_params_e56 "$rd" "$wd" "$rm" "$wm" "$tr" "$tw";
    show_network_buffer_params_e56
}
# EEX3-FUNCTION core migrate_legacy_user_maps
migrate_legacy_user_maps() {
    if test ! -f "$CONFIG" || ! command -v jq > /dev/null 2>&1; then
        return 0;
    fi;
    mkdir -p "$CONFIG_DIR" 2> /dev/null || true;
    touch "$USER_SNI_MAP" "$USER_TIME_MAP" 2> /dev/null || true;
    local now rows line uid remark sni;
    now=$(date +"%Y-%m-%d %H:%M");
    rows=$(jq -r '
      .inbounds[]? | select(.protocol=="vless" and .streamSettings?.security=="reality") as $in |
      (($in.streamSettings.realitySettings.serverNames[0] // (($in.streamSettings.realitySettings.dest // "www.microsoft.com:443") | split(":")[0]))) as $sni |
      $in.settings.clients[]? | [.id, (.email // "legacy"), $sni] | @tsv
    ' "$CONFIG" 2> /dev/null || true);
    while IFS='	' read -r uid remark sni; do
        test -n "${uid:-}" || continue;
        if ! grep -q "^${uid}|" "$USER_TIME_MAP" 2> /dev/null; then
            echo "${uid}|${now}" >> "$USER_TIME_MAP";
        fi;
        if test -n "${sni:-}" && ! grep -q "^${uid}|" "$USER_SNI_MAP" 2> /dev/null; then
            echo "${uid}|${sni}" >> "$USER_SNI_MAP";
        fi;
    done <<< "$rows"
}
# EEX3-FUNCTION core origin_guard_status
origin_guard_status() {
    title "Origin Guard 入口防滥用状态";
    if systemctl is-active --quiet xray-origin-guard.service 2> /dev/null; then
        info "xray-origin-guard.service 正在运行。";
    else
        warn "xray-origin-guard.service 未运行。";
    fi;
    echo -e "\n${cyan}【受保护 Xray 端口】${none}";
    if test -f "$SCRIPT_DIR/guard_ports.conf"; then
        sed 's/^/  - /' "$SCRIPT_DIR/guard_ports.conf";
    else
        get_xray_listen_ports | sed 's/^/  - /';
    fi;
    echo -e "\n${cyan}【iptables v4 摘要】${none}";
    iptables -S XRAY_ORIGIN_GUARD 2> /dev/null | sed 's/^/  /' || warn "未发现 IPv4 Guard 链。";
    echo -e "\n${cyan}【iptables v6 摘要】${none}";
    ip6tables -S XRAY_ORIGIN_GUARD 2> /dev/null | sed 's/^/  /' || true;
    local _p="";
    read -rp "按 Enter 返回..." _p || true
}
# EEX3-FUNCTION core pkg_install
pkg_install() {
    if test "${EEX3_AUTO_ACTIVE:-0}" = 1; then
        error "升级中请求安装软件包（$*）；为避免包维护脚本更改SSH，已中止并交由外层回滚。";
        return 1;
    fi;
    _eex3_pkg_install_manual "$@"
}
# EEX3-FUNCTION core preflight
preflight() {
    local os_id item cmd pkg;
    local -a pairs missing=();
    test "$EUID" -eq 0 || die "此脚本必须以root运行。";
    command -v systemctl > /dev/null 2>&1 || die "缺少systemctl。";
    test -d /run/systemd/system || die "当前环境没有运行中的systemd。";
    _e118_runtime_init || return 1;
    os_id=$(detect_os 2> /dev/null || echo unknown);
    pairs=("jq:jq" "curl:curl" "ip:iproute2" "ss:iproute2" "openssl:openssl");
    [[ "$os_id" =~ ^(centos|rhel|fedora|rocky|almalinux)$ ]] && pairs=("jq:jq" "curl:curl" "ip:iproute" "ss:iproute" "openssl:openssl");
    for item in "${pairs[@]}";
    do
        cmd=${item%%:*};
        pkg=${item#*:};
        command -v "$cmd" > /dev/null 2>&1 || missing+=("$pkg");
    done;
    if test "${#missing[@]}" -gt 0; then
        pkg_install "${missing[@]}" || return 1;
        for item in "${pairs[@]}";
        do
            cmd=${item%%:*};
            command -v "$cmd" > /dev/null 2>&1 || { 
                error "安装返回成功但命令仍不存在：$cmd";
                return 1
            };
        done;
    fi
}
