ming.logitech.com" "razer.com" "www.razer.com" "support.razer.com" "insider.razer.com" "corsair.com" "www.corsair.com" "support.corsair.com" "account.asus.com" "kingston.com" "www.kingston.com" "shop.kingston.com" "support.kingston.com" "seagate.com" "www.seagate.com" "support.seagate.com" "kleenex.com" "www.kleenex.com" "shop.kleenex.com" "scottbrand.com" "www.scottbrand.com" "tempo-world.com" "www.tempo-world.com" "www.zoom.us" "www.adobe.com" "www.autodesk.com" "www.salesforce.com" "www.cisco.com" "www.ibm.com" "www.qualcomm.com" "www.nissan-global.com" "www.target.com" "www.walmart.com" "www.homedepot.com" "www.lowes.com" "www.walgreens.com" "www.costco.com" "www.cvs.com" "www.bestbuy.com" "www.kroger.com" "www.mcdonalds.com" "www.starbucks.com" "www.puma.com" "www.underarmour.com" "www.hm.com" "www.gap.com" "www.rolex.com" "www.burberry.com" "www.cartier.com" "www.estee-lauder.com" "www.pfizer.com" "www.novartis.com" "www.roche.com" "www.sanofi.com" "www.merck.com" "www.gsk.com" "www.boeing.com" "www.airbus.com" "www.lockheedmartin.com" "www.geaerospace.com" "www.siemens.com" "www.hitachi.com" "www.schneider-electric.com" "www.caterpillar.com" "www.john-deere.com" "www.mitsubishicorp.com" "www.sharp.com" "www.lenovo.com" "www.huawei.com" "www.asus.com" "www.acer.com" "www.delltechnologies.com" "www.hpe.com" "www.tiktok.com" "www.spotify.com" "www.netflix.com" "www.hulu.com" "www.disneyplus.com");
    local tmp cache_tmp old_backup sni key time_raw ms success=0 stopped=0;
    if test -n "${E118_TMPDIR:-}" && test -d "$E118_TMPDIR"; then
        tmp=$(_e118_mktemp sni-full-scan.txt) || return 1;
    else
        tmp=$(mktemp /tmp/ex199e136-sni-full.XXXXXX) || return 1;
    fi;
    old_backup="";
    if test -s "$SNI_CACHE_FILE"; then
        mkdir -p "${E92_SNI_AUDIT_DIR:-$BACKUP_DIR}" 2> /dev/null || true;
        old_backup="${E92_SNI_AUDIT_DIR:-$BACKUP_DIR}/sni_cache.before-full.$(date +%Y%m%d_%H%M%S).txt";
        cp -a "$SNI_CACHE_FILE" "$old_backup" 2> /dev/null || old_backup="";
    fi;
    echo "按 q/Q 可中止；回车和其他残留按键不会中止。";
    for sni in "${sni_list[@]}";
    do
        key="";
        if test -t 0 && IFS= read -r -t 0.02 -n 1 key 2> /dev/null; then
            case "$key" in 
                q | Q)
                    echo;
                    warn "扫描已手动中止，正在整理已测结果。";
                    stopped=1;
                    break
                ;;
                *)
                    :
                ;;
            esac;
        fi;
        if ! time_raw=$(LC_ALL=C curl --proto '=https' --tlsv1.2 -sS -o /dev/null -w '%{time_appconnect}' --connect-timeout 3 --max-time 7 "https://$sni/" 2> /dev/null); then
            time_raw=0;
        fi;
        ms=$(printf '%s
' "$time_raw" | awk '{v=$1+0; if(v>0) printf "%d", v*1000; else print 0}' 2> /dev/null || echo 0);
        if test "${ms:-0}" -gt 0 2> /dev/null; then
            printf '  %b存活%b %-42s %b%4sms%b
' "$green" "$none" "$sni" "$yellow" "$ms" "$none";
            printf '%s %s NORM
' "$ms" "$sni" >> "$tmp";
            success=$((success+1));
        else
            printf '  %b超时%b %s
' "$gray" "$none" "$sni";
        fi;
    done;
    if test "$success" -gt 0 && test -s "$tmp"; then
        cache_tmp="${SNI_CACHE_FILE}.e124-new.$$";
        if ! sort -n "$tmp" | awk '!seen[$2]++ && count<20 {print $2, $1, $3; count++}' > "$cache_tmp" || test ! -s "$cache_tmp"; then
            rm -f -- "$cache_tmp" 2> /dev/null || true;
            error "SNI Top20 候选缓存生成失败，旧缓存保持不变。";
            rm -f "$tmp" 2> /dev/null || true;
            return 1;
        fi;
        chmod 0600 "$cache_tmp" 2> /dev/null || true;
        mv -f -- "$cache_tmp" "$SNI_CACHE_FILE" || { 
            rm -f -- "$cache_tmp";
            return 1
        };
        info "已更新 SNI Top20 缓存：$SNI_CACHE_FILE";
        test -z "$old_backup" || info "旧缓存备份：$old_backup";
    else
        warn "全量扫描没有成功节点；旧缓存保持不变。";
        if test ! -s "$SNI_CACHE_FILE"; then
            _e92_seed_sni_cache_if_empty;
        fi;
    fi;
    rm -f "$tmp" 2> /dev/null || true;
    test "$stopped" -eq 0 || return 0
}
# EEX3-FUNCTION core run_sni_top20_rescan_e92
run_sni_top20_rescan_e92() {
    title "V199e137：Top 20 SNI TLS 复测（仅 q/Q 中止）";
    _e92_prepare_dirs;
    _e92_seed_sni_cache_if_empty;
    test -s "$SNI_CACHE_FILE" || { 
        error "SNI Top20 缓存为空。";
        return 1
    };
    local tmp cache_tmp old_backup sni old_ms old_type time_raw ms key stopped=0;
    tmp=$(_e118_mktemp sni-top20.txt) || return 1;
    old_backup="$E92_SNI_AUDIT_DIR/sni_cache.before.$(_e92_ts).txt";
    cp -a "$SNI_CACHE_FILE" "$old_backup" 2> /dev/null || true;
    echo "仅复测当前缓存前20个域名；按 q/Q 才会中止。";
    while read -r sni old_ms old_type; do
        valid_domain "${sni:-}" || continue;
        key="";
        if test -t 0 && IFS= read -r -t 0.02 -n 1 key 2> /dev/null; then
            case "$key" in 
                q | Q)
                    echo;
                    warn "复测已手动中止。";
                    stopped=1;
                    break
                ;;
                *)
                    :
                ;;
            esac;
        fi;
        if ! time_raw=$(LC_ALL=C curl --proto '=https' --tlsv1.2 -sS -o /dev/null -w '%{time_appconnect}' --connect-timeout 3 --max-time 7 "https://$sni/" 2> /dev/null); then
            time_raw=0;
        fi;
        ms=$(printf '%s\n' "$time_raw" | awk '{v=$1+0; if(v>0) printf "%d",v*1000; else print 0}' 2> /dev/null || echo 0);
        if test "${ms:-0}" -gt 0 2> /dev/null; then
            printf '  %b存活%b %-42s %b%4sms%b\n' "$green" "$none" "$sni" "$yellow" "$ms" "$none";
            printf '%s %s %s\n' "$ms" "$sni" "${old_type:-NORM}" >> "$tmp";
        else
            printf '  %b超时%b %s\n' "$gray" "$none" "$sni";
        fi;
    done < <(head -n 20 "$SNI_CACHE_FILE");
    if test -s "$tmp"; then
        cache_tmp="${SNI_CACHE_FILE}.e124-new.$$";
        if ! sort -n "$tmp" | awk '!seen[$2]++ {print $2,$1,$3}' > "$cache_tmp" || test ! -s "$cache_tmp"; then
            rm -f -- "$cache_tmp" 2> /dev/null || true;
            error "Top20 复测缓存生成失败，旧缓存保持不变。";
            rm -f "$tmp" 2> /dev/null || true;
            return 1;
        fi;
        chmod 0600 "$cache_tmp" 2> /dev/null || true;
        mv -f -- "$cache_tmp" "$SNI_CACHE_FILE" || { 
            rm -f -- "$cache_tmp";
            return 1
        };
        info "Top20 缓存已更新；旧缓存：$old_backup";
    else
        warn "没有成功节点，旧缓存保持不变。";
    fi;
    rm -f "$tmp" 2> /dev/null || true;
    test "$stopped" -eq 0 || return 0
}
# EEX3-FUNCTION core set_or_replace_line
set_or_replace_line() {
    local file="$1" key_regex="$2" line="$3";
    touch "$file" 2> /dev/null || true;
    if grep -Eq "$key_regex" "$file" 2> /dev/null; then
        sed -i "s|$key_regex.*|$line|" "$file" 2> /dev/null || true;
    else
        echo "$line" >> "$file";
    fi
}
# EEX3-FUNCTION core set_sni_json_array
set_sni_json_array() {
