# EEX3-FUNCTION core show_network_buffer_params_e56
show_network_buffer_params_e56() {
    title "当前关键网络参数：运行值 vs 永久配置";
    echo -e "  永久配置文件：${cyan}${NETWORK_OPT_CONF}${none}";
    if test ! -f "$NETWORK_OPT_CONF"; then
        warn "该文件暂不存在；应用参数后会自动创建。";
    fi;
    hr;
    for key in net.core.default_qdisc net.ipv4.tcp_congestion_control net.ipv4.tcp_ecn net.ipv4.tcp_fastopen net.ipv4.tcp_mtu_probing net.ipv4.tcp_adv_win_scale net.ipv4.tcp_app_win net.core.rmem_default net.core.wmem_default net.core.rmem_max net.core.wmem_max net.ipv4.tcp_rmem net.ipv4.tcp_wmem;
    do
        _net_show_one_e56 "$key";
    done;
    hr;
    if test -e "/etc/sysctl.d/99-xray-hotupdate-fast.conf"; then
        warn "仍发现旧冲突文件：/etc/sysctl.d/99-xray-hotupdate-fast.conf；请选择 5 或重新热更新。";
    else
        info "旧 99-xray-hotupdate-fast.conf 已清理。";
    fi;
    echo -e "  ${cyan}提示：运行值来自 sysctl -n；永久文件值来自 $NETWORK_OPT_CONF。${none}"
}
# EEX3-FUNCTION core show_network_sysctl_conflicts_e58
show_network_sysctl_conflicts_e58() {
    echo "";
    echo -e "  ${cyan}关键网络参数定义来源扫描：${none}";
    grep -R "default_qdisc\|tcp_congestion_control\|tcp_ecn\|tcp_fastopen\|tcp_mtu_probing\|tcp_adv_win_scale\|tcp_app_win\|rmem_max\|wmem_max\|tcp_rmem\|tcp_wmem\|rmem_default\|wmem_default" /etc/sysctl.conf /etc/sysctl.d /usr/lib/sysctl.d /lib/sysctl.d 2> /dev/null | sed 's/^/    /' || true
}
# EEX3-FUNCTION core strip_buffer_keys_from_file_e58
strip_buffer_keys_from_file_e58() {
    local f="$1" tmp key;
    test -f "$f" || return 0;
    backup_sysctl_conflict_file_e58 "$f";
    tmp=$(mktemp /tmp/sysctl_strip_e58_XXXXXX) || return 0;
    cp -af "$f" "$tmp" 2> /dev/null || { 
        rm -f "$tmp";
        return 0
    };
    while read -r key; do
        sed -i "/^[[:space:]]*${key//./\\.}[[:space:]]*=/d" "$tmp" 2> /dev/null || true;
    done < <(_sysctl_buffer_keys_e58);
    cat "$tmp" > "$f" 2> /dev/null || true;
    rm -f "$tmp" 2> /dev/null || true
}
