title() {
    echo -e "\n${blue}======================================================================${none}";
    echo -e "  ${cyan}$*${none}";
    echo -e "${blue}======================================================================${none}"
}
# EEX3-FUNCTION core toggle_buffer
toggle_buffer() {
    _e266_buffer_menu
}
# EEX3-FUNCTION core toggle_cake_flag
toggle_cake_flag() {
    local flag="$1";
    mkdir -p "$FLAGS_DIR" 2> /dev/null || true;
    if test "$(check_cake_state)" != "true"; then
        warn "CAKE 当前未启用，子项 flag 不写入，避免状态误显示。";
        clear_cake_child_flags_default;
        update_hw_boot_script;
        return 0;
    fi;
    if test -f "$FLAGS_DIR/$flag"; then
        rm -f "$FLAGS_DIR/$flag" 2> /dev/null || true;
    else
        touch "$FLAGS_DIR/$flag" 2> /dev/null || true;
    fi;
    _apply_cake_live;
    update_hw_boot_script
}
# EEX3-FUNCTION core toggle_cake_qdisc
toggle_cake_qdisc() {
    local IFACE conf;
    IFACE=$(_get_default_iface);
    conf="/etc/sysctl.d/99-network-optimized.conf";
    if test -z "$IFACE"; then
        return;
    fi;
    if test "$(check_cake_state)" = "true"; then
        apply_fq_qdisc_default;
    else
        mkdir -p /etc/modules-load.d 2> /dev/null || true;
        echo "sch_cake" > /etc/modules-load.d/cake.conf 2> /dev/null || true;
        modprobe sch_cake > /dev/null 2>&1 || true;
        mkdir -p /etc/sysctl.d 2> /dev/null || true;
        if test -f "$conf" && grep -q '^net.core.default_qdisc' "$conf" 2> /dev/null; then
            sed -i 's/^net.core.default_qdisc.*/net.core.default_qdisc = cake/' "$conf" 2> /dev/null || true;
        else
            echo 'net.core.default_qdisc = cake' >> "$conf";
        fi;
        sysctl -w net.core.default_qdisc=cake > /dev/null 2>&1 || true;
        _apply_cake_live;
    fi;
    update_hw_boot_script
}
# EEX3-FUNCTION core toggle_cpu
toggle_cpu() {
    if [ "$(check_cpu_state)" = "unsupported" ]; then
        return;
    fi;
    if [ "$(check_cpu_state)" = "true" ]; then
        for cpu in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor;
        do
            if [ -f "$cpu" ]; then
                echo schedutil > "$cpu" 2> /dev/null || echo ondemand > "$cpu" 2> /dev/null || true;
            fi;
        done;
    else
        for cpu in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor;
        do
            if [ -f "$cpu" ]; then
                echo performance > "$cpu" 2> /dev/null || true;
            fi;
        done;
    fi;
    update_hw_boot_script
}
# EEX3-FUNCTION core toggle_dnsmasq
toggle_dnsmasq() {
    if [ "$(check_dnsmasq_state)" = "true" ]; then
        systemctl stop dnsmasq > /dev/null 2>&1 || true;
        systemctl disable dnsmasq > /dev/null 2>&1 || true;
        write_static_resolv_conf;
        _safe_jq_write '.dns = {"servers":["https://1.1.1.1/dns-query","https://208.67.224.224/dns-query","https://doh.opendns.com/dns-query"], "queryStrategy":"UseIPv4"}';
        return 0;
    fi;
    export DEBIAN_FRONTEND=noninteractive;
    repair_dns_if_broken;
    apt-get update -y > /dev/null 2>&1 || yum makecache -y > /dev/null 2>&1 || true;
    apt-get install -y dnsmasq > /dev/null 2>&1 || yum install -y dnsmasq > /dev/null 2>&1 || true;
    if ! command -v dnsmasq > /dev/null 2>&1; then
        warn "dnsmasq 未安装成功，保持静态 DNS，避免 resolv.conf 指向无人监听的 127.0.0.1。";
        write_static_resolv_conf;
        return 0;
    fi;
    systemctl stop systemd-resolved 2> /dev/null || true;
    systemctl disable systemd-resolved 2> /dev/null || true;
    systemctl stop resolvconf 2> /dev/null || true;
    systemctl disable resolvconf 2> /dev/null || true;
    cat > /etc/dnsmasq.conf <<EOF
port=53
listen-address=127.0.0.1
bind-interfaces
cache-size=10000
min-cache-ttl=300
neg-ttl=60
all-servers
server=1.1.1.1
server=1.0.0.1
server=208.67.224.224
server=8.8.8.8
no-resolv
no-poll
domain-needed
bogus-priv
dns-forward-max=1024
EOF

    systemctl enable dnsmasq > /dev/null 2>&1 || true;
    if systemctl restart dnsmasq > /dev/null 2>&1 && dns_local_listener_ok; then
        cp /etc/resolv.conf /etc/resolv.conf.bak 2> /dev/null || true;
        chattr -i /etc/resolv.conf 2> /dev/null || true;
        echo "nameserver 127.0.0.1" > /etc/resolv.conf;
        chmod 644 /etc/resolv.conf 2> /dev/null || true;
        if getent hosts api.ipify.org > /dev/null 2>&1 || getent hosts google.com > /dev/null 2>&1; then
            _safe_jq_write '.dns = {"servers":["127.0.0.1"], "queryStrategy":"UseIPv4"}';
            info "dnsmasq 已启用并通过解析验证。";
        else
            warn "dnsmasq 已启动但解析验证失败，回退静态 DNS。";
            systemctl stop dnsmasq > /dev/null 2>&1 || true;
            systemctl disable dnsmasq > /dev/null 2>&1 || true;
            write_static_resolv_conf;
        fi;
    else
        warn "dnsmasq 未能监听 127.0.0.1:53，已回退静态 DNS。";
        systemctl stop dnsmasq > /dev/null 2>&1 || true;
        systemctl disable dnsmasq > /dev/null 2>&1 || true;
        write_static_resolv_conf;
    fi
}
# EEX3-FUNCTION core toggle_gso
toggle_gso() {
    local IFACE;
    IFACE=$(_get_default_iface);
    if test -z "$IFACE" || ! command -v ethtool > /dev/null 2>&1; then
        return;
    fi;
    mkdir -p "$FLAGS_DIR" 2> /dev/null || true;
    if test -f "$FLAGS_DIR/gso_off"; then
        rm -f "$FLAGS_DIR/gso_off" 2> /dev/null || true;
        apply_gso_gro_on_default;
        info "GRO/GSO/TSO 已恢复为极速默认保留。";
    else
        touch "$FLAGS_DIR/gso_off" 2> /dev/null || true;
        ethtool -K "$IFACE" gro off gso off tso off 2> /dev/null || true;
        warn "已关闭 GRO/GSO/TSO，仅建议排障短测，不建议长期。";
    fi;
    update_hw_boot_script
}
# EEX3-FUNCTION core toggle_irq
toggle_irq() {
    local IFACE=$(ip route get 1.1.1.1 2> /dev/null | awk '{print $5; exit}' || echo "");
    if [ -z "$IFACE" ]; then
        return;
    fi;
    if [ "$(check_irq_state)" = "true" ]; then
        systemctl start irqbalance 2> /dev/null || true;
        systemctl enable irqbalance 2> /dev/null || true;
    else
        systemctl stop irqbalance 2> /dev/null || true;
        systemctl disable irqbalance 2> /dev/null || true;
        local CPU=$(nproc 2> /dev/null || echo 1);
        local MASK=$(cpu_mask_all "$CPU");
        for irq in $(grep "$IFACE" /proc/interrupts 2> /dev/null | awk '{print $1}' | tr -d ':' || true);
        do
            echo "$MASK" > "/proc/irq/$irq/smp_affinity" 2> /dev/null || true;
        done;
    fi;
    update_hw_boot_script
}
# EEX3-FUNCTION core toggle_journal
toggle_journal() {
    warn "V199e137 已固定为持久化3天日志，不再切换到 volatile。";
    _e121_install_log_retention
}
# EEX3-FUNCTION core toggle_mtu
toggle_mtu() {
    local conf="/etc/sysctl.d/99-network-optimized.conf";
    if [ "$(check_mtu_state)" = "true" ]; then
        sed -i 's/^net.ipv4.tcp_mtu_probing.*/net.ipv4.tcp_mtu_probing = 0/' "$conf" 2> /dev/null || true;
    else
        if grep -q "net.ipv4.tcp_mtu_probing" "$conf" 2> /dev/null; then
            sed -i 's/^net.ipv4.tcp_mtu_probing.*/net.ipv4.tcp_mtu_probing = 1/' "$conf" 2> /dev/null || true;
        else
            echo "net.ipv4.tcp_mtu_probing = 1" >> "$conf";
        fi;
    fi;
    sysctl -p "$conf" > /dev/null 2>&1 || true
}
# EEX3-FUNCTION core toggle_process_priority
toggle_process_priority() {
    local limit_file="/etc/systemd/system/xray.service.d/limits.conf";
    if [ ! -f "$limit_file" ]; then
        return;
    fi;
    if grep -q "^OOMScoreAdjust=-500" "$limit_file" 2> /dev/null; then
        sed -i '/^OOMScoreAdjust=/d' "$limit_file" 2> /dev/null || true;
        sed -i '/^IOSchedulingClass=/d' "$limit_file" 2> /dev/null || true;
        sed -i '/^IOSchedulingPriority=/d' "$limit_file" 2> /dev/null || true;
    else
        echo "OOMScoreAdjust=-500" >> "$limit_file";
        echo "IOSchedulingClass=best-effort" >> "$limit_file";
        echo "IOSchedulingPriority=0" >> "$limit_file";
    fi;
    systemctl daemon-reload > /dev/null 2>&1 || true
}
# EEX3-FUNCTION core toggle_ring
toggle_ring() {
    apply_ring_max_adaptive_default
}
# EEX3-FUNCTION core toggle_routeonly
toggle_routeonly() {
    if [ "$(check_routeonly_state)" = "true" ]; then
        _safe_jq_write '(.inbounds[]? | select(. != null) | select(.protocol=="vless" or .protocol=="shadowsocks") | .sniffing.routeOnly) = false';
    else
        _safe_jq_write '(.inbounds[]? | select(. != null) | select(.protocol=="vless" or .protocol=="shadowsocks") | .sniffing.routeOnly) = true';
    fi
}
# EEX3-FUNCTION core toggle_thp
toggle_thp() {
    if [ "$(check_thp_state)" = "true" ]; then
        echo always > /sys/kernel/mm/transparent_hugepage/enabled 2> /dev/null || true;
        echo always > /sys/kernel/mm/transparent_hugepage/defrag 2> /dev/null || true;
    else
        echo never > /sys/kernel/mm/transparent_hugepage/enabled 2> /dev/null || true;
        echo never > /sys/kernel/mm/transparent_hugepage/defrag 2> /dev/null || true;
    fi;
    update_hw_boot_script
}
# EEX3-FUNCTION core toggle_zram
toggle_zram() {
    enforce_swap_cap_1024_e52
}
# EEX3-FUNCTION core update_hw_boot_script
update_hw_boot_script() {
    cat > /usr/local/bin/xray-hw-tweaks.sh <<'EOF_E51_HW'
#!/bin/bash
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
CONFIG_DIR="/usr/local/etc/xray"
FLAGS_DIR="$CONFIG_DIR/flags"
CAKE_OPTS_FILE="$CONFIG_DIR/cake_opts.txt"
IFACE=$(ip route get 1.1.1.1 2>/dev/null | awk '{print $5; exit}' || true)
ring_value() {
    local section="$1" key="$2" iface="$3"
    ethtool -g "$iface" 2>/dev/null | awk -v section="$section" -v key="$key" '
        $0 ~ section {flag=1; next}
        flag && $0 ~ /^[[:space:]]*[A-Za-z ]+:/ {
            gsub(/^[[:space:]]+|[[:space:]]+$/, "", $1)
            if ($1 == key ":" && $2 ~ /^[0-9]+$/) {print $2; exit}
        }
    '
}
want_cake=0
if grep -q '^net.core.default_qdisc[[:space:]]*=[[:space:]]*cake' /etc/sysctl.d/98-xray-core-tuning.conf 2>/dev/null; then want_cake=1; fi
if grep -q '^sch_cake$' /etc/modules-load.d/cake.conf 2>/dev/null; then want_cake=1; fi
if test -n "$IFACE"; then
    if test -f "$FLAGS_DIR/gso_off"; then
        ethtool -K "$IFACE" gro off gso off tso off 2>/dev/null || true
    else
        ethtool -K "$IFACE" gro on gso on tso on 2>/dev/null || true
        ethtool -K "$IFACE" lro off rx-gro-hw on tx-udp-segmentation on 2>/dev/null || true
    fi
    ethtool -C "$IFACE" adaptive-rx on 2>/dev/null || true
    ip link set dev "$IFACE" txqueuelen 3000 2>/dev/null || true
    if test -f "$FLAGS_DIR/ring_max_adaptive" && command -v ethtool >/dev/null 2>&1 && ethtool -g "$IFACE" >/dev/null 2>&1; then
        MAX_RX=$(ring_value "Pre-set maximums" "RX" "$IFACE")
        MAX_TX=$(ring_value "Pre-set maximums" "TX" "$IFACE")
        if echo "${MAX_RX:-}" | grep -Eq '^[0-9]+$'; then
            if ! echo "${MAX_TX:-}" | grep -Eq '^[0-9]+$'; then MAX_TX="$MAX_RX"; fi
            echo "$MAX_RX" > "$CONFIG_DIR/ring_target_rx.txt" 2>/dev/null || true
            echo "$MAX_TX" > "$CONFIG_DIR/ring_target_tx.txt" 2>/dev/null || true
            echo "$MAX_RX" > "$CONFIG_DIR/ring_target.txt" 2>/dev/null || true
            echo "max" > "$CONFIG_DIR/ring_mode.txt" 2>/dev/null || true
            ethtool -G "$IFACE" rx "$MAX_RX" tx "$MAX_TX" 2>/dev/null || ethtool -G "$IFACE" rx "$MAX_RX" 2>/dev/null || true
        fi
    fi
    if command -v tc >/dev/null 2>&1; then
        if test "$want_cake" -eq 1; then
            modprobe sch_cake >/dev/null 2>&1 || true
            CAKE_OPTS=""; test -s "$CAKE_OPTS_FILE" && CAKE_OPTS=$(cat "$CAKE_OPTS_FILE" 2>/dev/null || true)
            ACK=""; ECN=""; WASH=""; test -f "$FLAGS_DIR/ack_filter" && ACK="ack-filter"; test -f "$FLAGS_DIR/ecn" && ECN="ecn"; test -f "$FLAGS_DIR/wash" && WASH="wash"
            tc qdisc replace dev "$IFACE" root cake $CAKE_OPTS $ACK $ECN $WASH 2>/dev/null || tc qdisc replace dev "$IFACE" root fq 2>/dev/null || true
            sysctl -w net.core.default_qdisc=cake >/dev/null 2>&1 || true
        else
            tc qdisc replace dev "$IFACE" root fq 2>/dev/null || true
            sysctl -w net.core.default_qdisc=fq >/dev/null 2>&1 || true
        fi
    fi
fi
if test -w /sys/kernel/mm/transparent_hugepage/enabled; then echo never > /sys/kernel/mm/transparent_hugepage/enabled 2>/dev/null || true; fi
if test -w /sys/kernel/mm/transparent_hugepage/defrag; then echo never > /sys/kernel/mm/transparent_hugepage/defrag 2>/dev/null || true; fi
for cpu in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do test -f "$cpu" && echo performance > "$cpu" 2>/dev/null || true; done
if test -f "$CONFIG_DIR/initcwnd.txt"; then
    CWND_VAL=$(cat "$CONFIG_DIR/initcwnd.txt" 2>/dev/null || echo "10"); DEF_ROUTE=$(ip route show default 2>/dev/null | head -n 1)
    if test -n "$DEF_ROUTE"; then CLEAN_ROUTE=$(echo "$DEF_ROUTE" | sed 's/ initcwnd [0-9]*//g' | sed 's/ initrwnd [0-9]*//g'); ip route change $CLEAN_ROUTE initcwnd "$CWND_VAL" initrwnd "$CWND_VAL" 2>/dev/null || true; fi
fi
modprobe iptable_mangle >/dev/null 2>&1 || true
modprobe xt_TCPMSS >/dev/null 2>&1 || true
iptables -t mangle -N XRAY_MSS_CLAMP 2>/dev/null || true
iptables -t mangle -F XRAY_MSS_CLAMP 2>/dev/null || true
iptables -t mangle -A XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null || true
iptables -t mangle -C POSTROUTING -j XRAY_MSS_CLAMP 2>/dev/null || iptables -t mangle -A POSTROUTING -j XRAY_MSS_CLAMP 2>/dev/null || true
EOF_E51_HW

    chmod +x /usr/local/bin/xray-hw-tweaks.sh 2> /dev/null || true;
    cat > /etc/systemd/system/xray-hw-tweaks.service <<'EOF_E51_SVC'
[Unit]
Description=Xray Hardware Tweaks Safe Defaults
Wants=network-online.target
After=network-online.target
Before=xray.service

[Service]
Type=oneshot
ExecStart=/usr/local/bin/xray-hw-tweaks.sh
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF_E51_SVC

    systemctl daemon-reload > /dev/null 2>&1 || true;
    systemctl enable xray-hw-tweaks.service > /dev/null 2>&1 || true;
    /usr/local/bin/xray-hw-tweaks.sh > /dev/null 2>&1 || true
}
# EEX3-FUNCTION core valid_domain
valid_domain() {
    local d="${1:-}";
    [[ "$d" =~ ^([A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$ ]]
}
# EEX3-FUNCTION core validate_port
validate_port() {
    local p="$1";
    if test -z "$p"; then
        return 1;
    fi;
    if ! [[ "$p" =~ ^[0-9]+$ ]]; then
        return 1;
    fi;
    if test "$p" -lt 1 2> /dev/null || test "$p" -gt 65535 2> /dev/null; then
        return 1;
    fi;
    if ss -H -tuln 2> /dev/null | awk '{print $5}' | grep -Eq "(^|:|\])${p}$"; then
        error "端口 $p 已被系统占用。";
        return 1;
    fi;
    return 0
}
# EEX3-FUNCTION core verify_dns_available
verify_dns_available() {
    if getent hosts api.ipify.org > /dev/null 2>&1 || getent hosts google.com > /dev/null 2>&1; then
        return 0;
    fi;
    repair_dns_if_broken;
    getent hosts api.ipify.org > /dev/null 2>&1 || getent hosts google.com > /dev/null 2>&1
}
# EEX3-FUNCTION core verify_e52_post_state
verify_e52_post_state() {
    local fail=0 buf pol env cron_bad dns_state ring_state zram_state swap_total;
    buf=$(jq -r '.policy.levels["0"].bufferSize // empty' "$CONFIG" 2> /dev/null || echo "");
    pol=$(jq -r '.policy.levels["0"].connIdle // empty' "$CONFIG" 2> /dev/null || echo "");
    env=$(systemctl cat xray 2> /dev/null | grep -i 'XRAY_RAY_BUFFER_SIZE' || true);
    cron_bad=$(crontab -l 2> /dev/null | grep -F "$UPDATE_DAT_SCRIPT" || true);
    dns_state=$(check_dnsmasq_state);
    ring_state=$(check_ring_state);
    zram_state=$(check_zram_state);
    swap_total=$(_swap_total_mb);
    if test "${swap_total:-0}" -gt 1024 2> /dev/null; then
        error "Swap 总量超过 1024MB：当前约 ${swap_total}MB";
        fail=1;
    fi;
    if test "$buf" != "$(_e266_buffer_managed_intent_readonly 2> /dev/null || _eex7_default_buffer)"; then
        error "Buffer 未落地：当前值=${buf:-MISSING}";
        fail=1;
    fi;
    if test "$pol" != "260"; then
        error "Policy connIdle 未落地：当前值=${pol:-MISSING}";
        fail=1;
    fi;
    if test -n "$env" && ! _e266_buffer_dropin_exact "$E266_BUFFER_DROPIN"; then
        error "systemd 仍残留 XRAY_RAY_BUFFER_SIZE：$env";
        fail=1;
    fi;
    if test "$dns_state" != "true"; then
        warn "Dnsmasq 未处于接管状态；可能是安装失败、端口 53 被占用或系统不允许。已保留静态 DNS 防断联。";
    fi;
    if test "$ring_state" = "false"; then
        warn "Ring Buffer 未能设置到 RX/TX 硬件最大值；可能是云厂商虚拟网卡限制。";
    fi;
    if test "$zram_state" != "true"; then
        warn "ZRAM 未处于 1024MB 上限模式；若系统不支持 ZRAM，则会使用 /swapfile 兜底。";
    fi;
    if test -n "$cron_bad"; then
        warn "检测到旧 cron 仍含 update-dat 脚本，建议手动检查 crontab -l。";
    fi;
    systemctl is-enabled xray-dat-update.timer > /dev/null 2>&1 && warn "xray-dat-update.timer 仍处于启用状态；e103 会在热更新收尾阶段禁用。";
    return "$fail"
}
# EEX3-FUNCTION core verify_e55_post_state
verify_e55_post_state() {
    verify_e52_post_state || return 1;
    echo "$SCRIPT_VERSION" > "$SCRIPT_VERSION_FILE" 2> /dev/null || true;
    return 0
}
# EEX3-FUNCTION core verify_e58_post_state
verify_e58_post_state() {
    verify_e63_post_state
}
# EEX3-FUNCTION core verify_e60_post_state
verify_e60_post_state() {
    local fail=0 rv perm;
    if test -e "/etc/sysctl.d/99-xray-hotupdate-fast.conf"; then
        error "旧冲突文件仍存在：/etc/sysctl.d/99-xray-hotupdate-fast.conf";
        fail=1;
    fi;
    for pat in '^net\.core\.default_qdisc[[:space:]]*=[[:space:]]*fq' '^net\.ipv4\.tcp_congestion_control[[:space:]]*=[[:space:]]*bbr' '^net\.ipv4\.tcp_ecn[[:space:]]*=[[:space:]]*0' '^net\.ipv4\.tcp_fastopen[[:space:]]*=[[:space:]]*0' '^net\.ipv4\.tcp_mtu_probing[[:space:]]*=[[:space:]]*1' '^net\.ipv4\.tcp_adv_win_scale[[:space:]]*=[[:space:]]*1' '^net\.ipv4\.tcp_app_win[[:space:]]*=[[:space:]]*31' '^net\.core\.rmem_default[[:space:]]*=[[:space:]]*7990577' '^net\.core\.wmem_default[[:space:]]*=[[:space:]]*7990577' '^net\.core\.rmem_max[[:space:]]*=[[:space:]]*97108868' '^net\.core\.wmem_max[[:space:]]*=[[:space:]]*97108868' '^net\.ipv4\.tcp_rmem[[:space:]]*=[[:space:]]*4096[[:space:]]+7990577[[:space:]]+97108868' '^net\.ipv4\.tcp_wmem[[:space:]]*=[[:space:]]*4096[[:space:]]+7990577[[:space:]]+97108868';
    do
        if ! grep -Eq "$pat" "$NETWORK_OPT_CONF" 2> /dev/null; then
            error "网络参数永久文件缺失匹配项：$pat";
            fail=1;
        fi;
    done;
    for kv in 'net.core.default_qdisc fq' 'net.ipv4.tcp_congestion_control bbr' 'net.ipv4.tcp_ecn 0' 'net.ipv4.tcp_fastopen 0' 'net.ipv4.tcp_mtu_probing 1' 'net.ipv4.tcp_adv_win_scale 1' 'net.ipv4.tcp_app_win 31' 'net.core.rmem_default 7990577' 'net.core.wmem_default 7990577' 'net.core.rmem_max 97108868' 'net.core.wmem_max 97108868';
    do
        set -- $kv;
        rv=$(sysctl -n "$1" 2> /dev/null || echo "");
        if test "$rv" != "$2"; then
            warn "当前运行 $1=$rv，与 V198e66 默认 $2 不一致。";
        fi;
    done;
    rv=$(sysctl -n net.ipv4.tcp_rmem 2> /dev/null | tr '\t' ' ' | tr -s ' ' || echo "");
    if test "$rv" != "4096 7990577 97108868"; then
        warn "当前运行 net.ipv4.tcp_rmem=$rv，与默认不一致。";
    fi;
    rv=$(sysctl -n net.ipv4.tcp_wmem 2> /dev/null | tr '\t' ' ' | tr -s ' ' || echo "");
    if test "$rv" != "4096 7990577 97108868"; then
        warn "当前运行 net.ipv4.tcp_wmem=$rv，与默认不一致。";
    fi;
    echo "$SCRIPT_VERSION" > "$SCRIPT_VERSION_FILE" 2> /dev/null || true;
    return "$fail"
}
# EEX3-FUNCTION core verify_e63_post_state
verify_e63_post_state() {
    verify_e60_post_state
}
# EEX3-FUNCTION core verify_e65_post_state
verify_e65_post_state() {
    local fail=0;
    verify_e63_post_state || fail=1;
    for pair in "net.core.default_qdisc fq" "net.ipv4.tcp_congestion_control bbr" "net.ipv4.tcp_ecn 0" "net.ipv4.tcp_fastopen 0" "net.ipv4.tcp_mtu_probing 1" "net.ipv4.tcp_adv_win_scale 1" "net.ipv4.tcp_app_win 31" "net.ipv4.tcp_notsent_lowat 131072" "net.core.busy_poll 0" "net.core.busy_read 0" "net.core.rmem_default 7990577" "net.core.wmem_default 7990577" "net.core.rmem_max 97108868" "net.core.wmem_max 97108868";
    do
        local key want got;
        key=$(printf '%s' "$pair" | awk '{print $1}');
        want=$(printf '%s' "$pair" | awk '{print $2}');
        got=$(sysctl -n "$key" 2> /dev/null | awk '{$1=$1; print}' || echo "");
        if test "$got" != "$want"; then
            warn "关键运行值未完全匹配：$key 当前=$got 目标=$want";
        fi;
    done;
    grep -Eq '^net\.ipv4\.tcp_notsent_lowat[[:space:]]*=[[:space:]]*262144' "$NETWORK_OPT_CONF" 2> /dev/null || { 
        error "永久配置未写入 tcp_notsent_lowat=131072";
        fail=1
    };
    grep -Eq '^net\.core\.busy_poll[[:space:]]*=[[:space:]]*0' "$NETWORK_OPT_CONF" 2> /dev/null || { 
        error "永久配置未写入 busy_poll=0";
        fail=1
    };
    return "$fail"
}
# EEX3-FUNCTION core verify_e66_post_state
verify_e66_post_state() {
    local fail=0 key want got;
    for pair in "net.core.default_qdisc fq" "net.ipv4.tcp_congestion_control bbr" "net.ipv4.tcp_ecn 0" "net.ipv4.tcp_fastopen 0" "net.ipv4.tcp_mtu_probing 1" "net.ipv4.tcp_adv_win_scale 1" "net.ipv4.tcp_app_win 31" "net.ipv4.tcp_notsent_lowat 131072" "net.core.busy_poll 0" "net.core.busy_read 0" "net.core.rmem_default 7990577" "net.core.wmem_default 7990577" "net.core.rmem_max 97108868" "net.core.wmem_max 97108868";
    do
        key=$(printf '%s' "$pair" | awk '{print $1}');
        want=$(printf '%s' "$pair" | awk '{print $2}');
        got=$(sysctl -n "$key" 2> /dev/null | awk '{$1=$1; print}' || echo "");
        if test "$got" != "$want"; then
            warn "关键运行值未匹配：$key 当前=$got 目标=$want";
            fail=1;
        fi;
    done;
    got=$(sysctl -n net.ipv4.tcp_rmem 2> /dev/null | awk '{$1=$1; print}' || echo "");
    test "$got" = "4096 7990577 97108868" || { 
        warn "关键运行值未匹配：net.ipv4.tcp_rmem 当前=$got";
        fail=1
    };
    got=$(sysctl -n net.ipv4.tcp_wmem 2> /dev/null | awk '{$1=$1; print}' || echo "");
    test "$got" = "4096 7990577 97108868" || { 
        warn "关键运行值未匹配：net.ipv4.tcp_wmem 当前=$got";
        fail=1
    };
    grep -Eq '^net\.ipv4\.tcp_notsent_lowat[[:space:]]*=[[:space:]]*262144' "$NETWORK_OPT_CONF" 2> /dev/null || { 
        error "永久配置未写入 tcp_notsent_lowat=131072";
        fail=1
    };
    grep -Eq '^net\.core\.busy_poll[[:space:]]*=[[:space:]]*0' "$NETWORK_OPT_CONF" 2> /dev/null || { 
        error "永久配置未写入 busy_poll=0";
        fail=1
    };
    iptables -t mangle -S XRAY_MSS_CLAMP > /dev/null 2>&1 || { 
        warn "未发现 XRAY_MSS_CLAMP 链，MSS 钳制可能未落地。";
        fail=1
    };
    return "$fail"
}
# EEX3-FUNCTION core verify_e68_post_state
verify_e68_post_state() {
    local fail=0 tz dns_state xrv_head;
    if declare -F verify_e66_post_state > /dev/null 2>&1; then
        verify_e66_post_state || fail=1;
    fi;
    tz=$(timedatectl show -p Timezone --value 2> /dev/null || cat /etc/timezone 2> /dev/null || echo "");
    if test "$tz" != "Asia/Singapore"; then
        warn "时区未匹配：当前=$tz，目标=Asia/Singapore";
        fail=1;
    fi;
    dns_state=$(check_dnsmasq_state 2> /dev/null || echo false);
    if test "$dns_state" != "true"; then
        warn "Dnsmasq 稳态缓存未接管；可能已回退静态 DNS。可进入 10→6→12 重试，或 10→2 使用静态 DNS 急救。";
    fi;
    if ! command -v xrv > /dev/null 2>&1; then
        error "xrv 快捷入口不存在。";
        fail=1;
    else
        xrv_head=$(head -n 5 "$(command -v xrv)" 2> /dev/null | tr '\n' ' ' || true);
        echo "$xrv_head" | grep -q 'ex198e75' || warn "xrv 已存在，但文件头未明确显示 ex198e75；请确认 /usr/local/bin/xrv 是否为最新脚本。";
    fi;
    return "$fail"
}
# EEX3-FUNCTION core verify_sni_strict
verify_sni_strict() {
    local target="$1" out verify=0;
    valid_domain "$target" || return 1;
    out=$(timeout 10 openssl s_client -connect "$target:443" -servername "$target" -verify_hostname "$target" -verify_return_error -alpn h2 -tls1_3 < /dev/null 2>&1 || true);
    grep -qi 'Verification: OK\|Verify return code: 0' <<< "$out" || verify=1;
    grep -qi 'TLSv1.3\|TLSv1\.3' <<< "$out" || verify=1;
    grep -qiE 'ALPN.*h2|ALPN protocol: h2' <<< "$out" || verify=1;
    if test "$verify" -ne 0; then
        error "SNI证书主机名/TLS1.3/ALPN h2质检未全部通过。";
        printf '%s\n' "$out" | tail -n 20 | sed 's/^/    /';
        return 1;
    fi;
    info "SNI证书主机名、TLS1.3和ALPN h2质检通过。"
}
