# EEX3-FUNCTION core write_safe_global_limits
write_safe_global_limits() {
    mkdir -p /etc/security/limits.d /etc/systemd/system.conf.d "$BACKUP_DIR" 2> /dev/null || true;
    cp -a /etc/security/limits.d/99-xray-limits.conf "$BACKUP_DIR/99-xray-limits.conf.e43.$(date +%Y%m%d_%H%M%S).bak" 2> /dev/null || true;
    cp -a /etc/systemd/system.conf.d/99-xray-limits.conf "$BACKUP_DIR/systemd-99-xray-limits.conf.e43.$(date +%Y%m%d_%H%M%S).bak" 2> /dev/null || true;
    cat > /etc/security/limits.d/99-xray-limits.conf <<'EOF_E44_LIMITS'
root soft nofile 1048576
root hard nofile 1048576
root soft nproc 65535
root hard nproc 65535
root soft core 0
root hard core unlimited
root soft stack 8192
root hard stack 65536

* soft nofile 1048576
* hard nofile 1048576
* soft nproc 65535
* hard nproc 65535
* soft core 0
* hard core unlimited
* soft stack 8192
* hard stack 65536
EOF_E44_LIMITS

    if test -f /etc/pam.d/common-session && ! grep -q "pam_limits.so" /etc/pam.d/common-session 2> /dev/null; then
        echo "session required pam_limits.so" >> /etc/pam.d/common-session;
    fi;
    if test -f /etc/pam.d/common-session-noninteractive && ! grep -q "pam_limits.so" /etc/pam.d/common-session-noninteractive 2> /dev/null; then
        echo "session required pam_limits.so" >> /etc/pam.d/common-session-noninteractive;
    fi;
    cat > /etc/systemd/system.conf.d/99-xray-limits.conf <<'EOF_E44_MANAGER_LIMITS'
[Manager]
DefaultLimitNOFILE=1048576
DefaultLimitNPROC=65535
DefaultLimitSTACK=8M
DefaultTasksMax=80%
EOF_E44_MANAGER_LIMITS

}
# EEX3-FUNCTION core write_static_resolv_conf
write_static_resolv_conf() {
    e67_install_static_dns_guard "1.1.1.1" "8.8.8.8" "208.67.224.224"
}
# EEX3-FUNCTION core xray_cpu_list
xray_cpu_list() {
    local n="${1:-$(nproc 2> /dev/null || echo 1)}" i out="";
    if ! [[ "$n" =~ ^[0-9]+$ ]] || test "$n" -lt 1 2> /dev/null; then
        n=1;
    fi;
    for ((i=0; i<n; i++))
    do
        out+="${i} ";
    done;
    echo "${out% }"
}
