# EEX3-FUNCTION legacy_e0_117 _e102_bbr3_flow
_e102_bbr3_flow() {
    local m conf go cfgv;
    while true; do
        cfgv="$(_e89_bbr_kconfig_value 2> /dev/null || echo unknown)";
        title "V198e105：BBR3 / XanMod → bbrx3_v1 参数中心";
        echo "  当前替换路线：$(_e102_bbr_mode_text)";
        if test "$cfgv" = "y"; then
            echo -e "  ${yellow}提示：当前是内置型 y；2/3/4 会最终转入完整内核编译，不能热替换 .ko。也可直接返回 17 菜单选 9。${none}";
        fi;
        echo "";
        echo "  1) 查看参数表：参数 / 原版 BBR3 / bbrx3_v1 建议 / 说明";
        echo "  2) 使用 bbrx3_v1 推荐参数生成配置";
        echo "  3) 自定义全部参数并生成配置（输入时同步显示参数表字段，?=完整表）";
        echo "  4) 使用当前配置替换 bbr / 内置型则完整编译新内核";
        echo "  7) 解释/检查内置型 y 与模块型 m 的区别";
        echo "  9) 内置型 BBR：完整内核源码补丁编译新内核（1000MB门槛）";
        echo "  0) 返回";
        read -rp "请选择: " m || true;
        case "${m:-}" in 
            1)
                _e89_show_bbr3_table;
                _e102_pause
            ;;
            2)
                _e89_collect_bbr3_params recommended || return;
                conf="$(_e89_write_bbr3_conf)";
                info "已写入：$conf";
                read -rp "是否立即替换 bbr / 内置型完整编译？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbr3 "$conf";
                _e102_pause
            ;;
            3)
                _e89_collect_bbr3_params custom || return;
                conf="$(_e89_write_bbr3_conf)";
                info "已写入：$conf";
                read -rp "是否立即替换 bbr / 内置型完整编译？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbr3 "$conf";
                _e102_pause
            ;;
            4)
                conf="$E89_BBRX_CURRENT/bbr3_replace.conf";
                if test -f "$conf"; then
                    _e89_build_replace_bbr bbr3 "$conf";
                else
                    warn "配置不存在，请先执行 2 或 3。";
                fi;
                _e102_pause
            ;;
            7)
                _e102_builtin_explain;
                _e102_pause
            ;;
            9)
                _e102_builtin_bbr_full_compile_menu
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION legacy_e0_117 _e102_bbr_compile_mode_text
_e102_bbr_compile_mode_text() {
    local cfgv;
    cfgv="$(_e89_bbr_kconfig_value 2> /dev/null || echo unknown)";
    case "$cfgv" in 
        m)
            echo "模块型 m：只允许匹配当前内核的 tcp_bbr.c 外部快编；拒绝跨版本源码"
        ;;
        y)
            echo "内置型 y：不能热替换 .ko；请走 9) 完整内核源码补丁编译新内核"
        ;;
        *)
            echo "未知：请先执行自动检测，禁止盲改"
        ;;
    esac
}
# EEX3-FUNCTION legacy_e0_117 _e102_bbr_find_or_prepare_source
_e102_bbr_find_or_prepare_source() {
    local src="" cfgv;
    cfgv="$(_e89_bbr_kconfig_value 2> /dev/null || echo unknown)";
    src="$(_e102_find_current_module_tcp_bbr_source_now 2> /dev/null || true)";
    if _e102_valid_current_bbr_module_source "$src"; then
        echo "$src";
        return 0;
    fi;
    _e102_extract_matching_linux_source_tars > /dev/null 2>&1 || true;
    src="$(_e102_find_current_module_tcp_bbr_source_now 2> /dev/null || true)";
    if _e102_valid_current_bbr_module_source "$src"; then
        echo "$src";
        return 0;
    fi;
    if test "$cfgv" = "m"; then
        _e102_try_install_current_linux_source;
        _e102_extract_matching_linux_source_tars > /dev/null 2>&1 || true;
        src="$(_e102_find_current_module_tcp_bbr_source_now 2> /dev/null || true)";
        if _e102_valid_current_bbr_module_source "$src"; then
            echo "$src";
            return 0;
        fi;
    fi;
    return 1
}
