# EEX3-FUNCTION legacy_e0_117 _e102_build_replace_bbr_module
_e102_build_replace_bbr_module() {
    local kind="$1" conf="$2" cfgv modp src work newko bdir release_now timeout_s kbuild;
    title "V198e105：模块型 BBR 严格快编热替换（只编 tcp_bbr.ko）";
    _e89_bbr_prepare_dirs;
    _e102_prepare_dirs;
    cfgv="$(_e89_bbr_kconfig_value 2> /dev/null || echo unknown)";
    modp="$(_e89_bbr_mod_path 2> /dev/null || true)";
    kbuild="/lib/modules/$(uname -r)/build";
    if test "$cfgv" != "m"; then
        error "当前 CONFIG_TCP_CONG_BBR=$cfgv，不是模块型 m。";
        return 1;
    fi;
    if test -z "$modp" || test ! -f "$modp"; then
        error "未找到原版 tcp_bbr.ko 路径，拒绝替换。";
        return 1;
    fi;
    if test ! -d "$kbuild"; then
        warn "缺少 $kbuild，尝试安装当前内核 headers。";
        export DEBIAN_FRONTEND=noninteractive;
        apt-get update -y > /dev/null 2>&1 || true;
        apt-get install -y "linux-headers-$(uname -r)" > /dev/null 2>&1 || true;
    fi;
    if test ! -d "$kbuild"; then
        error "仍缺少 $kbuild，无法外部模块快编。";
        return 1;
    fi;
    src="$(_e102_bbr_find_or_prepare_source 2> /dev/null || true)";
    if ! _e102_valid_current_bbr_module_source "$src"; then
        error "未找到与当前内核匹配且可被当前 headers 编译的 tcp_bbr.c。";
        warn "已拒绝跨版本源码快编，避免 6.1 内核误用 linux-6.8 源码产生 __bpf_kfunc/ABI 错误。";
        warn "可先执行 17 → 7 查看严格检查结果。";
        return 1;
    fi;
    info "使用匹配源码：$src";
    if declare -F _e91_conf_sane > /dev/null 2>&1; then
        _e91_conf_sane "$conf" "$kind" || return 1;
    fi;
    bdir="$(_e89_bbr_backup_state)" || { 
        error "备份失败，拒绝继续。";
        return 1
    };
    _e89_bbr_write_original_param_note "$bdir" "$kind";
    cp -af "$conf" "$bdir/generated_new_params.conf" 2> /dev/null || true;
    cp -af "$src" "$bdir/tcp_bbr.c.source.used" 2> /dev/null || true;
    echo "$src" > "$bdir/source.path.txt" 2> /dev/null || true;
    info "已创建替换前完整备份：$bdir";
    work="$E89_BBRX_BUILD_ROOT/build_$(_e102_ts)_$kind";
    mkdir -p "$work" || return 1;
    cp -af "$src" "$work/tcp_bbr.c";
    cp -af "$work/tcp_bbr.c" "$bdir/tcp_bbr.c.new.before_patch" 2> /dev/null || true;
    _e89_patch_bbr_source_from_conf "$work/tcp_bbr.c" "$conf" "$kind" || { 
        error "源码补丁后自检失败，拒绝编译。";
        return 1
    };
    cp -af "$work/tcp_bbr.c" "$bdir/tcp_bbr.c.new" 2> /dev/null || true;
    cat > "$work/Makefile" <<'EOF_MAKE_E102'
obj-m := tcp_bbr.o
EOF_MAKE_E102

    timeout_s="900";
    if declare -F _e97_module_make_timeout > /dev/null 2>&1; then
        timeout_s="$(_e97_module_make_timeout 2> /dev/null || echo 900)";
    fi;
    info "开始外部模块快编 tcp_bbr.ko：$work";
    info "命令：timeout ${timeout_s}s make -j1 -C $kbuild M=$work modules";
    if ! timeout "${timeout_s}s" make -j1 -C "$kbuild" M="$work" modules; then
        error "外部模块快编失败或超时，原系统未替换。工作目录：$work";
        warn "若错误含 __bpf_kfunc/结构体字段缺失，说明源码仍与当前 headers 不兼容。";
        return 1;
    fi;
    newko="$work/tcp_bbr.ko";
    if test ! -f "$newko"; then
        error "编译后未发现 $newko，拒绝替换。";
        return 1;
    fi;
    cp -af "$newko" "$bdir/tcp_bbr.ko.new" 2> /dev/null || true;
    sha256sum "$newko" > "$bdir/tcp_bbr.ko.new.sha256" 2> /dev/null || true;
    cat > "$bdir/rollback.sh" <<EOF_ROLLBACK_E102
#!/usr/bin/env bash
set -e
ORIG_KO="$modp"
BACKUP_DIR="$bdir"
sysctl -w net.ipv4.tcp_congestion_control=cubic >/dev/null 2>&1 || true
modprobe -r tcp_bbr 2>/dev/null || rmmod tcp_bbr 2>/dev/null || true
if test -f "\$BACKUP_DIR/tcp_bbr.ko.orig"; then cp -af "\$BACKUP_DIR/tcp_bbr.ko.orig" "\$ORIG_KO"; fi
depmod -a
modprobe tcp_bbr || true
sysctl -w net.ipv4.tcp_congestion_control=bbr >/dev/null 2>&1 || true
echo "rollback done"
EOF_ROLLBACK_E102

    chmod +x "$bdir/rollback.sh" 2> /dev/null || true;
    warn "准备替换原模块：$modp";
    read -rp "是否临时切到 cubic 并尝试卸载旧 tcp_bbr 后立即热替换？[Y/n]: " release_now || true;
    release_now="${release_now:-Y}";
    if [[ "$release_now" =~ ^[yY]$ ]]; then
        sysctl -w net.ipv4.tcp_congestion_control=cubic > /dev/null 2>&1 || true;
        modprobe -r tcp_bbr 2> /dev/null || rmmod tcp_bbr 2> /dev/null || warn "旧 tcp_bbr 当前仍被引用，磁盘替换仍会执行；可能需重启后完全生效。";
    fi;
    if declare -F _e89_install_new_ko_to_original_path > /dev/null 2>&1; then
        _e89_install_new_ko_to_original_path "$newko" "$modp" || { 
            error "写入 $modp 失败，已保留备份：$bdir";
            return 1
        };
    else
        cp -af "$newko" "$modp" || { 
            error "写入 $modp 失败，已保留备份：$bdir";
            return 1
        };
    fi;
    depmod -a > /dev/null 2>&1 || true;
    modprobe tcp_bbr 2> /dev/null || warn "modprobe tcp_bbr 未立即成功；如果旧模块仍在内存中，请重启后验证。";
    sysctl -w net.ipv4.tcp_congestion_control=bbr > /dev/null 2>&1 || true;
    echo "tcp_bbr" > "$E89_BBRX_MODULES_LOAD" 2> /dev/null || true;
    info "V198e105 模块型 BBR 快编替换完成。备份目录：$bdir";
    warn "请验证：sysctl net.ipv4.tcp_congestion_control && modinfo tcp_bbr | head && ss -tin";
    return 0
}
# EEX3-FUNCTION legacy_e0_117 _e102_builtin_bbr_full_compile_menu
_e102_builtin_bbr_full_compile_menu() {
    local m conf go cfgv;
    while true; do
        cfgv="$(_e89_bbr_kconfig_value 2> /dev/null || echo unknown)";
        title "V198e105：内置型 BBR 完整源码补丁编译入口";
        echo "  当前替换路线：$(_e102_bbr_mode_text)";
        echo "  CONFIG_TCP_CONG_BBR：$cfgv";
        echo "  编译门槛：Mem+Swap >= 1000MB；仍需手动 export 授权，热更新不会自动编译内核。";
        echo "";
        echo "  1) 仅运行完整编译前硬门禁检查（不编译）";
        echo "  2) 使用 bbrx3_v1 推荐参数 → 完整编译新内核";
        echo "  3) 自定义 BBR3/XanMod 参数 → 完整编译新内核";
        echo "  4) 使用当前 bbr3_replace.conf → 完整编译新内核";
        echo "  5) 使用普通 BBR v1 推荐参数 → 完整编译新内核（不建议 XanMod/BBR3）";
        echo "  7) 查看内置型 y 与模块型 m 说明";
        echo "  8 ) 解释：为什么完整编译会卡在 i40e/iavf/ice";
        echo "  0) 返回";
        read -rp "请选择: " m || true;
        case "${m:-}" in 
            1)
                _e102_builtin_full_compile_precheck "bbr3" "$E89_BBRX_CURRENT/bbr3_replace.conf" || true;
                _e102_pause
            ;;
            2)
                _e89_collect_bbr3_params recommended || return;
                conf="$(_e89_write_bbr3_conf)";
                info "已写入：$conf";
                read -rp "确认走完整内核源码补丁编译？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e90_build_builtin_bbr_kernel bbr3 "$conf";
                _e102_pause
            ;;
            3)
                _e89_collect_bbr3_params custom || return;
                conf="$(_e89_write_bbr3_conf)";
                info "已写入：$conf";
                read -rp "确认走完整内核源码补丁编译？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e90_build_builtin_bbr_kernel bbr3 "$conf";
                _e102_pause
            ;;
            4)
                conf="$E89_BBRX_CURRENT/bbr3_replace.conf";
                if test -f "$conf"; then
                    read -rp "确认使用 $conf 完整编译新内核？[y/N]: " go || true;
                    [[ "$go" =~ ^[yY]$ ]] && _e90_build_builtin_bbr_kernel bbr3 "$conf";
                else
                    warn "配置不存在，请先执行 2 或 3。";
                fi;
                _e102_pause
            ;;
            5)
                _e89_collect_bbrv1_params recommended || return;
                conf="$(_e89_write_bbrv1_conf)";
                info "已写入：$conf";
                warn "当前若为 XanMod/BBR3，不建议用 BBR v1 模板。";
                read -rp "仍确认完整编译新内核？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e90_build_builtin_bbr_kernel bbrv1 "$conf";
                _e102_pause
            ;;
            7)
                _e102_builtin_explain;
                _e102_pause
            ;;
            8)
                if declare -F _e97_why_intel_compile_stuck > /dev/null 2>&1; then
                    _e97_why_intel_compile_stuck;
                else
                    _e102_builtin_explain;
                fi;
                _e102_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION legacy_e0_117 _e102_builtin_explain
_e102_builtin_explain() {
    title "V198e105：内置型 BBR / XanMod 说明";
    cat <<'EOF_E102_EXPLAIN'
你现在看到 CONFIG_TCP_CONG_BBR=y，含义是：
  BBR/BBR3 已经被编进内核本体，不存在 tcp_bbr.ko 可热替换。

因此：
  - 模块型 m：可以编译 tcp_bbr.ko 并尝试热替换；
  - 内置型 y：只能完整编译新内核，重启进入新内核后生效；
  - e102 已在 17 子菜单显式增加 9) 内置型 BBR：完整内核源码补丁编译新内核；
  - e102 的完整编译 Mem+Swap 门槛为 1000MB，但低资源 VPS 仍有 OOM/IO 卡死/GRUB 风险。

更稳妥的路线：
  1) 先保留当前 XanMod BBR3；
  2) 用 fq/qdisc、notsent、adv_win/app_win、MSS、RPS/XPS 等参数优化；
  3) 如一定要改 BBR3 源码，优先用 4GB~8GB+ 临时编译机生成内核包再部署；
  4) 如果坚持本机编译，必须先做快照、确认 VNC/救援模式可用。
EOF_E102_EXPLAIN

}
# EEX3-FUNCTION legacy_e0_117 _e102_builtin_full_compile_precheck
_e102_builtin_full_compile_precheck() {
    local kind="${1:-}" conf="${2:-}" total root_free boot_free cfgv ok=1 log;
    cfgv="$(_e89_bbr_kconfig_value 2> /dev/null || echo unknown)";
    total="$(_e102_total_mem_swap_mb 2> /dev/null || echo 0)";
    root_free="$(_e102_root_free_mb 2> /dev/null || echo 0)";
    boot_free="$(_e102_boot_free_mb 2> /dev/null || echo 0)";
    log="$E102_AUDIT_DIR/builtin-compile-precheck.$(_e102_ts).log";
    mkdir -p "$E102_AUDIT_DIR" 2> /dev/null || true;
    title "V198e105：内置型 BBR 完整内核编译硬门禁";
    echo "  当前内核: $(uname -r 2> /dev/null || echo unknown)";
    echo "  CONFIG_TCP_CONG_BBR: $cfgv";
    echo "  当前配置文件: $conf";
    echo "  参数模板: $kind";
    echo "  Mem+Swap: ${total} MB";
    echo "  / 可用空间: ${root_free} MB";
    echo "  /boot 可用空间: ${boot_free} MB";
    hr;
    _e102_xanmod_hint;
    echo "";
    { 
        echo "kernel=$(uname -r 2> /dev/null || echo unknown)";
        echo "cfgv=$cfgv";
        echo "kind=$kind";
        echo "conf=$conf";
        echo "mem_swap_mb=$total";
        echo "root_free_mb=$root_free";
        echo "boot_free_mb=$boot_free";
        echo "date=$(date '+%F %T')"
    } > "$log" 2> /dev/null || true;
    if test "$cfgv" != "y"; then
        warn "当前不是内置型 y；如果是模块型 m，请优先走 2/3 的 tcp_bbr.ko 快编路线。";
        return 0;
    fi;
    if test "${total:-0}" -lt 1000 2> /dev/null; then
        error "Mem+Swap < 1000MB。当前约 ${total}MB，完整内核编译高概率 OOM/IO 卡死，已硬拒绝。";
        ok=0;
    fi;
    if test "${root_free:-0}" -lt 12000 2> /dev/null; then
        error "/ 可用空间 < 12GB，完整内核编译容易爆盘，已拒绝。";
        ok=0;
    fi;
    if test "${boot_free:-0}" -lt 350 2> /dev/null; then
        error "/boot 可用空间 < 350MB，initramfs/GRUB 有风险，已拒绝。";
        ok=0;
    fi;
    if test "$ok" -ne 1; then
        warn "这台 VPS 当前不适合完整内核编译。完整编译会编大量驱动，低资源机器很容易卡在 i40e/iavf/ice 或 OOM。";
        warn "审计日志：$log";
        echo "";
        echo "  如你坚持源码编译，请至少满足：";
        echo "    1) 做好 VPS 快照/VNC/救援模式；";
        echo "    2) Mem+Swap 最低 1000MB 才放行，仍建议 4GB+，更推荐 6GB+；";
        echo "    3) 根分区 20GB+；/boot 预留 350MB+；";
        echo "    4) 拿到与当前内核 tag 匹配或可兼容的完整源码。";
        echo "";
        echo "  强制继续需要设置授权变量后重新运行：";
        echo "    export XRAY_E102_ALLOW_BUILTIN_FULL_COMPILE=1";
        echo "    # 兼容旧变量：export XRAY_E100_ALLOW_BUILTIN_FULL_COMPILE=1";
        echo "    # 兼容旧变量：export XRAY_E98_ALLOW_BUILTIN_FULL_COMPILE=1";
        if test "${XRAY_E102_ALLOW_BUILTIN_FULL_COMPILE:-0}" != "1" && test "${XRAY_E100_ALLOW_BUILTIN_FULL_COMPILE:-0}" != "1" && test "${XRAY_E98_ALLOW_BUILTIN_FULL_COMPILE:-0}" != "1"; then
            return 1;
        fi;
    fi;
    if test "${XRAY_E102_ALLOW_BUILTIN_FULL_COMPILE:-0}" != "1" && test "${XRAY_E100_ALLOW_BUILTIN_FULL_COMPILE:-0}" != "1" && test "${XRAY_E98_ALLOW_BUILTIN_FULL_COMPILE:-0}" != "1"; then
        warn "为避免误触，V198e105 默认禁止内置型 BBR 完整编译。";
        warn "确认资源充足并已快照后，可手动 export XRAY_E102_ALLOW_BUILTIN_FULL_COMPILE=1 再尝试。";
        warn "兼容旧变量：XRAY_E100_ALLOW_BUILTIN_FULL_COMPILE=1 / XRAY_E98_ALLOW_BUILTIN_FULL_COMPILE=1。";
        return 1;
    fi;
    return 0
}
# EEX3-FUNCTION legacy_e0_117 _e102_extract_matching_linux_source_tars
_e102_extract_matching_linux_source_tars() {
    local tarball outdir marker base kshort found=0;
    kshort="$(_e102_kernel_shortver)";
    mkdir -p "$E96_BBR_SRC_ROOT" 2> /dev/null || true;
    for tarball in "/usr/src/linux-source-${kshort}.tar."* "/usr/src/linux-${kshort}"*.tar.* "/usr/src/linux_${kshort}"*.orig.tar.*;
    do
        test -f "$tarball" || continue;
        if ! tar -tf "$tarball" 2> /dev/null | grep -q 'net/ipv4/tcp_bbr.c'; then
            continue;
        fi;
        base=$(basename "$tarball" | sed -E 's/\.tar\..*$//; s/\.orig$//');
        outdir="$E96_BBR_SRC_ROOT/$base";
        marker="$outdir/.e102_extracted";
        if test ! -f "$marker"; then
            info "正在解包与当前内核主版本匹配的源码包：$tarball";
            rm -rf "$outdir" 2> /dev/null || true;
            mkdir -p "$outdir" 2> /dev/null || true;
            if tar -xf "$tarball" -C "$outdir" --strip-components=1 2> /dev/null; then
                touch "$marker" 2> /dev/null || true;
            else
                warn "解包失败：$tarball";
                rm -rf "$outdir" 2> /dev/null || true;
                continue;
            fi;
        fi;
        found=1;
    done;
    test "$found" -eq 1
}
# EEX3-FUNCTION legacy_e0_117 _e102_find_current_module_tcp_bbr_source_now
_e102_find_current_module_tcp_bbr_source_now() {
    local f base krel kshort;
    krel="$(uname -r 2> /dev/null || echo unknown)";
    kshort="$(_e102_kernel_shortver)";
    if test -n "${BBR_SOURCE:-}"; then
        if _e102_valid_current_bbr_module_source "$BBR_SOURCE" || { 
            test "${BBR_SOURCE_FORCE:-0}" = "1" && _e96_valid_bbr_source "$BBR_SOURCE"
        }; then
            echo "$BBR_SOURCE";
            return 0;
        fi;
    fi;
    for f in "/lib/modules/$krel/build/net/ipv4/tcp_bbr.c" "/lib/modules/$krel/source/net/ipv4/tcp_bbr.c" "/usr/src/linux-headers-$krel/net/ipv4/tcp_bbr.c" "/usr/src/linux-source-$kshort/net/ipv4/tcp_bbr.c" "/usr/src/linux-$kshort/net/ipv4/tcp_bbr.c" "$E96_BBR_SRC_ROOT/linux-source-$kshort/net/ipv4/tcp_bbr.c" "$E96_BBR_SRC_ROOT/linux-$kshort/net/ipv4/tcp_bbr.c";
    do
        if _e102_valid_current_bbr_module_source "$f"; then
            echo "$f";
            return 0;
        fi;
    done;
    for base in "/lib/modules/$krel/build" "/lib/modules/$krel/source" "$E96_BBR_SRC_ROOT" "/usr/src";
    do
        test -d "$base" || continue;
        while IFS= read -r f; do
            if _e102_valid_current_bbr_module_source "$f"; then
                echo "$f";
                return 0;
            fi;
        done < <(find "$base" -path '*/net/ipv4/tcp_bbr.c' -type f 2> /dev/null | sort);
    done;
    return 1
}
# EEX3-FUNCTION legacy_e0_117 _e102_kernel_shortver
_e102_kernel_shortver() {
    uname -r 2> /dev/null | sed -E 's/^([0-9]+\.[0-9]+).*/\1/'
}
# EEX3-FUNCTION legacy_e0_117 _e102_module_headers_support_source
_e102_module_headers_support_source() {
    local f="${1:-}" kbuild;
    kbuild="/lib/modules/$(uname -r)/build";
    test -d "$kbuild" || return 1;
    if grep -q '__bpf_kfunc' "$f" 2> /dev/null; then
        if ! grep -Rqs '__bpf_kfunc' "$kbuild/include" "$kbuild/scripts" 2> /dev/null; then
            return 1;
        fi;
    fi;
    return 0
}
# EEX3-FUNCTION legacy_e0_117 _e102_patched_source_sanity
_e102_patched_source_sanity() {
    local f="$1";
    if grep -nE '\\n[[:space:]]*BBR_UNIT|,[[:space:]]*\\n' "$f" > /tmp/e102-bbr-sanity.$$ 2> /dev/null; then
        error "生成后的 tcp_bbr.c 仍含字面量 \\n，拒绝编译。";
        sed 's/^/    /' /tmp/e102-bbr-sanity.$$ 2> /dev/null | head -n 20 || true;
        rm -f /tmp/e102-bbr-sanity.$$ 2> /dev/null || true;
        return 1;
    fi;
    rm -f /tmp/e102-bbr-sanity.$$ 2> /dev/null || true;
    if grep -q '__bpf_kfunc' "$f" 2> /dev/null && ! _e102_module_headers_support_source "$f"; then
        error "源码包含 __bpf_kfunc，但当前 headers 不支持；这是跨内核版本源码，拒绝模块快编。";
        return 1;
    fi;
    return 0
}
