}
# EEX3-FUNCTION legacy_e0_117 _e102_root_free_mb
_e102_root_free_mb() {
    df -Pm / 2> /dev/null | awk 'NR==2{print int($4)}'
}
# EEX3-FUNCTION legacy_e0_117 _e102_source_declared_release
_e102_source_declared_release() {
    local root f rel="";
    root="$(_e102_tcp_bbr_root "${1:-}")";
    for f in "$root/include/generated/utsrelease.h" "$root/include/config/kernel.release" "$root/.kernelrelease";
    do
        test -f "$f" || continue;
        rel=$(sed -n 's/.*UTS_RELEASE[[:space:]]*"\([^"]\+\)".*/\1/p;1p' "$f" 2> /dev/null | head -n1 | tr -d ' \t\r\n"' || true);
        test -n "$rel" && { 
            printf '%s\n' "$rel";
            return 0
        };
    done;
    if test -f "$root/Makefile"; then
        awk '
            /^VERSION[[:space:]]*=/ {v=$3}
            /^PATCHLEVEL[[:space:]]*=/ {p=$3}
            /^SUBLEVEL[[:space:]]*=/ {s=$3}
            /^EXTRAVERSION[[:space:]]*=/ {e=$3}
            END { if (v != "" && p != "") { printf "%s.%s", v, p; if (s != "") printf ".%s", s; if (e != "") printf "%s", e; printf "\n" } }
        ' "$root/Makefile" 2> /dev/null | head -n1;
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e102_source_matches_running_kernel
_e102_source_matches_running_kernel() {
    local f="${1:-}" krel kshort rel;
    test -n "$f" && test -f "$f" || return 1;
    krel="$(uname -r 2> /dev/null || echo unknown)";
    kshort="$(_e102_kernel_shortver)";
    case "$f" in 
        /lib/modules/"$krel"/build/* | /lib/modules/"$krel"/source/*)
