        ;;
    esac;
    if test -n "${BBR_SOURCE_FORCE:-}" && test "${BBR_SOURCE_FORCE:-0}" = "1" && test -n "${BBR_SOURCE:-}" && test "$f" = "$BBR_SOURCE"; then
        warn "BBR_SOURCE_FORCE=1：跳过源码版本保护，强制使用 $f。";
        return 0;
    fi;
    if echo "$f" | grep -Fq "$krel"; then
        return 0;
    fi;
    if echo "$f" | grep -Eq "linux(-source)?[-_/]?${kshort}([^0-9]|$)"; then
        return 0;
    fi;
    rel="$(_e102_source_declared_release "$f" 2> /dev/null | head -n1 || true)";
    if test -n "$rel"; then
        if test "$rel" = "$krel" || echo "$rel" | grep -Eq "^${kshort}([.-]|$)"; then
            return 0;
        fi;
    fi;
    return 1
}
