# EEX3-FUNCTION legacy_e0_117 _e111_backup_obsolete_state
_e111_backup_obsolete_state() {
    _e111_prepare_dirs;
    local ts dest;
    ts="$(date +%Y%m%d_%H%M%S)";
    dest="$E111_CLEAN_BACKUP_DIR/preclean_${ts}";
    mkdir -p "$dest/files" 2> /dev/null || true;
    { 
        echo "created_at=$(date '+%F %T')";
        echo "script_version=198e111";
        echo "reason=${1:-manual}";
        echo "normal_hotupdate_backup_dir=$BACKUP_DIR"
    } > "$dest/meta.env" 2> /dev/null || true;
    iptables-save > "$dest/iptables-save.txt" 2> /dev/null || true;
    ip6tables-save > "$dest/ip6tables-save.txt" 2> /dev/null || true;
    tc -s qdisc show > "$dest/tc-qdisc.txt" 2> /dev/null || true;
    ip -details link show > "$dest/ip-link.txt" 2> /dev/null || true;
    systemctl list-unit-files 'xray-*' --no-pager > "$dest/xray-unit-files.txt" 2> /dev/null || true;
    systemctl list-timers --all --no-pager > "$dest/timers.txt" 2> /dev/null || true;
    local f;
    for f in /etc/systemd/system/xray-pmtu-mss-e106.service /etc/systemd/system/xray-pmtu-mss-e107.service /etc/systemd/system/xray-mss-e108.service /etc/systemd/system/xray-shape-e108.service /etc/systemd/system/xray-mss-e109.service /etc/systemd/system/xray-shape-e109.service /usr/local/bin/xray-pmtu-mss-e106.sh /usr/local/bin/xray-pmtu-mss-e107.sh /usr/local/bin/xray-mss-e108.sh /usr/local/bin/xray-shape-e108.sh /usr/local/bin/xray-mss-e109.sh /usr/local/bin/xray-shape-e109.sh /etc/sysctl.d/99-xray-pmtu-e106.conf /etc/sysctl.d/99-xray-pmtu-e107.conf /etc/sysctl.d/99-auto-tune-relay-e108.conf /etc/sysctl.d/99-auto-tune-relay-e108.profile.txt /etc/sysctl.d/99-auto-tune-relay-e109.conf /etc/sysctl.d/99-auto-tune-relay-e109.profile.txt;
    do
        if test -e "$f"; then
            mkdir -p "$dest/files$(dirname "$f")" 2> /dev/null || true;
            cp -a "$f" "$dest/files$f" 2> /dev/null || true;
        fi;
    done;
    for f in "$CONFIG_DIR/pmtu_e106" "$CONFIG_DIR/pmtu_e107" "$CONFIG_DIR/netdiag_e108" "$CONFIG_DIR/netdiag_e109";
    do
        if test -e "$f"; then
            tar -C "$(dirname "$f")" -czf "$dest/$(basename "$f").tgz" "$(basename "$f")" 2> /dev/null || true;
        fi;
    done;
    echo "$dest" > "$E111_CLEAN_DIR/latest_backup.txt" 2> /dev/null || true;
    info "e111 清理前快照已保存：$dest"
}
# EEX3-FUNCTION legacy_e0_117 _e111_cleanup_chain_with_tool
_e111_cleanup_chain_with_tool() {
    local tool="$1" chain="$2" hook;
    command -v "$tool" > /dev/null 2>&1 || return 0;
    "$tool" -t mangle -S "$chain" > /dev/null 2>&1 || return 0;
    for hook in OUTPUT POSTROUTING PREROUTING FORWARD INPUT;
    do
        while "$tool" -t mangle -D "$hook" -j "$chain" > /dev/null 2>&1; do
            :;
        done;
    done;
    "$tool" -t mangle -F "$chain" > /dev/null 2>&1 || true;
    "$tool" -t mangle -X "$chain" > /dev/null 2>&1 || true
}
