# EEX3-FUNCTION legacy_e0_117 _e111_show_cleanup_state
_e111_show_cleanup_state() {
    title "V198e111：旧网络实验层残留检查";
    echo "服务残留：";
    local s c found=0;
    for s in $E111_OBSOLETE_SERVICES;
    do
        if systemctl list-unit-files "$s" --no-pager 2> /dev/null | grep -q "$s"; then
            echo "  $s : present";
            found=1;
        fi;
    done;
    if test "$found" -eq 0; then
        echo "  未发现旧 service。";
    fi;
    echo;
    echo "iptables mangle 链残留：";
    found=0;
    for c in $E111_OBSOLETE_CHAINS;
    do
        if iptables -t mangle -S "$c" > /dev/null 2>&1; then
            echo "  $c : present";
            found=1;
        fi;
    done;
    if test "$found" -eq 0; then
        echo "  未发现旧链。";
    fi;
    echo;
    echo "目录残留：";
    found=0;
    for d in "$CONFIG_DIR/pmtu_e106" "$CONFIG_DIR/pmtu_e107" "$CONFIG_DIR/netdiag_e108" "$CONFIG_DIR/netdiag_e109";
    do
        if test -e "$d"; then
            echo "  $d";
            found=1;
        fi;
    done;
    if test "$found" -eq 0; then
        echo "  未发现旧目录。";
    fi;
    echo;
    echo "最近 e111 清理备份：$(cat "$E111_CLEAN_DIR/latest_backup.txt" 2> /dev/null || echo none)"
}
