# EEX3-FUNCTION legacy_e0_117 _e116_backup_state
_e116_backup_state() {
    ( local tag="${1:-manual}" safe bdir f base seen=" " failed=0 latest_tmp enabled_state;
    umask 077;
    _e118_prepare_dirs || return 1;
    safe=$(printf '%s' "$tag" | tr -c 'A-Za-z0-9_.-' '_');
    bdir=$(mktemp -d "$E118_BACKUP_DIR/${safe}_$(date +%Y%m%d_%H%M%S)_XXXXXX") || return 1;
    chmod 0700 "$bdir" || { 
        rm -rf -- "$bdir";
        return 1
    };
    : > "$bdir/files.manifest" || { 
        rm -rf -- "$bdir";
        return 1
    };
    while IFS= read -r f; do
        test -n "$f" || continue;
        base=$(basename -- "$f");
        [[ "$base" =~ ^[A-Za-z0-9._-]+$ ]] || { 
            failed=1;
            break
        };
        [[ "$seen" != *" $base "* ]] || { 
            failed=1;
            break
        };
        seen+="$base ";
        test -e "$f" || continue;
        test -f "$f" || { 
            failed=1;
            break
        };
        install -o root -g root -m 0600 "$f" "$bdir/$base" || { 
            failed=1;
            break
        };
        printf '%s\n' "$base" >> "$bdir/files.manifest" || { 
            failed=1;
            break
        };
    done < <(_e118_managed_state_files);
    if test "$failed" -ne 0; then
        rm -rf -- "$bdir";
        return 1;
    fi;
    enabled_state=$(systemctl is-enabled xray.service 2> /dev/null || true);
    enabled_state=$(printf '%s' "$enabled_state" | tr -c 'A-Za-z0-9_.@:-' '_' | head -c 80);
    { 
        echo "created_at=$(date '+%F %T')";
        echo "version=$SCRIPT_VERSION";
        echo "tag=$safe";
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            echo xray_was_active=1;
        else
            echo xray_was_active=0;
        fi;
        if systemctl is-enabled --quiet xray.service 2> /dev/null; then
            echo xray_was_enabled=1;
        else
            echo xray_was_enabled=0;
        fi;
        echo "xray_enabled_state=${enabled_state:-unknown}"
    } > "$bdir/meta.env" || { 
        rm -rf -- "$bdir";
        return 1
    };
    command -v iptables-save > /dev/null 2>&1 && iptables-save > "$bdir/iptables-save.txt" 2> /dev/null || true;
    command -v ip6tables-save > /dev/null 2>&1 && ip6tables-save > "$bdir/ip6tables-save.txt" 2> /dev/null || true;
    : > "$bdir/files.sha256" || { 
        rm -rf -- "$bdir";
        return 1
    };
    while IFS= read -r base; do
        test -n "$base" || continue;
        ( cd "$bdir" && sha256sum -- "$base" ) >> "$bdir/files.sha256" || { 
            failed=1;
            break
        };
    done < "$bdir/files.manifest";
    if test "$failed" -ne 0; then
        rm -rf -- "$bdir";
        return 1;
    fi;
    chmod 0600 "$bdir"/* 2> /dev/null || { 
        rm -rf -- "$bdir";
        return 1
    };
    ( cd "$bdir" && find . -maxdepth 1 -type f ! -name snapshot-seal.sha256 -printf '%P\0' | sort -z | xargs -0 sha256sum > snapshot-seal.sha256 ) || { 
        rm -rf -- "$bdir";
        return 1
    };
    test -s "$bdir/snapshot-seal.sha256" && ( cd "$bdir" && sha256sum -c snapshot-seal.sha256 > /dev/null 2>&1 ) || { 
        rm -rf -- "$bdir";
        return 1
    };
    chmod 0600 "$bdir/snapshot-seal.sha256" || { 
        rm -rf -- "$bdir";
        return 1
    };
    latest_tmp="$E118_DIR/.latest_backup.e159.$$.$RANDOM";
    printf '%s\n' "$bdir" > "$latest_tmp" && chmod 0600 "$latest_tmp" && mv -f -- "$latest_tmp" "$E118_DIR/latest_backup.txt" || { 
        rm -f -- "$latest_tmp";
        rm -rf -- "$bdir";
        return 1
    };
    _e159_prune_state_snapshots;
    printf '%s\n' "$bdir" )
}
# EEX3-FUNCTION legacy_e0_117 _e116_config_has_reality_file
_e116_config_has_reality_file() {
    local f="${1:-$CONFIG}";
    test -s "$f" || return 1;
    jq -e '
      .inbounds[]?
      | select(.protocol=="vless")
      | select((.streamSettings.security // "") == "reality")
      | select(((.streamSettings.realitySettings.privateKey // "")|length) > 10)
      | select(((.streamSettings.realitySettings.serverNames // [])|length) >= 1)
      | select(((.streamSettings.realitySettings.shortIds // [])|length) >= 1)
      | select(((.settings.clients // .settings.users // [])|length) >= 1)
    ' "$f" > /dev/null 2>&1
}
