# EEX3-FUNCTION legacy_e0_117 _e116_install_fail2ban_guard
_e116_install_fail2ban_guard() {
    if ! command -v fail2ban-client > /dev/null 2>&1; then
        if command -v apt-get > /dev/null 2>&1; then
            DEBIAN_FRONTEND=noninteractive apt-get update -y > /dev/null 2>&1 || true;
            DEBIAN_FRONTEND=noninteractive apt-get install -y fail2ban > /dev/null 2>&1 || true;
        fi;
        if command -v yum > /dev/null 2>&1; then
            yum install -y fail2ban > /dev/null 2>&1 || true;
        fi;
    fi;
    command -v fail2ban-client > /dev/null 2>&1 || { 
        warn "fail2ban 未安装成功，跳过 SSH 失败封禁；端口自愈仍保留。";
        return 0
    };
    mkdir -p /etc/fail2ban/jail.d /etc/fail2ban/fail2ban.d /var/lib/fail2ban 2> /dev/null || true;
    cat > "$E116_F2B_DB_CONF" <<'EOF_E116_F2B_DB'
[Definition]
dbfile = /var/lib/fail2ban/fail2ban.sqlite3
dbpurgeage = 3d
EOF_E116_F2B_DB

    cat > "$E116_F2B_JAIL" <<EOF_E116_F2B_JAIL
[$E116_F2B_JAIL_NAME]
enabled = true
filter = sshd
backend = systemd
journalmatch = _SYSTEMD_UNIT=ssh.service + _SYSTEMD_UNIT=sshd.service
maxretry = $E116_MAXRETRY
findtime = $E116_FINDTIME
bantime = $E116_BANTIME
banaction = iptables-allports
EOF_E116_F2B_JAIL

    fail2ban-client -t > /tmp/fail2ban-e116-test.log 2>&1 || { 
        warn "fail2ban 配置测试未通过，已保留文件但不强制启动。";
        sed 's/^/    /' /tmp/fail2ban-e116-test.log 2> /dev/null || true;
        return 0
    };
    systemctl enable --now fail2ban > /dev/null 2>&1 || true;
    fail2ban-client reload > /dev/null 2>&1 || systemctl restart fail2ban > /dev/null 2>&1 || true
}
