# EEX3-FUNCTION legacy_e0_117 _e82_manual_tcp_notsent_lowat
_e82_manual_tcp_notsent_lowat() {
    local v="";
    echo "";
    warn "手动值建议在 26214 / 32768 / 65536 / 131072 中测试；过大可能增加排队延迟，过小可能限制高 RTT 吞吐。";
    read -rp "请输入 tcp_notsent_lowat 数值（0 或 4096~4194304，默认 26214）: " v || true;
    v=${v:-26214};
    _e82_set_tcp_notsent_lowat "$v" "手动输入"
}
# EEX3-FUNCTION legacy_e0_117 _e82_persistent_notsent_lowat
_e82_persistent_notsent_lowat() {
    if test -f "$NETWORK_OPT_CONF"; then
        awk -F= '/^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=/{gsub(/[[:space:]]/,"",$2); v=$2} END{if(v!="") print v; else print "未写入"}' "$NETWORK_OPT_CONF" 2> /dev/null || echo "未写入";
    else
        echo "文件不存在";
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e82_set_tcp_notsent_lowat
_e82_set_tcp_notsent_lowat() {
    _e139_network_apply balanced force
}
# EEX3-FUNCTION legacy_e0_117 _e82_show_notsent_conflicts
_e82_show_notsent_conflicts() {
    echo "";
    echo -e "  ${cyan}tcp_notsent_lowat 定义来源扫描：${none}";
    grep -R "^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=" /etc/sysctl.conf /etc/sysctl.d /usr/lib/sysctl.d /lib/sysctl.d 2> /dev/null | sed 's/^/    /' || true
}
# EEX3-FUNCTION legacy_e0_117 _e82_show_tcp_notsent_lowat_state
_e82_show_tcp_notsent_lowat_state() {
    local run perm saved;
    run=$(_e82_current_notsent_lowat);
    perm=$(_e82_persistent_notsent_lowat);
    saved=$(cat "$E82_NOTSENT_LOWAT_FILE" 2> /dev/null || echo "未记录");
    echo "";
    echo -e "  ${cyan}tcp_notsent_lowat 状态：${none}";
    printf "    %-22s %s\n" "运行态(sysctl):" "$run";
    printf "    %-22s %s\n" "永久配置($NETWORK_OPT_CONF):" "$perm";
    printf "    %-22s %s\n" "e82记录:" "$saved";
    echo "";
    echo "    26214  = 极低排队/极低 notsent：网页响应优先，可能限制高 RTT 大吞吐。";
    echo "    32768  = 低延迟倾向：小包交互更灵敏，吞吐比 26214 更稳。";
    echo "    65536  = 均衡倾向：日常翻墙、网页、视频、下载混合使用。";
    echo "    131072 = 高吞吐倾向：高 RTT、大文件、测速更激进。"
}
# EEX3-FUNCTION legacy_e0_117 _e82_validate_notsent_lowat
_e82_validate_notsent_lowat() {
    local v="${1:-}";
    [[ "$v" =~ ^[0-9]+$ ]] || return 1;
    if test "$v" -eq 0 2> /dev/null; then
        return 0;
    fi;
    test "$v" -ge 4096 2> /dev/null && test "$v" -le 4194304 2> /dev/null
}
# EEX3-FUNCTION legacy_e0_117 _e88_apply_fq_bbr_stable_core
_e88_apply_fq_bbr_stable_core() {
    title "应用 e88 稳态核心：fq + bbr + ECN=0 + TFO=0 + MTU probing=1";
    if declare -F apply_fq_qdisc_default > /dev/null 2>&1; then
        apply_fq_qdisc_default || true;
    fi;
    _e88_set_sysctl_key net.core.default_qdisc fq "fq pacing 队列";
    _e88_set_sysctl_key net.ipv4.tcp_congestion_control bbr "BBR 拥塞控制";
    _e88_set_sysctl_key net.ipv4.tcp_ecn 0 "关闭 ECN，减少兼容性问题";
    _e88_set_sysctl_key net.ipv4.tcp_ecn_fallback 1 "ECN fallback";
    _e88_set_sysctl_key net.ipv4.tcp_fastopen 0 "关闭 TFO，避免跨境兼容性毛刺";
    _e88_set_sysctl_key net.ipv4.tcp_mtu_probing 1 "启用 MTU probing";
    _e88_set_sysctl_key net.ipv4.tcp_slow_start_after_idle 0 "关闭空闲后慢启动";
    _e88_set_sysctl_key net.ipv4.tcp_autocorking 0 "关闭 autocorking，降低代理小包等待";
    _e88_set_sysctl_key net.ipv4.tcp_tso_win_divisor 6 "TSO 窗口分割";
    _e88_show_core_network_state
}
# EEX3-FUNCTION legacy_e0_117 _e88_apply_menu13_defaults
