# EEX3-FUNCTION legacy_e0_117 _e88_cpu_mask_all_safe
_e88_cpu_mask_all_safe() {
    local cores="${1:-$(nproc 2> /dev/null || echo 1)}";
    if ! [[ "$cores" =~ ^[0-9]+$ ]] || test "$cores" -lt 1 2> /dev/null; then
        cores=1;
    fi;
    if declare -F cpu_mask_all > /dev/null 2>&1; then
        cpu_mask_all "$cores" 2> /dev/null | tr 'A-F' 'a-f' || echo "1";
        return 0;
    fi;
    python3 - "$cores" <<'PY' 2> /dev/null || 
import sys
n=int(sys.argv[1])
print(format((1 << n) - 1, 'x'))
PY
 awk -v n="$cores" 'BEGIN{ if(n<=1) print "1"; else if(n>=31) print "ffffffff"; else printf "%x\n", (2^n)-1 }'
}
