# EEX3-FUNCTION legacy_e0_117 _e88_norm_hex_mask
_e88_norm_hex_mask() {
    local v="${1:-0}";
    v=$(printf '%s' "$v" | tr -d ',[:space:]' | tr 'A-F' 'a-f');
    v=$(printf '%s' "$v" | sed 's/^0*//');
    test -n "$v" || v="0";
    echo "$v"
}
