# EEX3-FUNCTION legacy_e0_117 _e88_ping_loss_percent
_e88_ping_loss_percent() {
    local host out loss;
    for host in 1.1.1.1 8.8.8.8;
    do
        if command -v ping > /dev/null 2>&1; then
            out=$(LC_ALL=C ping -c 4 -W 1 "$host" 2> /dev/null || true);
            loss=$(printf '%s\n' "$out" | awk -F',' '/packet loss/ {gsub(/[^0-9.]/,"",$3); print int($3); exit}');
            if [[ "$loss" =~ ^[0-9]+$ ]]; then
                echo "$loss";
                return 0;
            fi;
        fi;
    done;
    echo "unknown"
}
# EEX3-FUNCTION legacy_e0_117 _e88_ping_rtt_avg_ms
_e88_ping_rtt_avg_ms() {
    local host out avg;
    for host in 1.1.1.1 8.8.8.8;
    do
        if command -v ping > /dev/null 2>&1; then
            out=$(LC_ALL=C ping -c 4 -W 1 "$host" 2> /dev/null || true);
            avg=$(printf '%s\n' "$out" | awk -F'/' '/min\/avg\/max|round-trip/ {print int($5); exit}');
            if [[ "$avg" =~ ^[0-9]+$ ]] && test "$avg" -gt 0 2> /dev/null; then
                echo "$avg";
                return 0;
            fi;
        fi;
    done;
    return 1
}
