# EEX3-FUNCTION legacy_e0_117 _e88_set_adv_app_profile
_e88_set_adv_app_profile() {
    local scale="$1" app="$2" label="$3";
    if ! [[ "$scale" =~ ^-?[0-9]+$ ]] || test "$scale" -lt -2 2> /dev/null || test "$scale" -gt 4 2> /dev/null; then
        error "tcp_adv_win_scale 非法：$scale；建议 -2~4。";
        return 1;
    fi;
    if ! [[ "$app" =~ ^[0-9]+$ ]] || test "$app" -lt 0 2> /dev/null || test "$app" -gt 31 2> /dev/null; then
        error "tcp_app_win 非法：$app；建议 0~31。";
        return 1;
    fi;
    _e88_set_sysctl_key net.ipv4.tcp_adv_win_scale "$scale" "$label";
    _e88_set_sysctl_key net.ipv4.tcp_app_win "$app" "$label";
    _e88_show_core_network_state
}
# EEX3-FUNCTION legacy_e0_117 _e88_set_init_window
_e88_set_init_window() {
    local cw="${1:-}" rw="${2:-$1}" mode="${3:-manual}" clean="";
    if ! [[ "$cw" =~ ^[0-9]+$ ]] || ! [[ "$rw" =~ ^[0-9]+$ ]]; then
        error "initcwnd/initrwnd 必须为数字。";
        return 1;
    fi;
    if test "$cw" -lt 2 2> /dev/null || test "$cw" -gt 100 2> /dev/null || test "$rw" -lt 2 2> /dev/null || test "$rw" -gt 100 2> /dev/null; then
        error "initcwnd/initrwnd 建议范围 2~100。";
        return 1;
    fi;
    _e105_prepare_dirs;
    echo "$cw" > "$CONFIG_DIR/initcwnd.txt" 2> /dev/null || true;
    echo "$rw" > "$CONFIG_DIR/initrwnd.txt" 2> /dev/null || true;
    _e105_install_init_window_boot_restore "$cw" "$rw" || true;
    clean=$(_e105_default_route_clean 2> /dev/null || true);
    if test -n "$clean"; then
        if ip route change $clean initcwnd "$cw" initrwnd "$rw" 2> /dev/null; then
            info "已设置默认路由 initcwnd=$cw initrwnd=$rw，并写入开机恢复。";
        else
            warn "运行态 route change 失败；已保留持久化，开机/网络重建后会再次尝试应用。";
        fi;
    else
        warn "未检测到默认路由；已保留持久化，开机/网络重建后会尝试应用。";
    fi;
    _e105_init_window_note "$mode" "$cw" "$rw" "e105 写入 initcwnd/initrwnd 持久化与开机恢复。";
    return 0
}
# EEX3-FUNCTION legacy_e0_117 _e88_set_sysctl_key
_e88_set_sysctl_key() {
    local key="$1" value="$2" label="${3:-e88}" re;
    mkdir -p /etc/sysctl.d "$CONFIG_DIR" "$BACKUP_DIR/sysctl" 2> /dev/null || true;
    _e88_strip_key_conflicts "$key";
    if test -f "$NETWORK_OPT_CONF"; then
        cp -af "$NETWORK_OPT_CONF" "$BACKUP_DIR/sysctl/99-network-optimized.conf.e88.$(date +%Y%m%d_%H%M%S).bak" 2> /dev/null || true;
    else
        touch "$NETWORK_OPT_CONF" 2> /dev/null || true;
    fi;
    re=$(_e88_escape_key_re "$key");
    sed -i -E "/^[[:space:]]*${re}[[:space:]]*=/d" "$NETWORK_OPT_CONF" 2> /dev/null || true;
    cat >> "$NETWORK_OPT_CONF" <<EOF_E88_SYSCTL_KEY

# V198e88 ${label}
${key} = ${value}
EOF_E88_SYSCTL_KEY

    if sysctl -w "${key}=${value}" > /tmp/xray-e88-sysctl.log 2>&1; then
        info "运行态已应用：${key}=${value}";
    else
        warn "当前内核可能不支持：${key}=${value}；永久配置已写入，详情：/tmp/xray-e88-sysctl.log";
        sed 's/^/    /' /tmp/xray-e88-sysctl.log 2> /dev/null || true;
    fi;
    echo "${key}=${value}" >> "$E88_NETWORK_MENU_STATE_FILE" 2> /dev/null || true
}
# EEX3-FUNCTION legacy_e0_117 _e88_set_tcp_adv_win_scale_manual
_e88_set_tcp_adv_win_scale_manual() {
    local v cur;
    cur=$(_e88_sysctl_get net.ipv4.tcp_adv_win_scale);
    echo "";
    warn "tcp_adv_win_scale：默认 1；吞吐实验 2-3；允许 -31~31，但强烈建议先测 1/2/3。";
    read -rp "请输入 tcp_adv_win_scale（默认 ${cur:-1}，直接回车用 1）: " v || true;
    v=${v:-1};
    if ! [[ "$v" =~ ^-?[0-9]+$ ]] || test "$v" -lt -31 2> /dev/null || test "$v" -gt 31 2> /dev/null; then
        error "tcp_adv_win_scale 非法：$v；允许 -31~31。";
        return 1;
    fi;
    if test "$v" -gt 3 2> /dev/null || test "$v" -lt 0 2> /dev/null; then
        warn "你输入的是非常规值 $v；脚本允许写入，但建议先对比 1/2/3 的体感和测速。";
    fi;
    _e88_set_sysctl_key net.ipv4.tcp_adv_win_scale "$v" "V198e88 手动：tcp_adv_win_scale，默认1，吞吐2-3";
    echo "tcp_adv_win_scale=$v" >> "$E88_NET_MANUAL_STATE_FILE" 2> /dev/null || true
}
