# EEX3-FUNCTION legacy_e0_117 _e88_set_txqueuelen
_e88_set_txqueuelen() {
    local value="${1:-3000}" iface old rc=0 p tx;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    old=$(ip -o link show dev "$iface" | sed -n 's/.* qlen \([0-9]\+\).*/\1/p');
    _e137_prepare || return 1;
    tx="$E137_BACKUP_DIR/txq-$(date +%Y%m%d_%H%M%S)-$$";
    mkdir -p "$tx" || return 1;
    for p in "$E137_TXQ_SCRIPT" "$E137_TXQ_SERVICE" "$E137_TXQ_TIMER";
    do
        _e135_snapshot_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || return 1;
    done;
    _e137_txq_apply_base "$value" || rc=1;
    if test "$rc" -ne 0; then
        test -z "$old" || ip link set dev "$iface" txqueuelen "$old" > /dev/null 2>&1 || true;
        for p in "$E137_TXQ_SCRIPT" "$E137_TXQ_SERVICE" "$E137_TXQ_TIMER";
        do
            _e135_restore_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || true;
        done;
        systemctl daemon-reload > /dev/null 2>&1 || true;
        return 1;
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e88_set_txqueuelen_manual
_e88_set_txqueuelen_manual() {
    local v iface;
    iface=$(_e88_default_iface 2> /dev/null || true);
    echo "";
    warn "txqueuelen：默认 3000；1000 偏低排队，3000 偏稳态，高于 5000 可能增加排队延迟。";
    read -rp "请输入 txqueuelen（默认 3000）: " v || true;
    v=${v:-3000};
    if ! [[ "$v" =~ ^[0-9]+$ ]] || test "$v" -lt 100 2> /dev/null || test "$v" -gt 20000 2> /dev/null; then
        error "txqueuelen 非法：$v；建议 100~20000，常用 1000/3000/5000。";
        return 1;
    fi;
    if test "$v" -gt 5000 2> /dev/null; then
        warn "txqueuelen=$v 偏大，可能增加 bufferbloat。";
    fi;
    _e88_set_txqueuelen "$v";
    echo "txqueuelen=$v" >> "$E88_NET_MANUAL_STATE_FILE" 2> /dev/null || true
}
# EEX3-FUNCTION legacy_e0_117 _e88_show_core_network_state
_e88_show_core_network_state() {
    local iface qdisc txq;
    iface=$(_e88_default_iface);
    echo "";
    echo -e "  ${cyan}关键网络参数状态（运行态 / 永久态）：${none}";
    printf "    %-34s %-18s %-18s\n" "参数" "运行态" "永久态";
    printf "    %-34s %-18s %-18s\n" "----" "------" "------";
    local key;
    for key in net.core.default_qdisc net.ipv4.tcp_congestion_control net.ipv4.tcp_ecn net.ipv4.tcp_fastopen net.ipv4.tcp_mtu_probing net.ipv4.tcp_adv_win_scale net.ipv4.tcp_app_win net.ipv4.tcp_notsent_lowat net.ipv4.tcp_slow_start_after_idle net.ipv4.tcp_autocorking net.ipv4.tcp_tso_win_divisor net.core.rmem_default net.core.wmem_default net.core.rmem_max net.core.wmem_max;
    do
        printf "    %-34s %-18s %-18s\n" "$key" "$(_e88_sysctl_get "$key")" "$(_e88_sysctl_persistent "$key")";
    done;
    echo "";
    echo -e "  ${cyan}网卡运行态：${none}";
    if test -n "$iface"; then
        txq=$(ip -o link show "$iface" 2> /dev/null | sed -n 's/.*qlen \([0-9][0-9]*\).*/\1/p' | head -n1);
        qdisc=$(tc qdisc show dev "$iface" 2> /dev/null | head -n1 || true);
        printf "    %-18s %s\n" "默认出口网卡:" "$iface";
        printf "    %-18s %s\n" "txqueuelen:" "${txq:-unknown}";
        printf "    %-18s %s\n" "tc qdisc:" "${qdisc:-unknown}";
        if command -v ethtool > /dev/null 2>&1; then
            ethtool -k "$iface" 2> /dev/null | grep -E 'generic-segmentation-offload|generic-receive-offload|tcp-segmentation-offload|large-receive-offload|rx-gro-hw|tx-udp-segmentation' | sed 's/^/    /' || true;
        fi;
    else
        warn "未识别默认出口网卡。";
    fi
}
