# EEX3-FUNCTION legacy_e0_117 _e88_show_ip_gai_state
_e88_show_ip_gai_state() {
    title "V198e88：IPv4/IPv6 出口检测 + gai.conf 优先级查看（只读，不禁用 IPv6）";
    echo "  出口检测：";
    printf "    IPv4: ";
    curl -4 -s --connect-timeout 4 https://api.ipify.org 2> /dev/null || curl -4 -s --connect-timeout 4 https://ip.sb 2> /dev/null || echo "不可达/未配置";
    echo "";
    printf "    IPv6: ";
    curl -6 -s --connect-timeout 4 https://api64.ipify.org 2> /dev/null || curl -6 -s --connect-timeout 4 https://ip.sb 2> /dev/null || echo "不可达/未配置";
    echo "";
    echo "";
    echo "  gai.conf 状态：";
    if test -f /etc/gai.conf; then
        echo "    /etc/gai.conf 存在；未注释 precedence/label 规则如下：";
        grep -nE '^[[:space:]]*(precedence|label)[[:space:]]+' /etc/gai.conf 2> /dev/null | sed 's/^/      /' || echo "      未发现未注释 precedence/label。";
    else
        echo "    /etc/gai.conf 不存在，系统使用默认 getaddrinfo 优先级。";
    fi;
    echo "";
    echo "  当前解析优先级测试：";
    if command -v getent > /dev/null 2>&1; then
        getent ahosts api.ipify.org 2> /dev/null | head -n 8 | sed 's/^/    /' || true;
    else
        echo "    getent 不存在，跳过。";
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e88_show_menu13_manual_notes
_e88_show_menu13_manual_notes() {
    title "V198e88 菜单13：五项网络参数注释与默认值";
    local iface txq mss_state off_state;
    iface=$(_e88_default_iface 2> /dev/null || true);
    if test -n "$iface"; then
        txq=$(ip -o link show "$iface" 2> /dev/null | sed -n 's/.*qlen \([0-9][0-9]*\).*/\1/p' | head -n1);
    fi;
    mss_state=$(cat "$E88_MSS_STATE_FILE" 2> /dev/null || echo "unknown");
    off_state=$(cat "$E88_OFFLOAD_STATE_FILE" 2> /dev/null || echo "unknown");
    echo "  【默认策略】";
    _e88_note_line "tcp_adv_win_scale" "默认 1；吞吐实验 2-3；过大可能放大排队/内存压力。当前：$(_e88_sysctl_get net.ipv4.tcp_adv_win_scale)";
    _e88_note_line "tcp_app_win" "默认 31；允许 0~31；普通代理建议 31。当前：$(_e88_sysctl_get net.ipv4.tcp_app_win)";
    _e88_note_line "txqueuelen" "默认 3000；1000 偏低排队，3000 偏稳态吞吐。当前：${txq:-unknown}";
    _e88_note_line "GRO/GSO/TSO/LRO" "默认 OOOX，即 GRO=ON/GSO=ON/TSO=ON/LRO=OFF。记录：$off_state";
    _e88_note_line "MSS clamp" "默认 ON；用于降低 PMTU 黑洞/分片异常导致的卡顿。记录：$mss_state";
    echo "";
    echo "  【符号说明】";
    echo "    O = ON / 开启；X = OFF / 关闭。";
    echo "    OOOX = GRO ON、GSO ON、TSO ON、LRO OFF。";
    echo "";
    echo "  【建议】";
    echo "    日常翻墙：adv=1 / app=31 / txqueue=3000 / OOOX / MSS=ON。";
    echo "    高 RTT 吞吐测试：adv 可试 2 或 3，app 仍建议 31。"
}
# EEX3-FUNCTION legacy_e0_117 _e88_show_network_param_discussion
_e88_show_network_param_discussion() {
    title "V198e88 可放入 13 菜单管理的网络参数说明";
    cat <<'EOF_E88_DISCUSS'
  一、建议放进 13 菜单并可切换的高价值参数：
    1) tcp_notsent_lowat：影响小包响应、发送队列排队和高 RTT 吞吐；已提供 26214/32768/65536/131072/手动。
    2) rmem/wmem/tcp_rmem/tcp_wmem：影响高 RTT、大带宽连接的接收/发送缓冲；原菜单已有高吞吐、均衡、手动。
    3) default_qdisc + tcp_congestion_control：建议 fq + bbr；这是 VPS 代理的基础 pacing 组合。
    4) tcp_adv_win_scale + tcp_app_win：影响接收窗口与应用保留窗口；建议默认 1/31，实验可测 2/31。
    5) tcp_mtu_probing：建议 1，降低路径 MTU 黑洞导致的卡顿。
    6) tcp_ecn / tcp_fastopen：建议稳态关闭，即 0；不是默认提速开关。
    7) txqueuelen：建议 3000；过小可能压吞吐，过大可能增加排队延迟。
    8) GRO/GSO/TSO/LRO：建议 GRO/GSO/TSO 保留 ON，LRO OFF；降低 CPU 压力且避免 LRO 转发副作用。
    9) MSS clamp：建议可一键应用；用于 PMTU/分片异常时减少握手后卡顿。

  二、建议只显示、不做常规切换的参数：
    netdev_budget/dev_weight、tcp_retries、tcp_fin_timeout、somaxconn、backlog、ipfrag、dirty_ratio 等。
    它们会影响系统整体行为，过度菜单化容易造成“越调越乱”。

  三、当前 e88 菜单策略：
    保留原 1-12 项；新增 13-25 项。只把“最常用且可回退”的网络项放进菜单。
EOF_E88_DISCUSS

}
# EEX3-FUNCTION legacy_e0_117 _e88_show_notsent_conflicts
_e88_show_notsent_conflicts() {
    echo "";
    echo -e "  ${cyan}tcp_notsent_lowat 定义来源扫描：${none}";
    grep -R "^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=" /etc/sysctl.conf /etc/sysctl.d /usr/lib/sysctl.d /lib/sysctl.d 2> /dev/null | sed 's/^/    /' || true
}
# EEX3-FUNCTION legacy_e0_117 _e88_show_rps_rfs_state
_e88_show_rps_rfs_state() {
    title "V198e88：RPS/RFS 当前状态";
    local cpu_count mask flow_entries dev d rxq rxq_dir;
    cpu_count=$(nproc 2> /dev/null || echo 1);
    mask=$(_e88_cpu_mask_all_safe "$cpu_count");
    flow_entries=$(cat /proc/sys/net/core/rps_sock_flow_entries 2> /dev/null || echo "unknown");
    echo "  CPU 核心数: $cpu_count";
    echo "  推荐 RPS 掩码: 0x$mask";
    echo "  net.core.rps_sock_flow_entries: $flow_entries";
    echo "  e88 记录文件: $E88_RPS_STATE_FILE";
    if test -f "$E88_RPS_STATE_FILE"; then
        sed 's/^/    /' "$E88_RPS_STATE_FILE";
    fi;
    echo "";
    echo "  网卡队列读回：";
    for d in /sys/class/net/*;
    do
        test -e "$d" || continue;
        dev=$(basename "$d");
        _e88_is_physical_netdev "$dev" || continue;
        echo "    [$dev]";
        for rxq in /sys/class/net/$dev/queues/rx-*/rps_cpus;
        do
            test -f "$rxq" || continue;
            echo "      $(basename "$(dirname "$rxq")")/rps_cpus=$(cat "$rxq" 2> /dev/null || echo '?')";
        done;
        for rxq_dir in /sys/class/net/$dev/queues/rx-*/;
        do
            test -f "${rxq_dir}rps_flow_cnt" || continue;
            echo "      $(basename "$rxq_dir")/rps_flow_cnt=$(cat "${rxq_dir}rps_flow_cnt" 2> /dev/null || echo '?')";
        done;
    done
}
# EEX3-FUNCTION legacy_e0_117 _e88_show_tcp_notsent_lowat_state
_e88_show_tcp_notsent_lowat_state() {
    local run perm saved;
    run=$(_e88_current_notsent_lowat);
    perm=$(_e88_persistent_notsent_lowat);
    saved=$(cat "$E88_NOTSENT_LOWAT_FILE" 2> /dev/null || echo "未记录");
    echo "";
    echo -e "  ${cyan}tcp_notsent_lowat 状态：${none}";
    printf "    %-30s %s\n" "运行态(sysctl):" "$run";
