# EEX3-FUNCTION legacy_e0_117 _e88_ss_retrans_count
_e88_ss_retrans_count() {
    ss -ti 2> /dev/null | grep -oE 'retrans:[0-9]+/[0-9]+' | awk -F'[/:]' '{s+=$3} END{print s+0}' 2> /dev/null || echo 0
}
# EEX3-FUNCTION legacy_e0_117 _e88_ss_rtt_avg_ms
_e88_ss_rtt_avg_ms() {
    ss -ti 2> /dev/null | awk '
    {
      for (i=1;i<=NF;i++) {
        if ($i ~ /^rtt:/) {
          v=$i; sub(/^rtt:/,"",v); split(v,a,"/");
          if (a[1] ~ /^[0-9.]+$/) { total+=a[1]; count++ }
        }
      }
    }
    END { if (count>0) printf "%d\n", total/count }'
}
# EEX3-FUNCTION legacy_e0_117 _e88_strip_key_conflicts
_e88_strip_key_conflicts() {
    local key="$1" re f;
    re=$(_e88_escape_key_re "$key");
    mkdir -p "$BACKUP_DIR/sysctl" 2> /dev/null || true;
    for f in /etc/sysctl.conf /etc/sysctl.d/*.conf;
    do
        test -f "$f" || continue;
        if test "$(readlink -f "$f" 2> /dev/null || echo "$f")" = "$(readlink -f "$NETWORK_OPT_CONF" 2> /dev/null || echo "$NETWORK_OPT_CONF")"; then
            continue;
        fi;
        if grep -Eq "^[[:space:]]*${re}[[:space:]]*=" "$f" 2> /dev/null; then
            cp -af "$f" "$BACKUP_DIR/sysctl/$(basename "$f").e88.$(date +%Y%m%d_%H%M%S).bak" 2> /dev/null || true;
            sed -i -E "/^[[:space:]]*${re}[[:space:]]*=/d" "$f" 2> /dev/null || true;
            warn "已从冲突文件中移除 ${key}：$f";
        fi;
    done
}
# EEX3-FUNCTION legacy_e0_117 _e88_sysctl_get
_e88_sysctl_get() {
    local key="$1";
    sysctl -n "$key" 2> /dev/null | awk '{$1=$1; print}' || echo "unsupported"
}
# EEX3-FUNCTION legacy_e0_117 _e88_sysctl_persistent
_e88_sysctl_persistent() {
    local key="$1" file="${2:-$NETWORK_OPT_CONF}" re val;
    re=$(_e88_escape_key_re "$key");
    if test -f "$file"; then
        val=$(awk -F= -v re="^[[:space:]]*${re}[[:space:]]*=" '$0 ~ re {v=$2; gsub(/^[ \t]+|[ \t]+$/, "", v)} END{if(v!="") print v}' "$file" 2> /dev/null || true);
        test -n "$val" && echo "$val" || echo "未写入";
    else
        echo "文件不存在";
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e88_validate_notsent_lowat
_e88_validate_notsent_lowat() {
    local v="${1:-}";
    [[ "$v" =~ ^[0-9]+$ ]] || return 1;
    if test "$v" -eq 0 2> /dev/null; then
        return 0;
    fi;
    test "$v" -ge 4096 2> /dev/null && test "$v" -le 4194304 2> /dev/null
}
