# EEX3-FUNCTION legacy_e0_117 _e89_bbr3_flow
_e89_bbr3_flow() {
    local m conf go;
    while true; do
        title "V198e90：BBR3 / XanMod → bbrx3_v1 参数中心";
        echo "  当前替换路线：$(_e90_bbr_compile_mode_text)";
        echo "";
        echo "  1) 查看参数表：参数 / 原版 BBR3 / bbrx3_v1 建议 / 说明";
        echo "  2) 使用 bbrx3_v1 推荐参数生成配置";
        echo "  3) 自定义全部参数并生成配置（输入时同步显示参数表字段）";
        echo "  4) 使用当前配置替换 bbr（m=模块热替换；y=整内核编译）";
        echo "  0) 返回";
        read -rp "请选择: " m || true;
        case "${m:-}" in 
            1)
                _e89_show_bbr3_table;
                _e89_bbr_pause
            ;;
            2)
                _e89_collect_bbr3_params recommended || return;
                conf="$(_e89_write_bbr3_conf)";
                info "已写入：$conf";
                read -rp "是否立即替换 bbr？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbr3 "$conf";
                _e89_bbr_pause
            ;;
            3)
                _e89_collect_bbr3_params custom || return;
                conf="$(_e89_write_bbr3_conf)";
                info "已写入：$conf";
                read -rp "是否立即替换 bbr？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbr3 "$conf";
                _e89_bbr_pause
            ;;
            4)
                conf="$E89_BBRX_CURRENT/bbr3_replace.conf";
                if test -f "$conf"; then
                    _e89_build_replace_bbr bbr3 "$conf";
                else
                    warn "配置不存在，请先执行 2 或 3。";
                fi;
                _e89_bbr_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_backup_state
_e89_bbr_backup_state() {
    _e89_bbr_prepare_dirs;
    local ts bdir modp cfgv cc av;
    ts="$(date +%Y%m%d_%H%M%S)";
    bdir="$E89_BBRX_BACKUP_ROOT/$ts";
    mkdir -p "$bdir" || return 1;
    modp="$(_e89_bbr_mod_path)";
    cfgv="$(_e89_bbr_kconfig_value)";
    cc="$(sysctl -n net.ipv4.tcp_congestion_control 2> /dev/null || true)";
    av="$(sysctl -n net.ipv4.tcp_available_congestion_control 2> /dev/null || true)";
    { 
        echo "BACKUP_TS=$ts";
        echo "KERNEL_RELEASE=$(uname -r 2> /dev/null || true)";
        echo "CONFIG_TCP_CONG_BBR=$cfgv";
        echo "ORIGINAL_CC=$cc";
        echo "AVAILABLE_CC=$av";
        echo "ORIGINAL_BBR_KO=$modp"
    } > "$bdir/meta.env";
    uname -a > "$bdir/uname.txt" 2> /dev/null || true;
    sysctl -a 2> /dev/null | grep -E 'net\.ipv4\.tcp_|net\.core\.default_qdisc|net\.core\.[rw]mem|net\.core\.somaxconn' > "$bdir/sysctl_before.conf" 2> /dev/null || true;
    sysctl net.ipv4.tcp_available_congestion_control > "$bdir/available_cc_before.txt" 2> /dev/null || true;
    sysctl net.ipv4.tcp_congestion_control > "$bdir/selected_cc_before.txt" 2> /dev/null || true;
    tc qdisc show > "$bdir/qdisc_before.txt" 2> /dev/null || true;
    ip route show table main > "$bdir/route_before.txt" 2> /dev/null || true;
    lsmod > "$bdir/modules_before.txt" 2> /dev/null || true;
    modinfo tcp_bbr > "$bdir/modinfo_tcp_bbr_before.txt" 2> /dev/null || true;
    if test -n "$modp" && test -f "$modp"; then
        cp -a "$modp" "$bdir/tcp_bbr.ko.orig" 2> /dev/null || true;
        sha256sum "$modp" > "$bdir/tcp_bbr.ko.orig.sha256" 2> /dev/null || true;
    fi;
    local src;
    src="$(_e89_bbr_find_source 2> /dev/null || true)";
    if test -n "$src" && test -f "$src"; then
        cp -a "$src" "$bdir/tcp_bbr.c.orig" 2> /dev/null || true;
    fi;
    tar -czf "$bdir/sysctl_files_backup.tar.gz" /etc/sysctl.conf /etc/sysctl.d /etc/modules-load.d 2> /dev/null || true;
    echo "$bdir"
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_detect
_e89_bbr_detect() {
    title "V198e105：BBR 本体自动检测与编译建议";
    _e89_bbr_prepare_dirs;
    local krel cfgv cc av modp src kind rec;
    krel="$(uname -r 2> /dev/null || echo unknown)";
    cfgv="$(_e89_bbr_kconfig_value 2> /dev/null || echo unknown)";
    cc="$(sysctl -n net.ipv4.tcp_congestion_control 2> /dev/null || echo unknown)";
    av="$(sysctl -n net.ipv4.tcp_available_congestion_control 2> /dev/null || echo unknown)";
    modp="$(_e89_bbr_mod_path 2> /dev/null || true)";
    src="$(_e102_bbr_find_or_prepare_source 2> /dev/null || true)";
    kind="$(_e89_bbr_source_kind "$src" 2> /dev/null || echo unknown)";
    rec="$(_e89_bbr_recommend_kind 2> /dev/null || echo bbrv1)";
    echo "  当前内核：$krel";
    echo "  CONFIG_TCP_CONG_BBR：$cfgv";
    echo "  当前拥塞控制：$cc";
    echo "  可用拥塞控制：$av";
    echo "  tcp_bbr 模块路径：${modp:-未发现/可能内置}";
    if test -n "$src"; then
        echo "  可用 tcp_bbr.c 源码：$src";
        echo "  源码类型判断：$kind";
    else
        echo "  可用 tcp_bbr.c 源码：未找到与当前内核匹配的源码";
        echo "  源码类型判断：unknown";
    fi;
    hr;
    if test "$cfgv" = "m" && test -n "$modp" && test -f "$modp"; then
        print_green "  替换可行性：模块型 BBR，可热替换 tcp_bbr.ko，但必须使用当前内核匹配源码。";
    else
        if test "$cfgv" = "y"; then
            print_yellow "  替换可行性：内置型 BBR，不能替换 .ko；只能完整内核源码补丁编译，重启后生效。";
        else
            print_yellow "  替换可行性：未能确认模块型或内置型 BBR。";
        fi;
    fi;
    if test "$rec" = "bbr3"; then
        echo -e "  ${cyan}推荐编译方案：BBR3 / XanMod → bbrx3_v1 参数模板${none}";
    else
        echo -e "  ${cyan}推荐编译方案：普通 Linux 主线 BBR v1 → bbrx_v1 参数模板${none}";
    fi;
    echo "  当前替换路线：$(_e102_bbr_compile_mode_text)"
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_find_source
_e89_bbr_find_source() {
    _e102_bbr_find_or_prepare_source
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_find_source_e102_base
_e89_bbr_find_source_e102_base() {
    _e96_bbr_find_or_prepare_source
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_find_source_e95_base
_e89_bbr_find_source_e95_base() {
    local krel cand;
    krel="$(uname -r 2> /dev/null || true)";
    if test -n "${BBR_SOURCE:-}" && test -f "${BBR_SOURCE:-}"; then
        echo "$BBR_SOURCE";
        return 0;
    fi;
    for cand in "/lib/modules/$krel/build/net/ipv4/tcp_bbr.c" "/usr/src/linux-headers-$krel/net/ipv4/tcp_bbr.c" "/usr/src/linux-source-$krel/net/ipv4/tcp_bbr.c" /usr/src/linux*/net/ipv4/tcp_bbr.c /compile/linux*/net/ipv4/tcp_bbr.c /root/linux*/net/ipv4/tcp_bbr.c;
    do
        if test -f "$cand"; then
            echo "$cand";
            return 0;
        fi;
    done;
    return 1
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_kconfig_value
_e89_bbr_kconfig_value() {
    local krel cfg val;
    krel="$(uname -r 2> /dev/null || true)";
    for cfg in "/boot/config-$krel" "/lib/modules/$krel/build/.config" "/proc/config.gz";
    do
        if test "$cfg" = "/proc/config.gz" && test -f "$cfg"; then
            val=$(zcat "$cfg" 2> /dev/null | awk -F= '/^CONFIG_TCP_CONG_BBR=/{print $2; exit}' || true);
            test -n "$val" && { 
                echo "$val";
                return 0
            };
        else
            if test -f "$cfg"; then
                val=$(awk -F= '/^CONFIG_TCP_CONG_BBR=/{print $2; exit}' "$cfg" 2> /dev/null || true);
                test -n "$val" && { 
                    echo "$val";
                    return 0
                };
            fi;
        fi;
    done;
    echo "unknown"
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_mod_path
_e89_bbr_mod_path() {
    modinfo -n tcp_bbr 2> /dev/null || true
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_pause
_e89_bbr_pause() {
    if declare -F _e52_pause > /dev/null 2>&1; then
        _e52_pause;
    else
        local _p="";
        read -rp "按 Enter 继续..." _p || true;
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_prepare_dirs
_e89_bbr_prepare_dirs() {
    mkdir -p "$E89_BBRX_ROOT" "$E89_BBRX_CURRENT" "$E89_BBRX_BACKUP_ROOT" "$E89_BBRX_BUILD_ROOT" 2> /dev/null || true
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_recommend_kind
_e89_bbr_recommend_kind() {
    local src kind;
    src="$(_e89_bbr_find_source 2> /dev/null || true)";
    kind="$(_e89_bbr_source_kind "$src")";
    if test "$kind" = "unknown"; then
        if uname -r 2> /dev/null | grep -qiE 'xanmod|bbr3'; then
            kind="bbr3";
        else
            kind="bbrv1";
        fi;
    fi;
    echo "$kind"
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_rollback_latest
_e89_bbr_rollback_latest() {
    local bdir rb;
    bdir=$(ls -1dt "$E89_BBRX_BACKUP_ROOT"/* 2> /dev/null | head -n1 || true);
    if test -z "$bdir" || test ! -d "$bdir"; then
        error "未找到可回滚备份。";
        return 1;
    fi;
    rb="$bdir/rollback.sh";
    if test -x "$rb"; then
        bash "$rb";
    else
        error "备份中没有 rollback.sh：$bdir";
        return 1;
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_show_backups
_e89_bbr_show_backups() {
    title "V198e89：BBR 替换备份列表";
    ls -1dt "$E89_BBRX_BACKUP_ROOT"/* 2> /dev/null | head -n 20 | nl -w2 -s') ' || echo "  暂无备份。"
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_source_kind
_e89_bbr_source_kind() {
    local src="${1:-}";
    if test -n "$src" && test -f "$src"; then
        if grep -qE 'bbr_inflight_headroom|bbr_beta|bbr_probe_rtt_win_ms|bbr_bw_probe_max_rounds|BBR_VERSION[[:space:]]+3' "$src" 2> /dev/null; then
            echo "bbr3";
        else
            echo "bbrv1";
        fi;
    else
        if uname -r 2> /dev/null | grep -qiE 'xanmod|bbr3'; then
            echo "bbr3";
        else
            echo "unknown";
        fi;
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e89_bbr_status
_e89_bbr_status() {
