# EEX3-FUNCTION legacy_e0_117 _e89_bbrv1_flow
_e89_bbrv1_flow() {
    local m conf go;
    while true; do
        title "V198e90：普通 Linux 主线 BBR v1 → bbrx_v1 参数中心";
        echo "  当前替换路线：$(_e90_bbr_compile_mode_text)";
        echo "";
        echo "  1) 查看参数表：参数 / 原版 BBR / bbrx_v1 建议 / 说明";
        echo "  2) 使用 bbrx_v1 推荐参数生成配置";
        echo "  3) 自定义全部参数并生成配置（输入时同步显示参数表字段）";
        echo "  4) 使用当前配置替换 bbr（m=模块热替换；y=整内核编译）";
        echo "  0) 返回";
        read -rp "请选择: " m || true;
        case "${m:-}" in 
            1)
                _e89_show_bbrv1_table;
                _e89_bbr_pause
            ;;
            2)
                _e89_collect_bbrv1_params recommended || return;
                conf="$(_e89_write_bbrv1_conf)";
                info "已写入：$conf";
                read -rp "是否立即替换 bbr？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbrv1 "$conf";
                _e89_bbr_pause
            ;;
            3)
                _e89_collect_bbrv1_params custom || return;
                conf="$(_e89_write_bbrv1_conf)";
                info "已写入：$conf";
                read -rp "是否立即替换 bbr？[y/N]: " go || true;
                [[ "$go" =~ ^[yY]$ ]] && _e89_build_replace_bbr bbrv1 "$conf";
                _e89_bbr_pause
            ;;
            4)
                conf="$E89_BBRX_CURRENT/bbrv1_replace.conf";
                if test -f "$conf"; then
                    _e89_build_replace_bbr bbrv1 "$conf";
                else
                    warn "配置不存在，请先执行 2 或 3。";
                fi;
                _e89_bbr_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION legacy_e0_117 _e89_bool_c
_e89_bool_c() {
    if test "${1:-0}" = "1"; then
        echo "true";
    else
        echo "false";
    fi
}
# EEX3-FUNCTION legacy_e0_117 _e89_build_replace_bbr
_e89_build_replace_bbr() {
    local kind="$1" conf="$2" cfgv;
    cfgv="$(_e89_bbr_kconfig_value 2> /dev/null || echo unknown)";
    case "$cfgv" in 
        m)
            _e102_build_replace_bbr_module "$kind" "$conf"
        ;;
        y)
            _e90_build_builtin_bbr_kernel "$kind" "$conf"
        ;;
        *)
            error "当前 CONFIG_TCP_CONG_BBR=$cfgv，无法判断替换路线。";
            return 1
        ;;
    esac
}
