# EEX3-FUNCTION legacy_e0_117 _e90_build_builtin_bbr_kernel_e102_base
_e90_build_builtin_bbr_kernel_e102_base() {
    local kind="$1" conf="$2" bdir confirm route recommended alt bbr_arg old_allow rc;
    title "V198e91：内置型 BBR 源码补丁 + 完整内核编译路线";
    warn "当前 CONFIG_TCP_CONG_BBR=y：BBR 编进内核，不存在 tcp_bbr.ko 可热替换。";
    warn "正确路线：补丁 net/ipv4/tcp_bbr.c → 完整编译安装新内核 → 重启后生效。";
    warn "旧内核会保留；请确保有 VPS 快照 / VNC / 救援模式。";
    echo "";
    echo "  当前配置文件：$conf";
    echo "  参数模板：$kind";
    echo "  自动建议：$(_e89_bbr_recommend_kind 2> /dev/null || echo unknown)";
    echo "";
    _e91_conf_sane "$conf" "$kind" || return 1;
    if declare -F _kernel_source_precheck_e52 > /dev/null 2>&1; then
        _kernel_source_precheck_e52 || { 
            error "源码编译资源门槛未通过。";
            return 1
        };
    fi;
    read -rp "确认已有快照/VNC/救援模式，并开始完整内核编译？输入 YES 继续: " confirm || true;
    if test "$confirm" != "YES"; then
        warn "已取消内置型 BBR 编译。";
        return 1;
    fi;
    bdir="$(_e89_bbr_backup_state)" || { 
        error "备份失败，拒绝继续。";
        return 1
    };
    _e89_bbr_write_original_param_note "$bdir" "$kind";
    cp -af "$conf" "$bdir/generated_new_params.conf" 2> /dev/null || true;
    info "已创建编译前完整备份：$bdir";
    export E91_BBR_KERNEL_KIND="$kind";
    export E91_BBR_KERNEL_CONF="$conf";
    export E91_BBR_KERNEL_BACKUP="$bdir";
    export E90_BBR_KERNEL_KIND="$kind";
    export E90_BBR_KERNEL_CONF="$conf";
    export E90_BBR_KERNEL_BACKUP="$bdir";
    if test "$kind" = "bbr3" || uname -r 2> /dev/null | grep -qiE 'xanmod|bbr3'; then
        recommended="xanmod";
        alt="mainline";
    else
        recommended="mainline";
        alt="xanmod";
    fi;
    echo "";
    echo -e "  ${cyan}1) 源码编译 ${recommended}，并注入当前 BBR 参数 ${none}(推荐)";
    echo -e "  ${yellow}2) 源码编译 ${alt}，并注入当前 BBR 参数${none}";
    echo "  0) 取消";
    read -rp "请选择编译路线 (默认 1): " route || true;
    route="${route:-1}";
    case "$route" in 
        1)
            route="$recommended"
        ;;
        2)
            route="$alt"
        ;;
        0)
            warn "已取消。";
            unset E91_BBR_KERNEL_KIND E91_BBR_KERNEL_CONF E91_BBR_KERNEL_BACKUP E90_BBR_KERNEL_KIND E90_BBR_KERNEL_CONF E90_BBR_KERNEL_BACKUP;
            return 1
        ;;
        *)
            warn "无效选择，已取消。";
            unset E91_BBR_KERNEL_KIND E91_BBR_KERNEL_CONF E91_BBR_KERNEL_BACKUP E90_BBR_KERNEL_KIND E90_BBR_KERNEL_CONF E90_BBR_KERNEL_BACKUP;
            return 1
        ;;
    esac;
    bbr_arg="bbr";
    test "$kind" = "bbr3" && bbr_arg="bbr3";
    old_allow="${XRAY_ALLOW_SOURCE_KERNEL_COMPILE:-}";
    export XRAY_ALLOW_SOURCE_KERNEL_COMPILE=1;
    rc=0;
    case "$route" in 
        xanmod)
            _compile_kernel_xanmod || rc=$?
        ;;
        mainline)
            _compile_kernel_mainline "$bbr_arg" || rc=$?
        ;;
    esac;
    if test -n "$old_allow"; then
        export XRAY_ALLOW_SOURCE_KERNEL_COMPILE="$old_allow";
    else
        unset XRAY_ALLOW_SOURCE_KERNEL_COMPILE;
    fi;
    unset E91_BBR_KERNEL_KIND E91_BBR_KERNEL_CONF E91_BBR_KERNEL_BACKUP E90_BBR_KERNEL_KIND E90_BBR_KERNEL_CONF E90_BBR_KERNEL_BACKUP;
    if test "$rc" -ne 0; then
        error "内置型 BBR 源码编译/安装流程未完成。备份目录：$bdir";
        return "$rc";
    fi;
    info "V198e91：内置型 BBR 源码编译流程结束。请重启后验证 uname -r 与 ss -tin。";
    return 0
}
# EEX3-FUNCTION legacy_e0_117 _e90_build_replace_bbr_module_base
_e90_build_replace_bbr_module_base() {
    local kind="$1" conf="$2" cfgv modp src work newko bdir release_now;
    title "V198e89：编译并同名替换 tcp_bbr.ko（算法名仍为 bbr）";
    _e89_bbr_prepare_dirs;
    cfgv="$(_e89_bbr_kconfig_value)";
    modp="$(_e89_bbr_mod_path)";
    src="$(_e89_bbr_find_source 2> /dev/null || true)";
    if test "$cfgv" != "m"; then
        error "当前 CONFIG_TCP_CONG_BBR=$cfgv，不是模块型 m；为避免破坏内核，拒绝同名替换。";
        warn "如需内置型 BBR 真替换，请走完整内核源码编译路线。";
        return 1;
    fi;
    if test -z "$modp" || test ! -f "$modp"; then
        error "未找到原版 tcp_bbr.ko 路径，拒绝替换。";
        return 1;
    fi;
    if test -z "$src" || test ! -f "$src"; then
        error "未找到与当前内核匹配的 tcp_bbr.c 源码。";
        warn "可安装 linux-headers/linux-source，或导出 BBR_SOURCE=/path/to/tcp_bbr.c 后重试。";
        return 1;
    fi;
    if test ! -d "/lib/modules/$(uname -r)/build"; then
        error "缺少 /lib/modules/$(uname -r)/build，无法编译外部模块。请安装当前内核 headers。";
        return 1;
    fi;
    bdir="$(_e89_bbr_backup_state)" || { 
        error "备份失败，拒绝继续。";
        return 1
    };
    _e89_bbr_write_original_param_note "$bdir" "$kind";
    cp -af "$conf" "$bdir/generated_new_params.conf" 2> /dev/null || true;
    info "已创建替换前完整备份：$bdir";
    work="$E89_BBRX_BUILD_ROOT/build_$(date +%Y%m%d_%H%M%S)_$kind";
    mkdir -p "$work" || return 1;
    cp -af "$src" "$work/tcp_bbr.c";
    cp -af "$work/tcp_bbr.c" "$bdir/tcp_bbr.c.new.before_patch" 2> /dev/null || true;
    _e89_patch_bbr_source_from_conf "$work/tcp_bbr.c" "$conf" "$kind";
    cp -af "$work/tcp_bbr.c" "$bdir/tcp_bbr.c.new" 2> /dev/null || true;
    cat > "$work/Makefile" <<'EOF_MAKE'
obj-m += tcp_bbr.o
all:
	$(MAKE) -C /lib/modules/$(shell uname -r)/build M=$(PWD) modules
clean:
	$(MAKE) -C /lib/modules/$(shell uname -r)/build M=$(PWD) clean
EOF_MAKE

    info "开始编译 tcp_bbr.ko：$work";
    if ! make -C "/lib/modules/$(uname -r)/build" M="$work" modules; then
        error "编译失败，原系统未替换。工作目录：$work";
        return 1;
    fi;
    newko="$work/tcp_bbr.ko";
    if test ! -f "$newko"; then
        error "编译后未发现 $newko，拒绝替换。";
        return 1;
    fi;
    cp -af "$newko" "$bdir/tcp_bbr.ko.new" 2> /dev/null || true;
    sha256sum "$newko" > "$bdir/tcp_bbr.ko.new.sha256" 2> /dev/null || true;
    cat > "$bdir/rollback.sh" <<EOF_ROLLBACK
#!/usr/bin/env bash
set -e
ORIG_KO="$modp"
BACKUP_DIR="$bdir"
sysctl -w net.ipv4.tcp_congestion_control=cubic >/dev/null 2>&1 || true
modprobe -r tcp_bbr 2>/dev/null || rmmod tcp_bbr 2>/dev/null || true
if test -f "\$BACKUP_DIR/tcp_bbr.ko.orig"; then cp -af "\$BACKUP_DIR/tcp_bbr.ko.orig" "\$ORIG_KO"; fi
depmod -a
modprobe tcp_bbr || true
sysctl -w net.ipv4.tcp_congestion_control=bbr >/dev/null 2>&1 || true
sysctl --system >/dev/null 2>&1 || true
echo "已回滚到备份：\$BACKUP_DIR"
EOF_ROLLBACK

    chmod +x "$bdir/rollback.sh" 2> /dev/null || true;
    echo "";
    read -rp "是否临时切到 cubic 并尝试卸载旧 tcp_bbr 后立即热替换？[Y/n]: " release_now || true;
    if ! [[ "$release_now" =~ ^[nN]$ ]]; then
        sysctl -w net.ipv4.tcp_congestion_control=cubic > /dev/null 2>&1 || true;
        modprobe -r tcp_bbr 2> /dev/null || rmmod tcp_bbr 2> /dev/null || warn "旧 tcp_bbr 当前仍被引用，磁盘替换仍会执行；可能需重启后才完全生效。";
    fi;
    if ! _e89_install_new_ko_to_original_path "$newko" "$modp"; then
        error "写入新模块失败，尝试保持原状态。";
        return 1;
    fi;
    depmod -a > /dev/null 2>&1 || true;
    modprobe tcp_bbr 2> /dev/null || warn "modprobe tcp_bbr 未立即成功；如果旧模块仍在内存中，请重启后验证。";
    cat > "$E89_BBRX_SYSCTL" <<'EOF_SYSCTL'
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
EOF_SYSCTL

    echo "tcp_bbr" > "$E89_BBRX_MODULES_LOAD";
    sysctl -p "$E89_BBRX_SYSCTL" > /dev/null 2>&1 || true;
    info "替换完成。永久配置：$E89_BBRX_SYSCTL / $E89_BBRX_MODULES_LOAD";
    info "回滚脚本：$bdir/rollback.sh";
    sysctl net.ipv4.tcp_congestion_control 2> /dev/null || true;
    sysctl net.ipv4.tcp_available_congestion_control 2> /dev/null || true;
    modinfo tcp_bbr 2> /dev/null | sed -n '1,8p' || true
}
# EEX3-FUNCTION legacy_e0_117 _e90_execute_compilation_base
_e90_execute_compilation_base() {
    local extra_make_args="${1:-}" make_flags="${2:-}";
    local mem_mb swp_mb total_mb cpu_cores threads compiled_ver arg;
    local -a extra_args=();
    info "执行源码内核编译（argv隔离、安装步骤fail-fast）...";
    mem_mb=$(free -m 2> /dev/null | awk '/^Mem:/ {print int($2); exit}' || echo 1024);
    swp_mb=$(free -m 2> /dev/null | awk '/^Swap:/ {print int($2); exit}' || echo 0);
    [[ "$mem_mb" =~ ^[0-9]+$ ]] || mem_mb=1024;
    [[ "$swp_mb" =~ ^[0-9]+$ ]] || swp_mb=0;
    total_mb=$((mem_mb + swp_mb));
    cpu_cores=$(nproc 2> /dev/null || echo 1);
    [[ "$cpu_cores" =~ ^[1-9][0-9]*$ ]] || cpu_cores=1;
    threads=$((total_mb / 1000));
    test "$threads" -ge 1 || threads=1;
    test "$threads" -le "$cpu_cores" || threads=$cpu_cores;
    if test -n "$extra_make_args"; then
        read -r -a extra_args <<< "$extra_make_args";
        for arg in "${extra_args[@]}";
        do
            [[ "$arg" =~ ^[A-Za-z0-9_./:+,=@%-]+$ ]] || { 
                error "拒绝不安全的make参数：$arg";
                return 1
            };
        done;
    fi;
    if test -n "$make_flags" && gcc -E - -fcf-protection=none < /dev/null > /dev/null 2>&1; then
        make_flags="$make_flags -fcf-protection=none";
    fi;
    info "安全编译线程：$threads（内存+Swap ${total_mb}MB）";
    if test -n "$make_flags"; then
        make "-j$threads" "KCFLAGS=$make_flags" "${extra_args[@]}" || return 1;
    else
        make "-j$threads" "${extra_args[@]}" || return 1;
    fi;
    make modules_install || return 1;
    make install || return 1;
    compiled_ver=$(make -s kernelrelease 2> /dev/null || true);
    test -n "$compiled_ver" || { 
        error "无法识别编译后的 kernelrelease。";
        return 1
    };
    if command -v update-initramfs > /dev/null 2>&1; then
        if test -e "/boot/initrd.img-$compiled_ver"; then
            update-initramfs -u -k "$compiled_ver" || return 1;
        else
            update-initramfs -c -k "$compiled_ver" || return 1;
        fi;
    else
        if command -v dracut > /dev/null 2>&1; then
            dracut --force "/boot/initramfs-${compiled_ver}.img" "$compiled_ver" || return 1;
        else
            error "缺少 update-initramfs/dracut，无法生成 initramfs。";
            return 1;
        fi;
    fi;
    _kernel_pre_reboot_verify_e52 "$compiled_ver" || return 1;
    info "源码内核安装链路已通过：$compiled_ver。请确认有控制台/VNC后再重启。"
}
# EEX3-FUNCTION legacy_e0_117 _e90_kernel_patch_before_compile
_e90_kernel_patch_before_compile() {
    _e92_kernel_source_boot_space_guard || return 1;
    _e92_kernel_source_config_enforce_boot_safety || return 1;
    if declare -F _e90_kernel_patch_before_compile_e91_base > /dev/null 2>&1; then
        _e90_kernel_patch_before_compile_e91_base "$@" || return 1;
    fi;
    _e92_kernel_source_config_enforce_boot_safety || return 1;
    return 0
}
# EEX3-FUNCTION legacy_e0_117 _e90_kernel_patch_before_compile_e91_base
_e90_kernel_patch_before_compile_e91_base() {
    local ksrc="net/ipv4/tcp_bbr.c";
    local conf="${E91_BBR_KERNEL_CONF:-${E90_BBR_KERNEL_CONF:-}}";
    local kind="${E91_BBR_KERNEL_KIND:-${E90_BBR_KERNEL_KIND:-}}";
    local bdir="${E91_BBR_KERNEL_BACKUP:-${E90_BBR_KERNEL_BACKUP:-}}";
    local detected before after;
    test -n "$conf" || return 0;
    test -n "$kind" || return 0;
    _e91_conf_sane "$conf" "$kind" || return 1;
    if test ! -f "$ksrc"; then
        error "当前源码树未发现 $ksrc，拒绝继续编译，避免生成未注入参数的新内核。";
        return 1;
    fi;
    if test ! -x ./scripts/config; then
        error "当前源码树缺少 ./scripts/config，拒绝继续编译，避免 Kconfig 未正确写入。";
        return 1;
    fi;
    detected="$(_e91_kernel_source_kind "$ksrc")";
    if test "$detected" != "$kind" && test "${XRAY_BBRX_ALLOW_KIND_MISMATCH:-0}" != "1"; then
        error "源码类型与参数模板不匹配：源码=$detected，配置=$kind。";
        warn "如确实要强制交叉注入，请设置 XRAY_BBRX_ALLOW_KIND_MISMATCH=1 后重试；默认拒绝浪费编译时间。";
        return 1;
    fi;
    info "V198e91：正在注入 BBR 参数：kind=$kind source=$ksrc conf=$conf";
    before="$(sha256sum "$ksrc" 2> /dev/null | awk '{print $1}')";
    if test -n "$bdir" && test -d "$bdir"; then
        cp -af "$ksrc" "$bdir/tcp_bbr.c.kernel.before_patch" 2> /dev/null || true;
    fi;
    _e89_patch_bbr_source_from_conf "$ksrc" "$conf" "$kind";
    if ! _e91_verify_patch_hit "$ksrc" "$conf" "$kind"; then
        error "BBR 参数补丁未命中关键字段，拒绝继续编译。";
        warn "请检查当前源码是否真为 $kind，或改用推荐的 BBR 参数模板。";
        return 1;
    fi;
    after="$(sha256sum "$ksrc" 2> /dev/null | awk '{print $1}')";
    if test "$before" = "$after" && test "${XRAY_BBRX_ALLOW_NOOP_PATCH:-0}" != "1"; then
        warn "tcp_bbr.c 哈希未变化，可能源码已是同一组参数。默认继续写入 Kconfig，但建议确认不是重复编译。";
    fi;
    if test -n "$bdir" && test -d "$bdir"; then
        cp -af "$ksrc" "$bdir/tcp_bbr.c.kernel.after_patch" 2> /dev/null || true;
        diff -u "$bdir/tcp_bbr.c.kernel.before_patch" "$bdir/tcp_bbr.c.kernel.after_patch" > "$bdir/tcp_bbr.c.kernel.patch.diff" 2> /dev/null || true;
    fi;
    ./scripts/config --enable CONFIG_TCP_CONG_BBR 2> /dev/null || true;
    ./scripts/config --enable CONFIG_DEFAULT_BBR 2> /dev/null || true;
    if test "$kind" = "bbr3"; then
        ./scripts/config --enable CONFIG_TCP_BBR3 2> /dev/null || true;
    fi;
    ./scripts/config --set-str CONFIG_DEFAULT_TCP_CONG "bbr" 2> /dev/null || true;
    ./scripts/config --set-str CONFIG_LOCALVERSION "-bbrx91" 2> /dev/null || true;
    if ! make olddefconfig > /dev/null 2>&1; then
        error "make olddefconfig 失败，拒绝继续编译。";
        return 1;
    fi;
    info "V198e91：BBR 本体参数与 Kconfig 已注入源码，后续 make install 安装新内核，重启后生效。";
    return 0
}
# EEX3-FUNCTION legacy_e0_117 _e90_show_param_input_banner
_e90_show_param_input_banner() {
