# EEX3-FUNCTION legacy_e0_117 _e91_bbr3_flow
_e91_bbr3_flow() {
    local m conf go;
    while true; do
        title "V198e91：BBR3 / XanMod → bbrx3_v1 参数中心";
        echo "  当前替换路线：$(_e91_bbr_compile_mode_text)";
