# EEX3-FUNCTION legacy_e0_117 _e92_post_kernel_install_audit
_e92_post_kernel_install_audit() {
    local ver initrd;
    ver=$(make kernelversion 2> /dev/null || echo "");
    test -n "$ver" || return 0;
    for f in "/boot/initrd.img-$ver" "/boot/initramfs-$ver.img" "/boot/initramfs-${ver}.img";
    do
        if test -s "$f"; then
            initrd="$f";
            break;
        fi;
    done;
    if test -n "${initrd:-}"; then
        info "V198e92：新内核 initramfs 检查通过：$initrd";
    else
        warn "V198e92：未发现新内核 $ver 的 initramfs，请在重启前检查 update-initramfs/dracut 输出。";
    fi
}
