    "$IPT" -t mangle -A POSTROUTING -j XRAY_MSS_CLAMP 2>/dev/null || return 1
    return 0
}
apply_mss_one iptables || apply_mss_one iptables-legacy || apply_mss_one iptables-nft || true
exit 0
EOF_E70_HW

