}
# EEX3-FUNCTION legacy_e0_117 e75_build_full_config
e75_build_full_config() {
    local proto_choice="$1" ss_port="$2" ss_pass="$3" ss_method="$4";
    local tmp_config="$5";
    local need_vless="false" need_ss="false";
    if test "$proto_choice" = "1" || test "$proto_choice" = "3"; then
        need_vless="true";
    fi;
    if test "$proto_choice" = "2" || test "$proto_choice" = "3"; then
        need_ss="true";
    fi;
    local priv="" pub="" uuid="" sid="" ctime="";
    if test "$need_vless" = "true"; then
        local keys="";
        keys=$("$XRAY_BIN" x25519 2> /dev/null || true);
        priv=$(echo "$keys" | awk -F': ' 'tolower($1) ~ /private/ {print $2; exit}' | tr -d ' \r\n');
        pub=$(echo "$keys" | awk -F': ' 'tolower($1) ~ /public/ {print $2; exit}' | tr -d ' \r\n');
        uuid=$(cat /proc/sys/kernel/random/uuid 2> /dev/null || "$XRAY_BIN" uuid 2> /dev/null || true);
        sid=$(head -c 8 /dev/urandom | xxd -p | tr -d '\n\r' || true);
        ctime=$(date +"%Y-%m-%d %H:%M");
        if test -z "$priv" || test -z "$pub" || test -z "$uuid" || test -z "$sid"; then
            error "Reality 密钥 / UUID / ShortId 生成失败，终止写入。";
            return 1;
        fi;
    fi;
    if ! echo "$SNI_JSON_ARRAY" | jq -e 'type=="array" and length>0' > /dev/null 2>&1; then
        warn "SNI_JSON_ARRAY 非法，回退 www.microsoft.com。";
        SNI_JSON_ARRAY='["www.microsoft.com"]';
        BEST_SNI="www.microsoft.com";
    fi;
    jq -n --argjson need_vless "$need_vless" --argjson need_ss "$need_ss" --argjson vless_port "${LISTEN_PORT:-443}" --argjson ss_port "${ss_port:-8388}" --argjson snis "$SNI_JSON_ARRAY" --arg best_sni "${BEST_SNI:-www.microsoft.com}" --arg priv "$priv" --arg pub "$pub" --arg uuid "$uuid" --arg sid "$sid" --arg remark "${REMARK_NAME:-xp-reality}" --arg ss_pass "$ss_pass" --arg ss_method "$ss_method" '
{
  log: {
    loglevel: "warning",
    access: "none",
    error: "none"
  },
  routing: {
    domainStrategy: "AsIs",
    domainMatcher: "mph",
    rules: [
      {outboundTag: "block", _enabled: true, protocol: ["bittorrent"]},
      {outboundTag: "block", _enabled: true, domain: ["geosite:category-ads-all"]}
    ]
  },
  dns: {
    servers: ["https://1.1.1.1/dns-query", "https://208.67.224.224/dns-query"],
    queryStrategy: "UseIPv4"
  },
  policy: {
    levels: {
      "0": {
        handshake: 5,
        connIdle: 260,
        uplinkOnly: 2,
        downlinkOnly: 5,
        bufferSize: 768
      }
    },
    system: {
      statsInboundDownlink: false,
      statsInboundUplink: false
    }
  },
  inbounds: [],
  outbounds: [
    {
      protocol: "freedom",
      tag: "direct",
      settings: {domainStrategy: "AsIs"},
      streamSettings: {
        sockopt: {
          tcpNoDelay: true,
          tcpFastOpen: false,
          tcpKeepAliveIdle: 30,
          tcpKeepAliveInterval: 15
        }
      }
    },
    {
      protocol: "blackhole",
      tag: "block"
    }
  ]
}
| if $need_vless then
    .inbounds += [
      {
        tag: "vless-reality",
        listen: "0.0.0.0",
        port: $vless_port,
        protocol: "vless",
        settings: {
          clients: [
            {
              id: $uuid,
              flow: "xtls-rprx-vision",
              email: $remark
            }
          ],
          decryption: "none"
        },
        streamSettings: {
          network: "tcp",
          security: "reality",
          sockopt: {
            tcpNoDelay: true,
            tcpFastOpen: false,
            tcpKeepAliveIdle: 30,
            tcpKeepAliveInterval: 15
          },
          realitySettings: {
            show: false,
            dest: ($best_sni + ":443"),
            serverNames: $snis,
            privateKey: $priv,
            publicKey: $pub,
            shortIds: [$sid],
            maxTimeDiff: 60000,
            limitFallbackUpload: {afterBytes: 0, bytesPerSec: 0, burstBytesPerSec: 0},
            limitFallbackDownload: {afterBytes: 0, bytesPerSec: 0, burstBytesPerSec: 0}
          }
        },
        sniffing: {
          enabled: true,
          destOverride: ["http", "tls", "quic"],
          metadataOnly: true,
          routeOnly: true
        }
      }
    ]
  else . end
| if $need_ss then
    .inbounds += [
      {
        tag: "shadowsocks",
        listen: "0.0.0.0",
        port: $ss_port,
        protocol: "shadowsocks",
        settings: {
          method: $ss_method,
          password: $ss_pass,
          network: "tcp,udp"
        },
        streamSettings: {
          sockopt: {
            tcpNoDelay: true,
            tcpFastOpen: false,
            tcpKeepAliveIdle: 30,
            tcpKeepAliveInterval: 15
          }
        },
        sniffing: {
          enabled: true,
          destOverride: ["http", "tls", "quic"],
          metadataOnly: true,
          routeOnly: true
        }
      }
    ]
  else . end
' > "$tmp_config" || return 1;
    if test "$need_vless" = "true"; then
        echo "$pub" > "$PUBKEY_FILE";
        echo "$uuid|$ctime" > "$USER_TIME_MAP";
        : > "$USER_SNI_MAP";
    else
        : > "$USER_TIME_MAP";
        : > "$USER_SNI_MAP";
    fi;
    return 0
}
# EEX3-FUNCTION legacy_e0_117 e75_ensure_xray_service
e75_ensure_xray_service() {
