        out=$("$XRAY_BIN" vlessenc 2>&1 || true);
        if test -n "$out" && e77_generate_vlessenc_pair_from_text "$out" > /dev/null 2>&1; then
            info "VLESSENC：Core 命令存在，且 decryption/encryption 可成对解析。";
        else
            warn "VLESSENC：当前 Core 不支持，或输出格式无法可靠成对解析。";
        fi;
    fi
