# EEX3-FUNCTION legacy_e0_117 e77_gen_ss2022_pass
e77_gen_ss2022_pass() {
    local method="${1:-2022-blake3-aes-128-gcm}" bytes=0 value="";
    case "$method" in 
        2022-blake3-aes-128-gcm)
            bytes=16
        ;;
        2022-blake3-aes-256-gcm | 2022-blake3-chacha20-poly1305)
            bytes=32
        ;;
        *)
            error "不支持的 SS2022 加密方式：$method" 1>&2;
            return 1
        ;;
    esac;
    if command -v openssl > /dev/null 2>&1; then
        value=$(openssl rand -base64 "$bytes" 2> /dev/null | tr -d '\r\n');
    else
        value=$(head -c "$bytes" /dev/urandom | base64 | tr -d '\r\n');
    fi;
    test -n "$value" || return 1;
    printf '%s\n' "$value"
}
# EEX3-FUNCTION legacy_e0_117 e77_generate_vlessenc_pair
e77_generate_vlessenc_pair() {
    local out;
    out=$("$XRAY_BIN" vlessenc 2>&1 || true);
    test -n "$out" || { 
        warn "xray vlessenc 没有输出。";
        return 1
    };
    e77_generate_vlessenc_pair_from_text "$out"
}
# EEX3-FUNCTION legacy_e0_117 e77_generate_vlessenc_pair_from_text
e77_generate_vlessenc_pair_from_text() {
    local out="$1" pair dec enc;
    pair=$(printf '%s\n' "$out" | jq -r '
        ([.. | objects | .decryption? // empty] | first // "") as $d |
        ([.. | objects | .encryption? // empty] | first // "") as $e |
        if ($d|length)>0 and ($e|length)>0 then [$d,$e]|@tsv else empty end
    ' 2> /dev/null | head -n1 || true);
    if test -z "$pair"; then
        pair=$(printf '%s\n' "$out" | awk -F'"' '
            /"decryption"[[:space:]]*:/ && d=="" {d=$4; next}
            d!="" && /"encryption"[[:space:]]*:/ {print d "\t" $4; exit}');
    fi;
    dec=${pair%%'	'*};
    if [[ "$pair" == *'	'* ]]; then
        enc=${pair#*'	'};
    else
        enc="";
    fi;
    if test -z "$dec" || test -z "$enc" || test "${#dec}" -lt 16 || test "${#enc}" -lt 16; then
        dec=$(printf '%s\n' "$out" | jq -r '.. | objects | .decryption? // empty' 2> /dev/null | head -n1 || true);
        enc=$(printf '%s\n' "$out" | jq -r '.. | objects | .encryption? // empty' 2> /dev/null | head -n1 || true);
    fi;
    if test -z "$dec" || test -z "$enc" || [[ "$dec" =~ [[:space:]\"] ]] || [[ "$enc" =~ [[:space:]\"] ]]; then
        error "无法成对解析 xray vlessenc 的 decryption/encryption，拒绝拼接不同认证组。";
        printf '%s\n' "$out" | sed 's/^/    /' | tail -n 80 || true;
        return 1;
    fi;
    test "${#dec}" -ge 16 && test "${#enc}" -ge 16 || { 
        error "vlessenc 参数长度异常。";
        return 1
    };
    E77_VLESSENC_DECRYPTION="$dec";
    E77_VLESSENC_ENCRYPTION="$enc";
    E79_VLESSENC_ACTUAL_TUNING="xray-default-unmodified";
    case "${E79_VLESSENC_PROFILE:-balanced}" in 
        speed | strong)
            warn "为避免破坏 Xray 26.x 动态格式，e118 不再手工篡改 vlessenc 字符串；本次使用 Core 原生配对参数。"
        ;;
    esac;
    return 0
}
