# EEX3-FUNCTION legacy_e0_117 e77_pick_free_port
e77_pick_free_port() {
    local default_p="$1" prompt="$2" p="";
    while true; do
        read -rp "$prompt" p || true;
        p=${p:-$default_p};
        if ! [[ "$p" =~ ^[0-9]+$ ]] || test "$p" -lt 1 2> /dev/null || test "$p" -gt 65535 2> /dev/null; then
            error "端口必须是 1~65535 的整数。" 1>&2;
            continue;
        fi;
        if [[ " ${E118_RESERVED_PORTS:-} " == *" $p "* ]]; then
            error "端口 $p 已分配给本次候选配置中的另一个入站。" 1>&2;
            continue;
        fi;
        if ! ss -H -ltnu 2> /dev/null | awk -v p=":$p" '$4 ~ p"$" {found=1} END{exit !found}'; then
            printf '%s\n' "$p";
            return 0;
        fi;
        if _e118_port_owned_by_current_xray "$p"; then
            warn "端口 $p 正由当前 Xray 使用；事务重装将原位复用。" 1>&2;
            printf '%s\n' "$p";
            return 0;
        fi;
        error "端口 $p 已被其他 TCP/UDP 监听占用。" 1>&2;
    done
}
