# EEX3-FUNCTION runtime_e118_135 _e118_delete_user_record
_e118_delete_user_record() {
    local uuid="$1" t1 t2;
    t1=$(_e118_mktemp user-sni) || return 1;
    t2=$(_e118_mktemp user-time) || return 1;
    awk -F'|' -v u="$uuid" '$1!=u && $1!=""' "$USER_SNI_MAP" 2> /dev/null > "$t1" || true;
    awk -F'|' -v u="$uuid" '$1!=u && $1!=""' "$USER_TIME_MAP" 2> /dev/null > "$t2" || true;
    install -m 0600 "$t1" "$USER_SNI_MAP" && install -m 0600 "$t2" "$USER_TIME_MAP"
}
# EEX3-FUNCTION runtime_e118_135 _e118_download_official_installer
_e118_download_official_installer() {
    local out="$1" url actual;
    local -a urls=("https://raw.githubusercontent.com/XTLS/Xray-install/$E142_XRAY_INSTALL_COMMIT/install-release.sh" "https://github.com/XTLS/Xray-install/raw/$E142_XRAY_INSTALL_COMMIT/install-release.sh");
    for url in "${urls[@]}";
    do
        : > "$out" || return 1;
        curl --proto '=https' --tlsv1.2 -fsSL --show-error --retry 3 --connect-timeout 10 --max-time 180 -o "$out" "$url" || continue;
        actual=$(sha256sum "$out" 2> /dev/null | awk '{print $1}');
        test "$actual" = "$E142_XRAY_INSTALL_SHA256" || continue;
        head -n1 "$out" | grep -qE '^#!/usr/bin/env bash|^#!/bin/bash' || continue;
        grep -q 'XTLS/Xray-install' "$out" || continue;
        bash -n "$out" || continue;
        chmod 0700 "$out" || return 1;
        return 0;
    done;
    : > "$out" 2> /dev/null || true;
    return 1
}
# EEX3-FUNCTION runtime_e118_135 _e118_generate_reality_material
_e118_generate_reality_material() {
    local keys="";
    keys=$("$XRAY_BIN" x25519 2> /dev/null || true);
    _e118_parse_x25519_output "$keys" || { 
        error "无法解析 xray x25519 输出。V199e137 兼容 Password/PublicKey，但当前输出仍不符合预期。";
        printf '%s\n' "$keys" | sed 's/^/    /' || true;
        return 1
    };
    E77_REALITY_UUID=$(cat /proc/sys/kernel/random/uuid 2> /dev/null || "$XRAY_BIN" uuid 2> /dev/null || true);
    E77_REALITY_SID=$(openssl rand -hex 8 2> /dev/null || true);
    _e118_valid_uuid "$E77_REALITY_UUID" || return 1;
    _e118_valid_sid "$E77_REALITY_SID" || return 1
}
