# EEX3-FUNCTION runtime_e118_135 _e118_impl_check_and_clean_space
_e118_impl_check_and_clean_space() {
    info "执行 V199e137 安全空间清理（不 autoremove、不删除 headers/linux-source、不扫 /root 压缩包）。";
    command -v apt-get > /dev/null 2>&1 && apt-get clean > /dev/null 2>&1 || true;
    journalctl --vacuum-time=3d > /dev/null 2>&1 || true;
    find /tmp -maxdepth 1 -user root -type f \( -name 'xray.*' -o -name 'xray-*' -o -name 'sni_test.*' \) -mtime +1 -delete 2> /dev/null || true;
    if test -d /compile; then
        find /compile -mindepth 1 -maxdepth 1 -type d \( -name 'linux-*' -o -name 'xanmod*' -o -name 'bbr*' \) -mtime +2 -exec rm -rf -- {} + 2> /dev/null || true;
    fi;
    sync 2> /dev/null || true
}
# EEX3-FUNCTION runtime_e118_135 _e118_impl_cleanup_obsolete_network_layers
_e118_impl_cleanup_obsolete_network_layers() {
    _e111_prepare_dirs;
    _e111_backup_obsolete_state "${1:-e118-cleanup-obsolete}" || true;
    local s c statefile iface qline tool;
    for s in $E111_OBSOLETE_SERVICES;
    do
        systemctl disable --now "$s" > /dev/null 2>&1 || true;
    done;
    for statefile in "$CONFIG_DIR/netdiag_e108/shaping_state.env" "$CONFIG_DIR/netdiag_e109/shaping_state.env";
    do
        test -s "$statefile" || continue;
        iface=$(sed -n 's/^IFACE=//p' "$statefile" | head -n1 | tr -d "'\"" || true);
        [[ "$iface" =~ ^[A-Za-z0-9_.:-]+$ ]] || continue;
        qline=$(tc qdisc show dev "$iface" 2> /dev/null | head -n1 || true);
        if [[ "$qline" =~ (htb|tbf|netem) ]]; then
            tc qdisc del dev "$iface" root > /dev/null 2>&1 || true;
        fi;
    done;
    tool=$(_e111_first_iptables 2> /dev/null || true);
    for c in $E111_OBSOLETE_CHAINS;
    do
        test -n "$tool" && _e111_cleanup_chain_with_tool "$tool" "$c" || true;
        _e111_cleanup_chain_with_tool ip6tables "$c" || true;
        _e111_cleanup_chain_with_tool ip6tables-legacy "$c" || true;
        _e111_cleanup_chain_with_tool ip6tables-nft "$c" || true;
    done;
    rm -f /etc/systemd/system/xray-pmtu-mss-e106.service /etc/systemd/system/xray-pmtu-mss-e107.service /etc/systemd/system/xray-mss-e108.service /etc/systemd/system/xray-shape-e108.service /etc/systemd/system/xray-mss-e109.service /etc/systemd/system/xray-shape-e109.service /usr/local/bin/xray-pmtu-mss-e106.sh /usr/local/bin/xray-pmtu-mss-e107.sh /usr/local/bin/xray-mss-e108.sh /usr/local/bin/xray-shape-e108.sh /usr/local/bin/xray-mss-e109.sh /usr/local/bin/xray-shape-e109.sh /etc/sysctl.d/99-xray-pmtu-e106.conf /etc/sysctl.d/99-xray-pmtu-e107.conf /etc/sysctl.d/99-auto-tune-relay-e108.conf /etc/sysctl.d/99-auto-tune-relay-e108.profile.txt /etc/sysctl.d/99-auto-tune-relay-e109.conf /etc/sysctl.d/99-auto-tune-relay-e109.profile.txt 2> /dev/null || true;
    rm -rf -- "$CONFIG_DIR/pmtu_e106" "$CONFIG_DIR/pmtu_e107" "$CONFIG_DIR/netdiag_e108" "$CONFIG_DIR/netdiag_e109" 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || true
}
# EEX3-FUNCTION runtime_e118_135 _e118_impl_detect_ssh_ports
_e118_impl_detect_ssh_ports() {
    local ports="";
    if command -v sshd > /dev/null 2>&1; then
        ports="$ports $(sshd -T 2> /dev/null | awk '/^port /{print $2}')";
    fi;
    ports="$ports $(grep -hEi '^[[:space:]]*Port[[:space:]]+[0-9]+' /etc/ssh/sshd_config /etc/ssh/sshd_config.d/*.conf 2> /dev/null | awk '{print $2}')";
    ports="$ports $(ss -H -ltnp 2> /dev/null | awk '/sshd/ {p=$4; sub(/^.*:/,"",p); if(p~/^[0-9]+$/) print p}')";
    printf '%s\n' $ports 2> /dev/null | awk '$1~/^[0-9]+$/ && $1>=1 && $1<=65535{print $1}' | sort -nu
}
# EEX3-FUNCTION runtime_e118_135 _e118_impl_do_install
_e118_impl_do_install() {
    while true; do
        clear;
        title "V199e137：安装 / 重装节点（事务提交）";
        printf '  1) VLESS Reality Vision              %b\n' "${cyan}(默认推荐；Xray 26 Password兼容)${none}";
        printf '  2) Reality Vision + SS2022            %b\n' "${cyan}(主通道 + 备用通道)${none}";
        printf '  3) VLESSENC Vision 自选               %b\n' "${yellow}(Core原生配对参数，不再手改密文)${none}";
        printf '  4) SS2022                             %b\n' "${cyan}(轻量备用)${none}";
        echo "  0) 返回主菜单";
        hr;
        local sel="";
        read -rp "请输入编号 (回车默认 1): " sel || true;
        sel=${sel:-1};
        case "$sel" in 
            1)
                _e116_install_mode 1 "VLESS Reality Vision";
                _e116_pause;
                return
            ;;
            2)
                _e116_install_mode 4 "Reality Vision + SS2022";
                _e116_pause;
                return
            ;;
            3)
                _e116_install_mode 2 "VLESSENC Vision";
                _e116_pause;
                return
            ;;
            4)
                _e116_install_mode 3 "SS2022";
                _e116_pause;
                return
            ;;
            0 | q | Q)
                return
            ;;
            *)
                warn "无效选择。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION runtime_e118_135 _e118_impl_hot_update
_e118_impl_hot_update() {
    title "V199e137：事务稳态热更新";
    preflight || return 1;
    local bdir status_dat="failed" status_init="failed" status_ssh="failed" status_logs="failed" status_clean="failed" failed=0;
    bdir=$(_e116_backup_state "before_hot_update_e121") || { 
        error "热更新前快照失败，拒绝继续。";
        return 1
    };
    _e118_install_self || { 
        error "新脚本原子安装失败。";
        return 1
    };
    printf '%s\n' "$SCRIPT_VERSION" > "$SCRIPT_VERSION_FILE" || return 1;
    install_update_dat && status_dat="ok" || { 
        warn "DAT 更新器安装/即时更新不完整，旧 dat 已保留。";
        failed=1
    };
    if declare -F _e105_disable_xray_core_auto_update > /dev/null 2>&1; then
        _e105_disable_xray_core_auto_update || true;
    fi;
    _e116_apply_init_window_default30 && status_init="ok" || { 
        warn "initcwnd/initrwnd=30 未完全落地。";
        failed=1
    };
    _e111_cleanup_obsolete_network_layers "hot-update-e121" && status_clean="ok" || { 
        warn "旧实验网络层清理不完整。";
        failed=1
    };
    _e121_install_log_retention && status_logs="ok" || { 
        warn "3天日志滚动保留未完全落地。";
        failed=1
    };
    _e116_install_ssh_guard && status_ssh="ok" || { 
        warn "SSH 防爆破未完全安装，可稍后在菜单18重试。";
        failed=1
    };
    fix_permissions;
    if test -s "$CONFIG" && test -x "$XRAY_BIN"; then
        _e118_xray_test_config "$CONFIG" 1 || { 
            error "热更新后现有 Xray 配置复检失败。";
            failed=1
        };
        if test "$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2> /dev/null | head -n1)" = "1" && ! systemctl is-active --quiet xray; then
            error "热更新前 Xray 正在运行，但更新后未保持运行。";
            failed=1;
        fi;
    fi;
    printf '%s\n' "$SCRIPT_VERSION" > "$SCRIPT_VERSION_FILE" || return 1;
    { 
        echo "time=$(date '+%F %T')";
        echo "version=$SCRIPT_VERSION";
        echo "backup=$bdir";
        echo "dat=$status_dat";
        echo "init_window=$status_init";
        echo "ssh_guard=$status_ssh";
        echo "log_retention_3d=$status_logs";
        echo "legacy_cleanup=$status_clean"
    } > "$E118_STATE_FILE";
    chmod 600 "$E118_STATE_FILE" 2> /dev/null || true;
    info "V199e137 热更新主体完成。";
    echo "  DAT=$status_dat  init30=$status_init  SSH=$status_ssh  日志3天=$status_logs  旧层清理=$status_clean";
    info "回滚快照：$bdir";
    if test "$failed" -ne 0; then
        error "热更新存在未完成组件，已如实返回失败状态；可按上方状态逐项重试。";
        return 1;
    fi;
    return 0
}
