    { 
        echo "time=$(date '+%F %T')";
        echo "ports=$(_e116_detect_ssh_ports | paste -sd, -)";
        echo "maxretry=$E118_MAXRETRY";
        echo "findtime=$E118_FINDTIME";
        echo "bantime=$E118_BANTIME"
    } > "$E118_STATE_FILE";
    info "SSH 策略已生效：24小时内第2次失败触发封禁36小时；封禁数据库重启保留。"
}
# EEX3-FUNCTION runtime_e118_135 _e118_impl_install_update_dat
_e118_impl_install_update_dat() {
    _e118_prepare_dirs || return 1;
    local dat_candidate service_candidate timer_candidate;
    dat_candidate=$(_e118_mktemp update-dat.sh) || return 1;
    service_candidate=$(_e118_mktemp xray-dat-update.service) || return 1;
    timer_candidate=$(_e118_mktemp xray-dat-update.timer) || return 1;
    cat > "$dat_candidate" <<'UPDSH_E118'
#!/usr/bin/env bash
set -u
umask 022
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
DAT_DIR="/usr/local/share/xray"
CONFIG="/usr/local/etc/xray/config.json"
XRAY="/usr/local/bin/xray"
LOG="/var/log/xray/update-dat.log"
LOCK="/run/lock/xray-dat-update.lock"
mkdir -p "$DAT_DIR" "$(dirname "$LOG")" /run/lock 2>/dev/null || exit 1
exec 9>"$LOCK" || exit 1
LOCK_DIR=""
if command -v flock >/dev/null 2>&1; then
    flock -n 9 || exit 0
else
    LOCK_DIR="${LOCK}.d"
    mkdir "$LOCK_DIR" 2>/dev/null || exit 0
fi
TMP=$(mktemp -d /tmp/xray-dat-e118.XXXXXX) || exit 1
cleanup() {
    rm -rf "$TMP" 2>/dev/null || true
    test -z "$LOCK_DIR" || rmdir "$LOCK_DIR" 2>/dev/null || true
}
trap cleanup EXIT
trap 'exit 130' INT TERM HUP
log() { printf '[%s] %s\n' "$(date '+%F %T')" "$*" >> "$LOG"; }
if test -f "$LOG" && test "$(wc -c < "$LOG" 2>/dev/null || echo 0)" -gt 1048576; then
    tail -n 2000 "$LOG" > "$TMP/update-dat.log" 2>/dev/null && install -m 0640 "$TMP/update-dat.log" "$LOG" || true
fi
download_one() {
    local out="$1"; shift
    local url
    for url in "$@"; do
        if curl --proto '=https' --tlsv1.2 -fsSL --show-error --retry 3 --connect-timeout 10 --max-time 300 -o "$out" "$url"; then
            if test "$(wc -c < "$out" 2>/dev/null || echo 0)" -gt 1024; then return 0; fi
        fi
        : > "$out"
    done
    return 1
}

atomic_put() {
    local src="$1" dst="$2" mode="${3:-0644}" stage="${2}.e127-new.$$"
    install -m "$mode" "$src" "$stage" || { rm -f -- "$stage"; return 1; }
    mv -f -- "$stage" "$dst" || { rm -f -- "$stage"; return 1; }
}
socket_ready() {
    local proto="$1" port="$2" pid="$3" line=""
    if test "$proto" = tcp; then line=$(ss -H -ltnp 2>/dev/null | awk -v p=":$port" '$4~p"$"{print;exit}')
    else line=$(ss -H -lunp 2>/dev/null | awk -v p=":$port" '$4~p"$"{print;exit}')
    fi
    test -n "$line" || return 1
    if [[ "$line" == *"users:"* ]] && [[ "$line" != *"pid=$pid,"* ]] && [[ "$line" != *'"xray"'* ]]; then return 1; fi
}
verify_runtime() {
    local i stable=0 failed pid proto port network
    "$XRAY" run -test -config "$CONFIG" >/dev/null 2>&1 || return 1
    for i in {1..12}; do
        failed=0
        systemctl is-active --quiet xray.service 2>/dev/null || failed=1
        pid=$(systemctl show xray.service -p MainPID --value 2>/dev/null || true)
        [[ "$pid" =~ ^[1-9][0-9]*$ ]] && kill -0 "$pid" 2>/dev/null || failed=1
        if test "$failed" -eq 0; then
            while IFS=$'\t' read -r proto port network; do
                test -n "$proto" || continue
                if test "$proto" = vless; then socket_ready tcp "$port" "$pid" || { failed=1; break; }
                else
                    case ",${network:-tcp,udp}," in *,tcp,*) socket_ready tcp "$port" "$pid" || { failed=1; break; } ;; esac
                    case ",${network:-tcp,udp}," in *,udp,*) socket_ready udp "$port" "$pid" || { failed=1; break; } ;; esac
                fi
            done < <(jq -r '.inbounds[]? | select(.protocol=="vless" or .protocol=="shadowsocks") | [.protocol,(.port|tostring),(.settings.network//"tcp,udp")] | @tsv' "$CONFIG" 2>/dev/null)
        fi
        if test "$failed" -eq 0; then stable=$((stable+1)); test "$stable" -ge 3 && return 0; else stable=0; fi
        sleep 1
    done
    return 1
}
ok=0
download_one "$TMP/geoip.dat" \
  "https://github.com/Loyalsoldier/v2ray-rules-dat/raw/release/geoip.dat" \
  "https://raw.githubusercontent.com/Loyalsoldier/v2ray-rules-dat/release/geoip.dat" || { log "WARN geoip.dat 下载失败，保留旧文件"; ok=1; }
download_one "$TMP/geosite.dat" \
  "https://github.com/Loyalsoldier/domain-list-custom/releases/latest/download/geosite.dat" || { log "WARN geosite.dat 下载失败，保留旧文件"; ok=1; }

rollback_dat() {
    local n
    for n in geoip.dat geosite.dat; do
        if test -e "$TMP/$n.old"; then
            atomic_put "$TMP/$n.old" "$DAT_DIR/$n" 0644 || return 1
        elif test -e "$TMP/$n.was-absent"; then
            rm -f "$DAT_DIR/$n" 2>/dev/null || true
        fi
    done
}

changed=0
for name in geoip.dat geosite.dat; do
    test -s "$TMP/$name" || continue
    if test -s "$DAT_DIR/$name" && cmp -s "$TMP/$name" "$DAT_DIR/$name"; then
        log "INFO $name 无变化"
        continue
    fi
    if test -e "$DAT_DIR/$name"; then
        cp -a "$DAT_DIR/$name" "$TMP/$name.old" 2>/dev/null || { ok=1; continue; }
    else
        : > "$TMP/$name.was-absent"
    fi
    install -m 0644 "$TMP/$name" "$DAT_DIR/.$name.e118" || { ok=1; continue; }
    mv -f "$DAT_DIR/.$name.e118" "$DAT_DIR/$name" || { ok=1; continue; }
    changed=1
    log "INFO $name 已更新"
done

if test "$changed" -eq 1 && test -x "$XRAY"; then
    cat > "$TMP/dat-probe.json" <<'EOF_E118_DAT_PROBE'
{"log":{"loglevel":"none"},"inbounds":[],"outbounds":[{"protocol":"freedom","tag":"direct"}],"routing":{"domainStrategy":"AsIs","rules":[{"ip":["geoip:private"],"outboundTag":"direct"},{"domain":["geosite:category-ads-all"],"outboundTag":"direct"}]}}
EOF_E118_DAT_PROBE
    if ! "$XRAY" run -test -config "$TMP/dat-probe.json" >> "$LOG" 2>&1; then
        log "ERROR 新 dat 资源探针校验失败，回滚 dat"
        rollback_dat
        exit 1
    fi
    if test -s "$CONFIG" && ! "$XRAY" run -test -config "$CONFIG" >> "$LOG" 2>&1; then
        log "ERROR 新 dat 与当前配置校验失败，回滚 dat"
        rollback_dat
        exit 1
    fi
fi
if test "$changed" -eq 1 && systemctl is-active --quiet xray; then
    if systemctl restart xray.service >/dev/null 2>&1 && verify_runtime; then
        log "INFO Xray 已重启并通过 MainPID/入站端口稳定探针"
    else
        log "ERROR Xray 重启失败，回滚 dat 并恢复旧服务"
        if ! rollback_dat; then log "CRITICAL dat 原子回滚失败"; exit 1; fi
        if ! systemctl restart xray.service >/dev/null 2>&1 || ! verify_runtime; then
            log "CRITICAL 旧 dat 恢复后 Xray 仍未通过稳定探针"
        else
            log "INFO 旧 dat 与 Xray 运行态已恢复"
        fi
        exit 1
    fi
fi
exit "$ok"
UPDSH_E118

    bash -n "$dat_candidate" || { 
        error "DAT 更新器候选脚本语法失败。";
        return 1
    };
    _e118_atomic_install "$dat_candidate" "$UPDATE_DAT_SCRIPT" 0755 || return 1;
    cat > "$service_candidate" <<EOF_E118_DAT_SERVICE
[Unit]
Description=Xray geoip/geosite transactional updater V199e137
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$UPDATE_DAT_SCRIPT
Nice=10
IOSchedulingClass=best-effort
IOSchedulingPriority=7
UMask=0022
EOF_E118_DAT_SERVICE

    cat > "$timer_candidate" <<'EOF_E118_DAT_TIMER'
[Unit]
Description=Daily Xray dat update V199e137

[Timer]
OnCalendar=*-*-* 03:00:00
RandomizedDelaySec=20m
Persistent=true
AccuracySec=1m

[Install]
WantedBy=timers.target
EOF_E118_DAT_TIMER

    _e118_atomic_install "$service_candidate" /etc/systemd/system/xray-dat-update.service 0644 || return 1;
    _e118_atomic_install "$timer_candidate" /etc/systemd/system/xray-dat-update.timer 0644 || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl enable --now xray-dat-update.timer > /dev/null 2>&1 || return 1;
    if "$UPDATE_DAT_SCRIPT"; then
        info "geoip/geosite 更新器已安装并完成即时检查；每日 03:00 触发。";
        return 0;
    fi;
    warn "DAT 即时更新未完全成功，旧文件已保留；定时器仍会重试。";
    return 1
}
