# EEX3-FUNCTION runtime_e118_135 _e118_impl_show_init_window_state
_e118_impl_show_init_window_state() {
    title "V199e137：TCP initcwnd/initrwnd 状态";
    local route cw rw pcw prw;
    route=$(ip route show default 2> /dev/null | head -n1 || true);
    cw=$(sed -n 's/.*[[:space:]]initcwnd[[:space:]]\+\([0-9]\+\).*/\1/p' <<< "$route");
    rw=$(sed -n 's/.*[[:space:]]initrwnd[[:space:]]\+\([0-9]\+\).*/\1/p' <<< "$route");
    pcw=$(cat "$CONFIG_DIR/initcwnd.txt" 2> /dev/null || true);
    prw=$(cat "$CONFIG_DIR/initrwnd.txt" 2> /dev/null || true);
    echo "  默认路由：${route:-未发现}";
    echo "  运行态：initcwnd=${cw:-系统默认} initrwnd=${rw:-系统默认}";
    echo "  持久化：initcwnd=${pcw:-未记录} initrwnd=${prw:-未记录}";
    echo "  恢复服务：$(systemctl is-enabled xray-init-window-e105.service 2> /dev/null || echo disabled)"
}
