# EEX3-FUNCTION runtime_e118_135 _e118_impl_uninstall
_e118_impl_uninstall() {
    title "V199e137：受控卸载 Xray 环境";
    warn "将删除 Xray Core、配置、脚本服务和节点密钥；不会 purge dnsmasq，也不会删除你当前下载的 ex199e136.sh。";
    local confirm="" archive="/root/xray-before-uninstall-$(date +%Y%m%d_%H%M%S).tgz" f2b_active=0 f2b_enabled=0;
    read -rp "请输入 DELETE-XRAY 确认: " confirm || true;
    test "$confirm" = "DELETE-XRAY" || { 
        info "已取消。";
        return 0
    };
    if test -d "$CONFIG_DIR"; then
        tar -czf "$archive" "$CONFIG_DIR" "$SCRIPT_DIR" 2> /dev/null && info "卸载前备份：$archive" || warn "卸载前压缩备份失败。";
    fi;
    local unit;
    while IFS= read -r unit; do
        test -n "$unit" && systemctl disable --now "$unit" > /dev/null 2>&1 || true;
    done < <(systemctl list-unit-files --no-legend 'xray*' 2> /dev/null | awk '{print $1}');
    systemctl is-active --quiet fail2ban 2> /dev/null && f2b_active=1 || true;
    systemctl is-enabled --quiet fail2ban 2> /dev/null && f2b_enabled=1 || true;
    systemctl stop fail2ban > /dev/null 2>&1 || true;
    rm -f "$E118_F2B_JAIL" "$E118_F2B_DB_CONF" "$E116_F2B_JAIL" "$E116_F2B_DB_CONF" "${E121_F2B_JAIL:-}" "${E121_F2B_DB_CONF:-}" "${E121_F2B_COMPAT_CONF:-}" /etc/fail2ban/jail.d/99-xray-sshguard-e117.conf /etc/fail2ban/fail2ban.d/99-xray-e117-persistence.conf /etc/fail2ban/jail.d/99-xray-sshguard-e119.conf /etc/fail2ban/fail2ban.d/99-xray-e119-persistence.conf /etc/fail2ban/jail.d/zz-xray-sshguard-e119-compat.local /etc/rsyslog.d/30-xray-ssh-auth-e119.conf /etc/fail2ban/jail.d/99-xray-sshguard-e120.conf /etc/fail2ban/fail2ban.d/99-xray-e120-persistence.conf /etc/fail2ban/jail.d/zz-xray-sshguard-e120-compat.local /etc/rsyslog.d/30-xray-ssh-auth-e120.conf "${E121_RSYSLOG_CONF:-}" 2> /dev/null || true;
    systemctl reload rsyslog > /dev/null 2>&1 || true;
    if test "$f2b_enabled" -eq 1; then
        systemctl enable fail2ban > /dev/null 2>&1 || true;
    else
        systemctl disable fail2ban > /dev/null 2>&1 || true;
    fi;
    if test "$f2b_active" -eq 1; then
        systemctl start fail2ban > /dev/null 2>&1 || true;
    fi;
    if test -f /etc/resolv.conf.bak && test -e /etc/systemd/system/xray-static-dns-guard.service; then
        chattr -i /etc/resolv.conf 2> /dev/null || true;
        cp -f /etc/resolv.conf.bak /etc/resolv.conf 2> /dev/null || true;
    fi;
    rm -f /etc/systemd/system/xray*.service /etc/systemd/system/xray*.timer "$E118_SSH_GUARD_SCRIPT" "$E116_SSH_PORT_GUARD_SCRIPT" /usr/local/bin/xray-init-window-e105.sh /usr/local/bin/xray-dat-update.sh "$SYMLINK" "$XRAY_BIN" 2> /dev/null || true;
    rm -rf -- "$CONFIG_DIR" "$DAT_DIR" "$SCRIPT_DIR" "$LOG_DIR" 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || true;
    info "Xray 环境已卸载。备份（若成功）：$archive";
    exit 0
}
