# EEX3-FUNCTION runtime_e118_135 _e118_mktemp
_e118_mktemp() {
    local stem="${1:-tmp}" base ext;
    test -n "${E118_TMPDIR:-}" || _e118_runtime_init || return 1;
    stem=${stem##*/};
    case "$stem" in 
        *.*)
            base=${stem%.*};
            ext=.${stem##*.}
        ;;
        *)
            base=$stem;
            ext=""
        ;;
    esac;
    base=$(printf '%s' "$base" | tr -c 'A-Za-z0-9_.-' '_');
    ext=$(printf '%s' "$ext" | tr -c 'A-Za-z0-9._-' '_');
    test -n "$base" || base=tmp;
    case "$ext" in 
        "" | .[A-Za-z0-9]*)

        ;;
        *)
            ext=""
        ;;
    esac;
    mktemp "$E118_TMPDIR/${base}.XXXXXX${ext}"
}
# EEX3-FUNCTION runtime_e118_135 _e118_new_sid
_e118_new_sid() {
    local s;
    s=$(openssl rand -hex 8 2> /dev/null || true);
    _e118_valid_sid "$s" || return 1;
    printf '%s' "$s"
}
# EEX3-FUNCTION runtime_e118_135 _e118_new_uuid
_e118_new_uuid() {
    local u;
    u=$(cat /proc/sys/kernel/random/uuid 2> /dev/null || "$XRAY_BIN" uuid 2> /dev/null || true);
    _e118_valid_uuid "$u" || return 1;
    printf '%s' "$u"
}
# EEX3-FUNCTION runtime_e118_135 _e118_parse_x25519_output
_e118_parse_x25519_output() {
    local out="${1:-}" priv="" pub="" derived="";
    priv=$(_e124_x25519_field_from_text private "$out" 2> /dev/null || true);
    pub=$(_e124_x25519_field_from_text public "$out" 2> /dev/null || true);
    if _e124_valid_x25519_value "$priv" && ! _e124_valid_x25519_value "$pub"; then
        pub=$(_e124_reality_password_from_private "$priv" 2> /dev/null || true);
    fi;
    _e124_valid_x25519_value "$priv" || return 1;
    _e124_valid_x25519_value "$pub" || return 1;
    E77_REALITY_PRIV="$priv";
    E77_REALITY_PUB="$pub"
}
# EEX3-FUNCTION runtime_e118_135 _e118_port_in_use_elsewhere
_e118_port_in_use_elsewhere() {
    local p="$1" current="$2";
    test "$p" = "$current" && return 1;
    ss -H -ltn 2> /dev/null | awk -v p=":$p" '$4 ~ p"$" {found=1} END{exit !found}'
}
# EEX3-FUNCTION runtime_e118_135 _e118_port_owned_by_current_xray
_e118_port_owned_by_current_xray() {
    local p="$1";
    test -s "$CONFIG" && systemctl is-active --quiet xray 2> /dev/null || return 1;
    jq -e --argjson p "$p" '.inbounds[]? | select(.port==$p)' "$CONFIG" > /dev/null 2>&1 || return 1;
    ss -H -ltnup 2> /dev/null | awk -v p=":$p" '$4 ~ p"$" && $0 ~ /xray/ {found=1} END{exit !found}'
}
# EEX3-FUNCTION runtime_e118_135 _e118_prepare_dirs
_e118_prepare_dirs() {
    local d mode owner;
    mkdir -p "$CONFIG_DIR" "$DAT_DIR" "$SCRIPT_DIR" "$LOG_DIR" "$FLAGS_DIR" /run/lock 2> /dev/null || return 1;
    for d in "$BACKUP_DIR" "$E118_DIR" "$E118_BACKUP_DIR" "$E118_AUDIT_DIR";
    do
        test ! -L "$d" || { 
            error "拒绝使用符号链接事务目录：$d";
            return 1
        };
        install -d -o root -g root -m 0700 "$d" || return 1;
        mode=$(stat -c '%a' "$d" 2> /dev/null || true);
        owner=$(stat -c '%u:%g' "$d" 2> /dev/null || true);
        test "$mode" = 700 && test "$owner" = 0:0 || { 
            error "事务目录权限不安全：$d owner=$owner mode=$mode";
            return 1
        };
    done
}
# EEX3-FUNCTION runtime_e118_135 _e118_readonly_init
_e118_readonly_init() {
    if test -z "${E118_TMPDIR:-}"; then
        E118_TMPDIR=$(mktemp -d /tmp/ex199e136-readonly.XXXXXX) || return 1;
        chmod 700 "$E118_TMPDIR" 2> /dev/null || true;
    fi
}
# EEX3-FUNCTION runtime_e118_135 _e118_reality_password
_e118_reality_password() {
    local priv="" embedded="";
    priv=$(jq -r '.inbounds[]? | select(.protocol=="vless" and (.streamSettings.security//"")=="reality") | .streamSettings.realitySettings.privateKey // empty' "$CONFIG" 2> /dev/null | awk 'NF&&!done{print;done=1}');
    test -n "$priv" || return 1;
    embedded=$(jq -r '.inbounds[]? | select(.protocol=="vless" and (.streamSettings.security//"")=="reality") | (.streamSettings.realitySettings.password // .streamSettings.realitySettings.publicKey // empty)' "$CONFIG" 2> /dev/null | awk 'NF&&!done{print;done=1}');
    _e124_reality_password_for_private "$priv" "$embedded"
}
# EEX3-FUNCTION runtime_e118_135 _e118_remove_legacy_ssh_guard
_e118_remove_legacy_ssh_guard() {
    systemctl disable --now xray-ssh-port-guard-e116.service > /dev/null 2>&1 || true;
    rm -f "$E116_SSH_PORT_GUARD_SCRIPT" "$E116_SSH_PORT_GUARD_SERVICE" "$E116_F2B_JAIL" "$E116_F2B_DB_CONF" 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || true;
    if command -v fail2ban-client > /dev/null 2>&1; then
        fail2ban-client reload > /dev/null 2>&1 || return 1;
    fi;
    local managed=0 p legacy=0;
    command -v ufw > /dev/null 2>&1 && ufw status 2> /dev/null | grep -qi '^Status: active' && managed=1 || true;
    command -v firewall-cmd > /dev/null 2>&1 && systemctl is-active --quiet firewalld && managed=1 || true;
    if command -v iptables > /dev/null 2>&1; then
        while IFS= read -r p; do
            iptables -C INPUT -p tcp --dport "$p" -j ACCEPT > /dev/null 2>&1 || continue;
            legacy=1;
            if test "$managed" -eq 1; then
                while iptables -C INPUT -p tcp --dport "$p" -j ACCEPT > /dev/null 2>&1; do
                    iptables -D INPUT -p tcp --dport "$p" -j ACCEPT > /dev/null 2>&1 || break;
                done;
            fi;
        done < <(_e116_detect_ssh_ports);
    fi;
    if test "$legacy" -eq 1 && test "$managed" -ne 1; then
        error "检测到 e116 风格的裸 SSH ACCEPT，但系统未启用 UFW/firewalld；为避免锁机未自动删除。该规则可能绕过 fail2ban，请人工核对 iptables INPUT 顺序。";
        return 1;
    fi;
    return 0
}
# EEX3-FUNCTION runtime_e118_135 _e118_restore_core_payload
_e118_restore_core_payload() {
    local bdir="$1" name path was_active=0 was_enabled=0;
    _e127_backup_dir_ok "$bdir" || return 1;
    test ! -e "$bdir/core-payload-pruned" || { 
        error "该旧快照仅保留配置，Core 载荷已按空间策略收敛：$bdir";
        return 1
    };
    if test -s "$bdir/core-payload.sha256"; then
        ( cd "$bdir" && sha256sum -c core-payload.sha256 > /dev/null 2>&1 ) || { 
            error "Core/DAT/systemd 回滚载荷校验和失败：$bdir";
            return 1
        };
    fi;
    if test -f "$bdir/xray.core.before.sha256"; then
        ( cd "$bdir" && sha256sum -c xray.core.before.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2> /dev/null | head -n1);
    was_active=${was_active:-0};
    was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$bdir/meta.env" 2> /dev/null | head -n1);
    was_enabled=${was_enabled:-0};
    if test -f "$bdir/xray.core.before"; then
        _e118_atomic_install "$bdir/xray.core.before" "$XRAY_BIN" 0755 || return 1;
    else
        if test -e "$bdir/xray.core.was-absent"; then
            rm -f -- "$XRAY_BIN" 2> /dev/null || true;
        fi;
    fi;
    for name in geoip.dat geosite.dat;
    do
        if test -f "$bdir/core-$name.before"; then
            _e118_atomic_install "$bdir/core-$name.before" "$DAT_DIR/$name" 0644 || return 1;
        else
            if test -e "$bdir/core-$name.was-absent"; then
                rm -f -- "$DAT_DIR/$name" 2> /dev/null || true;
            fi;
        fi;
    done;
    for name in xray.service xray@.service;
    do
        path="/etc/systemd/system/$name";
        if test -f "$bdir/unit-$name.before"; then
            _e118_atomic_install "$bdir/unit-$name.before" "$path" 0644 || return 1;
        else
            if test -e "$bdir/unit-$name.was-absent"; then
                rm -f -- "$path" 2> /dev/null || true;
            fi;
        fi;
    done;
    for name in xray.service.d xray@.service.d;
    do
        path="/etc/systemd/system/$name";
        if test -d "$bdir/unit-$name.before"; then
            _e127_atomic_restore_dir "$bdir/unit-$name.before" "$path" || return 1;
        else
            if test -e "$bdir/unit-$name.was-absent"; then
                rm -rf -- "$path" 2> /dev/null || true;
            fi;
        fi;
    done;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    if test "$was_enabled" = 1; then
        systemctl enable xray.service > /dev/null 2>&1 || return 1;
    else
        systemctl disable xray.service > /dev/null 2>&1 || true;
    fi;
    if test "$was_active" = 1; then
        test -x "$XRAY_BIN" && test -s "$CONFIG" || return 1;
        _e118_xray_test_config "$CONFIG" 1 || return 1;
        systemctl reset-failed xray.service > /dev/null 2>&1 || true;
        systemctl restart xray.service > /dev/null 2>&1 || return 1;
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1;
    else
        systemctl stop xray.service > /dev/null 2>&1 || true;
        systemctl is-active --quiet xray.service 2> /dev/null && return 1 || true;
    fi
}
# EEX3-FUNCTION runtime_e118_135 _e118_restore_state
_e118_restore_state() {
    local bdir="${1:-}" f base was_active=0 was_enabled=0 restore_failed=0 now;
    _e127_verify_state_snapshot "$bdir" || return 1;
    was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2> /dev/null | head -n1);
    was_active=${was_active:-0};
    was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$bdir/meta.env" 2> /dev/null | head -n1);
    was_enabled=${was_enabled:-0};
    [[ "$was_active" =~ ^[01]$ && "$was_enabled" =~ ^[01]$ ]] || return 1;
    if grep -qx config.json "$bdir/files.manifest" 2> /dev/null; then
        test -s "$bdir/config.json" || return 1;
        _e118_xray_test_config "$bdir/config.json" 1 || return 1;
    fi;
    while IFS= read -r f; do
        test -n "$f" || continue;
        base=$(basename "$f");
        if grep -qxF "$base" "$bdir/files.manifest" 2> /dev/null; then
            _e118_atomic_install "$bdir/$base" "$f" 0600 || { 
                restore_failed=1;
                break
            };
        else
            rm -f -- "$f" 2> /dev/null || restore_failed=1;
        fi;
    done < <(_e118_managed_state_files);
    test "$restore_failed" -eq 0 || return 1;
    fix_permissions || return 1;
    if test "$was_enabled" = 1; then
        systemctl enable xray.service > /dev/null 2>&1 || return 1;
    else
        systemctl disable xray.service > /dev/null 2>&1 || return 1;
        now=$(systemctl is-enabled xray.service 2> /dev/null || true);
        case "$now" in 
            enabled | enabled-runtime | linked | linked-runtime)
                return 1
            ;;
        esac;
    fi;
    if test "$was_active" = 1; then
        systemctl reset-failed xray.service > /dev/null 2>&1 || true;
        systemctl restart xray.service > /dev/null 2>&1 || return 1;
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1;
    else
        systemctl stop xray.service > /dev/null 2>&1 || true;
        systemctl is-active --quiet xray.service 2> /dev/null && return 1 || true;
    fi;
    E118_TX_ACTIVE=0;
    E118_TX_BACKUP="";
    E118_TX_WAS_ACTIVE=0;
    return 0
}
# EEX3-FUNCTION runtime_e118_135 _e118_runtime_init
_e118_runtime_init() {
    if test "${E118_RUNTIME_READY:-0}" -eq 1; then
        return 0;
    fi;
    umask 077;
    _e118_prepare_dirs || { 
        error "无法创建 V199e137 工作目录。";
        return 1
    };
    E118_TMPDIR=$(mktemp -d /tmp/ex199e136.XXXXXX 2> /dev/null || true);
    if test -z "$E118_TMPDIR"; then
        E118_TMPDIR=$(mktemp -d /run/ex199e266.XXXXXX 2> /dev/null || true);
    fi;
    test -n "$E118_TMPDIR" || { 
        error "无法在/tmp或/run创建安全临时目录。";
        return 1
    };
    chmod 700 "$E118_TMPDIR" 2> /dev/null || true;
    if command -v flock > /dev/null 2>&1; then
        exec 9> "$E118_LOCK_FILE" || return 1;
        if ! flock -n 9; then
            error "检测到另一个 ex199e136/xrv 实例正在运行。为避免并发覆盖，本次退出。";
            return 1;
        fi;
    else
        E118_LOCK_DIR="${E118_LOCK_FILE}.d";
        if ! mkdir "$E118_LOCK_DIR" 2> /dev/null; then
            error "检测到另一个 ex199e136/xrv 实例正在运行，或遗留锁目录：$E118_LOCK_DIR";
            return 1;
        fi;
    fi;
    E118_RUNTIME_READY=1;
    trap '_e118_signal_handler INT' INT;
    trap '_e118_signal_handler TERM' TERM;
    trap '_e118_signal_handler HUP' HUP;
    return 0
}
# EEX3-FUNCTION runtime_e118_135 _e118_save_core_payload
_e118_save_core_payload() {
    local bdir="$1" file rel item;
    _e127_backup_dir_ok "$bdir" || return 1;
    _e127_save_core_payload_base "$bdir" || return 1;
    : > "$bdir/core-payload.sha256" || return 1;
    for item in "$bdir/xray.core.before" "$bdir"/core-*.before "$bdir"/unit-*.before;
    do
        if test -f "$item"; then
            rel=${item#"$bdir"/};
            ( cd "$bdir" && sha256sum -- "$rel" ) >> "$bdir/core-payload.sha256" || return 1;
        else
            if test -d "$item"; then
                while IFS= read -r file; do
                    rel=${file#"$bdir"/};
                    ( cd "$bdir" && sha256sum -- "$rel" ) >> "$bdir/core-payload.sha256" || return 1;
                done < <(find "$item" -type f -print 2> /dev/null | sort);
            fi;
        fi;
    done;
    chmod 0600 "$bdir/core-payload.sha256" 2> /dev/null || true
}
# EEX3-FUNCTION runtime_e118_135 _e118_self_test
_e118_self_test() {
    local rc=0 body apt_body;
    _e131_self_test_base || rc=1;
    echo;
    echo "V199e137 最终替换层回归测试：";
    body=$(declare -f _e118_install_self);
    [[ "$body" == *'ex199e136.sh'* && "$body" != *'ex199e128.sh'* ]] && echo "  [PASS] 版本化自安装路径" || { 
        echo "  [FAIL] 自安装路径";
        rc=1
    };
    body=$(declare -f fix_xray_systemd_limits);
    [[ "$body" == *'Nice=-20'* && "$body" == *'_e131_verify_nice_runtime'* ]] && echo "  [PASS] Nice=-20配置及回滚" || { 
        echo "  [FAIL] Nice事务";
        rc=1
    };
    body=$(declare -f _e131_verify_nice_runtime);
    [[ "$body" == *'ps -o ni='* && "$body" == *'MainPID'* ]] && echo "  [PASS] MainPID实际NI验证" || { 
        echo "  [FAIL] 仅检查systemd属性";
        rc=1
    };
    apt_body="$(declare -f do_install_xanmod_main_official)$(declare -f _e131_os_codename)";
    [[ "$apt_body" == *'archive.key'* && "$apt_body" == *'VERSION_CODENAME'* && "$apt_body" != *'https://dl.xanmod.org/gpg.key'* && "$apt_body" != *'releases main'* ]] && echo "  [PASS] XanMod当前官方APT流程" || { 
        echo "  [FAIL] XanMod APT旧流程残留";
        rc=1
    };
    body=$(declare -f _e131_xanmod_source_build);
    [[ "$body" == *'E131_XANMOD_EXPECTED_COMMIT'* && "$body" == *'bindeb-pkg'* && "$body" == *'kernelrelease'* && "$body" != *'make install'* && "$body" != *'ethtool -G'* ]] && echo "  [PASS] 源码commit锁定/打包/无网络夹带" || { 
        echo "  [FAIL] XanMod源码编译事务";
        rc=1
    };
    body=$(declare -f _update_matrix);
    [[ "$body" == *'.serverNames=[$sni]'* && "$body" == *'.target=$target'* ]] && echo "  [PASS] Reality单SNI/target" || { 
        echo "  [FAIL] Reality仍允许冲突SNI矩阵";
        rc=1
    };
    body=$(declare -f main_menu);
    [[ "$body" == *'declare -F do_xray_speed_diag_menu_e95'* && "$body" == *'_e131_dat_update_now'* ]] && echo "  [PASS] 菜单回退与DAT自修复" || { 
        echo "  [FAIL] 主菜单最终链";
        rc=1
    };
    body=$(declare -f hot_update_from_legacy);
    [[ "$body" == *'core_survival'* && "$body" == *'_e118_restore_core_payload'* && "$body" == *'_e121_install_ssh_guard'* && "$body" == *'_e116_apply_init_window_default30'* && "$body" == *'xray-dat-update.timer'* && "$body" == *'fix_xray_systemd_limits'* ]] && echo "  [PASS] 热更新生存事务与固定要求" || { 
        echo "  [FAIL] 热更新事务缺失";
        rc=1
    };
    echo "V199e137 回归结果：$(test "$rc" -eq 0 && echo PASS || echo FAIL)";
    return "$rc"
}
# EEX3-FUNCTION runtime_e118_135 _e118_signal_handler
_e118_signal_handler() {
    local sig="${1:-TERM}";
    trap - INT TERM HUP;
    if test "${E118_TX_ACTIVE:-0}" -eq 1 && test -n "${E118_TX_BACKUP:-}"; then
        warn "收到 $sig，正在回滚未完成的配置事务。";
        _e118_restore_state "$E118_TX_BACKUP" > /dev/null 2>&1 || true;
    fi;
    cleanup_temp_files;
    exit 130
}
# EEX3-FUNCTION runtime_e118_135 _e118_upsert_user_record
_e118_upsert_user_record() {
    local uuid="$1" sid="$2" sni="$3" ctime="${4:-$(date +'%Y-%m-%d %H:%M')}" t1 t2;
    t1=$(_e118_mktemp user-sni) || return 1;
    t2=$(_e118_mktemp user-time) || return 1;
    awk -F'|' -v u="$uuid" '$1!=u && $1!=""' "$USER_SNI_MAP" 2> /dev/null > "$t1" || true;
    printf '%s|%s|%s\n' "$uuid" "$sid" "$sni" >> "$t1";
    awk -F'|' -v u="$uuid" '$1!=u && $1!=""' "$USER_TIME_MAP" 2> /dev/null > "$t2" || true;
    printf '%s|%s\n' "$uuid" "$ctime" >> "$t2";
    install -m 0600 "$t1" "$USER_SNI_MAP" && install -m 0600 "$t2" "$USER_TIME_MAP"
}
# EEX3-FUNCTION runtime_e118_135 _e118_urlencode
_e118_urlencode() {
    jq -nr --arg v "${1:-}" '$v|@uri'
}
# EEX3-FUNCTION runtime_e118_135 _e118_user_sid
_e118_user_sid() {
    local uuid="$1" idx="$2" inbound_json="${3:-}" rec sid;
    rec=$(awk -F'|' -v u="$uuid" '$1==u{print; exit}' "$USER_SNI_MAP" 2> /dev/null || true);
    if test -n "$rec" && test "$(awk -F'|' '{print NF}' <<< "$rec")" -ge 3; then
        sid=$(cut -d'|' -f2 <<< "$rec");
    fi;
    if _e118_valid_sid "${sid:-}" && { 
        if test -n "$inbound_json"; then
            jq -e --arg s "$sid" '(.streamSettings.realitySettings.shortIds // []) | index($s)' <<< "$inbound_json" > /dev/null 2>&1;
        else
            jq -e --arg s "$sid" '.inbounds[]? | select(.protocol=="vless" and (.streamSettings.security//"")=="reality") | .streamSettings.realitySettings.shortIds | index($s)' "$CONFIG" > /dev/null 2>&1;
        fi
    }; then
        printf '%s' "$sid";
        return 0;
    fi;
    if test -n "$inbound_json"; then
        sid=$(jq -r --argjson i "$idx" '(.streamSettings.realitySettings.shortIds[$i] // .streamSettings.realitySettings.shortIds[0] // empty)' <<< "$inbound_json" 2> /dev/null | head -n1);
    else
        sid=$(jq -r --argjson i "$idx" '.inbounds[]? | select(.protocol=="vless" and (.streamSettings.security//"")=="reality") | (.streamSettings.realitySettings.shortIds[$i] // .streamSettings.realitySettings.shortIds[0] // empty)' "$CONFIG" 2> /dev/null | head -n1);
    fi;
    _e118_valid_sid "$sid" || { 
        printf '';
        return 0
    };
    printf '%s' "$sid"
}
# EEX3-FUNCTION runtime_e118_135 _e118_user_sni
_e118_user_sni() {
    local uuid="$1" inbound_json="${2:-}" rec sni;
    rec=$(awk -F'|' -v u="$uuid" '$1==u{print; exit}' "$USER_SNI_MAP" 2> /dev/null || true);
    if test -n "$rec"; then
        if test "$(awk -F'|' '{print NF}' <<< "$rec")" -ge 3; then
            sni=$(cut -d'|' -f3 <<< "$rec");
        else
            sni=$(cut -d'|' -f2 <<< "$rec");
        fi;
    fi;
    if test -n "${sni:-}" && valid_domain "$sni" && { 
        if test -n "$inbound_json"; then
            jq -e --arg s "$sni" '(.streamSettings.realitySettings.serverNames // []) | index($s)' <<< "$inbound_json" > /dev/null 2>&1;
        else
            jq -e --arg s "$sni" '.inbounds[]? | select(.protocol=="vless" and (.streamSettings.security//"")=="reality") | .streamSettings.realitySettings.serverNames | index($s)' "$CONFIG" > /dev/null 2>&1;
        fi
    }; then
        printf '%s' "$sni";
        return 0;
    fi;
    if test -n "$inbound_json"; then
        sni=$(jq -r '.streamSettings.realitySettings.serverNames[0] // empty' <<< "$inbound_json" 2> /dev/null | head -n1);
    else
        sni=$(jq -r '.inbounds[]? | select(.protocol=="vless" and (.streamSettings.security//"")=="reality") | .streamSettings.realitySettings.serverNames[0] // empty' "$CONFIG" 2> /dev/null | head -n1);
    fi;
    valid_domain "$sni" || { 
        printf '';
        return 0
    };
    printf '%s' "$sni"
}
