# EEX3-FUNCTION runtime_e118_135 _e118_write_ssh_port_guard
_e118_write_ssh_port_guard() {
    local ports;
    ports=$(_e116_detect_ssh_ports);
    test -n "$ports" || ports=22;
    cat > "$E118_SSH_GUARD_SCRIPT" <<'EOF_E118_SSH_GUARD'
#!/usr/bin/env bash
set -u
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
ports=""
if command -v sshd >/dev/null 2>&1; then ports="$ports $(sshd -T 2>/dev/null | awk '/^port /{print $2}')"; fi
ports="$ports $(grep -hEi '^[[:space:]]*Port[[:space:]]+[0-9]+' /etc/ssh/sshd_config /etc/ssh/sshd_config.d/*.conf 2>/dev/null | awk '{print $2}')"
ports="$ports $(ss -H -ltnp 2>/dev/null | awk '/sshd/ {p=$4; sub(/^.*:/,"",p); if(p~/^[0-9]+$/) print p}')"
ports=$(printf '%s\n' $ports | awk '$1~/^[0-9]+$/ && $1>=1 && $1<=65535{print $1}' | sort -nu)
test -n "$ports" || ports=22
if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -qi '^Status: active'; then
    for p in $ports; do ufw allow "$p/tcp" >/dev/null 2>&1 || true; done
fi
if command -v firewall-cmd >/dev/null 2>&1 && systemctl is-active --quiet firewalld; then
    changed=0
    for p in $ports; do firewall-cmd --permanent --query-port="${p}/tcp" >/dev/null 2>&1 || { firewall-cmd --permanent --add-port="${p}/tcp" >/dev/null 2>&1 && changed=1; }; done
    test "$changed" -eq 0 || firewall-cmd --reload >/dev/null 2>&1 || true
fi
# 不插入裸 iptables INPUT ACCEPT；否则手动巡检可能把 ACCEPT 放到 fail2ban 链之前。
exit 0
EOF_E118_SSH_GUARD

    chmod 0755 "$E118_SSH_GUARD_SCRIPT" || return 1;
    cat > "$E118_SSH_GUARD_SERVICE" <<EOF_E118_SSH_SERVICE
[Unit]
Description=Xray V199e137 SSH port firewall-manager guard
After=network-online.target ssh.service sshd.service ufw.service firewalld.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$E118_SSH_GUARD_SCRIPT
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF_E118_SSH_SERVICE

    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl enable --now xray-ssh-port-guard-e118.service > /dev/null 2>&1 || return 1;
    "$E118_SSH_GUARD_SCRIPT"
}
# EEX3-FUNCTION runtime_e118_135 _e118_xray_test_config
_e118_xray_test_config() {
    local f="${1:-}" require_core="${2:-1}" out="" logf="" test_file="" shadow="";
    test -n "$f" && test -s "$f" || { 
        error "待测试配置为空或不存在：${f:-未指定}";
        return 1
    };
    jq empty "$f" > /dev/null 2>&1 || { 
        error "待测试配置不是合法 JSON：$f";
        return 1
    };
    test_file="$f";
    case "$test_file" in 
        *.json)

        ;;
        *)
            shadow=$(_e118_mktemp xray-config-test.json) || return 1;
            install -m 0600 "$f" "$shadow" || return 1;
            test_file="$shadow"
        ;;
    esac;
    if test ! -x "$XRAY_BIN"; then
        if test "$require_core" = "1"; then
            error "缺少可执行 Xray Core，不能提交配置。";
            return 1;
        fi;
        warn "未发现 Xray Core，仅完成 JSON 检查。";
        return 0;
    fi;
    logf=$(_e118_mktemp xray-test.log) || return 1;
    if out=$("$XRAY_BIN" run -test -config "$test_file" 2>&1); then
        printf '%s\n' "$out" > "$logf";
        return 0;
    fi;
    printf '%s\n' "===== xray run -test -config =====" "$out" > "$logf";
    if out=$("$XRAY_BIN" -test -config "$test_file" 2>&1); then
        printf '%s\n' "$out" >> "$logf";
        return 0;
    fi;
    printf '%s\n' "===== xray -test -config =====" "$out" >> "$logf";
    error "Xray 配置测试失败，拒绝提交。";
    if grep -q 'Failed to get format' "$logf" 2> /dev/null; then
        warn "Xray 无法识别配置格式；测试文件必须以 .json 结尾。当前测试文件：$test_file";
    fi;
    sed 's/^/    /' "$logf" 2> /dev/null | tail -n 160 || true;
    return 1
}
