# EEX3-FUNCTION runtime_e118_135 _e121_atomic_install
_e121_atomic_install() {
    local source="$1" target="$2" mode="${3:-0644}" stage;
    mkdir -p "$(dirname "$target")" || return 1;
    stage="${target}.e121-new.$$";
    rm -f -- "$stage" 2> /dev/null || true;
    install -m "$mode" -- "$source" "$stage" || { 
        rm -f -- "$stage";
        return 1
    };
    mv -f -- "$stage" "$target" || { 
        rm -f -- "$stage";
        return 1
    }
}
# EEX3-FUNCTION runtime_e118_135 _e121_backup_fail2ban_state
_e121_backup_fail2ban_state() {
    local stamp dir path index=0 key;
    stamp=$(date +%Y%m%d_%H%M%S);
    dir="$E118_BACKUP_DIR/fail2ban_before_e121_${stamp}_$$";
    mkdir -p "$dir" || return 1;
    while IFS= read -r path; do
        index=$((index+1));
        printf -v key '%03d' "$index";
        printf '%s\n' "$path" > "$dir/$key.path";
        if test -e "$path" || test -L "$path"; then
            cp -a -- "$path" "$dir/$key.data" || return 1;
        else
            : > "$dir/$key.absent";
        fi;
    done < <(_e121_managed_fail2ban_paths);
    { 
        systemctl is-active --quiet rsyslog 2> /dev/null && echo 'rsyslog_active=1' || echo 'rsyslog_active=0';
        systemctl is-enabled --quiet rsyslog 2> /dev/null && echo 'rsyslog_enabled=1' || echo 'rsyslog_enabled=0'
    } > "$dir/services.env";
    printf '%s\n' "$dir"
}
