# EEX3-FUNCTION runtime_e118_135 _e121_do_uninstall
_e121_do_uninstall() {
    local tool p ports managed=0;
    ports=$(_e121_detect_ssh_ports);
    if command -v ufw > /dev/null 2>&1 && ufw status 2> /dev/null | grep -qi '^Status: active'; then
        for p in $ports;
        do
            ufw allow "$p/tcp" > /dev/null 2>&1 || true;
        done;
        managed=1;
    else
        if command -v firewall-cmd > /dev/null 2>&1 && systemctl is-active --quiet firewalld; then
            for p in $ports;
            do
                firewall-cmd --permanent --add-port="${p}/tcp" > /dev/null 2>&1 || true;
            done;
            firewall-cmd --reload > /dev/null 2>&1 || true;
            managed=1;
        fi;
    fi;
    if test "$managed" -eq 0 && command -v iptables > /dev/null 2>&1; then
        for tool in iptables ip6tables;
        do
            command -v "$tool" > /dev/null 2>&1 || continue;
            for p in $ports;
            do
                "$tool" -C INPUT -p tcp --dport "$p" -j ACCEPT > /dev/null 2>&1 || "$tool" -I INPUT 1 -p tcp --dport "$p" -j ACCEPT > /dev/null 2>&1 || true;
            done;
        done;
        warn "裸 iptables 环境：卸载前已保留 SSH 端口放行；卸载后请自行部署独立 SSH 防护。";
    fi;
    systemctl disable --now xray-ssh-port-guard-e121.timer xray-ssh-port-guard-e121.service xray-log-retention-e121.timer xray-log-retention-e121.service xray-ssh-port-guard-e120.timer xray-ssh-port-guard-e120.service xray-log-retention-e120.timer xray-log-retention-e120.service > /dev/null 2>&1 || true;
    for tool in iptables ip6tables;
    do
        command -v "$tool" > /dev/null 2>&1 || continue;
        while "$tool" -C INPUT -j "$E121_SSH_GUARD_CHAIN" > /dev/null 2>&1; do
            "$tool" -D INPUT -j "$E121_SSH_GUARD_CHAIN" > /dev/null 2>&1 || break;
        done;
        "$tool" -F "$E121_SSH_GUARD_CHAIN" > /dev/null 2>&1 || true;
        "$tool" -X "$E121_SSH_GUARD_CHAIN" > /dev/null 2>&1 || true;
        while "$tool" -C INPUT -j XRAY_SSH_E120 > /dev/null 2>&1; do
            "$tool" -D INPUT -j XRAY_SSH_E120 > /dev/null 2>&1 || break;
        done;
        "$tool" -F XRAY_SSH_E120 > /dev/null 2>&1 || true;
        "$tool" -X XRAY_SSH_E120 > /dev/null 2>&1 || true;
    done;
    rm -f -- "$E121_SSH_GUARD_SCRIPT" "$E121_SSH_GUARD_SERVICE" "$E121_SSH_GUARD_TIMER" "$E121_LOG_RETENTION_SCRIPT" "$E121_LOG_RETENTION_SERVICE" "$E121_LOG_RETENTION_TIMER" "$E121_JOURNAL_CONF" "$E121_LOGROTATE_CONF" /usr/local/bin/xray-ssh-port-guard-e120.sh /etc/systemd/system/xray-ssh-port-guard-e120.service /etc/systemd/system/xray-ssh-port-guard-e120.timer /usr/local/bin/xray-log-retention-e120.sh /etc/systemd/system/xray-log-retention-e120.service /etc/systemd/system/xray-log-retention-e120.timer /etc/systemd/journald.conf.d/zz-xray-retention-e120.conf /etc/logrotate.d/xray-e120 /var/lib/logrotate/xray-e120.status /var/lib/logrotate/xray-e121.status 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || true;
    systemctl restart systemd-journald > /dev/null 2>&1 || true;
    _e118_impl_uninstall "$@"
}
