# EEX3-FUNCTION runtime_e118_135 _e121_find_systemd_python
_e121_find_systemd_python() {
    local name py seen="|" runtime_found=0 tool line;
    local -a words=();
    for name in fail2ban-python3 fail2ban-python;
    do
        py=$(command -v "$name" 2> /dev/null || true);
        test -n "$py" || continue;
        runtime_found=1;
        case "$seen" in 
            *"|$py|"*)
                continue
            ;;
        esac;
        seen="${seen}${py}|";
        if "$py" -c 'from systemd import journal; assert journal.Reader' > /dev/null 2>&1; then
            printf '%s\n' "$py";
            return 0;
        fi;
    done;
    for tool in fail2ban-server fail2ban-client;
    do
        tool=$(command -v "$tool" 2> /dev/null || true);
        test -r "$tool" || continue;
        IFS= read -r line < "$tool" || true;
        case "$line" in 
            '#!'*python*)

            ;;
            *)
                continue
            ;;
        esac;
        words=();
        read -r -a words <<< "${line#\#!}";
        test "${#words[@]}" -gt 0 || continue;
        if test "${words[0]##*/}" = env; then
            test "${#words[@]}" -gt 1 || continue;
            py=$(command -v "${words[1]}" 2> /dev/null || true);
        else
            py=${words[0]};
        fi;
        test -x "$py" || continue;
        runtime_found=1;
        case "$seen" in 
            *"|$py|"*)
                continue
            ;;
        esac;
        seen="${seen}${py}|";
        if "$py" -c 'from systemd import journal; assert journal.Reader' > /dev/null 2>&1; then
            printf '%s\n' "$py";
            return 0;
        fi;
    done;
    if test "$runtime_found" -eq 0; then
        for name in /usr/bin/python3 python3;
        do
            py=$(command -v "$name" 2> /dev/null || true);
            test -n "$py" || continue;
            case "$seen" in 
                *"|$py|"*)
                    continue
                ;;
            esac;
            seen="${seen}${py}|";
            if "$py" -c 'from systemd import journal; assert journal.Reader' > /dev/null 2>&1; then
                printf '%s\n' "$py";
                return 0;
            fi;
        done;
    fi;
    return 1
}
# EEX3-FUNCTION runtime_e118_135 _e121_install_fail2ban_guard
_e121_install_fail2ban_guard() {
    local backend old_table;
    backend=$(_e152_firewall_backend 2> /dev/null || echo none);
    if ! command -v fail2ban-client > /dev/null 2>&1; then
        info '未检测到fail2ban，正在执行可诊断安装。';
        _e141_install_fail2ban_package || { 
            error "fail2ban安装失败，原始日志：$E141_F2B_INSTALL_LOG";
            return 1
        };
    fi;
    if test "$backend" = nft; then
        systemctl stop fail2ban.service > /dev/null 2>&1 || true;
        systemctl is-active --quiet fail2ban.service 2> /dev/null && { 
            error '无法停止Fail2ban以清理活动E165表。';
            return 1
        };
        nft delete table inet "$E165_NFT_F2B_TABLE" > /dev/null 2>&1 || true;
    fi;
    _e141_fail2ban_guard_original || return 1;
    if test "$backend" = nft; then
        _e152_fail2ban_passive_verify || { 
            error 'E170安装后Fail2ban/nftables被动读回失败。';
            return 1
        };
        for old_table in "$E165_LEGACY_E163_NFT_TABLE" "$E159_NFT_F2B_TABLE" "$E152_NFT_F2B_TABLE";
        do
            nft delete table inet "$old_table" > /dev/null 2>&1 || true;
            if nft list table inet "$old_table" > /dev/null 2>&1; then
                error "旧Fail2ban事务表$old_table仍存在。";
                return 1;
            fi;
        done;
        rm -f -- "$E165_LEGACY_E163_HELPER" "$E165_LEGACY_E163_ACTION_CONF" "$E165_LEGACY_E163_FILTER" "$E165_LEGACY_E163_DISABLE" "$E159_F2B_ACTION_CONF" "$E159_F2B_FILTER" "$E152_F2B_FILTER" 2> /dev/null || true;
        _e165_helper_check || return 1;
    fi
}
# EEX3-FUNCTION runtime_e118_135 _e121_install_log_retention
_e121_install_log_retention() {
    local tx before_count=${#E135_NEW_PACKAGES[@]} rc=0 restore_rc=0;
    tx=$(_e204_new_tx log-retention) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_log_retention_base "$@" || rc=$?;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    _e172_remove_packages_since "$before_count" || restore_rc=1;
    _e140_system_restore "$tx/system" || restore_rc=1;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical log-retention "$tx/system" 'rollback failed' || true;
        error "日志保留事务回滚未完整通过；快照：$tx/system";
    fi;
    _e204_tx_close "$tx" || true;
    return 1
}
