# EEX3-FUNCTION runtime_e118_135 _e121_restore_fail2ban_state
_e121_restore_fail2ban_state() {
    local dir="$1" marker key path rsyslog_active=0 rsyslog_enabled=0;
    test -d "$dir" || return 1;
    for marker in "$dir"/*.path;
    do
        test -f "$marker" || continue;
        key=${marker##*/};
        key=${key%.path};
        path=$(cat "$marker");
        rm -f -- "$path" 2> /dev/null || true;
        if test -e "$dir/$key.data" || test -L "$dir/$key.data"; then
            mkdir -p "$(dirname "$path")" || return 1;
            cp -a -- "$dir/$key.data" "$path" || return 1;
        fi;
    done;
    if test -f "$dir/services.env"; then
        rsyslog_active=$(sed -n 's/^rsyslog_active=//p' "$dir/services.env" | head -n1);
        rsyslog_enabled=$(sed -n 's/^rsyslog_enabled=//p' "$dir/services.env" | head -n1);
    fi;
    if test "$rsyslog_enabled" = 1; then
        systemctl enable rsyslog > /dev/null 2>&1 || true;
    else
        systemctl disable rsyslog > /dev/null 2>&1 || true;
    fi;
    if test "$rsyslog_active" = 1; then
        systemctl restart rsyslog > /dev/null 2>&1 || true;
    else
        systemctl stop rsyslog > /dev/null 2>&1 || true;
    fi
}
