        _e118_atomic_install "$tmp_client" "${E77_VLESSENC_CLIENT_FILE:-$CONFIG_DIR/vlessenc.client.txt}" 0600 || return 1;
        _e118_atomic_install "$tmp_server" "${E77_VLESSENC_SERVER_FILE:-$CONFIG_DIR/vlessenc.server.txt}" 0600 || return 1;
        _e118_atomic_install "$tmp_mode" "${E79_VLESSENC_MODE_FILE:-$CONFIG_DIR/vlessenc.mode.txt}" 0600 || return 1;
