        else
            rm -f "${E79_VLESSENC_XHTTP_PATH_FILE:-$CONFIG_DIR/vlessenc.xhttp.path.txt}";
        fi;
    else
        rm -f "${E77_VLESSENC_CLIENT_FILE:-$CONFIG_DIR/vlessenc.client.txt}" "${E77_VLESSENC_SERVER_FILE:-$CONFIG_DIR/vlessenc.server.txt}" "${E79_VLESSENC_MODE_FILE:-$CONFIG_DIR/vlessenc.mode.txt}" "${E79_VLESSENC_XHTTP_PATH_FILE:-$CONFIG_DIR/vlessenc.xhttp.path.txt}" 2> /dev/null || true;
