EOF_E118_META

    _e118_atomic_install "$tmp_meta" "${E77_NODE_META_FILE:-$CONFIG_DIR/node.meta}" 0600 || return 1;
    tmp_version=$(_e118_mktemp script-version.txt) || return 1;
    printf '%s\n' "$SCRIPT_VERSION" > "$tmp_version" || return 1;
