# EEX3-FUNCTION runtime_e118_135 _e127_rollback_config_or_emergency
_e127_rollback_config_or_emergency() {
    local bdir="$1" was_active=0 was_enabled=0 marker failed=0;
    _e118_restore_state "$bdir" && return 0;
    error "完整状态回滚失败，尝试最小化恢复旧config.json。";
    if _e127_verify_state_snapshot "$bdir"; then
        was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2> /dev/null | head -n1);
        was_active=${was_active:-0};
        was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$bdir/meta.env" 2> /dev/null | head -n1);
        was_enabled=${was_enabled:-0};
        if grep -qx config.json "$bdir/files.manifest" 2> /dev/null; then
            _e118_atomic_install "$bdir/config.json" "$CONFIG" 0600 || failed=1;
        else
            rm -f -- "$CONFIG" 2> /dev/null || failed=1;
        fi;
        test "$failed" -ne 0 || fix_permissions || failed=1;
        if test "$failed" -eq 0; then
            if test "$was_enabled" = 1; then
                systemctl enable xray.service > /dev/null 2>&1 || failed=1;
            else
                systemctl disable xray.service > /dev/null 2>&1 || failed=1;
            fi;
        fi;
        if test "$failed" -eq 0 && test "$was_active" = 1; then
            systemctl reset-failed xray.service > /dev/null 2>&1 || true;
            systemctl restart xray.service > /dev/null 2>&1 && _e127_verify_xray_runtime "$CONFIG" 12 && { 
                E118_TX_ACTIVE=0;
                E118_TX_BACKUP="";
                E118_TX_WAS_ACTIVE=0;
                return 0
            };
        else
            if test "$failed" -eq 0 && test "$was_active" = 0; then
                systemctl stop xray.service > /dev/null 2>&1 || true;
                if ! systemctl is-active --quiet xray.service 2> /dev/null; then
                    E118_TX_ACTIVE=0;
                    E118_TX_BACKUP="";
                    E118_TX_WAS_ACTIVE=0;
                    return 0;
                fi;
            fi;
        fi;
    fi;
    marker="$E118_DIR/CRITICAL_RECOVERY_REQUIRED.env";
    { 
        echo "time=$(date '+%F %T')";
        echo "backup=$bdir";
        echo "config=$CONFIG";
        echo "reason=e159-xray-rollback-incomplete"
    } > "${marker}.new.$$" 2> /dev/null && chmod 0600 "${marker}.new.$$" 2> /dev/null && mv -f -- "${marker}.new.$$" "$marker" 2> /dev/null || true;
    E118_TX_ACTIVE=0;
    E118_TX_BACKUP="";
    E118_TX_WAS_ACTIVE=0;
    return 1
}
# EEX3-FUNCTION runtime_e118_135 _e127_save_core_payload_base
_e127_save_core_payload_base() {
    local bdir="$1" name path;
    test -d "$bdir" || return 1;
    if test -x "$XRAY_BIN"; then
        install -m 0755 "$XRAY_BIN" "$bdir/xray.core.before" || return 1;
        sha256sum "$bdir/xray.core.before" > "$bdir/xray.core.before.sha256" 2> /dev/null || true;
    else
        : > "$bdir/xray.core.was-absent";
    fi;
    for name in geoip.dat geosite.dat;
    do
        if test -f "$DAT_DIR/$name"; then
            install -m 0644 "$DAT_DIR/$name" "$bdir/core-$name.before" || return 1;
        else
            : > "$bdir/core-$name.was-absent";
        fi;
    done;
    for name in xray.service xray@.service;
    do
        path="/etc/systemd/system/$name";
        if test -f "$path"; then
            install -m 0644 "$path" "$bdir/unit-$name.before" || return 1;
        else
            : > "$bdir/unit-$name.was-absent";
        fi;
    done;
    for name in xray.service.d xray@.service.d;
    do
        path="/etc/systemd/system/$name";
        if test -d "$path"; then
            cp -a -- "$path" "$bdir/unit-$name.before" || return 1;
        else
            : > "$bdir/unit-$name.was-absent";
        fi;
    done
}
# EEX3-FUNCTION runtime_e118_135 _e127_self_test_base
_e127_self_test_base() {
    local rc=0 count dup body remove_body hot_body;
    _e126_self_test_base || rc=1;
    echo;
    echo "V199e137 参数集合回归测试：";
    count=$(_e126_accel_metadata | wc -l | tr -d ' ');
    test "$count" -eq 31 && echo "  [PASS] 31项参数元数据" || { 
