    test -z "$dup" && echo "  [PASS] 参数键唯一" || { 
        echo "  [FAIL] 参数键重复=$dup";
        rc=1
    };
    body=$(declare -f _e126_write_boot_assets);
    if [[ "$body" == *'After=systemd-sysctl.service'* && "$body" == *'Before=xray.service'* && "$body" == *'restore_baseline'* && "$body" == *'write_state failed || exit 1'* && "$body" == *'rollback=ok'* ]]; then
        echo "  [PASS] 开机逐项读回、失败整组恢复与状态写入校验";
    else
        echo "  [FAIL] 开机失败回退实现缺失";
        rc=1;
    fi;
    body=$(declare -f _e126_apply_candidate);
    if [[ "$body" == *'_e126_baseline_ensure_candidate'* && "$body" == *'_e126_restore_removed_keys'* && "$body" == *'runtime.before'* && "$body" == *'enable --now'* && "$body" == *'baseline'* ]]; then
        echo "  [PASS] 原始基线、取消单项恢复与事务回滚";
    else
        echo "  [FAIL] 参数基线/取消恢复缺失";
        rc=1;
    fi;
    remove_body=$(declare -f _e126_remove_layer);
    if [[ "$remove_body" == *'_e126_restore_all_baselines'* && "$remove_body" == *'sysctl --system'* && "$remove_body" == *'_e126_rollback'* ]]; then
        echo "  [PASS] 移除层先恢复基线且失败撤销";
    else
        echo "  [FAIL] 移除层可能残留运行值";
        rc=1;
    fi;
    hot_body="$(declare -f hot_update_from_legacy 2> /dev/null || true)$(declare -f _e127_hot_update_base 2> /dev/null || true)";
    if [[ "$hot_body" == *'E126_LEGACY_ACCEL_CONF'* && "$hot_body" == *'_e126_seed_baseline_from_legacy'* && "$hot_body" == *'_e126_cleanup_legacy_accel'* ]]; then
        echo "  [PASS] E125 持久化层兼容迁移";
    else
        echo "  [FAIL] E125 迁移路径缺失";
        rc=1;
    fi;
    declare -f main_menu | grep -q '21) 跨境代理网络参数集合' && echo "  [PASS] 主菜单21接入" || { 
        echo "  [FAIL] 主菜单21未接入";
        rc=1
    };
    echo "V199e137 参数集合回归结果：$(test "$rc" -eq 0 && echo PASS || echo FAIL)";
    return "$rc"
}
# EEX3-FUNCTION runtime_e118_135 _e127_socket_ready
_e127_socket_ready() {
    local proto="$1" port="$2" pid="$3" line out;
    [[ "$port" =~ ^[0-9]+$ ]] && [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1;
    case "$proto" in 
        tcp)
            out=$(ss -H -ltnp 2> /dev/null || true)
        ;;
        udp)
            out=$(ss -H -lunp 2> /dev/null || true)
        ;;
        *)
            return 1
        ;;
    esac;
    while IFS= read -r line; do
        test -n "$line" || continue;
        awk -v p=":$port" '$4 ~ p"$"{ok=1} END{exit !ok}' <<< "$line" || continue;
        if [[ "$line" == *"users:"* ]]; then
            [[ "$line" == *"pid=$pid,"* ]] && return 0;
        fi;
    done <<< "$out";
    _e142_pid_owns_socket_port "$proto" "$port" "$pid"
}
# EEX3-FUNCTION runtime_e118_135 _e127_verify_state_snapshot
_e127_verify_state_snapshot() {
    local bdir="$1";
    _e159_verify_state_snapshot_base "$bdir" || return 1;
    if grep -qx 'version=199e159' "$bdir/meta.env" 2> /dev/null; then
        test -s "$bdir/snapshot-seal.sha256" || { 
            error "E159 Xray快照缺少元数据联合封印：$bdir";
            return 1
        };
    fi;
    if test -e "$bdir/snapshot-seal.sha256"; then
        test -s "$bdir/snapshot-seal.sha256" && ( cd "$bdir" && sha256sum -c snapshot-seal.sha256 > /dev/null 2>&1 ) || { 
            error "Xray快照元数据/清单联合封印失败：$bdir";
            return 1
        };
    fi
}
# EEX3-FUNCTION runtime_e118_135 _e127_verify_xray_runtime
_e127_verify_xray_runtime() {
    local cfg="${1:-$CONFIG}" timeout="${2:-12}" i pid stable=0 req proto port network failed;
    test -s "$cfg" || { 
        error "Xray 运行态复检缺少配置：$cfg";
        return 1
    };
    _e118_xray_test_config "$cfg" 1 || return 1;
    [[ "$timeout" =~ ^[0-9]+$ ]] || timeout=12;
    test "$timeout" -ge 3 || timeout=3;
    for ((i=1; i<=timeout; i++))
    do
        failed=0;
        systemctl is-active --quiet xray.service 2> /dev/null || failed=1;
        pid=$(systemctl show xray.service -p MainPID --value 2> /dev/null || true);
        [[ "$pid" =~ ^[1-9][0-9]*$ ]] && kill -0 "$pid" 2> /dev/null || failed=1;
        if test "$failed" -eq 0; then
            while IFS='	' read -r proto port network; do
                test -n "$proto" && test -n "$port" || continue;
                case "$proto" in 
                    vless)
                        _e127_socket_ready tcp "$port" "$pid" || { 
                            failed=1;
                            break
                        }
                    ;;
                    shadowsocks)
                        case ",${network:-tcp,udp}," in 
                            *,tcp,*)
                                _e127_socket_ready tcp "$port" "$pid" || { 
                                    failed=1;
                                    break
                                }
                            ;;
                        esac;
                        case ",${network:-tcp,udp}," in 
                            *,udp,*)
                                _e127_socket_ready udp "$port" "$pid" || { 
                                    failed=1;
                                    break
                                }
                            ;;
                        esac
                    ;;
                esac;
            done < <(jq -r '.inbounds[]? | select(.protocol=="vless" or .protocol=="shadowsocks") | [.protocol,(.port|tostring),(.settings.network//"tcp,udp")] | @tsv' "$cfg" 2> /dev/null);
        fi;
        if test "$failed" -eq 0; then
            stable=$((stable+1));
            test "$stable" -ge 3 && return 0;
        else
            stable=0;
        fi;
        sleep 1;
    done;
    error "Xray 未通过稳定运行探针：service/MainPID/配置端口未连续稳定3秒。";
    journalctl -u xray.service --no-pager -n 60 2> /dev/null | sed 's/^/    /' || true;
    return 1
}
# EEX3-FUNCTION runtime_e118_135 _e131_atomic_text_file
_e131_atomic_text_file() {
    local target="$1" mode="$2" tmp;
    mkdir -p "$(dirname "$target")" || return 1;
    tmp="$(dirname "$target")/.${target##*/}.e131.$$";
    cat > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    chmod "$mode" "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -f -- "$tmp" "$target" || { 
        rm -f -- "$tmp";
        return 1
    }
}
# EEX3-FUNCTION runtime_e118_135 _e131_choose_xanmod_tag
_e131_choose_xanmod_tag() {
    local requested="${1:-}" tag_json encoded expected;
    if test -n "$requested"; then
        LATEST_TAG="$requested";
    else
        local -a tags=();
        mapfile -t tags < <(_e131_xanmod_tags | head -n 30);
        if test "${#tags[@]}" -eq 0; then
            warn "GitLab Tag API 不可用，不使用过期硬编码版本。";
            read -rp "手动输入完整 XanMod Tag: " LATEST_TAG || true;
        else
            local i=1;
            echo "最近 XanMod Tags：";
            for requested in "${tags[@]}";
            do
                printf '  %d) %s\n' "$i" "$requested";
                i=$((i+1));
            done;
            echo "  0) 手动输入";
            local sel="";
            read -rp "选择 Tag (默认 1): " sel || true;
            sel=${sel:-1};
            if test "$sel" = 0; then
                read -rp "完整 Tag: " LATEST_TAG || true;
            else
                if [[ "$sel" =~ ^[0-9]+$ ]] && test "$sel" -ge 1 && test "$sel" -le "${#tags[@]}"; then
                    LATEST_TAG="${tags[$((sel-1))]}";
                else
                    error "Tag 序号无效。";
                    return 1;
                fi;
            fi;
        fi;
    fi;
    [[ "$LATEST_TAG" =~ ^[0-9]+\.[0-9]+\.[0-9]+(-rt[^-]*)?-xanmod[0-9]+$ ]] || { 
        error "Tag 格式非法：$LATEST_TAG";
        return 1
    };
    encoded=$(jq -rn --arg v "$LATEST_TAG" '$v|@uri');
    tag_json=$(curl --proto '=https' --tlsv1.2 -fsSL --connect-timeout 10 --max-time 60 "https://gitlab.com/api/v4/projects/xanmod%2Flinux/repository/tags/$encoded") || return 1;
    expected=$(printf '%s' "$tag_json" | jq -r '.commit.id // empty');
    [[ "$expected" =~ ^[0-9a-f]{40}$ ]] || { 
        error "无法取得 Tag 对应 commit SHA。";
        return 1
    };
    E131_XANMOD_EXPECTED_COMMIT="$expected";
    return 0
}
