# EEX3-FUNCTION runtime_e118_135 _e131_hot_update_base
_e131_hot_update_base() {
    local protect="" was_active=0 rc=0;
    if test -s "$CONFIG" && test -x "$XRAY_BIN"; then
        protect=$(_e116_backup_state "before_hot_update_e127_core_survival") || { 
            error "Core 生存快照失败，拒绝热更新。";
            return 1
        };
        _e118_save_core_payload "$protect" || { 
            error "Core/DAT 生存载荷备份失败，拒绝热更新。";
            return 1
        };
        was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" | head -n1);
        was_active=${was_active:-0};
    fi;
    if _e127_hot_update_base "$@"; then
        rc=0;
    else
        rc=$?;
    fi;
    if test -n "$protect" && test "$was_active" = 1; then
        if ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "热更新后 Xray 核心探针失败，启动生存回滚。";
            if ! _e118_restore_core_payload "$protect"; then
                _e118_restore_state "$protect" > /dev/null 2>&1 || true;
                _e118_restore_core_payload "$protect" || { 
                    error "严重：Core 生存回滚失败：$protect";
                    return 1
                };
            fi;
            _e118_restore_state "$protect" || { 
                error "严重：配置生存回滚失败：$protect";
                return 1
            };
            return 1;
        fi;
    else
        if test -n "$protect" && test "$was_active" = 0; then
            systemctl stop xray.service > /dev/null 2>&1 || true;
        fi;
    fi;
    test "$rc" -ne 0 || _e127_prune_core_payload_backups;
    return "$rc"
}
# EEX3-FUNCTION runtime_e118_135 _e131_hot_update_rollback
_e131_hot_update_rollback() {
    local protect="${1:-}";
    test -n "$protect" || return 1;
    _e118_restore_core_payload "$protect" > /dev/null 2>&1 || true;
    _e118_restore_state "$protect" > /dev/null 2>&1 || true;
