}
# EEX3-FUNCTION runtime_e118_135 _e131_install_kernel_build_deps
_e131_install_kernel_build_deps() {
    export DEBIAN_FRONTEND=noninteractive;
    local os_id;
    os_id=$(detect_os);
    [[ "$os_id" =~ ^(debian|ubuntu)$ ]] || { 
        error "E131 bindeb-pkg 路线仅支持 Debian/Ubuntu。";
        return 1
    };
    apt-get update || return 1;
    apt-get install -y --no-install-recommends git ca-certificates curl jq build-essential bc bison flex libssl-dev libelf-dev libncurses-dev dwarves pahole fakeroot rsync cpio kmod zstd lz4 xz-utils dpkg-dev python3 perl pkg-config || return 1;
    local c;
    for c in git make gcc bison flex dpkg-deb fakeroot;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "依赖命令缺失：$c";
            return 1
        };
    done
}
# EEX3-FUNCTION runtime_e118_135 _e131_kernel_build_precheck
_e131_kernel_build_precheck() {
    local root_free boot_free mem_avail;
    root_free=$(df -Pm /var/tmp 2> /dev/null | awk 'NR==2{print int($4)}' || echo 0);
    boot_free=$(df -Pm /boot 2> /dev/null | awk 'NR==2{print int($4)}' || echo 0);
    mem_avail=$(awk '/MemAvailable:/{print int($2/1024)}' /proc/meminfo 2> /dev/null || echo 0);
    echo "  /var/tmp 可用=${root_free}MB /boot 可用=${boot_free}MB MemAvailable=${mem_avail}MB";
    test "$root_free" -ge 15000 || { 
        error "完整打包编译要求 /var/tmp 至少 15GB 可用，推荐 25GB+。";
        return 1
    };
    test "$boot_free" -ge 350 || { 
        error "/boot 可用空间不足 350MB。";
        return 1
    };
    test "$mem_avail" -ge 700 || { 
        error "MemAvailable 低于 700MB，拒绝编译。";
        return 1
    };
    test -w /boot || { 
        error "/boot 不可写。";
        return 1
    }
}
# EEX3-FUNCTION runtime_e118_135 _e131_kernel_threads
_e131_kernel_threads() {
    local mem cores t;
    mem=$(awk '/MemAvailable:/{print int($2/1024)}' /proc/meminfo 2> /dev/null || echo 1024);
    cores=$(nproc 2> /dev/null || echo 1);
    t=$((mem/1800));
    test "$t" -ge 1 || t=1;
    test "$t" -le "$cores" || t="$cores";
    printf '%s' "$t"
}
# EEX3-FUNCTION runtime_e118_135 _e131_os_codename
