# EEX3-FUNCTION runtime_e118_135 _e131_user_maps_replace_uuid
_e131_user_maps_replace_uuid() {
    local old="$1" new="$2" sid="$3" sni="$4" ctime="$5" t1 t2;
    t1=$(_e118_mktemp user-sni) || return 1;
    t2=$(_e118_mktemp user-time) || return 1;
    awk -F'|' -v u="$old" '$1!=u && $1!=""' "$USER_SNI_MAP" 2> /dev/null > "$t1" || true;
    printf '%s|%s|%s\n' "$new" "$sid" "$sni" >> "$t1";
    awk -F'|' -v u="$old" '$1!=u && $1!=""' "$USER_TIME_MAP" 2> /dev/null > "$t2" || true;
    printf '%s|%s\n' "$new" "$ctime" >> "$t2";
    install -m 0600 "$t1" "$USER_SNI_MAP" && install -m 0600 "$t2" "$USER_TIME_MAP"
}
# EEX3-FUNCTION runtime_e118_135 _e131_verify_nice_runtime
_e131_verify_nice_runtime() {
    local unit_nice pid proc_nice;
    unit_nice=$(systemctl show xray.service -p Nice --value 2> /dev/null || true);
    test "$unit_nice" = "-20" || { 
        error "systemd 解析后的 Xray Nice=${unit_nice:-读取失败}，要求 -20。";
        return 1
    };
    if systemctl is-active --quiet xray.service 2> /dev/null; then
        pid=$(_e131_xray_main_pid);
        [[ "$pid" =~ ^[0-9]+$ ]] && test "$pid" -gt 1 2> /dev/null || { 
            error "Xray active 但 MainPID 无效。";
            return 1
        };
        proc_nice=$(ps -o ni= -p "$pid" 2> /dev/null | tr -d '[:space:]' || true);
        test "$proc_nice" = "-20" || { 
            error "Xray MainPID=$pid 实际 NI=${proc_nice:-读取失败}，要求 -20。";
            return 1
        };
    fi;
    return 0
}
# EEX3-FUNCTION runtime_e118_135 _e131_xanmod_pkg_name
_e131_xanmod_pkg_name() {
    local branch="$1" level="$2";
    test "$level" -le 3 || level=3;
    case "$branch" in 
        main)
            test "$level" -ge 2 || return 1;
            printf 'linux-xanmod-x64v%s' "$level"
        ;;
        lts)
            printf 'linux-xanmod-lts-x64v%s' "$level"
        ;;
        rt)
            test "$level" -ge 2 || return 1;
            printf 'linux-xanmod-rt-x64v%s' "$level"
        ;;
        *)
            return 1
        ;;
    esac
}
