# EEX3-FUNCTION runtime_e118_135 _e135_bundle_commit
_e135_bundle_commit() {
    local cfg="$1" smap="$2" tmap="$3" pkey="$4" reason="${5:-user-change}";
    local bdir was_active=0 failed=0 value="${EEX3_BUFFER_INTENT:-}" normalized;
    test -n "$value" || value=$(_e266_buffer_managed_intent_readonly 2> /dev/null || true);
    test -n "$value" || value=$(_eex7_default_buffer);
    normalized=$(_e118_mktemp eex7-user-policy) || return 1;
    _eex7_policy_candidate "$cfg" "$normalized" "$value" || return 1;
    cfg="$normalized";
    _e118_xray_test_config "$cfg" 1 || return 1;
    bdir=$(_e116_backup_state "before_e159_${reason}") || return 1;
    was_active=$(sed -n 's/^xray_was_active=//p' "$bdir/meta.env" 2> /dev/null | head -n1);
    was_active=${was_active:-0};
    [[ "$was_active" =~ ^[01]$ ]] || return 1;
    E118_TX_ACTIVE=1;
    E118_TX_BACKUP="$bdir";
    E118_TX_WAS_ACTIVE="$was_active";
    trap '' INT TERM HUP;
    install -m 0600 "$cfg" "$CONFIG_DIR/.config.e159.$$" || failed=1;
    test "$failed" -ne 0 || install -m 0600 "$smap" "$CONFIG_DIR/.user_sni.e159.$$" || failed=1;
    test "$failed" -ne 0 || install -m 0600 "$tmap" "$CONFIG_DIR/.user_time.e159.$$" || failed=1;
    test -z "$pkey" || test "$failed" -ne 0 || install -m 0600 "$pkey" "$CONFIG_DIR/.public.e159.$$" || failed=1;
    if test "$failed" -eq 0; then
        mv -f "$CONFIG_DIR/.config.e159.$$" "$CONFIG" || failed=1;
        test "$failed" -ne 0 || mv -f "$CONFIG_DIR/.user_sni.e159.$$" "$USER_SNI_MAP" || failed=1;
        test "$failed" -ne 0 || mv -f "$CONFIG_DIR/.user_time.e159.$$" "$USER_TIME_MAP" || failed=1;
        test -z "$pkey" || test "$failed" -ne 0 || mv -f "$CONFIG_DIR/.public.e159.$$" "$PUBKEY_FILE" || failed=1;
    fi;
    rm -f "$CONFIG_DIR"/.config.e159.$$ "$CONFIG_DIR"/.user_sni.e159.$$ "$CONFIG_DIR"/.user_time.e159.$$ "$CONFIG_DIR"/.public.e159.$$ 2> /dev/null || true;
    trap '_e118_signal_handler INT' INT;
    trap '_e118_signal_handler TERM' TERM;
    trap '_e118_signal_handler HUP' HUP;
    test "$failed" -ne 0 || fix_permissions || failed=1;
    test "$failed" -ne 0 || _e266_buffer_state_commit "$value" "$CONFIG" "$E266_BUFFER_STATE" || failed=1;
    if test "$failed" -eq 0 && test "$was_active" = 1; then
        systemctl restart xray.service > /dev/null 2>&1 || failed=1;
        test "$failed" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || failed=1;
    else
        if test "$failed" -eq 0 && systemctl is-active --quiet xray.service 2> /dev/null; then
            failed=1;
        fi;
    fi;
    if test "$failed" -ne 0; then
        error "用户/凭据事务失败，恢复变更前配置与元数据。";
        _e118_restore_state "$bdir" || error "自动回滚失败：$bdir";
        E118_TX_ACTIVE=0;
        E118_TX_BACKUP="";
        E118_TX_WAS_ACTIVE=0;
        return 1;
    fi;
    E118_TX_ACTIVE=0;
    E118_TX_BACKUP="";
    E118_TX_WAS_ACTIVE=0;
    info "事务提交成功：$reason"
}
# EEX3-FUNCTION runtime_e118_135 _e135_choose_single_sni
