# EEX3-FUNCTION runtime_e118_135 _e135_install_mode
_e135_install_mode() {
    local guard rc=0 rollback=0;
    guard=$(_e116_backup_state before_e159_node_install) || return 1;
    _e118_save_core_payload "$guard" || return 1;
    _e152_install_mode_base "$@" || rc=1;
    test "$rc" -ne 0 || _e159_write_version || rc=1;
    test "$rc" -ne 0 || fix_permissions || rc=1;
    test "$rc" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
    if test "$rc" -ne 0; then
        error "E159节点安装最终门禁失败，恢复安装前Core、配置、元数据与服务状态。";
        _e118_restore_core_payload "$guard" > /dev/null 2>&1 || rollback=1;
        _e118_restore_state "$guard" > /dev/null 2>&1 || rollback=1;
        test "$rollback" -eq 0 || error "节点安装完整回滚失败：$guard";
        return 1;
    fi;
    info "节点安装已通过E159最终Xray运行探针。"
}
# EEX3-FUNCTION runtime_e118_135 _e135_install_package_verified
_e135_install_package_verified() {
