# EEX3-FUNCTION runtime_e118_135 _e135_kernel_config_guard
_e135_kernel_config_guard() {
    local src="$1" conf="${E91_BBR_KERNEL_CONF:-${E90_BBR_KERNEL_CONF:-}}";
    _e204_kernel_config_guard_base "$src" || return 1;
    if test -n "$conf"; then
        _e204_bbr_conf_safe "$conf" || return 1;
        ( cd "$src" || exit 1;
        _e90_kernel_patch_before_compile || exit 1;
        _e91_verify_patch_hit net/ipv4/tcp_bbr.c "$conf" "${E91_BBR_KERNEL_KIND:-${E90_BBR_KERNEL_KIND:-}}" || exit 1 ) || { 
            error 'XanMod源码中的自定义BBR注入/逐项读回失败；未进入编译。';
            return 1
        };
    fi;
    make -C "$src" olddefconfig > /dev/null || return 1;
    _e204_kernel_kconfig_verify "$src"
}
# EEX3-FUNCTION runtime_e118_135 _e135_kernel_config_verify
_e135_kernel_config_verify() {
    local src="$1" virt fs dev sym failed=0;
    virt=$(systemd-detect-virt 2> /dev/null || echo none);
    fs=$(findmnt -n -o FSTYPE / 2> /dev/null || echo ext4);
    dev=$(findmnt -n -o SOURCE / 2> /dev/null || true);
    function _need_y () 
    { 
        grep -qx "$1=y" "$src/.config" || { 
            error "内核配置缺少启动必需项：$1=y";
            failed=1
        }
    };
    _need_y CONFIG_BLK_DEV_INITRD;
    _need_y CONFIG_DEVTMPFS;
    _need_y CONFIG_DEVTMPFS_MOUNT;
    case "$fs" in 
        ext4)
            _need_y CONFIG_EXT4_FS
        ;;
        xfs)
            _need_y CONFIG_XFS_FS
        ;;
        btrfs)
            _need_y CONFIG_BTRFS_FS
        ;;
    esac;
    case "$virt" in 
        kvm | qemu)
            for sym in CONFIG_VIRTIO CONFIG_VIRTIO_PCI CONFIG_VIRTIO_BLK CONFIG_VIRTIO_NET CONFIG_SCSI_VIRTIO;
            do
                _need_y "$sym";
            done
        ;;
        xen*)
            for sym in CONFIG_XEN CONFIG_XEN_BLKDEV_FRONTEND CONFIG_XEN_NETDEV_FRONTEND;
            do
                _need_y "$sym";
            done
        ;;
        microsoft)
            for sym in CONFIG_HYPERV CONFIG_HYPERV_STORAGE CONFIG_HYPERV_NET;
            do
                _need_y "$sym";
            done
        ;;
    esac;
    if [[ "$dev" == *nvme* ]]; then
        _need_y CONFIG_BLK_DEV_NVME;
        _need_y CONFIG_NVME_CORE;
    fi;
    grep -Eq '^CONFIG_TCP_CONG_BBR=(y|m)$' "$src/.config" || { 
        error "缺少CONFIG_TCP_CONG_BBR。";
        failed=1
    };
    grep -Eq '^CONFIG_NET_SCH_FQ=(y|m)$' "$src/.config" || { 
        error "缺少CONFIG_NET_SCH_FQ。";
        failed=1
    };
    return "$failed"
}
# EEX3-FUNCTION runtime_e118_135 _e135_kernel_precheck
_e135_kernel_precheck() {
    local work_free boot_free mem_avail cfg;
    [[ "$(uname -m)" = x86_64 ]] || { 
        error "源码编译仅支持x86_64。";
        return 1
    };
    work_free=$(df -Pm /var/tmp 2> /dev/null | awk 'NR==2{print int($4)}' || echo 0);
    boot_free=$(df -Pm /boot 2> /dev/null | awk 'NR==2{print int($4)}' || echo 0);
    mem_avail=$(awk '/MemAvailable:/{print int($2/1024)}' /proc/meminfo 2> /dev/null || echo 0);
    cfg="/boot/config-$(uname -r)";
    echo "  /var/tmp=${work_free}MB /boot=${boot_free}MB MemAvailable=${mem_avail}MB";
    ((work_free>=20000)) || { 
        error "要求/var/tmp至少20GB可用。";
        return 1
    };
    ((boot_free>=500)) || { 
        error "要求/boot至少500MB可用。";
        return 1
    };
    ((mem_avail>=1024)) || { 
        error "MemAvailable低于1GB，拒绝完整编译。";
        return 1
    };
    test -r "$cfg" || { 
        error "缺少当前内核配置$cfg；为避免云VPS驱动缺失，拒绝使用裸defconfig。";
        return 1
    }
}
# EEX3-FUNCTION runtime_e118_135 _e135_kernel_threads
_e135_kernel_threads() {
    local mem cores t;
    mem=$(awk '/MemAvailable:/{print int($2/1024)}' /proc/meminfo 2> /dev/null || echo 1024);
    cores=$(nproc 2> /dev/null || echo 1);
    t=$((mem/1800));
    ((t<1)) && t=1;
    ((t>cores)) && t=$cores;
    ((t>8)) && t=8;
    echo "$t"
}
# EEX3-FUNCTION runtime_e118_135 _e135_map_remove_uuid
_e135_map_remove_uuid() {
    local file="$1" uuid="$2" out="$3";
    awk -F'|' -v u="$uuid" '$1!=u && $1!="" {print}' "$file" 2> /dev/null > "$out" || true
}
# EEX3-FUNCTION runtime_e118_135 _e135_map_replace_uuid
_e135_map_replace_uuid() {
    local old="$1" new="$2" sid="$3" sni="$4" ctime="$5" smap="$6" tmap="$7" t;
    t=$(_e118_mktemp map-replace-sni) || return 1;
    awk -F'|' -v u="$old" '$1!=u && $1!="" {print}' "$smap" > "$t" 2> /dev/null || true;
    test -n "$sid" && printf '%s|%s|%s\n' "$new" "$sid" "$sni" >> "$t";
    mv -f "$t" "$smap" || return 1;
    t=$(_e118_mktemp map-replace-time) || return 1;
    awk -F'|' -v u="$old" '$1!=u && $1!="" {print}' "$tmap" > "$t" 2> /dev/null || true;
    printf '%s|%s\n' "$new" "$ctime" >> "$t";
    mv -f "$t" "$tmap"
}
