# EEX3-FUNCTION runtime_e118_135 _e135_network_validate
_e135_network_validate() {
    local file="$1" key value seen="" available p;
    test -s "$file" || { 
        error "网络候选文件为空。";
        return 1
    };
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs);
        value=$(printf '%s' "$value" | xargs);
        case "$key" in 
            '' | '#'*)
                continue
            ;;
        esac;
        _e136_network_keys | grep -Fxq "$key" || { 
            error "非E152白名单参数：$key";
            return 1
        };
        [[ " $seen " != *" $key "* ]] || { 
            error "候选参数重复：$key";
            return 1
        };
        seen="$seen $key";
        p=$(_e152_proc_path "$key");
        test -e "$p" || { 
            error "候选含当前内核不支持项：$key";
            return 1
        };
        case "$key" in 
            net.ipv4.tcp_notsent_lowat)
                test "$value" = 131072 || return 1
            ;;
            net.ipv4.tcp_congestion_control)
                available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2> /dev/null || true);
                [[ " $available " == *" $value "* ]] || return 1
            ;;
            net.ipv4.tcp_rmem | net.ipv4.tcp_wmem)
                [[ "$value" =~ ^[0-9]+[[:space:]]+[0-9]+[[:space:]]+[0-9]+$ ]] || return 1
            ;;
            *)
                [[ "$value" =~ ^[A-Za-z0-9._-]+([[:space:]][0-9]+)?$ ]] || return 1
            ;;
        esac;
    done < "$file"
}
# EEX3-FUNCTION runtime_e118_135 _e135_patch_fail2ban_ignoreip
_e135_patch_fail2ban_ignoreip() {
    local ip="$1" tmp file_values runtime_values previous previous_pre=1 base merged pre=0 token;
    test -f "$E121_F2B_JAIL" || return 1;
    previous=$(sed -n 's/^ip=//p' "$E152_TRANSIENT_IGNORE" 2> /dev/null | tail -n1);
    previous_pre=$(sed -n 's/^was_preexisting=//p' "$E152_TRANSIENT_IGNORE" 2> /dev/null | tail -n1);
    previous_pre=${previous_pre:-1};
    file_values=$(awk -F= '/^[[:space:]]*ignoreip[[:space:]]*=/{sub(/^[^=]*=/,"");print}' "$E121_F2B_JAIL" | _e137_normalize_ignore_tokens | xargs echo);
    runtime_values=$(fail2ban-client get "$E121_F2B_JAIL_NAME" ignoreip 2> /dev/null | _e137_normalize_ignore_tokens | xargs echo || true);
    base=$(printf '%s\n' "$runtime_values $file_values" | tr ' ' '\n' | awk 'NF&&!seen[$0]++');
    if test -n "$previous" && test "$previous_pre" = 0 && test "$previous" != "$ip"; then
        base=$(grep -Fxv "$previous" <<< "$base" || true);
    fi;
    grep -Fxq "$ip" <<< "$base" 2> /dev/null && pre=1 || true;
    merged=$(printf '%s\n%s\n' "$base" "$ip" | awk 'NF&&!seen[$0]++' | paste -sd' ' -);
    merged=$(_e136_merge_ignoreip_values "$merged" "");
    tmp=$(_e118_mktemp f2b-ignore-e152.conf) || return 1;
    awk -v merged="$merged" 'BEGIN{done=0} /^[[:space:]]*ignoreip[[:space:]]*=/{if(!done){print "ignoreip = " merged;done=1};next} {print} END{if(!done)print "ignoreip = " merged}' "$E121_F2B_JAIL" > "$tmp" || return 1;
    install -m 0644 "$tmp" "$E121_F2B_JAIL" || return 1;
    fail2ban-client -t > /dev/null 2>&1 || return 1;
    systemctl restart fail2ban > /dev/null 2>&1 || return 1;
    test -z "$ip" || fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip "$ip" > /dev/null 2>&1 || true;
    { 
        echo "ip=$ip";
        echo "was_preexisting=$pre";
        echo "updated=$(date -Is 2> /dev/null || date)"
    } > "$E152_TRANSIENT_IGNORE" || return 1;
    chmod 0600 "$E152_TRANSIENT_IGNORE" || return 1
}
# EEX3-FUNCTION runtime_e118_135 _e135_pause
_e135_pause() {
    local _x="";
    read -rp "按 Enter 继续..." _x || true
}
# EEX3-FUNCTION runtime_e118_135 _e135_pkg_present
_e135_pkg_present() {
    local pkg="$1";
    if command -v dpkg-query > /dev/null 2>&1; then
        dpkg-query -W -f='${Status}' "$pkg" 2> /dev/null | grep -q 'install ok installed';
    else
        if command -v rpm > /dev/null 2>&1; then
            rpm -q "$pkg" > /dev/null 2>&1;
        else
            return 1;
        fi;
    fi
}
# EEX3-FUNCTION runtime_e118_135 _e135_port_available
_e135_port_available() {
    local p="$1" current="${2:-}";
    [[ "$p" =~ ^[0-9]+$ ]] && ((p>=1 && p<=65535)) || return 1;
    test "$p" = "$current" && return 0;
    ss -H -tuln 2> /dev/null | awk '{print $5}' | grep -Eq "(^|:|\])${p}$" && return 1;
    return 0
}
# EEX3-FUNCTION runtime_e118_135 _e135_prepare
_e135_prepare() {
    local d mode owner;
    _e118_runtime_init || return 1;
    for d in "$E135_DIR" "$E135_BACKUP_DIR" "$E135_EXPORT_DIR";
    do
        test ! -L "$d" || { 
            error "拒绝使用符号链接凭据目录：$d";
            return 1
        };
        install -d -o root -g root -m 0700 "$d" || return 1;
        mode=$(stat -c '%a' "$d" 2> /dev/null || true);
        owner=$(stat -c '%u:%g' "$d" 2> /dev/null || true);
        test "$mode" = 700 && test "$owner" = 0:0 || { 
            error "凭据目录权限不安全：$d owner=$owner mode=$mode";
            return 1
        };
    done
}
# EEX3-FUNCTION runtime_e118_135 _e135_print_host_port
_e135_print_host_port() {
    printf '  %-18s %s\n' "地址:" "$1";
    printf '  %-18s %s\n' "端口:" "$2"
}
# EEX3-FUNCTION runtime_e118_135 _e135_remove_kernel_packages
_e135_remove_kernel_packages() {
    local p;
    for p in "$@";
    do
        test -n "$p" && dpkg -r "$p" > /dev/null 2>&1 || true;
    done;
    update-grub > /dev/null 2>&1 || true
}
# EEX3-FUNCTION runtime_e118_135 _e135_remove_new_runtime_tools
_e135_remove_new_runtime_tools() {
    local pkg rc=0;
    for pkg in "${E135_NEW_PACKAGES[@]}";
    do
        _e172_remove_package "$pkg" || rc=1;
    done;
    test "$rc" -ne 0 || E135_NEW_PACKAGES=();
    return "$rc"
}
# EEX3-FUNCTION runtime_e118_135 _e135_require_runtime_tools
_e135_require_runtime_tools() {
    _e135_install_package_verified qrencode qrencode || return 1;
    _e135_install_package_verified vnstat vnstat || return 1;
    systemctl enable --now vnstat.service > /dev/null 2>&1 || systemctl enable --now vnstat > /dev/null 2>&1 || { 
        error "vnStat服务无法启动。";
        return 1
    };
    vnstat --version > /dev/null 2>&1 || return 1;
    qrencode --version > /dev/null 2>&1 || return 1
}
# EEX3-FUNCTION runtime_e118_135 _e135_restore_file
_e135_restore_file() {
    local dst="$1" src="$2";
    if test -e "$src.present" || test -L "$src.present"; then
        mkdir -p "$(dirname "$dst")" || return 1;
        rm -rf -- "$dst" 2> /dev/null || true;
        cp -a -- "$src.present" "$dst" || return 1;
    else
        if test -e "$src.absent"; then
            rm -rf -- "$dst" 2> /dev/null || true;
        fi;
    fi
}
# EEX3-FUNCTION runtime_e118_135 _e135_safe_name
_e135_safe_name() {
    printf '%s' "${1:-node}" | tr -cs 'A-Za-z0-9._-' '_' | sed 's/^_\+//;s/_\+$//' | cut -c1-80
}
# EEX3-FUNCTION runtime_e118_135 _e135_self_test
_e135_self_test() {
    local rc=0 body tmp;
    echo "V199e137 release gate:";
    test "$SCRIPT_VERSION" = 199e136 && echo "  [PASS] version" || { 
        echo "  [FAIL] version";
        rc=1
    };
    body=$(declare -f do_summary);
    [[ "$body" == *'_e135_print_host_port'* && "$body" == *'_e135_emit_qr'* ]] && echo "  [PASS] export format/QR" || { 
        echo "  [FAIL] export";
        rc=1
    };
    body="$(declare -f _e135_install_ssh_guard)$(declare -f _e135_patch_fail2ban_ignoreip)";
    [[ "$body" == *'_e135_current_ssh_ip'* && "$body" == *'unbanip'* ]] && echo "  [PASS] SSH current-session protection" || { 
        echo "  [FAIL] SSH anti-lockout";
        rc=1
    };
    body="$(declare -f _e135_xanmod_source_build)$(declare -f _e135_kernel_config_verify)";
    [[ "$body" == *'bindeb-pkg'* && "$body" == *'dkms autoinstall'* && "$body" == *'_e135_remove_kernel_packages'* && "$body" == *'CONFIG_VIRTIO_NET'* ]] && echo "  [PASS] XanMod build transaction" || { 
        echo "  [FAIL] XanMod";
        rc=1
    };
    body=$(declare -f hot_update_from_legacy);
    [[ "$body" == *'_e135_system_snapshot'* && "$body" == *'_e135_system_restore'* && "$body" == *'_e135_network_apply balanced force'* && "$body" == *'_e135_require_runtime_tools'* && "$body" == *'_e135_disable_legacy_optimizers'* ]] && echo "  [PASS] clean hot-update transaction" || { 
        echo "  [FAIL] hot-update";
        rc=1
    };
    tmp=$(mktemp);
    _e135_network_candidate balanced "$tmp" || rc=1;
    grep -qx 'net.ipv4.tcp_notsent_lowat = 131072' "$tmp" && echo "  [PASS] notsent default=131072" || { 
        echo "  [FAIL] notsent default";
        rc=1
    };
    test "$(grep -cE '^[[:space:]]*net\.ipv4\.tcp_notsent_lowat[[:space:]]*=[[:space:]]*16384[[:space:]]*$' "$SCRIPT_PATH" 2> /dev/null || true)" = 0 && echo "  [PASS] no legacy literal 16384 owner" || { 
        echo "  [FAIL] legacy 16384 definition";
        rc=1
    };
    rm -f "$tmp";
    body=$(declare -f do_user_manager);
    [[ "$body" == *'_e135_vless_users_menu'* && "$body" == *'_e135_ss_manager'* ]] && echo "  [PASS] unified user manager" || { 
        echo "  [FAIL] users";
        rc=1
    };
    body=$(declare -f do_traffic_monitor);
    [[ "$body" == *'vnStat统计整台VPS'* && "$body" == *'_e135_xray_connections'* ]] && echo "  [PASS] traffic semantics" || { 
        echo "  [FAIL] traffic";
        rc=1
    };
    body=$(declare -f do_sys_init_menu);
    [[ "$body" == *'无旧大包围入口'* && "$body" == *'_e135_network_menu'* ]] && echo "  [PASS] clean optimization menu" || { 
        echo "  [FAIL] optimization menu";
        rc=1
    };
    body=$(declare -f fix_xray_systemd_limits);
    [[ "$body" == *'LoadState'* && "$body" == *'Nice=-20'* ]] && echo "  [PASS] Nice preinstall/runtime semantics" || { 
        echo "  [FAIL] Nice semantics";
        rc=1
    };
    echo "V199e137 result: $(test "$rc" -eq 0 && echo PASS || echo FAIL)";
    return "$rc"
}
# EEX3-FUNCTION runtime_e118_135 _e135_set_month_rotate
_e135_set_month_rotate() {
    local day old tmp;
    read -rp "月结日1-28: " day || true;
    [[ "$day" =~ ^[0-9]+$ ]] && ((day>=1&&day<=28)) || { 
        error "无效日期。";
        return 1
    };
    old=$(_e118_mktemp vnstat-old.conf);
    tmp=$(_e118_mktemp vnstat-new.conf);
    cp -a /etc/vnstat.conf "$old" || return 1;
    awk -v d="$day" 'BEGIN{done=0} /^[[:space:]]*MonthRotate[[:space:]]+/ {print "MonthRotate " d;done=1;next} {print} END{if(!done) print "MonthRotate " d}' /etc/vnstat.conf > "$tmp" || return 1;
    install -m 0644 "$tmp" /etc/vnstat.conf || return 1;
    if ! systemctl restart vnstat.service > /dev/null 2>&1 && ! systemctl restart vnstat > /dev/null 2>&1; then
        install -m 0644 "$old" /etc/vnstat.conf;
        return 1;
    fi;
    grep -Eq "^[[:space:]]*MonthRotate[[:space:]]+$day([[:space:]]|$)" /etc/vnstat.conf || { 
        install -m 0644 "$old" /etc/vnstat.conf;
        return 1
    };
    info "vnStat月结日已设为$day。"
}
# EEX3-FUNCTION runtime_e118_135 _e135_show_optimization_status
_e135_show_optimization_status() {
    local iface pid;
    iface=$(_e135_default_iface 2> /dev/null || true);
    pid=$(systemctl show xray.service -p MainPID --value 2> /dev/null || echo 0);
    title "V199e137：全部优化参数运行态";
    printf '  %-32s %s\n' "tcp_notsent_lowat" "$(sysctl -n net.ipv4.tcp_notsent_lowat 2> /dev/null || echo unsupported)";
    printf '  %-32s %s/%s\n' "qdisc/CC" "$(sysctl -n net.core.default_qdisc 2> /dev/null || echo unsupported)" "$(sysctl -n net.ipv4.tcp_congestion_control 2> /dev/null || echo unsupported)";
    printf '  %-32s %s\n' "tcp_mtu_probing" "$(sysctl -n net.ipv4.tcp_mtu_probing 2> /dev/null || echo unsupported)";
    printf '  %-32s %s\n' "initcwnd/initrwnd" "$(ip route show default 2> /dev/null | head -n1 | grep -oE 'initcwnd [0-9]+|initrwnd [0-9]+' | xargs echo || true)";
    printf '  %-32s %s\n' "Xray Nice(systemd/process)" "$(systemctl show xray.service -p Nice --value 2> /dev/null || echo n/a)/$(test "$pid" -gt 0 2> /dev/null && ps -o ni= -p "$pid" 2> /dev/null | xargs || echo n/a)";
    printf '  %-32s %s\n' "default interface" "${iface:-unknown}";
    if test -n "$iface" && command -v ethtool > /dev/null 2>&1; then
        echo "  Offload:";
        ethtool -k "$iface" 2> /dev/null | grep -E '(^generic-receive-offload|^generic-segmentation-offload|^tcp-segmentation-offload|^large-receive-offload)' | sed 's/^/    /' || true;
        echo "  Ring:";
        ethtool -g "$iface" 2> /dev/null | sed -n '/Current hardware settings/,$p' | sed 's/^/    /' || true;
    fi;
    echo "  Legacy broad optimizer units:";
    for svc in xray-hw-tweaks.service nic-optimize.service rps-optimize.service txqueue.service xray-accel-e125.service xray-accel-e126.service;
    do
        printf '    %-34s enabled=%-9s active=%s\n' "$svc" "$(systemctl is-enabled "$svc" 2> /dev/null || echo no)" "$(systemctl is-active "$svc" 2> /dev/null || echo no)";
    done
}
# EEX3-FUNCTION runtime_e118_135 _e135_snapshot_file
_e135_snapshot_file() {
    local src="$1" dst="$2";
    mkdir -p "$(dirname "$dst")" || return 1;
    if test -e "$src" || test -L "$src"; then
        cp -a -- "$src" "$dst.present" || return 1;
    else
        : > "$dst.absent" || return 1;
    fi
}
# EEX3-FUNCTION runtime_e118_135 _e135_ss_manager
_e135_ss_manager() {
    local tag="$1" action port new_port method pass cfg smap tmap;
    while true; do
        clear;
        title "V199e137：SS2022凭据管理";
        port=$(jq -r --arg t "$tag" '.inbounds[]|select(.tag==$t)|.port' "$CONFIG");
        method=$(jq -r --arg t "$tag" '.inbounds[]|select(.tag==$t)|.settings.method' "$CONFIG");
        echo "  tag=$tag 端口=$port 方法=$method";
        echo "  1) 轮换密码  2) 修改端口  3) 修改方法并轮换密码  0) 返回";
        read -rp "操作: " action || true;
        cfg=$(_e118_mktemp ss-edit.json);
        smap=$(_e118_mktemp ss-sni);
        tmap=$(_e118_mktemp ss-time);
        _e135_copy_or_empty "$USER_SNI_MAP" "$smap";
        _e135_copy_or_empty "$USER_TIME_MAP" "$tmap";
        case "$action" in 
            1)
                pass=$(e77_gen_ss2022_pass "$method") || continue;
                jq --arg t "$tag" --arg p "$pass" '(.inbounds[]|select(.tag==$t)|.settings.password)=$p' "$CONFIG" > "$cfg" || { 
                    error "候选配置生成失败。";
                    _e135_pause;
                    continue
                }
            ;;
            2)
                read -rp "新端口: " new_port || true;
                _e135_port_available "$new_port" "$port" || { 
                    error "端口无效或占用。";
                    _e135_pause;
                    continue
                };
                jq --arg t "$tag" --argjson p "$new_port" '(.inbounds[]|select(.tag==$t)|.port)=$p' "$CONFIG" > "$cfg" || { 
                    error "候选配置生成失败。";
                    _e135_pause;
                    continue
                }
            ;;
            3)
                method=$(e77_select_ss2022_method);
                pass=$(e77_gen_ss2022_pass "$method") || continue;
                jq --arg t "$tag" --arg m "$method" --arg p "$pass" '(.inbounds[]|select(.tag==$t)|.settings.method)=$m|(.inbounds[]|select(.tag==$t)|.settings.password)=$p' "$CONFIG" > "$cfg" || { 
                    error "候选配置生成失败。";
                    _e135_pause;
                    continue
                }
            ;;
            0)
                return 0
            ;;
            *)
                continue
            ;;
        esac;
        _e135_bundle_commit "$cfg" "$smap" "$tmap" "" ss2022-change && do_summary;
        _e135_pause;
    done
}
# EEX3-FUNCTION runtime_e118_135 _e135_ssh_guard_base
_e135_ssh_guard_base() {
    local firewall_backup="" tool;
    title "V199e137：SSH 端口自检 + 开机放行 + fail2ban 链序";
    if ! command -v sshd > /dev/null 2>&1 && ! systemctl cat ssh.service > /dev/null 2>&1 && ! systemctl cat sshd.service > /dev/null 2>&1; then
        error "未检测到 OpenSSH sshd；sshd 过滤器不适用于 Dropbear 或其他 SSH 实现。";
        return 1;
    fi;
    if command -v sshd > /dev/null 2>&1 && ! sshd -t > "$E118_TMPDIR/sshd-test.log" 2>&1; then
        error "sshd -t 未通过，拒绝变更防护配置。";
        sed 's/^/    /' "$E118_TMPDIR/sshd-test.log" || true;
        return 1;
    fi;
    if command -v iptables-save > /dev/null 2>&1; then
        firewall_backup="$E118_BACKUP_DIR/iptables_before_ssh_e121_$(date +%Y%m%d_%H%M%S)_$$.rules";
        iptables-save > "$firewall_backup" 2> /dev/null || firewall_backup="";
        test -z "$firewall_backup" || chmod 0600 "$firewall_backup" 2> /dev/null || true;
    fi;
    _e121_write_ssh_port_guard || return 1;
    _e121_install_fail2ban_guard || return 1;
    _e121_apply_ssh_port_guard || { 
        error "SSH 端口守护首次应用失败；旧放行规则尚未删除。";
        return 1
    };
    if ! _e121_verify_ssh_port_guard; then
        error "SSH 端口/防火墙链序复检失败；为避免锁机，可能仍保留旧放行规则。";
        test -s "$E121_SSH_GUARD_STATE" && sed 's/^/    /' "$E121_SSH_GUARD_STATE" || true;
        return 1;
    fi;
    systemctl disable --now xray-ssh-port-guard-e116.service xray-ssh-port-guard-e118.service xray-ssh-port-guard-e120.service xray-ssh-port-guard-e120.timer > /dev/null 2>&1 || true;
    rm -f -- "${E116_SSH_PORT_GUARD_SCRIPT:-/usr/local/bin/xray-ssh-port-guard-e116.sh}" "${E116_SSH_PORT_GUARD_SERVICE:-/etc/systemd/system/xray-ssh-port-guard-e116.service}" "$E118_SSH_GUARD_SCRIPT" "$E118_SSH_GUARD_SERVICE" /usr/local/bin/xray-ssh-port-guard-e120.sh /etc/systemd/system/xray-ssh-port-guard-e120.service /etc/systemd/system/xray-ssh-port-guard-e120.timer 2> /dev/null || true;
    for tool in iptables ip6tables;
    do
        command -v "$tool" > /dev/null 2>&1 || continue;
        while "$tool" -C INPUT -j XRAY_SSH_E120 > /dev/null 2>&1; do
            "$tool" -D INPUT -j XRAY_SSH_E120 > /dev/null 2>&1 || break;
        done;
        "$tool" -F XRAY_SSH_E120 > /dev/null 2>&1 || true;
        "$tool" -X XRAY_SSH_E120 > /dev/null 2>&1 || true;
        "$tool" -F XRAY_SSH_E120_NEW > /dev/null 2>&1 || true;
        "$tool" -X XRAY_SSH_E120_NEW > /dev/null 2>&1 || true;
    done;
    systemctl daemon-reload > /dev/null 2>&1 || true;
    info "SSH 端口已自动识别、开机及每5分钟复检；fail2ban 封禁链确认位于放行链之前。";
    info "SSH 策略：24小时内第2次失败触发封禁36小时；封禁数据库与端口状态跨重启保留。";
    test -z "$firewall_backup" || info "防火墙变更前快照：$firewall_backup"
}
# EEX3-FUNCTION runtime_e118_135 _e135_ssh_menu
_e135_ssh_menu() {
    local n;
    while true; do
        clear;
