# EEX3-FUNCTION runtime_e118_135 _e135_system_restore
_e135_system_restore() {
    local b="$1" rel key value svc enabled active;
    test -d "$b" || return 1;
    while IFS= read -r rel; do
        _e138_safe_restore_rel "$rel" || return 1;
        rm -rf -- "/${rel:?}" 2> /dev/null || true;
    done < <(cat "$b/present.list" "$b/absent.list" 2> /dev/null);
    test -s "$b/files.tar" && tar -C / -xpf "$b/files.tar" || true;
    while IFS='|' read -r key value; do
        test -n "$value" && sysctl -w "$key=$value" > /dev/null 2>&1 || true;
    done < "$b/runtime-sysctl.env";
    test -s "$b/iptables.rules" && command -v iptables-restore > /dev/null 2>&1 && iptables-restore < "$b/iptables.rules" || true;
    test -s "$b/ip6tables.rules" && command -v ip6tables-restore > /dev/null 2>&1 && ip6tables-restore < "$b/ip6tables.rules" || true;
    systemctl daemon-reload > /dev/null 2>&1 || true;
    while IFS='|' read -r svc enabled active; do
        if test "$enabled" = enabled; then
            systemctl enable "$svc" > /dev/null 2>&1 || true;
        else
            systemctl disable "$svc" > /dev/null 2>&1 || true;
        fi;
        if test "$active" = active; then
            systemctl restart "$svc" > /dev/null 2>&1 || true;
        else
            systemctl stop "$svc" > /dev/null 2>&1 || true;
        fi;
    done < "$b/services.env"
}
# EEX3-FUNCTION runtime_e118_135 _e135_system_snapshot
_e135_system_snapshot() {
    local b="$1" svc;
    _e137_system_snapshot_base "$b" || return 1;
    for svc in xray-warp-e137-health.service xray-warp-e137-health.timer xray-warp-e136-health.service xray-warp-e136-health.timer xray-init-window-e137.service xray-init-window-e137.timer xray-offload-e137.service xray-offload-e137.timer xray-rps-rfs-e137.service xray-rps-rfs-e137.timer xray-txqueue-e137.service xray-txqueue-e137.timer xray-ring-e137.service xray-ring-e137.timer xray-mss-clamp-e88.service xray-mss-clamp-e137.timer;
    do
        printf '%s|%s|%s\n' "$svc" "$(systemctl is-enabled "$svc" 2> /dev/null || true)" "$(systemctl is-active "$svc" 2> /dev/null || true)" >> "$b/services.env";
    done
}
# EEX3-FUNCTION runtime_e118_135 _e135_valid_ip
_e135_valid_ip() {
    local v="${1:-}";
    [[ "$v" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] && awk -F. '{for(i=1;i<=4;i++) if($i<0||$i>255) exit 1}' <<< "$v" && return 0;
    [[ "$v" == *:* ]] && return 0;
    return 1
}
# EEX3-FUNCTION runtime_e118_135 _e135_vless_users_menu
_e135_vless_users_menu() {
    local tag="$1" reality="$2" action idx count sid_count uuid remark new_uuid new_remark sid sni ctime current_port new_port cfg smap tmap pkey raw;
    while true; do
        clear;
        title "V199e137：$(test "$reality" = 1 && echo Reality || echo VLESSENC) 用户事务中心";
        count=$(jq -r --arg t "$tag" '.inbounds[]|select(.tag==$t)|.settings.clients|length' "$CONFIG");
        current_port=$(jq -r --arg t "$tag" '.inbounds[]|select(.tag==$t)|.port' "$CONFIG");
        if test "$reality" = 1; then
            sid_count=$(jq -r --arg t "$tag" '.inbounds[]|select(.tag==$t)|.streamSettings.realitySettings.shortIds|length' "$CONFIG");
            test "$sid_count" = "$count" || { 
                error "Reality clients数量($count)与shortIds数量($sid_count)不一致，拒绝用户操作；请先修复配置。";
                return 1
            };
            sni=$(jq -r --arg t "$tag" '.inbounds[]|select(.tag==$t)|.streamSettings.realitySettings.serverNames[0]//empty' "$CONFIG");
        else
            sni="";
        fi;
        jq -r --arg t "$tag" '.inbounds[]|select(.tag==$t)|.settings.clients|to_entries[]|"  \(.key+1)) \(.value.email//"未命名")  UUID=\(.value.id)"' "$CONFIG";
        echo "  端口: $current_port";
        test "$reality" = 1 && echo "  全局SNI: $sni";
        hr;
        echo "  a) 新增用户     m) 导入UUID";
        echo "  r) 修改备注     u) 更换UUID";
        test "$reality" = 1 && echo "  i) 轮换ShortId  s) 修改全局SNI/target  k) 轮换Reality密钥";
        echo "  p) 修改端口     d) 删除用户";
        echo "  q) 返回";
        read -rp "输入操作: " action || true;
        case "$action" in 
            q | Q)
                return 0
            ;;
            a | A | m | M)
                if [[ "$action" =~ ^[aA]$ ]]; then
                    uuid=$(_e118_new_uuid) || continue;
                else
                    read -rp "UUID: " uuid || true;
                    _e118_valid_uuid "$uuid" || { 
                        error "UUID非法。";
                        _e135_pause;
                        continue
                    };
                fi;
                jq -e --arg u "$uuid" '[.inbounds[]?.settings.clients[]?.id]|index($u)==null' "$CONFIG" > /dev/null || { 
                    error "UUID重复。";
                    _e135_pause;
                    continue
                };
                read -rp "备注: " remark || true;
                remark=${remark:-user-$(date +%s)};
                sid="";
                test "$reality" = 1 && sid=$(_e118_new_sid);
                cfg=$(_e118_mktemp user-add.json);
                smap=$(_e118_mktemp user-add-sni);
                tmap=$(_e118_mktemp user-add-time);
                _e135_copy_or_empty "$USER_SNI_MAP" "$smap";
                _e135_copy_or_empty "$USER_TIME_MAP" "$tmap";
                jq --arg t "$tag" --arg u "$uuid" --arg e "$remark" --arg sid "$sid" '
                  (.inbounds[]|select(.tag==$t)) |= (
                    .settings.clients += [{id:$u,flow:"xtls-rprx-vision",email:$e}] |
                    if (.streamSettings.security//"")=="reality" then .streamSettings.realitySettings.shortIds += [$sid] else . end
                  )' "$CONFIG" > "$cfg" || continue;
                if test "$reality" = 1; then
                    printf '%s|%s|%s\n' "$uuid" "$sid" "$sni" >> "$smap";
                fi;
                printf '%s|%s\n' "$uuid" "$(date '+%F %T')" >> "$tmap";
                _e135_bundle_commit "$cfg" "$smap" "$tmap" "" user-add && do_summary;
                _e135_pause
            ;;
            r | R | u | U | i | I | d | D)
                read -rp "用户序号: " idx || true;
                [[ "$idx" =~ ^[0-9]+$ ]] && ((idx>=1 && idx<=count)) || { 
                    error "序号无效。";
                    _e135_pause;
                    continue
                };
                idx=$((idx-1));
                uuid=$(jq -r --arg t "$tag" --argjson i "$idx" '.inbounds[]|select(.tag==$t)|.settings.clients[$i].id' "$CONFIG");
                remark=$(jq -r --arg t "$tag" --argjson i "$idx" '.inbounds[]|select(.tag==$t)|.settings.clients[$i].email//"未命名"' "$CONFIG");
                sid="";
                test "$reality" = 1 && sid=$(jq -r --arg t "$tag" --argjson i "$idx" '.inbounds[]|select(.tag==$t)|.streamSettings.realitySettings.shortIds[$i]//empty' "$CONFIG");
                ctime=$(awk -F'|' -v u="$uuid" '$1==u{print $2;exit}' "$USER_TIME_MAP" 2> /dev/null || true);
                ctime=${ctime:-$(date '+%F %T')};
                cfg=$(_e118_mktemp user-edit.json);
                smap=$(_e118_mktemp user-edit-sni);
                tmap=$(_e118_mktemp user-edit-time);
                _e135_copy_or_empty "$USER_SNI_MAP" "$smap";
                _e135_copy_or_empty "$USER_TIME_MAP" "$tmap";
                case "$action" in 
                    r | R)
                        read -rp "新备注: " new_remark || true;
                        test -n "$new_remark" || continue;
                        jq --arg t "$tag" --argjson i "$idx" --arg e "$new_remark" '(.inbounds[]|select(.tag==$t)|.settings.clients[$i].email)=$e' "$CONFIG" > "$cfg" || { 
                            error "候选配置生成失败。";
                            _e135_pause;
                            continue
                        }
                    ;;
                    u | U)
                        read -rp "新UUID（回车自动）: " new_uuid || true;
                        new_uuid=${new_uuid:-$(_e118_new_uuid)};
                        _e118_valid_uuid "$new_uuid" || { 
                            error "UUID非法。";
