                            continue
                        };
                        jq -e --arg u "$new_uuid" '[.inbounds[]?.settings.clients[]?.id]|index($u)==null' "$CONFIG" > /dev/null || { 
                            error "UUID重复。";
                            _e135_pause;
                            continue
                        };
                        jq --arg t "$tag" --argjson i "$idx" --arg u "$new_uuid" '(.inbounds[]|select(.tag==$t)|.settings.clients[$i].id)=$u' "$CONFIG" > "$cfg" || { 
                            error "候选配置生成失败。";
                            _e135_pause;
                            continue
                        };
                        _e135_map_replace_uuid "$uuid" "$new_uuid" "$sid" "$sni" "$ctime" "$smap" "$tmap" || continue
                    ;;
                    i | I)
                        test "$reality" = 1 || { 
                            warn "VLESSENC没有ShortId。";
                            _e135_pause;
                            continue
                        };
                        sid=$(_e118_new_sid) || continue;
                        jq --arg t "$tag" --argjson i "$idx" --arg sid "$sid" '(.inbounds[]|select(.tag==$t)|.streamSettings.realitySettings.shortIds[$i])=$sid' "$CONFIG" > "$cfg" || { 
                            error "候选配置生成失败。";
                            _e135_pause;
                            continue
                        };
                        awk -F'|' -v u="$uuid" -v sid="$sid" -v s="$sni" 'BEGIN{OFS="|";found=0} $1==u{print u,sid,s;found=1;next}{print} END{if(!found)print u,sid,s}' "$smap" > "$smap.new" && mv "$smap.new" "$smap" || { 
                            error "ShortId元数据更新失败。";
                            _e135_pause;
                            continue
                        }
                    ;;
                    d | D)
                        ((count>1)) || { 
                            error "至少保留一个用户。";
                            _e135_pause;
                            continue
                        };
                        read -rp "输入 DELETE-$((idx+1)) 确认: " new_remark || true;
                        test "$new_remark" = "DELETE-$((idx+1))" || continue;
                        jq --arg t "$tag" --argjson i "$idx" '(.inbounds[]|select(.tag==$t)) |= (.settings.clients |= del(.[$i]) | if (.streamSettings.security//"")=="reality" then .streamSettings.realitySettings.shortIds |= del(.[$i]) else . end)' "$CONFIG" > "$cfg" || { 
                            error "候选配置生成失败。";
                            _e135_pause;
                            continue
                        };
                        _e135_map_remove_uuid "$smap" "$uuid" "$smap.new";
                        mv "$smap.new" "$smap";
                        _e135_map_remove_uuid "$tmap" "$uuid" "$tmap.new";
                        mv "$tmap.new" "$tmap"
                    ;;
                esac;
                _e135_bundle_commit "$cfg" "$smap" "$tmap" "" "user-${action}" && do_summary;
                _e135_pause
            ;;
            p | P)
                read -rp "新端口（当前$current_port）: " new_port || true;
                new_port=${new_port:-$current_port};
                _e135_port_available "$new_port" "$current_port" || { 
                    error "端口无效或被其它进程占用。";
                    _e135_pause;
                    continue
                };
                cfg=$(_e118_mktemp port.json);
                smap=$(_e118_mktemp port-sni);
                tmap=$(_e118_mktemp port-time);
                _e135_copy_or_empty "$USER_SNI_MAP" "$smap";
                _e135_copy_or_empty "$USER_TIME_MAP" "$tmap";
                jq --arg t "$tag" --argjson p "$new_port" '(.inbounds[]|select(.tag==$t)|.port)=$p' "$CONFIG" > "$cfg" || { 
                    error "候选配置生成失败。";
                    _e135_pause;
                    continue
                };
                _e135_bundle_commit "$cfg" "$smap" "$tmap" "" port-change && do_summary;
                _e135_pause
            ;;
            s | S)
                test "$reality" = 1 || continue;
                _e135_choose_single_sni || { 
                    _e135_pause;
                    continue
                };
                cfg=$(_e118_mktemp sni.json);
                smap=$(_e118_mktemp sni-map);
                tmap=$(_e118_mktemp sni-time);
                _e135_copy_or_empty "$USER_SNI_MAP" "$smap";
                _e135_copy_or_empty "$USER_TIME_MAP" "$tmap";
                jq --arg t "$tag" --arg s "$BEST_SNI" --arg target "$BEST_SNI:443" '(.inbounds[]|select(.tag==$t)|.streamSettings.realitySettings) |= (.serverNames=[$s]|.target=$target|del(.dest))' "$CONFIG" > "$cfg" || { 
                    error "候选配置生成失败。";
                    _e135_pause;
                    continue
                };
                awk -F'|' -v s="$BEST_SNI" 'BEGIN{OFS="|"} $1!=""{print $1,$2,s}' "$smap" > "$smap.new" && mv "$smap.new" "$smap";
                _e135_bundle_commit "$cfg" "$smap" "$tmap" "" sni-change && do_summary;
                _e135_pause
            ;;
            k | K)
                test "$reality" = 1 || continue;
                raw=$("$XRAY_BIN" x25519 2> /dev/null || true);
                _e118_parse_x25519_output "$raw" || { 
                    error "X25519输出解析失败。";
                    _e135_pause;
                    continue
                };
                cfg=$(_e118_mktemp key.json);
                smap=$(_e118_mktemp key-sni);
                tmap=$(_e118_mktemp key-time);
                pkey=$(_e118_mktemp public.key);
                _e135_copy_or_empty "$USER_SNI_MAP" "$smap";
                _e135_copy_or_empty "$USER_TIME_MAP" "$tmap";
                printf '%s\n' "$E77_REALITY_PUB" > "$pkey";
                jq --arg t "$tag" --arg p "$E77_REALITY_PRIV" '(.inbounds[]|select(.tag==$t)|.streamSettings.realitySettings) |= (.privateKey=$p|del(.publicKey,.password))' "$CONFIG" > "$cfg" || { 
                    error "候选配置生成失败。";
                    _e135_pause;
                    continue
                };
                _e135_bundle_commit "$cfg" "$smap" "$tmap" "$pkey" key-rotate && do_summary;
                _e135_pause
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION runtime_e118_135 _e135_vnstat_prepare
_e135_vnstat_prepare() {
    local iface="$1";
    command -v vnstat > /dev/null 2>&1 || { 
        pkg_install vnstat;
        command -v vnstat > /dev/null 2>&1 || return 1
    };
    systemctl enable --now vnstat.service > /dev/null 2>&1 || systemctl enable --now vnstat > /dev/null 2>&1 || true;
    if ! vnstat --iflist 2> /dev/null | tr ' ' '\n' | grep -Fxq "$iface"; then
        vnstat --add -i "$iface" > /dev/null 2>&1 || vnstat -u -i "$iface" > /dev/null 2>&1 || true;
        systemctl restart vnstat.service > /dev/null 2>&1 || systemctl restart vnstat > /dev/null 2>&1 || true;
    fi;
    test -d "/sys/class/net/$iface"
}
# EEX3-FUNCTION runtime_e118_135 _e135_xanmod_choose_tag
_e135_xanmod_choose_tag() {
    local mode="${1:-}" json tag encoded expected sel i;
    if test -z "$mode"; then
        echo "  1) 普通 XanMod（非RT最新Tag）";
        echo "  2) XanMod RT（实时内核最新Tag）";
        echo "  3) 手动输入精确Tag";
        read -rp "选择 (默认1): " mode || true;
        case "${mode:-1}" in 
            1)
                mode=normal
            ;;
            2)
                mode=rt
            ;;
            3)
                mode=manual
            ;;
            *)
                return 1
            ;;
        esac;
    fi;
    if test "$mode" = manual; then
        read -rp "完整Tag: " tag || true;
    else
        json=$(curl --proto '=https' --tlsv1.2 -fsSL --connect-timeout 10 --max-time 90 'https://gitlab.com/api/v4/projects/xanmod%2Flinux/repository/tags?per_page=100' 2> /dev/null) || return 1;
        if test "$mode" = rt; then
            mapfile -t E135_TAGS < <(printf '%s' "$json" | jq -r '.[]?.name//empty' | grep -E '^[0-9]+\.[0-9]+\.[0-9]+-rt[^-]*-xanmod[0-9]+$' | grep -vE 'rc|beta' | sort -Vr | head -n 20);
        else
            mapfile -t E135_TAGS < <(printf '%s' "$json" | jq -r '.[]?.name//empty' | grep -E '^[0-9]+\.[0-9]+\.[0-9]+-xanmod[0-9]+$' | grep -vE 'rc|beta|rt' | sort -Vr | head -n 20);
        fi;
        test "${#E135_TAGS[@]}" -gt 0 || return 1;
        i=1;
        for tag in "${E135_TAGS[@]}";
        do
            printf '  %d) %s\n' "$i" "$tag";
            i=$((i+1));
        done;
        read -rp "选择Tag (默认1): " sel || true;
        sel=${sel:-1};
        [[ "$sel" =~ ^[0-9]+$ ]] && ((sel>=1&&sel<=${#E135_TAGS[@]})) || return 1;
        tag=${E135_TAGS[$((sel-1))]};
    fi;
    [[ "$tag" =~ ^[0-9]+\.[0-9]+\.[0-9]+(-rt[^-]*)?-xanmod[0-9]+$ ]] || { 
        error "Tag格式非法：$tag";
        return 1
    };
    encoded=$(jq -rn --arg v "$tag" '$v|@uri');
    json=$(curl --proto '=https' --tlsv1.2 -fsSL --connect-timeout 10 --max-time 90 "https://gitlab.com/api/v4/projects/xanmod%2Flinux/repository/tags/$encoded") || return 1;
    expected=$(printf '%s' "$json" | jq -r '.commit.id//empty');
    [[ "$expected" =~ ^[0-9a-f]{40}$ ]] || return 1;
    LATEST_TAG="$tag";
    E131_XANMOD_EXPECTED_COMMIT="$expected"
}
# EEX3-FUNCTION runtime_e118_135 _e135_xanmod_menu
_e135_xanmod_menu() {
    local n;
    while true; do
        clear;
        title "V199e137：XanMod内核中心";
        echo "  1) 安装官方APT预编译XanMod";
        echo "  2) 完整源码编译普通XanMod";
        echo "  3) 完整源码编译XanMod RT";
        echo "  4) 查看当前/已安装内核";
        echo "  0) 返回";
        read -rp "操作: " n || true;
        case "$n" in 
            1)
                do_install_xanmod_main_official;
                _e135_pause
            ;;
            2)
                _e135_xanmod_source_build normal;
                _e135_pause
            ;;
            3)
                _e135_xanmod_source_build rt;
                _e135_pause
            ;;
            4)
                uname -a;
                dpkg -l 'linux-image*' 2> /dev/null | awk '/^ii/{print $2,$3}';
                _e135_pause
            ;;
            0)
                return
            ;;
        esac;
    done
}
# EEX3-FUNCTION runtime_e118_135 _e135_xanmod_source_build
_e135_xanmod_source_build() {
    local guard old_dpkg rc had_errexit=0;
    [[ $- == *e* ]] && had_errexit=1 || true;
    guard=$(_e118_mktemp xanmod-pkg-guard-e152) || return 1;
    : > "$guard";
    old_dpkg=$(declare -f dpkg 2> /dev/null || true);
    function dpkg () 
    { 
        local arg pkg deb;
        if test "${1:-}" = -i; then
            shift;
            for deb in "$@";
            do
                pkg=$(command dpkg-deb -f "$deb" Package 2> /dev/null || return 1);
                if command dpkg-query -W -f='${Status}' "$pkg" 2> /dev/null | grep -q 'install ok installed'; then
                    error "同名内核包已安装，拒绝覆盖并避免失败回滚误删：$pkg";
                    return 1;
                fi;
                printf '%s\n' "$pkg" >> "$guard";
            done;
            command dpkg -i "$@";
        else
            if test "${1:-}" = -r; then
                shift;
                for pkg in "$@";
                do
                    grep -Fxq "$pkg" "$guard" || { 
                        warn "跳过删除非本事务新装包：$pkg";
                        continue
                    };
                    command dpkg -r "$pkg" || true;
                done;
            else
                command dpkg "$@";
            fi;
        fi
    };
    set +e;
    _e152_xanmod_source_build_base;
    rc=$?;
    test "$had_errexit" = 1 && set -e || set +e;
    unset -f dpkg;
    test -z "$old_dpkg" || eval "$old_dpkg";
    return "$rc"
}
# EEX3-FUNCTION runtime_e118_135 _e135_xray_connections
_e135_xray_connections() {
    title "Xray当前连接与入站监听";
    local ports p;
    ports=$(jq -r '.inbounds[]?.port//empty' "$CONFIG" 2> /dev/null | sort -nu | xargs echo);
    echo "  入站端口: ${ports:-none}";
    printf '  Xray进程TCP连接数: %s\n' "$(ss -Hntp 2> /dev/null | grep -c 'xray' || true)";
    for p in $ports;
    do
        printf '  端口 %-6s ESTABLISHED=%s\n' "$p" "$(ss -Hnt state established 2> /dev/null | awk -v p="$p" '$4 ~ (":"p"$") || $3 ~ (":"p"$") {c++} END{print c+0}')";
    done
}
