# EEX3-FUNCTION warp_e136_140 _e136_direct_ipv4
_e136_direct_ipv4() {
    local ip="" n;
    for n in 1 2;
    do
        ip=$(curl -4 -fsS --noproxy '*' --connect-timeout 3 --max-time 8 https://api.ipify.org 2> /dev/null | tr -d '\r\n' || true);
        _e136_is_ipv4 "$ip" && { 
            printf '%s\n' "$ip";
            return 0
        };
        ip=$(curl -4 -fsS --noproxy '*' --connect-timeout 3 --max-time 8 https://ifconfig.me/ip 2> /dev/null | tr -d '\r\n' || true);
        _e136_is_ipv4 "$ip" && { 
            printf '%s\n' "$ip";
            return 0
        };
        sleep 1;
    done;
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e136_hot_update_preflight
_e136_hot_update_preflight() {
    test "$EUID" -eq 0 || { 
        error "热更新必须使用root。";
        return 1
    };
    command -v systemctl > /dev/null 2>&1 || { 
        error "缺少systemd。";
        return 1
    };
    local c;
    for c in bash jq curl ip ss tar install awk sed grep sysctl;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "热更新预检缺少命令：$c";
            return 1
        };
    done;
    test -r "$SCRIPT_PATH" || { 
        error "当前脚本不可读。";
        return 1
    };
    return 0
}
