    awk -F. 'NF==4{for(i=1;i<=4;i++)if($i!~/^[0-9]+$/||$i<0||$i>255)exit 1;exit 0}{exit 1}' <<< "${1:-}"
}
# EEX3-FUNCTION warp_e136_140 _e136_merge_ignoreip_values
_e136_merge_ignoreip_values() {
    local existing="${1:-}" ip="${2:-}" token out="" seen=" ";
    for token in 127.0.0.1/8 ::1 $existing $ip;
    do
        test -n "$token" || continue;
        [[ "$seen" == *" $token "* ]] && continue;
        seen+="$token ";
        out+="${out:+ }$token";
    done;
    printf '%s' "$out"
}
# EEX3-FUNCTION warp_e136_140 _e136_network_apply
