# EEX3-FUNCTION warp_e136_140 _e136_network_candidate
_e136_network_candidate() {
    local profile="${1:-balanced}" out="$2" cc qdisc;
    case "$profile" in 
        balanced | low | throughput)

        ;;
        *)
            profile=balanced
        ;;
    esac;
    if sysctl -n net.ipv4.tcp_available_congestion_control 2> /dev/null | grep -qw bbr; then
        cc=bbr;
    else
        if sysctl -n net.ipv4.tcp_available_congestion_control 2> /dev/null | grep -qw cubic; then
            cc=cubic;
        else
            cc=$(sysctl -n net.ipv4.tcp_congestion_control 2> /dev/null || echo reno);
        fi;
    fi;
    qdisc=fq;
    { 
        echo "# Managed exclusively by ex199e152; profile=$profile; generated=$(date -Is 2> /dev/null || date)";
        echo "net.core.default_qdisc = $qdisc";
        echo "net.ipv4.tcp_congestion_control = $cc";
        echo "net.ipv4.tcp_mtu_probing = 1";
        echo "net.ipv4.tcp_slow_start_after_idle = 0";
        case "$profile" in 
            low)
                echo "net.ipv4.tcp_notsent_lowat = 65536";
                echo "net.ipv4.tcp_limit_output_bytes = 524288";
                echo "net.core.somaxconn = 4096";
                echo "net.core.netdev_max_backlog = 2048";
                echo "net.core.rmem_max = 33554432";
                echo "net.core.wmem_max = 33554432";
                echo "net.ipv4.tcp_rmem = 4096 131072 33554432";
                echo "net.ipv4.tcp_wmem = 4096 32768 33554432"
            ;;
            throughput)
                echo "net.ipv4.tcp_notsent_lowat = 262144";
                echo "net.ipv4.tcp_limit_output_bytes = 2097152";
                echo "net.core.somaxconn = 8192";
                echo "net.core.netdev_max_backlog = 8192";
                echo "net.core.rmem_max = 100663296";
                echo "net.core.wmem_max = 100663296";
                echo "net.ipv4.tcp_rmem = 4096 262144 100663296";
                echo "net.ipv4.tcp_wmem = 4096 131072 100663296"
            ;;
            *)
                echo "net.ipv4.tcp_notsent_lowat = 131072";
                echo "net.ipv4.tcp_limit_output_bytes = 1048576";
                echo "net.core.somaxconn = 4096";
                echo "net.core.netdev_max_backlog = 4096";
                echo "net.core.rmem_max = 67108864";
                echo "net.core.wmem_max = 67108864";
                echo "net.ipv4.tcp_rmem = 4096 131072 67108864";
                echo "net.ipv4.tcp_wmem = 4096 65536 67108864"
            ;;
        esac;
        echo "net.ipv4.tcp_fastopen = 1";
        echo "net.ipv4.tcp_ecn = 2";
        echo "net.ipv4.ip_local_port_range = 32768 65535";
        echo "net.ipv6.conf.all.disable_ipv6 = 1";
        echo "net.ipv6.conf.default.disable_ipv6 = 1";
        echo "net.ipv6.conf.lo.disable_ipv6 = 1"
    } > "$out"
}
