# EEX3-FUNCTION warp_e136_140 _e136_network_preflight
_e136_network_preflight() {
    test "$EUID" -eq 0 || { 
        error "网络参数管理必须使用root。";
        return 1
    };
    local c;
    for c in bash jq ip sysctl awk sed grep install;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "网络参数预检缺少命令：$c";
            return 1
        };
    done;
    return 0
}
