    _e136_network_candidate balanced "$net" || rc=1;
    grep -qx 'net.ipv4.tcp_notsent_lowat = 131072' "$net" && grep -qx 'net.ipv6.conf.all.disable_ipv6 = 1' "$net" && grep -qx 'net.ipv6.conf.default.disable_ipv6 = 1' "$net" && echo "  [PASS] IPv4-only network candidate" || { 
