    printf 'net.ipv4.tcp_notsent_lowat = %s\nfoo.bar = 1\nnet.ipv6.conf.all.disable_ipv6 = 0\n' "$((1<<14))" > "$src";
    _e136_strip_sysctl_file "$keys" "$src" "$stripped" || rc=1;
    test "$(cat "$stripped")" = 'foo.bar = 1' && echo "  [PASS] duplicate sysctl behavior" || { 
        echo "  [FAIL] sysctl strip";
        rc=1
    };
    domains=$(_e136_warp_domains_json google-meta-core) || rc=1;
    test "$(jq 'length' <<< "$domains")" -ge 20 && test "$(jq 'length == (unique|length)' <<< "$domains")" = true && echo "  [PASS] WARP domain profile" || { 
        echo "  [FAIL] WARP domains";
        rc=1
    };
    sample="$tmpd/sample.json";
    enabled="$tmpd/enabled.json";
    disabled="$tmpd/disabled.json";
    printf '%s\n' '{"dns":{"servers":["1.1.1.1"]},"outbounds":[{"tag":"direct","protocol":"freedom","settings":{}}],"routing":{"rules":[]}}' > "$sample";
    _e136_warp_config_build google-meta-core true "$enabled" "$sample" || rc=1;
    jq -e --arg w "$E136_WARP_TAG" --arg b "$E136_WARP_BLOCK_TAG" '([.outbounds[]|select(.tag==$w)]|length)==1 and ([.outbounds[]|select(.tag==$b)]|length)==1 and ([.routing.rules[]|select(.outboundTag==$w)]|length)==1 and ([.routing.rules[]|select(.outboundTag==$b)]|length)==1 and .dns.queryStrategy=="UseIPv4"' "$enabled" > /dev/null && echo "  [PASS] Xray WARP route build" || { 
        echo "  [FAIL] WARP config build";
        rc=1
    };
    _e136_warp_config_build disabled false "$disabled" "$enabled" || rc=1;
    jq -e --arg w "$E136_WARP_TAG" --arg b "$E136_WARP_BLOCK_TAG" '([.outbounds[]|select(.tag==$w or .tag==$b)]|length)==0 and ([.routing.rules[]|select(.outboundTag==$w or .outboundTag==$b)]|length)==0' "$disabled" > /dev/null && echo "  [PASS] Xray WARP route removal" || { 
        echo "  [FAIL] WARP removal";
        rc=1
    };
    test "$(cpu_mask_all 64)" = 'ffffffff,ffffffff' && echo "  [PASS] 64-core cpumask" || { 
        echo "  [FAIL] cpumask";
        rc=1
    };
    merged=$(_e136_merge_ignoreip_values '10.0.0.0/8 192.168.1.5' '203.0.113.9');
    [[ "$merged" == *'10.0.0.0/8'* && "$merged" == *'192.168.1.5'* && "$merged" == *'203.0.113.9'* ]] && echo "  [PASS] Fail2ban ignoreip preservation" || { 
        echo "  [FAIL] ignoreip merge";
        rc=1
