    body=$(declare -f _e136_warp_connect_local_proxy);
    [[ "$body" == *'_e136_route_guard_snapshot'* && "$body" == *'_e136_direct_ipv4'* && "$body" == *'loc" = CN'* && "$body" == *'disconnect'* ]] && echo "  [PASS] WARP route/policy/CN fail-closed" || { 
        echo "  [FAIL] WARP anti-lockout";
        rc=1
    };
    body=$(declare -f _e136_warp_health_check);
    [[ "$body" == *'_e136_warp_connect_local_proxy'* && "$body" == *'managed'* && "$body" == *'route_enabled'* ]] && echo "  [PASS] WARP health fail-closed" || { 
        echo "  [FAIL] WARP health guard";
        rc=1
    };
    body=$(declare -f _e136_network_apply);
    [[ "$body" == *'_e136_service_state_snapshot'* && "$body" == *'_e136_service_state_restore'* ]] && echo "  [PASS] network service rollback" || { 
        echo "  [FAIL] network service rollback";
        rc=1
    };
    body=$(declare -f hot_update_from_legacy);
    [[ "$body" == *'_e135_system_snapshot'* && "$body" == *'_e136_network_apply balanced force'* && "$body" == *'net.ipv6.conf.all.disable_ipv6'* ]] && echo "  [PASS] E136 hot-update chain" || { 
        echo "  [FAIL] hot-update";
        rc=1
    };
    body=$(declare -f _e136_hot_update_preflight);
    [[ "$body" != *'apt-get '* && "$body" != *'cp -'* && "$body" != *'systemctl enable'* && "$body" != *'systemctl restart'* ]] && echo "  [PASS] non-mutating hot-update preflight" || { 
        echo "  [FAIL] preflight mutates";
        rc=1
    };
    oldhint="ex199e""131";
    test "$(grep -c "$oldhint" "$SCRIPT_PATH" 2> /dev/null || true)" = 0 && echo "  [PASS] stale version text removed" || { 
        echo "  [FAIL] stale text";
        rc=1
    };
    rm -rf "$tmpd";
    echo "V199e137 result: $(test "$rc" -eq 0 && echo PASS || echo FAIL)";
    return "$rc"
}
# EEX3-FUNCTION warp_e136_140 _e136_service_state_restore
_e136_service_state_restore() {
    local in="$1" svc enabled active;
    test -s "$in" || return 0;
    while IFS='|' read -r svc enabled active; do
        test -n "$svc" || continue;
        if test "$enabled" = enabled; then
            systemctl enable "$svc" > /dev/null 2>&1 || true;
        else
            systemctl disable "$svc" > /dev/null 2>&1 || true;
        fi;
        if test "$active" = active; then
            systemctl restart "$svc" > /dev/null 2>&1 || true;
        else
            systemctl stop "$svc" > /dev/null 2>&1 || true;
        fi;
    done < "$in"
}
# EEX3-FUNCTION warp_e136_140 _e136_service_state_snapshot
_e136_service_state_snapshot() {
    local out="$1" svc;
    : > "$out" || return 1;
    for svc in xray-accel-e125.service xray-accel-e126.service xray-hw-tweaks.service nic-optimize.service rps-optimize.service txqueue.service;
    do
        printf '%s|%s|%s\n' "$svc" "$(systemctl is-enabled "$svc" 2> /dev/null || true)" "$(systemctl is-active "$svc" 2> /dev/null || true)" >> "$out";
    done
}
# EEX3-FUNCTION warp_e136_140 _e136_strip_sysctl_file
_e136_strip_sysctl_file() {
    local keys="$1" src="$2" out="$3";
    awk '
      NR==FNR {managed[$1]=1; next}
      {
        raw=$0; s=$0
        sub(/^[[:space:]]*/, "", s)
        if (s ~ /^#/ || s == "") {print raw; next}
        p=index(s, "=")
        if (p>0) {
          key=substr(s,1,p-1)
          gsub(/[[:space:]]/, "", key)
          if (key in managed) next
        }
        print raw
      }
    ' "$keys" "$src" > "$out"
}
