# EEX3-FUNCTION warp_e136_140 _e136_warp_preflight
_e136_warp_preflight() {
    test "$EUID" -eq 0 || { 
        error "WARP管理必须使用root。";
        return 1
    };
    command -v systemctl > /dev/null 2>&1 || { 
        error "缺少systemd。";
        return 1
    };
    local c;
    for c in bash curl jq ip ss awk sed grep install tar;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "WARP预检缺少命令：$c";
            return 1
        };
    done;
    test -r "$SCRIPT_PATH" || { 
        error "当前脚本不可读。";
        return 1
    };
    return 0
}
