# EEX3-FUNCTION warp_e136_140 _e137_mss_apply_base2
_e137_mss_apply_base2() {
    local rc=0;
    _e137_mss_base || rc=1;
    test "$rc" -eq 0 || return 1;
    sed -i '/^[[:space:]]*RemainAfterExit=/d' /etc/systemd/system/xray-mss-clamp-e88.service || return 1;
    cat > "$E137_MSS_TIMER" <<'EOF_E137_MSS_TIMER'
[Unit]
Description=Periodic MSS Clamp rule reconciliation E137
[Timer]
OnBootSec=1min
OnUnitInactiveSec=5min
Persistent=true
Unit=xray-mss-clamp-e88.service
[Install]
WantedBy=timers.target
EOF_E137_MSS_TIMER

    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl stop xray-mss-clamp-e88.service > /dev/null 2>&1 || true;
    systemctl start xray-mss-clamp-e88.service > /dev/null 2>&1 || return 1;
    systemctl enable --now xray-mss-clamp-e137.timer > /dev/null 2>&1 || return 1;
    iptables -w 5 -t mangle -C POSTROUTING -j XRAY_MSS_CLAMP > /dev/null 2>&1 || return 1;
    info "MSS Clamp已改为可重复oneshot并由5分钟timer校验。"
}
# EEX3-FUNCTION warp_e136_140 _e137_mss_base
_e137_mss_base() {
    local snapshot="" script=/usr/local/bin/xray-mss-clamp-e88.sh unit=/etc/systemd/system/xray-mss-clamp-e88.service failed=0;
    command -v iptables > /dev/null 2>&1 || { 
        error "缺少iptables，不能启用MSS Clamp。";
        return 1
    };
    command -v iptables-save > /dev/null 2>&1 && snapshot=$(_e118_mktemp mss-before.rules) || true;
    test -z "$snapshot" || iptables-save > "$snapshot" 2> /dev/null || snapshot="";
    cat > "$script" <<'EOF_E136_MSS_SCRIPT'
#!/usr/bin/env bash
set -euo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
modprobe iptable_mangle >/dev/null 2>&1 || true
modprobe xt_TCPMSS >/dev/null 2>&1 || true
iptables -w 5 -t mangle -N XRAY_MSS_CLAMP 2>/dev/null || true
iptables -w 5 -t mangle -F XRAY_MSS_CLAMP
iptables -w 5 -t mangle -A XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
iptables -w 5 -t mangle -C POSTROUTING -j XRAY_MSS_CLAMP 2>/dev/null || iptables -w 5 -t mangle -A POSTROUTING -j XRAY_MSS_CLAMP
iptables -w 5 -t mangle -C POSTROUTING -j XRAY_MSS_CLAMP
iptables -w 5 -t mangle -C XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
EOF_E136_MSS_SCRIPT

    chmod 0755 "$script" || failed=1;
    if test "$failed" = 0; then
        cat > "$unit" <<EOF_E136_MSS_UNIT
[Unit]
Description=Xray E136 verified IPv4 MSS Clamp restore
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$script
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF_E136_MSS_UNIT

        systemctl daemon-reload > /dev/null 2>&1 || failed=1;
        test "$failed" != 0 || systemctl enable --now xray-mss-clamp-e88.service > /dev/null 2>&1 || failed=1;
        test "$failed" != 0 || systemctl is-active --quiet xray-mss-clamp-e88.service || failed=1;
        test "$failed" != 0 || iptables -w 5 -t mangle -C POSTROUTING -j XRAY_MSS_CLAMP > /dev/null 2>&1 || failed=1;
        test "$failed" != 0 || iptables -w 5 -t mangle -C XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1 || failed=1;
    fi;
    if test "$failed" != 0; then
        error "MSS Clamp应用/读回失败，恢复原防火墙。";
        test -s "$snapshot" && command -v iptables-restore > /dev/null 2>&1 && iptables-restore < "$snapshot" || true;
        systemctl disable --now xray-mss-clamp-e88.service > /dev/null 2>&1 || true;
        rm -f "$unit" "$script" 2> /dev/null || true;
        systemctl daemon-reload > /dev/null 2>&1 || true;
        return 1;
    fi;
    echo "ON" > "$E88_MSS_STATE_FILE";
    info "MSS Clamp已启用，规则与开机恢复服务均通过读回验证。"
}
# EEX3-FUNCTION warp_e136_140 _e137_norm_mask
_e137_norm_mask() {
    tr -d ',[:space:]' | sed 's/^0*//;s/^$/0/' | tr 'A-F' 'a-f'
}
# EEX3-FUNCTION warp_e136_140 _e137_normalize_ignore_tokens
_e137_normalize_ignore_tokens() {
    tr ',[]' '   ' | tr -d "'\"" | xargs -n1 2> /dev/null | grep -E '^([0-9A-Fa-f:.%]+(/[0-9]{1,3})?|[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?|file:/[^[:space:]#;=]+)$' || true
}
# EEX3-FUNCTION warp_e136_140 _e137_offload_apply_base
_e137_offload_apply_base() {
    local pattern="${1:-OOOX}" tx failed=0;
    pattern=$(printf '%s' "$pattern" | tr '[:lower:]' '[:upper:]' | tr -cd OX);
    [[ "$pattern" =~ ^[OX]{4}$ ]] || { 
        error "Offload模式必须是4位O/X。";
        return 1
    };
    _e137_prepare || return 1;
    tx="$E137_BACKUP_DIR/offload-$(date +%Y%m%d_%H%M%S)-$$";
    mkdir -p "$tx" || return 1;
    for p in "$E137_OFFLOAD_SCRIPT" "$E137_OFFLOAD_SERVICE" "$E137_OFFLOAD_TIMER" "$E88_OFFLOAD_STATE_FILE";
    do
        _e135_snapshot_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || return 1;
    done;
    cat > "$E137_OFFLOAD_SCRIPT" <<EOF_E137_OFFLOAD_SCRIPT
#!/usr/bin/env bash
set -euo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
exec "$SYMLINK" --offload-restore "$pattern"
EOF_E137_OFFLOAD_SCRIPT

    chmod 0755 "$E137_OFFLOAD_SCRIPT" || failed=1;
    cat > "$E137_OFFLOAD_SERVICE" <<EOF_E137_OFFLOAD_SERVICE
[Unit]
Description=Verified dynamic-interface offload restore E137
After=network-online.target
Wants=network-online.target
[Service]
Type=oneshot
ExecStart=$E137_OFFLOAD_SCRIPT
EOF_E137_OFFLOAD_SERVICE

    cat > "$E137_OFFLOAD_TIMER" <<'EOF_E137_OFFLOAD_TIMER'
[Unit]
Description=Periodic offload drift check E137
[Timer]
OnBootSec=1min
OnUnitInactiveSec=5min
Persistent=true
[Install]
WantedBy=timers.target
EOF_E137_OFFLOAD_TIMER

    test "$failed" -ne 0 || _e137_offload_apply_runtime "$pattern" || failed=1;
    test "$failed" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || failed=1;
    test "$failed" -ne 0 || systemctl enable --now xray-offload-e137.timer > /dev/null 2>&1 || failed=1;
    if test "$failed" -ne 0; then
        error "Offload无法完整读回，恢复旧持久化文件；不报告成功。";
        for p in "$E137_OFFLOAD_SCRIPT" "$E137_OFFLOAD_SERVICE" "$E137_OFFLOAD_TIMER" "$E88_OFFLOAD_STATE_FILE";
        do
            _e135_restore_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || true;
        done;
        systemctl daemon-reload > /dev/null 2>&1 || true;
        return 1;
    fi;
    printf '%s\n' "$pattern" > "$E88_OFFLOAD_STATE_FILE" || return 1;
    systemctl disable --now xray-offload-e88.service > /dev/null 2>&1 || true;
    info "Offload=$pattern已逐项读回并启用动态网卡漂移检查。"
}
# EEX3-FUNCTION warp_e136_140 _e137_offload_apply_runtime
_e137_offload_apply_runtime() {
    local pattern="$1" iface gro gso tso lro actual key target;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    command -v ethtool > /dev/null 2>&1 || return 1;
    gro=$([ "${pattern:0:1}" = O ] && echo on || echo off);
    gso=$([ "${pattern:1:1}" = O ] && echo on || echo off);
    tso=$([ "${pattern:2:1}" = O ] && echo on || echo off);
    lro=$([ "${pattern:3:1}" = O ] && echo on || echo off);
    ethtool -K "$iface" gro "$gro" gso "$gso" tso "$tso" lro "$lro" > /dev/null 2>&1 || true;
    for key in generic-receive-offload generic-segmentation-offload tcp-segmentation-offload large-receive-offload;
    do
        case "$key" in 
            generic-receive-offload)
                target=$gro
            ;;
            generic-segmentation-offload)
                target=$gso
            ;;
            tcp-segmentation-offload)
                target=$tso
            ;;
            *)
                target=$lro
            ;;
        esac;
        actual=$(_e137_offload_get "$iface" "$key");
        test "$actual" = "$target" || return 1;
    done
}
# EEX3-FUNCTION warp_e136_140 _e137_offload_current_pattern
_e137_offload_current_pattern() {
    local iface val out="" key;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    for key in generic-receive-offload generic-segmentation-offload tcp-segmentation-offload large-receive-offload;
    do
        val=$(_e137_offload_get "$iface" "$key");
        case "$val" in 
            on)
                out+="O"
            ;;
            off)
                out+="X"
            ;;
            *)
                return 1
            ;;
        esac;
    done;
    printf '%s\n' "$out"
}
# EEX3-FUNCTION warp_e136_140 _e137_offload_get
_e137_offload_get() {
    local iface="$1" key="$2";
    ethtool -k "$iface" 2> /dev/null | awk -F: -v k="$key" '$1~"^[[:space:]]*"k"[[:space:]]*$"{gsub(/[[:space:]]/,"",$2);print $2;exit}'
}
# EEX3-FUNCTION warp_e136_140 _e137_pause
_e137_pause() {
    local _p="";
    read -rp "按 Enter 继续..." _p || true
}
# EEX3-FUNCTION warp_e136_140 _e137_prepare
_e137_prepare() {
    mkdir -p "$E137_DIR" "$E137_BACKUP_DIR" "$SCRIPT_DIR" "$LOG_DIR" || return 1
}
# EEX3-FUNCTION warp_e136_140 _e137_ring_apply_base
_e137_ring_apply_base() {
    local failed=0;
    _e137_prepare || return 1;
    cat > "$E137_RING_SCRIPT" <<EOF_E137_RING_SCRIPT
#!/usr/bin/env bash
set -euo pipefail
exec "$SYMLINK" --ring-restore
EOF_E137_RING_SCRIPT

    chmod 0755 "$E137_RING_SCRIPT" || failed=1;
    cat > "$E137_RING_SERVICE" <<EOF_E137_RING_SERVICE
[Unit]
Description=Dynamic-interface adaptive Ring restore E137
After=network-online.target
Wants=network-online.target
[Service]
Type=oneshot
ExecStart=$E137_RING_SCRIPT
EOF_E137_RING_SERVICE

    cat > "$E137_RING_TIMER" <<'EOF_E137_RING_TIMER'
[Unit]
Description=Periodic Ring drift check E137
[Timer]
OnBootSec=1min
OnUnitInactiveSec=5min
Persistent=true
[Install]
WantedBy=timers.target
EOF_E137_RING_TIMER

    test "$failed" -ne 0 || _e137_ring_apply_runtime || failed=1;
    test "$failed" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || failed=1;
    test "$failed" -ne 0 || systemctl enable --now xray-ring-e137.timer > /dev/null 2>&1 || failed=1;
    test "$failed" -eq 0 || { 
        error "Ring应用/读回失败。";
        return 1
    };
    systemctl disable --now xray-ring-e136.service > /dev/null 2>&1 || true;
    info "Ring已按当前默认IPv4出口网卡硬件上限读回验证。"
}
# EEX3-FUNCTION warp_e136_140 _e137_ring_apply_runtime
_e137_ring_apply_runtime() {
    local iface maxrx maxtx currx currtx;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    ethtool -g "$iface" > /dev/null 2>&1 || return 1;
    maxrx=$(_ring_max_rx_e52 "$iface");
    maxtx=$(_ring_max_tx_e52 "$iface");
    [[ "$maxrx" =~ ^[0-9]+$ ]] || return 1;
    if [[ "$maxtx" =~ ^[0-9]+$ ]] && ethtool -G "$iface" rx "$maxrx" tx "$maxtx" > /dev/null 2>&1; then
        :;
    else
        ethtool -G "$iface" rx "$maxrx" > /dev/null 2>&1 || return 1;
    fi;
    currx=$(_ring_cur_rx_e52 "$iface");
    currtx=$(_ring_cur_tx_e52 "$iface");
    test "$currx" = "$maxrx" || return 1;
    printf '%s\n' "$currx" > "$CONFIG_DIR/ring_target_rx.txt";
    printf '%s\n' "${currtx:-unchanged}" > "$CONFIG_DIR/ring_target_tx.txt"
}
# EEX3-FUNCTION warp_e136_140 _e137_rps_apply_base
_e137_rps_apply_base() {
    local failed=0;
    _e137_prepare || return 1;
    cat > "$E137_RPS_SCRIPT" <<EOF_E137_RPS_SCRIPT
#!/usr/bin/env bash
set -euo pipefail
exec "$SYMLINK" --rps-restore
EOF_E137_RPS_SCRIPT

    chmod 0755 "$E137_RPS_SCRIPT" || failed=1;
    cat > "$E137_RPS_SERVICE" <<EOF_E137_RPS_SERVICE
[Unit]
Description=Verified dynamic-interface RPS/RFS restore E137
After=network-online.target
Wants=network-online.target
[Service]
Type=oneshot
ExecStart=$E137_RPS_SCRIPT
EOF_E137_RPS_SERVICE

    cat > "$E137_RPS_TIMER" <<'EOF_E137_RPS_TIMER'
[Unit]
Description=Periodic RPS/RFS drift check E137
[Timer]
OnBootSec=1min
OnUnitInactiveSec=5min
Persistent=true
[Install]
WantedBy=timers.target
EOF_E137_RPS_TIMER

    test "$failed" -ne 0 || _e137_rps_apply_runtime || failed=$?;
    if test "$failed" = 2; then
        info "单核CPU无需RPS/RFS。";
        return 0;
    fi;
    test "$failed" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || failed=1;
    test "$failed" -ne 0 || systemctl enable --now xray-rps-rfs-e137.timer > /dev/null 2>&1 || failed=1;
    test "$failed" -eq 0 || { 
        error "RPS/RFS未能对全部默认网卡RX队列读回，未报告成功。";
        return 1
    };
    systemctl disable --now xray-rps-rfs-e88.service > /dev/null 2>&1 || true;
    info "RPS/RFS已对默认IPv4出口网卡全部RX队列读回验证。"
}
# EEX3-FUNCTION warp_e136_140 _e137_rps_apply_runtime
_e137_rps_apply_runtime() {
    local cpus mask flow perq iface q actual touched=0;
    cpus=$(nproc 2> /dev/null || echo 1);
    test "$cpus" -gt 1 || return 2;
    mask=$(_e137_cpu_mask "$cpus") || return 1;
    flow=$((4096*cpus));
    perq=$((flow/cpus));
    echo "$flow" > /proc/sys/net/core/rps_sock_flow_entries || return 1;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    for q in /sys/class/net/"$iface"/queues/rx-*/rps_cpus;
    do
        test -f "$q" || continue;
        touched=$((touched+1));
        echo "$mask" > "$q" || return 1;
        actual=$(cat "$q" | _e137_norm_mask);
        test "$actual" = "$(printf '%s' "$mask" | _e137_norm_mask)" || return 1;
        test ! -f "$(dirname "$q")/rps_flow_cnt" || echo "$perq" > "$(dirname "$q")/rps_flow_cnt" || return 1;
    done;
    test "$touched" -gt 0
}
# EEX3-FUNCTION warp_e136_140 _e137_rps_restore_runtime
_e137_rps_restore_runtime() {
    local dir="$1" path value;
    test -s "$dir/flow" && cat "$dir/flow" > /proc/sys/net/core/rps_sock_flow_entries 2> /dev/null || true;
    while IFS='|' read -r path value; do
        test -f "$path" && printf '%s\n' "$value" > "$path" 2> /dev/null || true;
    done < "$dir/queues"
}
# EEX3-FUNCTION warp_e136_140 _e137_rps_snapshot_runtime
_e137_rps_snapshot_runtime() {
    local dir="$1" iface q;
    mkdir -p "$dir" || return 1;
    cat /proc/sys/net/core/rps_sock_flow_entries > "$dir/flow" 2> /dev/null || : > "$dir/flow";
    iface=$(_e137_default_iface);
    printf '%s\n' "$iface" > "$dir/iface";
    : > "$dir/queues";
    for q in /sys/class/net/"$iface"/queues/rx-*/rps_cpus /sys/class/net/"$iface"/queues/rx-*/rps_flow_cnt;
    do
        test -f "$q" || continue;
        printf '%s|%s\n' "$q" "$(cat "$q" 2> /dev/null || true)" >> "$dir/queues";
    done
}
# EEX3-FUNCTION warp_e136_140 _e137_self_test
_e137_self_test() {
    local rc=0 tmp base cand body got;
    echo "V199e137 behavior gate:";
    test "$SCRIPT_VERSION" = 199e137 && test "$E137_VERSION" = 199e137 && echo "  [PASS] version" || { 
        echo "  [FAIL] version";
        rc=1
    };
    got="$(for s in 1 2 3 4;
do
    printf '%s:%s ' "$s" "$(_e137_mode_internal "$s" 2> /dev/null || echo x)";
done)";
    test "$got" = "1:1 2:4 3:2 4:3 " && echo "  [PASS] semantic install mode map" || { 
        echo "  [FAIL] semantic install mode map: $got";
        rc=1
    };
    tmp=$(mktemp -d /tmp/e137-selftest.XXXXXX) || return 1;
    base="$tmp/base.json";
    cand="$tmp/cand.json";
    cat > "$base" <<'JSON_E137_TEST'
{"outbounds":[{"tag":"direct","protocol":"freedom","settings":{}}],"routing":{"rules":[]},"inbounds":[]}
JSON_E137_TEST

    if _e137_warp_config_build google-core true "$cand" "$base" && jq -e --arg w "$E137_WARP_TAG" --arg b "$E137_WARP_BLOCK_TAG" '
         ([.outbounds[]|select(.tag==$w and .settings.address=="127.0.0.1" and .settings.port==40000)]|length)==1 and
         ([.routing.rules[]|select(.outboundTag==$w and .network=="tcp")]|length)==1 and
         ([.routing.rules[]|select(.outboundTag==$b and .network=="udp")]|length)==1
       ' "$cand" > /dev/null; then
        echo "  [PASS] WARP Xray build";
    else
        echo "  [FAIL] WARP Xray build";
        rc=1;
    fi;
    if _e137_warp_config_build disabled false "$tmp/removed.json" "$cand" && jq -e --arg w "$E137_WARP_TAG" --arg b "$E137_WARP_BLOCK_TAG" '
         (all(.outbounds[]?; .tag!=$w and .tag!=$b)) and
         (all(.routing.rules[]?; .outboundTag!=$w and .outboundTag!=$b))
       ' "$tmp/removed.json" > /dev/null; then
        echo "  [PASS] WARP Xray removal";
    else
        echo "  [FAIL] WARP Xray removal";
        rc=1;
    fi;
    body=$(declare -f _e137_warp_health_check);
    [[ "$body" == *'_e137_warp_config_integrity'* && "$body" == *'_e137_xray_apply_warp_route'* && "$body" == *'disconnect'* ]] && echo "  [PASS] WARP proxy+Xray reconciliation" || { 
        echo "  [FAIL] WARP reconciliation";
        rc=1
    };
    body=$(declare -f _e118_write_generated_metadata);
    [[ "$body" == *'version=$E137_VERSION'* && "$body" == *'mode_semantic'* && "$body" != *'version=199e131'* ]] && echo "  [PASS] metadata convergence" || { 
        echo "  [FAIL] metadata convergence";
        rc=1
    };
    body=$(declare -f _e137_write_init_window_units);
    [[ "$body" == *'CWND=30'* && "$body" == *'RWND=30'* && "$body" != *'RemainAfterExit'* ]] && echo "  [PASS] repeatable init30 unit" || { 
        echo "  [FAIL] init30 unit";
        rc=1
    };
    body=$(declare -f _e137_install_self);
    [[ "$body" == *'_e135_snapshot_file'* && "$body" == *'_e135_restore_file'* && "$body" == *'E137_LATEST_PATH'* ]] && echo "  [PASS] three-target self-install transaction" || { 
        echo "  [FAIL] self-install transaction";
        rc=1
    };
    body=$(declare -f _e135_xanmod_source_build);
    [[ "$body" != *'make defconfig'* && "$body" == *'return 0'* && "$body" == *'/proc/config.gz'* ]] && echo "  [PASS] XanMod safe config source/return" || { 
        echo "  [FAIL] XanMod safe path";
        rc=1
    };
    body=$(declare -f _e88_apply_offload_profile);
    [[ "$body" == *'_e137_offload_apply_base'* && "$body" == *'_e137_offload_current_pattern'* ]] && echo "  [PASS] Offload verified transaction" || { 
        echo "  [FAIL] Offload transaction";
        rc=1
    };
    body=$(declare -f _e88_apply_rps_rfs);
    [[ "$body" == *'_e137_rps_snapshot_runtime'* && "$body" == *'_e137_rps_restore_runtime'* ]] && echo "  [PASS] RPS/RFS verified transaction" || { 
        echo "  [FAIL] RPS/RFS transaction";
        rc=1
    };
    body=$(declare -f _e88_set_txqueuelen);
    [[ "$body" == *'_e137_txq_apply_base'* && "$body" == *'txqueuelen'* && "$body" == *'_e135_restore_file'* ]] && echo "  [PASS] TX Queue verified transaction" || { 
        echo "  [FAIL] TX Queue transaction";
        rc=1
    };
    body=$(declare -f apply_ring_max_adaptive_default);
    [[ "$body" == *'_e137_ring_apply_base'* && "$body" == *'oldrx'* && "$body" == *'_e135_restore_file'* ]] && echo "  [PASS] dynamic Ring transaction" || { 
        echo "  [FAIL] Ring transaction";
        rc=1
    };
    body=$(declare -f _e88_mss_clamp_on);
    [[ "$body" == *'_e137_mss_apply_base2'* && "$body" == *'iptables-restore'* && "$body" == *'_e135_restore_file'* ]] && echo "  [PASS] repeatable MSS transaction" || { 
        echo "  [FAIL] MSS transaction";
        rc=1
    };
    body=$(declare -f install_update_dat);
    [[ "$body" == *'_e137_existing_dat_valid'* && "$body" == *'降级成功'* ]] && echo "  [PASS] DAT degraded-success semantics" || { 
        echo "  [FAIL] DAT semantics";
        rc=1
    };
    body=$(declare -f _e135_patch_fail2ban_ignoreip);
    [[ "$body" == *'fail2ban-client get'* && "$body" == *'runtime_values'* ]] && echo "  [PASS] Fail2ban runtime ignore inheritance" || { 
        echo "  [FAIL] Fail2ban ignore inheritance";
        rc=1
    };
    body=$(declare -f hot_update_from_legacy);
    [[ "$body" == *'_e135_system_snapshot'* && "$body" == *'_e135_system_restore'* && "$body" == *'_e137_warp_config_integrity'* ]] && echo "  [PASS] E137 hot-update rollback chain" || { 
        echo "  [FAIL] hot-update chain";
        rc=1
    };
    got=$(_e137_cpu_mask 64 2> /dev/null || true);
    test "$got" = "ffffffff,ffffffff" && echo "  [PASS] 64-core cpumask" || { 
        echo "  [FAIL] 64-core cpumask=$got";
        rc=1
    };
    rm -rf "$tmp";
    echo "V199e137 result: $(test "$rc" = 0 && echo PASS || echo FAIL)";
    return "$rc"
}
# EEX3-FUNCTION warp_e136_140 _e137_ssh_backend_supported
_e137_ssh_backend_supported() {
    local backend;
    backend=$(_e152_firewall_backend 2> /dev/null || echo none);
    case "$backend" in 
        ufw | firewalld | iptables | nft)
            return 0
        ;;
        *)
            error "未发现可验证的UFW、firewalld、iptables或原生nftables后端。";
            return 1
        ;;
    esac
}
# EEX3-FUNCTION warp_e136_140 _e137_ssh_guard_base
_e137_ssh_guard_base() {
    local ip ports current_port f2b_backup="" ip4="" ip6="" failed=0;
    _e135_prepare || return 1;
    title "V199e137：SSH端口自适应 + fail2ban防自锁";
    command -v sshd > /dev/null 2>&1 || { 
        error "未检测到OpenSSH sshd。";
        return 1
    };
    sshd -t > "$E118_TMPDIR/sshd-e135.log" 2>&1 || { 
        error "sshd_config语法错误，拒绝变更。";
        sed 's/^/    /' "$E118_TMPDIR/sshd-e135.log";
        return 1
    };
    ports=$(_e135_detect_ssh_ports | xargs echo);
    test -n "$ports" || ports=22;
    ip=$(_e135_current_ssh_ip);
    current_port=$(_e135_current_ssh_port);
    echo "  sshd -T/sshd_config.d/监听端口合并结果: $ports";
    echo "  当前SSH会话端口: ${current_port:-控制台/未知}";
    echo "  当前SSH客户端IP: ${ip:-控制台/未知}";
    test -z "$current_port" || grep -qw "$current_port" <<< "$ports" || { 
        error "当前会话端口未进入放行集合，拒绝继续。";
        return 1
    };
    command -v iptables-save > /dev/null 2>&1 && { 
        ip4=$(_e118_mktemp iptables-e135.rules);
        iptables-save > "$ip4" || ip4=""
    };
    command -v ip6tables-save > /dev/null 2>&1 && { 
        ip6=$(_e118_mktemp ip6tables-e135.rules);
        ip6tables-save > "$ip6" || ip6=""
    };
    declare -F _e121_backup_fail2ban_state > /dev/null 2>&1 && f2b_backup=$(_e121_backup_fail2ban_state 2> /dev/null || true);
    _e135_ssh_guard_base || failed=1;
    test "$failed" -ne 0 || _e135_patch_fail2ban_ignoreip "$ip" || failed=1;
    if test "$failed" -eq 0; then
        _e121_verify_ssh_port_guard || failed=1;
        _e121_verify_fail2ban_runtime || failed=1;
    fi;
    if test "$failed" -ne 0; then
        error "SSH防护应用失败，恢复Fail2ban和防火墙快照。";
        test -n "$f2b_backup" && _e121_restore_fail2ban_state "$f2b_backup" > /dev/null 2>&1 || true;
        test -s "$ip4" && command -v iptables-restore > /dev/null 2>&1 && iptables-restore < "$ip4" || true;
        test -s "$ip6" && command -v ip6tables-restore > /dev/null 2>&1 && ip6tables-restore < "$ip6" || true;
        return 1;
    fi;
    info "SSH认证失败策略：24小时内第2次触发，封禁36小时。";
    test -z "$ip" || info "当前会话IP已加入ignoreip并执行unban：$ip";
    info "当前sshd有效端口已从sshd -T、配置文件、Include和监听socket交叉确认：$ports"
}
# EEX3-FUNCTION warp_e136_140 _e137_state_get
_e137_state_get() {
    local key="$1" def="${2:-}";
    local val;
    val=$(sed -n "s/^${key}=//p" "$E137_WARP_STATE" 2> /dev/null | tail -n1);
    printf '%s\n' "${val:-$def}"
}
# EEX3-FUNCTION warp_e136_140 _e137_state_write
_e137_state_write() {
    local enabled="$1" profile="$2" tmp;
    _e137_prepare || return 1;
    tmp=$(_e118_mktemp warp-state-e137) || return 1;
    { 
        echo "managed_by=e137";
        echo "route_enabled=$enabled";
        echo "profile=$profile";
        echo "port=$E137_WARP_PORT";
        echo "updated=$(date -Is 2> /dev/null || date)"
    } > "$tmp" || return 1;
    install -m 0600 "$tmp" "$E137_WARP_STATE" || return 1
}
