# EEX3-FUNCTION warp_e136_140 _e137_system_snapshot_base
_e137_system_snapshot_base() {
    local b="$1" p rel;
    mkdir -p "$b" || return 1;
    : > "$b/present.list";
    : > "$b/absent.list";
    : > "$b/runtime-sysctl.env";
    while IFS= read -r p; do
        test -n "$p" || continue;
        rel=${p#/};
        if test -e "$p" || test -L "$p"; then
            echo "$rel" >> "$b/present.list";
        else
            echo "$rel" >> "$b/absent.list";
        fi;
    done < <(_e135_system_paths);
    if test -s "$b/present.list"; then
        tar -C / -cpf "$b/files.tar" -T "$b/present.list" || return 1;
    fi;
    while IFS= read -r p; do
        printf '%s|%s\n' "$p" "$(sysctl -n "$p" 2> /dev/null || true)" >> "$b/runtime-sysctl.env";
    done < <(_e135_network_keys);
    command -v iptables-save > /dev/null 2>&1 && iptables-save > "$b/iptables.rules" 2> /dev/null || true;
    command -v ip6tables-save > /dev/null 2>&1 && ip6tables-save > "$b/ip6tables.rules" 2> /dev/null || true;
    for p in xray.service fail2ban.service xray-dat-update.timer vnstat.service xray-hw-tweaks.service nic-optimize.service rps-optimize.service txqueue.service xray-accel-e125.service xray-accel-e126.service;
    do
        _e159_snapshot_service "$p" >> "$b/services.env" || return 1;
    done
}
# EEX3-FUNCTION warp_e136_140 _e137_txq_apply_base
