    cat > "$E137_TXQ_TIMER" <<'EOF_E137_TXQ_TIMER'
[Unit]
Description=Periodic TX queue drift check E137
[Timer]
OnBootSec=1min
OnUnitInactiveSec=5min
Persistent=true
[Install]
WantedBy=timers.target
