    test "$failed" -ne 0 || _e137_txq_apply_runtime "$value" || failed=1;
    test "$failed" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || failed=1;
    test "$failed" -ne 0 || systemctl enable --now xray-txqueue-e137.timer > /dev/null 2>&1 || failed=1;
    test "$failed" -eq 0 || { 
        error "TX Queue应用/读回失败。";
        return 1
    };
    systemctl disable --now txqueue.service > /dev/null 2>&1 || true;
    info "txqueuelen=$value已读回验证并使用动态出口网卡恢复。"
}
# EEX3-FUNCTION warp_e136_140 _e137_txq_apply_runtime
_e137_txq_apply_runtime() {
    local value="$1" iface actual;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    ip link set dev "$iface" txqueuelen "$value" || return 1;
    actual=$(ip -o link show dev "$iface" | sed -n 's/.* qlen \([0-9]\+\).*/\1/p');
    test "$actual" = "$value"
}
