# EEX3-FUNCTION warp_e136_140 _e137_warp_enable_profile
_e137_warp_enable_profile() {
    local profile="${1:-google-meta-core}" confirm tx route_before was_active=0 preinstalled=0 managed failed=0;
    title "V199e137：启用WARP本地代理与Xray定向分流";
    warn "不会启用全局WARP；SSH、Xray入站和系统默认流量继续走原IPv4。";
    dpkg-query -W -f='${Status}' cloudflare-warp 2> /dev/null | grep -q 'install ok installed' && preinstalled=1 || true;
    managed=$(_e137_state_get managed_by "");
    if test "$preinstalled" = 1 && test -z "$managed" && test ! -s "${E136_WARP_STATE:-/nonexistent}"; then
        error "检测到非本脚本管理的WARP，拒绝覆盖其账户和模式。";
        return 1;
    fi;
    read -rp "输入 ENABLE-WARP 确认: " confirm || true;
    test "$confirm" = ENABLE-WARP || return 0;
    _e137_prepare || return 1;
    tx="$E137_BACKUP_DIR/warp-enable-$(date +%Y%m%d_%H%M%S)-$$";
    mkdir -p "$tx" || return 1;
    for p in "$CONFIG" "$E137_WARP_STATE" "$E137_WARP_HEALTH_SERVICE" "$E137_WARP_HEALTH_TIMER";
    do
        _e135_snapshot_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || return 1;
    done;
    systemctl is-active --quiet xray.service 2> /dev/null && was_active=1 || true;
    route_before=$(_e136_warp_route4);
    test -n "$route_before" || return 1;
    if ! _e136_warp_install_package "$tx" || ! _e137_warp_connect_local_proxy || ! _e137_xray_apply_warp_route "$profile" true || ! _e137_warp_health_install; then
        failed=1;
    fi;
    test "$failed" -ne 0 || test "$route_before" = "$(_e136_warp_route4)" || failed=1;
    test "$failed" -ne 0 || _e137_warp_proxy_ready || failed=1;
    test "$failed" -ne 0 || _e137_warp_config_integrity "$profile" || failed=1;
    if test "$failed" -ne 0; then
        error "WARP启用/路由保护验证失败，执行完整回滚。";
        _e136_warp_cli disconnect > /dev/null 2>&1 || true;
        for p in "$CONFIG" "$E137_WARP_STATE" "$E137_WARP_HEALTH_SERVICE" "$E137_WARP_HEALTH_TIMER";
        do
            _e135_restore_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || true;
        done;
        systemctl daemon-reload > /dev/null 2>&1 || true;
        test "$was_active" -eq 0 || systemctl restart xray.service > /dev/null 2>&1 || true;
        _e136_warp_install_rollback "$tx" || true;
        return 1;
    fi;
    info "WARP定向分流已启用并通过代理、Xray规则和IPv4路由一致性验证：$profile。";
    _e137_warp_status
}
