# EEX3-FUNCTION warp_e136_140 _e137_write_init_window_units
_e137_write_init_window_units() {
    cat > "$E137_INIT_SCRIPT" <<'EOF_E137_INIT_SCRIPT'
#!/usr/bin/env bash
set -euo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
CWND=30
RWND=30
route=$(ip -4 route show default 2>/dev/null | head -n1)
[ -n "$route" ] || exit 1
clean=$(printf '%s\n' "$route" | sed -E 's/[[:space:]]+initcwnd[[:space:]]+[0-9]+//g;s/[[:space:]]+initrwnd[[:space:]]+[0-9]+//g')
ip -4 route replace $clean initcwnd "$CWND" initrwnd "$RWND"
now=$(ip -4 route show default 2>/dev/null | head -n1)
printf '%s\n' "$now" | grep -Eq '(^|[[:space:]])initcwnd[[:space:]]+30([[:space:]]|$)'
printf '%s\n' "$now" | grep -Eq '(^|[[:space:]])initrwnd[[:space:]]+30([[:space:]]|$)'
EOF_E137_INIT_SCRIPT

    chmod 0755 "$E137_INIT_SCRIPT" || return 1
    cat > "$E137_INIT_SERVICE" <<EOF_E137_INIT_SERVICE
[Unit]
Description=Verify and restore initcwnd/initrwnd=30 E137
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$E137_INIT_SCRIPT
EOF_E137_INIT_SERVICE

    cat > "$E137_INIT_TIMER" <<'EOF_E137_INIT_TIMER'
[Unit]
Description=Periodic initcwnd/initrwnd=30 drift check E137

[Timer]
OnBootSec=45s
OnUnitInactiveSec=5min
Persistent=true

[Install]
WantedBy=timers.target
EOF_E137_INIT_TIMER

}
# EEX3-FUNCTION warp_e136_140 _e137_xray_apply_warp_route
_e137_xray_apply_warp_route() {
    local profile="${1:-google-meta-core}" enable="${2:-true}" tx cand was_active=0 failed=0;
    _e137_prepare || return 1;
    test -x "$XRAY_BIN" && test -s "$CONFIG" || { 
        error "Xray尚未安装或配置不存在。";
        return 1
    };
    test "$enable" != true || _e137_warp_proxy_ready || { 
        error "WARP本地代理未就绪。";
        return 1
    };
    tx="$E137_BACKUP_DIR/warp-route-$(date +%Y%m%d_%H%M%S)-$$";
    mkdir -p "$tx" || return 1;
    _e135_snapshot_file "$CONFIG" "$tx/config" || return 1;
    _e135_snapshot_file "$E137_WARP_STATE" "$tx/state" || return 1;
    cand=$(_e118_mktemp xray-warp-e137.json) || return 1;
    _e137_warp_config_build "$profile" "$enable" "$cand" "$CONFIG" || return 1;
    _e118_xray_test_config "$cand" 1 || { 
        error "WARP候选配置未通过Xray测试。";
        return 1
    };
    systemctl is-active --quiet xray.service 2> /dev/null && was_active=1 || true;
    install -m 0600 "$cand" "$CONFIG" || failed=1;
    test "$failed" -ne 0 || fix_permissions;
    if test "$failed" -eq 0 && test "$was_active" -eq 1; then
        systemctl restart xray.service > /dev/null 2>&1 || failed=1;
        test "$failed" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || failed=1;
    fi;
    if test "$failed" -eq 0 && test "$enable" = true; then
        _e137_warp_config_integrity "$profile" || failed=1;
    fi;
    if test "$failed" -eq 0; then
        if test "$enable" = true; then
            _e137_state_write 1 "$profile" || failed=1;
        else
            _e137_state_write 0 disabled || failed=1;
        fi;
    fi;
    if test "$failed" -ne 0; then
        error "WARP路由事务失败，恢复Xray配置和状态。";
        _e135_restore_file "$CONFIG" "$tx/config" || true;
        _e135_restore_file "$E137_WARP_STATE" "$tx/state" || true;
        fix_permissions;
        test "$was_active" -eq 0 || systemctl restart xray.service > /dev/null 2>&1 || true;
        return 1;
    fi
}
# EEX3-FUNCTION warp_e136_140 _e138_hot_update_preflight
_e138_hot_update_preflight() {
    test "$EUID" -eq 0 || { 
        error "热更新必须使用root。";
        return 1
    };
    command -v systemctl > /dev/null 2>&1 || return 1;
    for c in jq curl ip ss tar install sha256sum cp awk;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "缺少命令：$c";
            return 1
        };
    done;
    test -r "$SCRIPT_PATH" || return 1;
    mkdir -p "$E138_TX_ROOT" || return 1;
    test -w "$E138_TX_ROOT" || return 1
}
