# EEX3-FUNCTION warp_e136_140 _e138_network_backup_and_strip
_e138_network_backup_and_strip() {
    local bdir="$1" f tmp keys hash digest failed=0;
    mkdir -p "$bdir/files" || return 1;
    : > "$bdir/manifest.tsv" || return 1;
    keys=$(_e118_mktemp e138-sysctl-keys) || return 1;
    _e136_network_keys > "$keys" || return 1;
    while IFS= read -r f; do
        test -f "$f" || continue;
        test "$f" = "$E138_NETWORK_CONF" && continue;
        tmp=$(_e118_mktemp e138-sysctl-strip) || { 
            failed=1;
            break
        };
        _e136_strip_sysctl_file "$keys" "$f" "$tmp" || { 
            failed=1;
            break
        };
        if ! cmp -s "$f" "$tmp"; then
            hash=$(printf '%s' "$f" | sha256sum | awk '{print $1}');
            cp -a -- "$f" "$bdir/files/$hash" || { 
                failed=1;
                break
            };
            digest=$(sha256sum "$bdir/files/$hash" | awk '{print $1}') || { 
                failed=1;
                break
            };
            printf '%s\t%s\t%s\n' "$f" "$hash" "$digest" >> "$bdir/manifest.tsv" || { 
                failed=1;
                break
            };
            install -m 0644 "$tmp" "$f" || { 
                failed=1;
                break
            };
        fi;
    done < <(_e135_sysctl_sources);
    if test "$failed" -ne 0; then
        _e138_network_restore_files "$bdir" > /dev/null 2>&1 || true;
        return 1;
    fi;
    return 0
}
