# EEX3-FUNCTION warp_e136_140 _e138_network_restore_files
_e138_network_restore_files() {
    local bdir="$1" src hash digest expect actual;
    test -s "$bdir/manifest.tsv" || return 0;
    while IFS='	' read -r src hash digest; do
        test -n "$src" && [[ "$hash" =~ ^[0-9a-f]{64}$ ]] || return 1;
        case "$src" in 
            /etc/sysctl.conf | /etc/sysctl.d/*.conf)

            ;;
            *)
                return 1
            ;;
        esac;
        expect=$(printf '%s' "$src" | sha256sum | awk '{print $1}');
        test "$expect" = "$hash" && test -f "$bdir/files/$hash" || return 1;
        if test -n "$digest"; then
            [[ "$digest" =~ ^[0-9a-f]{64}$ ]] || return 1;
            actual=$(sha256sum "$bdir/files/$hash" 2> /dev/null | awk '{print $1}');
            test "$actual" = "$digest" || return 1;
        fi;
        mkdir -p "$(dirname "$src")" || return 1;
        cp -a -- "$bdir/files/$hash" "$src" || return 1;
    done < "$bdir/manifest.tsv"
}
