# EEX3-FUNCTION warp_e136_140 _e138_safe_restore_rel
_e138_safe_restore_rel() {
    local rel="$1";
    test -n "$rel" || return 1;
    case "$rel" in 
        etc/* | usr/* | var/* | run/*)

        ;;
        *)
