            return 1
        ;;
    esac
}
# EEX3-FUNCTION warp_e136_140 _e138_self_test
_e138_self_test() {
    local rc=0 tmp src stripped keys hash sample sel glob off body tx;
    tmp=$(mktemp -d /tmp/e138-selftest.XXXXXX) || return 1;
    echo "V199e138 release gate:";
    test "$SCRIPT_VERSION" = 199e138 && echo "  [PASS] version" || { 
        echo "  [FAIL] version=$SCRIPT_VERSION";
        rc=1
    };
    body=$(declare -f hot_update_from_legacy);
    [[ "$body" == *'_e138_new_tx hot-update'* && "$body" == *'_e138_system_snapshot'* && "$body" == *'_e138_system_restore'* ]] && echo "  [PASS] isolated hot-update transaction" || { 
        echo "  [FAIL] hot-update transaction";
        rc=1
    };
    body=$(declare -f _e138_system_snapshot);
    [[ "$body" == *'E138_TX_ROOT'* || "$E138_TX_ROOT" == /var/backups/* ]] && echo "  [PASS] snapshot outside config tree" || { 
        echo "  [FAIL] snapshot location";
        rc=1
    };
    body=$(declare -f _e138_system_restore);
    [[ "$body" == *'control.sha256'* && "$body" == *'tar -tf'* && "$body" == *'test -s "$b/services.env"'* ]] && echo "  [PASS] rollback metadata guarded" || { 
        echo "  [FAIL] rollback guard";
        rc=1
    };
    keys="$tmp/keys";
    src="$tmp/sysctl.conf";
    stripped="$tmp/stripped.conf";
    _e136_network_keys > "$keys";
    printf 'net.ipv4.tcp_notsent_lowat = %s\nfoo.bar = 1\n' "$((1<<14))" > "$src";
    _e136_strip_sysctl_file "$keys" "$src" "$stripped" || rc=1;
    test "$(cat "$stripped")" = 'foo.bar = 1' && echo "  [PASS] sysctl strip behavior" || { 
        echo "  [FAIL] sysctl strip";
        rc=1
    };
    body=$(declare -f _e138_network_backup_and_strip);
    [[ "$body" == *'manifest.tsv'* && "$body" == *'sha256sum'* && "$body" != *'--parents'* ]] && echo "  [PASS] explicit sysctl backup mapping" || { 
        echo "  [FAIL] sysctl mapping";
        rc=1
    };
    sample="$tmp/sample.json";
    sel="$tmp/selective.json";
    glob="$tmp/global.json";
    off="$tmp/off.json";
    printf '%s\n' '{"dns":{"servers":["1.1.1.1"]},"outbounds":[{"tag":"direct","protocol":"freedom","settings":{}}],"routing":{"rules":[]}}' > "$sample";
    _e138_warp_config_build selective google-meta-core true "$sel" "$sample" || rc=1;
    _e138_warp_config_build global global true "$glob" "$sample" || rc=1;
    _e138_warp_config_build disabled disabled false "$off" "$glob" || rc=1;
    jq -e --arg w "$E138_WARP_SELECT_TAG" 'any(.outbounds[]?;.tag==$w)' "$sel" > /dev/null && echo "  [PASS] selective WARP config" || { 
        echo "  [FAIL] selective config";
        rc=1
    };
    jq -e --arg w "$E138_WARP_GLOBAL_TAG" --arg b "$E138_WARP_GLOBAL_BLOCK_TAG" 'any(.outbounds[]?;.tag==$w) and any(.routing.rules[]?;.outboundTag==$w and .network=="tcp") and any(.routing.rules[]?;.outboundTag==$b and .network=="udp")' "$glob" > /dev/null && echo "  [PASS] global Xray WARP config" || { 
