        echo "  [FAIL] WARP removal";
        rc=1
    };
    test "$E138_TX_ROOT" != "$E138_DIR/backups" && echo "  [PASS] no self-archiving path" || { 
        echo "  [FAIL] self archive path";
        rc=1
    };
    body=$(declare -f _e138_install_self);
    [[ "$body" == *'E138_SELF_PATH'* && "$body" == *'_e135_restore_file'* ]] && echo "  [PASS] self-install transaction" || { 
        echo "  [FAIL] self-install";
        rc=1
    };
    if ( set -e;
    local_root="$tmp/live-snapshot";
    local_src="$local_root/source";
    local_tx="$local_root/tx";
    mkdir -p "$local_src/sub" "$local_tx";
    printf 'before\n' > "$local_src/sub/file.conf";
    function _e138_system_paths () 
    { 
        printf '%s\n' "$local_src"
    };
    function _e136_network_keys () 
    { 
        :
    };
    _e138_system_snapshot "$local_tx";
    tar -tf "$local_tx/files.tar" | grep -q "${local_src#/}/sub/file.conf";
    ! tar -tf "$local_tx/files.tar" | grep -q "${local_tx#/}";
    printf 'after\n' > "$local_src/sub/file.conf";
    _e138_system_restore "$local_tx";
    test "$(cat "$local_src/sub/file.conf")" = before;
    test -s "$local_tx/runtime-sysctl.env";
    test -s "$local_tx/services.env" ); then
        echo "  [PASS] live snapshot/restore without self-deletion";
    else
        echo "  [FAIL] live snapshot/restore";
        rc=1;
    fi;
    if ( set -e;
    nroot="$tmp/live-network";
    nsrc="$nroot/custom.conf";
    nb="$nroot/backup";
    mkdir -p "$nroot";
    printf 'net.ipv4.tcp_notsent_lowat = %s\nfoo.bar = 1\n' "$((1<<14))" > "$nsrc";
    function _e135_sysctl_sources () 
    { 
        printf '%s\n' "$nsrc"
