# EEX3-FUNCTION warp_e136_140 _e139_self_test
_e139_self_test() {
    local rc=0 tmp p cand mode body;
    tmp=$(mktemp -d /tmp/e139-selftest.XXXXXX) || return 1;
    echo "V199e139 release gate:";
    test "$SCRIPT_VERSION" = 199e139 && echo "  [PASS] version" || { 
        echo "  [FAIL] version=$SCRIPT_VERSION";
        rc=1
    };
    p="$tmp/missing/sysctl.d/99-test.conf";
    _e139_ensure_parent "$p" && test -d "$tmp/missing/sysctl.d" && echo "  [PASS] missing sysctl.d creation" || { 
        echo "  [FAIL] sysctl.d creation";
        rc=1
    };
    body="$(declare -f _e139_network_apply)$(declare -f _e139_network_rollback)";
    [[ "$body" == *'_e139_ensure_parent "$E139_NETWORK_CONF"'* && "$body" == *'dir_preexisting'* && "$body" == *'rmdir /etc/sysctl.d'* && "$body" == *'_e139_network_rollback'* ]] && echo "  [PASS] sysctl directory transaction" || { 
        echo "  [FAIL] sysctl directory transaction";
        rc=1
    };
    body=$(declare -f _e139_warp_full_enable);
    [[ "$body" == *'xray-warp-full-e139-rollback.timer'* && "$body" == *'KEEP-FULL-TUNNEL'* && "$body" == *'_e139_full_route_apply'* ]] && echo "  [PASS] 120-second full-tunnel guard" || { 
        echo "  [FAIL] full-tunnel guard";
        rc=1
    };
    body=$(declare -f _e139_full_route_apply);
    [[ "$body" == *'from "$src/32"'* && "$body" == *'route get "$ssh_ip" from "$src"'* ]] && echo "  [PASS] SSH/Xray reply policy route" || { 
        echo "  [FAIL] reply policy route";
        rc=1
    };
    body=$(declare -f _e135_install_mode);
    [[ "$body" == *'mode" != host-full'* && "$body" == *'_e137_validate_semantic_config'* && "$body" == *'_e139_warp_full_reconcile'* ]] && echo "  [PASS] menu 1-4 host-full preservation" || { 
        echo "  [FAIL] node/full-tunnel preservation";
        rc=1
    };
    body=$(declare -f hot_update_from_legacy);
    [[ "$body" == *'_e139_network_apply balanced force'* && "$body" == *'test -s "$E139_NETWORK_CONF"'* && "$body" == *'_e139_warp_full_reconcile'* ]] && echo "  [PASS] E139 hot-update path" || { 
        echo "  [FAIL] hot-update";
        rc=1
    };
    body=$(declare -f _e118_write_generated_metadata);
    [[ "$body" == *'version=$E139_VERSION'* ]] && echo "  [PASS] metadata version" || { 
        echo "  [FAIL] metadata version";
        rc=1
    };
    rm -rf "$tmp";
    echo "V199e139 result: $(test "$rc" = 0 && echo PASS || echo FAIL)";
    return "$rc"
}
# EEX3-FUNCTION warp_e136_140 _e139_state_set_fields
_e139_state_set_fields() {
    local tmp key val;
    _e139_prepare || return 1;
    tmp=$(_e118_mktemp warp-state-fields-e139) || return 1;
    if test -s "$E139_WARP_STATE"; then
        cat "$E139_WARP_STATE" > "$tmp";
    else
        printf 'managed_by=e139\nroute_enabled=0\nroute_mode=disabled\nprofile=disabled\n' > "$tmp";
    fi;
    while test "$#" -ge 2; do
        key="$1";
        val="$2";
        shift 2;
        awk -F= -v k="$key" '$1!=k{print}' "$tmp" > "${tmp}.n" || return 1;
        printf '%s=%s\n' "$key" "$val" >> "${tmp}.n" || return 1;
        mv -f "${tmp}.n" "$tmp" || return 1;
    done;
    awk -F= '!seen[$1]++' "$tmp" > "${tmp}.n" || return 1;
    install -m 0600 "${tmp}.n" "$E139_WARP_STATE" || return 1
}
# EEX3-FUNCTION warp_e136_140 _e139_system_restore
_e139_system_restore() {
    local b="$1" svc enabled active rc=0;
    _e138_system_restore "$b" || return 1;
    if test -e "$b/e139-services.env"; then
        test -s "$b/e139-services.sha256" && ( cd "$b" && sha256sum -c e139-services.sha256 > /dev/null 2>&1 ) || return 1;
        while IFS='|' read -r svc enabled active; do
            test -n "$svc" || continue;
            if _eex3_ssh_control_preserved && _eex3_ssh_unit_protected "$svc"; then
                continue;
            fi;
            _e266_service_state_apply "$svc" "" "$enabled" "$active" || rc=1;
        done < "$b/e139-services.env";
    fi;
    return "$rc"
}
# EEX3-FUNCTION warp_e136_140 _e139_system_snapshot
_e139_system_snapshot() {
    local b="$1" svc;
    _e138_system_snapshot "$b" || return 1;
    : > "$b/e139-services.env" || return 1;
    for svc in xray-warp-full-e139-route.service xray-warp-full-e139-health.service xray-warp-full-e139-health.timer xray-warp-full-e139-rollback.service xray-warp-full-e139-rollback.timer;
    do
        _e159_snapshot_service "$svc" >> "$b/e139-services.env" || return 1;
    done;
    sha256sum "$b/e139-services.env" > "$b/e139-services.sha256" || return 1
}
