# EEX3-FUNCTION warp_e136_140 _e139_warp_set_full_mode
_e139_warp_set_full_mode() {
    local mode="${1:-traffic-only}" ok=1;
    case "$mode" in 
        traffic-only)
            _e136_warp_cli mode warp > /dev/null 2>&1 || _e136_warp_cli mode set warp > /dev/null 2>&1 || _e136_warp_cli set-mode warp > /dev/null 2>&1 || _e136_warp_cli mode tunnel_only > /dev/null 2>&1 || _e136_warp_cli mode set tunnel_only > /dev/null 2>&1 || ok=0
        ;;
        traffic-dns)
            _e136_warp_cli mode warp+doh > /dev/null 2>&1 || _e136_warp_cli mode set warp+doh > /dev/null 2>&1 || _e136_warp_cli set-mode warp+doh > /dev/null 2>&1 || ok=0
        ;;
        *)
            ok=0
        ;;
    esac;
    test "$ok" = 1 || return 1;
    ! _e136_warp_cli settings 2> /dev/null | grep -qi 'WarpProxy'
}
# EEX3-FUNCTION warp_e136_140 _e139_warp_set_protocol
_e139_warp_set_protocol() {
    local p="${1:-MASQUE}";
    case "${p,,}" in 
        wireguard)
            _e136_warp_cli tunnel protocol set WireGuard > /dev/null 2>&1 || _e136_warp_cli tunnel protocol set wireguard > /dev/null 2>&1 || return 1
        ;;
        masque | auto)
            _e136_warp_cli tunnel protocol set MASQUE > /dev/null 2>&1 || _e136_warp_cli tunnel protocol set masque > /dev/null 2>&1 || return 1
        ;;
        *)
            return 1
        ;;
    esac
}
