# EEX3-FUNCTION warp_e136_140 _e140_capture_diagnostics
_e140_capture_diagnostics() {
    local log="${1:-$E140_ACTIVE_LOG}" svc;
    test -n "$log" || return 0;
    svc=$(_e140_warp_service_name);
    { 
        echo;
        echo "===== E140 DIAGNOSTICS $(date -Is 2> /dev/null || date) =====";
        echo "stage=$E140_LAST_STAGE";
        echo "error=$E140_LAST_ERROR";
        echo "warp-cli=$E140_WARP_CLI_BIN";
        "$E140_WARP_CLI_BIN" --version 2>&1 || true;
        echo "--- status ---";
        _e140_warp_cli_capture status || true;
        echo;
        echo "--- registration ---";
        _e140_warp_cli_capture registration show || true;
        echo;
        echo "--- settings ---";
        _e140_warp_settings;
        echo;
        echo "--- systemctl ---";
        systemctl status "$svc" --no-pager -l 2>&1 || true;
        echo "--- journal ---";
        journalctl -u "$svc" --no-pager -n 120 2>&1 || true;
        echo "--- ip rule ---";
        ip -4 rule show 2>&1 || true;
        echo "--- route main ---";
        ip -4 route show table main 2>&1 || true;
        echo "--- route e140 ---";
        ip -4 route show table "$E140_FULL_TABLE" 2>&1 || true;
        echo "--- addresses ---";
        ip -4 addr show 2>&1 || true;
        echo "--- resolv.conf ---";
        cat /etc/resolv.conf 2>&1 || true;
        echo "--- trace ---";
        _e140_full_trace || true;
        echo
    } >> "$log" 2>&1
}
