# EEX3-FUNCTION warp_e136_140 _e140_full_auto_rollback
_e140_full_auto_rollback() {
    local tx="";
    test -s "$E140_FULL_PENDING" || return 0;
    tx=$(cat "$E140_FULL_PENDING" 2> /dev/null || true);
    test -d "$tx" || { 
        rm -f "$E140_FULL_PENDING";
        return 1
    };
    E140_ACTIVE_LOG="$E140_FULL_LOG_DIR/auto-rollback-$(date +%Y%m%d_%H%M%S).log";
    _e140_set_stage auto-rollback "confirmation timeout";
    _e140_full_rollback_tx "$tx"
}
# EEX3-FUNCTION warp_e136_140 _e140_full_install_units
_e140_full_install_units() {
    _e140_install_self || return 1;
    cat > "$E140_FULL_ROUTE_SCRIPT" <<EOF_E140_ROUTE_SCRIPT
#!/usr/bin/env bash
exec /usr/local/bin/xrv --warp-full-route-restore
EOF_E140_ROUTE_SCRIPT

    chmod 0755 "$E140_FULL_ROUTE_SCRIPT" || return 1;
    cat > "$E140_FULL_ROUTE_SERVICE" <<EOF_E140_ROUTE_SERVICE
[Unit]
Description=E140 preserve original IPv4 reply path under Cloudflare full tunnel
After=network-online.target warp-svc.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$E140_FULL_ROUTE_SCRIPT
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF_E140_ROUTE_SERVICE

    cat > "$E140_FULL_HEALTH_SERVICE" <<EOF_E140_HEALTH_SERVICE
[Unit]
Description=E140 Cloudflare full tunnel health and reply-path check
After=network-online.target warp-svc.service xray.service

[Service]
Type=oneshot
ExecStart=/usr/local/bin/xrv --warp-full-health-check
EOF_E140_HEALTH_SERVICE

    cat > "$E140_FULL_HEALTH_TIMER" <<'EOF_E140_HEALTH_TIMER'
[Unit]
Description=E140 periodic Cloudflare full tunnel health check

[Timer]
OnBootSec=2min
OnUnitActiveSec=5min
AccuracySec=20s
Persistent=true
Unit=xray-warp-full-e140-health.service

[Install]
WantedBy=timers.target
EOF_E140_HEALTH_TIMER

    cat > "$E140_FULL_ROLLBACK_SERVICE" <<EOF_E140_ROLLBACK_SERVICE
[Unit]
Description=E140 automatic rollback for unconfirmed Cloudflare full tunnel

[Service]
Type=oneshot
ExecStart=/usr/local/bin/xrv --warp-full-auto-rollback
EOF_E140_ROLLBACK_SERVICE

    cat > "$E140_FULL_ROLLBACK_TIMER" <<'EOF_E140_ROLLBACK_TIMER'
[Unit]
Description=E140 120-second Cloudflare full tunnel rollback guard

[Timer]
OnActiveSec=120s
AccuracySec=1s
Unit=xray-warp-full-e140-rollback.service

[Install]
WantedBy=timers.target
EOF_E140_ROLLBACK_TIMER

    systemctl daemon-reload > /dev/null 2>&1 || return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_full_mode_active
_e140_full_mode_active() {
    test "$(_e138_state_get route_enabled 0)" = 1 && test "$(_e138_state_get route_mode disabled)" = host-full
}
# EEX3-FUNCTION warp_e136_140 _e140_full_restore_files
_e140_full_restore_files() {
    local tx="$1" p svc enabled active was_active=0 was_enabled=0 rc=0;
    _e142_full_snapshot_verify "$tx" || return 1;
    for p in "$CONFIG" "$E139_WARP_STATE" "$E140_FULL_ROUTE_SCRIPT" "$E140_FULL_ROUTE_SERVICE" "$E140_FULL_HEALTH_SERVICE" "$E140_FULL_HEALTH_TIMER" "$E140_FULL_ROLLBACK_SERVICE" "$E140_FULL_ROLLBACK_TIMER";
    do
        _e135_restore_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || rc=1;
    done;
    systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    if test -s "$tx/e142-services.env"; then
        while IFS='|' read -r svc enabled active; do
            test -n "$svc" || continue;
            if test "$enabled" = enabled; then
                systemctl enable "$svc" > /dev/null 2>&1 || rc=1;
            else
                systemctl disable "$svc" > /dev/null 2>&1 || true;
            fi;
            if test "$active" = active; then
                systemctl restart "$svc" > /dev/null 2>&1 || rc=1;
            else
                systemctl stop "$svc" > /dev/null 2>&1 || true;
            fi;
        done < "$tx/e142-services.env";
    fi;
    was_active=$(sed -n 's/^xray_was_active=//p' "$tx/e142-runtime.env" | tail -n1);
    was_active=${was_active:-0};
    was_enabled=$(sed -n 's/^xray_was_enabled=//p' "$tx/e142-runtime.env" | tail -n1);
    was_enabled=${was_enabled:-0};
    fix_permissions;
    if test "$was_enabled" = 1; then
        systemctl enable xray.service > /dev/null 2>&1 || rc=1;
    else
        systemctl disable xray.service > /dev/null 2>&1 || true;
    fi;
    if test "$was_active" = 1; then
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1 || rc=1;
        _e118_xray_test_config "$CONFIG" 1 || rc=1;
        systemctl restart xray.service > /dev/null 2>&1 || rc=1;
        test "$rc" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
    else
        systemctl stop xray.service > /dev/null 2>&1 || true;
    fi;
    return "$rc"
}
# EEX3-FUNCTION warp_e136_140 _e140_full_rollback_tx
_e140_full_rollback_tx() {
    local tx="$1" old_enabled=0 old_mode=disabled rc=0 verify_rc=0;
    _e142_full_tx_ok "$tx" || { 
        error "拒绝回滚事务根目录之外的路径：$tx";
        return 1
    };
    _e142_full_snapshot_verify "$tx" || verify_rc=$?;
    _e140_warp_cli disconnect > /dev/null 2>&1 || true;
    _e140_full_route_cleanup;
    rm -f "$E140_FULL_PENDING" 2> /dev/null || true;
    systemctl disable --now xray-warp-full-e140-rollback.timer > /dev/null 2>&1 || true;
    if test "$verify_rc" -eq 0; then
        _e140_full_restore_files "$tx" || rc=1;
    else
        if test "$verify_rc" -eq 2; then
            warn "检测到旧E140无校验快照，执行兼容回滚并强制复检Xray。";
            _e142_full_restore_legacy "$tx" || rc=1;
            if test -s "$CONFIG" && systemctl is-active --quiet xray.service 2> /dev/null; then
                _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
            fi;
        else
            error "Cloudflare全隧道快照校验失败，拒绝使用损坏载荷。";
            rc=1;
        fi;
    fi;
    old_enabled=$(sed -n 's/^old_enabled=//p' "$tx/old-state.env" 2> /dev/null | tail -n1);
    old_enabled=${old_enabled:-0};
    old_mode=$(sed -n 's/^old_mode=//p' "$tx/old-state.env" 2> /dev/null | tail -n1);
    old_mode=${old_mode:-disabled};
    if test "$rc" -eq 0 && test "$old_enabled" = 1 && [[ "$old_mode" =~ ^(selective|global)$ ]]; then
        _e139_local_warp_reconcile_base > /dev/null 2>&1 || rc=1;
    fi;
    if test "$old_mode" != host-full; then
        ip -4 rule show 2> /dev/null | grep -Eq "^${E140_FULL_RULE_PRIORITY}:" && rc=1 || true;
        ip -4 route show table "$E140_FULL_TABLE" 2> /dev/null | grep -q . && rc=1 || true;
    fi;
    if test "$rc" -ne 0; then
        install -d -m 0700 "$E142_DIR" 2> /dev/null || true;
        { 
            echo "time=$(date -Is 2> /dev/null || date)";
            echo "operation=warp-full-rollback";
            echo "transaction=$tx"
        } > "${E142_CRITICAL_MARKER}.new.$$" 2> /dev/null && chmod 0600 "${E142_CRITICAL_MARKER}.new.$$" 2> /dev/null && mv -f -- "${E142_CRITICAL_MARKER}.new.$$" "$E142_CRITICAL_MARKER" 2> /dev/null || true;
        error "全隧道回滚未能完整验证；恢复材料：$tx";
        return 1;
    fi;
    rm -f "$E142_CRITICAL_MARKER" 2> /dev/null || true
}
# EEX3-FUNCTION warp_e136_140 _e140_full_route_apply
_e140_full_route_apply() {
    _e140_full_route_apply_base
}
# EEX3-FUNCTION warp_e136_140 _e140_full_route_apply_base
_e140_full_route_apply_base() {
    local src iface def_b64 link_b64 table priority ssh_ip line;
    _e138_warp_migrate_state || return 1;
    src=$(_e139_full_state_value orig_src);
    iface=$(_e139_full_state_value orig_iface);
    def_b64=$(_e139_full_state_value orig_default_b64);
    link_b64=$(_e139_full_state_value orig_link_b64);
    table=$(_e139_full_state_value full_table "$E139_FULL_TABLE");
    priority=$(_e139_full_state_value full_priority "$E139_FULL_RULE_PRIORITY");
    ssh_ip=$(_e139_full_state_value ssh_ip);
    _e136_is_ipv4 "$src" && test -n "$iface" && test -n "$def_b64" || return 1;
    while ip -4 rule del priority "$priority" > /dev/null 2>&1; do
        :;
    done;
    ip -4 route flush table "$table" > /dev/null 2>&1 || true;
    while IFS= read -r line; do
        test -n "$line" || continue;
        ip -4 route add table "$table" $line > /dev/null 2>&1 || return 1;
    done < <(printf '%s' "$link_b64" | _e139_b64dec);
    while IFS= read -r line; do
        test -n "$line" || continue;
        ip -4 route add table "$table" $line > /dev/null 2>&1 || return 1;
    done < <(printf '%s' "$def_b64" | _e139_b64dec);
    ip -4 rule add priority "$priority" from "$src/32" lookup "$table" || return 1;
    ip -4 route get 1.1.1.1 from "$src" 2> /dev/null | grep -Fq "dev $iface" || return 1;
    if _e136_is_ipv4 "$ssh_ip"; then
        ip -4 route get "$ssh_ip" from "$src" 2> /dev/null | grep -Fq "dev $iface" || return 1;
    fi
}
# EEX3-FUNCTION warp_e136_140 _e140_full_route_cleanup
_e140_full_route_cleanup() {
    while ip -4 rule del priority "$E140_FULL_RULE_PRIORITY" > /dev/null 2>&1; do
        :;
    done;
    ip -4 route flush table "$E140_FULL_TABLE" > /dev/null 2>&1 || true;
    _e139_full_route_cleanup > /dev/null 2>&1 || true
}
# EEX3-FUNCTION warp_e136_140 _e140_full_snapshot
_e140_full_snapshot() {
    local tx="$1" svc f rel;
    _e142_full_tx_ok "$tx" || return 1;
    _e142_full_snapshot_base "$tx" || return 1;
    { 
        echo "xray_was_active=$(systemctl is-active --quiet xray.service 2> /dev/null && echo 1 || echo 0)";
        echo "xray_was_enabled=$(systemctl is-enabled --quiet xray.service 2> /dev/null && echo 1 || echo 0)"
    } > "$tx/e142-runtime.env" || return 1;
    : > "$tx/e142-services.env" || return 1;
    for svc in xray-warp-full-e140-route.service xray-warp-full-e140-health.service xray-warp-full-e140-health.timer xray-warp-full-e140-rollback.service xray-warp-full-e140-rollback.timer;
    do
        printf '%s|%s|%s\n' "$svc" "$(systemctl is-enabled "$svc" 2> /dev/null || true)" "$(systemctl is-active "$svc" 2> /dev/null || true)" >> "$tx/e142-services.env" || return 1;
    done;
    : > "$tx/e142-snapshot.sha256" || return 1;
    while IFS= read -r f; do
        rel=${f#"$tx"/};
        ( cd "$tx" && sha256sum -- "$rel" ) >> "$tx/e142-snapshot.sha256" || return 1;
    done < <(find "$tx" -maxdepth 1 -type f ! -name e142-snapshot.sha256 -print 2> /dev/null | sort);
    test -s "$tx/e142-snapshot.sha256"
}
# EEX3-FUNCTION warp_e136_140 _e140_full_trace
_e140_full_trace() {
    local out;
    out=$(curl -4 -fsS --noproxy '*' --connect-timeout 5 --max-time 15 https://www.cloudflare.com/cdn-cgi/trace 2> /dev/null || true);
    test -n "$out" || out=$(curl -4 -fsS --noproxy '*' --connect-timeout 5 --max-time 15 https://1.1.1.1/cdn-cgi/trace 2> /dev/null || true);
    printf '%s' "$out"
}
# EEX3-FUNCTION warp_e136_140 _e140_full_verify
_e140_full_verify() {
    local expected_mode="${1:-$(_e138_state_get full_service_mode traffic-only)}" expected_proto="${2:-$(_e138_state_get full_protocol MASQUE)}" trace loc ip src iface ssh_ip current;
    _e140_set_stage verify-route;
    _e140_full_route_apply || { 
        E140_LAST_ERROR="原IPv4回程策略路由验证失败";
        return 1
    };
    _e140_set_stage verify-service;
    _e140_warp_service_wait || return 1;
    _e140_set_stage verify-registration;
    _e140_warp_registration_ok || { 
        E140_LAST_ERROR="注册状态缺失";
        return 1
    };
    current=$(_e140_warp_mode_current);
    test "$current" = "$expected_mode" || { 
        _e140_set_stage verify-mode "期望$expected_mode，实际$current";
        return 1
    };
    current=$(_e140_warp_protocol_current);
    if test "$current" != unknown && test "${current,,}" != "${expected_proto,,}"; then
        _e140_set_stage verify-protocol "期望$expected_proto，实际$current";
        return 1;
    fi;
    _e140_set_stage verify-connected;
    _e140_warp_status_connected || { 
        E140_LAST_ERROR="warp-cli未显示Connected";
        return 1
    };
    trace=$(_e140_full_trace) || true;
    grep -Eq '^warp=(on|plus)$' <<< "$trace" || { 
        _e140_set_stage verify-trace "Cloudflare trace未显示warp=on/plus";
        return 1
    };
    loc=$(awk -F= '$1=="loc"{print toupper($2)}' <<< "$trace");
    ip=$(awk -F= '$1=="ip"{print $2}' <<< "$trace");
    test "$loc" != CN || { 
        _e140_set_stage verify-location "Cloudflare出口loc=CN";
        return 1
    };
    _e136_is_ipv4 "$ip" || { 
        _e140_set_stage verify-trace "Cloudflare trace出口IP无效";
        return 1
    };
    src=$(_e139_full_state_value orig_src);
    iface=$(_e139_full_state_value orig_iface);
    ssh_ip=$(_e139_full_state_value ssh_ip);
    ip -4 route get 1.1.1.1 from "$src" 2> /dev/null | grep -Fq "dev $iface" || { 
        _e140_set_stage verify-reply "原IPv4源地址未走原网卡";
        return 1
    };
    if _e136_is_ipv4 "$ssh_ip"; then
        ip -4 route get "$ssh_ip" from "$src" 2> /dev/null | grep -Fq "dev $iface" || { 
            _e140_set_stage verify-ssh "SSH客户端回程未走原网卡";
            return 1
        };
    fi;
    if systemctl list-unit-files xray.service > /dev/null 2>&1 && test -s "$CONFIG"; then
        systemctl is-active --quiet xray.service || { 
            _e140_set_stage verify-xray "Xray服务未运行";
            return 1
        };
        _e127_verify_xray_runtime "$CONFIG" 8 || { 
            _e140_set_stage verify-xray "Xray运行态验证失败";
            return 1
        };
    fi;
    _e140_set_stage verified
}
# EEX3-FUNCTION warp_e136_140 _e140_help
_e140_help() {
    _e152_help
}
# EEX3-FUNCTION warp_e136_140 _e140_hot_update_preflight
_e140_hot_update_preflight() {
    local c;
    test "$EUID" -eq 0 || { 
        error "热更新必须使用root。";
        return 1
    };
    for c in systemctl jq curl ip ss tar install sha256sum cp awk sed grep dirname mkdir mv cmp find sort readlink xargs base64 paste tr chmod sysctl;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "热更新预检缺少命令：$c";
            return 1
        };
    done;
    test -r "$SCRIPT_PATH" || return 1;
    test -d /run/systemd/system || { 
        error "当前环境没有运行中的systemd。";
        return 1
    };
    if test -e /etc/sysctl.d; then
        test -d /etc/sysctl.d && test -w /etc/sysctl.d || return 1;
    else
        test -w /etc || return 1;
    fi;
    install -d -m 0700 "$E142_TX_ROOT" || return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_install_mode_base
_e140_install_mode_base() {
    local semantic="$1" label="${2:-}" internal protect rc=0 enabled mode profile;
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    if test "$enabled" != 1 || test "$mode" != host-full; then
        _e139_install_mode_base "$@" || return 1;
        printf '%s\n' "$E139_VERSION" > "$SCRIPT_VERSION_FILE";
        return 0;
    fi;
    internal=$(_e137_mode_internal "$semantic") || return 1;
    label=${label:-$(_e137_mode_name "$semantic")};
    protect=$(_e116_backup_state "before_e139_full_install_${semantic}") || return 1;
    _e118_save_core_payload "$protect" || return 1;
    E137_SEMANTIC_MODE="$semantic";
    _e116_install_mode "$internal" "$label" || rc=1;
    test "$rc" -ne 0 || _e137_validate_semantic_config "$CONFIG" "$semantic" || rc=1;
    test "$rc" -ne 0 || fix_xray_systemd_limits || rc=1;
    test "$rc" -ne 0 || _e139_warp_full_reconcile || rc=1;
    if test "$rc" -eq 0 && systemctl is-active --quiet xray.service; then
        _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
        _e131_verify_nice_runtime || rc=1;
    fi;
    E137_SEMANTIC_MODE="";
    if test "$rc" -ne 0; then
        _e118_restore_core_payload "$protect" > /dev/null 2>&1 || true;
        _e118_restore_state "$protect" > /dev/null 2>&1 || true;
        _e139_warp_full_reconcile > /dev/null 2>&1 || true;
        return 1;
    fi;
    printf '%s\n' "$E139_VERSION" > "$SCRIPT_VERSION_FILE";
    info "E139节点重建完成：菜单$semantic支持Cloudflare系统全隧道，原IPv4入站回程保持。";
    do_summary
}
