# EEX3-FUNCTION warp_e136_140 _e140_log_cmd
_e140_log_cmd() {
    local desc="$1";
    shift;
    if test -n "$E140_ACTIVE_LOG"; then
        printf '\n[%s] CMD %s:' "$(date -Is 2> /dev/null || date)" "$desc" >> "$E140_ACTIVE_LOG";
        printf ' %q' "$@" >> "$E140_ACTIVE_LOG";
        printf '\n' >> "$E140_ACTIVE_LOG";
        "$@" >> "$E140_ACTIVE_LOG" 2>&1;
    else
        "$@";
    fi
}
# EEX3-FUNCTION warp_e136_140 _e140_network_keys
_e140_network_keys() {
