# EEX3-FUNCTION warp_e136_140 _e140_set_stage
_e140_set_stage() {
    E140_LAST_STAGE="$1";
    E140_LAST_ERROR="${2:-}";
    if test -n "$E140_ACTIVE_LOG"; then
        printf '[%s] STAGE=%s %s\n' "$(date -Is 2> /dev/null || date)" "$E140_LAST_STAGE" "$E140_LAST_ERROR" >> "$E140_ACTIVE_LOG" 2> /dev/null || true;
    fi
}
# EEX3-FUNCTION warp_e136_140 _e140_system_restore
_e140_system_restore() {
    ( local snapshot="$1" EEX5_RESTORE_SERVICE_PLAN rc=0;
    EEX5_RESTORE_SERVICE_PLAN=$(mktemp /tmp/eex5-restore-plan.XXXXXX) || return 1;
    trap 'rm -f -- "$EEX5_RESTORE_SERVICE_PLAN"' EXIT;
    _eex5_restore_plan_build_checked "$snapshot" "$EEX5_RESTORE_SERVICE_PLAN" all || { 
        error 'EEX5恢复预检未通过；没有开始文件、sysctl或服务恢复。';
        return 1
    };
    _eex3_system_restore_unplanned "$snapshot" || rc=$?;
    return "$rc" )
}
# EEX3-FUNCTION warp_e136_140 _e140_system_snapshot
_e140_system_snapshot() {
    ( local EEX8_CAPTURE_CACHE;
    EEX8_CAPTURE_CACHE=$(mktemp -d /tmp/eex8-capture.XXXXXX) || return 1;
    trap 'rm -rf -- "$EEX8_CAPTURE_CACHE"' EXIT;
    _eex8_system_snapshot_capture_base "$1" || return 1;
    test ! -e "$EEX8_CAPTURE_CACHE/failed" )
}
# EEX3-FUNCTION warp_e136_140 _e140_try_cli_candidates
_e140_try_cli_candidates() {
    local spec arg1 arg2 arg3 arg4 rc;
    while IFS='|' read -r arg1 arg2 arg3 arg4; do
        test -n "$arg1" || continue;
        set +e;
        if test -n "$arg4"; then
            _e140_warp_cli "$arg1" "$arg2" "$arg3" "$arg4" >> "${E140_ACTIVE_LOG:-/dev/null}" 2>&1;
        else
            if test -n "$arg3"; then
                _e140_warp_cli "$arg1" "$arg2" "$arg3" >> "${E140_ACTIVE_LOG:-/dev/null}" 2>&1;
            else
                if test -n "$arg2"; then
                    _e140_warp_cli "$arg1" "$arg2" >> "${E140_ACTIVE_LOG:-/dev/null}" 2>&1;
                else
                    _e140_warp_cli "$arg1" >> "${E140_ACTIVE_LOG:-/dev/null}" 2>&1;
                fi;
            fi;
        fi;
        rc=$?;
        set -e;
        test "$rc" = 0 && return 0;
    done;
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_cli
_e140_warp_cli() {
    "$E140_WARP_CLI_BIN" --accept-tos "$@" 2> /dev/null || "$E140_WARP_CLI_BIN" "$@" 2> /dev/null
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_cli_capture
_e140_warp_cli_capture() {
    local out rc;
    set +e;
    out=$("$E140_WARP_CLI_BIN" --accept-tos "$@" 2>&1);
    rc=$?;
    if test "$rc" -ne 0; then
        out=$("$E140_WARP_CLI_BIN" "$@" 2>&1);
        rc=$?;
    fi;
    set -e;
    printf '%s' "$out";
    return "$rc"
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_cli_exists
_e140_warp_cli_exists() {
    case "$E140_WARP_CLI_BIN" in 
        */*)
            test -x "$E140_WARP_CLI_BIN"
        ;;
        *)
            command -v "$E140_WARP_CLI_BIN" > /dev/null 2>&1
        ;;
    esac
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_connect_wait
_e140_warp_connect_wait() {
    local i status trace;
    _e140_warp_cli connect >> "${E140_ACTIVE_LOG:-/dev/null}" 2>&1 || { 
        _e140_set_stage connect "warp-cli connect返回失败";
        return 1
    };
    for i in $(seq 1 60);
    do
        status=$(_e140_warp_cli_capture status || true);
        trace=$(_e140_full_trace || true);
        if _e140_warp_status_connected && grep -Eq '^warp=(on|plus)$' <<< "$trace"; then
            return 0;
        fi;
        sleep 1;
    done;
    test -n "$E140_ACTIVE_LOG" && { 
        printf '\nfinal status:\n%s\nfinal trace:\n%s\n' "$status" "$trace" >> "$E140_ACTIVE_LOG"
    };
    _e140_set_stage connect "60秒内未同时达到Connected和warp=on/plus";
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_full_diagnose
_e140_warp_full_diagnose() {
    local log;
    if test "$EUID" -eq 0; then
        _e140_prepare || return 1;
        log="$E140_FULL_LOG_DIR/diagnose-$(date +%Y%m%d_%H%M%S)-$$.log";
    else
        log="/tmp/warp-full-e140-diagnose-$(date +%Y%m%d_%H%M%S)-$$.log";
    fi;
    E140_ACTIVE_LOG="$log";
    _e140_set_stage diagnose;
    _e140_capture_diagnostics "$log";
    title "V199e141：Cloudflare全隧道诊断";
    echo "诊断日志：$log";
    echo "warp-svc: $(systemctl is-active "$(_e140_warp_service_name)" 2> /dev/null || echo unknown)";
    echo "registration: $(_e140_warp_registration_ok && echo OK || echo MISSING)";
    echo "service mode: $(_e140_warp_mode_current)";
    echo "protocol: $(_e140_warp_protocol_current)";
    echo "status: $(_e140_warp_status_connected && echo CONNECTED || echo NOT-CONNECTED)";
    echo "trace: $(_e140_full_trace | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g')";
    echo "最近日志：";
    tail -n 80 "$log" 2> /dev/null | sed 's/^/  /'
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_full_disable
_e140_warp_full_disable() {
    local internal="${1:-}" token="" tx old_mode rc=0 restore_rc=0;
    if test "$internal" != force; then
        read -rp '输入 DISABLE-CLOUDFLARE-FULL-TUNNEL 确认: ' token || true;
        test "$token" = DISABLE-CLOUDFLARE-FULL-TUNNEL || return 0;
    fi;
    _e140_full_mode_active || { 
        info 'Cloudflare系统全隧道当前未启用；未改动WARP或宿主机网络。';
        return 0
    };
    old_mode=$(_e138_state_get route_mode host-full);
    tx=$(_e204_new_tx warp-full-disable) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_warp_full_disable_base force || rc=1;
    test "$rc" -ne 0 || ! _e140_full_mode_active || rc=1;
    test "$rc" -ne 0 || ! ip -4 rule show 2> /dev/null | grep -Eq "^${E140_FULL_RULE_PRIORITY}:" || rc=1;
    test "$rc" -ne 0 || ! ip -4 route show table "$E140_FULL_TABLE" 2> /dev/null | grep -q . || rc=1;
    test "$rc" -ne 0 || _e138_warp_config_integrity disabled disabled disabled disabled || rc=1;
    test "$rc" -ne 0 || _e204_xray_runtime_readback || rc=1;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    error 'E204系统全隧道关闭未通过读回，恢复关闭前状态。';
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical warp-full-disable "$tx/system" 'full-tunnel disable rollback/readback failed' || true;
        error "严重：系统全隧道关闭回滚未完整通过；快照：$tx/system";
    fi;
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_full_enable
_e140_warp_full_enable() {
    local tx old_mode rc=0 restore_rc=0;
    old_mode=$(_e138_state_get route_mode disabled);
    tx=$(_e204_new_tx warp-full-enable-outer) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_warp_package_snapshot "$tx/warp-packages.before" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e159_warp_full_enable_base "$@" || rc=$?;
    if test "$rc" -eq 0; then
        if ! _e140_full_mode_active; then
            _e204_tx_close "$tx";
            return $?;
        fi;
        _e140_full_verify "$(_e138_state_get full_service_mode traffic-only)" "$(_e138_state_get full_protocol MASQUE)" || rc=1;
    fi;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    error 'E204系统全隧道启用事务失败，恢复启用前完整系统状态。';
    _e140_warp_cli disconnect > /dev/null 2>&1 || true;
    _e140_full_route_cleanup;
    _e204_warp_package_restore "$tx/warp-packages.before" || restore_rc=1;
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical warp-full-enable "$tx/system" 'full-tunnel outer rollback/readback failed' || true;
        error "严重：系统全隧道回滚未完整通过；快照：$tx/system";
    fi;
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_full_health_check
_e140_warp_full_health_check() {
    local tx;
    _e140_full_mode_active || return 0;
    _e140_full_verify && return 0;
    E140_ACTIVE_LOG="$E140_FULL_LOG_DIR/health-$(date +%Y%m%d_%H%M%S)-$$.log";
    : > "$E140_ACTIVE_LOG";
    _e140_warp_full_reconcile && _e140_full_verify && return 0;
    _e140_capture_diagnostics "$E140_ACTIVE_LOG";
    tx=$(_e138_state_get full_commit_tx "");
    if test -n "$tx" && _e142_full_snapshot_verify "$tx" && _e140_full_rollback_tx "$tx"; then
        error "Cloudflare全隧道健康复检失败，已恢复启用前的Xray/WARP状态。日志：$E140_ACTIVE_LOG";
        return 1;
    fi;
    _e140_warp_cli disconnect > /dev/null 2>&1 || true;
    _e140_full_route_cleanup;
    _e139_clear_xray_warp_rules > /dev/null 2>&1 || true;
    _e139_state_set_fields route_enabled 0 route_mode disabled profile disabled full_commit_tx '' managed_by e152 > /dev/null 2>&1 || true;
    install -d -m 0700 "$E152_DIR" 2> /dev/null || true;
    { 
        echo "time=$(date -Is 2> /dev/null || date)";
        echo "operation=warp-full-health";
        echo "transaction=$tx";
        echo "log=$E140_ACTIVE_LOG"
    } > "$E152_CRITICAL_MARKER" 2> /dev/null || true;
    error "全隧道健康失败且无可验证提交快照；已显式转为disabled并标记人工复核，未保留虚假的host-full状态。";
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_full_menu
_e140_warp_full_menu() {
    local n;
    while true; do
        clear;
        _e140_warp_status;
        echo "  1) 启用：Traffic only + MASQUE（推荐）";
        echo "  2) 启用：Traffic only + WireGuard";
        echo "  3) 启用：Traffic and DNS + MASQUE";
        echo "  4) 分阶段修复/重连当前全隧道";
        echo "  5) 关闭全隧道，恢复原IPv4直连";
        echo "  6) 无修改诊断（显示失败阶段、CLI、journal、路由）";
        echo "  7) 查看源地址策略路由";
        echo "  0) 返回";
        read -rp "操作: " n || true;
        case "$n" in 
            1)
                _e140_warp_full_enable traffic-only MASQUE;
                _e140_pause
            ;;
            2)
                _e140_warp_full_enable traffic-only WireGuard;
                _e140_pause
            ;;
            3)
                _e140_warp_full_enable traffic-dns MASQUE;
                _e140_pause
            ;;
            4)
                if _e140_warp_full_reconcile; then
                    info "修复成功。";
                else
                    error "修复失败阶段：$E140_LAST_STAGE $E140_LAST_ERROR";
                    _e140_capture_diagnostics "$E140_ACTIVE_LOG";
                fi;
                _e140_pause
            ;;
            5)
                _e140_warp_full_disable;
                _e140_pause
            ;;
            6)
                _e140_warp_full_diagnose;
                _e140_pause
            ;;
            7)
                ip -4 rule show;
                ip -4 route show table "$E140_FULL_TABLE";
                _e140_pause
            ;;
            0)
                return
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_full_reconcile
_e140_warp_full_reconcile() {
    local tx old_mode rc=0 restore_rc=0;
    _e140_full_mode_active || return 0;
    old_mode=$(_e138_state_get route_mode host-full);
    tx=$(_e204_new_tx warp-full-reconcile) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_warp_full_reconcile_base || rc=1;
    test "$rc" -ne 0 || _e140_full_verify "$(_e138_state_get full_service_mode traffic-only)" "$(_e138_state_get full_protocol MASQUE)" || rc=1;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    error 'E204系统全隧道修复失败，恢复修复前状态。';
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical warp-full-reconcile "$tx/system" 'full-tunnel reconcile rollback/readback failed' || true;
        error "严重：系统全隧道修复回滚未完整通过；快照：$tx/system";
    fi;
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_ipc_ready
_e140_warp_ipc_ready() {
    local out;
    out=$(_e140_warp_cli_capture status || true);
    test -n "$out" || return 1;
    grep -qiE 'ipc|unable to connect|connection refused|daemon.*not|service.*not' <<< "$out" && return 1;
    return 0
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_mode_current
_e140_warp_mode_current() {
    local s;
    s=$(_e140_warp_settings);
    if grep -qi 'WarpWithDnsOverHttps' <<< "$s"; then
        echo traffic-dns;
    else
        if grep -qi 'TunnelOnly' <<< "$s"; then
            echo traffic-only;
        else
            if grep -qi 'WarpProxy' <<< "$s"; then
                echo proxy;
            else
                if grep -qiE 'mode[^[:alnum:]]+(warp\+doh|warpwithdns)' <<< "$s"; then
                    echo traffic-dns;
                else
                    if grep -qiE 'mode[^[:alnum:]]+warp([^[:alnum:]]|$)' <<< "$s"; then
                        echo traffic-only;
                    else
                        echo unknown;
                    fi;
                fi;
            fi;
        fi;
    fi
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_protocol_current
_e140_warp_protocol_current() {
    local s;
    s=$(_e140_warp_settings);
    if grep -qi 'MASQUE' <<< "$s"; then
        echo MASQUE;
    else
        if grep -qi 'WireGuard' <<< "$s"; then
            echo WireGuard;
        else
            echo unknown;
        fi;
    fi
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_register
_e140_warp_register() {
    local out i;
    _e140_warp_registration_ok && return 0;
    out=$(_e140_warp_cli_capture registration new || true);
    test -n "$E140_ACTIVE_LOG" && printf '\nregistration new output:\n%s\n' "$out" >> "$E140_ACTIVE_LOG";
    if grep -qiE 'team name|team_name|browser|cloudflareaccess|authentication|organization|required.*argument|usage:.*registration new' <<< "$out"; then
        _e140_set_stage registration "客户端要求Zero Trust组织/浏览器注册，无法在root无交互流程中自动完成";
        return 1;
    fi;
    for i in $(seq 1 45);
    do
        _e140_warp_registration_ok && return 0;
        sleep 1;
    done;
    _e140_set_stage registration "设备注册在45秒内未完成";
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_registration_ok
_e140_warp_registration_ok() {
    local out status;
    _e140_warp_cli_exists || return 1;
    out=$(_e140_warp_cli_capture registration show || true);
    if test -n "$out" && ! grep -qiE 'missing|not registered|no registration|error|failed|command not found|ipc' <<< "$out" && grep -qiE 'device|registration|account|organization|team|license' <<< "$out"; then
        return 0;
    fi;
    status=$(_e140_warp_cli_capture status || true);
    test -n "$status" || return 1;
    ! grep -qiE 'missing registration|not registered|registration.*missing|command not found|ipc' <<< "$status" && grep -qiE 'connected|disconnected|connecting|status' <<< "$status"
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_service_name
_e140_warp_service_name() {
    if systemctl cat warp-svc.service > /dev/null 2>&1; then
        echo warp-svc.service;
    else
        echo warp-svc;
    fi
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_service_wait
_e140_warp_service_wait() {
    local svc i version status restarted=0;
    _e140_warp_cli_exists || { 
        _e140_set_stage service 'warp-cli不存在';
        return 1
    };
    svc=$(_e140_warp_service_name);
    systemctl enable --now "$svc" >> "${E140_ACTIVE_LOG:-/dev/null}" 2>&1 || { 
        _e140_set_stage service 'warp-svc无法启动';
        return 1
    };
    for i in {1..60};
    do
        if systemctl is-active --quiet "$svc" 2> /dev/null && _e140_warp_ipc_ready; then
            return 0;
        fi;
        if test "$i" = 15 || test "$i" = 35; then
            systemctl restart "$svc" >> "${E140_ACTIVE_LOG:-/dev/null}" 2>&1 || true;
            restarted=$((restarted+1));
        fi;
        sleep 1;
    done;
    version=$(_e140_warp_cli_capture --version 2> /dev/null | head -n1 || true);
    status=$(_e140_warp_cli_capture status 2>&1 || true);
    install -d -m 0700 "$E159_DIR" 2> /dev/null || true;
    { 
        echo "time=$(date -Is 2> /dev/null || date)";
        echo "service=$svc";
        echo "service_state=$(systemctl is-active "$svc" 2> /dev/null || true)";
        echo "version=$version";
        echo "restarts=$restarted";
        echo 'status<<EOF';
        echo "$status";
        echo 'EOF';
        journalctl -u "$svc" -n 120 --no-pager 2>&1 || true
    } > "$E159_WARP_IPC_DIAG" 2> /dev/null || true;
    if grep -qE '2026\.4\.' <<< "$version"; then
        _e140_set_stage ipc "Cloudflare Linux 2026.4客户端IPC在60秒内未就绪；诊断：$E159_WARP_IPC_DIAG";
    else
        _e140_set_stage ipc "warp-svc运行但CLI IPC在60秒内未就绪；诊断：$E159_WARP_IPC_DIAG";
    fi;
    return 1
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_set_mode
_e140_warp_set_mode() {
    local desired="${1:-traffic-only}" current;
    current=$(_e140_warp_mode_current);
    test "$current" = "$desired" && return 0;
    case "$desired" in 
        traffic-only)
            _e140_try_cli_candidates <<'EOF_E140_TUNNEL_ONLY' || 
mode|warp
mode|set|warp
set-mode|warp
mode|tunnel_only
mode|set|tunnel_only
mode|tunnel-only
mode|set|tunnel-only
EOF_E140_TUNNEL_ONLY
 { 
                _e140_set_stage mode "无法设置Traffic-only/TunnelOnly；可能由Zero Trust设备配置锁定"
                return 1
            }
        ;;
        traffic-dns)
            _e140_try_cli_candidates <<'EOF_E140_WARP_DNS' || 
mode|warp+doh
mode|set|warp+doh
set-mode|warp+doh
mode|warp_with_dns_over_https
mode|set|warp_with_dns_over_https
EOF_E140_WARP_DNS
 { 
                _e140_set_stage mode "无法设置Traffic and DNS/WarpWithDnsOverHttps；可能由Zero Trust设备配置锁定"
                return 1
            }
        ;;
        *)
            _e140_set_stage mode "未知服务模式：$desired";
            return 1
        ;;
    esac;
    sleep 2;
    current=$(_e140_warp_mode_current);
    if test "$current" != "$desired"; then
        _e140_set_stage mode "命令执行后settings未收敛：期望$desired，实际$current";
        return 1;
    fi
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_set_protocol
_e140_warp_set_protocol() {
    local desired="${1:-MASQUE}" current;
    current=$(_e140_warp_protocol_current);
    test "${current,,}" = "${desired,,}" && return 0;
    case "${desired,,}" in 
        masque)
            _e140_try_cli_candidates <<'EOF_E140_MASQUE' || 
tunnel|protocol|set|MASQUE
tunnel|protocol|set|masque
EOF_E140_MASQUE
 { 
                _e140_set_stage protocol "无法设置MASQUE"
                return 1
            }
        ;;
        wireguard)
            _e140_try_cli_candidates <<'EOF_E140_WG' || 
tunnel|protocol|set|WireGuard
tunnel|protocol|set|wireguard
EOF_E140_WG
 { 
                _e140_set_stage protocol "无法设置WireGuard"
                return 1
            }
        ;;
        *)
            _e140_set_stage protocol "未知协议：$desired";
            return 1
        ;;
    esac;
    sleep 1;
    current=$(_e140_warp_protocol_current);
    if test "$current" != unknown && test "${current,,}" != "${desired,,}"; then
        _e140_set_stage protocol "命令返回成功，但settings读回为$current";
        return 1;
    fi
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_settings
_e140_warp_settings() {
    _e140_warp_cli_capture settings || true
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_status
_e140_warp_status() {
    _e186_warp_status
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_status_base
_e140_warp_status_base() {
    local enabled mode profile trace loc ip settings src iface ssh_ip route_check="N/A";
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    title "V199e139：WARP/Cloudflare状态";
    printf '  %-26s %s\n' "期望状态" "enabled=$enabled mode=$mode profile=$profile";
    if test "$mode" = host-full && test "$enabled" = 1; then
        trace=$(_e139_full_trace 2> /dev/null || true);
        loc=$(awk -F= '$1=="loc"{print $2}' <<< "$trace");
        loc=${loc:-unknown};
        ip=$(awk -F= '$1=="ip"{print $2}' <<< "$trace");
        ip=${ip:-unknown};
        src=$(_e139_full_state_value orig_src);
        iface=$(_e139_full_state_value orig_iface);
        ssh_ip=$(_e139_full_state_value ssh_ip);
        if _e136_is_ipv4 "$src" && ip -4 route get 1.1.1.1 from "$src" 2> /dev/null | grep -Fq "dev $iface"; then
            route_check=OK;
        else
            route_check=FAIL;
        fi;
        printf '  %-26s %s\n' "系统全隧道" "$(_e139_full_connected && echo CONNECTED || echo DOWN)";
        printf '  %-26s %s\n' "Cloudflare出口/loc" "$ip/$loc";
        printf '  %-26s %s\n' "原IPv4源地址/网卡" "$src/$iface";
        printf '  %-26s %s\n' "SSH/Xray回程保护" "$route_check (peer=${ssh_ip:-unknown})";
        printf '  %-26s %s\n' "服务模式/协议" "$(_e139_full_state_value full_service_mode traffic-only)/$(_e139_full_state_value full_protocol MASQUE)";
    else
        _e138_warp_config_integrity "$mode" "$profile" > /dev/null 2>&1 && route_check=CONSISTENT || route_check=MISSING;
        trace=$(_e136_warp_trace 2> /dev/null || true);
        loc=$(awk -F= '$1=="loc"{print $2}' <<< "$trace");
        loc=${loc:-unknown};
        ip=$(awk -F= '$1=="ip"{print $2}' <<< "$trace");
        ip=${ip:-unknown};
        printf '  %-26s %s\n' "本地代理" "$(_e137_warp_proxy_ready && echo UP || echo DOWN)";
        printf '  %-26s %s\n' "Xray配置一致性" "$route_check";
        printf '  %-26s %s\n' "WARP出口/loc" "$ip/$loc";
    fi;
    settings=$(command -v warp-cli > /dev/null 2>&1 && _e136_warp_cli settings 2> /dev/null | grep -Ei 'mode|service|protocol|proxy' | xargs echo || echo not-installed);
    printf '  %-26s %s\n' "warp-cli设置" "$settings"
}
# EEX3-FUNCTION warp_e136_140 _e140_warp_status_connected
_e140_warp_status_connected() {
    local s;
    s=$(_e140_warp_cli_capture status || true);
    grep -qiE '(^|[^a-z])connected([^a-z]|$)|status[^[:alnum:]]*connected' <<< "$s" && ! grep -qiE 'disconnected|disconnecting' <<< "$s"
}
