declare -gr E152_SSH_AUTH_TIMER="/etc/systemd/system/xray-ssh-auth-audit-e152.timer"
declare -gr E152_TRANSIENT_IGNORE="/usr/local/etc/xray/e152/ssh-transient-ignore.env"
