# Module functions
# EEX3-FUNCTION ssh_security_e141_158 _e141_fail2ban_guard_original
_e141_fail2ban_guard_original() {
    local backup baseline_ok=0 was_active=0 was_enabled=0 state_tmp;
    if ! command -v fail2ban-client > /dev/null 2>&1; then
        info "未检测到 fail2ban，正在按当前发行版自动安装。";
        pkg_install fail2ban || { 
            error "fail2ban 安装失败。";
            return 1
        };
    else
        info "已检测到 $(fail2ban-client --version 2> /dev/null | head -n1 || echo fail2ban)。";
    fi;
    backup=$(_e121_backup_fail2ban_state) || { 
        error "fail2ban 变更前快照失败。";
        return 1
    };
    systemctl is-active --quiet fail2ban 2> /dev/null && was_active=1 || true;
    systemctl is-enabled --quiet fail2ban 2> /dev/null && was_enabled=1 || true;
    fail2ban-client -t > /dev/null 2>&1 && baseline_ok=1 || true;
    if ! _e121_select_fail2ban_source; then
        error "无法获得可验证的 SSH 日志源：journald 绑定和文件日志均不可用。";
        _e121_restore_fail2ban_state "$backup" || true;
        return 1;
    fi;
    _e121_select_banaction || { 
        _e121_restore_fail2ban_state "$backup" || true;
        return 1
    };
    rm -f -- "$E118_F2B_JAIL" "$E118_F2B_DB_CONF" "${E116_F2B_JAIL:-/etc/fail2ban/jail.d/99-xray-sshguard-e116.conf}" "${E116_F2B_DB_CONF:-/etc/fail2ban/fail2ban.d/99-xray-e116-persistence.conf}" "/etc/fail2ban/jail.d/99-xray-sshguard-e117.conf" "/etc/fail2ban/fail2ban.d/99-xray-e117-persistence.conf" "/etc/fail2ban/jail.d/99-xray-sshguard-e119.conf" "/etc/fail2ban/fail2ban.d/99-xray-e119-persistence.conf" "/etc/fail2ban/jail.d/zz-xray-sshguard-e119-compat.local" "/etc/rsyslog.d/30-xray-ssh-auth-e119.conf" "/etc/fail2ban/jail.d/99-xray-sshguard-e120.conf" "/etc/fail2ban/fail2ban.d/99-xray-e120-persistence.conf" "/etc/fail2ban/jail.d/zz-xray-sshguard-e120-compat.local" "/etc/rsyslog.d/30-xray-ssh-auth-e120.conf" 2> /dev/null || true;
    _e121_write_fail2ban_candidates || { 
        _e121_restore_fail2ban_state "$backup" || true;
        error "fail2ban 候选配置写入失败，已恢复快照。";
        return 1
    };
    if ! _e121_test_and_repair_ssh_jails; then
        _e121_restore_fail2ban_state "$backup" || true;
        error "候选配置未应用，fail2ban 文件已恢复：$backup";
        return 1;
    fi;
    systemctl enable fail2ban > /dev/null 2>&1 || { 
        _e121_restore_fail2ban_state "$backup" || true;
        error "fail2ban 无法设为开机启动，候选配置已恢复。";
        return 1
    };
    if test "$was_active" -eq 1; then
        systemctl restart fail2ban > /dev/null 2>&1 || true;
    else
        systemctl start fail2ban > /dev/null 2>&1 || true;
    fi;
    if ! _e121_verify_fail2ban_runtime; then
        error "fail2ban 应用后运行态复检失败。";
        _e121_restore_fail2ban_state "$backup" || true;
        if test "$baseline_ok" -eq 1; then
            if test "$was_active" -eq 1; then
                systemctl restart fail2ban > /dev/null 2>&1 || true;
            else
                systemctl stop fail2ban > /dev/null 2>&1 || true;
            fi;
            if test "$was_enabled" -eq 1; then
                systemctl enable fail2ban > /dev/null 2>&1 || true;
            else
                systemctl disable fail2ban > /dev/null 2>&1 || true;
            fi;
        else
            warn "原 fail2ban 配置本就无效，未强制重启已恢复的旧配置，以免破坏仍存活的旧进程。";
        fi;
        return 1;
    fi;
    state_tmp=$(_e118_mktemp fail2ban-e121-state) || return 1;
    { 
        echo "time=$(date '+%F %T')";
        echo "version=$SCRIPT_VERSION";
        echo "fail2ban_version=$(fail2ban-client --version 2> /dev/null | head -n1 | tr ' ' '_')";
        echo "jail=$E121_F2B_JAIL_NAME";
        echo "backend=$E121_F2B_BACKEND";
        echo "logpath=${E121_F2B_LOGPATH:-journal:sshd-filter-journalmatch}";
        echo "python=${E121_F2B_PYTHON:-none}";
        echo "banaction=${E121_F2B_BANACTION:-distribution-default}";
        echo "actionstart_on_demand=$(test "$E121_F2B_EAGER_ACTION" -eq 1 && echo false || echo distribution-default)";
        echo "ports=$(_e116_detect_ssh_ports | paste -sd, -)";
        echo "maxretry=$E118_MAXRETRY";
        echo "findtime=$E118_FINDTIME";
        echo "bantime=$E118_BANTIME";
        echo "replaced_broken_jails=${E121_F2B_REPAIRED_JAILS:-none}";
        echo "backup=$backup"
    } > "$state_tmp";
    _e121_atomic_install "$state_tmp" "$E121_F2B_STATE" 0600 || return 1;
    info "fail2ban 已通过配置与运行态双重验证：$E121_F2B_JAIL_NAME / $E121_F2B_BACKEND。"
}
