# EEX3-FUNCTION ssh_security_e141_158 _e141_hot_update_base
_e141_hot_update_base() {
    local protect sysbackup rc=0 was_active=0 enabled=0 mode=disabled profile=disabled;
    E135_NEW_PACKAGES=();
    _e140_prepare || return 1;
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    protect=$(_e116_backup_state before_hot_update_e140) || return 1;
    _e118_save_core_payload "$protect" || return 1;
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
    was_active=${was_active:-0};
    sysbackup=$(_e140_new_tx hot-update) || return 1;
    _e140_system_snapshot "$sysbackup" || { 
        error "E140系统快照失败。";
        return 1
    };
    _e135_require_runtime_tools || rc=1;
    test "$rc" -ne 0 || _e135_disable_legacy_optimizers || rc=1;
    test "$rc" -ne 0 || _e140_install_self || rc=1;
    test "$rc" -ne 0 || install_update_dat || rc=1;
    test "$rc" -ne 0 || systemctl enable --now xray-dat-update.timer > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || _e105_disable_xray_core_auto_update || rc=1;
    test "$rc" -ne 0 || _e137_apply_init_window_default30 || rc=1;
    test "$rc" -ne 0 || _e139_network_apply balanced force || rc=1;
    test "$rc" -ne 0 || _e121_install_log_retention || rc=1;
    test "$rc" -ne 0 || _e135_install_ssh_guard || rc=1;
    test "$rc" -ne 0 || fix_xray_systemd_limits || rc=1;
    if test "$rc" = 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e140_full_install_units || rc=1;
            test "$rc" -ne 0 || _e140_warp_full_reconcile || rc=1;
        else
            _e137_warp_connect_local_proxy || rc=1;
            test "$rc" -ne 0 || _e138_xray_apply_warp "$mode" "$profile" true || rc=1;
            test "$rc" -ne 0 || _e138_warp_health_install || rc=1;
        fi;
    fi;
    test "$rc" -ne 0 || printf '%s\n' "$E141_VERSION" > "$SCRIPT_VERSION_FILE" || rc=1;
    if test "$rc" = 0 && test "$was_active" = 1; then
        _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
        _e131_verify_nice_runtime || rc=1;
    fi;
    test "$rc" -ne 0 || test "$(sysctl -n net.ipv4.tcp_notsent_lowat 2> /dev/null)" = 131072 || rc=1;
    test "$rc" -ne 0 || test "$(sysctl -n net.ipv6.conf.all.disable_ipv6 2> /dev/null)" = 1 || rc=1;
    test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
    test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
    test "$rc" -ne 0 || systemctl is-enabled --quiet xray-dat-update.timer || rc=1;
    if test "$rc" -ne 0; then
        error "E140热更新失败，恢复系统、Core、Xray、WARP和防火墙。";
        _e140_system_restore "$sysbackup" || error "系统快照恢复失败：$sysbackup";
        _e118_restore_core_payload "$protect" > /dev/null 2>&1 || true;
        _e118_restore_state "$protect" > /dev/null 2>&1 || true;
        _e135_remove_new_runtime_tools || true;
        return 1;
    fi;
    info "V199e141热更新完成。快照：$sysbackup";
    info "已验证：init30、notsent=131072、IPv6关闭、Nice=-20、DAT 03:00；WARP mode=$mode。"
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_install_fail2ban_package
_e141_install_fail2ban_package() {
    local had_f2b=0 had_py=0 pkg;
    _e135_pkg_present fail2ban && had_f2b=1 || true;
    _e135_pkg_present python3-systemd && had_py=1 || true;
    _e142_fail2ban_install_base || return 1;
    if test "$had_f2b" -eq 0 && _e135_pkg_present fail2ban; then
        E135_NEW_PACKAGES+=(fail2ban);
    fi;
    if test "$had_py" -eq 0 && _e135_pkg_present python3-systemd; then
        E135_NEW_PACKAGES+=(python3-systemd);
    fi;
    if test "${#E135_NEW_PACKAGES[@]}" -gt 0; then
        local -a unique=();
        for pkg in "${E135_NEW_PACKAGES[@]}";
        do
            [[ " ${unique[*]} " == *" $pkg "* ]] || unique+=("$pkg");
        done;
        E135_NEW_PACKAGES=("${unique[@]}");
    fi
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_install_key_only_ssh_guard
_e141_install_key_only_ssh_guard() {
    local tx ip failed=0 rollback_rc=0;
    tx=$(_e142_new_tx ssh-key-only-guard) || return 1;
    _e140_system_snapshot "$tx" || return 1;
    _e142_key_only_guard_base || failed=1;
    if test "$failed" -eq 0; then
        systemctl enable --now xray-ssh-port-guard-e121.service xray-ssh-port-guard-e121.timer > /dev/null 2>&1 || failed=1;
    fi;
    test "$failed" -ne 0 || _e142_verify_key_only_guard || failed=1;
    ip=$(_e135_current_ssh_ip 2> /dev/null || true);
    if test "$failed" -eq 0 && command -v fail2ban-client > /dev/null 2>&1 && fail2ban-client status "$E121_F2B_JAIL_NAME" > /dev/null 2>&1; then
        if test -f "$E121_F2B_JAIL"; then
            _e135_patch_fail2ban_ignoreip "$ip" || failed=1;
        else
            test -z "$ip" || fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip "$ip" > /dev/null 2>&1 || true;
            warn "检测到运行中的受管jail但未找到脚本拥有的配置文件；仅执行当前IP解封，不改写未知配置。";
        fi;
    fi;
    if test "$failed" -ne 0; then
        error "Key-only SSH防锁事务失败，恢复防火墙、Fail2ban、文件和服务状态。";
        _e140_system_restore "$tx" || rollback_rc=1;
        test "$rollback_rc" -eq 0 || error "Key-only SSH防锁回滚未完整通过；恢复材料：$tx";
        return 1;
    fi;
    info "Key-only SSH防锁已立即生效；开机与5分钟定时复检均处于活动状态。";
    test -z "$ip" || info "当前SSH客户端IP已在现有受管Fail2ban中保留/解封：$ip"
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_install_ssh_guard
_e141_install_ssh_guard() {
    local tx rc=0 restore_rc=0 before_count=${#E135_NEW_PACKAGES[@]};
    tx=$(_e204_new_tx ssh-guard) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_ssh_guard_install_base "$@" || rc=$?;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    error 'SSH/Fail2ban事务未通过，恢复操作前的配置、服务和防火墙状态。';
    _e172_remove_packages_since "$before_count" || restore_rc=1;
    _e140_system_restore "$tx/system" || restore_rc=1;
    if command -v sshd > /dev/null 2>&1; then
        sshd -t > /dev/null 2>&1 || restore_rc=1;
        _e182_sshd_reload_safe > /dev/null 2>&1 || restore_rc=1;
    fi;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical ssh-guard "$tx/system" 'outer SSH rollback/readback failed' || true;
        error "严重：SSH/Fail2ban外层回滚未完整通过；快照：$tx/system";
    else
        info "SSH/Fail2ban已恢复到操作前状态；快照：$tx/system";
    fi;
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_prepare
_e141_prepare() {
    install -d -m 0700 "$E141_DIR" || return 1;
    install -d -m 0750 "$E141_LOG_DIR" || return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_self_test
_e141_self_test() {
    local rc=0 body sample mode;
    echo "V199e141 release gate:";
    test "$SCRIPT_VERSION" = 199e141 && echo "  [PASS] version" || { 
        echo "  [FAIL] version=$SCRIPT_VERSION";
        rc=1
    };
    body="$(declare -f _e141_sshd_auth_profile)$(declare -f _e141_install_fail2ban_package)$(declare -f _e141_install_ssh_guard)";
    [[ "$body" == *'passwordauthentication'* && "$body" == *'kbdinteractiveauthentication'* && "$body" == *'dpkg --configure -a'* && "$body" == *'_e141_wait_apt_locks'* ]] && echo "  [PASS] key-only detection and truthful installer" || { 
        echo "  [FAIL] SSH/package state machine";
        rc=1
    };
    body="$(declare -f _e141_install_key_only_ssh_guard)";
    [[ "$body" == *'_e121_write_ssh_port_guard'* && "$body" == *'_e121_verify_ssh_port_guard'* && "$body" != *'_e121_install_fail2ban_guard'* ]] && echo "  [PASS] key-only path skips fail2ban" || { 
        echo "  [FAIL] key-only path";
        rc=1
    };
    body="$(declare -f _e141_hot_update_base)";
    [[ "$body" == *'_e135_install_ssh_guard'* && "$body" == *'E141_VERSION'* ]] && echo "  [PASS] E141 hot-update SSH path" || { 
        echo "  [FAIL] hot-update override";
        rc=1
    };
    bash -n "$SCRIPT_PATH" > /dev/null 2>&1 && echo "  [PASS] bash syntax" || { 
        echo "  [FAIL] bash syntax";
        rc=1
    };
    test "$rc" -eq 0 && echo "V199e141 result: PASS" || echo "V199e141 result: FAIL";
    return "$rc"
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_ssh_guard_status
_e141_ssh_guard_status() {
    if test "$(_e182_backend_state_get preferred_backend none)" = sshd-native; then
        title 'V199e182：OpenSSH原生防爆破降级状态';
        cat "$E182_BACKEND_STATE" 2> /dev/null || true;
        cat "$E182_NATIVE_STATE" 2> /dev/null || true;
        _e182_native_effective_values || true;
        if _e182_native_verify; then
            info '原生限流/审计运行正常；ip_ban_capable=0。';
        else
            error '原生限流/审计读回失败。';
            return 1;
        fi;
    else
        _e182_ssh_guard_status_base "$@";
    fi
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_sshd_auth_profile
_e141_sshd_auth_profile() {
    local user dump profile mode overall=non-password host addr any=0 match_risk=0;
    local profiles="" current_user="${SUDO_USER:-${USER:-root}}" current_dump current_profile current_mode context=global local_port=none;
    id "$current_user" > /dev/null 2>&1 || current_user=root;
    host=$(hostname -f 2> /dev/null || hostname 2> /dev/null || echo localhost);
    addr=$(awk '{print $1}' <<< "${SSH_CONNECTION:-198.51.100.1}");
    _e136_is_ipv4 "$addr" || addr=198.51.100.1;
    if test -n "${SSH_CONNECTION:-}"; then
        local a b c d;
        read -r a b c d <<< "$SSH_CONNECTION";
        context=live-ssh;
        local_port=${d:-none};
    fi;
    current_dump=$(_e141_sshd_effective_dump) || return 1;
    current_profile=$(_e142_classify_auth_dump "$current_dump" "$current_user") || return 1;
    current_mode=$(sed -n 's/^mode=//p' <<< "$current_profile" | head -n1);
    profiles+="user=$current_user,current=1,$(tr '\n' ',' <<< "$current_profile")\n";
    test "$current_mode" = password-capable && overall=password-capable;
    while IFS= read -r user; do
        any=1;
        dump=$(sshd -T -C "user=$user,host=$host,addr=$addr" 2> /dev/null) || return 1;
        profile=$(_e142_classify_auth_dump "$dump" "$user") || return 1;
        mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1);
        profiles+="user=$user,current=0,$(tr '\n' ',' <<< "$profile")\n";
        test "$mode" = password-capable && overall=password-capable;
    done < <(_e152_login_users);
    _e142_match_blocks_may_allow_secret && match_risk=1 || true;
    if test "$overall" != password-capable; then
        if test "$match_risk" = 1; then
            overall=ambiguous;
        else
            if test "$current_mode" = key-only; then
                overall=key-only;
            else
                overall=non-password;
            fi;
        fi;
    fi;
    printf 'mode=%s\nevaluated_user=%s\ncontext=%s\nlocal_port=%s\nlogin_user_count=%s\nmatch_secret_risk=%s\n' "$overall" "$current_user" "$context" "$local_port" "$any" "$match_risk";
    sed 's/^/current_/' <<< "$current_profile";
    printf 'profiles=%b' "$profiles"
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_sshd_effective_dump
_e141_sshd_effective_dump() {
    local user host client_ip client_port local_ip local_port;
    command -v sshd > /dev/null 2>&1 || return 1;
    user="${SUDO_USER:-${USER:-root}}";
    id "$user" > /dev/null 2>&1 || user=root;
    host=$(hostname -f 2> /dev/null || hostname 2> /dev/null || echo localhost);
    if test -n "${SSH_CONNECTION:-}"; then
        read -r client_ip client_port local_ip local_port <<< "$SSH_CONNECTION";
        if [[ "$client_ip" =~ ^[0-9A-Fa-f:.]+$ ]] && [[ "$client_port" =~ ^[0-9]+$ ]] && [[ "$local_ip" =~ ^[0-9A-Fa-f:.]+$ ]] && [[ "$local_port" =~ ^[0-9]+$ ]] && ((client_port >= 1 && client_port <= 65535)) && ((local_port >= 1 && local_port <= 65535)); then
            sshd -T -C "user=$user,host=$host,addr=$client_ip,laddr=$local_ip,lport=$local_port" 2> /dev/null || return 1;
            return 0;
        fi;
    fi;
    sshd -T 2> /dev/null
}
# EEX3-FUNCTION ssh_security_e141_158 _e141_wait_apt_locks
_e141_wait_apt_locks() {
    local i holder;
    for i in $(seq 1 60);
    do
        holder="";
        for f in /var/lib/dpkg/lock-frontend /var/lib/dpkg/lock /var/cache/apt/archives/lock /var/lib/apt/lists/lock;
        do
            test -e "$f" || continue;
            if command -v fuser > /dev/null 2>&1 && fuser "$f" > /dev/null 2>&1; then
                holder=1;
                break;
            fi;
        done;
        test -z "$holder" && return 0;
        sleep 2;
    done;
    return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_atomic_text
_e142_atomic_text() {
    local src="$1" dst="$2" mode="${3:-0600}" stage parent name;
    _e214_ensure_parent_dir "$dst" || return 1;
    parent=$(dirname -- "$dst") || return 1;
    name=${dst##*/};
    stage=$(mktemp --tmpdir="$parent" ".${name}.e142-new.XXXXXX") || return 1;
    install -m "$mode" "$src" "$stage" || { 
        rm -f -- "$stage";
        return 1
    };
    mv -f -- "$stage" "$dst" || { 
        rm -f -- "$stage";
        return 1
    }
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_classify_auth_dump
_e142_classify_auth_dump() {
    local dump="$1" user="${2:-root}" password kbd challenge methods pubkey permitroot usepam;
    local secret=0 mode=non-password normalized;
    password=$(awk '$1=="passwordauthentication"{print tolower($2);exit}' <<< "$dump");
    kbd=$(awk '$1=="kbdinteractiveauthentication"{print tolower($2);exit}' <<< "$dump");
    challenge=$(awk '$1=="challengeresponseauthentication"{print tolower($2);exit}' <<< "$dump");
    methods=$(awk '$1=="authenticationmethods"{$1="";sub(/^ /,"");print tolower($0);exit}' <<< "$dump");
    pubkey=$(awk '$1=="pubkeyauthentication"{print tolower($2);exit}' <<< "$dump");
    permitroot=$(awk '$1=="permitrootlogin"{print tolower($2);exit}' <<< "$dump");
    usepam=$(awk '$1=="usepam"{print tolower($2);exit}' <<< "$dump");
    password=${password:-yes};
    kbd=${kbd:-${challenge:-yes}};
    challenge=${challenge:-$kbd};
    methods=${methods:-any};
    pubkey=${pubkey:-yes};
    permitroot=${permitroot:-unknown};
    usepam=${usepam:-unknown};
    if test "$user" = root; then
        case "$permitroot" in 
            no | prohibit-password | without-password | forced-commands-only)
                password=no;
                kbd=no;
                challenge=no
            ;;
        esac;
    fi;
    if test "$methods" = any; then
        test "$password" = yes && secret=1;
        { 
            test "$kbd" = yes || test "$challenge" = yes
        } && secret=1;
    else
        normalized=${methods//keyboard-interactive:pam/keyboard-interactive};
        normalized=${normalized//keyboard-interactive:bsdauth/keyboard-interactive};
        [[ " $normalized " == *" password"* || " $normalized " == *",password"* ]] && test "$password" = yes && secret=1;
        [[ " $normalized " == *" keyboard-interactive"* || " $normalized " == *",keyboard-interactive"* ]] && { 
            test "$kbd" = yes || test "$challenge" = yes
        } && secret=1;
    fi;
    if test "$secret" -eq 1; then
        mode="password-capable";
    else
        if test "$pubkey" = yes; then
            mode="key-only";
        else
            mode="non-password";
        fi;
    fi;
    printf 'mode=%s\npasswordauthentication=%s\nkbdinteractiveauthentication=%s\nchallengeresponseauthentication=%s\nauthenticationmethods=%s\npubkeyauthentication=%s\npermitrootlogin=%s\nusepam=%s\n' "$mode" "$password" "$kbd" "$challenge" "$methods" "$pubkey" "$permitroot" "$usepam"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_core_install_base
_e142_core_install_base() {
    title "V199e137：安装 / 确认 Xray Core";
    if test -x "$XRAY_BIN"; then
        info "检测到现有 Xray Core：$($XRAY_BIN version 2> /dev/null | head -n1 || echo "$XRAY_BIN")";
        return 0;
    fi;
    local installer logf;
    installer=$(_e118_mktemp xray-install.sh) || return 1;
    logf=$(_e118_mktemp xray-install.log) || return 1;
    info "下载并校验官方 Xray 安装脚本。";
    _e118_download_official_installer "$installer" || { 
        error "官方安装脚本下载/语法校验失败。";
        return 1
    };
    if ! bash "$installer" install > "$logf" 2>&1; then
        error "Xray Core 安装失败。";
        tail -n 100 "$logf" | sed 's/^/    /' || true;
        return 1;
    fi;
    test -x "$XRAY_BIN" || { 
        error "安装器结束后仍未发现 $XRAY_BIN";
        return 1
    };
    info "Xray Core 安装完成：$($XRAY_BIN version 2> /dev/null | head -n1)"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_create_uninstall_archive
_e142_create_uninstall_archive() {
    local archive="$1" list p;
    list=$(_e118_mktemp uninstall-files-e142) || return 1;
    : > "$list" || return 1;
    for p in "$CONFIG_DIR" "$SCRIPT_DIR" "$DAT_DIR" "$LOG_DIR" "$XRAY_BIN" "$SYMLINK";
    do
        if test -e "$p" || test -L "$p"; then
            printf '%s\n' "${p#/}" >> "$list";
        fi;
    done;
    find /etc/systemd/system -maxdepth 2 \( -type f -o -type d -o -type l \) -name 'xray*' -printf '%p\n' 2> /dev/null | sed 's#^/##' >> "$list" || true;
    find /etc/sysctl.d /etc/fail2ban /etc/rsyslog.d -maxdepth 3 -type f \( -name '*xray*' -o -name '99-xray-*' -o -name 'zz-xray-*' \) -printf '%p\n' 2> /dev/null | sed 's#^/##' >> "$list" || true;
    awk 'NF&&!seen[$0]++' "$list" > "${list}.unique" || return 1;
    test -s "${list}.unique" || return 1;
    tar -C / -czf "$archive" -T "${list}.unique" 2> /dev/null || return 1;
    chmod 0600 "$archive" || return 1;
    test -s "$archive" && tar -tzf "$archive" > /dev/null 2>&1
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_fail2ban_install_base
_e142_fail2ban_install_base() {
    local os rc=0;
    _e141_prepare || return 1;
    : > "$E141_F2B_INSTALL_LOG" || return 1;
    exec 8>> "$E141_F2B_INSTALL_LOG";
    printf '[%s] fail2ban install start\n' "$(date -Is)" 1>&8;
    if command -v fail2ban-client > /dev/null 2>&1; then
        fail2ban-client --version 1>&8 2>&1 || true;
        exec 8>&-;
        return 0;
    fi;
    os="$(detect_os)";
    case "$os" in 
        debian | ubuntu)
            export DEBIAN_FRONTEND=noninteractive;
            _e141_wait_apt_locks || { 
                echo 'APT/DPKG lock timeout' 1>&8;
                exec 8>&-;
                return 1
            };
            dpkg --configure -a 1>&8 2>&1 || true;
            apt-get -f install -y 1>&8 2>&1 || true;
            apt-get update 1>&8 2>&1 || rc=$?;
            if test "$rc" -ne 0; then
                echo "apt-get update rc=$rc; attempting cached install" 1>&8;
            fi;
            rc=0;
            apt-get install -y --no-install-recommends fail2ban python3-systemd 1>&8 2>&1 || rc=$?;
            if test "$rc" -ne 0; then
                echo "first install rc=$rc; retry after dpkg repair" 1>&8;
                dpkg --configure -a 1>&8 2>&1 || true;
                apt-get -f install -y 1>&8 2>&1 || true;
                apt-get install -y fail2ban 1>&8 2>&1 || rc=$?;
            fi
        ;;
        centos | rhel | rocky | almalinux | fedora)
            rc=0;
            if command -v dnf > /dev/null 2>&1; then
                dnf install -y epel-release 1>&8 2>&1 || true;
                dnf install -y fail2ban fail2ban-systemd 1>&8 2>&1 || rc=$?;
            else
                yum install -y epel-release 1>&8 2>&1 || true;
                yum install -y fail2ban fail2ban-systemd 1>&8 2>&1 || rc=$?;
            fi
        ;;
        *)
            echo "unsupported os=$os" 1>&8;
            rc=1
        ;;
    esac;
    hash -r 2> /dev/null || true;
    if ! command -v fail2ban-client > /dev/null 2>&1; then
        echo "fail2ban-client still missing, rc=$rc" 1>&8;
        exec 8>&-;
        return 1;
    fi;
    systemctl daemon-reload 1>&8 2>&1 || true;
    fail2ban-client --version 1>&8 2>&1 || { 
        exec 8>&-;
        return 1
    };
    exec 8>&-;
    return 0
}
