# EEX3-FUNCTION ssh_security_e141_158 _e142_full_snapshot_base
_e142_full_snapshot_base() {
    local tx="$1" p;
    install -d -m 0700 "$tx" || return 1;
    for p in "$CONFIG" "$E139_WARP_STATE" "$E140_FULL_ROUTE_SCRIPT" "$E140_FULL_ROUTE_SERVICE" "$E140_FULL_HEALTH_SERVICE" "$E140_FULL_HEALTH_TIMER" "$E140_FULL_ROLLBACK_SERVICE" "$E140_FULL_ROLLBACK_TIMER";
    do
        _e135_snapshot_file "$p" "$tx/$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || return 1;
    done;
