}
# EEX3-FUNCTION ssh_security_e141_158 _e142_full_snapshot_verify
_e142_full_snapshot_verify() {
    local tx="$1";
    _e142_full_tx_ok "$tx" || return 1;
    test -s "$tx/e142-snapshot.sha256" || return 2;
    ( cd "$tx" && sha256sum -c e142-snapshot.sha256 > /dev/null 2>&1 )
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_full_tx_ok
_e142_full_tx_ok() {
    local d="$1" real root;
    test -d "$d" || return 1;
    real=$(readlink -f -- "$d" 2> /dev/null || true);
    test -n "$real" || return 1;
    for root in "$E142_TX_ROOT" "$E140_TX_ROOT";
    do
        root=$(readlink -f -- "$root" 2> /dev/null || true);
        test -n "$root" || continue;
        case "$real" in 
            "$root"/*)
                return 0
            ;;
        esac;
    done;
    return 1
}
