# EEX3-FUNCTION ssh_security_e141_158 _e142_hot_update
_e142_hot_update() {
    local protect sysbackup rc=0 rollback_rc=0 was_active=0 enabled=0 mode=disabled profile=disabled;
    local e140_dir_preexisting=0 e142_dir_preexisting=0;
    E135_NEW_PACKAGES=();
    test -e "$E140_DIR" && e140_dir_preexisting=1 || true;
    test -e "$E142_DIR" && e142_dir_preexisting=1 || true;
    _e140_prepare || return 1;
    _e142_prepare || return 1;
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    protect=$(_e116_backup_state before_hot_update_e142) || return 1;
    _e118_save_core_payload "$protect" || return 1;
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
    was_active=${was_active:-0};
    sysbackup=$(_e142_new_tx hot-update) || return 1;
    _e140_system_snapshot "$sysbackup" || { 
        error "E142系统快照失败。";
        return 1
    };
    _e135_require_runtime_tools || rc=1;
    test "$rc" -ne 0 || _e135_disable_legacy_optimizers || rc=1;
    test "$rc" -ne 0 || _e140_install_self || rc=1;
    test "$rc" -ne 0 || install_update_dat || rc=1;
    test "$rc" -ne 0 || systemctl enable --now xray-dat-update.timer > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || _e105_disable_xray_core_auto_update || rc=1;
    test "$rc" -ne 0 || _e137_apply_init_window_default30 || rc=1;
    test "$rc" -ne 0 || _e139_network_apply balanced force || rc=1;
    test "$rc" -ne 0 || _e121_install_log_retention || rc=1;
    test "$rc" -ne 0 || _e141_install_ssh_guard || rc=1;
    test "$rc" -ne 0 || fix_xray_systemd_limits || rc=1;
    if test "$rc" = 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e140_full_install_units || rc=1;
            test "$rc" -ne 0 || _e140_warp_full_reconcile || rc=1;
        else
            _e137_warp_connect_local_proxy || rc=1;
            test "$rc" -ne 0 || _e138_xray_apply_warp "$mode" "$profile" true || rc=1;
            test "$rc" -ne 0 || _e138_warp_health_install || rc=1;
        fi;
    fi;
    test "$rc" -ne 0 || _e142_write_version || rc=1;
    test "$rc" -ne 0 || { 
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1
    } || rc=1;
    if test "$rc" = 0 && test -s "$CONFIG"; then
        _e118_xray_test_config "$CONFIG" 1 || rc=1;
    fi;
    if test "$rc" = 0 && test "$was_active" = 1; then
        _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
        test "$rc" -ne 0 || _e131_verify_nice_runtime || rc=1;
    else
        if test "$rc" = 0 && systemctl is-active --quiet xray.service 2> /dev/null; then
            error "热更新意外启动了原本停止的Xray服务。";
            rc=1;
        fi;
    fi;
    test "$rc" -ne 0 || test "$(sysctl -n net.ipv4.tcp_notsent_lowat 2> /dev/null)" = 131072 || rc=1;
    test "$rc" -ne 0 || test "$(sysctl -n net.ipv6.conf.all.disable_ipv6 2> /dev/null)" = 1 || rc=1;
    test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
    test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
    test "$rc" -ne 0 || systemctl is-enabled --quiet xray-dat-update.timer 2> /dev/null || rc=1;
    test "$rc" -ne 0 || systemctl is-enabled --quiet xray-log-retention-e121.timer 2> /dev/null || rc=1;
    test "$rc" -ne 0 || systemctl is-enabled --quiet xray-ssh-auth-audit-e142.timer 2> /dev/null || rc=1;
    test "$rc" -ne 0 || test -x "$E142_LOG_EXTRA_SCRIPT" || rc=1;
    test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$SYMLINK" || rc=1;
    test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E142_SELF_PATH" || rc=1;
    if test "$rc" -ne 0; then
        error "E142热更新失败，恢复系统文件、Core、Xray、WARP、防火墙和服务状态。";
        _e140_system_restore "$sysbackup" || rollback_rc=1;
        _e118_restore_core_payload "$protect" > /dev/null 2>&1 || rollback_rc=1;
        _e118_restore_state "$protect" > /dev/null 2>&1 || rollback_rc=1;
        _e135_remove_new_runtime_tools || true;
        test "$e142_dir_preexisting" = 1 || rmdir "$E142_DIR" 2> /dev/null || true;
        test "$e140_dir_preexisting" = 1 || rmdir "$E140_DIR" 2> /dev/null || true;
        if test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 > /dev/null 2>&1 || rollback_rc=1;
        fi;
        if test "$rollback_rc" -ne 0; then
            install -d -m 0700 "$E142_DIR" 2> /dev/null || true;
            { 
                echo "time=$(date -Is 2> /dev/null || date)";
                echo "operation=hot-update";
                echo "system_backup=$sysbackup";
                echo "core_backup=$protect"
            } > "${E142_CRITICAL_MARKER}.new.$$" 2> /dev/null && chmod 0600 "${E142_CRITICAL_MARKER}.new.$$" 2> /dev/null && mv -f -- "${E142_CRITICAL_MARKER}.new.$$" "$E142_CRITICAL_MARKER" 2> /dev/null || true;
            error "严重：热更新回滚未通过复检。系统快照：$sysbackup；Core快照：$protect";
        fi;
        return 1;
    fi;
    rm -f "$E142_CRITICAL_MARKER" 2> /dev/null || true;
    _e142_prune_transactions "$sysbackup" "$protect" || warn "旧系统事务快照收敛未完成；当前热更新结果不受影响。";
    info "V199e142热更新完成。系统快照：$sysbackup";
    info "已验证：Xray Core/配置/运行态、init30、notsent=131072、IPv6关闭、3天日志、SSH认证策略；WARP mode=$mode。"
}
