# EEX3-FUNCTION ssh_security_e141_158 _e142_install_ssh_auth_audit_base
_e142_install_ssh_auth_audit_base() {
    local service_tmp timer_tmp;
    service_tmp=$(_e118_mktemp ssh-auth-audit-e142.service) || return 1;
    timer_tmp=$(_e118_mktemp ssh-auth-audit-e142.timer) || return 1;
    cat > "$service_tmp" <<'EOF_E142_AUTH_SERVICE'
[Unit]
Description=V199e142 reconcile SSH authentication policy and fail2ban
After=network-online.target ssh.service sshd.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/xrv --ssh-auth-reconcile-boot
TimeoutStartSec=600
EOF_E142_AUTH_SERVICE

    cat > "$timer_tmp" <<'EOF_E142_AUTH_TIMER'
[Unit]
Description=Periodic SSH authentication and fail2ban policy reconciliation

[Timer]
OnBootSec=90s
OnUnitActiveSec=15min
AccuracySec=1min
Persistent=true
Unit=xray-ssh-auth-audit-e142.service

[Install]
WantedBy=timers.target
EOF_E142_AUTH_TIMER

    _e121_atomic_install "$service_tmp" "$E142_SSH_AUTH_SERVICE" 0644 || return 1;
    _e121_atomic_install "$timer_tmp" "$E142_SSH_AUTH_TIMER" 0644 || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl enable --now xray-ssh-auth-audit-e142.timer > /dev/null 2>&1 || return 1;
    systemctl is-enabled --quiet xray-ssh-auth-audit-e142.timer 2> /dev/null
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_install_update_dat_base
_e142_install_update_dat_base() {
