}
# EEX3-FUNCTION ssh_security_e141_158 _e142_key_only_guard_base
_e142_key_only_guard_base() {
    local firewall_backup="";
    title "V199e142：Key-only SSH端口自适应防锁";
    command -v sshd > /dev/null 2>&1 || { 
        error "未检测到OpenSSH sshd。";
        return 1
    };
    sshd -t > "$E118_TMPDIR/sshd-test.log" 2>&1 || { 
        error "sshd -t未通过。";
        sed 's/^/    /' "$E118_TMPDIR/sshd-test.log";
        return 1
    };
    if command -v iptables-save > /dev/null 2>&1; then
        firewall_backup="$E118_BACKUP_DIR/iptables_before_ssh_e142_$(date +%Y%m%d_%H%M%S)_$$.rules";
        iptables-save > "$firewall_backup" 2> /dev/null || firewall_backup="";
    fi;
    _e142_write_key_only_guard || return 1;
    _e121_apply_ssh_port_guard || { 
        error "Key-only SSH端口守护首次应用失败。";
        return 1
    };
    _e142_verify_key_only_guard || { 
        error "Key-only SSH端口/开机守护复检失败。";
        return 1
    };
    info "有效认证为Key-only：不强制安装fail2ban；SSH端口已放行并启用开机/5分钟复检。";
    test -z "$firewall_backup" || info "iptables变更前快照：$firewall_backup"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_log_retention_base
_e142_log_retention_base() {
    local script_tmp service_tmp timer_tmp journal_tmp rotate_tmp;
    command -v logrotate > /dev/null 2>&1 || pkg_install logrotate || { 
        error "无法安装 logrotate，3天滚动日志未落地。";
        return 1
    };
    script_tmp=$(_e118_mktemp log-retention-e121) || return 1;
    service_tmp=$(_e118_mktemp log-retention-service-e121) || return 1;
    timer_tmp=$(_e118_mktemp log-retention-timer-e121) || return 1;
    journal_tmp=$(_e118_mktemp journald-retention-e121) || return 1;
    rotate_tmp=$(_e118_mktemp logrotate-e121) || return 1;
    cat > "$script_tmp" <<'EOF_E121_LOG_SCRIPT'
#!/usr/bin/env bash
set -u
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
journalctl --vacuum-time=3d >/dev/null 2>&1 || true
if command -v logrotate >/dev/null 2>&1 && test -f /etc/logrotate.d/xray-e121; then
    # 使用发行版默认状态文件，与系统 logrotate.timer/cron 共享轮转进度，避免一天转两次。
    logrotate /etc/logrotate.d/xray-e121 >/dev/null 2>&1 || exit 1
fi
# 只删除明确的轮转归档，不碰当前 auth/fail2ban/Xray 活动日志。
find /var/log -maxdepth 1 -type f -mtime +3 \
    \( -name 'auth.log.*' -o -name 'secure-*' -o -name 'fail2ban.log.*' \
       -o -name 'fail2ban.log-*' -o -name 'xray-fail2ban.log.*' -o -name 'xray-fail2ban.log-*' \
       -o -name 'xray-sshd-auth.log.*' -o -name 'xray-sshd-auth.log-*' \) \
    -delete 2>/dev/null || true
exit 0
EOF_E121_LOG_SCRIPT

    cat > "$journal_tmp" <<'EOF_E121_JOURNAL'
[Journal]
Storage=persistent
MaxRetentionSec=3day
MaxFileSec=1day
EOF_E121_JOURNAL

    cat > "$rotate_tmp" <<'EOF_E121_ROTATE'
/var/log/xray/*.log /var/log/xray/*/*.log /var/log/xray/*/*/*.log /var/log/xray-sshd-auth.log /var/log/xray-fail2ban.log {
    daily
    rotate 3
    maxage 3
    missingok
    notifempty
    compress
    delaycompress
    dateext
    copytruncate
    su root root
}
EOF_E121_ROTATE

    cat > "$service_tmp" <<EOF_E121_LOG_SERVICE
[Unit]
Description=Xray and SSH security log 3-day retention
After=systemd-journald.service

[Service]
Type=oneshot
ExecStart=$E121_LOG_RETENTION_SCRIPT
EOF_E121_LOG_SERVICE

    cat > "$timer_tmp" <<'EOF_E121_LOG_TIMER'
[Unit]
Description=Daily Xray and SSH security log retention

[Timer]
OnCalendar=*-*-* 04:20:00
RandomizedDelaySec=15min
Persistent=true
Unit=xray-log-retention-e121.service

[Install]
WantedBy=timers.target
EOF_E121_LOG_TIMER

    logrotate -d "$rotate_tmp" > /dev/null 2>&1 || { 
        error "e121 logrotate 候选配置测试失败。";
        return 1
    };
    _e121_atomic_install "$script_tmp" "$E121_LOG_RETENTION_SCRIPT" 0755 || return 1;
    if test -f /etc/systemd/journald.conf.d/99-xray-volatile.conf; then
        mkdir -p "$E118_BACKUP_DIR/log-retention-e121" || return 1;
        cp -a /etc/systemd/journald.conf.d/99-xray-volatile.conf "$E118_BACKUP_DIR/log-retention-e121/99-xray-volatile.conf.$(date +%Y%m%d_%H%M%S).bak" || return 1;
        rm -f /etc/systemd/journald.conf.d/99-xray-volatile.conf || return 1;
    fi;
    _e121_atomic_install "$journal_tmp" "$E121_JOURNAL_CONF" 0644 || return 1;
    _e121_atomic_install "$rotate_tmp" "$E121_LOGROTATE_CONF" 0644 || return 1;
    _e121_atomic_install "$service_tmp" "$E121_LOG_RETENTION_SERVICE" 0644 || return 1;
    _e121_atomic_install "$timer_tmp" "$E121_LOG_RETENTION_TIMER" 0644 || return 1;
    systemctl disable --now xray-log-retention-e120.timer xray-log-retention-e120.service > /dev/null 2>&1 || true;
    rm -f -- /usr/local/bin/xray-log-retention-e120.sh /etc/systemd/system/xray-log-retention-e120.service /etc/systemd/system/xray-log-retention-e120.timer /etc/systemd/journald.conf.d/zz-xray-retention-e120.conf /etc/logrotate.d/xray-e120 /var/lib/logrotate/xray-e120.status /var/lib/logrotate/xray-e121.status 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    mkdir -p /var/log/journal || return 1;
    systemd-tmpfiles --create --prefix /var/log/journal > /dev/null 2>&1 || true;
    systemctl restart systemd-journald > /dev/null 2>&1 || return 1;
    systemctl enable --now xray-log-retention-e121.timer > /dev/null 2>&1 || return 1;
    systemctl start xray-log-retention-e121.service > /dev/null 2>&1 || return 1;
    systemctl is-enabled --quiet xray-log-retention-e121.timer 2> /dev/null || return 1;
    info "journald、SSH 安全日志与 Xray 日志已设置为每日滚动、最多保留3天。"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_log_retention_before_migration
_e142_log_retention_before_migration() {
    local script_tmp dropin_tmp rc=0 had_logrotate=0;
    _e135_pkg_present logrotate && had_logrotate=1 || true;
    _e142_log_retention_base || rc=$?;
    if test "$had_logrotate" -eq 0 && _e135_pkg_present logrotate; then
        E135_NEW_PACKAGES+=(logrotate);
    fi;
    test "$rc" -eq 0 || return "$rc";
    script_tmp=$(_e118_mktemp log-retention-extra-e142.sh) || return 1;
    dropin_tmp=$(_e118_mktemp log-retention-extra-e142.conf) || return 1;
    cat > "$script_tmp" <<'EOF_E142_LOG_EXTRA'
#!/usr/bin/env bash
set -u
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
# Base logrotate covers current top-level and nested *.log files.  Only remove
# old rotated archives here; deleting a quiet current log unlinks the file
# while a daemon may still hold its descriptor and is not a real rotation.
if test -d /var/log/xray; then
    find /var/log/xray -mindepth 2 -type f -mmin +4320 \
        \( -name '*.log.[0-9]*' -o -name '*.log-*.gz' -o -name '*.log.*.gz' \) \
        -delete 2>/dev/null || true
    find /var/log/xray -mindepth 2 -type d -empty -mmin +4320 -delete 2>/dev/null || true
fi
# GNU find -mtime +3 rounds in 24-hour units and can retain nearly four days.
# Use 4320 minutes for the security archives that are not owned by logrotate.
find /var/log -maxdepth 1 -type f -mmin +4320 \
    \( -name 'auth.log.*' -o -name 'secure-*' -o -name 'fail2ban.log.*' \
       -o -name 'fail2ban.log-*' -o -name 'xray-fail2ban.log.*' -o -name 'xray-fail2ban.log-*' \
       -o -name 'xray-sshd-auth.log.*' -o -name 'xray-sshd-auth.log-*' \) \
    -delete 2>/dev/null || true
exit 0
EOF_E142_LOG_EXTRA

    cat > "$dropin_tmp" <<EOF_E142_LOG_DROPIN
[Service]
ExecStartPost=$E142_LOG_EXTRA_SCRIPT
EOF_E142_LOG_DROPIN

    bash -n "$script_tmp" || return 1;
    _e121_atomic_install "$script_tmp" "$E142_LOG_EXTRA_SCRIPT" 0755 || return 1;
    install -d -m 0755 "$E142_LOG_DROPIN_DIR" || return 1;
    _e121_atomic_install "$dropin_tmp" "$E142_LOG_DROPIN" 0644 || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl start xray-log-retention-e121.service > /dev/null 2>&1 || return 1;
    systemctl is-enabled --quiet xray-log-retention-e121.timer 2> /dev/null || return 1;
    info "嵌套WARP/fail2ban安装日志也已纳入3天清理。"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_match_blocks_may_allow_secret
_e142_match_blocks_may_allow_secret() {
    local f;
    local -a files=();
    while IFS= read -r f; do
        files+=("$f");
    done < <(_e142_sshd_config_files);
    test "${#files[@]}" -gt 0 || return 1;
    awk '
      BEGIN{inmatch=0; risky=0}
      /^[[:space:]]*#/ || /^[[:space:]]*$/ {next}
      tolower($1)=="match" {inmatch=1; next}
      inmatch && tolower($1)=="passwordauthentication" && tolower($2)=="yes" {risky=1}
      inmatch && (tolower($1)=="kbdinteractiveauthentication" || tolower($1)=="challengeresponseauthentication") && tolower($2)=="yes" {risky=1}
      inmatch && tolower($1)=="authenticationmethods" {
        x=tolower($0); if(x ~ /(^|[ ,])(password|keyboard-interactive)(:[a-z0-9_-]+)?([ ,]|$)/) risky=1
      }
      END{exit !risky}
    ' "${files[@]}" 2> /dev/null
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_network_apply_base
_e142_network_apply_base() {
    local profile="${1:-balanced}" confirm="${2:-}" candidate backup key value old failed=0 iface_file dir_preexisting=0;
    _e139_prepare || return 1;
    test -d /etc/sysctl.d && dir_preexisting=1 || true;
    _e139_ensure_parent "$E139_NETWORK_CONF" || { 
        error "无法创建或写入 /etc/sysctl.d。";
        return 1
    };
    candidate=$(_e118_mktemp e139-network.conf) || return 1;
    _e136_network_candidate "$profile" "$candidate" || return 1;
    sed -i '1s/ex199e136/ex199e142/' "$candidate" 2> /dev/null || true;
    grep -q '^net.ipv4.conf.all.rp_filter' "$candidate" || echo 'net.ipv4.conf.all.rp_filter = 2' >> "$candidate";
    grep -q '^net.ipv4.conf.default.rp_filter' "$candidate" || echo 'net.ipv4.conf.default.rp_filter = 2' >> "$candidate";
    _e135_network_validate "$candidate" || return 1;
    if test "$confirm" != force; then
        warn "将创建/验证/etc/sysctl.d，迁移旧定义并唯一写入$E139_NETWORK_CONF。";
        read -rp "输入 APPLY-NETWORK 确认: " confirm || true;
        test "$confirm" = APPLY-NETWORK || { 
            info "已取消。";
            return 0
        };
    fi;
    backup=$(_e139_new_tx network) || return 1;
    printf 'dir_preexisting=%s\n' "$dir_preexisting" > "$backup/meta.env" || return 1;
    : > "$backup/runtime.env" || return 1;
    while IFS= read -r key; do
        old=$(sysctl -n "$key" 2> /dev/null || true);
        printf '%s|%s\n' "$key" "$old" >> "$backup/runtime.env" || return 1;
    done < <(_e136_network_keys);
    _e135_snapshot_file "$E139_NETWORK_CONF" "$backup/e139-conf" || return 1;
    _e135_snapshot_file "$E138_NETWORK_CONF" "$backup/e138-conf" || return 1;
    _e135_snapshot_file "$E136_NETWORK_CONF" "$backup/e136-conf" || return 1;
    _e135_snapshot_file "$E135_NETWORK_CONF" "$backup/e135-conf" || return 1;
    _e139_network_backup_and_strip "$backup" || { 
        error "旧sysctl定义迁移失败。";
        _e139_network_rollback "$backup" "$dir_preexisting" || error "严重：网络事务回滚不完整，恢复材料：$backup";
        return 1
    };
    _e142_seal_network_tx "$backup" || { 
        error "网络事务快照封存失败，拒绝继续应用。";
        _e139_network_rollback "$backup" "$dir_preexisting" || error "严重：网络事务回滚不完整，恢复材料：$backup";
        return 1
    };
    install -m 0644 "$candidate" "$E139_NETWORK_CONF" || failed=1;
    if test "$failed" -eq 0; then
        while IFS='=' read -r key value; do
            key=$(printf '%s' "$key" | xargs);
            value=$(printf '%s' "$value" | xargs);
            case "$key" in 
                '' | '#'*)
                    continue
                ;;
            esac;
            test -w "/proc/sys/${key//./\/}" || continue;
            sysctl -w "$key=$value" > /dev/null 2>&1 || { 
                failed=1;
                break
            };
        done < "$candidate";
    fi;
    if test "$failed" -eq 0; then
        for iface_file in /proc/sys/net/ipv6/conf/*/disable_ipv6;
        do
            test -e "$iface_file" || continue;
            printf '1\n' > "$iface_file" 2> /dev/null || { 
                failed=1;
                break
            };
        done;
    fi;
    if test "$failed" -eq 0; then
        while IFS='=' read -r key value; do
            key=$(printf '%s' "$key" | xargs);
            value=$(printf '%s' "$value" | xargs);
            case "$key" in 
                '' | '#'*)
                    continue
                ;;
            esac;
            test -e "/proc/sys/${key//./\/}" || continue;
            test "$(sysctl -n "$key" 2> /dev/null | xargs)" = "$value" || { 
                error "运行态读回失败：$key";
                failed=1;
                break
            };
        done < "$candidate";
    fi;
    if test "$failed" -ne 0; then
        error "E139网络参数应用失败，恢复文件、运行值和目录状态。";
        _e139_network_rollback "$backup" "$dir_preexisting" || error "严重：网络事务回滚不完整，恢复材料：$backup";
        return 1;
    fi;
    rm -f "$E135_NETWORK_CONF" "$E136_NETWORK_CONF" "$E138_NETWORK_CONF" 2> /dev/null || true;
    if ! { 
        echo "profile=$profile";
        echo "applied=$(date -Is 2> /dev/null || date)";
        echo "tcp_notsent_lowat=131072";
        echo "ipv6_disabled=1";
        echo "owner=$E139_NETWORK_CONF";
        echo "backup=$backup"
    } > "$E139_NETWORK_STATE"; then
        error "网络状态文件写入失败，回滚网络事务。";
        _e139_network_rollback "$backup" "$dir_preexisting" || error "严重：网络事务回滚不完整，恢复材料：$backup";
        return 1;
    fi;
    chmod 0600 "$E139_NETWORK_STATE" 2> /dev/null || true;
    info "V199e142统一网络参数已应用并读回：/etc/sysctl.d可用，notsent=131072，IPv6关闭。"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_network_tx_dir_ok
_e142_network_tx_dir_ok() {
    _e152_network_tx_dir_ok "$@"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_new_tx
_e142_new_tx() {
    local name="${1:-tx}" safe d;
    _e142_prepare || return 1;
    safe=$(printf '%s' "$name" | tr -c 'A-Za-z0-9_.-' '_');
    test -n "$safe" || safe=tx;
    d="$E142_TX_ROOT/${safe}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM";
    install -d -m 0700 "$d" || return 1;
    printf '%s\n' "$d"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_patch_dat_updater
_e142_patch_dat_updater() {
    local tmp;
    test -x "$UPDATE_DAT_SCRIPT" || return 1;
    grep -q 'E142 exact MainPID socket ownership v2' "$UPDATE_DAT_SCRIPT" 2> /dev/null && return 0;
    tmp=$(_e118_mktemp update-dat-e142.sh) || return 1;
    awk '
      /^ok=0$/ && !done {
        print "# E142 exact MainPID socket ownership v2"
        print "pid_owns_port() {"
        print "    local proto=\"$1\" port=\"$2\" pid=\"$3\" want state table inode fd target"
        print "    case \"$port\" in \"\"|*[!0-9]*) return 1;; esac"
        print "    test \"$port\" -ge 1 && test \"$port\" -le 65535 || return 1"
        print "    case \"$pid\" in \"\"|0|*[!0-9]*) return 1;; esac"
        print "    want=$(printf '''%04X''' \"$port\")"
        print "    if test \"$proto\" = tcp; then state=0A; set -- /proc/net/tcp /proc/net/tcp6"
        print "    elif test \"$proto\" = udp; then state=07; set -- /proc/net/udp /proc/net/udp6; else return 1; fi"
        print "    for table in \"$@\"; do"
        print "        test -r \"$table\" || continue"
        print "        while IFS= read -r inode; do"
        print "            case \"$inode\" in \"\"|*[!0-9]*) continue;; esac"
        print "            for fd in \"/proc/$pid/fd/\"*; do"
        print "                test -L \"$fd\" || continue"
        print "                target=$(readlink -- \"$fd\" 2>/dev/null || true)"
        print "                test \"$target\" = \"socket:[$inode]\" && return 0"
        print "            done"
        print "        done < <(awk -v p=\"$want\" -v s=\"$state\" '\''NR>1{split($2,a,\":\"); if(toupper(a[2])==p && toupper($4)==s) print $10}'\'' \"$table\")"
        print "    done"
        print "    return 1"
        print "}"
        print "socket_ready() {"
        print "    local proto=\"$1\" port=\"$2\" pid=\"$3\" line out"
        print "    if test \"$proto\" = tcp; then out=$(ss -H -ltnp 2>/dev/null || true); else out=$(ss -H -lunp 2>/dev/null || true); fi"
        print "    while IFS= read -r line; do"
        print "        test -n \"$line\" || continue"
        print "        awk -v p=\":$port\" '\''$4 ~ p\"$\"{ok=1} END{exit !ok}'\'' <<< \"$line\" || continue"
        print "        if [[ \"$line\" == *\"users:\"* ]]; then [[ \"$line\" == *\"pid=$pid,\"* ]] && return 0; fi"
        print "    done <<< \"$out\""
        print "    pid_owns_port \"$proto\" \"$port\" \"$pid\""
        print "}"
        done=1
      }
      {print}
      END{if(!done) exit 42}
    ' "$UPDATE_DAT_SCRIPT" > "$tmp" || return 1;
    bash -n "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$UPDATE_DAT_SCRIPT" 0755
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_pid_owns_socket_port
_e142_pid_owns_socket_port() {
    local proto="$1" port="$2" pid="$3" want state table inode fd target;
    [[ "$port" =~ ^[0-9]+$ ]] && ((port >= 1 && port <= 65535)) && [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1;
    want=$(printf '%04X' "$port");
    case "$proto" in 
        tcp)
            state=0A;
            set -- /proc/net/tcp /proc/net/tcp6
        ;;
        udp)
            state=07;
            set -- /proc/net/udp /proc/net/udp6
        ;;
        *)
            return 1
        ;;
    esac;
    for table in "$@";
    do
        test -r "$table" || continue;
        while IFS= read -r inode; do
            [[ "$inode" =~ ^[0-9]+$ ]] || continue;
            for fd in "/proc/$pid/fd/"*;
            do
                test -L "$fd" || continue;
                target=$(readlink -- "$fd" 2> /dev/null || true);
                test "$target" = "socket:[$inode]" && return 0;
            done;
        done < <(awk -v p="$want" -v s="$state" 'NR>1{split($2,a,":"); if(toupper(a[2])==p && toupper($4)==s) print $10}' "$table");
    done;
    return 1
}
