# EEX3-FUNCTION ssh_security_e141_158 _e142_restore_network_baseline
_e142_restore_network_baseline() {
    if _e202_unrecognized_current_active; then
        return 1;
    fi;
    if _e202_unrecognized_legacy_active; then
        return 1;
    fi;
    if _e202_small_bbr_active; then
        _e202_small_bbr_disable force || return 1;
    else
