# EEX3-FUNCTION ssh_security_e141_158 _e142_sshd_config_files
_e142_sshd_config_files() {
    local f real token pattern hit i=0;
    local -a queue=(/etc/ssh/sshd_config);
    local seen=" ";
    while test "$i" -lt "${#queue[@]}" && test "$i" -lt 128; do
        f=${queue[$i]};
        i=$((i+1));
        test -f "$f" || continue;
        real=$(readlink -f -- "$f" 2> /dev/null || true);
        test -n "$real" || continue;
        [[ "$seen" == *" $real "* ]] && continue;
        seen+="$real ";
        printf '%s\n' "$real";
        while IFS= read -r token; do
            token=${token#\"};
            token=${token%\"};
            token=${token#\'};
            token=${token%\'};
            case "$token" in 
                /*)
                    pattern=$token
                ;;
                *)
                    pattern="/etc/ssh/$token"
                ;;
            esac;
            while IFS= read -r hit; do
                test -f "$hit" && queue+=("$hit");
            done < <(compgen -G "$pattern" 2> /dev/null || true);
        done < <(awk 'tolower($1)=="include"{for(i=2;i<=NF;i++)print $i}' "$real" 2> /dev/null);
    done
}
