# EEX3-FUNCTION ssh_security_e141_158 _e142_systemd_backend_base
_e142_systemd_backend_base() {
    E121_F2B_PYTHON=$(_e121_find_systemd_python 2> /dev/null || true);
    if test -z "$E121_F2B_PYTHON"; then
        info "fail2ban 的 systemd Python 绑定缺失，正在自动补齐。";
        pkg_install python3-systemd > /dev/null 2>&1 || true;
        E121_F2B_PYTHON=$(_e121_find_systemd_python 2> /dev/null || true);
    fi;
    test -n "$E121_F2B_PYTHON" || return 1;
    command -v journalctl > /dev/null 2>&1 || return 1;
    test -S /run/systemd/journal/socket || test -S /run/systemd/journal/stdout || return 1;
    return 0
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_test_auth_case
_e142_test_auth_case() {
    local expected="$1" user="$2" dump="$3" got;
    got=$(_e142_classify_auth_dump "$dump" "$user" | sed -n 's/^mode=//p' | head -n1);
    test "$got" = "$expected"
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_tx_dir_ok
_e142_tx_dir_ok() {
    local d="$1" real root;
    test -d "$d" || return 1;
    real=$(readlink -f -- "$d" 2> /dev/null || true);
    root=$(readlink -f -- "$E142_TX_ROOT" 2> /dev/null || true);
    test -n "$real" && test -n "$root" || return 1;
    case "$real" in 
        "$root"/*)
            return 0
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_verify_key_only_guard
_e142_verify_key_only_guard() {
    _e142_verify_key_only_guard_base || return 1;
    systemctl is-active --quiet xray-ssh-port-guard-e121.timer 2> /dev/null || return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e142_verify_key_only_guard_base
_e142_verify_key_only_guard_base() {
    local detected recorded mode p current_port;
    systemctl is-enabled --quiet xray-ssh-port-guard-e121.service 2> /dev/null || return 1;
    systemctl is-enabled --quiet xray-ssh-port-guard-e121.timer 2> /dev/null || return 1;
    test -s "$E121_SSH_GUARD_STATE" || return 1;
    detected=$(_e121_detect_ssh_ports | paste -sd, -);
    recorded=$(sed -n 's/^ports=//p' "$E121_SSH_GUARD_STATE" | head -n1);
    mode=$(sed -n 's/^mode=//p' "$E121_SSH_GUARD_STATE" | head -n1);
    test -n "$detected" && test "$detected" = "$recorded" || return 1;
    current_port=$(_e135_current_ssh_port 2> /dev/null || true);
    test -z "$current_port" || tr ',' '\n' <<< "$recorded" | grep -Fxq "$current_port" || return 1;
    case "$mode" in 
        ufw)
            while IFS= read -r p; do
                LC_ALL=C ufw status 2> /dev/null | awk -v p="$p/tcp" '$1==p{for(i=2;i<=NF;i++)if($i=="ALLOW")ok=1} END{exit !ok}' || return 1;
            done < <(_e121_detect_ssh_ports)
        ;;
        firewalld)
            while IFS= read -r p; do
                firewall-cmd --query-port="$p/tcp" > /dev/null 2>&1 || return 1;
            done < <(_e121_detect_ssh_ports)
        ;;
        iptables-managed-chain)
            iptables -C INPUT -j "$E121_SSH_GUARD_CHAIN" > /dev/null 2>&1 || return 1;
            while IFS= read -r p; do
                iptables -C "$E121_SSH_GUARD_CHAIN" -p tcp --dport "$p" -j ACCEPT > /dev/null 2>&1 || return 1;
            done < <(_e121_detect_ssh_ports);
            if command -v ip6tables > /dev/null 2>&1 && ip -6 addr show scope global 2> /dev/null | grep -q 'inet6'; then
                ip6tables -C INPUT -j "$E121_SSH_GUARD_CHAIN" > /dev/null 2>&1 || return 1;
                while IFS= read -r p; do
                    ip6tables -C "$E121_SSH_GUARD_CHAIN" -p tcp --dport "$p" -j ACCEPT > /dev/null 2>&1 || return 1;
                done < <(_e121_detect_ssh_ports);
            fi
        ;;
        *)
            return 1
        ;;
    esac
}
