# EEX3-FUNCTION ssh_security_e141_158 _e152_architecture_audit
_e152_architecture_audit() {
    local total unique dup evals ors dispatch;
    total=$(grep -Ec '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" 2> /dev/null || echo 0);
    unique=$(grep -E '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" 2> /dev/null | sed -E 's/[[:space:]]*\(\).*//' | sort -u | wc -l);
    dup=$(grep -E '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" 2> /dev/null | sed -E 's/[[:space:]]*\(\).*//' | sort | uniq -d | wc -l);
    evals=$(grep -Fc 'eval "$(declare -f' "$SCRIPT_PATH" 2> /dev/null || echo 0);
    dispatch=$(grep -Fc 'case "${1:-}" in' "$SCRIPT_PATH" 2> /dev/null || echo 0);
    echo "E152架构审计：";
    echo "  函数定义总数=$total 唯一函数=$unique 重复函数名=$dup";
    echo "  declare-f覆盖层=$evals dispatcher文本数=$dispatch";
    echo "  结论：E152修复最终生效链，但历史层仍是技术债；未宣称已重写为无重复模块化代码。"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_build_effective_candidate
_e152_build_effective_candidate() {
    local profile="${1:-balanced}" out="$2" raw key value p;
    raw=$(_e118_mktemp e152-network-raw) || return 1;
    _e136_network_candidate "$profile" "$raw" || return 1;
    grep -q '^net.ipv4.conf.all.rp_filter' "$raw" || echo 'net.ipv4.conf.all.rp_filter = 2' >> "$raw";
    grep -q '^net.ipv4.conf.default.rp_filter' "$raw" || echo 'net.ipv4.conf.default.rp_filter = 2' >> "$raw";
    printf '# Managed exclusively by ex199e152; profile=%s; generated=%s\n' "$profile" "$(date -Is 2> /dev/null || date)" > "$out" || return 1;
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs);
        value=$(printf '%s' "$value" | xargs);
        case "$key" in 
            '' | '#'*)
                continue
            ;;
        esac;
        p=$(_e152_proc_path "$key");
        test -e "$p" || continue;
        printf '%s = %s\n' "$key" "$value" >> "$out" || return 1;
    done < "$raw";
    for key in net.ipv4.tcp_notsent_lowat net.ipv4.ip_local_port_range net.ipv4.conf.all.rp_filter net.ipv4.conf.default.rp_filter;
    do
        grep -q "^${key//./\\.}[[:space:]]*=" "$out" || { 
            error "当前内核缺少E152强制参数：$key";
            return 1
        };
    done;
    _e152_network_validate "$out"
}
