    rm -f -- "$E152_LEGACY_E143_NETWORK_CONF" "$E152_LEGACY_E143_NETWORK_SCRIPT" "$E152_LEGACY_E143_NETWORK_SERVICE" "$E152_LEGACY_E143_NETWORK_TIMER" "$E152_LEGACY_E143_SSH_SERVICE" "$E152_LEGACY_E143_SSH_TIMER" "$E152_LEGACY_E143_FILTER" 2> /dev/null || true;
