    fi;
    systemctl daemon-reload > /dev/null 2>&1 || return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_collect_ignoreip
_e152_collect_ignoreip() {
    local ip="${1:-}" f;
    { 
        echo "127.0.0.1/8";
        echo "::1";
        test -z "$ip" || echo "$ip";
        if command -v fail2ban-client > /dev/null 2>&1; then
            fail2ban-client get "$E121_F2B_JAIL_NAME" ignoreip 2> /dev/null | _e137_normalize_ignore_tokens || true;
        fi;
        if test -f "$E121_F2B_JAIL"; then
            awk -F= '/^[[:space:]]*ignoreip[[:space:]]*=/{sub(/^[^=]*=/,"");print}' "$E121_F2B_JAIL" 2> /dev/null | _e137_normalize_ignore_tokens || true;
        fi;
        for f in /etc/fail2ban/jail.conf /etc/fail2ban/jail.local /etc/fail2ban/jail.d/*.conf /etc/fail2ban/jail.d/*.local;
        do
            test -f "$f" || continue;
            awk '
              BEGIN{in_default=0}
              /^[[:space:]]*\[/ {
                line=$0; gsub(/[[:space:]]/,"",line)
                in_default=(tolower(line)=="[default]")
                next
              }
              in_default && /^[[:space:]]*ignoreip[[:space:]]*=/ {
                sub(/^[^=]*=/,""); print
              }
            ' "$f" 2> /dev/null | _e137_normalize_ignore_tokens || true;
        done
    } | awk 'NF&&!seen[$0]++' | paste -sd' ' -
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_collect_sysctl_files
_e152_collect_sysctl_files() {
    local regex f real;
    local -a seen=();
    regex=$(_e152_managed_key_regex);
    for f in /etc/sysctl.conf /etc/sysctl.d/*.conf;
    do
        test -f "$f" || test -L "$f" || continue;
        real=$(readlink -f -- "$f" 2> /dev/null || true);
        test -n "$real" || continue;
        case "$real" in 
            /etc/*)

            ;;
            *)
                continue
            ;;
        esac;
        grep -Eq "^[[:space:]]*($regex)[[:space:]]*=" "$real" 2> /dev/null || continue;
        [[ " ${seen[*]} " == *" $real "* ]] || { 
            seen+=("$real");
            printf '%s\n' "$real"
        };
    done;
    for f in "$E152_NETWORK_CONF" /etc/sysctl.d/99-xray-e145-network.conf /etc/sysctl.d/99-xray-e143-network.conf /etc/sysctl.d/99-xray-e142-network.conf /etc/sysctl.d/99-xray-e139-network.conf /etc/sysctl.d/99-xray-e138-network.conf /etc/sysctl.d/99-xray-e136-network.conf /etc/sysctl.d/99-xray-e135-network.conf;
    do
        real=$(readlink -f -- "$f" 2> /dev/null || printf '%s' "$f");
        [[ " ${seen[*]} " == *" $real "* ]] || { 
            seen+=("$real");
            printf '%s\n' "$real"
        };
    done
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_disable_legacy_iptables_ssh_guard
_e152_disable_legacy_iptables_ssh_guard() {
    local unit state;
    for unit in xray-ssh-port-guard-e121.timer xray-ssh-port-guard-e121.service;
    do
        systemctl disable --now "$unit" > /dev/null 2>&1 || true;
        systemctl is-active --quiet "$unit" 2> /dev/null && { 
            error "旧E121 iptables型SSH守护仍在运行：$unit";
            return 1
        };
        state=$(systemctl is-enabled "$unit" 2> /dev/null || true);
        case "$state" in 
            enabled | enabled-runtime | linked | linked-runtime)
                error "旧E121 iptables型SSH守护仍为启用状态：$unit ($state)";
                return 1
            ;;
        esac;
    done;
    return 0
}
