# EEX3-FUNCTION ssh_security_e141_158 _e152_f2b_candidates_base
_e152_f2b_candidates_base() {
    local ports csv jail_tmp db_tmp;
    ports=$(_e116_detect_ssh_ports);
    test -n "$ports" || ports=22;
    csv=$(printf '%s\n' $ports | paste -sd, -);
    mkdir -p /etc/fail2ban/jail.d /etc/fail2ban/fail2ban.d /var/lib/fail2ban || return 1;
    jail_tmp=$(_e118_mktemp fail2ban-e121-jail) || return 1;
    db_tmp=$(_e118_mktemp fail2ban-e121-db) || return 1;
    cat > "$db_tmp" <<'EOF_E121_F2B_DB'
[Definition]
allowipv6 = auto
dbfile = /var/lib/fail2ban/fail2ban.sqlite3
dbpurgeage = 3d
logtarget = /var/log/xray-fail2ban.log
loglevel = INFO
EOF_E121_F2B_DB

    { 
        echo "[$E121_F2B_JAIL_NAME]";
        echo "enabled = true";
        echo "filter = sshd";
        echo "backend = $E121_F2B_BACKEND";
        if test "$E121_F2B_BACKEND" != "systemd"; then
            echo "logpath = $E121_F2B_LOGPATH";
        fi;
        echo "port = $csv";
        if test "$E121_F2B_EAGER_ACTION" -eq 1; then
            echo "banaction = $E121_F2B_BANACTION";
            echo "chain = INPUT";
            echo "action = %(action_)s[name=$E121_F2B_JAIL_NAME,actionstart_on_demand=false]";
        else
            if test -n "$E121_F2B_BANACTION"; then
                echo "banaction = $E121_F2B_BANACTION";
            fi;
        fi;
        echo "maxretry = $E118_MAXRETRY";
        echo "findtime = $E118_FINDTIME";
        echo "bantime = $E118_BANTIME"
    } > "$jail_tmp";
    _e121_atomic_install "$db_tmp" "$E121_F2B_DB_CONF" 0644 || return 1;
    _e121_atomic_install "$jail_tmp" "$E121_F2B_JAIL" 0644 || return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_fail2ban_numeric_verify
_e152_fail2ban_numeric_verify() {
    local maxretry findtime bantime;
    fail2ban-client ping > /dev/null 2>&1 || return 1;
    fail2ban-client status "$E121_F2B_JAIL_NAME" > /dev/null 2>&1 || return 1;
    maxretry=$(_e121_fail2ban_get_number "$E121_F2B_JAIL_NAME" maxretry || true);
    findtime=$(_e121_fail2ban_get_number "$E121_F2B_JAIL_NAME" findtime || true);
    bantime=$(_e121_fail2ban_get_number "$E121_F2B_JAIL_NAME" bantime || true);
    test "$maxretry" = 2 && test "$findtime" = 86400 && test "$bantime" = 129600
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_fail2ban_passive_verify
_e152_fail2ban_passive_verify() {
    local backend;
    systemctl is-enabled --quiet fail2ban.service 2> /dev/null || return 1;
    systemctl is-active --quiet fail2ban.service 2> /dev/null || return 1;
    _e152_fail2ban_numeric_verify || return 1;
    backend=$(_e152_firewall_backend 2> /dev/null || echo none);
    case "$backend" in 
        nft)
            _e165_f2b_action_present && _e165_helper_check
        ;;
        iptables)
            fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2> /dev/null | grep -qi iptables
        ;;
        ufw | firewalld)
            test -n "$(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2> /dev/null || true)"
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_firewall_backend
_e152_firewall_backend() {
    local detected preferred="${E182_BACKEND_OVERRIDE:-}";
    detected=$(_e182_firewall_detector_base 2> /dev/null || echo none);
    case "$detected" in 
        ufw | firewalld)
            echo "$detected";
            return 0
        ;;
    esac;
    if test -z "$preferred" && test -s "$E182_BACKEND_STATE"; then
        preferred=$(_e182_backend_state_get preferred_backend none);
    fi;
    case "$preferred" in 
        nft)
            command -v nft > /dev/null 2>&1 && nft list ruleset > /dev/null 2>&1 && { 
                echo nft;
                return 0
            }
        ;;
        iptables)
            command -v iptables > /dev/null 2>&1 && iptables -w 2 -S INPUT > /dev/null 2>&1 && { 
                echo iptables;
                return 0
            }
        ;;
        sshd-native)
            echo sshd-native;
            return 0
        ;;
    esac;
    echo "$detected"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_firewall_backend_status
_e152_firewall_backend_status() {
    local backend native_mode;
    if test "$EUID" -ne 0; then
        echo 'firewall_backend=unknown-unprivileged';
        echo 'privilege=root-required-to-read-active-ruleset';
        return 0;
    fi;
    backend=$(_e152_firewall_backend 2> /dev/null || echo none);
    echo "firewall_backend=$backend";
    echo "e182_state=$E182_BACKEND_STATE";
    echo "e182_native_state=$E182_NATIVE_STATE";
    echo "e182_diagnostic=$E182_BACKEND_DIAG";
    echo "ip_ban_capable=$(_e182_backend_state_get ip_ban_capable unknown)";
    echo "managed_fail2ban_jail_runtime=$(_e182_managed_f2b_runtime_state)";
    case "$backend" in 
        nft)
            echo 'ssh_guard_model=fail2ban-owned-native-nft-base-chain'
        ;;
        iptables)
            echo 'ssh_guard_model=managed-xtables-chain'
        ;;
        ufw | firewalld)
            echo 'ssh_guard_model=active-firewall-manager'
        ;;
        sshd-native)
            native_mode=$(sed -n 's/^mode=//p' "$E182_NATIVE_STATE" 2> /dev/null | tail -n1);
            echo "ssh_guard_model=openssh-${native_mode:-not-applied}-no-firewall-ban"
        ;;
        *)
            echo 'ssh_guard_model=unclassified'
        ;;
    esac
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_help
_e152_help() {
    cat <<'EOF_E152_HELP'
V199e152:
  --hot-update              transactional hot update
  --self-test               release and behavior tests
  --optimization-menu       advanced optimization menu
  --micro-menu              complete 1-25 + 26/27/28 micro-control menu
  --micro-28                execute option 28 after explicit CLI confirmation
  --optimization-menu-audit verify 10 -> 6 -> 28 menu mapping
  --network-apply           E152 balanced network profile
  --network-audit           managed sysctl audit
  --summary                 root-only node export
EOF_E152_HELP

}
# EEX3-FUNCTION ssh_security_e141_158 _e152_hot_update
_e152_hot_update() {
    local lock=/run/lock/xray-e152-hot-update.lock;
    local protect sysbackup rc=0 rollback_rc=0 was_active=0;
    local enabled=0 mode=disabled profile=disabled phase=start;
    _e214_ensure_run_lock || return 1;
    exec 150> "$lock";
    flock -n 150 || { 
        error "已有另一个E152热更新正在运行。";
        return 1
    };
    : > "$E152_FINAL_HOTUPDATE_LOG" 2> /dev/null || true;
    E135_NEW_PACKAGES=();
    _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" start begin "$SCRIPT_PATH";
    _e152_prepare || return 1;
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    phase=xray-snapshot;
    _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" begin;
    protect=$(_e116_backup_state before_hot_update_e152) || rc=1;
    test "$rc" -ne 0 || _e118_save_core_payload "$protect" || rc=1;
    if test "$rc" -eq 0; then
        was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
        was_active=${was_active:-0};
        _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" ok "$protect";
    fi;
    if test "$rc" -eq 0; then
        phase=system-snapshot;
        sysbackup=$(_e152_new_tx hot-update) || rc=1;
        test "$rc" -ne 0 || _e140_system_snapshot "$sysbackup" || rc=1;
        test "$rc" -ne 0 || _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" ok "$sysbackup";
    fi;
    test "$rc" -ne 0 || _e152_hot_update_step runtime-tools _e135_require_runtime_tools || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step disable-legacy _e135_disable_legacy_optimizers || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step self-install _e152_install_self || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step dat-install install_update_dat || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step dat-timer systemctl enable --now xray-dat-update.timer || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step core-auto-update-off _e105_disable_xray_core_auto_update || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step init-window _e137_apply_init_window_default30 || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step network _e152_network_apply balanced force || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step log-retention _e121_install_log_retention || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step ssh-guard _e141_install_ssh_guard || rc=1;
    test "$rc" -ne 0 || _e152_hot_update_step xray-limits fix_xray_systemd_limits || rc=1;
    if test "$rc" -eq 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e152_hot_update_step warp-full-units _e140_full_install_units || rc=1;
            test "$rc" -ne 0 || _e152_hot_update_step warp-full-reconcile _e140_warp_full_reconcile || rc=1;
        else
            _e152_hot_update_step warp-proxy _e137_warp_connect_local_proxy || rc=1;
            test "$rc" -ne 0 || _e152_hot_update_step warp-xray _e138_xray_apply_warp "$mode" "$profile" true || rc=1;
            test "$rc" -ne 0 || _e152_hot_update_step warp-health _e138_warp_health_install || rc=1;
        fi;
    fi;
    test "$rc" -ne 0 || _e152_hot_update_step version-write _e152_write_version || rc=1;
    if test "$rc" -eq 0; then
        phase=verify;
        _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" begin;
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1 || rc=1;
        test "$rc" -ne 0 || test ! -s "$CONFIG" || _e118_xray_test_config "$CONFIG" 1 || rc=1;
        if test "$rc" -eq 0 && test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
            test "$rc" -ne 0 || _e131_verify_nice_runtime || rc=1;
        else
            if test "$rc" -eq 0 && systemctl is-active --quiet xray.service 2> /dev/null; then
                error "热更新意外启动了原本停止的Xray服务。";
                rc=1;
            fi;
        fi;
        test "$rc" -ne 0 || test "$(sysctl -n net.ipv4.tcp_notsent_lowat 2> /dev/null)" = 131072 || rc=1;
        test "$rc" -ne 0 || _e152_ipv6_closed || rc=1;
        test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
        test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
        for unit in xray-dat-update.timer xray-log-retention-e121.timer xray-ssh-auth-audit-e152.timer xray-network-e152.timer;
        do
            test "$rc" -ne 0 || systemctl is-enabled --quiet "$unit" 2> /dev/null || rc=1;
            test "$rc" -ne 0 || systemctl is-active --quiet "$unit" 2> /dev/null || rc=1;
        done;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$SYMLINK" || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E152_SELF_PATH" || rc=1;
        test "$rc" -eq 0 && _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" ok || _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" fail;
    fi;
    if test "$rc" -ne 0; then
        error "E152热更新失败，开始总回滚；阶段日志：$E152_FINAL_HOTUPDATE_LOG";
        test -z "${sysbackup:-}" || _e140_system_restore "$sysbackup" || rollback_rc=1;
        test -z "${protect:-}" || _e118_restore_core_payload "$protect" > /dev/null 2>&1 || rollback_rc=1;
        test -z "${protect:-}" || _e118_restore_state "$protect" > /dev/null 2>&1 || rollback_rc=1;
        _e135_remove_new_runtime_tools || true;
        if test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 > /dev/null 2>&1 || rollback_rc=1;
        fi;
        if test "$rollback_rc" -ne 0; then
            { 
                echo "time=$(date -Is 2> /dev/null || date)";
                echo "operation=hot-update";
                echo "system_backup=${sysbackup:-none}";
                echo "core_backup=${protect:-none}";
                echo "log=$E152_FINAL_HOTUPDATE_LOG"
            } > "$E152_CRITICAL_MARKER" 2> /dev/null || true;
            error "严重：E152回滚未通过复检。";
        fi;
        _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" finish fail "rollback=$rollback_rc";
        return 1;
    fi;
    rm -f "$E152_CRITICAL_MARKER" 2> /dev/null || true;
    _e142_prune_transactions "$sysbackup" "$protect" || warn "旧事务快照收敛未完成。";
    _e152_cleanup_legacy_e143_units || warn "旧E143单元清理未完全完成，但不会回滚已验证的E152。";
    _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" finish ok;
    info "V199e152热更新完成。系统快照：$sysbackup";
    info "阶段日志：$E152_FINAL_HOTUPDATE_LOG"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_hot_update_core
_e152_hot_update_core() {
    local protect sysbackup rc=0 rollback_rc=0 was_active=0 enabled=0 mode=disabled profile=disabled;
    E135_NEW_PACKAGES=();
