            { 
                echo "time=$(date -Is 2> /dev/null || date)";
                echo "operation=hot-update";
                echo "system_backup=$sysbackup";
                echo "core_backup=$protect"
            } > "$E152_CRITICAL_MARKER" 2> /dev/null || true;
            error "严重：E152回滚未通过复检。系统快照：$sysbackup；Core快照：$protect";
        fi;
        return 1;
    fi;
    rm -f "$E152_CRITICAL_MARKER" 2> /dev/null || true;
    _e142_prune_transactions "$sysbackup" "$protect" || warn "旧事务快照收敛未完成。";
    info "V199e152热更新完成。系统快照：$sysbackup";
    info "已验证：Xray生存/运行态、init30、notsent=131072、IPv6关闭或不可用、网络5分钟自愈、3天日志、SSH认证策略；WARP mode=$mode。"
