# EEX3-FUNCTION ssh_security_e141_158 _e152_hot_update_inherited
_e152_hot_update_inherited() {
    _e152_hot_update_core "$@" || return $?;
    _e152_cleanup_legacy_e143_units || warn "E152已生效，但旧E143单元清理未完全完成；不会回滚已验证的新版本。"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_hot_update_preflight
_e152_hot_update_preflight() {
    local c;
    test "$EUID" -eq 0 || { 
        error "热更新必须使用root。";
        return 1
    };
    test -d /run/systemd/system || { 
        error "systemd未运行。";
        return 1
    };
    for c in bash systemctl jq curl ip ss tar install sha256sum cp awk sed grep dirname mkdir mv cmp find sort readlink base64 paste tr chmod chown stat sysctl mktemp flock xargs;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "热更新预检缺少命令：$c";
            return 1
        };
    done;
    test -r "$SCRIPT_PATH" || { 
        error "当前脚本不可读：$SCRIPT_PATH";
        return 1
    };
    install -d -m 0700 "$E152_TX_ROOT" "$E152_FINAL_NETWORK_TX_ROOT" "$E152_DIAG_DIR" || return 1;
    if test -e /etc/sysctl.d; then
        test -d /etc/sysctl.d && test -w /etc/sysctl.d || { 
            error "/etc/sysctl.d存在但不是可写目录。";
            return 1
        };
    else
        test -w /etc || return 1;
    fi
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_hot_update_step
_e152_hot_update_step() {
    local phase="$1";
    shift;
    _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" begin;
    if "$@"; then
        _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" ok;
        return 0;
    fi;
    _e152_phase_log "$E152_FINAL_HOTUPDATE_LOG" "$phase" fail;
    error "E152热更新失败阶段：$phase";
    return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_install_mode_base
_e152_install_mode_base() {
    local guard was_active=0 rc=0 rollback_rc=0;
    guard=$(_e116_backup_state before_e142_node_install) || return 1;
    _e118_save_core_payload "$guard" || return 1;
    was_active=$(sed -n 's/^xray_was_active=//p' "$guard/meta.env" 2> /dev/null | tail -n1);
    was_active=${was_active:-0};
    _e140_install_mode_base "$@" || rc=1;
    test "$rc" -ne 0 || _e142_write_version || rc=1;
    if test "$rc" -eq 0; then
        return 0;
    fi;
    error "节点安装事务失败，执行e142外层Core/配置生存回滚。";
    _e118_restore_core_payload "$guard" > /dev/null 2>&1 || rollback_rc=1;
    _e118_restore_state "$guard" > /dev/null 2>&1 || rollback_rc=1;
    if test "$was_active" = 1; then
        _e127_verify_xray_runtime "$CONFIG" 12 > /dev/null 2>&1 || rollback_rc=1;
    else
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            rollback_rc=1;
        fi;
    fi;
    if test "$rollback_rc" -ne 0; then
        install -d -m 0700 "$E142_DIR" 2> /dev/null || true;
        { 
            echo "time=$(date -Is 2> /dev/null || date)";
            echo "operation=node-install";
            echo "core_backup=$guard"
        } > "${E142_CRITICAL_MARKER}.new.$$" 2> /dev/null && chmod 0600 "${E142_CRITICAL_MARKER}.new.$$" 2> /dev/null && mv -f -- "${E142_CRITICAL_MARKER}.new.$$" "$E142_CRITICAL_MARKER" 2> /dev/null || true;
        error "严重：旧Xray运行态未能恢复；快照：$guard";
    fi;
    return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_install_network_guard
_e152_install_network_guard() {
    local script_tmp service_tmp timer_tmp;
    script_tmp=$(_e118_mktemp network-e152.sh) || return 1;
    service_tmp=$(_e118_mktemp network-e152.service) || return 1;
    timer_tmp=$(_e118_mktemp network-e152.timer) || return 1;
    cat > "$script_tmp" <<'EOF_E152_NETWORK_SCRIPT'
#!/usr/bin/env bash
set -euo pipefail
CONF=/etc/sysctl.d/99-xray-e152-network.conf
test -s "$CONF"
while IFS='=' read -r key value; do
  key=$(printf '%s' "$key" | xargs)
  value=$(printf '%s' "$value" | xargs)
  case "$key" in ''|'#'*) continue ;; esac
  path="/proc/sys/${key//./\/}"
  test -w "$path"
  sysctl -w "$key=$value" >/dev/null
  test "$(sysctl -n "$key" | xargs)" = "$value"
done <"$CONF"
if test -d /proc/sys/net/ipv6/conf; then
  for f in /proc/sys/net/ipv6/conf/*/disable_ipv6; do
    test ! -e "$f" || printf '1\n' >"$f"
  done
  for f in /proc/sys/net/ipv6/conf/*/disable_ipv6; do
    test ! -e "$f" || test "$(cat "$f")" = 1
  done
fi
EOF_E152_NETWORK_SCRIPT

    cat > "$service_tmp" <<EOF_E152_NETWORK_SERVICE
[Unit]
Description=V199e152 canonical network profile apply and verification
After=systemd-sysctl.service network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$E152_NETWORK_SCRIPT
TimeoutStartSec=45
EOF_E152_NETWORK_SERVICE

    cat > "$timer_tmp" <<'EOF_E152_NETWORK_TIMER'
[Unit]
Description=V199e152 network profile drift repair

[Timer]
OnBootSec=60s
OnUnitInactiveSec=5min
AccuracySec=30s
Persistent=true
Unit=xray-network-e152.service

[Install]
WantedBy=timers.target
EOF_E152_NETWORK_TIMER

    bash -n "$script_tmp" || return 1;
    _e121_atomic_install "$script_tmp" "$E152_NETWORK_SCRIPT" 0755 || return 1;
    _e121_atomic_install "$service_tmp" "$E152_NETWORK_SERVICE" 0644 || return 1;
    _e121_atomic_install "$timer_tmp" "$E152_NETWORK_TIMER" 0644 || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl enable --now xray-network-e152.timer > /dev/null 2>&1 || return 1;
    systemctl start xray-network-e152.service > /dev/null 2>&1 || return 1;
    systemctl is-enabled --quiet xray-network-e152.timer || return 1;
    systemctl is-active --quiet xray-network-e152.timer || return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_install_nft_ssh_audit
_e152_install_nft_ssh_audit() {
    local script_tmp service_tmp timer_tmp diag_tmp;
    script_tmp=$(_e118_mktemp ssh-native-e152.sh) || return 1;
    service_tmp=$(_e118_mktemp ssh-native-e152.service) || return 1;
    timer_tmp=$(_e118_mktemp ssh-native-e152.timer) || return 1;
    cat > "$script_tmp" <<EOF_E152_NATIVE_SCRIPT
#!/usr/bin/env bash
set -euo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
exec "$SYMLINK" --ssh-native-nft-check
EOF_E152_NATIVE_SCRIPT

    cat > "$service_tmp" <<EOF_E152_NATIVE_SERVICE
[Unit]
Description=V199e152 native nftables SSH and Fail2ban truth audit
After=network-online.target ssh.service sshd.service fail2ban.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$E152_NATIVE_SSH_SCRIPT
TimeoutStartSec=45
EOF_E152_NATIVE_SERVICE

    cat > "$timer_tmp" <<'EOF_E152_NATIVE_TIMER'
[Unit]
Description=Periodic native nftables SSH and Fail2ban truth audit

[Timer]
OnBootSec=60s
OnUnitInactiveSec=5min
AccuracySec=30s
Persistent=true
Unit=xray-ssh-native-e152.service

[Install]
WantedBy=timers.target
EOF_E152_NATIVE_TIMER

    bash -n "$script_tmp" || return 1;
    _e121_atomic_install "$script_tmp" "$E152_NATIVE_SSH_SCRIPT" 0755 || return 1;
    _e121_atomic_install "$service_tmp" "$E152_NATIVE_SSH_SERVICE" 0644 || return 1;
    _e121_atomic_install "$timer_tmp" "$E152_NATIVE_SSH_TIMER" 0644 || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    install -d -m 0750 "$(dirname -- "$E266_SSH_AUDIT_LOG")" || return 1;
    diag_tmp="${E266_SSH_AUDIT_LOG}.tmp.$$";
    : > "$diag_tmp" || return 1;
    chmod 0600 "$diag_tmp" || return 1;
    if ! systemctl enable xray-ssh-native-e152.timer >> "$diag_tmp" 2>&1; then
        printf 'stage=timer-enable\n' >> "$diag_tmp";
        mv -f -- "$diag_tmp" "$E266_SSH_AUDIT_LOG" || true;
        error "SSH审计定时器启用失败；诊断：$E266_SSH_AUDIT_LOG";
        return 1;
    fi;
    rm -f -- "$E152_NATIVE_SSH_STATE" >> "$diag_tmp" 2>&1 || { 
        printf 'stage=boot-audit-state-reset\n' >> "$diag_tmp";
        mv -f -- "$diag_tmp" "$E266_SSH_AUDIT_LOG" || true;
        error "SSH启动审计旧状态清除失败；完整诊断：$E266_SSH_AUDIT_LOG";
        return 1
    };
    systemctl reset-failed xray-ssh-native-e152.service > /dev/null 2>&1 || true;
    if ! systemctl start xray-ssh-native-e152.service >> "$diag_tmp" 2>&1; then
        printf 'stage=boot-audit-start\n' >> "$diag_tmp";
        systemctl status xray-ssh-native-e152.service --no-pager -l >> "$diag_tmp" 2>&1 || true;
        journalctl -u xray-ssh-native-e152.service --no-pager -n 80 >> "$diag_tmp" 2>&1 || true;
        mv -f -- "$diag_tmp" "$E266_SSH_AUDIT_LOG" || true;
        error "SSH启动审计失败；完整诊断：$E266_SSH_AUDIT_LOG";
        return 1;
    fi;
    if test ! -s "$E152_NATIVE_SSH_STATE"; then
        printf 'stage=boot-audit-readback\n' >> "$diag_tmp";
        systemctl status xray-ssh-native-e152.service --no-pager -l >> "$diag_tmp" 2>&1 || true;
        test ! -r "$E152_NATIVE_SSH_STATE" || sed 's/^/state: /' "$E152_NATIVE_SSH_STATE" >> "$diag_tmp";
        mv -f -- "$diag_tmp" "$E266_SSH_AUDIT_LOG" || true;
        error "SSH启动审计读回失败；完整诊断：$E266_SSH_AUDIT_LOG";
        return 1;
    fi;
    if ! systemctl start xray-ssh-native-e152.timer >> "$diag_tmp" 2>&1 || ! systemctl is-active --quiet xray-ssh-native-e152.timer 2> /dev/null; then
        printf 'stage=timer-start-readback\n' >> "$diag_tmp";
        systemctl status xray-ssh-native-e152.timer --no-pager -l >> "$diag_tmp" 2>&1 || true;
        mv -f -- "$diag_tmp" "$E266_SSH_AUDIT_LOG" || true;
        error "SSH审计定时器启动/读回失败；完整诊断：$E266_SSH_AUDIT_LOG";
        return 1;
    fi;
    { 
        printf 'stage=complete\n';
        sed 's/^/state: /' "$E152_NATIVE_SSH_STATE"
    } >> "$diag_tmp" || return 1;
    mv -f -- "$diag_tmp" "$E266_SSH_AUDIT_LOG"
}
