# EEX3-FUNCTION ssh_security_e141_158 _e152_ipv6_closed
_e152_ipv6_closed() {
    local root="${E152_PROC_ROOT:-/proc/sys}" f;
    test ! -d "$root/net/ipv6" && return 0;
    for f in "$root"/net/ipv6/conf/*/disable_ipv6;
    do
