# EEX3-FUNCTION ssh_security_e141_158 _e152_micro_control_available
_e152_micro_control_available() {
    local body n;
    body=$(declare -f _e182_micro_control_menu 2> /dev/null || true);
    for n in {1..28};
    do
        grep -Eq "echo \\\"[[:space:]]+${n}\\)" <<< "$body" || return 1;
