# EEX3-FUNCTION ssh_security_e141_158 _e152_network_apply_runtime
_e152_network_apply_runtime() {
    local file="$1" key value p f;
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs);
        value=$(printf '%s' "$value" | xargs);
        case "$key" in 
            '' | '#'*)
                continue
            ;;
        esac;
        p=$(_e152_proc_path "$key");
        test -w "$p" || return 1;
        sysctl -w "$key=$value" > /dev/null 2>&1 || return 1;
    done < "$file";
    if test -d "${E152_PROC_ROOT:-/proc/sys}/net/ipv6/conf"; then
        for f in "${E152_PROC_ROOT:-/proc/sys}"/net/ipv6/conf/*/disable_ipv6;
        do
            test -e "$f" || continue;
            printf '1\n' > "$f" || return 1;
        done;
    fi;
    while IFS='=' read -r key value; do
        key=$(printf '%s' "$key" | xargs);
        value=$(printf '%s' "$value" | xargs);
        case "$key" in 
            '' | '#'*)
                continue
            ;;
        esac;
        test "$(sysctl -n "$key" 2> /dev/null | xargs)" = "$value" || return 1;
    done < "$file";
    _e152_ipv6_closed
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_network_audit
_e152_network_audit() {
    local key c hits=0 profile owner;
    profile=$(sed -n 's/^profile=//p' "$E152_NETWORK_STATE" 2> /dev/null | head -n1);
    profile=${profile:-balanced};
    owner=$(sed -n 's/^owner=//p' "$E152_NETWORK_STATE" 2> /dev/null | head -n1);
    owner=${owner:-$E152_NETWORK_CONF};
    title "V199e152：网络参数与重复定义审计";
    echo "  当前档位：$profile";
    echo "  唯一持久化目标：$owner";
    echo "  Xray入站端口：由config.json决定；与ip_local_port_range无关";
    while IFS= read -r key; do
        printf '\n[%s] runtime=%s\n' "$key" "$(sysctl -n "$key" 2> /dev/null || echo unsupported)";
        grep -RnsE "^[[:space:]]*${key//./\\.}[[:space:]]*=" /etc/sysctl.conf /etc/sysctl.d 2> /dev/null | sed 's/^/  /' || echo "  未定义";
        c=$(grep -RhsE "^[[:space:]]*${key//./\\.}[[:space:]]*=" /etc/sysctl.conf /etc/sysctl.d 2> /dev/null | wc -l);
        (( c > 1 )) && hits=$((hits+1));
    done < <(_e136_network_keys);
    echo;
    echo "重复定义参数数：$hits"
}
