# EEX3-FUNCTION ssh_security_e141_158 _e152_network_restore
_e152_network_restore() {
    local tx="$1" p key old te ta se sa rc=0;
    _e152_network_tx_verify "$tx" || return 1;
    systemctl disable --now xray-network-e152.timer xray-network-e152.service > /dev/null 2>&1 || true;
    while IFS= read -r p; do
        test -n "$p" || continue;
        _e152_restore_path "$p" "$tx" || rc=1;
    done < "$tx/paths.list";
    while IFS='|' read -r key old; do
        test -n "$key" || continue;
        test -z "$old" || sysctl -w "$key=$old" > /dev/null 2>&1 || rc=1;
    done < "$tx/runtime.env";
    systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    te=$(sed -n 's/^timer_enabled=//p' "$tx/services.env");
    ta=$(sed -n 's/^timer_active=//p' "$tx/services.env");
    se=$(sed -n 's/^service_enabled=//p' "$tx/services.env");
    sa=$(sed -n 's/^service_active=//p' "$tx/services.env");
    _e152_restore_service_state xray-network-e152.timer "$te" "$ta";
    _e152_restore_service_state xray-network-e152.service "$se" "$sa";
    return "$rc"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_network_rollback
_e152_network_rollback() {
    local backup="$1" dir_preexisting="${2:-1}" key old rc=0;
    _e152_verify_network_tx_seal "$backup" || { 
        error "E152网络事务封存校验失败，拒绝使用损坏快照回滚：$backup";
        return 1
    };
    _e138_network_restore_files "$backup" || rc=1;
    if test -s "$backup/runtime.env"; then
        while IFS='|' read -r key old; do
            test -n "$key" || continue;
            test -z "$old" || sysctl -w "$key=$old" > /dev/null 2>&1 || rc=1;
        done < "$backup/runtime.env";
    fi;
    if test "$dir_preexisting" = 0; then
        rmdir /etc/sysctl.d 2> /dev/null || true;
    fi;
    return "$rc"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_network_snapshot
_e152_network_snapshot() {
    local tx="$1" p key old;
    : > "$tx/paths.list" || return 1;
    { 
        _e152_collect_sysctl_files;
        _e152_network_owned_paths
    } | awk 'NF&&!seen[$0]++' > "$tx/paths.list" || return 1;
    while IFS= read -r p; do
        test -n "$p" || continue;
        _e152_snapshot_path "$p" "$tx" || return 1;
    done < "$tx/paths.list";
    : > "$tx/runtime.env" || return 1;
    while IFS= read -r key; do
        old=$(sysctl -n "$key" 2> /dev/null || true);
        printf '%s|%s\n' "$key" "$old" >> "$tx/runtime.env" || return 1;
    done < <(_e136_network_keys);
    { 
        echo "timer_enabled=$(systemctl is-enabled xray-network-e152.timer 2> /dev/null || true)";
        echo "timer_active=$(systemctl is-active xray-network-e152.timer 2> /dev/null || true)";
        echo "service_enabled=$(systemctl is-enabled xray-network-e152.service 2> /dev/null || true)";
        echo "service_active=$(systemctl is-active xray-network-e152.service 2> /dev/null || true)"
    } > "$tx/services.env" || return 1;
    ( cd "$tx" && find . -maxdepth 1 -type f ! -name seal.sha256 -print0 | sort -z | xargs -0 -r sha256sum > seal.sha256 ) || return 1;
    test -s "$tx/seal.sha256"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_network_snapshot_verify
_e152_network_snapshot_verify() {
    local tx="$1" real root;
    real=$(readlink -f "$tx" 2> /dev/null || true);
    root=$(readlink -f "$E152_FINAL_NETWORK_TX_ROOT" 2> /dev/null || true);
    test -n "$real" && test -n "$root" || return 1;
    case "$real" in 
        "$root"/*)

        ;;
        *)
            return 1
        ;;
    esac;
    test -s "$tx/seal.sha256" || return 1;
    ( cd "$tx" && sha256sum -c seal.sha256 > /dev/null 2>&1 )
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_network_tx_dir_ok
_e152_network_tx_dir_ok() {
    local d="$1" real root;
    test -d "$d" || return 1;
    real=$(readlink -f -- "$d" 2> /dev/null || true);
    test -n "$real" || return 1;
    for root in "$E152_TX_ROOT" "$E139_TX_ROOT" "$E138_TX_ROOT";
    do
        root=$(readlink -f -- "$root" 2> /dev/null || true);
        test -n "$root" || continue;
        case "$real" in 
            "$root"/*)
                return 0
            ;;
        esac;
    done;
    return 1
}
