# EEX3-FUNCTION ssh_security_e141_158 _e152_network_tx_verify
_e152_network_tx_verify() {
    local tx="$1" real root;
    real=$(readlink -f -- "$tx" 2> /dev/null || true);
    root=$(readlink -f -- "$E152_FINAL_NETWORK_TX_ROOT" 2> /dev/null || true);
    test -n "$real" && test -n "$root" || return 1;
    case "$real" in 
        "$root"/*)

        ;;
        *)
            return 1
        ;;
    esac;
    test -s "$tx/seal.sha256" || return 1;
    ( cd "$tx" && sha256sum -c seal.sha256 > /dev/null 2>&1 )
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_network_validate
_e152_network_validate() {
    local file="$1" line key value seen="" available a b c;
    test -s "$file" || return 1;
    while IFS= read -r line; do
        line=${line%%#*};
        line=$(printf '%s' "$line" | xargs);
        test -n "$line" || continue;
        key=$(printf '%s' "$line" | cut -d= -f1 | xargs);
        value=$(printf '%s' "$line" | cut -d= -f2- | xargs);
        _e136_network_keys | grep -Fxq "$key" || { 
            error "非E152受管参数：$key";
            return 1
        };
        [[ " $seen " != *" $key "* ]] || { 
            error "候选参数重复：$key";
            return 1
        };
        seen="$seen $key";
        case "$key" in 
            net.ipv4.tcp_notsent_lowat)
                case "$value" in 
                    65536 | 131072 | 262144)

                    ;;
                    *)
                        return 1
                    ;;
                esac
            ;;
            net.ipv4.tcp_limit_output_bytes)
                case "$value" in 
                    524288 | 1048576 | 2097152)

                    ;;
                    *)
                        return 1
                    ;;
                esac
            ;;
            net.ipv4.ip_local_port_range)
                test "$value" = "32768 65535" || return 1
            ;;
            net.ipv4.tcp_congestion_control)
                available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2> /dev/null || true);
                [[ " $available " == *" $value "* ]] || return 1
            ;;
            net.ipv4.tcp_rmem | net.ipv4.tcp_wmem)
                read -r a b c <<< "$value";
                [[ "$a" =~ ^[0-9]+$ && "$b" =~ ^[0-9]+$ && "$c" =~ ^[0-9]+$ ]] || return 1;
                (( a <= b && b <= c )) || return 1
            ;;
            *)
                [[ "$value" =~ ^[A-Za-z0-9._-]+([[:space:]][0-9]+)?$ ]] || return 1
            ;;
        esac;
    done < "$file"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_new_tx
_e152_new_tx() {
    local name="${1:-tx}" safe d;
    _e152_prepare || return 1;
    safe=$(printf '%s' "$name" | tr -c 'A-Za-z0-9_.-' '_');
    test -n "$safe" || safe=tx;
    d="$E152_TX_ROOT/${safe}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM";
    install -d -m 0700 "$d" || return 1;
    printf '%s\n' "$d"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_nft_ssh_check
_e152_nft_ssh_check() {
    local profile mode ports listening current_port stale tmp actions;
    local state_dir="$E152_DIR" state_file="$E152_NATIVE_SSH_STATE";
    command -v nft > /dev/null 2>&1 && nft list ruleset > /dev/null 2>&1 || return 1;
    command -v sshd > /dev/null 2>&1 && sshd -t > /dev/null 2>&1 || return 1;
    profile=$(_e141_sshd_auth_profile) || return 1;
    mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1);
    ports=$(_e116_detect_ssh_ports 2> /dev/null | sort -nu || true);
    test -n "$ports" || ports=22;
    listening=$(_e266_detect_live_ssh_ports 2> /dev/null || true);
    current_port=$(_e135_current_ssh_port 2> /dev/null || true);
    stale=$(_e266_ssh_listener_assess "$ports" "$listening" "$current_port") || { 
        error 'SSH定时审计未找到配置端口/当前会话端口与TCP监听的有效交集。';
        return 1
    };
    test -z "$stale" || warn "SSH审计发现配置保留但当前未监听的端口：$stale；继续保护但不判定服务故障。";
    case "$mode" in 
        password-capable)
            _e152_fail2ban_passive_verify || return 1;
            actions=$(fail2ban-client get "$E121_F2B_JAIL_NAME" actions 2> /dev/null || true);
            grep -qi 'nftables' <<< "$actions" || return 1
        ;;
        key-only | non-password | ambiguous)

        ;;
        *)
            return 1
        ;;
    esac;
