        state_dir=${state_file%/*};
    fi;
    install -d -m 0700 "$state_dir" || return 1;
    tmp="${state_file}.tmp.$$";
    { 
        echo "checked=$(date -Is 2> /dev/null || date)";
        echo "backend=nft";
        echo "auth_mode=$mode";
        echo "ports=$(printf '%s\n' $ports | paste -sd, -)";
        echo "listening=$(printf '%s\n' $listening | paste -sd, -)";
        echo "policy_mutated=0";
        echo "fail2ban_required=$(test "$mode" = password-capable && echo 1 || echo 0)"
    } > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    chmod 0600 "$tmp" || return 1;
    mv -f -- "$tmp" "$state_file"
