# EEX3-FUNCTION ssh_security_e141_158 _e152_nft_ssh_tx_begin
_e152_nft_ssh_tx_begin() {
    local tx unit;
    tx=$(_e172_nft_ssh_tx_begin_base) || return 1;
    rm -f -- "$tx/ssh-seal.sha256" || return 1;
    for unit in xray-ssh-auth-audit-e141w.service xray-ssh-auth-audit-e141w.timer xray-ssh-auth-audit-e142.service xray-ssh-auth-audit-e142.timer xray-ssh-auth-audit-e143.service xray-ssh-auth-audit-e143.timer;
    do
        grep -q "^${unit}|" "$tx/services.env" 2> /dev/null || _e152_unit_state_line "$unit" >> "$tx/services.env" || return 1;
    done;
    ( cd "$tx" && find . -type f ! -name ssh-seal.sha256 ! -name COMMITTED -print0 | sort -z | xargs -0 sha256sum > ssh-seal.sha256 ) || return 1;
    test -s "$tx/ssh-seal.sha256" || return 1;
    printf '%s\n' "$tx"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_nft_ssh_tx_commit
_e152_nft_ssh_tx_commit() {
    local tx="$1";
    test -d "$tx" && test -s "$tx/ssh-seal.sha256" && ( cd "$tx" && sha256sum -c ssh-seal.sha256 > /dev/null 2>&1 ) || return 1;
    { 
        echo "committed=$(date -Is 2> /dev/null || date)";
        echo "version=$SCRIPT_VERSION"
    } > "$tx/COMMITTED" || return 1;
    chmod 0600 "$tx/COMMITTED" || return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_nft_ssh_tx_rollback
_e152_nft_ssh_tx_rollback() {
    local tx="$1" p key unit enabled active table label rc=0;
    test -d "$tx" && test -s "$tx/files.manifest" && test -s "$tx/services.env" && test -s "$tx/ssh-seal.sha256" && ( cd "$tx" && sha256sum -c ssh-seal.sha256 > /dev/null 2>&1 ) || return 1;
    systemctl stop xray-ssh-native-e152.timer xray-ssh-native-e152.service xray-ssh-auth-audit-e152.timer xray-ssh-auth-audit-e152.service fail2ban.service > /dev/null 2>&1 || true;
    while IFS= read -r table; do
        nft delete table inet "$table" > /dev/null 2>&1 || true;
    done < <(_e165_nft_tables);
    while IFS='|' read -r p key; do
        test -n "$p" && test -n "$key" || continue;
        _e135_restore_file "$p" "$tx/files/$key" || rc=1;
    done < "$tx/files.manifest";
    systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    while IFS='|' read -r unit enabled active; do
        test -n "$unit" || continue;
        if test "$enabled" = 1; then
            systemctl enable "$unit" > /dev/null 2>&1 || rc=1;
        else
            systemctl disable "$unit" > /dev/null 2>&1 || true;
        fi;
    done < "$tx/services.env";
    while IFS='|' read -r unit enabled active; do
        test -n "$unit" || continue;
        if test "$active" = 1; then
            if test "$unit" = fail2ban.service; then
                systemctl restart "$unit" > /dev/null 2>&1 || rc=1;
            else
                systemctl start "$unit" > /dev/null 2>&1 || rc=1;
            fi;
        else
            systemctl stop "$unit" > /dev/null 2>&1 || true;
        fi;
    done < "$tx/services.env";
    while IFS= read -r table; do
        local restore_batch current_present=0;
        label=$(printf '%s' "$table" | tr -c 'A-Za-z0-9_.-' '_');
        nft list table inet "$table" > /dev/null 2>&1 && current_present=1 || true;
        if test -e "$tx/$label.present"; then
            restore_batch=$(mktemp /run/xray-e165-restore.XXXXXX) || { 
                rc=1;
                continue
            };
            { 
                test "$current_present" -eq 0 || echo "delete table inet $table";
                cat "$tx/$label.nft"
            } > "$restore_batch";
            nft -f "$restore_batch" > /dev/null 2>&1 || rc=1;
            rm -f -- "$restore_batch";
            nft list table inet "$table" > /dev/null 2>&1 || rc=1;
        else
            nft delete table inet "$table" > /dev/null 2>&1 || true;
            nft list table inet "$table" > /dev/null 2>&1 && rc=1 || true;
        fi;
    done < <(_e165_nft_tables);
    if systemctl is-active --quiet fail2ban.service 2> /dev/null; then
        fail2ban-client ping > /dev/null 2>&1 || rc=1;
    fi;
    return "$rc"
}
