# EEX3-FUNCTION ssh_security_e141_158 _e152_profile_value
_e152_profile_value() {
    local file="$1" key="$2";
    awk -F= -v k="$key" '
      {
        lhs=$1; gsub(/[[:space:]]/,"",lhs)
        if(lhs==k){
          sub(/^[^=]*=/,"")
          gsub(/^[[:space:]]+|[[:space:]]+$/,"")
          print
          exit
        }
      }' "$file"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_prune_transactions_base
_e152_prune_transactions_base() {
    local keep="${XRAY_E142_TX_KEEP:-12}" root row real p rc=0;
    local protected=" " pending="";
    [[ "$keep" =~ ^[0-9]+$ ]] && ((keep >= 12 && keep <= 100)) || keep=12;
    for p in "$@";
    do
        real=$(readlink -f -- "$p" 2> /dev/null || true);
        test -z "$real" || protected+="$real ";
    done;
    if test -s "$E140_FULL_PENDING"; then
        pending=$(head -n1 "$E140_FULL_PENDING" 2> /dev/null || true);
        real=$(readlink -f -- "$pending" 2> /dev/null || true);
        test -z "$real" || protected+="$real ";
    fi;
    if test -s "$E142_CRITICAL_MARKER"; then
        while IFS= read -r p; do
            real=$(readlink -f -- "$p" 2> /dev/null || true);
            test -z "$real" || protected+="$real ";
        done < <(sed -nE 's/^(system_backup|transaction|core_backup)=//p' "$E142_CRITICAL_MARKER");
    fi;
    for root in "$E142_TX_ROOT" "$E140_TX_ROOT";
    do
        test -d "$root" || continue;
        root=$(readlink -f -- "$root" 2> /dev/null || true);
        test -n "$root" || { 
            rc=1;
            continue
        };
        while IFS= read -r row; do
            test -n "$row" || continue;
            real=$(readlink -f -- "$row" 2> /dev/null || true);
            case "$real" in 
                "$root"/*)

                ;;
                *)
                    rc=1;
                    continue
                ;;
            esac;
            [[ "$protected" == *" $real "* ]] && continue;
            rm -rf -- "${real:?}" 2> /dev/null || rc=1;
        done < <(find "$root" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2> /dev/null | sort -nr | awk -F '\t' -v keep="$keep" 'NR>keep{print $2}');
    done;
    return "$rc"
}
