# EEX3-FUNCTION ssh_security_e141_158 _e152_restore_one
_e152_restore_one() {
    local path="$1" dir="$2" id type mode uid gid target;
    id=$(printf '%s' "$path" | sha256sum | awk '{print $1}');
    test -s "$dir/$id.meta" || return 1;
    type=$(sed -n 's/^type=//p' "$dir/$id.meta");
    mode=$(sed -n 's/^mode=//p' "$dir/$id.meta");
    uid=$(sed -n 's/^uid=//p' "$dir/$id.meta");
    gid=$(sed -n 's/^gid=//p' "$dir/$id.meta");
    case "$type" in 
        absent)
            rm -rf -- "$path"
        ;;
        symlink)
            target=$(sed -n 's/^target=//p' "$dir/$id.meta");
            rm -rf -- "$path";
            _e214_ensure_parent_dir "$path";
            ln -s -- "$target" "$path"
        ;;
        file)
            _e214_ensure_parent_dir "$path";
            install -m "$mode" "$dir/$id.data" "$path";
            chown "$uid:$gid" "$path" 2> /dev/null || true
        ;;
        dir)
            rm -rf -- "$path";
            tar -C / -xpf "$dir/$id.tar";
            chmod "$mode" "$path" 2> /dev/null || true;
            chown "$uid:$gid" "$path" 2> /dev/null || true
        ;;
        *)
            return 1
        ;;
    esac
}
