# EEX3-FUNCTION ssh_security_e141_158 _e152_snapshot_one
_e152_snapshot_one() {
    local path="$1" dir="$2" id meta;
    id=$(printf '%s' "$path" | sha256sum | awk '{print $1}');
    meta="$dir/$id.meta";
    if test -L "$path"; then
        printf 'type=symlink\npath=%s\ntarget=%s\n' "$path" "$(readlink "$path")" > "$meta" || return 1;
    else
        if test -f "$path"; then
            printf 'type=file\npath=%s\nmode=%s\nuid=%s\ngid=%s\n' "$path" "$(stat -c %a "$path")" "$(stat -c %u "$path")" "$(stat -c %g "$path")" > "$meta" || return 1;
            cp -a -- "$path" "$dir/$id.data" || return 1;
        else
            if test -d "$path"; then
                printf 'type=dir\npath=%s\nmode=%s\nuid=%s\ngid=%s\n' "$path" "$(stat -c %a "$path")" "$(stat -c %u "$path")" "$(stat -c %g "$path")" > "$meta" || return 1;
                tar -C / -cpf "$dir/$id.tar" "${path#/}" || return 1;
            else
                printf 'type=absent\npath=%s\n' "$path" > "$meta" || return 1;
            fi;
        fi;
    fi
}
