            cp -a -- "$path" "$tx/$id.data" || return 1;
        else
            if test -d "$path"; then
                printf 'type=dir\npath=%s\nmode=%s\nuid=%s\ngid=%s\n' "$path" "$(stat -c %a "$path")" "$(stat -c %u "$path")" "$(stat -c %g "$path")" > "$meta" || return 1;
            else
                printf 'type=absent\npath=%s\n' "$path" > "$meta" || return 1;
            fi;
        fi;
    fi
