# EEX3-FUNCTION ssh_security_e141_158 _e152_ssh_guard_inherited
_e152_ssh_guard_inherited() {
    local profile mode ip tmp;
    _e141_prepare || return 1;
    profile=$(_e141_sshd_auth_profile) || { 
        error "无法读取sshd有效认证配置。";
        return 1
    };
    mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1);
    ip=$(_e135_current_ssh_ip 2> /dev/null || true);
    tmp="${E141_SSH_AUTH_STATE}.tmp.$$";
    { 
        printf '%s\n' "$profile";
        printf 'current_ssh_ip=%s\nchecked_at=%s\n' "$ip" "$(date -Is 2> /dev/null || date)"
    } > "$tmp" || return 1;
    install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || { 
        rm -f "$tmp";
        return 1
    };
    rm -f "$tmp";
    case "$mode" in 
        key-only | non-password)
            _e141_install_key_only_ssh_guard || return 1
        ;;
        password-capable)
            info "检测到真实可登录账户仍允许密码/交互式认证：必须启用Fail2ban密码失败过滤。";
            _e137_ssh_backend_supported || return 1;
            _e137_ssh_guard_base || return 1
        ;;
        ambiguous)
            warn "Match块可能改变认证策略，但未确认真实可登录账户可用密码。先启用Key-only端口防锁。";
            _e141_install_key_only_ssh_guard || return 1;
            if command -v fail2ban-client > /dev/null 2>&1; then
                warn "系统已有Fail2ban，将继续验证脚本受管jail；不执行新软件安装。";
                _e137_ssh_backend_supported && _e137_ssh_guard_base || return 1;
            else
                warn "Fail2ban未安装；歧义模式不把软件源故障升级为热更新致命错误。";
            fi
        ;;
        *)
            error "未知SSH认证判定：$mode";
            return 1
        ;;
    esac;
    _e152_install_ssh_auth_audit
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_strip_managed_file
_e152_strip_managed_file() {
    local file="$1" keys tmp mode uid gid;
    test -f "$file" || return 0;
    keys=$(_e118_mktemp e152-managed-keys) || return 1;
    _e136_network_keys > "$keys" || return 1;
    tmp=$(_e118_mktemp e152-sysctl-strip) || return 1;
    mode=$(stat -c %a "$file");
    uid=$(stat -c %u "$file");
    gid=$(stat -c %g "$file");
    awk '
      NR==FNR { managed[$1]=1; next }
      {
        line=$0
        sub(/^[[:space:]]*/,"",line)
        if(line ~ /^#/ || line==""){ print; next }
        split(line,a,/=[[:space:]]*/)
        key=a[1]; gsub(/[[:space:]]/,"",key)
        if(managed[key]) next
        print
      }
    ' "$keys" "$file" > "$tmp" || return 1;
    install -m "$mode" "$tmp" "$file" || return 1;
    chown "$uid:$gid" "$file" 2> /dev/null || true
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_strip_old_definitions
_e152_strip_old_definitions() {
    local f;
    while IFS= read -r f; do
        test -f "$f" || continue;
        _e152_strip_managed_file "$f" || return 1;
    done < <(_e152_collect_sysctl_files)
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_structure_audit
_e152_structure_audit() {
    local total unique dup overrides dispatch;
    total=$(grep -Ec '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" || true);
    unique=$(grep -E '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" | sed -E 's/[[:space:]]*\(\).*//' | sort -u | wc -l);
    dup=$(grep -E '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" | sed -E 's/[[:space:]]*\(\).*//' | sort | uniq -d | wc -l);
    overrides=$(grep -Fc 'declare -f' "$SCRIPT_PATH" || true);
    dispatch=$(grep -Fc 'case "${1:-}" in' "$SCRIPT_PATH" || true);
    echo "V199e152结构审计：";
    echo "  函数定义=$total";
    echo "  唯一函数=$unique";
    echo "  重复函数名=$dup";
    echo "  动态函数复制=$overrides";
    echo "  dispatcher文本=$dispatch";
    echo "  最终网络事务=E152窄范围文件清单";
    echo "  最终热更新=E152真实阶段编排";
    echo "  说明：历史层仍保留，未虚构为模块化重写。"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_summary_base
_e152_summary_base() {
    _e135_prepare || return 1;
    test -s "$CONFIG" || { 
        error "config.json不存在，请先新建节点。";
        return 1
    };
    jq empty "$CONFIG" > /dev/null 2>&1 || { 
        error "config.json不是合法JSON。";
        return 1
    };
    title "V199e137 节点链接、参数与二维码输出中心";
    local ip host inbound port security network tag idx uuid flow email sid sni priv pbk link enc path type_part found=0 label method pass b64;
    ip=$(_get_ip);
    test -n "$ip" && test "$ip" != 获取失败 || { 
        ip=YOUR_SERVER_IP;
        warn "公网IP获取失败，请手动替换。"
    };
    [[ "$ip" == *:* ]] && host="[$ip]" || host="$ip";
    while IFS= read -r inbound; do
        security=$(jq -r '.streamSettings.security//"none"' <<< "$inbound");
        network=$(jq -r '.streamSettings.network//"tcp"' <<< "$inbound");
        port=$(jq -r '.port' <<< "$inbound");
        tag=$(jq -r '.tag//"vless"' <<< "$inbound");
        if test "$security" = reality; then
            priv=$(jq -r '.streamSettings.realitySettings.privateKey//empty' <<< "$inbound");
            pbk=$(_e124_reality_password_for_private "$priv" "" 2> /dev/null || true);
            sni=$(jq -r '.streamSettings.realitySettings.serverNames[0]//empty' <<< "$inbound");
            idx=0;
            while IFS= read -r uuid; do
                test -n "$uuid" || continue;
                found=1;
                flow=$(jq -r --argjson i "$idx" '.settings.clients[$i].flow//"xtls-rprx-vision"' <<< "$inbound");
                email=$(jq -r --argjson i "$idx" '.settings.clients[$i].email//"Reality"' <<< "$inbound");
                sid=$(_e118_user_sid "$uuid" "$idx");
                hr;
                printf '  %b【VLESS Reality Vision】%b\n' "$cyan" "$none";
                _e135_print_host_port "$ip" "$port";
                printf '  %-18s %s\n' "UUID:" "$uuid";
                printf '  %-18s %s\n' "流控:" "$flow";
                printf '  %-18s %s\n' "传输:" "$network";
                printf '  %-18s %s\n' "安全:" "reality";
                printf '  %-18s %s\n' "SNI:" "$sni";
                printf '  %-18s %s\n' "Password(pbk):" "${pbk:-缺失}";
                printf '  %-18s %s\n' "ShortId:" "${sid:-缺失}";
                printf '  %-18s %s\n' "Fingerprint:" "chrome";
                if test -n "$pbk" && test -n "$sid" && test -n "$sni"; then
                    link="vless://${uuid}@${host}:${port}?encryption=none&flow=$(_e118_urlencode "$flow")&security=reality&sni=$(_e118_urlencode "$sni")&fp=chrome&pbk=$(_e118_urlencode "$pbk")&sid=$(_e118_urlencode "$sid")&type=tcp#$(_e118_urlencode "$email")";
                    printf '\n  %b配置导入链接:%b\n%s\n' "$cyan" "$none" "$link";
                    _e135_emit_qr "$link" "${tag}-${email}-${idx}-reality";
                else
                    warn "Reality参数不完整，拒绝生成无效链接。";
                fi;
                idx=$((idx+1));
            done < <(jq -r '.settings.clients[]?.id//empty' <<< "$inbound");
        else
            if test "$(jq -r '.settings.decryption//"none"' <<< "$inbound")" != none; then
                enc=$(cat "${E77_VLESSENC_CLIENT_FILE:-$CONFIG_DIR/vlessenc.client.txt}" 2> /dev/null || true);
                idx=0;
                while IFS= read -r uuid; do
                    test -n "$uuid" || continue;
                    found=1;
                    flow=$(jq -r --argjson i "$idx" '.settings.clients[$i].flow//"xtls-rprx-vision"' <<< "$inbound");
                    email=$(jq -r --argjson i "$idx" '.settings.clients[$i].email//"VLESSENC"' <<< "$inbound");
                    hr;
                    printf '  %b【VLESSENC Vision】%b\n' "$cyan" "$none";
                    _e135_print_host_port "$ip" "$port";
                    printf '  %-18s %s\n' "UUID:" "$uuid";
                    printf '  %-18s %s\n' "流控:" "$flow";
                    printf '  %-18s %s\n' "传输:" "$network";
                    printf '  %-18s %s\n' "安全:" "none";
                    if test -n "$enc"; then
                        if test "$network" = xhttp; then
                            path=$(jq -r '.streamSettings.xhttpSettings.path//empty' <<< "$inbound");
                            type_part="type=xhttp&path=$(_e118_urlencode "$path")&mode=auto";
                        else
                            type_part=type=tcp;
                        fi;
                        link="vless://${uuid}@${host}:${port}?encryption=$(_e118_urlencode "$enc")&flow=$(_e118_urlencode "$flow")&security=none&${type_part}#$(_e118_urlencode "$email")";
                        printf '\n  %b完整导入链接:%b\n%s\n' "$cyan" "$none" "$link";
                        _e135_emit_qr "$link" "${tag}-${email}-${idx}-vlessenc";
                    else
                        warn "缺少VLESSENC客户端encryption参数文件。";
                    fi;
                    idx=$((idx+1));
                done < <(jq -r '.settings.clients[]?.id//empty' <<< "$inbound");
            fi;
        fi;
    done < <(jq -c '.inbounds[]? | select(.protocol=="vless")' "$CONFIG");
    while IFS= read -r inbound; do
        found=1;
        port=$(jq -r '.port' <<< "$inbound");
        method=$(jq -r '.settings.method' <<< "$inbound");
        pass=$(jq -r '.settings.password' <<< "$inbound");
        label="${REMARK_NAME:-xp-reality}-SS2022";
        b64=$(printf '%s:%s' "$method" "$pass" | base64 | tr '+/' '-_' | tr -d '=\n\r');
        link="ss://${b64}@${host}:${port}#$(_e118_urlencode "$label")";
        hr;
        printf '  %b【SS2022】%b\n' "$cyan" "$none";
        _e135_print_host_port "$ip" "$port";
        printf '  %-18s %s\n' "加密方式:" "$method";
        printf '  %-18s %s\n' "密码:" "$pass";
        printf '\n  %b配置导入链接:%b\n%s\n' "$cyan" "$none" "$link";
        _e135_emit_qr "$link" "${label}-${port}";
    done < <(jq -c '.inbounds[]? | select(.protocol=="shadowsocks")' "$CONFIG");
    test "$found" -eq 1 || { 
        warn "没有可导出的节点。";
        return 1
    };
    info "导出目录：$E135_EXPORT_DIR"
}
