# EEX3-FUNCTION ssh_security_e141_158 _e152_system_restore_base
_e152_system_restore_base() {
    local b="$1" svc enabled active rc=0 journal_pre=1 dropin_pre=1;
    test -d "$b" || return 1;
    if test -e "$b/e139-services.env"; then
        test -s "$b/e139-services.sha256" && ( cd "$b" && sha256sum -c e139-services.sha256 > /dev/null 2>&1 ) || { 
            error "E139服务状态快照校验失败，拒绝恢复。";
            return 1
        };
    fi;
    if test -e "$b/e140-services.env"; then
        test -s "$b/e140-services.sha256" && ( cd "$b" && sha256sum -c e140-services.sha256 > /dev/null 2>&1 ) || { 
            error "E140服务状态快照校验失败，拒绝恢复。";
            return 1
        };
    fi;
    _e139_system_restore "$b" || return 1;
    if test -s "$b/e140-services.env"; then
        while IFS='|' read -r svc enabled active; do
            test -n "$svc" || continue;
            if _eex3_ssh_control_preserved && _eex3_ssh_unit_protected "$svc"; then
                continue;
            fi;
            _e266_service_state_apply "$svc" "" "$enabled" "$active" || rc=1;
        done < "$b/e140-services.env";
    fi;
    if test -s "$b/e142-prestate.env"; then
        journal_pre=$(sed -n 's/^journal_dir_preexisting=//p' "$b/e142-prestate.env" | tail -n1);
        dropin_pre=$(sed -n 's/^journald_dropin_dir_preexisting=//p' "$b/e142-prestate.env" | tail -n1);
        [[ "$journal_pre" =~ ^[01]$ ]] || return 1;
        [[ "$dropin_pre" =~ ^[01]$ ]] || return 1;
        test "$journal_pre" = 1 || rm -rf -- /var/log/journal 2> /dev/null || rc=1;
        test "$dropin_pre" = 1 || rmdir /etc/systemd/journald.conf.d 2> /dev/null || true;
    fi;
    systemctl restart systemd-journald.service > /dev/null 2>&1 || rc=1;
    return "$rc"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_system_snapshot_base
_e152_system_snapshot_base() {
    local b="$1" svc;
    _e139_system_snapshot "$b" || return 1;
    : > "$b/e140-services.env" || return 1;
    for svc in xray-warp-full-e140-route.service xray-warp-full-e140-health.service xray-warp-full-e140-health.timer xray-warp-full-e140-rollback.service xray-warp-full-e140-rollback.timer xray-ssh-port-guard-e121.service xray-ssh-port-guard-e121.timer xray-log-retention-e121.service xray-log-retention-e121.timer xray-ssh-auth-audit-e142.service xray-ssh-auth-audit-e142.timer;
    do
        _e159_snapshot_service "$svc" >> "$b/e140-services.env" || return 1;
    done;
    { 
        echo "journal_dir_preexisting=$(test -e /var/log/journal && echo 1 || echo 0)";
        echo "journald_dropin_dir_preexisting=$(test -e /etc/systemd/journald.conf.d && echo 1 || echo 0)"
    } > "$b/e142-prestate.env" || return 1;
    ( cd "$b" && sha256sum e140-services.env e142-prestate.env > e140-services.sha256 ) || return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_test_snapshot_behavior
_e152_test_snapshot_behavior() {
    local d tx f;
    d=$(mktemp -d /tmp/e152-snapshot.XXXXXX) || return 1;
    tx="$d/tx";
    f="$d/file";
    mkdir "$tx" || return 1;
    printf 'before\n' > "$f";
    _e152_snapshot_path "$f" "$tx" || { 
        rm -rf "$d";
        return 1
    };
    printf 'after\n' > "$f";
    _e152_restore_path "$f" "$tx" || { 
        rm -rf "$d";
        return 1
    };
    grep -qx before "$f";
    local rc=$?;
    rm -rf "$d";
    return "$rc"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_test_strip_behavior
_e152_test_strip_behavior() {
    local d f;
    d=$(mktemp -d /tmp/e152-strip.XXXXXX) || return 1;
    f="$d/test.conf";
    cat > "$f" <<'EOF_E152_TEST_SYSCTL'
# keep comment
net.ipv4.tcp_notsent_lowat = 999
vm.swappiness = 10
net.ipv4.conf.all.rp_filter = 1
EOF_E152_TEST_SYSCTL

    _e152_strip_managed_file "$f" || { 
        rm -rf "$d";
        return 1
    };
    grep -q '^vm.swappiness = 10$' "$f" && ! grep -q 'tcp_notsent_lowat' "$f" && ! grep -q 'rp_filter' "$f";
    local rc=$?;
    rm -rf "$d";
    return "$rc"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_tx_ok
_e152_tx_ok() {
    local d="$1" real root;
    test -d "$d" || return 1;
    real=$(readlink -f -- "$d" 2> /dev/null || true);
    root=$(readlink -f -- "$E152_TX_ROOT" 2> /dev/null || true);
    test -n "$real" && test -n "$root" || return 1;
    case "$real" in 
        "$root"/*)
            return 0
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_uninstall_base
_e152_uninstall_base() {
    local confirm="" archive;
    local enabled mode;
    archive="/root/xray-before-uninstall-e152-$(date +%Y%m%d_%H%M%S)-$$.tgz";
    title "V199e152：受控卸载 Xray 环境";
    warn "先创建可读回归档，再关闭脚本管理的WARP、恢复网络基线，最后移除Xray。";
    warn "cloudflare-warp软件包不会被删除，但脚本管理的连接和策略路由会关闭。";
    read -rp "请输入 DELETE-XRAY 确认: " confirm || true;
    test "$confirm" = DELETE-XRAY || { 
        info "已取消，系统未修改。";
        return 0
    };
    _e142_create_uninstall_archive "$archive" || { 
        error "卸载前归档创建或读回失败；拒绝执行删除。";
        return 1
    };
    info "已验证卸载前归档：$archive";
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    if test "$enabled" = 1; then
        _e138_warp_disable || { 
            error "WARP关闭失败，拒绝继续卸载。";
            return 1
        };
    fi;
    _e140_full_route_cleanup;
    ip -4 rule show 2> /dev/null | grep -Eq "^(${E140_FULL_RULE_PRIORITY}|${E139_FULL_RULE_PRIORITY}):" && { 
        error "仍存在脚本管理的全隧道策略规则，拒绝删除恢复材料。";
        return 1
    } || true;
    _e142_restore_network_baseline || return 1;
    _e126_remove_layer uninstall || return 1;
    rm -f -- "$E135_NETWORK_CONF" "$E136_NETWORK_CONF" "$E138_NETWORK_CONF" "$E139_NETWORK_CONF" 2> /dev/null || true;
    sysctl --system > /dev/null 2>&1 || warn "其它系统sysctl文件存在加载错误；已恢复的逐项运行基线仍保留。";
    systemctl disable --now xray-log-retention-e121.timer xray-log-retention-e121.service > /dev/null 2>&1 || true;
    rm -rf -- "$E142_LOG_DROPIN_DIR" 2> /dev/null || true;
    rm -f -- "$E142_LOG_EXTRA_SCRIPT" 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || true;
    _e142_restore_preexisting_journal_policy || { 
        error "安装前journald策略恢复失败，拒绝删除其备份。";
        return 1
    };
    _e121_do_uninstall <<< 'DELETE-XRAY'
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_uninstall_inherited
_e152_uninstall_inherited() {
    local rc=0;
    _e152_uninstall_base "$@" || rc=$?;
    systemctl disable --now xray-ssh-auth-audit-e152.timer xray-ssh-auth-audit-e152.service > /dev/null 2>&1 || true;
    rm -f -- "$E152_SSH_AUTH_SERVICE" "$E152_SSH_AUTH_TIMER" "$E152_F2B_FILTER" "$E152_TRANSIENT_IGNORE" "$E152_SELF_PATH" 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || true;
    return "$rc"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_unit_state_line
_e152_unit_state_line() {
    local unit="$1" enabled=0 active=0;
    systemctl is-enabled --quiet "$unit" 2> /dev/null && enabled=1 || true;
    systemctl is-active --quiet "$unit" 2> /dev/null && active=1 || true;
    printf '%s|%s|%s\n' "$unit" "$enabled" "$active"
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_verify_network_tx_seal
_e152_verify_network_tx_seal() {
    local tx="$1";
    _e152_network_tx_dir_ok "$tx" || return 1;
    if test -e "$tx/e152-transaction.sha256"; then
        test -s "$tx/e152-transaction.sha256" && ( cd "$tx" && sha256sum -c e152-transaction.sha256 > /dev/null 2>&1 );
        return;
    fi;
    if test -e "$tx/e142-transaction.sha256"; then
        test -s "$tx/e142-transaction.sha256" && ( cd "$tx" && sha256sum -c e142-transaction.sha256 > /dev/null 2>&1 );
        return;
    fi;
    return 1
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_verify_nft_fail2ban_action
_e152_verify_nft_fail2ban_action() {
    _e165_f2b_action_present || { 
        _e165_f2b_diag fail action-not-loaded none;
        error "Fail2ban未加载$E165_F2B_ACTION_ID；诊断：$E165_F2B_DIAG";
        return 1
    };
    _e165_f2b_test_family inet4 || { 
        error "Fail2ban IPv4票据→E165 nft集合→unban清理闭环失败；诊断：$E165_F2B_DIAG";
        return 1
    };
    _e165_helper_check || { 
        _e165_f2b_diag fail helper-contract-after-ipv4 none;
        error "E165 nftables只读结构验证在真实封禁后失败；诊断：$E165_F2B_DIAG";
        return 1
    };
    if _e159_ipv6_ssh_relevant; then
        _e165_f2b_test_family inet6 || { 
            error "SSH暴露IPv6，但E165 IPv6封禁闭环失败；诊断：$E165_F2B_DIAG";
            return 1
        };
    fi
}
# EEX3-FUNCTION ssh_security_e141_158 _e152_warp_full_enable_base
_e152_warp_full_enable_base() {
    local service_mode="${1:-traffic-only}" protocol="${2:-MASQUE}" token tx failed=0 confirm="";
    title "V199e142：Cloudflare系统全隧道（确认竞态修复版）";
    if _e140_full_mode_active; then
        error "系统全隧道已处于启用状态；拒绝叠加第二个启用事务，请使用修复/关闭入口。";
        return 1;
    fi;
    warn "将接管VPS新建出站；必须有网页控制台/VNC，并用第二SSH会话确认。";
    read -rp "输入 ENABLE-CLOUDFLARE-FULL-TUNNEL 确认: " token || true;
    test "$token" = ENABLE-CLOUDFLARE-FULL-TUNNEL || return 0;
    _e140_prepare || return 1;
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    tx=$(_e142_new_tx warp-full-enable) || return 1;
    E140_ACTIVE_LOG="$E140_FULL_LOG_DIR/enable-$(date +%Y%m%d_%H%M%S)-$$.log";
    : > "$E140_ACTIVE_LOG" || return 1;
    _e140_full_snapshot "$tx" || return 1;
    _e140_set_stage package;
    _e136_warp_install_package "$tx" || { 
        E140_LAST_ERROR="cloudflare-warp安装/服务启用失败";
        failed=1
    };
    test "$failed" -ne 0 || { 
        _e140_set_stage service-ipc;
        _e140_warp_service_wait || failed=1
    };
    test "$failed" -ne 0 || { 
        _e140_set_stage clear-xray-local-warp;
        _e139_clear_xray_warp_rules || failed=1
    };
    test "$failed" -ne 0 || systemctl disable --now xray-warp-e136-health.timer xray-warp-e137-health.timer xray-warp-e138-health.timer > /dev/null 2>&1 || true;
    test "$failed" -ne 0 || { 
        _e140_set_stage capture-direct-route;
        _e140_capture_direct_route || { 
            E140_LAST_ERROR="无法捕获原IPv4默认路由/源地址";
            failed=1
        }
    };
    test "$failed" -ne 0 || _e139_state_set_fields route_enabled 1 route_mode host-full profile host-full full_service_mode "$service_mode" full_protocol "$protocol" full_strict_loc non-cn managed_by e142 || failed=1;
    test "$failed" -ne 0 || { 
        _e140_set_stage install-units;
        _e140_full_install_units || failed=1
    };
    test "$failed" -ne 0 || { 
        _e140_set_stage reply-route;
        _e140_full_route_apply || { 
            E140_LAST_ERROR="原IPv4回程策略路由建立失败";
            failed=1
        }
    };
    if test "$failed" = 0; then
        printf '%s\n' "$tx" > "$E140_FULL_PENDING" || failed=1;
        systemctl enable --now xray-warp-full-e140-rollback.timer >> "$E140_ACTIVE_LOG" 2>&1 || failed=1;
    fi;
    test "$failed" -ne 0 || { 
        _e140_set_stage registration;
        _e140_warp_register || failed=1
    };
    test "$failed" -ne 0 || { 
        _e140_set_stage protocol;
        _e140_warp_set_protocol "$protocol" || failed=1
    };
    test "$failed" -ne 0 || { 
        _e140_set_stage mode;
        _e140_warp_set_mode "$service_mode" || failed=1
    };
    test "$failed" -ne 0 || { 
        _e140_set_stage connect;
        _e140_warp_connect_wait || failed=1
    };
    test "$failed" -ne 0 || { 
        _e140_set_stage final-verify;
        _e140_full_verify "$service_mode" "$protocol" || failed=1
    };
    if test "$failed" -ne 0; then
        _e140_capture_diagnostics "$E140_ACTIVE_LOG";
        error "Cloudflare全隧道失败阶段：${E140_LAST_STAGE:-unknown} ${E140_LAST_ERROR:-}";
        _e140_full_rollback_tx "$tx" || true;
        return 1;
    fi;
    warn "请在110秒内另开一个SSH窗口登录；成功后输入 KEEP-FULL-TUNNEL。";
    if read -r -t 110 -p "确认: " confirm && test "$confirm" = KEEP-FULL-TUNNEL; then
        systemctl restart xray-warp-full-e140-rollback.timer > /dev/null 2>&1 || failed=1;
        test "$failed" -ne 0 || systemctl is-active --quiet xray-warp-full-e140-rollback.timer 2> /dev/null || failed=1;
        test "$failed" -ne 0 || _e140_full_verify "$service_mode" "$protocol" || failed=1;
        test "$failed" -ne 0 || systemctl enable --now xray-warp-full-e140-route.service xray-warp-full-e140-health.timer > /dev/null 2>&1 || failed=1;
        test "$failed" -ne 0 || systemctl is-enabled --quiet xray-warp-full-e140-health.timer 2> /dev/null || failed=1;
        if test "$failed" -eq 0; then
            rm -f "$E140_FULL_PENDING" || failed=1;
        fi;
        if test "$failed" -eq 0; then
            systemctl disable --now xray-warp-full-e140-rollback.timer > /dev/null 2>&1 || failed=1;
            systemctl is-active --quiet xray-warp-full-e140-rollback.timer 2> /dev/null && failed=1 || true;
        fi;
        if test "$failed" -eq 0; then
            info "Cloudflare系统全隧道已启用、复检并解除自动回滚。日志：$E140_ACTIVE_LOG";
            _e140_warp_status;
            return 0;
        fi;
        error "确认后的最终固化失败，执行显式回滚。";
        _e140_full_rollback_tx "$tx" || true;
        return 1;
    fi;
    warn "未完成第二SSH会话确认，执行安全回滚。";
    _e140_full_rollback_tx "$tx";
    return 1
}
