# EEX3-FUNCTION network_e159_164 _e159_action_tfo_toggle
_e159_action_tfo_toggle() {
    local current;
    current=$(jq -r '.outbounds[]? | select(.protocol=="freedom") | .streamSettings?.sockopt?.tcpFastOpen // false' "$CONFIG" 2> /dev/null | head -n1);
    if test "$current" = true; then
        _safe_jq_write '(.outbounds[]? | select(.streamSettings?.sockopt? != null) | .streamSettings.sockopt.tcpFastOpen)=false | (.inbounds[]? | select(.streamSettings?.sockopt? != null) | .streamSettings.sockopt.tcpFastOpen)=false';
    else
        _safe_jq_write '(.outbounds[]? | select(.streamSettings?.sockopt? != null) | .streamSettings.sockopt.tcpFastOpen)=true | (.inbounds[]? | select(.streamSettings?.sockopt? != null) | .streamSettings.sockopt.tcpFastOpen)=true';
    fi
}
