# EEX3-FUNCTION network_e159_164 _e159_alias_matrix_test
_e159_alias_matrix_test() {
    local d spec effective report root case_name old_proc="" had_proc=0 rc=0;
    d=$(mktemp -d /tmp/e159-alias-matrix.XXXXXX) || return 1;
    spec="$d/spec.conf";
    cat > "$spec" <<'EOF_E159_ALIAS_SPEC'
net.ipv4.neigh.default.unres_qlen = 3000
net.ipv4.neigh.default.unres_qlen_bytes = 65535
EOF_E159_ALIAS_SPEC

    if test -n "${E159_PROC_ROOT+x}"; then
        old_proc=$E159_PROC_ROOT;
        had_proc=1;
    fi;
    for case_name in both packets bytes;
    do
        root="$d/$case_name/proc";
        mkdir -p "$root/net/ipv4/neigh/default" || { 
            rc=1;
            break
        };
        case "$case_name" in 
            both)
                : > "$root/net/ipv4/neigh/default/unres_qlen";
                : > "$root/net/ipv4/neigh/default/unres_qlen_bytes"
            ;;
            packets)
                : > "$root/net/ipv4/neigh/default/unres_qlen"
            ;;
            bytes)
                : > "$root/net/ipv4/neigh/default/unres_qlen_bytes"
            ;;
        esac;
        effective="$d/$case_name/effective.conf";
        report="$d/$case_name/report.tsv";
        E159_PROC_ROOT="$root";
        _e159_build_effective "$spec" "$effective" "$report" || { 
            rc=1;
            break
        };
        case "$case_name" in 
            both)
                grep -q '^net.ipv4.neigh.default.unres_qlen	shadowed-alias	3000	' "$report" && grep -q '^net.ipv4.neigh.default.unres_qlen_bytes	supported	65535	' "$report" && ! grep -Eq '^net\.ipv4\.neigh\.default\.unres_qlen[[:space:]]*=' "$effective" || { 
                    rc=1;
                    break
                }
            ;;
            packets)
                grep -q '^net.ipv4.neigh.default.unres_qlen	supported	3000	' "$report" && grep -q '^net.ipv4.neigh.default.unres_qlen_bytes	unsupported	65535	' "$report" && grep -qx 'net.ipv4.neigh.default.unres_qlen = 3000' "$effective" || { 
                    rc=1;
                    break
                }
            ;;
            bytes)
                grep -q '^net.ipv4.neigh.default.unres_qlen	unsupported	3000	' "$report" && grep -q '^net.ipv4.neigh.default.unres_qlen_bytes	supported	65535	' "$report" && grep -qx 'net.ipv4.neigh.default.unres_qlen_bytes = 65535' "$effective" || { 
                    rc=1;
                    break
                }
            ;;
        esac;
    done;
    if test "$had_proc" -eq 1; then
        E159_PROC_ROOT=$old_proc;
    else
        unset E159_PROC_ROOT;
    fi;
    rm -rf -- "$d";
    return "$rc"
}
# EEX3-FUNCTION network_e159_164 _e159_all_source_sysctl_audit
_e159_all_source_sysctl_audit() {
    local requested="$1" key f n count duplicate_keys=0 source_files=0;
    local -a sources=();
    mapfile -t sources < <(_e159_sysctl_sources);
    source_files=${#sources[@]};
    echo;
    echo "  全来源持久化审计：$source_files 个唯一文件";
    echo "  范围：/usr/lib、/usr/local/lib、/lib、/run、/etc/sysctl.d、/etc/sysctl.conf";
    echo "  处理原则：vendor/run只读；仅迁移脚本确认拥有的/etc文件。";
    while IFS= read -r key; do
        test -n "$key" || continue;
        count=0;
        for f in "${sources[@]}";
        do
            n=$(awk -F= -v wanted="$key" '
              /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
                k=$1; gsub(/[[:space:]]/,"",k); if(k==wanted)n++
              }
              END{print n+0}' "$f" 2> /dev/null || echo 0);
            count=$((count+n));
        done;
        if (( count > 1 )); then
            duplicate_keys=$((duplicate_keys+1));
            printf '    [重复%u] %s\n' "$count" "$key";
            for f in "${sources[@]}";
            do
                grep -nE "^[[:space:]]*${key//./\\.}[[:space:]]*=" "$f" 2> /dev/null | sed "s#^#      $f:#" || true;
            done;
        fi;
    done < <(_e159_active_keys "$requested");
    echo "  全来源重复键数量：$duplicate_keys"
}
