# EEX3-FUNCTION network_e159_164 _e159_apply_runtime
_e159_apply_runtime() {
    local file="$1" key value current failed=0 low="" high="" pair=0;
    value=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ip_forward[[:space:]]*$/{print $2;exit}' "$file" | xargs);
    if test -n "$value"; then
        current=$(sysctl -n net.ipv4.ip_forward 2> /dev/null | xargs || true);
        test "$current" = "$value" || sysctl -w "net.ipv4.ip_forward=$value" > /dev/null 2>&1 || return 1;
    fi;
    low=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ipfrag_low_thresh[[:space:]]*$/{print $2;exit}' "$file" | xargs);
    high=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ipfrag_high_thresh[[:space:]]*$/{print $2;exit}' "$file" | xargs);
    if test -n "$low" && test -n "$high"; then
        _e170_apply_ipfrag_pair_values "$low" "$high" || return 1;
        pair=1;
    fi;
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key");
        value=$(_e159_norm "$value");
        case "$key" in 
            '' | '#'* | net.ipv4.ip_forward | net.ipv4.route.flush)
                continue
            ;;
            net.ipv4.ipfrag_low_thresh | net.ipv4.ipfrag_high_thresh)
                test "$pair" -eq 1 && continue
            ;;
        esac;
        sysctl -w "$key=$value" > /dev/null 2>&1 || { 
            error "E159写入失败：$key";
            return 1
        };
    done < "$file";
    if grep -q '^net.ipv4.route.flush[[:space:]]*=' "$file"; then
        sysctl -w net.ipv4.route.flush=1 > /dev/null 2>&1 || { 
            error "路由缓存刷新触发失败。";
            return 1
        };
    fi;
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key");
        value=$(_e159_norm "$value");
        case "$key" in 
            '' | '#'* | net.ipv4.route.flush)
                continue
            ;;
        esac;
        current=$(sysctl -n "$key" 2> /dev/null || true);
        _e159_value_equal "$key" "$value" "$current" || { 
            error "E159读回不一致：$key 期望=$value 实际=${current:-unreadable}";
            failed=1
        };
    done < "$file";
    test "$failed" -eq 0
}
