# EEX3-FUNCTION network_e159_164 _e159_core_update_signal
_e159_core_update_signal() {
    local sig="${1:-TERM}" bdir="${E159_CORE_TX_BACKUP:-}" rc=0;
    trap - INT TERM HUP;
    warn "Core更新收到$sig，执行Core、配置、元数据与服务联合回滚。";
    test -n "$bdir" && _e159_restore_core_update "$bdir" || rc=1;
    if test "$rc" -ne 0; then
        { 
            echo "time=$(date -Is 2> /dev/null || date)";
            echo "operation=core-update-signal";
            echo "signal=$sig";
            echo "core_backup=${bdir:-none}"
        } > "$E159_CRITICAL_MARKER" 2> /dev/null || true;
    fi;
    cleanup_temp_files;
    exit 130
}
# EEX3-FUNCTION network_e159_164 _e159_critical_key
