    case "$1" in 
        net.core.default_qdisc | net.ipv4.tcp_congestion_control | net.ipv4.tcp_mtu_probing | net.ipv4.tcp_slow_start_after_idle | net.core.rmem_default | net.core.wmem_default | net.core.rmem_max | net.core.wmem_max | net.ipv4.tcp_rmem | net.ipv4.tcp_wmem | net.ipv4.tcp_notsent_lowat | net.ipv4.tcp_limit_output_bytes | net.ipv4.conf.all.rp_filter | net.ipv4.conf.default.rp_filter | net.ipv4.ip_forward | net.ipv4.conf.all.forwarding)
            return 0
        ;;
        *)
            return 1
        ;;
    esac
}
