    do
        rm -f -- "$f" 2> /dev/null || return 1;
    done;
    for f in /etc/sysctl.d/99-network-optimized.conf /etc/sysctl.d/98-xray-core-tuning.conf /etc/sysctl.d/99-xray-hotupdate-fast.conf /etc/sysctl.d/99-xray-pmtu-e106.conf /etc/sysctl.d/99-xray-pmtu-e107.conf /etc/sysctl.d/99-auto-tune-relay-e108.conf /etc/sysctl.d/99-auto-tune-relay-e109.conf /etc/sysctl.d/98-xray-swap.conf;
    do
        test -e "$f" || continue;
        if _e159_legacy_sysctl_owned "$f"; then
            rm -f -- "$f" || return 1;
        else
            warn "保留未能确认归属的旧sysctl文件：$f（逐项审计会报告重复定义）。";
        fi;
    done;
    rm -f -- "$E152_NETWORK_STATE" 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || return 1
}
