# EEX3-FUNCTION network_e159_164 _e159_f2b_action_values_valid
_e159_f2b_action_values_valid() {
    local table="$1" family="$2" chain="$3" hook="$4" priority="$5";
    local demand="$6" type="$7" blocktype="$8" port="$9" protocol="${10}";
    local expected_ports="${11}" start="${12}" ban="${13}" unban="${14}";
    test "$table" = "$E159_NFT_F2B_TABLE" || return 1;
    test "$family" = inet || return 1;
    test "$chain" = "$E159_NFT_F2B_CHAIN" || return 1;
    test "$hook" = input || return 1;
    test "$priority" = -1 || return 1;
    test "$type" = multiport || return 1;
    test "$blocktype" = reject || return 1;
    test "$protocol" = tcp || return 1;
    test "${port//[[:space:]]/}" = "${expected_ports//[[:space:]]/}" || return 1;
    case "${demand,,}" in 
        0 | false | no | off)

        ;;
        *)
            return 1
        ;;
    esac;
    [[ "$start" == *"add table"* && "$start" == *"add chain"* ]] || return 1;
    [[ "$ban" == *"add element"* ]] || return 1;
    [[ "$unban" == *"delete element"* ]] || return 1
}
