# EEX3-FUNCTION network_e159_164 _e159_f2b_mock_planes
_e159_f2b_mock_planes() {
    ( local MOCK_MODE=good MOCK_BANNED="";
    function sleep () 
    { 
        :
    };
    function _e159_f2b_diag () 
    { 
        :
    };
    function _e116_detect_ssh_ports () 
    { 
        echo 22
    };
    function fail2ban-client () 
    { 
        local op="${1:-}" sub="${3:-}" name="${4:-}" property="${5:-}" ip="";
        if test "$op" = get && test "$sub" = actions; then
            echo "['nftables']";
            return 0;
        fi;
        if test "$op" = get && test "$sub" = action; then
            case "$property" in 
                table)
                    echo f2b-e159
                ;;
                table_family)
                    echo inet
                ;;
                chain)
                    echo f2b-e159-input
                ;;
                chain_hook)
                    echo input
                ;;
                chain_priority)
                    echo -1
                ;;
                actionstart_on_demand)
                    echo false
                ;;
                type)
                    echo multiport
                ;;
                blocktype)
                    echo reject
                ;;
                port)
                    echo 22
                ;;
                protocol)
                    echo tcp
                ;;
                actionstart)
                    echo 'nft add table inet f2b-e159; nft add chain inet f2b-e159 f2b-e159-input'
                ;;
                actionban)
                    echo 'nft add element inet f2b-e159 addr-set-mock { <ip> }'
                ;;
                actionunban)
                    echo 'nft delete element inet f2b-e159 addr-set-mock { <ip> }'
                ;;
                *)
                    return 1
                ;;
            esac;
            return 0;
        fi;
        if test "$op" = get && test "$sub" = banned; then
            ip="$name";
            test -n "$MOCK_BANNED" && test "$MOCK_BANNED" = "$ip" && echo 1 || echo 0;
            return 0;
        fi;
        if test "$op" = get && test "$sub" = banip; then
            test -z "$MOCK_BANNED" || echo "$MOCK_BANNED";
            return 0;
        fi;
        if test "$op" = set && test "$sub" = banip; then
            MOCK_BANNED="$name";
            return 0;
        fi;
        if test "$op" = set && test "$sub" = unbanip; then
            MOCK_BANNED="";
            return 0;
        fi;
        return 1
    };
    function nft () 
    { 
        local element="";
        test "$MOCK_MODE" != good || element="$MOCK_BANNED";
        if test "${1:-}" = -j; then
            command jq -nc --arg ip "$element" '{nftables:[
              {chain:{name:"f2b-e159-input",hook:"input",prio:-1}},
              {rule:{expr:[{match:{right:"@addr-set-mock"}},{reject:null}],element:$ip}}
            ]}';
            return 0;
        fi;
        if test "${1:-}" = -a; then
            printf 'chain f2b-e159-input { type filter hook input priority -1; ip saddr @addr-set-mock reject; }\n';
            test -z "$element" || printf '%s\n' "$element";
            return 0;
        fi;
        if test "${1:-}" = list; then
            printf 'chain f2b-e159-input { type filter hook input priority -1; ip saddr @addr-set-mock reject; }\n';
            test -z "$element" || printf '%s\n' "$element";
            return 0;
        fi;
        return 0
    };
    _e159_f2b_action_contract || return 1;
    _e159_nft_table_contract || return 1;
    _e159_f2b_test_family inet4 || return 1;
    test -z "$MOCK_BANNED" || return 1;
    MOCK_MODE=ticket-only;
    ! _e159_f2b_test_family inet4 || return 1;
    test -z "$MOCK_BANNED" )
}
# EEX3-FUNCTION network_e159_164 _e159_f2b_test_family
_e159_f2b_test_family() {
    ( local family="$1" current="${E152_CURRENT_SSH_IP:-}" candidate test_ip="" i;
    local plane_ticket=0 plane_nft=0 cleanup_ok=0;
    local -a candidates4=(192.0.2.159 198.51.100.159 203.0.113.159 192.0.2.160);
    local -a candidates6=(2001:db8:159::1 2001:db8:159::2 2001:db8:160::1);
    local -a candidates=();
    case "$family" in 
        inet4)
            candidates=("${candidates4[@]}")
        ;;
        inet6)
            candidates=("${candidates6[@]}")
        ;;
        *)
            return 1
        ;;
    esac;
    function cleanup_test_ip () 
    { 
        local j;
        test -n "$test_ip" || return 0;
        fail2ban-client set "$E121_F2B_JAIL_NAME" unbanip --report-absent "$test_ip" > /dev/null 2>&1 || true;
        for j in {1..20};
        do
            _e159_f2b_banned_state "$test_ip" 0 > /dev/null 2>&1 && ! _e159_nft_has_element "$test_ip" && return 0;
            sleep 0.1;
        done;
        return 1
    };
    trap cleanup_test_ip EXIT;
    trap 'exit 130' INT TERM HUP;
    for candidate in "${candidates[@]}";
    do
        test "$candidate" = "$current" && continue;
        test_ip="$candidate";
        cleanup_test_ip || { 
            test_ip="";
            continue
        };
        if ! fail2ban-client set "$E121_F2B_JAIL_NAME" banip "$candidate" > /dev/null 2>&1; then
            cleanup_test_ip || true;
            test_ip="";
            continue;
        fi;
        plane_ticket=0;
        plane_nft=0;
        for i in {1..60};
        do
            _e159_f2b_banned_state "$candidate" 1 && plane_ticket=1 || true;
            _e159_nft_has_element "$candidate" && plane_nft=1 || true;
            test "$plane_ticket" -eq 1 && test "$plane_nft" -eq 1 && break;
            sleep 0.2;
        done;
        test "$plane_ticket" -eq 1 && test "$plane_nft" -eq 1 && break;
        cleanup_test_ip || true;
        test_ip="";
    done;
    if test -z "$test_ip" || test "$plane_ticket" -ne 1 || test "$plane_nft" -ne 1; then
        _e159_f2b_diag fail "$family:ticket=$plane_ticket,nft=$plane_nft,no-converged-test-address" none;
        return 1;
    fi;
    if cleanup_test_ip; then
        cleanup_ok=1;
    fi;
    if test "$cleanup_ok" -ne 1; then
        _e159_f2b_diag fail "$family:ticket=1,nft=1,cleanup=0" "$test_ip";
        return 1;
    fi;
    _e159_f2b_diag pass "$family:ticket=1,nft=1,cleanup=1" "$test_ip";
    test_ip="";
    return 0 )
}
