# EEX3-FUNCTION network_e159_164 _e159_forwarding_conflict
_e159_forwarding_conflict() {
    local svc current_forward=0 all_forward=0 enabled=0 mode=disabled;
    if declare -F _e138_state_get > /dev/null 2>&1; then
        enabled=$(_e138_state_get route_enabled 0);
        mode=$(_e138_state_get route_mode disabled);
    fi;
    test "$enabled" = 1 && test "$mode" = host-full && info '检测到Cloudflare host-full：保留原IPv4回程，允许E127的ip_forward=0。';
    for svc in docker.service podman.service containerd.service kubelet.service k3s.service k3s-agent.service rke2-server.service rke2-agent.service libvirtd.service virtqemud.service lxd.service incus.service tailscaled.service zerotier-one.service;
    do
        if systemctl is-active --quiet "$svc" 2> /dev/null; then
            test "${E159_ALLOW_FORWARDING_OFF:-0}" = 1 || { 
                error "检测到$svc运行；E127完整参数的ip_forward=0可能中断容器/虚拟网络。";
                error '确认不需要内核转发后，使用E159_ALLOW_FORWARDING_OFF=1显式执行。';
                return 1
            };
        fi;
    done;
    current_forward=$(sysctl -n net.ipv4.ip_forward 2> /dev/null || echo 0);
    all_forward=$(sysctl -n net.ipv4.conf.all.forwarding 2> /dev/null || echo 0);
    if { 
        test "$current_forward" = 1 || test "$all_forward" = 1
    } && test "${E159_ALLOW_FORWARDING_OFF:-0}" != 1; then
        error "当前主机正在进行IPv4内核转发（ip_forward=$current_forward/all.forwarding=$all_forward）。";
        error 'E127完整参数要求二者为0；确认本机不是路由器/NAT后再显式覆盖。';
        return 1;
    fi
}
# EEX3-FUNCTION network_e159_164 _e159_full_spec
_e159_full_spec() {
    local qdisc="${1:-fq}" new_scale="${2:-1}" new_app="${3:-31}" out="${4:--}";
    [[ "$qdisc" =~ ^(fq|fq_codel|cake)$ ]] || { 
        error "qdisc仅允许 fq/fq_codel/cake。";
        return 1
    };
    [[ "$new_scale" =~ ^-?[0-9]+$ ]] && (( new_scale >= -31 && new_scale <= 31 )) || { 
        error "tcp_adv_win_scale必须在-31~31。";
        return 1
    };
    [[ "$new_app" =~ ^[0-9]+$ ]] && (( new_app >= 0 && new_app <= 31 )) || { 
        error "tcp_app_win必须在0~31。";
        return 1
    };
    { 
        echo "# Managed exclusively by ex199e159";
        echo "# Requested entries: 127 = 125 persistent controls + 1 write trigger + 1 semantic alias";
        echo "# qdisc=$qdisc; adv_win_scale=$new_scale; app_win=$new_app";
        echo "# Unsupported/removed kernel keys are retained in the requested specification";
        echo "# and commented in the effective /etc/sysctl.d file instead of being silently lost.";
        cat <<EOF_E159_SPEC
net.core.default_qdisc = ${qdisc}
net.ipv4.tcp_congestion_control = bbr
net.ipv4.neigh.default.base_reachable_time_ms = 60000
net.ipv4.neigh.default.mcast_solicit = 2
net.ipv4.neigh.default.retrans_time_ms = 500
net.ipv4.conf.all.rp_filter = 0
net.ipv4.conf.default.rp_filter = 0
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_ecn = 0
