# EEX3-FUNCTION network_e159_164 _e159_hot_step
_e159_hot_step() {
    local phase="$1";
    shift;
    _e159_phase_log "$E182_HOT_LOG" "$phase" begin;
    if "$@"; then
        _e159_phase_log "$E182_HOT_LOG" "$phase" ok;
        return 0;
    fi;
    _e159_phase_log "$E182_HOT_LOG" "$phase" fail;
    error "E182热更新失败阶段：$phase";
    return 1
}
# EEX3-FUNCTION network_e159_164 _e159_hot_update
_e159_hot_update() {
    ( local protect="" sysbackup="" network_tx="" rc=0 rollback_rc=0 was_active=0;
    local enabled=0 mode=disabled profile=disabled phase=start;
    local effective_active=0 effective_persistent=0 unsupported=0 shadowed=0 trigger=0;
    _e214_ensure_run_lock || return 1;
    exec 153> /run/lock/xray-e159-hot-update.lock;
    flock -n 153 || { 
        error "已有另一个E159热更新正在运行。";
        return 1
    };
    : > "$E159_HOT_LOG" || return 1;
    E135_NEW_PACKAGES=();
    _e159_phase_log "$E159_HOT_LOG" start begin "$SCRIPT_PATH";
    _e159_prepare || return 1;
    phase=xray-snapshot;
    protect=$(_e116_backup_state before_hot_update_e159) || rc=1;
    test "$rc" -ne 0 || _e118_save_core_payload "$protect" || rc=1;
    if test "$rc" -eq 0; then
        was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
        was_active=${was_active:-0};
        _e159_phase_log "$E159_HOT_LOG" "$phase" ok "$protect";
    fi;
    if test "$rc" -eq 0; then
        phase=system-snapshot;
        sysbackup=$(_e159_new_tx hot-update) || rc=1;
        test "$rc" -ne 0 || _e140_system_snapshot "$sysbackup" || rc=1;
        test "$rc" -ne 0 || _e159_phase_log "$E159_HOT_LOG" "$phase" ok "$sysbackup";
    fi;
    test "$rc" -ne 0 || _e159_hot_step warp-state-migrate _e138_warp_migrate_state || rc=1;
    if test "$rc" -eq 0; then
        enabled=$(_e138_state_get route_enabled 0);
        mode=$(_e138_state_get route_mode disabled);
        profile=$(_e138_state_get profile disabled);
    fi;
    test "$rc" -ne 0 || _e159_hot_step runtime-tools _e135_require_runtime_tools || rc=1;
    test "$rc" -ne 0 || _e159_hot_step disable-legacy _e135_disable_legacy_optimizers || rc=1;
    test "$rc" -ne 0 || _e159_hot_step self-install _e159_install_self || rc=1;
    test "$rc" -ne 0 || _e159_hot_step dat-install install_update_dat || rc=1;
    test "$rc" -ne 0 || _e159_hot_step dat-timer systemctl enable --now xray-dat-update.timer || rc=1;
    test "$rc" -ne 0 || _e159_hot_step core-auto-update-off _e105_disable_xray_core_auto_update || rc=1;
    test "$rc" -ne 0 || _e159_hot_step init-window _e137_apply_init_window_default30 || rc=1;
    if test "$rc" -eq 0; then
        E159_DEFER_HOST_FULL_VERIFY=1;
        _e159_hot_step network-source127-controls125 _e159_network_apply fq 1 31 force || rc=1;
        unset E159_DEFER_HOST_FULL_VERIFY;
        test "$rc" -ne 0 || network_tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" | tail -n1);
    fi;
    test "$rc" -ne 0 || _e159_hot_step host-safe-migrate _e159_migrate_host_safe || rc=1;
    test "$rc" -ne 0 || _e159_hot_step log-retention _e121_install_log_retention || rc=1;
    test "$rc" -ne 0 || _e159_hot_step ssh-guard _e141_install_ssh_guard || rc=1;
    test "$rc" -ne 0 || _e159_hot_step xray-limits fix_xray_systemd_limits || rc=1;
    if test "$rc" -eq 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e159_hot_step warp-full-units _e140_full_install_units || rc=1;
            test "$rc" -ne 0 || _e159_hot_step warp-full-reconcile _e140_warp_full_reconcile || rc=1;
        else
            _e159_hot_step warp-proxy _e137_warp_connect_local_proxy || rc=1;
            test "$rc" -ne 0 || _e159_hot_step warp-xray _e138_xray_apply_warp "$mode" "$profile" true || rc=1;
            test "$rc" -ne 0 || _e159_hot_step warp-health _e138_warp_health_install || rc=1;
        fi;
    fi;
    test "$rc" -ne 0 || _e159_hot_step version-write _e159_write_version || rc=1;
    if test "$rc" -eq 0; then
        phase=verify;
        _e159_phase_log "$E159_HOT_LOG" "$phase" begin;
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1 || rc=1;
        test "$rc" -ne 0 || test ! -s "$CONFIG" || _e118_xray_test_config "$CONFIG" 1 || rc=1;
        if test "$rc" -eq 0 && test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
            test "$rc" -ne 0 || _e131_verify_nice_runtime || rc=1;
        else
            if test "$rc" -eq 0 && systemctl is-active --quiet xray.service 2> /dev/null; then
                error "热更新意外启动了原本停止的Xray服务。";
                rc=1;
            fi;
        fi;
        test "$rc" -ne 0 || _e159_network_verify_effective || rc=1;
        test "$rc" -ne 0 || _e159_network_verify_ownership || rc=1;
        test "$rc" -ne 0 || _e159_ssh_guard_verify_final || rc=1;
        test "$rc" -ne 0 || grep -qx 'net.ipv4.tcp_notsent_lowat = 16384' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || grep -qx 'net.core.busy_poll = 50' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || _e159_verify_neighbor_queue_semantics || rc=1;
        test "$rc" -ne 0 || ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
        test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
        for unit in xray-dat-update.timer xray-log-retention-e121.timer xray-ssh-auth-audit-e152.timer xray-network-e159.timer;
        do
            test "$rc" -ne 0 || systemctl is-enabled --quiet "$unit" 2> /dev/null || rc=1;
            test "$rc" -ne 0 || systemctl is-active --quiet "$unit" 2> /dev/null || rc=1;
        done;
        test "$rc" -ne 0 || systemctl is-enabled --quiet xray-network-e159.service 2> /dev/null || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$SYMLINK" || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E159_SELF_PATH" || rc=1;
        test "$rc" -eq 0 && _e159_phase_log "$E159_HOT_LOG" "$phase" ok || _e159_phase_log "$E159_HOT_LOG" "$phase" fail;
    fi;
    if test "$rc" -ne 0; then
        error "E159热更新失败，开始总回滚；阶段日志：$E159_HOT_LOG";
        test -z "$network_tx" || _e159_network_restore "$network_tx" || rollback_rc=1;
        test -z "$sysbackup" || _e140_system_restore "$sysbackup" || rollback_rc=1;
        test -z "$protect" || _e118_restore_core_payload "$protect" > /dev/null 2>&1 || rollback_rc=1;
        test -z "$protect" || _e118_restore_state "$protect" > /dev/null 2>&1 || rollback_rc=1;
        _e135_remove_new_runtime_tools || true;
        if test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 > /dev/null 2>&1 || rollback_rc=1;
        fi;
        if test "$rollback_rc" -ne 0; then
            { 
                echo "time=$(date -Is 2> /dev/null || date)";
                echo "operation=hot-update";
                echo "system_backup=${sysbackup:-none}";
                echo "network_backup=${network_tx:-none}";
                echo "core_backup=${protect:-none}";
                echo "log=$E159_HOT_LOG"
            } > "$E159_CRITICAL_MARKER" 2> /dev/null || true;
            error "严重：E159回滚未通过复检。";
        fi;
        _e159_phase_log "$E159_HOT_LOG" finish fail "rollback=$rollback_rc";
        return 1;
    fi;
    rm -f "$E159_CRITICAL_MARKER" 2> /dev/null || true;
    _e142_prune_transactions "$sysbackup" "$protect" || warn "旧事务快照收敛未完成。";
    _e127_prune_core_payload_backups;
    _e159_prune_system_tx "$sysbackup";
    _e152_cleanup_legacy_e143_units || true;
    _e159_phase_log "$E159_HOT_LOG" finish ok;
    effective_active=$(sed -n 's/^effective_active=//p' "$E159_NETWORK_STATE" | tail -n1);
    effective_persistent=$(sed -n 's/^effective_persistent=//p' "$E159_NETWORK_STATE" | tail -n1);
    unsupported=$(sed -n 's/^unsupported=//p' "$E159_NETWORK_STATE" | tail -n1);
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$E159_NETWORK_STATE" | tail -n1);
    trigger=$(sed -n 's/^write_trigger=//p' "$E159_NETWORK_STATE" | tail -n1);
    info "V199e159热更新完成：127条请求（persistent=$effective_persistent，trigger=$trigger，unsupported=$unsupported，shadowed_alias=$shadowed，effective_assignments=$effective_active）、init30、3天日志、SSH守护和Xray运行态均已验证。";
    info "系统快照：$sysbackup";
    info "网络快照：$network_tx";
    info "阶段日志：$E159_HOT_LOG" )
}
# EEX3-FUNCTION network_e159_164 _e159_hot_update_preflight
_e159_hot_update_preflight() {
    _e152_hot_update_preflight || return 1;
    _e159_prepare || return 1;
    for c in modprobe tc cut wc uniq head tail;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "E159预检缺少命令：$c";
            return 1
        };
    done;
    _e159_forwarding_conflict || return 1
}
# EEX3-FUNCTION network_e159_164 _e159_install_fail2ban_guard_verified_base
_e159_install_fail2ban_guard_verified_base() {
    local backend;
    backend=$(_e152_firewall_backend 2> /dev/null || echo none);
    if test "$backend" = nft; then
        systemctl stop fail2ban.service > /dev/null 2>&1 || true;
        systemctl is-active --quiet fail2ban.service 2> /dev/null && { 
            error "无法停止Fail2ban以清理E159残留事务表。";
            return 1
        };
        nft delete table inet "$E159_NFT_F2B_TABLE" > /dev/null 2>&1 || true;
        nft list table inet "$E159_NFT_F2B_TABLE" > /dev/null 2>&1 && { 
            error "无法清理残留的$E159_NFT_F2B_TABLE。";
            return 1
        } || true;
    fi;
    _e159_fail2ban_guard_base || return 1;
    if test "$backend" = nft; then
        _e159_f2b_action_contract && _e159_nft_table_contract || return 1;
        nft delete table inet "$E152_NFT_F2B_TABLE" > /dev/null 2>&1 || true;
        nft list table inet "$E152_NFT_F2B_TABLE" > /dev/null 2>&1 && { 
            error "旧$E152_NFT_F2B_TABLE仍残留，拒绝留下双重SSH封禁所有者。";
            return 1
        } || true;
    fi
}
# EEX3-FUNCTION network_e159_164 _e159_install_host_safe
_e159_install_host_safe() {
    ( local mode="${1:-all}" tx p id unit enabled active failed=0 rollback=0;
    local -a paths=("$E159_HOST_STATE" "$E159_HOST_SCRIPT" "$E159_HOST_SERVICE" "$E159_LEGACY_E156_HOST_STATE" "$E159_LEGACY_E156_HOST_SCRIPT" "$E159_LEGACY_E156_HOST_SERVICE" "$E159_LEGACY_E154_HOST_STATE" "$E159_LEGACY_E154_HOST_SCRIPT" "$E159_LEGACY_E154_HOST_SERVICE");
    _e159_prepare || return 1;
    tx=$(_e159_new_tx host-safe) || return 1;
    install -d -m 0700 "$tx/host-files" || return 1;
    for p in "${paths[@]}";
    do
        id=$(printf '%s' "$p" | sha256sum | awk '{print $1}');
        printf '%s|%s\n' "$p" "$id" >> "$tx/host-paths.tsv" || return 1;
        _e135_snapshot_file "$p" "$tx/host-files/$id" || return 1;
    done;
    { 
        _e159_snapshot_service xray-host-safe-e159.service || return 1;
        _e159_snapshot_service xray-host-safe-e156.service || return 1;
        _e159_snapshot_service xray-host-safe-e154.service || return 1
    } > "$tx/host-services.before" || return 1;
    ( cd "$tx" && find host-files host-paths.tsv host-services.before -type f -print0 | sort -z | xargs -0 sha256sum > host-seal.sha256 ) || return 1;
    _e159_install_host_safe_impl "$mode" || failed=1;
    if test "$failed" -eq 0; then
        _e159_prune_system_tx "$tx";
        return 0;
    fi;
    error "E159 host-safe安装失败，恢复E159/E154文件与服务状态。";
    ( cd "$tx" && sha256sum -c host-seal.sha256 > /dev/null 2>&1 ) || { 
        error "host-safe回滚快照校验失败：$tx";
        return 1
    };
    systemctl disable --now xray-host-safe-e159.service > /dev/null 2>&1 || true;
    while IFS='|' read -r p id; do
        _e135_restore_file "$p" "$tx/host-files/$id" || rollback=1;
    done < "$tx/host-paths.tsv";
    systemctl daemon-reload > /dev/null 2>&1 || rollback=1;
    while IFS='|' read -r unit enabled active; do
        _e159_restore_service "$unit" "$enabled" "$active" || rollback=1;
    done < "$tx/host-services.before";
    test "$rollback" -eq 0 || error "host-safe回滚未完整通过：$tx";
    return 1 )
}
# EEX3-FUNCTION network_e159_164 _e159_install_host_safe_impl
_e159_install_host_safe_impl() {
    local mode="${1:-all}" script service state previous="$E159_HOST_STATE" thp=0 cpu=0;
    test -s "$previous" || previous="$E159_LEGACY_E156_HOST_STATE";
    test -s "$previous" || previous="$E159_LEGACY_E154_HOST_STATE";
    case "$mode" in 
        all)
            thp=1;
            cpu=1
        ;;
        thp)
            thp=1;
            cpu=$(sed -n 's/^cpu=//p' "$previous" 2> /dev/null | tail -n1);
            cpu=${cpu:-0}
        ;;
        cpu)
            cpu=1;
            thp=$(sed -n 's/^thp=//p' "$previous" 2> /dev/null | tail -n1);
            thp=${thp:-0}
        ;;
        migrate)
            thp=$(sed -n 's/^thp=//p' "$previous" 2> /dev/null | tail -n1);
            thp=${thp:-0};
            cpu=$(sed -n 's/^cpu=//p' "$previous" 2> /dev/null | tail -n1);
            cpu=${cpu:-0}
        ;;
        *)
            return 1
        ;;
    esac;
    [[ "$thp" =~ ^[01]$ && "$cpu" =~ ^[01]$ ]] || { 
        error "host-safe状态损坏：thp=$thp cpu=$cpu";
        return 1
    };
    script=$(_e118_mktemp e159-host-safe.sh) || return 1;
    service=$(_e118_mktemp e159-host-safe.service) || return 1;
    state=$(_e118_mktemp e159-host-safe.env) || return 1;
    printf 'thp=%s\ncpu=%s\n' "$thp" "$cpu" > "$state" || return 1;
    cat > "$script" <<'EOF_E159_HOST'
#!/usr/bin/env bash
set -u
STATE=/usr/local/etc/xray/e159/host-safe.env
thp=$(sed -n 's/^thp=//p' "$STATE" 2>/dev/null | tail -n1); thp=${thp:-0}
cpu=$(sed -n 's/^cpu=//p' "$STATE" 2>/dev/null | tail -n1); cpu=${cpu:-0}
if test "$thp" = 1; then
    for f in /sys/kernel/mm/transparent_hugepage/enabled /sys/kernel/mm/transparent_hugepage/defrag; do
        test -w "$f" && printf 'never\n' >"$f" 2>/dev/null || true
    done
fi
