# EEX3-FUNCTION network_e159_164 _e159_install_network_assets
_e159_install_network_assets() {
    local script service timer modules qdisc;
    script=$(_e118_mktemp e159-network.sh) || return 1;
    service=$(_e118_mktemp e159-network.service) || return 1;
    timer=$(_e118_mktemp e159-network.timer) || return 1;
    modules=$(_e118_mktemp e159-modules.conf) || return 1;
    qdisc=$(awk -F= '$1 ~ /^[[:space:]]*net.core.default_qdisc[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$E159_EFFECTIVE_CONF");
    [[ "$qdisc" =~ ^(fq|fq_codel|cake)$ ]] || { 
        error "E159有效配置中的qdisc无效。";
        return 1
    };
    printf 'tcp_bbr\nsch_%s\n' "$qdisc" > "$modules" || return 1;
    cat > "$script" <<'EOF_E159_BOOT'
#!/usr/bin/env bash
set -euo pipefail
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
CONF=/etc/sysctl.d/99-xray-e159-full.conf
SEAL=/usr/local/etc/xray/e159/network-files.sha256
LOG=/var/log/xray/e159/network-boot.log
install -d -m 0700 "$(dirname "$LOG")"
: >"$LOG"
if test -e /run/lock || test -L /run/lock; then
    test -d /run/lock && test -x /run/lock || exit 1
else
    install -d -m 0755 /run/lock || exit 1
fi
exec 9>/run/lock/xray-network-e159.lock
flock -w 30 9
test -s "$CONF" && test -s "$SEAL"
sha256sum -c "$SEAL" >>"$LOG" 2>&1
modprobe tcp_bbr >/dev/null 2>&1 || true
qdisc=$(awk -F= '$1 ~ /^[[:space:]]*net.core.default_qdisc[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$CONF")
case "$qdisc" in fq|fq_codel|cake) modprobe "sch_$qdisc" >/dev/null 2>&1 || true ;; *) exit 1 ;; esac
norm() { printf '%s\n' "${1:-}" | awk '{$1=$1;print}'; }
equal() {
  local key="$1" expected actual
  expected=$(norm "$2"); actual=$(norm "$3")
  case "$key" in
    net.ipv4.tcp_recovery) (( expected == actual )) 2>/dev/null ;;
    net.ipv4.tcp_child_ehash_entries)
      test "$expected" = "$actual" || { test "$expected" = 65535 && test "$actual" = 65536; } ;;
    *) test "$expected" = "$actual" ;;
  esac
}
failed=0 changed=0
forward=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.ip_forward[[:space:]]*$/{print $2;exit}' "$CONF" | xargs)
if test -n "$forward" && test "$(sysctl -n net.ipv4.ip_forward 2>/dev/null | xargs)" != "$forward"; then
  sysctl -w "net.ipv4.ip_forward=$forward" >/dev/null 2>&1 || failed=1
  changed=$((changed+1))
fi
while IFS='=' read -r key value; do
  key=$(norm "$key"); value=$(norm "$value")
  case "$key" in ''|'#'*|net.ipv4.ip_forward|net.ipv4.route.flush) continue ;; esac
  path="/proc/sys/${key//./\/}"
  if test ! -w "$path"; then
    printf '%s unsupported %s\n' "$(date -Is)" "$key" >>"$LOG"
    failed=1
    continue
  fi
  actual=$(sysctl -n "$key" 2>/dev/null || true)
  if ! equal "$key" "$value" "$actual"; then
    if sysctl -w "$key=$value" >/dev/null 2>&1; then changed=$((changed+1)); else failed=1; continue; fi
  fi
  actual=$(sysctl -n "$key" 2>/dev/null || true)
  equal "$key" "$value" "$actual" || failed=1
done <"$CONF"
printf '%s changed=%s failed=%s\n' "$(date -Is)" "$changed" "$failed" >>"$LOG"
test "$failed" -eq 0
EOF_E159_BOOT

    cat > "$service" <<EOF_E159_SERVICE
[Unit]
Description=V199e159 127-request / 125-persistent-control network verification
After=systemd-sysctl.service network-online.target
Wants=network-online.target
Before=xray.service

[Service]
Type=oneshot
ExecStart=$E159_NETWORK_SCRIPT
TimeoutStartSec=90

[Install]
WantedBy=multi-user.target
EOF_E159_SERVICE

    cat > "$timer" <<'EOF_E159_TIMER'
[Unit]
Description=V199e159 network drift verification

[Timer]
# OnActiveSec avoids an immediate elapsed-OnBootSec trigger while the install
# transaction is still committing.  The separately enabled service still runs
# during normal boot before xray.service.
OnActiveSec=2min
OnUnitInactiveSec=15min
AccuracySec=1min
Persistent=true
Unit=xray-network-e159.service

[Install]
WantedBy=timers.target
EOF_E159_TIMER

    bash -n "$script" || return 1;
    _e121_atomic_install "$script" "$E159_NETWORK_SCRIPT" 0755 || return 1;
    _e121_atomic_install "$service" "$E159_NETWORK_SERVICE" 0644 || return 1;
    _e121_atomic_install "$timer" "$E159_NETWORK_TIMER" 0644 || return 1;
    _e121_atomic_install "$modules" "$E159_MODULES_CONF" 0644 || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl enable xray-network-e159.service xray-network-e159.timer > /dev/null 2>&1 || return 1;
    systemctl start xray-network-e159.timer > /dev/null 2>&1 || return 1;
    systemctl is-enabled --quiet xray-network-e159.service || return 1;
    systemctl is-enabled --quiet xray-network-e159.timer || return 1;
    systemctl is-active --quiet xray-network-e159.timer || return 1
}
