# EEX3-FUNCTION network_e159_164 _e159_kernel_prepare
_e159_kernel_prepare() {
    local qdisc="${1:-fq}" available;
    modprobe tcp_bbr > /dev/null 2>&1 || true;
    available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2> /dev/null || true);
    [[ " $available " == *" bbr "* ]] || { 
        error "当前内核没有注册BBR；E159不会用Cubic冒充你要求的BBR。可用：${available:-none}";
        return 1
    };
    modprobe "sch_${qdisc}" > /dev/null 2>&1 || true;
    test -w "$(_e159_proc_path net.core.default_qdisc)" || { 
        error "当前环境不可写net.core.default_qdisc。";
        return 1
    }
}
# EEX3-FUNCTION network_e159_164 _e159_key_note
_e159_key_note() {
    case "$1" in 
        net.ipv4.ipfrag_low_thresh)
            echo 'obsolete-since-linux-4.17'
        ;;
        net.ipv4.tcp_adv_win_scale)
            echo 'obsolete-noop-since-linux-6.6'
        ;;
        net.ipv4.tcp_child_ehash_entries)
            echo 'kernel-rounds-nonzero-value-up-to-power-of-two'
        ;;
        net.ipv4.route.flush)
            echo 'write-only-trigger'
        ;;
        net.ipv4.neigh.default.unres_qlen)
            echo 'deprecated-packet-view-shared-with-unres_qlen_bytes'
        ;;
        net.ipv4.neigh.default.unres_qlen_bytes)
            echo 'authoritative-unresolved-neighbour-queue-byte-limit'
        ;;
        net.core.busy_poll)
            echo 'cpu-cost-and-application-dependent'
        ;;
        net.ipv4.tcp_notsent_lowat)
            echo 'aggressive-low-latency-16KiB'
        ;;
        net.ipv4.ip_forward | net.ipv4.conf.all.forwarding)
            echo 'breaks-router-container-host-full-warp'
        ;;
        net.ipv4.tcp_retries2 | net.ipv4.tcp_syn_retries | net.ipv4.tcp_synack_retries)
            echo 'aggressive-failure-timeout'
        ;;
        net.core.rmem_default | net.core.wmem_default | net.ipv4.tcp_rmem | net.ipv4.tcp_wmem)
            echo 'large-per-socket-default-memory'
        ;;
        kernel.sysrq)
            echo 'security-sensitive-sysrq-enabled'
        ;;
        *)
            echo 'requested'
        ;;
    esac
}
