# EEX3-FUNCTION network_e159_164 _e159_legacy_sysctl_owned
_e159_legacy_sysctl_owned() {
    local f="$1" count;
    case "$f" in 
        /etc/sysctl.d/98-xray-core-tuning.conf | /etc/sysctl.d/99-xray-hotupdate-fast.conf | /etc/sysctl.d/99-xray-pmtu-e106.conf | /etc/sysctl.d/99-xray-pmtu-e107.conf | /etc/sysctl.d/99-auto-tune-relay-e108.conf | /etc/sysctl.d/99-auto-tune-relay-e109.conf | /etc/sysctl.d/98-xray-swap.conf)
            return 0
        ;;
        /etc/sysctl.d/99-network-optimized.conf)
            test -s "$f" || return 1;
            grep -Eq '^# Xray / VPS Network Optimized Sysctl Profile([[:space:]]|$)' "$f" && return 0;
            count=$(_e159_active_keys "$f" | wc -l | tr -d ' ');
            test "$count" -ge 100 || return 1;
            grep -Eq '^net\.core\.rmem_max[[:space:]]*=[[:space:]]*97108868([[:space:]]*)$' "$f" || return 1;
            grep -Eq '^net\.unix\.max_dgram_qlen[[:space:]]*=[[:space:]]*130000([[:space:]]*)$' "$f" || return 1;
            grep -Eq '^net\.ipv4\.tcp_pacing_ss_ratio[[:space:]]*=[[:space:]]*210([[:space:]]*)$' "$f" || return 1;
            return 0
        ;;
        *)
            return 1
        ;;
    esac
}
