# EEX3-FUNCTION network_e159_164 _e159_micro28_restore
_e159_micro28_restore() {
    local protect="$1" sysbackup="$2" network_before="${3:-}" network_tx="" rc=0;
    network_tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2> /dev/null | tail -n1);
    if test -n "$network_tx" && test "$network_tx" != "$network_before"; then
        _e159_network_restore "$network_tx" || rc=1;
    fi;
    _e140_system_restore "$sysbackup" || rc=1;
    _e118_restore_core_payload "$protect" > /dev/null 2>&1 || rc=1;
    _e118_restore_state "$protect" > /dev/null 2>&1 || rc=1;
    test "$rc" -eq 0 || error "第28项完整回滚失败：system=$sysbackup xray=$protect";
    return "$rc"
}
# EEX3-FUNCTION network_e159_164 _e159_migrate_host_safe
_e159_migrate_host_safe() {
    local old_enabled;
    if test -s "$E159_LEGACY_E156_HOST_STATE"; then
        _e159_install_host_safe migrate;
        return;
    fi;
    if test -s "$E159_LEGACY_E154_HOST_STATE"; then
        _e159_install_host_safe migrate;
        return;
    fi;
    old_enabled="$(systemctl is-enabled xray-host-safe-e156.service 2> /dev/null || true) $(systemctl is-enabled xray-host-safe-e154.service 2> /dev/null || true)";
    if test -e "$E159_LEGACY_E156_HOST_SCRIPT" || test -e "$E159_LEGACY_E156_HOST_SERVICE" || test -e "$E159_LEGACY_E154_HOST_SCRIPT" || test -e "$E159_LEGACY_E154_HOST_SERVICE" || [[ "$old_enabled" =~ (enabled|enabled-runtime|linked|linked-runtime) ]]; then
        warn "旧E154/E156 host-safe缺少可验证状态；停用孤立单元，不猜测THP/CPU策略。";
        systemctl disable --now xray-host-safe-e156.service xray-host-safe-e154.service > /dev/null 2>&1 || true;
        rm -f -- "$E159_LEGACY_E156_HOST_SCRIPT" "$E159_LEGACY_E156_HOST_SERVICE" "$E159_LEGACY_E154_HOST_SCRIPT" "$E159_LEGACY_E154_HOST_SERVICE" 2> /dev/null || return 1;
        systemctl daemon-reload > /dev/null 2>&1 || return 1;
    fi
}
