# EEX3-FUNCTION network_e159_164 _e159_network_apply_exact_base
_e159_network_apply_exact_base() {
    ( local qdisc="${1:-fq}" scale="${2:-1}" app="${3:-31}" confirm="${4:-}";
    local requested effective report tx tmp seal_tmp failed=0 legacy_ipv6=0;
    local supported unsupported shadowed trigger effective_active effective_persistent;
    local origin_backup="";
    _e159_prepare || return 1;
    exec 154> /run/lock/xray-network-e159.lock;
    flock -w 90 154 || { 
        error "另一个E159网络事务/开机复检占用锁超过90秒。";
        return 1
    };
    _e159_forwarding_conflict || return 1;
    _e159_kernel_prepare "$qdisc" || return 1;
    requested=$(_e118_mktemp e159-requested.conf) || return 1;
    effective=$(_e118_mktemp e159-effective.conf) || return 1;
    report=$(_e118_mktemp e159-compat.tsv) || return 1;
    _e159_full_spec "$qdisc" "$scale" "$app" "$requested" || return 1;
    _e159_spec_validate "$requested" || return 1;
    _e159_build_effective "$requested" "$effective" "$report" || return 1;
    _e159_network_artifacts_validate "$requested" "$effective" "$report" || return 1;
    if test "$confirm" != force; then
        warn "将事务应用完整参数集：127条请求/125个持久控制，BBR/$qdisc、7990577/97108868、busy_poll=50、notsent=16384。";
        warn "其中ip_forward=0、激进重试、16KiB notsent和大默认缓冲会影响整台VPS。";
        read -rp "输入 APPLY-FULL-125 确认: " confirm || true;
        test "$confirm" = APPLY-FULL-125 || { 
            info "已取消。";
            return 0
        };
    fi;
    grep -RqsE '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=[[:space:]]*1' "$E152_NETWORK_CONF" /etc/sysctl.d/99-xray-e1*-network.conf 2> /dev/null && legacy_ipv6=1 || true;
    origin_backup=$(sed -n 's/^origin_backup=//p' "$E159_NETWORK_STATE" 2> /dev/null | tail -n1);
    test -n "$origin_backup" || origin_backup=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2> /dev/null | tail -n1);
    if test -z "$origin_backup" && test -s "$E159_LEGACY_E156_STATE"; then
        origin_backup=$(sed -n 's/^origin_backup=//p' "$E159_LEGACY_E156_STATE" 2> /dev/null | tail -n1);
        test -n "$origin_backup" || origin_backup=$(sed -n 's/^backup=//p' "$E159_LEGACY_E156_STATE" 2> /dev/null | tail -n1);
    fi;
    if test -z "$origin_backup" && test -s "$E159_LEGACY_E154_STATE"; then
        origin_backup=$(sed -n 's/^origin_backup=//p' "$E159_LEGACY_E154_STATE" 2> /dev/null | tail -n1);
        test -n "$origin_backup" || origin_backup=$(sed -n 's/^backup=//p' "$E159_LEGACY_E154_STATE" 2> /dev/null | tail -n1);
    fi;
    if test -n "$origin_backup" && ! _e159_network_tx_verify "$origin_backup"; then
        warn "旧origin_backup无效；本次事务将建立新的可验证起点。";
        origin_backup="";
    fi;
    tx=$(_e159_network_tx_new) || return 1;
    _e159_network_snapshot "$tx" "$requested" || return 1;
    test -n "$origin_backup" || origin_backup="$tx";
    _e159_disable_old_network_layers || failed=1;
    test "$failed" -ne 0 || _e121_atomic_install "$requested" "$E159_REQUESTED_CONF" 0600 || failed=1;
    test "$failed" -ne 0 || _e121_atomic_install "$effective" "$E159_EFFECTIVE_CONF" 0644 || failed=1;
    test "$failed" -ne 0 || _e121_atomic_install "$report" "$E159_NETWORK_REPORT" 0600 || failed=1;
    test "$failed" -ne 0 || _e159_network_artifacts_validate "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" || failed=1;
    if test "$failed" -eq 0; then
        seal_tmp=$(_e118_mktemp e159-network-seal) || failed=1;
    fi;
    if test "$failed" -eq 0; then
        sha256sum "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" > "$seal_tmp" || failed=1;
        test "$failed" -ne 0 || _e121_atomic_install "$seal_tmp" "$E159_NETWORK_SEAL" 0600 || failed=1;
        test "$failed" -ne 0 || sha256sum -c "$E159_NETWORK_SEAL" > /dev/null 2>&1 || failed=1;
    fi;
    test "$failed" -ne 0 || _e159_apply_runtime "$E159_EFFECTIVE_CONF" || failed=1;
    test "$failed" -ne 0 || _e159_install_network_assets || failed=1;
    test "$failed" -ne 0 || _e159_network_verify_ownership || failed=1;
    test "$failed" -ne 0 || _e159_restore_ipv6_if_e152_owned "$legacy_ipv6" || failed=1;
    if test "$failed" -eq 0; then
        supported=$(awk -F'\t' 'NR>1 && $2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
        unsupported=$(awk -F'\t' 'NR>1 && $2=="unsupported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
        shadowed=$(awk -F'\t' 'NR>1 && $2=="shadowed-alias"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
        trigger=$(awk -F'\t' 'NR>1 && $1=="net.ipv4.route.flush" && $2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
        effective_active=$(_e159_active_keys "$E159_EFFECTIVE_CONF" | wc -l | tr -d ' ');
        effective_persistent=$((effective_active-trigger));
        test "$effective_active" -eq "$supported" && test $((supported+unsupported+shadowed)) -eq 127 && test "$effective_persistent" -ge 0 || failed=1;
    fi;
    if test "$failed" -eq 0; then
        tmp="$E159_NETWORK_STATE.tmp.$$";
        { 
            echo "version=199e159";
            echo "profile=full125-persistent/source127";
            echo "qdisc=$qdisc";
            echo "tcp_adv_win_scale=$scale";
            echo "tcp_app_win=$app";
            echo "requested_entries=127";
            echo "logical_controls=125";
            echo "effective_active=$effective_active";
            echo "effective_persistent=$effective_persistent";
            echo "supported=$supported";
            echo "unsupported=$unsupported";
            echo "shadowed_alias=$shadowed";
            echo "write_trigger=$trigger";
            echo "ipv6_policy=preserve";
            echo "backup=$tx";
            echo "origin_backup=$origin_backup";
            echo "applied=$(date -Is 2> /dev/null || date)"
        } > "$tmp" && chmod 0600 "$tmp" && mv -f "$tmp" "$E159_NETWORK_STATE" || failed=1;
    fi;
    test "$failed" -ne 0 || _e159_network_state_validate "$E159_NETWORK_STATE" || failed=1;
    if test "$failed" -ne 0; then
        error "E159完整网络事务失败，正在恢复全部运行值、文件和服务状态。";
        _e159_network_restore "$tx" || error "严重：E159网络回滚未完整通过。快照：$tx";
        return 1;
    fi;
    _e159_prune_network_tx;
    info "完整参数集已事务提交：127条请求 = persistent=$effective_persistent + trigger=$trigger + unsupported=$unsupported + shadowed_alias=$shadowed；effective_assignments=$effective_active，IPv6=保留。";
    info "请求规格：$E159_REQUESTED_CONF";
    info "有效配置：$E159_EFFECTIVE_CONF";
    info "兼容报告：$E159_NETWORK_REPORT";
    info "回滚快照：$tx" )
}
# EEX3-FUNCTION network_e159_164 _e159_network_artifacts_validate
_e159_network_artifacts_validate() {
    ( local requested="$1" effective="$2" report="$3";
    local work;
    local req_keys rep_keys sup_keys eff_keys req_values rep_values eff_values sup_values;
    local requested_count requested_unique report_count report_unique;
    local supported unsupported shadowed status_total effective_count effective_unique bad;
    test -s "$requested" && test -s "$effective" && test -s "$report" || { 
        error "E159网络产物缺失或为空。";
        return 1
    };
    work=$(mktemp -d /tmp/e159-artifacts.XXXXXX) || return 1;
    trap 'rm -rf -- "$work"' EXIT;
    req_keys="$work/requested.keys";
    rep_keys="$work/report.keys";
    sup_keys="$work/supported.keys";
    eff_keys="$work/effective.keys";
    req_values="$work/requested.values";
    rep_values="$work/report.values";
    eff_values="$work/effective.values";
    sup_values="$work/supported.values";
    _e159_active_keys "$requested" | sort > "$req_keys" || return 1;
    _e159_active_keys "$effective" | sort > "$eff_keys" || return 1;
    awk -F'\t' 'NR>1 && NF{print $1}' "$report" | sort > "$rep_keys" || return 1;
    awk -F'\t' 'NR>1 && $2=="supported"{print $1}' "$report" | sort > "$sup_keys" || return 1;
    requested_count=$(wc -l < "$req_keys" | tr -d ' ');
    requested_unique=$(uniq "$req_keys" | wc -l | tr -d ' ');
    report_count=$(wc -l < "$rep_keys" | tr -d ' ');
    report_unique=$(uniq "$rep_keys" | wc -l | tr -d ' ');
    effective_count=$(wc -l < "$eff_keys" | tr -d ' ');
    effective_unique=$(uniq "$eff_keys" | wc -l | tr -d ' ');
    supported=$(awk -F'\t' 'NR>1 && $2=="supported"{n++}END{print n+0}' "$report");
    unsupported=$(awk -F'\t' 'NR>1 && $2=="unsupported"{n++}END{print n+0}' "$report");
    shadowed=$(awk -F'\t' 'NR>1 && $2=="shadowed-alias"{n++}END{print n+0}' "$report");
    status_total=$((supported+unsupported+shadowed));
    test "$(head -n1 "$report")" = 'key	status	requested	note' || { 
        error "E159兼容报告表头损坏。";
        return 1
    };
    bad=$(awk -F'\t' 'NR>1 && NF && (NF<4 || $1 !~ /^[A-Za-z0-9_.-]+$/ || $2 !~ /^(supported|unsupported|shadowed-alias)$/){print NR;exit}' "$report");
    test -z "$bad" || { 
        error "E159兼容报告第${bad}行结构/状态非法。";
        return 1
    };
    test "$requested_count" -eq 127 && test "$requested_unique" -eq 127 || { 
        error "E159请求集合不变量失败：rows=$requested_count unique=$requested_unique（必须均为127）。";
        return 1
    };
    test "$report_count" -eq 127 && test "$report_unique" -eq 127 && test "$status_total" -eq 127 || { 
        error "E159报告集合不变量失败：rows=$report_count unique=$report_unique status_total=$status_total。";
        return 1
    };
    if ! cmp -s "$req_keys" "$rep_keys"; then
        error "E159兼容报告与请求规格的键集合不一致。";
        comm -3 "$req_keys" "$rep_keys" | head -n 20 | sed 's/^/    /' 1>&2 || true;
        return 1;
    fi;
    test "$effective_count" -eq "$effective_unique" && test "$effective_count" -eq "$supported" || { 
        error "E159有效集合不变量失败：active=$effective_count unique=$effective_unique supported=$supported。";
        return 1
    };
    if ! cmp -s "$eff_keys" "$sup_keys"; then
        error "E159有效配置并非兼容报告中supported集合的精确映射。";
        comm -3 "$eff_keys" "$sup_keys" | head -n 20 | sed 's/^/    /' 1>&2 || true;
        return 1;
    fi;
    awk -F= '
      /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
        k=$1; gsub(/[[:space:]]/,"",k); v=substr($0,index($0,"=")+1)
        gsub(/^[[:space:]]+|[[:space:]]+$/,"",v); gsub(/[[:space:]]+/," ",v)
        print k "\t" v
      }' "$requested" | sort > "$req_values" || return 1;
    awk -F'\t' 'NR>1 && NF{v=$3;gsub(/^[[:space:]]+|[[:space:]]+$/,"",v);gsub(/[[:space:]]+/," ",v);print $1 "\t" v}' "$report" | sort > "$rep_values" || return 1;
    cmp -s "$req_values" "$rep_values" || { 
        error "E159兼容报告中的请求值与127条原始规格不一致。";
        return 1
    };
    awk -F= '
      /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
        k=$1; gsub(/[[:space:]]/,"",k); v=substr($0,index($0,"=")+1)
        gsub(/^[[:space:]]+|[[:space:]]+$/,"",v); gsub(/[[:space:]]+/," ",v)
        print k "\t" v
      }' "$effective" | sort > "$eff_values" || return 1;
    awk -F'\t' 'NR>1 && $2=="supported"{v=$3;gsub(/^[[:space:]]+|[[:space:]]+$/,"",v);gsub(/[[:space:]]+/," ",v);print $1 "\t" v}' "$report" | sort > "$sup_values" || return 1;
    cmp -s "$eff_values" "$sup_values" || { 
        error "E159有效配置的键值与supported报告不一致。";
        return 1
    };
    (( shadowed <= 1 )) || { 
        error "E159共享别名数量异常：$shadowed。";
        return 1
    };
    if test "$shadowed" -eq 1; then
        grep -q '^net.ipv4.neigh.default.unres_qlen	shadowed-alias	' "$report" && grep -q '^net.ipv4.neigh.default.unres_qlen_bytes	supported	' "$report" && ! grep -q '^net.ipv4.neigh.default.unres_qlen$' "$eff_keys" || { 
            error "E159邻居队列共享别名关系不完整。";
            return 1
        };
    fi;
    ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$effective" || { 
        error "E159有效配置意外接管了IPv6 disable策略。";
        return 1
    };
    return 0 )
}
# EEX3-FUNCTION network_e159_164 _e159_network_audit
_e159_network_audit() {
    local rc=0 requested;
    _e159_network_audit_base || rc=$?;
    if test -s "$E159_REQUESTED_CONF"; then
        requested="$E159_REQUESTED_CONF";
    else
        requested=$(_e118_mktemp e159-audit-requested.conf) || return 1;
        _e159_full_spec fq 1 31 "$requested" || return 1;
    fi;
    _e159_all_source_sysctl_audit "$requested";
    return "$rc"
}
# EEX3-FUNCTION network_e159_164 _e159_network_audit_base
_e159_network_audit_base() {
    local requested key value actual status supported=0 unsupported=0 mismatch=0 trigger=0 alias_normalized=0 duplicates=0 f n;
    local bytes_actual;
    local qdisc=fq scale=1 app=31;
    title "V199e159：125个持久控制（127条请求）逐项审计";
    if test -r "$E159_REQUESTED_CONF" && test -s "$E159_REQUESTED_CONF"; then
        requested="$E159_REQUESTED_CONF";
    else
        requested=$(_e118_mktemp e159-audit-requested.conf) || return 1;
        if test -r "$E159_EFFECTIVE_CONF"; then
            qdisc=$(awk -F= '$1 ~ /^[[:space:]]*net.core.default_qdisc[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$E159_EFFECTIVE_CONF");
            qdisc=${qdisc:-fq};
            scale=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.tcp_adv_win_scale[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$E159_EFFECTIVE_CONF");
            scale=${scale:-1};
            app=$(awk -F= '$1 ~ /^[[:space:]]*net.ipv4.tcp_app_win[[:space:]]*$/{gsub(/[[:space:]]/,"",$2);print $2;exit}' "$E159_EFFECTIVE_CONF");
            app=${app:-31};
        fi;
        _e159_full_spec "$qdisc" "$scale" "$app" "$requested" || return 1;
    fi;
    printf '  %-44s %-12s %s\n' 参数 状态 '请求值 -> 运行值';
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key");
        value=$(_e159_norm "$value");
        case "$key" in 
            '' | '#'*)
                continue
            ;;
        esac;
        if test "$key" = net.ipv4.route.flush; then
            status=trigger;
            actual='write-only';
            trigger=$((trigger+1));
        else
            if test "$key" = net.ipv4.neigh.default.unres_qlen && test -e "$(_e159_proc_path net.ipv4.neigh.default.unres_qlen)" && test -e "$(_e159_proc_path net.ipv4.neigh.default.unres_qlen_bytes)"; then
                actual=$(sysctl -n "$key" 2> /dev/null || echo unreadable);
                bytes_actual=$(sysctl -n net.ipv4.neigh.default.unres_qlen_bytes 2> /dev/null || echo unreadable);
                if _e159_unres_alias_equal "$requested" "$(_e159_norm "$actual")" "$(_e159_norm "$bytes_actual")"; then
                    status=alias-bytes;
                    alias_normalized=$((alias_normalized+1));
                else
                    status=MISMATCH;
                    mismatch=$((mismatch+1));
                fi;
            else
                if test ! -e "$(_e159_proc_path "$key")"; then
                    status=unsupported;
                    actual='not-present';
                    unsupported=$((unsupported+1));
                else
                    actual=$(sysctl -n "$key" 2> /dev/null || echo unreadable);
                    if _e159_value_equal "$key" "$value" "$actual"; then
                        if test "$(_e159_norm "$value")" = "$(_e159_norm "$actual")"; then
                            status=ok;
                        else
                            status=normalized;
                        fi;
                        supported=$((supported+1));
                    else
                        status=MISMATCH;
                        mismatch=$((mismatch+1));
                    fi;
                fi;
            fi;
        fi;
        printf '  %-44s %-12s %s -> %s\n' "$key" "$status" "$value" "$(_e159_norm "$actual")";
    done < "$requested";
    while IFS= read -r key; do
        value=0;
        for f in /etc/sysctl.conf /etc/sysctl.d/*.conf;
        do
            test -f "$f" || continue;
            n=$(awk -F= -v wanted="$key" '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);if(k==wanted)n++}END{print n+0}' "$f");
            value=$((value+n));
        done;
        (( value > 1 )) && duplicates=$((duplicates+1)) || true;
    done < <(_e159_active_keys "$requested");
    echo;
    echo "  原始请求: 127；持久独立匹配: $supported；共享别名: $alias_normalized；写触发器: $trigger；不支持: $unsupported；不一致: $mismatch";
    echo "  存在重复持久化定义的参数数: $duplicates（E159服务会以运行态读回为准）";
    echo "  BBR可用: $(sysctl -n net.ipv4.tcp_available_congestion_control 2> /dev/null || echo unknown)";
    echo "  默认qdisc: $(sysctl -n net.core.default_qdisc 2> /dev/null || echo unknown)";
    local iface;
    iface=$(ip route show default 2> /dev/null | awk 'NR==1{print $5}');
    test -z "$iface" || echo "  实际qdisc($iface): $(tc qdisc show dev "$iface" 2> /dev/null | head -n1 || echo unknown)";
    echo "  IPv6禁用项由E159管理: 否（保留系统/用户策略）";
    echo "  开机复检: $(systemctl is-enabled xray-network-e159.timer 2> /dev/null || echo disabled) / $(systemctl is-active xray-network-e159.timer 2> /dev/null || echo inactive)";
    test -r "$E159_NETWORK_STATE" && test -s "$E159_NETWORK_STATE" && sed 's/^/    /' "$E159_NETWORK_STATE" || true;
    test "$mismatch" -eq 0
}
# EEX3-FUNCTION network_e159_164 _e159_network_menu
_e159_network_menu() {
    _e182_network_menu "$@"
}
# EEX3-FUNCTION network_e159_164 _e159_network_paths
_e159_network_paths() {
    local p;
    while IFS= read -r p; do
        case "$p" in 
            "$E159_HOST_STATE" | "$E159_HOST_SCRIPT" | "$E159_HOST_SERVICE" | *host-safe* | *swap* | *zram*)
                continue
            ;;
        esac;
        printf '%s\n' "$p";
    done < <(_eex3_network_paths_legacy)
}
# EEX3-FUNCTION network_e159_164 _e159_network_remove
_e159_network_remove() {
    ( local confirm="${1:-}" origin requested safety rc=0;
    if test "$confirm" != force; then
        warn '将按首次接管前的密封快照恢复完整网络层；恢复成功前不会停用或删除当前所有者。';
        read -rp '输入 REMOVE-E159-NETWORK 确认: ' confirm || true;
        test "$confirm" = REMOVE-E159-NETWORK || return 0;
    fi;
    _e159_prepare || return 1;
    exec 154> /run/lock/xray-network-e159.lock;
    flock -w 90 154 || { 
        error '另一个完整网络事务占用锁超过90秒。';
        return 1
    };
    _e204_network_owner_present || { 
        info '完整网络层当前不存在。';
        return 0
    };
    origin=$(_e204_network_origin 2> /dev/null || true);
    test -n "$origin" && _e204_network_origin_clean "$origin" || { 
        error '首次接管前快照不可验证或不是干净基线；未停止服务、未删除文件。';
        return 1
    };
    requested="$E159_EFFECTIVE_CONF";
    if test ! -s "$requested"; then
        requested=$(_e118_mktemp e204-network-remove-spec) || return 1;
        _e159_full_spec fq 1 31 "$requested" || return 1;
    fi;
    safety=$(_e159_network_tx_new) || return 1;
    _e159_network_snapshot "$safety" "$requested" || return 1;
    _e159_network_tx_verify "$safety" || return 1;
    if ! _eex3_network_restore_scoped "$origin"; then
        error '网络基线恢复未通过，正在恢复移除前的完整网络现场。';
        if ! _eex3_network_restore_scoped "$safety"; then
            _e204_mark_critical network-remove "$safety" 'origin restore and safety restore both failed' || true;
            error "严重：二次恢复也失败；现场快照：$safety";
        fi;
        return 1;
    fi;
    for requested in "$E159_EFFECTIVE_CONF" "$E159_NETWORK_STATE" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER";
    do
        test ! -e "$requested" || rc=1;
    done;
    if test "$rc" -ne 0; then
        error '首次基线读回仍含E159所有者，恢复移除前现场。';
        _eex3_network_restore_scoped "$safety" || _e204_mark_critical network-remove-readback "$safety" 'safety restore failed' || true;
        return 1;
    fi;
    info "完整网络层已恢复到首次接管前状态；移除前安全快照：$safety" )
}
# EEX3-FUNCTION network_e159_164 _e159_network_restore
_e159_network_restore() {
    _eex5_network_restore_checked "$1" _eex5_network_restore_legacy
}
# EEX3-FUNCTION network_e159_164 _e159_network_risk_notes
_e159_network_risk_notes() {
    cat <<'EOF_E159_RISKS'
  原始块的127条请求已完整保留（125个持久控制+1个写触发器+1个共享别名），但并非每项都是“纯加速”：
  - tcp_notsent_lowat=16384：响应优先、排队很低；高RTT大吞吐可能更频繁唤醒应用。
  - rmem/wmem默认7990577、上限97108868：高BDP有余量，也提高大量并发socket的内存压力。
  - tcp_retries2=8、syn_retries=3、synack_retries=2：故障发现更快，极差跨境链路也更早放弃。
  - ip_forward=0/all.forwarding=0：适合纯Xray主机，会与Docker/路由器/host-full WARP冲突。
  - busy_poll=50：只有应用/内核路径使用busy-poll时才可能受益，会增加CPU占用。
  - tcp_adv_win_scale在Linux 6.6+已是no-op；ipfrag_low_thresh自4.17起废弃。
  - tcp_child_ehash_entries=65535会被内核按语义向上取整为65536；审计标为normalized。
  - unres_qlen=3000与unres_qlen_bytes=65535是同一内核存储的包数/字节数视图，无法同时精确成立。
    E159保留127条原始请求作审计证据，但在有效配置中以现代unres_qlen_bytes=65535为准；
    因而unres_qlen通常读回约31，审计标为alias-bytes，不再误判为事务失败。
  - rps_sock_flow_entries只建立全局表；每队列rps_flow_cnt/RPS掩码仍由独立RPS菜单管理。
  - route.flush是写触发器，不存在可持久读回的“当前值”。
  - 默认qdisc只影响新建队列；菜单20已有HTB/CAKE时以tc实际root qdisc为准。
EOF_E159_RISKS

}
# EEX3-FUNCTION network_e159_164 _e159_network_snapshot
_e159_network_snapshot() {
    local tx="$1" requested="$2" p id key old;
    : > "$tx/paths.tsv" || return 1;
    while IFS= read -r p; do
        test -n "$p" || continue;
        id=$(printf '%s' "$p" | sha256sum | awk '{print $1}');
        printf '%s|%s\n' "$p" "$id" >> "$tx/paths.tsv" || return 1;
        _e135_snapshot_file "$p" "$tx/files/$id" || return 1;
    done < <(_e159_network_paths | awk 'NF&&!seen[$0]++');
    : > "$tx/runtime.before" || return 1;
    while IFS= read -r key; do
        test "$key" = net.ipv4.route.flush && continue;
        old=$(sysctl -n "$key" 2> /dev/null || true);
        test -n "$old" && printf '%s|%s\n' "$key" "$(_e159_norm "$old")" >> "$tx/runtime.before";
    done < <(_e159_active_keys "$requested");
    _e159_snapshot_side_effects "$tx" || return 1;
    { 
        _e159_snapshot_service xray-network-e159.timer || return 1;
        _e159_snapshot_service xray-network-e159.service || return 1;
        _e159_snapshot_service xray-network-e156.timer || return 1;
        _e159_snapshot_service xray-network-e156.service || return 1;
        _e159_snapshot_service xray-network-e154.timer || return 1;
        _e159_snapshot_service xray-network-e154.service || return 1;
        _e159_snapshot_service xray-network-e152.timer || return 1;
        _e159_snapshot_service xray-network-e152.service || return 1;
        _e159_snapshot_service xray-hw-tweaks.service || return 1;
        _e159_snapshot_service xray-accel-e125.service || return 1;
        _e159_snapshot_service xray-accel-e126.service || return 1
    } > "$tx/services.before" || return 1;
    printf 'created=%s\nkernel=%s\n' "$(date -Is 2> /dev/null || date)" "$(uname -r)" > "$tx/meta.env";
    ( cd "$tx" && find . -type f ! -name seal.sha256 -print0 | sort -z | xargs -0 sha256sum > seal.sha256 ) || return 1;
    test -s "$tx/seal.sha256"
}
# EEX3-FUNCTION network_e159_164 _e159_network_state_validate
_e159_network_state_validate() {
    local state="${1:-$E159_NETWORK_STATE}" requested logical effective_active effective_persistent;
    local supported unsupported shadowed trigger backup origin actual;
    local report_supported report_unsupported report_shadowed report_trigger;
    test -s "$state" || return 1;
    test "$(sed -n 's/^version=//p' "$state" | tail -n1)" = 199e159 || return 1;
    requested=$(sed -n 's/^requested_entries=//p' "$state" | tail -n1);
    logical=$(sed -n 's/^logical_controls=//p' "$state" | tail -n1);
    effective_active=$(sed -n 's/^effective_active=//p' "$state" | tail -n1);
    effective_persistent=$(sed -n 's/^effective_persistent=//p' "$state" | tail -n1);
    supported=$(sed -n 's/^supported=//p' "$state" | tail -n1);
    unsupported=$(sed -n 's/^unsupported=//p' "$state" | tail -n1);
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$state" | tail -n1);
    trigger=$(sed -n 's/^write_trigger=//p' "$state" | tail -n1);
    for actual in "$requested" "$logical" "$effective_active" "$effective_persistent" "$supported" "$unsupported" "$shadowed" "$trigger";
    do
        [[ "$actual" =~ ^[0-9]+$ ]] || return 1;
    done;
    test "$requested" -eq 127 && test "$logical" -eq 125 && test "$effective_active" -eq "$supported" && test "$effective_persistent" -eq $((supported-trigger)) && test $((supported+unsupported+shadowed)) -eq 127 && (( trigger <= 1 && shadowed <= 1 )) || return 1;
    actual=$(_e159_active_keys "$E159_EFFECTIVE_CONF" | wc -l | tr -d ' ');
    test "$actual" -eq "$effective_active" || return 1;
    report_supported=$(awk -F'\t' 'NR>1&&$2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
    report_unsupported=$(awk -F'\t' 'NR>1&&$2=="unsupported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
    report_shadowed=$(awk -F'\t' 'NR>1&&$2=="shadowed-alias"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
    report_trigger=$(awk -F'\t' 'NR>1&&$1=="net.ipv4.route.flush"&&$2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
    test "$report_supported" -eq "$supported" && test "$report_unsupported" -eq "$unsupported" && test "$report_shadowed" -eq "$shadowed" && test "$report_trigger" -eq "$trigger" || return 1;
    backup=$(sed -n 's/^backup=//p' "$state" | tail -n1);
    origin=$(sed -n 's/^origin_backup=//p' "$state" | tail -n1);
    _e159_network_tx_verify "$backup" && _e159_network_tx_verify "$origin"
}
# EEX3-FUNCTION network_e159_164 _e159_network_tx_new
_e159_network_tx_new() {
    local d;
    _e159_prepare || return 1;
    d="$E159_NETWORK_TX_ROOT/tx-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM";
    install -d -m 0700 "$d/files" || return 1;
    printf '%s\n' "$d"
}
# EEX3-FUNCTION network_e159_164 _e159_network_tx_verify
_e159_network_tx_verify() {
    local tx="$1" real root trusted=0;
    real=$(readlink -f -- "$tx" 2> /dev/null || true);
    test -n "$real" || return 1;
    for root in "$E159_NETWORK_TX_ROOT" "$E159_LEGACY_E156_NETWORK_TX_ROOT" "$E159_LEGACY_E154_NETWORK_TX_ROOT";
    do
        root=$(readlink -f -- "$root" 2> /dev/null || true);
        test -n "$root" || continue;
        case "$real" in 
            "$root"/*)
                trusted=1;
                break
            ;;
        esac;
    done;
    test "$trusted" -eq 1 || return 1;
    test -s "$tx/seal.sha256" || return 1;
    ( cd "$tx" && sha256sum -c seal.sha256 > /dev/null 2>&1 )
}
# EEX3-FUNCTION network_e159_164 _e159_network_verify_effective
_e159_network_verify_effective() {
    local key value actual failed=0;
    test -s "$E159_EFFECTIVE_CONF" && test -s "$E159_NETWORK_SEAL" || return 1;
    sha256sum -c "$E159_NETWORK_SEAL" > /dev/null 2>&1 || { 
        error "E159网络配置封印校验失败，拒绝把被改写的产物当成当前事务。";
        return 1
    };
    _e159_network_artifacts_validate "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" || return 1;
    _e159_network_state_validate "$E159_NETWORK_STATE" || { 
        error "E159网络状态计数/报告/快照不变量失败。";
        return 1
    };
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key");
        value=$(_e159_norm "$value");
        case "$key" in 
            '' | '#'* | net.ipv4.route.flush)
                continue
            ;;
        esac;
        actual=$(sysctl -n "$key" 2> /dev/null || true);
        _e159_value_equal "$key" "$value" "$actual" || failed=1;
    done < "$E159_EFFECTIVE_CONF";
    test "$failed" -eq 0
}
