# EEX3-FUNCTION network_e159_164 _e159_restore_runtime_file
_e159_restore_runtime_file() {
    local file="$1" key old current rc=0 low="" high="" pair=0;
    test -s "$file" || return 0;
    old=$(awk -F'|' '$1=="net.ipv4.ip_forward"{print substr($0,index($0,"|")+1);exit}' "$file");
    if test -n "$old"; then
        current=$(sysctl -n net.ipv4.ip_forward 2> /dev/null || true);
        test "$current" = "$old" || sysctl -w "net.ipv4.ip_forward=$old" > /dev/null 2>&1 || rc=1;
    fi;
    low=$(awk -F'|' '$1=="net.ipv4.ipfrag_low_thresh"{print substr($0,index($0,"|")+1);exit}' "$file");
    high=$(awk -F'|' '$1=="net.ipv4.ipfrag_high_thresh"{print substr($0,index($0,"|")+1);exit}' "$file");
    test -n "$low" && test -n "$high" && pair=1 || true;
    while IFS='|' read -r key old; do
        test -n "$key" || continue;
        case "$key" in 
            net.ipv4.ip_forward | net.ipv4.route.flush)
                continue
            ;;
            net.ipv4.ipfrag_low_thresh | net.ipv4.ipfrag_high_thresh)
                test "$pair" -eq 1 && continue
            ;;
        esac;
        sysctl -w "$key=$old" > /dev/null 2>&1 || rc=1;
    done < "$file";
    if test "$pair" -eq 1; then
        _e170_apply_ipfrag_pair_values "$low" "$high" || rc=1;
    fi;
    return "$rc"
}
