# EEX3-FUNCTION network_e159_164 _e159_restore_side_effects
_e159_restore_side_effects() {
    local file="$1" root="${E159_PROC_ROOT:-/proc/sys}" rel encoded value path current rc=0;
    test -s "$file" || return 0;
    while IFS='	' read -r rel encoded; do
        [[ "$rel" =~ ^(net/ipv4/conf/[A-Za-z0-9_.:-]+/[A-Za-z0-9_]+|vm/dirty_bytes)$ ]] || { 
            rc=1;
            continue
        };
        path="$root/$rel";
        test -e "$path" || continue;
        test -w "$path" || { 
            rc=1;
            continue
        };
        value=$(printf '%s' "$encoded" | base64 -d 2> /dev/null) || { 
            rc=1;
            continue
        };
        printf '%s\n' "$value" > "$path" 2> /dev/null || { 
            rc=1;
            continue
        };
    done < "$file";
    while IFS='	' read -r rel encoded; do
        [[ "$rel" =~ ^(net/ipv4/conf/[A-Za-z0-9_.:-]+/[A-Za-z0-9_]+|vm/dirty_bytes)$ ]] || continue;
        path="$root/$rel";
        test -r "$path" || continue;
        value=$(printf '%s' "$encoded" | base64 -d 2> /dev/null) || { 
            rc=1;
            continue
        };
        current=$(_e159_norm "$(cat "$path" 2> /dev/null || true)");
        test "$current" = "$(_e159_norm "$value")" || rc=1;
    done < "$file";
    return "$rc"
}
