# EEX3-FUNCTION network_e159_164 _e159_snapshot_side_effects
_e159_snapshot_side_effects() {
    local tx="$1" root="${E159_PROC_ROOT:-/proc/sys}" path rel value encoded;
    : > "$tx/side-effects.before" || return 1;
    if test -d "$root/net/ipv4/conf"; then
        while IFS= read -r path; do
            test -r "$path" && test -w "$path" || continue;
            rel=${path#"$root"/};
            value=$(_e159_norm "$(cat "$path" 2> /dev/null || true)");
            encoded=$(printf '%s' "$value" | base64 | tr -d '\n\r');
            printf '%s\t%s\n' "$rel" "$encoded" >> "$tx/side-effects.before" || return 1;
        done < <(find "$root/net/ipv4/conf" -type f -print 2> /dev/null | sort);
    fi;
    path="$root/vm/dirty_bytes";
    if test -r "$path" && test -w "$path"; then
        value=$(_e159_norm "$(cat "$path" 2> /dev/null || true)");
        if test "${value:-0}" != 0; then
            encoded=$(printf '%s' "$value" | base64 | tr -d '\n\r');
            printf 'vm/dirty_bytes\t%s\n' "$encoded" >> "$tx/side-effects.before" || return 1;
        fi;
    fi
}
# EEX3-FUNCTION network_e159_164 _e159_space_cleanup_impl
_e159_space_cleanup_impl() {
