# EEX3-FUNCTION network_e159_164 _e159_spec_validate
_e159_spec_validate() {
    local file="$1" count dup;
    test -s "$file" || { 
        error "E159请求规格为空。";
        return 1
    };
    count=$(_e159_active_keys "$file" | wc -l | tr -d ' ');
    test "$count" -eq 127 || { 
        error "E159原始规格应为127条（125控制+1触发器+1别名），实际$count。";
        return 1
    };
    dup=$(_e159_active_keys "$file" | sort | uniq -d | head -n1);
    test -z "$dup" || { 
        error "E159规格重复参数：$dup";
        return 1
    };
    grep -qx 'net.ipv4.tcp_congestion_control = bbr' "$file" || return 1;
    grep -qx 'net.core.rmem_default = 7990577' "$file" || return 1;
    grep -qx 'net.core.rmem_max = 97108868' "$file" || return 1;
    grep -qx 'net.ipv4.tcp_notsent_lowat = 16384' "$file" || return 1;
    grep -qx 'net.core.busy_poll = 50' "$file" || return 1;
    grep -qx 'net.ipv4.tcp_fastopen = 0' "$file" || return 1;
    grep -qx 'net.ipv4.tcp_ecn = 0' "$file" || return 1;
    ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$file"
}
# EEX3-FUNCTION network_e159_164 _e159_ssh_guard_install_base
_e159_ssh_guard_install_base() {
    local profile mode ip tmp backend tx="" failed=0;
    _e141_prepare || return 1;
    profile=$(_e141_sshd_auth_profile) || { 
        error "无法读取sshd有效认证配置。";
        return 1
    };
    mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1);
    ip=$(_e135_current_ssh_ip 2> /dev/null || true);
    E152_CURRENT_SSH_IP="$ip";
    backend=$(_e152_firewall_backend 2> /dev/null);
    if test "$backend" != nft; then
        tmp="${E141_SSH_AUTH_STATE}.tmp.$$";
        { 
            printf '%s\n' "$profile";
            printf 'current_ssh_ip=%s\nfirewall_backend=%s\nchecked_at=%s\n' "$ip" "$backend" "$(date -Is 2> /dev/null || date)"
        } > "$tmp" || return 1;
        install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || { 
            rm -f "$tmp";
            return 1
        };
        rm -f "$tmp";
        _e152_ssh_guard_inherited || return 1;
        return 0;
    fi;
    tx=$(_e152_nft_ssh_tx_begin) || { 
        error "原生nftables SSH变更前快照失败。";
        return 1
    };
    tmp="${E141_SSH_AUTH_STATE}.tmp.$$";
    { 
        printf '%s\n' "$profile";
        printf 'current_ssh_ip=%s\nfirewall_backend=%s\nchecked_at=%s\ntransaction=%s\n' "$ip" "$backend" "$(date -Is 2> /dev/null || date)" "$tx"
    } > "$tmp" || failed=1;
    test "$failed" -ne 0 || install -m 0600 "$tmp" "$E141_SSH_AUTH_STATE" || failed=1;
    rm -f "$tmp" 2> /dev/null || true;
    if test "$failed" -eq 0; then
        case "$mode" in 
            key-only | non-password)
                info "原生nftables + $mode：保留现有防火墙策略，不强装Fail2ban，不伪造万能ACCEPT链。";
                _e152_install_nft_ssh_audit || failed=1
            ;;
            password-capable)
                info "原生nftables + 密码认证：启用Fail2ban原生nftables action。";
                _e121_install_fail2ban_guard || failed=1;
                test "$failed" -ne 0 || _e135_patch_fail2ban_ignoreip "$ip" || failed=1;
                test "$failed" -ne 0 || _e152_fail2ban_passive_verify || failed=1;
                test "$failed" -ne 0 || _e152_verify_nft_fail2ban_action || failed=1;
                test "$failed" -ne 0 || _e152_install_nft_ssh_audit || failed=1
            ;;
            ambiguous)
                warn "SSH认证策略存在Match歧义：保留nft策略并部署只读审计。";
                if command -v fail2ban-client > /dev/null 2>&1; then
                    _e121_install_fail2ban_guard || failed=1;
                    test "$failed" -ne 0 || _e135_patch_fail2ban_ignoreip "$ip" || failed=1;
                fi;
                test "$failed" -ne 0 || _e152_install_nft_ssh_audit || failed=1
            ;;
            *)
                error "未知SSH认证判定：$mode";
                failed=1
            ;;
        esac;
    fi;
    test "$failed" -ne 0 || _e152_install_ssh_auth_audit || failed=1;
    test "$failed" -ne 0 || _e152_disable_legacy_iptables_ssh_guard || failed=1;
    test "$failed" -ne 0 || _e152_nft_ssh_check || failed=1;
    test "$failed" -ne 0 || _e152_nft_ssh_tx_commit "$tx" || failed=1;
    if test "$failed" -ne 0; then
        error "原生nftables SSH/Fail2ban事务失败，恢复原配置、服务状态及E152/E159专用表。";
        _e152_nft_ssh_tx_rollback "$tx" || warn "局部回滚未完全成功；热更新总事务仍会继续执行系统级回滚。";
        return 1;
    fi;
    return 0
}
