# EEX3-FUNCTION network_e159_164 _e159_system_restore_base
_e159_system_restore_base() {
    local b="$1";
    test -s "$b/e152-extra.sha256" || { 
        error "E152附加回滚校验缺失：$b";
        return 1
    };
    grep -qv '^#' "$b/e152-extra.sha256" 2> /dev/null && ( cd "$b" && sha256sum -c e152-extra.sha256 > /dev/null 2>&1 ) || { 
        grep -q '^# no optional payload$' "$b/e152-extra.sha256" || { 
            error "E152附加回滚校验失败：$b";
            return 1
        }
    };
    _e152_restore_stage_verify "$b" || { 
        error "回滚归档无法完整预解包，尚未删除任何在线路径。";
        return 1
    };
    _e152_system_restore_base "$b"
}
# EEX3-FUNCTION network_e159_164 _e159_system_snapshot_base
_e159_system_snapshot_base() {
    local b="$1" f;
    _e152_system_snapshot_base "$b" || return 1;
    command -v nft > /dev/null 2>&1 && nft list ruleset > "$b/nft.rules.diagnostic" 2> /dev/null || true;
    : > "$b/e152-extra.sha256" || return 1;
    for f in iptables.rules ip6tables.rules nft.rules.diagnostic e140-services.env e142-prestate.env;
    do
        test ! -e "$b/$f" || ( cd "$b" && sha256sum "$f" >> e152-extra.sha256 ) || return 1;
    done;
    test -s "$b/e152-extra.sha256" || printf '%s\n' '# no optional payload' > "$b/e152-extra.sha256"
}
