# EEX3-FUNCTION network_e159_164 _e159_unres_alias_equal
_e159_unres_alias_equal() {
    local requested="$1" actual_packets="$2" actual_bytes="$3" expected_bytes;
    [[ "$actual_packets" =~ ^[0-9]+$ ]] || return 1;
    expected_bytes=$(awk -F= '$1 ~ /^[[:space:]]*net\.ipv4\.neigh\.default\.unres_qlen_bytes[[:space:]]*$/{print $2;exit}' "$requested" 2> /dev/null | xargs);
    test -n "$expected_bytes" || return 1;
    _e159_value_equal net.ipv4.neigh.default.unres_qlen_bytes "$expected_bytes" "$actual_bytes"
}
# EEX3-FUNCTION network_e159_164 _e159_value_equal
_e159_value_equal() {
    local key="$1" expected actual;
    expected=$(_e159_norm "$2");
    actual=$(_e159_norm "$3");
    case "$key" in 
        net.ipv4.tcp_recovery)
            (( expected == actual )) 2> /dev/null
        ;;
        net.ipv4.tcp_child_ehash_entries)
            test "$expected" = "$actual" || { 
                test "$expected" = 65535 && test "$actual" = 65536
            }
        ;;
        *)
            test "$expected" = "$actual"
        ;;
    esac
}
# EEX3-FUNCTION network_e159_164 _e159_verify_neighbor_queue_semantics
_e159_verify_neighbor_queue_semantics() {
    local packet_status bytes_status shadowed packet_actual bytes_actual;
    packet_status=$(awk -F'\t' '$1=="net.ipv4.neigh.default.unres_qlen"{print $2;exit}' "$E159_NETWORK_REPORT" 2> /dev/null || true);
    bytes_status=$(awk -F'\t' '$1=="net.ipv4.neigh.default.unres_qlen_bytes"{print $2;exit}' "$E159_NETWORK_REPORT" 2> /dev/null || true);
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$E159_NETWORK_STATE" 2> /dev/null | tail -n1);
    shadowed=${shadowed:-0};
    case "$packet_status:$bytes_status:$shadowed" in 
        shadowed-alias:supported:1)
            ! grep -Eq '^[[:space:]]*net\.ipv4\.neigh\.default\.unres_qlen[[:space:]]*=' "$E159_EFFECTIVE_CONF" || return 1;
            grep -qx 'net.ipv4.neigh.default.unres_qlen_bytes = 65535' "$E159_EFFECTIVE_CONF" || return 1;
            bytes_actual=$(sysctl -n net.ipv4.neigh.default.unres_qlen_bytes 2> /dev/null || true);
            test "$bytes_actual" = 65535
        ;;
        supported:unsupported:0)
            grep -qx 'net.ipv4.neigh.default.unres_qlen = 3000' "$E159_EFFECTIVE_CONF" || return 1;
            packet_actual=$(sysctl -n net.ipv4.neigh.default.unres_qlen 2> /dev/null || true);
            test "$packet_actual" = 3000
        ;;
        unsupported:supported:0)
            grep -qx 'net.ipv4.neigh.default.unres_qlen_bytes = 65535' "$E159_EFFECTIVE_CONF" || return 1;
            bytes_actual=$(sysctl -n net.ipv4.neigh.default.unres_qlen_bytes 2> /dev/null || true);
            test "$bytes_actual" = 65535
        ;;
        unsupported:unsupported:0)
            ! grep -Eq '^[[:space:]]*net\.ipv4\.neigh\.default\.unres_qlen(_bytes)?[[:space:]]*=' "$E159_EFFECTIVE_CONF"
        ;;
        *)
            error "邻居未解析队列别名状态不一致：packet=$packet_status bytes=$bytes_status shadowed=$shadowed";
            return 1
        ;;
    esac
}
# EEX3-FUNCTION network_e159_164 _e159_verify_runtime_file
_e159_verify_runtime_file() {
    local file="$1" key old current failed=0;
    test -s "$file" || return 0;
    while IFS='|' read -r key old; do
        test -n "$key" || continue;
        case "$key" in 
            net.ipv4.route.flush)
                continue
            ;;
        esac;
        current=$(sysctl -n "$key" 2> /dev/null || true);
        _e159_value_equal "$key" "$old" "$current" || { 
            error "E159回滚读回不一致：$key 期望=$old 实际=${current:-unreadable}";
            failed=1
        };
    done < "$file";
    test "$failed" -eq 0
}
# EEX3-FUNCTION network_e159_164 _e159_verify_state_snapshot_base
_e159_verify_state_snapshot_base() {
    local bdir="$1" base seen="";
    _e127_backup_dir_ok "$bdir" || { 
        error "拒绝使用事务目录之外的快照：$bdir";
        return 1
    };
    test -f "$bdir/files.manifest" && test -f "$bdir/meta.env" || return 1;
    while IFS= read -r base; do
        test -n "$base" || continue;
        [[ "$base" =~ ^[A-Za-z0-9._-]+$ ]] || { 
            error "快照文件名非法：$base";
            return 1
        };
        [[ " $seen " != *" $base "* ]] || { 
            error "快照清单重复：$base";
            return 1
        };
        test -f "$bdir/$base" || { 
            error "快照文件缺失：$base";
            return 1
        };
        seen="$seen $base";
    done < "$bdir/files.manifest";
    if test -s "$bdir/files.sha256"; then
        ( cd "$bdir" && sha256sum -c files.sha256 > /dev/null 2>&1 ) || { 
            error "配置事务快照校验和失败：$bdir";
            return 1
        };
    fi
}
# EEX3-FUNCTION network_e159_164 _e159_warp_full_enable_base
_e159_warp_full_enable_base() {
    local before after tx rc=0;
    before=$(_e118_mktemp warp-full-before-e204) || return 1;
    find "$E142_TX_ROOT" "$E140_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -name 'warp-full-enable-*' -print 2> /dev/null | LC_ALL=C sort > "$before" || true;
    _e152_warp_full_enable_impl "$@" || rc=$?;
    test "$rc" -eq 0 || return "$rc";
    _e140_full_mode_active || return 0;
    after=$(_e118_mktemp warp-full-after-e204) || return 1;
    find "$E142_TX_ROOT" "$E140_TX_ROOT" -mindepth 1 -maxdepth 1 -type d -name 'warp-full-enable-*' -print 2> /dev/null | LC_ALL=C sort > "$after" || true;
    tx=$(comm -13 "$before" "$after" | tail -n1);
    test -n "$tx" || { 
        error '全隧道显示已启用，但本次调用没有产生独立事务；拒绝借用旧快照。';
        return 1
    };
    _e142_full_snapshot_verify "$tx" || { 
        error '全隧道已连接但本次提交快照不可验证，立即回滚。';
        _e140_full_rollback_tx "$tx" || true;
        return 1
    };
    _e139_state_set_fields full_commit_tx "$tx" full_committed_at "$(date -Is 2> /dev/null || date)" managed_by e204 || { 
        _e140_full_rollback_tx "$tx" || true;
        return 1
    };
    info "已记录E204全隧道提交快照：$tx"
}
# EEX3-FUNCTION network_e159_164 _e159_warp_status_impl
_e159_warp_status_impl() {
    local enabled mode profile trace loc ip settings src iface ssh_ip route_check="N/A";
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    title "V199e159：WARP/Cloudflare状态";
    printf '  %-28s %s\n' "期望状态" "enabled=$enabled mode=$mode profile=$profile";
    printf '  %-28s %s\n' "warp-svc" "$(systemctl is-active "$(_e140_warp_service_name)" 2> /dev/null || echo unknown)";
    printf '  %-28s %s\n' "注册" "$(_e140_warp_registration_ok && echo OK || echo MISSING)";
    printf '  %-28s %s\n' "客户端模式" "$(_e140_warp_mode_current)";
    printf '  %-28s %s\n' "隧道协议" "$(_e140_warp_protocol_current)";
    if test "$mode" = host-full && test "$enabled" = 1; then
        trace=$(_e140_full_trace 2> /dev/null || true);
        loc=$(awk -F= '$1=="loc"{print $2}' <<< "$trace");
        loc=${loc:-unknown};
        ip=$(awk -F= '$1=="ip"{print $2}' <<< "$trace");
        ip=${ip:-unknown};
        src=$(_e139_full_state_value orig_src);
        iface=$(_e139_full_state_value orig_iface);
        ssh_ip=$(_e139_full_state_value ssh_ip);
        if _e136_is_ipv4 "$src" && ip -4 route get 1.1.1.1 from "$src" 2> /dev/null | grep -Fq "dev $iface"; then
            route_check=OK;
        else
            route_check=FAIL;
        fi;
        printf '  %-28s %s\n' "系统全隧道" "$(_e140_warp_status_connected && echo CONNECTED || echo DOWN)";
        printf '  %-28s %s\n' "Cloudflare出口/loc" "$ip/$loc";
        printf '  %-28s %s\n' "原IPv4源地址/网卡" "$src/$iface";
        printf '  %-28s %s\n' "SSH/Xray回程保护" "$route_check (peer=${ssh_ip:-unknown})";
    else
        trace=$(_e136_warp_trace 2> /dev/null || true);
        loc=$(awk -F= '$1=="loc"{print $2}' <<< "$trace");
        loc=${loc:-unknown};
        ip=$(awk -F= '$1=="ip"{print $2}' <<< "$trace");
        ip=${ip:-unknown};
        _e138_warp_config_integrity "$mode" "$profile" > /dev/null 2>&1 && route_check=CONSISTENT || route_check=MISSING;
        printf '  %-28s %s\n' "本地代理" "$(_e137_warp_proxy_ready && echo UP || echo DOWN)";
        printf '  %-28s %s\n' "Xray配置一致性" "$route_check";
        printf '  %-28s %s\n' "WARP出口/loc" "$ip/$loc";
    fi;
    settings=$(_e140_warp_settings | grep -Ei 'mode|service|protocol|proxy' | xargs echo || true);
    printf '  %-28s %s\n' "settings摘要" "${settings:-unavailable}";
    echo "  诊断目录: $E140_FULL_LOG_DIR"
}
# EEX3-FUNCTION network_e159_164 _e159_write_nft_action_candidate
_e159_write_nft_action_candidate() {
    local out="$1";
    cat > "$out" <<EOF_E159_NFT_ACTION
[INCLUDES]
before = nftables.conf

[Init]
type = multiport
table = $E159_NFT_F2B_TABLE
table_family = inet
chain = $E159_NFT_F2B_CHAIN
chain_type = filter
chain_hook = input
chain_priority = -1
blocktype = reject
actionstart_on_demand = false
EOF_E159_NFT_ACTION

}
# EEX3-FUNCTION network_e159_164 _e159_write_version
_e159_write_version() {
    _e214_write_version "$@"
}
# EEX3-FUNCTION network_e159_164 _e159_xray_action_rollback
_e159_xray_action_rollback() {
    local protect="$1" rc=0;
    _e118_restore_core_payload "$protect" > /dev/null 2>&1 || rc=1;
    _e118_restore_state "$protect" > /dev/null 2>&1 || rc=1;
    test "$rc" -eq 0 || error "Xray动作回滚未完整通过：$protect";
    return "$rc"
}
# EEX3-FUNCTION network_e159_164 _e159_xray_action_tx
_e159_xray_action_tx() {
    local name="${1:-}";
    test -n "$name" || { 
        error 'E204 Xray事务缺少动作名称。';
        return 1
    };
    _e204_advanced_action_tx "xray-$name" _e204_xray_action_tx_base "$@"
}
