                _e121_install_fail2ban_guard || failed=1;
                if test "$failed" -eq 0 && test -n "$ip" && ! _e170_current_ip_ignored "$ip"; then
                    stage=ignoreip-reconcile;
                    _e135_patch_fail2ban_ignoreip "$ip" || failed=1;
                    test "$failed" -ne 0 || restart_after_install=1;
                fi;
                if test "$failed" -eq 0; then
                    stage=passive-readback;
                    _e152_fail2ban_passive_verify || failed=1;
                fi;
                if test "$failed" -eq 0; then
                    if test "$restart_after_install" -eq 1; then
                        stage=live-ban-after-final-restart;
