        rm -f -- "$E165_F2B_HELPER" "$E165_F2B_ACTION_CONF" "$E165_F2B_FILTER" "$E165_F2B_LEGACY_DISABLE" "$E165_LEGACY_E163_HELPER" "$E165_LEGACY_E163_ACTION_CONF" "$E165_LEGACY_E163_FILTER" "$E165_LEGACY_E163_DISABLE" "$E165_SELF_PATH" 2> /dev/null || true;
        rm -rf -- "$E165_DIR" 2> /dev/null || true;
        if command -v fail2ban-client > /dev/null 2>&1 && fail2ban-client -t > /dev/null 2>&1; then
            systemctl start fail2ban.service > /dev/null 2>&1 || true;
        fi;
    fi;
    return "$rc"
}
