# EEX3-FUNCTION firewall_warp_e165_188 _e168_build_full_config_impl
_e168_build_full_config_impl() {
    local mode="$1" reality_port="$2" enc_port="$3" ss_port="$4" ss_method="$5" ss_pass="$6" tmp_config="$7";
    local need_reality=false need_enc=false need_ss=false;
    E77_REALITY_PRIV="";
    E77_REALITY_PUB="";
    E77_REALITY_UUID="";
    E77_REALITY_SID="";
    E77_VLESSENC_UUID="";
    E77_VLESSENC_DECRYPTION="";
    E77_VLESSENC_ENCRYPTION="";
    E77_SS_METHOD="$ss_method";
    E77_SS_PASS="$ss_pass";
    E77_CTIME="$(date +'%Y-%m-%d %H:%M')";
    case "$mode" in 
        1)
            need_reality=true
        ;;
        2)
            need_enc=true
        ;;
        3)
            need_ss=true
        ;;
        4)
            need_reality=true;
            need_ss=true
        ;;
        *)
            error "未知建仓模式：$mode";
            return 1
        ;;
    esac;
    if test "$need_reality" = true; then
        _e118_generate_reality_material || return 1;
        if ! printf '%s' "$SNI_JSON_ARRAY" | jq -e 'type=="array" and length>0 and all(.[]; type=="string" and length>0)' > /dev/null 2>&1; then
            error "SNI 列表非法，拒绝静默回退。请重新选择 SNI。";
            return 1;
        fi;
    fi;
    if test "$need_enc" = true; then
        E77_VLESSENC_UUID=$(cat /proc/sys/kernel/random/uuid 2> /dev/null || "$XRAY_BIN" uuid 2> /dev/null || true);
        _e118_valid_uuid "$E77_VLESSENC_UUID" || { 
            error "VLESSENC UUID 生成失败。";
            return 1
        };
        e77_generate_vlessenc_pair || return 1;
    fi;
    jq -n --argjson need_reality "$need_reality" --argjson need_enc "$need_enc" --argjson need_ss "$need_ss" --argjson reality_port "$reality_port" --argjson enc_port "$enc_port" --argjson ss_port "$ss_port" --argjson snis "$SNI_JSON_ARRAY" --arg best_sni "$BEST_SNI" --arg r_priv "$E77_REALITY_PRIV" --arg r_uuid "$E77_REALITY_UUID" --arg r_sid "$E77_REALITY_SID" --arg e_uuid "$E77_VLESSENC_UUID" --arg e_dec "$E77_VLESSENC_DECRYPTION" --arg remark "${REMARK_NAME:-xp-reality}" --arg ss_pass "$ss_pass" --arg ss_method "$ss_method" '
    {
      log: {loglevel: "warning", access: "none", error: "none"},
      routing: {
        domainStrategy: "AsIs",
        rules: [
          {outboundTag: "block", protocol: ["bittorrent"]},
          {outboundTag: "block", domain: ["geosite:category-ads-all"]}
        ]
      },
      dns: {servers: ["https://1.1.1.1/dns-query", "https://208.67.224.224/dns-query"], queryStrategy: "UseIPv4"},
      policy: {
        levels: {"0": {handshake: 5, connIdle: 260, uplinkOnly: 2, downlinkOnly: 5, bufferSize: 768}},
        system: {statsInboundDownlink: false, statsInboundUplink: false}
      },
      inbounds: [],
      outbounds: [
        {protocol: "freedom", tag: "direct", settings: {targetStrategy: "UseIPv4"}, streamSettings: {sockopt: {tcpNoDelay: true, tcpFastOpen: false, tcpKeepAliveIdle: 30, tcpKeepAliveInterval: 15}}},
        {protocol: "blackhole", tag: "block"}
      ]
    }
    | if $need_reality then .inbounds += [{
        tag: "vless-reality-vision", listen: "0.0.0.0", port: $reality_port, protocol: "vless",
        settings: {clients: [{id: $r_uuid, flow: "xtls-rprx-vision", email: ($remark+"-reality")}], decryption: "none"},
        streamSettings: {
          network: "raw", security: "reality",
          sockopt: {tcpNoDelay: true, tcpFastOpen: false, tcpKeepAliveIdle: 30, tcpKeepAliveInterval: 15},
          realitySettings: {show: false, target: ($best_sni+":443"), serverNames: $snis, privateKey: $r_priv, shortIds: [$r_sid], maxTimeDiff: 60000}
        },
        sniffing: {enabled: true, destOverride: ["http","tls","quic"], metadataOnly: true, routeOnly: true}
      }] else . end
    | if $need_enc then .inbounds += [{
        tag: "vlessenc-vision-raw", listen: "0.0.0.0", port: $enc_port, protocol: "vless",
        settings: {clients: [{id: $e_uuid, flow: "xtls-rprx-vision", email: ($remark+"-vlessenc")}], decryption: $e_dec},
        streamSettings: {network: "raw", security: "none", sockopt: {tcpNoDelay: true, tcpFastOpen: false, tcpKeepAliveIdle: 30, tcpKeepAliveInterval: 15}},
        sniffing: {enabled: true, destOverride: ["http","tls","quic"], metadataOnly: true, routeOnly: true}
      }] else . end
    | if $need_ss then .inbounds += [{
        tag: "ss2022", listen: "0.0.0.0", port: $ss_port, protocol: "shadowsocks",
        settings: {method: $ss_method, password: $ss_pass, network: "tcp,udp"},
        streamSettings: {sockopt: {tcpNoDelay: true, tcpFastOpen: false, tcpKeepAliveIdle: 30, tcpKeepAliveInterval: 15}},
        sniffing: {enabled: true, destOverride: ["http","tls","quic"], metadataOnly: true, routeOnly: true}
      }] else . end
    ' > "$tmp_config" || return 1
}
