# EEX3-FUNCTION firewall_warp_e165_188 _e168_structure_audit
_e168_structure_audit() {
    local rc=0 defs dup_names final_dispatchers size lines menu hot advanced;
    echo 'V199e168 structure audit:';
    size=$(wc -c < "$SCRIPT_PATH" | tr -d ' ');
    lines=$(wc -l < "$SCRIPT_PATH" | tr -d ' ');
    defs=$(grep -Ec '^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" || true);
    dup_names=$(grep -E '^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$SCRIPT_PATH" | sed -E 's/^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*).*/\1/' | sort | uniq -d | wc -l | tr -d ' ');
    final_dispatchers=$(grep -c '^# V199e168 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    menu=$(declare -f _e168_main_menu_impl);
    hot=$(declare -f _e168_hot_update);
    advanced=$(declare -f _e168_advanced_menu);
    echo "  file_bytes=$size";
    echo "  lines=$lines";
    echo "  function_definitions=$defs";
    echo "  historical_duplicate_names=$dup_names";
    echo "  final_dispatchers=$final_dispatchers";
    echo '  menu_owner=e168 (E127 top-level contract)';
    echo '  network_owner=e159 data model / e168 safe presentation and action menu';
    echo '  node_owner=e168 identity / inherited E159-E165 Xray survival transaction';
    echo "  fail2ban_owner=$E165_F2B_ACTION_ID";
    test "$size" -gt 2000000 || rc=1;
    test "$lines" -gt 45000 || rc=1;
    test "$final_dispatchers" -eq 1 || rc=1;
    grep -q 'V199e168 - 事务稳态版' <<< "$menu" || rc=1;
    grep -q '_e168_advanced_menu' <<< "$menu" || rc=1;
    grep -q '_e168_install_self' <<< "$hot" || rc=1;
    grep -q '_e165_ssh_guard_verify_final' <<< "$hot" || rc=1;
    grep -q '_e168_tc_menu' <<< "$advanced" || rc=1;
    declare -F _e152_pause _e152_disable_legacy_optimizers _e152_show_optimization_status > /dev/null || rc=1;
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL';
    return "$rc"
}
