# EEX3-FUNCTION firewall_warp_e165_188 _e168_validate_generated_config_base
_e168_validate_generated_config_base() {
    local f="$1" mode="$2";
    jq empty "$f" > /dev/null 2>&1 || { 
        error "候选配置不是合法 JSON。";
        return 1
    };
    if ! jq -e --arg mode "$mode" '
      def uuid: test("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$");
      def domain: test("^([A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?\\.)+[A-Za-z]{2,63}$");
      def reality: [.inbounds[]? | select(.protocol=="vless" and (.streamSettings.security//"")=="reality")];
      def venc: [.inbounds[]? | select(.protocol=="vless" and (.settings.decryption//"none")!="none" and (.streamSettings.security//"none")=="none")];
      def ss: [.inbounds[]? | select(.protocol=="shadowsocks")];
      (.inbounds|type)=="array" and (.outbounds|type)=="array" and
      ([.inbounds[]?.port] | all(type=="number" and .>=1 and .<=65535)) and
      (([.inbounds[]?.port]|length) == ([.inbounds[]?.port]|unique|length)) and
      (reality | all(
        (.streamSettings.network//"tcp") as $n | ($n=="tcp" or $n=="raw") and
        (.settings.decryption//"")=="none" and
        ((.settings.clients//[])|length)>0 and
        ((.settings.clients//[])|all((.id//"")|uuid)) and
        ((.settings.clients//[])|all((.flow//"")=="xtls-rprx-vision")) and
        (((.streamSettings.realitySettings.target // .streamSettings.realitySettings.dest // "")|length)>3) and
        ((.streamSettings.realitySettings.privateKey//"")|test("^[A-Za-z0-9_-]{43}$")) and
        (((.streamSettings.realitySettings.serverNames//[])|length)>0) and
        ((.streamSettings.realitySettings.serverNames//[])|all(type=="string" and domain)) and
        (((.streamSettings.realitySettings.shortIds//[])|length)>0) and
        ((.streamSettings.realitySettings.shortIds//[])|all(test("^[0-9a-fA-F]{2,16}$") and (length%2==0)))
      )) and
      (venc | all(
        ((.settings.decryption//"none")|length)>10 and
        ((.settings.clients//[])|length)>0 and
        ((.settings.clients//[])|all((.id//"")|uuid)) and
        ((.settings.clients//[])|all((.flow//"")=="xtls-rprx-vision")) and
        ((.streamSettings.network//"tcp")=="tcp" or (.streamSettings.network//"")=="raw" or (.streamSettings.network//"")=="xhttp")
      )) and
      (ss | all(
        ((.settings.method//"") as $m | ($m=="2022-blake3-aes-128-gcm" or $m=="2022-blake3-aes-256-gcm" or $m=="2022-blake3-chacha20-poly1305")) and
        ((.settings.password//"")|length)>=20
      )) and
      (if $mode=="1" then (reality|length)==1 and (venc|length)==0 and (ss|length)==0
       elif $mode=="2" then (reality|length)==0 and (venc|length)==1 and (ss|length)==0
       elif $mode=="3" then (reality|length)==0 and (venc|length)==0 and (ss|length)==1
       elif $mode=="4" then (reality|length)==1 and (venc|length)==0 and (ss|length)==1
       else false end)
    ' "$f" > /dev/null 2>&1; then
        error "候选配置的协议数量、端口、密钥、Vision flow 或 Reality/VLESSENC 语义不符合所选模式。";
        jq -r '.inbounds[]? | "tag=\(.tag//"-") protocol=\(.protocol//"-") port=\(.port//"-") security=\(.streamSettings.security//"none") network=\(.streamSettings.network//"-")"' "$f" 2> /dev/null | sed 's/^/    /' || true;
        return 1;
    fi;
    _e124_validate_ss2022_inbounds "$f" || return 1;
    _e118_xray_test_config "$f" 1
}
