# EEX3-FUNCTION firewall_warp_e165_188 _e170_apply_ipfrag_pair_values
_e170_apply_ipfrag_pair_values() {
    local low="$1" high="$2" current_low current_high;
    [[ "$low" =~ ^[0-9]+$ && "$high" =~ ^[0-9]+$ ]] || { 
        error "ipfrag阈值不是非负整数：low=$low high=$high";
        return 1
    };
    (( low <= high )) || { 
        error "ipfrag阈值关系非法：low=$low > high=$high";
        return 1
    };
    current_low=$(sysctl -n net.ipv4.ipfrag_low_thresh 2> /dev/null | xargs || true);
    current_high=$(sysctl -n net.ipv4.ipfrag_high_thresh 2> /dev/null | xargs || true);
    [[ "$current_low" =~ ^[0-9]+$ && "$current_high" =~ ^[0-9]+$ ]] || return 1;
    if (( high < current_low )); then
        test "$current_low" = "$low" || sysctl -w "net.ipv4.ipfrag_low_thresh=$low" > /dev/null 2>&1 || { 
            error "E170写入失败：net.ipv4.ipfrag_low_thresh（降阈值前置）";
            return 1
        };
        test "$current_high" = "$high" || sysctl -w "net.ipv4.ipfrag_high_thresh=$high" > /dev/null 2>&1 || { 
            error "E170写入失败：net.ipv4.ipfrag_high_thresh";
            return 1
        };
    else
        test "$current_high" = "$high" || sysctl -w "net.ipv4.ipfrag_high_thresh=$high" > /dev/null 2>&1 || { 
            error "E170写入失败：net.ipv4.ipfrag_high_thresh（升阈值前置）";
            return 1
        };
        test "$current_low" = "$low" || sysctl -w "net.ipv4.ipfrag_low_thresh=$low" > /dev/null 2>&1 || { 
            error "E170写入失败：net.ipv4.ipfrag_low_thresh";
            return 1
        };
    fi;
    current_low=$(sysctl -n net.ipv4.ipfrag_low_thresh 2> /dev/null | xargs || true);
    current_high=$(sysctl -n net.ipv4.ipfrag_high_thresh 2> /dev/null | xargs || true);
    test "$current_low" = "$low" && test "$current_high" = "$high"
}
