# EEX3-FUNCTION firewall_warp_e165_188 _e170_ipfrag_order_verify
_e170_ipfrag_order_verify() {
    local file="${1:-$E159_EFFECTIVE_CONF}" low_line high_line;
    test -s "$file" || return 1;
    low_line=$(grep -nE '^[[:space:]]*net\.ipv4\.ipfrag_low_thresh[[:space:]]*=' "$file" | head -n1 | cut -d: -f1 || true);
    high_line=$(grep -nE '^[[:space:]]*net\.ipv4\.ipfrag_high_thresh[[:space:]]*=' "$file" | head -n1 | cut -d: -f1 || true);
    if test -n "$low_line" && test -n "$high_line"; then
        (( high_line < low_line )) || { 
            error "E170持久配置的ipfrag提交顺序不安全：high行=$high_line low行=$low_line";
            return 1
        };
    fi
}
