# EEX3-FUNCTION firewall_warp_e165_188 _e170_network_verify_ownership_base
_e170_network_verify_ownership_base() {
    local unit f;
    for unit in xray-network-e156.timer xray-network-e156.service xray-network-e154.timer xray-network-e154.service xray-network-e152.timer xray-network-e152.service xray-hw-tweaks.service xray-accel-e125.service xray-accel-e126.service;
    do
        systemctl is-enabled --quiet "$unit" 2> /dev/null && { 
            error "旧网络所有者仍被启用：$unit";
            return 1
        } || true;
        systemctl is-active --quiet "$unit" 2> /dev/null && { 
            error "旧网络所有者仍在运行：$unit";
            return 1
        } || true;
    done;
    for f in "$E159_LEGACY_E156_REQUESTED_CONF" "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_REPORT" "$E159_LEGACY_E156_STATE" "$E159_LEGACY_E156_SEAL" "$E159_LEGACY_E156_SCRIPT" "$E159_LEGACY_E156_SERVICE" "$E159_LEGACY_E156_TIMER" "$E159_LEGACY_E156_MODULES_CONF" "$E159_LEGACY_E154_REQUESTED_CONF" "$E159_LEGACY_E154_EFFECTIVE_CONF" "$E159_LEGACY_E154_REPORT" "$E159_LEGACY_E154_STATE" "$E159_LEGACY_E154_SCRIPT" "$E159_LEGACY_E154_SERVICE" "$E159_LEGACY_E154_TIMER" "$E159_LEGACY_E154_MODULES_CONF" "$E152_NETWORK_CONF" "$E152_NETWORK_SCRIPT" "$E152_NETWORK_SERVICE" "$E152_NETWORK_TIMER" /usr/local/bin/xray-hw-tweaks.sh /etc/systemd/system/xray-hw-tweaks.service /etc/sysctl.d/99-xray-e125-accel.conf /etc/sysctl.d/99-xray-e126-accel.conf;
    do
        test ! -e "$f" || { 
            error "旧网络所有者文件仍存在：$f";
            return 1
        };
    done;
    systemctl is-enabled --quiet xray-network-e159.service 2> /dev/null || return 1;
    systemctl is-enabled --quiet xray-network-e159.timer 2> /dev/null || return 1;
    systemctl is-active --quiet xray-network-e159.timer 2> /dev/null || return 1
}
