# EEX3-FUNCTION firewall_warp_e165_188 _e170_reorder_ipfrag_file
_e170_reorder_ipfrag_file() {
    local file="$1" tmp;
    test -s "$file" || return 1;
    grep -Eq '^[[:space:]]*net\.ipv4\.ipfrag_low_thresh[[:space:]]*=' "$file" || return 0;
    grep -Eq '^[[:space:]]*net\.ipv4\.ipfrag_high_thresh[[:space:]]*=' "$file" || return 0;
    tmp=$(mktemp /tmp/e170-ipfrag-order.XXXXXX) || return 1;
    awk '
      /^[[:space:]]*net\.ipv4\.ipfrag_low_thresh[[:space:]]*=/ { low=$0; next }
      /^[[:space:]]*net\.ipv4\.ipfrag_high_thresh[[:space:]]*=/ {
        print
        if (low != "") { print low; low="" }
        next
      }
      { print }
      END { if (low != "") print low }
    ' "$file" > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -f -- "$tmp" "$file"
}
