    for mode in 1 2 3 4;
    do
        file="$d/mode-$mode.json";
        e79_build_full_config "$mode" 443 8443 8388 2022-blake3-aes-128-gcm AAAAAAAAAAAAAAAAAAAAAA== "$file" || exit 1;
        jq -e --arg m "$mode" '
              ([.outbounds[]|select(.tag=="direct" and .protocol=="freedom" and .settings.targetStrategy=="UseIPv4")]|length)==1 and
              (if $m=="1" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==0
               elif $m=="2" then ([.inbounds[]|select(.protocol=="vless" and .streamSettings.security=="none")]|length)==1
               elif $m=="3" then ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1 and ([.inbounds[]|select(.protocol=="vless")]|length)==0
               elif $m=="4" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1
               else false end)' "$file" > /dev/null || exit 1;
    done ); then
        echo '  [PASS] all four node builders and IPv4 Freedom contract';
    else
        echo '  [FAIL] generated node contract';
        rc=1;
    fi;
    declare -f _e170_install_mode | grep -q '_e137_validate_semantic_config' && declare -f _e170_install_mode | grep -q '_e138_warp_config_integrity' && declare -f _e118_write_generated_metadata | grep -q '_e170_write_generated_metadata_impl' && echo '  [PASS] node config/runtime/metadata/WARP gates bind to E170' || { 
        echo '  [FAIL] node transaction binding';
        rc=1
    };
    _e170_optimization_menu_audit > /dev/null && echo '  [PASS] every menu-10 entry is bound' || { 
        echo '  [FAIL] menu-10 handler audit';
        rc=1
    };
    body=$(declare -f _e165_ssh_guard_install_base);
    grep -q 'live-ban-after-final-restart' <<< "$body" && grep -q 'final-readback' <<< "$body" && echo '  [PASS] SSH staged transaction and final live proof' || { 
        echo '  [FAIL] SSH staged gates';
        rc=1
    };
    menu=$(declare -f _e170_main_menu_impl);
    grep -q 'V199e170 - 事务稳态版' <<< "$menu" && grep -q '21) 跨境代理网络参数集合' <<< "$menu" && echo '  [PASS] E127 homepage contract retained' || { 
        echo '  [FAIL] homepage contract';
        rc=1
    };
    hot=$(declare -f _e170_hot_update);
    grep -q '_e170_install_self' <<< "$hot" && grep -q '_e170_ssh_guard_verify_final' <<< "$hot" && grep -q 'E170_HOT_LOG' <<< "$hot" && echo '  [PASS] E170 hot-update identity and final gates' || { 
        echo '  [FAIL] hot-update binding';
        rc=1
    };
    rm -rf -- "$d";
    _e170_structure_audit > /dev/null || rc=1;
    test "$rc" -eq 0 && echo 'V199e170 result: PASS' || echo 'V199e170 result: FAIL';
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e170_show_optimization_status
_e170_show_optimization_status() {
    _e135_show_optimization_status;
    echo;
    echo "  E170持久化控制单元：";
    local unit;
    for unit in xray-init-window-e137.timer xray-offload-e137.timer xray-rps-rfs-e137.timer xray-txqueue-e137.timer xray-ring-e137.timer xray-mss-clamp-e137.timer xray-tc-limit-e95.service;
    do
        printf '    %-36s enabled=%-9s active=%s\n' "$unit" "$(systemctl is-enabled "$unit" 2> /dev/null || echo no)" "$(systemctl is-active "$unit" 2> /dev/null || echo no)";
    done
}
