# EEX3-FUNCTION firewall_warp_e165_188 _e170_structure_audit
_e170_structure_audit() {
    local rc=0 size lines dispatchers menu advanced hot;
    echo 'V199e170 structure audit:';
    size=$(wc -c < "$SCRIPT_PATH" | tr -d ' ');
    lines=$(wc -l < "$SCRIPT_PATH" | tr -d ' ');
    dispatchers=$(grep -c '^# V199e170 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    menu=$(declare -f _e170_main_menu_impl 2> /dev/null || true);
    advanced=$(declare -f _e170_advanced_menu 2> /dev/null || true);
    hot=$(declare -f _e170_hot_update 2> /dev/null || true);
    echo "  file_bytes=$size";
    echo "  lines=$lines";
    echo "  final_dispatchers=$dispatchers";
    echo '  menu_owner=e170 (E127 top-level contract)';
    echo '  network_owner=e159 data model / e170 ordered ipfrag commit';
    echo '  node_owner=e170 identity / Xray survival transaction';
    echo '  ssh_owner=e165 official action / e170 staged verifier';
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    grep -q 'V199e170 - 事务稳态版' <<< "$menu" || rc=1;
    grep -q '_e170_advanced_menu' <<< "$menu" || rc=1;
    grep -q '_e170_run_micro_control_menu' <<< "$advanced" || rc=1;
    grep -q '_e170_install_self' <<< "$hot" || rc=1;
    grep -q '_e170_ssh_guard_verify_final' <<< "$hot" || rc=1;
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL';
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e170_system_paths_base
