# EEX3-FUNCTION firewall_warp_e165_188 _e172_install_mode
_e172_install_mode() {
    local semantic="$1" label="${2:-}" guard rc=0 rollback=0;
    local enabled=0 warp_mode=disabled profile=disabled;
    _e137_mode_internal "$semantic" > /dev/null || { 
        error "未知节点语义编号：$semantic";
        return 1
    };
    label=${label:-$(_e137_mode_name "$semantic")};
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    warp_mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    guard=$(_e116_backup_state before_e172_node_install) || return 1;
    _e118_save_core_payload "$guard" || return 1;
    _e152_install_mode_base "$semantic" "$label" || rc=1;
    if test "$E172_SNI_CANCELLED" -eq 1; then
        _e118_restore_core_payload "$guard" > /dev/null 2>&1 || rollback=1;
        _e118_restore_state "$guard" > /dev/null 2>&1 || rollback=1;
        _e172_restore_warp_after_node_failure "$enabled" "$warp_mode" || rollback=1;
        test "$rollback" -eq 0 || error "取消建仓后的旧状态恢复未完整通过：$guard";
        warn "已取消节点建仓；旧Core、配置、元数据、WARP与服务状态保持。";
        return 0;
    fi;
    test "$rc" -ne 0 || _e137_validate_semantic_config "$CONFIG" "$semantic" || rc=1;
    test "$rc" -ne 0 || _e172_write_version || rc=1;
    test "$rc" -ne 0 || _e172_install_self || rc=1;
    test "$rc" -ne 0 || fix_permissions || rc=1;
    test "$rc" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
    if test "$rc" -eq 0 && test "$enabled" = 1 && test "$warp_mode" != host-full; then
        _e138_warp_config_integrity "$warp_mode" "$profile" || rc=1;
    fi;
    if test "$rc" -ne 0; then
        error "E172节点建仓最终门禁失败，恢复安装前Core、配置、元数据、WARP与服务状态。";
        _e118_restore_core_payload "$guard" > /dev/null 2>&1 || rollback=1;
        _e118_restore_state "$guard" > /dev/null 2>&1 || rollback=1;
        _e172_restore_warp_after_node_failure "$enabled" "$warp_mode" || rollback=1;
        test "$rollback" -eq 0 || error "节点建仓完整回滚未通过：$guard";
        return 1;
    fi;
    info "E172节点建仓已通过协议语义、Xray配置/运行态、版本、自复制与WARP一致性门禁。"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_install_package_no_start
_e172_install_package_no_start() {
    local pkg="$1" cmd="$2" was=0 rc=0;
    command -v "$cmd" > /dev/null 2>&1 && return 0;
    _e135_pkg_present "$pkg" && was=1 || true;
    if command -v apt-get > /dev/null 2>&1 && command -v dpkg-query > /dev/null 2>&1; then
        ( local d policy=/usr/sbin/policy-rc.d tmp;
        d=$(mktemp -d /run/xray-e172-policy.XXXXXX) || exit 1;
        function cleanup () 
        { 
            _e135_restore_file "$policy" "$d/policy" > /dev/null 2>&1 || true;
            rm -rf -- "$d" 2> /dev/null || true
        };
        trap cleanup EXIT INT TERM HUP;
        _e135_snapshot_file "$policy" "$d/policy" || exit 1;
        tmp="$d/policy.new";
        printf '%s\n' '#!/bin/sh' '# E172 package transaction: never start services' 'exit 101' > "$tmp" || exit 1;
        install -m 0755 "$tmp" "$policy" || exit 1;
        pkg_install "$pkg" || exit $?;
        command -v "$cmd" > /dev/null 2>&1 || exit 1 ) || rc=$?;
        hash -r 2> /dev/null || true;
        test "$rc" -eq 0 || return "$rc";
        test "$was" -eq 1 || E135_NEW_PACKAGES+=("$pkg");
        return 0;
    fi;
    _e135_install_package_verified "$pkg" "$cmd"
}
