# EEX3-FUNCTION firewall_warp_e165_188 _e172_install_ssh_guard_lock_base
_e172_install_ssh_guard_lock_base() {
    local lock_fd rc=0;
    _e214_ensure_run_lock || return 1;
    exec {lock_fd}> /run/lock/xray-ssh-guard-e165.lock || return 1;
    if ! flock -w 540 "$lock_fd"; then
        exec {lock_fd}>&-;
        error 'SSH/Fail2ban事务锁等待超过540秒。';
        return 1;
    fi;
    if _e165_ssh_guard_install_base "$@"; then
        rc=0;
    else
        rc=$?;
    fi;
    flock -u "$lock_fd" > /dev/null 2>&1 || true;
    exec {lock_fd}>&-;
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_iptables_write_probe
_e172_iptables_write_probe() {
    ( local chain="XE172P$$_$RANDOM" rc=0;
    chain=${chain:0:27};
    command -v iptables > /dev/null 2>&1 || return 1;
    _e214_ensure_run_lock || return 1;
    exec 172> /run/lock/xray-firewall-capability-e172.lock;
    flock -w 30 172 || return 1;
    function cleanup () 
    { 
        iptables -w 2 -F "$chain" > /dev/null 2>&1 || true;
        iptables -w 2 -X "$chain" > /dev/null 2>&1 || true
    };
    trap cleanup EXIT INT TERM HUP;
    iptables -w 2 -N "$chain" > /dev/null 2>&1 || return 1;
    iptables -w 2 -L "$chain" -n > /dev/null 2>&1 || rc=1;
    cleanup;
    trap - EXIT INT TERM HUP;
    ! iptables -w 2 -L "$chain" -n > /dev/null 2>&1 || rc=1;
    return "$rc" )
}
