# EEX3-FUNCTION firewall_warp_e165_188 _e172_nft_service_contract
_e172_nft_service_contract() {
    local enabled_before="$1" active_before="$2" enabled_after active_after;
    enabled_after=$(systemctl is-enabled nftables.service 2> /dev/null || true);
    active_after=$(systemctl is-active nftables.service 2> /dev/null || true);
    case "$enabled_before" in 
        enabled | enabled-runtime | linked | linked-runtime)
            case "$enabled_after" in 
                enabled | enabled-runtime | linked | linked-runtime)

                ;;
                *)
                    error 'nftables.service启用状态在能力安装期间意外丢失。';
                    return 1
                ;;
            esac
        ;;
        *)
            case "$enabled_after" in 
                enabled | enabled-runtime | linked | linked-runtime)
                    systemctl disable nftables.service > /dev/null 2>&1 || return 1;
                    enabled_after=$(systemctl is-enabled nftables.service 2> /dev/null || true);
                    case "$enabled_after" in 
                        enabled | enabled-runtime | linked | linked-runtime)
                            return 1
                        ;;
                    esac
                ;;
            esac
        ;;
    esac;
    case "$active_before" in 
        active | activating | reloading)
            case "$active_after" in 
                active | activating | reloading)

                ;;
                *)
                    error '原本活动的nftables.service在能力安装期间发生状态漂移。';
                    return 1
                ;;
            esac
        ;;
        *)
            case "$active_after" in 
                active | activating | reloading)
                    error '软件包安装意外启动nftables.service；为避免flush在线规则，不执行盲目stop。';
                    return 1
                ;;
            esac
        ;;
    esac
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_nft_ssh_tx_begin_base
_e172_nft_ssh_tx_begin_base() {
    local tx p key table label;
    tx=$(_e152_new_tx ssh-native-e165) || return 1;
    install -d -m 0700 "$tx/files" || return 1;
    : > "$tx/files.manifest" || return 1;
    while IFS= read -r p; do
        test -n "$p" || continue;
        key=$(printf '%s' "$p" | sha256sum | awk '{print $1}');
        printf '%s|%s\n' "$p" "$key" >> "$tx/files.manifest" || return 1;
        _e135_snapshot_file "$p" "$tx/files/$key" || return 1;
    done < <(_e121_managed_fail2ban_paths | awk 'NF&&!seen[$0]++');
    : > "$tx/services.env" || return 1;
    for p in fail2ban.service xray-ssh-port-guard-e121.service xray-ssh-port-guard-e121.timer xray-ssh-native-e152.service xray-ssh-native-e152.timer xray-ssh-auth-audit-e152.service xray-ssh-auth-audit-e152.timer rsyslog.service;
    do
        _e152_unit_state_line "$p" >> "$tx/services.env" || return 1;
    done;
    while IFS= read -r table; do
        label=$(printf '%s' "$table" | tr -c 'A-Za-z0-9_.-' '_');
        if command -v nft > /dev/null 2>&1 && nft list table inet "$table" > "$tx/$label.nft" 2> /dev/null; then
            : > "$tx/$label.present";
        else
            : > "$tx/$label.absent";
        fi;
    done < <(_e165_nft_tables);
    ( cd "$tx" && find . -type f ! -name ssh-seal.sha256 ! -name COMMITTED -print0 | sort -z | xargs -0 sha256sum > ssh-seal.sha256 ) || return 1;
    test -s "$tx/ssh-seal.sha256" || return 1;
    printf '%s\n' "$tx"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_nft_write_probe
_e172_nft_write_probe() {
    ( local table="xray_e172_probe_$$_$RANDOM" rc=0;
    command -v nft > /dev/null 2>&1 || return 1;
    _e214_ensure_run_lock || return 1;
    exec 172> /run/lock/xray-firewall-capability-e172.lock;
    flock -w 30 172 || return 1;
    function cleanup () 
    { 
        nft delete table inet "$table" > /dev/null 2>&1 || true
    };
    trap cleanup EXIT INT TERM HUP;
    nft add table inet "$table" > /dev/null 2>&1 || return 1;
    nft "add chain inet $table probe_input { type filter hook input priority -1; }" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || nft "add set inet $table probe_addr { type ipv4_addr; }" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || nft list chain inet "$table" probe_input > /dev/null 2>&1 || rc=1;
    cleanup;
    trap - EXIT INT TERM HUP;
    ! nft list table inet "$table" > /dev/null 2>&1 || rc=1;
    return "$rc" )
}
