_e172_quiesce_ssh_managers() {
    local auth_mode="${1:-unknown}" unit;
    local -a timers=(xray-ssh-native-e152.timer xray-ssh-auth-audit-e152.timer xray-ssh-auth-audit-e141w.timer xray-ssh-auth-audit-e142.timer xray-ssh-auth-audit-e143.timer xray-ssh-port-guard-e121.timer);
    local -a audits=(xray-ssh-native-e152.service xray-ssh-auth-audit-e152.service xray-ssh-auth-audit-e141w.service xray-ssh-auth-audit-e142.service xray-ssh-auth-audit-e143.service xray-ssh-port-guard-e121.service);
    for unit in "${timers[@]}";
    do
        systemctl stop "$unit" > /dev/null 2>&1 || true;
    done;
    for unit in "${audits[@]}";
    do
        systemctl stop "$unit" > /dev/null 2>&1 || true;
    done;
    if test "$auth_mode" = password-capable; then
        systemctl stop fail2ban.service > /dev/null 2>&1 || true;
        systemctl is-active --quiet fail2ban.service 2> /dev/null && { 
            error '无法在已快照事务内暂停Fail2ban；拒绝并发改写规则。';
