# EEX3-FUNCTION firewall_warp_e165_188 _e172_remove_package
_e172_remove_package() {
    local pkg="${1:-}" rc=0;
    case "$pkg" in 
        nftables | iptables | fail2ban | python3-systemd | rsyslog | logrotate | qrencode | vnstat)

        ;;
        *)
            return 0
        ;;
    esac;
    _e135_pkg_present "$pkg" || return 0;
    if command -v apt-get > /dev/null 2>&1; then
        apt-get -o DPkg::Lock::Timeout=120 remove -y -- "$pkg" > /dev/null 2>&1 || rc=1;
    else
        if command -v dnf > /dev/null 2>&1; then
            dnf -y remove "$pkg" > /dev/null 2>&1 || rc=1;
        else
            if command -v yum > /dev/null 2>&1; then
                yum -y remove "$pkg" > /dev/null 2>&1 || rc=1;
            else
                rc=1;
            fi;
        fi;
    fi;
    hash -r 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    _e135_pkg_present "$pkg" && rc=1 || true;
    test "$rc" -eq 0 || error "事务新装软件包未能撤销：$pkg";
    return "$rc"
}
