    for unit in xray-init-window-e137.timer xray-offload-e137.timer xray-rps-rfs-e137.timer xray-txqueue-e137.timer xray-ring-e137.timer xray-mss-clamp-e137.timer xray-tc-limit-e95.service;
    do
        printf '    %-36s enabled=%-9s active=%s\n' "$unit" "$(systemctl is-enabled "$unit" 2> /dev/null || echo no)" "$(systemctl is-active "$unit" 2> /dev/null || echo no)";
    done
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_ssh_guard_verify_base
_e172_ssh_guard_verify_base() {
    local profile mode backend;
    profile=$(_e141_sshd_auth_profile 2> /dev/null || true);
    mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1);
    backend=$(_e152_firewall_backend 2> /dev/null || echo none);
    case "$backend:$mode" in 
        nft:password-capable)
            _e152_fail2ban_passive_verify && _e165_helper_check && _e170_fail2ban_live_proof && _e152_nft_ssh_check
        ;;
        nft:key-only | nft:non-password | nft:ambiguous)
            _e152_nft_ssh_check
        ;;
        *:password-capable)
            _e152_fail2ban_passive_verify && _e121_verify_ssh_port_guard
        ;;
        *:key-only | *:non-password | *:ambiguous)
            _e142_verify_key_only_guard
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_ssh_guard_verify_final
_e172_ssh_guard_verify_final() {
    _e182_ssh_guard_verify_final "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_ssh_listener_precheck
_e172_ssh_listener_precheck() {
    local ports="" listening="" current_port="" stale="";
    command -v sshd > /dev/null 2>&1 && sshd -t > /dev/null 2>&1 || { 
        error 'sshd配置语法/命令预检失败。';
        return 1
    };
    ports=$(_e116_detect_ssh_ports 2> /dev/null | sort -nu || true);
    listening=$(_e266_detect_live_ssh_ports 2> /dev/null || true);
    current_port=$(_e135_current_ssh_port 2> /dev/null || true);
    stale=$(_e266_ssh_listener_assess "$ports" "$listening" "$current_port") || { 
        error "SSH配置/会话端口均未命中当前TCP监听集合，拒绝进入防火墙事务。";
        return 1
    };
    test -z "$stale" || warn "SSH配置集合含当前未监听端口：$stale；保留放行但不再误判为事务失败。"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_structure_audit
_e172_structure_audit() {
    local rc=0 size lines dispatchers menu advanced hot ssh ensure quiesce;
    echo 'V199e172 structure audit:';
    size=$(wc -c < "$SCRIPT_PATH" | tr -d ' ');
    lines=$(wc -l < "$SCRIPT_PATH" | tr -d ' ');
    dispatchers=$(grep -c '^# V199e172 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    menu=$(declare -f _e172_main_menu_impl 2> /dev/null || true);
    advanced=$(declare -f _e172_advanced_menu 2> /dev/null || true);
    hot=$(declare -f _e172_hot_update 2> /dev/null || true);
    ssh=$(declare -f _e165_ssh_guard_install_base 2> /dev/null || true);
    ensure=$(declare -f _e172_ensure_firewall_backend 2> /dev/null || true);
    quiesce=$(declare -f _e172_quiesce_ssh_managers 2> /dev/null || true);
    echo "  file_bytes=$size";
    echo "  lines=$lines";
    echo "  final_dispatchers=$dispatchers";
    echo '  menu_owner=e172 (E127 top-level contract)';
    echo '  network_owner=e159 data model / E170 ordered ipfrag transaction';
    echo '  ssh_owner=e172 backend bootstrap + E165 official Fail2Ban action';
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    grep -q 'V199e172 - 事务稳态版' <<< "$menu" || rc=1;
    grep -q '_e172_advanced_menu' <<< "$menu" || rc=1;
    grep -q '_e172_run_micro_control_menu' <<< "$advanced" || rc=1;
    grep -q '_e172_install_self' <<< "$hot" || rc=1;
    grep -q '_e172_ssh_guard_verify_final' <<< "$hot" || rc=1;
    grep -q '_e172_quiesce_ssh_managers' <<< "$ssh" || rc=1;
    grep -q '_e172_install_package_no_start nftables nft' <<< "$ensure" || rc=1;
    grep -q '_e172_nft_service_contract' <<< "$ensure" || rc=1;
    ! grep -Eq 'systemctl (stop|disable).*nftables' <<< "$ensure" || rc=1;
    ! grep -Eq 'systemctl (stop|restart).*\b(xray|ssh|sshd)\b' <<< "$quiesce" || rc=1;
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL';
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_system_paths_base
_e172_system_paths_base() {
    _e170_system_paths_base;
    printf '%s\n' "$E170_DIR" "$E170_SELF_PATH" "$E170_LATEST_PATH"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_tc_menu
_e172_tc_menu() {
    local opt="" iface qdisc enabled active mbit tenable restore conf_iface leaf tx confirm rc;
    _e95_install_tc_component || { 
        error "TC组件生成失败。";
        return 1
    };
    _e168_tc_component_ready || { 
        error "TC生成脚本/服务/配置未通过完整性检查。";
        return 1
    };
    while true; do
        clear;
        title "V199e172：TC 带宽控制（读回验证 / 失败回滚）";
        iface=$(_e95_default_iface 2> /dev/null || true);
        qdisc=$(_e95_root_qdisc_line "$iface");
        enabled=$(systemctl is-enabled xray-tc-limit-e95.service 2> /dev/null || echo disabled);
        active=$(systemctl is-active xray-tc-limit-e95.service 2> /dev/null || echo inactive);
        tenable=$(_e95_tc_current_conf_value TC_ENABLE);
        tenable=${tenable:-0};
        mbit=$(_e95_tc_current_conf_value TC_EGRESS_MBIT);
        restore=$(_e95_tc_current_conf_value TC_RESTORE_QDISC);
        restore=${restore:-fq};
        leaf=$(_e95_tc_current_conf_value TC_LEAF_QDISC);
        leaf=${leaf:-fq};
        conf_iface=$(_e95_tc_current_conf_value TC_IFACE);
        conf_iface=${conf_iface:-auto};
        echo "  默认出口网卡: ${iface:-未知}";
        echo "  当前 root qdisc: ${qdisc:-未读取}";
        echo "  配置: enable=$tenable iface=$conf_iface mbit=${mbit:-未设置} leaf=$leaf restore=$restore";
        echo "  服务: active=$active enabled=$enabled";
        hr;
        echo "  1) 查看TC/qdisc/class/stats";
        echo "  2) 设置出口上限并立即应用";
        echo "  3) 只保存出口上限，不启用";
        echo "  4) 按当前配置立即应用";
        echo "  5) 停止限速并恢复配置的qdisc";
        echo "  6) 开启开机自启（要求有效上限）";
        echo "  7) 关闭开机自启（不改变当前qdisc）";
        echo "  8) 恢复默认并停用e93/e94/e95";
        echo "  9) 查看日志";
        echo " 10) 删除E95组件";
        echo " 11) 查看TC/BBR/fq/cake说明";
        echo "  0) 返回";
        read -rp "操作: " opt || true;
        case "$opt" in 
            1)
                "$E95_TC_SCRIPT" status || true;
                _e116_pause
            ;;
            2)
                tx=$(_e168_tc_tx_begin apply-new) || { 
                    _e116_pause;
                    continue
                };
                rc=0;
                _e95_tc_prompt_conf 1 || rc=1;
                test "$rc" -ne 0 || "$E95_TC_SCRIPT" apply || rc=1;
                test "$rc" -ne 0 || _e168_tc_verify_applied || rc=1;
                if test "$rc" -eq 0; then
                    info "TC新上限已应用并读回。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC应用 || true;
                fi;
                _e116_pause
            ;;
            3)
                tx=$(_e168_tc_tx_begin config-only) || { 
                    _e116_pause;
                    continue
                };
                if _e95_tc_prompt_conf 0 && _e168_tc_conf_valid && test "$(_e95_tc_current_conf_value TC_ENABLE)" = 0; then
                    info "TC配置已保存；没有启用限速。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC配置写入 || true;
                fi;
                _e116_pause
            ;;
            4)
                tx=$(_e168_tc_tx_begin apply-current) || { 
                    _e116_pause;
                    continue
                };
                if _e95_tc_enable_config_inplace && "$E95_TC_SCRIPT" apply && _e168_tc_verify_applied; then
                    info "TC当前配置已应用并读回。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC重放 || true;
                fi;
                _e116_pause
            ;;
            5)
                tx=$(_e168_tc_tx_begin stop) || { 
                    _e116_pause;
                    continue
                };
                if "$E95_TC_SCRIPT" stop && _e168_tc_rewrite_enable 0 && _e168_tc_verify_stopped; then
                    info "TC限速已停止，配置保留为disabled。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC停止 || true;
                fi;
                _e116_pause
            ;;
            6)
                tx=$(_e168_tc_tx_begin enable-boot) || { 
                    _e116_pause;
                    continue
                };
                if _e168_tc_rewrite_enable 1 && systemctl enable xray-tc-limit-e95.service > /dev/null 2>&1 && systemctl is-enabled --quiet xray-tc-limit-e95.service 2> /dev/null; then
                    info "TC开机自启已启用；本操作未改变当前qdisc。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC开机自启 || true;
                fi;
                _e116_pause
            ;;
            7)
                tx=$(_e168_tc_tx_begin disable-boot) || { 
                    _e116_pause;
                    continue
                };
                if systemctl disable xray-tc-limit-e95.service > /dev/null 2>&1 && ! systemctl is-enabled --quiet xray-tc-limit-e95.service 2> /dev/null; then
                    info "TC开机自启已关闭；当前qdisc未改变。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC关闭自启 || true;
                fi;
                _e116_pause
            ;;
            8)
                read -rp "输入 RESET-TC 确认恢复默认: " confirm || true;
                if test "$confirm" = RESET-TC; then
                    tx=$(_e168_tc_tx_begin reset) || { 
                        _e116_pause;
                        continue
                    };
                    rc=0;
                    for v in e95 e94 e93;
                    do
                        systemctl disable --now "xray-tc-limit-${v}.service" > /dev/null 2>&1 || true;
                        test ! -x "/usr/local/bin/xray-tc-limit-${v}.sh" || "/usr/local/bin/xray-tc-limit-${v}.sh" stop > /dev/null 2>&1 || rc=1;
                    done;
                    test "$rc" -ne 0 || _e95_tc_write_conf "" 0 auto fq fq || rc=1;
                    test "$rc" -ne 0 || _e168_tc_verify_stopped || rc=1;
                    if test "$rc" -eq 0; then
                        info "TC已恢复默认并通过读回。";
                        _e168_prune_system_tx "$tx";
                    else
                        _e168_tc_fail "$tx" TC恢复默认 || true;
                    fi;
                else
                    warn "已取消。";
                fi;
                _e116_pause
            ;;
            9)
                tail -n 120 "$E95_TC_LOG" 2> /dev/null || warn "暂无日志：$E95_TC_LOG";
                _e116_pause
            ;;
            10)
                read -rp "输入 DELETE-TC-E95 确认: " confirm || true;
                if test "$confirm" = DELETE-TC-E95; then
                    tx=$(_e168_tc_tx_begin delete) || { 
                        _e116_pause;
                        continue
                    };
                    rc=0;
                    if test -x "$E95_TC_SCRIPT"; then
                        "$E95_TC_SCRIPT" stop > /dev/null 2>&1 || rc=1;
                    fi;
                    test "$rc" -ne 0 || _e168_tc_verify_stopped || rc=1;
                    test "$rc" -ne 0 || systemctl disable --now xray-tc-limit-e95.service > /dev/null 2>&1 || rc=1;
                    test "$rc" -ne 0 || rm -f -- "$E95_TC_SERVICE" "$E95_TC_SCRIPT" "$E95_TC_CONF" || rc=1;
                    test "$rc" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || rc=1;
                    if test "$rc" -eq 0 && test ! -e "$E95_TC_SERVICE" && test ! -e "$E95_TC_SCRIPT" && test ! -e "$E95_TC_CONF" && ! systemctl is-active --quiet xray-tc-limit-e95.service 2> /dev/null && _e168_tc_verify_stopped; then
                        info "E95 TC组件已删除并读回。";
                        _e168_prune_system_tx "$tx";
                    else
                        _e168_tc_fail "$tx" TC组件删除 || true;
                    fi;
                else
                    warn "已取消。";
                fi;
                _e116_pause
            ;;
            11)
                cat <<'EOF_E172_TC_INFO'
TC用于限制出口总带宽，不是提速器。HTB负责总上限，fq/fq_codel作为叶子队列；
启用后实际root qdisc由HTB接管，不能同时把CAKE作为root。BBR仍可在fq叶子上pacing。
建议上限设为晚高峰稳定速度的85%-95%，减少队列和丢包。
EOF_E172_TC_INFO

                _e116_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn "无效操作。"
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION firewall_warp_e165_188 _e172_traffic_monitor
_e172_traffic_monitor() {
    _e135_prepare || return 1;
    local iface n list;
    iface=$(_e135_default_iface);
    test -n "$iface" || { 
        error "无法识别默认出口网卡。";
        return 1
    };
    _e135_vnstat_prepare "$iface" || { 
        error "vnStat初始化失败。";
        return 1
    };
    while true; do
        clear;
        title "V199e172：网络连接审计与流量记账";
        echo "  监控网卡: $iface";
        echo "  说明: vnStat统计整台VPS网卡总流量，不等于Xray独占流量。";
        echo "  1) 今日/本月汇总  2) 实时流量  3) 小时  4) 每日  5) 每月";
        echo "  6) Xray连接与入站端口  7) 数据库健康  8) 选择网卡  9) 设置月结日  0) 返回";
        read -rp "操作: " n || true;
        case "$n" in 
            1)
                vnstat -i "$iface";
                _e135_pause
            ;;
            2)
                vnstat -l -i "$iface" || true;
                _e135_pause
            ;;
            3)
                vnstat -h -i "$iface";
                _e135_pause
            ;;
            4)
                vnstat -d -i "$iface";
                _e135_pause
            ;;
            5)
                vnstat -m -i "$iface";
                _e135_pause
            ;;
            6)
                _e135_xray_connections;
                _e135_pause
            ;;
            7)
                echo "vnStat: $(vnstat --version 2> /dev/null | head -n1)";
                systemctl status vnstat.service --no-pager -n 10 2> /dev/null || systemctl status vnstat --no-pager -n 10 2> /dev/null || true;
                vnstat --iflist 2> /dev/null || true;
                _e135_pause
            ;;
            8)
                list=$(find /sys/class/net -mindepth 1 -maxdepth 1 -printf '%f\n' | grep -v '^lo$');
                printf '%s\n' "$list";
                read -rp "输入网卡名: " iface || true;
                test -d "/sys/class/net/$iface" || { 
                    error "网卡不存在。";
                    iface=$(_e135_default_iface);
                    _e135_pause;
                    continue
                };
                printf '%s\n' "$iface" > "$E135_TRAFFIC_IFACE_FILE";
                _e135_vnstat_prepare "$iface" || true
            ;;
            9)
                _e135_set_month_rotate;
                _e135_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
