# EEX3-FUNCTION firewall_warp_e165_188 _e182_backend_diag
_e182_backend_diag() {
    local result="${1:-unknown}" detail="${2:-none}" selected="${3:-none}" bin;
    install -d -m 0700 "$(dirname "$E182_BACKEND_DIAG")" 2> /dev/null || return 0;
    { 
        echo "time=$(date -Is 2> /dev/null || date)";
        echo "result=$result";
        echo "detail=$detail";
        echo "selected=$selected";
        echo "virt=$(systemd-detect-virt 2> /dev/null || echo unknown)";
        echo "kernel=$(uname -r 2> /dev/null || echo unknown)";
        echo "euid=$EUID";
        echo "cap_eff=$(awk '/^CapEff:/{print $2}' /proc/self/status 2> /dev/null || echo unreadable)";
        echo '--- nft';
        command -v nft 2>&1 || true;
        nft --version 2>&1 || true;
        nft list ruleset 2>&1 | sed -n '1,100p' || true;
        echo '--- xtables variants';
        for bin in iptables iptables-nft iptables-legacy ip6tables ip6tables-nft ip6tables-legacy;
        do
            echo "[$bin]";
            command -v "$bin" 2>&1 || true;
            "$bin" --version 2>&1 || true;
            "$bin" -w 2 -S INPUT 2>&1 | sed -n '1,40p' || true;
        done;
        echo '--- modules';
        grep -E '(^|[[:space:]])(nf_tables|ip_tables|ip6_tables|x_tables)([[:space:]]|$)' /proc/modules 2> /dev/null || true;
        echo '--- sshd native capabilities';
        sshd -T 2> /dev/null | grep -E '^(maxauthtries|logingracetime|maxstartups|persourcemaxstartups|persourcepenalties) ' || true
    } > "$E182_BACKEND_DIAG" 2>&1;
    chmod 0600 "$E182_BACKEND_DIAG" 2> /dev/null || true
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_backend_record
_e182_backend_record() {
    local backend="$1" source="$2" ip_ban="${3:-0}" reason="${4:-none}" tmp;
    case "$backend" in 
        nft | iptables | ufw | firewalld | sshd-native)

        ;;
        *)
            return 1
        ;;
    esac;
    tmp=$(_e182_secure_state_temp "$E182_BACKEND_STATE") || return 1;
    { 
        echo "version=$E182_VERSION";
        echo "preferred_backend=$backend";
        echo "source=$source";
        echo "ip_ban_capable=$ip_ban";
        echo "degraded=$(test "$ip_ban" = 1 && echo 0 || echo 1)";
        echo "reason=$reason";
        echo "iptables_target=$(readlink -f "$(command -v iptables 2> /dev/null)" 2> /dev/null || true)";
        echo "ip6tables_target=$(readlink -f "$(command -v ip6tables 2> /dev/null)" 2> /dev/null || true)";
        echo "nft_service_started=0";
        echo "sshd_stopped=0";
        echo "xray_stopped=0";
        echo "verified=$(date -Is 2> /dev/null || date)"
    } > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    _e182_commit_state "$tmp" "$E182_BACKEND_STATE" || return 1;
    E182_BACKEND_OVERRIDE="$backend";
    E182_BACKEND_PREFLIGHT_VERIFIED=1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_backend_state_get
_e182_backend_state_get() {
    local key="$1" fallback="${2:-}";
    test -s "$E182_BACKEND_STATE" && sed -n "s/^${key}=//p" "$E182_BACKEND_STATE" | tail -n1 || printf '%s\n' "$fallback"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_backend_state_verify
_e182_backend_state_verify() {
    local expected actual;
    test -s "$E182_BACKEND_STATE" || return 1;
    expected=$(_e182_backend_state_get preferred_backend none);
    actual=$(_e152_firewall_backend 2> /dev/null || echo none);
    test "$expected" = "$actual" || return 1;
    grep -qx 'nft_service_started=0' "$E182_BACKEND_STATE" || return 1;
    grep -qx 'sshd_stopped=0' "$E182_BACKEND_STATE" || return 1;
    grep -qx 'xray_stopped=0' "$E182_BACKEND_STATE" || return 1;
    case "$actual" in 
        nft)
            grep -qx 'ip_ban_capable=1' "$E182_BACKEND_STATE" && command -v nft > /dev/null 2>&1 && nft list ruleset > /dev/null 2>&1 && _e172_nft_write_probe
        ;;
        iptables)
            grep -qx 'ip_ban_capable=1' "$E182_BACKEND_STATE" && command -v iptables > /dev/null 2>&1 && iptables -w 2 -S INPUT > /dev/null 2>&1 && _e182_xtables_write_probe iptables && { 
                ! _e182_ipv6_guard_required || _e182_xtables_write_probe ip6tables
            }
        ;;
        ufw)
            grep -qx 'ip_ban_capable=1' "$E182_BACKEND_STATE" && LC_ALL=C ufw status 2> /dev/null | grep -qi '^Status: active'
        ;;
        firewalld)
            grep -qx 'ip_ban_capable=1' "$E182_BACKEND_STATE" && firewall-cmd --state 2> /dev/null | grep -qi running
        ;;
        sshd-native)
            grep -qx 'ip_ban_capable=0' "$E182_BACKEND_STATE" && _e182_native_verify
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_bbr_kernel_menu
_e182_bbr_kernel_menu() {
    local n="" confirm="";
    while true; do
        clear;
        title "V199e182：BBR 本体替换 / 自定义编译中心";
        echo "  1) 查看当前 BBR / qdisc / 模块状态";
        echo "  2) 自动检测 BBR 内置/模块形态与可行路线";
        echo "  3) XanMod 官方包 / 完整源码编译中心";
        echo "  4) 查看内置型 BBR 与模块型 BBR 说明";
        echo -e "  ${yellow}5) 进入旧版实验性 tcp_bbr.ko / 自定义替换中心${none}";
        echo "  0) 返回";
        hr;
        read -rp "请输入操作代码: " n || true;
        case "$n" in 
            1)
                _e89_bbr_status;
                _e116_pause
            ;;
            2)
                _e89_bbr_detect;
                _e116_pause
            ;;
            3)
                _e135_xanmod_menu
            ;;
            4)
                _e102_builtin_explain;
                _e116_pause
            ;;
            5)
                warn "该旧入口可能替换内核模块；源码/内核不匹配会导致网络或启动故障。";
                read -rp "输入 ENABLE-LEGACY-BBR-KO 才继续: " confirm || true;
                test "$confirm" = "ENABLE-LEGACY-BBR-KO" && do_bbr_body_replace_menu_e89 || warn "已取消实验性内核模块操作。"
            ;;
            0)
                return 0
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_check_reexport
_e182_check_reexport() {
    title "V199e182：检查配置并重新输出节点";
    test -s "$CONFIG" || { 
        error "config.json 不存在。";
        return 1
    };
    _e118_xray_test_config "$CONFIG" 1 || return 1;
    _e138_warp_reconcile || return 1;
    fix_xray_systemd_limits || return 1;
    if systemctl is-active --quiet xray.service 2> /dev/null; then
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1;
    else
        warn "Xray原本处于停止状态：配置已通过静态检查，未擅自启动服务。";
    fi;
    do_summary
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_choose_sni_base
_e182_choose_sni_base() {
    if _e172_choose_sni_base "$@"; then
        E172_SNI_CANCELLED=0;
        return 0;
    fi;
    E172_SNI_CANCELLED=1;
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_commit_state
_e182_commit_state() {
    local tmp="$1" dest="$2" mode="${3:-0600}";
    test -f "$tmp" && test -n "$dest" || return 1;
    chmod "$mode" "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -f -- "$tmp" "$dest" || { 
        rm -f -- "$tmp";
        return 1
    };
    chmod "$mode" "$dest" || return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_disable_legacy_tx
_e182_disable_legacy_tx() {
    _e172_disable_legacy_tx "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_disable_managed_f2b_jail_native
_e182_disable_managed_f2b_jail_native() {
    local tmp running=0;
    if ! command -v fail2ban-client > /dev/null 2>&1 && test ! -e "$E121_F2B_JAIL"; then
        rm -f -- "$E182_NATIVE_F2B_DISABLE" "$E182_PREVIOUS_NATIVE_F2B_DISABLE" "$E182_OLDER_NATIVE_F2B_DISABLE" "$E182_LEGACY_NATIVE_F2B_DISABLE" 2> /dev/null || true;
        return 0;
    fi;
    _e214_ensure_parent_dir "$E182_NATIVE_F2B_DISABLE" || return 1;
    tmp=$(mktemp /run/xray-e182-f2b-disable.XXXXXX) || return 1;
    { 
        echo "[$E121_F2B_JAIL_NAME]";
        echo 'enabled = false';
        echo '# E182: kernel firewall unavailable; do not claim a working ban action.'
    } > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    _e121_atomic_install "$tmp" "$E182_NATIVE_F2B_DISABLE" 0644 || { 
        rm -f -- "$tmp";
        return 1
    };
    rm -f -- "$tmp";
    rm -f -- "$E182_PREVIOUS_NATIVE_F2B_DISABLE" "$E182_OLDER_NATIVE_F2B_DISABLE" "$E182_LEGACY_NATIVE_F2B_DISABLE" || return 1;
    if command -v fail2ban-client > /dev/null 2>&1 && fail2ban-client status "$E121_F2B_JAIL_NAME" > /dev/null 2>&1; then
        running=1;
        fail2ban-client stop "$E121_F2B_JAIL_NAME" > /dev/null 2>&1 || true;
    fi;
    if test "$running" -eq 1; then
        if fail2ban-client status "$E121_F2B_JAIL_NAME" > /dev/null 2>&1; then
            fail2ban-client set "$E121_F2B_JAIL_NAME" idle on > /dev/null 2>&1 || true;
            warn "脚本所属Fail2ban jail仍在旧进程中运行；已持久禁用，未重启全局Fail2ban，也未影响其它jail。";
        fi;
    fi;
    return 0
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_enable_managed_f2b_jail_firewall
_e182_enable_managed_f2b_jail_firewall() {
    rm -f -- "$E182_NATIVE_F2B_DISABLE" "$E182_PREVIOUS_NATIVE_F2B_DISABLE" "$E182_OLDER_NATIVE_F2B_DISABLE" "$E182_LEGACY_NATIVE_F2B_DISABLE" 2> /dev/null || return 1;
    if command -v fail2ban-client > /dev/null 2>&1 && fail2ban-client status "$E121_F2B_JAIL_NAME" > /dev/null 2>&1; then
        fail2ban-client set "$E121_F2B_JAIL_NAME" idle off > /dev/null 2>&1 || true;
    fi
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ensure_firewall_backend
_e182_ensure_firewall_backend() {
    local backend selected nft_enabled_before nft_active_before nft_contract_ok=1;
    local before_count=${#E135_NEW_PACKAGES[@]};
    backend=$(_e182_firewall_detector_base 2> /dev/null || echo none);
    case "$backend" in 
        ufw | firewalld)
            _e182_backend_record "$backend" active-manager 1 none || return 1;
            _e182_backend_diag pass active-manager "$backend";
            info "SSH防护沿用活动防火墙管理器：$backend。";
            return 0
        ;;
        nft)
            if _e172_nft_write_probe; then
                _e182_backend_record nft existing-nft 1 none || return 1;
                _e182_backend_diag pass existing-nft nft;
                info '已验证原生nftables临时表、输入hook与集合写入能力。';
                return 0;
            fi
        ;;
        iptables)
            if selected=$(_e182_try_xtables_matrix); then
                _e182_backend_record iptables "existing-$selected" 1 none || return 1;
                _e182_backend_diag pass "existing-$selected" iptables;
                info "已验证xtables后端：$selected。";
                return 0;
            fi
        ;;
    esac;
    nft_enabled_before=$(systemctl is-enabled nftables.service 2> /dev/null || true);
    nft_active_before=$(systemctl is-active nftables.service 2> /dev/null || true);
    command -v nft > /dev/null 2>&1 || _e172_install_package_no_start nftables nft || true;
    hash -r 2> /dev/null || true;
    _e172_nft_service_contract "$nft_enabled_before" "$nft_active_before" || { 
        nft_contract_ok=0;
        warn 'nftables软件包服务状态发生漂移；不采用该后端，继续测试xtables/OpenSSH。'
    };
    modprobe nf_tables > /dev/null 2>&1 || true;
    if test "$nft_contract_ok" -eq 1 && command -v nft > /dev/null 2>&1 && nft list ruleset > /dev/null 2>&1 && _e172_nft_write_probe; then
        _e182_backend_record nft auto-installed-nft 1 none || return 1;
        _e182_backend_diag pass auto-installed-nft nft;
        info '已安装并验证nftables能力；未启动或加载nftables.service。';
        return 0;
    fi;
    command -v iptables > /dev/null 2>&1 || _e172_install_package_no_start iptables iptables || true;
    hash -r 2> /dev/null || true;
    modprobe ip_tables > /dev/null 2>&1 || true;
    modprobe ip6_tables > /dev/null 2>&1 || true;
    if selected=$(_e182_try_xtables_matrix); then
        _e182_backend_record iptables "auto-$selected" 1 none || return 1;
        _e182_backend_diag pass "auto-$selected" iptables;
        info "nft不可写；已验证并选择xtables后端：$selected。";
        return 0;
    fi;
    _e182_backend_record sshd-native no-netfilter-write 0 cap-net-admin-or-kernel || return 1;
    _e182_backend_diag degraded no-netfilter-write sshd-native;
    _e172_remove_packages_since "$before_count" || { 
        error '防火墙能力探测失败后，事务新装软件包未能完整撤销。';
        return 1
    };
    warn 'nft、iptables-nft与iptables-legacy均不可写；切换到OpenSSH原生限流/审计模式。';
    warn "该模式不能宣称按IP防火墙封禁；完整诊断：$E182_BACKEND_DIAG";
    return 0
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_firewall_detector_base
_e182_firewall_detector_base() {
    local detected preferred="${E172_BACKEND_OVERRIDE:-}";
    detected=$(_e172_firewall_backend_base 2> /dev/null || echo none);
    case "$detected" in 
        ufw | firewalld)
            echo "$detected";
            return 0
        ;;
    esac;
    if test -z "$preferred" && test -s "$E172_BACKEND_STATE"; then
        preferred=$(sed -n 's/^preferred_backend=//p' "$E172_BACKEND_STATE" | tail -n1);
    fi;
    case "$preferred" in 
        nft)
            command -v nft > /dev/null 2>&1 && nft list ruleset > /dev/null 2>&1 && { 
                echo nft;
                return 0
            }
        ;;
        iptables)
            command -v iptables > /dev/null 2>&1 && iptables -w 2 -S INPUT > /dev/null 2>&1 && { 
                echo iptables;
                return 0
            }
        ;;
        ufw | firewalld)

        ;;
    esac;
    echo "$detected"
}
