# EEX3-FUNCTION firewall_warp_e165_188 _e182_install_mode_base
_e182_install_mode_base() {
    local semantic="$1" label="${2:-}" guard rc=0 rollback=0;
    local enabled=0 warp_mode=disabled profile=disabled;
    _e137_mode_internal "$semantic" > /dev/null || { 
        error "未知节点语义编号：$semantic";
        return 1
    };
    label=${label:-$(_e137_mode_name "$semantic")};
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    warp_mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    guard=$(_e116_backup_state before_e182_node_install) || return 1;
    _e118_save_core_payload "$guard" || return 1;
    _e152_install_mode_base "$semantic" "$label" || rc=1;
    if test "$E182_SNI_CANCELLED" -eq 1; then
        _e118_restore_core_payload "$guard" > /dev/null 2>&1 || rollback=1;
        _e118_restore_state "$guard" > /dev/null 2>&1 || rollback=1;
        _e182_restore_warp_after_node_failure "$enabled" "$warp_mode" || rollback=1;
        test "$rollback" -eq 0 || error "取消建仓后的旧状态恢复未完整通过：$guard";
        warn "已取消节点建仓；旧Core、配置、元数据、WARP与服务状态保持。";
        return 0;
    fi;
    test "$rc" -ne 0 || _e137_validate_semantic_config "$CONFIG" "$semantic" || rc=1;
    test "$rc" -ne 0 || _e182_write_version || rc=1;
    test "$rc" -ne 0 || _e182_install_self || rc=1;
    test "$rc" -ne 0 || fix_permissions || rc=1;
    test "$rc" -ne 0 || _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
    if test "$rc" -eq 0 && test "$enabled" = 1 && test "$warp_mode" != host-full; then
        _e138_warp_config_integrity "$warp_mode" "$profile" || rc=1;
    fi;
    if test "$rc" -ne 0; then
        error "E182节点建仓最终门禁失败，恢复安装前Core、配置、元数据、WARP与服务状态。";
        _e118_restore_core_payload "$guard" > /dev/null 2>&1 || rollback=1;
        _e118_restore_state "$guard" > /dev/null 2>&1 || rollback=1;
        _e182_restore_warp_after_node_failure "$enabled" "$warp_mode" || rollback=1;
        test "$rollback" -eq 0 || error "节点建仓完整回滚未通过：$guard";
        return 1;
    fi;
    info "E182节点建仓已通过协议语义、Xray配置/运行态、版本、自复制与WARP一致性门禁。"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_install_native_guard
_e182_install_native_guard() {
    local outer_tx tx profile auth_mode dump current_auth current_grace;
    local current_starts new_auth new_grace new_starts;
    local per_current="" per_new="" settings location rc=0;
    outer_tx="${1:-}";
    tx="$outer_tx";
    test -n "$tx" || { 
        tx=$(_e182_new_tx ssh-native-throttle) || return 1;
        _e140_system_snapshot "$tx" || return 1
    };
    profile=$(_e141_sshd_auth_profile 2> /dev/null || true);
    auth_mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1);
    test -n "$auth_mode" || auth_mode=unknown;
    _e172_quiesce_ssh_managers "$auth_mode" || rc=1;
    dump=$(sshd -T 2> /dev/null) || rc=1;
    if test "$rc" -eq 0; then
        current_auth=$(awk '$1=="maxauthtries"{print $2;exit}' <<< "$dump");
        current_grace=$(awk '$1=="logingracetime"{print $2;exit}' <<< "$dump");
        current_starts=$(awk '$1=="maxstartups"{print $2;exit}' <<< "$dump");
        [[ "$current_auth" =~ ^[0-9]+$ ]] || current_auth=6;
        [[ "$current_grace" =~ ^[0-9]+$ ]] || current_grace=120;
        (( current_auth > 0 && current_auth < 3 )) && new_auth=$current_auth || new_auth=3;
        (( current_grace > 0 && current_grace < 30 )) && new_grace=$current_grace || new_grace=30;
        new_starts=$(_e182_tighten_maxstartups "$current_starts") || rc=1;
        per_current=$(awk '$1=="persourcemaxstartups"{print $2;exit}' <<< "$dump");
        if [[ "$per_current" =~ ^[0-9]+$ ]]; then
            (( per_current > 0 && per_current < 3 )) && per_new=$per_current || per_new=3;
        else
            if test "$per_current" = none; then
                per_new=3;
            fi;
        fi;
        settings=$(mktemp /run/xray-e182-native.XXXXXX) || rc=1;
    fi;
    if test "$rc" -eq 0; then
        { 
            echo '# Managed by ex199e182.sh; does not disable password authentication.';
            echo "MaxAuthTries $new_auth";
            echo "LoginGraceTime $new_grace";
            echo "MaxStartups $new_starts";
            test -z "$per_new" || echo "PerSourceMaxStartups $per_new"
        } > "$settings" || rc=1;
    fi;
    if test "$rc" -eq 0; then
        location=$(_e182_write_native_settings "$settings" "$new_auth" "$new_grace" "$new_starts" "$per_new") || rc=1;
    fi;
    rm -f -- "${settings:-}" 2> /dev/null || true;
    test "$rc" -ne 0 || _e182_sshd_reload_safe || rc=1;
    if test "$rc" -eq 0; then
        systemctl disable --now xray-ssh-port-guard-e121.timer xray-ssh-port-guard-e121.service xray-ssh-native-e152.timer xray-ssh-native-e152.service > /dev/null 2>&1 || true;
        _e182_disable_managed_f2b_jail_native || rc=1;
    fi;
    if test "$rc" -eq 0; then
        _e152_install_ssh_auth_audit || rc=1;
    fi;
    test "$rc" -ne 0 || _e172_retire_legacy_ssh_audits || rc=1;
    test "$rc" -ne 0 || _e182_native_state_write native-throttle "$new_auth" "$new_grace" "$new_starts" "${per_new:-none}" "$location" "$tx" || rc=1;
    test "$rc" -ne 0 || _e182_auth_state_write_native || rc=1;
    test "$rc" -ne 0 || _e182_native_verify || rc=1;
    if test "$rc" -eq 0; then
        info "E182 OpenSSH原生限流已验证：auth=$auth_mode MaxAuthTries=$new_auth LoginGraceTime=$new_grace MaxStartups=$new_starts PerSourceMaxStartups=${per_new:-unsupported}。";
        warn '当前VPS没有netfilter写权限，因此没有声称Fail2ban可执行IP封禁。';
        return 0;
    fi;
    error 'OpenSSH原生限流事务未通过，恢复旧sshd配置和服务状态。';
    if ! _e140_system_restore "$tx" > /dev/null 2>&1 || ! _e182_sshd_reload_safe > /dev/null 2>&1; then
        install -d -m 0700 "${E182_DIR:-$CONFIG_DIR/e182}" 2> /dev/null || true;
        { 
            echo "time=$(date -Is 2> /dev/null || date)";
            echo 'operation=ssh-native-rollback';
            echo "backup=$tx";
            echo "auth_mode=$auth_mode"
        } > "${E182_CRITICAL_MARKER:-$CONFIG_DIR/e182/CRITICAL_RECOVERY_REQUIRED.env}" 2> /dev/null || true;
        error "严重：OpenSSH限流提交和回滚均未通过；保留快照：$tx";
        return 1;
    fi;
    _e182_install_audit_only "$tx"
}
