}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_apply
_e182_ipv6_apply() {
    local desired="$1" source="${2:-menu}" hot="${3:-0}" override="${4:-}" token="";
    if test "$desired" = 1 && ! _e204_ipv4_management_viable; then
        case "$source" in 
            hot-update | install | node-install)
                _e204_ipv6_pending_write no-viable-ipv4-management || return 1;
                warn '主机没有可验证的IPv4管理路径；默认关闭IPv6已暂缓，避免IPv6-only VPS失联。';
                return 0
            ;;
            menu)
                warn '主机没有可验证的IPv4默认路由/源地址；关闭IPv6可能令VPS完全失联。';
                read -rp '若已有VNC/串口控制台，输入 DISABLE-IPV6-WITHOUT-IPV4 继续: ' token || true;
                test "$token" = DISABLE-IPV6-WITHOUT-IPV4 || return 2
            ;;
            *)
                if test "$override" != DISABLE-IPV6-WITHOUT-IPV4 && test "${XRAY_E204_ALLOW_IPV6_ONLY_DISABLE:-0}" != 1; then
                    error '拒绝在无IPv4管理路径时关闭IPv6；请从菜单25二次确认或传入安全覆盖令牌。';
                    return 2;
                fi
            ;;
        esac;
    fi;
    _e204_ipv6_apply_base "$desired" "$source" "$hot"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_apply_default
_e182_ipv6_apply_default() {
    local source="${1:-install}" desired;
    desired=$(_e182_ipv6_policy_desired) || return 1;
    if test "$desired" = 1 && _e182_ipv6_live_ssh_session; then
        _e182_ipv6_pending_write || return 1;
        warn '默认IPv6关闭已因当前IPv6 SSH会话暂缓；请从IPv4 SSH/控制台执行菜单25。';
        return 0;
    fi;
    _e182_ipv6_apply "$desired" "$source" 0
}
