        return 1
    };
    _e182_commit_state "$tmp" "$E182_IPV6_PENDING"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_policy_desired
_e182_ipv6_policy_desired() {
    local desired;
    desired=$(_e182_ipv6_state_get desired_disable_ipv6 '');
    case "$desired" in 
        0 | 1)
            printf '%s\n' "$desired";
            return
        ;;
    esac;
    desired=$(sed -n 's/^[[:space:]]*net\.ipv6\.conf\.all\.disable_ipv6[[:space:]]*=[[:space:]]*\([01]\)[[:space:]]*$/\1/p' "$E182_IPV6_CONF" 2> /dev/null | tail -n1);
    case "$desired" in 
        0 | 1)
            printf '%s\n' "$desired"
        ;;
        *)
            echo 1
        ;;
    esac
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_recover_stale_serialized
_e182_ipv6_recover_stale_serialized() {
    ( test -s "$E182_IPV6_HOT_MARKER" || return 0;
    _e214_ensure_run_lock || return 1;
    exec 183> /run/lock/xray-ipv6-policy-e182.lock;
    flock -w 30 183 || { 
        error '另一个IPv6策略事务正在运行，无法恢复中断事务。';
        return 1
    };
    _e182_ipv6_hot_recover_stale )
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_runtime_capture
_e182_ipv6_runtime_capture() {
    local out="$1" f value;
    : > "$out" || return 1;
    chmod 0600 "$out" || return 1;
    if test ! -d "$E182_IPV6_PROC_ROOT"; then
        echo 'kernel-unavailable|1' > "$out";
        return 0;
    fi;
    for f in "$E182_IPV6_PROC_ROOT"/*/disable_ipv6;
    do
        test -e "$f" || continue;
        value=$(cat "$f" 2> /dev/null) || return 1;
        case "$value" in 
            0 | 1)

            ;;
            *)
                return 1
            ;;
        esac;
        printf '%s|%s\n' "$f" "$value" >> "$out" || return 1;
    done;
    test -s "$out"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_runtime_restore
_e182_ipv6_runtime_restore() {
    local snap="$1" path value rc=0;
    test -s "$snap" || return 1;
    grep -qx 'kernel-unavailable|1' "$snap" 2> /dev/null && return 0;
    while IFS='|' read -r path value; do
        case "$path" in 
            "$E182_IPV6_PROC_ROOT"/*/disable_ipv6)

            ;;
            *)
                rc=1;
                continue
            ;;
        esac;
        case "$value" in 
            0 | 1)

            ;;
            *)
                rc=1;
                continue
            ;;
        esac;
        test -e "$path" || continue;
        printf '%s\n' "$value" > "$path" 2> /dev/null || rc=1;
    done < "$snap";
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_runtime_set
_e182_ipv6_runtime_set() {
    local desired="$1" f current rc=0;
    case "$desired" in 
        0 | 1)

        ;;
        *)
            return 1
        ;;
    esac;
    test -d "$E182_IPV6_PROC_ROOT" || { 
        test "$desired" = 1;
        return
    };
    for f in "$E182_IPV6_PROC_ROOT/default/disable_ipv6" "$E182_IPV6_PROC_ROOT/all/disable_ipv6" "$E182_IPV6_PROC_ROOT"/*/disable_ipv6;
    do
        test -e "$f" || continue;
        current=$(cat "$f" 2> /dev/null || true);
        test "$current" = "$desired" || printf '%s\n' "$desired" > "$f" 2> /dev/null || rc=1;
    done;
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_state_get
_e182_ipv6_state_get() {
    local key="$1" fallback="${2:-}";
    test -s "$E182_IPV6_STATE" && sed -n "s/^${key}=//p" "$E182_IPV6_STATE" | tail -n1 || printf '%s\n' "$fallback"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_ipv6_state_write
_e182_ipv6_state_write() {
    local mode="$1" desired="$2" tx="$3" initial="$4" source="$5" tmp;
    case "$mode" in 
        enabled | disabled | kernel-disabled)

        ;;
        *)
            return 1
        ;;
    esac;
    case "$desired" in 
        0 | 1)

        ;;
        *)
            return 1
        ;;
    esac;
    tmp=$(_e182_secure_state_temp "$E182_IPV6_STATE") || return 1;
    { 
        echo "version=$E182_VERSION";
        echo "mode=$mode";
        echo "desired_disable_ipv6=$desired";
        echo "transaction=$tx";
        echo "initial_transaction=$initial";
        echo "source=$source";
        echo "persistent_conf=$E182_IPV6_CONF";
        echo "checked_at=$(date -Is 2> /dev/null || date)"
