# EEX3-FUNCTION firewall_warp_e165_188 _e182_managed_f2b_runtime_state
_e182_managed_f2b_runtime_state() {
    if ! command -v fail2ban-client > /dev/null 2>&1; then
        echo unavailable;
    else
        if fail2ban-client status "$E121_F2B_JAIL_NAME" > /dev/null 2>&1; then
            echo active;
        else
            echo inactive;
        fi;
    fi
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_micro_control_menu
_e182_micro_control_menu() {
    _e204_micro_control_menu "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_mss_action
_e182_mss_action() {
    _e172_mss_action "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_native_effective_values
_e182_native_effective_values() {
    sshd -T 2> /dev/null | awk '
      $1=="maxauthtries" || $1=="logingracetime" || $1=="maxstartups" ||
      $1=="persourcemaxstartups" || $1=="persourcepenalties" {print}'
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_native_state_write
_e182_native_state_write() {
    local mode="$1" auth="${2:-none}" grace="${3:-none}" starts="${4:-none}";
    local per="${5:-none}" location="${6:-none}" tx="${7:-none}" tmp jail_runtime;
    jail_runtime=$(_e182_managed_f2b_runtime_state);
    tmp=$(_e182_secure_state_temp "$E182_NATIVE_STATE") || return 1;
    { 
        echo "version=$E182_VERSION";
        echo "mode=$mode";
        echo "ip_ban_capable=0";
        echo "maxauthtries=$auth";
        echo "logingracetime=$grace";
        echo "maxstartups=$starts";
        echo "persourcemaxstartups=$per";
        echo "location=$location";
        echo "transaction=$tx";
        echo "managed_jail_runtime=$jail_runtime";
        echo "checked_at=$(date -Is 2> /dev/null || date)"
    } > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    _e182_commit_state "$tmp" "$E182_NATIVE_STATE"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_native_values_verify
_e182_native_values_verify() {
    local auth="$1" grace="$2" starts="$3" per="${4:-}" dump;
    dump=$(_e182_native_effective_values) || return 1;
    grep -qx "maxauthtries $auth" <<< "$dump" || return 1;
    grep -qx "logingracetime $grace" <<< "$dump" || return 1;
    grep -qx "maxstartups $starts" <<< "$dump" || return 1;
    test -z "$per" || grep -qx "persourcemaxstartups $per" <<< "$dump"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_native_verify
_e182_native_verify() {
    local mode auth grace starts per backend;
    test -s "$E182_NATIVE_STATE" || return 1;
    mode=$(sed -n 's/^mode=//p' "$E182_NATIVE_STATE" | tail -n1);
    backend=$(_e182_backend_state_get preferred_backend none);
    test "$backend" = sshd-native || return 1;
    grep -qx 'ip_ban_capable=0' "$E182_NATIVE_STATE" || return 1;
    sshd -t > /dev/null 2>&1 || return 1;
    _e172_ssh_listener_precheck || return 1;
