# EEX3-FUNCTION firewall_warp_e165_188 _e182_ssh_auth_reconcile_base
_e182_ssh_auth_reconcile_base() {
    local profile mode backend healthy=0;
    profile=$(_e141_sshd_auth_profile 2> /dev/null || true);
    mode=$(sed -n 's/^mode=//p' <<< "$profile" | head -n1);
    backend=$(_e152_firewall_backend 2> /dev/null || echo none);
    if test "$backend" = nft; then
        _e152_nft_ssh_check > /dev/null 2>&1 && healthy=1 || true;
    else
        case "$mode" in 
            key-only | non-password)
                _e142_verify_key_only_guard > /dev/null 2>&1 && healthy=1 || true
            ;;
            password-capable)
                _e152_fail2ban_passive_verify > /dev/null 2>&1 && _e121_verify_ssh_port_guard > /dev/null 2>&1 && healthy=1 || true
            ;;
            ambiguous)
                _e142_verify_key_only_guard > /dev/null 2>&1 && healthy=1 || true
            ;;
        esac;
    fi;
    test "$healthy" -eq 1 && return 0;
    warn "SSH/Fail2ban运行态发生漂移，执行一次完整事务修复。";
    _e141_install_ssh_guard
}
