# EEX3-FUNCTION firewall_warp_e165_188 _e182_sshd_reload_safe
_e182_sshd_reload_safe() {
    local pid need_hup=0;
    sshd -t > /dev/null 2>&1 || return 1;
    if systemctl is-active --quiet ssh.service 2> /dev/null; then
        systemctl reload ssh.service > /dev/null 2>&1 || need_hup=1;
    else
        if systemctl is-active --quiet sshd.service 2> /dev/null; then
            systemctl reload sshd.service > /dev/null 2>&1 || need_hup=1;
        else
            if systemctl is-active --quiet ssh.socket 2> /dev/null || systemctl is-active --quiet sshd.socket 2> /dev/null; then
                :;
            else
                need_hup=1;
            fi;
        fi;
    fi;
    if test "$need_hup" -eq 1; then
        pid=$(ss -H -ltnp 2> /dev/null | sed -n 's/.*"sshd",pid=\([0-9][0-9]*\).*/\1/p' | head -n1);
        [[ "$pid" =~ ^[0-9]+$ ]] || return 1;
        test "$(cat "/proc/$pid/comm" 2> /dev/null || true)" = sshd || return 1;
        kill -HUP "$pid" > /dev/null 2>&1 || return 1;
        sleep 1;
    fi;
    _e172_ssh_listener_precheck
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_strip_main_native_block
_e182_strip_main_native_block() {
    local src="$1" dst="$2";
    awk -v b="$E182_NATIVE_MAIN_BEGIN" -v e="$E182_NATIVE_MAIN_END" -v pb="$E182_PREVIOUS_NATIVE_MAIN_BEGIN" -v pe="$E182_PREVIOUS_NATIVE_MAIN_END" -v ob="$E182_OLDER_NATIVE_MAIN_BEGIN" -v oe="$E182_OLDER_NATIVE_MAIN_END" -v lb="$E182_LEGACY_NATIVE_MAIN_BEGIN" -v le="$E182_LEGACY_NATIVE_MAIN_END" '
      $0==b  {if(skip) exit 2; skip="current"; next}
      $0==pb {if(skip) exit 2; skip="previous"; next}
      $0==ob {if(skip) exit 2; skip="older"; next}
      $0==lb {if(skip) exit 2; skip="legacy"; next}
      $0==e  {if(skip!="current") exit 2; skip=""; next}
      $0==pe {if(skip!="previous") exit 2; skip=""; next}
      $0==oe {if(skip!="older") exit 2; skip=""; next}
      $0==le {if(skip!="legacy") exit 2; skip=""; next}
      !skip {print}
      END {if(skip) exit 2}
    ' "$src" > "$dst"
}
