# EEX3-FUNCTION firewall_warp_e165_188 _e182_switch_xtables_variant
_e182_switch_xtables_variant() {
    local candidate="$1" variant old4 old6 target4 target6 rc=0;
    case "$candidate" in 
        iptables-nft)
            variant=nft
        ;;
        iptables-legacy)
