    old4=$(readlink /etc/alternatives/iptables 2> /dev/null || readlink -f "$(command -v iptables 2> /dev/null)" 2> /dev/null || true);
    old6=$(readlink /etc/alternatives/ip6tables 2> /dev/null || readlink -f "$(command -v ip6tables 2> /dev/null)" 2> /dev/null || true);
    if command -v update-alternatives > /dev/null 2>&1; then
        update-alternatives --set iptables "$target4" > /dev/null 2>&1 || rc=1;
        if test "$rc" -eq 0 && test -n "$target6"; then
            update-alternatives --set ip6tables "$target6" > /dev/null 2>&1 || rc=1;
        fi;
    else
        if command -v alternatives > /dev/null 2>&1; then
            alternatives --set iptables "$target4" > /dev/null 2>&1 || rc=1;
            if test "$rc" -eq 0 && test -n "$target6"; then
                alternatives --set ip6tables "$target6" > /dev/null 2>&1 || rc=1;
            fi;
        else
            return 1;
        fi;
    fi;
    hash -r 2> /dev/null || true;
    test "$rc" -ne 0 || _e182_xtables_write_probe iptables || rc=1;
    if test "$rc" -eq 0 && _e182_ipv6_guard_required; then
        _e182_xtables_write_probe ip6tables || rc=1;
    fi;
    if test "$rc" -ne 0; then
        if command -v update-alternatives > /dev/null 2>&1; then
            test -z "$old4" || update-alternatives --set iptables "$old4" > /dev/null 2>&1 || true;
            test -z "$old6" || update-alternatives --set ip6tables "$old6" > /dev/null 2>&1 || true;
        else
            if command -v alternatives > /dev/null 2>&1; then
                test -z "$old4" || alternatives --set iptables "$old4" > /dev/null 2>&1 || true;
                test -z "$old6" || alternatives --set ip6tables "$old6" > /dev/null 2>&1 || true;
            fi;
        fi;
        hash -r 2> /dev/null || true;
        return 1;
    fi;
    return 0
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_system_paths_base
_e182_system_paths_base() {
    _e172_system_paths_base;
    printf '%s\n' "$E172_DIR" "$E172_SELF_PATH" "$E172_LATEST_PATH" "$E172_BACKEND_STATE" /etc/nftables.conf /etc/sysconfig/nftables.conf
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_tc_menu
_e182_tc_menu() {
    local opt="" iface qdisc enabled active mbit tenable restore conf_iface leaf tx confirm rc;
    _e95_install_tc_component || { 
        error "TC组件生成失败。";
        return 1
    };
    _e168_tc_component_ready || { 
        error "TC生成脚本/服务/配置未通过完整性检查。";
        return 1
    };
    while true; do
        clear;
        title "V199e182：TC 带宽控制（读回验证 / 失败回滚）";
        iface=$(_e95_default_iface 2> /dev/null || true);
        qdisc=$(_e95_root_qdisc_line "$iface");
        enabled=$(systemctl is-enabled xray-tc-limit-e95.service 2> /dev/null || echo disabled);
        active=$(systemctl is-active xray-tc-limit-e95.service 2> /dev/null || echo inactive);
        tenable=$(_e95_tc_current_conf_value TC_ENABLE);
        tenable=${tenable:-0};
        mbit=$(_e95_tc_current_conf_value TC_EGRESS_MBIT);
        restore=$(_e95_tc_current_conf_value TC_RESTORE_QDISC);
        restore=${restore:-fq};
        leaf=$(_e95_tc_current_conf_value TC_LEAF_QDISC);
        leaf=${leaf:-fq};
        conf_iface=$(_e95_tc_current_conf_value TC_IFACE);
        conf_iface=${conf_iface:-auto};
        echo "  默认出口网卡: ${iface:-未知}";
        echo "  当前 root qdisc: ${qdisc:-未读取}";
        echo "  配置: enable=$tenable iface=$conf_iface mbit=${mbit:-未设置} leaf=$leaf restore=$restore";
        echo "  服务: active=$active enabled=$enabled";
        hr;
        echo "  1) 查看TC/qdisc/class/stats";
        echo "  2) 设置出口上限并立即应用";
        echo "  3) 只保存出口上限，不启用";
        echo "  4) 按当前配置立即应用";
        echo "  5) 停止限速并恢复配置的qdisc";
        echo "  6) 开启开机自启（要求有效上限）";
        echo "  7) 关闭开机自启（不改变当前qdisc）";
        echo "  8) 恢复默认并停用e93/e94/e95";
        echo "  9) 查看日志";
        echo " 10) 删除E95组件";
        echo " 11) 查看TC/BBR/fq/cake说明";
        echo "  0) 返回";
        read -rp "操作: " opt || true;
        case "$opt" in 
            1)
                "$E95_TC_SCRIPT" status || true;
                _e116_pause
            ;;
            2)
                tx=$(_e168_tc_tx_begin apply-new) || { 
                    _e116_pause;
                    continue
                };
                rc=0;
                _e95_tc_prompt_conf 1 || rc=1;
                test "$rc" -ne 0 || "$E95_TC_SCRIPT" apply || rc=1;
                test "$rc" -ne 0 || _e168_tc_verify_applied || rc=1;
                if test "$rc" -eq 0; then
                    info "TC新上限已应用并读回。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC应用 || true;
                fi;
                _e116_pause
            ;;
            3)
                tx=$(_e168_tc_tx_begin config-only) || { 
                    _e116_pause;
                    continue
                };
                if _e95_tc_prompt_conf 0 && _e168_tc_conf_valid && test "$(_e95_tc_current_conf_value TC_ENABLE)" = 0; then
                    info "TC配置已保存；没有启用限速。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC配置写入 || true;
                fi;
                _e116_pause
            ;;
            4)
                tx=$(_e168_tc_tx_begin apply-current) || { 
                    _e116_pause;
                    continue
                };
                if _e95_tc_enable_config_inplace && "$E95_TC_SCRIPT" apply && _e168_tc_verify_applied; then
                    info "TC当前配置已应用并读回。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC重放 || true;
                fi;
                _e116_pause
            ;;
            5)
                tx=$(_e168_tc_tx_begin stop) || { 
                    _e116_pause;
                    continue
                };
                if "$E95_TC_SCRIPT" stop && _e168_tc_rewrite_enable 0 && _e168_tc_verify_stopped; then
                    info "TC限速已停止，配置保留为disabled。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC停止 || true;
                fi;
                _e116_pause
            ;;
            6)
                tx=$(_e168_tc_tx_begin enable-boot) || { 
                    _e116_pause;
                    continue
                };
                if _e168_tc_rewrite_enable 1 && systemctl enable xray-tc-limit-e95.service > /dev/null 2>&1 && systemctl is-enabled --quiet xray-tc-limit-e95.service 2> /dev/null; then
                    info "TC开机自启已启用；本操作未改变当前qdisc。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC开机自启 || true;
                fi;
                _e116_pause
            ;;
            7)
                tx=$(_e168_tc_tx_begin disable-boot) || { 
                    _e116_pause;
                    continue
                };
                if systemctl disable xray-tc-limit-e95.service > /dev/null 2>&1 && ! systemctl is-enabled --quiet xray-tc-limit-e95.service 2> /dev/null; then
                    info "TC开机自启已关闭；当前qdisc未改变。";
                    _e168_prune_system_tx "$tx";
                else
                    _e168_tc_fail "$tx" TC关闭自启 || true;
                fi;
                _e116_pause
            ;;
            8)
                read -rp "输入 RESET-TC 确认恢复默认: " confirm || true;
                if test "$confirm" = RESET-TC; then
                    tx=$(_e168_tc_tx_begin reset) || { 
                        _e116_pause;
                        continue
                    };
                    rc=0;
                    for v in e95 e94 e93;
                    do
                        systemctl disable --now "xray-tc-limit-${v}.service" > /dev/null 2>&1 || true;
                        test ! -x "/usr/local/bin/xray-tc-limit-${v}.sh" || "/usr/local/bin/xray-tc-limit-${v}.sh" stop > /dev/null 2>&1 || rc=1;
                    done;
                    test "$rc" -ne 0 || _e95_tc_write_conf "" 0 auto fq fq || rc=1;
                    test "$rc" -ne 0 || _e168_tc_verify_stopped || rc=1;
                    if test "$rc" -eq 0; then
                        info "TC已恢复默认并通过读回。";
                        _e168_prune_system_tx "$tx";
                    else
                        _e168_tc_fail "$tx" TC恢复默认 || true;
                    fi;
                else
                    warn "已取消。";
                fi;
                _e116_pause
            ;;
            9)
                tail -n 120 "$E95_TC_LOG" 2> /dev/null || warn "暂无日志：$E95_TC_LOG";
                _e116_pause
            ;;
            10)
                read -rp "输入 DELETE-TC-E95 确认: " confirm || true;
                if test "$confirm" = DELETE-TC-E95; then
                    tx=$(_e168_tc_tx_begin delete) || { 
                        _e116_pause;
                        continue
                    };
                    rc=0;
                    if test -x "$E95_TC_SCRIPT"; then
                        "$E95_TC_SCRIPT" stop > /dev/null 2>&1 || rc=1;
                    fi;
                    test "$rc" -ne 0 || _e168_tc_verify_stopped || rc=1;
                    test "$rc" -ne 0 || systemctl disable --now xray-tc-limit-e95.service > /dev/null 2>&1 || rc=1;
                    test "$rc" -ne 0 || rm -f -- "$E95_TC_SERVICE" "$E95_TC_SCRIPT" "$E95_TC_CONF" || rc=1;
                    test "$rc" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || rc=1;
                    if test "$rc" -eq 0 && test ! -e "$E95_TC_SERVICE" && test ! -e "$E95_TC_SCRIPT" && test ! -e "$E95_TC_CONF" && ! systemctl is-active --quiet xray-tc-limit-e95.service 2> /dev/null && _e168_tc_verify_stopped; then
                        info "E95 TC组件已删除并读回。";
                        _e168_prune_system_tx "$tx";
                    else
                        _e168_tc_fail "$tx" TC组件删除 || true;
                    fi;
                else
                    warn "已取消。";
                fi;
                _e116_pause
            ;;
            11)
                cat <<'EOF_E182_TC_INFO'
TC用于限制出口总带宽，不是提速器。HTB负责总上限，fq/fq_codel作为叶子队列；
启用后实际root qdisc由HTB接管，不能同时把CAKE作为root。BBR仍可在fq叶子上pacing。
建议上限设为晚高峰稳定速度的85%-95%，减少队列和丢包。
EOF_E182_TC_INFO

                _e116_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn "无效操作。"
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_tighten_maxstartups
_e182_tighten_maxstartups() {
    local current="$1" s r f new_s new_r new_f;
    IFS=: read -r s r f <<< "$current";
    [[ "$s" =~ ^[0-9]+$ ]] || s=10;
    [[ "$r" =~ ^[0-9]+$ ]] || r=30;
    [[ "$f" =~ ^[0-9]+$ ]] || f=100;
    (( s < 10 )) && new_s=$s || new_s=10;
    (( r > 30 )) && new_r=$r || new_r=30;
    (( f < 60 )) && new_f=$f || new_f=60;
    (( new_f < new_s )) && new_f=$new_s;
    printf '%s:%s:%s\n' "$new_s" "$new_r" "$new_f"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_traffic_monitor
_e182_traffic_monitor() {
    _e135_prepare || return 1;
    local iface n list;
    iface=$(_e135_default_iface);
    test -n "$iface" || { 
        error "无法识别默认出口网卡。";
        return 1
    };
    _e135_vnstat_prepare "$iface" || { 
        error "vnStat初始化失败。";
        return 1
    };
    while true; do
        clear;
        title "V199e182：网络连接审计与流量记账";
        echo "  监控网卡: $iface";
        echo "  说明: vnStat统计整台VPS网卡总流量，不等于Xray独占流量。";
        echo "  1) 今日/本月汇总  2) 实时流量  3) 小时  4) 每日  5) 每月";
        echo "  6) Xray连接与入站端口  7) 数据库健康  8) 选择网卡  9) 设置月结日  0) 返回";
        read -rp "操作: " n || true;
        case "$n" in 
            1)
                vnstat -i "$iface";
                _e135_pause
            ;;
            2)
                vnstat -l -i "$iface" || true;
                _e135_pause
            ;;
            3)
                vnstat -h -i "$iface";
                _e135_pause
            ;;
            4)
                vnstat -d -i "$iface";
                _e135_pause
            ;;
            5)
                vnstat -m -i "$iface";
                _e135_pause
            ;;
            6)
                _e135_xray_connections;
                _e135_pause
            ;;
            7)
                echo "vnStat: $(vnstat --version 2> /dev/null | head -n1)";
                systemctl status vnstat.service --no-pager -n 10 2> /dev/null || systemctl status vnstat --no-pager -n 10 2> /dev/null || true;
                vnstat --iflist 2> /dev/null || true;
                _e135_pause
            ;;
            8)
                list=$(find /sys/class/net -mindepth 1 -maxdepth 1 -printf '%f\n' | grep -v '^lo$');
                printf '%s\n' "$list";
                read -rp "输入网卡名: " iface || true;
                test -d "/sys/class/net/$iface" || { 
                    error "网卡不存在。";
                    iface=$(_e135_default_iface);
                    _e135_pause;
                    continue
                };
                printf '%s\n' "$iface" > "$E135_TRAFFIC_IFACE_FILE";
                _e135_vnstat_prepare "$iface" || true
            ;;
            9)
                _e135_set_month_rotate;
                _e135_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn "无效操作。";
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_try_xtables_matrix
_e182_try_xtables_matrix() {
    local candidate v6 selected="";
    for candidate in iptables iptables-legacy iptables-nft;
    do
        command -v "$candidate" > /dev/null 2>&1 || continue;
        _e182_xtables_write_probe "$candidate" || continue;
        if _e182_ipv6_guard_required; then
            case "$candidate" in 
                iptables)
                    v6=ip6tables
                ;;
                iptables-legacy)
                    v6=ip6tables-legacy
                ;;
                iptables-nft)
                    v6=ip6tables-nft
                ;;
            esac;
            command -v "$v6" > /dev/null 2>&1 && _e182_xtables_write_probe "$v6" || continue;
        fi;
        if test "$candidate" != iptables; then
            _e182_switch_xtables_variant "$candidate" || continue;
        fi;
        _e182_xtables_write_probe iptables || continue;
        selected="$candidate";
        break;
    done;
    test -n "$selected" || return 1;
    printf '%s\n' "$selected"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_txq_action
_e182_txq_action() {
    _e172_txq_action "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_uninstall_base
_e182_uninstall_base() {
    local rc=0;
    _e172_uninstall_base "$@" || rc=$?;
    if test "$rc" -eq 0 && test ! -e "$XRAY_BIN" && test ! -e "$CONFIG"; then
        rm -f -- "$E172_SELF_PATH" "$E172_LATEST_PATH" 2> /dev/null || true;
        rm -rf -- "$E172_DIR" 2> /dev/null || true;
    fi;
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_write_generated_metadata_impl
_e182_write_generated_metadata_impl() {
    _e214_write_generated_metadata_impl "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_write_native_settings
_e182_write_native_settings() {
    local settings="$1" auth="$2" grace="$3" starts="$4" per="${5:-}";
    local d clean main_tmp main_mode;
    install -d -m 0755 /etc/ssh/sshd_config.d || return 1;
    d=$(mktemp -d /run/xray-e182-sshd.XXXXXX) || return 1;
    clean="$d/sshd.clean";
    main_tmp="$d/sshd.new";
    _e182_strip_main_native_block /etc/ssh/sshd_config "$clean" || { 
        rm -rf -- "$d";
        return 1
    };
    main_mode=$(stat -c '%a' /etc/ssh/sshd_config 2> /dev/null || echo 600);
    [[ "$main_mode" =~ ^[0-7]{3,4}$ ]] || main_mode=600;
    rm -f -- "$E182_PREVIOUS_NATIVE_DROPIN" "$E182_OLDER_NATIVE_DROPIN" "$E182_LEGACY_NATIVE_DROPIN" || { 
        rm -rf -- "$d";
        return 1
    };
    if ! cmp -s "$clean" /etc/ssh/sshd_config; then
        _e118_atomic_install "$clean" /etc/ssh/sshd_config "$main_mode" || { 
            rm -rf -- "$d";
            return 1
        };
    fi;
    _e118_atomic_install "$settings" "$E182_NATIVE_DROPIN" 0644 || { 
        rm -rf -- "$d";
        return 1
    };
    if sshd -t > /dev/null 2>&1 && _e182_native_values_verify "$auth" "$grace" "$starts" "$per"; then
        rm -rf -- "$d";
        printf '%s\n' dropin;
        return 0;
    fi;
    rm -f -- "$E182_NATIVE_DROPIN" || { 
        rm -rf -- "$d";
        return 1
    };
    { 
        echo "$E182_NATIVE_MAIN_BEGIN";
        cat "$settings";
        echo "$E182_NATIVE_MAIN_END";
        cat "$clean"
    } > "$main_tmp" || { 
        rm -rf -- "$d";
        return 1
    };
    _e118_atomic_install "$main_tmp" /etc/ssh/sshd_config "$main_mode" || { 
        rm -rf -- "$d";
        return 1
    };
    rm -rf -- "$d";
    sshd -t > /dev/null 2>&1 && _e182_native_values_verify "$auth" "$grace" "$starts" "$per" && { 
        printf '%s\n' main-prefix;
        return 0
    };
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_write_version
_e182_write_version() {
    _e214_write_version "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e182_xtables_write_probe
_e182_xtables_write_probe() {
    ( local bin="$1" chain="XE182P$$_$RANDOM" rc=0;
    chain=${chain:0:27};
    command -v "$bin" > /dev/null 2>&1 || return 1;
    _e214_ensure_run_lock || return 1;
    exec 176> /run/lock/xray-xtables-capability-e182.lock;
    flock -w 30 176 || return 1;
    function cleanup () 
    { 
        "$bin" -w 3 -F "$chain" > /dev/null 2>&1 || true;
        "$bin" -w 3 -X "$chain" > /dev/null 2>&1 || true
    };
    trap cleanup EXIT INT TERM HUP;
    "$bin" -w 3 -N "$chain" > /dev/null 2>&1 || return 1;
    "$bin" -w 3 -L "$chain" -n > /dev/null 2>&1 || rc=1;
    cleanup;
    trap - EXIT INT TERM HUP;
    ! "$bin" -w 3 -L "$chain" -n > /dev/null 2>&1 || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION firewall_warp_e165_188 _e183_dns_strategy
_e183_dns_strategy() {
    case "$(_e183_warp_family_normalize "${1:-ipv4}")" in 
        ipv4)
            echo UseIPv4
        ;;
        ipv6)
            echo UseIPv6
        ;;
        dual)
            echo UseIP
        ;;
        *)
            echo UseIPv4
        ;;
    esac
}
# EEX3-FUNCTION firewall_warp_e165_188 _e183_ensure_qrencode
_e183_ensure_qrencode() {
    if command -v qrencode > /dev/null 2>&1 && qrencode --version > /dev/null 2>&1; then
        return 0;
    fi;
    test "$EUID" -eq 0 || { 
        warn 'qrencode不可用，且当前不是root，无法自动安装。';
        return 1
    };
    if declare -F _e135_install_package_verified > /dev/null 2>&1; then
        _e135_install_package_verified qrencode qrencode > /dev/null 2>&1 || true;
    else
        if command -v apt-get > /dev/null 2>&1; then
            DEBIAN_FRONTEND=noninteractive apt-get update -y > /dev/null 2>&1 || true;
            DEBIAN_FRONTEND=noninteractive apt-get install -y qrencode > /dev/null 2>&1 || true;
        fi;
    fi;
    hash -r 2> /dev/null || true;
    command -v qrencode > /dev/null 2>&1 && qrencode --version > /dev/null 2>&1
}
