# EEX3-FUNCTION firewall_warp_e165_188 _e183_hot_step
_e183_hot_step() {
    local phase="$1";
    shift;
    _e159_phase_log "$E183_HOT_LOG" "$phase" begin;
    if "$@"; then
        _e159_phase_log "$E183_HOT_LOG" "$phase" ok;
        return 0;
    fi;
    _e159_phase_log "$E183_HOT_LOG" "$phase" fail;
    error "E183热更新失败阶段：$phase";
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e183_hot_update
_e183_hot_update() {
    ( local protect="" sysbackup="" network_tx="" ssh_tx="" rc=0 rollback_rc=0 was_active=0;
    local enabled=0 mode=disabled profile=disabled phase=start auth_mode="";
    local effective_active=0 effective_persistent=0 unsupported=0 shadowed=0 trigger=0;
    _e214_ensure_run_lock || return 1;
    exec 183> /run/lock/xray-e183-hot-update.lock;
    flock -n 183 || { 
        error '已有另一个E183热更新正在运行。';
        return 1
    };
    : > "$E183_HOT_LOG" || return 1;
    E135_NEW_PACKAGES=();
