    test "$rc" -ne 0 || _e183_hot_step self-install _e183_install_self || rc=1;
    test "$rc" -ne 0 || _e183_hot_step dat-install install_update_dat || rc=1;
    test "$rc" -ne 0 || _e183_hot_step dat-timer systemctl enable --now xray-dat-update.timer || rc=1;
    test "$rc" -ne 0 || _e183_hot_step core-auto-update-off _e105_disable_xray_core_auto_update || rc=1;
    test "$rc" -ne 0 || _e183_hot_step init-window _e137_apply_init_window_default30 || rc=1;
    if test "$rc" -eq 0; then
        E159_DEFER_HOST_FULL_VERIFY=1;
        _e183_hot_step network-e159-stable-owner _e159_network_apply fq 1 31 force || rc=1;
