            test "$rc" -ne 0 || _e183_hot_step warp-health _e138_warp_health_install || rc=1;
        fi;
    fi;
    test "$rc" -ne 0 || _e183_hot_step version-write _e183_write_version || rc=1;
    if test "$rc" -eq 0; then
        phase=verify;
        _e159_phase_log "$E183_HOT_LOG" "$phase" begin;
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1 || rc=1;
