# EEX3-FUNCTION firewall_warp_e165_188 _e183_new_tx
_e183_new_tx() {
    local name="${1:-transaction}" dir;
    _e183_prepare || return 1;
    dir="$E183_TX_ROOT/${name}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM";
    install -d -m 0700 "$dir" || return 1;
    printf '%s\n' "$dir"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e183_png_valid
_e183_png_valid() {
    local file="$1" sig;
    test -s "$file" || return 1;
    sig=$(od -An -tx1 -N8 "$file" 2> /dev/null | tr -d ' \n');
    test "$sig" = 89504e470d0a1a0a
}
# EEX3-FUNCTION firewall_warp_e165_188 _e183_prepare
_e183_prepare() {
