}
# EEX3-FUNCTION firewall_warp_e165_188 _e183_self_test
_e183_self_test() {
    local rc=0 d family strategy out;
    echo 'V199e183 fast release gate:';
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' || { 
        echo '  [FAIL] bash syntax';
        rc=1
    };
    test "$SCRIPT_VERSION" = 199e183 && test "$E183_VERSION" = 199e183 && echo '  [PASS] release identity' || { 
        echo '  [FAIL] release identity';
        rc=1
    };
    d=$(mktemp -d /tmp/e183-selftest.XXXXXX) || return 1;
    cat > "$d/base.json" <<'EOF_E183_TEST_JSON'
{"dns":{"servers":["1.1.1.1"],"queryStrategy":"UseIPv4"},"outbounds":[{"tag":"direct","protocol":"freedom","settings":{"domainStrategy":"UseIPv4"}},{"tag":"block","protocol":"blackhole"}],"routing":{"domainStrategy":"AsIs","rules":[]}}
EOF_E183_TEST_JSON

    for family in ipv4 ipv6 dual;
    do
        out="$d/$family.json";
        _e138_warp_config_build global global true "$out" "$d/base.json" "$family" || rc=1;
        strategy=$(_e183_warp_strategy "$family");
        jq -e --arg w "$E138_WARP_GLOBAL_TAG" --arg s "$E183_WARP_GLOBAL_SOCKS_TAG" --arg st "$strategy" 'any(.outbounds[]?;.tag==$s and .protocol=="socks") and any(.outbounds[]?;.tag==$w and .settings.domainStrategy==$st and .proxySettings.tag==$s)' "$out" > /dev/null 2>&1 || rc=1;
    done;
    test "$rc" -ne 0 || echo '  [PASS] IPv4/IPv6/dual WARP config generation';
    grep -q 'qrencode -l L' <<< "$(declare -f _e135_emit_qr)" && grep -q '_e183_png_valid' <<< "$(declare -f _e135_emit_qr)" && echo '  [PASS] QR terminal/PNG/SVG pipeline' || { 
        echo '  [FAIL] QR pipeline';
        rc=1
    };
    grep -q '_e140_warp_service_wait' <<< "$(declare -f _e183_warp_connect_local_proxy)" && grep -q 'seq 1 75' <<< "$(declare -f _e183_warp_connect_local_proxy)" && echo '  [PASS] WARP convergence and route guard' || { 
        echo '  [FAIL] WARP convergence';
        rc=1
    };
    grep -q '_e182_traffic_monitor' <<< "$(declare -f _e183_main_menu_impl)" && grep -q '_e182_ipv6_menu' <<< "$(declare -f _e183_main_menu_impl)" && ! grep -q '_e183_traffic_monitor' <<< "$(declare -f _e183_main_menu_impl)" && echo '  [PASS] final menu handlers resolve to inherited E182 owners' || { 
        echo '  [FAIL] final menu handler binding';
        rc=1
    };
    grep -q '_e183_warp_full_status_base' <<< "$(declare -f _e183_warp_status)" && echo '  [PASS] host-full status recursion guard' || { 
        echo '  [FAIL] host-full status recursion guard';
        rc=1
    };
    rm -rf -- "$d";
    _e183_structure_audit > /dev/null || rc=1;
    test "$rc" -eq 0 && echo 'V199e183 result: PASS' || echo 'V199e183 result: FAIL';
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e183_structure_audit
_e183_structure_audit() {
    local rc=0 size lines dispatchers menu warp qr hot f;
    echo 'V199e183 structure audit:';
    size=$(wc -c < "$SCRIPT_PATH" | tr -d ' ');
    lines=$(wc -l < "$SCRIPT_PATH" | tr -d ' ');
    dispatchers=$(grep -c '^# V199e183 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    menu=$(declare -f _e183_main_menu_impl 2> /dev/null || true);
    warp=$(declare -f _e183_warp_connect_local_proxy 2> /dev/null || true);
    qr=$(declare -f _e135_emit_qr 2> /dev/null || true);
    hot=$(declare -f _e183_hot_update 2> /dev/null || true);
    echo "  file_bytes=$size";
    echo "  lines=$lines";
    echo "  final_dispatchers=$dispatchers";
    echo '  warp_owner=e183 (MASQUE local proxy + 75s convergence + family selector)';
    echo '  qr_owner=e183 (terminal + atomic PNG/SVG + diagnostics)';
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    grep -q 'V199e183 - 事务稳态版' <<< "$menu" || rc=1;
    for f in do_install do_user_manager do_summary _e182_traffic_monitor _e182_advanced_menu _e182_network_params_menu _e182_check_reexport _e182_bbr_kernel_menu _e182_security_center _e182_ipv6_menu _e138_warp_global_menu;
    do
        declare -F "$f" > /dev/null 2>&1 || { 
            echo "  missing_menu_handler=$f";
            rc=1
        };
    done;
    grep -q '_e182_traffic_monitor' <<< "$menu" || rc=1;
    grep -q '_e182_ipv6_menu' <<< "$menu" || rc=1;
    grep -q 'seq 1 75' <<< "$warp" || rc=1;
    grep -q 'warp-local-last.log' <<< "$(declare -p E183_WARP_DIAG 2> /dev/null || true)" || rc=1;
    grep -q 'UTF8i' <<< "$qr" && grep -q 'SVG' <<< "$qr" || rc=1;
    grep -q '_e183_install_self' <<< "$hot" && grep -q 'qr-runtime' <<< "$hot" || rc=1;
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL';
    return "$rc"
}
