# EEX3-FUNCTION firewall_warp_e165_188 _e183_warp_capture_diag
_e183_warp_capture_diag() {
    local reason="${1:-unknown}" svc;
    svc=$(_e136_warp_service_name);
    install -d -m 0700 "$(dirname "$E183_WARP_DIAG")" 2> /dev/null || true;
    { 
        echo "time=$(date -Is 2> /dev/null || date)";
        echo "reason=$reason";
        echo "port=$E138_WARP_PORT";
        echo '--- warp-cli version ---';
        _e183_warp_cli_capture --version 2>&1 || true;
        echo '--- warp-cli status ---';
        _e183_warp_cli_capture status 2>&1 || true;
        echo '--- warp-cli settings ---';
        _e183_warp_cli_capture settings 2>&1 || true;
        echo '--- registration ---';
        _e183_warp_cli_capture registration show 2>&1 || true;
        echo '--- listeners ---';
        ss -H -lntp4 2>&1 | grep -E "(:|])${E138_WARP_PORT}([[:space:]]|$)" || true;
        echo '--- route guard ---';
        _e136_route_guard_snapshot 2>&1 || true;
        echo '--- direct IPv4 ---';
        _e136_direct_ipv4 2>&1 || true;
        echo '--- proxy trace ---';
        _e136_warp_trace 2>&1 || true;
        echo '--- service ---';
        systemctl status "$svc" --no-pager 2>&1 || true;
        echo '--- journal ---';
        journalctl -u "$svc" -n 180 --no-pager 2>&1 || true
    } > "$E183_WARP_DIAG" 2>&1;
    chmod 0600 "$E183_WARP_DIAG" 2> /dev/null || true
}
