# EEX3-FUNCTION firewall_warp_e165_188 _e183_warp_migrate_state_base
_e183_warp_migrate_state_base() {
    local old enabled=0 mode=disabled profile=disabled;
    _e139_prepare || return 1;
    test -s "$E139_WARP_STATE" && return 0;
    for old in "$E138_WARP_STATE" "$E137_WARP_STATE" "${E136_WARP_STATE:-/nonexistent}";
    do
        test -s "$old" || continue;
        enabled=$(sed -n 's/^route_enabled=//p' "$old" | tail -n1);
        enabled=${enabled:-0};
        mode=$(sed -n 's/^route_mode=//p' "$old" | tail -n1);
        mode=${mode:-selective};
        profile=$(sed -n 's/^profile=//p' "$old" | tail -n1);
        profile=${profile:-disabled};
        break;
    done;
    test "$enabled" = 1 || { 
        mode=disabled;
        profile=disabled
    };
    _e138_state_write "$enabled" "$mode" "$profile"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e183_warp_mode_is_proxy
_e183_warp_mode_is_proxy() {
