# EEX3-FUNCTION firewall_warp_e165_188 _e185_backend_normalize
_e185_backend_normalize() {
    case "${1:-auto}" in 
        auto)
            echo auto
        ;;
        masque | local | official | proxy)
            echo masque
        ;;
        xray-wg | wireguard | wg | native-wg)
            echo xray-wg
        ;;
