# EEX3-FUNCTION firewall_warp_e165_188 _e185_capture_backend_diag
_e185_capture_backend_diag() {
    local reason="${1:-unknown}" backend="${2:-unknown}" family="${3:-unknown}";
    _e185_prepare > /dev/null 2>&1 || true;
    { 
        echo "time=$(date -Is 2> /dev/null || date)";
        echo "reason=$reason";
        echo "backend=$backend";
        echo "family=$family";
        echo '--- interpretation ---';
        case "$reason" in 
            masque-ingress-udp-timeout)
                echo 'Official Local proxy requires MASQUE. IPv4 MASQUE ingress UDP attempts timed out.';
                echo 'The IPv6 NetworkUnreachable entries are secondary on an IPv4-only host.'
            ;;
            wireguard-ingress-udp-unreachable)
                echo 'Xray-native WARP WireGuard probes failed on the tested Cloudflare ingress ports.';
                echo 'The provider, host firewall or upstream network likely blocks all usable WARP UDP transport.'
            ;;
        esac;
        echo '--- current state ---';
        cat "$E138_WARP_STATE" 2> /dev/null || true;
        echo '--- endpoint state ---';
        cat "$E185_WG_ENDPOINT_STATE" 2> /dev/null || true;
        echo '--- route guard ---';
        _e136_route_guard_snapshot 2>&1 || true;
        echo '--- direct IPv4 ---';
        _e136_direct_ipv4 2>&1 || true;
        echo '--- E183 MASQUE diagnostics tail ---';
        tail -n 260 "$E183_WARP_DIAG" 2> /dev/null || true;
        echo '--- E185 WireGuard diagnostics tail ---';
        tail -n 260 "$E185_WG_LOG" 2> /dev/null || true
    } > "$E185_WARP_DIAG" 2>&1;
    chmod 0600 "$E185_WARP_DIAG" 2> /dev/null || true
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_confirm_wgcf_fallback
_e185_confirm_wgcf_fallback() {
    local token="";
    if test "${E185_ACCEPT_WGCF_FALLBACK:-0}" = 1; then
        return 0;
    fi;
    warn '官方Local proxy只能使用MASQUE；当前MASQUE入口不可达。';
    warn 'E185可改用Xray内置WireGuard WARP，不改VPS默认路由；注册工具wgcf为非Cloudflare官方开源工具。';
    read -rp '输入 ENABLE-WARP-XRAY-WG-FALLBACK 确认: ' token || true;
    test "$token" = ENABLE-WARP-XRAY-WG-FALLBACK
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_endpoint_host_port
_e185_endpoint_host_port() {
    local endpoint="$1" host port;
    if [[ "$endpoint" =~ ^\[([^]]+)\]:([0-9]+)$ ]]; then
        host="${BASH_REMATCH[1]}";
        port="${BASH_REMATCH[2]}";
    else
        if [[ "$endpoint" =~ ^([^:]+):([0-9]+)$ ]]; then
            host="${BASH_REMATCH[1]}";
            port="${BASH_REMATCH[2]}";
        else
            return 1;
        fi;
    fi;
    printf '%s %s\n' "$host" "$port"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_family_normalize
_e185_family_normalize() {
    _e183_warp_family_normalize "${1:-ipv4}"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_find_probe_port
_e185_find_probe_port() {
    local p;
    for p in $(seq "$E185_WG_PROBE_PORT_BASE" $((E185_WG_PROBE_PORT_BASE+30)));
    do
        ss -H -lnt 2> /dev/null | awk '{print $4}' | grep -Eq "(^|:|\])${p}$" || { 
            echo "$p";
            return 0
        };
    done;
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_force_backend_menu
_e185_force_backend_menu() {
    local backend="$1" mode="$2" profile="$3" n;
    while true; do
        echo "  1) IPv4目标";
        echo "  2) IPv6目标";
        echo "  3) IPv4+IPv6目标（IPv4优先）";
        echo "  0) 返回";
        read -rp '地址族: ' n || true;
        case "$n" in 
            1)
                _e138_warp_enable "$mode" "$profile" ipv4 "$backend";
                return
            ;;
            2)
                _e138_warp_enable "$mode" "$profile" ipv6 "$backend";
                return
            ;;
            3)
                _e138_warp_enable "$mode" "$profile" dual "$backend";
                return
            ;;
            0)
                return
            ;;
            *)
                warn '无效操作。'
            ;;
        esac;
    done
}
