# EEX3-FUNCTION firewall_warp_e165_188 _e185_host_route_guard_snapshot
_e185_host_route_guard_snapshot() {
    { 
        echo '[route4]';
        ip -4 route show table main 2> /dev/null || true;
        echo '[rule4]';
        ip -4 rule show 2> /dev/null || true;
        echo '[route6]';
        ip -6 route show table main 2> /dev/null || true;
        echo '[rule6]';
        ip -6 rule show 2> /dev/null || true;
        echo '[ssh-route]';
        if test -n "${SSH_CONNECTION:-}"; then
            ip route get "${SSH_CONNECTION%% *}" 2> /dev/null || true;
        fi
    } | sed -E 's/[[:space:]]+/ /g'
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_hot_step
_e185_hot_step() {
    local phase="$1";
    shift;
    _e159_phase_log "$E185_HOT_LOG" "$phase" begin;
    if "$@"; then
        _e159_phase_log "$E185_HOT_LOG" "$phase" ok;
        return 0;
    fi;
    _e159_phase_log "$E185_HOT_LOG" "$phase" fail;
    error "E185热更新失败阶段：$phase";
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_hot_update
_e185_hot_update() {
    ( local protect="" sysbackup="" network_tx="" ssh_tx="" rc=0 rollback_rc=0 was_active=0;
    local enabled=0 mode=disabled profile=disabled phase=start auth_mode="";
    local effective_active=0 effective_persistent=0 unsupported=0 shadowed=0 trigger=0;
    _e214_ensure_run_lock || return 1;
    exec 185> /run/lock/xray-e185-hot-update.lock;
    flock -n 185 || { 
        error '已有另一个E185热更新正在运行。';
        return 1
    };
    : > "$E185_HOT_LOG" || return 1;
    E135_NEW_PACKAGES=();
    _e159_phase_log "$E185_HOT_LOG" start begin "$SCRIPT_PATH";
    _e182_prepare || return 1;
    phase=xray-snapshot;
    protect=$(_e116_backup_state before_hot_update_e185) || rc=1;
    test "$rc" -ne 0 || _e118_save_core_payload "$protect" || rc=1;
    if test "$rc" -eq 0; then
        was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
        was_active=${was_active:-0};
        _e159_phase_log "$E185_HOT_LOG" "$phase" ok "$protect";
    fi;
    if test "$rc" -eq 0; then
        phase=system-snapshot;
        sysbackup=$(_e185_new_tx hot-update) || rc=1;
        test "$rc" -ne 0 || _e140_system_snapshot "$sysbackup" || rc=1;
        test "$rc" -ne 0 || _e159_phase_log "$E185_HOT_LOG" "$phase" ok "$sysbackup";
    fi;
    test "$rc" -ne 0 || _e185_hot_step ipv6-policy _e182_ipv6_hot_apply_default || rc=1;
    test "$rc" -ne 0 || _e185_hot_step firewall-capability _e182_ensure_firewall_backend || rc=1;
    test "$rc" -ne 0 || _e185_hot_step warp-state-migrate _e138_warp_migrate_state || rc=1;
    test "$rc" -ne 0 || _e185_hot_step warp-family-state _e138_warp_migrate_state || rc=1;
    test "$rc" -ne 0 || _e185_hot_step warp-backend-state _e138_warp_migrate_state || rc=1;
    if test "$rc" -eq 0; then
        enabled=$(_e138_state_get route_enabled 0);
        mode=$(_e138_state_get route_mode disabled);
        profile=$(_e138_state_get profile disabled);
    fi;
    test "$rc" -ne 0 || _e185_hot_step runtime-tools _e135_require_runtime_tools || rc=1;
    test "$rc" -ne 0 || _e185_hot_step qr-runtime _e183_ensure_qrencode || rc=1;
    test "$rc" -ne 0 || _e185_hot_step disable-legacy _e135_disable_legacy_optimizers || rc=1;
    test "$rc" -ne 0 || _e185_hot_step self-install _e185_install_self || rc=1;
    test "$rc" -ne 0 || _e185_hot_step dat-install install_update_dat || rc=1;
    test "$rc" -ne 0 || _e185_hot_step dat-timer systemctl enable --now xray-dat-update.timer || rc=1;
    test "$rc" -ne 0 || _e185_hot_step core-auto-update-off _e105_disable_xray_core_auto_update || rc=1;
    test "$rc" -ne 0 || _e185_hot_step init-window _e137_apply_init_window_default30 || rc=1;
    if test "$rc" -eq 0; then
        E159_DEFER_HOST_FULL_VERIFY=1;
        _e185_hot_step network-e159-stable-owner _e159_network_apply fq 1 31 force || rc=1;
        unset E159_DEFER_HOST_FULL_VERIFY;
        test "$rc" -ne 0 || network_tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" | tail -n1);
    fi;
    test "$rc" -ne 0 || _e185_hot_step host-safe-migrate _e159_migrate_host_safe || rc=1;
    test "$rc" -ne 0 || _e185_hot_step log-retention _e121_install_log_retention || rc=1;
    test "$rc" -ne 0 || _e185_hot_step ssh-guard-e182 _e141_install_ssh_guard || rc=1;
    if test "$rc" -eq 0; then
        ssh_tx=$(sed -n 's/^transaction=//p' "$E141_SSH_AUTH_STATE" 2> /dev/null | tail -n1);
    fi;
    test "$rc" -ne 0 || _e185_hot_step xray-limits fix_xray_systemd_limits || rc=1;
    if test "$rc" -eq 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e185_hot_step warp-full-units _e140_full_install_units || rc=1;
            test "$rc" -ne 0 || _e185_hot_step warp-full-reconcile _e140_warp_full_reconcile || rc=1;
        else
            _e185_hot_step warp-backend-reconcile _e185_hot_warp_reconcile || rc=1;
        fi;
    fi;
    test "$rc" -ne 0 || _e185_hot_step version-write _e185_write_version || rc=1;
    if test "$rc" -eq 0; then
        phase=verify;
        _e159_phase_log "$E185_HOT_LOG" "$phase" begin;
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1 || rc=1;
        test "$rc" -ne 0 || test ! -s "$CONFIG" || _e118_xray_test_config "$CONFIG" 1 || rc=1;
        if test "$rc" -eq 0 && test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
            test "$rc" -ne 0 || _e131_verify_nice_runtime || rc=1;
        else
            if test "$rc" -eq 0 && systemctl is-active --quiet xray.service 2> /dev/null; then
                error '热更新意外启动了原本停止的Xray服务。';
                rc=1;
            fi;
        fi;
        test "$rc" -ne 0 || _e159_network_verify_effective || rc=1;
        test "$rc" -ne 0 || _e159_network_verify_ownership || rc=1;
        test "$rc" -ne 0 || _e182_ssh_guard_verify_final || rc=1;
        test "$rc" -ne 0 || grep -qx 'net.ipv4.tcp_notsent_lowat = 16384' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || grep -qx 'net.core.busy_poll = 50' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || _e159_verify_neighbor_queue_semantics || rc=1;
        test "$rc" -ne 0 || _e182_ipv6_hot_verify || rc=1;
        test "$rc" -ne 0 || ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
        test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
        for unit in xray-dat-update.timer xray-log-retention-e121.timer xray-ssh-auth-audit-e152.timer xray-network-e159.timer;
        do
            test "$rc" -ne 0 || systemctl is-enabled --quiet "$unit" 2> /dev/null || rc=1;
            test "$rc" -ne 0 || systemctl is-active --quiet "$unit" 2> /dev/null || rc=1;
        done;
        test "$rc" -ne 0 || systemctl is-enabled --quiet xray-network-e159.service 2> /dev/null || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$SYMLINK" || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E185_SELF_PATH" || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E185_LATEST_PATH" || rc=1;
        test "$rc" -eq 0 && _e159_phase_log "$E185_HOT_LOG" "$phase" ok || _e159_phase_log "$E185_HOT_LOG" "$phase" fail;
    fi;
    if test "$rc" -ne 0; then
        error "E185热更新失败，开始总回滚；阶段日志：$E185_HOT_LOG";
        test -z "$ssh_tx" || _e152_nft_ssh_tx_rollback "$ssh_tx" || rollback_rc=1;
        test -z "$network_tx" || _e159_network_restore "$network_tx" || rollback_rc=1;
        _e182_ipv6_hot_rollback_if_marked || rollback_rc=1;
        test -z "$sysbackup" || _e140_system_restore "$sysbackup" || rollback_rc=1;
        test -z "$sysbackup" || _e182_sshd_reload_safe || rollback_rc=1;
        test -z "$protect" || _e118_restore_core_payload "$protect" > /dev/null 2>&1 || rollback_rc=1;
        test -z "$protect" || _e118_restore_state "$protect" > /dev/null 2>&1 || rollback_rc=1;
        _e135_remove_new_runtime_tools || true;
        if test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 > /dev/null 2>&1 || rollback_rc=1;
        fi;
        if test "$rollback_rc" -ne 0; then
            { 
                echo "time=$(date -Is 2> /dev/null || date)";
                echo 'operation=hot-update';
                echo "system_backup=${sysbackup:-none}";
                echo "network_backup=${network_tx:-none}";
                echo "ssh_backup=${ssh_tx:-none}";
                echo "core_backup=${protect:-none}";
                echo "log=$E185_HOT_LOG"
            } > "$E185_CRITICAL_MARKER" 2> /dev/null || true;
            error '严重：E185回滚未通过复检。';
        fi;
        _e159_phase_log "$E185_HOT_LOG" finish fail "rollback=$rollback_rc";
        return 1;
    fi;
    _e182_ipv6_hot_commit;
    rm -f "$E185_CRITICAL_MARKER" 2> /dev/null || true;
    _e142_prune_transactions "$sysbackup" "$protect" "$ssh_tx" || warn '旧事务快照收敛未完成。';
    _e127_prune_core_payload_backups;
    _e182_prune_system_tx "$sysbackup";
    _e152_cleanup_legacy_e143_units || true;
    _e159_phase_log "$E185_HOT_LOG" finish ok;
    effective_active=$(sed -n 's/^effective_active=//p' "$E159_NETWORK_STATE" | tail -n1);
    effective_persistent=$(sed -n 's/^effective_persistent=//p' "$E159_NETWORK_STATE" | tail -n1);
    unsupported=$(sed -n 's/^unsupported=//p' "$E159_NETWORK_STATE" | tail -n1);
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$E159_NETWORK_STATE" | tail -n1);
    trigger=$(sed -n 's/^write_trigger=//p' "$E159_NETWORK_STATE" | tail -n1);
    auth_mode=$(_e141_sshd_auth_profile 2> /dev/null | sed -n 's/^mode=//p' | head -n1);
    if test "$auth_mode" = password-capable; then
        info "V199e185热更新完成：127条请求（persistent=$effective_persistent，trigger=$trigger，unsupported=$unsupported，shadowed_alias=$shadowed，effective_assignments=$effective_active）、init30、3天日志、SSH能力状态（防火墙封禁、OpenSSH原生限流或只读审计）和Xray运行态均已验证。";
    else
        info "V199e185热更新完成：127条请求（persistent=$effective_persistent，trigger=$trigger，unsupported=$unsupported，shadowed_alias=$shadowed，effective_assignments=$effective_active）、init30、3天日志、SSH认证模式=$auth_mode（未强制启用Fail2ban）和Xray运行态均已验证。";
    fi;
    info "系统快照：$sysbackup";
    info "网络快照：$network_tx";
    info "SSH快照：${ssh_tx:-none}";
    info "阶段日志：$E185_HOT_LOG" )
}
