# EEX3-FUNCTION firewall_warp_e165_188 _e185_hot_warp_reconcile
_e185_hot_warp_reconcile() {
    local enabled mode profile family backend request;
    _e138_warp_migrate_state || return 1;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    family=$(_e138_state_get family ipv4);
    backend=$(_e138_state_get backend disabled);
    request=$(_e138_state_get backend_request "$backend");
    test "$enabled" = 1 || return 0;
    test "$mode" != host-full || { 
        _e140_warp_full_reconcile;
        return $?
    };
    case "$backend" in 
        masque | xray-wg)
            _e185_warp_reconcile
        ;;
        auto | disabled | '')
            warn '检测到旧版残留的WARP期望状态，但没有可验证的实际后端；热更新将安全清除失效路由，稍后可从菜单22/23重新启用。';
            _e138_xray_apply_warp disabled disabled false disabled disabled disabled || return 1;
            systemctl disable --now xray-warp-e138-health.timer > /dev/null 2>&1 || true
        ;;
        *)
            error "未知WARP后端状态：$backend";
            return 1
        ;;
    esac
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_ini_value
_e185_ini_value() {
    local file="$1" section="$2" key="$3";
    awk -F= -v wanted="[$section]" -v key="$key" '
      function trim(s){gsub(/^[ \t\r\n]+|[ \t\r\n]+$/,"",s); return s}
      /^[ \t]*\[/ {sec=trim($0); next}
      sec==wanted && trim($1)==key {
        v=substr($0,index($0,"=")+1); print trim(v); exit
      }' "$file" 2> /dev/null
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_ini_values
