# EEX3-FUNCTION firewall_warp_e165_188 _e185_install_wgcf
_e185_install_wgcf() {
    local arch api tag asset_url checksum_url asset_name tmpdir bin checks expected actual;
    _e185_wgcf_works && return 0;
    test "$EUID" -eq 0 || { 
        error '安装wgcf需要root。';
        return 1
    };
    command -v curl > /dev/null 2>&1 && command -v jq > /dev/null 2>&1 || return 1;
    arch=$(_e185_wgcf_arch) || { 
        error 'wgcf暂不支持当前CPU架构。';
        return 1
    };
    tmpdir=$(mktemp -d /tmp/xray-e185-wgcf.XXXXXX) || return 1;
    bin="$tmpdir/wgcf";
    checks="$tmpdir/checksums.txt";
    api=$(curl --proto '=https' --tlsv1.2 -fsSL --connect-timeout 10 --max-time 30 https://api.github.com/repos/ViRb3/wgcf/releases/latest 2>> "$E185_WG_LOG" || true);
    tag=$(jq -r '.tag_name // empty' <<< "$api" 2> /dev/null || true);
    asset_url=$(jq -r --arg a "linux_${arch}" '.assets[]? | select(.name|endswith($a)) | .browser_download_url' <<< "$api" 2> /dev/null | head -n1);
    checksum_url=$(jq -r '.assets[]? | select(.name=="checksums.txt") | .browser_download_url' <<< "$api" 2> /dev/null | head -n1);
    if test -z "$asset_url" || test -z "$checksum_url"; then
        tag="v2.2.31";
        asset_name="wgcf_2.2.31_linux_${arch}";
        asset_url="https://github.com/ViRb3/wgcf/releases/download/${tag}/${asset_name}";
        checksum_url="https://github.com/ViRb3/wgcf/releases/download/${tag}/checksums.txt";
    else
        asset_name=$(basename "$asset_url");
    fi;
    { 
        echo "time=$(date -Is 2> /dev/null || date)";
        echo "phase=download-wgcf";
        echo "tag=$tag";
        echo "asset=$asset_name"
    } > "$E185_WG_LOG";
    if ! curl --proto '=https' --tlsv1.2 -fL --connect-timeout 10 --max-time 180 "$asset_url" -o "$bin" >> "$E185_WG_LOG" 2>&1; then
        rm -rf -- "$tmpdir";
        return 1;
    fi;
    if ! curl --proto '=https' --tlsv1.2 -fL --connect-timeout 10 --max-time 60 "$checksum_url" -o "$checks" >> "$E185_WG_LOG" 2>&1; then
        rm -rf -- "$tmpdir";
        return 1;
    fi;
    expected=$(grep -F "$asset_name" "$checks" 2> /dev/null | grep -oE '^[0-9a-fA-F]{64}' | head -n1);
    actual=$(sha256sum "$bin" | awk '{print $1}');
    if test -z "$expected" || test "${expected,,}" != "${actual,,}"; then
        echo "checksum_expected=$expected checksum_actual=$actual" >> "$E185_WG_LOG";
        rm -rf -- "$tmpdir";
        return 1;
    fi;
    _e214_ensure_parent_dir "$E185_WGCF_BIN" || { 
        rm -rf -- "$tmpdir";
        return 1
    };
    install -m 0755 "$bin" "$E185_WGCF_BIN" || { 
        rm -rf -- "$tmpdir";
        return 1
    };
    rm -rf -- "$tmpdir";
    _e185_wgcf_works
}
