# EEX3-FUNCTION firewall_warp_e165_188 _e185_masque_failure_reason
_e185_masque_failure_reason() {
    local f="${1:-$E183_WARP_DIAG}";
    if grep -qiE 'AllChecksTimedOut|Failed to perform happy eyeballs|All Happy Eyeballs checks failed' "$f" 2> /dev/null; then
        if grep -qiE 'v4=.*(TimedOut|timed out)|connection timedout|pending connection closed on_timeout' "$f" 2> /dev/null; then
            echo masque-ingress-udp-timeout;
            return;
        fi;
        echo masque-happy-eyeballs-failed;
        return;
    fi;
    if grep -qiE 'Network is unreachable' "$f" 2> /dev/null; then
        echo masque-ipv6-underlay-unreachable;
        return;
    fi;
    if grep -qiE 'port.*(occupied|in use)|端口.*占用' "$f" 2> /dev/null; then
        echo local-port-conflict;
        return;
    fi;
    echo masque-not-converged
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_new_tx
_e185_new_tx() {
    local name="${1:-transaction}" dir;
    _e185_prepare || return 1;
    dir="$E185_TX_ROOT/${name}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM";
    install -d -m 0700 "$dir" || return 1;
    printf '%s\n' "$dir"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_prepare
_e185_prepare() {
    _e183_prepare || return 1;
    install -d -m 0700 "$E185_DIR" "$E185_TX_ROOT" "$E185_WG_DIR" "$(dirname "$E185_HOT_LOG")" "$(dirname "$E185_WG_LOG")" || return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_recent_masque_blocked
_e185_recent_masque_blocked() {
    local f="${1:-$E183_WARP_DIAG}" now mtime age reason;
    test -s "$f" || return 1;
    now=$(date +%s 2> /dev/null || echo 0);
    mtime=$(stat -c %Y "$f" 2> /dev/null || echo 0);
    age=$((now-mtime));
    test "$age" -ge 0 2> /dev/null && test "$age" -le 21600 2> /dev/null || return 1;
    reason=$(_e185_masque_failure_reason "$f");
    test "$reason" = masque-ingress-udp-timeout || return 1;
    grep -qiE 'AllChecksTimedOut|Failed to perform happy eyeballs' "$f" 2> /dev/null
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_self_test
_e185_self_test() {
    local rc=0 d profile out family strategy;
    d=$(mktemp -d /tmp/xray-e185-selftest.XXXXXX) || return 1;
    profile="$d/wgcf-profile.conf";
    cat > "$profile" <<'EOF_E185_PROFILE'
[Interface]
PrivateKey = AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=
Address = 172.16.0.2/32
Address = 2606:4700:110:1234::2/128
MTU = 1280
[Peer]
PublicKey = bmXOC+F1FxEMF9dyiK2H5/1SUtzH0JuVo51h2wPfgyo=
Endpoint = engage.cloudflareclient.com:2408
AllowedIPs = 0.0.0.0/0, ::/0
Reserved = 1, 2, 3
EOF_E185_PROFILE

    echo 'V199e185 fast release gate:';
    test "$SCRIPT_VERSION" = 199e185 && test "$E185_VERSION" = 199e185 && echo '  [PASS] release identity' || { 
        echo '  [FAIL] release identity';
        rc=1
    };
    for family in ipv4 ipv6 dual;
    do
        out="$d/$family.json";
        _e185_wg_outbound_json "$profile" 162.159.193.10:2408 "$family" warp-test-e185 "$out" || rc=1;
        strategy=$(_e185_wg_strategy "$family");
        jq -e --arg s "$strategy" '
          .protocol=="wireguard" and .settings.noKernelTun==true and
          .settings.domainStrategy==$s and .settings.peers[0].endpoint=="162.159.193.10:2408" and
          .settings.reserved==[1,2,3]
        ' "$out" > /dev/null 2>&1 || rc=1;
    done;
    test "$rc" -ne 0 || echo '  [PASS] IPv4/IPv6/dual native WireGuard generation';
    grep -q 'AllChecksTimedOut' <<< "$(declare -f _e185_masque_failure_reason)" && echo '  [PASS] MASQUE failure classifier' || { 
        echo '  [FAIL] classifier';
        rc=1
    };
    grep -q 'wgcf为非Cloudflare官方' <<< "$(declare -f _e185_confirm_wgcf_fallback)" && echo '  [PASS] explicit unofficial-fallback consent' || { 
        echo '  [FAIL] consent';
        rc=1
    };
    grep -q 'queryStrategy' <<< "$(declare -f _e138_warp_config_build)" && { 
        echo '  [FAIL] global DNS queryStrategy mutation remains';
        rc=1
    } || echo '  [PASS] no global DNS queryStrategy mutation';
    _e185_structure_audit > /dev/null || rc=1;
    rm -rf -- "$d";
    test "$rc" -eq 0 && echo 'V199e185 result: PASS' || echo 'V199e185 result: FAIL';
    return "$rc"
}
