# EEX3-FUNCTION firewall_warp_e165_188 _e185_structure_audit
_e185_structure_audit() {
    local rc=0 size lines dispatchers menu build enable;
    echo 'V199e185 structure audit:';
    size=$(wc -c < "$SCRIPT_PATH" | tr -d ' ');
    lines=$(wc -l < "$SCRIPT_PATH" | tr -d ' ');
    dispatchers=$(grep -c '^# V199e185 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    menu=$(declare -f _e185_main_menu_impl 2> /dev/null || true);
    build=$(declare -f _e138_warp_config_build 2> /dev/null || true);
    enable=$(declare -f _e185_warp_enable 2> /dev/null || true);
    echo "  file_bytes=$size";
    echo "  lines=$lines";
    echo "  final_dispatchers=$dispatchers";
    echo '  warp_backend_owner=e185 (MASQUE + Xray-native WireGuard fallback)';
    echo '  host_route_policy=noKernelTun=true for Xray WireGuard';
    echo '  qr_owner=e183 retained';
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    grep -q 'V199e185 - 事务稳态版' <<< "$menu" || rc=1;
    grep -q 'protocol:"wireguard"' <<< "$(declare -f _e185_wg_outbound_json)" || rc=1;
    grep -q 'noKernelTun' <<< "$(declare -f _e185_wg_outbound_json)" || rc=1;
    grep -q '_e185_confirm_wgcf_fallback' <<< "$enable" || rc=1;
    grep -q 'masque-ingress-udp-timeout' <<< "$(declare -f _e185_masque_failure_reason)" || rc=1;
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL';
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_uninstall_base
_e185_uninstall_base() {
    local rc=0;
    _e183_uninstall_base "$@" || rc=$?;
    if test "$rc" -eq 0; then
        rm -f -- "$E183_SELF_PATH" "$E183_LATEST_PATH" 2> /dev/null || true;
        rm -rf -- "$E183_DIR" "$E183_TX_ROOT" "$(dirname "$E183_HOT_LOG")" 2> /dev/null || true;
    fi;
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_warp_disable
_e185_warp_disable() {
    local tx old_mode rc=0 restore_rc=0;
    old_mode=$(_e138_state_get route_mode disabled);
    test "$old_mode" != host-full || { 
        _e140_warp_full_disable force;
        return $?
    };
    tx=$(_e204_new_tx warp-local-disable) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_warp_disable_base || rc=1;
    test "$rc" -ne 0 || test "$(_e138_state_get route_enabled 0)" = 0 || rc=1;
    test "$rc" -ne 0 || _e138_warp_config_integrity disabled disabled disabled disabled || rc=1;
    test "$rc" -ne 0 || _e204_xray_runtime_readback || rc=1;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    error 'E204 Xray层WARP关闭未通过读回，恢复关闭前状态。';
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1;
    test "$restore_rc" -eq 0 || { 
        _e204_mark_critical warp-local-disable "$tx/system" 'local WARP disable rollback/readback failed' || true;
        error "严重：Xray层WARP关闭回滚未完整通过；快照：$tx/system"
    };
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_warp_enable
_e185_warp_enable() {
    local tx rc=0 restore_rc=0;
    _e204_prepare || return 1;
    tx=$(_e204_new_tx warp-enable) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_warp_package_snapshot "$tx/warp-packages.before" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_warp_enable_base "$@" || rc=$?;
    if test "$rc" -eq 0 && test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || rc=1;
    fi;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    error 'E204 WARP外层事务未通过，恢复配置、凭据、期望状态和原服务启停状态。';
    _e204_warp_package_restore "$tx/warp-packages.before" || restore_rc=1;
    _e140_system_restore "$tx/system" || restore_rc=1;
    if systemctl is-active --quiet xray.service 2> /dev/null; then
        systemctl restart xray.service > /dev/null 2>&1 || restore_rc=1;
        test ! -s "$CONFIG" || _e127_verify_xray_runtime "$CONFIG" 12 || restore_rc=1;
    fi;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical warp-enable "$tx/system" 'outer WARP rollback/readback failed' || true;
        error "严重：WARP回滚未完整通过；快照：$tx/system";
    fi;
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_warp_health_check
_e185_warp_health_check() {
    local enabled backend mode profile family endpoint;
    enabled=$(_e138_state_get route_enabled 0);
    test "$enabled" = 1 || return 0;
    backend=$(_e138_state_get backend disabled);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    family=$(_e138_state_get family ipv4);
    if test "$backend" = xray-wg; then
        endpoint=$(_e185_state_endpoint);
        test -n "$endpoint" && systemctl is-active --quiet xray.service && _e138_warp_config_integrity "$mode" "$profile" "$family" "$backend" && _e185_wg_probe_endpoint "$endpoint" "$family" || { 
            echo "[$(date -Is)] FAIL backend=xray-wg functional-egress" >> "$E138_WARP_LOG";
            return 1
        };
        echo "[$(date -Is)] OK backend=xray-wg functional-egress family=$family" >> "$E138_WARP_LOG";
        return 0;
    fi;
    _e204_warp_health_base "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_warp_migrate_state_base
_e185_warp_migrate_state_base() {
    local enabled mode profile family;
    _e183_warp_migrate_state_base || return 1;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    family=$(_e138_state_get family '');
    if test "$enabled" = 1; then
        family=$(_e183_warp_family_normalize "${family:-ipv4}") || family=ipv4;
        _e138_state_write 1 "$mode" "$profile" "$family";
    else
        _e138_state_write 0 disabled disabled disabled;
    fi
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_warp_reconcile
_e185_warp_reconcile() {
    local tx old_mode rc=0 restore_rc=0;
    old_mode=$(_e138_state_get route_mode disabled);
    test "$old_mode" != host-full || { 
        _e140_warp_full_reconcile;
        return $?
    };
    tx=$(_e204_new_tx warp-local-reconcile) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_warp_package_snapshot "$tx/warp-packages.before" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e204_warp_reconcile_base || rc=1;
    if test "$rc" -eq 0 && test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || rc=1;
    fi;
    test "$rc" -ne 0 || _e204_xray_runtime_readback || rc=1;
    if test "$rc" -eq 0; then
        _e204_tx_close "$tx";
        return $?;
    fi;
    error 'E204 Xray层WARP修复失败，恢复修复前状态。';
    _e204_warp_package_restore "$tx/warp-packages.before" || restore_rc=1;
    _e204_warp_outer_restore "$tx/system" "$old_mode" || restore_rc=1;
    test "$restore_rc" -eq 0 || { 
        _e204_mark_critical warp-local-reconcile "$tx/system" 'local WARP reconcile rollback/readback failed' || true;
        error "严重：Xray层WARP修复回滚未完整通过；快照：$tx/system"
    };
    _e204_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_warp_status
_e185_warp_status() {
    _e186_warp_status
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_warp_status_e183_base
_e185_warp_status_e183_base() {
    local enabled mode profile family proxy=DOWN integrity=MISSING trace loc warpip strategy;
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    family=$(_e138_state_get family disabled);
    strategy=$(_e183_warp_strategy "${family:-ipv4}" 2> /dev/null || echo n/a);
    title 'V199e183：WARP/Cloudflare状态';
    printf '  %-28s %s\n' '期望状态' "enabled=$enabled mode=$mode profile=$profile family=$family";
    printf '  %-28s %s\n' 'Xray目标解析策略' "$strategy";
    printf '  %-28s %s\n' 'warp-svc' "$(systemctl is-active "$(_e140_warp_service_name)" 2> /dev/null || echo unknown)";
    printf '  %-28s %s\n' '客户端模式' "$(_e140_warp_mode_current)";
    printf '  %-28s %s\n' '隧道协议' "$(_e140_warp_protocol_current)";
    if test "$mode" = host-full && test "$enabled" = 1; then
        _e183_warp_full_status_base;
        return $?;
    fi;
    _e183_warp_listener_ok && proxy=UP || true;
    _e138_warp_config_integrity "$mode" "$profile" "$family" > /dev/null 2>&1 && integrity=CONSISTENT || true;
    trace=$(_e136_warp_trace 2> /dev/null || true);
    loc=$(awk -F= '$1=="loc"{print $2}' <<< "$trace");
    loc=${loc:-unknown};
    warpip=$(awk -F= '$1=="ip"{print $2}' <<< "$trace");
    warpip=${warpip:-unknown};
    printf '  %-28s %s\n' '本地代理' "$proxy (127.0.0.1:$E138_WARP_PORT)";
    printf '  %-28s %s\n' 'Xray配置一致性' "$integrity";
    printf '  %-28s %s\n' 'WARP出口/loc' "$warpip/$loc";
    printf '  %-28s %s\n' '失败诊断' "$E183_WARP_DIAG"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_endpoint_candidates
_e185_wg_endpoint_candidates() {
    local profile="${1:-$E185_WG_PROFILE}" raw hp host port ip;
    raw=$(_e185_ini_value "$profile" Peer Endpoint);
    hp=$(_e185_endpoint_host_port "$raw" 2> /dev/null || true);
    host=$(awk '{print $1}' <<< "$hp");
    port=$(awk '{print $2}' <<< "$hp");
    port=${port:-2408};
    if _e185_is_ipv4 "$host"; then
        ip="$host";
    else
        ip=$(getent ahostsv4 "$host" 2> /dev/null | awk '$1 ~ /^[0-9.]+$/ {print $1; exit}');
    fi;
    { 
        for host in "$ip" 162.159.193.10 162.159.193.1 162.159.193.100;
        do
            test -n "$host" || continue;
            for port in "$port" 2408 500 1701 4500;
            do
                printf '%s:%s\n' "$host" "$port";
            done;
        done
    } | awk '!seen[$0]++'
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_has_v6_address
_e185_wg_has_v6_address() {
    _e185_wg_profile_addresses "${1:-$E185_WG_PROFILE}" | grep -q ':'
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_import
_e185_wg_import() {
    local src="${1:-}";
    test -n "$src" && test -s "$src" || { 
        error '请提供有效wgcf-profile.conf路径。';
        return 1
    };
    _e185_prepare || return 1;
    install -m 0600 "$src" "$E185_WG_PROFILE" || return 1;
    _e185_wg_profile_valid || { 
        rm -f "$E185_WG_PROFILE";
        error '导入文件不是有效wgcf WireGuard配置。';
        return 1
    };
    rm -f "$E185_WG_ENDPOINT_STATE" 2> /dev/null || true;
    info "已导入WARP WireGuard配置：$E185_WG_PROFILE"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_outbound_json
_e185_wg_outbound_json() {
    local profile="$1" endpoint="$2" family="$3" tag="$4" out="$5";
    local private public mtu reserved strategy addresses_json reserved_json;
    private=$(_e185_ini_value "$profile" Interface PrivateKey);
    public=$(_e185_ini_value "$profile" Peer PublicKey);
    mtu=$(_e185_ini_value "$profile" Interface MTU);
    mtu=${mtu:-1280};
    reserved=$(_e185_ini_value "$profile" Peer Reserved);
    strategy=$(_e185_wg_strategy "$family");
    addresses_json=$(_e185_wg_profile_addresses "$profile" | jq -Rsc 'split("\n")|map(select(length>0))');
    test -n "$private" && test -n "$public" && test "$addresses_json" != '[]' || return 1;
    [[ "$mtu" =~ ^[0-9]+$ ]] || mtu=1280;
    if [[ "$reserved" =~ ^[[:space:]]*[0-9]+[[:space:]]*,[[:space:]]*[0-9]+[[:space:]]*,[[:space:]]*[0-9]+[[:space:]]*$ ]]; then
        reserved_json=$(tr -d ' ' <<< "$reserved" | awk -F, '{printf "[%d,%d,%d]",$1,$2,$3}');
    else
        reserved_json='null';
    fi;
    jq -n --arg tag "$tag" --arg key "$private" --arg pub "$public" --arg ep "$endpoint" --arg strategy "$strategy" --argjson addresses "$addresses_json" --argjson mtu "$mtu" --argjson reserved "$reserved_json" '
      {
        tag:$tag,
        protocol:"wireguard",
        settings:(
          {
            secretKey:$key,
            address:$addresses,
            noKernelTun:true,
            mtu:$mtu,
            domainStrategy:$strategy,
            peers:[{
              endpoint:$ep,
              publicKey:$pub,
              allowedIPs:["0.0.0.0/0","::/0"],
              keepAlive:25
            }]
          } + (if $reserved==null then {} else {reserved:$reserved} end)
        )
      }' > "$out"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_prepare
_e185_wg_prepare() {
    local family="$1" endpoint saved_family;
    _e185_wgcf_ensure_profile || return 1;
    _e185_wg_validate_family "$family" || return 1;
    family="$E185_WG_EFFECTIVE_FAMILY";
    endpoint=$(_e185_state_endpoint);
    saved_family=$(_e185_state_probe_value family '');
    if test -n "$endpoint" && test "$saved_family" = "$family" && _e185_wg_probe_endpoint "$endpoint" "$family"; then
        return 0;
    fi;
    _e185_wg_select_endpoint "$family"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_probe_endpoint
_e185_wg_probe_endpoint() {
    local endpoint="$1" family="$2" port d outbound cfg log pid i trace rc=1 warp loc;
    port=$(_e185_find_probe_port) || return 1;
    d=$(mktemp -d /tmp/xray-e185-wg-probe.XXXXXX) || return 1;
    outbound="$d/outbound.json";
    cfg="$d/config.json";
    log="$d/xray.log";
    _e185_wg_outbound_json "$E185_WG_PROFILE" "$endpoint" "$family" warp-probe-e185 "$outbound" || { 
        rm -rf "$d";
        return 1
    };
    jq -n --argjson wg "$(cat "$outbound")" --argjson p "$port" '
      {
        log:{loglevel:"warning"},
        inbounds:[{tag:"probe-in-e185",listen:"127.0.0.1",port:$p,protocol:"socks",settings:{udp:false}}],
        outbounds:[$wg],
        routing:{domainStrategy:"AsIs",rules:[{type:"field",inboundTag:["probe-in-e185"],outboundTag:"warp-probe-e185"}]}
      }' > "$cfg" || { 
        rm -rf "$d";
        return 1
    };
    _e118_xray_test_config "$cfg" 1 >> "$E185_WG_LOG" 2>&1 || { 
        cat "$cfg" > /dev/null;
        rm -rf "$d";
        return 1
    };
    "$XRAY_BIN" run -config "$cfg" > "$log" 2>&1 & pid=$!;
    for i in $(seq 1 12);
    do
        kill -0 "$pid" 2> /dev/null || break;
        ss -H -lnt 2> /dev/null | awk '{print $4}' | grep -Eq "127\.0\.0\.1:${port}$" && break;
        sleep 1;
    done;
    if kill -0 "$pid" 2> /dev/null && ss -H -lnt 2> /dev/null | awk '{print $4}' | grep -Eq "127\.0\.0\.1:${port}$"; then
        trace=$(curl --proto '=https' --tlsv1.2 -fsS --noproxy '' --socks5-hostname "127.0.0.1:$port" --connect-timeout 8 --max-time 18 https://www.cloudflare.com/cdn-cgi/trace 2>> "$log" || true);
        warp=$(awk -F= '$1=="warp"{print $2}' <<< "$trace");
        loc=$(awk -F= '$1=="loc"{print toupper($2)}' <<< "$trace");
        if [[ "$warp" =~ ^(on|plus)$ ]] && test "$loc" != CN; then
            rc=0;
        fi;
        { 
            echo "probe_endpoint=$endpoint family=$family warp=${warp:-off} loc=${loc:-unknown}";
            printf '%s\n' "$trace"
        } >> "$E185_WG_LOG";
    fi;
    kill "$pid" > /dev/null 2>&1 || true;
    wait "$pid" > /dev/null 2>&1 || true;
    if test "$rc" -ne 0; then
        { 
            echo "probe_endpoint=$endpoint family=$family result=fail";
            tail -n 80 "$log" 2> /dev/null || true
        } >> "$E185_WG_LOG";
    fi;
    rm -rf -- "$d";
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_profile_addresses
_e185_wg_profile_addresses() {
    _e185_ini_values "$1" Interface Address | tr ',' '\n' | sed -E 's/^[[:space:]]+|[[:space:]]+$//g' | sed '/^$/d' | awk '!seen[$0]++'
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_profile_valid
_e185_wg_profile_valid() {
    local f="${1:-$E185_WG_PROFILE}";
    test -s "$f" || return 1;
    test -n "$(_e185_ini_value "$f" Interface PrivateKey)" || return 1;
    test -n "$(_e185_ini_values "$f" Interface Address)" || return 1;
    test -n "$(_e185_ini_value "$f" Peer PublicKey)" || return 1;
    test -n "$(_e185_ini_value "$f" Peer Endpoint)" || return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_select_endpoint
_e185_wg_select_endpoint() {
    local family="$1" endpoint count=0 before after warp loc tmp;
    before=$(_e185_host_route_guard_snapshot);
    : > "$E185_WG_LOG";
    { 
        echo "time=$(date -Is 2> /dev/null || date)";
        echo "phase=wireguard-endpoint-probe";
        echo "family=$family"
    } >> "$E185_WG_LOG";
    while IFS= read -r endpoint; do
        test -n "$endpoint" || continue;
        count=$((count+1));
        test "$count" -le 12 || break;
        if _e185_wg_probe_endpoint "$endpoint" "$family"; then
            after=$(_e185_host_route_guard_snapshot);
            test "$before" = "$after" || { 
                error 'Xray WireGuard探针导致宿主机路由漂移，拒绝使用。';
                return 1
            };
            warp=$(tail -n 100 "$E185_WG_LOG" | sed -n 's/.* warp=\([^ ]*\).*/\1/p' | tail -n1);
            loc=$(tail -n 100 "$E185_WG_LOG" | sed -n 's/.* loc=\([^ ]*\).*/\1/p' | tail -n1);
            tmp=$(_e118_mktemp e185-wg-endpoint) || return 1;
            { 
                echo "endpoint=$endpoint";
                echo "family=$family";
                echo "last_warp=${warp:-on}";
                echo "last_loc=${loc:-unknown}";
                echo "verified=$(date -Is 2> /dev/null || date)"
            } > "$tmp";
            install -m 0600 "$tmp" "$E185_WG_ENDPOINT_STATE" || return 1;
            info "Xray原生WARP WireGuard可用：endpoint=$endpoint，family=$family。";
            return 0;
        fi;
    done < <(_e185_wg_endpoint_candidates);
    _e185_capture_backend_diag wireguard-ingress-udp-unreachable xray-wg "$family";
    error "WARP WireGuard入口也不可达；上游可能阻断全部WARP UDP。诊断：$E185_WARP_DIAG";
    return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_strategy
_e185_wg_strategy() {
    case "$(_e185_family_normalize "${1:-ipv4}")" in 
        ipv4)
            echo ForceIPv4
        ;;
        ipv6)
            echo ForceIPv6
        ;;
        dual)
            echo ForceIPv4v6
        ;;
        *)
            echo ForceIP
        ;;
    esac
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wg_validate_family
_e185_wg_validate_family() {
    local requested;
    requested=$(_e185_family_normalize "${1:-ipv4}") || return 1;
    E185_WG_EFFECTIVE_FAMILY="$requested";
    if test "$requested" = ipv6 && ! _e185_wg_has_v6_address; then
        error '当前wgcf注册没有IPv6隧道地址，不能启用IPv6-only WARP。';
        return 1;
    fi;
    if test "$requested" = dual && ! _e185_wg_has_v6_address; then
        warn '当前wgcf注册仅有IPv4隧道地址；双栈请求降级为IPv4。';
        E185_WG_EFFECTIVE_FAMILY=ipv4;
    fi
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wgcf_arch
_e185_wgcf_arch() {
    case "$(uname -m 2> /dev/null || true)" in 
        x86_64 | amd64)
            echo amd64
        ;;
        aarch64 | arm64)
            echo arm64
        ;;
        armv7l | armv7)
            echo armv7
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wgcf_ensure_profile
_e185_wgcf_ensure_profile() {
    local rc=0;
    _e185_prepare || return 1;
    _e185_wg_profile_valid && return 0;
    _e185_install_wgcf || { 
        error "wgcf安装失败；诊断：$E185_WG_LOG";
        return 1
    };
    ( set -e;
    umask 077;
    cd "$E185_WG_DIR";
    if test ! -s wgcf-account.toml; then
        "$E185_WGCF_BIN" register --accept-tos;
    fi;
    "$E185_WGCF_BIN" generate;
    chmod 0600 wgcf-account.toml wgcf-profile.conf 2> /dev/null || true ) >> "$E185_WG_LOG" 2>&1 || rc=$?;
    test "$rc" -eq 0 && _e185_wg_profile_valid || { 
        error "WARP WireGuard配置注册/生成失败；诊断：$E185_WG_LOG";
        return 1
    }
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_wgcf_works
_e185_wgcf_works() {
    test -x "$E185_WGCF_BIN" && { 
        "$E185_WGCF_BIN" --version > /dev/null 2>&1 || "$E185_WGCF_BIN" version > /dev/null 2>&1 || "$E185_WGCF_BIN" help > /dev/null 2>&1
    }
}
# EEX3-FUNCTION firewall_warp_e165_188 _e185_write_version
