# EEX3-FUNCTION firewall_warp_e165_188 _e186_listener_set_safe
_e186_listener_set_safe() {
    local lines="${1:-}" line addr count=0 have_v4=0;
    test -n "$lines" || return 1;
    while IFS= read -r line; do
        test -n "$line" || continue;
        addr=$(awk '{print $4}' <<< "$line");
        case "$addr" in 
            "127.0.0.1:$E138_WARP_PORT")
                have_v4=1
            ;;
            "[::1]:$E138_WARP_PORT")
                :
            ;;
            *)
                return 1
            ;;
        esac;
        count=$((count+1));
    done <<< "$lines";
    test "$count" -gt 0 && test "$have_v4" -eq 1
}
