    local output rc;
    if output=$(_e182_optimization_menu_audit 2>&1); then
        rc=0;
    else
        rc=$?;
    fi;
    printf '%s\n' "$output" | sed '1s/^V199e182 /V199e186 /';
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_png_valid
_e186_png_valid() {
    local file="$1" sig;
    test -s "$file" || return 1;
    sig=$(od -An -tx1 -N8 "$file" 2> /dev/null | tr -d ' \n');
    test "$sig" = 89504e470d0a1a0a
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_prepare
_e186_prepare() {
    _e185_prepare || return 1;
    install -d -m 0700 "$E186_DIR" "$E186_TX_ROOT" "$(dirname "$E186_HOT_LOG")" "$E186_QR_DIAG_DIR" || return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_qr_generate_files
_e186_qr_generate_files() {
    local uri="$1" png="$2" svg="$3" diag="$4";
    local tmp_png tmp_svg generated=0 level;
    level=$(_e186_qr_level "$uri");
    tmp_png=$(mktemp "$(dirname -- "$png")/.e186-qr-png.XXXXXX") || return 1;
    if qrencode -l "$level" -m 4 -s 8 -t PNG -o "$tmp_png" "$uri" 2>> "$diag" && _e186_png_valid "$tmp_png"; then
        chmod 0600 "$tmp_png" || { 
            rm -f -- "$tmp_png";
            return 1
        };
        mv -f -- "$tmp_png" "$png" || { 
            rm -f -- "$tmp_png";
            return 1
        };
        generated=1;
    else
        rm -f -- "$tmp_png" "$png" 2> /dev/null || true;
    fi;
    tmp_svg=$(mktemp "$(dirname -- "$svg")/.e186-qr-svg.XXXXXX") || { 
        test "$generated" -eq 1;
        return
    };
    if qrencode -l "$level" -m 4 -t SVG -o "$tmp_svg" "$uri" 2>> "$diag" && _e186_svg_valid "$tmp_svg"; then
        chmod 0600 "$tmp_svg" || { 
            rm -f -- "$tmp_svg";
            return 1
        };
        mv -f -- "$tmp_svg" "$svg" || { 
            rm -f -- "$tmp_svg";
            return 1
        };
        generated=1;
    else
        rm -f -- "$tmp_svg" "$svg" 2> /dev/null || true;
    fi;
    test "$generated" -eq 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_qr_level
_e186_qr_level() {
    local bytes;
    bytes=$(LC_ALL=C printf '%s' "${1:-}" | wc -c | tr -d ' ');
    if test "$bytes" -le 1200; then
        echo H;
    else
        if test "$bytes" -le 1600; then
            echo Q;
        else
            if test "$bytes" -le 2300; then
                echo M;
            else
                echo L;
            fi;
        fi;
    fi
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_qr_terminal
_e186_qr_terminal() {
    _e188_qr_terminal "$@"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_qr_terminal_wanted
_e186_qr_terminal_wanted() {
    test "${E186_FORCE_TERMINAL_QR:-0}" = 1 || test "${E186_QR_TERMINAL:-auto}" = always || test -t 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_route_guard_snapshot
_e186_route_guard_snapshot() {
    local ssh_ip="";
    declare -F _e135_current_ssh_ip > /dev/null 2>&1 && ssh_ip=$(_e135_current_ssh_ip 2> /dev/null || true);
    { 
        echo '[default4]';
        ip -4 route show default 2> /dev/null | sed -E 's/[[:space:]]+expires[[:space:]]+[0-9]+sec//g; s/[[:space:]]+/ /g' | LC_ALL=C sort;
        echo '[rule4]';
        ip -4 rule show 2> /dev/null | sed -E 's/[[:space:]]+/ /g' | LC_ALL=C sort;
        echo '[default6]';
        ip -6 route show default 2> /dev/null | sed -E 's/[[:space:]]+expires[[:space:]]+[0-9]+sec//g; s/[[:space:]]+/ /g' | LC_ALL=C sort;
        echo '[rule6]';
        ip -6 rule show 2> /dev/null | sed -E 's/[[:space:]]+/ /g' | LC_ALL=C sort;
        if _e136_is_ipv4 "$ssh_ip"; then
            echo '[ssh-route4]';
            ip -4 route get "$ssh_ip" 2> /dev/null | head -n1 | sed -E 's/[[:space:]]+expires[[:space:]]+[0-9]+sec//g; s/[[:space:]]+/ /g';
        else
            if test -n "$ssh_ip"; then
                echo '[ssh-route6]';
                ip -6 route get "$ssh_ip" 2> /dev/null | head -n1 | sed -E 's/[[:space:]]+expires[[:space:]]+[0-9]+sec//g; s/[[:space:]]+/ /g';
            fi;
        fi
    }
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_self_test
_e186_self_test() {
    local rc=0 d out family strategy png svg diag fake profile;
    d=$(mktemp -d /tmp/xray-e186-selftest.XXXXXX) || return 1;
    echo 'V199e186 fast release gate:';
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' || { 
        echo '  [FAIL] bash syntax';
        rc=1
    };
    test "$SCRIPT_VERSION" = 199e186 && test "$E186_VERSION" = 199e186 && echo '  [PASS] release identity' || { 
        echo '  [FAIL] release identity';
        rc=1
    };
    _e186_listener_set_safe "LISTEN 0 4096 127.0.0.1:$E138_WARP_PORT 0.0.0.0:* users:((\"warp-svc\",pid=1,fd=1))" && ! _e186_listener_set_safe "LISTEN 0 4096 0.0.0.0:$E138_WARP_PORT 0.0.0.0:*" && ! _e186_listener_set_safe "LISTEN 0 4096 [::]:$E138_WARP_PORT [::]:*" && echo '  [PASS] strict Local proxy listener parser' || { 
        echo '  [FAIL] listener parser';
        rc=1
    };
    _e186_warp_trace_ok 'warp=on
loc=US
' && ! _e186_warp_trace_ok 'warp=off
loc=US
' && ! _e186_warp_trace_ok 'warp=on
loc=CN
' && echo '  [PASS] SOCKS trace truth classifier' || { 
        echo '  [FAIL] trace classifier';
        rc=1
    };
    cat > "$d/legacy-global.json" <<'EOF_E186_LEGACY_WARP'
{"outbounds":[{"tag":"warp-global-e138","protocol":"socks","settings":{"address":"127.0.0.1","port":40000}}],"routing":{"rules":[{"type":"field","network":"tcp","outboundTag":"warp-global-e138"}]}}
EOF_E186_LEGACY_WARP

    cat > "$d/legacy-selective.json" <<'EOF_E186_LEGACY_SELECTIVE'
{"outbounds":[{"tag":"warp-selective-socks-e183","protocol":"socks","settings":{"address":"127.0.0.1","port":40000}},{"tag":"warp-selective-e138","protocol":"freedom"}],"routing":{"rules":[]}}
EOF_E186_LEGACY_SELECTIVE

    test "$(_e186_warp_config_mode "$d/legacy-global.json")" = global && test "$(_e186_warp_config_backend "$d/legacy-global.json")" = masque && test "$(_e186_warp_config_mode "$d/legacy-selective.json")" = selective && test "$(_e186_warp_config_backend "$d/legacy-selective.json")" = masque && echo '  [PASS] E138/E183 WARP state migration classifier' || { 
        echo '  [FAIL] legacy WARP migration classifier';
        rc=1
    };
    cat > "$d/base.json" <<'EOF_E186_BASE'
{"dns":{"servers":["1.1.1.1"],"queryStrategy":"UseIPv4"},"outbounds":[{"tag":"direct","protocol":"freedom","settings":{"domainStrategy":"UseIPv4"}},{"tag":"block","protocol":"blackhole"}],"routing":{"domainStrategy":"AsIs","rules":[]}}
EOF_E186_BASE

    for family in ipv4 ipv6 dual;
    do
        out="$d/$family.json";
        _e138_warp_config_build global global true "$out" "$d/base.json" "$family" masque || rc=1;
        strategy=$(_e185_freedom_strategy "$family");
        jq -e --arg w "$E185_WARP_GLOBAL_TAG" --arg s "$E185_WARP_GLOBAL_SOCKS_TAG" --arg st "$strategy" '
          any(.outbounds[]?;.tag==$s and .protocol=="socks" and .settings.address=="127.0.0.1") and
          any(.outbounds[]?;.tag==$w and .protocol=="freedom" and .settings.domainStrategy==$st and .proxySettings.tag==$s) and
          .dns.queryStrategy=="UseIPv4"
        ' "$out" > /dev/null 2>&1 || rc=1;
        case "$family" in 
            ipv4)
                jq -e --arg b "$E185_WARP_FAMILY_BLOCK_TAG" 'any(.routing.rules[]?;.outboundTag==$b and .ip==["::/0"])' "$out" > /dev/null 2>&1 || rc=1
            ;;
            ipv6)
                jq -e --arg b "$E185_WARP_FAMILY_BLOCK_TAG" 'any(.routing.rules[]?;.outboundTag==$b and .ip==["0.0.0.0/0"])' "$out" > /dev/null 2>&1 || rc=1
            ;;
            dual)
                jq -e --arg b "$E185_WARP_FAMILY_BLOCK_TAG" 'all(.routing.rules[]?;.outboundTag!=$b)' "$out" > /dev/null 2>&1 || rc=1
            ;;
        esac;
    done;
    test "$rc" -ne 0 || echo '  [PASS] IPv4/IPv6/dual MASQUE config generation';
    profile="$d/wgcf-profile.conf";
    cat > "$profile" <<'EOF_E186_WG_PROFILE'
[Interface]
PrivateKey = AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=
Address = 172.16.0.2/32
Address = 2606:4700:110:1234::2/128
MTU = 1280
[Peer]
PublicKey = bmXOC+F1FxEMF9dyiK2H5/1SUtzH0JuVo51h2wPfgyo=
Endpoint = engage.cloudflareclient.com:2408
AllowedIPs = 0.0.0.0/0, ::/0
Reserved = 1, 2, 3
EOF_E186_WG_PROFILE

    for family in ipv4 ipv6 dual;
    do
        out="$d/wg-$family.json";
        _e185_wg_outbound_json "$profile" 162.159.193.10:2408 "$family" warp-test-e186 "$out" || rc=1;
        strategy=$(_e185_wg_strategy "$family");
        jq -e --arg s "$strategy" '
          .protocol=="wireguard" and .settings.noKernelTun==true and
          .settings.domainStrategy==$s and
          .settings.peers[0].endpoint=="162.159.193.10:2408" and
          .settings.reserved==[1,2,3]
        ' "$out" > /dev/null 2>&1 || rc=1;
    done;
    test "$rc" -ne 0 || echo '  [PASS] IPv4/IPv6/dual Xray WireGuard generation';
    fake="$d/bin";
    mkdir -p "$fake";
    cat > "$fake/qrencode" <<'EOF_E186_FAKE_QR'
#!/usr/bin/env bash
if test "${1:-}" = --version; then echo 'qrencode mock 1'; exit 0; fi
type=PNG
out=
while test "$#" -gt 0; do
    case "$1" in
        -t) type="$2"; shift 2 ;;
        -o) out="$2"; shift 2 ;;
        -l|-m|-s) shift 2 ;;
        *) shift ;;
    esac
done
case "$type" in
    PNG) printf '\211PNG\r\n\032\nmock' >"$out" ;;
    SVG) printf '<svg xmlns=\"http://www.w3.org/2000/svg\"></svg>\n' >"$out" ;;
    *) printf '[mock qr]\n' ;;
esac
EOF_E186_FAKE_QR

    chmod 0755 "$fake/qrencode";
    png="$d/test.png";
    svg="$d/test.svg";
    diag="$d/test.log";
    if PATH="$fake:$PATH" _e186_qr_generate_files 'vless://unit-test' "$png" "$svg" "$diag" && _e186_png_valid "$png" && _e186_svg_valid "$svg"; then
        echo '  [PASS] QR PNG/SVG generation and signature validation';
    else
        echo '  [FAIL] QR artifact pipeline';
        rc=1;
    fi;
    _e186_structure_audit > /dev/null || rc=1;
    rm -rf -- "$d";
    test "$rc" -eq 0 && echo 'V199e186 result: PASS' || echo 'V199e186 result: FAIL';
    return "$rc"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_state_write_impl
_e186_state_write_impl() {
    local enabled="$1" mode="$2" profile="$3" family="${4:-}" backend="${5:-}" backend_request="${6:-}" tmp endpoint="";
    _e138_prepare || return 1;
    if test "$enabled" = 1 && test "$mode" != host-full; then
        test -n "$family" || family=$(_e138_state_get family ipv4);
        family=$(_e185_family_normalize "${family:-ipv4}") || return 1;
        test "$family" != disabled || family=ipv4;
        test -n "$backend" || backend=$(_e138_state_get backend auto);
        backend=$(_e185_backend_normalize "${backend:-auto}") || return 1;
        test "$backend" != disabled || backend=auto;
        test -n "$backend_request" || backend_request=$(_e138_state_get backend_request "$backend");
        backend_request=$(_e185_backend_normalize "${backend_request:-$backend}") || backend_request="$backend";
        test "$backend" != xray-wg || endpoint=$(_e185_state_endpoint);
    else
        if test "$enabled" = 1 && test "$mode" = host-full; then
            family=disabled;
            backend=host-full;
            backend_request=host-full;
        else
            enabled=0;
            mode=disabled;
            profile=disabled;
            family=disabled;
            backend=disabled;
            backend_request=disabled;
        fi;
    fi;
    tmp=$(_e118_mktemp warp-state-e185) || return 1;
    { 
        echo 'managed_by=e186';
        echo "route_enabled=$enabled";
        echo "route_mode=$mode";
        echo "profile=$profile";
        echo "family=$family";
        echo "backend=$backend";
        echo "backend_request=$backend_request";
        test -z "$endpoint" || echo "wg_endpoint=$endpoint";
        echo "port=$E138_WARP_PORT";
        echo "updated=$(date -Is 2> /dev/null || date)"
    } > "$tmp" || return 1;
    install -m 0600 "$tmp" "$E138_WARP_STATE" || return 1
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_structure_audit
_e186_structure_audit() {
    local rc=0 size lines dispatchers menu listener qr hot;
    echo 'V199e186 structure audit:';
    size=$(wc -c < "$SCRIPT_PATH" | tr -d ' ');
    lines=$(wc -l < "$SCRIPT_PATH" | tr -d ' ');
    dispatchers=$(grep -c '^# V199e186 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    menu=$(declare -f _e186_main_menu_impl 2> /dev/null || true);
    listener=$(declare -f _e186_warp_connect_local_proxy 2> /dev/null || true);
    qr=$(declare -f _e135_emit_qr 2> /dev/null || true);
    hot=$(declare -f _e186_hot_update 2> /dev/null || true);
    echo "  file_bytes=$size";
    echo "  lines=$lines";
    echo "  final_dispatchers=$dispatchers";
    echo '  warp_owner=e186 (strict loopback + SOCKS5 trace + route guard)';
    echo '  family_policy=IPv4 / IPv6 / dual Xray targets';
    echo '  qr_owner=e186 (forced terminal + verified atomic PNG/SVG)';
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    grep -q 'V199e186 - 事务稳态版' <<< "$menu" || rc=1;
    grep -q '_e186_warp_trace_ok' <<< "$listener" || rc=1;
    grep -q 'E186_WARP_WAIT_SECONDS' <<< "$listener" || rc=1;
    grep -q '_e186_qr_generate_files' <<< "$qr" || rc=1;
    grep -q '_e186_install_self' <<< "$hot" || rc=1;
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL';
    return "$rc"
}
