}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_warp_migrate_state_base
_e186_warp_migrate_state_base() {
    local enabled mode profile family backend request;
    _e185_warp_migrate_state_base > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    if test "$enabled" != 1; then
        _e138_state_write 0 disabled disabled disabled disabled disabled;
        return 0;
    fi;
    if test "$mode" = host-full; then
        return 0;
    fi;
    family=$(_e138_state_get family ipv4);
    family=$(_e185_family_normalize "${family:-ipv4}" 2> /dev/null || echo ipv4);
    test "$family" != disabled || family=ipv4;
    backend=$(_e138_state_get backend '');
    request=$(_e138_state_get backend_request '');
    if ! backend=$(_e185_backend_normalize "${backend:-}" 2> /dev/null); then
        if jq -e --arg a "$E185_WARP_SELECT_TAG" --arg b "$E185_WARP_GLOBAL_TAG" 'any(.outbounds[]?;((.tag==$a or .tag==$b) and .protocol=="wireguard"))' "$CONFIG" > /dev/null 2>&1; then
            backend=xray-wg;
        else
            if jq -e --arg a "$E183_WARP_SELECT_SOCKS_TAG" --arg b "$E183_WARP_GLOBAL_SOCKS_TAG" 'any(.outbounds[]?;(.tag==$a or .tag==$b))' "$CONFIG" > /dev/null 2>&1; then
                backend=masque;
            else
                backend=auto;
            fi;
        fi;
    fi;
    request=$(_e185_backend_normalize "${request:-$backend}" 2> /dev/null || echo "$backend");
    _e138_state_write 1 "$mode" "$profile" "$family" "$backend" "$request"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_warp_port_preflight
_e186_warp_port_preflight() {
    local lines trace;
    lines=$(_e186_warp_listener_lines 2> /dev/null || true);
    test -z "$lines" && return 0;
    if ! _e186_listener_set_safe "$lines"; then
        error "TCP端口$E138_WARP_PORT存在非回环监听，或缺少Xray所需的127.0.0.1监听；拒绝配置Local proxy。";
        sed 's/^/    /' <<< "$lines";
        return 1;
    fi;
    trace=$(_e186_warp_trace 2> /dev/null || true);
    if _e186_warp_trace_ok "$trace" || _e186_warp_listener_owner_ok "$lines"; then
        return 0;
    fi;
    error "TCP端口$E138_WARP_PORT仅在回环监听，但无法确认属于warp-svc；拒绝覆盖。";
    sed 's/^/    /' <<< "$lines";
    return 1
}
