# EEX3-FUNCTION firewall_warp_e165_188 _e186_warp_status_base
_e186_warp_status_base() {
    local enabled mode profile family backend request integrity=MISSING strategy endpoint warp loc proxy=DOWN;
    _e138_warp_migrate_state > /dev/null 2>&1 || true;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    family=$(_e138_state_get family disabled);
    backend=$(_e138_state_get backend disabled);
    request=$(_e138_state_get backend_request "$backend");
    if test "$mode" = host-full && test "$enabled" = 1; then
        _e183_warp_full_status_base;
        return $?;
    fi;
    if test "$backend" = xray-wg; then
        strategy=$(_e185_wg_strategy "${family:-ipv4}" 2> /dev/null || echo n/a);
    else
        strategy=$(_e185_freedom_strategy "${family:-ipv4}" 2> /dev/null || echo n/a);
    fi;
    _e138_warp_config_integrity "$mode" "$profile" "$family" "$backend" > /dev/null 2>&1 && integrity=CONSISTENT || true;
    title 'V199e186：WARP/Cloudflare状态';
    printf '  %-28s %s\n' '期望状态' "enabled=$enabled mode=$mode profile=$profile family=$family";
    printf '  %-28s %s\n' '请求/实际后端' "$request/$backend";
    printf '  %-28s %s\n' 'Xray目标解析策略' "$strategy";
    printf '  %-28s %s\n' 'Xray配置一致性' "$integrity";
    if test "$backend" = xray-wg; then
        endpoint=$(_e185_state_endpoint);
        endpoint=${endpoint:-missing};
        warp=$(_e185_state_probe_value last_warp unknown);
        loc=$(_e185_state_probe_value last_loc unknown);
        printf '  %-28s %s\n' '实现方式' 'Xray原生WireGuard（noKernelTun=true）';
        printf '  %-28s %s\n' '宿主机默认路由' '不接管';
        printf '  %-28s %s\n' 'WireGuard endpoint' "$endpoint";
        printf '  %-28s %s\n' '最近探针 warp/loc' "$warp/$loc";
        printf '  %-28s %s\n' 'warp-svc' '不需要';
        printf '  %-28s %s\n' 'wgcf配置' "$(test -s "$E185_WG_PROFILE" && echo READY || echo MISSING)";
    else
        _e183_warp_listener_ok && proxy=UP || true;
        printf '  %-28s %s\n' '实现方式' 'Cloudflare官方Local proxy（MASQUE）';
        printf '  %-28s %s\n' 'warp-svc' "$(systemctl is-active "$(_e140_warp_service_name)" 2> /dev/null || echo unknown)";
        printf '  %-28s %s\n' '客户端模式' "$(_e140_warp_mode_current)";
        printf '  %-28s %s\n' '隧道协议' "$(_e140_warp_protocol_current)";
        printf '  %-28s %s\n' '本地代理' "$proxy (127.0.0.1:$E138_WARP_PORT)";
        warp=$(_e136_warp_trace 2> /dev/null || true);
        printf '  %-28s %s\n' 'WARP出口/loc' "$(awk -F= '$1=="ip"{print $2}' <<< "$warp")/$(awk -F= '$1=="loc"{print $2}' <<< "$warp")";
    fi;
    printf '  %-28s %s\n' 'E185诊断' "$E185_WARP_DIAG";
    printf '  %-28s %s\n' 'WireGuard诊断' "$E185_WG_LOG"
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_warp_trace
_e186_warp_trace() {
    curl --proto '=https' --tlsv1.2 -fsS --noproxy '' --proxy "socks5h://127.0.0.1:$E138_WARP_PORT" --connect-timeout 5 --max-time 9 https://www.cloudflare.com/cdn-cgi/trace 2> /dev/null
}
# EEX3-FUNCTION firewall_warp_e165_188 _e186_warp_trace_ok
_e186_warp_trace_ok() {
    local trace="${1:-}" warp loc;
    warp=$(awk -F= '$1=="warp"{print tolower($2)}' <<< "$trace");
    loc=$(awk -F= '$1=="loc"{print toupper($2)}' <<< "$trace");
    [[ "$warp" =~ ^(on|plus)$ ]] && test "$loc" != CN
}
