}
# EEX3-FUNCTION firewall_warp_e165_188 _e188_summary_transaction_self_test
_e188_summary_transaction_self_test() {
    ( local emitted=0;
    function _e188_summary_base () 
    { 
        emitted=$((emitted + 1));
        return 0
    };
    function _e188_install_mode_base () 
    { 
        do_summary;
        do_summary;
        return 0
    };
    _e182_install_mode 1 test > /dev/null || return 1;
    test "$emitted" -eq 1 || return 1;
    emitted=0;
    function _e188_install_mode_base () 
    { 
        do_summary;
        return 7
    };
    if _e182_install_mode 1 test > /dev/null; then
        return 1;
    fi;
    test "$emitted" -eq 0 || return 1;
    emitted=0;
    function _e188_install_mode_base () 
    { 
        E182_SNI_CANCELLED=1;
        do_summary;
        return 0
    };
    _e182_install_mode 1 test > /dev/null || return 1;
    test "$emitted" -eq 0 || return 1;
    emitted=0;
    function _e188_install_mode_base () 
    { 
        do_summary;
        return 0
    };
    _e182_install_mode 3 test > /dev/null || return 1;
    test "$emitted" -eq 1 || return 1;
    emitted=0;
    do_summary > /dev/null || return 1;
    test "$emitted" -eq 1 )
}
