# EEX3-FUNCTION small_bbr_e189_205 _e202_capture_active_config
_e202_capture_active_config() {
    local label="$1" state="$2" conf="$3" out="$4";
    _e202_legacy_active_config_valid "$label" "$state" "$conf" || return 1;
    cp -f -- "$conf" "$out" || return 1;
    case "$label" in 
        196 | 198)
            _e202_legacy_profile_id "$out" "$label" > /dev/null
        ;;
        200)
            _e202_legacy_e200_validate_file "$out"
        ;;
        *)
            _e202_small_bbr_validate_file "$out"
        ;;
    esac
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_check_and_clean_space_base
_e202_check_and_clean_space_base() {
    _e121_check_and_clean_space "$@" || return 1;
    _e159_prune_state_snapshots;
    _e159_prune_network_tx;
    _e159_prune_system_tx
