# EEX3-FUNCTION small_bbr_e189_205 _e202_convert_e200_profile
_e202_convert_e200_profile() {
    local source="$1" out="$2" lines assignments delay_count delay;
    test -f "$source" || return 1;
    lines=$(awk 'NF{n++}END{print n+0}' "$source");
    assignments=$(_e202_small_bbr_assignment_count "$source");
    case "$lines:$assignments" in 
        14:14)
            cp -f -- "$source" "$out" || return 1
        ;;
        23:23)
            delay_count=$(awk -F= '
              {
                k=$1
                gsub(/[[:space:]]/,"",k)
                if (k=="net.ipv4.tcp_tw_reuse_delay") n++
              }
              END {print n+0}
            ' "$source");
            test "$delay_count" -eq 1 || return 1;
            delay=$(_e202_profile_value "$source" net.ipv4.tcp_tw_reuse_delay);
            [[ "$delay" =~ ^[0-9]+$ ]] && test "$delay" -ge 1000 && test "$delay" -le 600000 || return 1;
            awk -F= '
              {
                k=$1
                gsub(/[[:space:]]/,"",k)
                if (k!="net.ipv4.tcp_tw_reuse_delay") print
              }
            ' "$source" > "$out" || return 1;
            cat >> "$out" <<'EOF_E202_E200_RECOVERY_TAIL'
net.ipv4.tcp_sack = 1
net.ipv4.tcp_dsack = 1
net.ipv4.tcp_recovery = 1
EOF_E202_E200_RECOVERY_TAIL

        ;;
        *)
            return 1
        ;;
    esac
    _e202_small_bbr_validate_file "$out"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_current_owner_claimed
_e202_current_owner_claimed() {
    local active_flag unit_state unit_enabled;
    _e202_small_bbr_active && return 0;
    active_flag=$(sed -n 's/^active=//p' "$E202_SMALL_STATE" 2> /dev/null | tail -n1);
    test "$active_flag" = 1 && return 0;
    unit_state=$(systemctl is-active "$E202_SMALL_UNIT" 2> /dev/null || true);
    case "$unit_state" in 
        active | activating | reloading)
            return 0
        ;;
    esac;
    unit_enabled=$(systemctl is-enabled "$E202_SMALL_UNIT" 2> /dev/null || true);
    case "$unit_enabled" in 
        enabled | enabled-runtime | linked | linked-runtime | alias)
            return 0
        ;;
    esac;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_delegate_legacy_small_bbr_exit
_e202_delegate_legacy_small_bbr_exit() {
    local version="$1" script="$2" active_fn="$3" unit="$4" reported state enabled;
    local label="${version#199e}";
    "$active_fn" || return 0;
    test -r "$script" || { 
        error "检测到E${label}小BBR仍启用，但原版退出脚本缺失：$script";
        error "请恢复原版ex${version}.sh后执行：bash $script --small-bbr-disable";
        return 1
    };
    bash -n "$script" > /dev/null 2>&1 || { 
        error "原版E${label}脚本语法检查失败，拒绝由新版本猜测旧快照。";
        return 1
    };
    reported=$(bash "$script" --version 2> /dev/null | tail -n1 || true);
    test "$reported" = "$version" || { 
        error "旧脚本身份不符：期望=$version 实际=${reported:-unknown} 路径=$script";
        return 1
    };
    warn "检测到E${label}小BBR；按稳态迁移规则，先由原版E${label}自己退出旧档位。";
    bash "$script" --small-bbr-disable || { 
        error "原版E${label}退出失败；热更新尚未开始。";
        error "请手动执行：bash $script --small-bbr-disable";
        return 1
    };
    "$active_fn" && { 
        error "原版E${label}返回成功但状态仍标记active；停止热更新。";
        return 1
    };
    state=$(systemctl is-active "$unit" 2> /dev/null || true);
    case "$state" in 
        active | activating | reloading)
            error "原版E${label}退出后旧服务仍在运行：$unit";
            return 1
        ;;
    esac;
    enabled=$(systemctl is-enabled "$unit" 2> /dev/null || true);
    case "$enabled" in 
        enabled | enabled-runtime | linked | linked-runtime | alias)
            error "原版E${label}退出后旧服务仍设为开机启动：$unit";
            error '拒绝继续，避免重启后旧网络所有者复活。';
            return 1
        ;;
    esac;
    info "原版E${label}已退出旧小BBR并恢复其原始基线；现在才允许进入E202热更新。"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_full_network_apply_base
_e202_full_network_apply_base() {
    local enabled=0 mode=disabled tx="" rc=0;
    if declare -F _e138_state_get > /dev/null 2>&1; then
        enabled=$(_e138_state_get route_enabled 0);
        mode=$(_e138_state_get route_mode disabled);
    fi;
    _e159_network_apply_exact_base "$@" || return 1;
    if test "$enabled" = 1 && test "$mode" = host-full; then
        if ! _e140_full_route_apply; then
            tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2> /dev/null | tail -n1);
            error 'E159网络已应用，但host-full原IPv4回程策略无法重建；恢复网络事务。';
            test -z "$tx" || _e159_network_restore "$tx" || rc=1;
            _e140_full_route_apply > /dev/null 2>&1 || rc=1;
            test "$rc" -eq 0 || error '严重：网络恢复后host-full原IPv4回程仍未恢复。';
            return 1;
        fi;
        if test "${E159_DEFER_HOST_FULL_VERIFY:-0}" = 1; then
            info 'E159网络重放后已恢复host-full原IPv4回程；完整WARP验证延后到热更新专用阶段。';
            return 0;
        fi;
        if _e140_full_verify; then
            info 'E159网络重放后Cloudflare host-full及SSH/Xray原IPv4回程已复检。';
            return 0;
        fi;
        tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2> /dev/null | tail -n1);
        error 'E159网络已应用，但host-full完整复检失败；恢复网络事务。';
        test -z "$tx" || _e159_network_restore "$tx" || rc=1;
        _e140_full_route_apply > /dev/null 2>&1 || rc=1;
        _e140_full_verify > /dev/null 2>&1 || rc=1;
        test "$rc" -eq 0 || error '严重：网络恢复后host-full仍未通过复检。';
        return 1;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_full_network_owner_present
_e202_full_network_owner_present() {
    local class p unit;
    class=$(_eex3_network_owner_classify) || return 0;
    case "$class" in 
        valid-active | invalid-live)
            return 0
        ;;
        none | inert-residue)

        ;;
        *)
            return 0
        ;;
    esac;
    for p in /etc/sysctl.d/99-xray-e{125-accel,126-accel,135-network,136-network,138-network,139-network,142-network,143-network,145-network}.conf "$E202_LEGACY_E190_CONF" "$E202_LEGACY_E192_CONF" "$E202_LEGACY_E194_CONF" "$E202_LEGACY_E196_CONF" "$E202_LEGACY_E198_CONF" "$E202_LEGACY_E200_CONF";
    do
        if test -f "$p"; then
            test -r "$p" || return 0;
            grep -Eq '^[[:space:]]*-?[A-Za-z0-9_./*-]+[[:space:]]*=' "$p" && return 0;
        else
            if test -e "$p" || test -L "$p"; then
                return 0;
            fi;
        fi;
    done;
    for unit in xray-accel-e125.service xray-accel-e126.service xray-hw-tweaks.service "$E202_LEGACY_E190_UNIT" "$E202_LEGACY_E192_UNIT" "$E202_LEGACY_E194_UNIT" "$E202_LEGACY_E196_UNIT" "$E202_LEGACY_E198_UNIT" "$E202_LEGACY_E200_UNIT";
    do
        _eex3_systemd_unit_claimed "$unit" && return 0;
    done;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_help
_e202_help() {
    cat <<'EOF_E202_HELP'
V199e202:
  --hot-update                         事务热更新到E202
  --small-bbr-menu                     八个预设档位与14/25/26项自定义菜单
  --small-bbr-enable                   启用当前保存档（无保存值时模式2）
  --small-bbr-status                   只读查看当前14/25/26项及重复定义
  --small-bbr-reconcile                开机/手动复检并仅重写当前档位
  --small-bbr-disable                  退出并恢复启用前网络档位
  --summary                            手动导出节点URI、单次终端QR及PNG/SVG
  --self-test                          E202快速发行门禁
  --structure-audit                    E202最终绑定审计
EOF_E202_HELP

}
# EEX3-FUNCTION small_bbr_e189_205 _e202_hot_step
_e202_hot_step() {
    local phase="$1";
    shift;
    _e159_phase_log "$E202_HOT_LOG" "$phase" begin;
    if "$@"; then
        _e159_phase_log "$E202_HOT_LOG" "$phase" ok;
        return 0;
    fi;
    _e159_phase_log "$E202_HOT_LOG" "$phase" fail;
    error "E202热更新失败阶段：$phase";
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_hot_update
_e202_hot_update() {
    ( local small_owner=none outer="" rc=0 legacy_profile_tmp="" legacy_source="";
    local legacy_raw_tmp="" saved_profile_snapshot="";
    local assignments=0 profile_id="";
    if _e202_small_bbr_active; then
        small_owner=e202;
    else
        if _e202_legacy_e200_active; then
            small_owner=e200;
        else
            if _e202_legacy_e198_active; then
                small_owner=e198;
            else
                if _e202_legacy_e196_active; then
                    small_owner=e196;
                else
                    if _e202_legacy_e194_active; then
                        small_owner=e194;
                    else
                        if _e202_legacy_e192_active; then
                            small_owner=e192;
                        else
                            if _e202_legacy_e190_active; then
                                small_owner=e190;
                            fi;
                        fi;
                    fi;
                fi;
            fi;
        fi;
    fi;
    if test "$small_owner" = e202; then
        outer=$(_e202_new_tx hot-update-outer) || return 1;
        _e140_system_snapshot "$outer/system" || return 1;
        _e202_snapshot_valid "$outer/system" || return 1;
        legacy_profile_tmp=$(_e118_mktemp e202-active-profile-import) || return 1;
        _e202_capture_active_config 202 "$E202_SMALL_STATE" "$E202_SMALL_CONF" "$legacy_profile_tmp" || return 1;
        saved_profile_snapshot="$outer/saved-profile-choice";
        _e135_snapshot_file "$E202_SMALL_PROFILE" "$saved_profile_snapshot" || return 1;
        _e202_small_bbr_disable force || { 
            _e202_small_bbr_restore_snapshot "$outer/system" hot-preflight-restore || true;
            return 1
        };
    else
        if test "$small_owner" = e200; then
            legacy_profile_tmp=$(_e118_mktemp e200-profile-import) || return 1;
            legacy_raw_tmp=$(_e118_mktemp e200-active-profile-raw) || return 1;
            _e202_capture_active_config 200 "$E202_LEGACY_E200_STATE" "$E202_LEGACY_E200_CONF" "$legacy_raw_tmp" || return 1;
            if _e202_legacy_e200_validate_file "$E202_LEGACY_E200_PROFILE" && ! cmp -s "$E202_LEGACY_E200_PROFILE" "$E202_LEGACY_E200_CONF"; then
                warn 'E200另有尚未应用的保存档；本次只迁移状态哈希密封的活动档，旧保存文件继续保留供人工核对。';
            fi;
            _e202_prepare_legacy_profile 200 "$legacy_raw_tmp" "$legacy_profile_tmp" || return 1;
            _e202_legacy_e200_disable || return 1;
        else
            if test "$small_owner" = e198; then
                legacy_profile_tmp=$(_e118_mktemp e198-profile-import) || return 1;
                legacy_raw_tmp=$(_e118_mktemp e198-active-profile-raw) || return 1;
                _e202_capture_active_config 198 "$E202_LEGACY_E198_STATE" "$E202_LEGACY_E198_CONF" "$legacy_raw_tmp" || return 1;
                if _e202_legacy_profile_id "$E202_LEGACY_E198_PROFILE" 198 > /dev/null && ! cmp -s "$E202_LEGACY_E198_PROFILE" "$E202_LEGACY_E198_CONF"; then
                    warn 'E198另有尚未应用的保存档；本次只迁移状态哈希密封的活动档，旧保存文件继续保留供人工核对。';
                fi;
                _e202_prepare_legacy_profile 198 "$legacy_raw_tmp" "$legacy_profile_tmp" || return 1;
                _e202_legacy_e198_disable || return 1;
            else
                if test "$small_owner" = e196; then
                    legacy_profile_tmp=$(_e118_mktemp e196-profile-import) || return 1;
                    legacy_raw_tmp=$(_e118_mktemp e196-active-profile-raw) || return 1;
                    _e202_capture_active_config 196 "$E202_LEGACY_E196_STATE" "$E202_LEGACY_E196_CONF" "$legacy_raw_tmp" || return 1;
                    legacy_source="$legacy_raw_tmp";
                    if _e202_legacy_profile_id "$E202_LEGACY_E196_PROFILE" 196 > /dev/null && ! cmp -s "$E202_LEGACY_E196_PROFILE" "$E202_LEGACY_E196_CONF"; then
                        warn 'E196另有尚未应用的保存档；本次只迁移已密封的活动档，旧保存文件继续保留供人工核对。';
                    fi;
                    _e202_prepare_legacy_profile 196 "$legacy_source" "$legacy_profile_tmp" || return 1;
                    _e202_legacy_e196_disable || return 1;
                else
                    if test "$small_owner" = e194; then
                        legacy_profile_tmp=$(_e118_mktemp e194-profile-import) || return 1;
                        _e202_capture_active_config 194 "$E202_LEGACY_E194_STATE" "$E202_LEGACY_E194_CONF" "$legacy_profile_tmp" || return 1;
                        if _e202_small_bbr_validate_file "$E202_LEGACY_E194_PROFILE" && ! cmp -s "$E202_LEGACY_E194_PROFILE" "$E202_LEGACY_E194_CONF"; then
                            warn 'E194另有尚未应用的保存档；本次只迁移已密封的活动档。';
                        fi;
                        _e202_legacy_e194_disable || return 1;
                    else
                        if test "$small_owner" = e192; then
                            _e202_legacy_e192_disable || return 1;
                        else
                            if test "$small_owner" = e190; then
                                _e202_legacy_e190_disable || return 1;
                            fi;
                        fi;
                    fi;
                fi;
            fi;
        fi;
    fi;
    _e202_hot_update_base || rc=1;
    if test "$rc" -eq 0; then
        case "$small_owner" in 
            e202 | e194 | e196 | e198 | e200)
                _e202_small_bbr_profile_save "$legacy_profile_tmp" || rc=1
            ;;
        esac;
    fi;
    if test "$rc" -eq 0 && test "$small_owner" != none; then
        _e202_small_bbr_enable force || rc=1;
    fi;
    if test "$rc" -ne 0 && test "$small_owner" = e202; then
        error 'E202热更新/小BBR重入失败，恢复热更新前的E202活动档位。';
        _e202_small_bbr_restore_snapshot "$outer/system" hot-update-failed || true;
        return 1;
    fi;
    if test "$rc" -ne 0 && test "$small_owner" != none; then
        error "E202热更新/小BBR重入失败；原版${small_owner}已安全退出，当前保留已通过回滚复检的非小BBR网络状态。";
        error '拒绝由E202反向猜测并重建旧版本档位。';
        return 1;
    fi;
    if test "$small_owner" = e202; then
        _e135_restore_file "$E202_SMALL_PROFILE" "$saved_profile_snapshot" || { 
            error 'E202活动档已重入，但恢复热更新前的待应用保存档失败；执行总回滚。';
            _e202_small_bbr_restore_snapshot "$outer/system" hot-saved-choice-failed || true;
            return 1
        };
    fi;
    if test "$small_owner" != none; then
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF");
        profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF");
        info "热更新后已进入E202：$(_e202_small_bbr_profile_name "$profile_id")；持久参数=$assignments，隐藏参数=0。";
    fi;
    return "$rc" )
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_hot_update_base
_e202_hot_update_base() {
    _eex6_step hot-ssh-baseline _eex3_ssh_upgrade_baseline_verify || return $?;
    _eex6_step hot-install-entries _e214_install_self || return $?;
    _eex6_step hot-ipv6 _e182_ipv6_hot_apply_default || return $?;
    _eex6_step hot-warp-state _e138_warp_migrate_state || return $?;
    _eex6_step hot-core-update-policy _e105_disable_xray_core_auto_update || return $?;
    _eex6_step hot-init30 _e137_apply_init_window_default30 || return $?;
    _eex6_step hot-network-owner _eex3_network_owner_converge || return $?;
    if test "${EEX3_AUTO_ACTIVE:-0}" != 1; then
        _eex6_step hot-item28 _eex3_apply_item28_components || return $?;
    fi;
    _eex6_step hot-write-version _e202_write_version || return $?;
    _eex6_step hot-readback _e214_hot_verify || return $?;
    _eex6_step hot-ssh-final _eex3_ssh_upgrade_baseline_verify
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_hot_update_preflight
_e202_hot_update_preflight() {
    if test "${EEX3_AUTO_ACTIVE:-0}" = 1; then
        _eex3_upgrade_dependencies && _e118_xray_test_config "$CONFIG" 1;
    else
        _eex3_e202_preflight_legacy "$@";
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_inherited_core_self_test
_e202_inherited_core_self_test() {
    ( local d fake out png svg diag family strategy mode menu rc=0;
    d=$(mktemp -d /tmp/xray-e202-core-test.XXXXXX) || return 1;
    _e186_listener_set_safe "LISTEN 0 4096 127.0.0.1:$E138_WARP_PORT 0.0.0.0:* users:((\"warp-svc\",pid=1,fd=1))" && ! _e186_listener_set_safe "LISTEN 0 4096 0.0.0.0:$E138_WARP_PORT 0.0.0.0:*" && ! _e186_listener_set_safe "LISTEN 0 4096 [::]:$E138_WARP_PORT [::]:*" && _e186_warp_trace_ok 'warp=on
loc=US
' && ! _e186_warp_trace_ok 'warp=off
loc=US
' || rc=1;
    fake="$d/bin";
    mkdir -p "$fake" || rc=1;
    cat > "$fake/qrencode" <<'EOF_E202_FAKE_QR'
#!/usr/bin/env bash
type=
out=
while test "$#" -gt 0; do
    case "$1" in
        --version) echo 'qrencode mock 1'; exit 0 ;;
        -t) type="$2"; shift 2 ;;
        -o) out="$2"; shift 2 ;;
        -l|-m|-s) shift 2 ;;
        *) shift ;;
    esac
done
case "$type" in
    UTF8) printf 'discarded-partial\n'; exit 1 ;;
    ANSIUTF8) printf 'single-terminal-qr\n'; exit 0 ;;
    PNG) printf '\211PNG\r\n\032\nmock' >"$out"; exit 0 ;;
    SVG) printf '<svg xmlns="http://www.w3.org/2000/svg"></svg>\n' >"$out"; exit 0 ;;
    *) exit 1 ;;
esac
EOF_E202_FAKE_QR

    chmod 0755 "$fake/qrencode" || rc=1;
    function qrencode () 
    { 
        bash "$fake/qrencode" "$@"
    };
    diag="$d/qr.log";
    out=$(PATH="$fake:$PATH" _e188_qr_terminal 'vless://unit-test' "$diag" 2> /dev/null || true);
    test "$out" = single-terminal-qr || rc=1;
    png="$d/test.png";
    svg="$d/test.svg";
    PATH="$fake:$PATH" _e186_qr_generate_files 'vless://unit-test' "$png" "$svg" "$diag" && _e186_png_valid "$png" && _e186_svg_valid "$svg" || rc=1;
    if command -v jq > /dev/null 2>&1; then
        cat > "$d/base.json" <<'EOF_E202_WARP_BASE'
{"dns":{"servers":["1.1.1.1"],"queryStrategy":"UseIPv4"},"outbounds":[{"tag":"direct","protocol":"freedom","settings":{"domainStrategy":"UseIPv4"}},{"tag":"block","protocol":"blackhole"}],"routing":{"domainStrategy":"AsIs","rules":[]}}
EOF_E202_WARP_BASE

        for family in ipv4 ipv6 dual;
        do
            out="$d/warp-$family.json"
            _e138_warp_config_build global global true "$out" "$d/base.json" "$family" masque || rc=1;
            strategy=$(_e185_freedom_strategy "$family");
            jq -e --arg w "$E185_WARP_GLOBAL_TAG" --arg s "$E185_WARP_GLOBAL_SOCKS_TAG" --arg st "$strategy" '
              any(.outbounds[]?;.tag==$s and .protocol=="socks" and .settings.address=="127.0.0.1") and
              any(.outbounds[]?;.tag==$w and .protocol=="freedom" and .settings.domainStrategy==$st and .proxySettings.tag==$s) and
              .dns.queryStrategy=="UseIPv4"
            ' "$out" > /dev/null 2>&1 || rc=1;
        done;
        BEST_SNI=www.example.com;
        SNI_JSON_ARRAY='["www.example.com"]';
        REMARK_NAME=e202-selftest;
        E79_VLESSENC_NETWORK=raw;
        function _e118_generate_reality_material () 
        { 
            E77_REALITY_PRIV=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA;
            E77_REALITY_PUB=BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB;
            E77_REALITY_UUID=11111111-1111-4111-8111-111111111111;
            E77_REALITY_SID=a1b2c3d4
        };
        function e77_generate_vlessenc_pair () 
        { 
            E77_VLESSENC_DECRYPTION=mlkem768x25519plus.native.0rtt;
            E77_VLESSENC_ENCRYPTION=mlkem768x25519plus.native.0rtt
        };
        for mode in 1 2 3 4;
        do
            out="$d/node-$mode.json";
            e79_build_full_config "$mode" 443 8443 8388 2022-blake3-aes-128-gcm AAAAAAAAAAAAAAAAAAAAAA== "$out" || rc=1;
            jq -e --arg m "$mode" '
              ([.outbounds[]|select(.tag=="direct" and .protocol=="freedom" and .settings.targetStrategy=="UseIPv4")]|length)==1 and
              (if $m=="1" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==0
               elif $m=="2" then ([.inbounds[]|select(.protocol=="vless" and .streamSettings.security=="none")]|length)==1
               elif $m=="3" then ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1 and ([.inbounds[]|select(.protocol=="vless")]|length)==0
               elif $m=="4" then ([.inbounds[]|select(.streamSettings.security=="reality")]|length)==1 and ([.inbounds[]|select(.protocol=="shadowsocks")]|length)==1
               else false end)
            ' "$out" > /dev/null 2>&1 || rc=1;
        done;
    fi;
    menu=$(declare -f _e202_main_menu_impl 2> /dev/null || true);
    grep -q '_e138_warp_selective_menu' <<< "$menu" && grep -q '_e138_warp_global_menu' <<< "$menu" && grep -q '_e140_warp_full_menu' <<< "$menu" && grep -q '_e182_ipv6_menu' <<< "$menu" && grep -q '_e202_small_bbr_menu' <<< "$menu" || rc=1;
    rm -rf -- "$d";
    return "$rc" )
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_install_self
_e202_install_self() {
    _e214_install_self "$@"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_legacy_active_config_valid
_e202_legacy_active_config_valid() {
    local label="$1" state="$2" conf="$3" stored_sha actual_sha;
    local stored_assignments actual_assignments;
    case "$label" in 
        196 | 198)
            _e202_legacy_profile_id "$conf" "$label" > /dev/null || { 
                error "E${label}活动配置不是可证明的内置14/21项档位：$conf";
                return 1
            }
        ;;
        200)
            _e202_legacy_e200_validate_file "$conf" || { 
                error "E200活动小BBR持久配置缺失或不是可转换的14/23项档位：$conf";
                return 1
            }
        ;;
        *)
            _e202_small_bbr_validate_file "$conf" || { 
                error "E${label}活动小BBR持久配置缺失或格式无效：$conf";
                return 1
            }
        ;;
    esac;
    stored_sha=$(sed -n 's/^config_sha256=//p' "$state" 2> /dev/null | tail -n1);
    actual_sha=$(sha256sum "$conf" 2> /dev/null | awk '{print $1}');
    [[ "$stored_sha" =~ ^[0-9a-f]{64}$ ]] && test "$stored_sha" = "$actual_sha" || { 
        error "E${label}活动配置哈希与状态不一致；拒绝猜测迁移。";
        return 1
    };
    stored_assignments=$(sed -n 's/^persistent_assignments=//p' "$state" 2> /dev/null | tail -n1);
    actual_assignments=$(_e202_small_bbr_assignment_count "$conf");
    [[ "$stored_assignments" =~ ^[0-9]+$ ]] && test "$stored_assignments" -eq "$actual_assignments" || { 
        error "E${label}活动配置项数与状态不一致；拒绝猜测迁移。";
        return 1
    }
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_legacy_e190_active
_e202_legacy_e190_active() {
    test -s "$E202_LEGACY_E190_STATE" && test "$(sed -n 's/^active=//p' "$E202_LEGACY_E190_STATE" 2> /dev/null | tail -n1)" = 1 && test "$(sed -n 's/^profile=//p' "$E202_LEGACY_E190_STATE" 2> /dev/null | tail -n1)" = small-bbr-6
}
