        SERVER_IP=$(_get_ip);
        echo -e "${magenta}======================================================================${none}";
        echo -e "  ${cyan}Xray System Advanced Management V199e202 - 事务稳态版${none}";
        echo -e "  ${green}引擎:${none} $(systemctl is-active xray 2> /dev/null || echo unknown) | ${cyan}快捷指令:${none} xrv | ${cyan}公网IP:${none} ${SERVER_IP:-unknown}";
        echo -e "${magenta}======================================================================${none}";
        echo "  1) 安装 / 重装节点（Reality / Reality+SS2022 / VLESSENC / SS2022）";
        echo "  2) Reality 用户、UUID、SNI、端口与密钥管理";
        echo "  3) 节点链接与参数输出";
