# EEX3-FUNCTION small_bbr_e189_205 _e202_network_audit
_e202_network_audit() {
    if _e202_small_bbr_active; then
        _e202_small_bbr_status;
    else
        if _e202_current_owner_claimed; then
            _e202_small_bbr_status;
        else
            if _e202_legacy_e200_active; then
                warn '当前仍是E200旧小BBR；请先用原版E200执行 --small-bbr-disable并确认恢复，再运行菜单11。';
                _e202_legacy_e200_status;
            else
                if _e202_legacy_e198_active; then
                    warn '当前仍是E198旧小BBR；请先用原版E198执行 --small-bbr-disable并确认恢复，再运行菜单11。';
                    _e202_legacy_e198_status;
                else
                    if _e202_legacy_e196_active; then
                        warn '当前仍是E196旧小BBR；请先用原版E196执行 --small-bbr-disable并确认恢复，再运行菜单11。';
                        _e202_legacy_e196_status;
                    else
                        if _e202_legacy_e190_active; then
                            warn '当前仍是E190旧小BBR；请先用原版E190执行 --small-bbr-disable并确认恢复，再运行菜单11。';
                            _e202_legacy_e190_status;
                        else
                            if _e202_legacy_e192_active; then
                                warn '当前仍是E192旧小BBR；请先用原版E192执行 --small-bbr-disable并确认恢复，再运行菜单11。';
                                _e202_legacy_e192_status;
                            else
                                if _e202_legacy_e194_active; then
                                    warn '当前仍是E194旧小BBR；请先用原版E194执行 --small-bbr-disable并确认恢复，再运行菜单11。';
                                    _e202_legacy_e194_status;
                                else
                                    _e159_network_audit;
                                fi;
                            fi;
                        fi;
                    fi;
                fi;
            fi;
        fi;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_network_params_menu
_e202_network_params_menu() {
    local num="" owner="系统/完整参数档位";
    while true; do
        owner='系统/完整参数档位';
        if _e202_small_bbr_active; then
            owner='E202兼容小BBR（八档14/25/26项）';
        else
            if _e202_current_owner_claimed; then
                owner='E202小BBR（状态异常，禁止覆盖）';
            else
                if _e202_legacy_e200_active; then
                    owner='E200旧小BBR（待升级）';
                else
                    if _e202_legacy_e198_active; then
                        owner='E198旧小BBR（待升级）';
                    else
                        if _e202_legacy_e196_active; then
                            owner='E196旧小BBR（待升级）';
                        else
                            if _e202_legacy_e194_active; then
                                owner='E194旧小BBR（待升级）';
                            else
                                if _e202_legacy_e192_active; then
                                    owner='E192旧小BBR（待升级）';
                                else
                                    if _e202_legacy_e190_active; then
                                        owner='E190旧小BBR（待升级）';
                                    fi;
                                fi;
                            fi;
                        fi;
                    fi;
                fi;
            fi;
        fi;
        clear;
        title '网络参数中心（V199e202：默认 initcwnd/initrwnd=30）';
        echo "  当前网络档位: $owner";
        echo '  1) 进入完整127条请求 / 125个持久控制事务菜单';
        echo ' 35) 查看 initcwnd/initrwnd 状态';
        echo ' 36) 事务应用 initcwnd/initrwnd=30';
        echo ' 37) 按当前档位只读审计（小BBR=14/25/26项；完整档位=127条）';
        echo '  0) 返回';
        read -rp '请输入操作代码: ' num || true;
        case "$num" in 
            1)
                _e182_network_menu
            ;;
            35)
                _e88_show_init_window_state;
                _e116_pause
            ;;
            36)
                _e182_apply_init30_tx || true;
                _e116_pause
            ;;
            37)
                _e202_network_audit || true;
                _e116_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn '无效操作。';
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_new_tx
_e202_new_tx() {
    local name="${1:-transaction}" dir;
    _e202_prepare || return 1;
    dir="$E202_TX_ROOT/${name}-$(date +%Y%m%d_%H%M%S)-$$-$RANDOM";
    install -d -m 0700 "$dir" || return 1;
    printf '%s\n' "$dir"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_prepare
_e202_prepare() {
    _e188_prepare || return 1;
    install -d -m 0700 "$E202_DIR" "$E202_TX_ROOT" "$(dirname "$E202_HOT_LOG")" || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_prepare_exclusive_small_profile
_e202_prepare_exclusive_small_profile() {
    if _e202_unrecognized_current_active; then
        return 1;
    fi;
    if _e202_recognized_legacy_active; then
        return 1;
    fi;
    if _e202_unrecognized_legacy_active; then
        return 1;
    fi;
    _e159_network_remove force || return 1;
    _e202_retire_confirmed_legacy_layers || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_prepare_legacy_profile
_e202_prepare_legacy_profile() {
    local label="$1" source="$2" out="$3" id new_id;
    if test "$label" = 200; then
        _e202_convert_e200_profile "$source" "$out" || { 
            error 'E200活动档不是可验证的14/23项档位；拒绝删除参数或退出旧档。';
            return 1
        };
        id=$(_e202_small_bbr_profile_id_file "$out") || return 1;
        info "已密封E200活动档：移除tcp_tw_reuse_delay并显式加入SACK/DSACK/RACK；将迁移为E202的${id}（14/25项）。";
        return 0;
    fi;
    id=$(_e202_legacy_profile_id "$source" "$label") || { 
        error "E${label}活动档不是可证明的内置14/21项预设；为避免猜测迁移，热更新尚未退出旧档。";
        error "请先用原版E${label}切换到内置模式1/2/3/1F/2F/3F/B，或先退出旧小BBR。";
        return 1
    };
    new_id="$id";
    if test "$id" = modeb; then
        _e202_legacy_old_profile modeb 300 | sed -n '1,14p' > "$out" || return 1;
        _e202_small_bbr_f_tail >> "$out" || return 1;
        new_id=custom-f;
    else
        "_e202_small_bbr_${new_id}" > "$out" || return 1;
    fi;
    _e202_small_bbr_validate_file "$out" || return 1;
    info "已验证E${label}活动内置档${id}，将迁移为E202的${new_id}（14/25项新规格）。"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_profile_value
_e202_profile_value() {
    local file="$1" wanted="$2";
    awk -F= -v wanted="$wanted" '{
      k=$1
      gsub(/[[:space:]]/,"",k)
      if (k==wanted) {
        v=substr($0,index($0,"=")+1)
        gsub(/^[[:space:]]+|[[:space:]]+$/,"",v)
        print v
        exit
      }
    }' "$file"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_prune_tx
_e202_prune_tx() {
    if test "${EEX3_NO_AUTO_GC:-0}" = 1; then
        return 0;
    fi;
    _eex3_retention_e202_prune_tx "$@"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_prune_tx_root
_e202_prune_tx_root() {
    if test "${EEX3_NO_AUTO_GC:-0}" = 1; then
        return 0;
    fi;
    _eex3_retention_e202_prune_tx_root "$@"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_recognized_legacy_active
_e202_recognized_legacy_active() {
    local label fn row;
    local -a rows=("190|_e202_legacy_e190_active" "192|_e202_legacy_e192_active" "194|_e202_legacy_e194_active" "196|_e202_legacy_e196_active" "198|_e202_legacy_e198_active" "200|_e202_legacy_e200_active");
    for row in "${rows[@]}";
    do
        IFS='|' read -r label fn <<< "$row";
        if "$fn"; then
            error "E${label}旧小BBR仍是活动所有者；拒绝由E202清理其文件或服务。";
            error "请先使用原版ex199e${label}.sh执行 --small-bbr-disable。";
            return 0;
        fi;
    done;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_restore_network_baseline_base
_e202_restore_network_baseline_base() {
    _e159_network_remove force || return 1;
    _e159_restore_network_baseline_base "$@"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_retire_confirmed_legacy_layers
_e202_retire_confirmed_legacy_layers() {
    local f;
    systemctl disable --now "$E202_LEGACY_E190_UNIT" "$E202_LEGACY_E192_UNIT" "$E202_LEGACY_E194_UNIT" "$E202_LEGACY_E196_UNIT" "$E202_LEGACY_E198_UNIT" "$E202_LEGACY_E200_UNIT" xray-network-e159.timer xray-network-e159.service xray-network-e156.timer xray-network-e156.service xray-network-e154.timer xray-network-e154.service xray-network-e152.timer xray-network-e152.service xray-hw-tweaks.service xray-accel-e125.service xray-accel-e126.service > /dev/null 2>&1 || true;
    for f in "$E202_LEGACY_E190_CONF" "$E202_LEGACY_E190_STATE" "$E202_LEGACY_E190_SERVICE" "$E202_LEGACY_E192_CONF" "$E202_LEGACY_E192_STATE" "$E202_LEGACY_E192_SERVICE" "$E202_LEGACY_E194_CONF" "$E202_LEGACY_E194_STATE" "$E202_LEGACY_E194_SERVICE" "$E202_LEGACY_E196_CONF" "$E202_LEGACY_E196_STATE" "$E202_LEGACY_E196_SERVICE" "$E202_LEGACY_E198_CONF" "$E202_LEGACY_E198_STATE" "$E202_LEGACY_E198_SERVICE" "$E202_LEGACY_E200_CONF" "$E202_LEGACY_E200_STATE" "$E202_LEGACY_E200_SERVICE" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_SCRIPT" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER" "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_SERVICE" "$E159_LEGACY_E156_TIMER" "$E159_LEGACY_E154_EFFECTIVE_CONF" "$E159_LEGACY_E154_SERVICE" "$E159_LEGACY_E154_TIMER" /etc/sysctl.d/99-xray-e125-accel.conf /etc/sysctl.d/99-xray-e126-accel.conf /etc/sysctl.d/99-xray-e135-network.conf /etc/sysctl.d/99-xray-e136-network.conf /etc/sysctl.d/99-xray-e138-network.conf /etc/sysctl.d/99-xray-e139-network.conf /etc/sysctl.d/99-xray-e142-network.conf /etc/sysctl.d/99-xray-e143-network.conf /etc/sysctl.d/99-xray-e145-network.conf;
    do
        rm -f -- "$f" 2> /dev/null || return 1;
    done;
    for f in /etc/sysctl.d/99-network-optimized.conf /etc/sysctl.d/98-xray-core-tuning.conf /etc/sysctl.d/99-xray-hotupdate-fast.conf /etc/sysctl.d/99-xray-pmtu-e106.conf /etc/sysctl.d/99-xray-pmtu-e107.conf /etc/sysctl.d/99-auto-tune-relay-e108.conf /etc/sysctl.d/99-auto-tune-relay-e109.conf;
    do
        test -e "$f" || continue;
        if _e159_legacy_sysctl_owned "$f"; then
            rm -f -- "$f" || return 1;
        else
            warn "保留无法确认归属的sysctl文件：$f；小BBR状态页会逐键报告其重复定义。";
        fi;
    done;
    systemctl daemon-reload > /dev/null 2>&1 || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_self_test
_e202_self_test() {
    local rc=0;
    echo 'V199e202 fast release gate:';
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' || { 
        echo '  [FAIL] bash syntax';
        rc=1
    };
    test "$SCRIPT_VERSION" = 199e202 && test "$E202_VERSION" = 199e202 && echo '  [PASS] release identity' || { 
        echo '  [FAIL] release identity';
        rc=1
    };
    _e188_summary_transaction_self_test && echo '  [PASS] inherited one-summary/one-QR transaction gate' || { 
        echo '  [FAIL] inherited QR transaction gate';
        rc=1
    };
    _e202_inherited_core_self_test && echo '  [PASS] inherited Xray/WARP/QR behavior gate' || { 
        echo '  [FAIL] inherited Xray/WARP/QR behavior gate';
        rc=1
    };
    _e202_small_bbr_self_test && echo '  [PASS] eight exact 14/25/26-line profiles; no hidden knobs' || { 
        echo '  [FAIL] small-BBR eight-profile invariant';
        rc=1
    };
    _e202_structure_audit > /dev/null && echo '  [PASS] menu/hot-update/rollback final bindings' || { 
        echo '  [FAIL] E202 structure binding';
        rc=1
    };
    test "$rc" -eq 0 && echo 'V199e202 result: PASS' || echo 'V199e202 result: FAIL';
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_active
_e202_small_bbr_active() {
    test -s "$E202_SMALL_STATE" && test "$(sed -n 's/^active=//p' "$E202_SMALL_STATE" 2> /dev/null | tail -n1)" = 1 && test "$(sed -n 's/^profile=//p' "$E202_SMALL_STATE" 2> /dev/null | tail -n1)" = small-bbr-multi
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_all_keys
_e202_small_bbr_all_keys() {
    { 
        _e202_small_bbr_base_keys;
        _e202_small_bbr_extra_keys;
        _e202_small_bbr_f2_extra_keys
    } | awk 'NF&&!seen[$0]++'
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_apply_runtime
_e202_small_bbr_apply_runtime() {
    local key value;
    _e202_small_bbr_validate_file "$E202_SMALL_CONF" || { 
        error "小BBR持久文件不是合法的14/25/26行档位：$E202_SMALL_CONF";
        return 1
    };
    _e202_small_bbr_kernel_ready || return 1;
    for key in net.core.default_qdisc net.ipv4.tcp_congestion_control net.core.rmem_max net.core.wmem_max net.core.rmem_default net.core.wmem_default net.ipv4.tcp_rmem net.ipv4.tcp_wmem net.ipv4.tcp_moderate_rcvbuf net.ipv4.tcp_window_scaling net.ipv4.tcp_adv_win_scale net.ipv4.tcp_mtu_probing net.ipv4.tcp_ecn net.ipv4.tcp_slow_start_after_idle net.ipv4.tcp_max_reordering net.ipv4.tcp_fastopen net.ipv4.tcp_timestamps net.ipv4.tcp_tw_reuse net.ipv4.tcp_fin_timeout net.ipv4.tcp_max_syn_backlog net.core.netdev_max_backlog net.core.somaxconn net.ipv4.tcp_sack net.ipv4.tcp_dsack net.ipv4.tcp_recovery net.ipv4.tcp_max_tw_buckets;
    do
        value=$(_e202_profile_value "$E202_SMALL_CONF" "$key");
        test -n "$value" || continue;
        sysctl -w "$key=$value" > /dev/null 2>&1 || { 
            error "小BBR写入失败：$key";
            return 1
        };
    done;
    _e202_small_bbr_verify_runtime "$E202_SMALL_CONF"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_assignment_count
_e202_small_bbr_assignment_count() {
    local file="$1";
    awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{n++}END{print n+0}' "$file"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_base_keys
_e202_small_bbr_base_keys() {
    _e202_small_bbr_mode2 | awk -F= '{
        key=$1
        gsub(/[[:space:]]/,"",key)
        if (key!="") print key
    }'
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_boot_preflight
_e202_small_bbr_boot_preflight() {
    local cmd;
    test "$EUID" -eq 0 || return 1;
    for cmd in sysctl modprobe flock sha256sum awk sed grep readlink systemctl install;
    do
        command -v "$cmd" > /dev/null 2>&1 || { 
            error "小BBR开机复检缺少命令：$cmd";
            return 1
        };
    done
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_commit_profile_and_enable
_e202_small_bbr_commit_profile_and_enable() {
    local source="$1" tx profile_snapshot;
    _e202_small_bbr_validate_file "$source" || { 
        error '拒绝提交：目标档位未通过精确14/25/26项校验。';
        return 1
    };
    tx=$(_e202_new_tx profile-selection) || return 1;
    profile_snapshot="$tx/saved-profile";
    _e135_snapshot_file "$E202_SMALL_PROFILE" "$profile_snapshot" || { 
        error '无法快照当前保存档；未修改档位。';
        return 1
    };
    _e202_small_bbr_profile_save "$source" || return 1;
    if _e202_small_bbr_enable force; then
        return 0;
    fi;
    error '目标档位未能生效；恢复选择前的保存档。';
    if ! _e135_restore_file "$E202_SMALL_PROFILE" "$profile_snapshot"; then
        error "保存档恢复失败；人工恢复依据：$profile_snapshot";
    fi;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_default
_e202_small_bbr_default() {
    _e202_small_bbr_mode2
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_desired
_e202_small_bbr_desired() {
    if _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        cat -- "$E202_SMALL_PROFILE";
    else
        _e202_small_bbr_default;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_disable
_e202_small_bbr_disable() {
    ( local confirm="${1:-}" snapshot saved_profile="";
    if ! _e202_small_bbr_active; then
        info '小BBR当前未启用。';
        return 0;
    fi;
    if test "$confirm" != force; then
        warn '将退出小BBR，并恢复启用前的网络文件、运行值和systemd所有者。';
        read -rp '确认退出小BBR？[y/N]: ' confirm || true;
        case "$confirm" in 
            y | Y | yes | YES | Yes)

            ;;
            *)
                info '已取消。';
                return 0
            ;;
        esac;
    fi;
    _e202_prepare || return 1;
    _e214_ensure_run_lock || return 1;
    exec 189> /run/lock/xray-small-bbr-e202.lock || { 
        error '无法创建小BBR事务锁。';
        return 1
    };
    flock -w 90 189 || { 
        error '另一个小BBR事务占用锁超过90秒。';
        return 1
    };
    snapshot=$(sed -n 's/^restore_snapshot=//p' "$E202_SMALL_STATE" | tail -n1);
    _e202_snapshot_valid "$snapshot" || { 
        error "恢复快照无效，拒绝删除当前小BBR：$snapshot";
        return 1
    };
    saved_profile=$(_e118_mktemp e202-saved-profile) || return 1;
    if _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        cp -f -- "$E202_SMALL_PROFILE" "$saved_profile" || return 1;
    else
        if _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
            cp -f -- "$E202_SMALL_CONF" "$saved_profile" || return 1;
        else
            _e202_small_bbr_default > "$saved_profile" || return 1;
        fi;
    fi;
    _e202_small_bbr_restore_snapshot "$snapshot" disable || return 1;
    _e202_small_bbr_profile_save "$saved_profile" || { 
        error '网络基线已恢复，但保存小BBR档位失败；活动网络未受影响。';
        return 1
    };
    _e202_prune_tx;
    info '小BBR已退出，启用前的网络配置与服务状态已恢复并读回验证。' )
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_duplicate_count
_e202_small_bbr_duplicate_count() {
    local key="$1" f count=0 n;
    for f in /etc/sysctl.conf /etc/sysctl.d/*.conf /run/sysctl.d/*.conf /usr/local/lib/sysctl.d/*.conf /usr/lib/sysctl.d/*.conf /lib/sysctl.d/*.conf;
    do
        test -f "$f" || continue;
        test "$f" = "$E202_SMALL_CONF" && continue;
        n=$(awk -F= -v wanted="$key" '
          /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
            k=$1
            gsub(/[[:space:]]/,"",k)
            if (k==wanted) n++
          }
          END {print n+0}
        ' "$f");
        count=$((count+n));
    done;
    printf '%s\n' "$count"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_edit_profile
_e202_small_bbr_edit_profile() {
    local tmp next choice key current value max_index assignments;
    local -a keys;
    tmp=$(_e118_mktemp e202-small-bbr-edit) || return 1;
    _e202_small_bbr_desired > "$tmp" || return 1;
    while true; do
        mapfile -t keys < <(_e202_small_bbr_file_keys "$tmp");
        assignments=${#keys[@]};
        max_index="$assignments";
        clear;
        title "V199e202：逐项自定义小BBR（严格${assignments}项）";
        echo "  1、2项 fq/bbr 为结构锚点，只读；3—${max_index}项可修改。";
        echo '  数值必须通过范围、布尔值及 min<=default<=max 联合校验。';
        echo;
        nl -ba -w2 -s') ' "$tmp" | sed 's/^/  /';
        echo;
        echo '  S) 保存但暂不应用';
        echo '  A) 保存并立即启用/应用';
        echo '  R) 将编辑区恢复为E202默认值';
        echo '  0) 放弃并返回';
        read -rp '选择参数编号或操作: ' choice || true;
        case "$choice" in 
            1 | 2)
                warn 'fq 与 bbr 是小BBR结构锚点，不在自定义菜单中改变。';
                sleep 1
            ;;
            [3-9] | 1[0-9] | 2[0-6])
                test "$choice" -le "$max_index" || { 
                    warn '该编号不属于当前档位。';
                    sleep 1;
                    continue
                };
                key="${keys[$((choice-1))]}";
                current=$(_e202_profile_value "$tmp" "$key");
                read -rp "$key 当前=$current，新值: " value || true;
                value=$(_e159_norm "$value");
                test -n "$value" || { 
                    warn '空值未保存。';
                    sleep 1;
                    continue
                };
                next="${tmp}.next";
                awk -F= -v wanted="$key" -v replacement="$value" '{
                  k=$1
                  gsub(/[[:space:]]/,"",k)
                  if (k==wanted) print wanted " = " replacement
                  else print
                }' "$tmp" > "$next" || { 
                    rm -f -- "$next";
                    return 1
                };
                if _e202_small_bbr_validate_file "$next"; then
                    mv -f -- "$next" "$tmp" || return 1;
                    info '编辑值已通过联合校验。';
                else
                    rm -f -- "$next";
                    error '该值会形成无效档位，未写入。请检查范围及缓冲三元组顺序。';
                fi;
                sleep 1
            ;;
            S | s)
                _e202_small_bbr_profile_save "$tmp" || return 1;
                info "自定义${assignments}项已保存：$E202_SMALL_PROFILE";
                return 0
            ;;
            A | a)
                _e202_small_bbr_commit_profile_and_enable "$tmp";
                return $?
            ;;
            R | r)
                _e202_small_bbr_default > "$tmp" || return 1;
                info '编辑区已恢复默认值；尚未保存或应用。';
                sleep 1
            ;;
            0)
                info '已放弃本次编辑。';
                return 0
            ;;
            *)
                warn '无效操作。';
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_enable
_e202_small_bbr_enable() {
    ( local confirm="${1:-}" tx="" snapshot="" restore_snapshot="" failed=0;
    local assignments profile_id token desired_tmp;
    if test -e "$E202_SMALL_PROFILE" && ! _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        error "保存的小BBR档位无效，请先在菜单26重新编辑或恢复默认值：$E202_SMALL_PROFILE";
        return 1;
    fi;
    if _e202_unrecognized_current_active; then
        return 1;
    fi;
    if _e202_legacy_e190_active; then
        error '检测到E190小BBR仍在运行；必须先由原版E190执行 --small-bbr-disable。';
        return 1;
    fi;
    if _e202_legacy_e192_active; then
        error '检测到E192小BBR仍在运行；必须先由原版E192执行 --small-bbr-disable。';
        return 1;
    fi;
    if _e202_legacy_e194_active; then
        error '检测到E194小BBR仍在运行；必须先由原版E194执行 --small-bbr-disable。';
        return 1;
    fi;
    if _e202_legacy_e196_active; then
        error '检测到E196小BBR仍在运行；必须先由原版E196执行 --small-bbr-disable。';
        return 1;
    fi;
    if _e202_legacy_e198_active; then
        error '检测到E198小BBR仍在运行；必须先由原版E198执行 --small-bbr-disable。';
        return 1;
    fi;
    if _e202_legacy_e200_active; then
        error '检测到E200小BBR仍在运行；必须先由原版E200执行 --small-bbr-disable。';
        return 1;
    fi;
    assignments=$(_e202_small_bbr_desired | awk -F= '/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/{n++}END{print n+0}');
    desired_tmp=$(_e118_mktemp e202-profile-id) || return 1;
    _e202_small_bbr_desired > "$desired_tmp" || return 1;
    profile_id=$(_e202_small_bbr_profile_id_file "$desired_tmp") || return 1;
    if test "$confirm" != force; then
        warn "将切换到互斥小BBR档位：$(_e202_small_bbr_profile_name "$profile_id")。";
        warn "该档位持久化${assignments}项，隐藏参数=0：";
        _e202_small_bbr_desired | sed 's/^/    /';
        warn 'E159及脚本确认拥有的旧网络层会被暂停；退出小BBR时按快照完整恢复。';
        token=APPLY-SMALL-BBR-14;
        if test "$assignments" -ge 25; then
            warn '扩展档会改变乱序上限、TFO、回环TIME_WAIT复用、时间戳、FIN_WAIT_2、连接队列与SACK/DSACK/RACK；26项档还会限制TIME_WAIT桶上限。';
            token=APPLY-SMALL-BBR-F;
        fi;
        read -rp "输入 $token 确认: " confirm || true;
        test "$confirm" = "$token" || { 
            info '已取消。';
            return 0
        };
    fi;
    _e202_prepare || return 1;
    _e214_ensure_run_lock || return 1;
    exec 189> /run/lock/xray-small-bbr-e202.lock || { 
        error '无法创建小BBR事务锁。';
        return 1
    };
    flock -w 90 189 || { 
        error '另一个小BBR事务占用锁超过90秒。';
        return 1
    };
    if _e202_small_bbr_active; then
        restore_snapshot=$(sed -n 's/^restore_snapshot=//p' "$E202_SMALL_STATE" | tail -n1);
        _e202_snapshot_valid "$restore_snapshot" || { 
            error '现有小BBR状态的恢复快照无效；拒绝覆盖唯一回滚依据。';
            return 1
        };
        _e202_install_self || return 1;
        _e202_write_version || return 1;
        tx=$(_e202_new_tx profile-switch) || return 1;
        snapshot="$tx/system";
        _e140_system_snapshot "$snapshot" || { 
            error '无法建立小BBR档位切换前快照。';
            return 1
        };
        _e202_snapshot_valid "$snapshot" || return 1;
        if _e202_full_network_owner_present; then
            _e202_prepare_exclusive_small_profile || failed=1;
        fi;
        test "$failed" -ne 0 || _e202_small_bbr_write_assets || failed=1;
        test "$failed" -ne 0 || _e202_small_bbr_restore_unowned_runtime "$restore_snapshot" "$E202_SMALL_CONF" || failed=1;
        test "$failed" -ne 0 || _e202_small_bbr_write_state "$restore_snapshot" || failed=1;
        test "$failed" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || failed=1;
        test "$failed" -ne 0 || systemctl enable "$E202_SMALL_UNIT" > /dev/null 2>&1 || failed=1;
        test "$failed" -ne 0 || _e202_small_bbr_apply_runtime || failed=1;
        test "$failed" -ne 0 || _e202_small_bbr_verify_runtime "$E202_SMALL_CONF" || failed=1;
        if test "$failed" -ne 0; then
            error '小BBR配置切换失败，恢复切换前的活动配置与运行值。';
            _e202_small_bbr_restore_snapshot "$snapshot" profile-switch-failed || true;
            return 1;
        fi;
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF");
        profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF");
        _e202_prune_tx "$restore_snapshot" "$snapshot";
        info "小BBR已按原恢复点提交：$(_e202_small_bbr_profile_name "$profile_id")；持久参数=$assignments，隐藏参数=0。";
        return 0;
    fi;
    _e202_install_self || return 1;
    _e202_write_version || return 1;
    tx=$(_e202_new_tx enable) || return 1;
    snapshot="$tx/system";
    _e140_system_snapshot "$snapshot" || { 
        error '无法建立小BBR启用前的完整系统快照。';
        return 1
    };
    _e202_snapshot_valid "$snapshot" || return 1;
    _e202_prepare_exclusive_small_profile || failed=1;
    test "$failed" -ne 0 || _e202_small_bbr_write_assets || failed=1;
    test "$failed" -ne 0 || _e202_small_bbr_restore_unowned_runtime "$snapshot" "$E202_SMALL_CONF" || failed=1;
    test "$failed" -ne 0 || _e202_small_bbr_write_state "$snapshot" || failed=1;
    test "$failed" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || failed=1;
    test "$failed" -ne 0 || systemctl enable "$E202_SMALL_UNIT" > /dev/null 2>&1 || failed=1;
    test "$failed" -ne 0 || _e202_small_bbr_apply_runtime || failed=1;
    test "$failed" -ne 0 || _e202_small_bbr_verify_runtime "$E202_SMALL_CONF" || failed=1;
    test "$failed" -ne 0 || systemctl is-enabled --quiet "$E202_SMALL_UNIT" || failed=1;
    if test "$failed" -ne 0; then
        error '小BBR事务失败，正在恢复启用前的完整网络配置。';
        _e202_small_bbr_restore_snapshot "$snapshot" enable-failed || true;
        return 1;
    fi;
    rm -f -- "$E202_CRITICAL_MARKER" 2> /dev/null || true;
    assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF");
    profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF");
    _e202_prune_tx "$snapshot";
    info "小BBR已事务提交：$(_e202_small_bbr_profile_name "$profile_id")；持久参数=$assignments，隐藏参数=0，开机复检=enabled。";
    info "精确配置：$E202_SMALL_CONF";
    info "退出恢复快照：$snapshot" )
}
