# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_menu
_e202_small_bbr_menu() {
    local n;
    while true; do
        clear;
        title 'V199e266：小BBR八档切换中心（E202兼容稳定所有权）';
        echo '  基础档=精确14项；F/B1档=精确25项；3F2档=精确26项；隐藏项=0。';
        echo '  IPv6、WARP、MSS、重试与ip_forward不属于小BBR；tcp_max_tw_buckets仅属于3F2。';
        echo '  tcp_adv_win_scale在Linux 6.6起已废弃；保留是为了兼容你的明确参数规格。';
        echo '  1) 模式1--2.50-22MB（256KiB对称 / 22.68MiB / idle=1）';
        echo '  2) 模式2--1.30x0.19-31MB（128KiB/18.91KiB / 31.05MiB，默认）';
        echo '  3) 模式3--0.9x0.25-13MB（95.10KiB/25.60KiB / 12.47MiB）';
        echo '  4) 模式1F--模式1缓冲 + 11项扩展参数（idle=0）';
        echo '  5) 模式2F--1.30w0.19-31MB + 11项扩展参数';
        echo '  6) 模式3F--0.9w0.23-14MB + 11项扩展参数';
        echo '  7) 模式B1--3.5w2.6-62MB + 11项扩展参数';
        echo '  8) 模式3F2--0.90w0.25-21MB-time10s + 12项扩展参数';
        echo '  9) 查看目标值、运行值、持久状态与重复定义';
        echo ' 10) 逐项自定义当前14/25/26项并选择保存/生效';
        echo ' 11) 应用当前保存档位（无保存值时使用模式2）';
        echo ' 12) 按当前活动档位修复/重新应用';
        echo ' 13) 恢复默认模式2并立即生效';
        echo ' 14) 退出小BBR并恢复首次启用前网络配置';
        echo ' 15) 显示八个预设、保存值和活动值';
        echo '  0) 返回';
        read -rp '操作: ' n || true;
        case "$n" in 
            1)
                _e202_small_bbr_select_profile mode1;
                _e138_pause
            ;;
            2)
                _e202_small_bbr_select_profile mode2;
                _e138_pause
            ;;
            3)
                _e202_small_bbr_select_profile mode3;
                _e138_pause
            ;;
            4)
                _e202_small_bbr_select_profile mode1f;
                _e138_pause
            ;;
            5)
                _e202_small_bbr_select_profile mode2f;
                _e138_pause
            ;;
            6)
                _e202_small_bbr_select_profile mode3f;
                _e138_pause
            ;;
            7)
                _e202_small_bbr_select_profile modeb1;
                _e138_pause
            ;;
            8)
                _e202_small_bbr_select_profile mode3f2;
                _e138_pause
            ;;
            9)
                _e202_small_bbr_status || true;
                _e138_pause
            ;;
            10)
                _e202_small_bbr_edit_profile;
                _e138_pause
            ;;
            11)
                _e202_small_bbr_enable;
                _e138_pause
            ;;
            12)
                if _e202_small_bbr_active; then
                    _e202_small_bbr_reconcile;
                else
                    warn '小BBR尚未启用；请先选择一个档位或应用保存档。';
                fi;
                _e138_pause
            ;;
            13)
                _e202_small_bbr_reset_default;
                _e138_pause
            ;;
            14)
                _e202_small_bbr_disable || { 
                    _e138_pause;
                    continue
                };
                return 0
            ;;
            15)
                _e202_small_bbr_show_profiles;
                _e138_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn '无效操作。';
                sleep 1
            ;;
        esac;
    done
}
