# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_profile_id_file
_e202_small_bbr_profile_id_file() {
    local file="$1" id fn;
    _e202_small_bbr_validate_file "$file" || { 
        echo invalid;
        return 1
    };
    for id in mode1 mode2 mode3 mode1f mode2f mode3f mode3f2 modeb1;
    do
        fn="_e202_small_bbr_${id}";
        cmp -s "$file" <("$fn") && { 
            echo "$id";
            return 0
        };
    done;
    case "$(awk 'NF{n++}END{print n+0}' "$file")" in 
        14)
            echo custom
        ;;
        25)
            echo custom-f
        ;;
        26)
            echo custom-f2
        ;;
        *)
            echo invalid;
            return 1
        ;;
    esac
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_profile_name
_e202_small_bbr_profile_name() {
    case "${1:-}" in 
        mode1)
            echo '模式1--2.50-22MB'
        ;;
        mode2)
            echo '模式2--1.30x0.19-31MB（默认）'
        ;;
        mode3)
            echo '模式3--0.9x0.25-13MB'
        ;;
        mode1f)
            echo '模式1F--2.50-22MB'
        ;;
        mode2f)
            echo '模式2F--1.30w0.19-31MB'
        ;;
        mode3f)
            echo '模式3F--0.9w0.23-14MB'
        ;;
        mode3f2)
            echo '模式3F2--0.90w0.25-21MB-time10s'
        ;;
        modeb1)
            echo '模式B1--3.5w2.6-62MB'
        ;;
        custom)
            echo '自定义基础14项'
        ;;
        custom-f)
            echo '自定义扩展25项'
        ;;
        custom-f2)
            echo '自定义扩展26项'
        ;;
        invalid)
            echo '无效保存档（拒绝应用）'
        ;;
        *)
            echo '未知档位'
        ;;
    esac
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_profile_save
_e202_small_bbr_profile_save() {
    local source="$1" tmp;
    _e202_small_bbr_validate_file "$source" || { 
        error '拒绝保存：档位未通过精确14/25/26项结构与范围校验。';
        return 1
    };
    _e202_prepare || return 1;
    tmp="$E202_SMALL_PROFILE.tmp.$$";
    install -m 0600 "$source" "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -f -- "$tmp" "$E202_SMALL_PROFILE" || { 
        rm -f -- "$tmp";
        return 1
    }
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_reconcile
_e202_small_bbr_reconcile() {
    ( _e202_small_bbr_boot_preflight || return 1;
    _e214_ensure_run_lock || return 1;
    exec 189> /run/lock/xray-small-bbr-e202.lock || { 
        error '无法创建小BBR事务锁。';
        return 1
    };
    flock -w 90 189 || { 
        error '另一个小BBR事务占用锁超过90秒。';
        return 1
    };
    _e202_small_bbr_reconcile_locked )
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_reconcile_locked
_e202_small_bbr_reconcile_locked() {
    local sha assignments profile_id restore_snapshot;
    _e202_small_bbr_active || { 
        error '小BBR状态未启用，拒绝开机复写。';
        return 1
    };
    _e202_small_bbr_validate_file "$E202_SMALL_CONF" || { 
        error '小BBR配置不是合法的14/25/26项档位，拒绝使用被改写的文件。';
        return 1
    };
    sha=$(sed -n 's/^config_sha256=//p' "$E202_SMALL_STATE" | tail -n1);
    test "$sha" = "$(sha256sum "$E202_SMALL_CONF" | awk '{print $1}')" || { 
        error '小BBR配置哈希与状态不一致。';
        return 1
    };
    restore_snapshot=$(sed -n 's/^restore_snapshot=//p' "$E202_SMALL_STATE" | tail -n1);
    _e202_snapshot_valid "$restore_snapshot" || { 
        error '小BBR首次启用恢复点无效；拒绝进行不完整的开机复写。';
        return 1
    };
    if _e202_full_network_owner_present; then
        warn '检测到完整参数或旧小BBR所有者复现；先收敛脚本拥有的冲突层，再重放当前档位。';
        _e202_prepare_exclusive_small_profile || return 1;
    fi;
    _e202_small_bbr_restore_unowned_runtime "$restore_snapshot" "$E202_SMALL_CONF" || return 1;
    _e202_small_bbr_apply_runtime || return 1;
    assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF");
    profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF") || return 1;
    install -d -m 0700 "$(dirname "$E202_SMALL_LOG")" 2> /dev/null || true;
    printf '%s result=ok profile=%s assignments=%s hidden=0\n' "$(date -Is 2> /dev/null || date)" "$profile_id" "$assignments" >> "$E202_SMALL_LOG" 2> /dev/null || true
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_reset_default
_e202_small_bbr_reset_default() {
    local confirm="" tmp;
    warn '这会恢复默认模式2并立即启用/应用；原退出快照保持不变。';
    read -rp '确认恢复模式2并立即生效？[y/N]: ' confirm || true;
    case "$confirm" in 
        y | Y | yes | YES | Yes)

        ;;
        *)
            info '已取消。';
            return 0
        ;;
    esac;
    tmp=$(_e118_mktemp e202-small-bbr-default) || return 1;
    _e202_small_bbr_default > "$tmp" || return 1;
    _e202_small_bbr_commit_profile_and_enable "$tmp"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_restore_snapshot
_e202_small_bbr_restore_snapshot() {
    local snapshot="${1:-}" operation="${2:-unknown}" E266_E202_LINEAGE_RECORD="";
    _e202_snapshot_valid "$snapshot" || { 
        error "小BBR回滚快照不可验证：$snapshot";
        return 1
    };
    if test "${E242_INTERNAL_SELF_TEST:-0}" != 1 || test "${E266_E202_SCOPE_TEST_BYPASS:-0}" != 1; then
        E266_E202_LINEAGE_RECORD=$(_e266_e202_snapshot_e159_lineage "$snapshot") || { 
            error '小BBR回滚快照中的完整网络所有权无法唯一分类；尚未停止服务或改写文件。';
            return 1
        };
        case "$E266_E202_LINEAGE_RECORD" in 
            broken\|*)
                test "${E266_ALLOW_LINEAGE_SALVAGE:-0}" = 1 || { 
                    error '小BBR回滚快照引用的E159初始基线已被删除；尚未停止服务或改写文件。';
                    error '手动退出保持失败关闭；请改用E266一键升级的外层保护恢复。';
                    return 1
                }
            ;;
            none\|* | clean\|*)

            ;;
            *)
                return 1
            ;;
        esac;
    fi;
    _eex5_restore_preflight "$snapshot" all || { 
        error "EEX5小BBR退出预检失败；原服务启用状态保持不变。";
        return 1
    };
    if ! _e266_e202_restore_readback "$snapshot"; then
        install -d -m 0700 "$E202_DIR" 2> /dev/null || true;
        { 
            echo "time=$(date -Is 2> /dev/null || date)";
            echo "operation=$operation";
            echo "restore_snapshot=$snapshot"
        } > "$E202_CRITICAL_MARKER" 2> /dev/null || true;
        error "严重：小BBR事务恢复未通过E266专用复检；快照：$snapshot";
        return 1;
    fi;
    rm -f -- "$E202_CRITICAL_MARKER" 2> /dev/null || true
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_restore_unowned_runtime
_e202_small_bbr_restore_unowned_runtime() {
    local snapshot="$1" target="$2" key expected actual path failed=0;
    _e202_snapshot_valid "$snapshot" || return 1;
    _e202_small_bbr_validate_file "$target" || return 1;
    while IFS= read -r key; do
        grep -Fqx "$key" < <(_e202_small_bbr_file_keys "$target") && continue;
        path=$(_e159_proc_path "$key");
        test -e "$path" && test -w "$path" || continue;
        expected=$(awk -F'|' -v wanted="$key" '$1==wanted {
            print substr($0,index($0,"|")+1)
            exit
        }' "$snapshot/runtime-sysctl.env");
        test -n "$expected" || { 
            error "恢复非目标参数时快照缺值：$key";
            failed=1;
            continue
        };
        sysctl -w "$key=$expected" > /dev/null 2>&1 || { 
            error "恢复非目标参数失败：$key";
            failed=1;
            continue
        };
        actual=$(sysctl -n "$key" 2> /dev/null || true);
        _e159_value_equal "$key" "$expected" "$actual" || { 
            error "恢复非目标参数读回不一致：$key 期望=$expected 实际=${actual:-unreadable}";
            failed=1
        };
    done < <(_e202_small_bbr_all_keys);
    test "$failed" -eq 0
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_select_profile
_e202_small_bbr_select_profile() {
    local id="$1" fn tmp confirm token;
    case "$id" in 
        mode1 | mode2 | mode3 | mode1f | mode2f | mode3f | mode3f2 | modeb1)

        ;;
        *)
            error "未知小BBR档位：$id";
            return 1
        ;;
    esac;
    fn="_e202_small_bbr_${id}";
    tmp=$(_e118_mktemp "e202-${id}") || return 1;
    "$fn" > "$tmp" || return 1;
    _e202_small_bbr_validate_file "$tmp" || { 
        error "内置档位未通过发布校验：$id";
        return 1
    };
    title "应用 $(_e202_small_bbr_profile_name "$id")";
    nl -ba -w2 -s') ' "$tmp" | sed 's/^/  /';
    echo;
    token=APPLY-SMALL-BBR-14;
    if test "$(_e202_small_bbr_assignment_count "$tmp")" -ge 25; then
        warn 'F/B1是扩展实验档：会改变乱序上限、TFO、回环TIME_WAIT复用、时间戳、FIN_WAIT_2、连接队列与SACK/DSACK/RACK。';
        warn 'tcp_tw_reuse=2仅对loopback连接启用复用；不会直接加速公网Xray连接。';
        warn 'tcp_max_reordering=300与tcp_timestamps=1为当前Linux文档默认值。';
        if test "$id" = mode3f2; then
            warn '模式3F2还会把tcp_fin_timeout设为10，并把tcp_max_tw_buckets设为8192；后者限制系统可同时保留的TIME_WAIT套接字总数。';
        fi;
        token=APPLY-SMALL-BBR-F;
    fi;
    warn '切换失败会恢复切换前活动档；退出小BBR会恢复首次启用前完整网络层。';
    read -rp "输入 $token 确认: " confirm || true;
    test "$confirm" = "$token" || { 
        info '已取消，保存档与活动档均未改变。';
        return 0
    };
    _e202_small_bbr_commit_profile_and_enable "$tmp"
}
