# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_show_profiles
_e202_small_bbr_show_profiles() {
    local id fn;
    title 'V199e266：小BBR八个预设 / 保存值 / 活动值（E202兼容稳定所有权）';
    for id in mode1 mode2 mode3 mode1f mode2f mode3f mode3f2 modeb1;
    do
        fn="_e202_small_bbr_${id}";
        echo "  [$id] $(_e202_small_bbr_profile_name "$id")";
        "$fn" | nl -ba -w2 -s') ' | sed 's/^/    /';
        echo;
    done;
    echo '  当前保存值（无保存文件时等于模式2）：';
    _e202_small_bbr_desired | nl -ba -w2 -s') ' | sed 's/^/    /';
    if _e202_small_bbr_active; then
        echo;
        echo '  当前活动持久值：';
        if _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
            nl -ba -w2 -s') ' "$E202_SMALL_CONF" | sed 's/^/    /';
        else
            warn '活动持久文件缺失或无效。';
        fi;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_status
_e202_small_bbr_status() {
    local rc=0 result status load;
    _e204_small_bbr_status_base "$@" || rc=$?;
    if _e202_small_bbr_active; then
        result=$(systemctl show "$E202_SMALL_UNIT" -p Result --value 2> /dev/null || true);
        status=$(systemctl show "$E202_SMALL_UNIT" -p ExecMainStatus --value 2> /dev/null || true);
        load=$(systemctl show "$E202_SMALL_UNIT" -p LoadState --value 2> /dev/null || true);
        echo "  最近开机复检: load=${load:-unknown} result=${result:-unknown} exit=${status:-unknown}";
        test "$load" = loaded && test "$result" = success && test "${status:-1}" = 0 || { 
            error '小BBR开机oneshot最近一次执行未成功。';
            rc=1
        };
    fi;
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_unit_candidate
_e202_small_bbr_unit_candidate() {
    local out="$1";
    cat > "$out" <<EOF_E202_SMALL_UNIT
[Unit]
Description=V199e202 exact selected small BBR profile boot verification
After=systemd-sysctl.service
Before=xray.service
ConditionPathExists=$E202_SMALL_STATE

[Service]
Type=oneshot
ExecStart=$E202_SELF_PATH --small-bbr-reconcile
TimeoutStartSec=60

[Install]
WantedBy=multi-user.target
EOF_E202_SMALL_UNIT

}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_validate_file
_e202_small_bbr_validate_file() {
    local file="$1" lines active keys expected_keys qdisc cc key value extended=0 f2=0;
    local rdef wdef rmax wmax trmin trdef trmax twmin twdef twmax;
    local tw_reuse timestamps;
    test -f "$file" || return 1;
    lines=$(awk 'NF{n++}END{print n+0}' "$file");
    active=$(awk -F= '
      /^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {n++}
      END {print n+0}
    ' "$file");
    case "$lines:$active" in 
        14:14)
            expected_keys=$(_e202_small_bbr_base_keys)
        ;;
        25:25)
            expected_keys=$({ _e202_small_bbr_base_keys
_e202_small_bbr_extra_keys; } | awk 'NF&&!seen[$0]++');
            extended=1
        ;;
        26:26)
            expected_keys=$(_e202_small_bbr_all_keys);
            extended=1;
            f2=1
        ;;
        *)
            return 1
        ;;
    esac;
    keys=$(_e202_small_bbr_file_keys "$file");
    test "$keys" = "$expected_keys" || return 1;
    qdisc=$(_e202_profile_value "$file" net.core.default_qdisc);
    cc=$(_e202_profile_value "$file" net.ipv4.tcp_congestion_control);
    test "$qdisc" = fq && test "$cc" = bbr || return 1;
    for key in net.core.rmem_default net.core.wmem_default net.core.rmem_max net.core.wmem_max;
    do
        value=$(_e202_profile_value "$file" "$key");
        [[ "$value" =~ ^[0-9]+$ ]] || return 1;
        test "$value" -ge 4096 && test "$value" -le 1073741824 || return 1;
    done;
    rdef=$(_e202_profile_value "$file" net.core.rmem_default);
    wdef=$(_e202_profile_value "$file" net.core.wmem_default);
    rmax=$(_e202_profile_value "$file" net.core.rmem_max);
    wmax=$(_e202_profile_value "$file" net.core.wmem_max);
    test "$rdef" -le "$rmax" && test "$wdef" -le "$wmax" || return 1;
    read -r trmin trdef trmax <<< "$(_e202_profile_value "$file" net.ipv4.tcp_rmem)";
    read -r twmin twdef twmax <<< "$(_e202_profile_value "$file" net.ipv4.tcp_wmem)";
    for value in "$trmin" "$trdef" "$trmax" "$twmin" "$twdef" "$twmax";
    do
        [[ "$value" =~ ^[0-9]+$ ]] || return 1;
        test "$value" -ge 1024 && test "$value" -le 1073741824 || return 1;
    done;
    test "$trmin" -le "$trdef" && test "$trdef" -le "$trmax" || return 1;
    test "$twmin" -le "$twdef" && test "$twdef" -le "$twmax" || return 1;
    test "$trmax" -le "$rmax" && test "$twmax" -le "$wmax" || return 1;
    for key in net.ipv4.tcp_moderate_rcvbuf net.ipv4.tcp_window_scaling net.ipv4.tcp_slow_start_after_idle;
    do
        value=$(_e202_profile_value "$file" "$key");
        case "$value" in 
            0 | 1)

            ;;
            *)
                return 1
            ;;
        esac;
    done;
    value=$(_e202_profile_value "$file" net.ipv4.tcp_adv_win_scale);
    [[ "$value" =~ ^-?[0-9]+$ ]] && test "$value" -ge -31 && test "$value" -le 31 || return 1;
    value=$(_e202_profile_value "$file" net.ipv4.tcp_mtu_probing);
    case "$value" in 
        0 | 1 | 2)

        ;;
        *)
            return 1
        ;;
    esac;
    value=$(_e202_profile_value "$file" net.ipv4.tcp_ecn);
    case "$value" in 
        0 | 1 | 2 | 3 | 4 | 5)

        ;;
        *)
            return 1
        ;;
    esac;
    if test "$extended" -eq 1; then
        value=$(_e202_profile_value "$file" net.ipv4.tcp_max_reordering);
        [[ "$value" =~ ^[0-9]+$ ]] && test "$value" -ge 3 && test "$value" -le 100000 || return 1;
        value=$(_e202_profile_value "$file" net.ipv4.tcp_fastopen);
        [[ "$value" =~ ^[0-9]+$ ]] && test "$value" -ge 0 && test "$value" -le 2047 || return 1;
        tw_reuse=$(_e202_profile_value "$file" net.ipv4.tcp_tw_reuse);
        case "$tw_reuse" in 
            0 | 1 | 2)

            ;;
            *)
                return 1
            ;;
        esac;
        timestamps=$(_e202_profile_value "$file" net.ipv4.tcp_timestamps);
        case "$timestamps" in 
            0 | 1 | 2)

            ;;
            *)
                return 1
            ;;
        esac;
        if test "$tw_reuse" != 0; then
            test "$timestamps" != 0 || return 1;
        fi;
        value=$(_e202_profile_value "$file" net.ipv4.tcp_fin_timeout);
        [[ "$value" =~ ^[0-9]+$ ]] && test "$value" -ge 1 && test "$value" -le 600 || return 1;
        for key in net.ipv4.tcp_max_syn_backlog net.core.netdev_max_backlog net.core.somaxconn;
        do
            value=$(_e202_profile_value "$file" "$key");
            [[ "$value" =~ ^[0-9]+$ ]] && test "$value" -ge 128 && test "$value" -le 16777216 || return 1;
        done;
        for key in net.ipv4.tcp_sack net.ipv4.tcp_dsack;
        do
            value=$(_e202_profile_value "$file" "$key");
            case "$value" in 
                0 | 1)

                ;;
                *)
                    return 1
                ;;
            esac;
        done;
        value=$(_e202_profile_value "$file" net.ipv4.tcp_recovery);
        [[ "$value" =~ ^(0[xX][0-9A-Fa-f]+|[0-9]+)$ ]] || return 1;
        (( value >= 0 && value <= 255 )) 2> /dev/null || return 1;
        if test "$f2" -eq 1; then
            value=$(_e202_profile_value "$file" net.ipv4.tcp_max_tw_buckets);
            [[ "$value" =~ ^[0-9]+$ ]] && test "$value" -ge 1024 && test "$value" -le 16777216 || return 1;
        fi;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_verify_runtime
_e202_small_bbr_verify_runtime() {
    local source="${1:-$E202_SMALL_CONF}" key value actual failed=0;
    _e202_small_bbr_validate_file "$source" || return 1;
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key");
        value=$(_e159_norm "$value");
        actual=$(sysctl -n "$key" 2> /dev/null || true);
        if ! _e159_value_equal "$key" "$value" "$actual"; then
            error "小BBR读回不一致：$key 期望=$value 实际=${actual:-unreadable}";
            failed=1;
        fi;
    done < "$source";
    test "$failed" -eq 0
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_write_assets
_e202_small_bbr_write_assets() {
    local conf_tmp unit_tmp;
    if test -e "$E202_SMALL_PROFILE" && ! _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
        error "保存的小BBR档位无效，拒绝静默回落默认值：$E202_SMALL_PROFILE";
        return 1;
    fi;
    conf_tmp=$(_e118_mktemp e202-small-bbr.conf) || return 1;
    unit_tmp=$(_e118_mktemp e202-small-bbr.service) || return 1;
    _e202_small_bbr_desired > "$conf_tmp" || return 1;
    _e202_small_bbr_unit_candidate "$unit_tmp" || return 1;
    _e202_small_bbr_validate_file "$conf_tmp" || return 1;
    grep -Fqx "ExecStart=$E202_SELF_PATH --small-bbr-reconcile" "$unit_tmp" || return 1;
    _e121_atomic_install "$conf_tmp" "$E202_SMALL_CONF" 0644 || return 1;
    _e121_atomic_install "$unit_tmp" "$E202_SMALL_SERVICE" 0644 || return 1;
    _e202_small_bbr_validate_file "$E202_SMALL_CONF" || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_small_bbr_write_state
_e202_small_bbr_write_state() {
    local snapshot="$1" tmp profile_id assignments extensions;
    _e202_snapshot_valid "$snapshot" || return 1;
    profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF") || return 1;
    assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF");
    extensions=$((assignments-14));
    tmp="$E202_SMALL_STATE.tmp.$$";
    { 
        echo 'version=199e202';
        echo 'active=1';
        echo 'profile=small-bbr-multi';
        echo "profile_id=$profile_id";
        echo "profile_kind=$profile_id";
        echo "persistent_assignments=$assignments";
        echo "extension_assignments=$extensions";
        echo 'extra_assignments=0';
        echo "restore_snapshot=$snapshot";
        echo "config_sha256=$(sha256sum "$E202_SMALL_CONF" | awk '{print $1}')";
        echo "applied=$(date -Is 2> /dev/null || date)"
    } > "$tmp" || return 1;
    chmod 0600 "$tmp" || return 1;
    mv -f -- "$tmp" "$E202_SMALL_STATE" || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_snapshot_capture_small_runtime
_e202_snapshot_capture_small_runtime() {
    local b="$1" key value tmp;
    test -s "$b/runtime-sysctl.env" || return 1;
    tmp="$b/runtime-sysctl.env.e202.$$";
    cp -f -- "$b/runtime-sysctl.env" "$tmp" || return 1;
    while IFS= read -r key; do
        grep -Fq "${key}|" "$tmp" && continue;
        value=$(sysctl -n "$key" 2> /dev/null || true);
        test -n "$value" || continue;
        printf '%s|%s\n' "$key" "$value" >> "$tmp" || { 
            rm -f -- "$tmp";
            return 1
        };
    done < <(_e202_small_bbr_all_keys);
    awk -F'|' 'NF&&!seen[$1]++' "$tmp" > "$b/runtime-sysctl.env" || { 
        rm -f -- "$tmp";
        return 1
    };
    rm -f -- "$tmp";
    ( cd "$b" && sha256sum present.list absent.list runtime-sysctl.env services.env > control.sha256 ) || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_snapshot_runtime_verify
_e202_snapshot_runtime_verify() {
    local snapshot="$1" key expected actual failed=0;
    test -s "$snapshot/runtime-sysctl.env" || return 1;
    while IFS= read -r key; do
        test -e "$(_e159_proc_path "$key")" || continue;
        expected=$(awk -F'|' -v wanted="$key" '$1==wanted {
            print substr($0,index($0,"|")+1)
            exit
        }' "$snapshot/runtime-sysctl.env");
        test -n "$expected" || { 
            error "小BBR回滚快照缺少运行值：$key";
            failed=1;
            continue
        };
        actual=$(sysctl -n "$key" 2> /dev/null || true);
        _e159_value_equal "$key" "$expected" "$actual" || failed=1;
    done < <(_e202_small_bbr_all_keys);
    test "$failed" -eq 0
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_snapshot_valid
_e202_snapshot_valid() {
    local snapshot="$1" real root;
    real=$(readlink -f -- "$snapshot" 2> /dev/null || true);
    root=$(readlink -f -- "$E202_TX_ROOT" 2> /dev/null || true);
    test -n "$real" && test -n "$root" || return 1;
    case "$real" in 
        "$root"/*/system)

        ;;
        *)
            return 1
        ;;
    esac;
    test -s "$real/control.sha256" && ( cd "$real" && sha256sum -c control.sha256 > /dev/null 2>&1 ) || return 1;
    if test -s "$real/files.tar"; then
        test -s "$real/archive.sha256" && ( cd "$real" && sha256sum -c archive.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    if test -e "$real/e159-services.env" || test -e "$real/e159-services.sha256"; then
        test -s "$real/e159-services.env" && test -s "$real/e159-services.sha256" && ( cd "$real" && sha256sum -c e159-services.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    if test -e "$real/e202-services.env" || test -e "$real/e202-services.sha256"; then
        test -s "$real/e202-services.env" && test -s "$real/e202-services.sha256" && ( cd "$real" && sha256sum -c e202-services.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    if test -e "$real/e190-services.env" || test -e "$real/e190-services.sha256"; then
        test -s "$real/e190-services.env" && test -s "$real/e190-services.sha256" && ( cd "$real" && sha256sum -c e190-services.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    if test -e "$real/e192-services.env" || test -e "$real/e192-services.sha256"; then
        test -s "$real/e192-services.env" && test -s "$real/e192-services.sha256" && ( cd "$real" && sha256sum -c e192-services.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    if test -e "$real/e194-services.env" || test -e "$real/e194-services.sha256"; then
        test -s "$real/e194-services.env" && test -s "$real/e194-services.sha256" && ( cd "$real" && sha256sum -c e194-services.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    if test -e "$real/e196-services.env" || test -e "$real/e196-services.sha256"; then
        test -s "$real/e196-services.env" && test -s "$real/e196-services.sha256" && ( cd "$real" && sha256sum -c e196-services.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    if test -e "$real/e198-services.env" || test -e "$real/e198-services.sha256"; then
        test -s "$real/e198-services.env" && test -s "$real/e198-services.sha256" && ( cd "$real" && sha256sum -c e198-services.sha256 > /dev/null 2>&1 ) || return 1;
    fi;
    if test -e "$real/e200-services.env" || test -e "$real/e200-services.sha256"; then
        test -s "$real/e200-services.env" && test -s "$real/e200-services.sha256" && ( cd "$real" && sha256sum -c e200-services.sha256 > /dev/null 2>&1 ) || return 1;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_structure_audit
_e202_structure_audit() {
    local rc=0 size lines dispatchers menu expected apply hot commit select edit reset;
    local reconcile cleanup prune full_apply convert snapshot;
    echo 'V199e202 structure audit:';
    size=$(wc -c < "$SCRIPT_PATH" | tr -d ' ');
    lines=$(wc -l < "$SCRIPT_PATH" | tr -d ' ');
    dispatchers=$(grep -c '^# V199e202 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    menu=$(declare -f _e202_main_menu_impl 2> /dev/null || true);
    expected=$(_e202_small_bbr_expected);
    apply=$(declare -f _e202_small_bbr_apply_runtime 2> /dev/null || true);
    hot=$(declare -f _e202_hot_update 2> /dev/null || true);
    commit=$(declare -f _e202_small_bbr_commit_profile_and_enable 2> /dev/null || true);
    select=$(declare -f _e202_small_bbr_select_profile 2> /dev/null || true);
    edit=$(declare -f _e202_small_bbr_edit_profile 2> /dev/null || true);
    reset=$(declare -f _e202_small_bbr_reset_default 2> /dev/null || true);
    reconcile=$(declare -f _e202_small_bbr_reconcile_locked 2> /dev/null || true);
    cleanup=$(declare -f check_and_clean_space 2> /dev/null || true);
    prune=$(declare -f _e202_prune_tx 2> /dev/null || true);
    full_apply=$(declare -f _e159_network_apply 2> /dev/null || true);
    convert=$(declare -f _e202_convert_e200_profile 2> /dev/null || true);
    snapshot=$(declare -f _e140_system_snapshot 2> /dev/null || true);
    echo "  file_bytes=$size";
    echo "  lines=$lines";
    echo "  final_dispatchers=$dispatchers";
    echo '  small_bbr_owner=e202 (exclusive eight-profile 14/25/26 transaction)';
    echo '  full_profile_owner=e159 (blocked while small BBR is active)';
    echo '  network_audit=profile-aware (14/25/26-item or 127-request)';
    echo '  node_summary_owner=e188 (single final QR)';
    test "$size" -gt 2000000 && test "$lines" -gt 45000 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    case "$(printf '%s\n' "$expected" | awk 'NF{n++}END{print n+0}')" in 
        14 | 25 | 26)

        ;;
        *)
            rc=1
        ;;
    esac;
    ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' <<< "$expected" || rc=1;
    ! grep -q 'tcp_tw_reuse_delay' <<< "$apply" || rc=1;
    grep -q '26) 小BBR' <<< "$menu" || rc=1;
    grep -q '_e202_small_bbr_menu' <<< "$menu" || rc=1;
    declare -f _e202_small_bbr_menu | grep -q '_e202_small_bbr_select_profile mode3f2' || rc=1;
    grep -q '_e202_small_bbr_kernel_ready' <<< "$apply" || rc=1;
    grep -q '_e202_small_bbr_disable force' <<< "$hot" || rc=1;
    grep -q '_e202_legacy_e190_disable' <<< "$hot" || rc=1;
    grep -q '_e202_legacy_e192_disable' <<< "$hot" || rc=1;
    grep -q '_e202_legacy_e194_disable' <<< "$hot" || rc=1;
    grep -q '_e202_legacy_e196_disable' <<< "$hot" || rc=1;
    grep -q '_e202_legacy_e198_disable' <<< "$hot" || rc=1;
    grep -q '_e202_legacy_e200_disable' <<< "$hot" || rc=1;
    grep -q '_e202_prepare_legacy_profile 196' <<< "$hot" || rc=1;
    grep -q '_e202_prepare_legacy_profile 198' <<< "$hot" || rc=1;
    grep -q '_e202_prepare_legacy_profile 200' <<< "$hot" || rc=1;
    grep -q '_e202_capture_active_config 202' <<< "$hot" || rc=1;
    grep -q '_e202_capture_active_config 200' <<< "$hot" || rc=1;
    grep -q '_e202_capture_active_config 198' <<< "$hot" || rc=1;
    grep -q '_e202_capture_active_config 196' <<< "$hot" || rc=1;
    grep -q '_e202_capture_active_config 194' <<< "$hot" || rc=1;
    grep -q 'tcp_tw_reuse_delay' <<< "$convert" || rc=1;
    grep -q 'E202_LEGACY_E200_UNIT' <<< "$snapshot" || rc=1;
    grep -q '_e135_restore_file "$E202_SMALL_PROFILE"' <<< "$hot" || rc=1;
    grep -q '_e202_small_bbr_enable force' <<< "$hot" || rc=1;
    grep -q '_e202_small_bbr_restore_unowned_runtime' <<< "$reconcile" || rc=1;
    grep -q '_e202_unrecognized_current_active' <<< "$full_apply" || rc=1;
    grep -q '_e202_unrecognized_legacy_active' <<< "$full_apply" || rc=1;
    grep -q '_e202_recognized_legacy_active' <<< "$full_apply" || rc=1;
    ! grep -q 'E202_ALLOW_FULL_APPLY' <<< "$full_apply" || rc=1;
    grep -q '_e135_snapshot_file "$E202_SMALL_PROFILE"' <<< "$commit" || rc=1;
    grep -q '_e135_restore_file "$E202_SMALL_PROFILE"' <<< "$commit" || rc=1;
    grep -q '_e202_small_bbr_commit_profile_and_enable' <<< "$select" || rc=1;
    grep -q '_e202_small_bbr_commit_profile_and_enable' <<< "$edit" || rc=1;
    grep -Fq '2[0-5]' <<< "$edit" || rc=1;
    grep -q '_e202_small_bbr_commit_profile_and_enable' <<< "$reset" || rc=1;
    grep -q '_e202_prune_tx' <<< "$cleanup" || rc=1;
    grep -q 'E202_SMALL_STATE' <<< "$prune" || rc=1;
    grep -q 'E202_CRITICAL_MARKER' <<< "$prune" || rc=1;
    declare -f _e202_prepare_exclusive_small_profile | grep -q '_e202_unrecognized_legacy_active' || rc=1;
    declare -f _e202_prepare_exclusive_small_profile | grep -q '_e202_unrecognized_current_active' || rc=1;
    declare -f _e202_prepare_exclusive_small_profile | grep -q '_e202_recognized_legacy_active' || rc=1;
    declare -f _e202_hot_update_preflight | grep -q '_e202_unrecognized_legacy_active' || rc=1;
    declare -f _e202_hot_update_preflight | grep -q '_e202_unrecognized_current_active' || rc=1;
    declare -f _e202_small_bbr_menu | grep -q '_e202_small_bbr_select_profile modeb1' || rc=1;
    declare -f _e202_network_params_menu | grep -q '_e202_network_audit' || rc=1;
    test "$rc" -eq 0 && echo '  result=PASS' || echo '  result=FAIL';
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_system_paths_base
_e202_system_paths_base() {
    _e188_system_paths_base;
    printf '%s\n' "$E188_DIR" "$E188_SELF_PATH" "$E188_LATEST_PATH"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_system_restore_base
_e202_system_restore_base() {
    local b="$1" unit enabled active rc=0;
    if test -e "$b/e159-services.env" || test -e "$b/e159-services.sha256"; then
        test -s "$b/e159-services.env" && test -s "$b/e159-services.sha256" && ( cd "$b" && sha256sum -c e159-services.sha256 > /dev/null 2>&1 ) || { 
            error "E159服务状态快照损坏：$b";
            return 1
        };
    fi;
    _e159_system_restore_base "$b" || rc=1;
    if test -s "$b/e159-services.env"; then
        while IFS='|' read -r unit enabled active; do
            test -n "$unit" || continue;
            _e159_restore_service "$unit" "$enabled" "$active" || rc=1;
        done < "$b/e159-services.env";
    fi;
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_system_snapshot_base
_e202_system_snapshot_base() {
    local b="$1" unit;
    _e159_system_snapshot_base "$b" || return 1;
    : > "$b/e159-services.env" || return 1;
    for unit in xray-network-e159.service xray-network-e159.timer xray-host-safe-e159.service xray-network-e156.service xray-network-e156.timer xray-host-safe-e156.service xray-network-e154.service xray-network-e154.timer xray-host-safe-e154.service;
    do
        _e159_snapshot_service "$unit" >> "$b/e159-services.env" || return 1;
    done;
    ( cd "$b" && sha256sum e159-services.env > e159-services.sha256 ) || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_uninstall_base
_e202_uninstall_base() {
    local rc=0;
    _e188_uninstall_base "$@" || rc=$?;
    if test "$rc" -eq 0; then
        rm -f -- "$E188_SELF_PATH" "$E188_LATEST_PATH" 2> /dev/null || true;
        rm -rf -- "$E188_DIR" "$E188_TX_ROOT" "$(dirname "$E188_HOT_LOG")" 2> /dev/null || true;
    fi;
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_unrecognized_current_active
_e202_unrecognized_current_active() {
    local active_flag unit_state unit_enabled;
    _e202_small_bbr_active && return 1;
    active_flag=$(sed -n 's/^active=//p' "$E202_SMALL_STATE" 2> /dev/null | tail -n1);
    unit_state=$(systemctl is-active "$E202_SMALL_UNIT" 2> /dev/null || true);
    unit_enabled=$(systemctl is-enabled "$E202_SMALL_UNIT" 2> /dev/null || true);
    if test "$active_flag" = 1; then
        error "E202小BBR状态标记active，但状态格式/档位标识损坏：$E202_SMALL_STATE";
        error '拒绝覆盖其唯一恢复快照；请先依据状态文件和CRITICAL_RECOVERY_REQUIRED.env修复。';
        return 0;
    fi;
    case "$unit_state" in 
        active | activating | reloading)
            error "E202小BBR服务仍在运行，但活动状态无法验证：$E202_SMALL_UNIT";
            return 0
        ;;
    esac;
    case "$unit_enabled" in 
        enabled | enabled-runtime | linked | linked-runtime | alias)
            error "E202小BBR服务仍设为开机运行，但活动状态无法验证：$E202_SMALL_UNIT";
            error '拒绝把异常状态当作首次启用，否则退出快照会指向错误基线。';
            return 0
        ;;
    esac;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e202_unrecognized_legacy_active
_e202_unrecognized_legacy_active() {
    local label state unit fn active_flag unit_state unit_enabled row;
    local -a rows=("190|$E202_LEGACY_E190_STATE|$E202_LEGACY_E190_UNIT|_e202_legacy_e190_active" "192|$E202_LEGACY_E192_STATE|$E202_LEGACY_E192_UNIT|_e202_legacy_e192_active" "194|$E202_LEGACY_E194_STATE|$E202_LEGACY_E194_UNIT|_e202_legacy_e194_active" "196|$E202_LEGACY_E196_STATE|$E202_LEGACY_E196_UNIT|_e202_legacy_e196_active" "198|$E202_LEGACY_E198_STATE|$E202_LEGACY_E198_UNIT|_e202_legacy_e198_active" "200|$E202_LEGACY_E200_STATE|$E202_LEGACY_E200_UNIT|_e202_legacy_e200_active");
    for row in "${rows[@]}";
    do
        IFS='|' read -r label state unit fn <<< "$row";
        "$fn" && continue;
        active_flag=$(sed -n 's/^active=//p' "$state" 2> /dev/null | tail -n1);
        unit_state=$(systemctl is-active "$unit" 2> /dev/null || true);
        unit_enabled=$(systemctl is-enabled "$unit" 2> /dev/null || true);
        if test "$active_flag" = 1; then
            error "E${label}旧小BBR状态标记active，但档位格式无法识别：$state";
            error "必须使用原版ex199e${label}.sh检查/退出，E202拒绝直接删除其恢复依据。";
            return 0;
        fi;
        case "$unit_state" in 
            active | activating | reloading)
                error "E${label}旧小BBR服务仍在运行，但状态不完整：$unit";
                error "必须使用原版ex199e${label}.sh检查/退出，E202拒绝直接停止并覆盖。";
                return 0
            ;;
        esac;
        case "$unit_enabled" in 
            enabled | enabled-runtime | linked | linked-runtime | alias)
                error "E${label}旧小BBR服务仍设为开机运行，但状态未证明其可安全接管：$unit";
                error "必须使用原版ex199e${label}.sh退出；E202拒绝留下重启后复活的旧网络所有者。";
                return 0
            ;;
        esac;
    done;
    return 1
}
