# EEX3-FUNCTION small_bbr_e189_205 _e204_action_dns_ipv4
_e204_action_dns_ipv4() {
    _safe_jq_write '.dns=(.dns//{}) | .dns.queryStrategy="UseIPv4"'
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_action_metadata_only
_e204_action_metadata_only() {
    _safe_jq_write '(.inbounds[]? | select(.protocol=="vless")) |= (.sniffing=(.sniffing//{}) | .sniffing.enabled=true | .sniffing.metadataOnly=true)'
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_action_route_only
_e204_action_route_only() {
    _safe_jq_write '(.inbounds[]? | select(.protocol=="vless")) |= (.sniffing=(.sniffing//{}) | .sniffing.enabled=true | .sniffing.routeOnly=true)'
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_action_socket_keepalive
_e204_action_socket_keepalive() {
    _safe_jq_write '
      (.outbounds[]? | select(.protocol=="freedom" or .protocol=="vless" or .protocol=="shadowsocks")) |= (
        .streamSettings = (.streamSettings // {}) |
        .streamSettings.sockopt = (.streamSettings.sockopt // {}) |
        .streamSettings.sockopt.tcpKeepAliveIdle = 30 |
        .streamSettings.sockopt.tcpKeepAliveInterval = 15
      )'
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_advanced_action_tx
_e204_advanced_action_tx() {
    local label="${1:-advanced}" handler="${2:-}" tx="" rc=0 restore_rc=0;
    shift 2 || return 1;
    declare -F "$handler" > /dev/null 2>&1 || { 
        error "E204高级事务处理器不存在：$handler";
        return 1
    };
    tx=$(_e204_new_tx "advanced-$label") || return 1;
    _e140_system_snapshot "$tx/system" || { 
        rm -f -- "$tx/.active.env" 2> /dev/null || true;
        error "E204高级事务快照失败：$label";
        return 1
    };
    if "$handler" "$@"; then
        rm -f -- "$tx/.active.env" 2> /dev/null || true;
        return 0;
    else
        rc=$?;
    fi;
    error "E204高级事务失败：$label；执行外围完整恢复。";
    _e140_system_restore "$tx/system" || restore_rc=1;
    rm -f -- "$tx/.active.env" 2> /dev/null || true;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical "advanced-$label" "$tx/system" "outer rollback/readback failed; inner_rc=$rc" || true;
        error "严重：$label 外围回滚未完整通过；快照：$tx/system";
    else
        info "$label 已恢复到操作前文件与服务状态；快照：$tx/system";
    fi;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_advanced_menu
_e204_advanced_menu() {
    local n="" confirm="";
    while true; do
        clear;
        title 'V199e266：内核 / 网络 / 应用层高级控制板（E204稳定事务底座）';
        echo '  1) 完整127条请求 / 125个持久控制事务（保留IPv6策略）';
        echo '  2) 固化并验证 Xray Nice=-20';
        echo '  3) 固化 initcwnd/initrwnd=30';
        echo '  4) 网卡 Offload 独立事务';
        echo '  5) RPS/RFS 独立事务与状态';
        echo '  6) 完整28项应用层与系统微操中心';
        echo '  7) MSS Clamp 独立事务';
        echo '  8) TX Queue 独立事务';
        echo '  9) TC/HTB/fq 带宽控制事务';
        echo ' 10) BBR / XanMod官方包 / 完整源码编译';
        echo ' 11) 停用旧大包围优化服务（验证/回滚）';
        echo ' 12) 显示全部优化参数运行态';
        echo ' 13) Ring Buffer自适应最大化（显式事务）';
        echo ' 14) 直接执行第28项稳态一键优化';
        echo -e "  ${cyan}15) WARP定向分流（Google/Meta）${none}";
        echo -e "  ${cyan}16) WARP全局分流（仅Xray层）${none}";
        echo -e "  ${yellow}17) Cloudflare系统全隧道（SSH自动回滚）${none}";
        echo '  0) 返回';
        hr;
        read -rp '请输入操作代码: ' n || true;
        case "$n" in 
            1)
                _e170_network_menu
            ;;
            2)
                _e159_xray_action_tx xray-limits fix_xray_systemd_limits || true;
                _e116_pause
            ;;
            3)
                _e170_apply_init30_tx || true;
                _e116_pause
            ;;
            4)
                _e170_offload_action || true;
                _e116_pause
            ;;
            5)
                _e88_show_rps_rfs_state || true;
                read -rp '输入 APPLY-RPS 启用/刷新，其他键返回: ' confirm || true;
                test "$confirm" = APPLY-RPS && _e170_rps_action || true;
                _e116_pause
            ;;
            6)
                _e204_micro_control_menu || true
            ;;
            7)
                _e170_mss_action || true
            ;;
            8)
                _e170_txq_action || true;
                _e116_pause
            ;;
            9)
                _e204_tc_menu || true
            ;;
            10)
                _e170_bbr_kernel_menu
            ;;
            11)
                warn '将停用并删除E125/E126及更早的大包围优化服务。';
                read -rp '输入 DISABLE-LEGACY-OPT 确认: ' confirm || true;
                test "$confirm" = DISABLE-LEGACY-OPT && _e170_disable_legacy_tx || true;
                _e116_pause
            ;;
            12)
                _e170_show_optimization_status;
                _e116_pause
            ;;
            13)
                warn 'Ring最大化可能增加排队。';
                read -rp '输入 APPLY-RING 确认: ' confirm || true;
                test "$confirm" = APPLY-RING && _e170_ring_action || true;
                _e116_pause
            ;;
            14)
                warn '第28项可能重启Xray。';
                read -rp '输入 APPLY-MICRO-28 确认: ' confirm || true;
                test "$confirm" = APPLY-MICRO-28 && _e159_apply_micro_28 || true;
                _e116_pause
            ;;
            15)
                _e136_warp_preflight && _e138_warp_selective_menu || true
            ;;
            16)
                _e136_warp_preflight && _e138_warp_global_menu || true
            ;;
            17)
                _e136_warp_preflight && _e140_warp_full_menu || true
            ;;
            0)
                return 0
            ;;
            *)
                warn '无效操作。';
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_advanced_tx_self_test
_e204_advanced_tx_self_test() {
    ( local d result=0 restore_fail=0;
    d=$(mktemp -d /tmp/xray-e204-advanced-tx.XXXXXX) || return 1;
    : > "$d/order";
    function _e204_new_tx () 
    { 
        install -d -m 0700 "$d/tx/system" || return 1;
        : > "$d/tx/.active.env";
        printf '%s\n' "$d/tx"
    };
    function _e140_system_snapshot () 
    { 
        echo snapshot >> "$d/order"
    };
    function _e140_system_restore () 
    { 
        echo restore >> "$d/order";
        test "$restore_fail" -eq 0
    };
    function _e204_mark_critical () 
    { 
        echo critical >> "$d/order"
    };
    function _e204_test_failed_handler () 
    { 
        echo handler-37 >> "$d/order";
        return 37
    };
    ! _e204_advanced_action_tx test _e204_test_failed_handler > /dev/null 2>&1 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot handler-37 restore ' || result=1;
    test ! -e "$d/tx/.active.env" || result=1;
    : > "$d/order";
    restore_fail=1;
    ! _e204_advanced_action_tx test _e204_test_failed_handler > /dev/null 2>&1 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot handler-37 restore critical ' || result=1;
    rm -rf -- "$d";
    return "$result" )
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_apply_init30_tx_base
_e204_apply_init30_tx_base() {
    local tx oldroute;
    oldroute=$(ip -4 route show default 2> /dev/null | head -n1 || true);
    test -n "$oldroute" || { 
        error "没有IPv4默认路由。";
        return 1
    };
    tx=$(_e168_system_tx_begin init30) || return 1;
    if _e137_apply_init_window_default30 && grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) && grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) && systemctl is-enabled --quiet xray-init-window-e137.timer 2> /dev/null && systemctl is-active --quiet xray-init-window-e137.timer 2> /dev/null && bash -n "$E137_INIT_SCRIPT"; then
        _e168_prune_system_tx "$tx";
        return 0;
    fi;
    _e168_system_tx_fail "$tx" init30 || true;
    ip -4 route replace $oldroute > /dev/null 2>&1 || true;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_atomic_install_base
_e204_atomic_install_base() {
    local src="$1" target="$2" mode="${3:-0600}" dir base stage;
    test -f "$src" || return 1;
    dir=$(dirname "$target");
    base=$(basename "$target");
    mkdir -p "$dir" || return 1;
    stage="$dir/.${base}.e118.$$";
    install -m "$mode" "$src" "$stage" || { 
        rm -f "$stage";
        return 1
    };
    mv -f "$stage" "$target" || { 
        rm -f "$stage";
        return 1
    }
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_bbr_conf_safe
_e204_bbr_conf_safe() {
    local conf="$1";
    test -s "$conf" || { 
        error "BBR参数文件不存在或为空：$conf";
        return 1
    };
    awk '
      /^[[:space:]]*($|#)/ {next}
      /^[A-Z][A-Z0-9_]*=[0-9]+$/ {next}
      /^[A-Z][A-Z0-9_]*="[A-Za-z0-9_. +*\/<>()-]+"$/ {next}
      {print NR ":" $0 > "/dev/stderr"; bad=1}
      END {exit bad?1:0}
    ' "$conf" || { 
        error 'BBR参数文件含可执行Shell语法或未知格式；拒绝source和编译。';
        return 1
    };
    ! grep -Eq '(`|\$\(|\$\{|;|\||&|(^|[^<])>([^=]|$))' "$conf" || { 
        error 'BBR参数文件含命令替换、控制符或重定向。';
        return 1
    }
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_clean_space_base
_e204_clean_space_base() {
    _e202_check_and_clean_space_base "$@" || return 1;
    _e202_prune_tx
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_dat_existing_pair_usable
_e204_dat_existing_pair_usable() {
    local probe geoip_size geosite_size;
    test -x "$UPDATE_DAT_SCRIPT" && bash -n "$UPDATE_DAT_SCRIPT" || return 1;
    test -x "$XRAY_BIN" || return 1;
    test -r "$DAT_DIR/geoip.dat" && test -r "$DAT_DIR/geosite.dat" || return 1;
    geoip_size=$(stat -c '%s' "$DAT_DIR/geoip.dat" 2> /dev/null || true);
    geosite_size=$(stat -c '%s' "$DAT_DIR/geosite.dat" 2> /dev/null || true);
    [[ "$geoip_size" =~ ^[0-9]+$ && "$geosite_size" =~ ^[0-9]+$ ]] || return 1;
    test "$geoip_size" -gt 1024 && test "$geosite_size" -gt 1024 || return 1;
    systemctl is-enabled --quiet xray-dat-update.timer 2> /dev/null || return 1;
    systemctl is-active --quiet xray-dat-update.timer 2> /dev/null || return 1;
    probe=$(_e118_mktemp e204-dat-existing-probe.json) || return 1;
    cat > "$probe" <<'EOF_E204_DAT_EXISTING_PROBE'
{"log":{"loglevel":"none"},"inbounds":[],"outbounds":[{"protocol":"freedom","tag":"direct"}],"routing":{"domainStrategy":"AsIs","rules":[{"ip":["geoip:private"],"outboundTag":"direct"},{"domain":["geosite:category-ads-all"],"outboundTag":"direct"}]}}
EOF_E204_DAT_EXISTING_PROBE

    "$XRAY_BIN" run -test -config "$probe" > /dev/null 2>&1 || return 1;
    test ! -s "$CONFIG" || _e118_xray_test_config "$CONFIG" 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_disable_legacy_tx_base
_e204_disable_legacy_tx_base() {
    local tx svc p rc=0;
    local -a svcs=(xray-hw-tweaks.service nic-optimize.service rps-optimize.service txqueue.service xray-accel-e125.service xray-accel-e126.service);
    local -a paths=(/etc/systemd/system/xray-hw-tweaks.service /usr/local/bin/xray-hw-tweaks.sh /etc/systemd/system/nic-optimize.service /usr/local/bin/nic-optimize.sh /etc/systemd/system/rps-optimize.service /usr/local/bin/rps-optimize.sh /etc/systemd/system/txqueue.service /usr/local/bin/txqueue.sh /etc/systemd/system/xray-accel-e125.service /usr/local/bin/xray-accel-e125.sh /etc/systemd/system/xray-accel-e126.service /usr/local/bin/xray-accel-e126.sh);
    tx=$(_e168_system_tx_begin disable-legacy) || return 1;
    _e135_disable_legacy_optimizers || rc=1;
    for svc in "${svcs[@]}";
    do
        systemctl is-enabled --quiet "$svc" 2> /dev/null && rc=1 || true;
        systemctl is-active --quiet "$svc" 2> /dev/null && rc=1 || true;
    done;
    for p in "${paths[@]}";
    do
        test ! -e "$p" && test ! -L "$p" || rc=1;
    done;
    if test "$rc" -eq 0; then
        _e168_prune_system_tx "$tx";
        info "旧大包围优化服务已停用，并通过文件/enable/active三重读回。";
        return 0;
    fi;
    _e168_system_tx_fail "$tx" '旧优化器清理' || true;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_dnsmasq_base
_e204_dnsmasq_base() {
    title "Dnsmasq 本地缓存稳态模式（验证通过才接管 resolv.conf）";
    e67_disable_static_dns_guard;
    chattr -i /etc/resolv.conf 2> /dev/null || true;
    export DEBIAN_FRONTEND=noninteractive;
    apt-get update -y > /dev/null 2>&1 || true;
    apt-get install -y dnsmasq > /dev/null 2>&1 || yum install -y dnsmasq > /dev/null 2>&1 || true;
    if ! command -v dnsmasq > /dev/null 2>&1; then
        warn "dnsmasq 未安装成功，回退静态 DNS，避免 resolv.conf 指向无人监听的 127.0.0.1。";
        write_static_resolv_conf;
        return 1;
    fi;
    systemctl stop systemd-resolved > /dev/null 2>&1 || true;
    systemctl disable systemd-resolved > /dev/null 2>&1 || true;
    systemctl stop resolvconf > /dev/null 2>&1 || true;
    systemctl disable resolvconf > /dev/null 2>&1 || true;
    cat > /etc/dnsmasq.conf <<'EOF_DNSMASQ_E67'
port=53
listen-address=127.0.0.1
bind-interfaces
no-resolv
no-poll
domain-needed
bogus-priv
cache-size=10000
min-cache-ttl=300
neg-ttl=60
max-cache-ttl=86400
server=1.1.1.1
server=8.8.8.8
server=208.67.224.224
strict-order
EOF_DNSMASQ_E67

    systemctl enable dnsmasq > /dev/null 2>&1 || true;
    if systemctl restart dnsmasq > /dev/null 2>&1 && dns_local_listener_ok; then
        cp -a /etc/resolv.conf "$BACKUP_DIR/resolv.conf.before-dnsmasq.e67.$(date +%Y%m%d_%H%M%S).bak" 2> /dev/null || true;
        rm -f /etc/resolv.conf 2> /dev/null || true;
        cat > /etc/resolv.conf <<'EOF_RESOLV_DNSMASQ_E67'
nameserver 127.0.0.1
options timeout:2 attempts:2 rotate
EOF_RESOLV_DNSMASQ_E67

        chmod 644 /etc/resolv.conf 2> /dev/null || true;
        if getent hosts api.ipify.org > /dev/null 2>&1 || getent hosts google.com > /dev/null 2>&1; then
            echo "dnsmasq" > "$E67_DNS_MODE_FILE" 2> /dev/null || true;
            info "dnsmasq 已启用并接管本机解析。";
            return 0;
        fi;
    fi;
    warn "dnsmasq 未通过监听/解析验证，自动回退静态 DNS。";
    systemctl stop dnsmasq > /dev/null 2>&1 || true;
    systemctl disable dnsmasq > /dev/null 2>&1 || true;
    write_static_resolv_conf;
    return 1
}
