# EEX3-FUNCTION small_bbr_e189_205 _e204_hot_rollback_self_test
_e204_hot_rollback_self_test() {
    ( local d result=0;
    d=$(mktemp -d /tmp/xray-e204-hot-rollback.XXXXXX) || return 1;
    : > "$d/order";
    function _e204_prepare () 
    { 
        :
    };
    function _e204_new_tx () 
    { 
        install -d -m 0700 "$d/tx/system";
        printf '%s\n' "$d/tx"
    };
    function _e159_phase_log () 
    { 
        :
    };
    function _e140_system_snapshot () 
    { 
        echo snapshot >> "$d/order"
    };
    function _e204_hot_update_base () 
    { 
        echo mutate-fail >> "$d/order";
        return 1
    };
    function _e140_system_restore () 
    { 
        echo restore >> "$d/order";
        return 0
    };
    function _e204_mark_critical () 
    { 
        echo critical >> "$d/order";
        return 0
    };
    ! E204_INTERNAL_SELF_TEST=1 E204_INTERNAL_SELF_TEST_TMP="$d" _e204_hot_update > /dev/null 2>&1 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot mutate-fail restore ' || result=1;
    rm -rf -- "$d";
