# EEX3-FUNCTION small_bbr_e189_205 _e204_hot_update
_e204_hot_update() {
    ( local tx rc=0 restore_rc=0 hot_log="$E204_HOT_LOG" lock_path=/run/lock/xray-e204-hot-update.lock;
    _e204_prepare || return 1;
    if test "${E204_INTERNAL_SELF_TEST:-0}" = 1; then
        if test -n "${E204_INTERNAL_SELF_TEST_TMP:-}"; then
            install -d -m 0700 "$E204_INTERNAL_SELF_TEST_TMP" || return 1;
            hot_log="$E204_INTERNAL_SELF_TEST_TMP/hot.log";
        else
            hot_log=$(mktemp /tmp/xray-e204-hot-selftest.XXXXXX.log) || return 1;
        fi;
        lock_path="${hot_log}.lock";
    fi;
    exec 204> "$lock_path";
    flock -n 204 || { 
        error '已有E204热更新事务正在运行。';
        return 1
    };
    tx=$(_e204_new_tx hot-update-outer) || return 1;
    : > "$hot_log" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e159_phase_log "$hot_log" outer-snapshot begin;
    _e140_system_snapshot "$tx/system" || { 
        _e204_tx_close "$tx" || true;
        return 1
    };
    _e159_phase_log "$hot_log" outer-snapshot ok;
    _e204_hot_update_base || rc=$?;
    test "$rc" -ne 0 || _e204_install_self || rc=1;
    test "$rc" -ne 0 || _e204_write_version || rc=1;
    test "$rc" -ne 0 || _e204_hot_verify || rc=1;
    if test "$rc" -eq 0; then
        _e159_phase_log "$hot_log" final-readback ok;
        info 'V199e204热更新完成：核心、节点、网络、SSH、WARP、IPv6与脚本入口均已读回。';
        info "外层回滚快照：$tx/system";
        _e204_tx_close "$tx";
        return $?;
    fi;
    _e159_phase_log "$hot_log" final-readback fail;
    error 'E204热更新未完整通过，开始恢复热更新前完整系统状态。';
    _e140_system_restore "$tx/system" || restore_rc=1;
    if test "$restore_rc" -eq 0 && test -s "$CONFIG" && test -x "$XRAY_BIN"; then
        _e118_xray_test_config "$CONFIG" 1 || restore_rc=1;
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || restore_rc=1;
        fi;
    fi;
    if test "$restore_rc" -ne 0; then
        _e204_mark_critical hot-update "$tx/system" 'outer rollback/readback failed' || true;
        error "严重：E204总回滚未完全通过；必须保留快照：$tx/system";
    else
        info "已恢复热更新前状态；快照：$tx/system";
    fi;
    _e204_tx_close "$tx" || true;
    return 1 )
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_hot_update_base
_e204_hot_update_base() {
    ( local small_owner=none outer="" rc=0 legacy_profile_tmp="" legacy_source="";
    local legacy_raw_tmp="" saved_profile_snapshot="";
    local assignments=0 profile_id="";
    if _e202_small_bbr_active; then
        small_owner=e202;
    else
        if _e202_legacy_e200_active; then
            small_owner=e200;
        else
            if _e202_legacy_e198_active; then
                small_owner=e198;
            else
                if _e202_legacy_e196_active; then
                    small_owner=e196;
                else
                    if _e202_legacy_e194_active; then
                        small_owner=e194;
                    else
                        if _e202_legacy_e192_active; then
                            small_owner=e192;
                        else
                            if _e202_legacy_e190_active; then
                                small_owner=e190;
                            fi;
                        fi;
                    fi;
                fi;
            fi;
        fi;
    fi;
    if test "$small_owner" = e202; then
        outer=$(_e202_new_tx hot-update-outer) || return 1;
        _e140_system_snapshot "$outer/system" || return 1;
        _e202_snapshot_valid "$outer/system" || return 1;
        legacy_profile_tmp=$(_e118_mktemp e202-active-profile-import) || return 1;
        _e202_capture_active_config 202 "$E202_SMALL_STATE" "$E202_SMALL_CONF" "$legacy_profile_tmp" || return 1;
        saved_profile_snapshot="$outer/saved-profile-choice";
        _e135_snapshot_file "$E202_SMALL_PROFILE" "$saved_profile_snapshot" || return 1;
        _e202_small_bbr_disable force || { 
            _e202_small_bbr_restore_snapshot "$outer/system" hot-preflight-restore || true;
            return 1
        };
    else
        if test "$small_owner" = e200; then
            legacy_profile_tmp=$(_e118_mktemp e200-profile-import) || return 1;
            legacy_raw_tmp=$(_e118_mktemp e200-active-profile-raw) || return 1;
            _e202_capture_active_config 200 "$E202_LEGACY_E200_STATE" "$E202_LEGACY_E200_CONF" "$legacy_raw_tmp" || return 1;
            if _e202_legacy_e200_validate_file "$E202_LEGACY_E200_PROFILE" && ! cmp -s "$E202_LEGACY_E200_PROFILE" "$E202_LEGACY_E200_CONF"; then
                warn 'E200另有尚未应用的保存档；本次只迁移状态哈希密封的活动档，旧保存文件继续保留供人工核对。';
            fi;
            _e202_prepare_legacy_profile 200 "$legacy_raw_tmp" "$legacy_profile_tmp" || return 1;
            _e202_legacy_e200_disable || return 1;
        else
            if test "$small_owner" = e198; then
                legacy_profile_tmp=$(_e118_mktemp e198-profile-import) || return 1;
                legacy_raw_tmp=$(_e118_mktemp e198-active-profile-raw) || return 1;
                _e202_capture_active_config 198 "$E202_LEGACY_E198_STATE" "$E202_LEGACY_E198_CONF" "$legacy_raw_tmp" || return 1;
                if _e202_legacy_profile_id "$E202_LEGACY_E198_PROFILE" 198 > /dev/null && ! cmp -s "$E202_LEGACY_E198_PROFILE" "$E202_LEGACY_E198_CONF"; then
                    warn 'E198另有尚未应用的保存档；本次只迁移状态哈希密封的活动档，旧保存文件继续保留供人工核对。';
                fi;
                _e202_prepare_legacy_profile 198 "$legacy_raw_tmp" "$legacy_profile_tmp" || return 1;
                _e202_legacy_e198_disable || return 1;
            else
                if test "$small_owner" = e196; then
                    legacy_profile_tmp=$(_e118_mktemp e196-profile-import) || return 1;
                    legacy_raw_tmp=$(_e118_mktemp e196-active-profile-raw) || return 1;
                    _e202_capture_active_config 196 "$E202_LEGACY_E196_STATE" "$E202_LEGACY_E196_CONF" "$legacy_raw_tmp" || return 1;
                    legacy_source="$legacy_raw_tmp";
                    if _e202_legacy_profile_id "$E202_LEGACY_E196_PROFILE" 196 > /dev/null && ! cmp -s "$E202_LEGACY_E196_PROFILE" "$E202_LEGACY_E196_CONF"; then
                        warn 'E196另有尚未应用的保存档；本次只迁移已密封的活动档，旧保存文件继续保留供人工核对。';
                    fi;
                    _e202_prepare_legacy_profile 196 "$legacy_source" "$legacy_profile_tmp" || return 1;
                    _e202_legacy_e196_disable || return 1;
                else
                    if test "$small_owner" = e194; then
                        legacy_profile_tmp=$(_e118_mktemp e194-profile-import) || return 1;
                        _e202_capture_active_config 194 "$E202_LEGACY_E194_STATE" "$E202_LEGACY_E194_CONF" "$legacy_profile_tmp" || return 1;
                        if _e202_small_bbr_validate_file "$E202_LEGACY_E194_PROFILE" && ! cmp -s "$E202_LEGACY_E194_PROFILE" "$E202_LEGACY_E194_CONF"; then
                            warn 'E194另有尚未应用的保存档；本次只迁移已密封的活动档。';
                        fi;
                        _e202_legacy_e194_disable || return 1;
                    else
                        if test "$small_owner" = e192; then
                            _e202_legacy_e192_disable || return 1;
                        else
                            if test "$small_owner" = e190; then
                                _e202_legacy_e190_disable || return 1;
                            fi;
                        fi;
                    fi;
                fi;
            fi;
        fi;
    fi;
    _e202_hot_update_base || rc=1;
    if test "$rc" -eq 0; then
        case "$small_owner" in 
            e202 | e194 | e196 | e198 | e200)
                _e202_small_bbr_profile_save "$legacy_profile_tmp" || rc=1
            ;;
        esac;
    fi;
    if test "$rc" -eq 0 && test "$small_owner" != none; then
        _e202_small_bbr_enable force || rc=1;
    fi;
    if test "$rc" -ne 0 && test "$small_owner" = e202; then
        error 'E202热更新/小BBR重入失败，恢复热更新前的E202活动档位。';
        _e202_small_bbr_restore_snapshot "$outer/system" hot-update-failed || true;
        return 1;
    fi;
    if test "$rc" -ne 0 && test "$small_owner" != none; then
        error "E202热更新/小BBR重入失败；原版${small_owner}已安全退出，当前保留已通过回滚复检的非小BBR网络状态。";
        error '拒绝由E202反向猜测并重建旧版本档位。';
        return 1;
    fi;
    if test "$small_owner" = e202; then
        _e135_restore_file "$E202_SMALL_PROFILE" "$saved_profile_snapshot" || { 
            error 'E202活动档已重入，但恢复热更新前的待应用保存档失败；执行总回滚。';
            _e202_small_bbr_restore_snapshot "$outer/system" hot-saved-choice-failed || true;
            return 1
        };
    fi;
    if test "$small_owner" != none; then
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF");
        profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF");
        info "热更新后已进入E202：$(_e202_small_bbr_profile_name "$profile_id")；持久参数=$assignments，隐藏参数=0。";
    fi;
    return "$rc" )
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_hot_update_preflight
_e204_hot_update_preflight() {
    local owner="" fn;
    bash -n "$SCRIPT_PATH" || return 1;
    test "$SCRIPT_VERSION" = 199e204 && test "$E204_VERSION" = 199e204 || return 1;
    for fn in _e204_install_self _e140_system_snapshot _e140_system_restore _e182_install_mode _e159_network_apply _e159_network_remove _e185_warp_health_check _e204_structure_audit;
    do
        declare -F "$fn" > /dev/null 2>&1 || { 
            error "E204热更新缺少最终函数：$fn";
            return 1
        };
    done;
    _e204_structure_audit > /dev/null || { 
        error 'E204发布结构/参数不变量门禁失败；热更新尚未开始。';
        return 1
    };
    _e202_hot_update_preflight || return 1;
    owner=$(_e204_legacy_small_bbr_owner 2> /dev/null || true);
    if test -n "$owner"; then
        error "检测到旧小BBR所有者：$owner。E204不会猜测旧版快照并代替旧版退出。";
        error '请先执行对应旧版脚本的 --small-bbr-disable，确认恢复成功后再运行E204热更新。';
        return 1;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_hot_verify
_e204_hot_verify() {
    local target;
    for target in "$SYMLINK" "$E204_SELF_PATH" "$E204_LATEST_PATH" "$E202_SELF_PATH";
    do
        test -x "$target" && bash -n "$target" && cmp -s "$SCRIPT_PATH" "$target" || { 
            error "E204入口安装读回失败：$target";
            return 1
        };
    done;
    test "$(cat "$SCRIPT_VERSION_FILE" 2> /dev/null || true)" = "$E204_VERSION" || { 
        error '脚本版本文件没有读回199e204。';
        return 1
    };
    if test -s "$CONFIG"; then
        _e118_xray_test_config "$CONFIG" 1 || return 1;
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || return 1;
        fi;
    fi;
    if test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || return 1;
    fi;
    _e182_ipv6_hot_verify || return 1;
    if _e202_small_bbr_active; then
        _e202_small_bbr_status > /dev/null || return 1;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_install_mode_base
_e204_install_mode_base() {
    local rc=0;
    local E188_SUMMARY_SUPPRESS=1;
    local E188_SUMMARY_PENDING=0;
    E182_SNI_CANCELLED=0;
    E168_SNI_CANCELLED=0;
    _e188_install_mode_base "$@" || rc=$?;
    test "$rc" -eq 0 || return "$rc";
    if test "${E182_SNI_CANCELLED:-0}" = 1 || test "${E168_SNI_CANCELLED:-0}" = 1; then
        return 0;
    fi;
    E188_SUMMARY_SUPPRESS=0;
    E188_SUMMARY_PENDING=0;
    do_summary || rc=$?;
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_install_self
_e204_install_self() {
    _e214_install_self "$@"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_ipv4_management_viable
_e204_ipv4_management_viable() {
    local src;
    ip -4 route show default 2> /dev/null | grep -q . || return 1;
    src=$(ip -4 route get 1.1.1.1 2> /dev/null | awk '{for(i=1;i<=NF;i++) if($i=="src"){print $(i+1);exit}}');
    test -n "$src" || return 1;
    awk -F. 'NF==4{for(i=1;i<=4;i++)if($i!~/^[0-9]+$/||$i>255)exit 1;exit 0}{exit 1}' <<< "$src"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_ipv6_apply_base
_e204_ipv6_apply_base() {
    ( local desired="$1" source="${2:-menu}" hot="${3:-0}";
    local tx initial old_initial mode rc=0 marker_tmp;
    case "$desired" in 
        0 | 1)

        ;;
        *)
            return 1
        ;;
    esac;
    if test "$desired" = 1 && _e182_ipv6_live_ssh_session; then
        error '当前管理会话使用IPv6；拒绝立即关闭IPv6，避免SSH自锁。请改用IPv4 SSH或控制台后重试。';
        return 2;
    fi;
    _e214_ensure_run_lock || return 1;
    exec 182> /run/lock/xray-ipv6-policy-e182.lock;
    flock -w 30 182 || { 
        error '另一个IPv6策略事务正在运行。';
        return 1
    };
    _e182_ipv6_hot_recover_stale || { 
        error '无法恢复上次中断的IPv6事务；拒绝覆盖其回滚证据。';
        return 1
    };
    tx=$(_e182_new_tx ipv6-policy) || return 1;
    _e182_ipv6_tx_snapshot "$tx" || return 1;
    old_initial=$(_e182_ipv6_state_get initial_transaction '');
    if _e182_ipv6_tx_valid "$old_initial"; then
        initial="$old_initial";
    else
        initial="$tx";
    fi;
    if test "$hot" = 1; then
        marker_tmp=$(_e182_secure_state_temp "$E182_IPV6_HOT_MARKER") || return 1;
        printf 'transaction=%s\n' "$tx" > "$marker_tmp" && _e182_commit_state "$marker_tmp" "$E182_IPV6_HOT_MARKER" || { 
            rm -f -- "$marker_tmp";
            return 1
        };
    fi;
    if test ! -d "$E182_IPV6_PROC_ROOT"; then
        if test "$desired" = 0; then
            error '当前内核未提供IPv6协议栈，无法执行“开启IPv6”。';
            rc=1;
        else
            systemctl disable --now "$E182_IPV6_UNIT" > /dev/null 2>&1 || true;
            rm -f -- "$E182_IPV6_CONF" "$E182_IPV6_APPLY" "$E182_IPV6_SERVICE" || rc=1;
            systemctl daemon-reload > /dev/null 2>&1 || rc=1;
            test "$rc" -ne 0 || _e182_ipv6_state_write kernel-disabled 1 "$tx" "$initial" "$source" || rc=1;
        fi;
    else
        _e182_ipv6_install_assets "$desired" || rc=1;
        test "$rc" -ne 0 || _e182_ipv6_verify "$desired" || rc=1;
        if test "$desired" = 1; then
            mode=disabled;
        else
            mode=enabled;
        fi;
        test "$rc" -ne 0 || _e182_ipv6_state_write "$mode" "$desired" "$tx" "$initial" "$source" || rc=1;
    fi;
    if test "$rc" -ne 0; then
        if ! _e182_ipv6_tx_restore "$tx" > /dev/null 2>&1; then
            install -d -m 0700 "$E182_DIR" 2> /dev/null || true;
            { 
                echo "time=$(date -Is 2> /dev/null || date)";
                echo 'operation=ipv6-policy';
                echo "backup=$tx";
                echo "desired_disable_ipv6=$desired"
            } > "$E182_CRITICAL_MARKER" 2> /dev/null || true;
            error "严重：IPv6策略提交失败且回滚未通过；保留快照：$tx";
            return 1;
        fi;
        rm -f -- "$E182_IPV6_HOT_MARKER" 2> /dev/null || true;
        error 'IPv6策略事务失败，已恢复配置、服务状态和全部可见接口运行值。';
        return 1;
    fi;
    rm -f -- "$E182_IPV6_PENDING" 2> /dev/null || true;
    if grep -qx 'operation=ipv6-policy' "$E182_CRITICAL_MARKER" 2> /dev/null; then
        rm -f -- "$E182_CRITICAL_MARKER" 2> /dev/null || true;
    fi;
    if test "$desired" = 1; then
        info 'IPv6已永久关闭，并通过当前接口、sysctl.d与开机复检服务读回。';
    else
        info 'IPv6已永久开启，并通过当前接口、sysctl.d与开机复检服务读回。';
    fi )
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_ipv6_hot_verify_base
_e204_ipv6_hot_verify_base() {
    local desired;
    if test -s "$E182_IPV6_PENDING"; then
        _e182_ipv6_live_ssh_session || return 1;
        grep -qx 'desired_disable_ipv6=1' "$E182_IPV6_PENDING";
        return;
    fi;
    desired=$(_e182_ipv6_policy_desired) || return 1;
    _e182_ipv6_verify "$desired"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_ipv6_pending_abi_self_test
_e204_ipv6_pending_abi_self_test() {
    ( local d captured="";
    d=$(mktemp -d /tmp/xray-e204-ipv6-pending.XXXXXX) || return 1;
    function _e182_secure_state_temp () 
    { 
        mktemp "$d/pending.XXXXXX"
    };
    function _e182_commit_state () 
    { 
        captured=$(cat "$1");
        return 0
    };
    _e204_ipv6_pending_write || { 
        rm -rf -- "$d";
        return 1
    };
    grep -qx 'reason=live-ipv6-ssh-session' <<< "$captured" || { 
        rm -rf -- "$d";
        return 1
    };
    rm -rf -- "$d" )
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_ipv6_pending_write
_e204_ipv6_pending_write() {
    local reason="${1:-live-ipv6-ssh-session}" tmp;
    tmp=$(_e182_secure_state_temp "$E182_IPV6_PENDING") || return 1;
    { 
        echo 'desired_disable_ipv6=1';
        echo "reason=$reason";
        echo "ssh_connection=${SSH_CONNECTION:-none}";
        echo "checked_at=$(date -Is 2> /dev/null || date)"
    } > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    _e182_commit_state "$tmp" "$E182_IPV6_PENDING"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_kernel_config_guard_base
_e204_kernel_config_guard_base() {
    local _kernel_src_dir="$1" virt fs dev;
    virt=$(systemd-detect-virt 2> /dev/null || echo none);
    fs=$(findmnt -n -o FSTYPE / 2> /dev/null || echo ext4);
    dev=$(findmnt -n -o SOURCE / 2> /dev/null || true);
    test -x "$_kernel_src_dir/scripts/config" || return 1;
    "$_kernel_src_dir/scripts/config" --enable CONFIG_BLK_DEV_INITRD --enable CONFIG_DEVTMPFS --enable CONFIG_DEVTMPFS_MOUNT || return 1;
    case "$fs" in 
        ext4)
            "$_kernel_src_dir/scripts/config" --enable CONFIG_EXT4_FS
        ;;
        xfs)
            "$_kernel_src_dir/scripts/config" --enable CONFIG_XFS_FS
        ;;
        btrfs)
            "$_kernel_src_dir/scripts/config" --enable CONFIG_BTRFS_FS
        ;;
    esac;
    case "$virt" in 
        kvm | qemu)
            "$_kernel_src_dir/scripts/config" --enable CONFIG_VIRTIO --enable CONFIG_VIRTIO_PCI --enable CONFIG_VIRTIO_BLK --enable CONFIG_VIRTIO_NET --enable CONFIG_SCSI_VIRTIO || return 1
        ;;
        xen*)
            "$_kernel_src_dir/scripts/config" --enable CONFIG_XEN --enable CONFIG_XEN_PV --enable CONFIG_XEN_BLKDEV_FRONTEND --enable CONFIG_XEN_NETDEV_FRONTEND || true
        ;;
        microsoft)
            "$_kernel_src_dir/scripts/config" --enable CONFIG_HYPERV --enable CONFIG_HYPERV_STORAGE --enable CONFIG_HYPERV_NET || true
        ;;
    esac;
    [[ "$dev" == *nvme* ]] && "$_kernel_src_dir/scripts/config" --enable CONFIG_BLK_DEV_NVME --enable CONFIG_NVME_CORE || true;
    "$_kernel_src_dir/scripts/config" --enable CONFIG_TCP_CONG_BBR --enable CONFIG_NET_SCH_FQ --set-str CONFIG_DEFAULT_TCP_CONG bbr || true;
    "$_kernel_src_dir/scripts/config" --set-str CONFIG_LOCALVERSION '-xrv135' || true;
    "$_kernel_src_dir/scripts/config" --set-str CONFIG_SYSTEM_TRUSTED_KEYS '' --set-str CONFIG_SYSTEM_REVOCATION_KEYS '' || true
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_kernel_kconfig_verify
_e204_kernel_kconfig_verify() {
    local src="$1" rc=0;
    test -s "$src/.config" || { 
        error '内核.config不存在。';
        return 1
    };
    grep -Eq '^CONFIG_TCP_CONG_BBR=(y|m)$' "$src/.config" || rc=1;
    grep -qx 'CONFIG_DEFAULT_BBR=y' "$src/.config" || rc=1;
    grep -qx 'CONFIG_DEFAULT_TCP_CONG="bbr"' "$src/.config" || rc=1;
    grep -Eq '^CONFIG_NET_SCH_FQ=(y|m)$' "$src/.config" || rc=1;
    if test "$rc" -ne 0; then
        error 'BBR/FQ默认Kconfig读回不完整；拒绝继续安装内核。';
        return 1;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_legacy_optimizer_owned
_e204_legacy_optimizer_owned() {
    local unit="$1";
    case "$unit" in 
        nic-optimize.service)
            grep -Fqx 'ExecStart=/usr/local/bin/nic-optimize.sh' /etc/systemd/system/nic-optimize.service 2> /dev/null && grep -q 'rx-gro-hw' /usr/local/bin/nic-optimize.sh 2> /dev/null
        ;;
        rps-optimize.service)
            grep -Fqx 'ExecStart=/usr/local/bin/rps-optimize.sh' /etc/systemd/system/rps-optimize.service 2> /dev/null && grep -q 'rps_sock_flow_entries=131072' /usr/local/bin/rps-optimize.sh 2> /dev/null
        ;;
        txqueue.service)
            grep -Fqx 'Description=Set TX Queue Length for Low Latency' /etc/systemd/system/txqueue.service 2> /dev/null && grep -Eq '^ExecStart=.*/ip([[:space:]]+|$).*txqueuelen[[:space:]]+3000$' /etc/systemd/system/txqueue.service 2> /dev/null
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_legacy_small_bbr_owner
_e204_legacy_small_bbr_owner() {
    local v;
    for v in 200 198 196 194 192 190;
    do
        if "_e202_legacy_e${v}_active" 2> /dev/null; then
            printf 'e%s\n' "$v";
            return 0;
        fi;
    done;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_legacy_swapfile_owned
_e204_legacy_swapfile_owned() {
    test -f "$E204_SWAPFILE" && test ! -L "$E204_SWAPFILE" || return 1;
    test "$(stat -c '%u:%a' "$E204_SWAPFILE" 2> /dev/null || true)" = 0:600 || return 1;
    awk -v p="$E204_SWAPFILE" '$1==p && $3=="swap"{found=1} END{exit !found}' /etc/fstab 2> /dev/null
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_log_retention_base
_e204_log_retention_base() {
    _e142_log_retention_before_migration || return 1;
    rm -f -- "$E142_LEGACY_LOG_SCRIPT" "$E142_LEGACY_LOG_DROPIN" 2> /dev/null || true;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl restart xray-log-retention-e121.service > /dev/null 2>&1 || return 1;
    systemctl is-enabled --quiet xray-log-retention-e121.timer 2> /dev/null || return 1;
    systemctl is-active --quiet xray-log-retention-e121.timer 2> /dev/null || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_main_menu
_e204_main_menu() {
    _e214_main_menu "$@"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_mark_critical
_e204_mark_critical() {
    local operation="$1" backup="${2:-unknown}" detail="${3:-unspecified}" tmp;
    _e204_prepare || return 1;
    tmp=$(_e118_mktemp e204-critical) || return 1;
    { 
        echo "time=$(date -Is 2> /dev/null || date)";
        echo "operation=$operation";
        echo "backup=$backup";
        printf 'detail=%s\n' "$detail" | tr '\n\r' '  '
    } > "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$E204_CRITICAL_MARKER" 0600
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_micro28_base
_e204_micro28_base() {
    local protect sysbackup network_before="" was_active=0;
    test -s "$CONFIG" || { 
        error "config.json不存在。";
        return 1
    };
    protect=$(_e116_backup_state before_micro28_e159) || return 1;
    _e118_save_core_payload "$protect" || return 1;
    sysbackup=$(_e159_new_tx micro28) || return 1;
    _e140_system_snapshot "$sysbackup" || return 1;
    network_before=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" 2> /dev/null | tail -n1);
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
    was_active=${was_active:-0};
    if ! _turn_on_app || ! apply_safe_turbo_defaults; then
        error "第28项失败，恢复执行前网络、系统和Xray状态。";
        _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true;
        return 1;
    fi;
    if ! systemctl daemon-reload > /dev/null 2>&1; then
        error "第28项systemd重载失败，恢复完整旧状态。";
        _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true;
        return 1;
    fi;
    if test "$was_active" = 1; then
        if ! systemctl restart xray.service > /dev/null 2>&1 || ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "第28项后Xray重启/运行探针失败，恢复完整旧状态。";
            _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true;
            return 1;
        fi;
    else
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            error "第28项意外启动原本停止的Xray，恢复完整旧状态。";
            _e159_micro28_restore "$protect" "$sysbackup" "$network_before" || true;
            return 1;
        fi;
    fi;
    _e142_prune_transactions "$sysbackup" "$protect" || true;
    _e159_prune_system_tx "$sysbackup";
    info "第28项已通过Xray配置测试、MainPID/监听端口探针和完整网络事务。"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_micro_control_menu
_e204_micro_control_menu() {
    local opt="" qdisc="" confirm="";
