            ;;
            12)
                warn 'Dnsmasq会接管resolv.conf并停用systemd-resolved/resolvconf。';
                read -rp '输入 APPLY-DNSMASQ 确认: ' confirm || true;
                test "$confirm" = APPLY-DNSMASQ && _e159_xray_action_tx dnsmasq enable_dnsmasq_cache_safely || true;
                _e52_pause
            ;;
            13)
                _e159_install_host_safe thp || error 'THP固化失败。';
                _e52_pause
            ;;
            14)
                warn '该项会事务重放完整127条网络请求，并非只修改PMTU。';
                read -rp '输入 APPLY-FULL-127 确认: ' confirm || true;
                test "$confirm" = APPLY-FULL-127 && _e159_network_apply fq 1 31 || true;
                _e52_pause
            ;;
            15)
                _e159_install_host_safe cpu || error 'CPU策略固化失败。';
