# EEX3-FUNCTION small_bbr_e189_205 _e204_patch_dat_pair
_e204_patch_dat_pair() {
    local tmp;
    test -x "$UPDATE_DAT_SCRIPT" || return 1;
    grep -q 'E204 atomic geoip/geosite pair v1' "$UPDATE_DAT_SCRIPT" 2> /dev/null && return 0;
    tmp=$(_e118_mktemp update-dat-e204.sh) || return 1;
    awk '
      /^rollback_dat\(\)[[:space:]]*\{/ && !download_gate {
        print "# E204 atomic geoip/geosite pair v1"
        print "if test \"$ok\" -ne 0 || test ! -s \"$TMP/geoip.dat\" || test ! -s \"$TMP/geosite.dat\"; then"
        print "    log \"WARN DAT资源未成对下载完成；本次不提交任何文件\""
        print "    exit 1"
        print "fi"
        download_gate=1
      }
      /^changed=0$/ {in_commit=1}
      in_commit && /^done$/ && !commit_gate {
        print
        print "if test \"$ok\" -ne 0; then"
        print "    log \"ERROR DAT成对提交失败，恢复两份旧资源\""
        print "    if ! rollback_dat; then log \"CRITICAL DAT成对回滚失败\"; fi"
        print "    exit 1"
        print "fi"
        commit_gate=1
        next
      }
      {print}
      END {if(!download_gate || !commit_gate) exit 42}
    ' "$UPDATE_DAT_SCRIPT" > "$tmp" || return 1;
    bash -n "$tmp" || return 1;
    E204_DAT_PATCHING=1 _e204_atomic_install_base "$tmp" "$UPDATE_DAT_SCRIPT" 0755
}
