    _eex3_retention_e204_prune_transactions "$@"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_reality_sid_self_test
_e204_reality_sid_self_test() {
    local uuid='7f109b8e-6a37-4fa8-a2c4-204204204204' a b sid_a sid_b;
    a='{"streamSettings":{"realitySettings":{"shortIds":["a1b2c3d4"]}}}';
    b='{"streamSettings":{"realitySettings":{"shortIds":["d4c3b2a1"]}}}';
