# EEX3-FUNCTION small_bbr_e189_205 _e204_remove_xray_env_buffer
_e204_remove_xray_env_buffer() {
    local f tmp mode owner changed=0;
    while IFS= read -r -d '' f; do
        grep -Fq 'XRAY_RAY_BUFFER_SIZE' "$f" 2> /dev/null || continue;
        if test -L "$f" || test ! -f "$f"; then
            error "Xray环境文件不是可安全改写的普通文件：$f";
            return 1;
        fi;
        owner=$(stat -c '%u' "$f" 2> /dev/null || echo -1);
        mode=$(stat -c '%a' "$f" 2> /dev/null || echo 777);
        test "$owner" = 0 && [[ "$mode" =~ ^[0-7]{3,4}$ ]] && test $((8#$mode & 0022)) -eq 0 || { 
            error "Xray环境文件所有者/权限不安全：$f";
            return 1
        };
        tmp=$(_e118_mktemp e204-xray-env-buffer) || return 1;
        awk 'index($0,"XRAY_RAY_BUFFER_SIZE")==0{print}' "$f" > "$tmp" || return 1;
        _e118_atomic_install "$tmp" "$f" "$mode" || return 1;
        ! grep -Fq 'XRAY_RAY_BUFFER_SIZE' "$f" || return 1;
        changed=1;
    done < <({ test ! -e /etc/systemd/system/xray.service || printf '%s\0' /etc/systemd/system/xray.service
test ! -d /etc/systemd/system/xray.service.d || find -P /etc/systemd/system/xray.service.d -maxdepth 2 \( -type f -o -type l \) -print0 2> /dev/null; });
    test "$changed" -eq 0 || systemctl daemon-reload > /dev/null 2>&1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_restore_managed_swap_runtime
_e204_restore_managed_swap_runtime() {
    local kind="${1:-none}";
    case "$kind" in 
        swapfile)
            test -e "$E204_SWAPFILE" || return 1;
            if ! swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
                swapon -p 10 "$E204_SWAPFILE" > /dev/null 2>&1 || return 1;
            fi
        ;;
        zram)
            if _e204_swap_owned zram /dev/zram0; then
                systemctl start "$E204_ZRAM_UNIT" > /dev/null 2>&1 || return 1;
                swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq /dev/zram0 || return 1;
            fi
        ;;
    esac
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_ring_action_base
_e204_ring_action_base() {
    local tx iface oldrx oldtx;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    oldrx=$(_ring_cur_rx_e52 "$iface" 2> /dev/null || true);
    oldtx=$(_ring_cur_tx_e52 "$iface" 2> /dev/null || true);
    tx=$(_e168_system_tx_begin ring) || return 1;
    if apply_ring_max_adaptive_default && _e168_ring_verify; then
        _e168_prune_system_tx "$tx";
        return 0;
    fi;
    _e168_system_tx_fail "$tx" 'Ring Buffer' || true;
    if [[ "$oldrx" =~ ^[0-9]+$ && "$oldtx" =~ ^[0-9]+$ ]]; then
        ethtool -G "$iface" rx "$oldrx" tx "$oldtx" > /dev/null 2>&1 || true;
    else
        if [[ "$oldrx" =~ ^[0-9]+$ ]]; then
            ethtool -G "$iface" rx "$oldrx" > /dev/null 2>&1 || true;
        fi;
    fi;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_rps_action_base
_e204_rps_action_base() {
    local tx rc=0 cpus;
    cpus=$(nproc 2> /dev/null || echo 1);
    if test "$cpus" -le 1; then
        info "单核CPU无需RPS/RFS；未写入持久化服务，也未报告伪成功。";
        return 0;
    fi;
    tx=$(_e168_system_tx_begin rps) || return 1;
    _e137_rps_snapshot_runtime "$tx/rps-runtime" || return 1;
    _e88_apply_rps_rfs || rc=1;
    test "$rc" -ne 0 || _e168_rps_verify || rc=1;
    if test "$rc" -eq 0; then
        { 
            echo "cpus=$cpus";
            echo "iface=$(_e137_default_iface)";
            echo "mask=$(_e137_cpu_mask "$cpus")"
        } > "${E88_RPS_STATE_FILE}.tmp.$$" && chmod 0600 "${E88_RPS_STATE_FILE}.tmp.$$" && mv -f -- "${E88_RPS_STATE_FILE}.tmp.$$" "$E88_RPS_STATE_FILE" || rc=1;
    fi;
    if test "$rc" -eq 0; then
        _e168_prune_system_tx "$tx";
        return 0;
    fi;
    _e168_system_tx_fail "$tx" RPS/RFS || true;
    _e137_rps_restore_runtime "$tx/rps-runtime" > /dev/null 2>&1 || true;
    return 1
}
