# EEX3-FUNCTION small_bbr_e189_205 _e204_service_candidate_ok
_e204_service_candidate_ok() {
    case "${1:-}" in 
        *@.service | *@.timer | *@.socket)
            return 1
        ;;
        xray*.service | xray*.timer | xray*.socket | ssh*.service | ssh*.timer | ssh*.socket | fail2ban.service | warp-svc.service | dnsmasq.service | systemd-resolved.service | resolvconf.service | nftables.service | firewalld.service | ufw.service | rsyslog.service | systemd-journald.service)
            return 0
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_service_candidates
_e204_service_candidates() {
    local path unit;
    printf '%s\n' xray.service fail2ban.service ssh.service sshd.service ssh.socket sshd.socket warp-svc.service dnsmasq.service systemd-resolved.service resolvconf.service nftables.service firewalld.service ufw.service rsyslog.service systemd-journald.service;
    while IFS= read -r path; do
        unit=${path##*/};
        _e204_service_candidate_ok "$unit" && printf '%s\n' "$unit";
    done < <(_e138_system_paths 2> /dev/null || true);
    if test -r "$SCRIPT_PATH"; then
        while IFS= read -r unit; do
            _e204_service_candidate_ok "$unit" && printf '%s\n' "$unit";
        done < <(LC_ALL=C grep -Eo '[A-Za-z0-9_.@-]+\.(service|timer|socket)' "$SCRIPT_PATH" 2> /dev/null | LC_ALL=C sort -u);
    fi;
    while IFS=' ' read -r unit _; do
        _e204_service_candidate_ok "$unit" && printf '%s\n' "$unit";
    done < <(systemctl list-unit-files 'xray*.service' 'xray*.timer' 'xray*.socket' --no-legend 2> /dev/null || true)
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_service_restore_line
_e204_service_restore_line() {
    _e266_service_state_apply "$@"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_service_restore_self_test
_e204_service_restore_self_test() {
    ( local enabled_state=disabled active_state=inactive load_state=loaded freeze_enabled=0 freeze_active=0;
    function systemctl () 
    { 
        local cmd="${1:-}";
        shift || true;
        case "$cmd" in 
            daemon-reload)
                return 0
            ;;
            unmask)
                load_state=loaded;
                enabled_state=disabled;
                return 0
            ;;
            mask)
                if test "${1:-}" = --runtime; then
                    enabled_state=masked-runtime;
                else
                    enabled_state=masked;
                fi;
                load_state=masked;
                return 0
            ;;
            enable)
                test "$freeze_enabled" -eq 1 && return 0;
                if test "${1:-}" = --runtime; then
                    enabled_state=enabled-runtime;
                else
                    enabled_state=enabled;
                fi;
                return 0
            ;;
            disable)
                test "$freeze_enabled" -eq 1 || enabled_state=disabled;
                return 0
            ;;
            start)
                active_state=active;
                return 0
            ;;
            stop)
                test "$freeze_active" -eq 1 || active_state=inactive;
                return 0
            ;;
            is-active)
                printf '%s\n' "$active_state";
                test "$active_state" = active
            ;;
            is-enabled)
                printf '%s\n' "$enabled_state";
                test "$enabled_state" != disabled
            ;;
            show)
                printf '%s\n' "$load_state";
                return 0
            ;;
            *)
                return 1
            ;;
        esac
    };
    _e204_service_restore_line demo.service loaded enabled active || return 1;
    test "$enabled_state:$active_state:$load_state" = enabled:active:loaded || return 1;
    _e204_service_restore_line demo.service masked masked-runtime inactive || return 1;
    test "$enabled_state:$active_state:$load_state" = masked-runtime:inactive:masked || return 1;
    load_state=loaded;
    enabled_state=disabled;
    active_state=inactive;
    freeze_enabled=1;
    ! _e204_service_restore_line demo.service loaded enabled inactive || return 1;
    freeze_enabled=0;
    freeze_active=1;
    load_state=loaded;
    enabled_state=disabled;
    active_state=failed;
    ! _e204_service_restore_line demo.service loaded disabled inactive || return 1;
    freeze_active=0;
    load_state=not-found;
    enabled_state=disabled;
    active_state=inactive;
    _e204_service_restore_line missing.service not-found disabled inactive )
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_service_snapshot
_e204_service_snapshot() {
    _eex8_snapshot_row "$1"
