# EEX3-FUNCTION small_bbr_e189_205 _e204_services_restore_file
_e204_services_restore_file() {
    local file="$1" unit load enabled active rc=0;
    test -s "$file" || return 0;
    systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    while IFS='|' read -r unit load enabled active; do
        test -n "$unit" || continue;
        _e204_service_restore_line "$unit" "$load" "$enabled" "$active" || rc=1;
    done < "$file";
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_small_bbr_status_base
_e204_small_bbr_status_base() {
    local active=no config=absent unit=disabled owner=absent profile_id=mode2;
    local pending=no saved_profile_state=absent key value actual duplicates;
    local malformed_current=no;
    local rc=0 assignments=14 target_file;
    _e202_small_bbr_active && active=yes;
    if test "$active" != yes && _e202_unrecognized_current_active; then
        malformed_current=yes;
        rc=1;
    fi;
    test -e "$E202_SMALL_CONF" && config=invalid;
    if _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF");
        config="exact-${assignments}-lines";
    fi;
    if test -e "$E202_SMALL_PROFILE"; then
        if _e202_small_bbr_validate_file "$E202_SMALL_PROFILE"; then
            saved_profile_state=valid;
            profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_PROFILE");
        else
            saved_profile_state=invalid;
            profile_id=invalid;
            pending=invalid;
            rc=1;
        fi;
    fi;
    if test "$active" = yes && test "$saved_profile_state" != invalid && _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
        cmp -s "$E202_SMALL_CONF" <(_e202_small_bbr_desired) || pending=yes;
    fi;
    _e202_full_network_owner_present && owner=CONFLICT;
    unit=$(systemctl is-enabled "$E202_SMALL_UNIT" 2> /dev/null || true);
    case "$unit" in 
        enabled | enabled-runtime | linked | linked-runtime | disabled | static | masked | indirect)

        ;;
        *)
            unit=unavailable
        ;;
    esac;
    target_file="$E202_SMALL_PROFILE";
    if test "$active" = yes && _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
        target_file="$E202_SMALL_CONF";
        profile_id=$(_e202_small_bbr_profile_id_file "$E202_SMALL_CONF");
        assignments=$(_e202_small_bbr_assignment_count "$E202_SMALL_CONF");
    else
        if test "$saved_profile_state" = invalid; then
            assignments=0;
            profile_id=invalid;
        else
            if ! _e202_small_bbr_validate_file "$target_file"; then
                assignments=14;
                profile_id=mode2;
            else
                assignments=$(_e202_small_bbr_assignment_count "$target_file");
            fi;
        fi;
    fi;
    title 'V199e266：小BBR八档状态（E202兼容稳定所有权）';
    echo "  状态: $active";
    echo "  持久配置: $config";
    echo "  目标/活动档位: $(_e202_small_bbr_profile_name "$profile_id") [$profile_id]";
    echo "  保存档文件状态: $saved_profile_state";
    echo "  保存值待应用: $pending";
    echo "  当前档位sysctl项: $assignments";
    echo '  隐藏sysctl项: 0';
    echo "  开机复检服务: $unit";
    echo "  脚本旧网络所有者: $owner";
    echo '  兼容提示: tcp_adv_win_scale自Linux 6.6起已废弃；仍按请求保存/读回，但新内核可能不再用它计算窗口。';
    echo;
    printf '  %-43s %-25s %-25s %s\n' 参数 目标值 运行值 其他文件定义;
    if test "$saved_profile_state" = invalid && test "$active" != yes; then
        warn '保存档无效；下表仅显示默认模式2参考值，不会静默覆盖或应用无效文件。';
    fi;
    while IFS='=' read -r key value; do
        key=$(_e159_norm "$key");
        value=$(_e159_norm "$value");
        actual=$(sysctl -n "$key" 2> /dev/null || echo unsupported);
        duplicates=$(_e202_small_bbr_duplicate_count "$key");
        printf '  %-43s %-25s %-25s %s\n' "$key" "$value" "$actual" "$duplicates";
        if test "$active" = yes && ! _e159_value_equal "$key" "$value" "$actual"; then
            rc=1;
        fi;
    done < <(if test "$active" = yes && _e202_small_bbr_validate_file "$E202_SMALL_CONF"; then
    cat -- "$E202_SMALL_CONF";
else
    _e202_small_bbr_desired;
fi);
    echo;
    echo '  说明：已清理脚本确认拥有的冲突层；未知/用户文件只报告，不擅自删除。';
    if test "$active" = yes; then
        case "$config" in 
            exact-14-lines | exact-25-lines | exact-26-lines)

            ;;
            *)
                rc=1
            ;;
        esac;
        test "$owner" = absent || rc=1;
        case "$unit" in 
            enabled | enabled-runtime | linked | linked-runtime)

            ;;
            *)
                rc=1
            ;;
        esac;
        _e202_snapshot_valid "$(sed -n 's/^restore_snapshot=//p' "$E202_SMALL_STATE" | tail -n1)" || rc=1;
        test "$(sed -n 's/^config_sha256=//p' "$E202_SMALL_STATE" | tail -n1)" = "$(sha256sum "$E202_SMALL_CONF" 2> /dev/null | awk '{print $1}')" || rc=1;
        test "$(sed -n 's/^persistent_assignments=//p' "$E202_SMALL_STATE" | tail -n1)" = "$assignments" || rc=1;
        test "$rc" -eq 0 && info "小BBR状态通过：$assignments 项全部一致，隐藏项=0。" || error '小BBR启用态存在漂移；可在菜单26选择修复。';
    else
        if test "$malformed_current" = yes; then
            error 'E202小BBR存在不可验证的状态/服务所有权；未将其误报为“未启用”。';
        else
            info '小BBR未启用；当前网络参数由现有系统/E159档位管理。';
        fi;
    fi;
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_snapshot_path_absent
_e204_snapshot_path_absent() {
    local tx="$1" path="$2" id;
    id=$(awk -F'|' -v p="$path" '$1==p{print $2;exit}' "$tx/paths.tsv" 2> /dev/null || true);
    test -n "$id" && test -e "$tx/files/$id.absent"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_ssh_access_preflight
_e204_ssh_access_preflight() {
    local ports p policy nft_policy zones zone listening current_port stale;
    ports=$(_e121_detect_ssh_ports 2> /dev/null || true);
    test -n "$ports" || { 
        error '卸载前无法识别SSH监听端口。';
        return 1
    };
    listening=$(_e266_detect_live_ssh_ports 2> /dev/null || true);
    current_port=$(_e135_current_ssh_port 2> /dev/null || true);
    stale=$(_e266_ssh_listener_assess "$ports" "$listening" "$current_port") || { 
        error '卸载前没有找到配置端口/当前会话端口与TCP监听的有效交集。';
        return 1
    };
    test -z "$stale" || warn "卸载前SSH配置含未监听端口：$stale；继续保留其放行规则，但不误判当前SSH故障。";
    if command -v ufw > /dev/null 2>&1 && ufw status 2> /dev/null | grep -qi '^Status: active'; then
        for p in $ports;
        do
            ufw allow "$p/tcp" > /dev/null || return 1;
        done;
        return 0;
    fi;
    if command -v firewall-cmd > /dev/null 2>&1 && systemctl is-active --quiet firewalld.service; then
        zones=$(firewall-cmd --get-active-zones 2> /dev/null | awk 'NF && $1!="interfaces:" && $1!="sources:"{print $1}' | sort -u);
        test -n "$zones" || zones=$(firewall-cmd --get-default-zone 2> /dev/null || true);
        test -n "$zones" || { 
            error 'firewalld活动/default zone无法识别。';
            return 1
        };
        for zone in $zones;
        do
            for p in $ports;
            do
                firewall-cmd --permanent --zone="$zone" --add-port="${p}/tcp" > /dev/null || return 1;
            done;
        done;
        firewall-cmd --reload > /dev/null || return 1;
        for zone in $zones;
        do
            for p in $ports;
            do
                firewall-cmd --zone="$zone" --query-port="${p}/tcp" > /dev/null || return 1;
            done;
        done;
        return 0;
    fi;
    if command -v iptables > /dev/null 2>&1 && iptables -S INPUT > /dev/null 2>&1; then
        policy=$(iptables -S INPUT 2> /dev/null | awk '$1=="-P"&&$2=="INPUT"{print $3;exit}');
        test "$policy" != DROP && test "$policy" != REJECT && return 0;
        command -v netfilter-persistent > /dev/null 2>&1 || { 
            error 'INPUT默认策略为DROP且没有可验证的持久防火墙管理器；拒绝卸载SSH守护层。';
            return 1
        };
        for p in $ports;
        do
            iptables -C INPUT -p tcp --dport "$p" -j ACCEPT > /dev/null 2>&1 || iptables -I INPUT 1 -p tcp --dport "$p" -j ACCEPT || return 1;
        done;
        netfilter-persistent save > /dev/null || return 1;
        return 0;
    fi;
    if command -v nft > /dev/null 2>&1 && nft list ruleset > /dev/null 2>&1; then
        nft_policy=$(nft -nn list ruleset 2> /dev/null | awk '
          /hook input/ {seen=1}
          seen && /policy (accept|drop|reject)/ {
            for(i=1;i<=NF;i++)if($i=="policy"){gsub(/;/,"",$(i+1));print $(i+1);exit}
          }');
        test -z "$nft_policy" || test "$nft_policy" = accept || { 
            error '原生nftables INPUT策略不是accept且无法证明有持久SSH放行；拒绝卸载SSH守护层。';
            return 1
        };
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_ssh_guard_install_base
_e204_ssh_guard_install_base() {
    local tx backend before_count=${#E135_NEW_PACKAGES[@]} rc=0;
    tx=$(_e182_new_tx ssh-guard-dispatch) || return 1;
    _e140_system_snapshot "$tx" || return 1;
    install -d -m 0700 "$E141_DIR" || rc=1;
    if test "$rc" -eq 0 && test "${E182_BACKEND_PREFLIGHT_VERIFIED:-0}" != 1; then
        _e182_ensure_firewall_backend || rc=1;
    fi;
    E182_BACKEND_PREFLIGHT_VERIFIED=0;
    backend=$(_e152_firewall_backend 2> /dev/null || echo none);
    if test "$rc" -eq 0; then
        case "$backend" in 
            sshd-native)
                _e182_install_native_guard "$tx" || rc=1
            ;;
            *)
                _e182_enable_managed_f2b_jail_firewall || rc=1;
                test "$rc" -ne 0 || _e182_install_ssh_guard_firewall_base "$@" || rc=1
            ;;
        esac;
    fi;
    if test "$rc" -ne 0; then
        _e140_system_restore "$tx" > /dev/null 2>&1 || true;
        _e182_sshd_reload_safe > /dev/null 2>&1 || true;
        _e172_remove_packages_since "$before_count";
        E182_BACKEND_OVERRIDE="";
        E182_BACKEND_PREFLIGHT_VERIFIED=0;
        return 1;
    fi;
    E182_BACKEND_PREFLIGHT_VERIFIED=0;
    return 0
}
