# EEX3-FUNCTION small_bbr_e189_205 _e204_ssh_port_listening
_e204_ssh_port_listening() {
    local p="$1" suffix;
    [[ "$p" =~ ^[0-9]+$ ]] && test "$p" -ge 1 && test "$p" -le 65535 || return 1;
    suffix=":$p";
    ss -H -lnt 2> /dev/null | awk -v s="$suffix" '
      {a=$4; if(length(a)>=length(s) && substr(a,length(a)-length(s)+1)==s){found=1; exit}}
      END{exit !found}'
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_structure_audit
_e204_structure_audit() {
    local rc=0 size lines dispatchers menu micro kernel hot uninstall network node warp dat;
    local snapshot services service_list paths ssh sshguard dns tc tc_menu prune cleanup summary metadata;
    local warp_enable warp_base warp_full warp_full_commit warp_disable warp_reconcile;
