    warp_full_commit=$(declare -f _e159_warp_full_enable_base 2> /dev/null || true);
    warp_disable=$(declare -f _e185_warp_disable 2> /dev/null || true);
    warp_reconcile=$(declare -f _e185_warp_reconcile 2> /dev/null || true);
    dat=$(declare -f _e204_patch_dat_pair 2> /dev/null || true);
