    grep -q '_e140_system_snapshot' <<< "$advanced_tx" || rc=1;
    grep -q '_e140_system_restore' <<< "$advanced_tx" || rc=1;
    grep -q '_e204_mark_critical' <<< "$advanced_tx" || rc=1;
    for id in _e159_xray_action_tx _e168_apply_init30_tx _e168_offload_action _e168_rps_action _e168_mss_action _e168_txq_action _e168_ring_action _e168_disable_legacy_tx _e159_apply_micro_28;
    do
