    restore_line=$(grep -n '_e135_restore_file' <<< "$dns" | head -n1 | cut -d: -f1);
    [[ "$purge_line" =~ ^[0-9]+$ && "$restore_line" =~ ^[0-9]+$ ]] && test "$purge_line" -lt "$restore_line" || rc=1;
    d=$(mktemp -d /tmp/xray-e204-profile-audit.XXXXXX) || return 1;
    conf="$d/profile.conf";
    for id in mode1 mode2 mode3 mode1f mode2f mode3f mode3f2 modeb1;
    do
        "_e202_small_bbr_${id}" > "$conf" || rc=1;
        _e202_small_bbr_validate_file "$conf" || rc=1;
        count=$(_e202_small_bbr_assignment_count "$conf");
        case "$id" in 
            mode1 | mode2 | mode3)
                test "$count" -eq 14 || rc=1
            ;;
            mode3f2)
                test "$count" -eq 26 || rc=1
            ;;
            *)
                test "$count" -eq 25 || rc=1
            ;;
        esac;
        grep -Fqx 'net.ipv4.tcp_adv_win_scale = 1' "$conf" || rc=1;
        ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' "$conf" || rc=1;
        case "$id" in 
            mode1f | mode2f | mode3f | mode3f2 | modeb1)
                grep -Fqx 'net.ipv4.tcp_max_reordering = 300' "$conf" || rc=1;
                grep -Fqx 'net.ipv4.tcp_tw_reuse = 2' "$conf" || rc=1;
                grep -Fqx 'net.ipv4.tcp_recovery = 1' "$conf" || rc=1
            ;;
        esac;
    done;
    rm -rf -- "$d";
    if test "$rc" -eq 0; then
        echo '  result=PASS';
    else
        echo '  result=FAIL';
    fi;
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_swap_owned
_e204_swap_owned() {
    local want_kind="$1" want_device="$2" kind device;
    grep -qx 'owned_by=e204' "$E204_ZRAM_STATE" 2> /dev/null || return 1;
    kind=$(_e204_swap_state_value kind '');
    device=$(_e204_swap_state_value device '');
    if test -z "$kind"; then
        test "$device" = /dev/zram0 || return 1;
        kind=zram;
    fi;
    test "$kind" = "$want_kind" && test "$device" = "$want_device"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_swap_state_value
_e204_swap_state_value() {
    local key="$1" default="${2:-}" value;
    value=$(awk -F= -v k="$key" '$1==k{print substr($0,index($0,"=")+1);exit}' "$E204_ZRAM_STATE" 2> /dev/null || true);
    printf '%s\n' "${value:-$default}"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_swap_state_write
_e204_swap_state_write() {
    local kind="$1" device="$2" tmp;
    case "$kind:$device" in 
        zram:/dev/zram0 | swapfile:"$E204_SWAPFILE")

        ;;
        *)
            return 1
        ;;
    esac;
    tmp=$(_e118_mktemp e204-swap-owner) || return 1;
    { 
        echo 'owned_by=e204';
        echo "kind=$kind";
        echo "device=$device";
        echo "created_at=$(date -Is 2> /dev/null || date)"
    } > "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$E204_ZRAM_STATE" 0600
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_swapfile_activate
_e204_swapfile_activate() {
    local free_mb tmpfstab tmpfile created=0 active=0;
    swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE" && active=1 || true;
    if test "$active" -eq 1 && ! _e204_swap_owned swapfile "$E204_SWAPFILE" && ! _e204_legacy_swapfile_owned; then
        error "检测到活动的$E204_SWAPFILE，但没有E204所有权证据；拒绝接管。";
        return 1;
    fi;
    if swapon --show=NAME --noheadings 2> /dev/null | grep -q .; then
        if test "$active" -ne 1; then
            warn '检测到现有Swap；E204不会关闭或替换用户Swap。';
            return 0;
        fi;
    fi;
    if test -e "$E204_SWAPFILE" && test "$active" -ne 1 && ! _e204_swap_owned swapfile "$E204_SWAPFILE" && ! _e204_legacy_swapfile_owned; then
        error "发现同名但不属于E204的文件，拒绝覆盖：$E204_SWAPFILE";
        return 1;
    fi;
    if test ! -e "$E204_SWAPFILE"; then
        free_mb=$(df -Pm / 2> /dev/null | awk 'NR==2{print int($4)}');
        [[ "$free_mb" =~ ^[0-9]+$ ]] && test "$free_mb" -ge 1300 || { 
            error '空间不足，未创建1GiB swapfile。';
            return 1
        };
        tmpfile="${E204_SWAPFILE}.new.$$";
        test ! -e "$tmpfile" || { 
            error "临时Swap文件已存在：$tmpfile";
            return 1
        };
        if command -v fallocate > /dev/null 2>&1; then
            fallocate -l 1024M "$tmpfile" || { 
                rm -f -- "$tmpfile";
                return 1
            };
        else
            dd if=/dev/zero of="$tmpfile" bs=1M count=1024 status=none || { 
                rm -f -- "$tmpfile";
                return 1
            };
        fi;
        chmod 0600 "$tmpfile" || { 
            rm -f -- "$tmpfile";
            return 1
        };
        mkswap "$tmpfile" > /dev/null 2>&1 || { 
            rm -f -- "$tmpfile";
            return 1
        };
        mv -f -- "$tmpfile" "$E204_SWAPFILE" || { 
            rm -f -- "$tmpfile";
            return 1
        };
        created=1;
    else
        test -f "$E204_SWAPFILE" && test ! -L "$E204_SWAPFILE" && test "$(stat -c '%u:%a' "$E204_SWAPFILE" 2> /dev/null || true)" = 0:600 || { 
            error 'E204 Swap文件属性不安全。';
            return 1
        };
    fi;
    if test "$active" -ne 1; then
        swapon -p 10 "$E204_SWAPFILE" > /dev/null 2>&1 || { 
            test "$created" -eq 0 || rm -f -- "$E204_SWAPFILE";
            return 1
        };
    fi;
    swapon --show=NAME --noheadings | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE" || { 
        test "$created" -eq 0 || rm -f -- "$E204_SWAPFILE";
        return 1
    };
    tmpfstab=$(_e118_mktemp e204-fstab) || return 1;
    awk -v p="$E204_SWAPFILE" '$1!=p{print}' /etc/fstab > "$tmpfstab" || return 1;
    printf '%s none swap sw,nofail 0 0\n' "$E204_SWAPFILE" >> "$tmpfstab";
    _e118_atomic_install "$tmpfstab" /etc/fstab 0644 || return 1;
    _e204_swap_state_write swapfile "$E204_SWAPFILE"
}
