# EEX3-FUNCTION small_bbr_e189_205 _e204_tc_readonly_status
_e204_tc_readonly_status() {
    local iface line;
    iface=$(_e95_default_iface 2> /dev/null || true);
    line=$(_e95_root_qdisc_line "$iface");
    echo "  默认出口网卡: ${iface:-未知}";
    echo "  当前 root qdisc: ${line:-未读取}";
    echo "  E95组件: 未安装或完整性/权限未通过";
    if test -n "$iface" && command -v tc > /dev/null 2>&1; then
        tc -s qdisc show dev "$iface" 2> /dev/null || true;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_tc_tx_begin_base
_e204_tc_tx_begin_base() {
    local name="${1:-tc}" tx p id svc;
    tx=$(_e168_new_tx "tc-$name") || return 1;
    install -d -m 0700 "$tx/files" || return 1;
    for p in "$E95_TC_CONF" "$E95_TC_SCRIPT" "$E95_TC_SERVICE";
    do
        id=$(printf '%s' "$p" | sha256sum | awk '{print $1}');
        printf '%s|%s\n' "$p" "$id" >> "$tx/paths.tsv" || return 1;
        _e135_snapshot_file "$p" "$tx/files/$id" || return 1;
    done;
    : > "$tx/services.tsv" || return 1;
    for svc in xray-tc-limit-e93.service xray-tc-limit-e94.service xray-tc-limit-e95.service;
    do
        printf '%s|%s|%s\n' "$svc" "$(systemctl is-enabled "$svc" 2> /dev/null || true)" "$(systemctl is-active "$svc" 2> /dev/null || true)" >> "$tx/services.tsv" || return 1;
    done;
    ( cd "$tx" && find files paths.tsv services.tsv -type f -print0 | sort -z | xargs -0 sha256sum > seal.sha256 ) || return 1;
    printf '%s\n' "$tx"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_tx_close
_e204_tx_close() {
    local tx="${1:-}" root real;
    test -n "$tx" || return 0;
    root=$(readlink -f -- "$E204_TX_ROOT" 2> /dev/null || true);
    real=$(readlink -f -- "$tx" 2> /dev/null || true);
    test -n "$root" && test -n "$real" || return 1;
    case "$real" in 
        "$root"/*)
            rm -f -- "$real/.active.env"
        ;;
        *)
            error "拒绝关闭E204事务根目录外的标记：$tx";
            return 1
        ;;
    esac
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_txq_action_base
_e204_txq_action_base() {
    local tx iface old;
    iface=$(_e137_default_iface);
    test -n "$iface" || return 1;
    old=$(ip -o link show dev "$iface" | sed -n 's/.* qlen \([0-9]\+\).*/\1/p');
    tx=$(_e168_system_tx_begin txqueue) || return 1;
    if _e88_manual_txqueue && _e168_txq_verify; then
        _e168_prune_system_tx "$tx";
        return 0;
    fi;
    _e168_system_tx_fail "$tx" 'TX Queue' || true;
    test -z "$old" || ip link set dev "$iface" txqueuelen "$old" > /dev/null 2>&1 || true;
    return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_uninstall_managed_swap
_e204_uninstall_managed_swap() {
    local tmp;
    E204_UNINSTALL_SWAP_KIND=none;
    if _e204_swap_owned zram /dev/zram0; then
        E204_UNINSTALL_SWAP_KIND=zram;
        systemctl disable --now "$E204_ZRAM_UNIT" > /dev/null 2>&1 || true;
        if swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq /dev/zram0; then
            swapoff /dev/zram0 || return 1;
            command -v zramctl > /dev/null 2>&1 && zramctl --reset /dev/zram0 > /dev/null 2>&1 || true;
        fi;
        return 0;
    fi;
    if _e204_swap_owned swapfile "$E204_SWAPFILE" || _e204_legacy_swapfile_owned; then
        E204_UNINSTALL_SWAP_KIND=swapfile;
        if swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
            swapoff "$E204_SWAPFILE" || return 1;
        fi;
        tmp=$(_e118_mktemp e204-uninstall-fstab) || return 1;
        awk -v p="$E204_SWAPFILE" '$1!=p{print}' /etc/fstab > "$tmp" || return 1;
        _e118_atomic_install "$tmp" /etc/fstab 0644 || return 1;
        return 0;
    fi;
    if test -e "$E204_SWAPFILE" || swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq "$E204_SWAPFILE"; then
        warn "保留没有E204所有权证据的同名Swap：$E204_SWAPFILE";
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_uninstall_owned_units
_e204_uninstall_owned_units() {
    local p unit;
    while IFS= read -r p; do
        case "$p" in 
            /etc/systemd/system/xray*.service | /etc/systemd/system/xray*.timer)
                unit=$(basename -- "$p");
                test "$unit" = xray.service && continue;
                printf '%s\n' "$unit"
            ;;
        esac;
    done < <(_e138_system_paths | sort -u);
    for unit in nic-optimize.service rps-optimize.service txqueue.service;
    do
        _e204_legacy_optimizer_owned "$unit" && printf '%s\n' "$unit" || true;
    done
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_uninstall_remove_owned_files
_e204_uninstall_remove_owned_files() {
    local p unit rc=0;
    while IFS= read -r p; do
        case "$p" in 
            /etc/systemd/system/xray*.service | /etc/systemd/system/xray*.timer | /etc/systemd/system/xray.service.d | /usr/local/bin/xray-*.sh | /usr/local/libexec/xray-* | /etc/fail2ban/*/*xray* | /etc/rsyslog.d/*xray* | /etc/logrotate.d/xray* | /etc/systemd/journald.conf.d/*xray* | /etc/sysctl.d/*xray* | /etc/modules-load.d/xray* | /etc/ssh/sshd_config.d/*xray*)
                rm -rf -- "$p" || rc=1
            ;;
        esac;
    done < <(_e138_system_paths | sort -u);
    for unit in nic-optimize.service rps-optimize.service txqueue.service;
    do
        if _e204_legacy_optimizer_owned "$unit"; then
            case "$unit" in 
                nic-optimize.service)
                    rm -f -- /etc/systemd/system/nic-optimize.service /usr/local/bin/nic-optimize.sh || rc=1
                ;;
                rps-optimize.service)
                    rm -f -- /etc/systemd/system/rps-optimize.service /usr/local/bin/rps-optimize.sh || rc=1
                ;;
                txqueue.service)
                    rm -f -- /etc/systemd/system/txqueue.service /usr/local/bin/txqueue.sh || rc=1
                ;;
            esac;
        else
            if test -e "/etc/systemd/system/$unit"; then
                warn "保留无法证明由本脚本创建的同名服务：/etc/systemd/system/$unit";
            fi;
        fi;
    done;
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_uninstall_stop_owned_units
_e204_uninstall_stop_owned_units() {
    local unit;
    while IFS= read -r unit; do
        test -n "$unit" || continue;
        systemctl stop "$unit" > /dev/null 2>&1 || true;
        systemctl disable "$unit" > /dev/null 2>&1 || true;
    done < <(_e204_uninstall_owned_units | sort -u)
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_verify_patch_hit_base
_e204_verify_patch_hit_base() {
    local src="$1" conf="$2" kind="$3";
    source "$conf";
    if test "$kind" = "bbr3"; then
        grep -Eq "bbr_cwnd_gain[[:space:]]*=[[:space:]]*BBR_UNIT[[:space:]]*\*[[:space:]]*${BBR_CWND_GAIN}[[:space:]]*/[[:space:]]*100" "$src" || return 1;
        grep -Eq "bbr_loss_thresh[[:space:]]*=[[:space:]]*BBR_UNIT[[:space:]]*\*[[:space:]]*${BBR_LOSS_THRESH_PERMILLE}[[:space:]]*/[[:space:]]*1000" "$src" || return 1;
        grep -Eq "bbr_inflight_headroom[[:space:]]*=[[:space:]]*BBR_UNIT[[:space:]]*\*[[:space:]]*${BBR_INFLIGHT_HEADROOM}[[:space:]]*/[[:space:]]*100" "$src" || return 1;
    else
        grep -Eq "bbr_high_gain[[:space:]]*=[[:space:]]*BBR_UNIT[[:space:]]*\*[[:space:]]*${BBR_HIGH_GAIN}[[:space:]]*/[[:space:]]*100" "$src" || return 1;
        grep -Eq "bbr_cwnd_gain[[:space:]]*=[[:space:]]*BBR_UNIT[[:space:]]*\*[[:space:]]*${BBR_CWND_GAIN}[[:space:]]*/[[:space:]]*100" "$src" || return 1;
        grep -Eq "BBR_UNIT[[:space:]]*\*[[:space:]]*${BBR_PACING_GAIN_0}[[:space:]]*/[[:space:]]*100" "$src" || return 1;
    fi;
    return 0
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_warp_disable_base
_e204_warp_disable_base() {
    _e138_xray_apply_warp disabled disabled false disabled disabled disabled || return 1;
    systemctl disable --now xray-warp-e138-health.timer > /dev/null 2>&1 || true;
    _e183_warp_cli_capture disconnect > /dev/null 2>&1 || true;
    info 'Xray WARP选择/全局分流已关闭；Cloudflare客户端和wgcf凭据保留。'
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_warp_enable_base
_e204_warp_enable_base() {
    local mode="$1" profile="$2" family="${3:-ipv4}" backend_request="${4:-auto}";
    local token tx route_before ip_before preinstalled=0 failed=0 backend="" reason="" package_attempted=0;
    family=$(_e185_family_normalize "$family") || { 
        error "未知WARP地址族：$family";
        return 1
    };
    backend_request=$(_e185_backend_normalize "$backend_request") || return 1;
    title "V199e186：启用WARP $mode 分流（family=$family backend=$backend_request）";
    if test "$mode" = global; then
        warn '全局仅指Xray层；VPS默认路由、SSH、APT和宿主机流量不进入WARP。';
        warn "未被已有明确规则命中的TCP经WARP；同范围UDP阻断。目标地址族=$family。目标族不等于WARP隧道下层地址族。";
        read -rp '输入 ENABLE-WARP-GLOBAL 确认: ' token || true;
        test "$token" = ENABLE-WARP-GLOBAL || return 0;
    else
        warn "仅指定Google/Meta域名TCP走WARP；相关UDP阻断；目标地址族=$family。";
        read -rp '输入 ENABLE-WARP 确认: ' token || true;
        test "$token" = ENABLE-WARP || return 0;
    fi;
    _e138_prepare || return 1;
    tx=$(_e138_new_tx warp-enable-e185) || return 1;
    _e135_snapshot_file "$CONFIG" "$tx/config" || return 1;
    _e135_snapshot_file "$E138_WARP_STATE" "$tx/state" || return 1;
    _e135_snapshot_file "$E138_WARP_HEALTH_SERVICE" "$tx/service" || return 1;
    _e135_snapshot_file "$E138_WARP_HEALTH_TIMER" "$tx/timer" || return 1;
    _e135_snapshot_file "$E185_WG_ENDPOINT_STATE" "$tx/wg-endpoint" || return 1;
    dpkg-query -W -f='${Status}' cloudflare-warp 2> /dev/null | grep -q 'install ok installed' && preinstalled=1 || true;
    route_before=$(_e136_warp_route4);
    ip_before=$(_e136_direct_ipv4 2> /dev/null || true);
    test -n "$route_before" || return 1;
    case "$backend_request" in 
        masque)
            package_attempted=1;
            _e136_warp_install_package "$tx" || failed=1;
            test "$failed" -ne 0 || _e183_warp_connect_local_proxy || failed=1;
            test "$failed" -ne 0 || backend=masque
        ;;
        xray-wg)
            _e185_confirm_wgcf_fallback || return 0;
            _e185_wg_prepare "$family" || failed=1;
            if test "$failed" -eq 0; then
                family="$E185_WG_EFFECTIVE_FAMILY";
                backend=xray-wg;
            fi
        ;;
        auto)
            if _e185_recent_masque_blocked "$E183_WARP_DIAG"; then
                reason=masque-ingress-udp-timeout;
                warn '检测到6小时内已确认的MASQUE IPv4入口UDP全端口超时；本次不再重复等待75秒。';
                _e185_capture_backend_diag "$reason" masque "$family";
            else
                package_attempted=1;
                if _e136_warp_install_package "$tx" && _e183_warp_connect_local_proxy; then
                    backend=masque;
                else
                    reason=$(_e185_masque_failure_reason);
                    _e185_capture_backend_diag "$reason" masque "$family";
                    warn "官方MASQUE Local proxy失败：$reason。";
                    _e183_warp_cli_capture disconnect > /dev/null 2>&1 || true;
                fi;
            fi;
            if test -z "$backend"; then
                if _e185_confirm_wgcf_fallback && _e185_wg_prepare "$family"; then
                    family="$E185_WG_EFFECTIVE_FAMILY";
                    backend=xray-wg;
                    failed=0;
                else
                    failed=1;
                fi;
            fi
        ;;
        *)
            failed=1
        ;;
    esac;
    test "$failed" -ne 0 || _e138_xray_apply_warp "$mode" "$profile" true "$family" "$backend" "$backend_request" || failed=1;
    test "$failed" -ne 0 || _e138_warp_health_install || failed=1;
    test "$failed" -ne 0 || test "$route_before" = "$(_e136_warp_route4)" || failed=1;
    if test -n "$ip_before" && test "$failed" -eq 0; then
        test "$ip_before" = "$(_e136_direct_ipv4 2> /dev/null || true)" || failed=1;
    fi;
    if test "$failed" -eq 0 && test "$backend" = xray-wg; then
        _e183_warp_cli_capture disconnect > /dev/null 2>&1 || true;
        systemctl disable --now "$(_e136_warp_service_name)" > /dev/null 2>&1 || true;
        if test "$preinstalled" -eq 0 && test "$package_attempted" -eq 1 && test -s "$tx/package.env"; then
            _e136_warp_install_rollback "$tx" > /dev/null 2>&1 || true;
        fi;
    fi;
    if test "$failed" -ne 0; then
        error 'E186 WARP启用失败，执行完整回滚。';
        _e135_restore_file "$CONFIG" "$tx/config" || true;
        _e135_restore_file "$E138_WARP_STATE" "$tx/state" || true;
        _e135_restore_file "$E138_WARP_HEALTH_SERVICE" "$tx/service" || true;
        _e135_restore_file "$E138_WARP_HEALTH_TIMER" "$tx/timer" || true;
        _e135_restore_file "$E185_WG_ENDPOINT_STATE" "$tx/wg-endpoint" || true;
        systemctl daemon-reload > /dev/null 2>&1 || true;
        systemctl restart xray.service > /dev/null 2>&1 || true;
        if test "$preinstalled" -eq 0 && test "$package_attempted" -eq 1 && test -s "$tx/package.env"; then
            _e136_warp_install_rollback "$tx" || true;
        fi;
        _e183_warp_cli_capture disconnect > /dev/null 2>&1 || true;
        _e185_capture_backend_diag "${reason:-enable-failed}" "${backend:-$backend_request}" "$family";
        return 1;
    fi;
    _e185_warp_status
}
