# EEX3-FUNCTION small_bbr_e189_205 _e204_warp_package_restore
_e204_warp_package_restore() {
    local before="$1" pkg was rc=0 dir base;
    local -a added=();
    test -s "$before" || return 1;
    test -s "$before.sha256" || return 1;
    dir=$(dirname -- "$before") || return 1;
    base=$(basename -- "$before") || return 1;
    ( cd "$dir" && sha256sum -c "$base.sha256" > /dev/null 2>&1 ) || return 1;
    while IFS='|' read -r pkg was; do
        case "$pkg" in 
            ca-certificates | curl | gnupg | lsb-release | cloudflare-warp)

            ;;
            *)
                return 1
            ;;
        esac;
        test "$was" = 0 || continue;
        dpkg-query -W -f='${Status}' "$pkg" 2> /dev/null | grep -q 'install ok installed' && added=("$pkg" "${added[@]}") || true;
    done < "$before";
    test "${#added[@]}" -eq 0 || DEBIAN_FRONTEND=noninteractive apt-get purge -y "${added[@]}" > /dev/null 2>&1 || rc=1;
    return "$rc"
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_warp_package_snapshot
_e204_warp_package_snapshot() {
    local out="$1" pkg dir base;
    : > "$out" || return 1;
    for pkg in ca-certificates curl gnupg lsb-release cloudflare-warp;
    do
        if command -v dpkg-query > /dev/null 2>&1 && dpkg-query -W -f='${Status}' "$pkg" 2> /dev/null | grep -q 'install ok installed'; then
            printf '%s|1\n' "$pkg" >> "$out" || return 1;
        else
            printf '%s|0\n' "$pkg" >> "$out" || return 1;
        fi;
    done;
    chmod 0600 "$out" || return 1;
    dir=$(dirname -- "$out") || return 1;
    base=$(basename -- "$out") || return 1;
    ( cd "$dir" && sha256sum -- "$base" > "$base.sha256" ) || return 1;
    chmod 0600 "$out.sha256" || return 1
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_warp_reconcile_base
_e204_warp_reconcile_base() {
    local enabled mode profile family backend request;
    _e138_warp_migrate_state || return 1;
    enabled=$(_e138_state_get route_enabled 0);
    mode=$(_e138_state_get route_mode disabled);
    profile=$(_e138_state_get profile disabled);
    family=$(_e138_state_get family ipv4);
    backend=$(_e138_state_get backend auto);
    request=$(_e138_state_get backend_request "$backend");
    test "$enabled" = 1 || { 
        _e138_warp_config_integrity disabled disabled disabled disabled || _e138_xray_apply_warp disabled disabled false disabled disabled disabled;
        return $?
    };
    test "$mode" != host-full || { 
        _e140_warp_full_reconcile;
        return $?
    };
    case "$backend" in 
        masque)
            _e136_warp_install_package "$(_e138_new_tx reconcile-package)" || return 1;
            _e183_warp_connect_local_proxy || return 1
        ;;
        xray-wg)
            _e185_wg_profile_valid || { 
                error 'WARP WireGuard配置缺失，需手工重新启用。';
                return 1
            };
            test -n "$(_e185_state_endpoint)" || { 
                error 'WARP WireGuard endpoint缺失，需手工重新启用。';
                return 1
            }
        ;;
        auto | *)
            error 'WARP状态尚未确定实际后端，请重新执行启用流程。';
            return 1
        ;;
    esac;
    _e138_warp_config_integrity "$mode" "$profile" "$family" "$backend" || _e138_xray_apply_warp "$mode" "$profile" true "$family" "$backend" "$request" || return 1;
    _e138_warp_health_install
}
