# EEX3-FUNCTION small_bbr_e189_205 _e204_xray_action_tx_base
_e204_xray_action_tx_base() {
    local name="$1" protect was_active=0;
    shift;
    test -s "$CONFIG" || { 
        error "config.json不存在。";
        return 1
    };
    protect=$(_e116_backup_state "before_${name}_e159") || return 1;
    _e118_save_core_payload "$protect" || return 1;
    was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
    was_active=${was_active:-0};
    if ! "$@"; then
        error "$name 执行失败，恢复Xray配置、Core、systemd drop-in与原启停状态。";
        _e159_xray_action_rollback "$protect" || true;
        return 1;
    fi;
    _e118_xray_test_config "$CONFIG" 1 || { 
        _e159_xray_action_rollback "$protect" || true;
        return 1
    };
    systemctl daemon-reload > /dev/null 2>&1 || { 
        _e159_xray_action_rollback "$protect" || true;
        return 1
    };
    if test "$was_active" = 1; then
        if ! systemctl restart xray.service > /dev/null 2>&1 || ! _e127_verify_xray_runtime "$CONFIG" 12; then
            error "$name 后Xray运行探针失败，自动回滚。";
            _e159_xray_action_rollback "$protect" || true;
            return 1;
        fi;
    else
        systemctl stop xray.service > /dev/null 2>&1 || true;
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            error "$name 意外启动了原本停止的Xray，自动回滚。";
            _e159_xray_action_rollback "$protect" || true;
            return 1;
        fi;
    fi;
    info "$name 已通过配置测试、启停状态保持与运行探针。"
}
