_e204_xray_runtime_readback() {
    test -s "$CONFIG" || return 0;
    _e118_xray_test_config "$CONFIG" 1 || return 1;
    if systemctl is-active --quiet xray.service 2> /dev/null; then
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1;
    fi
}
# EEX3-FUNCTION small_bbr_e189_205 _e204_zram_activate
_e204_zram_activate() {
    local script_tmp unit_tmp state_tmp disksize=0;
    if swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -E '^/dev/zram' | grep -Fvx /dev/zram0 | grep -q .; then
        error '检测到非E204的活动ZRAM设备；拒绝重置用户ZRAM。';
        return 1;
    fi;
    if swapon --show=NAME --noheadings 2> /dev/null | awk '{$1=$1}1' | grep -Fxq /dev/zram0 && ! _e204_swap_owned zram /dev/zram0; then
        warn '检测到用户已有/dev/zram0；E204不接管、不覆盖，也不写入伪所有权。';
        return 0;
    fi;
    if test -r /sys/block/zram0/disksize && ! _e204_swap_owned zram /dev/zram0; then
        disksize=$(cat /sys/block/zram0/disksize 2> /dev/null || echo 0);
        [[ "$disksize" =~ ^[0-9]+$ ]] || disksize=0;
        if test "$disksize" -gt 0; then
            warn '检测到未激活但已配置的用户/dev/zram0；E204不重置该设备。';
            return 0;
        fi;
    fi;
    script_tmp=$(_e118_mktemp e204-zram.sh) || return 1;
    unit_tmp=$(_e118_mktemp e204-zram.service) || return 1;
    cat > "$script_tmp" <<'EOF_E204_ZRAM_SCRIPT'
#!/usr/bin/env bash
set -euo pipefail
modprobe zram num_devices=1
if swapon --show=NAME --noheadings | awk '{$1=$1}1' | grep -Fxq /dev/zram0; then exit 0; fi
test -e /sys/block/zram0/disksize
echo lz4 > /sys/block/zram0/comp_algorithm 2>/dev/null || true
echo 1024M > /sys/block/zram0/disksize
mkswap /dev/zram0 >/dev/null
swapon -p 100 /dev/zram0
swapon --show=NAME --noheadings | awk '{$1=$1}1' | grep -Fxq /dev/zram0
EOF_E204_ZRAM_SCRIPT

    cat > "$unit_tmp" <<EOF_E204_ZRAM_UNIT
[Unit]
Description=Xray E204 non-destructive 1GiB ZRAM
After=local-fs.target
[Service]
Type=oneshot
ExecStart=$E204_ZRAM_SCRIPT
RemainAfterExit=yes
[Install]
WantedBy=multi-user.target
EOF_E204_ZRAM_UNIT

    bash -n "$script_tmp" || return 1;
    _e118_atomic_install "$script_tmp" "$E204_ZRAM_SCRIPT" 0755 || return 1;
    _e118_atomic_install "$unit_tmp" "$E204_ZRAM_SERVICE" 0644 || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl enable --now "$E204_ZRAM_UNIT" > /dev/null 2>&1 || return 1;
    swapon --show=NAME --noheadings | awk '{$1=$1}1' | grep -Fxq /dev/zram0 || return 1;
    state_tmp=$(_e118_mktemp e204-zram-owner) || return 1;
    { 
        echo 'owned_by=e204';
        echo 'kind=zram';
        echo 'device=/dev/zram0';
        echo "created_at=$(date -Is 2> /dev/null || date)"
    } > "$state_tmp" || return 1;
    _e118_atomic_install "$state_tmp" "$E204_ZRAM_STATE" 0600
}
