# EEX3-FUNCTION mtu_mss_e206_220 _e214_critical_preflight
_e214_critical_preflight() {
    local label marker;
    while IFS='	' read -r label marker; do
        if test ! -e "$marker" && test ! -L "$marker"; then
            continue;
        fi;
        error "检测到${label}严重恢复标记，拒绝用新热更新覆盖未确认状态：$marker";
        if test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker"; then
            sed -n '1,20s/^/    /p' "$marker" 2> /dev/null || true;
        else
            error '恢复标记为空、不可读、类型异常或为符号链接；不能证明系统已恢复。';
        fi;
        error '请先依据标记中的backup完成恢复与读回，确认后再移走该标记。';
        return 1;
    done < <(_e214_recovery_markers)
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_directory_mode_self_test
_e214_directory_mode_self_test() {
    ( local d parent target before after;
    d=$(mktemp -d /tmp/xray-e214-dir-mode.XXXXXX) || return 1;
    trap 'rm -rf -- "${d:-}"' EXIT;
    chmod 1777 "$d" || return 1;
    before=$(stat -c '%a' "$d" 2> /dev/null || true);
    _e214_ensure_directory "$d" 0755 || return 1;
    after=$(stat -c '%a' "$d" 2> /dev/null || true);
    test "$before:$after" = 1777:1777 || return 1;
    parent="$d/existing-parent";
    target="$parent/entry";
    mkdir "$parent" || return 1;
    chmod 0711 "$parent" || return 1;
    _e214_ensure_parent_dir "$target" || return 1;
    test "$(stat -c '%a' "$parent" 2> /dev/null || true)" = 711 || return 1;
    _e214_ensure_parent_dir "$d/new-parent/entry" || return 1;
    test "$(stat -c '%a' "$d/new-parent" 2> /dev/null || true)" = 755 || return 1;
    : > "$d/not-a-directory" || return 1;
    ! _e214_ensure_directory "$d/not-a-directory" 0755 > /dev/null 2>&1 || return 1;
    rm -rf -- "$d";
    trap - EXIT )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_ensure_directory
_e214_ensure_directory() {
    local dir="${1:-}" create_mode="${2:-0755}";
    test -n "$dir" || return 1;
    if test -e "$dir" || test -L "$dir"; then
        test -d "$dir" && test -x "$dir" || { 
            error "目录路径存在但不可作为目录使用：$dir";
            return 1
        };
        return 0;
    fi;
    install -d -m "$create_mode" -- "$dir" || return 1;
    test -d "$dir" && test ! -L "$dir"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_ensure_parent_dir
_e214_ensure_parent_dir() {
    local target="${1:-}" parent;
    test -n "$target" || return 1;
    parent=$(dirname -- "$target") || return 1;
    _e214_ensure_directory "$parent" 0755
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_ensure_run_lock
_e214_ensure_run_lock() {
    _e214_ensure_directory /run/lock 0755
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_help
_e214_help() {
    cat <<'EOF_E214_HELP'
V199e214:
  --hot-update                         事务热更新到E214
  --summary                            导出节点URI、一次终端QR及PNG/SVG
  --network-audit                      只读网络参数/重复定义审计
  --full-network-apply                 事务应用完整127条请求
  --small-bbr-menu                     八个精确14/25/26项档位菜单
  --small-bbr-enable|status|disable    启用、读回或恢复小BBR
  --mtu-menu|--mtu-status              宿主机网卡MTU安全事务/只读状态
  --mtu-reconcile|--mtu-disable        立即复检/恢复首次接管前MTU
  --ipv6-disable|enable|status         IPv6永久策略（无IPv4时默认拒绝关闭）
  --warp-menu|--warp-global-menu       Xray层定向/全局WARP
  --warp-full-menu                     Cloudflare系统全隧道
  --recovery-status                    严重恢复标记/受保护事务状态（只读）
  --micro-menu                         完整28项微操中心
  --structure-audit                    E214最终绑定与不变量审计
  --self-test                          E214离线发行门禁
  --uninstall                          受控卸载（先恢复各事务基线）

升级注意：若任何旧版（包括E190-E200和E202兼容的E204-E212）小BBR仍处于
活动档，先用当前已安装的旧脚本执行 --small-bbr-disable 并确认恢复，
再运行E214热更新；热更新完成后再重新启用小BBR。

MTU说明：E212、完整127请求、菜单10→6→28项与小BBR都不会改宿主机
ens3/eth0的MTU；WARP中的MTU=1280仅属于虚拟隧道。菜单27才是独立的主机MTU所有者。
EOF_E214_HELP

}
