# EEX3-FUNCTION mtu_mss_e206_220 _e214_hot_rollback_self_test
_e214_hot_rollback_self_test() {
    ( local d result=0 restore_fail=0 legacy_fail=0 unexpected=0 status=0 base_fail=1;
    d=$(mktemp -d /tmp/xray-e214-hot-rollback.XXXXXX) || return 1;
    : > "$d/order";
    function _e214_prepare_tx () 
    { 
        :
    };
    function _e214_new_tx () 
    { 
        install -d -m 0700 "$d/tx/system";
        printf '%s\n' "$d/tx"
    };
    function _e214_tx_close () 
    { 
        :
    };
    function _e159_phase_log () 
    { 
        :
    };
    function _e140_system_snapshot () 
    { 
        echo snapshot >> "$d/order"
    };
    function _e202_hot_update_preflight () 
    { 
        echo legacy-preflight >> "$d/order";
        test "$unexpected" -eq 0 || exit 77;
        test "$legacy_fail" -eq 0
    };
    function _e204_hot_update_base () 
    { 
        if test "$base_fail" -eq 1; then
            echo mutate-fail >> "$d/order";
            return 1;
        fi;
        echo mutate-ok >> "$d/order"
    };
    function _e214_hot_verify () 
    { 
        echo verify >> "$d/order"
    };
    function _e214_install_self () 
    { 
        echo duplicate-install >> "$d/order";
        return 1
    };
    function _e214_write_version () 
    { 
        echo duplicate-version >> "$d/order";
        return 1
    };
    function _e140_system_restore () 
    { 
        echo restore >> "$d/order";
        test "$restore_fail" -eq 0
    };
    function _e214_mark_critical () 
    { 
        echo critical >> "$d/order";
        return 0
    };
    ! E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update > /dev/null 2>&1 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot legacy-preflight mutate-fail restore ' || result=1;
    : > "$d/order";
    restore_fail=1;
    ! E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update > /dev/null 2>&1 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot legacy-preflight mutate-fail restore critical ' || result=1;
    : > "$d/order";
    restore_fail=0;
    legacy_fail=1;
    ! E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update > /dev/null 2>&1 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot legacy-preflight restore ' || result=1;
    : > "$d/order";
    legacy_fail=0;
    unexpected=1;
    if E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update > /dev/null 2>&1; then
        status=0;
    else
        status=$?;
    fi;
    test "$status" -eq 77 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot legacy-preflight restore ' || result=1;
    : > "$d/order";
    restore_fail=1;
    if E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update > /dev/null 2>&1; then
        status=0;
    else
        status=$?;
    fi;
    test "$status" -eq 77 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot legacy-preflight restore critical ' || result=1;
    : > "$d/order";
    restore_fail=0;
    unexpected=0;
    base_fail=0;
    E214_INTERNAL_SELF_TEST=1 E214_INTERNAL_SELF_TEST_TMP="$d" _e214_hot_update > /dev/null 2>&1 || result=1;
    test "$(tr '\n' ' ' < "$d/order")" = 'snapshot legacy-preflight mutate-ok verify ' || result=1;
    rm -rf -- "$d";
    return "$result" )
}
