}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_install_self
_e214_install_self() {
    local tx source rc=0;
    local -a targets=();
    source=$(_eex6_release_source) && _eex6_release_artifact_verify "$source" || return 1;
    _e214_prepare || return 1;
    tx=$(_e214_new_tx "self-install-$EEX3_BUILD_ID") || return 1;
    mapfile -t targets < <(_eex3_script_targets);
    _eex3_script_entries_install "$source" "$tx" "${targets[@]}" || rc=$?;
    _e214_tx_close "$tx" || { 
        error "入口事务关闭失败：$tx";
        return 1
    };
    test "$rc" -eq 0 || { 
        error "入口安装失败，已执行入口事务回滚：$tx rc=$rc";
        return "$rc"
    };
    hash -r 2> /dev/null || true
}
