# EEX3-FUNCTION mtu_mss_e206_220 _e214_mark_critical
_e214_mark_critical() {
    local operation="$1" backup="$2" reason="$3" tmp preserved=0 marked=0;
    _e214_preserve_tx "$backup" "$operation: $reason" && preserved=1 || true;
    _e214_prepare || return 1;
    tmp=$(_e118_mktemp e214-critical) || return 1;
    { 
        printf 'version=%s\n' "$E214_VERSION";
        printf 'time=%s\n' "$(date '+%F %T %z')";
        printf 'operation=%s\n' "$operation";
        printf 'backup=%s\n' "$backup";
        printf 'reason=%s\n' "$(printf '%s' "$reason" | tr '\r\n' '  ')"
    } > "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$E214_CRITICAL_MARKER" 0600 && marked=1 || true;
    ((preserved == 1 || marked == 1))
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_active
_e214_mtu_active() {
    _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_any_state
_e214_mtu_any_state() {
    test -e "$E214_MTU_STATE" || test -L "$E214_MTU_STATE" || test -e "$E214_MTU_BASELINE" || test -L "$E214_MTU_BASELINE" || test -e "$E214_MTU_SERVICE" || test -L "$E214_MTU_SERVICE" || test -e "$E214_MTU_TIMER" || test -L "$E214_MTU_TIMER" || { 
        test -d /run/systemd/system && { 
            systemctl is-enabled --quiet "$E214_MTU_UNIT" 2> /dev/null || systemctl is-enabled --quiet "$E214_MTU_TIMER_UNIT" 2> /dev/null || systemctl is-active --quiet "$E214_MTU_TIMER_UNIT" 2> /dev/null
        }
    }
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_apply_runtime
_e214_mtu_apply_runtime() {
    local iface="${1:-}" value="${2:-}" now;
    _e214_mtu_iface_candidate "$iface" || { 
        error "拒绝修改虚拟、隧道或不存在的网卡：$iface";
        return 1
    };
    _e214_mtu_value_valid "$value" || { 
        error 'MTU必须是1280-9000之间的整数。';
        return 1
    };
    ip link set dev "$iface" mtu "$value" > /dev/null 2>&1 || return 1;
    now=$(_e214_mtu_current "$iface" 2> /dev/null || true);
    test "$now" = "$value" || { 
        error "网卡MTU读回不一致：iface=$iface expected=$value actual=${now:-unreadable}";
        return 1
    }
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_baseline_add
_e214_mtu_baseline_add() {
    local file="${1:-}" iface="${2:-}" value tmp;
    _e214_mtu_iface_candidate "$iface" || return 1;
    if _e214_mtu_baseline_has "$file" "$iface"; then
        return 0;
    fi;
    value=$(_e214_mtu_current "$iface") || return 1;
    printf '%s|%s\n' "$iface" "$value" >> "$file" || return 1;
    tmp="${file}.sort.$$";
    LC_ALL=C sort -t'|' -k1,1 "$file" > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -f -- "$tmp" "$file" || { 
        rm -f -- "$tmp";
        return 1
    };
    _e214_mtu_baseline_validate "$file"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_baseline_has
_e214_mtu_baseline_has() {
    local file="${1:-}" iface="${2:-}";
    awk -F'|' -v wanted="$iface" '$1==wanted{n++}END{exit(n==1?0:1)}' "$file" 2> /dev/null
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_baseline_validate
_e214_mtu_baseline_validate() {
    local file="${1:-}" line iface value count=0;
    local -A seen=();
    test -f "$file" && test ! -L "$file" && test -r "$file" && test -s "$file" || return 1;
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([A-Za-z0-9_.:-]+)\|([0-9]+)$ ]] || return 1;
        iface=${BASH_REMATCH[1]};
        value=${BASH_REMATCH[2]};
        _e214_mtu_iface_valid "$iface" || return 1;
        _e214_mtu_original_value_valid "$value" || return 1;
        test -z "${seen[$iface]+x}" || return 1;
        seen[$iface]=1;
        count=$((count + 1));
    done < "$file";
    test "$count" -ge 1 && test "$count" -le 64
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_candidates
_e214_mtu_candidates() {
    local root p iface;
    root=$(_e214_mtu_sysroot) || return 1;
    for p in "$root"/*;
    do
        test -e "$p" || continue;
        iface=${p##*/};
        _e214_mtu_iface_candidate "$iface" && printf '%s\n' "$iface";
    done | LC_ALL=C sort -u
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_commit
_e214_mtu_commit() {
    local work="$1" baseline="$2" selector="$3" configured="$4" target="$5" iface="$6";
    local state_c="$work/mtu-policy.env" service_c="$work/xray-mtu-e214.service" timer_c="$work/xray-mtu-e214.timer";
    _e214_prepare || return 1;
    _e214_mtu_write_state_candidate "$state_c" "$baseline" "$selector" "$configured" "$target" "$iface" || return 1;
    _e214_mtu_write_unit_candidates "$service_c" "$timer_c" || return 1;
    _e118_atomic_install "$baseline" "$E214_MTU_BASELINE" 0600 || return 1;
    _e118_atomic_install "$state_c" "$E214_MTU_STATE" 0600 || return 1;
    _e118_atomic_install "$service_c" "$E214_MTU_SERVICE" 0644 || return 1;
    _e118_atomic_install "$timer_c" "$E214_MTU_TIMER" 0644 || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    systemctl enable "$E214_MTU_UNIT" "$E214_MTU_TIMER_UNIT" > /dev/null 2>&1 || return 1;
    systemctl start "$E214_MTU_TIMER_UNIT" > /dev/null 2>&1 || return 1;
    _e214_mtu_persistence_validate
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_current
_e214_mtu_current() {
    local iface="${1:-}" root value;
    _e214_mtu_iface_valid "$iface" || return 1;
    root=$(_e214_mtu_sysroot) || return 1;
    value=$(tr -d '[:space:]' < "$root/$iface/mtu" 2> /dev/null || true);
    _e214_mtu_original_value_valid "$value" || return 1;
    printf '%s\n' "$value"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_default_iface
_e214_mtu_default_iface() {
    local iface;
    while IFS= read -r iface; do
        iface=${iface%%@*};
        if _e214_mtu_iface_candidate "$iface"; then
            printf '%s\n' "$iface";
            return 0;
        fi;
    done < <({ ip -4 route get 1.1.1.1 2> /dev/null || true
ip -4 route show default 2> /dev/null || true
ip -6 route get 2606:4700:4700::1111 2> /dev/null || true
ip -6 route show default 2> /dev/null || true; } | awk '{for(i=1;i<=NF;i++)if($i=="dev" && (i+1)<=NF){print $(i+1);break}}');
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_disable
_e214_mtu_disable() {
    ( _e214_ensure_run_lock || return 1;
    exec 207> /run/lock/xray-mtu-e214.lock || return 1;
    flock -n 207 || { 
        error '已有MTU应用/复检/退出事务正在运行。';
        return 1
    };
    _e220_mtu_disable_unlocked "$@" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_guard_confirm
_e214_mtu_guard_confirm() {
    local guard="${1:-}" tmp;
    test -n "$guard" || return 1;
    tmp="${guard}.new.$$";
    printf 'confirmed=1\ntime=%s\n' "$(date +%s)" > "$tmp" || return 1;
    chmod 0600 "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -f -- "$tmp" "$guard"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_guard_is_confirmed
_e214_mtu_guard_is_confirmed() {
    local guard="${1:-}";
    test -f "$guard" && test ! -L "$guard" && grep -Fqx 'confirmed=1' "$guard" 2> /dev/null
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_iface_candidate
_e214_mtu_iface_candidate() {
    local iface="${1:-}" root;
    _e214_mtu_iface_valid "$iface" || return 1;
    case "$iface" in 
        lo | docker* | br-* | virbr* | veth* | cni* | flannel* | cali* | kube* | podman* | vnet* | vmnet* | ifb* | dummy* | tun* | tap* | wg* | warp* | CloudflareWARP* | tailscale* | zt* | ip6tnl* | sit* | gre* | gretap* | erspan* | vxlan* | geneve* | pf-wg*)
            return 1
        ;;
    esac;
    root=$(_e214_mtu_sysroot) || return 1;
    test -r "$root/$iface/mtu"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_iface_valid
_e214_mtu_iface_valid() {
    local iface="${1:-}";
    test -n "$iface" && test "${#iface}" -le 15 && [[ "$iface" =~ ^[A-Za-z0-9_.:-]+$ ]]
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_log_line
_e214_mtu_log_line() {
    install -d -m 0750 "$(dirname -- "$E214_MTU_LOG")" 2> /dev/null || return 0;
    printf '%s %s\n' "$(date '+%F %T %z')" "$*" >> "$E214_MTU_LOG" 2> /dev/null || true
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_menu
_e214_mtu_menu() {
    local opt="" iface="" value="" current="";
    while true; do
        clear;
        title 'V199e266：宿主机网卡 MTU 手动设置中心';
        echo '  1) 只读查看实际MTU、默认出口与E214稳定所有权';
        echo '  2) 自动识别当前默认出口并手动输入MTU（推荐）';
        echo '  3) 指定宿主机网卡并手动输入MTU';
        echo '  4) 立即执行一次开机/漂移复检';
        echo '  5) 退出E214 MTU策略并恢复首次接管前数值';
        echo '  6) 查看MTU、tcp_mtu_probing与WARP虚拟MTU边界';
        echo -e "  ${cyan}7) 默认出口快捷设置 MTU=1350（一次 y/N 确认）${none}";
        echo '  0) 返回';
        hr;
        read -rp '操作: ' opt || true;
        case "$opt" in 
            1)
                _e214_mtu_status;
                _e116_pause
            ;;
            2)
                iface=$(_e214_mtu_default_iface 2> /dev/null || true);
                if test -z "$iface"; then
                    error '未识别到稳定默认出口。';
                    _e116_pause;
                    continue;
                fi;
                current=$(_e214_mtu_current "$iface" 2> /dev/null || true);
                read -rp "目标MTU [1280-9000，当前$current]: " value || true;
                value=${value:-$current};
                _e214_mtu_set_interactive auto - "$value" || true;
                _e116_pause
            ;;
            3)
                _e214_mtu_status;
                read -rp '宿主机网卡名: ' iface || true;
                if ! _e214_mtu_iface_candidate "$iface"; then
                    error '网卡不存在或属于虚拟/隧道排除列表。';
                    _e116_pause;
                    continue;
                fi;
                current=$(_e214_mtu_current "$iface" 2> /dev/null || true);
                read -rp "目标MTU [1280-9000，当前$current]: " value || true;
                value=${value:-$current};
                _e214_mtu_set_interactive iface "$iface" "$value" || true;
                _e116_pause
            ;;
            4)
                _e214_mtu_reconcile || error 'MTU复检失败；查看状态与日志。';
                _e214_mtu_status;
                _e116_pause
            ;;
            5)
                _e214_mtu_disable || true;
                _e116_pause
            ;;
            6)
                title 'MTU边界说明';
                echo '  - E212/28项/完整127请求/小BBR都不设置物理网卡MTU。';
                echo '  - tcp_mtu_probing=1只在TCP路径MTU黑洞时探测，不改ip link MTU。';
                echo '  - WARP/WireGuard的MTU=1280属于虚拟隧道，不等于ens3/eth0 MTU。';
                echo '  - E214允许1280-9000；过大需整条链路支持，错误值会丢包或卡顿。';
                echo '  - 自动出口变化时E214停止盲目写入，必须回到本菜单重新确认。';
                _e116_pause
            ;;
            7)
                iface=$(_e214_mtu_default_iface 2> /dev/null || true);
                if test -z "$iface"; then
                    error '未识别到稳定默认出口。';
                    _e116_pause;
                    continue;
                fi;
                current=$(_e214_mtu_current "$iface" 2> /dev/null || true);
                warn "快捷档只把宿主机默认出口 $iface 从 ${current:-unknown} 改为1350；不改WARP/tun/wg虚拟MTU。";
                warn 'MTU=1350是高防清洗/动态路由隐藏隧道的保守兼容档，可减少分片与PMTU黑洞；它不是DDoS或暴力攻击防护。';
                _e214_mtu_set_interactive auto - 1350 || true;
                _e116_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn '无效操作。';
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_original_value_valid
_e214_mtu_original_value_valid() {
    local value="${1:-}";
    [[ "$value" =~ ^[0-9]+$ ]] && ((value >= 68 && value <= 65535))
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_persistence_validate
_e214_mtu_persistence_validate() {
    local selector target last actual resolved;
    _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || return 1;
    test -f "$E214_SELF_PATH" && test ! -L "$E214_SELF_PATH" && test -x "$E214_SELF_PATH" && bash -n "$E214_SELF_PATH" || return 1;
    test -f "$E214_MTU_SERVICE" && test ! -L "$E214_MTU_SERVICE" && test -f "$E214_MTU_TIMER" && test ! -L "$E214_MTU_TIMER" || return 1;
    grep -Fqx 'Type=oneshot' "$E214_MTU_SERVICE" || return 1;
    grep -Fqx "ExecStart=/bin/bash $E214_SELF_PATH --mtu-reconcile" "$E214_MTU_SERVICE" || return 1;
    grep -Fqx 'WantedBy=multi-user.target' "$E214_MTU_SERVICE" || return 1;
    ! grep -q 'RemainAfterExit' "$E214_MTU_SERVICE" || return 1;
    grep -Fqx 'OnUnitActiveSec=5min' "$E214_MTU_TIMER" || return 1;
    systemctl is-enabled --quiet "$E214_MTU_UNIT" 2> /dev/null || return 1;
    systemctl is-enabled --quiet "$E214_MTU_TIMER_UNIT" 2> /dev/null || return 1;
    systemctl is-active --quiet "$E214_MTU_TIMER_UNIT" 2> /dev/null || return 1;
    selector=$(_e214_mtu_state_get_file "$E214_MTU_STATE" selector) || return 1;
    target=$(_e214_mtu_state_get_file "$E214_MTU_STATE" target_mtu) || return 1;
    last=$(_e214_mtu_state_get_file "$E214_MTU_STATE" last_iface) || return 1;
    actual=$(_e214_mtu_current "$last" 2> /dev/null || true);
    test "$actual" = "$target" || return 1;
    if test "$selector" = auto; then
        resolved=$(_e214_mtu_default_iface 2> /dev/null || true);
        test "$resolved" = "$last" || return 1;
    fi;
    _e214_mtu_route_health "$last" "$selector"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_reconcile
_e214_mtu_reconcile() {
    ( local selector configured target last iface current lock_path=/run/lock/xray-mtu-e214.lock;
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1; then
        lock_path="${E242_MTU_LOCK_PATH:-$lock_path}";
    fi;
    _e214_ensure_run_lock || return 1;
    exec 207> "$lock_path" || return 1;
    flock -n 207 || { 
        _e214_mtu_log_line 'result=failed reason=busy';
        return 75
    };
    _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || return 1;
    selector=$(_e214_mtu_state_get_file "$E214_MTU_STATE" selector) || return 1;
    configured=$(_e214_mtu_state_get_file "$E214_MTU_STATE" configured_iface) || return 1;
    target=$(_e214_mtu_state_get_file "$E214_MTU_STATE" target_mtu) || return 1;
    last=$(_e214_mtu_state_get_file "$E214_MTU_STATE" last_iface) || return 1;
    iface=$configured;
    if test "$selector" = auto; then
        iface=$(_e214_mtu_default_iface 2> /dev/null) || return 1;
    fi;
    test "$iface" = "$last" || { 
        _e214_mtu_log_line "result=failed reason=default-route-changed expected=$last actual=$iface";
        return 1
    };
    _e214_mtu_route_health "$iface" "$selector" || return 1;
    _e214_mtu_apply_runtime "$iface" "$target" || return 1;
    _e214_mtu_persistence_validate )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_restore_baseline_except
_e214_mtu_restore_baseline_except() {
    local file="${1:-}" keep="${2:-}" iface value now rc=0;
    _e214_mtu_baseline_validate "$file" || return 1;
    while IFS='|' read -r iface value; do
        test -n "$iface" || continue;
        test "$iface" = "$keep" && continue;
        if ! _e214_mtu_iface_candidate "$iface"; then
            warn "MTU基线中的旧网卡当前不存在，跳过运行态恢复：$iface";
            continue;
        fi;
        ip link set dev "$iface" mtu "$value" > /dev/null 2>&1 || { 
            rc=1;
            continue
        };
        now=$(_e214_mtu_current "$iface" 2> /dev/null || true);
        test "$now" = "$value" || rc=1;
    done < "$file";
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_restore_guarded
_e214_mtu_restore_guarded() {
    local tx="$1" unit="$2" guard="$3" rc=0;
    exec 208> "$tx/mtu-rollback.lock";
    flock 208 || return 1;
    _e140_system_restore "$tx/system" || rc=1;
    if test "$rc" -eq 0; then
        _e214_mtu_guard_confirm "$guard" || rc=1;
    fi;
    flock -u 208 || true;
    if test "$rc" -eq 0; then
        _e214_mtu_transient_stop "$unit";
        _e214_tx_close "$tx" || true;
        return 0;
    fi;
    _e214_mark_critical mtu-apply "$tx/system" 'interactive MTU rollback/readback failed' || true;
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_rollback_snapshot
_e214_mtu_rollback_snapshot() {
    local snapshot="${1:-}" guard="${2:-}" root real tx lock guard_parent rc=0;
    root=$(readlink -f -- "$E214_TX_ROOT" 2> /dev/null || true);
    real=$(readlink -f -- "$snapshot" 2> /dev/null || true);
    test -n "$root" && test -d "$root" && test -n "$real" && test -d "$real" || return 1;
    case "$real" in 
        "$root"/*/system)

        ;;
        *)
            return 1
        ;;
    esac;
    tx=${real%/system};
    test "${guard##*/}" = mtu-confirmed || return 1;
    guard_parent=$(readlink -f -- "$(dirname -- "$guard")" 2> /dev/null || true);
    test "$guard_parent" = "$tx" || return 1;
    guard="$tx/mtu-confirmed";
    lock="$tx/mtu-rollback.lock";
    exec 208> "$lock";
    flock 208 || return 1;
    _e214_mtu_guard_is_confirmed "$guard" && return 0;
    _e140_system_restore "$real" || rc=1;
    if test "$rc" -eq 0; then
        _e214_mtu_log_line "result=rolled-back snapshot=$real reason=confirmation-timeout-or-session-loss";
        _e214_tx_close "$tx" || true;
        return 0;
    fi;
    _e214_mark_critical mtu-timeout "$real" 'automatic MTU rollback/readback failed' || true;
    _e214_mtu_log_line "result=critical snapshot=$real reason=automatic-rollback-failed";
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_route_health
_e214_mtu_route_health() {
    local iface="${1:-}" selector="${2:-iface}" client family=4 tuple;
    _e214_mtu_iface_candidate "$iface" || return 1;
    if test "$selector" = auto; then
        test "$(_e214_mtu_default_iface 2> /dev/null)" = "$iface" || return 1;
        tuple=$(_eex3_route_tuple 4 1.1.1.1) || return 1;
        test "${tuple%%|*}" = "$iface" || { 
            error '默认流量出口与MTU目标不一致。';
            return 1
        };
    fi;
    _eex3_ssh_tuple_validate || return 1;
    if test -n "${SSH_CONNECTION:-}"; then
        read -r client _ <<< "${SSH_CONNECTION:-}";
        [[ "$client" != *:* ]] || family=6;
        _eex3_route_tuple "$family" "$client" > /dev/null || return 1;
    fi;
    test -z "${EEX3_MTU_ROUTE_PLAN:-}" || _eex3_route_plan_verify "$EEX3_MTU_ROUTE_PLAN"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_schedule_rollback
_e214_mtu_schedule_rollback() {
    local unit="$1" runner="$2" snapshot="$3" guard="$4";
    command -v systemd-run > /dev/null 2>&1 || return 1;
    systemd-run --quiet --collect --unit="$unit" --on-active=120s --timer-property=AccuracySec=1s --property=Type=oneshot /bin/bash "$runner" --mtu-rollback-snapshot "$snapshot" "$guard" > /dev/null
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_self_test
_e214_mtu_self_test() {
    ( local d baseline state service timer actual rc=0;
    d=$(mktemp -d /tmp/xray-e214-mtu-selftest.XXXXXX) || return 1;
    trap 'rm -rf -- "${d:-}"' EXIT;
    mkdir -p "$d/sys/ens3" "$d/sys/ens4" "$d/sys/wgcf" || return 1;
    printf '1500\n' > "$d/sys/ens3/mtu";
    printf 'up\n' > "$d/sys/ens3/operstate";
    printf '1450\n' > "$d/sys/ens4/mtu";
    printf 'down\n' > "$d/sys/ens4/operstate";
    printf '1280\n' > "$d/sys/wgcf/mtu";
    printf 'unknown\n' > "$d/sys/wgcf/operstate";
    E214_MTU_SYSFS_ROOT="$d/sys";
    SSH_CONNECTION="";
    function ip () 
    { 
        if test "${1:-}" = link && test "${2:-}" = set && test "${3:-}" = dev && test "${5:-}" = mtu; then
            test -f "$E214_MTU_SYSFS_ROOT/${4:-}/mtu" || return 1;
            printf '%s\n' "${6:-}" > "$E214_MTU_SYSFS_ROOT/${4:-}/mtu";
            return 0;
        fi;
        if test "${1:-}" = -4 && test "${2:-}" = route && test "${3:-}" = get; then
            echo '1.1.1.1 via 192.0.2.1 dev ens3 src 192.0.2.2';
            return 0;
        fi;
        if test "${1:-}" = -4 && test "${2:-}" = route && test "${3:-}" = show; then
            echo 'default via 192.0.2.1 dev ens3';
            return 0;
        fi;
        return 1
    };
    _e214_mtu_iface_candidate ens3 || rc=1;
    ! _e214_mtu_iface_candidate wgcf || rc=1;
    test "$(_e214_mtu_default_iface)" = ens3 || rc=1;
    _e214_mtu_value_valid 1280 && _e214_mtu_value_valid 1350 && _e214_mtu_value_valid 9000 || rc=1;
    ! _e214_mtu_value_valid 1279 && ! _e214_mtu_value_valid 9001 || rc=1;
    baseline="$d/baseline.tsv";
    state="$d/state.env";
    printf 'ens3|1500\n' > "$baseline";
    chmod 0600 "$baseline";
    _e214_mtu_baseline_validate "$baseline" || rc=1;
    _e214_mtu_baseline_add "$baseline" ens4 || rc=1;
    test "$(wc -l < "$baseline" | tr -d ' ')" -eq 2 || rc=1;
    _e214_mtu_write_state_candidate "$state" "$baseline" auto - 1420 ens3 || rc=1;
    _e214_mtu_state_validate "$state" "$baseline" || rc=1;
    ! _e214_mtu_write_state_candidate "$d/bad-state" "$baseline" iface ens4 1420 ens3 > /dev/null 2>&1 || rc=1;
    printf 'tamper\n' >> "$baseline";
    ! _e214_mtu_state_validate "$state" "$baseline" || rc=1;
    sed -i '$d' "$baseline";
    _e214_mtu_write_state_candidate "$state" "$baseline" auto - 1420 ens3 || rc=1;
    _e214_mtu_apply_runtime ens3 1420 || rc=1;
    actual=$(_e214_mtu_current ens3 2> /dev/null || true);
    test "$actual" = 1420 || rc=1;
    _e214_mtu_route_health ens3 auto || rc=1;
    _e214_mtu_restore_baseline_except "$baseline" "" || rc=1;
    test "$(_e214_mtu_current ens3)" = 1500 || rc=1;
    test "$(_e214_mtu_current ens4)" = 1450 || rc=1;
    service="$d/service";
    timer="$d/timer";
    _e214_mtu_write_unit_candidates "$service" "$timer" || rc=1;
    grep -Fqx 'Type=oneshot' "$service" || rc=1;
    grep -Fqx 'WantedBy=multi-user.target' "$service" || rc=1;
    ! grep -q 'RemainAfterExit' "$service" || rc=1;
    grep -Fqx 'OnActiveSec=5min' "$timer" || rc=1;
    rm -rf -- "$d";
    trap - EXIT;
    return "$rc" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_set_interactive
_e214_mtu_set_interactive() {
    ( local selector="${1:-auto}" configured="${2:--}" target="${3:-}" iface="" answer="";
    local tx="" baseline_work="" snapshot_ready=0 finished=0 rc=0 restore_rc=0;
    function _e242_mtu_simple_exit_guard () 
    { 
        local status="${1:-1}";
        trap - EXIT HUP INT TERM;
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error 'MTU操作被中断，恢复操作前状态。';
            _e140_system_restore "$tx/system" || { 
                _e214_mark_critical mtu-apply "$tx/system" 'E242 interrupted manual MTU rollback failed' || true
            };
            _e214_tx_close "$tx" || true;
            test "$status" -ne 0 || status=1;
        else
            if test -n "$tx"; then
                _e214_tx_close "$tx" || true;
            fi;
        fi;
        [[ "$status" =~ ^[0-9]+$ ]] || status=1;
        exit "$status"
    };
    trap '_e242_mtu_simple_exit_guard $?' EXIT;
    trap 'exit 129' HUP;
    trap 'exit 130' INT;
    trap 'exit 143' TERM;
    case "$selector" in 
        auto)
            configured=-;
            iface=$(_e214_mtu_default_iface 2> /dev/null || true)
        ;;
        iface)
            iface=$configured
        ;;
        *)
            error 'MTU selector无效。';
            return 1
        ;;
    esac;
    _e214_mtu_iface_candidate "$iface" || { 
        error "无法把网卡作为宿主机MTU目标：${iface:-none}";
        return 1
    };
    _e214_mtu_value_valid "$target" || { 
        error 'MTU必须是1280-9000之间的整数。';
        return 1
    };
    warn "将把宿主机网卡 $iface 的MTU设为 $target；失败会立即恢复。";
    read -rp '确认执行？[y/N]: ' answer || true;
    case "$answer" in 
        y | Y | yes | YES | Yes)

        ;;
        *)
            info '已取消，系统未修改。';
            return 0
        ;;
    esac;
    _e214_prepare || return 1;
    _e214_ensure_run_lock || return 1;
    exec 207> /run/lock/xray-mtu-e214.lock;
    flock -n 207 || { 
        error '已有MTU应用/复检事务正在运行。';
        return 1
    };
    if _e214_mtu_any_state; then
        _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || { 
            error '现有MTU状态不完整；拒绝覆盖。';
            return 1
        };
    fi;
    tx=$(_e214_new_tx mtu-apply) || return 1;
    _e140_system_snapshot "$tx/system" || return 1;
    snapshot_ready=1;
    baseline_work="$tx/mtu-baseline.work";
    if _e214_mtu_active; then
        install -m 0600 "$E214_MTU_BASELINE" "$baseline_work" || rc=1;
        test "$rc" -ne 0 || _e214_mtu_restore_baseline_except "$baseline_work" "$iface" || rc=1;
    else
        : > "$baseline_work" || rc=1;
        chmod 0600 "$baseline_work" || rc=1;
    fi;
    test "$rc" -ne 0 || _e214_mtu_baseline_add "$baseline_work" "$iface" || rc=1;
    test "$rc" -ne 0 || _e214_mtu_apply_runtime "$iface" "$target" || rc=1;
    test "$rc" -ne 0 || _e214_mtu_route_health "$iface" "$selector" || rc=1;
    test "$rc" -ne 0 || _e214_install_self || rc=1;
    test "$rc" -ne 0 || _e214_mtu_commit "$tx" "$baseline_work" "$selector" "$configured" "$target" "$iface" || rc=1;
    test "$rc" -ne 0 || _e214_mtu_apply_runtime "$iface" "$target" || rc=1;
    test "$rc" -ne 0 || _e214_mtu_route_health "$iface" "$selector" || rc=1;
    test "$rc" -ne 0 || _e214_mtu_persistence_validate || rc=1;
    if test "$rc" -ne 0; then
        error 'MTU应用/持久化/读回失败，恢复操作前状态。';
        _e140_system_restore "$tx/system" || restore_rc=1;
        if test "$restore_rc" -ne 0; then
            _e214_mark_critical mtu-apply "$tx/system" 'E242 manual MTU rollback failed' || true;
            error "MTU回滚未完整通过；保留快照：$tx/system";
        fi;
        finished=1;
        _e214_tx_close "$tx" || true;
        trap - EXIT HUP INT TERM;
        return 1;
    fi;
    finished=1;
    _e214_tx_close "$tx" || warn "MTU已提交，但事务活动标记未关闭：$tx";
    trap - EXIT HUP INT TERM;
    info "MTU已一次确认提交并读回：selector=$selector iface=$iface mtu=$target" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_set_interactive_retired_two_confirm
_e214_mtu_set_interactive_retired_two_confirm() {
    ( local selector="${1:-auto}" configured="${2:--}" target="${3:-}" iface tx="" unit="" guard="";
    local runner baseline_work answer token snapshot_ready=0 finished=0 rc=0;
    function _e214_mtu_exit_guard () 
    { 
        local status="${1:-1}";
        trap - EXIT HUP INT TERM;
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error 'MTU事务被中断，立即恢复操作前网卡、文件与服务状态。';
            _e214_mtu_restore_guarded "$tx" "$unit" "$guard" || true;
            test "$status" -ne 0 || status=1;
        else
            if test -n "$tx"; then
                _e214_tx_close "$tx" || true;
            fi;
        fi;
        [[ "$status" =~ ^[0-9]+$ ]] || status=1;
        exit "$status"
    };
    trap '_e214_mtu_exit_guard $?' EXIT;
    trap 'exit 129' HUP;
    trap 'exit 130' INT;
    trap 'exit 143' TERM;
    case "$selector" in 
        auto)
            configured=-;
            iface=$(_e214_mtu_default_iface 2> /dev/null || true)
        ;;
        iface)
            iface=$configured
        ;;
        *)
            error 'MTU selector无效。';
            return 1
        ;;
    esac;
    _e214_mtu_iface_candidate "$iface" || { 
        error "无法把网卡作为宿主机MTU目标：${iface:-none}";
        return 1
    };
    _e214_mtu_value_valid "$target" || { 
        error 'MTU必须是1280-9000之间的整数。';
        return 1
    };
    token="APPLY-MTU-$target";
    warn "将修改宿主机网卡 $iface 的MTU为 $target；错误值可能使当前SSH断线。";
    echo '  WARP/wg/tun虚拟接口不会被修改。操作后仍需第二次限时确认。';
    read -rp "输入 $token 开始安全事务: " answer || true;
    test "$answer" = "$token" || { 
        info '已取消，系统未修改。';
        return 0
    };
    _e214_prepare || return 1;
    _e214_ensure_run_lock || return 1;
    exec 207> /run/lock/xray-mtu-e214.lock;
    flock -n 207 || { 
        error '已有MTU应用/复检事务正在运行。';
        return 1
    };
    if _e214_mtu_any_state; then
        _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || { 
            error '现有MTU所有权状态不完整；拒绝覆盖，先查看菜单27状态。';
            return 1
        };
    fi;
    tx=$(_e214_new_tx mtu-apply) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e214_tx_close "$tx" || true;
        return 1
    };
    snapshot_ready=1;
    runner="$tx/mtu-rollback-runner.sh";
    guard="$tx/mtu-confirmed";
    install -m 0700 "$SCRIPT_PATH" "$runner" && bash -n "$runner" || return 1;
    unit="xray-mtu-e214-rollback-$$-$RANDOM";
    _e214_mtu_schedule_rollback "$unit" "$runner" "$tx/system" "$guard" || { 
        error '无法创建独立断线回滚定时器；未修改MTU。';
        return 1
    };
    baseline_work="$tx/mtu-baseline.work";
    if _e214_mtu_active; then
        install -m 0600 "$E214_MTU_BASELINE" "$baseline_work" || return 1;
        _e214_mtu_restore_baseline_except "$baseline_work" "$iface" || return 1;
    else
        : > "$baseline_work" || return 1;
        chmod 0600 "$baseline_work" || return 1;
    fi;
    _e214_mtu_baseline_add "$baseline_work" "$iface" || return 1;
    _e214_mtu_apply_runtime "$iface" "$target" || return 1;
    _e214_mtu_route_health "$iface" "$selector" || { 
        error '修改后路由/SSH回程只读复检失败。';
        return 1
    };
    echo;
    info "临时MTU已读回：$iface=$target";
    warn '请在90秒内确认当前SSH/代理仍正常；不确认会恢复完整快照。';
    read -r -t 90 -p '输入 KEEP-MTU 确认永久生效: ' answer || answer="";
    echo;
    if test "$answer" != KEEP-MTU; then
        warn '未收到KEEP-MTU，恢复操作前MTU与全部持久状态。';
        _e214_mtu_restore_guarded "$tx" "$unit" "$guard" || return 1;
        finished=1;
        trap - EXIT HUP INT TERM;
        return 1;
    fi;
    exec 208> "$tx/mtu-rollback.lock";
    flock 208 || return 1;
    _e214_install_self || rc=1;
    test "$rc" -ne 0 || _e214_mtu_commit "$tx" "$baseline_work" "$selector" "$configured" "$target" "$iface" || rc=1;
    test "$rc" -ne 0 || _e214_mtu_apply_runtime "$iface" "$target" || rc=1;
    test "$rc" -ne 0 || _e214_mtu_route_health "$iface" "$selector" || rc=1;
    test "$rc" -ne 0 || _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || rc=1;
    if test "$rc" -eq 0; then
        _e214_mtu_guard_confirm "$guard" || rc=1;
    fi;
    flock -u 208 || true;
    if test "$rc" -ne 0; then
        error 'MTU持久化或最终读回失败，恢复操作前完整状态。';
        _e214_mtu_restore_guarded "$tx" "$unit" "$guard" || return 1;
        finished=1;
        trap - EXIT HUP INT TERM;
        return 1;
    fi;
    _e214_mtu_transient_stop "$unit";
    _e214_tx_close "$tx" || warn "MTU已提交，但事务活动标记未关闭：$tx";
    finished=1;
    trap - EXIT HUP INT TERM;
    info "宿主机MTU策略已提交：selector=$selector iface=$iface mtu=$target";
    info '开机服务与每5分钟漂移复检已启用；默认出口改变时不会盲目接管新网卡。' )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_snapshot_self_test
_e214_mtu_snapshot_self_test() {
    ( local d rc=0;
    d=$(mktemp -d /tmp/xray-e214-mtu-snapshot.XXXXXX) || return 1;
    trap 'rm -rf -- "${d:-}"' EXIT;
    mkdir -p "$d/sys/ens3" || return 1;
    printf '1500\n' > "$d/sys/ens3/mtu";
    printf 'up\n' > "$d/sys/ens3/operstate";
    E214_MTU_SYSFS_ROOT="$d/sys";
    function _e214_system_snapshot_base () 
    { 
        install -d -m 0700 "$1"
    };
    function _e214_system_restore_base () 
    { 
        :
    };
    function _e204_service_snapshot () 
    { 
        printf '%s|not-found|disabled|inactive\n' "$1"
    };
    function _e204_services_restore_file () 
    { 
        test -s "$1"
    };
    function ip () 
    { 
        test "${1:-} ${2:-} ${3:-} ${5:-}" = 'link set dev mtu' || return 1;
        test -f "$E214_MTU_SYSFS_ROOT/${4:-}/mtu" || return 1;
        printf '%s\n' "${6:-}" > "$E214_MTU_SYSFS_ROOT/${4:-}/mtu"
    };
    _e140_system_snapshot "$d/snapshot" || rc=1;
    printf '1300\n' > "$d/sys/ens3/mtu";
    _e140_system_restore "$d/snapshot" || rc=1;
    test "$(_e214_mtu_current ens3)" = 1500 || rc=1;
    printf 'ens3|1400\n' > "$d/snapshot/e214-link-mtu.tsv";
    ! _e140_system_restore "$d/snapshot" > /dev/null 2>&1 || rc=1;
    rm -rf -- "$d";
    trap - EXIT;
    return "$rc" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_state_get_file
_e214_mtu_state_get_file() {
    local file="${1:-}" key="${2:-}";
    awk -F= -v wanted="$key" '
      $1==wanted {n++; value=substr($0,index($0,"=")+1)}
      END {if(n==1)print value; else exit 1}
    ' "$file" 2> /dev/null
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_state_validate
_e214_mtu_state_validate() {
    local state="${1:-$E214_MTU_STATE}" baseline="${2:-$E214_MTU_BASELINE}";
    local line key value count=0 version active selector configured target last hash epoch actual;
    local -A seen=();
    test -f "$state" && test ! -L "$state" && test -r "$state" && test -s "$state" || return 1;
    _e214_mtu_baseline_validate "$baseline" || return 1;
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([A-Za-z_][A-Za-z0-9_]*)=([A-Za-z0-9_.:-]+)$ ]] || return 1;
        key=${BASH_REMATCH[1]};
        value=${BASH_REMATCH[2]};
        case "$key" in 
            version | active | selector | configured_iface | target_mtu | last_iface | baseline_sha256 | updated_epoch)

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${seen[$key]+x}" || return 1;
        seen[$key]=1;
        count=$((count + 1));
    done < "$state";
    test "$count" -eq 8 || return 1;
    for key in version active selector configured_iface target_mtu last_iface baseline_sha256 updated_epoch;
    do
        test -n "${seen[$key]+x}" || return 1;
    done;
    version=$(_e214_mtu_state_get_file "$state" version) || return 1;
    active=$(_e214_mtu_state_get_file "$state" active) || return 1;
    selector=$(_e214_mtu_state_get_file "$state" selector) || return 1;
    configured=$(_e214_mtu_state_get_file "$state" configured_iface) || return 1;
    target=$(_e214_mtu_state_get_file "$state" target_mtu) || return 1;
    last=$(_e214_mtu_state_get_file "$state" last_iface) || return 1;
    hash=$(_e214_mtu_state_get_file "$state" baseline_sha256) || return 1;
    epoch=$(_e214_mtu_state_get_file "$state" updated_epoch) || return 1;
    test "$version" = 199e214 && test "$active" = 1 || return 1;
    case "$selector" in 
        auto)
            test "$configured" = - || return 1
        ;;
        iface)
            _e214_mtu_iface_valid "$configured" && test "$configured" = "$last" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    _e214_mtu_value_valid "$target" || return 1;
    _e214_mtu_iface_valid "$last" || return 1;
    [[ "$hash" =~ ^[0-9a-f]{64}$ ]] || return 1;
    [[ "$epoch" =~ ^[0-9]{1,20}$ ]] || return 1;
    actual=$(sha256sum "$baseline" 2> /dev/null | awk '{print $1}') || return 1;
    test "$actual" = "$hash" || return 1;
    awk -F'|' -v wanted="$last" '$1==wanted{n++}END{exit(n==1?0:1)}' "$baseline"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_status
_e214_mtu_status() {
    local default_iface iface mtu oper marker selector configured target last original actual resolved;
    title 'V199e266：宿主机网卡 MTU 状态（E214稳定所有权，只读）';
    default_iface=$(_e214_mtu_default_iface 2> /dev/null || true);
    echo '  E220行为: 第28项、完整127请求和小BBR均不设置宿主机网卡MTU。';
    echo '  E220策略: 沿用E214稳定所有权，只管理明确确认的宿主机出口；不管理wg/tun/WARP/Docker虚拟接口。';
    echo "  tcp_mtu_probing: $(sysctl -n net.ipv4.tcp_mtu_probing 2> /dev/null || echo unsupported)（不会改变网卡MTU）";
    hr;
    if _e214_mtu_any_state; then
        if _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE"; then
            selector=$(_e214_mtu_state_get_file "$E214_MTU_STATE" selector);
            configured=$(_e214_mtu_state_get_file "$E214_MTU_STATE" configured_iface);
            target=$(_e214_mtu_state_get_file "$E214_MTU_STATE" target_mtu);
            last=$(_e214_mtu_state_get_file "$E214_MTU_STATE" last_iface);
            actual=$(_e214_mtu_current "$last" 2> /dev/null || echo unavailable);
            original=$(awk -F'|' -v wanted="$last" '$1==wanted{print $2;exit}' "$E214_MTU_BASELINE");
            resolved=$(_e214_mtu_default_iface 2> /dev/null || true);
            echo "  owner: active  selector=$selector  configured=$configured";
            echo "  managed_iface=$last  target=$target  actual=$actual  original=$original";
            if test "$actual" != "$target"; then
                warn '运行态MTU与目标不一致；可执行菜单27→4立即复检。';
            fi;
            if _e214_mtu_persistence_validate; then
                echo '  persistence: service=enabled timer=enabled/active readback=ok';
            else
                warn '持久服务/定时器不完整；请用菜单27重新应用同一MTU修复。';
            fi;
            if test "$selector" = auto && test "$resolved" != "$last"; then
                warn "默认出口已变化：当前=${resolved:-none}，为防误改新网卡，自动复检不会接管；请重新确认应用。";
            fi;
        else
            error 'E214 MTU状态或基线损坏/不一致；拒绝自动写网卡。';
        fi;
    else
        echo '  owner: disabled（实际MTU由云平台/发行版/networkd/NetworkManager决定）';
    fi;
    hr;
    printf '  %-15s %-8s %-10s\n' 'interface' 'mtu' 'state/default';
    while IFS= read -r iface; do
        mtu=$(_e214_mtu_current "$iface" 2> /dev/null || echo '?');
        oper=$(tr -d '[:space:]' < "$(_e214_mtu_sysroot)/$iface/operstate" 2> /dev/null || echo '?');
        marker="$oper";
        test "$iface" != "$default_iface" || marker="$oper/default";
        printf '  %-15s %-8s %-10s\n' "$iface" "$mtu" "$marker";
    done < <(_e214_mtu_candidates);
    test -n "$default_iface" && echo "  当前自动识别出口：$default_iface" || warn '未能识别稳定的IPv4/IPv6默认出口。'
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_sysroot
_e214_mtu_sysroot() {
    printf '%s\n' "${E214_MTU_SYSFS_ROOT:-/sys/class/net}"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_transient_stop
_e214_mtu_transient_stop() {
    local unit="${1:-}";
    test -n "$unit" || return 0;
    systemctl stop "$unit.timer" "$unit.service" > /dev/null 2>&1 || true;
    systemctl reset-failed "$unit.timer" "$unit.service" > /dev/null 2>&1 || true
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_value_valid
_e214_mtu_value_valid() {
    local value="${1:-}";
    [[ "$value" =~ ^[0-9]+$ ]] && ((value >= 1280 && value <= 9000))
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_write_state_candidate
_e214_mtu_write_state_candidate() {
    local out="$1" baseline="$2" selector="$3" configured="$4" target="$5" last="$6" hash;
    _e214_mtu_baseline_validate "$baseline" || return 1;
    case "$selector" in 
        auto)
            test "$configured" = - || return 1
        ;;
        iface)
            _e214_mtu_iface_valid "$configured" && test "$configured" = "$last" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    _e214_mtu_value_valid "$target" && _e214_mtu_iface_valid "$last" || return 1;
    hash=$(sha256sum "$baseline" | awk '{print $1}') || return 1;
    { 
        printf 'version=199e214\n';
        printf 'active=1\n';
        printf 'selector=%s\n' "$selector";
        printf 'configured_iface=%s\n' "$configured";
        printf 'target_mtu=%s\n' "$target";
        printf 'last_iface=%s\n' "$last";
        printf 'baseline_sha256=%s\n' "$hash";
        printf 'updated_epoch=%s\n' "$(date +%s)"
    } > "$out" || return 1;
    chmod 0600 "$out" || return 1;
    _e214_mtu_state_validate "$out" "$baseline"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_mtu_write_unit_candidates
_e214_mtu_write_unit_candidates() {
    local service="$1" timer="$2";
    cat > "$service" <<EOF_E214_MTU_SERVICE
[Unit]
Description=Xray E214 host NIC MTU reconcile
Wants=network-online.target
After=network-online.target
Before=xray.service
ConditionPathExists=$E214_MTU_STATE

[Service]
Type=oneshot
ExecStart=/bin/bash $E214_SELF_PATH --mtu-reconcile

[Install]
WantedBy=multi-user.target
EOF_E214_MTU_SERVICE

    cat > "$timer" <<EOF_E214_MTU_TIMER
[Unit]
Description=Periodic Xray E214 host NIC MTU drift check

[Timer]
OnActiveSec=5min
OnUnitActiveSec=5min
AccuracySec=30s
Unit=$E214_MTU_UNIT

[Install]
WantedBy=timers.target
EOF_E214_MTU_TIMER

    chmod 0644 "$service" "$timer" || return 1;
    grep -Fqx 'Type=oneshot' "$service" && grep -Fqx "ExecStart=/bin/bash $E214_SELF_PATH --mtu-reconcile" "$service" && grep -Fqx 'WantedBy=multi-user.target' "$service" && ! grep -q 'RemainAfterExit' "$service" && grep -Fqx 'OnUnitActiveSec=5min' "$timer"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_new_tx
_e214_new_tx() {
    local purpose="${1:-transaction}" d start owner_pid="";
    owner_pid=$(_e242_tx_owner_pid) || return 1;
    _e214_prepare_tx || return 1;
    purpose=$(printf '%s' "$purpose" | tr -cd 'A-Za-z0-9._-' | cut -c1-48);
    test -n "$purpose" || purpose=transaction;
    d="$E214_TX_ROOT/${purpose}-$(date +%Y%m%d_%H%M%S)-${owner_pid}-$RANDOM";
    install -d -m 0700 "$d" || return 1;
    start=$(_e214_proc_start_time "$owner_pid" || true);
    [[ "$start" =~ ^[0-9]+$ ]] || { 
        rmdir -- "$d" 2> /dev/null || true;
        return 1
    };
    printf 'pid=%s\nstart=%s\n' "$owner_pid" "$start" > "$d/.active.env" || return 1;
    chmod 0600 "$d/.active.env" || return 1;
    :;
    printf '%s\n' "$d"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_prepare
_e214_prepare() {
    _e214_prepare_tx || return 1;
    install -d -m 0700 "$E214_DIR" || return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_prepare_tx
_e214_prepare_tx() {
    _e214_ensure_run_lock || return 1;
    install -d -m 0700 "$E214_TX_ROOT" "$(dirname -- "$E214_HOT_LOG")" || return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_preserve_tx
_e214_preserve_tx() {
    local backup="$1" reason="${2:-unspecified}" root real child tx tmp;
    root=$(readlink -f -- "$E214_TX_ROOT" 2> /dev/null || true);
    real=$(readlink -f -- "$backup" 2> /dev/null || true);
    test -n "$root" && test -d "$root" && test -n "$real" || return 1;
    case "$real" in 
        "$root"/*)
            child=${real#"$root"/};
            child=${child%%/*};
            test -n "$child" || return 1;
            tx="$root/$child"
        ;;
        *)
            return 1
        ;;
    esac;
    tmp="$tx/.preserve.env.new.$$";
    { 
        printf 'time=%s\n' "$(date '+%F %T %z')";
        printf 'reason=%s\n' "$(printf '%s' "$reason" | tr '\r\n' '  ')"
    } > "$tmp" || return 1;
    chmod 0600 "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -f -- "$tmp" "$tx/.preserve.env"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_proc_start_time
_e214_proc_start_time() {
    local pid="${1:-}";
    [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1;
    awk '{
      s=$0
      sub(/^.*\) /,"",s)
      n=split(s,a," ")
      if(n>=20 && a[20] ~ /^[0-9]+$/) print a[20]
    }' "/proc/$pid/stat" 2> /dev/null
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_prune_root
_e214_prune_root() {
    if test "${EEX3_NO_AUTO_GC:-0}" = 1; then
        return 0;
    fi;
    _eex3_retention_e214_prune_root "$@"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_prune_self_test
_e214_prune_self_test() {
    ( local d marker i count start;
    d=$(mktemp -d /tmp/xray-e214-prune.XXXXXX) || return 1;
    marker="$d/critical.env";
    for i in $(seq -w 1 13);
    do
        mkdir -p "$d/tx$i/system" || return 1;
        touch -d "@$((10#$i))" "$d/tx$i" || return 1;
    done;
    : > "$marker" || return 1;
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "$marker" > /dev/null 2>&1 || return 1;
    count=$(find "$d" -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ');
    test "$count" -eq 13 || return 1;
    printf 'backup=%s\nbackup=%s\n' "$d/tx01/system" "/tmp/outside-e214-snapshot" > "$marker" || return 1;
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "$marker" > /dev/null 2>&1 || return 1;
    count=$(find "$d" -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ');
    test "$count" -eq 13 || return 1;
    printf 'backup=%s\n' "$d/tx01/system" > "$marker" || return 1;
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "$marker" || return 1;
    test -d "$d/tx01" || return 1;
    count=$(find "$d" -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ');
    test "$count" -eq 13 || return 1;
    rm -f -- "$marker";
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1;
    count=$(find "$d" -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ');
    test "$count" -eq 12 || return 1;
    mkdir -p "$d/tx00" || return 1;
    printf 'reason=test\n' > "$d/tx00/.preserve.env" || return 1;
    touch -d '@0' "$d/tx00" || return 1;
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1;
    test -d "$d/tx00" || return 1;
    rm -f -- "$d/tx00/.preserve.env";
    touch -d '@0' "$d/tx00" || return 1;
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1;
    test ! -d "$d/tx00" || return 1;
    mkdir -p "$d/tx00" || return 1;
    : > "$d/tx00/.preserve.env" || return 1;
    touch -d '@0' "$d/tx00" || return 1;
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" > /dev/null 2>&1 || return 1;
    test -d "$d/tx00" || return 1;
    rm -f -- "$d/tx00/.preserve.env";
    ln -s /dev/null "$d/tx00/.preserve.env" || return 1;
    touch -d '@0' "$d/tx00" || return 1;
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" > /dev/null 2>&1 || return 1;
    test -d "$d/tx00" || return 1;
    rm -f -- "$d/tx00/.preserve.env";
    printf 'pid=bad\nstart=bad\n' > "$d/tx00/.active.env" || return 1;
    touch -d '@0' "$d/tx00" || return 1;
    ! XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" > /dev/null 2>&1 || return 1;
    test -d "$d/tx00" || return 1;
    printf 'pid=2147483647\nstart=1\n' > "$d/tx00/.active.env" || return 1;
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1;
    test ! -d "$d/tx00" || return 1;
    mkdir -p "$d/tx00" || return 1;
    start=$(_e214_proc_start_time 1 || true);
    [[ "$start" =~ ^[0-9]+$ ]] && kill -0 1 2> /dev/null || return 1;
    printf 'pid=1\nstart=%s\n' "$start" > "$d/tx00/.active.env" || return 1;
    touch -d '@0' "$d/tx00" || return 1;
    XRAY_E214_TX_KEEP=12 _e214_prune_root "$d" "" || return 1;
    test -d "$d/tx00" || return 1;
    rm -rf -- "$d" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_prune_transactions
_e214_prune_transactions() {
    if test "${EEX3_NO_AUTO_GC:-0}" = 1; then
        return 0;
    fi;
    _eex3_retention_e214_prune_transactions "$@"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_recovery_markers
_e214_recovery_markers() {
    printf '%s\t%s\n' E204 "$E204_CRITICAL_MARKER";
    printf '%s\t%s\n' E206 "$E214_LEGACY_E206_CRITICAL_MARKER";
    printf '%s\t%s\n' E208 "$E214_LEGACY_E208_CRITICAL_MARKER";
    printf '%s\t%s\n' E210 "$E214_LEGACY_E210_CRITICAL_MARKER";
    printf '%s\t%s\n' E212 "$E214_LEGACY_E212_CRITICAL_MARKER";
    printf '%s\t%s\n' E214 "$E214_CRITICAL_MARKER";
    printf '%s\t%s\n' E220-MSS "$E220_MSS_CRITICAL_MARKER"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_recovery_status
_e214_recovery_status() {
    local label marker found=0 count=0;
    title 'V199e266：严重恢复标记 / 受保护事务状态（只读）';
    while IFS='	' read -r label marker; do
        test -n "$marker" || continue;
        if test -e "$marker" || test -L "$marker"; then
            found=1;
            echo "  [$label] $marker";
            if test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker"; then
                sed -n '1,20s/^/      /p' "$marker" 2> /dev/null || true;
            else
                warn '该恢复标记为空、不可读、类型异常或为符号链接；按严重状态处理。';
            fi;
        fi;
    done < <(_e214_recovery_markers);
    for marker in "$E204_TX_ROOT" "$E214_LEGACY_E206_TX_ROOT" "$E214_LEGACY_E208_TX_ROOT" "$E214_LEGACY_E210_TX_ROOT" "$E214_LEGACY_E212_TX_ROOT" "$E214_TX_ROOT" "$(_e220_mss_tx_root 2> /dev/null || true)";
    do
        test -d "$marker" || continue;
        count=$(find "$marker" -mindepth 2 -maxdepth 2 -name .preserve.env -printf . 2> /dev/null | wc -c | tr -d ' ');
        test "${count:-0}" -eq 0 || echo "  [PRESERVE] $marker：${count}个事务被禁止自动清理";
    done;
    if ! _e220_mss_unresolved_report > /dev/null 2>&1; then
        found=1;
        echo '  [E220-MSS] 未关闭、失效或受保护的持久事务：';
        _e220_mss_unresolved_report || true;
    fi;
    if test "$found" -eq 0; then
        info '未发现E204/E206/E208/E210/E212/E214/E220-MSS严重恢复标记。';
    fi
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_self_test
_e214_self_test() {
    local rc=0 d spec total unique;
    echo 'V199e214 offline release gate:';
    bash -n "$SCRIPT_PATH" && echo '  [PASS] bash syntax' || { 
        echo '  [FAIL] bash syntax';
        rc=1
    };
    _e214_prune_self_test && echo '  [PASS] E206/E208/E210/E212/E214 fail-closed transaction retention' || { 
        echo '  [FAIL] E214 transaction pruning';
        rc=1
    };
    _e214_directory_mode_self_test && echo '  [PASS] shared/existing directory modes remain unchanged' || { 
        echo '  [FAIL] directory-mode preservation';
        rc=1
    };
    _e214_snapshot_match_self_test && echo '  [PASS] script-entry snapshot restore readback' || { 
        echo '  [FAIL] E214 script-entry snapshot readback';
        rc=1
    };
    _e214_mtu_self_test && echo '  [PASS] host-MTU selector/state/baseline/runtime/unit invariants' || { 
        echo '  [FAIL] host-MTU invariant';
        rc=1
    };
    _e214_mtu_snapshot_self_test && echo '  [PASS] host-MTU full-system snapshot/restore checksum boundary' || { 
        echo '  [FAIL] host-MTU snapshot boundary';
        rc=1
    };
    _e202_small_bbr_self_test > /dev/null && echo '  [PASS] eight exact 14/25/26-item small-BBR profiles' || { 
        echo '  [FAIL] small-BBR invariant';
        rc=1
    };
    _e202_inherited_core_self_test > /dev/null && echo '  [PASS] inherited Xray/WARP/QR behavior' || { 
        echo '  [FAIL] inherited core behavior';
        rc=1
    };
    E204_INTERNAL_SELF_TEST=1 _e188_summary_transaction_self_test > /dev/null && echo '  [PASS] one-summary/one-QR transaction' || { 
        echo '  [FAIL] one-summary/one-QR transaction';
        rc=1
    };
    _e204_advanced_tx_self_test && echo '  [PASS] menu-10 outer transaction rollback' || { 
        echo '  [FAIL] menu-10 transaction';
        rc=1
    };
    _e204_tc_menu_readonly_self_test && echo '  [PASS] TC menu enter/exit is read-only' || { 
        echo '  [FAIL] TC menu entry';
        rc=1
    };
    _e214_hot_rollback_self_test && echo '  [PASS] E214 hot-update rollback + single-commit path' || { 
        echo '  [FAIL] E214 hot rollback/commit';
        rc=1
    };
    d=$(mktemp -d /tmp/xray-e214-full-spec.XXXXXX) || return 1;
    spec="$d/spec.conf";
    _e159_full_spec fq 1 31 "$spec" || rc=1;
    total=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.]+[[:space:]]*=/{n++}END{print n+0}' "$spec");
    unique=$(awk -F= '/^[[:space:]]*[A-Za-z0-9_.]+[[:space:]]*=/{k=$1;gsub(/[[:space:]]/,"",k);a[k]=1}END{for(k in a)n++;print n+0}' "$spec");
    test "$total" -eq 125 && test "$unique" -eq 125 && grep -Fq 'Requested entries: 127 = 125 persistent controls + 1 write trigger + 1 semantic alias' "$spec" && grep -Eq '^net\.ipv4\.route\.flush[[:space:]]*=[[:space:]]*1$' "$spec" && echo '  [PASS] full-network spec 127 logical / 125 unique assignments' || { 
        echo "  [FAIL] full-network spec assignments=$total unique=$unique";
        rc=1
    };
    rm -rf -- "$d";
    _e214_structure_audit > /dev/null && echo '  [PASS] E214 final bindings/ownership gates' || { 
        echo '  [FAIL] E214 structure binding';
        rc=1
    };
    if test "$rc" -eq 0; then
        echo 'V199e214 result: PASS';
    else
        echo 'V199e214 result: FAIL';
    fi;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_snapshot_match_self_test
_e214_snapshot_match_self_test() {
    ( local d target snap;
    d=$(mktemp -d /tmp/xray-e214-snapshot.XXXXXX) || return 1;
    target="$d/entry";
    snap="$d/snap/entry";
    printf 'old\n' > "$target" || return 1;
    chmod 0755 "$target" || return 1;
    _e135_snapshot_file "$target" "$snap" || return 1;
    printf 'new\n' > "$target" || return 1;
    _e135_restore_file "$target" "$snap" || return 1;
    _e214_snapshot_matches "$target" "$snap" || return 1;
    rm -rf -- "$d" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_snapshot_matches
_e214_snapshot_matches() {
    local target="$1" snap="$2" smode tmode suid tuid sgid tgid;
    if test -L "$snap.present"; then
        test -L "$target" && test "$(readlink -- "$target")" = "$(readlink -- "$snap.present")";
    else
        if test -f "$snap.present"; then
            test -f "$target" && test ! -L "$target" && cmp -s "$snap.present" "$target" || return 1;
            smode=$(stat -c '%a' "$snap.present" 2> /dev/null || true);
            tmode=$(stat -c '%a' "$target" 2> /dev/null || true);
            suid=$(stat -c '%u' "$snap.present" 2> /dev/null || true);
            tuid=$(stat -c '%u' "$target" 2> /dev/null || true);
            sgid=$(stat -c '%g' "$snap.present" 2> /dev/null || true);
            tgid=$(stat -c '%g' "$target" 2> /dev/null || true);
            test "$smode:$suid:$sgid" = "$tmode:$tuid:$tgid";
        else
            if test -e "$snap.absent"; then
                test ! -e "$target" && test ! -L "$target";
            else
                return 1;
            fi;
        fi;
    fi
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_structure_audit
_e214_structure_audit() {
