    for id in _e214_install_self _e214_hot_verify _e214_structure_audit _e182_install_mode _e185_warp_health_check _e202_small_bbr_mode3f2 _e214_mtu_menu _e214_mtu_status _e214_mtu_set_interactive _e214_mtu_reconcile _e214_mtu_disable _e214_mtu_rollback_snapshot;
    do
