        _e202_small_bbr_validate_file "$conf" || rc=1;
        profile_id=$(_e202_small_bbr_profile_id_file "$conf" 2> /dev/null || true);
        test "$profile_id" = "$id" || rc=1;
        count=$(_e202_small_bbr_assignment_count "$conf");
        case "$id" in 
            mode1 | mode2 | mode3)
                test "$count" -eq 14 || rc=1
            ;;
            mode3f2)
                test "$count" -eq 26 || rc=1
            ;;
            *)
                test "$count" -eq 25 || rc=1
            ;;
        esac;
        grep -Fqx 'net.ipv4.tcp_adv_win_scale = 1' "$conf" || rc=1;
        ! grep -q '^net.ipv4.tcp_tw_reuse_delay[[:space:]]*=' "$conf" || rc=1;
        case "$id" in 
            mode1f | mode2f | mode3f | mode3f2 | modeb1)
                grep -Fqx 'net.ipv4.tcp_max_reordering = 300' "$conf" || rc=1;
                grep -Fqx 'net.ipv4.tcp_tw_reuse = 2' "$conf" || rc=1;
                grep -Fqx 'net.ipv4.tcp_recovery = 1' "$conf" || rc=1
            ;;
        esac;
        if test "$id" = mode3f2; then
            grep -Fqx 'net.core.rmem_default = 96695' "$conf" || rc=1;
            grep -Fqx 'net.core.wmem_default = 36215' "$conf" || rc=1;
            grep -Fqx 'net.core.rmem_max = 22977218' "$conf" || rc=1;
            grep -Fqx 'net.core.wmem_max = 22977218' "$conf" || rc=1;
            grep -Fqx 'net.ipv4.tcp_rmem = 4096 96695 22977218' "$conf" || rc=1;
            grep -Fqx 'net.ipv4.tcp_wmem = 4096 36215 22977218' "$conf" || rc=1;
            grep -Fqx 'net.ipv4.tcp_fin_timeout = 10' "$conf" || rc=1;
            grep -Fqx 'net.ipv4.tcp_max_tw_buckets = 8192' "$conf" || rc=1;
        else
            ! grep -q '^net.ipv4.tcp_max_tw_buckets[[:space:]]*=' "$conf" || rc=1;
        fi;
    done;
    rm -rf -- "$d";
    _e204_optimization_menu_audit > /dev/null || rc=1;
    if test "$rc" -eq 0; then
        echo '  result=PASS';
    else
        echo '  result=FAIL';
    fi;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_system_paths_base
_e214_system_paths_base() {
    _e204_system_paths_base;
    printf '%s\n' "$XRAY_BIN" "$CONFIG" "$PUBKEY_FILE" "$SNI_CACHE_FILE" "$INSTALL_DATE_FILE" "$SCRIPT_VERSION_FILE" "$USER_SNI_MAP" "$USER_TIME_MAP" "$DAT_DIR/geoip.dat" "$DAT_DIR/geosite.dat" "$CONFIG_DIR/xray_core_auto_update_disabled_e105.txt" /etc/systemd/system/xray.service /etc/systemd/system/xray.service.d "$E204_DIR" "$E204_SELF_PATH" "$E204_LATEST_PATH" /etc/resolv.conf /etc/dnsmasq.conf "${E67_DNS_MODE_FILE:-$CONFIG_DIR/dns_mode.txt}" /etc/fstab /etc/sysctl.d/98-xray-swap.conf /var/spool/cron/crontabs/root /var/spool/cron/root "$E204_ZRAM_SCRIPT" "$E204_ZRAM_SERVICE" "$E204_ZRAM_STATE"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_system_restore_base
_e214_system_restore_base() {
    local b="$1" rc=0;
    if test -e "$b/e204-services.env" || test -e "$b/e204-services.sha256"; then
        test -s "$b/e204-services.env" && test -s "$b/e204-services.sha256" && ( cd "$b" && sha256sum -c e204-services.sha256 > /dev/null 2>&1 ) || { 
            error "E204服务状态快照损坏：$b";
            return 1
        };
    fi;
    _e204_system_restore_base "$b" || rc=1;
    test ! -s "$b/e204-services.env" || _e204_services_restore_file "$b/e204-services.env" || rc=1;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_system_snapshot_base
_e214_system_snapshot_base() {
    local b="$1" unit;
    _e204_system_snapshot_base "$b" || return 1;
    : > "$b/e204-services.env" || return 1;
    while IFS= read -r unit; do
        test -n "$unit" || continue;
        _e204_service_snapshot "$unit" >> "$b/e204-services.env" || return 1;
    done < <(_e204_service_candidates | LC_ALL=C sort -u);
    test -s "$b/e204-services.env" || return 1;
    ( cd "$b" && sha256sum e204-services.env > e204-services.sha256 ) || return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_tx_close
_e214_tx_close() {
    local tx="${1:-}" root real;
    test -n "$tx" || return 0;
    root=$(readlink -f -- "$E214_TX_ROOT" 2> /dev/null || true);
    real=$(readlink -f -- "$tx" 2> /dev/null || true);
    test -n "$root" && test -d "$root" && test -n "$real" || return 1;
    case "$real" in 
        "$root"/*)
            rm -f -- "$real/.active.env"
        ;;
        *)
            error "拒绝关闭E214事务根目录外的标记：$tx";
            return 1
        ;;
    esac
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_write_generated_metadata_impl
_e214_write_generated_metadata_impl() {
    local internal="${1:-}" semantic="${E137_SEMANTIC_MODE:-}" meta tmp;
    test -n "$semantic" || semantic="$internal";
    meta="${E77_NODE_META_FILE:-$CONFIG_DIR/node.meta}";
    tmp=$(_e118_mktemp node-meta-e214) || return 1;
    { 
        echo "version=$E214_VERSION";
        echo "mode_semantic=$semantic";
        echo "mode_internal=$internal";
        echo "remark=${REMARK_NAME:-xp-reality}";
        echo "created=${E77_CTIME:-$(date -Is 2> /dev/null || date)}";
        echo "vlessenc_profile=${E79_VLESSENC_PROFILE:-none}";
        echo "vlessenc_network=${E79_VLESSENC_NETWORK:-none}";
        echo "vlessenc_actual_tuning=${E79_VLESSENC_ACTUAL_TUNING:-none}"
    } > "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$meta" 0600 || return 1;
    _e214_write_version
}
# EEX3-FUNCTION mtu_mss_e206_220 _e214_write_version
_e214_write_version() {
    local tmp;
    _e214_prepare || return 1;
    tmp=$(_e118_mktemp e214-version) || return 1;
    printf '%s\n' "$E214_VERSION" > "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$SCRIPT_VERSION_FILE" 0600
