# EEX3-FUNCTION mtu_mss_e206_220 _e216_help
_e216_help() {
    cat <<'EOF_E216_HELP'
V199e216:
  --hot-update                         事务热更新到E216
  --summary                            导出节点URI、一次终端QR及PNG/SVG
  --network-audit                      只读网络参数/重复定义审计
  --full-network-apply                 事务应用完整127条请求
  --small-bbr-menu                     八个精确14/25/26项档位菜单
  --small-bbr-enable|status|disable    启用、读回或恢复小BBR
  --mtu-menu|--mtu-status              宿主机MTU事务；菜单内含1350快捷档
  --mtu-reconcile|--mtu-disable        立即复检/恢复首次接管前MTU
  --mss-status                         只读核对MSS、MTU、后端、规则和持久服务
  --mss-enable|--mss-disable           菜单10→7同一套IPv4动态MSS事务
  --ipv6-disable|enable|status         IPv6永久策略（无IPv4时默认拒绝关闭）
  --warp-menu|--warp-global-menu       Xray层定向/全局WARP
  --warp-full-menu                     Cloudflare系统全隧道
  --micro-menu                         完整28项微操中心
  --structure-audit|--self-test        E216最终绑定审计/离线发行门禁
  --uninstall                          受控卸载（先恢复各事务基线）

升级顺序：先用当前旧脚本 --small-bbr-disable 并确认恢复，再下载/执行E216
热更新，完成后再启用小BBR。E216会拒绝覆盖仍处于active的旧小BBR。

MTU与MSS：菜单27的1350快捷档只改宿主默认出口，并有断线回滚、开机与
5分钟复检。MSS Clamp只缩小TCP SYN中的MSS通告，不会修改网卡MTU；
第28项和小BBR都不会自动开关MSS。WARP虚拟MTU仍由WARP模块独立管理。
EOF_E216_HELP

}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_apply_backend
_e216_mss_apply_backend() {
    local backend="${1:-}" tool jumps rules;
    tool=$(_e216_mss_tool_path "$backend") || return 1;
    _e216_mss_cleanup_backend "$backend" || return 1;
    modprobe iptable_mangle > /dev/null 2>&1 || true;
    modprobe xt_TCPMSS > /dev/null 2>&1 || true;
    "$tool" -w 5 -t mangle -N "$E216_MSS_CHAIN" > /dev/null 2>&1 || return 1;
    "$tool" -w 5 -t mangle -A "$E216_MSS_CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1 || return 1;
    "$tool" -w 5 -t mangle -I POSTROUTING 1 -j "$E216_MSS_CHAIN" > /dev/null 2>&1 || return 1;
    "$tool" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" > /dev/null 2>&1 || return 1;
    "$tool" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1 || return 1;
    jumps=$("$tool" -w 5 -t mangle -S POSTROUTING 2> /dev/null | grep -Ec -- "^-A POSTROUTING( .*)? -j $E216_MSS_CHAIN$" || true);
    rules=$("$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" 2> /dev/null | grep -Ec -- "^-A $E216_MSS_CHAIN .* -j TCPMSS --clamp-mss-to-pmtu$" || true);
    test "$jumps" -eq 1 && test "$rules" -eq 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_backend_readable
_e216_mss_backend_readable() {
    local tool;
    tool=$(_e216_mss_tool_path "${1:-}") || return 1;
    "$tool" -w 5 -t mangle -S > /dev/null 2>&1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_backend_state_validate
_e216_mss_backend_state_validate() {
    local file="${1:-$E216_MSS_BACKEND_STATE}" line key value count=0 version backend family mode epoch;
    local -A seen=();
    test -f "$file" && test ! -L "$file" && test -s "$file" || return 1;
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z_]+)=([A-Za-z0-9_.:-]+)$ ]] || return 1;
        key=${BASH_REMATCH[1]};
        value=${BASH_REMATCH[2]};
        case "$key" in 
            version | backend | family | mode | updated_epoch)

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${seen[$key]+x}" || return 1;
        seen[$key]=1;
        count=$((count + 1));
    done < "$file";
    test "$count" -eq 5 || return 1;
    for key in version backend family mode updated_epoch;
    do
        test -n "${seen[$key]+x}" || return 1;
    done;
    version=$(_e216_mss_state_value "$file" version) || return 1;
    backend=$(_e216_mss_state_value "$file" backend) || return 1;
    family=$(_e216_mss_state_value "$file" family) || return 1;
    mode=$(_e216_mss_state_value "$file" mode) || return 1;
    epoch=$(_e216_mss_state_value "$file" updated_epoch) || return 1;
    test "$version" = 199e216 && _e216_mss_backend_valid "$backend" && test "$family" = ipv4 && test "$mode" = clamp-to-pmtu && [[ "$epoch" =~ ^[0-9]{1,20}$ ]]
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_backend_valid
_e216_mss_backend_valid() {
    case "${1:-}" in 
        iptables | iptables-nft | iptables-legacy)
            return 0
        ;;
    esac;
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_build_script
_e216_mss_build_script() {
    local tool="${1:-}" out="${2:-}";
    case "$tool" in 
        /*)
            test -x "$tool" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    test -n "$out" || return 1;
    cat > "$out" <<EOF_E216_MSS_SCRIPT
#!/usr/bin/env bash
set -Eeuo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
IPT=$(printf '%q' "$tool")
CHAIN=$E216_MSS_CHAIN
modprobe iptable_mangle >/dev/null 2>&1 || true
modprobe xt_TCPMSS >/dev/null 2>&1 || true
while "\$IPT" -w 5 -t mangle -D POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; do :; done
while "\$IPT" -w 5 -t mangle -D POSTROUTING -j "\$CHAIN" >/dev/null 2>&1; do :; done
"\$IPT" -w 5 -t mangle -F "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -X "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -N "\$CHAIN"
"\$IPT" -w 5 -t mangle -A "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
"\$IPT" -w 5 -t mangle -I POSTROUTING 1 -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C POSTROUTING -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
! "\$IPT" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1
EOF_E216_MSS_SCRIPT

    chmod 0755 "$out" || return 1;
    bash -n "$out"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_build_units
_e216_mss_build_units() {
    local service="${1:-}" timer="${2:-}";
    test -n "$service" && test -n "$timer" || return 1;
    cat > "$service" <<EOF_E216_MSS_SERVICE
[Unit]
Description=Xray E216 verified IPv4 MSS Clamp restore
Wants=network-online.target
After=network-online.target

[Service]
Type=oneshot
ExecStart=$E216_MSS_SCRIPT

[Install]
WantedBy=multi-user.target
EOF_E216_MSS_SERVICE

    cat > "$timer" <<EOF_E216_MSS_TIMER
[Unit]
Description=Periodic Xray E216 IPv4 MSS Clamp reconciliation

[Timer]
OnBootSec=1min
OnUnitInactiveSec=5min
AccuracySec=30s
Persistent=true
Unit=$E216_MSS_SERVICE_UNIT

[Install]
WantedBy=timers.target
EOF_E216_MSS_TIMER

    chmod 0644 "$service" "$timer" || return 1;
    grep -Fqx 'Type=oneshot' "$service" && grep -Fqx "ExecStart=$E216_MSS_SCRIPT" "$service" && ! grep -q 'RemainAfterExit' "$service" && grep -Fqx 'OnUnitInactiveSec=5min' "$timer"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_candidate_order
_e216_mss_candidate_order() {
    local tool version="";
    tool=$(command -v iptables 2> /dev/null || true);
    if test -n "$tool"; then
        version=$("$tool" -V 2> /dev/null || true);
    fi;
    { 
        case "$version" in 
            *nf_tables*)
                echo iptables-nft
            ;;
            *legacy*)
                echo iptables-legacy
            ;;
        esac;
        echo iptables;
        echo iptables-nft;
        echo iptables-legacy
    } | awk 'NF&&!seen[$0]++'
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_cleanup_backend
_e216_mss_cleanup_backend() {
    local backend="${1:-}" tool line rc=0 direct_rc allow_direct=0;
    tool=$(_e216_mss_tool_path "$backend") || return 1;
    "$tool" -w 5 -t mangle -S > /dev/null 2>&1 || return 1;
    _e220_mss_backend_has_direct "$backend";
    direct_rc=$?;
    case "$direct_rc" in 
        0)
            if _e220_mss_legacy_direct_is_owned "$backend"; then
                allow_direct=1;
            else
                warn "保留管理员所有的裸TCPMSS规则：backend=$backend";
            fi
        ;;
        1)

        ;;
        *)
            return 1
        ;;
    esac;
    if test "$allow_direct" -eq 1; then
        while "$tool" -w 5 -t mangle -D POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1; do
            :;
        done;
    fi;
    while "$tool" -w 5 -t mangle -D POSTROUTING -j "$E216_MSS_CHAIN" > /dev/null 2>&1; do
        :;
    done;
    "$tool" -w 5 -t mangle -F "$E216_MSS_CHAIN" > /dev/null 2>&1 || true;
    "$tool" -w 5 -t mangle -X "$E216_MSS_CHAIN" > /dev/null 2>&1 || true;
    while IFS= read -r line; do
        [[ "$line" == *"-j $E216_MSS_CHAIN"* ]] && rc=1;
    done < <("$tool" -w 5 -t mangle -S POSTROUTING 2> /dev/null || true);
    "$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" > /dev/null 2>&1 && rc=1 || true;
    if test "$allow_direct" -eq 1; then
        _e220_mss_backend_has_direct "$backend" && rc=1 || test "$?" -eq 1 || rc=1;
    fi;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_disable
_e216_mss_disable() {
    local backend="" candidate selected_ok=0 readable=0 rc=0;
    if _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE"; then
        backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend) || return 1;
    else
        if test "$(cat "$E88_MSS_STATE_FILE" 2> /dev/null || true)" = ON; then
            backend=$(_e216_mss_discover_backend 2> /dev/null || true);
            test -n "$backend" || { 
                error '历史MSS状态为ON，但未找到可验证的真实规则后端；拒绝声称已完整关闭。';
                return 1
            };
            warn "检测到历史MSS规则，按真实运行态接管后关闭：backend=$backend";
        fi;
    fi;
    systemctl disable --now "$E216_MSS_TIMER_UNIT" "$E216_MSS_SERVICE_UNIT" > /dev/null 2>&1 || true;
    for candidate in iptables iptables-nft iptables-legacy;
    do
        _e216_mss_backend_readable "$candidate" || continue;
        readable=$((readable + 1));
        if _e216_mss_cleanup_backend "$candidate"; then
            test "$candidate" != "$backend" || selected_ok=1;
        else
            rc=1;
        fi;
    done;
    if test -n "$backend" && test "$selected_ok" -ne 1; then
        error "无法在记录后端 $backend 证明MSS规则已删除。";
        rc=1;
    fi;
    if test "$rc" -ne 0; then
        return 1;
    fi;
    rm -f -- "$E216_MSS_SERVICE" "$E216_MSS_TIMER" "$E216_MSS_SCRIPT" "$E216_MSS_BACKEND_STATE" 2> /dev/null || return 1;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    _e216_mss_write_legacy_state OFF || return 1;
    systemctl is-enabled --quiet "$E216_MSS_TIMER_UNIT" 2> /dev/null && return 1 || true;
    info "IPv4 MSS Clamp已关闭并清理可读xtables后端（checked=$readable）。"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_discover_backend
_e216_mss_discover_backend() {
    local candidate tool;
    while IFS= read -r candidate; do
        tool=$(_e216_mss_tool_path "$candidate" 2> /dev/null || true);
        test -n "$tool" || continue;
        if "$tool" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" > /dev/null 2>&1 && "$tool" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1; then
            printf '%s\n' "$candidate";
            return 0;
        fi;
        if "$tool" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1; then
            printf '%s\n' "$candidate";
            return 0;
        fi;
    done < <(_e216_mss_candidate_order);
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_enable
_e216_mss_enable() {
    ( local d backend="" candidate tool pair save restore snapshot state_c service_c timer_c rc=0;
    _e216_prepare || return 1;
    test -d /run/systemd/system || { 
        error 'systemd未运行，不能安全持久化MSS Clamp。';
        return 1
    };
    d=$(mktemp -d /tmp/xray-e216-mss.XXXXXX) || return 1;
    trap 'rm -rf -- "${d:-}"' EXIT;
    while IFS= read -r candidate; do
        _e216_mss_backend_readable "$candidate" || continue;
        pair=$(_e216_mss_save_restore_paths "$candidate" 2> /dev/null || true);
        test -n "$pair" || continue;
        save=${pair%%|*};
        restore=${pair#*|};
        snapshot="$d/$candidate.rules";
        "$save" > "$snapshot" 2> /dev/null || continue;
        if _e216_mss_apply_backend "$candidate"; then
            backend=$candidate;
            break;
        fi;
        "$restore" < "$snapshot" > /dev/null 2>&1 || { 
            error "MSS后端试写失败且规则恢复失败：$candidate";
            return 1
        };
    done < <(_e216_mss_candidate_order);
    test -n "$backend" || { 
        error '没有同时具备可读、可写、可快照/恢复能力的IPv4 xtables后端；MSS Clamp未修改。';
        return 1
    };
    tool=$(_e216_mss_tool_path "$backend") || return 1;
    pair=$(_e216_mss_save_restore_paths "$backend") || return 1;
    restore=${pair#*|};
    snapshot="$d/$backend.rules";
    test -s "$snapshot" || return 1;
    service_c="$d/service";
    timer_c="$d/timer";
    state_c="$d/state";
    _e216_mss_build_script "$tool" "$d/script" || rc=1;
    test "$rc" -ne 0 || _e216_mss_build_units "$service_c" "$timer_c" || rc=1;
    if test "$rc" -eq 0; then
        _e118_atomic_install "$d/script" "$E216_MSS_SCRIPT" 0755 || rc=1;
        test "$rc" -ne 0 || _e118_atomic_install "$service_c" "$E216_MSS_SERVICE" 0644 || rc=1;
        test "$rc" -ne 0 || _e118_atomic_install "$timer_c" "$E216_MSS_TIMER" 0644 || rc=1;
        test "$rc" -ne 0 || _e216_mss_write_backend_state "$backend" || rc=1;
        test "$rc" -ne 0 || _e216_mss_write_legacy_state ON || rc=1;
    fi;
    test "$rc" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || systemctl enable "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || systemctl start "$E216_MSS_SERVICE_UNIT" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || systemctl start "$E216_MSS_TIMER_UNIT" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || _e216_mss_verify_on || rc=1;
    if test "$rc" -ne 0; then
        "$restore" < "$snapshot" > /dev/null 2>&1 || error "MSS失败后防火墙快照恢复失败：$snapshot";
        error 'MSS Clamp应用、服务或运行态读回失败；外围事务将恢复全部文件与服务。';
        return 1;
    fi;
    info "IPv4 MSS Clamp已验证：backend=$backend，单一POSTROUTING跳转，动态clamp-to-pmtu，5分钟复检。" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_save_restore_paths
_e216_mss_save_restore_paths() {
    local backend="${1:-}" save restore;
    _e216_mss_backend_valid "$backend" || return 1;
    case "$backend" in 
        iptables)
            save=iptables-save;
            restore=iptables-restore
        ;;
        iptables-nft)
            save=iptables-nft-save;
            restore=iptables-nft-restore
        ;;
        iptables-legacy)
            save=iptables-legacy-save;
            restore=iptables-legacy-restore
        ;;
    esac;
    save=$(command -v "$save" 2> /dev/null || true);
    restore=$(command -v "$restore" 2> /dev/null || true);
    case "$save:$restore" in 
        /*:/*)
            test -x "$save" && test -x "$restore" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    printf '%s|%s\n' "$save" "$restore"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_self_test
_e216_mss_self_test() {
    ( local d state script service timer rc=0;
    d=$(mktemp -d /tmp/xray-e216-mss-selftest.XXXXXX) || return 1;
    trap 'rm -rf -- "${d:-}"' EXIT;
    mkdir -p "$d/e216" || return 1;
    state="$d/e216/mss-backend.env";
    { 
        echo version=199e216;
        echo backend=iptables-nft;
        echo family=ipv4;
        echo mode=clamp-to-pmtu;
        echo updated_epoch=1780000000
    } > "$state";
    _e216_mss_backend_state_validate "$state" || rc=1;
    sed -i 's/backend=iptables-nft/backend=bad/' "$state";
    ! _e216_mss_backend_state_validate "$state" || rc=1;
    script="$d/script";
    service="$d/service";
    timer="$d/timer";
    _e216_mss_build_script /bin/true "$script" || rc=1;
    _e216_mss_build_units "$service" "$timer" || rc=1;
    bash -n "$script" || rc=1;
    grep -Fq -- '--clamp-mss-to-pmtu' "$script" || rc=1;
    grep -Fq -- '-I POSTROUTING 1' "$script" || rc=1;
    grep -Fq -- '-D POSTROUTING -p tcp' "$script" || rc=1;
    grep -Fq -- '! "$IPT" -w 5 -t mangle -C POSTROUTING -p tcp' "$script" || rc=1;
    ! grep -Fq -- '--set-mss' "$script" || rc=1;
    grep -Fqx 'OnUnitInactiveSec=5min' "$timer" || rc=1;
    ! grep -q 'RemainAfterExit' "$service" || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_state_value
_e216_mss_state_value() {
    local file="${1:-}" key="${2:-}";
    awk -F= -v wanted="$key" '$1==wanted{n++;v=substr($0,index($0,"=")+1)}END{if(n==1)print v;else exit 1}' "$file" 2> /dev/null
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_status
_e216_mss_status() {
    local default_iface mtu mss4 mss6 state backend="" candidate tool jump rule direct readable=0;
    title 'V199e216：MSS Clamp / MTU 关系与运行态（只读）';
    default_iface=$(_e214_mtu_default_iface 2> /dev/null || true);
    mtu=$(_e214_mtu_current "$default_iface" 2> /dev/null || true);
    if [[ "$mtu" =~ ^[0-9]+$ ]] && ((mtu >= 1280)); then
        mss4=$((mtu - 40));
        mss6=$((mtu - 60));
        echo "  默认出口=${default_iface:-unknown}  MTU=$mtu  名义IPv4 MSS=$mss4  名义IPv6 MSS=$mss6";
    else
        echo "  默认出口=${default_iface:-unknown}  MTU=${mtu:-unknown}";
    fi;
    echo '  Clamp方式：仅改TCP SYN内的MSS通告，使用路径MTU动态计算；不改网卡MTU。';
    echo '  范围：E216独立管理IPv4 POSTROUTING；IPv6、WARP虚拟MTU与宿主MTU由各自模块管理。';
    echo '  第28项和小BBR不会自动开关MSS Clamp。';
    hr;
    state=$(cat "$E88_MSS_STATE_FILE" 2> /dev/null || echo UNSET);
    if _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE"; then
        backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend);
    fi;
    echo "  owner_state=$state  recorded_backend=${backend:-none}";
    for candidate in iptables iptables-nft iptables-legacy;
    do
        tool=$(_e216_mss_tool_path "$candidate" 2> /dev/null || true);
        test -n "$tool" || continue;
        if ! "$tool" -w 5 -t mangle -S > /dev/null 2>&1; then
            printf '  %-17s %s\n' "$candidate" 'unreadable/no-CAP_NET_ADMIN';
            continue;
        fi;
        readable=$((readable + 1));
        jump=0;
        rule=0;
        direct=0;
        "$tool" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" > /dev/null 2>&1 && jump=1 || true;
        "$tool" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1 && rule=1 || true;
        "$tool" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1 && direct=1 || true;
        printf '  %-17s jump=%s rule=%s legacy_direct=%s%s\n' "$candidate" "$jump" "$rule" "$direct" "$(test "$candidate" = "$backend" && echo ' [owner]' || true)";
    done;
    test "$readable" -gt 0 || warn '没有可读xtables后端；不能把状态文件当作规则已生效的证明。';
    if test "$state" = ON; then
        if _e216_mss_verify_on; then
            info 'MSS Clamp状态、后端、规则、服务与定时器一致。';
        else
            error 'MSS Clamp存在状态/规则/服务脱节；请从菜单10→7重新启用或关闭。';
        fi;
    fi
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_tool_path
_e216_mss_tool_path() {
    local name="${1:-}" path;
    _e216_mss_backend_valid "$name" || return 1;
    path=$(command -v "$name" 2> /dev/null || true);
    case "$path" in 
        /*)
            test -x "$path" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    test "${path##*/}" = "$name" || return 1;
    printf '%s\n' "$path"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_verify_on
_e216_mss_verify_on() {
    local backend tool jumps rules direct;
    test "$(cat "$E88_MSS_STATE_FILE" 2> /dev/null || true)" = ON || return 1;
    _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE" || return 1;
    backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend) || return 1;
    tool=$(_e216_mss_tool_path "$backend") || return 1;
    test -f "$E216_MSS_SCRIPT" && test ! -L "$E216_MSS_SCRIPT" && bash -n "$E216_MSS_SCRIPT" || return 1;
    test -f "$E216_MSS_SERVICE" && test ! -L "$E216_MSS_SERVICE" && test -f "$E216_MSS_TIMER" && test ! -L "$E216_MSS_TIMER" || return 1;
    grep -Fqx "IPT=$(printf '%q' "$tool")" "$E216_MSS_SCRIPT" || return 1;
    systemctl is-enabled --quiet "$E216_MSS_SERVICE_UNIT" 2> /dev/null || return 1;
    systemctl is-enabled --quiet "$E216_MSS_TIMER_UNIT" 2> /dev/null || return 1;
    systemctl is-active --quiet "$E216_MSS_TIMER_UNIT" 2> /dev/null || return 1;
    test "$(systemctl show "$E216_MSS_SERVICE_UNIT" -p Result --value 2> /dev/null || true)" = success || return 1;
    "$tool" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" > /dev/null 2>&1 || return 1;
    "$tool" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1 || return 1;
    jumps=$("$tool" -w 5 -t mangle -S POSTROUTING 2> /dev/null | grep -Ec -- "^-A POSTROUTING( .*)? -j $E216_MSS_CHAIN$" || true);
    rules=$("$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" 2> /dev/null | grep -Ec -- "^-A $E216_MSS_CHAIN .* -j TCPMSS --clamp-mss-to-pmtu$" || true);
    direct=$("$tool" -w 5 -t mangle -S POSTROUTING 2> /dev/null | grep -Ec -- '^-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu$' || true);
    test "$jumps" -eq 1 && test "$rules" -eq 1 && test "$direct" -eq 0
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_write_backend_state
_e216_mss_write_backend_state() {
    local backend="${1:-}" tmp;
    _e216_mss_backend_valid "$backend" || return 1;
    _e216_prepare || return 1;
    tmp=$(_e118_mktemp e216-mss-backend) || return 1;
    { 
        printf 'version=199e216\n';
        printf 'backend=%s\n' "$backend";
        printf 'family=ipv4\n';
        printf 'mode=clamp-to-pmtu\n';
        printf 'updated_epoch=%s\n' "$(date +%s)"
    } > "$tmp" || return 1;
    chmod 0600 "$tmp" || return 1;
    _e216_mss_backend_state_validate "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$E216_MSS_BACKEND_STATE" 0600
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_mss_write_legacy_state
_e216_mss_write_legacy_state() {
    local value="${1:-}" tmp;
    case "$value" in 
        ON | OFF)

        ;;
        *)
            return 1
        ;;
    esac;
    _e216_prepare || return 1;
    tmp=$(_e118_mktemp e216-mss-state) || return 1;
    printf '%s\n' "$value" > "$tmp" || return 1;
    chmod 0600 "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$E88_MSS_STATE_FILE" 0600
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_prepare
_e216_prepare() {
    _e214_prepare || return 1;
    test ! -L "$E216_DIR" || { 
        error "拒绝使用符号链接目录：$E216_DIR";
        return 1
    };
    _e214_ensure_directory "$E216_DIR" 0700 || return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_self_test
_e216_self_test() {
    local rc=0;
    _e214_self_test || rc=1;
    _e216_mss_self_test && echo '  [PASS] E216 MSS backend/state/script/unit invariants' || { 
        echo '  [FAIL] E216 MSS invariant';
        rc=1
    };
    _e216_structure_audit > /dev/null && echo '  [PASS] E216 identity/MTU1350/MSS final bindings' || { 
        echo '  [FAIL] E216 final binding';
        rc=1
    };
    if test "$rc" -eq 0; then
        echo 'V199e216 result: PASS';
    else
        echo 'V199e216 result: FAIL';
    fi;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e216_structure_audit
_e216_structure_audit() {
    local rc=0 menu mtu_menu installer paths;
    _e214_structure_audit > /dev/null || rc=1;
    menu=$(declare -f _e214_main_menu 2> /dev/null || true);
    mtu_menu=$(declare -f _e214_mtu_menu 2> /dev/null || true);
    installer=$(declare -f _e214_install_self 2> /dev/null || true);
    paths=$(declare -f _e138_system_paths 2> /dev/null || true);
    echo 'V199e216 structure audit:';
    test "$SCRIPT_VERSION" = 199e216 && test "$E216_VERSION" = 199e216 || rc=1;
    grep -q 'V199e216 - 事务稳态版' <<< "$menu" || rc=1;
    grep -q 'MTU=1350' <<< "$mtu_menu" || rc=1;
    grep -q '_e214_mtu_set_interactive auto - 1350' <<< "$mtu_menu" || rc=1;
    grep -q 'E216_SELF_PATH' <<< "$installer" || rc=1;
    grep -q 'E216_MSS_BACKEND_STATE' <<< "$paths" || rc=1;
    for f in _e216_mss_enable _e216_mss_disable _e216_mss_status _e216_mss_verify_on _e216_mss_build_script _e216_mss_backend_state_validate;
    do
        declare -F "$f" > /dev/null 2>&1 || rc=1;
    done;
    grep -Fq -- '--mss-status)' "$SCRIPT_PATH" || rc=1;
    grep -Fq -- '--e216-summary)' "$SCRIPT_PATH" || rc=1;
    if test "$rc" -eq 0; then
        echo '  result=PASS';
    else
        echo '  result=FAIL';
    fi;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_help
_e218_help() {
    cat <<'EOF_E218_HELP'
V199e218:
  --hot-update                         事务热更新到E218
  --summary                            导出节点URI、一次终端QR及PNG/SVG
  --network-audit                      只读网络参数/重复定义审计
  --full-network-apply                 事务应用完整127条请求
  --small-bbr-menu                     八个精确14/25/26项档位菜单
  --small-bbr-enable|status|disable    启用、读回或恢复小BBR
  --mtu-menu|--mtu-status              宿主机MTU事务；菜单内含1350快捷档
  --mtu-reconcile|--mtu-disable        立即复检/恢复首次接管前MTU
  --mss-status                         只读核对MSS、MTU、后端、规则和持久服务
  --mss-enable|--mss-disable           菜单10→7同一套IPv4动态MSS事务
  --ipv6-disable|enable|status         IPv6永久策略（无IPv4时默认拒绝关闭）
  --warp-menu|--warp-global-menu       Xray层定向/全局WARP
  --warp-full-menu                     Cloudflare系统全隧道
  --micro-menu                         完整28项微操中心
  --structure-audit|--self-test        E218最终绑定审计/离线发布门禁
  --uninstall                          受控卸载（先恢复各事务基线）

推荐工作流：
  新装：安装/新建节点 -> 菜单10→6→第28项 -> 重启 -> 小BBR。
  升级：必须先用当前旧脚本 --small-bbr-disable 并读回恢复，
        再下载/热更新E218，最后重新启用小BBR。新版不猜旧快照。
  MTU：仅在确认有隧道封装、PMTU黑洞或大包卡顿时使用菜单27的1350档；
       1350不是DDoS/暴力破解防护。

MTU与MSS：MTU=1350时无选项头的名义IPv4 MSS约1310。MSS Clamp只改
新TCP握手中的MSS通告，不改网卡MTU，不影响UDP；第28项和小BBR不会
暗中开关MSS。E218对MSS做固定后端、规则快照、失败回滚和OFF残留读回。
EOF_E218_HELP

}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_any_evidence
_e218_mss_any_evidence() {
    _e218_mss_static_evidence || _e218_mss_runtime_evidence
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_backend_has_owned
_e218_mss_backend_has_owned() {
    local backend="${1:-}" rc;
    _e220_mss_backend_has_managed "$backend";
    rc=$?;
    case "$rc" in 
        0)
            return 0
        ;;
        1)

        ;;
        *)
            return 2
        ;;
    esac;
    _e220_mss_backend_has_direct "$backend";
    rc=$?;
    case "$rc" in 
        0)
            _e220_mss_legacy_direct_is_owned "$backend" && return 0 || return 1
        ;;
        1)
            return 1
        ;;
        *)
            return 2
        ;;
    esac
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_backend_identity
_e218_mss_backend_identity() {
    local tool actual;
    tool=$(_e216_mss_tool_path "${1:-}") || return 1;
    actual=$(readlink -f -- "$tool" 2> /dev/null || true);
    case "$actual" in 
        /*)
            test -x "$actual" && test ! -L "$actual" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    printf '%s\n' "$actual"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_backend_identity_matches
_e218_mss_backend_identity_matches() {
    local backend="${1:-}" expected="${2:-}" actual;
    [[ "$expected" =~ ^/[A-Za-z0-9_./+-]+$ ]] || return 1;
    actual=$(_e218_mss_backend_identity "$backend" 2> /dev/null || true);
    test -n "$actual" && test "$actual" = "$expected"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_build_script
_e218_mss_build_script() {
    local tool_path="${1:-}" tool_identity="${2:-}" out="${3:-}" actual;
    [[ "$tool_path" =~ ^/[A-Za-z0-9_./+-]+$ ]] && test -x "$tool_path" || return 1;
    [[ "$tool_identity" =~ ^/[A-Za-z0-9_./+-]+$ ]] && test -x "$tool_identity" && test ! -L "$tool_identity" || return 1;
    actual=$(readlink -f -- "$tool_path" 2> /dev/null || true);
    test "$actual" = "$tool_identity" && test -n "$out" && test ! -L "$out" || return 1;
    cat > "$out" <<EOF_E220_MSS_SCRIPT
#!/usr/bin/env bash
set -Eeuo pipefail
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
IPT=$(printf '%q' "$tool_path")
IDENTITY=$(printf '%q' "$tool_identity")
CHAIN=$E216_MSS_CHAIN
test -x "\$IPT"
test "\$(readlink -f -- "\$IPT" 2>/dev/null || true)" = "\$IDENTITY"
modprobe iptable_mangle >/dev/null 2>&1 || true
modprobe xt_TCPMSS >/dev/null 2>&1 || true
if "\$IPT" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1; then
    echo 'unowned direct TCPMSS rule collision; refusing destructive reconcile' >&2
    exit 73
fi
while "\$IPT" -w 5 -t mangle -D POSTROUTING -j "\$CHAIN" >/dev/null 2>&1; do :; done
"\$IPT" -w 5 -t mangle -F "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -X "\$CHAIN" >/dev/null 2>&1 || true
"\$IPT" -w 5 -t mangle -N "\$CHAIN"
"\$IPT" -w 5 -t mangle -A "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
"\$IPT" -w 5 -t mangle -I POSTROUTING 1 -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C POSTROUTING -j "\$CHAIN"
"\$IPT" -w 5 -t mangle -C "\$CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
! "\$IPT" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu >/dev/null 2>&1
EOF_E220_MSS_SCRIPT

    chmod 0755 "$out" || return 1;
    bash -n "$out" || return 1;
    grep -Fqx "IPT=$(printf '%q' "$tool_path")" "$out" && grep -Fqx "IDENTITY=$(printf '%q' "$tool_identity")" "$out" && grep -Fq 'exit 73' "$out" && ! grep -Fq -- '-D POSTROUTING -p tcp' "$out"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_capture_backends
_e218_mss_capture_backends() {
    local d="${1:-}" list="${2:-}" candidate identity pair save save_identity restore restore_identity snapshot idx=0 owned_rc;
    local -A seen=();
    test -n "$d" && test -n "$list" || return 1;
    : > "$list" || return 1;
    while IFS= read -r candidate; do
        _e216_mss_backend_readable "$candidate" || continue;
        identity=$(_e218_mss_backend_identity "$candidate" 2> /dev/null || true);
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue;
        seen[$identity]=1;
        pair=$(_e216_mss_save_restore_paths "$candidate" 2> /dev/null || true);
        if test -z "$pair"; then
            _e218_mss_backend_has_owned "$candidate";
            owned_rc=$?;
            case "$owned_rc" in 
                0)
                    error "后端 $candidate 存在MSS规则，但缺少配套save/restore；拒绝无快照修改。";
                    return 1
                ;;
                1)
                    continue
                ;;
                *)
                    error "后端 $candidate 在快照前失去可读性。";
                    return 1
                ;;
            esac;
        fi;
        save=${pair%%|*};
        restore=${pair#*|};
        save_identity=$(_e218_mss_path_identity "$save" 2> /dev/null || true);
        restore_identity=$(_e218_mss_path_identity "$restore" 2> /dev/null || true);
        if test -z "$save_identity" || test -z "$restore_identity"; then
            error "后端 $candidate 的save/restore实体不可固定；拒绝无身份快照。";
            return 1;
        fi;
        idx=$((idx + 1));
        snapshot="$d/firewall-$idx.rules";
        if ! "$save" > "$snapshot" 2> /dev/null; then
            _e218_mss_backend_has_owned "$candidate";
            owned_rc=$?;
            case "$owned_rc" in 
                0)
                    error "后端 $candidate 存在MSS规则，但快照失败；拒绝修改。";
                    return 1
                ;;
                1)
                    rm -f -- "$snapshot";
                    continue
                ;;
                *)
                    error "后端 $candidate 在快照失败后无法读回。";
                    return 1
                ;;
            esac;
        fi;
        test "$(_e218_mss_path_identity "$save" 2> /dev/null || true)" = "$save_identity" || return 1;
        test "$(_e218_mss_path_identity "$restore" 2> /dev/null || true)" = "$restore_identity" || return 1;
        printf '%s|%s|%s|%s|%s|%s|%s\n' "$candidate" "$identity" "$save" "$save_identity" "$restore" "$restore_identity" "$snapshot" >> "$list" || return 1;
    done < <(_e216_mss_candidate_order);
    test -s "$list"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_capture_control
_e218_mss_capture_control() {
    local d="${1:-}" path snap unit;
    test -n "$d" || return 1;
    install -d -m 0700 "$d/control" || return 1;
    : > "$d/control/manifest" || return 1;
    for path in "$E88_MSS_STATE_FILE" "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" "$E216_MSS_SCRIPT" "$E216_MSS_SERVICE" "$E216_MSS_TIMER";
    do
        snap="$d/control/$(printf '%s' "$path" | sha256sum | awk '{print $1}')";
        _e135_snapshot_file "$path" "$snap" || return 1;
        printf '%s|%s\n' "$path" "$snap" >> "$d/control/manifest" || return 1;
    done;
    : > "$d/control/services.env" || return 1;
    for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT";
    do
        _e204_service_snapshot "$unit" >> "$d/control/services.env" || return 1;
    done;
    ( cd "$d/control" && sha256sum manifest services.env > control.sha256 ) || return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_captured_exclusive
_e218_mss_captured_exclusive() {
    local list="${1:-}" selected="${2:-}" backend identity save save_identity restore restore_identity snapshot rc owners=0;
    test -s "$list" && _e216_mss_backend_valid "$selected" || return 1;
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        _e218_mss_backend_identity_matches "$backend" "$identity" || return 1;
        _e216_mss_backend_readable "$backend" || return 1;
        _e218_mss_backend_has_owned "$backend";
        rc=$?;
        if test "$backend" = "$selected"; then
            test "$rc" -eq 0 || return 1;
            owners=$((owners + 1));
        else
            test "$rc" -eq 1 || return 1;
        fi;
    done < "$list";
    test "$owners" -eq 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_captured_off
_e218_mss_captured_off() {
    local list="${1:-}" backend identity save save_identity restore restore_identity snapshot rc;
    test -s "$list" || return 1;
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        _e218_mss_backend_identity_matches "$backend" "$identity" || return 1;
        _e216_mss_backend_readable "$backend" || return 1;
        _e218_mss_backend_has_owned "$backend";
        rc=$?;
        test "$rc" -eq 1 || return 1;
    done < "$list"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_cleanup_captured
_e218_mss_cleanup_captured() {
    local list="${1:-}" backend identity save save_identity restore restore_identity snapshot;
    test -s "$list" || return 1;
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        _e218_mss_backend_identity_matches "$backend" "$identity" || return 1;
        _e216_mss_cleanup_backend "$backend" || return 1;
    done < "$list"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_consistency
_e218_mss_consistency() {
    local state;
    state=$(_e218_mss_owner_state 2> /dev/null || echo INVALID);
    case "$state" in 
        ON)
            _e218_mss_verify_on
        ;;
        OFF | UNSET)
            ! _e218_mss_static_evidence && ! _e218_mss_runtime_evidence
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_disable
_e218_mss_disable() {
    ( local d="" list="" evidence=0 state rc=0 path unit;
    local snapshot_ready=0 finished=0 phase=created;
    function _e220_mss_exit_guard () 
    { 
        local status="${1:-1}" rollback_rc=0;
        trap - EXIT HUP INT TERM;
        if test "$finished" -eq 0 && test "$snapshot_ready" -eq 1 && test -n "$d"; then
            phase=$(cat "$d/.phase" 2> /dev/null || echo unknown);
            if _e220_mss_rollback "$d" "$list" "$phase"; then
                _e218_mss_log "action=disable result=failed rollback=ok snapshot=$d phase=$phase";
                info "MSS关闭失败已恢复操作前控制文件、规则与服务；快照：$d";
                _e220_mss_tx_close "$d" rolled-back || rollback_rc=1;
            else
                rollback_rc=1;
            fi;
            if test "$rollback_rc" -ne 0; then
                _e220_mss_mark_critical "$d" 'MSS disable rollback/readback failed' || true;
                _e220_mss_tx_close "$d" critical > /dev/null 2>&1 || true;
                _e218_mss_log "action=disable result=critical snapshot=$d phase=$phase";
                error "严重：MSS关闭回滚未完整通过；已保留持久快照：$d";
            fi;
        else
            if test "$finished" -eq 0 && test -n "$d"; then
                _e220_mss_tx_close "$d" no-mutation > /dev/null 2>&1 || true;
            fi;
        fi;
        [[ "$status" =~ ^[0-9]+$ ]] || status=1;
        test "$status" -ne 0 || status=1;
        exit "$status"
    };
    trap '_e220_mss_exit_guard $?' EXIT;
    trap 'exit 129' HUP;
    trap 'exit 130' INT;
    trap 'exit 143' TERM;
    _e220_mss_preflight_readonly || return 1;
    _e220_prepare || return 1;
    _e218_mss_any_evidence && evidence=1 || true;
    if test "$evidence" -eq 0; then
        finished=1;
        trap - EXIT HUP INT TERM;
        info 'IPv4 MSS Clamp未启用，也未发现可读残留。';
        return 0;
    fi;
    test -d /run/systemd/system || { 
        error 'systemd未运行，拒绝声称已完整关闭MSS。';
        return 1
    };
    _e214_ensure_run_lock || return 1;
    exec 209> "$E218_MSS_LOCK" || return 1;
    flock -n 209 || { 
        error '已有MSS Clamp事务正在运行。';
        return 1
    };
    _e220_mss_preflight_readonly || return 1;
    d=$(_e220_mss_new_tx disable) || return 1;
    list="$d/backends.tsv";
    _e220_mss_capture_control "$d" || return 1;
    snapshot_ready=1;
    phase=control-ready;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    _e218_mss_stop_triggers || return 1;
    phase=triggers-stopped;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    _e220_mss_capture_backends "$d" "$list" || return 1;
    phase=backends-ready;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    phase=mutation-started;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    _e218_mss_cleanup_captured "$list" || rc=1;
    test "$rc" -ne 0 || _e218_mss_captured_off "$list" || rc=1;
    test "$rc" -ne 0 || _e242_mss_disable_units_idempotent || rc=1;
    if test "$rc" -eq 0; then
        rm -f -- "$E216_MSS_SERVICE" "$E216_MSS_TIMER" "$E216_MSS_SCRIPT" "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" || rc=1;
    fi;
    test "$rc" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || _e216_mss_write_legacy_state OFF || rc=1;
    if test "$rc" -eq 0; then
        for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT";
        do
            systemctl is-active --quiet "$unit" 2> /dev/null && rc=1 || true;
            systemctl is-enabled --quiet "$unit" 2> /dev/null && rc=1 || true;
        done;
        for path in "$E216_MSS_SERVICE" "$E216_MSS_TIMER" "$E216_MSS_SCRIPT" "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE";
        do
            test ! -e "$path" && test ! -L "$path" || rc=1;
        done;
        _e218_mss_captured_off "$list" || rc=1;
        _e218_mss_consistency || rc=1;
    fi;
    test "$rc" -eq 0 || { 
        error 'MSS关闭后的脚本自有规则、状态、文件或systemd读回失败。';
        for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT";
        do
            printf '    unit=%s load=%s enabled=%s active=%s\n' "$unit" "$(systemctl show "$unit" -p LoadState --value 2> /dev/null || echo unknown)" "$(systemctl is-enabled "$unit" 2> /dev/null || true)" "$(systemctl is-active "$unit" 2> /dev/null || true)" 1>&2;
        done;
        return 1
    };
    state=$(_e218_mss_owner_state) || return 1;
    phase=committed;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    _e220_mss_tx_close "$d" committed || return 1;
    finished=1;
    trap - EXIT HUP INT TERM;
    _e218_mss_log "action=disable result=ok state=$state snapshot=$d";
    info "IPv4 MSS Clamp已关闭：所有快照后端、服务、定时器、脚本与状态均已读回；快照=$d" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_enable
_e218_mss_enable() {
    ( local d="" list="" row backend="" candidate identity save save_identity;
    local restore restore_identity snapshot tool_path="" tool_identity="" attempt=0;
    local service_c timer_c rc=0 snapshot_ready=0 finished=0 phase=created;
    function _e220_mss_exit_guard () 
    { 
        local status="${1:-1}" rollback_rc=0;
        trap - EXIT HUP INT TERM;
        if test "$finished" -eq 0 && test "$snapshot_ready" -eq 1 && test -n "$d"; then
            phase=$(cat "$d/.phase" 2> /dev/null || echo unknown);
            if _e220_mss_rollback "$d" "$list" "$phase"; then
                _e218_mss_log "action=enable result=failed rollback=ok snapshot=$d phase=$phase";
                info "MSS启用失败已恢复操作前控制文件、规则与服务；快照：$d";
                _e220_mss_tx_close "$d" rolled-back || rollback_rc=1;
            else
                rollback_rc=1;
            fi;
            if test "$rollback_rc" -ne 0; then
                _e220_mss_mark_critical "$d" 'MSS enable rollback/readback failed' || true;
                _e220_mss_tx_close "$d" critical > /dev/null 2>&1 || true;
                _e218_mss_log "action=enable result=critical snapshot=$d phase=$phase";
                error "严重：MSS启用回滚未完整通过；已保留持久快照：$d";
            fi;
        else
            if test "$finished" -eq 0 && test -n "$d"; then
                _e220_mss_tx_close "$d" no-mutation > /dev/null 2>&1 || true;
            fi;
        fi;
        [[ "$status" =~ ^[0-9]+$ ]] || status=1;
        test "$status" -ne 0 || status=1;
        exit "$status"
    };
    trap '_e220_mss_exit_guard $?' EXIT;
    trap 'exit 129' HUP;
    trap 'exit 130' INT;
    trap 'exit 143' TERM;
    _e220_mss_preflight_readonly || return 1;
    _e220_prepare || return 1;
    test -d /run/systemd/system || { 
        error 'systemd未运行，不能安全持久化MSS Clamp。';
        return 1
    };
    _e214_ensure_run_lock || return 1;
    exec 209> "$E218_MSS_LOCK" || return 1;
    flock -n 209 || { 
        error '已有MSS Clamp事务正在运行。';
        return 1
    };
    _e220_mss_preflight_readonly || return 1;
    d=$(_e220_mss_new_tx enable) || return 1;
    list="$d/backends.tsv";
    _e220_mss_capture_control "$d" || return 1;
    snapshot_ready=1;
    phase=control-ready;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    _e218_mss_stop_triggers || { 
        error '旧MSS定时器/服务未能停止。';
        return 1
    };
    phase=triggers-stopped;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    _e220_mss_capture_backends "$d" "$list" || { 
        error '没有可安全快照、固定实体并恢复的IPv4 xtables后端。';
        return 1
    };
    phase=backends-ready;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    phase=mutation-started;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    while IFS= read -r row; do
        IFS='|' read -r candidate identity save save_identity restore restore_identity snapshot <<< "$row";
        attempt=$((attempt + 1));
        if test "$attempt" -gt 1; then
            _e220_mss_restore_backends "$d" "$list" || break;
        fi;
        _e218_mss_cleanup_captured "$list" || continue;
        if _e216_mss_apply_backend "$candidate"; then
            backend=$candidate;
            tool_identity=$identity;
            tool_path=$(_e216_mss_tool_path "$candidate") || break;
            break;
        fi;
    done < "$list";
    test -n "$backend" && test -n "$tool_path" || { 
        error 'MSS所有候选后端试写/读回失败。';
        return 1
    };
    service_c="$d/service";
    timer_c="$d/timer";
    _e218_mss_build_script "$tool_path" "$tool_identity" "$d/script" || rc=1;
    test "$rc" -ne 0 || _e216_mss_build_units "$service_c" "$timer_c" || rc=1;
    test "$rc" -ne 0 || _e118_atomic_install "$d/script" "$E216_MSS_SCRIPT" 0755 || rc=1;
    test "$rc" -ne 0 || _e118_atomic_install "$service_c" "$E216_MSS_SERVICE" 0644 || rc=1;
    test "$rc" -ne 0 || _e118_atomic_install "$timer_c" "$E216_MSS_TIMER" 0644 || rc=1;
    test "$rc" -ne 0 || _e216_mss_write_backend_state "$backend" || rc=1;
    test "$rc" -ne 0 || _e218_mss_write_owner_state "$backend" "$tool_path" "$tool_identity" || rc=1;
    test "$rc" -ne 0 || _e216_mss_write_legacy_state ON || rc=1;
    test "$rc" -ne 0 || systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || systemctl enable "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || systemctl start "$E216_MSS_SERVICE_UNIT" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || systemctl start "$E216_MSS_TIMER_UNIT" > /dev/null 2>&1 || rc=1;
    test "$rc" -ne 0 || _e218_mss_verify_on || rc=1;
    test "$rc" -ne 0 || _e218_mss_captured_exclusive "$list" "$backend" || rc=1;
    test "$rc" -eq 0 || { 
        error 'MSS规则、固定后端、状态、服务或唯一性读回失败。';
        return 1
    };
    phase=committed;
    _e220_mss_set_phase "$d" "$phase" || return 1;
    _e220_mss_tx_close "$d" committed || return 1;
    finished=1;
    trap - EXIT HUP INT TERM;
    _e218_mss_log "action=enable result=ok backend=$backend tool=$tool_path identity=$tool_identity snapshot=$d";
    info "IPv4 MSS Clamp已验证：backend=$backend（实体已固定），5分钟复检，快照=$d";
    warn '作用域是宿主机全部IPv4 TCP新握手（包含Xray和转发流量），不是仅Xray；UDP/IPv6不受影响。' )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_log
_e218_mss_log() {
    local log="$E220_MSS_AUDIT";
    if test "${E220_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E220_INTERNAL_SELF_TEST_TMP:-}"; then
        log="$E220_INTERNAL_SELF_TEST_TMP/mss-last.log";
    fi;
    install -d -m 0750 "$(dirname -- "$log")" 2> /dev/null || return 0;
    printf '%s %s\n' "$(date '+%F %T %z')" "$*" >> "$log" 2> /dev/null || true
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_mock_self_test
_e218_mss_mock_self_test() {
    ( local d fake save_fake restore_fake state owner list rc=0;
    d=$(mktemp -d /tmp/xray-e218-mss-mock.XXXXXX) || return 1;
    trap 'rm -rf -- "${d:-}"' EXIT;
    install -d -m 0700 "$d/bin" || return 1;
    fake="$d/bin/iptables";
    state="$d/mock.state";
    cat > "$fake" <<'EOF_E218_MOCK_IPTABLES'
#!/usr/bin/env bash
set -euo pipefail
state=${E218_MOCK_IPTABLES_STATE:?}
chain=0; jump=0; rule=0; direct=0
test ! -f "$state" || source "$state"
save_state() {
    printf 'chain=%s\njump=%s\nrule=%s\ndirect=%s\n' "$chain" "$jump" "$rule" "$direct" >"$state.tmp"
    mv -f -- "$state.tmp" "$state"
}
while test "$#" -gt 0; do
    case "$1" in -w) shift 2 ;; -t) shift 2 ;; *) break ;; esac
done
cmd=${1:-}; test "$#" -eq 0 || shift
case "$cmd" in
    -S)
        target=${1:-all}
        case "$target" in
            all) test "$chain" = 0 || echo '-N XRAY_MSS_CLAMP'; test "$jump" = 0 || echo '-A POSTROUTING -j XRAY_MSS_CLAMP'; test "$rule" = 0 || echo '-A XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu'; test "$direct" = 0 || echo '-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu' ;;
            POSTROUTING) test "$jump" = 0 || echo '-A POSTROUTING -j XRAY_MSS_CLAMP'; test "$direct" = 0 || echo '-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu' ;;
            XRAY_MSS_CLAMP) test "$chain" = 1 || exit 1; test "$rule" = 0 || echo '-A XRAY_MSS_CLAMP -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu' ;;
            *) exit 1 ;;
        esac ;;
    -C)
        target=${1:-}; shift || true; args=" $* "
        case "$target:$args" in
            'POSTROUTING: -j XRAY_MSS_CLAMP ') test "$jump" = 1 ;;
            XRAY_MSS_CLAMP:*) test "$chain" = 1 && test "$rule" = 1 ;;
            POSTROUTING:*) test "$direct" = 1 ;;
            *) exit 1 ;;
        esac ;;
    -D)
        test "${E218_MOCK_FAIL_DELETE:-0}" = 0 || exit 1
        target=${1:-}; shift || true; args=" $* "
        case "$target:$args" in
            'POSTROUTING: -j XRAY_MSS_CLAMP ') test "$jump" = 1 || exit 1; jump=0 ;;
            POSTROUTING:*) test "$direct" = 1 || exit 1; direct=0 ;;
            *) exit 1 ;;
        esac
        save_state ;;
    -N) test "${1:-}" = XRAY_MSS_CLAMP && test "$chain" = 0; chain=1; save_state ;;
    -A)
        target=${1:-}; test "$#" -eq 0 || shift
        case "$target" in XRAY_MSS_CLAMP) test "$chain" = 1; rule=1 ;; POSTROUTING) direct=1 ;; *) exit 1 ;; esac
        save_state ;;
    -I) test "${1:-}" = POSTROUTING && test "${2:-}" = 1; jump=1; save_state ;;
    -F) test "${E218_MOCK_FAIL_DELETE:-0}" = 0 || exit 1; test "${1:-}" = XRAY_MSS_CLAMP && test "$chain" = 1; rule=0; save_state ;;
    -X) test "${E218_MOCK_FAIL_DELETE:-0}" = 0 || exit 1; test "${1:-}" = XRAY_MSS_CLAMP && test "$chain" = 1 && test "$rule" = 0 && test "$jump" = 0; chain=0; save_state ;;
    *) exit 1 ;;
esac
EOF_E218_MOCK_IPTABLES

    chmod 0755 "$fake" || return 1;
    save_fake="$d/bin/iptables-save";
    restore_fake="$d/bin/iptables-restore";
    cat > "$save_fake" <<'EOF_E218_MOCK_SAVE'
#!/usr/bin/env bash
printf '%s\n' '# e218 mock ruleset'
EOF_E218_MOCK_SAVE

    cat > "$restore_fake" <<'EOF_E218_MOCK_RESTORE'
#!/usr/bin/env bash
cat >/dev/null
EOF_E218_MOCK_RESTORE

    chmod 0755 "$save_fake" "$restore_fake" || return 1;
    printf 'chain=0\njump=0\nrule=0\ndirect=0\n' > "$state";
    export E218_MOCK_IPTABLES_STATE="$state";
    PATH="$d/bin:$PATH";
    function _e218_mss_owner_state () 
    { 
        echo UNSET
    };
    _e216_mss_apply_backend iptables || rc=1;
    _e218_mss_backend_has_owned iptables || rc=1;
    _e216_mss_cleanup_backend iptables || rc=1;
    _e218_mss_backend_has_owned iptables && rc=1 || test "$?" -eq 1 || rc=1;
    printf 'chain=0\njump=0\nrule=0\ndirect=1\n' > "$state";
    _e216_mss_cleanup_backend iptables > /dev/null 2>&1 || rc=1;
    grep -Fqx 'direct=1' "$state" || rc=1;
    _e218_mss_runtime_evidence && rc=1 || true;
    printf 'chain=0\njump=0\nrule=0\ndirect=0\n' > "$state";
    list="$d/backends.tsv";
    _e218_mss_capture_backends "$d" "$list" || rc=1;
    awk -F'|' 'NF==7{n++} END{exit(n==1?0:1)}' "$list" || rc=1;
    _e218_mss_restore_backends "$list" || rc=1;
    printf 'chain=1\njump=1\nrule=1\ndirect=0\n' > "$state";
    E218_MOCK_FAIL_DELETE=1 _e216_mss_apply_backend iptables > /dev/null 2>&1 && rc=1 || true;
    grep -Fqx 'chain=1' "$state" && grep -Fqx 'jump=1' "$state" || rc=1;
    owner="$d/owner.env";
    { 
        echo version=199e218;
        echo backend=iptables;
        echo "tool_path=$fake";
        echo "tool_identity=$fake";
        echo family=ipv4;
        echo mode=clamp-to-pmtu;
        echo updated_epoch=1780000000
    } > "$owner";
    _e218_mss_owner_state_validate "$owner" || rc=1;
    _e218_mss_build_script "$fake" "$fake" "$d/reconcile.sh" || rc=1;
    grep -Fqx "IDENTITY=$(printf '%q' "$fake")" "$d/reconcile.sh" || rc=1;
    sed -i 's/family=ipv4/family=ipv6/' "$owner";
    ! _e218_mss_owner_state_validate "$owner" || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_owner_state
_e218_mss_owner_state() {
    local value;
    if test ! -e "$E88_MSS_STATE_FILE" && test ! -L "$E88_MSS_STATE_FILE"; then
        echo UNSET;
        return 0;
    fi;
    test -f "$E88_MSS_STATE_FILE" && test ! -L "$E88_MSS_STATE_FILE" || { 
        echo INVALID;
        return 1
    };
    value=$(awk 'NF{n++;v=$0}END{if(n==1)print v;else exit 1}' "$E88_MSS_STATE_FILE" 2> /dev/null || true);
    case "$value" in 
        ON | OFF)
            echo "$value";
            return 0
        ;;
        *)
            echo INVALID;
            return 1
        ;;
    esac
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_owner_state_validate
_e218_mss_owner_state_validate() {
    local file="${1:-$E218_MSS_OWNER_STATE}" line key value count=0;
    local version backend tool_path tool_identity family mode epoch actual expected_path;
    local -A seen=();
    test -f "$file" && test ! -L "$file" && test -s "$file" || return 1;
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z_]+)=(.*)$ ]] || return 1;
        key=${BASH_REMATCH[1]};
        value=${BASH_REMATCH[2]};
        case "$key" in 
            version | backend | tool_path | tool_identity | family | mode | updated_epoch)

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${seen[$key]+x}" || return 1;
        test -n "$value" || return 1;
        seen[$key]=1;
        count=$((count + 1));
    done < "$file";
    test "$count" -eq 7 || return 1;
    for key in version backend tool_path tool_identity family mode updated_epoch;
    do
        test -n "${seen[$key]+x}" || return 1;
    done;
    version=$(_e218_mss_owner_state_value "$file" version) || return 1;
    backend=$(_e218_mss_owner_state_value "$file" backend) || return 1;
    tool_path=$(_e218_mss_owner_state_value "$file" tool_path) || return 1;
    tool_identity=$(_e218_mss_owner_state_value "$file" tool_identity) || return 1;
    family=$(_e218_mss_owner_state_value "$file" family) || return 1;
    mode=$(_e218_mss_owner_state_value "$file" mode) || return 1;
    epoch=$(_e218_mss_owner_state_value "$file" updated_epoch) || return 1;
    test "$version" = 199e218 && _e216_mss_backend_valid "$backend" || return 1;
    [[ "$tool_path" =~ ^/[A-Za-z0-9_./+-]+$ ]] || return 1;
    [[ "$tool_identity" =~ ^/[A-Za-z0-9_./+-]+$ ]] || return 1;
    test -x "$tool_path" || return 1;
    expected_path=$(_e216_mss_tool_path "$backend" 2> /dev/null || true);
    test -n "$expected_path" && test "$tool_path" = "$expected_path" || return 1;
    test -x "$tool_identity" && test ! -L "$tool_identity" || return 1;
    actual=$(readlink -f -- "$tool_path" 2> /dev/null || true);
    test "$actual" = "$tool_identity" || return 1;
    test "$family" = ipv4 && test "$mode" = clamp-to-pmtu || return 1;
    [[ "$epoch" =~ ^[0-9]{1,20}$ ]]
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_owner_state_value
_e218_mss_owner_state_value() {
    local file="${1:-}" key="${2:-}";
    awk -F= -v wanted="$key" '$1==wanted{n++;v=substr($0,index($0,"=")+1)}END{if(n==1)print v;else exit 1}' "$file" 2> /dev/null
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_path_identity
_e218_mss_path_identity() {
    local path="${1:-}" actual;
    case "$path" in 
        /*)
            test -x "$path" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    actual=$(readlink -f -- "$path" 2> /dev/null || true);
    case "$actual" in 
        /*)
            test -x "$actual" && test ! -L "$actual" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    printf '%s\n' "$actual"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_restore_backends
_e218_mss_restore_backends() {
    local list="${1:-}" i backend identity save save_identity restore restore_identity snapshot rc=0;
    local -a rows=();
    test -s "$list" || return 1;
    mapfile -t rows < "$list" || return 1;
    for ((i=${#rows[@]}-1; i>=0; i--))
    do
        IFS='|' read -r backend identity save save_identity restore restore_identity snapshot <<< "${rows[$i]}";
        test "$(_e218_mss_path_identity "$restore" 2> /dev/null || true)" = "$restore_identity" && test -s "$snapshot" && "$restore" < "$snapshot" > /dev/null 2>&1 || rc=1;
    done;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_restore_control
_e218_mss_restore_control() {
    local d="${1:-}" path snap rc=0;
    test -s "$d/control/control.sha256" && ( cd "$d/control" && sha256sum -c control.sha256 > /dev/null 2>&1 ) || return 1;
    while IFS='|' read -r path snap; do
        test -n "$path" && test -n "$snap" || continue;
        _e135_restore_file "$path" "$snap" || rc=1;
    done < "$d/control/manifest";
    systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    _e204_services_restore_file "$d/control/services.env" || rc=1;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_rollback
_e218_mss_rollback() {
    local d="${1:-}" list="${2:-}" rc=0;
    _e218_mss_restore_control "$d" || rc=1;
    test ! -s "$list" || _e218_mss_restore_backends "$list" || rc=1;
    test "$rc" -eq 0 || error "MSS内层回滚未完全通过：$d";
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_runtime_evidence
_e218_mss_runtime_evidence() {
    local candidate identity rc;
    local -A seen=();
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2> /dev/null || true);
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue;
        seen[$identity]=1;
        _e220_mss_backend_has_managed "$candidate";
        rc=$?;
        test "$rc" -eq 0 && return 0;
    done < <(_e216_mss_candidate_order);
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_static_evidence
_e218_mss_static_evidence() {
    local state path unit;
    state=$(_e218_mss_owner_state 2> /dev/null || echo INVALID);
    case "$state" in 
        ON | INVALID)
            return 0
        ;;
    esac;
    for path in "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" "$E216_MSS_SCRIPT" "$E216_MSS_SERVICE" "$E216_MSS_TIMER";
    do
        test ! -e "$path" && test ! -L "$path" || return 0;
    done;
    if test -d /run/systemd/system; then
        for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT";
        do
            systemctl is-enabled --quiet "$unit" 2> /dev/null && return 0 || true;
            systemctl is-active --quiet "$unit" 2> /dev/null && return 0 || true;
        done;
    fi;
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_status
_e218_mss_status() {
    local rc=0 unresolved=0;
    if ! _e220_mss_unresolved_report > /dev/null 2>&1; then
        unresolved=1;
        title 'V199e266：MSS未完成事务 / 恢复证据';
        _e220_mss_unresolved_report || true;
        warn '存在未完成事务；请运行 --mss-recover，未恢复前不会覆盖快照。';
    fi;
    _e220_mss_status_base "$@" || rc=$?;
    _e220_mss_unowned_direct_report || true;
    test "$unresolved" -eq 0 || rc=1;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_stop_triggers
_e218_mss_stop_triggers() {
    systemctl stop "$E216_MSS_TIMER_UNIT" "$E216_MSS_SERVICE_UNIT" > /dev/null 2>&1 || true;
    systemctl is-active --quiet "$E216_MSS_TIMER_UNIT" 2> /dev/null && return 1 || true;
    systemctl is-active --quiet "$E216_MSS_SERVICE_UNIT" 2> /dev/null && return 1 || true
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_verify_off
_e218_mss_verify_off() {
    local state;
    state=$(_e218_mss_owner_state 2> /dev/null || echo INVALID);
    case "$state" in 
        OFF | UNSET)

        ;;
        *)
            return 1
        ;;
    esac;
    ! _e218_mss_static_evidence && ! _e218_mss_runtime_evidence
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_verify_on
_e218_mss_verify_on() {
    local backend tool tool_identity expected jumps rules direct candidate identity rc;
    local -A seen=();
    test "$(_e218_mss_owner_state 2> /dev/null || true)" = ON || return 1;
    if test -e "$E218_MSS_OWNER_STATE" || test -L "$E218_MSS_OWNER_STATE"; then
        _e218_mss_owner_state_validate "$E218_MSS_OWNER_STATE" || return 1;
    else
        _e216_mss_verify_on;
        return $?;
    fi;
    _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE" || return 1;
    backend=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" backend) || return 1;
    tool=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_path) || return 1;
    tool_identity=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_identity) || return 1;
    expected=$(_e218_mss_backend_identity "$backend" 2> /dev/null || true);
    test "$expected" = "$tool_identity" || return 1;
    test "$(readlink -f -- "$tool" 2> /dev/null || true)" = "$tool_identity" || return 1;
    test "$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend)" = "$backend" || return 1;
    test -f "$E216_MSS_SCRIPT" && test ! -L "$E216_MSS_SCRIPT" && bash -n "$E216_MSS_SCRIPT" || return 1;
    grep -Fqx "IPT=$(printf '%q' "$tool")" "$E216_MSS_SCRIPT" || return 1;
    grep -Fqx "IDENTITY=$(printf '%q' "$tool_identity")" "$E216_MSS_SCRIPT" || return 1;
    test -f "$E216_MSS_SERVICE" && test ! -L "$E216_MSS_SERVICE" && test -f "$E216_MSS_TIMER" && test ! -L "$E216_MSS_TIMER" || return 1;
    systemctl is-enabled --quiet "$E216_MSS_SERVICE_UNIT" 2> /dev/null || return 1;
    systemctl is-enabled --quiet "$E216_MSS_TIMER_UNIT" 2> /dev/null || return 1;
    systemctl is-active --quiet "$E216_MSS_TIMER_UNIT" 2> /dev/null || return 1;
    test "$(systemctl show "$E216_MSS_SERVICE_UNIT" -p Result --value 2> /dev/null || true)" = success || return 1;
    "$tool" -w 5 -t mangle -S > /dev/null 2>&1 || return 1;
    jumps=$("$tool" -w 5 -t mangle -S POSTROUTING 2> /dev/null | grep -Ec -- "^-A POSTROUTING( .*)? -j $E216_MSS_CHAIN$" || true);
    rules=$("$tool" -w 5 -t mangle -S "$E216_MSS_CHAIN" 2> /dev/null | grep -Ec -- "^-A $E216_MSS_CHAIN .* -j TCPMSS --clamp-mss-to-pmtu$" || true);
    direct=$("$tool" -w 5 -t mangle -S POSTROUTING 2> /dev/null | grep -Ec -- '^-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu$' || true);
    test "$jumps" -eq 1 && test "$rules" -eq 1 && test "$direct" -eq 0 || return 1;
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2> /dev/null || true);
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue;
        seen[$identity]=1;
        test "$identity" = "$tool_identity" && continue;
        _e218_mss_backend_has_owned "$candidate";
        rc=$?;
        test "$rc" -eq 1 || return 1;
    done < <(_e216_mss_candidate_order);
    _e220_mss_unowned_direct_report > /dev/null 2>&1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_mss_write_owner_state
_e218_mss_write_owner_state() {
    local backend="${1:-}" tool_path="${2:-}" tool_identity="${3:-}" tmp actual;
    _e216_mss_backend_valid "$backend" || return 1;
    [[ "$tool_path" =~ ^/[A-Za-z0-9_./+-]+$ ]] && test -x "$tool_path" || return 1;
    [[ "$tool_identity" =~ ^/[A-Za-z0-9_./+-]+$ ]] && test -x "$tool_identity" && test ! -L "$tool_identity" || return 1;
    actual=$(readlink -f -- "$tool_path" 2> /dev/null || true);
    test "$actual" = "$tool_identity" || return 1;
    _e218_prepare || return 1;
    tmp=$(_e118_mktemp e218-mss-owner) || return 1;
    { 
        printf 'version=199e218\n';
        printf 'backend=%s\n' "$backend";
        printf 'tool_path=%s\n' "$tool_path";
        printf 'tool_identity=%s\n' "$tool_identity";
        printf 'family=ipv4\n';
        printf 'mode=clamp-to-pmtu\n';
        printf 'updated_epoch=%s\n' "$(date +%s)"
    } > "$tmp" || return 1;
    chmod 0600 "$tmp" || return 1;
    _e218_mss_owner_state_validate "$tmp" || return 1;
    _e118_atomic_install "$tmp" "$E218_MSS_OWNER_STATE" 0600
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_prepare
_e218_prepare() {
    _e216_prepare || return 1;
    test ! -L "$E218_DIR" || { 
        error "拒绝使用符号链接目录：$E218_DIR";
        return 1
    };
    _e214_ensure_directory "$E218_DIR" 0700 || return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_self_test
_e218_self_test() {
    local rc=0;
    _e214_self_test || rc=1;
    _e216_mss_self_test && echo '  [PASS] E216 compatibility state/script/unit invariants' || { 
        echo '  [FAIL] E216 compatibility MSS invariant';
        rc=1
    };
    _e218_mss_mock_self_test && echo '  [PASS] E218 strict cleanup/apply/backend-pin mock transaction' || { 
        echo '  [FAIL] E218 MSS mock transaction';
        rc=1
    };
    _e218_structure_audit > /dev/null && echo '  [PASS] E218 MTU1350/MSS/hot-update final bindings' || { 
        echo '  [FAIL] E218 final binding';
        rc=1
    };
    if test "$rc" -eq 0; then
        echo 'V199e218 result: PASS';
    else
        echo 'V199e218 result: FAIL';
    fi;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e218_structure_audit
_e218_structure_audit() {
    local rc=0 menu mtu_menu installer paths preflight hot_verify mtu_persist mtu_commit;
    local mss_apply mss_disable uninstaller dispatchers mtu_line mss_line smallbbr_line;
    _e214_structure_audit > /dev/null || rc=1;
    menu=$(declare -f _e214_main_menu 2> /dev/null || true);
    mtu_menu=$(declare -f _e214_mtu_menu 2> /dev/null || true);
    installer=$(declare -f _e214_install_self 2> /dev/null || true);
    paths=$(declare -f _e138_system_paths 2> /dev/null || true);
    preflight=$(declare -f _e214_hot_update_preflight 2> /dev/null || true);
    hot_verify=$(declare -f _e214_hot_verify 2> /dev/null || true);
    mtu_persist=$(declare -f _e214_mtu_persistence_validate 2> /dev/null || true);
    mtu_commit=$(declare -f _e214_mtu_commit 2> /dev/null || true);
    mss_apply=$(declare -f _e216_mss_apply_backend 2> /dev/null || true);
    mss_disable=$(declare -f _e218_mss_disable 2> /dev/null || true);
    uninstaller=$(declare -f do_uninstall 2> /dev/null || true);
    mtu_line=$(grep -n '_e214_mtu_any_state' <<< "$uninstaller" | head -n 1 | cut -d: -f1 || true);
    mss_line=$(grep -n '_e218_mss_any_evidence' <<< "$uninstaller" | head -n 1 | cut -d: -f1 || true);
    smallbbr_line=$(grep -n '_e202_small_bbr_active' <<< "$uninstaller" | head -n 1 | cut -d: -f1 || true);
    dispatchers=$(grep -c '^# V199e218 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    echo 'V199e218 structure audit:';
    test "$SCRIPT_VERSION" = 199e218 && test "$E218_VERSION" = 199e218 || rc=1;
    test "$E216_VERSION" = 199e216 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    ! LC_ALL=C grep -q $'\r' "$SCRIPT_PATH" || rc=1;
    grep -q 'V199e218 - 事务稳态版' <<< "$menu" || rc=1;
    grep -q '热更新到 V199e218' <<< "$menu" || rc=1;
    grep -q '27) 宿主机网卡 MTU' <<< "$menu" || rc=1;
    grep -q 'MTU=1350' <<< "$mtu_menu" || rc=1;
    grep -q '_e214_mtu_set_interactive auto - 1350' <<< "$mtu_menu" || rc=1;
    grep -q 'E218_SELF_PATH' <<< "$installer" || rc=1;
    grep -q 'E218_MSS_OWNER_STATE' <<< "$paths" || rc=1;
    grep -q '_e218_structure_audit' <<< "$preflight" || rc=1;
    grep -q '_e218_mss_consistency' <<< "$preflight" || rc=1;
    grep -q '_e218_mss_consistency' <<< "$hot_verify" || rc=1;
    grep -q 'E214_SELF_PATH' <<< "$mtu_persist" || rc=1;
    grep -q '_e214_mtu_current' <<< "$mtu_persist" || rc=1;
    grep -q 'systemctl start.*E214_MTU_UNIT' <<< "$mtu_commit" || rc=1;
    grep -q '_e216_mss_cleanup_backend.*|| return 1' <<< "$mss_apply" || rc=1;
    grep -q '_e218_mss_capture_control' <<< "$mss_disable" || rc=1;
    grep -q '_e218_mss_capture_backends' <<< "$mss_disable" || rc=1;
    grep -q '_e218_mss_rollback' <<< "$mss_disable" || rc=1;
    grep -q '_e218_mss_consistency' <<< "$mss_disable" || rc=1;
    [[ "$mtu_line" =~ ^[0-9]+$ && "$mss_line" =~ ^[0-9]+$ && "$smallbbr_line" =~ ^[0-9]+$ ]] || rc=1;
    if [[ "$mtu_line" =~ ^[0-9]+$ && "$mss_line" =~ ^[0-9]+$ && "$smallbbr_line" =~ ^[0-9]+$ ]]; then
        ((mtu_line < smallbbr_line && mss_line < smallbbr_line)) || rc=1;
    fi;
    grep -q 'xray-before-uninstall-e218-' <<< "$uninstaller" || rc=1;
    grep -q 'E218卸载任一阶段' <<< "$uninstaller" || rc=1;
    for f in _e218_mss_enable _e218_mss_disable _e218_mss_status _e218_mss_build_script _e218_mss_verify_on _e218_mss_verify_off _e218_mss_consistency _e218_mss_mock_self_test;
    do
        declare -F "$f" > /dev/null 2>&1 || rc=1;
    done;
    grep -Fq -- '--e218-summary)' "$SCRIPT_PATH" || rc=1;
    grep -Fq -- '--mss-status)' "$SCRIPT_PATH" || rc=1;
    if test "$rc" -eq 0; then
        echo '  result=PASS';
    else
        echo '  result=FAIL';
    fi;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_choose_banaction_for_backend
_e220_choose_banaction_for_backend() {
    local backend="${1:-}" action_dir="${2:-/etc/fail2ban/action.d}" a;
    test -d "$action_dir" && test ! -L "$action_dir" || return 1;
    case "$backend" in 
        nft)
            command -v nft > /dev/null 2>&1 || return 1;
            test -f "$action_dir/nftables.conf" && test ! -L "$action_dir/nftables.conf" || return 1;
            printf '%s\n' "$E165_F2B_ACTION_ID"
        ;;
        iptables)
            test -f "$action_dir/iptables-multiport.conf" && test ! -L "$action_dir/iptables-multiport.conf" || return 1;
            printf '%s\n' iptables-multiport
        ;;
        ufw)
            if test -f "$action_dir/ufw.conf" && test ! -L "$action_dir/ufw.conf"; then
                printf '%s\n' ufw;
            else
                if command -v nft > /dev/null 2>&1 && test -f "$action_dir/nftables.conf" && test ! -L "$action_dir/nftables.conf"; then
                    printf '%s\n' "$E165_F2B_ACTION_ID";
                else
                    if test -f "$action_dir/iptables-multiport.conf" && test ! -L "$action_dir/iptables-multiport.conf"; then
                        printf '%s\n' iptables-multiport;
                    else
                        return 1;
                    fi;
                fi;
            fi
        ;;
        firewalld)
            for a in firewallcmd-rich-rules firewallcmd-multiport firewallcmd-allports;
            do
                if test -f "$action_dir/$a.conf" && test ! -L "$action_dir/$a.conf"; then
                    printf '%s\n' "$a";
                    return 0;
                fi;
            done;
            if command -v nft > /dev/null 2>&1 && test -f "$action_dir/nftables.conf" && test ! -L "$action_dir/nftables.conf"; then
                printf '%s\n' "$E165_F2B_ACTION_ID";
            else
                return 1;
            fi
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_fail2ban_action_self_test
_e220_fail2ban_action_self_test() {
    ( local d actions actual rc=0;
    d=$(mktemp -d /tmp/xray-e220-f2b-action.XXXXXX) || return 1;
    trap 'rm -rf -- "${d:-}"' EXIT;
    actions="$d/actions";
    mkdir -p "$actions" "$d/bin" || return 1;
    : > "$actions/iptables-multiport.conf";
    : > "$actions/ufw.conf";
    : > "$actions/firewallcmd-rich-rules.conf";
    : > "$actions/nftables.conf";
    printf '#!/usr/bin/env bash\nexit 0\n' > "$d/bin/nft";
    chmod 0755 "$d/bin/nft";
    PATH="$d/bin:$PATH";
    actual=$(_e152_choose_banaction_for_backend iptables "$actions" 2> /dev/null || true);
    test "$actual" = iptables-multiport || rc=1;
    actual=$(_e152_choose_banaction_for_backend ufw "$actions" 2> /dev/null || true);
    test "$actual" = ufw || rc=1;
    actual=$(_e152_choose_banaction_for_backend firewalld "$actions" 2> /dev/null || true);
    test "$actual" = firewallcmd-rich-rules || rc=1;
    actual=$(_e152_choose_banaction_for_backend nft "$actions" 2> /dev/null || true);
    test "$actual" = "$E165_F2B_ACTION_ID" || rc=1;
    ! _e152_choose_banaction_for_backend none "$actions" > /dev/null 2>&1 || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_help
_e220_help() {
    cat <<'EOF_E220_HELP'
V199e243:
  --hot-update                         一键升级到E242（完成后不自动重启）
  --summary                            导出节点URI、一次终端QR及PNG/SVG
  --network-audit                      只读网络参数/重复定义审计
  --full-network-apply                 事务应用完整127条请求
  --small-bbr-menu                     八个精确14/25/26项档位菜单
  --small-bbr-enable|status|disable    启用、读回或恢复小BBR
  --mtu-menu|--mtu-status              宿主机MTU事务；菜单内含1350快捷档
  --mtu-reconcile|--mtu-disable        立即复检/恢复首次接管前MTU
  --mss-status                         只读核对MSS、MTU、后端、规则与恢复证据
  --mss-enable|--mss-disable           启用/关闭IPv4动态MSS Clamp
  --mss-recover                        从E220兼容持久快照恢复中断的MSS事务
  --ipv6-disable|enable|status         IPv6永久策略（无IPv4时默认拒绝关闭）
  --warp-menu|--warp-global-menu       Xray层定向/全局WARP
  --warp-full-menu                     Cloudflare系统全隧道
  --micro-menu                         完整28项微操中心
  --structure-audit|--self-test        E242最终绑定审计/离线发布门禁
  --uninstall                          受控卸载（先恢复各事务基线）

固定工作流：
  新装：安装/新建节点 -> 菜单10→6→第28项 -> 重启 -> 小BBR。
  升级：直接运行下载的E242并选择一键升级；它会调用当前已安装旧脚本
        安全退出活动小BBR，完成热更新/第28项后恢复原活动档位。
        MSS状态一致时原样保留；可验证旧事务自动恢复，脚本自有漂移
        自动事务收敛，不再要求先手工运行--mss-status/--mss-disable。
        同一次确认内，默认出口MTU会强制提交为1350并完成持久化读回。
  MTU：商家因高防清洗/动态路由隐藏隧道而导致大包卡顿时，
       可使用菜单27的1350保守兼容档；它不是DDoS防御本身。

MSS边界：MTU=1350时无TCP选项头的名义IPv4 MSS约1310。
--clamp-mss-to-pmtu只缩小宿主机全部IPv4 POSTROUTING TCP新握手
（包含Xray，不是仅Xray），不改MTU、不处理UDP/IPv6，也不能猜出未知
PMTU黑洞。第28项、小BBR和MTU=1350都不会暗中开关MSS。
EOF_E220_HELP

}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_backend_has_direct
_e220_mss_backend_has_direct() {
    local backend="${1:-}" tool;
    tool=$(_e216_mss_tool_path "$backend") || return 2;
    "$tool" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_backend_has_managed
_e220_mss_backend_has_managed() {
    local backend="${1:-}" tool rules;
    tool=$(_e216_mss_tool_path "$backend") || return 2;
    rules=$("$tool" -w 5 -t mangle -S 2> /dev/null) || return 2;
    grep -Eq -- "(^-N $E216_MSS_CHAIN$|^-A [^ ]+( .*)? -j $E216_MSS_CHAIN$)" <<< "$rules"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_backends_match
_e220_mss_backends_match() {
    local d="${1:-}" list="${2:-}" i backend identity save save_identity;
    local restore restore_identity snapshot rc=0 current;
    local -a rows=();
    declare -F _e220_mss_normalize_rules > /dev/null 2>&1 || return 1;
    _e220_mss_backends_validate "$d" "$list" || return 1;
    mapfile -t rows < "$list" || return 1;
    for ((i=0; i<${#rows[@]}; i++))
    do
        IFS='|' read -r backend identity save save_identity restore restore_identity snapshot <<< "${rows[$i]}";
        current="$d/.mss-signature-$i.tmp";
        if grep -Fq -- "-A $E216_MSS_CHAIN " "$snapshot.mss" 2> /dev/null; then
            _e220_mss_signature "$backend" > "$current" 2> /dev/null || rc=1;
        else
            _e242_mss_signature_legacy "$backend" > "$current" 2> /dev/null || rc=1;
        fi;
        test "$rc" -ne 0 || cmp -s "$snapshot.mss" "$current" || rc=1;
        rm -f -- "$current";
    done;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_backends_validate
_e220_mss_backends_validate() {
    local d="${1:-}" list="${2:-}" backend identity save save_identity;
    local restore restore_identity snapshot count=0 real sig normalized;
    local -A seen=();
    test "$list" = "$d/backends.tsv" && test -f "$list" && test ! -L "$list" && test -s "$list" && test -f "$d/backends.sha256" && test ! -L "$d/backends.sha256" && test -s "$d/backends.sha256" || return 1;
    sha256sum -c "$d/backends.sha256" > /dev/null 2>&1 || return 1;
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        _e216_mss_backend_valid "$backend" || return 1;
        test -z "${seen[$identity]+x}" || return 1;
        seen[$identity]=1;
        count=$((count + 1));
        case "$snapshot" in 
            "$d"/firewall-[0-9]*.rules)

            ;;
            *)
                return 1
            ;;
        esac;
        real=$(readlink -f -- "$snapshot" 2> /dev/null || true);
        case "$real" in 
            "$d"/firewall-[0-9]*.rules)

            ;;
            *)
                return 1
            ;;
        esac;
        sig="$snapshot.mss";
        normalized="$snapshot.normalized";
        test -f "$snapshot" && test ! -L "$snapshot" && test -s "$snapshot" && test -f "$sig" && test ! -L "$sig" && test -f "$normalized" && test ! -L "$normalized" || return 1;
        _e218_mss_backend_identity_matches "$backend" "$identity" || return 1;
        test "$(_e218_mss_path_identity "$save" 2> /dev/null || true)" = "$save_identity" || return 1;
        test "$(_e218_mss_path_identity "$restore" 2> /dev/null || true)" = "$restore_identity" || return 1;
    done < "$list";
    test "$count" -gt 0
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_capture_backends
_e220_mss_capture_backends() {
    local d="${1:-}" list="${2:-}" backend identity save save_identity;
    local restore restore_identity snapshot sig normalized tmp;
    _e218_mss_capture_backends "$d" "$list" || return 1;
    chmod 0600 "$list" || return 1;
    while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
        sig="$snapshot.mss";
        normalized="$snapshot.normalized";
        _e220_mss_signature "$backend" > "$sig" || return 1;
        _e220_mss_normalize_rules "$snapshot" > "$normalized" || return 1;
        chmod 0600 "$snapshot" "$sig" "$normalized" || return 1;
    done < "$list";
    tmp="$d/backends.sha256.tmp.$$";
    { 
        sha256sum "$list" || exit 1;
        while IFS='|' read -r backend identity save save_identity restore restore_identity snapshot; do
            sha256sum "$snapshot" "$snapshot.mss" "$snapshot.normalized" || exit 1;
        done < "$list"
    } > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    chmod 0600 "$tmp" && mv -f -- "$tmp" "$d/backends.sha256"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_capture_control
_e220_mss_capture_control() {
    local d="${1:-}" path snap unit;
    test -n "$d" && test -d "$d" && test ! -L "$d" || return 1;
    install -d -m 0700 "$d/control" || return 1;
    : > "$d/control/manifest" || return 1;
    chmod 0600 "$d/control/manifest" || return 1;
    for path in "$E88_MSS_STATE_FILE" "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" "$E216_MSS_SCRIPT" "$E216_MSS_SERVICE" "$E216_MSS_TIMER";
    do
        if test -e "$path" || test -L "$path"; then
            test -f "$path" && test ! -L "$path" || { 
                error "MSS控制文件类型异常，拒绝快照：$path";
                return 1
            };
        fi;
        snap="$d/control/$(printf '%s' "$path" | sha256sum | awk '{print $1}')";
        _e135_snapshot_file "$path" "$snap" || return 1;
        printf '%s|%s\n' "$path" "$snap" >> "$d/control/manifest" || return 1;
    done;
    : > "$d/control/services.env" || return 1;
    chmod 0600 "$d/control/services.env" || return 1;
    for unit in "$E216_MSS_SERVICE_UNIT" "$E216_MSS_TIMER_UNIT";
    do
        _e204_service_snapshot "$unit" >> "$d/control/services.env" || return 1;
    done;
    ( cd "$d/control" || exit 1;
    find . -maxdepth 1 -type f ! -name control.sha256 -print0 | LC_ALL=C sort -z | xargs -0 sha256sum > control.sha256;
    test -s control.sha256 && chmod 0600 control.sha256 )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_control_matches
_e220_mss_control_matches() {
    local d="${1:-}" path snap rc=0;
    _e220_mss_control_validate "$d" || return 1;
    while IFS='|' read -r path snap; do
        _e214_snapshot_matches "$path" "$snap" || rc=1;
    done < "$d/control/manifest";
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_control_validate
_e220_mss_control_validate() {
    local d="${1:-}" path snap expected count=0 unit load enabled active;
    local -A seen=();
    test -d "$d/control" && test ! -L "$d/control" && test -f "$d/control/control.sha256" && test ! -L "$d/control/control.sha256" && test -s "$d/control/control.sha256" || return 1;
    test -z "$(find "$d/control" -mindepth 1 -maxdepth 1 -type l -print -quit 2> /dev/null)" || return 1;
    ( cd "$d/control" && sha256sum -c control.sha256 > /dev/null 2>&1 ) || return 1;
    while IFS='|' read -r path snap; do
        case "$path" in 
            "$E88_MSS_STATE_FILE" | "$E216_MSS_BACKEND_STATE" | "$E218_MSS_OWNER_STATE" | "$E216_MSS_SCRIPT" | "$E216_MSS_SERVICE" | "$E216_MSS_TIMER")

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${seen[$path]+x}" || return 1;
        seen[$path]=1;
        count=$((count + 1));
        expected="$d/control/$(printf '%s' "$path" | sha256sum | awk '{print $1}')";
        test "$snap" = "$expected" || return 1;
        if test -f "$snap.present" && test ! -L "$snap.present"; then
            test ! -e "$snap.absent" && test ! -L "$snap.absent" || return 1;
        else
            if test -f "$snap.absent" && test ! -L "$snap.absent"; then
                test ! -e "$snap.present" && test ! -L "$snap.present" || return 1;
            else
                return 1;
            fi;
        fi;
    done < "$d/control/manifest";
    test "$count" -eq 6 || return 1;
    count=0;
    unset seen;
    declare -A seen=();
    while IFS='|' read -r unit load enabled active; do
        case "$unit" in 
            "$E216_MSS_SERVICE_UNIT" | "$E216_MSS_TIMER_UNIT")

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${seen[$unit]+x}" || return 1;
        seen[$unit]=1;
        count=$((count + 1));
        test -n "$load" && test -n "$enabled" && test -n "$active" || return 1;
    done < "$d/control/services.env";
    test "$count" -eq 2
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_legacy_direct_is_owned
_e220_mss_legacy_direct_is_owned() {
    local requested="${1:-}" requested_identity candidate identity found="" rc;
    local -A seen=();
    test "$(_e218_mss_owner_state 2> /dev/null || true)" = ON || return 1;
    test ! -e "$E216_MSS_BACKEND_STATE" && test ! -L "$E216_MSS_BACKEND_STATE" || return 1;
    test ! -e "$E218_MSS_OWNER_STATE" && test ! -L "$E218_MSS_OWNER_STATE" || return 1;
    requested_identity=$(_e218_mss_backend_identity "$requested" 2> /dev/null || true);
    test -n "$requested_identity" || return 1;
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2> /dev/null || true);
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue;
        seen[$identity]=1;
        _e220_mss_backend_has_managed "$candidate";
        rc=$?;
        test "$rc" -eq 1 || return 1;
        _e220_mss_backend_has_direct "$candidate";
        rc=$?;
        case "$rc" in 
            0)
                test -z "$found" || return 1;
                found=$identity
            ;;
            1)

            ;;
            *)
                return 1
            ;;
        esac;
    done < <(_e216_mss_candidate_order);
    test -n "$found" && test "$found" = "$requested_identity"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_mark_critical
_e220_mss_mark_critical() {
    local d="${1:-}" reason="${2:-MSS rollback/readback failed}" real tmp phase;
    real=$(_e220_mss_tx_real "$d") || return 1;
    phase=$(cat "$real/.phase" 2> /dev/null || echo unknown);
    reason=$(printf '%s' "$reason" | tr '\r\n' '  ');
    _e220_mss_preserve_tx "$real" "$reason" || true;
    _e220_prepare || return 1;
    test ! -L "$E220_MSS_CRITICAL_MARKER" || return 1;
    tmp=$(mktemp --tmpdir="$E220_DIR" .mss-critical.XXXXXX) || return 1;
    { 
        printf 'version=%s\n' "$E220_VERSION";
        printf 'time=%s\n' "$(date '+%F %T %z')";
        printf 'operation=mss-transaction\n';
        printf 'backup=%s\n' "$real";
        printf 'phase=%s\n' "$phase";
        printf 'reason=%s\n' "$reason"
    } > "$tmp" && chmod 0600 "$tmp" && mv -f -- "$tmp" "$E220_MSS_CRITICAL_MARKER"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_menu_action
_e220_mss_menu_action() {
    local opt="" token="";
    while true; do
        clear;
        title 'V199e266：IPv4 MSS Clamp 独立控制中心';
        echo '  1) 只读查看MTU、名义MSS、规则后端、持久服务与恢复证据';
        echo '  2) 启用动态 --clamp-mss-to-pmtu（宿主机全部IPv4 TCP握手）';
        echo '  3) 关闭并验证清理本脚本拥有的MSS规则/服务';
        echo '  4) 从E220持久快照恢复被中断的MSS事务';
        echo '  0) 返回';
        echo;
        echo '  边界：不改网卡MTU，不处理UDP/IPv6，不只作用于Xray，也不能猜未知PMTU黑洞。';
        hr;
        read -rp '操作: ' opt || true;
        case "$opt" in 
            1)
                _e218_mss_status || true;
                _e116_pause
            ;;
            2)
                warn '该规则位于IPv4 POSTROUTING，会影响宿主机全部IPv4 TCP新握手。';
                read -rp '输入 APPLY-MSS-CLAMP 确认: ' token || true;
                test "$token" = APPLY-MSS-CLAMP && _e218_mss_enable || true;
                _e116_pause
            ;;
            3)
                read -rp '输入 DISABLE-MSS-CLAMP 确认: ' token || true;
                test "$token" = DISABLE-MSS-CLAMP && _e218_mss_disable || true;
                _e116_pause
            ;;
            4)
                _e220_mss_recover || true;
                _e116_pause
            ;;
            0)
                return 0
            ;;
            *)
                warn '无效操作。';
                sleep 1
            ;;
        esac;
    done
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_new_tx
_e220_mss_new_tx() {
    local purpose="${1:-mss}" root d start owner_pid="";
    owner_pid=$(_e242_tx_owner_pid) || return 1;
    _e220_prepare || return 1;
    root=$(_e220_mss_tx_root) || return 1;
    purpose=$(printf '%s' "$purpose" | tr -cd 'A-Za-z0-9._-' | cut -c1-40);
    test -n "$purpose" || purpose=mss;
    d="$root/${purpose}-$(date +%Y%m%d_%H%M%S)-${owner_pid}-$RANDOM";
    install -d -o 0 -g 0 -m 0700 -- "$d" || return 1;
    start=$(_e214_proc_start_time "$owner_pid" 2> /dev/null || true);
    [[ "$start" =~ ^[0-9]+$ ]] || { 
        rmdir -- "$d" 2> /dev/null || true;
        return 1
    };
    { 
        printf 'version=%s\n' "$E220_VERSION";
        printf 'pid=%s\n' "$owner_pid";
        printf 'start=%s\n' "$start";
        printf 'purpose=%s\n' "$purpose";
        printf 'created_epoch=%s\n' "$(date +%s)"
    } > "$d/.active.env" || return 1;
    chmod 0600 "$d/.active.env" || return 1;
    printf 'created\n' > "$d/.phase" || return 1;
    chmod 0600 "$d/.phase" || return 1;
    _e214_prune_root "$root" "$E220_MSS_CRITICAL_MARKER" || warn 'E220 MSS旧事务未能全部收敛；当前事务仍保守继续。' 1>&2;
    printf '%s\n' "$d"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_normalize_rules
_e220_mss_normalize_rules() {
    local file="${1:-}";
    test -f "$file" && test ! -L "$file" || return 1;
    sed -e '/^# Generated by .* on /d' -e '/^# Completed on /d' "$file"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_preflight_readonly
_e220_mss_preflight_readonly() {
    if _e220_mss_unresolved_report > /dev/null 2>&1; then
        return 0;
    fi;
    error 'E220检测到未关闭或受保护的MSS事务；拒绝覆盖恢复证据。';
    _e220_mss_unresolved_report 1>&2 || true;
    error '请先运行 --mss-recover，或依据 --recovery-status 中的快照人工恢复。';
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_preserve_tx
_e220_mss_preserve_tx() {
    local real reason="${2:-manual-recovery-required}" tmp;
    real=$(_e220_mss_tx_real "${1:-}") || return 1;
    reason=$(printf '%s' "$reason" | tr '\r\n' '  ');
    tmp="$real/.preserve.env.tmp.$$";
    { 
        printf 'version=%s\n' "$E220_VERSION";
        printf 'time=%s\n' "$(date '+%F %T %z')";
        printf 'reason=%s\n' "$reason"
    } > "$tmp" && chmod 0600 "$tmp" && mv -f -- "$tmp" "$real/.preserve.env"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_recover
_e220_mss_recover() {
    ( local force="${1:-}" d locked phase list answer rc=0;
    if _e220_mss_unresolved_report > /dev/null 2>&1; then
        info '没有可恢复的E220 MSS事务。';
        return 0;
    fi;
    d=$(_e220_mss_select_recovery_tx 2> /dev/null || true);
    test -n "$d" || { 
        error '存在MSS恢复证据，但事务路径或关键标记无效；拒绝声称没有快照。';
        _e220_mss_unresolved_report 1>&2 || true;
        return 1
    };
    if _e220_mss_tx_live "$d"; then
        error "MSS事务进程仍存活，拒绝并发恢复：$d";
        return 1;
    fi;
    phase=$(cat "$d/.phase" 2> /dev/null || echo unknown);
    list="$d/backends.tsv";
    if test "$force" != force; then
        warn "将从持久快照恢复MSS控制文件、所有已快照xtables后端和systemd状态：$d";
        read -rp '输入 RECOVER-MSS 确认: ' answer || true;
        test "$answer" = RECOVER-MSS || { 
            info '已取消。';
            return 0
        };
    fi;
    _e214_ensure_run_lock || return 1;
    exec 209> "$E218_MSS_LOCK" || return 1;
    flock -n 209 || { 
        error '已有MSS Clamp事务正在运行。';
        return 1
    };
    locked=$(_e220_mss_select_recovery_tx 2> /dev/null || true);
    if test -z "$locked"; then
        info 'MSS事务已由另一进程恢复。';
        return 0;
    fi;
    test "$locked" = "$d" || { 
        error "MSS恢复目标在加锁前发生变化：before=$d after=$locked";
        return 1
    };
    if _e220_mss_tx_live "$d"; then
        error "MSS事务进程仍存活，拒绝并发恢复：$d";
        return 1;
    fi;
    phase=$(cat "$d/.phase" 2> /dev/null || echo unknown);
    list="$d/backends.tsv";
    if test "$phase" = created; then
        _e220_mss_tx_close "$d" no-mutation-recovered || return 1;
        rm -f -- "$d/.preserve.env";
        if test -f "$E220_MSS_CRITICAL_MARKER" && test ! -L "$E220_MSS_CRITICAL_MARKER"; then
            rm -f -- "$E220_MSS_CRITICAL_MARKER";
        fi;
        info "未发生系统修改的中断MSS事务已关闭：$d";
        return 0;
    fi;
    _e220_mss_rollback "$d" "$list" "$phase" || rc=1;
    if test "$rc" -eq 0; then
        _e220_mss_tx_close "$d" manual-recovery || rc=1;
        rm -f -- "$d/.preserve.env" || rc=1;
        if test -e "$E220_MSS_CRITICAL_MARKER" || test -L "$E220_MSS_CRITICAL_MARKER"; then
            test -f "$E220_MSS_CRITICAL_MARKER" && test ! -L "$E220_MSS_CRITICAL_MARKER" && rm -f -- "$E220_MSS_CRITICAL_MARKER" || rc=1;
        fi;
    fi;
    if test "$rc" -ne 0; then
        _e220_mss_mark_critical "$d" 'manual MSS recovery/readback failed' || true;
        error "MSS手动恢复未完整通过；快照仍受保护：$d";
        return 1;
    fi;
    _e218_mss_log "action=recover result=ok snapshot=$d";
    info "MSS已从持久快照恢复并读回：$d" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_restore_backends
_e220_mss_restore_backends() {
    local d="${1:-}" list="${2:-}" i backend identity save save_identity;
    local restore restore_identity snapshot rc=0 current current_rules current_normalized;
    local -a rows=();
    _e220_mss_backends_validate "$d" "$list" || return 1;
    mapfile -t rows < "$list" || return 1;
    for ((i=${#rows[@]}-1; i>=0; i--))
    do
        IFS='|' read -r backend identity save save_identity restore restore_identity snapshot <<< "${rows[$i]}";
        _e218_mss_backend_identity_matches "$backend" "$identity" && test "$(_e218_mss_path_identity "$save" 2> /dev/null || true)" = "$save_identity" && test "$(_e218_mss_path_identity "$restore" 2> /dev/null || true)" = "$restore_identity" && "$restore" < "$snapshot" > /dev/null 2>&1 || rc=1;
    done;
    _e220_mss_backends_match "$d" "$list"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_restore_control_files
_e220_mss_restore_control_files() {
    local d="${1:-}" path snap rc=0;
    _e220_mss_control_validate "$d" || return 1;
    while IFS='|' read -r path snap; do
        _e135_restore_file "$path" "$snap" || rc=1;
    done < "$d/control/manifest";
    systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_restore_control_services
_e220_mss_restore_control_services() {
    local d="${1:-}";
    _e220_mss_control_validate "$d" || return 1;
    _e204_services_restore_file "$d/control/services.env"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_rollback
_e220_mss_rollback() {
    local d="${1:-}" list="${2:-}" phase="${3:-unknown}" rc=0;
    case "$phase" in 
        created)
            _e220_mss_set_phase "$d" rolled-back;
            return
        ;;
        control-ready | triggers-stopped | backends-ready | mutation-started | committed)

        ;;
        *)
            return 1
        ;;
    esac;
    _e218_mss_stop_triggers || rc=1;
    _e220_mss_restore_control_files "$d" || rc=1;
    case "$phase" in 
        backends-ready | mutation-started | committed)
            _e220_mss_restore_backends "$d" "$list" || rc=1
        ;;
    esac;
    _e220_mss_restore_control_services "$d" || rc=1;
    case "$phase" in 
        backends-ready | mutation-started | committed)
            _e220_mss_backends_match "$d" "$list" || rc=1
        ;;
    esac;
    _e220_mss_control_matches "$d" || rc=1;
    if test "$rc" -eq 0; then
        _e220_mss_set_phase "$d" rolled-back || rc=1;
    fi;
    test "$rc" -eq 0 || error "MSS持久事务回滚未完全通过：$d";
    return "$rc"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_select_recovery_tx
_e220_mss_select_recovery_tx() {
    local root backup="" marker="$E220_MSS_CRITICAL_MARKER";
    root=$(_e220_mss_tx_root) || return 1;
    if test -e "$marker" || test -L "$marker"; then
        test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker" || return 1;
        backup=$(awk -F= '$1=="backup"{n++;v=substr($0,index($0,"=")+1)}END{if(n==1)print v;else exit 1}' "$marker") || return 1;
        _e220_mss_tx_real "$backup";
        return;
    fi;
    test -d "$root" && test ! -L "$root" || return 1;
    backup=$(find "$root" -mindepth 1 -maxdepth 1 -type d \( -exec test -f '{}/.active.env' \; -o -exec test -f '{}/.preserve.env' \; \) -printf '%T@\t%p\n' 2> /dev/null | LC_ALL=C sort -nr | head -n1 | cut -f2-);
    test -n "$backup" || return 1;
    _e220_mss_tx_real "$backup"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_set_phase
_e220_mss_set_phase() {
    local d phase="${2:-}" real tmp;
    real=$(_e220_mss_tx_real "${1:-}") || return 1;
    case "$phase" in 
        created | control-ready | triggers-stopped | backends-ready | mutation-started | committed | rolled-back)

        ;;
        *)
            return 1
        ;;
    esac;
    tmp="$real/.phase.tmp.$$";
    printf '%s\n' "$phase" > "$tmp" && chmod 0600 "$tmp" && mv -f -- "$tmp" "$real/.phase"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_signature
_e220_mss_signature() {
    local backend="${1:-}" tool;
    tool=$(_e216_mss_tool_path "$backend") || return 1;
    "$tool" -w 5 -t mangle -S 2> /dev/null | awk -v chain="$E216_MSS_CHAIN" '
          $0 == "-N " chain || index($0,"-A " chain " ")==1 ||
          index($0," -j " chain) ||
          $0 == "-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu" {print}
        ' | LC_ALL=C sort
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_status_base
_e220_mss_status_base() {
    local default_iface mtu mss4 mss6 state backend="" tool="" tool_identity="" candidate identity rc readable=0;
    local jump rule direct verdict;
    local -A seen=();
    title 'V199e266：MSS Clamp / MTU 关系与运行态（只读）';
    default_iface=$(_e214_mtu_default_iface 2> /dev/null || true);
    mtu=$(_e214_mtu_current "$default_iface" 2> /dev/null || true);
    if [[ "$mtu" =~ ^[0-9]+$ ]] && ((mtu >= 1280)); then
        mss4=$((mtu - 40));
        mss6=$((mtu - 60));
        echo "  默认出口=${default_iface:-unknown}  MTU=$mtu  无选项头时IPv4 MSS≈$mss4  IPv6 MSS≈$mss6";
    else
        echo "  默认出口=${default_iface:-unknown}  MTU=${mtu:-unknown}";
    fi;
    echo '  MTU=1350时：名义IPv4 MSS≈1310，IPv6 MSS≈1290（TCP选项可使实际头部更长）。';
    echo '  Clamp只改新TCP握手SYN/SYN-ACK中的MSS通告，不改网卡MTU，不处理UDP。';
    echo '  Xray是本机进程，所以使用IPv4 POSTROUTING；只改FORWARD会漏掉本机Xray出站。';
    echo '  作用域=宿主机所有经IPv4 POSTROUTING的TCP新握手（包含Xray，不是仅Xray）。';
    echo '  动态clamp只按内核已知的路由PMTU缩小且不会放大MSS；它不能猜出被ICMP屏蔽的未知更小PMTU。';
    echo '  本机TCP通常已会从出口MTU派生MSS；Clamp是转发/路径异常的防御性兜底，不是加速开关。';
    echo '  第28项、小BBR与MTU=1350都不会暗中开关MSS Clamp。';
    hr;
    state=$(_e218_mss_owner_state 2> /dev/null || echo INVALID);
    if _e218_mss_owner_state_validate "$E218_MSS_OWNER_STATE"; then
        backend=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" backend);
        tool=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_path);
        tool_identity=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_identity);
    else
        if test -e "$E218_MSS_OWNER_STATE" || test -L "$E218_MSS_OWNER_STATE"; then
            backend='invalid-e218-state';
            tool='invalid';
            tool_identity='invalid';
        else
            if _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE"; then
                backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend);
                tool='legacy-unpinned';
            fi;
        fi;
    fi;
    echo "  owner_state=$state  recorded_backend=${backend:-none}  frontend=${tool:-none}  pinned_identity=${tool_identity:-none}";
    if test "$state" = ON && test "$tool" = legacy-unpinned; then
        warn '检测到兼容保留的E216活动MSS；当前可继续使用，但尚未固定后端实体。可在菜单10→7重新启用以迁移。';
    fi;
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2> /dev/null || true);
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue;
        seen[$identity]=1;
        if ! _e216_mss_backend_readable "$candidate"; then
            printf '  %-17s %s\n' "$candidate" 'unreadable/no-CAP_NET_ADMIN';
            continue;
        fi;
        readable=$((readable + 1));
        jump=0;
        rule=0;
        direct=0;
        "$candidate" -w 5 -t mangle -C POSTROUTING -j "$E216_MSS_CHAIN" > /dev/null 2>&1 && jump=1 || true;
        "$candidate" -w 5 -t mangle -C "$E216_MSS_CHAIN" -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1 && rule=1 || true;
        "$candidate" -w 5 -t mangle -C POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu > /dev/null 2>&1 && direct=1 || true;
        printf '  %-17s jump=%s rule=%s legacy_direct=%s real=%s%s\n' "$candidate" "$jump" "$rule" "$direct" "$identity" "$(test "$candidate" = "$backend" && echo ' [owner]' || true)";
    done < <(_e216_mss_candidate_order);
    if test "$readable" -eq 0; then
        warn '没有可读xtables后端；不能把状态文件当作规则生效或规则已清空的证据。';
        case "$state" in 
            OFF | UNSET)
                ! _e218_mss_static_evidence || return 1;
                info 'MSS状态结论：无静态所有权证据；运行态不可验证（未宣称OFF-clean）。';
                return 0
            ;;
        esac;
    fi;
    if _e218_mss_consistency; then
        case "$state" in 
            ON)
                verdict='ON-consistent'
            ;;
            *)
                verdict='OFF-clean'
            ;;
        esac;
        info "MSS状态结论：$verdict";
    else
        error 'MSS存在状态/规则/后端/服务漂移；请从菜单10→7显式重新启用或关闭。';
        return 1;
    fi
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_tx_close
_e220_mss_tx_close() {
    local real result="${2:-closed}" tmp;
    real=$(_e220_mss_tx_real "${1:-}") || return 1;
    result=$(printf '%s' "$result" | tr -cd 'A-Za-z0-9._-' | cut -c1-48);
    test -n "$result" || result=closed;
    tmp="$real/.closed.env.tmp.$$";
    { 
        printf 'version=%s\n' "$E220_VERSION";
        printf 'result=%s\n' "$result";
        printf 'closed_epoch=%s\n' "$(date +%s)"
    } > "$tmp" && chmod 0600 "$tmp" && mv -f -- "$tmp" "$real/.closed.env" && rm -f -- "$real/.active.env"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_tx_live
_e220_mss_tx_live() {
    _e242_mss_tx_live "$@"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_tx_real
_e220_mss_tx_real() {
    local requested="${1:-}" root_path root real parent;
    test -n "$requested" || return 1;
    root_path=$(_e220_mss_tx_root) || return 1;
    test -d "$root_path" && test ! -L "$root_path" || return 1;
    test -d "$requested" && test ! -L "$requested" || return 1;
    root=$(readlink -f -- "$root_path" 2> /dev/null || true);
    real=$(readlink -f -- "$requested" 2> /dev/null || true);
    test -n "$root" && test -d "$root" && test ! -L "$root" && test -n "$real" && test -d "$real" && test ! -L "$real" || return 1;
    parent=$(dirname -- "$real") || return 1;
    test "$parent" = "$root" || return 1;
    printf '%s\n' "$real"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_tx_root
_e220_mss_tx_root() {
    if test "${E220_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E220_INTERNAL_SELF_TEST_TMP:-}"; then
        printf '%s\n' "$E220_INTERNAL_SELF_TEST_TMP/tx";
    else
        printf '%s\n' "$E220_MSS_TX_ROOT";
    fi
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_tx_self_test
_e220_mss_tx_self_test() {
    ( local d tx order list rules normalized link script true_identity rc=0;
    d=$(mktemp -d /tmp/xray-e220-mss-selftest.XXXXXX) || return 1;
    trap 'rm -rf -- "${d:-}"' EXIT;
    E220_INTERNAL_SELF_TEST=1;
    E220_INTERNAL_SELF_TEST_TMP="$d";
    tx=$(_e220_mss_new_tx selftest) || return 1;
    case "$tx" in 
        "$d/tx/"*)

        ;;
        *)
            rc=1
        ;;
    esac;
    test -s "$tx/.active.env" && test "$(cat "$tx/.phase")" = created || rc=1;
    ! _e220_mss_preflight_readonly > /dev/null 2>&1 || rc=1;
    _e220_mss_tx_close "$tx" selftest || rc=1;
    test ! -e "$tx/.active.env" && test -s "$tx/.closed.env" || rc=1;
    _e220_mss_preflight_readonly > /dev/null 2>&1 || rc=1;
    tx=$(_e220_mss_new_tx created-only) || return 1;
    list="$tx/backends.tsv";
    _e220_mss_rollback "$tx" "$list" created || rc=1;
    test "$(cat "$tx/.phase")" = rolled-back || rc=1;
    _e220_mss_tx_close "$tx" created-selftest || rc=1;
    mkdir "$tx/nested" || rc=1;
    ! _e220_mss_tx_real "$tx/nested" > /dev/null 2>&1 || rc=1;
    link="$d/tx/transaction-link";
    ln -s "$tx" "$link" || rc=1;
    ! _e220_mss_tx_real "$link" > /dev/null 2>&1 || rc=1;
    rm -f -- "$link";
    rules="$d/rules.save";
    normalized="$d/rules.normalized";
    { 
        echo '# Generated by iptables-save v1.8.9 on Fri Aug 21 00:00:00 2026';
        echo '*filter';
        echo ':INPUT ACCEPT [0:0]';
        echo COMMIT;
        echo '# Completed on Fri Aug 21 00:00:00 2026'
    } > "$rules";
    _e220_mss_normalize_rules "$rules" > "$normalized" || rc=1;
    test "$(paste -sd, "$normalized")" = '*filter,:INPUT ACCEPT [0:0],COMMIT' || rc=1;
    script="$d/reconcile.sh";
    true_identity=$(_e218_mss_path_identity /bin/true 2> /dev/null || true);
    test -n "$true_identity" && _e218_mss_build_script /bin/true "$true_identity" "$script" || rc=1;
    grep -Fq 'unowned direct TCPMSS rule collision' "$script" || rc=1;
    grep -Fq 'exit 73' "$script" || rc=1;
    ! grep -Fq -- '-D POSTROUTING -p tcp' "$script" || rc=1;
    mkdir "$d/tx/invalid-marker" || rc=1;
    ln -s /dev/null "$d/tx/invalid-marker/.active.env" || rc=1;
    ! _e220_mss_preflight_readonly > /dev/null 2>&1 || rc=1;
    rm -f -- "$d/tx/invalid-marker/.active.env";
    rmdir -- "$d/tx/invalid-marker" || rc=1;
    _e220_mss_preflight_readonly > /dev/null 2>&1 || rc=1;
    tx=$(_e220_mss_new_tx rollback-order) || return 1;
    list="$tx/backends.tsv";
    : > "$list";
    chmod 0600 "$list";
    order="$d/order";
    : > "$order";
    function _e218_mss_stop_triggers () 
    { 
        echo stop >> "$order"
    };
    function _e220_mss_restore_control_files () 
    { 
        echo files >> "$order"
    };
    function _e220_mss_restore_backends () 
    { 
        echo backends >> "$order"
    };
    function _e220_mss_restore_control_services () 
    { 
        echo services >> "$order"
    };
    function _e220_mss_backends_match () 
    { 
        echo backend-match >> "$order"
    };
    function _e220_mss_control_matches () 
    { 
        echo matches >> "$order"
    };
    _e220_mss_rollback "$tx" "$list" mutation-started || rc=1;
    test "$(paste -sd, "$order")" = stop,files,backends,services,backend-match,matches || rc=1;
    test "$(cat "$tx/.phase")" = rolled-back || rc=1;
    _e220_mss_tx_close "$tx" rollback-selftest || rc=1;
    case "$E220_MSS_TX_ROOT" in 
        /var/backups/*)

        ;;
        *)
            rc=1
        ;;
    esac;
    return "$rc" )
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_unowned_direct_report
_e220_mss_unowned_direct_report() {
    local candidate identity rc found=0;
    local -A seen=();
    while IFS= read -r candidate; do
        identity=$(_e218_mss_backend_identity "$candidate" 2> /dev/null || true);
        test -n "$identity" && test -z "${seen[$identity]+x}" || continue;
        seen[$identity]=1;
        _e220_mss_backend_has_direct "$candidate";
        rc=$?;
        if test "$rc" -eq 0 && ! _e220_mss_legacy_direct_is_owned "$candidate"; then
            warn "检测到外部裸TCPMSS规则，E220未接管也不会删除：backend=$candidate real=$identity";
            found=1;
        fi;
    done < <(_e216_mss_candidate_order);
    return "$found"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mss_unresolved_report
_e220_mss_unresolved_report() {
    local root path found=0 state active preserve;
    root=$(_e220_mss_tx_root) || return 1;
    if test -e "$E220_MSS_CRITICAL_MARKER" || test -L "$E220_MSS_CRITICAL_MARKER"; then
        found=1;
        echo "  [critical] $E220_MSS_CRITICAL_MARKER";
        if test -f "$E220_MSS_CRITICAL_MARKER" && test ! -L "$E220_MSS_CRITICAL_MARKER"; then
            sed -n '1,20s/^/      /p' "$E220_MSS_CRITICAL_MARKER" 2> /dev/null || true;
        else
            echo '      marker=invalid-or-symlink';
        fi;
    fi;
    if test -e "$root" || test -L "$root"; then
        if ! test -d "$root" || test -L "$root"; then
            echo "  [invalid-root] $root";
            return 1;
        fi;
    else
        test "$found" -eq 0;
        return;
    fi;
    while IFS= read -r -d '' path; do
        test -n "$path" || continue;
        if test -L "$path"; then
            found=1;
            echo "  [invalid-transaction-link] $path";
            continue;
        fi;
        active="$path/.active.env";
        preserve="$path/.preserve.env";
        if test -e "$active" || test -L "$active"; then
            found=1;
            state=invalid;
            if test -f "$active" && test ! -L "$active"; then
                state=stale;
                _e220_mss_tx_live "$path" && state=live || true;
            fi;
            echo "  [${state}-active] $path";
        fi;
        if test -e "$preserve" || test -L "$preserve"; then
            found=1;
            if test -f "$preserve" && test ! -L "$preserve" && test -s "$preserve"; then
                echo "  [preserved] $path";
            else
                echo "  [invalid-preserve] $path";
            fi;
        fi;
    done < <(find "$root" -mindepth 1 -maxdepth 1 \( -type d -o -type l \) -print0 2> /dev/null | LC_ALL=C sort -z);
    test "$found" -eq 0
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_mtu_disable_unlocked
_e220_mtu_disable_unlocked() {
    local force="${1:-}" answer="" tx removed rc=0 restore_rc=0;
    if ! _e214_mtu_any_state; then
        info 'E214宿主机MTU策略未启用。';
        return 0;
    fi;
    if test "$force" != force; then
        warn '将恢复脚本首次接管每张网卡前记录的MTU，并移除开机/5分钟复检。';
        read -rp '输入 RESTORE-MTU 确认: ' answer || true;
        test "$answer" = RESTORE-MTU || { 
            info '已取消。';
            return 0
        };
    fi;
    if test -e "$E214_MTU_BASELINE" || test -L "$E214_MTU_BASELINE"; then
        _e214_mtu_baseline_validate "$E214_MTU_BASELINE" || { 
            error 'MTU基线损坏；拒绝猜测原值。';
            return 1
        };
    fi;
    if test -e "$E214_MTU_STATE" || test -L "$E214_MTU_STATE"; then
        _e214_mtu_state_validate "$E214_MTU_STATE" "$E214_MTU_BASELINE" || { 
            error 'MTU状态/基线校验失败；拒绝破坏恢复证据。';
            return 1
        };
    fi;
    tx=$(_e214_new_tx mtu-disable) || return 1;
    _e140_system_snapshot "$tx/system" || { 
        _e214_tx_close "$tx" || true;
        return 1
    };
    systemctl disable --now "$E214_MTU_TIMER_UNIT" "$E214_MTU_UNIT" > /dev/null 2>&1 || true;
    test ! -s "$E214_MTU_BASELINE" || _e214_mtu_restore_baseline_except "$E214_MTU_BASELINE" "" || rc=1;
    if test "$rc" -eq 0; then
        rm -f -- "$E214_MTU_STATE" "$E214_MTU_BASELINE" "$E214_MTU_SERVICE" "$E214_MTU_TIMER" || rc=1;
        systemctl daemon-reload > /dev/null 2>&1 || rc=1;
        systemctl is-active --quiet "$E214_MTU_UNIT" 2> /dev/null && rc=1 || true;
        systemctl is-active --quiet "$E214_MTU_TIMER_UNIT" 2> /dev/null && rc=1 || true;
        systemctl is-enabled --quiet "$E214_MTU_UNIT" 2> /dev/null && rc=1 || true;
        systemctl is-enabled --quiet "$E214_MTU_TIMER_UNIT" 2> /dev/null && rc=1 || true;
        for removed in "$E214_MTU_STATE" "$E214_MTU_BASELINE" "$E214_MTU_SERVICE" "$E214_MTU_TIMER";
        do
            test ! -e "$removed" && test ! -L "$removed" || rc=1;
        done;
    fi;
    if test "$rc" -eq 0; then
        info "E214宿主机MTU策略已退出并恢复基线；快照：$tx/system";
        _e214_tx_close "$tx" || true;
        return 0;
    fi;
    error 'MTU退出未通过，恢复退出前完整状态。';
    _e140_system_restore "$tx/system" || restore_rc=1;
    if test "$restore_rc" -ne 0; then
        _e214_mark_critical mtu-disable "$tx/system" 'MTU disable rollback/readback failed' || true;
        error "严重：MTU退出回滚不完整；快照：$tx/system";
    fi;
    _e214_tx_close "$tx" || true;
    return 1
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_prepare
_e220_prepare() {
    local root;
    if test "${E220_INTERNAL_SELF_TEST:-0}" != 1; then
        _e218_prepare || return 1;
        _e220_secure_private_dir "$E220_DIR" || return 1;
    fi;
    root=$(_e220_mss_tx_root) || return 1;
    _e220_secure_private_dir "$root"
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_secure_private_dir
_e220_secure_private_dir() {
    local dir="${1:-}";
    test -n "$dir" || return 1;
    if test -e "$dir" || test -L "$dir"; then
        test -d "$dir" && test ! -L "$dir" || { 
            error "拒绝使用非目录或符号链接：$dir";
            return 1
        };
        test "$(stat -c '%u' "$dir" 2> /dev/null || true)" = 0 || { 
            error "专用事务目录不属于root：$dir";
            return 1
        };
        chmod 0700 "$dir" || return 1;
    else
        install -d -o 0 -g 0 -m 0700 -- "$dir" || return 1;
    fi;
    test -d "$dir" && test ! -L "$dir" && test "$(stat -c '%a:%u:%g' "$dir" 2> /dev/null || true)" = 700:0:0
}
# EEX3-FUNCTION mtu_mss_e206_220 _e220_self_test
_e220_self_test() {
