# EEX3-FUNCTION mtu_mss_e206_220 _e220_structure_audit
_e220_structure_audit() {
    local rc=0 menu help installer hot_pre hot_verify mtu_disable small_enable;
    local mss_enable mss_disable mss_rollback mss_status mss_menu legacy_mss uninstaller dispatchers;
    local mss_builder mss_cleanup stop_line files_line backends_line services_line post_match_line;
    _e214_structure_audit > /dev/null || rc=1;
    menu=$(declare -f _e214_main_menu 2> /dev/null || true);
