    hot_verify=$(declare -f _e214_hot_verify 2> /dev/null || true);
    mtu_disable=$(declare -f _e214_mtu_disable 2> /dev/null || true);
    small_enable=$(declare -f _e202_small_bbr_enable 2> /dev/null || true);
    mss_enable=$(declare -f _e218_mss_enable 2> /dev/null || true);
    mss_disable=$(declare -f _e218_mss_disable 2> /dev/null || true);
    mss_rollback=$(declare -f _e220_mss_rollback 2> /dev/null || true);
    mss_status=$(declare -f _e218_mss_status 2> /dev/null || true);
    mss_menu=$(declare -f _e220_mss_menu_action 2> /dev/null || true);
    legacy_mss=$(declare -f _e88_manual_mss_clamp 2> /dev/null || true);
    uninstaller=$(declare -f do_uninstall 2> /dev/null || true);
    mss_builder=$(declare -f _e218_mss_build_script 2> /dev/null || true);
    mss_cleanup=$(declare -f _e216_mss_cleanup_backend 2> /dev/null || true);
    dispatchers=$(grep -c '^# V199e243 SINGLE FINAL DISPATCHER$' "$SCRIPT_PATH" || true);
    echo 'V199e243 structure audit:';
    test "$SCRIPT_VERSION" = 199e243 && test "$E214_VERSION" = 199e243 && test "$E220_VERSION" = 199e243 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    ! LC_ALL=C grep -q $'\r' "$SCRIPT_PATH" || rc=1;
    grep -q 'V199e243 - 事务稳态版' <<< "$menu" || rc=1;
    grep -q 'E243一键稳态升级（强制默认出口MTU=1350）' <<< "$menu" || rc=1;
    grep -q '27) 宿主机网卡 MTU' <<< "$menu" || rc=1;
    grep -q 'E220_SELF_PATH' <<< "$installer" || rc=1;
    grep -q 'E220_SELF_PATH' <<< "$hot_verify" || rc=1;
    grep -q '_e220_structure_audit' <<< "$hot_pre" || rc=1;
    grep -q '_e220_mss_preflight_readonly' <<< "$hot_pre" || rc=1;
    grep -q 'xray-mtu-e214.lock' <<< "$mtu_disable" || rc=1;
    grep -q '_e220_mtu_disable_unlocked' <<< "$mtu_disable" || rc=1;
    grep -q 'assignments.*-ge 25' <<< "$small_enable" || rc=1;
    grep -q '26项档还会限制TIME_WAIT桶上限' <<< "$small_enable" || rc=1;
    grep -q '_e220_mss_new_tx' <<< "$mss_enable" || rc=1;
    grep -q '_e220_mss_new_tx' <<< "$mss_disable" || rc=1;
    grep -q '_e242_mss_disable_units_idempotent' <<< "$mss_disable" || rc=1;
    ! grep -q 'systemctl disable.*E216_MSS_TIMER_UNIT' <<< "$mss_disable" || rc=1;
    ! grep -q 'mktemp -d /tmp/xray-e218-mss' <<< "$mss_enable$mss_disable" || rc=1;
    grep -q '作用域是宿主机全部IPv4 TCP' <<< "$mss_enable" || rc=1;
    grep -q '_e220_mss_unresolved_report' <<< "$mss_status" || rc=1;
    grep -q 'APPLY-MSS-CLAMP' <<< "$mss_menu" || rc=1;
    grep -q 'DISABLE-MSS-CLAMP' <<< "$mss_menu" || rc=1;
    grep -q '_e220_mss_menu_action' <<< "$legacy_mss" || rc=1;
    grep -q '_e220_mss_preflight_readonly' <<< "$uninstaller" || rc=1;
    ! grep -q '1=ON.*0=OFF' <<< "$mss_menu$legacy_mss" || rc=1;
    grep -q 'unowned direct TCPMSS rule collision' <<< "$mss_builder" || rc=1;
    grep -q '_e220_mss_legacy_direct_is_owned' <<< "$mss_cleanup" || rc=1;
    stop_line=$(grep -n '_e218_mss_stop_triggers' <<< "$mss_rollback" | head -n1 | cut -d: -f1 || true);
    files_line=$(grep -n '_e220_mss_restore_control_files' <<< "$mss_rollback" | head -n1 | cut -d: -f1 || true);
    backends_line=$(grep -n '_e220_mss_restore_backends' <<< "$mss_rollback" | head -n1 | cut -d: -f1 || true);
    services_line=$(grep -n '_e220_mss_restore_control_services' <<< "$mss_rollback" | head -n1 | cut -d: -f1 || true);
    post_match_line=$(grep -n '_e220_mss_backends_match' <<< "$mss_rollback" | tail -n1 | cut -d: -f1 || true);
    [[ "$stop_line" =~ ^[0-9]+$ && "$files_line" =~ ^[0-9]+$ && "$backends_line" =~ ^[0-9]+$ && "$services_line" =~ ^[0-9]+$ ]] || rc=1;
    if [[ "$stop_line" =~ ^[0-9]+$ && "$files_line" =~ ^[0-9]+$ && "$backends_line" =~ ^[0-9]+$ && "$services_line" =~ ^[0-9]+$ && "$post_match_line" =~ ^[0-9]+$ ]]; then
        ((stop_line < files_line && files_line < backends_line           && backends_line < services_line && services_line < post_match_line)) || rc=1;
    else
        rc=1;
    fi;
    grep -q '新装：安装/新建节点' <<< "$help" || rc=1;
    grep -q '升级：直接运行下载的E242并选择一键升级' <<< "$help" || rc=1;
    grep -q '高防清洗/动态路由隐藏隧道' <<< "$help" || rc=1;
    grep -Fq -- '--e220-summary)' "$SCRIPT_PATH" || rc=1;
    grep -Fq -- '--mss-recover)' "$SCRIPT_PATH" || rc=1;
    grep -q '_e220_mss_normalize_rules' <<< "$(declare -f _e220_mss_backends_match 2> /dev/null || true)" || rc=1;
    grep -q 'created)' <<< "$(declare -f _e220_mss_rollback 2> /dev/null || true)" || rc=1;
    for _e220_f in _e220_choose_banaction_for_backend _e220_fail2ban_action_self_test _e220_mss_capture_control _e220_mss_capture_backends _e220_mss_restore_backends _e220_mss_backends_match _e220_mss_backend_has_managed _e220_mss_backend_has_direct _e220_mss_legacy_direct_is_owned _e220_mss_rollback _e220_mss_recover _e220_mss_normalize_rules _e220_mss_tx_self_test;
    do
        declare -F "$_e220_f" > /dev/null 2>&1 || rc=1;
    done;
    ! grep -q '_e159_choose_banaction_base' <<< "$(declare -f _e220_choose_banaction_for_backend 2> /dev/null || true)" || rc=1;
    if test "$rc" -eq 0; then
        echo '  result=PASS';
    else
        echo '  result=FAIL';
    fi;
    return "$rc"
}
