# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_auto_preflight
_e242_auto_preflight() {
    local owner="${1:-}" old_version="${2:-}" generation="" iface="" tmp="";
    test "$EUID" -eq 0 || { 
        error 'E266自动升级必须使用root。';
        return 1
    };
    bash -n "$(_eex6_release_source)" || return 1;
    test "$SCRIPT_VERSION" = "$E242_VERSION" || return 1;
    if test -n "$old_version"; then
        generation=${old_version##*e};
        [[ "$generation" =~ ^[0-9]+$ ]] || return 1;
        ((generation <= 262 || generation == 266)) || { 
            error "已安装版本$old_version比E266更新，拒绝降级覆盖。";
            return 1
        };
    fi;
    _e266_release_binding_gate || { 
        error 'E266发布结构门禁失败，自动升级尚未开始。';
        return 1
    };
    _e242_non_mss_critical_preflight || return 1;
    _e242_mss_plan_readonly > /dev/null || return 1;
    if _e214_mtu_any_state; then
        _e214_mtu_persistence_validate || return 1;
    fi;
    iface=$(_e214_mtu_default_iface 2> /dev/null || true);
    _e214_mtu_iface_candidate "$iface" || { 
        error '未识别到可安全设置MTU=1350的宿主机默认出口；升级尚未开始。';
        return 1
    };
    if test -n "$owner"; then
        test -n "$old_version" && _e242_old_script_can_exit_owner "$owner" "$old_version" || { 
            error "活动小BBR所有者=$owner，但已安装xrv版本=${old_version:-不可验证}不能证明可安全退出它。";
            error '未修改网络；请保留并使用该小BBR所属旧版脚本退出。';
            return 1
        };
    else
        tmp=$(mktemp /tmp/xray-e242-preflight-profile.XXXXXX) || return 1;
        if ! _e242_inactive_small_profile "$tmp" 0; then
            rm -f -- "$tmp";
            return 1;
        fi;
        rm -f -- "$tmp";
    fi
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_auto_tx_root_ok
_e242_auto_tx_root_ok() {
