    fi;
    root=$(readlink -f -- "$E214_TX_ROOT" 2> /dev/null || true);
    test -n "$root" || return 1;
    case "$real" in 
        "$root"/auto-upgrade-e266-*)

        ;;
        *)
            return 1
        ;;
    esac;
    test "$(stat -c %u "$real" 2> /dev/null || true)" = 0
}
