# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_e204_warp_marker_snapshot
_e242_e204_warp_marker_snapshot() {
    local marker="${1:-$E204_CRITICAL_MARKER}" tx_root="${2:-$E204_TX_ROOT}";
    local line key value count=0 operation backup root real parent pid start actual;
    local -A seen=();
    test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker" && test "$(stat -c %u "$marker" 2> /dev/null || true)" = 0 || return 1;
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z0-9_]+)=(.*)$ ]] || return 1;
        key=${BASH_REMATCH[1]};
        value=${BASH_REMATCH[2]};
        case "$key" in 
            time | operation | backup | detail)

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${seen[$key]+x}" && test -n "$value" || return 1;
        seen[$key]=1;
        count=$((count + 1));
    done < "$marker";
    test "$count" -eq 4 || return 1;
    operation=$(_e242_independent_value "$marker" operation) || return 1;
    backup=$(_e242_independent_value "$marker" backup) || return 1;
    test "$operation" = warp-local-reconcile || return 1;
    root=$(readlink -f -- "$tx_root" 2> /dev/null || true);
    real=$(readlink -f -- "$backup" 2> /dev/null || true);
    test -n "$root" && test -d "$root" && test ! -L "$tx_root" && test -n "$real" && test -d "$real" && test ! -L "$backup" || return 1;
    case "$real" in 
        "$root"/warp-local-reconcile-*/system)

        ;;
        *)
            return 1
        ;;
    esac;
    parent=${real%/system};
    if test -e "$parent/.active.env" || test -L "$parent/.active.env"; then
        test -f "$parent/.active.env" && test ! -L "$parent/.active.env" || return 1;
        pid=$(awk -F= '$1=="pid"{n++;v=$2}END{if(n==1)print v;else exit 1}' "$parent/.active.env") || return 1;
        start=$(awk -F= '$1=="start"{n++;v=$2}END{if(n==1)print v;else exit 1}' "$parent/.active.env") || return 1;
        [[ "$pid" =~ ^[1-9][0-9]*$ && "$start" =~ ^[0-9]+$ ]] || return 1;
        if kill -0 "$pid" 2> /dev/null; then
            actual=$(_e214_proc_start_time "$pid" 2> /dev/null || true);
            test -n "$actual" && test "$actual" != "$start" || { 
                error "E204 WARP恢复事务仍存活，拒绝并发恢复：pid=$pid" 1>&2;
                return 1
            };
        fi;
    fi;
    _e242_warp_package_snapshot_validate "$parent/warp-packages.before" || return 1;
    for key in control.sha256 present.list absent.list runtime-sysctl.env services.env;
    do
        test -f "$real/$key" && test ! -L "$real/$key" || return 1;
    done;
    test "$(stat -c %u "$real" 2> /dev/null || true)" = 0 && test -z "$(find "$real" -mindepth 1 ! -uid 0 -print -quit 2> /dev/null)" && test -z "$(find "$real" -mindepth 1 -type l -print -quit 2> /dev/null)" || return 1;
    ( cd "$real" && sha256sum -c control.sha256 > /dev/null 2>&1 ) || return 1;
    if test -s "$real/files.tar"; then
        test -f "$real/archive.sha256" && test ! -L "$real/archive.sha256" && ( cd "$real" && sha256sum -c archive.sha256 > /dev/null 2>&1 ) && tar -tf "$real/files.tar" > /dev/null 2>&1 || return 1;
    fi;
    printf '%s\n' "$real"
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_entry_mock_self_test
_e242_entry_mock_self_test() {
    ( local d order rc=0;
    d=$(mktemp -d /tmp/xray-e242-entry-selftest.XXXXXX) || return 1;
