# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_expected_public_digest
_e242_expected_public_digest() {
    local file="${1:-}" priv="" embedded="" value="";
    test -f "$file" && test ! -L "$file" || return 1;
    priv=$(jq -r '.inbounds[]? |
      select(.protocol=="vless" and (.streamSettings.security//"")=="reality") |
      .streamSettings.realitySettings.privateKey // empty' "$file" 2> /dev/null | awk 'NF&&!done{print;done=1}');
    if test -z "$priv"; then
        printf 'absent\n';
        return 0;
    fi;
    embedded=$(jq -r '.inbounds[]? |
      select(.protocol=="vless" and (.streamSettings.security//"")=="reality") |
      (.streamSettings.realitySettings.password //
       .streamSettings.realitySettings.publicKey // empty)' "$file" 2> /dev/null | awk 'NF&&!done{print;done=1}');
    value=$(_e124_reality_password_for_private "$priv" "$embedded" 2> /dev/null || true);
    _e124_valid_x25519_value "$value" || return 1;
    printf '%s' "$value" | sha256sum | awk '{print $1}'
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_file_digest
_e242_file_digest() {
    local file="${1:-}";
    if test -e "$file" || test -L "$file"; then
        test -f "$file" && test ! -L "$file" || return 1;
        sha256sum -- "$file" 2> /dev/null | awk '{print $1}';
    else
        printf 'absent\n';
    fi
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_help
_e242_help() {
    _e220_help;
    cat <<'EOF_E242_HELP'

E242新增：
  --auto-upgrade-reboot               一次确认完整升级、小BBR、MTU=1350并重启
  --auto-upgrade-no-reboot            相同完整事务，但不自动重启
  --hot-update-raw                    专家用原始热更新（要求小BBR已退出）

E242撤销E240错误的“升级保持原MTU”回归：一键升级必须强制MTU=1350。
同时修复E238现场恢复套娃：兼容并规范化e238-previous-*标记，重试失败
原样保留同一标记/快照，不再生成新operation。回滚分开报告system/Xray、
MSS和WARP软件包结果。旧小BBR退出只调用旧脚本公开CLI，不再source私有函数。
小BBR保存档只提示一次；独立IPv6恢复不再伪造
“上次中断”热更新标记；Reality privateKey作为唯一权威源，缺失或漂移的
Password(pbk)兼容缓存会在密封事务内重新派生、原子写入并读回，不轮换密钥。
同时兼容读取E232/E234/E238/E240的合法MSS活动记录与失败升级快照。

直接运行下载的E242时，如发现已安装旧版，只需输入一次AUTO-UPGRADE-E243。
可验证的E194+活动档由旧脚本安全退出并原样迁移；E190/E192旧6/13项
档明确迁移到模式3F2。无活动档时使用有效保存档，无保存档时也使用
模式3F2。MSS无需预先关闭：一致状态原样保留，可验证的旧中断事务先
恢复，脚本自有ON/OFF漂移在精确快照后自动收敛；外部TCPMSS规则不动。
一键升级在同一个外层事务内强制默认出口MTU=1350，不建立MTU子事务，
不要求第二次确认；菜单27手动设置MTU也只确认一次，不再要求KEEP-MTU。
新建节点或修改用户后，第28项应用设置会自动重放，
每个稳定阶段都会记录无凭据状态并立即核对语义身份；最后验证
Xray/WARP/IPv6/小BBR/MTU/MSS后才输出节点摘要与二维码。
EOF_E242_HELP

}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_host_full_runtime_state_readonly
_e242_host_full_runtime_state_readonly() {
    local priority table service rule_up=0 route_up=0 service_up=0;
    priority=$(_e138_state_get full_priority "${E140_FULL_RULE_PRIORITY:-11990}");
    table=$(_e138_state_get full_table "${E140_FULL_TABLE:-51820}");
    [[ "$priority" =~ ^[0-9]{1,10}$ && "$table" =~ ^[0-9]{1,10}$ ]] || return 1;
    ip -4 rule show 2> /dev/null | awk -v p="$priority" -v t="$table" '
          $1 == p ":" && ($0 ~ ("lookup " t "([[:space:]]|$)") ||
                            $0 ~ ("table " t "([[:space:]]|$)")) {ok=1}
          END{exit !ok}' && rule_up=1 || true;
    test -n "$(ip -4 route show table "$table" 2> /dev/null)" && route_up=1 || true;
    service=$(_e140_warp_service_name 2> /dev/null || true);
    test -n "$service" && systemctl is-active --quiet "$service" 2> /dev/null && service_up=1 || true;
    if test "$rule_up:$route_up:$service_up" = 1:1:1; then
        printf 'active\n';
    else
        if test "$rule_up:$route_up" = 0:0; then
            printf 'inactive\n';
        else
            printf 'partial\n';
        fi;
    fi
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_identity_bundle_capture
_e242_identity_bundle_capture() {
