    test -n "$dir" && test ! -e "$dir" && test ! -L "$dir" || return 1;
    install -d -o 0 -g 0 -m 0700 -- "$dir" || return 1;
    _e242_inbounds_canonical "$cfg" > "$dir/inbounds.canonical.json" || return 1;
    chmod 0600 "$dir/inbounds.canonical.json" || return 1;
    semantic=$(sha256sum "$dir/inbounds.canonical.json" | awk '{print $1}') || return 1;
