    utime=$(_e242_user_map_digest "$USER_TIME_MAP") || return 1;
    pub=$(_e242_expected_public_digest "$cfg") || return 1;
    { 
        printf 'version=199e266\n';
        printf 'semantic_sha256=%s\n' "$semantic";
        printf 'raw_sha256=%s\n' "$raw";
        printf 'user_sni_sha256=%s\n' "$sni";
        printf 'user_time_sha256=%s\n' "$utime";
        printf 'public_key_sha256=%s\n' "$pub"
    } > "$dir/identity.env" || return 1;
    chmod 0600 "$dir/identity.env" || return 1
}
