# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_inbounds_canonical
_e242_inbounds_canonical() {
    local file="${1:-}";
    test -f "$file" && test ! -L "$file" && command -v jq > /dev/null 2>&1 || return 1;
    jq -e '(.inbounds // []) | type == "array"' "$file" > /dev/null 2>&1 || return 1;
    jq -S -c '
      def reality:
        .protocol == "vless" and
        ((.streamSettings.security // "") == "reality");
      def canonical_reality:
        .settings = (.settings // {}) |
        .settings.decryption = "none" |
        .settings.clients = ((.settings.clients // []) |
          map(. + {flow:"xtls-rprx-vision"})) |
        .streamSettings = (.streamSettings // {}) |
        .streamSettings.network = "raw" |
        .streamSettings.realitySettings =
          ((.streamSettings.realitySettings // {}) |
            .show = false |
            .maxTimeDiff = 60000 |
            .target = (.target // .dest) |
            del(.dest, .limitFallbackUpload, .limitFallbackDownload)) |
        .sniffing = ((.sniffing // {}) |
          .enabled = true |
          .metadataOnly = true |
          .routeOnly = true);
      (.inbounds // [])
      | map(if reality then canonical_reality else . end)
      | sort_by([(.tag // ""), (.protocol // ""),
                 (.listen // ""), ((.port // 0) | tostring), tojson])
    ' "$file" 2> /dev/null
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_inbounds_digest
_e242_inbounds_digest() {
    local file="${1:-}";
    _e242_inbounds_canonical "$file" | sha256sum | awk '{print $1}'
