# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_complete_on_without_legacy
_e242_mss_complete_on_without_legacy() {
    local backend owner_backend tool identity rc;
    _e218_mss_owner_state_validate "$E218_MSS_OWNER_STATE" || return 1;
    _e216_mss_backend_state_validate "$E216_MSS_BACKEND_STATE" || return 1;
    backend=$(_e216_mss_state_value "$E216_MSS_BACKEND_STATE" backend) || return 1;
    owner_backend=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" backend) || return 1;
    tool=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_path) || return 1;
    identity=$(_e218_mss_owner_state_value "$E218_MSS_OWNER_STATE" tool_identity) || return 1;
    test "$backend" = "$owner_backend" && test "$(readlink -f -- "$tool" 2> /dev/null || true)" = "$identity" || return 1;
    test -f "$E216_MSS_SCRIPT" && test ! -L "$E216_MSS_SCRIPT" && bash -n "$E216_MSS_SCRIPT" || return 1;
    test -f "$E216_MSS_SERVICE" && test ! -L "$E216_MSS_SERVICE" && test -f "$E216_MSS_TIMER" && test ! -L "$E216_MSS_TIMER" || return 1;
    systemctl is-enabled --quiet "$E216_MSS_SERVICE_UNIT" 2> /dev/null || return 1;
    systemctl is-enabled --quiet "$E216_MSS_TIMER_UNIT" 2> /dev/null || return 1;
    systemctl is-active --quiet "$E216_MSS_TIMER_UNIT" 2> /dev/null || return 1;
    _e220_mss_backend_has_managed "$backend";
    rc=$?;
    test "$rc" -eq 0
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_control_types_safe
_e242_mss_control_types_safe() {
    local path;
    for path in "$E88_MSS_STATE_FILE" "$E216_MSS_BACKEND_STATE" "$E218_MSS_OWNER_STATE" "$E216_MSS_SCRIPT" "$E216_MSS_SERVICE" "$E216_MSS_TIMER";
    do
        if test -e "$path" || test -L "$path"; then
            test -f "$path" && test ! -L "$path" || { 
                error "MSS控制路径不是可信普通文件：$path" 1>&2;
                return 1
            };
        fi;
    done
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_converge_expected
_e242_mss_converge_expected() {
    local expected="${1:-}";
    case "$expected" in 
        on | off)

        ;;
        *)
            return 1
        ;;
    esac;
    if _e242_mss_verify_intent "$expected"; then
        return 0;
    fi;
    case "$expected" in 
        off)
            info '旧网络基线恢复后收敛MSS：仅清理脚本自有残留并保持OFF。';
            _e218_mss_disable || return 1
        ;;
        on)
            info '旧网络基线恢复后收敛MSS：清理旧层并按唯一后端重建为ON。';
            _e218_mss_disable && _e218_mss_enable || return 1
        ;;
    esac;
    _e242_mss_verify_intent "$expected" || { 
        error "旧小BBR退出后MSS意图收敛失败：expected=$expected";
        return 1
    }
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_disable_units_idempotent
_e242_mss_disable_units_idempotent() {
    local unit;
    for unit in "$E216_MSS_TIMER_UNIT" "$E216_MSS_SERVICE_UNIT";
    do
        systemctl stop "$unit" > /dev/null 2>&1 || true;
        systemctl disable "$unit" > /dev/null 2>&1 || true;
    done;
    return 0
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_expected_from_plan
_e242_mss_expected_from_plan() {
    case "${1:-}" in 
        steady-on | repair-on)
            printf 'on\n'
        ;;
        steady-off | repair-off)
            printf 'off\n'
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_idempotent_unit_mock_self_test
_e242_mss_idempotent_unit_mock_self_test() {
    ( local calls=0;
