    };
    _e242_mss_disable_units_idempotent || return 1;
    test "$calls" -eq 4 )
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_outer_capture
_e242_mss_outer_capture() {
    local snapshot="${1:-}" plan="${2:-}" final meta backend_mode=exact readable="";
    test -d "$snapshot" && test ! -L "$snapshot" || return 1;
    case "$plan" in 
        steady-on | steady-off | repair-on | repair-off)

        ;;
        *)
            return 1
        ;;
    esac;
    final="$snapshot/e242-mss-exact";
    test ! -e "$final" && test ! -L "$final" || return 1;
