    else
        _e220_mss_capture_backends "$final" "$final/backends.tsv" || { 
            error "E242 MSS外层快照失败：$readable 个可读xtables后端未能完整save/restore身份密封。";
            rm -rf -- "$final";
            return 1
        };
    fi;
    meta="$final/outer.env";
    { 
        printf 'version=199e266\n';
        printf 'plan=%s\n' "$plan";
        printf 'backend_mode=%s\n' "$backend_mode";
        printf 'created_epoch=%s\n' "$(date +%s)"
    } > "$meta" && chmod 0600 "$meta" || { 
        rm -rf -- "$final";
        return 1
    };
    ( cd "$final" && sha256sum outer.env > outer.sha256 ) || { 
        rm -rf -- "$final";
        return 1
    };
    chmod 0600 "$final/outer.sha256" || { 
        rm -rf -- "$final";
        return 1
    };
    _e242_mss_outer_validate "$final" || { 
        rm -rf -- "$final";
        return 1
    }
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_outer_restore
_e242_mss_outer_restore() {
    local d="${1:-}" rc=0 backend_mode=exact;
    _e242_mss_outer_validate "$d" || return 1;
    backend_mode=$(_e218_mss_owner_state_value "$d/outer.env" backend_mode 2> /dev/null || echo exact);
