        _e220_mss_restore_backends "$d" "$d/backends.tsv" || rc=1;
        _e220_mss_backends_match "$d" "$d/backends.tsv" || rc=1;
    else
        _e218_mss_verify_off || rc=1;
    fi;
    _e220_mss_control_matches "$d" || rc=1;
    return "$rc"
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_outer_validate
_e242_mss_outer_validate() {
    local d="${1:-}" version plan epoch backend_mode=exact line key value count=0;
    local -A seen=();
    test -d "$d" && test ! -L "$d" && test -f "$d/outer.env" && test ! -L "$d/outer.env" && test -f "$d/outer.sha256" && test ! -L "$d/outer.sha256" || return 1;
    ( cd "$d" && sha256sum -c outer.sha256 > /dev/null 2>&1 ) || return 1;
