        [[ "$line" =~ ^([a-z_]+)=(.*)$ ]] || return 1;
        key=${BASH_REMATCH[1]};
        value=${BASH_REMATCH[2]};
        case "$key" in 
            version | plan | backend_mode | created_epoch)

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${seen[$key]+x}" && test -n "$value" || return 1;
        seen[$key]=1;
        count=$((count + 1));
    done < "$d/outer.env";
    version=$(_e218_mss_owner_state_value "$d/outer.env" version) || return 1;
    plan=$(_e218_mss_owner_state_value "$d/outer.env" plan) || return 1;
    epoch=$(_e218_mss_owner_state_value "$d/outer.env" created_epoch) || return 1;
    case "$version" in 
        199e238 | 199e240 | 199e242 | 199e243 | 199e244 | 199e246 | 199e252 | 199e254 | 199e256 | 199e258 | 199e260 | 199e262 | 199e266)
            test "$count" -eq 4 || return 1;
            backend_mode=$(_e218_mss_owner_state_value "$d/outer.env" backend_mode) || return 1;
            case "$backend_mode" in 
                exact | none)

                ;;
                *)
                    return 1
                ;;
            esac
        ;;
        199e226 | 199e228 | 199e230 | 199e232 | 199e234 | 199e236)
            test "$count" -eq 3 && test -z "${seen[backend_mode]+x}" || return 1;
            backend_mode=exact
        ;;
        *)
            return 1
        ;;
    esac;
    [[ "$epoch" =~ ^[0-9]{1,20}$ ]] || return 1;
    case "$plan" in 
        steady-on | steady-off | repair-on | repair-off)

        ;;
        *)
            return 1
        ;;
    esac;
    _e220_mss_control_validate "$d" || return 1;
    case "$backend_mode" in 
        exact)
            _e220_mss_backends_validate "$d" "$d/backends.tsv"
        ;;
        none)
            { 
                test "$version" = 199e238 || test "$version" = 199e240 || test "$version" = 199e242 || test "$version" = 199e243 || test "$version" = 199e244 || test "$version" = 199e246 || test "$version" = 199e252 || test "$version" = 199e254 || test "$version" = 199e256 || test "$version" = 199e258 || test "$version" = 199e260 || test "$version" = 199e262 || test "$version" = 199e266
            } && test "$plan" = steady-off && test -f "$d/backends.tsv" && test ! -L "$d/backends.tsv" && test ! -s "$d/backends.tsv" && test ! -e "$d/backends.sha256" && test ! -L "$d/backends.sha256" && test -z "$(find "$d" -maxdepth 1 -name 'firewall-*.rules*' -print -quit 2> /dev/null)"
        ;;
    esac
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_plan_readonly
_e242_mss_plan_readonly() {
    local recovery state desired direct_rc;
    recovery=$(_e242_mss_recovery_candidate) || return 1;
    if test "$recovery" != none; then
        printf 'recover\n';
        return 0;
    fi;
    _e242_mss_control_types_safe || return 1;
    state=$(_e218_mss_owner_state 2> /dev/null || echo INVALID);
    case "$state" in 
        ON | OFF | UNSET)

        ;;
        *)
            error 'MSS ON/OFF状态文件损坏；不能自动猜测用户意图。' 1>&2;
            return 1
        ;;
    esac;
    if _e218_mss_consistency; then
        if test "$state" = ON; then
            printf 'steady-on\n';
        else
            printf 'steady-off\n';
        fi;
        return 0;
    fi;
    case "$state" in 
        ON)
            desired=on
        ;;
        OFF)
            desired=off
        ;;
        UNSET)
            if _e242_mss_complete_on_without_legacy; then
                desired=on;
            else
                desired=off;
            fi
        ;;
    esac;
    if test "$desired" = on; then
        if _e220_mss_unowned_direct_report 1>&2; then
            direct_rc=0;
        else
            direct_rc=$?;
        fi;
        if test "$direct_rc" -ne 0; then
            error 'MSS计划为ON，但存在外部裸TCPMSS规则；不会覆盖或形成双重Clamp。' 1>&2;
            return 1;
        fi;
    fi;
