        error 'MSS漂移需要systemd事务收敛，但当前systemd未运行。' 1>&2;
        return 1
    };
    printf 'repair-%s\n' "$desired"
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_readable_backend_count
_e242_mss_readable_backend_count() {
    local candidate="" identity="" count=0;
    local -A seen=();
