# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_reconcile_plan
_e242_mss_reconcile_plan() {
    local plan="${1:-}" expected;
    expected=$(_e242_mss_expected_from_plan "$plan") || return 1;
    case "$plan" in 
        steady-on | steady-off)

        ;;
        repair-off)
            info '自动收敛MSS漂移：保留外部规则，仅清理脚本自有残留并保持OFF。';
            _e218_mss_disable || return 1
        ;;
        repair-on)
            info '自动收敛MSS漂移：先事务清理旧层，再按唯一后端重建并保持ON。';
            _e218_mss_disable && _e218_mss_enable || return 1
        ;;
        *)
            return 1
        ;;
