    root=$(_e220_mss_tx_root) || return 1;
    test -d "$root" && test ! -L "$root" || { 
        error "MSS事务根目录无效：$root" 1>&2;
        return 1
    };
    selected=$(_e220_mss_select_recovery_tx 2> /dev/null || true);
    test -n "$selected" || { 
        error 'MSS存在恢复证据，但无法唯一解析安全事务。' 1>&2;
        _e220_mss_unresolved_report 1>&2 || true;
        return 1
    };
    while IFS= read -r -d '' path; do
        test ! -L "$path" && test -d "$path" || { 
            error "MSS事务目录类型异常：$path" 1>&2;
            return 1
        };
        active="$path/.active.env";
        preserve="$path/.preserve.env";
        has=0;
        if test -e "$active" || test -L "$active"; then
            _e242_mss_active_record_validate "$active" || { 
                error "MSS活动记录损坏或版本不受支持：$active" 1>&2;
                return 1
            };
            if _e242_mss_tx_live "$path"; then
                error "旧版MSS事务进程仍在运行，拒绝并发恢复：$path" 1>&2;
                return 1;
            fi;
            has=1;
        fi;
        if test -e "$preserve" || test -L "$preserve"; then
            test -f "$preserve" && test ! -L "$preserve" && test -s "$preserve" || { 
                error "MSS保留标记损坏：$preserve" 1>&2;
                return 1
            };
            has=1;
        fi;
        if test "$has" -eq 1; then
            count=$((count + 1));
            only="$path";
        fi;
    done < <(find "$root" -mindepth 1 -maxdepth 1 \( -type d -o -type l \) -print0 2> /dev/null | LC_ALL=C sort -z);
    test "$count" -eq 1 && test "$selected" = "$only" || { 
        error "MSS未完成事务不是唯一目标（count=$count selected=${selected:-none}）。" 1>&2;
        _e220_mss_unresolved_report 1>&2 || true;
        return 1
    };
    phase=$(cat "$selected/.phase" 2> /dev/null || true);
    case "$phase" in 
        created | rolled-back)

        ;;
        control-ready | triggers-stopped)
            _e220_mss_control_validate "$selected" || { 
                error "MSS恢复事务控制快照校验失败：$selected" 1>&2;
                return 1
            }
        ;;
        backends-ready | mutation-started | committed)
            _e220_mss_control_validate "$selected" && _e220_mss_backends_validate "$selected" "$selected/backends.tsv" || { 
                error "MSS恢复事务规则/控制快照校验失败：$selected" 1>&2;
                return 1
            }
        ;;
        *)
            error "MSS恢复事务阶段无效：${phase:-missing}" 1>&2;
            return 1
        ;;
    esac;
    printf 'recover|%s\n' "$selected"
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_scoped_match_mock_self_test
_e242_mss_scoped_match_mock_self_test() {
    ( local d list snapshot rc=0 mode=full mismatch=0;
    d=$(mktemp -d /tmp/xray-e242-mss-scope.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    snapshot="$d/firewall-1.rules";
    list="$d/backends.tsv";
    : > "$snapshot";
    printf 'iptables|id|/bin/false|save-id|/bin/false|restore-id|%s\n' "$snapshot" > "$list";
    function _e220_mss_backends_validate () 
    { 
        return 0
    };
    function _e220_mss_signature () 
    { 
        test "$mismatch" -eq 0 || { 
            echo '-N WRONG';
            return 0
        };
        printf '%s\n' "-A $E216_MSS_CHAIN -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu" '-A POSTROUTING -j XRAY_MSS_CLAMP' '-N XRAY_MSS_CLAMP' | LC_ALL=C sort
    };
    function _e242_mss_signature_legacy () 
    { 
        printf '%s\n' '-A POSTROUTING -j XRAY_MSS_CLAMP' '-N XRAY_MSS_CLAMP' | LC_ALL=C sort
    };
    _e220_mss_signature iptables > "$snapshot.mss";
    _e220_mss_backends_match "$d" "$list" || rc=1;
    _e242_mss_signature_legacy iptables > "$snapshot.mss";
    _e220_mss_backends_match "$d" "$list" || rc=1;
    _e220_mss_signature iptables > "$snapshot.mss";
    mismatch=1;
    _e220_mss_backends_match "$d" "$list" > /dev/null 2>&1 && rc=1 || true;
    return "$rc" )
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_signature_legacy
_e242_mss_signature_legacy() {
    local backend="${1:-}" tool;
    tool=$(_e216_mss_tool_path "$backend") || return 1;
    "$tool" -w 5 -t mangle -S 2> /dev/null | awk -v chain="$E216_MSS_CHAIN" '
          $0 == "-N " chain || index($0," -j " chain) ||
          $0 == "-A POSTROUTING -p tcp -m tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu" {print}
        ' | LC_ALL=C sort
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_mss_tx_live
_e242_mss_tx_live() {
    local d="${1:-}" pid expected actual;
    _e242_mss_active_record_validate "$d/.active.env" || return 1;
    pid=$(_e218_mss_owner_state_value "$d/.active.env" pid) || return 1;
    expected=$(_e218_mss_owner_state_value "$d/.active.env" start) || return 1;
    kill -0 "$pid" 2> /dev/null || return 1;
    actual=$(_e214_proc_start_time "$pid" 2> /dev/null || true);
    test -n "$actual" && test "$actual" = "$expected"
}
