# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_non_mss_critical_preflight
_e242_non_mss_critical_preflight() {
    local label marker;
    while IFS='	' read -r label marker; do
        test "$marker" = "$E220_MSS_CRITICAL_MARKER" && continue;
        if test ! -e "$marker" && test ! -L "$marker"; then
            continue;
        fi;
        error "检测到${label}严重恢复标记，拒绝覆盖：$marker" 1>&2;
        if test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker"; then
            sed -n '1,20s/^/    /p' "$marker" 1>&2 || true;
        else
            error '恢复标记为空、不可读、类型异常或为符号链接。' 1>&2;
        fi;
