        printf '%s\n' '    flock -n 9 || exit 4';
        printf '%s\n' '    printf disabled >"$E266_LEGACY_TEST_MARKER" ;;';
        printf '%s\n' '  *) exit 2 ;;';
        printf '%s\n' 'esac'
    } > "$old" || return 1;
    chmod 0755 "$old" || return 1;
    exec 9> "$lock" || return 1;
    flock -n 9 || return 1;
    function _e242_installed_script_real () 
    { 
        printf '%s\n' "$old"
    };
    _e242_old_small_bbr_disable e190 199e190 > /dev/null 2>&1 || rc=1;
    grep -qx disabled "$marker" 2> /dev/null || rc=1;
