}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_old_script_can_exit_owner
_e242_old_script_can_exit_owner() {
    local owner="${1:-}" version="${2:-}" generation="";
    generation=${version##*e};
    [[ "$generation" =~ ^[0-9]+$ ]] || return 1;
    case "$owner" in 
        e202)
            ((generation >= 202 && generation <= 266))
        ;;
        e190 | e192 | e194 | e196 | e198 | e200)
            test "$generation" = "${owner#e}"
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_old_small_bbr_disable
_e242_old_small_bbr_disable() {
    local owner="${1:-}" expected_version="${2:-}" real="" actual_version="";
    local restore_snapshot="" rc=0 relock_rc=0 E266_ALLOW_LINEAGE_SALVAGE=0;
    real=$(_e242_installed_script_real) || { 
        error '无法重新固定当前已安装旧脚本；未调用旧小BBR恢复点。';
        return 1
    };
    actual_version=$("$real" --version 2> /dev/null | tail -n1 | tr -d '[:space:]');
    test -n "$expected_version" && test "$actual_version" = "$expected_version" || { 
        error "旧脚本在锁定前发生变化：expected=${expected_version:-missing} actual=${actual_version:-missing}";
        return 1
    };
    if test "$owner" = e202; then
        if test "${E266_AUTO_UPGRADE_ACTIVE:-0}" = 1; then
            restore_snapshot=$(_e266_state_value_once "$E202_SMALL_STATE" restore_snapshot) || return 1;
            _e266_lineage_rescue_prepare "$restore_snapshot" || return 1;
            test -z "${E266_LINEAGE_RESCUE_TX:-}" || E266_ALLOW_LINEAGE_SALVAGE=1;
        fi;
        warn "活动档属于E202稳定ABI；由E266当前恢复器读取${actual_version}保存的原快照，不再执行旧版私有恢复逻辑。";
        _e202_small_bbr_disable force;
        return $?;
    fi;
    case "$owner" in 
        e190 | e192 | e194 | e196 | e198 | e200)

        ;;
        *)
            return 1
        ;;
    esac;
    flock -u 9 || { 
        error '无法临时交还xrv全局锁。';
        return 1
    };
    /bin/bash "$real" --small-bbr-disable < /dev/null || rc=$?;
    flock -w 90 9 || relock_rc=$?;
    if test "$relock_rc" -ne 0; then
        error '旧小BBR退出后90秒内未能重新取得xrv全局锁；停止后续写入。';
        return 1;
    fi;
    test "$rc" -eq 0 || error "旧版小BBR退出失败：owner=${owner:-unknown} old=$real rc=$rc";
    return "$rc"
}
