            return 1
        ;;
    esac;
    parent=${real%/system};
    if test -e "$parent/.active.env" || test -L "$parent/.active.env"; then
        test -f "$parent/.active.env" && test ! -L "$parent/.active.env" || return 1;
        pid=$(awk -F= '$1=="pid"{n++;v=$2}END{if(n==1)print v;else exit 1}' "$parent/.active.env") || return 1;
        start=$(awk -F= '$1=="start"{n++;v=$2}END{if(n==1)print v;else exit 1}' "$parent/.active.env") || return 1;
        [[ "$pid" =~ ^[1-9][0-9]*$ && "$start" =~ ^[0-9]+$ ]] || return 1;
        if kill -0 "$pid" 2> /dev/null; then
            actual=$(_e214_proc_start_time "$pid" 2> /dev/null || true);
            test -n "$actual" && test "$actual" != "$start" || { 
                error "旧${version}自动升级进程仍存活，拒绝并发恢复：pid=$pid" 1>&2;
                return 1
            };
        fi;
    fi;
    printf '%s|%s|%s\n' "$version" "$operation" "$real"
}
