# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_public_cache_verify
_e242_public_cache_verify() {
    local file="${1:-$CONFIG}" priv="" embedded="" expected="" actual="" cached="";
    local pub_target="${E124_PUBKEY_FILE_OVERRIDE:-$PUBKEY_FILE}";
    local meta_target="${E124_REALITY_CACHE_META_OVERRIDE:-$E124_REALITY_CACHE_META}";
    local mode="" uid="";
    test -f "$file" && test ! -L "$file" && jq empty "$file" > /dev/null 2>&1 || return 1;
    priv=$(jq -r '.inbounds[]? |
      select(.protocol=="vless" and (.streamSettings.security//"")=="reality") |
      .streamSettings.realitySettings.privateKey // empty' "$file" 2> /dev/null | awk 'NF&&!done{print;done=1}');
    if test -z "$priv"; then
        return 0;
    fi;
    embedded=$(jq -r '.inbounds[]? |
      select(.protocol=="vless" and (.streamSettings.security//"")=="reality") |
      (.streamSettings.realitySettings.password //
       .streamSettings.realitySettings.publicKey // empty)' "$file" 2> /dev/null | awk 'NF&&!done{print;done=1}');
    expected=$(_e124_reality_password_for_private "$priv" "$embedded" 2> /dev/null || true);
    _e124_valid_x25519_value "$expected" || return 1;
    for file in "$pub_target" "$meta_target";
    do
        test -f "$file" && test ! -L "$file" || return 1;
        uid=$(stat -c %u "$file" 2> /dev/null || true);
        mode=$(stat -c %a "$file" 2> /dev/null || true);
        test "$uid" = 0 && [[ "$mode" =~ ^[0-7]{3,4}$ ]] || return 1;
        (( (8#$mode & 0077) == 0 )) || return 1;
    done;
    actual=$(tr -d '[:space:]' < "$pub_target" 2> /dev/null || true);
    test "$actual" = "$expected" || return 1;
    cached=$(_e124_cache_read_matching "$priv" 2> /dev/null || true);
    test "$cached" = "$expected"
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_raw_inbounds_digest
_e242_raw_inbounds_digest() {
    local file="${1:-}";
    test -f "$file" && test ! -L "$file" && command -v jq > /dev/null 2>&1 || return 1;
    jq -e '(.inbounds // []) | type == "array"' "$file" > /dev/null 2>&1 || return 1;
    jq -S -c '.inbounds // []' "$file" 2> /dev/null | sha256sum | awk '{print $1}'
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_reality_cache_reconcile
_e242_reality_cache_reconcile() {
    if _e242_public_cache_verify "$CONFIG"; then
        return 0;
    fi;
    warn 'Reality Password(pbk)兼容缓存缺失或漂移；将按现有privateKey重新派生，不更换节点密钥。';
    _e124_repair_reality_password_cache || { 
        error 'Reality Password(pbk)兼容缓存自动修复失败。';
        return 1
    };
    _e242_public_cache_verify "$CONFIG" || { 
        error 'Reality Password(pbk)兼容缓存修复后读回仍不一致。';
        return 1
    }
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_recover_legacy_warp_marker
_e242_recover_legacy_warp_marker() {
    local marker="$E204_CRITICAL_MARKER" tx_root="$E204_TX_ROOT";
    local snapshot="" parent="" record="" truth="";
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1; then
        marker="${1:-$marker}";
        tx_root="${2:-$tx_root}";
    else
        if test "$#" -ne 0; then
            return 1;
        fi;
    fi;
    if test ! -e "$marker" && test ! -L "$marker"; then
        return 0;
    fi;
    snapshot=$(_e242_e204_warp_marker_snapshot "$marker" "$tx_root") || { 
        error '检测到E204严重恢复标记，但不是可验证的warp-local-reconcile快照；拒绝猜测恢复。';
        return 1
    };
    parent=${snapshot%/system};
    record=$(_e242_warp_truth_readonly 2> /dev/null || true);
    if test -n "$record" && _e242_warp_normalize_effective_state_only "$record"; then
        rm -f -- "$marker" "$parent/.preserve.env" "$parent/.active.env" || return 1;
        info 'E204 WARP标记已由当前稳定运行态取代；未重放较旧的内层快照。';
        return 0;
    fi;
    warn "当前WARP运行态不能完整证明，恢复上次E204事务快照：$snapshot";
    _e204_warp_package_restore "$parent/warp-packages.before" && _e140_system_restore "$snapshot" || return 1;
    record=$(_e242_warp_truth_readonly) || return 1;
    truth=${record%%|*};
    case "$truth" in 
        off | stale-off)
            _e242_warp_converge_effective "$record" 1 || return 1
        ;;
        active)
            _e242_warp_converge_effective "$record" 1 || return 1
        ;;
        host-full)
            error 'warp-local-reconcile快照却恢复出host-full意图；事务类型不一致，拒绝自动修改宿主机路由。';
            return 1
        ;;
        *)
            return 1
        ;;
    esac;
    rm -f -- "$marker" "$parent/.preserve.env" "$parent/.active.env" || return 1;
    info 'E204 WARP失败事务已恢复：实际配置无WARP时收敛为OFF；凭据与外部规则均保留。'
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_recover_previous_failed_auto
_e242_recover_previous_failed_auto() {
    local record="" prior_version="" prior_operation="" snapshot="" parent="";
    local candidate="" recovery_tx="" shown_version="" shown_operation="";
    local marker="$E214_CRITICAL_MARKER" tx_root="$E214_TX_ROOT";
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1; then
        marker="${1:-$marker}";
        tx_root="${2:-$tx_root}";
    else
        if test "$#" -ne 0; then
            return 1;
        fi;
    fi;
    if test ! -e "$marker" && test ! -L "$marker"; then
        return 0;
    fi;
    record=$(_e242_previous_auto_marker_snapshot "$marker" "$tx_root") || { 
        shown_version=$(sed -n 's/^version=//p' "$marker" 2> /dev/null | tail -n1);
        shown_operation=$(sed -n 's/^operation=//p' "$marker" 2> /dev/null | tail -n1);
        [[ "$shown_version" =~ ^[A-Za-z0-9._-]{1,40}$ ]] || shown_version=invalid;
        [[ "$shown_operation" =~ ^[A-Za-z0-9._-]{1,80}$ ]] || shown_operation=invalid;
        error "存在严重恢复标记，但不是受支持的一键升级事务：version=$shown_version operation=$shown_operation";
        error '支持自动恢复E222/E224/E226/E228/E230/E232/E234/E236/E238/E240/E242/E243/E244/E246/E252/E254/E256/E258/E260/E262/E266的精确auto-upgrade快照；其他事务拒绝猜测。';
        error '请保留标记与快照，可先运行 --recovery-status 查看只读诊断。';
        return 1
    };
    IFS='|' read -r prior_version prior_operation snapshot <<< "$record";
    [[ "$prior_version" =~ ^199e(222|224|226|228|230|232|234|236|238|240|242|243|244|246|252|254|256|258|260|262|266)$ ]] && [[ "$prior_operation" =~ ^e(222|224|226|228|230|232|234|236|238|240|242|243|244|246|252|254|256|258|260|262|266)-auto-upgrade(-interrupted|-unexpected)?$ ]] && test -n "$snapshot" || return 1;
    _eex5_restore_preflight "$snapshot" all || return 1;
    candidate=$(_e242_mss_recovery_candidate) || return 1;
    if test "$candidate" != none; then
        case "$candidate" in 
            recover\|/*)
                recovery_tx=${candidate#recover|}
            ;;
            *)
                return 1
            ;;
        esac;
        warn "先恢复${prior_version}失败路径留下的唯一MSS事务：$recovery_tx";
        _e242_mss_recover_force "$recovery_tx" || return 1;
    fi;
    warn "重新读回${prior_version}一键升级起点快照：$snapshot";
    _e242_restore_outer "$snapshot" "previous-${prior_version}-auto" 0 || return 1;
    parent=${snapshot%/system};
    rm -f -- "$marker" "$parent/.preserve.env" "$parent/.active.env" || return 1;
    info "${prior_version}失败事务已恢复并关闭严重标记；保留快照供审计：$snapshot"
}
