    function _e242_identity_bundle_verify () 
    { 
        test "$1" = "$d/independent/identity" && test "$2" = '阶段fixture' && test "$3" = "$cfg" && test "$5" = required
    };
    function _e242_inbounds_digest () 
    { 
        printf '%064d\n' 1
    };
    function _e242_raw_inbounds_digest () 
    { 
        printf '%064d\n' 2
    };
    function _e242_user_map_digest () 
    { 
        case "$1" in 
            "$USER_SNI_MAP")
                printf '%064d\n' 3
            ;;
            "$USER_TIME_MAP")
                printf '%064d\n' 4
            ;;
            *)
                return 1
            ;;
        esac
    };
    function _e242_warp_truth_readonly () 
    { 
        printf 'off|0|disabled|disabled|disabled|disabled|disabled\n'
    };
    function _e182_ipv6_policy_desired () 
    { 
        printf '1\n'
    };
    function _e242_active_small_owner () 
    { 
        printf 'none\n'
    };
    function _e218_mss_owner_state () 
    { 
        printf 'OFF\n'
    };
    function _e214_mtu_default_iface () 
    { 
        return 1
    };
    _e242_stage_state_record "$tx" fixture "$d/independent" required || rc=1;
    file="$audit/fixture.env";
    test -f "$file" && test ! -L "$file" && test "$(stat -c %a "$file")" = 600 || rc=1;
    test -f "$file.sha256" && test ! -L "$file.sha256" && ( cd "$audit" && sha256sum -c fixture.env.sha256 > /dev/null 2>&1 ) || rc=1;
    grep -qx 'version=199e266' "$file" || rc=1;
    grep -qx 'stage=fixture' "$file" || rc=1;
    grep -qx 'inbound_count=2' "$file" || rc=1;
    grep -qx 'reality_count=1' "$file" || rc=1;
    grep -qx 'vless_user_count=1' "$file" || rc=1;
    grep -qx 'shadowsocks_count=1' "$file" || rc=1;
    grep -qx 'unique_port_count=2' "$file" || rc=1;
    grep -qx 'xray_active=0' "$file" || rc=1;
    grep -qx 'default_iface=unknown' "$file" || rc=1;
    _e242_stage_state_record "$tx" fixture "$d/independent" required > /dev/null 2>&1 && rc=1 || true;
    _e242_stage_state_record "$tx" 'INVALID/STAGE' "$d/independent" required > /dev/null 2>&1 && rc=1 || true;
    _e242_stage_state_record "$tx" second "$d/independent" invalid-policy > /dev/null 2>&1 && rc=1 || true;
    printf 'tampered=1\n' >> "$file";
    ( cd "$audit" && sha256sum -c fixture.env.sha256 > /dev/null 2>&1 ) && rc=1 || true;
    return "$rc" )
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_stage_state_record
_e242_stage_state_record() {
    local tx="${1:-}" stage="${2:-}" independent="${3:-}" cache_policy="${4:-required}";
    local audit="" file="" tmp="" iface="" mtu="" active=0 enabled_state="";
    local semantic="" raw="" sni="" utime="" warp="" ipv6="" owner="" mss="";
    local counts="" inbound_count="" reality_count="" vless_users="" ss_count="" port_count="";
    local cfg="$CONFIG";
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E242_STAGE_CONFIG_OVERRIDE:-}"; then
        cfg="$E242_STAGE_CONFIG_OVERRIDE";
    fi;
    _e242_auto_tx_root_ok "$tx" || { 
        error "阶段${stage:-unknown}读回失败：事务根不在受信E266目录。";
        return 1
    };
    [[ "$stage" =~ ^[a-z0-9][a-z0-9-]{0,47}$ ]] || return 1;
    case "$cache_policy" in 
        required | ignore)

        ;;
        *)
            return 1
        ;;
    esac;
    test -s "$cfg" && test ! -L "$cfg" || { 
        error "阶段$stage读回失败：Xray配置缺失、为空或为符号链接。";
        return 1
    };
    _e118_xray_test_config "$cfg" 1 || { 
        error "阶段$stage读回失败：Xray配置语法/语义测试未通过。";
        return 1
    };
    if systemctl is-active --quiet xray.service 2> /dev/null; then
        active=1;
        _e127_verify_xray_runtime "$cfg" 12 || { 
            error "阶段$stage读回失败：Xray处于active但监听/运行探针未通过。";
            return 1
        };
    fi;
    if test -n "$independent"; then
        _e242_identity_bundle_verify "$independent/identity" "阶段${stage}" "$cfg" "$tx/e242-state-audit/${stage}-identity-diagnostics" "$cache_policy" || { 
            error "阶段$stage读回失败：节点/用户/Reality语义身份或PBK缓存门禁未通过。";
            return 1
        };
    fi;
    semantic=$(_e242_inbounds_digest "$cfg") || return 1;
    raw=$(_e242_raw_inbounds_digest "$cfg") || return 1;
    sni=$(_e242_user_map_digest "$USER_SNI_MAP") || return 1;
    utime=$(_e242_user_map_digest "$USER_TIME_MAP") || return 1;
    counts=$(jq -r '
      [((.inbounds // []) | length),
       ([.inbounds[]? | select(.protocol=="vless" and
         ((.streamSettings.security // "")=="reality"))] | length),
       ([.inbounds[]? | select(.protocol=="vless") |
         .settings.clients[]?] | length),
       ([.inbounds[]? | select(.protocol=="shadowsocks")] | length),
       ([.inbounds[]? | .port? | select(type=="number")] | unique | length)]
      | @tsv
    ' "$cfg" 2> /dev/null) || return 1;
    IFS='	' read -r inbound_count reality_count vless_users ss_count port_count <<< "$counts";
    for counts in "$inbound_count" "$reality_count" "$vless_users" "$ss_count" "$port_count";
    do
        [[ "$counts" =~ ^[0-9]+$ ]] || return 1;
    done;
    warp=$(_e242_warp_truth_readonly) || { 
        error "阶段$stage读回失败：WARP有效状态无法唯一分类。";
        return 1
    };
    [[ "$warp" =~ ^[A-Za-z0-9._:+|-]{1,560}$ ]] || return 1;
    ipv6=$(_e182_ipv6_policy_desired) || { 
        error "阶段$stage读回失败：IPv6持久意图无法唯一读出。";
        return 1
    };
    [[ "$ipv6" =~ ^[01]$ ]] || return 1;
    owner=$(_e242_active_small_owner 2> /dev/null || true);
    owner=${owner:-none};
    [[ "$owner" =~ ^[A-Za-z0-9._+-]{1,40}$ ]] || return 1;
    mss=$(_e218_mss_owner_state 2> /dev/null || true);
    mss=${mss:-UNSET};
    [[ "$mss" =~ ^[A-Za-z0-9._+-]{1,40}$ ]] || mss=unknown;
    iface=$(_e214_mtu_default_iface 2> /dev/null || true);
    iface=${iface:-unknown};
    [[ "$iface" =~ ^[A-Za-z0-9_.:-]{1,64}$ ]] || return 1;
    if test "$iface" != unknown && test -r "/sys/class/net/$iface/mtu"; then
        mtu=$(< "/sys/class/net/$iface/mtu");
    else
        mtu=unknown;
    fi;
    [[ "$mtu" = unknown || "$mtu" =~ ^[0-9]{3,5}$ ]] || return 1;
    enabled_state=$(systemctl is-enabled xray.service 2> /dev/null || true);
    [[ "$enabled_state" =~ ^[A-Za-z0-9._+-]{1,40}$ ]] || enabled_state=unknown;
    audit="$tx/e242-state-audit";
    if test -e "$audit" || test -L "$audit"; then
        test -d "$audit" && test ! -L "$audit" || return 1;
    else
        install -d -o root -g root -m 0700 -- "$audit" || return 1;
    fi;
    file="$audit/$stage.env";
    test ! -e "$file" && test ! -L "$file" || return 1;
    tmp="$audit/.${stage}.tmp.${BASHPID:-$$}";
    test ! -e "$tmp" && test ! -L "$tmp" || return 1;
    { 
        printf 'version=199e266\n';
        printf 'stage=%s\n' "$stage";
        printf 'time=%s\n' "$(date -Is 2> /dev/null || date)";
        printf 'config_sha256=%s\n' "$(sha256sum "$cfg" | awk '{print $1}')";
        printf 'inbounds_semantic_sha256=%s\n' "$semantic";
        printf 'inbounds_raw_sha256=%s\n' "$raw";
        printf 'user_sni_sha256=%s\n' "$sni";
        printf 'user_time_sha256=%s\n' "$utime";
        printf 'inbound_count=%s\nreality_count=%s\nvless_user_count=%s\n' "$inbound_count" "$reality_count" "$vless_users";
        printf 'shadowsocks_count=%s\nunique_port_count=%s\n' "$ss_count" "$port_count";
        printf 'xray_active=%s\nxray_enabled_state=%s\n' "$active" "$enabled_state";
        printf 'warp_truth=%s\nipv6_desired=%s\n' "$warp" "$ipv6";
        printf 'small_bbr_owner=%s\nmss_state=%s\n' "$owner" "$mss";
        printf 'default_iface=%s\ndefault_iface_mtu=%s\n' "$iface" "$mtu"
    } > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    chmod 0600 "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -T -- "$tmp" "$file" || { 
        rm -f -- "$tmp";
        return 1
    };
    ( cd "$audit" && sha256sum "$(basename -- "$file")" > "$(basename -- "$file").sha256" ) || return 1;
    chmod 0600 "$file.sha256" || return 1
}
