    grep -q 'E242_LEGACY_E234_SELF_PATH' <<< "$installer$verify" || rc=1;
    grep -q 'E242_LEGACY_E232_SELF_PATH' <<< "$installer$verify" || rc=1;
    grep -q 'E242_LEGACY_E230_SELF_PATH' <<< "$installer$verify" || rc=1;
    grep -q 'E242_LEGACY_E228_SELF_PATH' <<< "$installer$verify" || rc=1;
    grep -q 'E242_LEGACY_E226_SELF_PATH' <<< "$installer$verify" || rc=1;
    grep -q 'E242_LEGACY_E224_SELF_PATH' <<< "$installer$verify" || rc=1;
    grep -q 'E242_LEGACY_E222_SELF_PATH' <<< "$installer" || rc=1;
    ! grep -q '_e214_mtu_schedule_rollback' <<< "$(declare -f _e214_mtu_set_interactive 2> /dev/null || true)" || rc=1;
    grep -q '_e214_mtu_commit' <<< "$mtu" || rc=1;
    grep -q '_e242_mtu_target_verify' <<< "$mtu" || rc=1;
    grep -q '_e242_auto_tx_root_ok' <<< "$mtu" || rc=1;
    ! grep -q '_e214_new_tx' <<< "$(declare -f _e242_mtu_set_1350_outer 2> /dev/null || true)" || rc=1;
    ! grep -q '_e214_mtu_schedule_rollback' <<< "$(declare -f _e242_mtu_set_1350_outer 2> /dev/null || true)" || rc=1;
    ! grep -q 'systemd-run' <<< "$(declare -f _e242_mtu_set_1350_outer 2> /dev/null || true)" || rc=1;
    ! grep -q 'read -' <<< "$(declare -f _e242_mtu_set_1350_outer 2> /dev/null || true)" || rc=1;
    grep -q '确认执行' <<< "$mtu" || rc=1;
    ! grep -q 'KEEP-MTU' <<< "$(declare -f _e214_mtu_set_interactive 2> /dev/null || true)" || rc=1;
    grep -q 'V199e243' <<< "$menu" || rc=1;
    grep -q 'hot_update_from_legacy || true' <<< "$menu11" || rc=1;
    ! grep -Eq '(_e116_pause|read[[:space:]]+-r?p)' <<< "$menu11" || rc=1;
    if test "$rc" -eq 0; then
