# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_user_manager_base
_e242_user_manager_base() {
    _e135_prepare || return 1;
    test -s "$CONFIG" || { 
        error "config.json不存在。";
        return 1
    };
    jq empty "$CONFIG" > /dev/null 2>&1 || { 
        error "config.json不是有效JSON。";
        return 1
    };
    local -a rows=();
    local i=1 row protocol security tag choice;
    mapfile -t rows < <(jq -r '.inbounds[]? | select(.protocol=="vless" or .protocol=="shadowsocks") | [.tag,.protocol,(.streamSettings.security//"none")] | @tsv' "$CONFIG");
    test "${#rows[@]}" -gt 0 || { 
        warn "没有可管理入站。";
        return 1
    };
    while true; do
        clear;
        title "V199e137：用户、凭据、端口与密钥管理";
        i=1;
        for row in "${rows[@]}";
        do
            IFS='	' read -r tag protocol security <<< "$row";
            printf '  %d) %-28s protocol=%s security=%s\n' "$i" "$tag" "$protocol" "$security";
            i=$((i+1));
        done;
        echo "  0) 返回";
        read -rp "选择入站: " choice || true;
        test "$choice" = 0 && return 0;
        [[ "$choice" =~ ^[0-9]+$ ]] && ((choice>=1 && choice<=${#rows[@]})) || { 
            warn "序号无效。";
            sleep 1;
            continue
        };
        IFS='	' read -r tag protocol security <<< "${rows[$((choice-1))]}";
        if test "$protocol" = shadowsocks; then
            _e135_ss_manager "$tag";
        else
            if test "$security" = reality; then
                _e135_vless_users_menu "$tag" 1;
            else
                _e135_vless_users_menu "$tag" 0;
            fi;
        fi;
        mapfile -t rows < <(jq -r '.inbounds[]? | select(.protocol=="vless" or .protocol=="shadowsocks") | [.tag,.protocol,(.streamSettings.security//"none")] | @tsv' "$CONFIG");
    done
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_user_manager_transaction
_e242_user_manager_transaction() {
    ( local tx="" before="" after="" rc=0 managed=0 snapshot_ready=0 finished=0;
    local identity_root="" identity="";
    local E242_SUMMARY_SUPPRESS=0 E242_SUMMARY_PENDING=0;
    function _e242_user_exit_guard () 
    { 
        local status="${1:-1}";
        trap - EXIT HUP INT TERM;
        _e242_identity_tmp_cleanup "$identity_root";
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error '用户事务意外中断，恢复进入用户管理前的完整状态。';
            _e242_restore_outer "$tx/system" user-manager-interrupted || true;
            _e214_tx_close "$tx" || true;
            test "$status" -ne 0 || status=1;
        else
            if test "$finished" -eq 0 && test -n "$tx"; then
                _e214_tx_close "$tx" || true;
            fi;
        fi;
        [[ "$status" =~ ^[0-9]+$ ]] || status=1;
        exit "$status"
    };
    trap '_e242_user_exit_guard $?' EXIT;
    trap 'exit 129' HUP;
    trap 'exit 130' INT;
    trap 'exit 143' TERM;
    _e242_workflow_managed && managed=1 || true;
    test "$managed" -eq 0 || E242_SUMMARY_SUPPRESS=1;
    tx=$(_e214_new_tx user-manager-e242) || return 1;
    _e140_system_snapshot "$tx/system" || return 1;
    snapshot_ready=1;
    before=$(_e242_config_sha);
    _e242_user_manager_base "$@" || rc=$?;
    after=$(_e242_config_sha);
    if test "$rc" -eq 0 && test "$managed" -eq 1 && test "$before" != "$after"; then
        identity_root=$(mktemp -d /tmp/xray-e242-user-identity.XXXXXX) || rc=1;
        identity="$identity_root/identity";
        test "$rc" -ne 0 || _e242_identity_bundle_capture "$identity" "$CONFIG" || rc=1;
    fi;
    if test "$rc" -eq 0 && test "$managed" -eq 1 && test "$before" != "$after"; then
        _e242_post_config_reconcile || rc=1;
    fi;
    if test "$rc" -eq 0 && test "$managed" -eq 1 && test "$before" != "$after"; then
        _e242_identity_bundle_verify "$identity" 用户变更继承 "$CONFIG" "$tx/e242-user-identity-diagnostics" required || rc=1;
    fi;
    if test "$rc" -eq 0 && test "$managed" -eq 1 && test "$before" != "$after"; then
        E242_SUMMARY_SUPPRESS=0;
        E242_SUMMARY_PENDING=0;
        do_summary || rc=1;
    fi;
    if test "$rc" -eq 0; then
        _e242_identity_tmp_cleanup "$identity_root";
        finished=1;
        _e214_tx_close "$tx" || warn "用户修改已生效，但事务活动标记未关闭：$tx";
        trap - EXIT HUP INT TERM;
        return 0;
    fi;
    _e242_restore_outer "$tx/system" user-profile-reconcile || true;
    _e242_identity_tmp_cleanup "$identity_root";
    finished=1;
    _e214_tx_close "$tx" || true;
    trap - EXIT HUP INT TERM;
    return 1 )
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_user_map_digest
_e242_user_map_digest() {
    local file="${1:-}";
    if test -e "$file" || test -L "$file"; then
        test -f "$file" && test ! -L "$file" || return 1;
        awk '{sub(/\r$/, ""); if(length($0)>0) print}' "$file" | LC_ALL=C sort | sha256sum | awk '{print $1}';
    else
        printf 'absent\n';
    fi
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_warp_config_backend_readonly
_e242_warp_config_backend_readonly() {
    local config="${1:-$CONFIG}";
    test -s "$config" || { 
        echo disabled;
        return 0
    };
    jq -r --argjson p "${E138_WARP_PORT:-40000}" '
      . as $root |
      def primary($t):
        $t == "warp-global" or $t == "warp-global-e138" or $t == "warp-global-e185" or
        $t == "warp-e136" or $t == "warp-selective" or
        $t == "warp-selective-e138" or $t == "warp-selective-e185";
      def local_socks:
        .protocol == "socks" and
        (((.settings.address? == "127.0.0.1") and (.settings.port? == $p)) or
         any(.settings.servers[]?; .address == "127.0.0.1" and .port == $p));
      [ .routing.rules[]? | (.outboundTag? // "") | select(primary(.)) ] as $route_tags |
      [ (.outbounds // [])[] | select(.tag as $t | $route_tags | index($t)) ] as $active |
      if ($active | any(.protocol == "wireguard")) then "xray-wg"
      elif ($active | any(
        local_socks or
        ((.proxySettings.tag? // "") as $proxy |
          ($proxy | length) > 0 and
          (($root.outbounds // []) | any(.tag == $proxy and local_socks)))
      )) then "masque"
      else "disabled" end
    ' "$config" 2> /dev/null || return 1
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_warp_config_family_readonly
_e242_warp_config_family_readonly() {
    local config="${1:-$CONFIG}";
    test -s "$config" || { 
        echo unknown;
        return 0
    };
    jq -r '
      def primary($t):
        $t == "warp-global" or $t == "warp-global-e138" or $t == "warp-global-e185" or
        $t == "warp-e136" or $t == "warp-selective" or
        $t == "warp-selective-e138" or $t == "warp-selective-e185";
      [ .routing.rules[]? | (.outboundTag? // "") | select(primary(.)) ] as $route_tags |
      [ (.outbounds // [])[] | select(.tag as $t | $route_tags | index($t)) |
        (.settings.domainStrategy? // "") | select(length > 0) ] | unique as $s |
      if ($s|length)==0 then "unknown"
      elif ($s|all(. == "ForceIPv4" or . == "UseIPv4")) then "ipv4"
      elif ($s|all(. == "ForceIPv6" or . == "UseIPv6")) then "ipv6"
      elif ($s|all(. == "ForceIPv4v6" or . == "UseIPv4v6")) then "dual"
      else "unknown" end
    ' "$config" 2> /dev/null || return 1
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_warp_config_mode_readonly
_e242_warp_config_mode_readonly() {
    local config="${1:-$CONFIG}";
    test -s "$config" || { 
        echo disabled;
        return 0
    };
    jq -r '
      # Only primary TCP route tags prove that traffic is assigned to WARP.
      # An orphan outbound, UDP blackhole or private-bypass rule is not ON.
      def known($t): [
        "warp-global","warp-global-e138","warp-global-e185",
        "warp-e136","warp-selective","warp-selective-e138","warp-selective-e185",
        "warp-block-udp-e136","warp-selective-udp-block","warp-selective-udp-block-e138",
        "warp-selective-udp-block-e185","warp-global-udp-block-e138",
        "warp-global-udp-block-e185","warp-global-private-e138","warp-global-private-e185",
        "warp-family-block-e183","warp-family-block-e185",
        "warp-selective-socks-e183","warp-global-socks-e183",
        "warp-selective-socks-e185","warp-global-socks-e185"
      ] | index($t) != null;
      [ .routing.rules[]? | (.outboundTag? // "") | select(length > 0) ] as $tags |
      if ($tags | any(startswith("warp-") and (known(.) | not))) then "unknown"
      elif ($tags | any(. == "warp-global" or . == "warp-global-e138" or . == "warp-global-e185")) then "global"
      elif ($tags | any(. == "warp-e136" or . == "warp-selective" or
                        . == "warp-selective-e138" or . == "warp-selective-e185")) then "selective"
      else "disabled" end
    ' "$config" 2> /dev/null || return 1
}
