# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_warp_package_snapshot_validate
_e242_warp_package_snapshot_validate() {
    local before="${1:-}" line pkg was count=0 dir base;
    local -A seen=();
    test -f "$before" && test ! -L "$before" && test -s "$before" && test -f "$before.sha256" && test ! -L "$before.sha256" && test -s "$before.sha256" && test "$(stat -c %u "$before" 2> /dev/null || true)" = 0 && test "$(stat -c %u "$before.sha256" 2> /dev/null || true)" = 0 || return 1;
    dir=$(dirname -- "$before") || return 1;
    base=$(basename -- "$before") || return 1;
    ( cd "$dir" && sha256sum -c "$base.sha256" > /dev/null 2>&1 ) || return 1;
    while IFS= read -r line || test -n "$line"; do
        IFS='|' read -r pkg was <<< "$line";
        case "$pkg" in 
            ca-certificates | curl | gnupg | lsb-release | cloudflare-warp)

            ;;
            *)
                return 1
            ;;
        esac;
        case "$was" in 
            0 | 1)

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${seen[$pkg]+x}" || return 1;
        seen[$pkg]=1;
        count=$((count + 1));
    done < "$before";
    test "$count" -eq 5
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_warp_state_hint_readonly
_e242_warp_state_hint_readonly() {
    local key="${1:-}" def="${2:-}" scope="${3:-all}" file value;
    local -a files=();
    [[ "$key" =~ ^[a-z_]+$ ]] || return 1;
    if test "$scope" = all; then
        files+=("${E139_WARP_STATE:-/nonexistent}");
    fi;
    files+=("${E138_WARP_STATE:-/nonexistent}" "${E137_WARP_STATE:-/nonexistent}" "${E136_WARP_STATE:-/nonexistent}");
    for file in "${files[@]}";
    do
        test -f "$file" && test ! -L "$file" && test -r "$file" || continue;
        value=$(awk -F= -v key="$key" '
          $1==key {n++; v=substr($0,index($0,"=")+1)}
          END {if(n==1 && length(v)>0) print v; else exit 1}
        ' "$file" 2> /dev/null || true);
        [[ "$value" =~ ^[A-Za-z0-9._:+-]{1,80}$ ]] || continue;
        printf '%s\n' "$value";
        return 0;
    done;
    printf '%s\n' "$def"
}
