# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_warp_truth_readonly
_e242_warp_truth_readonly() {
    local state_enabled state_mode state_profile state_family state_backend state_request;
    local retired_enabled retired_mode;
    local config_mode config_backend config_family config_profile;
    local truth profile family backend request host_state;
    state_enabled=$(_e138_state_get route_enabled 0);
    state_mode=$(_e138_state_get route_mode disabled);
    state_profile=$(_e242_warp_state_hint_readonly profile disabled);
    state_family=$(_e242_warp_state_hint_readonly family ipv4);
    state_backend=$(_e242_warp_state_hint_readonly backend disabled);
    state_request=$(_e242_warp_state_hint_readonly backend_request "$state_backend");
    retired_enabled=$(_e242_warp_state_hint_readonly route_enabled 0 retired);
    retired_mode=$(_e242_warp_state_hint_readonly route_mode disabled retired);
    host_state=$(_e242_host_full_runtime_state_readonly) || return 1;
    if { 
        test "$state_enabled" = 1 && test "$state_mode" = host-full
    } || { 
        test "$retired_enabled" = 1 && test "$retired_mode" = host-full
    } || test "$host_state" = active || test "$host_state" = partial; then
        case "$host_state" in 
            active)
                if test "$state_mode" != host-full && test "$retired_mode" = host-full; then
                    state_profile=$(_e242_warp_state_hint_readonly profile "$state_profile" retired);
                fi;
                profile=${state_profile:-host-full};
                test "$profile" != disabled || profile=host-full;
                [[ "$profile" =~ ^[A-Za-z0-9._:+-]{1,80}$ ]] || profile=host-full;
                printf 'host-full|1|host-full|%s|disabled|host-full|host-full\n' "$profile";
                return 0
            ;;
            inactive)

            ;;
            partial)
                error 'WARP状态宣称Cloudflare系统全隧道，但服务/策略路由仅部分存在；拒绝自动改写。' 1>&2;
                return 1
            ;;
            *)
                return 1
            ;;
        esac;
    fi;
    config_mode=$(_e242_warp_config_mode_readonly) || return 1;
    config_backend=$(_e242_warp_config_backend_readonly) || return 1;
    config_family=$(_e242_warp_config_family_readonly) || return 1;
    config_profile=$(_e242_warp_config_profile_readonly "$CONFIG" "$config_mode") || return 1;
    case "$config_mode" in 
        disabled)
            if test "$state_enabled" = 1 || test "$state_mode" = selective || test "$state_mode" = global; then
                truth=stale-off;
            else
                truth=off;
            fi;
            printf '%s|0|disabled|disabled|disabled|disabled|disabled\n' "$truth"
        ;;
        selective | global)
            case "$config_backend" in 
                masque | xray-wg)

                ;;
                *)
                    error "Xray配置含${config_mode} WARP路由，但无法证明实际后端；拒绝猜测迁移。" 1>&2;
                    return 1
                ;;
            esac;
            if test "$state_mode" != "$config_mode"; then
                state_profile=$(_e242_warp_state_hint_readonly profile "$state_profile" retired);
                state_family=$(_e242_warp_state_hint_readonly family "$state_family" retired);
                state_request=$(_e242_warp_state_hint_readonly backend_request "$state_request" retired);
            fi;
            profile=$config_profile;
            if test "$config_mode" = global; then
                profile=global;
            else
                if test "$profile" = unknown; then
                    profile=$state_profile;
                    if test -z "$profile" || test "$profile" = disabled || test "$profile" = global; then
                        profile=google-meta-core;
                    fi;
                fi;
            fi;
            [[ "$profile" =~ ^[A-Za-z0-9._:+-]{1,80}$ ]] || return 1;
            case "$config_family" in 
                ipv4 | ipv6 | dual)
                    family=$config_family
                ;;
                *)
                    family=$state_family
                ;;
            esac;
            family=$(_e185_family_normalize "${family:-ipv4}" 2> /dev/null || echo ipv4);
            test "$family" != disabled || family=ipv4;
            backend=$config_backend;
            request=$(_e185_backend_normalize "${state_request:-$backend}" 2> /dev/null || echo "$backend");
            test "$request" != disabled || request="$backend";
            printf 'active|1|%s|%s|%s|%s|%s\n' "$config_mode" "$profile" "$family" "$backend" "$request"
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_workflow_managed
_e242_workflow_managed() {
    local file;
    for file in "$E242_WORKFLOW_STATE" "$E242_LEGACY_E262_WORKFLOW_STATE" "$E242_LEGACY_E260_WORKFLOW_STATE" "$E242_LEGACY_E258_WORKFLOW_STATE" "$E242_LEGACY_E256_WORKFLOW_STATE" "$E242_LEGACY_E254_WORKFLOW_STATE" "$E242_LEGACY_E252_WORKFLOW_STATE" "$E242_LEGACY_E246_WORKFLOW_STATE" "$E242_LEGACY_E244_WORKFLOW_STATE" "$E242_LEGACY_E243_WORKFLOW_STATE" "$E242_LEGACY_E242_WORKFLOW_STATE" "$E242_LEGACY_E240_WORKFLOW_STATE" "$E242_LEGACY_E238_WORKFLOW_STATE" "$E242_LEGACY_E236_WORKFLOW_STATE" "$E242_LEGACY_E234_WORKFLOW_STATE";
