# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_xray_service_intent_verify
_e242_xray_service_intent_verify() {
    local meta="${1:-}" expected_active="" expected_enabled="" now="" actual_enabled=0;
    test -f "$meta" && test ! -L "$meta" || return 1;
    expected_active=$(_e242_independent_value "$meta" xray_was_active) || return 1;
    expected_enabled=$(_e242_independent_value "$meta" xray_was_enabled) || return 1;
    [[ "$expected_active" =~ ^[01]$ && "$expected_enabled" =~ ^[01]$ ]] || return 1;
    now=$(systemctl is-enabled xray.service 2> /dev/null || true);
    case "$now" in 
        enabled | enabled-runtime | linked | linked-runtime)
            actual_enabled=1
        ;;
    esac;
    test "$actual_enabled" = "$expected_enabled" || { 
        error "升级后Xray开机状态改变：expected=$expected_enabled actual=$actual_enabled($now)";
        return 1
    };
    _e118_xray_test_config "$CONFIG" 1 || return 1;
    if test "$expected_active" = 1; then
        systemctl is-active --quiet xray.service 2> /dev/null && _e127_verify_xray_runtime "$CONFIG" 12 || { 
            error '升级前Xray处于运行态，但升级后服务或监听探针未通过。';
            return 1
        };
    else
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            error '升级前Xray处于停止态，但升级后被意外启动。';
            return 1;
        fi;
    fi
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_xray_snapshot_restore
_e242_xray_snapshot_restore() {
    local bdir="${1:-}" trust="${2:-}" f="" base="" now="";
    local was_active="" was_enabled="" rc=0;
    _e242_xray_snapshot_validate "$bdir" "$trust" || return 1;
    was_active=$(_e242_independent_value "$bdir/meta.env" xray_was_active) || return 1;
    was_enabled=$(_e242_independent_value "$bdir/meta.env" xray_was_enabled) || return 1;
    while IFS= read -r f; do
        test -n "$f" || continue;
        base=$(basename -- "$f");
        if grep -qxF "$base" "$bdir/files.manifest" 2> /dev/null; then
            _e118_atomic_install "$bdir/$base" "$f" 0600 || rc=1;
        else
            rm -f -- "$f" 2> /dev/null || rc=1;
        fi;
        test "$rc" -eq 0 || break;
    done < <(_e118_managed_state_files);
    test "$rc" -eq 0 && fix_permissions || return 1;
    if test "$was_enabled" = 1; then
        systemctl enable xray.service > /dev/null 2>&1 || return 1;
    else
        systemctl disable xray.service > /dev/null 2>&1 || return 1;
        now=$(systemctl is-enabled xray.service 2> /dev/null || true);
        case "$now" in 
            enabled | enabled-runtime | linked | linked-runtime)
                return 1
            ;;
        esac;
    fi;
    if test "$was_active" = 1; then
        systemctl reset-failed xray.service > /dev/null 2>&1 || true;
        systemctl restart xray.service > /dev/null 2>&1 || return 1;
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1;
    else
        systemctl stop xray.service > /dev/null 2>&1 || true;
        systemctl is-active --quiet xray.service 2> /dev/null && return 1 || true;
    fi;
    E118_TX_ACTIVE=0;
    E118_TX_BACKUP="";
    E118_TX_WAS_ACTIVE=0
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e242_xray_snapshot_validate
_e242_xray_snapshot_validate() {
    local bdir="${1:-}" trust="${2:-}" real="" trusted="" base="" line="";
    local key="" value="" count=0 allowed=" " seen=" " manifest_count=0;
    local active="" enabled="" version="";
    local -A meta_seen=();
    test -n "$bdir" && test -n "$trust" || return 1;
    _e242_independent_root_ok "$trust" && test -d "$bdir" && test ! -L "$bdir" || return 1;
    trusted=$(readlink -f -- "$trust" 2> /dev/null || true);
    real=$(readlink -f -- "$bdir" 2> /dev/null || true);
    test -n "$trusted" && test -n "$real" || return 1;
    case "$real" in 
        "$trusted"/xray)

        ;;
        *)
            return 1
        ;;
    esac;
    test "$(stat -c %u "$trusted" 2> /dev/null || true)" = 0 && test "$(stat -c %u "$real" 2> /dev/null || true)" = 0 || return 1;
    test -z "$(find "$bdir" -mindepth 1 ! -uid 0 -print -quit 2> /dev/null)" || return 1;
    test -z "$(find "$bdir" -mindepth 1 -type l -print -quit 2> /dev/null)" || return 1;
    test -z "$(find "$bdir" -mindepth 1 -maxdepth 1 ! -type f -print -quit 2> /dev/null)" || return 1;
    test -z "$(find "$bdir" -mindepth 1 -perm /022 -print -quit 2> /dev/null)" || return 1;
    for base in files.manifest meta.env files.sha256 snapshot-seal.sha256;
    do
        test -f "$bdir/$base" && test ! -L "$bdir/$base" || return 1;
    done;
    test -s "$bdir/meta.env" && test -s "$bdir/snapshot-seal.sha256" || return 1;
    while IFS= read -r base; do
        test -n "$base" || continue;
        base=$(basename -- "$base");
        [[ "$base" =~ ^[A-Za-z0-9._-]+$ ]] || return 1;
        [[ "$allowed" != *" $base "* ]] || return 1;
        allowed+="$base ";
    done < <(_e118_managed_state_files);
    while IFS= read -r base || test -n "$base"; do
        test -n "$base" || return 1;
        [[ "$base" =~ ^[A-Za-z0-9._-]+$ ]] || return 1;
        [[ "$allowed" == *" $base "* ]] || return 1;
        [[ "$seen" != *" $base "* ]] || return 1;
        seen+="$base ";
        manifest_count=$((manifest_count + 1));
        test -f "$bdir/$base" && test ! -L "$bdir/$base" || return 1;
    done < "$bdir/files.manifest";
    count=0;
    seen=" ";
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([0-9a-f]{64})[[:space:]][[:space:]]([A-Za-z0-9._-]+)$ ]] || return 1;
        base=${BASH_REMATCH[2]};
        [[ "$allowed" == *" $base "* && "$seen" != *" $base "* ]] || return 1;
        seen+="$base ";
        count=$((count + 1));
    done < "$bdir/files.sha256";
    test "$count" -eq "$manifest_count" || return 1;
    if test "$count" -gt 0; then
        ( cd "$bdir" && sha256sum -c files.sha256 > /dev/null 2>&1 ) || return 1;
    else
        test ! -s "$bdir/files.sha256" || return 1;
    fi;
    seen=" ";
    count=0;
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([0-9a-f]{64})[[:space:]][[:space:]]([A-Za-z0-9._-]+)$ ]] || return 1;
        base=${BASH_REMATCH[2]};
        test "$base" != snapshot-seal.sha256 && [[ "$seen" != *" $base "* ]] || return 1;
        test -f "$bdir/$base" && test ! -L "$bdir/$base" || return 1;
        seen+="$base ";
        count=$((count + 1));
    done < "$bdir/snapshot-seal.sha256";
    while IFS= read -r base; do
        test -n "$base" && [[ "$seen" == *" $base "* ]] || return 1;
        count=$((count - 1));
    done < <(find "$bdir" -mindepth 1 -maxdepth 1 -type f ! -name snapshot-seal.sha256 -printf '%f\n' | LC_ALL=C sort);
    test "$count" -eq 0 || return 1;
