        value=${BASH_REMATCH[2]};
        case "$key" in 
            created_at | version | tag | xray_was_active | xray_was_enabled | xray_enabled_state)

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${meta_seen[$key]+x}" && test -n "$value" || return 1;
        meta_seen[$key]=1;
        count=$((count + 1));
    done < "$bdir/meta.env";
    test "${#meta_seen[@]}" -eq 6 || return 1;
    version=$(_e242_independent_value "$bdir/meta.env" version) || return 1;
    active=$(_e242_independent_value "$bdir/meta.env" xray_was_active) || return 1;
    enabled=$(_e242_independent_value "$bdir/meta.env" xray_was_enabled) || return 1;
    [[ "$version" =~ ^(198|199)e[0-9]+$ && "$active" =~ ^[01]$ && "$enabled" =~ ^[01]$ ]] || return 1;
