    fi
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e243_check_reexport
_e243_check_reexport() {
    local warp_truth="";
    title 'V199e266：只读检查Xray并重新输出节点';
    _e118_readonly_init || return 1;
    test -s "$CONFIG" && test ! -L "$CONFIG" || { 
        error 'config.json不存在、为空或类型异常。';
        return 1
    };
    command -v jq > /dev/null 2>&1 || { 
        error '缺少jq，无法只读解析配置。';
        return 1
    };
    _e118_xray_test_config "$CONFIG" 1 || return 1;
    if systemctl is-active --quiet xray.service 2> /dev/null; then
        _e127_verify_xray_runtime "$CONFIG" 12 || return 1;
    else
        warn 'Xray当前停止：静态配置通过，未擅自启动或重启服务。';
    fi;
    warp_truth=$(_e242_warp_truth_readonly 2> /dev/null || true);
    test -z "$warp_truth" || info "WARP只读有效状态：$warp_truth";
    info '检查阶段未执行WARP reconcile、Nice修复或服务重启。';
    warn '导出阶段会重写节点URI/二维码文件；缺少qrencode时可能安装该导出依赖。';
    do_summary
}
