        };
    fi;
    E242_INTERNAL_SELF_TEST=1;
    E243_DEDUPE_CANONICAL_OVERRIDE="$canonical";
    _e243_dedupe_script_entries "$canonical" "$alias1" "$alias2" || rc=1;
    i0=$(stat -c '%d:%i' "$canonical" 2> /dev/null || true);
    i1=$(stat -c '%d:%i' "$alias1" 2> /dev/null || true);
    i2=$(stat -c '%d:%i' "$alias2" 2> /dev/null || true);
    test -n "$i0" && test "$i0" = "$i1" && test "$i0" = "$i2" || rc=1;
    _e243_script_entry_validate "$canonical" || rc=1;
    _e243_script_entry_validate "$alias1" || rc=1;
    _e243_script_entry_validate "$alias2" || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e243_dedupe_script_entries
_e243_dedupe_script_entries() {
    local canonical="$E242_SELF_PATH" target="" parent="" name="" link_dir="" tmp="";
    local canonical_dev="" target_dev="" canonical_inode="" target_inode="";
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E243_DEDUPE_CANONICAL_OVERRIDE:-}"; then
        canonical=$E243_DEDUPE_CANONICAL_OVERRIDE;
    fi;
    _e243_script_entry_validate "$canonical" || return 1;
    for target in "$@";
    do
        test "$target" != "$canonical" || continue;
        _e243_script_entry_validate "$target" || return 1;
        canonical_dev=$(stat -c '%d' "$canonical" 2> /dev/null || true);
        target_dev=$(stat -c '%d' "$target" 2> /dev/null || true);
        test -n "$canonical_dev" && test "$canonical_dev" = "$target_dev" || continue;
        canonical_inode=$(stat -c '%i' "$canonical" 2> /dev/null || true);
        target_inode=$(stat -c '%i' "$target" 2> /dev/null || true);
        test -n "$canonical_inode" && test "$canonical_inode" != "$target_inode" || continue;
        parent=$(dirname -- "$target") || return 1;
        name=${target##*/};
        link_dir=$(mktemp -d --tmpdir="$parent" ".${name}.e243-link.XXXXXX" 2> /dev/null || true);
        if test -z "$link_dir"; then
            warn "入口去重不可用，保留已验证普通副本：$target";
            continue;
        fi;
        chmod 0700 "$link_dir" 2> /dev/null || true;
        tmp="$link_dir/entry";
        if ! ln -- "$canonical" "$tmp" 2> /dev/null || ! mv -f -- "$tmp" "$target" 2> /dev/null; then
            rm -f -- "$tmp" 2> /dev/null || true;
            rmdir -- "$link_dir" 2> /dev/null || true;
            warn "入口无法硬链接去重，保留已验证普通副本：$target";
            _e243_script_entry_validate "$target" || return 1;
            continue;
        fi;
        rmdir -- "$link_dir" 2> /dev/null || true;
        _e243_script_entry_validate "$target" || return 1;
    done
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e243_default_iface_readonly
_e243_default_iface_readonly() {
    local iface="";
    if test -f "$E135_TRAFFIC_IFACE_FILE" && test ! -L "$E135_TRAFFIC_IFACE_FILE"; then
        iface=$(sed -n '1p' "$E135_TRAFFIC_IFACE_FILE" 2> /dev/null || true);
        [[ "$iface" =~ ^[A-Za-z0-9_.:-]{1,64}$ ]] && test -d "/sys/class/net/$iface" && { 
            printf '%s\n' "$iface";
            return 0
        };
    fi;
    iface=$(ip -4 route show default 2> /dev/null | awk 'NR==1{print $5}' || true);
    if test -z "$iface"; then
        iface=$(ip -6 route show default 2> /dev/null | awk 'NR==1{print $5}' || true);
    fi;
    [[ "$iface" =~ ^[A-Za-z0-9_.:-]{1,64}$ ]] && test -d "/sys/class/net/$iface" || return 1;
    printf '%s\n' "$iface"
}
# EEX3-FUNCTION upgrade_recovery_e221_265 _e243_diagnostic_menu
_e243_diagnostic_menu() {
    local opt="" token="";
    while true; do
        clear;
        title 'V199e266：恢复 / 审计 / 显式修复中心';
        echo '  1) 严重恢复标记与受保护事务（只读）';
        echo '  2) 运行态状态隔离与能力审计（只读）';
        echo '  3) E243最终绑定与菜单结构审计（只读）';
        echo '  4) 历史覆盖层架构审计（只读）';
        echo '  5) 跨版本所有权审计（只读）';
        echo '  6) 高级/28项菜单绑定审计（只读）';
        echo '  7) 3天日志策略状态（只读）';
        echo '  8) 安装/修复3天日志策略（需确认）';
        echo '  9) 主动修复WARP/Nice/Xray并重新导出（需确认）';
        echo ' 10) 运行完整离线发行自测（只读/mock）';
        echo '  0) 返回';
        read -rp '操作: ' opt || true;
        case "$opt" in 
            1)
                _e214_recovery_status || true;
                _e116_pause
            ;;
            2)
                e77_audit_runtime_state || true;
                _e116_pause
            ;;
            3)
                _e243_structure_audit || true;
                _e116_pause
            ;;
            4)
                _e152_architecture_audit || true;
                _e116_pause
            ;;
            5)
                _e159_cross_version_audit || true;
                _e116_pause
            ;;
            6)
                _e188_optimization_menu_audit || true;
                _e116_pause
            ;;
            7)
                _e121_show_log_retention || true;
                _e116_pause
            ;;
            8)
                read -rp '输入 APPLY-LOG-RETENTION 确认: ' token || true;
                test "$token" = APPLY-LOG-RETENTION && _e121_install_log_retention || true;
                _e116_pause
            ;;
            9)
                _e243_repair_reexport || true;
                _e116_pause
            ;;
            10)
                _e243_self_test || true;
                _e116_pause
            ;;
            0 | '')
                return 0
            ;;
            *)
                warn '无效操作。';
                sleep 1
            ;;
        esac;
    done
}
