# EEX3-FUNCTION upgrade_recovery_e221_265 _e243_network_owner_label
_e243_network_owner_label() {
    if _e202_small_bbr_active; then
        echo 'E202兼容小BBR（八档14/25/26项）';
    else
        if _e202_current_owner_claimed; then
            echo 'E202小BBR（状态异常，禁止覆盖）';
        else
            if _e202_legacy_e200_active; then
                echo 'E200旧小BBR（待升级）';
            else
                if _e202_legacy_e198_active; then
                    echo 'E198旧小BBR（待升级）';
                else
                    if _e202_legacy_e196_active; then
                        echo 'E196旧小BBR（待升级）';
                    else
