                            error '流量网卡状态文件创建失败。';
                            _e116_pause;
                            continue
                        };
                        printf '%s\n' "$iface" > "$tmp";
                        _e118_atomic_install "$tmp" "$E135_TRAFFIC_IFACE_FILE" 0600 || { 
                            error '流量网卡状态提交失败。';
                            _e116_pause;
                            continue
                        };
                        _e243_vnstat_ready "$iface" && info "vnStat已初始化并读回：iface=$iface" || error 'vnStat初始化后读回未通过。';
