# EEX3-FUNCTION upgrade_recovery_e221_265 _e243_vnstat_ready
_e243_vnstat_ready() {
    local iface="${1:-}" owned_iface="";
    test -n "$iface" && command -v vnstat > /dev/null 2>&1 || return 1;
    test -f "$E135_TRAFFIC_IFACE_FILE" && test ! -L "$E135_TRAFFIC_IFACE_FILE" && test -r "$E135_TRAFFIC_IFACE_FILE" || return 1;
    owned_iface=$(sed -n '1p' "$E135_TRAFFIC_IFACE_FILE" 2> /dev/null || true);
    test "$owned_iface" = "$iface" || return 1;
    { 
        systemctl is-active --quiet vnstat.service 2> /dev/null || systemctl is-active --quiet vnstat 2> /dev/null
    } || return 1;
    { 
        systemctl is-enabled --quiet vnstat.service 2> /dev/null || systemctl is-enabled --quiet vnstat 2> /dev/null
    } || return 1;
    vnstat --iflist 2> /dev/null | tr ' ' '\n' | grep -Fxq "$iface"
