            return 1
        };
        _e266_buffer_candidate_build "$config" "$value" "$candidate" || { 
            _e266_buffer_fail "$log" candidate-build 'jq候选配置构建失败' 1;
            return 1
        };
        _e266_buffer_xray_test "$candidate" || { 
            _e266_buffer_fail "$log" candidate-config-test '候选配置未通过Xray测试' 1;
            return 1
        };
        file_mode=$(stat -c '%a' "$config" 2> /dev/null || true);
        uid=$(stat -c '%u' "$config" 2> /dev/null || true);
        gid=$(stat -c '%g' "$config" 2> /dev/null || true);
        [[ "$file_mode" =~ ^[0-7]{3,4}$ && "$uid" =~ ^[0-9]+$ && "$gid" =~ ^[0-9]+$ ]] || { 
            _e266_buffer_fail "$log" config-metadata '无法读取原配置权限/所有者' 1;
            return 1
        };
        _e266_buffer_atomic_replace "$candidate" "$config" "$file_mode" "$uid" "$gid" || { 
            _e266_buffer_fail "$log" config-commit '候选配置原子提交失败' 1;
            return 1
        };
        config_changed=1;
        need_restart=1;
        _e266_buffer_log_event "$log" OK config-commit 0 "${current:-unset}->${value}" || true;
    else
        _e266_buffer_log_event "$log" INFO config-idempotent 0 "JSON已经是${value}KB" || true;
    fi;
    if ! _e266_buffer_dropin_exact "$dropin"; then
        if test -e "$dropin" || test -L "$dropin"; then
            _e266_buffer_path_safe_file "$dropin" || { 
                _e266_buffer_fail "$log" dropin-trust '现有drop-in不是可信root普通文件' 1;
                return 1
            };
        fi;
        _e266_buffer_dropin_install "$dropin" || { 
            _e266_buffer_fail "$log" dropin-commit 'systemd环境屏蔽drop-in提交失败' 1;
            return 1
        };
        dropin_changed=1;
        _e266_buffer_log_event "$log" OK dropin-commit 0 '精确安装UnsetEnvironment' || true;
    fi;
    _e266_buffer_systemctl daemon-reload > /dev/null 2>&1 || { 
        _e266_buffer_fail "$log" daemon-reload 'systemd daemon-reload失败' 1;
        return 1
    };
    if test "$expected_active" = 1; then
        local live_pid="";
        live_pid=$(_e266_buffer_systemctl show xray.service -p MainPID --value 2> /dev/null || true);
        _e266_buffer_process_env_clean "$live_pid" "$proc_root" || need_restart=1;
        if test "$need_restart" = 1; then
            _e266_buffer_systemctl restart xray.service > /dev/null 2>&1 || { 
                _e266_buffer_fail "$log" service-restart 'Xray restart命令失败' 1;
                return 1
            };
            restarted=1;
        fi;
    fi;
    _e266_buffer_state_commit "$value" "$config" "$state" || { 
        _e266_buffer_fail "$log" state-commit '哈希绑定状态文件提交失败' 1;
        return 1
    };
    _e266_buffer_log_event "$log" INFO mutation-summary 0 "config_changed=$config_changed dropin_changed=$dropin_changed restarted=$restarted" || true;
    _e266_buffer_readback "$value" "$expected_active" "$config" "$dropin" "$state" "$proc_root" "$log"
}
# EEX3-FUNCTION release_e266 _e266_buffer_config_value
_e266_buffer_config_value() {
    local file="${1:-$CONFIG}";
    test -f "$file" && test ! -L "$file" && command -v jq > /dev/null 2>&1 || return 1;
    jq -er '
      (.policy.levels["0"].bufferSize // empty) as $v |
      select(($v|type)=="number" and ($v|floor)==$v and $v>=0) |
      ($v|tostring)
    ' "$file" 2> /dev/null
}
# EEX3-FUNCTION release_e266 _e266_buffer_dropin_exact
_e266_buffer_dropin_exact() {
    local file="${1:-$E266_BUFFER_DROPIN}";
    _e266_buffer_path_safe_file "$file" || return 1;
    cmp -s -- "$file" <(printf '[Service]\nUnsetEnvironment=XRAY_RAY_BUFFER_SIZE\n')
}
# EEX3-FUNCTION release_e266 _e266_buffer_dropin_install
_e266_buffer_dropin_install() {
    local target="${1:-$E266_BUFFER_DROPIN}" tmp="";
    tmp=$(_e118_mktemp e266-buffer-dropin) || return 1;
    printf '[Service]\nUnsetEnvironment=XRAY_RAY_BUFFER_SIZE\n' > "$tmp" || return 1;
    _e266_buffer_atomic_replace "$tmp" "$target" 0644 0 0 || return 1;
    _e266_buffer_dropin_exact "$target"
}
# EEX3-FUNCTION release_e266 _e266_buffer_exit_guard
_e266_buffer_exit_guard() {
    local status="${1:-1}" tx="${2:-}" committed="${3:-0}";
    trap - EXIT HUP INT TERM;
    test "$committed" = 0 || exit "$status";
    error 'E266 bufferSize事务未提交，正在恢复原配置、环境与Xray运行状态。';
    if _e266_buffer_rollback "$tx"; then
        rm -rf --one-file-system -- "$tx" 2> /dev/null || true;
        info 'bufferSize事务已安全回滚。';
        test "$status" -ne 0 || status=1;
        exit "$status";
    fi;
    printf 'reason=buffer-rollback-or-readback-failed\n' > "$tx/.preserve.env" 2> /dev/null || true;
    error "严重：bufferSize回滚未完整通过；微型恢复证据：$tx";
    exit 70
}
# EEX3-FUNCTION release_e266 _e266_buffer_fail
_e266_buffer_fail() {
    local log="${1:-$E266_BUFFER_LOG}" stage="${2:-unknown}";
    local detail="${3:-未说明}" rc="${4:-1}";
    [[ "$rc" =~ ^[1-9][0-9]{0,2}$ ]] && ((rc <= 255)) || rc=1;
    _e266_buffer_log_event "$log" FAIL "$stage" "$rc" "$detail" 2> /dev/null || true;
    error "E266 bufferSize子门禁失败：$stage（$detail），rc=$rc。";
    error "E266 bufferSize诊断日志：$log";
    return "$rc"
}
# EEX3-FUNCTION release_e266 _e266_buffer_log_event
_e266_buffer_log_event() {
    local log="${1:-$E266_BUFFER_LOG}" event="${2:-INFO}" stage="${3:-unknown}";
    local rc="${4:-0}" detail="${5:-}";
    [[ "$event" =~ ^(BEGIN|OK|FAIL|INFO)$ && "$stage" =~ ^[a-z0-9][a-z0-9-]{0,63}$ && "$rc" =~ ^[0-9]{1,3}$ ]] || return 1;
    detail=${detail//$'\r'/ };
    detail=${detail//$'\n'/ };
    detail=${detail//|/ };
    detail=${detail:0:200};
    printf 'time=%s|event=%s|stage=%s|rc=%s|detail=%s\n' "$(date -Is 2> /dev/null || date)" "$event" "$stage" "$rc" "$detail" >> "$log"
}
# EEX3-FUNCTION release_e266 _e266_buffer_log_init
_e266_buffer_log_init() {
    local log="${1:-$E266_BUFFER_LOG}" mode="${2:-unknown}" value="${3:-unknown}";
    local dir="";
    dir=$(dirname -- "$log") || return 1;
    if test -e "$dir" || test -L "$dir"; then
        test -d "$dir" && test ! -L "$dir" || return 1;
    else
        install -d -o 0 -g 0 -m 0700 -- "$dir" || return 1;
    fi;
    if test -e "$log" || test -L "$log"; then
        _e266_buffer_path_safe_file "$log" || return 1;
    fi;
    ( umask 077;
    : > "$log" ) || return 1;
    chmod 0600 -- "$log" || return 1;
    printf 'release=199e266\nmode=%s\nrequested_kib=%s\nstarted_at=%s\n' "$mode" "$value" "$(date -Is 2> /dev/null || date)" >> "$log"
}
# EEX3-FUNCTION release_e266 _e266_buffer_managed_intent_readonly
_e266_buffer_managed_intent_readonly() {
    local state="${1:-}" config="${2:-$CONFIG}" version="${3:-}" value="";
    if test -n "$state"; then
        test -n "$version" || version=$(_e266_buffer_meta_value "$state" version 2> /dev/null || true);
        case "$version" in 
            199e260 | 199e262 | 199e266)

            ;;
            *)
                return 1
            ;;
        esac;
        _e266_buffer_state_intent_file "$state" "$config" "$version";
        return $?;
    fi;
    value=$(_e266_buffer_state_intent_file "$E266_BUFFER_STATE" "$config" 199e266 2> /dev/null || true);
    if _e266_buffer_value_valid "$value"; then
        printf '%s\n' "$value";
        return 0;
    fi;
    value=$(_e266_buffer_state_intent_file "$E266_LEGACY_E262_BUFFER_STATE" "$config" 199e262 2> /dev/null || true);
    if _e266_buffer_value_valid "$value"; then
        printf '%s\n' "$value";
        return 0;
    fi;
    value=$(_e266_buffer_state_intent_file "$E266_LEGACY_E260_BUFFER_STATE" "$config" 199e260 2> /dev/null || true);
    _e266_buffer_value_valid "$value" || return 1;
    printf '%s\n' "$value"
}
# EEX3-FUNCTION release_e266 _e266_buffer_menu
_e266_buffer_menu() {
    local choice value confirm current;
    while true; do
        current=$(_e266_buffer_config_value "$CONFIG" 2> /dev/null || true);
        title "${EEX3_BUILD_ID^^}：Xray bufferSize（持久化及运行读回）";
        printf '  当前等级0：%s KB\n' "${current:-未设置}";
        printf '%s\n' '  1) 128 KB' '  2) 256 KB' '  3) 512 KB' '  4) 768 KB' '  5) 1024 KB' '  6) 4096 KB' '  7) 只读状态' '  8) 自定义 1–16384 KB' '  0) 返回';
        read -rp '选择: ' choice || return 0;
        case "$choice" in 
            1)
                value=128
            ;;
            2)
                value=256
            ;;
            3)
                value=512
            ;;
            4)
                value=768
            ;;
            5)
                value=1024
            ;;
            6)
                value=4096
            ;;
            7)
                _e266_buffer_status;
                continue
            ;;
            8)
                read -rp '整数KB: ' value || return 0
            ;;
            0 | '')
                return 0
            ;;
            *)
                warn '无效选项。';
                continue
            ;;
        esac;
        _e266_buffer_value_valid "$value" || { 
            warn '请输入1–16384整数，不含前导零。';
            continue
        };
        warn '数值越大不代表越快；并发时可能增加内存占用，生效可能需要重启Xray并短暂断流。';
        read -rp "将配置中所有现有/引用用户等级设为${value}KB，确认？[y/N]: " confirm || return 0;
        case "$confirm" in 
            y | Y)
                _eex3_buffer_cli "$value"
            ;;
            *)
                info '已取消。'
            ;;
        esac;
    done
}
# EEX3-FUNCTION release_e266 _e266_buffer_meta_value
_e266_buffer_meta_value() {
    local file="${1:-}" key="${2:-}";
    [[ "$key" =~ ^[a-z0-9_]+$ ]] || return 1;
    awk -F= -v k="$key" '
      $1==k { n++; v=substr($0,index($0,"=")+1) }
      END { if(n==1 && v!="") print v; else exit 1 }
    ' "$file" 2> /dev/null
}
# EEX3-FUNCTION release_e266 _e266_buffer_mock_self_test
_e266_buffer_mock_self_test() {
    ( local d="" config="" candidate="" dropin="" state="" tx="" value="" rc=0;
    local before_config="" before_dropin="" before_state="" sha="";
    d=$(mktemp -d /tmp/xray-e266-buffer-test.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    config="$d/config.json";
    candidate="$d/candidate.json";
    dropin="$d/99-e266-buffer.conf";
    state="$d/xray-buffer.env";
    tx="$d/tx";
    printf '{"log":{"loglevel":"warning"},"policy":{"levels":{"0":{"bufferSize":128}}}}\n' > "$config" || return 1;
    chmod 0600 "$config" || return 1;
    for value in 128 256 512 768 1024 4096;
    do
        _e266_buffer_candidate_build "$config" "$value" "$candidate" || rc=1;
        test "$(_e266_buffer_config_value "$candidate" 2> /dev/null || true)" = "$value" || rc=1;
    done;
    for value in 0 01 016384 16385 -1 1.5 bad;
    do
        _e266_buffer_candidate_build "$config" "$value" "$candidate" > /dev/null 2>&1 && rc=1 || true;
    done;
    for value in 128 256 512 768 1024 4096;
    do
        _e266_buffer_candidate_build "$config" "$value" "$candidate" || return 1;
        install -m 0600 "$candidate" "$config" || return 1;
        sha=$(sha256sum "$config" | awk '{print $1}') || return 1;
        printf 'version=199e266\nbuffer_size_kib=%s\nconfig_sha256=%s\nupdated_epoch=1\n' "$value" "$sha" > "$state" || return 1;
        chmod 0600 "$state" || return 1;
        test "$(_e266_buffer_managed_intent_readonly "$state" "$config" 199e266 2> /dev/null || true)" = "$value" || rc=1;
    done;
    sha=$(sha256sum "$config" | awk '{print $1}') || return 1;
    printf 'version=199e266\nbuffer_size_kib=896\nconfig_sha256=%s\nupdated_epoch=1\n' "$sha" > "$state";
    _e266_buffer_managed_intent_readonly "$state" "$config" 199e266 > /dev/null 2>&1 && rc=1 || true;
    printf 'version=199e266\nbuffer_size_kib=128\nconfig_sha256=%s\nupdated_epoch=1\n' "$(printf stale | sha256sum | awk '{print $1}')" > "$state";
    _e266_buffer_managed_intent_readonly "$state" "$config" 199e266 > /dev/null 2>&1 && rc=1 || true;
    _e266_buffer_candidate_build "$config" 128 "$candidate" || return 1;
    install -m 0600 "$candidate" "$config" || return 1;
    sha=$(sha256sum "$config" | awk '{print $1}') || return 1;
    printf 'version=199e260\nbuffer_size_kib=128\nconfig_sha256=%s\nupdated_epoch=1\n' "$sha" > "$state" || return 1;
    test "$(_e266_buffer_managed_intent_readonly "$state" "$config" 199e260 2> /dev/null || true)" = 128 || rc=1;
    printf 'version=199e262\nbuffer_size_kib=128\nconfig_sha256=%s\nupdated_epoch=1\n' "$sha" > "$state" || return 1;
    test "$(_e266_buffer_managed_intent_readonly "$state" "$config" 199e262 2> /dev/null || true)" = 128 || rc=1;
    printf '[Service]\nEnvironment="GOGC=300"\n' > "$dropin" || return 1;
    chmod 0644 "$dropin";
    chmod 0600 "$state" || return 1;
    before_config=$(sha256sum "$config" | awk '{print $1}');
    before_dropin=$(sha256sum "$dropin" | awk '{print $1}');
    before_state=$(sha256sum "$state" | awk '{print $1}');
    _e266_buffer_snapshot_create "$tx" "$config" "$dropin" "$state" 512 0 || return 1;
    _e266_buffer_snapshot_verify "$tx" || rc=1;
    printf '{"changed":true}\n' > "$config";
    printf 'changed\n' > "$dropin";
    printf 'changed\n' > "$state";
    _e266_buffer_snapshot_restore "$tx" "$config" "$dropin" "$state" || rc=1;
    test "$(sha256sum "$config" | awk '{print $1}')" = "$before_config" || rc=1;
    test "$(sha256sum "$dropin" | awk '{print $1}')" = "$before_dropin" || rc=1;
    test "$(sha256sum "$state" | awk '{print $1}')" = "$before_state" || rc=1;
    rm -rf -- "$tx";
    rm -f -- "$dropin" "$state";
    _e266_buffer_snapshot_create "$tx" "$config" "$dropin" "$state" 1024 0 || return 1;
    printf 'new\n' > "$dropin";
    printf 'new\n' > "$state";
    _e266_buffer_snapshot_restore "$tx" "$config" "$dropin" "$state" || rc=1;
    test ! -e "$dropin" && test ! -L "$dropin" || rc=1;
    test ! -e "$state" && test ! -L "$state" || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION release_e266 _e266_buffer_path_safe_file
_e266_buffer_path_safe_file() {
    local file="${1:-}" uid="" mode="";
    test -f "$file" && test ! -L "$file" || return 1;
    uid=$(stat -c '%u' "$file" 2> /dev/null || true);
    mode=$(stat -c '%a' "$file" 2> /dev/null || true);
    test "$uid" = 0 && [[ "$mode" =~ ^[0-7]{3,4}$ ]] && test $((8#$mode & 0022)) -eq 0
}
# EEX3-FUNCTION release_e266 _e266_buffer_process_env_clean
_e266_buffer_process_env_clean() {
    local pid="${1:-}" proc_root="${2:-/proc}" item="" env_file="";
    [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1;
    env_file="${proc_root%/}/$pid/environ";
    test -r "$env_file" && test -f "$env_file" || return 1;
    while IFS= read -r -d '' item; do
        case "$item" in 
            XRAY_RAY_BUFFER_SIZE=*)
                return 1
            ;;
        esac;
    done < "$env_file";
    return 0
}
# EEX3-FUNCTION release_e266 _e266_buffer_readback
_e266_buffer_readback() {
    _eex3_buffer_readback_abi "$@" && _eex3_buffer_levels_match "${3:-$CONFIG}" "${1:-}"
}
# EEX3-FUNCTION release_e266 _e266_buffer_recover_one_pending
_e266_buffer_recover_one_pending() {
    local label="${1:-E266}" tx="${2:-}" dropin="${3:-}" state="${4:-}";
    local expected_version="${5:-199e266}" trusted_tx="";
    case "$expected_version" in 
        199e260)
            trusted_tx="$E266_LEGACY_E260_BUFFER_TX"
        ;;
        199e262)
            trusted_tx="$E266_LEGACY_E262_BUFFER_TX"
        ;;
        199e266)
            trusted_tx="$E266_BUFFER_TX"
        ;;
        *)
            return 1
        ;;
    esac;
    test "$tx" = "$trusted_tx" || return 1;
    test ! -e "$tx" && test ! -L "$tx" && return 0;
    _e266_buffer_tx_trusted "$tx" "$trusted_tx" || { 
        error "$label bufferSize事务目录不可信，拒绝覆盖：$tx";
        return 1
    };
    if test -f "$tx/.committed.env" && test ! -L "$tx/.committed.env"; then
        rm -rf --one-file-system -- "$tx";
        return $?;
    fi;
    if test ! -e "$tx/.active.env" && test ! -L "$tx/.active.env"; then
        warn "发现尚未进入写入阶段的$label bufferSize残留事务，正在移除。";
        rm -rf --one-file-system -- "$tx";
        return $?;
    fi;
    warn "检测到上次未关闭的$label bufferSize事务，先恢复原配置和服务状态。";
    if _e266_buffer_rollback "$tx" "$dropin" "$state" "$expected_version"; then
        rm -rf --one-file-system -- "$tx";
        info "$label bufferSize遗留事务已恢复并读回。";
        return 0;
    fi;
    printf 'reason=pending-buffer-rollback-failed\n' > "$tx/.preserve.env" 2> /dev/null || true;
    error "$label bufferSize遗留事务恢复失败，已保留证据：$tx";
    return 1
}
# EEX3-FUNCTION release_e266 _e266_buffer_recover_pending
_e266_buffer_recover_pending() {
    _e266_buffer_recover_one_pending E260 "$E266_LEGACY_E260_BUFFER_TX" "$E266_LEGACY_E260_BUFFER_DROPIN" "$E266_LEGACY_E260_BUFFER_STATE" 199e260 || return 1;
    _e266_buffer_recover_one_pending E262 "$E266_LEGACY_E262_BUFFER_TX" "$E266_LEGACY_E262_BUFFER_DROPIN" "$E266_LEGACY_E262_BUFFER_STATE" 199e262 || return 1;
    _e266_buffer_recover_one_pending E266 "$E266_BUFFER_TX" "$E266_BUFFER_DROPIN" "$E266_BUFFER_STATE" 199e266
}
# EEX3-FUNCTION release_e266 _e266_buffer_restore_copy
_e266_buffer_restore_copy() {
    local source="${1:-}" target="${2:-}" dir="" base="" stage="";
    test -f "$source" && test ! -L "$source" || return 1;
    dir=$(dirname -- "$target");
    base=$(basename -- "$target");
    if test -e "$dir" || test -L "$dir"; then
        test -d "$dir" && test ! -L "$dir" || return 1;
    else
        install -d -o 0 -g 0 -m 0755 "$dir" || return 1;
    fi;
    stage=$(mktemp --tmpdir="$dir" ".${base}.e266-restore.XXXXXX") || return 1;
    cp -a --remove-destination -- "$source" "$stage" || { 
        rm -f -- "$stage";
        return 1
    };
    mv -fT -- "$stage" "$target" || { 
        rm -f -- "$stage";
        return 1
    }
}
# EEX3-FUNCTION release_e266 _e266_buffer_rollback
_e266_buffer_rollback() {
    local tx="${1:-}" dropin="${2:-$E266_BUFFER_DROPIN}" state="${3:-$E266_BUFFER_STATE}";
    local expected_version="${4:-199e266}" proc_root="${5:-/proc}" log="${6:-$E266_BUFFER_LOG}";
    local was_active="" active="" rc=0;
    _e266_buffer_snapshot_verify "$tx" "$expected_version" || return 1;
    was_active=$(_e266_buffer_meta_value "$tx/meta.env" xray_was_active) || return 1;
    _e266_buffer_snapshot_restore "$tx" "$CONFIG" "$dropin" "$state" "$expected_version" || rc=1;
    _e266_buffer_systemctl daemon-reload > /dev/null 2>&1 || rc=1;
    _e266_buffer_xray_test "$CONFIG" || rc=1;
    if test "$was_active" = 1; then
        _e266_buffer_systemctl restart xray.service > /dev/null 2>&1 || rc=1;
        active=$(_e266_buffer_systemctl show xray.service -p ActiveState --value 2> /dev/null || true);
        test "$active" = active || rc=1;
        test "$rc" -ne 0 || _e266_buffer_runtime_verify "$CONFIG" || rc=1;
    else
        _e266_buffer_systemctl stop xray.service > /dev/null 2>&1 || true;
        active=$(_e266_buffer_systemctl show xray.service -p ActiveState --value 2> /dev/null || true);
        test "$active" = inactive || rc=1;
    fi;
    if test "$rc" -eq 0; then
        _e266_buffer_log_event "$log" OK rollback 0 "snapshot_version=$expected_version active=$was_active" 2> /dev/null || true;
    else
        _e266_buffer_log_event "$log" FAIL rollback 1 "snapshot_version=$expected_version active=$was_active" 2> /dev/null || true;
    fi;
    return "$rc"
}
# EEX3-FUNCTION release_e266 _e266_buffer_runtime_verify
_e266_buffer_runtime_verify() {
    _e127_verify_xray_runtime "${1:-$CONFIG}" 12
}
# EEX3-FUNCTION release_e266 _e266_buffer_service_activity
_e266_buffer_service_activity() {
    local load="" active="";
    load=$(_e266_buffer_systemctl show xray.service -p LoadState --value 2> /dev/null) || return 1;
    test "$load" = loaded || return 1;
    active=$(_e266_buffer_systemctl show xray.service -p ActiveState --value 2> /dev/null) || return 1;
    case "$active" in 
        active)
            printf '1\n'
        ;;
        inactive)
            printf '0\n'
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION release_e266 _e266_buffer_snapshot_create
_e266_buffer_snapshot_create() {
    local tx="${1:-}" config="${2:-}" dropin="${3:-}" state="${4:-}";
    local value="${5:-}" was_active="${6:-0}" dropin_was=absent state_was=absent;
    _e266_buffer_value_valid "$value" && [[ "$was_active" =~ ^[01]$ ]] || return 1;
    _e266_buffer_path_safe_file "$config" || return 1;
    test ! -e "$tx" && test ! -L "$tx" || return 1;
    install -d -o 0 -g 0 -m 0700 "$tx" || return 1;
    cp -a -- "$config" "$tx/config.before" || return 1;
    if test -e "$dropin" || test -L "$dropin"; then
        _e266_buffer_path_safe_file "$dropin" || return 1;
        cp -a -- "$dropin" "$tx/dropin.before" || return 1;
        dropin_was=present;
    fi;
    if test -e "$state" || test -L "$state"; then
        _e266_buffer_path_safe_file "$state" || return 1;
        cp -a -- "$state" "$tx/state.before" || return 1;
        state_was=present;
    fi;
    { 
        printf 'version=199e266\n';
        printf 'requested=%s\n' "$value";
        printf 'xray_was_active=%s\n' "$was_active";
        printf 'dropin_was=%s\n' "$dropin_was";
        printf 'state_was=%s\n' "$state_was"
    } > "$tx/meta.env" || return 1;
    ( cd "$tx" || exit 1;
    sha256sum config.before meta.env > before.sha256 || exit 1;
    test "$dropin_was" != present || sha256sum dropin.before >> before.sha256 || exit 1;
    test "$state_was" != present || sha256sum state.before >> before.sha256 || exit 1 ) || return 1;
    { 
        printf 'version=199e266\n';
        printf 'pid=%s\n' "${BASHPID:-$$}";
        printf 'created_epoch=%s\n' "$(date +%s)"
    } > "$tx/.active.env" || return 1;
    chmod 0600 "$tx/meta.env" "$tx/before.sha256" "$tx/.active.env" || return 1
}
# EEX3-FUNCTION release_e266 _e266_buffer_snapshot_restore
_e266_buffer_snapshot_restore() {
    local tx="${1:-}" config="${2:-}" dropin="${3:-}" state="${4:-}";
    local expected_version="${5:-199e266}" dropin_was="" state_was="" rc=0;
    _e266_buffer_snapshot_verify "$tx" "$expected_version" || return 1;
    dropin_was=$(_e266_buffer_meta_value "$tx/meta.env" dropin_was) || return 1;
    state_was=$(_e266_buffer_meta_value "$tx/meta.env" state_was) || return 1;
    _e266_buffer_restore_copy "$tx/config.before" "$config" || rc=1;
    if test "$dropin_was" = present; then
        _e266_buffer_restore_copy "$tx/dropin.before" "$dropin" || rc=1;
    else
        test ! -d "$dropin" || rc=1;
        rm -f -- "$dropin" || rc=1;
    fi;
    if test "$state_was" = present; then
        _e266_buffer_restore_copy "$tx/state.before" "$state" || rc=1;
    else
        test ! -d "$state" || rc=1;
        rm -f -- "$state" || rc=1;
    fi;
    return "$rc"
}
# EEX3-FUNCTION release_e266 _e266_buffer_snapshot_verify
_e266_buffer_snapshot_verify() {
    local tx="${1:-}" expected_version="${2:-199e266}";
    local dropin_was="" state_was="" requested="" was_active="";
    case "$expected_version" in 
        199e260 | 199e262 | 199e266)

        ;;
        *)
            return 1
        ;;
    esac;
    test -d "$tx" && test ! -L "$tx" && test -f "$tx/meta.env" && test ! -L "$tx/meta.env" && test -f "$tx/before.sha256" && test ! -L "$tx/before.sha256" || return 1;
    ( cd "$tx" && sha256sum -c before.sha256 > /dev/null 2>&1 ) || return 1;
    test "$(_e266_buffer_meta_value "$tx/meta.env" version)" = "$expected_version" || return 1;
    requested=$(_e266_buffer_meta_value "$tx/meta.env" requested) || return 1;
    was_active=$(_e266_buffer_meta_value "$tx/meta.env" xray_was_active) || return 1;
    dropin_was=$(_e266_buffer_meta_value "$tx/meta.env" dropin_was) || return 1;
    state_was=$(_e266_buffer_meta_value "$tx/meta.env" state_was) || return 1;
    _e266_buffer_value_valid "$requested" && [[ "$was_active" =~ ^[01]$ ]] || return 1;
    case "$dropin_was" in 
        present)
            test -f "$tx/dropin.before" && test ! -L "$tx/dropin.before" || return 1
        ;;
        absent)
            test ! -e "$tx/dropin.before" && test ! -L "$tx/dropin.before" || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    case "$state_was" in 
        present)
            test -f "$tx/state.before" && test ! -L "$tx/state.before" || return 1
        ;;
        absent)
            test ! -e "$tx/state.before" && test ! -L "$tx/state.before" || return 1
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION release_e266 _e266_buffer_state_commit
_e266_buffer_state_commit() {
    local value="${1:-}" config="${2:-$CONFIG}" state="${3:-$E266_BUFFER_STATE}" tmp sha;
    _e266_buffer_value_valid "$value" && _eex3_buffer_levels_match "$config" "$value" || return 1;
    sha=$(sha256sum "$config") || return 1;
    sha=${sha%% *};
    tmp=$(_e118_mktemp eex7-buffer-state) || return 1;
    printf 'version=199e266\nschema=2\nbuffer_size_kib=%s\nconfig_sha256=%s\nupdated_epoch=%s\n' "$value" "$sha" "$(date +%s)" > "$tmp" || return 1;
    _e266_buffer_atomic_replace "$tmp" "$state" 0600 0 0
}
# EEX3-FUNCTION release_e266 _e266_buffer_state_intent_file
_e266_buffer_state_intent_file() {
    local state="${1:-}" config="${2:-$CONFIG}" expected_version="${3:-199e266}" line key value version sha updated;
    local -A fields=();
    _e266_buffer_path_safe_file "$state" && _e266_buffer_path_safe_file "$config" || return 1;
    if ! grep -qx 'schema=2' "$state"; then
        _eex7_buffer_state_v1_read "$state" "$config" "$expected_version";
        return $?;
    fi;
    test "$expected_version" = 199e266 || return 1;
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-z0-9_]+)=(.+)$ ]] || return 1;
        key=${BASH_REMATCH[1]};
        value=${BASH_REMATCH[2]};
        case "$key" in 
            version | schema | buffer_size_kib | config_sha256 | updated_epoch)

            ;;
            *)
                return 1
            ;;
        esac;
        test -z "${fields[$key]+x}" || return 1;
        fields[$key]=$value;
    done < "$state";
    test "${#fields[@]}" = 5 && test "${fields[version]}" = 199e266 && test "${fields[schema]}" = 2 || return 1;
    value=${fields[buffer_size_kib]};
    sha=${fields[config_sha256]};
    updated=${fields[updated_epoch]};
    _e266_buffer_value_valid "$value" && [[ "$sha" =~ ^[0-9a-f]{64}$ && "$updated" =~ ^[0-9]{1,20}$ ]] || return 1;
    _eex3_buffer_levels_match "$config" "$value" || return 1;
    printf '%s\n' "$value"
}
# EEX3-FUNCTION release_e266 _e266_buffer_status
_e266_buffer_status() {
    local current="" state_value="" active="unknown" environment="";
    local config_gate=fail pid="" process_override=unknown;
    current=$(_e266_buffer_config_value "$CONFIG" 2> /dev/null || true);
    state_value=$(_e266_buffer_managed_intent_readonly 2> /dev/null || true);
    active=$(_e266_buffer_systemctl show xray.service -p ActiveState --value 2> /dev/null || true);
    _e118_xray_test_config "$CONFIG" 1 > /dev/null 2>&1 && config_gate=pass || true;
    environment=$(_e266_buffer_systemctl show xray.service -p Environment --value 2> /dev/null || true);
    if test "$active" = active; then
        pid=$(_e266_buffer_systemctl show xray.service -p MainPID --value 2> /dev/null || true);
        if _e266_buffer_process_env_clean "$pid" /proc; then
            process_override=absent;
        else
            if [[ "$pid" =~ ^[1-9][0-9]*$ ]] && test -r "/proc/$pid/environ"; then
                process_override=present;
            fi;
        fi;
    fi;
    title 'V199e266：Xray bufferSize 状态（只读）';
    echo "  JSON当前值      : ${current:-未设置（使用Xray默认值）}KB";
    echo "  E266持久化登记  : ${state_value:-未登记}${state_value:+KB}";
    echo "  Xray服务        : $active";
    echo "  Xray配置门禁    : $config_gate";
    if _e266_buffer_dropin_exact "$E266_BUFFER_DROPIN"; then
        echo "  systemd环境覆盖 : E266已安装屏蔽（运行进程=$process_override）";
    else
        if grep -Fq 'XRAY_RAY_BUFFER_SIZE=' <<< "$environment"; then
            echo "  systemd环境覆盖 : 存在且未屏蔽（运行进程=$process_override）";
        else
            echo '  systemd环境覆盖 : 无';
        fi;
    fi;
    if _e266_buffer_dropin_exact "$E266_BUFFER_DROPIN" && test -n "$state_value"; then
        echo '  开机持续设置    : 已安装systemd环境屏蔽 + JSON持久值';
    else
        echo '  开机持续设置    : 尚未由E266接管';
    fi
}
# EEX3-FUNCTION release_e266 _e266_buffer_structure_audit
_e266_buffer_structure_audit() {
    local rc=0 value="" menu="" micro="" apply="" low="" auto="" core="" node_tx="" install_entry="";
    local seal_line="" reconcile_line="" pending_line="" tx_line="" readback="" process_env="";
    menu=$(declare -f _e214_main_menu 2> /dev/null || true);
    micro=$(declare -f _e204_micro_control_menu 2> /dev/null || true);
    apply=$(declare -f _e266_buffer_apply 2> /dev/null || true);
    low=$(declare -f _e266_buffer_commit_lowlevel 2> /dev/null || true);
    auto=$(declare -f _e242_auto_upgrade 2> /dev/null || true);
    core=$(declare -f force_apply_xray_core_defaults_e52 2> /dev/null || true);
    node_tx=$(declare -f _e242_install_mode_transaction 2> /dev/null || true);
    install_entry=$(declare -f _e182_install_mode 2> /dev/null || true);
    readback=$(declare -f _e266_buffer_readback 2> /dev/null || true);
    process_env=$(declare -f _e266_buffer_process_env_clean 2> /dev/null || true);
    echo 'V199e266 bufferSize structure audit:';
    for value in 128 256 512 768 1024 4096;
    do
        _e266_buffer_value_valid "$value" || rc=1;
    done;
    for value in 0 64 129 896 2048 8192 bad;
    do
        _e266_buffer_value_valid "$value" && rc=1 || true;
    done;
    test "$E266_BUFFER_STATE" = "$CONFIG_DIR/e266/xray-buffer.env" && test "$E266_BUFFER_TX" = "$CONFIG_DIR/e266/xray-buffer-transaction" && test "$E266_BUFFER_DROPIN" = /etc/systemd/system/xray.service.d/99-e266-buffer.conf && test "$E266_LEGACY_E262_BUFFER_TX" = "$CONFIG_DIR/e262/xray-buffer-transaction" && test "$E266_LEGACY_E262_BUFFER_DROPIN" = /etc/systemd/system/xray.service.d/99-e262-buffer.conf && test "$E266_LEGACY_E260_BUFFER_TX" = "$CONFIG_DIR/e260/xray-buffer-transaction" && test "$E266_LEGACY_E260_BUFFER_DROPIN" = /etc/systemd/system/xray.service.d/99-e260-buffer.conf && echo '  [PASS] 六档白名单、E266独立持久化路径与E262/E260遗留恢复路径' || { 
        echo '  [FAIL] 档位白名单或持久化路径';
        rc=1
    };
    grep -q '30) Xray bufferSize' <<< "$menu" && grep -q '_e266_buffer_menu' <<< "$menu" && grep -q '5) Xray bufferSize 六档调整' <<< "$micro" && grep -q '_e266_buffer_menu' <<< "$micro" && grep -Fq -- '--buffer-menu)' "$SCRIPT_PATH" && grep -Fq -- '--buffer-status)' "$SCRIPT_PATH" && echo '  [PASS] 主菜单30、微操5与CLI均绑定同一六档入口' || { 
        echo '  [FAIL] bufferSize菜单或CLI绑定';
        rc=1
    };
    grep -q '_e266_buffer_snapshot_create' <<< "$apply" && grep -q '_e266_buffer_exit_guard' <<< "$apply" && grep -q '_e266_buffer_commit_lowlevel' <<< "$apply" && ! grep -q '_e140_system_snapshot\|_safe_jq_write' <<< "$apply$low" && grep -q '_e266_buffer_xray_test' <<< "$low" && grep -q '_e266_buffer_systemctl restart xray.service' <<< "$low" && grep -q '_e266_buffer_readback' <<< "$low" && grep -q 'LoadState' <<< "$readback" && grep -q 'ActiveState' <<< "$readback" && grep -q 'readback-active-state' <<< "$readback" && ! grep -q -- '-p UnsetEnvironment' <<< "$readback" && grep -q 'read -r -d' <<< "$process_env" && grep -q '_e266_buffer_state_intent_file' <<< "$readback" && grep -q 'UnsetEnvironment=XRAY_RAY_BUFFER_SIZE' <<< "$(declare -f _e266_buffer_dropin_install 2> /dev/null || true)" && grep -q 'config-idempotent' <<< "$low" && grep -q 'E266 bufferSize子门禁失败' <<< "$(declare -f _e266_buffer_fail 2> /dev/null || true)" && echo '  [PASS] 微型事务、幂等收敛、active状态闭环、进程环境与分阶段诊断' || { 
        echo '  [FAIL] bufferSize事务或有效读回契约';
        rc=1
    };
    grep -q '_e266_buffer_managed_intent_readonly' <<< "$core" && grep -q -- '--argjson e266_buffer' <<< "$core" && grep -Fq 'bufferSize:$e266_buffer' <<< "$core" && grep -q 'connIdle:260' <<< "$core" && ! grep -q 'bufferSize:768' <<< "$core" && grep -q '_e266_buffer_managed_intent_readonly' <<< "$node_tx" && grep -q '_e266_buffer_upgrade_reconcile' <<< "$node_tx" && grep -q '_e266_buffer_recover_pending' <<< "$install_entry" && echo '  [PASS] 菜单8/26/28与重装重放只动态保持bufferSize，其余核心默认不变' || { 
        echo '  [FAIL] 其他应用入口会覆盖已登记bufferSize';
        rc=1
    };
    seal_line=$(grep -n '_e266_buffer_upgrade_intent_readonly' <<< "$auto" | head -n1 | cut -d: -f1 || true);
    reconcile_line=$(grep -n '_e266_buffer_upgrade_reconcile' <<< "$auto" | head -n1 | cut -d: -f1 || true);
    pending_line=$(grep -n '_e266_buffer_recover_pending' <<< "$auto" | head -n1 | cut -d: -f1 || true);
    tx_line=$(grep -n '_e214_new_tx auto-upgrade-e266' <<< "$auto" | head -n1 | cut -d: -f1 || true);
    [[ "$seal_line" =~ ^[0-9]+$ && "$reconcile_line" =~ ^[0-9]+$ ]] && ((seal_line < reconcile_line)) && [[ "$pending_line" =~ ^[0-9]+$ && "$tx_line" =~ ^[0-9]+$ ]] && ((pending_line < tx_line)) && grep -q 'buffer-final-readback' <<< "$auto" && grep -q '_e266_buffer_upgrade_verify' <<< "$auto" && echo '  [PASS] 热升级先密封旧值，热更新后恢复并纳入最终门禁' || { 
        echo '  [FAIL] 热升级bufferSize保持或最终门禁';
        rc=1
    };
    return "$rc"
}
