# EEX3-FUNCTION release_e266 _e266_buffer_systemd_mock_self_test
_e266_buffer_systemd_mock_self_test() {
    ( local d="" config="" dropin="" state="" log="" proc_root="" restart_log="";
    local mock_active=active mock_load=loaded mock_pid=4242 mock_restart_mode=normal;
    local mock_runtime_ok=1 before_restarts=0 after_restarts=0 rc=0 prop="";
    d=$(mktemp -d /tmp/xray-e266-buffer-systemd-test.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    config="$d/config.json";
    dropin="$d/99-e266-buffer.conf";
    state="$d/xray-buffer.env";
    log="$d/buffer.log";
    proc_root="$d/proc";
    restart_log="$d/restarts";
    E118_TMPDIR="$d/tmp";
    mkdir -p "$E118_TMPDIR" "$proc_root/$mock_pid" || return 1;
    chmod 0700 "$E118_TMPDIR" "$proc_root" "$proc_root/$mock_pid" || return 1;
    printf '{"policy":{"levels":{"0":{"bufferSize":128}}},"inbounds":[],"outbounds":[]}\n' > "$config" || return 1;
    chmod 0600 "$config" || return 1;
    : > "$restart_log";
    printf 'PATH=/usr/bin\0' > "$proc_root/$mock_pid/environ" || return 1;
    chmod 0600 "$proc_root/$mock_pid/environ" || return 1;
    function _e266_buffer_xray_test () 
    { 
        jq empty "${1:-}" > /dev/null 2>&1
    };
    function _e266_buffer_runtime_verify () 
    { 
        test "$mock_runtime_ok" = 1
    };
    function _e266_buffer_systemctl () 
    { 
        case "${1:-}" in 
            daemon-reload)
                return 0
            ;;
            restart)
                printf 'restart\n' >> "$restart_log" || return 1;
                if test "$mock_restart_mode" = collapse; then
                    mock_active=inactive;
                else
                    mock_active=active;
                    printf 'PATH=/usr/bin\0' > "$proc_root/$mock_pid/environ" || return 1;
                fi;
                return 0
            ;;
            stop)
                mock_active=inactive;
                return 0
            ;;
            is-active)
                test "$mock_active" = active;
                return
            ;;
            show)
                prop="";
                while test "$#" -gt 0; do
                    test "$1" != -p || { 
                        shift;
                        prop="${1:-}"
                    };
                    shift || true;
                done;
                case "$prop" in 
                    LoadState)
                        printf '%s\n' "$mock_load"
                    ;;
                    ActiveState)
                        printf '%s\n' "$mock_active"
                    ;;
                    MainPID)
                        printf '%s\n' "$mock_pid"
                    ;;
                    Environment)
                        printf '\n'
                    ;;
                    UnsetEnvironment)
                        : > "$d/unset-property-was-queried";
                        return 77
                    ;;
                    *)
                        return 1
                    ;;
                esac
            ;;
            *)
                return 1
            ;;
        esac
    };
    _e266_buffer_commit_lowlevel 128 fixture "$config" "$dropin" "$state" "$proc_root" "$log" > /dev/null 2>&1 || rc=1;
    test "$(wc -l < "$restart_log" | tr -d ' ')" -eq 1 || rc=1;
    test ! -e "$d/unset-property-was-queried" || rc=1;
    test "$(_e266_buffer_state_intent_file "$state" "$config" 199e266 2> /dev/null || true)" = 128 || rc=1;
    _e266_buffer_commit_lowlevel 128 fixture-idempotent "$config" "$dropin" "$state" "$proc_root" "$log" > /dev/null 2>&1 || rc=1;
    test "$(wc -l < "$restart_log" | tr -d ' ')" -eq 1 || rc=1;
    printf 'XRAY_RAY_BUFFER_SIZE=128\0PATH=/usr/bin\0' > "$proc_root/$mock_pid/environ" || return 1;
    _e266_buffer_commit_lowlevel 128 fixture-env "$config" "$dropin" "$state" "$proc_root" "$log" > /dev/null 2>&1 || rc=1;
    test "$(wc -l < "$restart_log" | tr -d ' ')" -eq 2 || rc=1;
    _e266_buffer_process_env_clean "$mock_pid" "$proc_root" || rc=1;
    mock_restart_mode=collapse;
    _e266_buffer_commit_lowlevel 256 fixture-collapse "$config" "$dropin" "$state" "$proc_root" "$log" > /dev/null 2>&1 && rc=1 || true;
    grep -q 'stage=readback-active-state' "$log" || rc=1;
    mock_restart_mode=normal;
    mock_active=active;
    mock_runtime_ok=0;
    printf 'PATH=/usr/bin\0' > "$proc_root/$mock_pid/environ" || return 1;
    _e266_buffer_commit_lowlevel 512 fixture-runtime "$config" "$dropin" "$state" "$proc_root" "$log" > /dev/null 2>&1 && rc=1 || true;
    grep -q 'stage=readback-runtime' "$log" || rc=1;
    mock_runtime_ok=1;
    mock_active=inactive;
    mock_restart_mode=normal;
    before_restarts=$(wc -l < "$restart_log" | tr -d ' ');
    _e266_buffer_commit_lowlevel 768 fixture-inactive "$config" "$dropin" "$state" "$proc_root" "$log" > /dev/null 2>&1 || rc=1;
    after_restarts=$(wc -l < "$restart_log" | tr -d ' ');
    test "$before_restarts" = "$after_restarts" || rc=1;
    test "$mock_active" = inactive || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION release_e266 _e266_buffer_tx_trusted
_e266_buffer_tx_trusted() {
