# EEX3-FUNCTION release_e266 _e266_cache_cleanup
_e266_cache_cleanup() {
    test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && return 0;
    command -v apt-get > /dev/null 2>&1 && apt-get clean > /dev/null 2>&1 || true;
    command -v journalctl > /dev/null 2>&1 && journalctl --rotate > /dev/null 2>&1 || true;
    command -v journalctl > /dev/null 2>&1 && journalctl --vacuum-time=3d --vacuum-size=100M > /dev/null 2>&1 || true;
