    find /var/log -xdev -type f -name '*.gz' -mtime +3 -delete 2> /dev/null || true;
    find /var/log -xdev -type f \( -name '*.old' -o -name '*.1' \) -mtime +3 -delete 2> /dev/null || true;
    find /var/lib/systemd/coredump -xdev -type f -mtime +3 -delete 2> /dev/null || true;
    find /tmp /var/tmp -xdev -type f -user root -mtime +3 -delete 2> /dev/null || true
}
