        printf '%s|%s\n' "${1:-}" "${2:-}" >> "$calls"
    };
    printf '\n' | _e266_safe_space_cleanup > /dev/null 2>&1 || rc=1;
    printf 'n\n' | _e266_safe_space_cleanup > /dev/null 2>&1 || rc=1;
    test ! -s "$calls" || rc=1;
    printf 'y\n' | _e266_safe_space_cleanup > /dev/null 2>&1 || rc=1;
    test "$(cat "$calls" 2> /dev/null)" = 'menu|0' || rc=1;
    return "$rc" )
}
