# EEX3-FUNCTION release_e266 _e266_disk_headroom_preflight
_e266_disk_headroom_preflight() {
    local estimate="" available="" required="" inode_free="";
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test "${E266_HEADROOM_SELF_TEST_BYPASS:-0}" = 1; then
        return 0;
    fi;
    estimate=$(_e266_snapshot_estimate_kb) || { 
        error '无法估算E266外层快照体积；安装/升级尚未开始。';
        return 1
    };
    available=$(df -Pk / 2> /dev/null | awk 'NR==2{print int($4)}');
    inode_free=$(df -Pi / 2> /dev/null | awk 'NR==2{print int($4)}');
    [[ "$available" =~ ^[0-9]+$ && "$inode_free" =~ ^[0-9]+$ ]] || return 1;
    required=$((estimate * 2 + 524288));
    ((required < 1048576)) && required=1048576;
    if ((available >= required && inode_free >= 4096)); then
        info "E266空间门禁通过：未压缩估算${estimate}KiB，可用${available}KiB，要求${required}KiB，free_inodes=$inode_free。";
        return 0;
    fi;
    error "E266空间门禁未通过：available=${available}KiB required=${required}KiB free_inodes=$inode_free。";
    error '尚未创建新快照或修改小BBR、MTU、网络、Xray；请进入主菜单12确认清理后重试。';
    return 1
}
# EEX3-FUNCTION release_e266 _e266_e159_restore_preupgrade_baseline
_e266_e159_restore_preupgrade_baseline() {
    local lost_origin="${1:-}" state_digest="${2:-}" audit="${E266_LINEAGE_REBASE_DIR:-}";
    local env="" status="" rescue="" expected_lost="" actual_lost="";
    local expected_state="" expected_seal="" actual_seal="" tmp="";
    _e266_lineage_audit_dir_validate "$audit" || return 1;
    env="$audit/lineage.env";
    test -f "$env" && test ! -L "$env" && test "$(stat -c %u "$env" 2> /dev/null || true)" = 0 || return 1;
    status=$(_e266_state_value_once "$env" status) || return 1;
    test "$status" = prepared-owner-free-baseline || return 1;
    test "$(_e266_state_value_once "$env" reason)" = e254-gc-deleted-transitive-e159-origin || return 1;
    test "$(_e266_state_value_once "$env" baseline_kind)" = verified-e202-active-owner-free || return 1;
    rescue=$(_e266_state_value_once "$env" rescue_origin) || return 1;
    test -n "${E266_LINEAGE_RESCUE_TX:-}" && test "$rescue" = "$E266_LINEAGE_RESCUE_TX" || return 1;
    expected_lost=$(_e266_state_value_once "$env" lost_origin_path_sha256) || return 1;
    expected_state=$(_e266_state_value_once "$env" archived_e159_state_sha256) || return 1;
    expected_seal=$(_e266_state_value_once "$env" rescue_seal_sha256) || return 1;
    actual_lost=$(printf '%s' "$lost_origin" | sha256sum | awk 'NR==1{print $1}');
    actual_seal=$(sha256sum "$rescue/seal.sha256" 2> /dev/null | awk 'NR==1{print $1}');
    test "$actual_lost" = "$expected_lost" && test "$state_digest" = "$expected_state" && test "$actual_seal" = "$expected_seal" || return 1;
    _e159_network_tx_verify "$rescue" && _e204_network_origin_clean "$rescue" || return 1;
    _e266_e159_restored_owner_validate "$state_digest" || return 1;
    _e159_network_restore "$rescue" || return 1;
    _e204_network_owner_present && return 1 || true;
    _e159_verify_runtime_file "$rescue/runtime.before" || return 1;
    _e266_e202_inactive_verify || return 1;
    tmp="$audit/.lineage.env.restore.${BASHPID:-$$}";
    sed 's/^status=prepared-owner-free-baseline$/status=restored-owner-free-baseline/' "$env" > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    grep -qx 'status=restored-owner-free-baseline' "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    printf 'baseline_restored_at=%s\n' "$(date -Is 2> /dev/null || date)" >> "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    chmod 0600 "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -T -- "$tmp" "$env" || { 
        rm -f -- "$tmp";
        return 1
    };
    warn '已用阶段9前密封的E202无E159所有者基线撤销断链E159；没有把E159当前运行值伪装成初始基线。'
}
# EEX3-FUNCTION release_e266 _e266_e159_restored_owner_validate
_e266_e159_restored_owner_validate() {
    local expected_digest="${1:-}" digest="" state_supported="" state_unsupported="";
    local state_shadowed="" state_trigger="" report_supported="" report_unsupported="";
    local report_shadowed="" report_trigger="" active="" p="";
    [[ "$expected_digest" =~ ^[0-9a-f]{64}$ ]] || return 1;
    for p in "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" "$E159_NETWORK_STATE" "$E159_NETWORK_SCRIPT" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER" "$E159_MODULES_CONF" "$E159_NETWORK_SEAL";
    do
        test -f "$p" && test ! -L "$p" || return 1;
    done;
    digest=$(sha256sum "$E159_NETWORK_STATE" 2> /dev/null | awk 'NR==1{print $1}');
    test "$digest" = "$expected_digest" || return 1;
    _e266_e159_state_payload_sane "$E159_NETWORK_STATE" || return 1;
    sha256sum -c "$E159_NETWORK_SEAL" > /dev/null 2>&1 || return 1;
    _e159_network_artifacts_validate "$E159_REQUESTED_CONF" "$E159_EFFECTIVE_CONF" "$E159_NETWORK_REPORT" > /dev/null 2>&1 || return 1;
    bash -n "$E159_NETWORK_SCRIPT" > /dev/null 2>&1 || return 1;
    state_supported=$(_e266_state_value_once "$E159_NETWORK_STATE" supported) || return 1;
    state_unsupported=$(_e266_state_value_once "$E159_NETWORK_STATE" unsupported) || return 1;
    state_shadowed=$(_e266_state_value_once "$E159_NETWORK_STATE" shadowed_alias) || return 1;
    state_trigger=$(_e266_state_value_once "$E159_NETWORK_STATE" write_trigger) || return 1;
    report_supported=$(awk -F'\t' 'NR>1&&$2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
    report_unsupported=$(awk -F'\t' 'NR>1&&$2=="unsupported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
    report_shadowed=$(awk -F'\t' 'NR>1&&$2=="shadowed-alias"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
    report_trigger=$(awk -F'\t' 'NR>1&&$1=="net.ipv4.route.flush"&&$2=="supported"{n++}END{print n+0}' "$E159_NETWORK_REPORT");
    active=$(_e159_active_keys "$E159_EFFECTIVE_CONF" | wc -l | tr -d ' ');
    test "$state_supported:$state_unsupported:$state_shadowed:$state_trigger" = "$report_supported:$report_unsupported:$report_shadowed:$report_trigger" && test "$active" = "$state_supported" || return 1;
    for p in "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E156_STATE" "$E159_LEGACY_E154_EFFECTIVE_CONF" "$E159_LEGACY_E154_STATE";
    do
        test ! -e "$p" && test ! -L "$p" || return 1;
    done;
    _e159_network_verify_ownership > /dev/null 2>&1
}
# EEX3-FUNCTION release_e266 _e266_e159_state_payload_sane
_e266_e159_state_payload_sane() {
    local state="${1:-}" version="" requested="" logical="" active="" persistent="";
    local supported="" unsupported="" shadowed="" trigger="" backup="" origin="" n="";
    local tx_re='^/var/backups/xray-e(159|156|154)-network/[A-Za-z0-9._-]+-[0-9]{8}_[0-9]{6}-[0-9]+(-[A-Za-z0-9]+)?$';
    test -f "$state" && test ! -L "$state" && test -s "$state" || return 1;
    version=$(_e266_state_value_once "$state" version) || return 1;
    requested=$(_e266_state_value_once "$state" requested_entries) || return 1;
    logical=$(_e266_state_value_once "$state" logical_controls) || return 1;
    active=$(_e266_state_value_once "$state" effective_active) || return 1;
    persistent=$(_e266_state_value_once "$state" effective_persistent) || return 1;
    supported=$(_e266_state_value_once "$state" supported) || return 1;
    unsupported=$(_e266_state_value_once "$state" unsupported) || return 1;
    shadowed=$(_e266_state_value_once "$state" shadowed_alias) || return 1;
    trigger=$(_e266_state_value_once "$state" write_trigger) || return 1;
    backup=$(_e266_state_value_once "$state" backup) || return 1;
    origin=$(_e266_state_value_once "$state" origin_backup) || return 1;
    test "$version" = 199e159 || return 1;
    for n in "$requested" "$logical" "$active" "$persistent" "$supported" "$unsupported" "$shadowed" "$trigger";
    do
        [[ "$n" =~ ^[0-9]+$ ]] || return 1;
    done;
    test "$requested" -eq 127 && test "$logical" -eq 125 && test "$active" -eq "$supported" && test "$persistent" -eq $((supported-trigger)) && test $((supported+unsupported+shadowed)) -eq 127 && ((trigger <= 1 && shadowed <= 1)) || return 1;
    [[ "$backup" =~ $tx_re && "$origin" =~ $tx_re ]]
}
# EEX3-FUNCTION release_e266 _e266_e202_inactive_verify
_e266_e202_inactive_verify() {
    local active_flag="" unit_active="" unit_enabled="";
