# EEX3-FUNCTION release_e266 _e266_e202_restore_readback
_e266_e202_restore_readback() {
    local snapshot="${1:-}" record="${E266_E202_LINEAGE_RECORD:-}" class="" origin="" digest="";
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test "${E266_E202_SCOPE_TEST_BYPASS:-0}" = 1; then
        _e266_e202_restore_readback_base "$snapshot";
