# EEX3-FUNCTION release_e266 _e266_e202_snapshot_e159_lineage
_e266_e202_snapshot_e159_lineage() {
    local snapshot="${1:-}" archive="" list="" state="" raw="" rel="";
    local state_member="" state_count=0 owner=0 legacy=0 origin="" digest="";
    _e202_snapshot_valid "$snapshot" || return 1;
    archive="$snapshot/files.tar";
    if test ! -s "$archive"; then
        printf 'none|-|-\n';
        return 0;
    fi;
    test -f "$archive" && test ! -L "$archive" && test -r "$archive" || return 1;
    list=$(mktemp /run/xray-e266-lineage-list.XXXXXX 2> /dev/null || true);
    test -n "$list" || list=$(mktemp /tmp/xray-e266-lineage-list.XXXXXX) || return 1;
    state="${list}.state";
    if ! LC_ALL=C tar -tf "$archive" --quoting-style=literal > "$list" 2> /dev/null; then
        rm -f -- "$list" "$state" 2> /dev/null || true;
        return 1;
    fi;
    while IFS= read -r raw; do
        test -n "$raw" || continue;
        rel=${raw#./};
        rel=${rel%/};
        [[ "$rel" != *$'\r'* ]] || { 
            rm -f -- "$list" "$state";
            return 1
        };
        case "$rel" in 
            usr/local/etc/xray/e159/network.state)
                state_count=$((state_count + 1));
                state_member="$raw";
                owner=1
            ;;
            etc/sysctl.d/99-xray-e159-full.conf | etc/systemd/system/xray-network-e159.service | etc/systemd/system/xray-network-e159.timer)
                owner=1
            ;;
            usr/local/etc/xray/e154/network.state | usr/local/etc/xray/e156/network.state | etc/sysctl.d/99-xray-e154-full.conf | etc/sysctl.d/99-xray-e156-full.conf | etc/systemd/system/xray-network-e154.service | etc/systemd/system/xray-network-e156.service)
                legacy=1
            ;;
        esac;
    done < "$list";
    if test "$legacy" -ne 0 || test "$state_count" -gt 1 || { 
        test "$owner" -eq 1 && test "$state_count" -ne 1
    }; then
        rm -f -- "$list" "$state" 2> /dev/null || true;
        return 1;
    fi;
    if test "$owner" -eq 0; then
        rm -f -- "$list" "$state" 2> /dev/null || true;
        printf 'none|-|-\n';
        return 0;
    fi;
    tar -xOf "$archive" -- "$state_member" > "$state" 2> /dev/null || { 
        rm -f -- "$list" "$state";
        return 1
    };
    test "$(stat -c %s "$state" 2> /dev/null || echo 0)" -le 131072 && _e266_e159_state_payload_sane "$state" || { 
        rm -f -- "$list" "$state";
        return 1
    };
    origin=$(_e266_state_value_once "$state" origin_backup) || { 
        rm -f -- "$list" "$state";
        return 1
    };
    digest=$(sha256sum "$state" 2> /dev/null | awk 'NR==1{print $1}');
    [[ "$digest" =~ ^[0-9a-f]{64}$ ]] || { 
        rm -f -- "$list" "$state";
        return 1
    };
    rm -f -- "$list" "$state" 2> /dev/null || true;
    if _e159_network_tx_verify "$origin" 2> /dev/null && _e204_network_origin_clean "$origin" 2> /dev/null; then
        printf 'clean|%s|%s\n' "$origin" "$digest";
    else
        printf 'broken|%s|%s\n' "$origin" "$digest";
    fi
}
# EEX3-FUNCTION release_e266 _e266_e202_xray_basic_gate
_e266_e202_xray_basic_gate() {
