# EEX3-FUNCTION release_e266 _e266_gc_candidate_reference_scan
_e266_gc_candidate_reference_scan() {
    local candidate="${1:-}" out="${2:-}" archive="" list="" payload="";
    local raw="" rel="" count=0 archive_count=0 size=0;
    local regex="";
    regex=$(_e266_gc_reference_regex) || return 1;
    test -d "$candidate" && test ! -L "$candidate" && test -n "$out" || return 1;
    find "$candidate" -xdev -type f -size -2048k ! -name files.tar -print0 2> /dev/null | xargs -0 -r grep -aohE -- "$regex" 2> /dev/null >> "$out" || true;
    list=$(mktemp /run/xray-e266-gc-archive-list.XXXXXX 2> /dev/null || true);
    test -n "$list" || list=$(mktemp /tmp/xray-e266-gc-archive-list.XXXXXX) || return 1;
    payload="${list}.payload";
    while IFS= read -r -d '' archive; do
        archive_count=$((archive_count + 1));
        ((archive_count <= 16)) || { 
            rm -f -- "$list" "$payload";
            return 1
        };
        test -f "$archive" && test ! -L "$archive" && test -r "$archive" || { 
            rm -f -- "$list" "$payload";
            return 1
        };
        if ! LC_ALL=C tar -tf "$archive" --quoting-style=literal > "$list" 2> /dev/null; then
            rm -f -- "$list" "$payload" 2> /dev/null || true;
            return 1;
        fi;
        while IFS= read -r raw; do
            test -n "$raw" || continue;
            rel=${raw#./};
            rel=${rel%/};
            [[ "$rel" != *$'\r'* ]] || { 
                rm -f -- "$list" "$payload";
                return 1
            };
            case "$rel" in 
                usr/local/etc/xray/e[0-9]*/*.env | usr/local/etc/xray/e[0-9]*/*.state | usr/local/etc/xray/e[0-9]*/*.conf | usr/local/etc/xray/e[0-9]*/*.tsv | usr/local/etc/xray/e[0-9]*/*.txt)
                    count=$((count + 1));
                    ((count <= 4096)) || { 
                        rm -f -- "$list" "$payload";
                        return 1
                    };
                    : > "$payload" || { 
                        rm -f -- "$list" "$payload";
                        return 1
                    };
                    tar -xOf "$archive" -- "$raw" > "$payload" 2> /dev/null || { 
                        rm -f -- "$list" "$payload";
                        return 1
                    };
                    size=$(stat -c %s "$payload" 2> /dev/null || true);
                    [[ "$size" =~ ^[0-9]+$ ]] && ((size <= 2097152)) || { 
                        rm -f -- "$list" "$payload";
                        return 1
                    };
                    grep -aohE -- "$regex" "$payload" 2> /dev/null >> "$out" || true
                ;;
            esac;
        done < "$list";
    done < <(find "$candidate" -xdev -mindepth 1 -maxdepth 2 -type f -name files.tar -print0 2> /dev/null);
    rm -f -- "$list" "$payload" 2> /dev/null || true
}
# EEX3-FUNCTION release_e266 _e266_gc_candidate_resolve
_e266_gc_candidate_resolve() {
    local requested_root="${1:-}" candidate="${2:-}" root="" real="" child="";
    _e266_gc_root_allowed "$requested_root" || return 1;
    test -d "$requested_root" && test ! -L "$requested_root" || return 1;
    test -d "$candidate" && test ! -L "$candidate" || return 1;
    root=$(readlink -f -- "$requested_root" 2> /dev/null || true);
    real=$(readlink -f -- "$candidate" 2> /dev/null || true);
    test -n "$root" && test -n "$real" || return 1;
    case "$real" in 
        "$root"/*)

        ;;
        *)
            return 1
        ;;
    esac;
    child=${real#"$root"/};
    [[ "$child" != */* && "$child" =~ ^[A-Za-z0-9._-]+-[0-9]{8}_[0-9]{6}-[0-9]+(-[A-Za-z0-9]+)?$ ]] || return 1;
    printf '%s\n' "$real"
}
# EEX3-FUNCTION release_e266 _e266_gc_live_or_uncertain
_e266_gc_live_or_uncertain() {
    local tx="${1:-}" active="" pid="" expected="" actual="" pid_count=0 start_count=0;
    active="$tx/.active.env";
    test -e "$active" || test -L "$active" || return 1;
    test -f "$active" && test ! -L "$active" && test -r "$active" && test -s "$active" || return 0;
    pid=$(awk -F= '$1=="pid"{n++;v=$2}END{if(n==1)print v;else exit 1}' "$active" 2> /dev/null) || return 0;
    expected=$(awk -F= '$1=="start"{n++;v=$2}END{if(n==1)print v;else exit 1}' "$active" 2> /dev/null) || return 0;
    [[ "$pid" =~ ^[1-9][0-9]*$ && "$expected" =~ ^[0-9]+$ ]] || return 0;
    kill -0 "$pid" 2> /dev/null || return 1;
    actual=$(_e214_proc_start_time "$pid" 2> /dev/null || true);
    test -n "$actual" && test "$actual" = "$expected"
}
# EEX3-FUNCTION release_e266 _e266_gc_log
_e266_gc_log() {
    local line="${1:-}";
    if test "${E266_GC_QUIET:-0}" != 1; then
        case "$line" in 
            BEGIN\|* | END\|* | INFO\|*)
                printf '%s\n' "$line"
            ;;
            *)
                test "${E266_GC_VERBOSE:-0}" = 1 && printf '%s\n' "$line" || true
            ;;
        esac;
    fi;
    test -z "${E266_GC_LOG_ACTIVE:-}" || printf '%s\n' "$line" >> "$E266_GC_LOG_ACTIVE" 2> /dev/null || true
}
# EEX3-FUNCTION release_e266 _e266_gc_mock_self_test
_e266_gc_mock_self_test() {
