    outside="$d/outside-20260101_000006-1-6";
    mkdir -p "$referenced/system" "$disposable" "$preserved" "$live" "$newest" "$outside" || return 1;
    printf 'backup=%s/system\n' "$referenced" > "$refs/state.env" || return 1;
    printf 'reason=fixture\n' > "$preserved/.preserve.env" || return 1;
    start=$(_e214_proc_start_time "$live_pid") || return 1;
