    test -d "$referenced" && test -d "$live" && test ! -e "$preserved" && test ! -e "$newest" || rc=1;
    _e266_gc_remove_candidate "$root" "$outside" 1 > /dev/null 2>&1 && rc=1 || true;
    test -d "$outside" || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION release_e266 _e266_gc_reference_index_build
_e266_gc_reference_index_build() {
    ( local out="${1:-}" work raw index scanned queue additions next candidate count=0 publish="";
    test -n "$out" || return 1;
    work=$(mktemp -d /tmp/eex7-gc-index.XXXXXX) || return 1;
    trap 'rm -rf -- "$work"; test -z "$publish" || rm -f -- "$publish"' EXIT;
    raw="$work/raw";
    index="$work/index";
    scanned="$work/scanned";
    queue="$work/queue";
    additions="$work/additions";
    next="$work/next";
    : > "$scanned" || return 1;
    _e266_gc_reference_index_seed "$raw" || return 1;
    _e266_gc_reference_normalize_file "$raw" "$index" || return 1;
    LC_ALL=C sort -u -o "$index" "$index" || return 1;
    while :; do
        LC_ALL=C comm -23 "$index" "$scanned" > "$queue" || return 1;
        test -s "$queue" || break;
        : > "$additions" || return 1;
        while IFS= read -r candidate; do
            count=$((count+1));
            test "$count" -le 4096 || return 1;
            : > "$raw" || return 1;
            _e266_gc_candidate_reference_scan "$candidate" "$raw" || return 1;
            cat "$raw" >> "$additions" || return 1;
            printf '%s\n' "$candidate" >> "$scanned" || return 1;
        done < "$queue";
        LC_ALL=C sort -u -o "$scanned" "$scanned" || return 1;
        _e266_gc_reference_normalize_file "$additions" "$next" || return 1;
        cat "$next" >> "$index" || return 1;
        LC_ALL=C sort -u -o "$index" "$index" || return 1;
    done;
    publish=$(mktemp "${out}.new.XXXXXX") || return 1;
    cat "$index" > "$publish" && chmod 0600 "$publish" && mv -f -- "$publish" "$out" || return 1;
    publish="" )
}
# EEX3-FUNCTION release_e266 _e266_gc_reference_index_seed
_e266_gc_reference_index_seed() {
    local out="${1:-}" base="" link="" real="" root="" root_real="";
    local child="" candidate="";
    local regex="";
    regex=$(_e266_gc_reference_regex) || return 1;
    test -n "$out" || return 1;
    : > "$out" || return 1;
    while IFS= read -r base; do
        test -d "$base" && test ! -L "$base" || continue;
        find "$base" -xdev -type f -size -2048k -print0 2> /dev/null | xargs -0 -r grep -aohE -- "$regex" 2> /dev/null >> "$out" || true;
        while IFS= read -r link; do
            real=$(readlink -f -- "$link" 2> /dev/null || true);
            test -n "$real" || continue;
            while IFS= read -r root; do
                test -d "$root" && test ! -L "$root" || continue;
                root_real=$(readlink -f -- "$root" 2> /dev/null || true);
                case "$real" in 
                    "$root_real"/*)
                        child=${real#"$root_real"/};
                        child=${child%%/*};
                        candidate="$root_real/$child";
                        _e266_gc_candidate_resolve "$root_real" "$candidate" >> "$out" 2> /dev/null || true;
                        break
                    ;;
                esac;
            done < <(_e266_gc_roots);
        done < <(find "$base" -xdev -type l -print 2> /dev/null);
    done < <(_e266_gc_reference_roots);
    LC_ALL=C sort -u -o "$out" "$out" || return 1;
    chmod 0600 "$out" 2> /dev/null || true
}
# EEX3-FUNCTION release_e266 _e266_gc_reference_normalize_file
_e266_gc_reference_normalize_file() {
    local input="${1:-}" output="${2:-}" ref="" root="" root_real="";
    local child="" candidate="" resolved="";
    test -f "$input" && test ! -L "$input" && test -n "$output" || return 1;
    : > "$output" || return 1;
    while IFS= read -r ref; do
        test -n "$ref" || continue;
        while IFS= read -r root; do
            test -d "$root" && test ! -L "$root" || continue;
            root_real=$(readlink -f -- "$root" 2> /dev/null || true);
            test -n "$root_real" || return 1;
            case "$ref" in 
                "$root"/*)
                    child=${ref#"$root"/}
                ;;
                "$root_real"/*)
                    child=${ref#"$root_real"/}
                ;;
                *)
                    continue
                ;;
            esac;
            child=${child%%/*};
            test -n "$child" || return 1;
            candidate="$root_real/$child";
            resolved=$(_e266_gc_candidate_resolve "$root_real" "$candidate" 2> /dev/null || true);
            test -z "$resolved" || printf '%s\n' "$resolved" >> "$output" || return 1;
            break;
        done < <(_e266_gc_roots);
    done < "$input";
    LC_ALL=C sort -u -o "$output" "$output" || return 1
}
# EEX3-FUNCTION release_e266 _e266_gc_reference_regex
_e266_gc_reference_regex() {
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E266_GC_TEST_REFERENCE_REGEX:-}"; then
        printf '%s\n' "$E266_GC_TEST_REFERENCE_REGEX";
        return 0;
    fi;
    printf '%s\n' '/var/backups/(xray-e[0-9]+(-network)?|xray-mss-e[0-9]+|xray-small-bbr-e[0-9]+)/[A-Za-z0-9._-]+-[0-9]{8}_[0-9]{6}-[0-9]+(-[A-Za-z0-9]+)?'
