# EEX3-FUNCTION release_e266 _e266_gc_reference_roots
_e266_gc_reference_roots() {
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E266_GC_TEST_REFERENCE_ROOT:-}"; then
