}
# EEX3-FUNCTION release_e266 _e266_gc_referenced
_e266_gc_referenced() {
    local candidate="${1:-}" base="" file="" link="" real="";
    test -n "$candidate" || return 1;
    if test -n "${E266_GC_REFERENCE_INDEX:-}"; then
