        grep -Fxq -- "$candidate" "$E266_GC_REFERENCE_INDEX" 2> /dev/null;
        return $?;
    fi;
    while IFS= read -r base; do
        test -d "$base" && test ! -L "$base" || continue;
        while IFS= read -r file; do
            grep -Fq -- "$candidate" "$file" 2> /dev/null && return 0;
        done < <(find "$base" -xdev -type f -size -2048k -print 2> /dev/null);
        while IFS= read -r link; do
            real=$(readlink -f -- "$link" 2> /dev/null || true);
            case "$real" in 
                "$candidate" | "$candidate"/*)
                    return 0
                ;;
            esac;
        done < <(find "$base" -xdev -type l -print 2> /dev/null);
    done < <(_e266_gc_reference_roots);
    return 1
}
# EEX3-FUNCTION release_e266 _e266_gc_remove_candidate
_e266_gc_remove_candidate() {
    local root="${1:-}" candidate="${2:-}" allow_preserve="${3:-0}";
