# EEX3-FUNCTION release_e266 _e266_global_cleanup
_e266_global_cleanup() {
    local context="${1:-manual}" requested_aggressive="${2:-0}";
    local root="" keep=1 allow_preserve=0 rc=0 lock="" lock_fd="" ref_index="";
    local total_kb=0 available_kb=0 budget_kb=0 usage_kb=0 aggressive=0;
    [[ "$requested_aggressive" =~ ^[01]$ ]] || return 1;
    test "$EUID" -eq 0 || { 
        error 'E266空间清理必须使用root。';
        return 1
    };
    if test "${E242_INTERNAL_SELF_TEST:-0}" != 1; then
        lock=/run/lock/xray-e266-backup-gc.lock;
        _e214_ensure_run_lock || return 1;
        exec {lock_fd}> "$lock" || return 1;
        flock -w 30 "$lock_fd" || { 
            exec {lock_fd}>&- 2> /dev/null || true;
            warn '另一个E266清理事务仍在运行，本次跳过。';
            return 1
        };
