            E266_GC_LOG_ACTIVE="$E266_CLEANUP_LOG";
        else
            E266_GC_LOG_ACTIVE=/run/xray-e266-cleanup-last.log;
        fi;
        ( umask 077;
        : > "$E266_GC_LOG_ACTIVE" ) 2> /dev/null || E266_GC_LOG_ACTIVE="";
    fi;
    E266_GC_DELETED=0;
    E266_GC_PROTECTED=0;
    E266_GC_RECLAIMED_KB=0;
