    if test "${E242_INTERNAL_SELF_TEST:-0}" != 1; then
        ref_index=$(mktemp /run/xray-e266-gc-references.XXXXXX 2> /dev/null || true);
        if test -z "$ref_index" || ! _e266_gc_reference_index_build "$ref_index"; then
            test -z "$ref_index" || rm -f -- "$ref_index" 2> /dev/null || true;
            _e266_gc_log 'END|deleted=0|protected=0|reclaimed=0KiB|rc=1|reason=reference-index';
            E266_GC_LOG_ACTIVE="";
            test -z "$lock_fd" || exec {lock_fd}>&- 2> /dev/null || true;
            error '无法一次性建立恢复引用索引；为避免误删，清理尚未开始。';
            return 1;
        fi;
        E266_GC_REFERENCE_INDEX="$ref_index";
        _e266_gc_log "INFO|reference-index|entries=$(wc -l < "$ref_index" 2> /dev/null || echo 0)";
    fi;
    _e266_cache_cleanup || rc=1;
    while IFS= read -r root; do
        _e266_gc_root "$root" 1 "$allow_preserve" || rc=1;
    done < <(_e266_gc_roots);
    if test "${E242_INTERNAL_SELF_TEST:-0}" != 1; then
        total_kb=$(df -Pk / 2> /dev/null | awk 'NR==2{print int($2)}');
        available_kb=$(df -Pk / 2> /dev/null | awk 'NR==2{print int($4)}');
        usage_kb=$(_e266_backup_usage_kb 2> /dev/null || echo 0);
        [[ "$total_kb" =~ ^[0-9]+$ ]] || total_kb=0;
        [[ "$available_kb" =~ ^[0-9]+$ ]] || available_kb=0;
        [[ "$usage_kb" =~ ^[0-9]+$ ]] || usage_kb=0;
        budget_kb=$((total_kb / 5));
        ((budget_kb < 524288)) && budget_kb=524288;
        ((budget_kb > 2097152)) && budget_kb=2097152;
        if test "$requested_aggressive" = 1 || ((usage_kb > budget_kb || available_kb < 1048576)); then
            aggressive=1;
        fi;
    else
        aggressive=$requested_aggressive;
    fi;
    if test "$aggressive" = 1; then
        _e266_gc_log "INFO|aggressive-pass|budget=${budget_kb}KiB|usage=${usage_kb}KiB|available=${available_kb}KiB";
        while IFS= read -r root; do
            keep=0;
            test "$root" != /var/backups/xray-e214 || keep=1;
            _e266_gc_root "$root" "$keep" "$allow_preserve" || rc=1;
        done < <(_e266_gc_roots);
    fi;
    sync 2> /dev/null || true;
    _e266_gc_log "END|deleted=$E266_GC_DELETED|protected=$E266_GC_PROTECTED|reclaimed=${E266_GC_RECLAIMED_KB}KiB|rc=$rc";
    info "E266手动清理完成：删除${E266_GC_DELETED}个无引用旧事务，保护${E266_GC_PROTECTED}个恢复点，目录体积约释放${E266_GC_RECLAIMED_KB}KiB。";
    test -z "$E266_GC_LOG_ACTIVE" || info "清理记录：$E266_GC_LOG_ACTIVE";
    test -z "$ref_index" || rm -f -- "$ref_index" 2> /dev/null || true;
    E266_GC_REFERENCE_INDEX="";
    E266_GC_LOG_ACTIVE="";
    test -z "$lock_fd" || exec {lock_fd}>&- 2> /dev/null || true;
    return "$rc"
}
# EEX3-FUNCTION release_e266 _e266_help
_e266_help() {
    printf '%s.sh — modular single-definition build; recovery ABI %s\n' "$EEX3_BUILD_ID" "$EEX3_ABI_VERSION";
