# EEX3-FUNCTION release_e266 _e266_mtu_runtime_verify
_e266_mtu_runtime_verify() {
    local b="${1:-}" iface="" expected="" actual="" rc=0;
    test ! -s "$b/e214-link-mtu.tsv" && return 0;
    while IFS='|' read -r iface expected; do
        test -n "$iface" || continue;
        _e214_mtu_iface_valid "$iface" && _e214_mtu_original_value_valid "$expected" || { 
            rc=1;
            continue
        };
        _e214_mtu_iface_candidate "$iface" || continue;
        ip link set dev "$iface" mtu "$expected" > /dev/null 2>&1 || { 
            rc=1;
            continue
        };
        actual=$(_e214_mtu_current "$iface" 2> /dev/null || true);
        test "$actual" = "$expected" || rc=1;
    done < "$b/e214-link-mtu.tsv";
    return "$rc"
