# EEX3-FUNCTION release_e266 _e266_network_lineage_status
_e266_network_lineage_status() {
    local snapshot="" record="" class="" origin="" digest="";
    title 'V199e266：E159 / E202 恢复引用链（只读）';
    if _e202_small_bbr_active; then
        snapshot=$(_e266_state_value_once "$E202_SMALL_STATE" restore_snapshot) || { 
            error 'E202处于活动状态，但restore_snapshot字段不可唯一读取。';
            return 1
        };
        echo "  E202退出快照: $snapshot";
        record=$(_e266_e202_snapshot_e159_lineage "$snapshot") || { 
            error 'E202退出快照中的网络所有权无法安全分类。';
            return 1
        };
        IFS='|' read -r class origin digest <<< "$record";
        case "$class" in 
            none)
                info 'E202退出快照不含完整网络所有者；无需E159基线。'
            ;;
            clean)
                info "E202退出快照内E159引用链完整：origin=$origin"
            ;;
            broken)
                error 'E202退出快照内E159内容可验证，但其初始基线已丢失或不干净。';
                echo "  丢失引用: $origin";
                echo "  封存状态SHA256: $digest";
                return 1
            ;;
            *)
                return 1
            ;;
        esac;
        return 0;
    fi;
    if _e204_network_owner_present; then
        origin=$(_e204_network_origin 2> /dev/null || true);
        if test -n "$origin" && _e204_network_origin_clean "$origin"; then
            info "当前E159所有者引用链完整：origin=$origin";
            return 0;
        fi;
        error '当前存在完整网络所有者，但初始基线不可验证或不干净。';
        return 1;
    fi;
    info '当前既无活动E202小BBR，也无E159完整网络所有者。'
}
