    local rc=0 package_rc=0 system_rc=0 mss_rc=0 exact="" parent="" plan="" expected="";
    local release_key=e266;
    test -n "$snapshot" && test -d "$snapshot" || return 1;
    case "$remark" in 
        0 | 1)

        ;;
        *)
            return 1
        ;;
    esac;
    parent=${snapshot%/system};
    if test -e "$parent/warp-packages.before" || test -L "$parent/warp-packages.before" || test -e "$parent/warp-packages.before.sha256" || test -L "$parent/warp-packages.before.sha256"; then
        _e242_warp_package_snapshot_validate "$parent/warp-packages.before" && _e204_warp_package_restore "$parent/warp-packages.before" || package_rc=1;
    fi;
    _e266_hot_restore_readback "$snapshot" || system_rc=1;
    if test -e "$snapshot/e242-mss-exact" || test -L "$snapshot/e242-mss-exact"; then
        exact="$snapshot/e242-mss-exact";
    else
        if test -e "$snapshot/e240-mss-exact" || test -L "$snapshot/e240-mss-exact"; then
            exact="$snapshot/e240-mss-exact";
        else
            if test -e "$snapshot/e238-mss-exact" || test -L "$snapshot/e238-mss-exact"; then
                exact="$snapshot/e238-mss-exact";
            else
                if test -e "$snapshot/e236-mss-exact" || test -L "$snapshot/e236-mss-exact"; then
                    exact="$snapshot/e236-mss-exact";
                else
                    if test -e "$snapshot/e234-mss-exact" || test -L "$snapshot/e234-mss-exact"; then
                        exact="$snapshot/e234-mss-exact";
                    else
                        if test -e "$snapshot/e232-mss-exact" || test -L "$snapshot/e232-mss-exact"; then
                            exact="$snapshot/e232-mss-exact";
                        else
                            if test -e "$snapshot/e230-mss-exact" || test -L "$snapshot/e230-mss-exact"; then
                                exact="$snapshot/e230-mss-exact";
                            else
                                if test -e "$snapshot/e228-mss-exact" || test -L "$snapshot/e228-mss-exact"; then
                                    exact="$snapshot/e228-mss-exact";
                                else
                                    if test -e "$snapshot/e226-mss-exact" || test -L "$snapshot/e226-mss-exact"; then
                                        exact="$snapshot/e226-mss-exact";
                                    fi;
                                fi;
                            fi;
                        fi;
                    fi;
                fi;
            fi;
        fi;
    fi;
    if test -n "$exact"; then
        if ! _e242_mss_outer_restore "$exact"; then
            plan=$(_e218_mss_owner_state_value "$exact/outer.env" plan 2> /dev/null || true);
            case "$plan" in 
                steady-on | repair-on)
                    expected=on
                ;;
                steady-off | repair-off)
                    expected=off
                ;;
                *)
                    expected=""
                ;;
            esac;
            if test -n "$expected"; then
                warn "MSS逐文件精确恢复未通过，按已密封逻辑意图=$expected 收敛并复检。";
                _e242_mss_converge_expected "$expected" || mss_rc=1;
            else
                mss_rc=1;
            fi;
        fi;
    fi;
    test "$system_rc" -eq 0 && test "$mss_rc" -eq 0 && test "$package_rc" -eq 0 || rc=1;
    if test "$package_rc" -ne 0; then
        warn 'WARP软件包集合未能逐包还原；即使配置恢复成功，也保留严重恢复标记，不宣称完整恢复。';
    fi;
    if test "$rc" -ne 0; then
        if test "$remark" = 1; then
            _e214_mark_critical "${release_key}-$operation" "$snapshot" "E266 rollback failed: system=$system_rc mss=$mss_rc packages=$package_rc" || true;
        fi;
        error "回滚子步骤：system/xray=$system_rc mss=$mss_rc warp-packages=$package_rc。";
        error "严重：${operation}回滚未完整通过；必须保留快照：$snapshot";
        return 1;
    fi;
    test "$package_rc" -eq 0 || info "${operation}主状态已恢复；WARP软件包差异不再阻塞下一次修复。";
    info "${operation}失败，已恢复操作前完整状态；快照：$snapshot"
}
