# EEX3-FUNCTION release_e266 _e266_runtime_headroom_guard
_e266_runtime_headroom_guard() {
    local stage="${1:-unknown}" available="" inode_free="";
    test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && return 0;
    available=$(df -Pk / 2> /dev/null | awk 'NR==2{print int($4)}');
    inode_free=$(df -Pi / 2> /dev/null | awk 'NR==2{print int($4)}');
    [[ "$available" =~ ^[0-9]+$ && "$inode_free" =~ ^[0-9]+$ ]] || return 1;
    if ((available >= 524288 && inode_free >= 2048)); then
        return 0;
    fi;
    error "阶段${stage}前空间保护中止：available=${available}KiB free_inodes=$inode_free。";
    error 'E266不会在安装/升级中自动清理；请在回滚完成后进入主菜单12并输入y。';
    return 1
}
# EEX3-FUNCTION release_e266 _e266_runtime_sysctl_reconcile
_e266_runtime_sysctl_reconcile() {
    local b="${1:-}" key="" expected="" actual="" proc="" pass=0 rc=0;
    test ! -s "$b/runtime-sysctl.env" && return 0;
    if grep -Fq 'net.ipv4.tcp_congestion_control|bbr' "$b/runtime-sysctl.env" 2> /dev/null; then
        modprobe tcp_bbr > /dev/null 2>&1 || true;
        modprobe sch_fq > /dev/null 2>&1 || true;
    fi;
    for pass in 1 2;
    do
        while IFS='|' read -r key expected; do
            test -n "$key" || continue;
            [[ "$key" =~ ^[A-Za-z0-9_.-]+$ ]] || return 1;
            proc="/proc/sys/${key//./\/}";
            if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E266_PROC_ROOT:-}"; then
                proc="${E266_PROC_ROOT%/}/${key//./\/}";
            fi;
            test -e "$proc" || continue;
            test -n "$expected" || continue;
            sysctl -w "$key=$expected" > /dev/null 2>&1 || true;
        done < "$b/runtime-sysctl.env";
    done;
    while IFS='|' read -r key expected; do
        test -n "$key" || continue;
        [[ "$key" =~ ^[A-Za-z0-9_.-]+$ ]] || return 1;
        proc="/proc/sys/${key//./\/}";
        if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E266_PROC_ROOT:-}"; then
            proc="${E266_PROC_ROOT%/}/${key//./\/}";
        fi;
        test -e "$proc" || continue;
        if test -z "$expected"; then
            error "回滚sysctl快照缺少当前受支持键的值：$key";
            rc=1;
            continue;
        fi;
        actual=$(sysctl -n "$key" 2> /dev/null || true);
        if declare -F _e159_value_equal > /dev/null 2>&1; then
            _e159_value_equal "$key" "$expected" "$actual" || { 
                error "回滚sysctl未收敛：$key expected=[$expected] actual=[$actual]";
                rc=1
            };
        else
            if test "$actual" != "$expected"; then
                error "回滚sysctl未收敛：$key expected=[$expected] actual=[$actual]";
                rc=1;
            fi;
        fi;
    done < "$b/runtime-sysctl.env";
    return "$rc"
}
