# EEX3-FUNCTION release_e266 _e266_service_state_apply
_e266_service_state_apply() {
    local unit="$1" row sources type remain ignored load enabled active;
    if test -n "${EEX5_RESTORE_SERVICE_PLAN:-}"; then
        row=$(awk -F'|' -v u="$unit" '$1==u{print; n++} END{if(n!=1)exit 1}' "$EEX5_RESTORE_SERVICE_PLAN") || { 
            _eex8_service_state_apply_base "$@";
            return $?
        };
        sources=${row##*|};
        case ",$sources," in 
            *,e8-optional-preserve,*)
                IFS='|' read -r ignored load enabled active sources <<< "$row";
                test "$unit" = vnstat.service && _e266_service_state_semantic_ok "$unit" "$load" "$enabled" "$active" || { 
                    error 'EEX8 vnstat 保留基线已变化；拒绝根据旧空字段修改当前服务。';
                    return 1
                };
                return 0
            ;;
        esac;
        case ",$sources," in 
            *,e8-sealed-oneshot,*)
                type=$(systemctl show "$unit" -p Type --value 2> /dev/null) || return 1;
                remain=$(systemctl show "$unit" -p RemainAfterExit --value 2> /dev/null) || return 1;
                test "$type:$remain" = oneshot:no || { 
                    error "EEX8已恢复服务类型与归档不符：$unit";
                    return 1
                }
            ;;
        esac;
    fi;
    _eex8_service_state_apply_base "$@"
}
# EEX3-FUNCTION release_e266 _e266_service_state_semantic_ok
_e266_service_state_semantic_ok() {
    local unit="$1" load="$2" enabled="$3" active="$4" now_load now_enabled now_active;
    now_load=$(systemctl show "$unit" -p LoadState --value 2> /dev/null || true);
    now_enabled=$(systemctl is-enabled "$unit" 2> /dev/null || true);
    now_active=$(systemctl is-active "$unit" 2> /dev/null || true);
    case "$now_load" in 
        loaded | not-found | masked)

        ;;
        *)
            return 1
        ;;
    esac;
    if test "$load" = not-found; then
        if test "$now_load" = not-found; then
            case "$now_enabled" in 
                '' | not-found | disabled)

                ;;
                *)
                    return 1
                ;;
            esac;
            case "$now_active" in 
                inactive | failed | unknown)
                    return 0
                ;;
                *)
                    return 1
                ;;
            esac;
        fi;
        test "$now_load:$now_enabled:$now_active" = loaded:disabled:inactive;
        return;
    fi;
    test -z "$load" || test "$load" = "$now_load" || return 1;
    test -n "$enabled" && test "$enabled" = "$now_enabled" || return 1;
    case "$active:$now_active" in 
        active:active | active:reloading | inactive:inactive | inactive:failed)
            return 0
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION release_e266 _e266_snapshot_archive_dedupe
_e266_snapshot_archive_dedupe() {
    local target_dir="${1:-}" target="" target_real="" target_hash="";
    local target_size="" target_dev="" root="" root_real="" allowed=0;
    local candidate="" candidate_real="" candidate_size="" candidate_dev="";
    local candidate_hash="" candidate_claim="" candidate_dir="";
    local link_dir="" tmp="" method="" saved_kb=0;
    test -d "$target_dir" && test ! -L "$target_dir" || return 1;
    target="$target_dir/files.tar";
    test -f "$target" && test ! -L "$target" || return 1;
    test -s "$target" || return 0;
    target_real=$(readlink -f -- "$target" 2> /dev/null || true);
    test -n "$target_real" || return 1;
    while IFS= read -r root; do
        test -d "$root" && test ! -L "$root" || continue;
        root_real=$(readlink -f -- "$root" 2> /dev/null || true);
        test -n "$root_real" || continue;
        case "$target_real" in 
            "$root_real"/*)
                allowed=1;
                break
            ;;
        esac;
    done < <(_e266_gc_roots);
    test "$allowed" -eq 1 || return 0;
    target_hash=$(awk 'NF>=2 && $1 ~ /^[0-9a-f]{64}$/ \
      && $2 ~ /(^|\/)files[.]tar$/ {print $1; exit}' "$target_dir/archive.sha256" 2> /dev/null || true);
    test -n "$target_hash" || target_hash=$(sha256sum "$target" 2> /dev/null | awk 'NR==1{print $1}');
    target_size=$(stat -c %s -- "$target" 2> /dev/null || true);
    target_dev=$(stat -c %d -- "$target" 2> /dev/null || true);
    [[ "$target_hash" =~ ^[0-9a-f]{64}$ && "$target_size" =~ ^[0-9]+$ && "$target_dev" =~ ^[0-9]+$ ]] || return 1;
    while IFS= read -r root; do
        test -d "$root" && test ! -L "$root" || continue;
        while IFS= read -r candidate; do
            test -f "$candidate" && test ! -L "$candidate" || continue;
            candidate_real=$(readlink -f -- "$candidate" 2> /dev/null || true);
            test -n "$candidate_real" && test "$candidate_real" != "$target_real" || continue;
            candidate_size=$(stat -c %s -- "$candidate" 2> /dev/null || true);
            candidate_dev=$(stat -c %d -- "$candidate" 2> /dev/null || true);
            test "$candidate_size" = "$target_size" && test "$candidate_dev" = "$target_dev" || continue;
            candidate_dir=$(dirname -- "$candidate") || continue;
            candidate_claim=$(awk 'NF>=2 && $1 ~ /^[0-9a-f]{64}$/ \
              && $2 ~ /(^|\/)files[.]tar$/ {print $1; exit}' "$candidate_dir/archive.sha256" 2> /dev/null || true);
            test "$candidate_claim" = "$target_hash" || continue;
            candidate_hash=$(sha256sum "$candidate" 2> /dev/null | awk 'NR==1{print $1}');
            test "$candidate_hash" = "$target_hash" || continue;
            link_dir=$(mktemp -d --tmpdir="$target_dir" .e266-archive-reuse.XXXXXX 2> /dev/null || true);
            test -n "$link_dir" || return 1;
            chmod 0700 "$link_dir" 2> /dev/null || true;
            tmp="$link_dir/files.tar";
            method="";
            if cp --reflink=always --preserve=mode,ownership,timestamps -- "$candidate" "$tmp" 2> /dev/null; then
                method=reflink;
            else
                if ln -- "$candidate" "$tmp" 2> /dev/null; then
                    method=hardlink;
                fi;
            fi;
            if test -n "$method" && test "$(sha256sum "$tmp" 2> /dev/null | awk 'NR==1{print $1}')" = "$target_hash" && mv -f -- "$tmp" "$target"; then
                rmdir -- "$link_dir" 2> /dev/null || true;
                chmod 0400 "$target" 2> /dev/null || true;
                saved_kb=$(((target_size + 1023) / 1024));
                { 
                    printf 'version=199e266\n';
                    printf 'method=%s\n' "$method";
                    printf 'sha256=%s\n' "$target_hash";
                    printf 'logical_saved_kb=%s\n' "$saved_kb"
                } > "$target_dir/archive-reuse.env" || return 1;
                chmod 0600 "$target_dir/archive-reuse.env" 2> /dev/null || true;
                info "E266复用相同快照归档：method=$method logical_saved=${saved_kb}KiB。";
                return 0;
            fi;
            rm -f -- "$tmp" 2> /dev/null || true;
            rmdir -- "$link_dir" 2> /dev/null || true;
        done < <(find "$root" -xdev -mindepth 2 -maxdepth 4 -type f -name files.tar -print 2> /dev/null);
    done < <(_e266_gc_roots);
    return 0
}
# EEX3-FUNCTION release_e266 _e266_snapshot_authority_verify
_e266_snapshot_authority_verify() {
