        exec {verbose_fd}< <(LC_ALL=C _eex3_scoped_tar -tvf "$b/files.tar" --numeric-owner --full-time --quoting-style=literal);
        while IFS= read -r raw <&"$name_fd"; do
            IFS= read -r verbose <&"$verbose_fd" || return 1;
            test -n "$raw" || continue;
            type=${verbose:0:1};
            rel=${raw#./};
            rel=${rel%/};
            _e138_safe_restore_rel "$rel" || return 1;
            if _eex3_ssh_control_preserved && _eex3_ssh_path_protected "$rel"; then
                continue;
            fi;
            dst="/$rel";
            case "$type" in 
                d)
                    test -d "$dst" && test ! -L "$dst" || return 1
                ;;
                l)
                    marker="$raw -> ";
                    target=${verbose#*"$marker"};
                    test "$target" != "$verbose" && test -L "$dst" && test "$(readlink -- "$dst")" = "$target" || return 1
                ;;
                h)
