                    test "$target" != "$verbose" && _e138_safe_restore_rel "$target" && test -e "$dst" && test -e "/$target" && test "$(stat -c '%d:%i' "$dst" 2> /dev/null || true)" = "$(stat -c '%d:%i' "/$target" 2> /dev/null || true)" || return 1
                ;;
