                ;;
                *)
                    test -e "$dst" || test -L "$dst" || return 1
                ;;
            esac;
        done;
        IFS= read -r verbose <&"$verbose_fd" && return 1 || true;
        exec {name_fd}>&-;
        exec {verbose_fd}>&-;
    fi;
    while IFS= read -r rel; do
        test -n "$rel" || continue;
        rel=${rel#./};
        rel=${rel%/};
        _e138_safe_restore_rel "$rel" || return 1;
        if _eex3_ssh_control_preserved && _eex3_ssh_path_protected "$rel"; then
            continue;
        fi;
        test -e "/$rel" || test -L "/$rel" || return 1;
    done < "$b/present.list";
    while IFS= read -r rel; do
        test -n "$rel" || continue;
        _e138_safe_restore_rel "$rel" || return 1;
        if _eex3_ssh_control_preserved && _eex3_ssh_path_protected "$rel"; then
            continue;
        fi;
        if _eex3_ssh_control_preserved && _eex3_ssh_path_ancestor "$rel"; then
            continue;
        fi;
        test ! -e "/$rel" && test ! -L "/$rel" || return 1;
    done < "$b/absent.list"
}
# EEX3-FUNCTION release_e266 _e266_snapshot_estimate_kb
_e266_snapshot_estimate_kb() {
    local d="" rel="" size="" total=0;
    d=$(mktemp -d /run/xray-e266-headroom.XXXXXX 2> /dev/null || true);
    test -n "$d" || d=$(mktemp -d /tmp/xray-e266-headroom.XXXXXX 2> /dev/null || true);
