        rm -rf -- "$d" 2> /dev/null || true;
        return 1;
    fi;
    while IFS= read -r rel; do
        test -n "$rel" || continue;
        size=$(du -skx -- "/$rel" 2> /dev/null | awk 'NR==1{print int($1)}');
