# EEX3-FUNCTION release_e266 _e266_snapshot_manifest_build
_e266_snapshot_manifest_build() {
    local b="${1:-}" present="${2:-}" absent="${3:-}";
    local all="" sorted="" p="" rel="" root="" covered=0;
    local -a selected=();
    test -n "$b" && test -n "$present" && test -n "$absent" || return 1;
    all="$b/.e266-paths-all.${BASHPID:-$$}";
    sorted="$b/.e266-paths-sorted.${BASHPID:-$$}";
    : > "$present" && : > "$absent" || return 1;
    _e138_system_paths | awk 'NF&&!seen[$0]++' > "$all" || return 1;
    awk '{printf "%012d\t%s\n",length($0),$0}' "$all" | LC_ALL=C sort -n -k1,1 -k2,2 > "$sorted" || return 1;
    while IFS='	' read -r _ p; do
        test -n "$p" || continue;
        case "$p" in 
            /*)

            ;;
            *)
                rm -f -- "$all" "$sorted";
                return 1
            ;;
        esac;
        [[ "$p" != *$'\n'* && "$p" != *$'\r'* && "$p" != *'	'* ]] || { 
            rm -f -- "$all" "$sorted";
            return 1
        };
