            return 1
        };
        if test -e "$p" || test -L "$p"; then
            covered=0;
            for root in "${selected[@]}";
            do
                if [[ "$p" == "$root"/* ]] && test -d "$root" && test ! -L "$root"; then
                    covered=1;
                    break;
                fi;
            done;
            if test "$covered" -eq 0; then
                printf '%s\n' "$rel" >> "$present" || return 1;
                selected+=("$p");
            fi;
        else
            printf '%s\n' "$rel" >> "$absent" || return 1;
        fi;
    done < "$sorted";
    rm -f -- "$all" "$sorted"
}
# EEX3-FUNCTION release_e266 _e266_ssh_listener_assess
_e266_ssh_listener_assess() {
    local configured="${1:-}" listening="${2:-}" current="${3:-}";
    local p="" matched=0 stale="";
    test -n "$listening" || return 1;
    for p in $listening;
    do
        [[ "$p" =~ ^[0-9]+$ ]] && ((p >= 1 && p <= 65535)) || return 1;
    done;
    if test -n "$current"; then
        [[ "$current" =~ ^[0-9]+$ ]] && ((current >= 1 && current <= 65535)) || return 1;
        grep -Fxq "$current" <<< "$listening" || return 1;
        matched=1;
    fi;
    for p in $configured;
    do
        [[ "$p" =~ ^[0-9]+$ ]] && ((p >= 1 && p <= 65535)) || return 1;
        if grep -Fxq "$p" <<< "$listening"; then
            matched=1;
        else
            stale="${stale}${stale:+,}$p";
        fi;
    done;
    test "$matched" -eq 1 || return 1;
    printf '%s\n' "$stale"
}
