            is-enabled)
                printf 'disabled\n';
                return 1
            ;;
            is-active)
                printf 'inactive\n';
                return 3
            ;;
            show)
                printf 'not-found\n';
                return 0
            ;;
            *)
                return 0
            ;;
        esac
    };
    _e138_system_snapshot "$b" || return 1;
    printf 'changed\n' > "$live/state.conf";
    printf 'must-disappear\n' > "$missing";
    _e138_system_restore "$b" || rc=1;
    grep -qx before "$live/state.conf" || rc=1;
    test ! -e "$missing" && test ! -L "$missing" || rc=1;
    _e266_snapshot_authority_verify "$b" || rc=1;
    test -z "$(find "$b" -maxdepth 1 -type d \( -name '.restore-stage.*' -o -name '.e266-authority.*' \) -print -quit)" || rc=1;
    return "$rc" )
}
