# EEX3-FUNCTION release_e266 _e266_sysctl_retry_mock_self_test
_e266_sysctl_retry_mock_self_test() {
    ( local d="" b="" stored=old writes=0 rc=0;
    d=$(mktemp -d /tmp/xray-e266-sysctl-test.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    b="$d/backup";
    mkdir -p "$b" "$d/proc/test" || return 1;
    : > "$d/proc/test/key";
    printf 'test.key|desired\n' > "$b/runtime-sysctl.env";
    E242_INTERNAL_SELF_TEST=1;
    E266_PROC_ROOT="$d/proc";
    function sysctl () 
    { 
        case "${1:-}" in 
            -w)
                writes=$((writes + 1));
                test "$writes" -lt 2 || stored=${2#*=};
                return 0
            ;;
            -n)
                printf '%s\n' "$stored"
            ;;
            *)
                return 1
            ;;
        esac
    };
    function _e159_value_equal () 
    { 
        test "${2:-}" = "${3:-}"
    };
    _e266_runtime_sysctl_reconcile "$b" > /dev/null 2>&1 || rc=1;
    test "$writes" -eq 2 && test "$stored" = desired || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION release_e266 _e266_xray_recovery_gate
_e266_xray_recovery_gate() {
    local b="${1:-}" expected_active="" expected_enabled="" expected_load="" now="";
    if test -s "$b/e204-services.env"; then
        IFS='|' read -r _ expected_load expected_enabled expected_active < <(awk -F'|' '$1=="xray.service"{print;exit}' "$b/e204-services.env");
    else
        if test -s "$b/services.env"; then
            IFS='|' read -r _ expected_enabled expected_active < <(awk -F'|' '$1=="xray.service"{print;exit}' "$b/services.env");
        fi;
    fi;
    test -n "$expected_active" && test -n "$expected_enabled" || return 1;
    if test -s "$CONFIG"; then
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1 || return 1;
        _e118_xray_test_config "$CONFIG" 1 || return 1;
        _e242_reality_cache_reconcile || return 1;
    fi;
    case "$expected_enabled" in 
        enabled | enabled-runtime | linked | linked-runtime)
            now=$(systemctl is-enabled xray.service 2> /dev/null || true);
            case "$now" in 
                enabled | enabled-runtime | linked | linked-runtime)

                ;;
                *)
                    return 1
                ;;
            esac
        ;;
        masked | masked-runtime)
            now=$(systemctl is-enabled xray.service 2> /dev/null || true);
            case "$now" in 
                masked | masked-runtime)

                ;;
                *)
                    return 1
                ;;
            esac
        ;;
        *)
            now=$(systemctl is-enabled xray.service 2> /dev/null || true);
            case "$now" in 
                enabled | enabled-runtime | linked | linked-runtime | masked | masked-runtime)
                    return 1
                ;;
            esac
        ;;
    esac;
    case "$expected_active" in 
        active | activating | reloading)
            systemctl restart xray.service > /dev/null 2>&1 || return 1;
            systemctl is-active --quiet xray.service 2> /dev/null && _e127_verify_xray_runtime "$CONFIG" 12 || return 1
        ;;
        *)
            systemctl is-active --quiet xray.service 2> /dev/null && return 1 || true
        ;;
    esac
}
# EEX3-FUNCTION release_e266 _eex3_app_config_apply
_eex3_app_config_apply() {
    local value="${EEX3_BUFFER_INTENT:-}" candidate backup;
    test -n "$value" || value=$(_e266_buffer_upgrade_intent_readonly) || return 1;
    _e266_buffer_value_valid "$value" || return 1;
    if _eex3_app_config_verify "$CONFIG" && _eex3_buffer_levels_match "$CONFIG" "$value"; then
        _e118_xray_test_config "$CONFIG" 1;
        return;
    fi;
    candidate=$(_e118_mktemp eex6-item28.json) || return 1;
    _eex6_app_candidate "$CONFIG" "$candidate" "$value" || return 1;
    _e118_xray_test_config "$candidate" 1 || return 1;
    backup=$(_e116_backup_state before_item28_eex6) || return 1;
    _e118_commit_config "$candidate" "$backup" preserve || return 1;
    _eex3_app_config_verify "$CONFIG" && _eex3_buffer_levels_match "$CONFIG" "$value"
}
# EEX3-FUNCTION release_e266 _eex3_app_config_jq
_eex3_app_config_jq() {
    printf '%s\n' '
      .log=(.log//{}) | .log.loglevel="warning" |
      .dns=(.dns//{}) | .dns.queryStrategy="UseIPv4" |
      .policy=(.policy//{}) | .policy.levels=(.policy.levels//{}) |
      .policy.levels["0"]=(.policy.levels["0"]//{}) + {handshake:5,connIdle:260,uplinkOnly:2,downlinkOnly:5,bufferSize:$b} |
      (.inbounds[]? | select(.protocol=="vless" and .streamSettings.security=="reality")) |=
        (.sniffing=(.sniffing//{}) | .sniffing.enabled=true | .sniffing.metadataOnly=true |
         .sniffing.routeOnly=true | .streamSettings.realitySettings.maxTimeDiff=60000)
    '
}
# EEX3-FUNCTION release_e266 _eex3_app_config_verify
_eex3_app_config_verify() {
    local cfg="${1:-$CONFIG}";
    jq -e '
      .policy.levels["0"] as $p |
      $p.handshake==5 and $p.connIdle==260 and $p.uplinkOnly==2 and $p.downlinkOnly==5
      and .dns.queryStrategy=="UseIPv4"
      and .log.loglevel=="warning"
      and ([.inbounds[]? | select(.protocol=="vless" and .streamSettings.security=="reality") |
          (.sniffing.enabled==true and .sniffing.metadataOnly==true and .sniffing.routeOnly==true
           and .streamSettings.realitySettings.maxTimeDiff==60000)] | all)
    ' "$cfg" > /dev/null 2>&1
}
# EEX3-FUNCTION release_e266 _eex3_apply_item28_components
_eex3_apply_item28_components() {
    local EEX7_UNIT_PREPARE_ONLY=1 was_active value="${EEX3_BUFFER_INTENT:-}" candidate backup;
    was_active=$(_e266_buffer_service_activity) || return 1;
    test -n "$value" || value=$(_e266_buffer_managed_intent_readonly 2> /dev/null || true);
    test -n "$value" || value=$(_eex7_default_buffer);
    candidate=$(_e118_mktemp eex7-item28) || return 1;
    _eex6_app_candidate "$CONFIG" "$candidate" "$value" || return 1;
    _e118_xray_test_config "$candidate" 1 || return 1;
    backup=$(_e116_backup_state before_item28_eex7) || return 1;
    _eex6_step item28-xray-unit fix_xray_systemd_limits || return $?;
    _eex6_step item28-host-policy _e159_install_host_safe all || return $?;
    _eex6_step item28-log-retention _e121_install_log_retention || return $?;
    _eex6_step item28-buffer-environment _e266_buffer_dropin_install "$E266_BUFFER_DROPIN" || return $?;
    systemctl daemon-reload || return 1;
    _eex6_step item28-config _e118_commit_config "$candidate" "$backup" preserve || return $?;
    _eex6_step item28-final-readback _eex3_item28_components_verify
}
# EEX3-FUNCTION release_e266 _eex3_architecture_audit
_eex3_architecture_audit() {
    local total unique duplicate_names top_level_overrides dispatchers rc=0;
    total=$(awk '$1=="#" && $2=="EEX3-FUNCTION"{n++} END{print n+0}' "$(_eex6_release_source)");
    unique=$(awk '$1=="#" && $2=="EEX3-FUNCTION"{print $4}' "$(_eex6_release_source)" | LC_ALL=C sort -u | wc -l | tr -d ' ');
    duplicate_names=$((total - unique));
    top_level_overrides=$(grep -Ec '^eval[[:space:]].*declare -f' "$(_eex6_release_source)" 2> /dev/null || true);
    dispatchers=$(grep -c '^# EEX3 SINGLE FINAL DISPATCHER$' "$(_eex6_release_source)" 2> /dev/null || true);
    test "$total" -eq "$EEX3_FUNCTION_COUNT" || rc=1;
    test "$duplicate_names" -eq 0 || rc=1;
    test "$top_level_overrides" -eq 0 || rc=1;
    test "$dispatchers" -eq 1 || rc=1;
    _eex3_module_audit > /dev/null || rc=1;
    printf '%s architecture audit:\n' "${EEX3_BUILD_ID^^}";
    printf '  modules=%s functions=%s unique=%s duplicate_names=%s\n' "${#EEX3_MODULES[@]}" "$total" "$unique" "$duplicate_names";
    printf '  top_level_declare_f_overrides=%s final_dispatchers=%s\n' "$top_level_overrides" "$dispatchers";
    if test "$rc" -eq 0; then
        printf '%s architecture audit: PASS\n' "${EEX3_BUILD_ID^^}";
    else
        printf '%s architecture audit: FAIL\n' "${EEX3_BUILD_ID^^}" 1>&2;
    fi;
    return "$rc"
}
