        return 0
    };
    function _eex5_active_snapshot_preflight () 
    { 
        return 0
    };
    _eex5_auto_fault_legacy_test )
}
# EEX3-FUNCTION release_e266 _eex3_auto_transaction
_eex3_auto_transaction() {
    ( local reboot_after="${1:-0}" owner="" old_version="" tx="" profile="" pending="" independent="";
    local had_small=0 rc=0 finished=0 restore_rc=0 workflow=full28 snapshot_ready=0;
    local auto_lock_fd="" mss_plan="" mss_expected="" recovery="" recovery_tx="";
    local warp_plan="" buffer_intent="" current_stage=initializing failed_stage="" failed_rc=0 stage_seq=0;
    local E266_AUTO_UPGRADE_ACTIVE=1 E266_LINEAGE_REBASE_DIR="";
    local E266_LINEAGE_RESCUE_TX="";
    local auto_log="$E242_AUTO_LOG";
    local lock_path="$E214_TX_ROOT/.e266-auto-upgrade.lock";
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1; then
        lock_path="${E242_AUTO_LOCK_PATH:-$lock_path}";
        auto_log="${E242_AUTO_LOG_PATH:-$auto_log}";
    fi;
    local EEX6_TRACE_LOG="$auto_log";
    function _e242_auto_log_event () 
    { 
        local event="${1:-}" stage="${2:-}" code="${3:-0}" label="${4:-}";
        [[ "$event" =~ ^(BEGIN|OK|FAIL|INFO)$ && "$stage" =~ ^[a-z0-9][a-z0-9-]{0,63}$ && "$code" =~ ^[0-9]{1,3}$ ]] || return 1;
        label=${label//$'\r'/ };
        label=${label//$'\n'/ };
        label=${label//|/ };
        label=${label:0:180};
        printf 'time=%s|event=%s|stage=%s|rc=%s|label=%s\n' "$(date -Is 2> /dev/null || date)" "$event" "$stage" "$code" "$label" >> "$auto_log"
    };
    function _e242_auto_mark_failure () 
    { 
        local stage="${1:-unknown}" label="${2:-未说明}" code="${3:-1}";
        [[ "$code" =~ ^[1-9][0-9]{0,2}$ ]] && ((code <= 255)) || code=1;
        current_stage="$stage";
        failed_stage="$stage";
        failed_rc="$code";
        _e242_auto_log_event FAIL "$stage" "$code" "$label" || true;
        error "E266阶段失败：$stage（$label），rc=$code。";
        error "E266阶段日志：$auto_log";
        return "$code"
    };
    function _e242_auto_stage () 
    { 
        local stage="${1:-}" label="${2:-}" step_rc=0;
        shift 2 || return 1;
        current_stage="$stage";
        stage_seq=$((stage_seq + 1));
        _e266_runtime_headroom_guard "$stage" || { 
            _e242_auto_mark_failure "$stage" '阶段开始前空间保护门禁未通过' 1;
            return 1
        };
        info "E266事务阶段[$stage_seq]：$label";
        _e242_auto_log_event BEGIN "$stage" 0 "$label" || { 
            _e242_auto_mark_failure stage-log-write '无法写入阶段BEGIN记录' 1;
            return 1
        };
        if "$@"; then
            _e242_auto_log_event OK "$stage" 0 "$label" || { 
                _e242_auto_mark_failure stage-log-write '无法写入阶段OK记录' 1;
                return 1
            };
            return 0;
        else
            step_rc=$?;
        fi;
        _e242_auto_mark_failure "$stage" "$label" "$step_rc"
    };
    function _e242_assert_no_active_small () 
    { 
        local live="";
        live=$(_e242_active_small_owner 2> /dev/null || true);
        test -z "$live" || { 
            error "旧小BBR退出后仍检测到活动所有者：$live";
            return 1
        }
    };
    function _e242_auto_exit_guard () 
    { 
        local status="${1:-1}" guard_restore_rc=0;
        trap - EXIT HUP INT TERM;
        rm -f -- "${profile:-}" "${pending:-}" 2> /dev/null || true;
        if test "$snapshot_ready" -eq 1 && test "$finished" -eq 0 && test -n "$tx"; then
            error "E266自动升级在阶段${current_stage:-unknown}意外退出，执行升级起点总回滚。";
            _e242_auto_log_event FAIL "${current_stage:-unexpected}" "$status" 'shell意外退出或收到信号' || true;
            _e242_restore_outer "$tx/system" auto-upgrade-unexpected || guard_restore_rc=1;
            _e214_tx_close "$tx" || true;
            test "$status" -ne 0 || status=1;
            test "$guard_restore_rc" -eq 0 || status=1;
        else
            if test "$finished" -eq 0 && test -n "$tx"; then
                _e214_tx_close "$tx" || true;
            fi;
        fi;
        [[ "$status" =~ ^[0-9]+$ ]] || status=1;
        exit "$status"
    };
    trap '_e242_auto_exit_guard $?' EXIT;
    trap 'exit 129' HUP;
    trap 'exit 130' INT;
    trap 'exit 143' TERM;
    test "$EUID" -eq 0 || { 
        error 'E266自动升级必须使用root。';
        return 1
    };
    _e266_release_binding_gate || { 
        error 'E266最终发布绑定门禁失败；未进入恢复、快照或网络写入阶段。';
        return 1
    };
    _e118_runtime_init || return 1;
    trap 'exit 129' HUP;
    trap 'exit 130' INT;
    trap 'exit 143' TERM;
    _e266_buffer_recover_pending || { 
        error 'E266阶段失败：recover-pending-buffer（尚未创建升级事务或修改网络）。';
        return 1
    };
    _e266_runtime_headroom_guard recover-previous-auto || { 
        error 'E266阶段失败：recovery-headroom（尚未恢复或创建新事务）。';
