    old_version=$(_e242_installed_version 2> /dev/null || true);
    _e242_auto_preflight "$owner" "$old_version" || return 1;
    buffer_intent=${EEX3_BUFFER_INTENT:-768} || return 1;
    EEX3_BUFFER_INTENT="$buffer_intent";
    EEX3_XRAY_ACTIVITY=$(_e266_buffer_service_activity) || return 1;
    mss_plan=$(_e242_mss_plan_readonly) || return 1;
    if test "$mss_plan" = recover; then
