        _e242_mss_recover_force "$recovery_tx" || return 1;
        _e214_critical_preflight || return 1;
        mss_plan=$(_e242_mss_plan_readonly) || return 1;
        test "$mss_plan" != recover || return 1;
    fi;
    mss_expected=$(_e242_mss_expected_from_plan "$mss_plan") || return 1;
