    test "$rc" -ne 0 || _e242_auto_stage mss-outer-snapshot '密封MSS控制文件、服务与可读规则后端' _e242_mss_outer_capture "$tx/system" "$mss_plan" || rc=$?;
    independent="$tx/e242-independent";
    test "$rc" -ne 0 || _e242_auto_stage independent-state-snapshot '密封Xray、节点、Reality、WARP与IPv6独立状态' _e242_independent_state_capture "$independent" || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage baseline-readback '读回升级起点与节点语义身份' _e242_stage_state_record "$tx" baseline-sealed "$independent" ignore || rc=$?;
