                pending=$(mktemp /tmp/xray-e242-pending-profile.XXXXXX) || { 
                    _e242_auto_mark_failure pending-profile-temp '无法创建小BBR保存档迁移临时文件' 1;
                    rc=1
                };
                test "$rc" -ne 0 || _e242_auto_stage pending-profile-copy '密封活动档对应的有效保存档' cp -f -- "$E202_SMALL_PROFILE" "$pending" || rc=$?;
            fi;
            test "$rc" -ne 0 || _e242_auto_stage legacy-small-exit '调用已固定旧脚本安全退出旧小BBR' _e242_old_small_bbr_disable "$owner" "$old_version" || rc=$?;
            test "$rc" -ne 0 || _e242_auto_stage legacy-small-exit-readback '确认旧小BBR活动所有权已清空' _e242_assert_no_active_small || rc=$?;
        else
