        fi;
    fi;
    test "$rc" -ne 0 || _e242_auto_stage independent-state-restore '旧网络基线后恢复Xray、节点、WARP与IPv6独立状态' _e242_independent_state_restore "$independent" || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage mss-intent-converge "旧网络基线后收敛MSS原意图=$mss_expected" _e242_mss_converge_expected "$mss_expected" || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage legacy-baseline-readback '读回旧小BBR退出后的完整独立状态' _e242_stage_state_record "$tx" legacy-baseline-restored "$independent" ignore || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage hot-update-preflight '执行热更新写入前门禁' _e214_hot_update_preflight || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage hot-update '事务更新脚本与基础策略，SSH控制面保持不变' _e214_hot_update || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage pbk-cache-after-hot '按Reality privateKey收敛PBK兼容缓存' _e242_reality_cache_reconcile || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage hot-update-readback '读回热更新后的节点身份与PBK缓存' _e242_stage_state_record "$tx" hot-update "$independent" required || rc=$?;
    if test "$rc" -eq 0; then
