        test "$rc" -ne 0 || _e242_auto_stage small-bbr-enable '启用固定3F2并执行真实开机路径' _eex3_small_target_apply "$profile" || rc=$?;
        if test "$rc" -eq 0 && test "$had_small" = 1 && test -n "$pending"; then
            _e242_auto_stage pending-profile-retained-in-backup '原待应用档仅保存在回滚快照' true || rc=$?;
        fi;
    fi;
    if test "$rc" -eq 0; then
        if _e140_full_mode_active; then
            workflow=app-only-host-full;
            warn '检测到Cloudflare系统全隧道：保留其ip_forward/路由所有权，只重放第28项应用层，不写入互斥的完整网络档。';
            _e242_auto_stage micro28-host-full '系统全隧道下仅重放第28项应用层' _e242_post_config_reconcile || rc=$?;
            test "$rc" -ne 0 || _e242_auto_stage workflow-state-write '提交app-only-host-full工作流状态' _e242_write_workflow_state "$workflow" || rc=$?;
        else
            _e242_auto_stage micro28 '应用第28项应用和主机优化（网络由3F2统一管理）' _e159_apply_micro_28 || rc=$?;
        fi;
    fi;
    test "$rc" -ne 0 || _e242_auto_stage buffer-reconcile "应用当前发布目标Xray bufferSize=${buffer_intent:-unmanaged}KB并持久化" _e266_buffer_upgrade_reconcile "$buffer_intent" || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage pbk-cache-after-micro28 '第28项后再次按privateKey收敛PBK缓存' _e242_reality_cache_reconcile || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage micro28-readback '读回第28项后的节点身份、PBK与网络意图' _e242_stage_state_record "$tx" micro28 "$independent" required || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage small-bbr-readback '读回小BBR后的节点与独立网络状态' _e242_stage_state_record "$tx" small-bbr "$independent" required || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage mtu1350 '在一键外层事务内强制默认出口MTU=1350（无二次确认）' _e242_mtu_set_1350_outer "$tx" || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage mtu1350-readback '读回MTU=1350及全部独立状态' _e242_stage_state_record "$tx" mtu1350 "$independent" required || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage buffer-final-readback '最终读回当前发布目标bufferSize' _e266_buffer_upgrade_verify "$buffer_intent" || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage workflow-commit "登记当前发布最终目标" _eex3_workflow_commit || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage final-gates '执行小BBR、MTU、MSS、IPv6、WARP、Xray最终门禁' _e242_auto_verify "$profile" "$mss_expected" "$independent" || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage lineage-finalize "验证并闭合无E159依赖的新恢复链" _e266_lineage_rebase_finalize || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage final-state-seal '密封最终无凭据审计记录' _e242_stage_state_record "$tx" final "$independent" required || rc=$?;
    test "$rc" -ne 0 || _e242_auto_stage success-baseline-index '登记最近一次成功升级的唯一外层回滚基线' _e266_mark_last_success "$tx" || rc=$?;
    if test "$rc" -ne 0; then
        error "E266一键升级未完整通过：失败阶段=${failed_stage:-unknown} rc=${failed_rc:-$rc}。";
        error '正在恢复升级开始前的脚本、网络、Xray与所有独立状态。';
        _e242_auto_log_event INFO rollback 0 '开始恢复升级起点快照' || true;
        _e242_restore_outer "$tx/system" auto-upgrade || restore_rc=1;
        if test "$restore_rc" -eq 0; then
            _e242_auto_log_event OK rollback 0 '升级起点完整状态已恢复' || true;
        else
            _e242_auto_log_event FAIL rollback 1 '升级起点恢复未完整通过' || true;
            error "E266回滚门禁未完整通过；必须保留事务快照：$tx/system";
        fi;
        finished=1;
        _e214_tx_close "$tx" || true;
        rm -f -- "${profile:-}" "${pending:-}" 2> /dev/null || true;
        trap - EXIT HUP INT TERM;
        return 1;
    fi;
    _e242_auto_log_event OK committed 0 'E266一键升级全部门禁通过' || warn "升级已通过但最终日志记录失败：$auto_log";
    finished=1;
    _e214_tx_close "$tx" || warn "自动升级已通过，但事务活动标记未关闭：$tx";
    rm -f -- "${profile:-}" "${pending:-}" 2> /dev/null || true;
    trap - EXIT HUP INT TERM;
