        [.inbounds[]? | (.settings.clients[]?.level // 0), (.settings.userLevel // 0)]) | unique as $levels |
      if all($levels[]; type=="number" and floor==. and .>=0 and .<=4294967295) then $levels else error("invalid user level") end
    '
}
