# EEX3-FUNCTION release_e266 _eex3_buffer_readback_abi
_eex3_buffer_readback_abi() {
    local expected="${1:-}" expected_active="${2:-}" config="${3:-$CONFIG}";
    local dropin="${4:-$E266_BUFFER_DROPIN}" state="${5:-$E266_BUFFER_STATE}";
    local proc_root="${6:-/proc}" log="${7:-$E266_BUFFER_LOG}";
    local actual="" load="" active="" pid="" state_value="";
    _e266_buffer_value_valid "$expected" && [[ "$expected_active" =~ ^[01]$ ]] || { 
        _e266_buffer_fail "$log" readback-arguments '期望值或服务状态参数无效' 1;
        return 1
    };
    actual=$(_e266_buffer_config_value "$config" 2> /dev/null || true);
    test "$actual" = "$expected" || { 
        _e266_buffer_fail "$log" readback-json "JSON=$actual expected=$expected" 1;
        return 1
    };
    _e266_buffer_xray_test "$config" || { 
        _e266_buffer_fail "$log" readback-config-test 'Xray配置测试未通过' 1;
        return 1
    };
    _e266_buffer_dropin_exact "$dropin" || { 
        _e266_buffer_fail "$log" readback-dropin 'systemd环境屏蔽drop-in不是精确受管内容' 1;
        return 1
    };
    _e266_buffer_systemctl daemon-reload > /dev/null 2>&1 || { 
        _e266_buffer_fail "$log" readback-daemon-reload 'systemd daemon-reload失败' 1;
        return 1
    };
    load=$(_e266_buffer_systemctl show xray.service -p LoadState --value 2> /dev/null || true);
    test "$load" = loaded || { 
        _e266_buffer_fail "$log" readback-load-state "LoadState=${load:-empty}" 1;
        return 1
    };
    active=$(_e266_buffer_systemctl show xray.service -p ActiveState --value 2> /dev/null || true);
    if test "$expected_active" = 1; then
        test "$active" = active || { 
            _e266_buffer_fail "$log" readback-active-state "重启后ActiveState=${active:-empty}" 1;
            return 1
        };
        pid=$(_e266_buffer_systemctl show xray.service -p MainPID --value 2> /dev/null || true);
        [[ "$pid" =~ ^[1-9][0-9]*$ ]] || { 
            _e266_buffer_fail "$log" readback-mainpid "MainPID=${pid:-empty}" 1;
            return 1
        };
        _e266_buffer_process_env_clean "$pid" "$proc_root" || { 
            _e266_buffer_fail "$log" readback-process-env '运行进程仍含XRAY_RAY_BUFFER_SIZE或environ不可读' 1;
            return 1
        };
        _e266_buffer_runtime_verify "$config" || { 
            _e266_buffer_fail "$log" readback-runtime 'MainPID/监听端口/联网运行探针失败' 1;
            return 1
        };
    else
        test "$active" = inactive || { 
            _e266_buffer_fail "$log" readback-inactive-state "原停止服务被改变为${active:-empty}" 1;
            return 1
        };
    fi;
    state_value=$(_e266_buffer_state_intent_file "$state" "$config" 199e266 2> /dev/null || true);
    test "$state_value" = "$expected" || { 
        _e266_buffer_fail "$log" readback-state '持久化状态未与当前JSON哈希绑定' 1;
        return 1
    };
    _e266_buffer_log_event "$log" OK readback 0 "JSON=${expected} active=${expected_active} pid=${pid:-none}" 2> /dev/null || true;
    return 0
}
