_eex3_e202_restore_readback_inner() {
    local snapshot="${1:-}" diag="" inherited_rc=0 rc=0;
    test -n "$snapshot" && _e202_snapshot_valid "$snapshot" || return 1;
    diag="${snapshot%/system}/e266-small-bbr-recovery-domains.tsv";
