    : > "$diag" ) 2> /dev/null || diag="";
    test -z "$diag" || chmod 0600 "$diag" 2> /dev/null || true;
    _e140_system_restore "$snapshot" || inherited_rc=1;
    _e266_recovery_diag "$diag" inherited-aggregate "$inherited_rc" '仅作诊断；E202退出由网络所有者、相关服务、目标sysctl和Xray基础门禁裁决';
    if _e266_e202_service_domains_reconcile "$snapshot"; then
        _e266_recovery_diag "$diag" e202-network-services 0 'E159/E202及兼容小BBR服务一致';
    else
        _e266_recovery_diag "$diag" e202-network-services 1 '相关网络服务未收敛';
        rc=1;
    fi;
    if _e202_snapshot_runtime_verify "$snapshot"; then
        _e266_recovery_diag "$diag" e202-runtime-sysctl 0 'E202管理参数与启用前快照一致';
    else
