        rc=1;
    fi;
    if _e266_e202_inactive_verify; then
        _e266_recovery_diag "$diag" e202-owner-inactive 0 'E202活动状态与服务均已退出';
    else
        _e266_recovery_diag "$diag" e202-owner-inactive 1 'E202仍有活动或开机所有权';
        rc=1;
    fi;
    if _e266_e202_xray_basic_gate "$snapshot"; then
        _e266_recovery_diag "$diag" xray-basic 0 'Xray配置、服务与必要监听可用';
    else
        _e266_recovery_diag "$diag" xray-basic 1 'Xray基础可用性未通过';
        rc=1;
    fi;
    if test "$rc" -eq 0; then
        test "$inherited_rc" -eq 0 || warn 'E202旧聚合恢复返回1，但E266小BBR专用四域门禁全部通过。';
        test -z "$diag" || info "E266小BBR恢复报告：$diag";
        return 0;
    fi;
    test -z "$diag" || error "E266小BBR专用恢复未通过：$diag";
    return 1
}
