# EEX3-FUNCTION release_e266 _eex3_entry_transaction_self_test
_eex3_entry_transaction_self_test() {
    ( local d rc=0 fail_at=0 calls=0 mode=normal outcome source;
    d=$(mktemp -d /tmp/eex6-entry-test.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    source=$(_eex6_release_source) || return 1;
    install -m 0755 "$source" "$d/source" || return 1;
    function _e214_ensure_parent_dir () 
    { 
        [[ "$1" == "$d/"* ]]
    };
    function _e214_mark_critical () 
    { 
        printf '%s\n' "$*" >> "$d/critical"
    };
    function mv () 
    { 
        calls=$((calls+1));
        if test "$calls" = "$fail_at"; then
            if test "$mode" = signal; then
                kill -TERM "${BASHPID:-$$}";
            else
                return 1;
            fi;
        fi;
        command mv "$@"
    };
    for mode in normal failure signal;
    do
        mkdir -p "$d/$mode";
        printf 'old-entry\n' > "$d/entry-a";
        rm -f -- "$d/entry-b";
        ln -s entry-a "$d/entry-b";
        fail_at=2;
        calls=0;
        test "$mode" != normal || fail_at=0;
        if _eex3_script_entries_install "$d/source" "$d/$mode" "$d/entry-a" "$d/entry-b"; then
            outcome=0;
        else
            outcome=$?;
        fi;
        if test "$mode" = normal; then
            test "$outcome" = 0 && cmp -s "$d/source" "$d/entry-a" && cmp -s "$d/source" "$d/entry-b" || rc=1;
            test "$("$d/entry-a" --release-id)" = "$EEX3_BUILD_ID" || rc=1;
            _eex3_script_entry_verify "$d/source" "$d/entry-b" || rc=1;
        else
            test "$outcome" != 0 && test "$(< "$d/entry-a")" = old-entry || rc=1;
            test -L "$d/entry-b" && test "$(readlink "$d/entry-b")" = entry-a || rc=1;
            test ! -e "$d/critical" || rc=1;
        fi;
    done;
    return "$rc" )
}
