# EEX3-FUNCTION release_e266 _eex3_fail2ban_client_not_banned
_eex3_fail2ban_client_not_banned() {
    local ip="" jail="" banned="" status="" jails="";
    command -v fail2ban-client > /dev/null 2>&1 || return 0;
    if ! status=$(fail2ban-client status 2> /dev/null); then
        ! systemctl is-active --quiet fail2ban.service 2> /dev/null || { 
            error 'Fail2ban正在运行但无法读取封禁状态；未假定当前客户端可连接。';
            return 1
        };
        return 0;
    fi;
    jails=$(sed -n 's/^.*Jail list:[[:space:]]*//p' <<< "$status" | tr ',' '\n' | awk '{$1=$1; if(NF)print}');
    while IFS= read -r jail; do
        test -n "$jail" || continue;
        [[ "$jail" =~ ^[A-Za-z0-9_.-]+$ ]] || return 1;
        banned=$(fail2ban-client get "$jail" banip 2> /dev/null) || { 
            error "无法读取Fail2ban封禁集合：$jail";
            return 1
        };
        while IFS= read -r ip; do
            test -n "$ip" || continue;
            grep -Fwq -- "$ip" <<< "$banned" && { 
                error "当前SSH客户端地址已在Fail2ban封禁集合中：jail=$jail ip=$ip";
                return 1
            };
        done < <(_eex3_current_ssh_client_ips);
    done <<< "$jails";
    return 0
}
