_eex3_hash_stream() {
    sha256sum | awk '{print $1}'
}
# EEX3-FUNCTION release_e266 _eex3_help
_eex3_help() {
    _e266_help
}
# EEX3-FUNCTION release_e266 _eex3_hot_components_legacy
_eex3_hot_components_legacy() {
    ( local protect="" sysbackup="" network_tx="" ssh_tx="" rc=0 rollback_rc=0 was_active=0;
    local enabled=0 mode=disabled profile=disabled phase=start auth_mode="";
    local effective_active=0 effective_persistent=0 unsupported=0 shadowed=0 trigger=0;
    _e214_ensure_run_lock || return 1;
    exec 192> /run/lock/xray-e202-hot-update.lock;
    flock -n 192 || { 
        error '已有另一个E202热更新正在运行。';
        return 1
    };
    : > "$E202_HOT_LOG" || return 1;
    E135_NEW_PACKAGES=();
    _e159_phase_log "$E202_HOT_LOG" start begin "$SCRIPT_PATH";
    _e182_prepare || return 1;
    phase=xray-snapshot;
    protect=$(_e116_backup_state before_hot_update_e202) || rc=1;
    test "$rc" -ne 0 || _e118_save_core_payload "$protect" || rc=1;
    if test "$rc" -eq 0; then
        was_active=$(sed -n 's/^xray_was_active=//p' "$protect/meta.env" 2> /dev/null | tail -n1);
        was_active=${was_active:-0};
        _e159_phase_log "$E202_HOT_LOG" "$phase" ok "$protect";
    fi;
    if test "$rc" -eq 0; then
        phase=system-snapshot;
        sysbackup=$(_e202_new_tx hot-update) || rc=1;
        test "$rc" -ne 0 || _e140_system_snapshot "$sysbackup" || rc=1;
        test "$rc" -ne 0 || _e159_phase_log "$E202_HOT_LOG" "$phase" ok "$sysbackup";
    fi;
    test "$rc" -ne 0 || _e202_hot_step ipv6-policy _e182_ipv6_hot_apply_default || rc=1;
    test "$rc" -ne 0 || _e202_hot_step ssh-readonly-baseline _eex3_ssh_upgrade_baseline_capture || rc=1;
    test "$rc" -ne 0 || _e202_hot_step warp-state-migrate _e138_warp_migrate_state || rc=1;
    test "$rc" -ne 0 || _e202_hot_step warp-family-state _e138_warp_migrate_state || rc=1;
    test "$rc" -ne 0 || _e202_hot_step warp-backend-state _e138_warp_migrate_state || rc=1;
    if test "$rc" -eq 0; then
        enabled=$(_e138_state_get route_enabled 0);
        mode=$(_e138_state_get route_mode disabled);
        profile=$(_e138_state_get profile disabled);
    fi;
    test "$rc" -ne 0 || _e202_hot_step runtime-tools _e135_require_runtime_tools || rc=1;
    test "$rc" -ne 0 || _e202_hot_step qr-runtime _e183_ensure_qrencode || rc=1;
    test "$rc" -ne 0 || _e202_hot_step disable-legacy _e135_disable_legacy_optimizers || rc=1;
    test "$rc" -ne 0 || _e202_hot_step self-install _e202_install_self || rc=1;
    test "$rc" -ne 0 || _e202_hot_step dat-install install_update_dat || rc=1;
    test "$rc" -ne 0 || _e202_hot_step dat-timer systemctl enable --now xray-dat-update.timer || rc=1;
    test "$rc" -ne 0 || _e202_hot_step core-auto-update-off _e105_disable_xray_core_auto_update || rc=1;
    test "$rc" -ne 0 || _e202_hot_step init-window _e137_apply_init_window_default30 || rc=1;
    if test "$rc" -eq 0; then
        E159_DEFER_HOST_FULL_VERIFY=1;
        _e202_hot_step network-e159-stable-owner _e159_network_apply fq 1 31 force || rc=1;
        unset E159_DEFER_HOST_FULL_VERIFY;
        test "$rc" -ne 0 || network_tx=$(sed -n 's/^backup=//p' "$E159_NETWORK_STATE" | tail -n1);
    fi;
    test "$rc" -ne 0 || _e202_hot_step host-safe-migrate _e159_migrate_host_safe || rc=1;
    test "$rc" -ne 0 || _e202_hot_step log-retention _e121_install_log_retention || rc=1;
    test "$rc" -ne 0 || _e202_hot_step ssh-readonly-readback _eex3_ssh_upgrade_baseline_verify || rc=1;
    if test "$rc" -eq 0; then
        ssh_tx="";
    fi;
    test "$rc" -ne 0 || _e202_hot_step xray-limits fix_xray_systemd_limits || rc=1;
    if test "$rc" -eq 0 && test "$enabled" = 1; then
        if test "$mode" = host-full; then
            _e202_hot_step warp-full-units _e140_full_install_units || rc=1;
            test "$rc" -ne 0 || _e202_hot_step warp-full-reconcile _e140_warp_full_reconcile || rc=1;
        else
            _e202_hot_step warp-backend-reconcile _e185_hot_warp_reconcile || rc=1;
        fi;
    fi;
    test "$rc" -ne 0 || _e202_hot_step version-write _e202_write_version || rc=1;
    if test "$rc" -eq 0; then
        phase=verify;
        _e159_phase_log "$E202_HOT_LOG" "$phase" begin;
        test -x "$XRAY_BIN" && "$XRAY_BIN" version > /dev/null 2>&1 || rc=1;
        test "$rc" -ne 0 || test ! -s "$CONFIG" || _e118_xray_test_config "$CONFIG" 1 || rc=1;
        if test "$rc" -eq 0 && test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 || rc=1;
            test "$rc" -ne 0 || _e131_verify_nice_runtime || rc=1;
        else
            if test "$rc" -eq 0 && systemctl is-active --quiet xray.service 2> /dev/null; then
                error '热更新意外启动了原本停止的Xray服务。';
                rc=1;
            fi;
        fi;
        test "$rc" -ne 0 || _e159_network_verify_effective || rc=1;
        test "$rc" -ne 0 || _e159_network_verify_ownership || rc=1;
        test "$rc" -ne 0 || _eex3_ssh_upgrade_baseline_verify || rc=1;
        test "$rc" -ne 0 || grep -qx 'net.ipv4.tcp_notsent_lowat = 16384' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || grep -qx 'net.core.busy_poll = 50' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || _e159_verify_neighbor_queue_semantics || rc=1;
        test "$rc" -ne 0 || _e182_ipv6_hot_verify || rc=1;
        test "$rc" -ne 0 || ! grep -Eq '^[[:space:]]*net\.ipv6\.conf\..*\.disable_ipv6[[:space:]]*=' "$E159_EFFECTIVE_CONF" || rc=1;
        test "$rc" -ne 0 || grep -Eq 'initcwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
        test "$rc" -ne 0 || grep -Eq 'initrwnd[[:space:]]+30' < <(ip -4 route show default) || rc=1;
        for unit in xray-dat-update.timer xray-log-retention-e121.timer xray-network-e159.timer;
        do
            test "$rc" -ne 0 || systemctl is-enabled --quiet "$unit" 2> /dev/null || rc=1;
            test "$rc" -ne 0 || systemctl is-active --quiet "$unit" 2> /dev/null || rc=1;
        done;
        test "$rc" -ne 0 || systemctl is-enabled --quiet xray-network-e159.service 2> /dev/null || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$SYMLINK" || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E202_SELF_PATH" || rc=1;
        test "$rc" -ne 0 || cmp -s "$SCRIPT_PATH" "$E202_LATEST_PATH" || rc=1;
        test "$rc" -eq 0 && _e159_phase_log "$E202_HOT_LOG" "$phase" ok || _e159_phase_log "$E202_HOT_LOG" "$phase" fail;
    fi;
    if test "$rc" -ne 0; then
        error "E202热更新失败，开始总回滚；阶段日志：$E202_HOT_LOG";
        test -z "$ssh_tx" || _e152_nft_ssh_tx_rollback "$ssh_tx" || rollback_rc=1;
        test -z "$network_tx" || _e159_network_restore "$network_tx" || rollback_rc=1;
        _e182_ipv6_hot_rollback_if_marked || rollback_rc=1;
        test -z "$sysbackup" || _e140_system_restore "$sysbackup" || rollback_rc=1;
        test -z "$sysbackup" || _e182_sshd_reload_safe || rollback_rc=1;
        test -z "$protect" || _e118_restore_core_payload "$protect" > /dev/null 2>&1 || rollback_rc=1;
        test -z "$protect" || _e118_restore_state "$protect" > /dev/null 2>&1 || rollback_rc=1;
        _e135_remove_new_runtime_tools || true;
        if test "$was_active" = 1; then
            _e127_verify_xray_runtime "$CONFIG" 12 > /dev/null 2>&1 || rollback_rc=1;
        fi;
        if test "$rollback_rc" -ne 0; then
            { 
                echo "time=$(date -Is 2> /dev/null || date)";
                echo 'operation=hot-update';
                echo "system_backup=${sysbackup:-none}";
                echo "network_backup=${network_tx:-none}";
                echo "ssh_backup=${ssh_tx:-none}";
                echo "core_backup=${protect:-none}";
                echo "log=$E202_HOT_LOG"
            } > "$E202_CRITICAL_MARKER" 2> /dev/null || true;
            error '严重：E202回滚未通过复检。';
        fi;
        _e159_phase_log "$E202_HOT_LOG" finish fail "rollback=$rollback_rc";
        return 1;
    fi;
    _e182_ipv6_hot_commit;
    rm -f "$E202_CRITICAL_MARKER" 2> /dev/null || true;
    _e142_prune_transactions "$sysbackup" "$protect" "$ssh_tx" || warn '旧事务快照收敛未完成。';
    _e127_prune_core_payload_backups;
    _e182_prune_system_tx "$sysbackup";
    :;
    _e159_phase_log "$E202_HOT_LOG" finish ok;
    effective_active=$(sed -n 's/^effective_active=//p' "$E159_NETWORK_STATE" | tail -n1);
    effective_persistent=$(sed -n 's/^effective_persistent=//p' "$E159_NETWORK_STATE" | tail -n1);
    unsupported=$(sed -n 's/^unsupported=//p' "$E159_NETWORK_STATE" | tail -n1);
    shadowed=$(sed -n 's/^shadowed_alias=//p' "$E159_NETWORK_STATE" | tail -n1);
    trigger=$(sed -n 's/^write_trigger=//p' "$E159_NETWORK_STATE" | tail -n1);
    auth_mode=$(_e141_sshd_auth_profile 2> /dev/null | sed -n 's/^mode=//p' | head -n1);
    if test "$auth_mode" = password-capable; then
        info "E242兼容热更新阶段完成：127条请求（persistent=$effective_persistent，trigger=$trigger，unsupported=$unsupported，shadowed_alias=$shadowed，effective_assignments=$effective_active）、init30、3天日志、SSH能力状态（防火墙封禁、OpenSSH原生限流或只读审计）和Xray运行态均已验证。";
    else
        info "E242兼容热更新阶段完成：127条请求（persistent=$effective_persistent，trigger=$trigger，unsupported=$unsupported，shadowed_alias=$shadowed，effective_assignments=$effective_active）、init30、3天日志、SSH认证模式=$auth_mode（未强制启用Fail2ban）和Xray运行态均已验证。";
    fi;
    info "系统快照：$sysbackup";
    info "网络快照：$network_tx";
    info "SSH快照：${ssh_tx:-none}";
    info "阶段日志：$E202_HOT_LOG" )
}
# EEX3-FUNCTION release_e266 _eex3_hot_preflight_legacy
_eex3_hot_preflight_legacy() {
    local owner="" fn c;
    test "$EUID" -eq 0 || { 
        error 'E266热更新必须使用root。';
        return 1
    };
    test -d /run/systemd/system || { 
        error 'systemd未运行。';
        return 1
    };
    for c in bash systemctl jq curl ip ss tar install sha256sum cp awk sed grep dirname mkdir mv cmp find sort readlink base64 paste tr chmod chown stat sysctl mktemp flock xargs cat cut date head kill rm rmdir tail touch wc;
    do
        command -v "$c" > /dev/null 2>&1 || { 
            error "E266只读预检缺少命令：$c";
            return 1
        };
    done;
    test -r "$SCRIPT_PATH" || { 
        error "当前脚本不可读：$SCRIPT_PATH";
        return 1
    };
    bash -n "$SCRIPT_PATH" || return 1;
    _e266_release_binding_gate || return 1;
    _e214_critical_preflight || return 1;
    _e220_mss_preflight_readonly || return 1;
    for fn in _e214_install_self _e140_system_snapshot _e140_system_restore _e182_install_mode _e159_network_apply _e159_network_remove _e185_warp_health_check _e266_structure_audit _e218_mss_consistency;
    do
        declare -F "$fn" > /dev/null 2>&1 || { 
            error "E266热更新缺少最终函数：$fn";
            return 1
        };
    done;
    owner=$(_e204_legacy_small_bbr_owner 2> /dev/null || true);
    if test -n "$owner"; then
        error "检测到旧小BBR所有者：$owner。E266不会猜测旧版快照并代替旧版退出。";
        error '请先由对应旧版脚本执行 --small-bbr-disable并确认恢复，再运行E266热更新。';
        return 1;
    fi;
    if _e202_small_bbr_active; then
        error '检测到当前E202兼容小BBR仍处于active。E266不会在唯一恢复快照之上覆盖热更新入口。';
        error '请先用当前已安装的旧脚本执行：xrv --small-bbr-disable，确认恢复后再热更新。';
        return 1;
    fi;
    if _e214_mtu_any_state; then
        _e214_mtu_persistence_validate || { 
            error 'E214 MTU状态/基线/持久服务不完整；为避免热更新覆盖恢复证据，拒绝继续。';
            error '请先在菜单27重新应用当前MTU或安全退出MTU策略。';
            return 1
        };
    fi;
    if _e218_mss_any_evidence; then
        _e218_mss_consistency || { 
            error 'MSS Clamp在热更新前已存在状态/规则/服务漂移；拒绝覆盖恢复证据。';
            error '请先用旧脚本的菜单10→7显式修复或关闭MSS Clamp。';
            return 1
        };
    fi
}
# EEX3-FUNCTION release_e266 _eex3_hot_restore_readback_base
_eex3_hot_restore_readback_base() {
    local snapshot="${1:-}" diag="" inherited_rc=0 rc=0;
    test -n "$snapshot" && test -d "$snapshot" || return 1;
    diag="${snapshot%/system}/e266-recovery-domains.tsv";
    if ! ( umask 077;
    : > "$diag" ) 2> /dev/null; then
        diag="/run/xray-e266-recovery-${BASHPID:-$$}.tsv";
        ( umask 077;
        : > "$diag" ) 2> /dev/null || diag="";
    fi;
    test -z "$diag" || chmod 0600 "$diag" 2> /dev/null || true;
    _e140_system_restore "$snapshot" || inherited_rc=1;
    _e266_recovery_diag "$diag" inherited-aggregate "$inherited_rc" '旧聚合返回值，仅作诊断；最终结果由下列独立门禁决定';
    if _e266_snapshot_authority_verify "$snapshot"; then
        _e266_recovery_diag "$diag" authoritative-files 0 '快照文件、符号链接和缺席路径一致';
    else
        _e266_recovery_diag "$diag" authoritative-files 1 '权威文件或密封校验不一致';
        rc=1;
    fi;
    if _e266_service_domains_reconcile "$snapshot"; then
        _e266_recovery_diag "$diag" services 0 '服务状态已逐项恢复并读回';
    else
        _e266_recovery_diag "$diag" services 1 '至少一个密封服务状态不一致';
        rc=1;
    fi;
    if _e266_runtime_sysctl_reconcile "$snapshot"; then
        _e266_recovery_diag "$diag" runtime-sysctl 0 '运行态sysctl一致';
    else
        _e266_recovery_diag "$diag" runtime-sysctl 1 '运行态sysctl不一致';
        rc=1;
    fi;
    if _e266_firewall_runtime_reconcile "$snapshot"; then
        _e266_recovery_diag "$diag" firewall-runtime 0 '密封xtables运行态已重放';
    else
        _e266_recovery_diag "$diag" firewall-runtime 1 '密封xtables运行态无法重放';
        rc=1;
    fi;
    if _e266_mtu_runtime_verify "$snapshot"; then
        _e266_recovery_diag "$diag" mtu-runtime 0 '仍存在的原接口MTU一致';
    else
        _e266_recovery_diag "$diag" mtu-runtime 1 '原接口MTU不一致';
        rc=1;
    fi;
    if _e266_xray_recovery_gate "$snapshot"; then
        _e266_recovery_diag "$diag" xray-reality 0 '配置、服务、监听和PBK派生缓存一致';
    else
        _e266_recovery_diag "$diag" xray-reality 1 'Xray/Reality独立门禁不一致';
        rc=1;
    fi;
    if test "$rc" -eq 0; then
        test "$inherited_rc" -eq 0 || warn "旧聚合恢复曾返回1，但E266全部独立门禁通过；不再把历史辅助返回值误判为整机恢复失败。";
        test -z "$diag" || info "E266分域恢复报告：$diag";
        return 0;
    fi;
    if test -n "$diag"; then
        error "E266分域恢复未通过；逐域报告：$diag";
    else
        error 'E266分域恢复未通过；根分区与/run均无法写入诊断文件。';
    fi;
    return 1
}
# EEX3-FUNCTION release_e266 _eex3_hot_verify_abi
_eex3_hot_verify_abi() {
    local target;
    for target in "$SYMLINK" "$E242_SELF_PATH" "$E242_LEGACY_E262_SELF_PATH" "$E242_LEGACY_E260_SELF_PATH" "$E242_LEGACY_E258_SELF_PATH" "$E242_LEGACY_E256_SELF_PATH" "$E242_LEGACY_E254_SELF_PATH" "$E242_LEGACY_E252_SELF_PATH" "$E242_LEGACY_E246_SELF_PATH" "$E242_LEGACY_E244_SELF_PATH" "$E242_LEGACY_E243_SELF_PATH" "$E242_LEGACY_E242_SELF_PATH" "$E242_LEGACY_E240_SELF_PATH" "$E242_LEGACY_E238_SELF_PATH" "$E242_LEGACY_E236_SELF_PATH" "$E242_LEGACY_E234_SELF_PATH" "$E242_LEGACY_E232_SELF_PATH" "$E242_LEGACY_E230_SELF_PATH" "$E242_LEGACY_E228_SELF_PATH" "$E242_LEGACY_E226_SELF_PATH" "$E242_LEGACY_E224_SELF_PATH" "$E242_LEGACY_E222_SELF_PATH" "$E220_SELF_PATH" "$E218_SELF_PATH" "$E216_SELF_PATH" "$E214_SELF_PATH" "$E214_LEGACY_E212_SELF_PATH" "$E214_LEGACY_E210_SELF_PATH" "$E214_LEGACY_E208_SELF_PATH" "$E214_LEGACY_E206_SELF_PATH" "$E214_LATEST_PATH" "$E204_SELF_PATH" "$E202_SELF_PATH";
    do
        test -f "$target" && test ! -L "$target" && test -x "$target" && test "$(stat -c '%a:%u:%g' "$target" 2> /dev/null || true)" = 755:0:0 && bash -n "$target" && cmp -s "$(_eex6_release_source)" "$target" || { 
            error "E220入口安装读回失败：$target";
            return 1
        };
    done;
    test "$(cat "$SCRIPT_VERSION_FILE" 2> /dev/null || true)" = "$E214_VERSION" || { 
        error '脚本版本文件没有读回199e266。';
        return 1
    };
    if test -s "$CONFIG"; then
        _e118_xray_test_config "$CONFIG" 1 || return 1;
        if systemctl is-active --quiet xray.service 2> /dev/null; then
            _e127_verify_xray_runtime "$CONFIG" 12 || return 1;
        fi;
    fi;
    if test "$(_e138_state_get route_enabled 0)" = 1; then
        _e185_warp_health_check || return 1;
    fi;
    _e182_ipv6_hot_verify || return 1;
    if _e202_small_bbr_active; then
        _e202_small_bbr_status > /dev/null || return 1;
    fi;
    if _e214_mtu_any_state; then
        _e214_mtu_persistence_validate || return 1;
    fi;
    _e218_mss_consistency || return 1
}
# EEX3-FUNCTION release_e266 _eex3_inactive_profile_manual
_eex3_inactive_profile_manual() {
    local out="${1:-}" announce="${2:-1}" source="$E202_SMALL_PROFILE";
    test -n "$out" || return 1;
    case "$announce" in 
        0 | 1)

        ;;
        *)
            return 1
        ;;
    esac;
    if test "${E242_INTERNAL_SELF_TEST:-0}" = 1 && test -n "${E242_SMALL_PROFILE_OVERRIDE:-}"; then
        source=$E242_SMALL_PROFILE_OVERRIDE;
    fi;
    if test -e "$source" || test -L "$source"; then
        _e202_small_bbr_validate_file "$source" || { 
            error "检测到无效的小BBR保存档，拒绝在自动升级中猜测或覆盖：$source";
            return 1
        };
        install -m 0600 "$source" "$out" || return 1;
        if test "$announce" = 1; then
            info "未检测到活动小BBR，将应用现有有效保存档：$(_e202_small_bbr_profile_name "$(_e202_small_bbr_profile_id_file "$out")")";
        fi;
    else
        case "$E242_DEFAULT_SMALL_PROFILE" in 
            mode3f2)
                _e202_small_bbr_mode3f2 > "$out" || return 1
            ;;
            *)
                error "E266内置默认小BBR档位无效：$E242_DEFAULT_SMALL_PROFILE";
                return 1
            ;;
        esac;
        chmod 0600 "$out" || return 1;
        _e202_small_bbr_validate_file "$out" || return 1;
        test "$announce" = 0 || info '未检测到活动或保存的小BBR档位，将按你的固定流程应用模式3F2。';
    fi
}
# EEX3-FUNCTION release_e266 _eex3_installed_release_readonly
_eex3_installed_release_readonly() {
    local path release;
    path=$(readlink -f -- "$SYMLINK") || return 1;
    test -f "$path" && test -r "$path" || return 1;
    release=$(sed -nE 's/^readonly EEX3_BUILD_ID="(eex[1-9][0-9]*)"$/\1/p' "$path") || return 1;
    [[ "$release" =~ ^eex[1-9][0-9]*$ ]] || return 1;
    printf '%s\n' "$release"
}
# EEX3-FUNCTION release_e266 _eex3_item28_components_verify
_eex3_item28_components_verify() {
    local path pid;
    _eex7_handshake_verify "$CONFIG" || return 1;
    if systemctl is-active --quiet xray.service; then
        _e131_verify_nice_runtime || return 1;
        pid=$(systemctl show xray.service -p MainPID --value) || return 1;
        _eex7_gogc_process_verify "$pid" || return 1;
    fi;
    _eex3_app_config_verify || return 1;
    _e118_xray_test_config "$CONFIG" 1 || return 1;
    test "$(systemctl show xray.service -p Nice --value 2> /dev/null)" = -20 || return 1;
    test "$(systemctl show xray.service -p OOMScoreAdjust --value 2> /dev/null)" = -500 || return 1;
    test "$(systemctl show xray.service -p LimitNOFILE --value 2> /dev/null)" = 1048576 || return 1;
    systemctl show xray.service -p Environment --value 2> /dev/null | grep -Eq '(^|[[:space:]"])GOGC=300([[:space:]"]|$)' || return 1;
    test -s "$E159_HOST_SCRIPT" && test ! -L "$E159_HOST_SCRIPT" && bash -n "$E159_HOST_SCRIPT" || return 1;
    grep -Fxq "ExecStart=$E159_HOST_SCRIPT" "$E159_HOST_SERVICE" || return 1;
    systemctl show xray-host-safe-e159.service -p ExecStart --value 2> /dev/null | grep -Fq "path=$E159_HOST_SCRIPT ;" || return 1;
    grep -qx 'thp=1' "$E159_HOST_STATE" && grep -qx 'cpu=1' "$E159_HOST_STATE" || return 1;
    systemctl is-enabled --quiet xray-host-safe-e159.service || return 1;
    test "$(systemctl show xray-host-safe-e159.service -p Result --value 2> /dev/null)" = success || return 1;
    test "$(systemctl show xray-host-safe-e159.service -p ExecMainStatus --value 2> /dev/null)" = 0 || return 1;
    for path in /sys/kernel/mm/transparent_hugepage/enabled /sys/kernel/mm/transparent_hugepage/defrag;
    do
        test ! -w "$path" || grep -Fq '[never]' "$path" || return 1;
    done;
    for path in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor;
    do
        test ! -w "$path" || test "$(< "$path")" = performance || return 1;
    done;
    test -s "$E121_JOURNAL_CONF" && test -s "$E121_LOGROTATE_CONF" || return 1;
    grep -qx 'MaxRetentionSec=3day' "$E121_JOURNAL_CONF" && grep -qx 'MaxFileSec=1day' "$E121_JOURNAL_CONF" || return 1;
    grep -Eq '^[[:space:]]*daily[[:space:]]*$' "$E121_LOGROTATE_CONF" && grep -Eq '^[[:space:]]*rotate[[:space:]]+3[[:space:]]*$' "$E121_LOGROTATE_CONF" || return 1;
    logrotate -d "$E121_LOGROTATE_CONF" > /dev/null 2>&1 || return 1;
    systemctl is-enabled --quiet xray-log-retention-e121.timer || return 1;
    systemctl is-active --quiet xray-log-retention-e121.timer
}
# EEX3-FUNCTION release_e266 _eex3_kernel_tcp_listen_ports
_eex3_kernel_tcp_listen_ports() {
    command -v ss > /dev/null 2>&1 || return 0;
    ss -H -ltn 2> /dev/null | awk '
      {
        endpoint=$4
        sub(/^.*:/,"",endpoint)
        if(endpoint ~ /^[0-9]+$/ && endpoint>=1 && endpoint<=65535 && !seen[endpoint]++)
          print endpoint
      }' | sort -nu
}
# EEX3-FUNCTION release_e266 _eex3_lineage_finalize_e159
_eex3_lineage_finalize_e159() {
    local audit="${E266_LINEAGE_REBASE_DIR:-}" env="" status="" lost_digest="";
    local archived_digest="" started="" baseline_restored="" rescue="" rescue_seal="";
    local snapshot="" record="" class="" origin="" digest="" tmp="" snapshot_digest="";
    test -n "$audit" || return 0;
    env="$audit/lineage.env";
    test -e "$env" || test -L "$env" || return 0;
    _e266_lineage_audit_dir_validate "$audit" || return 1;
    test -f "$env" && test ! -L "$env" && test "$(stat -c %u "$env" 2> /dev/null || true)" = 0 || return 1;
    status=$(_e266_state_value_once "$env" status) || return 1;
    test "$status" = restored-owner-free-baseline || return 1;
    test "$(_e266_state_value_once "$env" reason)" = e254-gc-deleted-transitive-e159-origin || return 1;
    test "$(_e266_state_value_once "$env" baseline_kind)" = verified-e202-active-owner-free || return 1;
    lost_digest=$(_e266_state_value_once "$env" lost_origin_path_sha256) || return 1;
    archived_digest=$(_e266_state_value_once "$env" archived_e159_state_sha256) || return 1;
    rescue=$(_e266_state_value_once "$env" rescue_origin) || return 1;
    rescue_seal=$(_e266_state_value_once "$env" rescue_seal_sha256) || return 1;
    started=$(_e266_state_value_once "$env" started_at) || return 1;
    baseline_restored=$(_e266_state_value_once "$env" baseline_restored_at) || return 1;
    [[ "$lost_digest" =~ ^[0-9a-f]{64}$ && "$archived_digest" =~ ^[0-9a-f]{64}$ && "$rescue_seal" =~ ^[0-9a-f]{64}$ ]] || return 1;
    _e159_network_tx_verify "$rescue" && _e204_network_origin_clean "$rescue" && test "$(sha256sum "$rescue/seal.sha256" | awk 'NR==1{print $1}')" = "$rescue_seal" || return 1;
    snapshot=$(_e266_state_value_once "$E202_SMALL_STATE" restore_snapshot) || return 1;
    record=$(_e266_e202_snapshot_e159_lineage "$snapshot") || return 1;
    IFS='|' read -r class origin digest <<< "$record";
    test "$class" = clean && [[ "$digest" =~ ^[0-9a-f]{64}$ ]] || return 1;
    _e159_network_tx_verify "$origin" > /dev/null 2>&1 && _e204_network_origin_clean "$origin" > /dev/null 2>&1 || return 1;
    test "$origin" != "$rescue" || return 1;
    test "$(printf '%s' "$origin" | sha256sum | awk 'NR==1{print $1}')" != "$lost_digest" || return 1;
    snapshot_digest=$(printf '%s' "$snapshot" | sha256sum | awk 'NR==1{print $1}');
    tmp="$audit/.lineage.env.commit.${BASHPID:-$$}";
    { 
        printf 'version=199e266\n';
        printf 'status=committed-clean-origin\n';
        printf 'reason=e254-gc-deleted-transitive-e159-origin\n';
        printf 'lost_origin_path_sha256=%s\n' "$lost_digest";
        printf 'archived_e159_state_sha256=%s\n' "$archived_digest";
        printf 'baseline_kind=verified-e202-active-owner-free\n';
        printf 'rescue_origin=%s\n' "$rescue";
        printf 'rescue_seal_sha256=%s\n' "$rescue_seal";
        printf 'started_at=%s\n' "$started";
        printf 'baseline_restored_at=%s\n' "$baseline_restored";
        printf 'new_origin_backup=%s\n' "$origin";
        printf 'new_e159_state_sha256=%s\n' "$digest";
        printf 'new_e202_snapshot_path_sha256=%s\n' "$snapshot_digest";
        printf 'committed_at=%s\n' "$(date -Is 2> /dev/null || date)"
    } > "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    chmod 0600 "$tmp" || { 
        rm -f -- "$tmp";
        return 1
    };
    mv -T -- "$tmp" "$env" || { 
        rm -f -- "$tmp";
        return 1
    };
    info "E266已从阶段9前真实无E159基线闭合新恢复链；审计记录：$env"
}
# EEX3-FUNCTION release_e266 _eex3_lineage_finalize_self_test
_eex3_lineage_finalize_self_test() {
    ( local d rc=0 mock_record='none|-|-' E266_LINEAGE_REBASE_DIR rescue seal;
    d=$(mktemp -d /tmp/eex3-lineage-close.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    E266_LINEAGE_REBASE_DIR="$d/audit";
    rescue="$d/rescue";
    mkdir -p "$E266_LINEAGE_REBASE_DIR" "$rescue";
    printf 'fixture\n' > "$rescue/seal.sha256";
    seal=$(sha256sum "$rescue/seal.sha256" | awk '{print $1}');
    printf 'status=restored-owner-free-baseline\nreason=e254-gc-deleted-transitive-e159-origin\nbaseline_kind=verified-e202-active-owner-free\nrescue_origin=%s\nrescue_seal_sha256=%s\n' "$rescue" "$seal" > "$d/before";
    cp -- "$d/before" "$E266_LINEAGE_REBASE_DIR/lineage.env";
    function _e266_lineage_audit_dir_validate () 
    { 
        test "$1" = "$d/audit"
    };
    function _e266_state_value_once () 
    { 
        if test "$1:$2" = "$E202_SMALL_STATE:restore_snapshot"; then
            printf '%s\n' "$d/snapshot";
        else
            _e218_mss_owner_state_value "$@";
        fi
    };
    function _e266_e202_snapshot_e159_lineage () 
    { 
        printf '%s\n' "$mock_record"
    };
    function _e159_network_tx_verify () 
    { 
        test "$1" = "$d/rescue"
    };
    function _e204_network_origin_clean () 
    { 
        test "$1" = "$d/rescue"
    };
    function _eex3_mode3f2_verify () 
    { 
        return 0
    };
    function info () 
    { 
        :
    };
    _e266_lineage_rebase_finalize || rc=1;
    grep -qx 'status=committed-owner-free' "$E266_LINEAGE_REBASE_DIR/lineage.env" || rc=1;
    cp -- "$d/before" "$E266_LINEAGE_REBASE_DIR/lineage.env";
    mock_record='broken|/lost/origin|abc';
    if _e266_lineage_rebase_finalize; then
        rc=1;
    fi;
    cmp -s "$d/before" "$E266_LINEAGE_REBASE_DIR/lineage.env" || rc=1;
    return "$rc" )
}
