    for v in 'bad' '1.2.3.4 0 2.3.4.5 22' '1.2.3.4 1234 2.3.4.5 22 extra';
    do
        SSH_CONNECTION="$v";
        if _eex3_ssh_tuple_validate; then
            rc=1;
        fi;
    done;
    return "$rc" )
}
# EEX3-FUNCTION release_e266 _eex3_network_owner_classify
_eex3_network_owner_classify() {
    local origin p any=0 operative=0 unit;
    for p in "$E159_EFFECTIVE_CONF" "$E159_NETWORK_STATE" "$E159_NETWORK_SCRIPT" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER";
    do
        if test -e "$p" || test -L "$p"; then
            any=1;
        fi;
    done;
    for unit in xray-network-e159.service xray-network-e159.timer xray-network-e156.service xray-network-e156.timer xray-network-e154.service xray-network-e154.timer;
    do
        _eex3_systemd_unit_claimed "$unit" && operative=1 || true;
    done;
    for p in "$E159_EFFECTIVE_CONF" "$E159_LEGACY_E156_EFFECTIVE_CONF" "$E159_LEGACY_E154_EFFECTIVE_CONF";
    do
        if test -e "$p" || test -L "$p"; then
            any=1;
            operative=1;
        fi;
    done;
    if test "$any:$operative" = 0:0; then
        printf 'none\n';
        return;
    fi;
    origin=$(_e204_network_origin 2> /dev/null || true);
    if test -n "$origin" && _e159_network_tx_verify "$origin" && _e204_network_origin_clean "$origin"; then
        printf 'valid-active\n';
    else
        if test "$operative" = 0; then
            printf 'inert-residue\n';
        else
            printf 'invalid-live\n';
        fi;
    fi
}
# EEX3-FUNCTION release_e266 _eex3_network_owner_converge
_eex3_network_owner_converge() {
    local class p;
    class=$(_eex3_network_owner_classify) || return 1;
    case "$class" in 
        none)
            return 0
        ;;
        valid-active)
            _e159_network_remove force
        ;;
        inert-residue)
            test "${EEX3_AUTO_ACTIVE:-0}" = 1 && test -n "${EEX3_OUTER_TX:-}" && _eex5_restore_preflight "$EEX3_OUTER_TX/system" all || return 1;
            for p in "$E159_NETWORK_STATE" "$E159_NETWORK_SCRIPT" "$E159_NETWORK_SERVICE" "$E159_NETWORK_TIMER";
            do
                test ! -d "$p" || return 1;
                rm -f -- "$p" || return 1;
            done;
            systemctl daemon-reload > /dev/null 2>&1
        ;;
        *)
            error '完整网络层存在不可证明的活动/开机所有权；未猜测原始基线，保留现场。';
            return 1
        ;;
    esac
}
