# EEX3-FUNCTION release_e266 _eex3_package_plan_build
_eex3_package_plan_build() {
    local out="${1:-}" file="" line="" pkg="" wanted="" extra="" source="";
    local tmp="" sorted="" rc=0 rows=0;
    local -A seen=() wants=() sources=();
    shift || true;
    test -n "$out" && test ! -L "$out" && test -d "$(dirname -- "$out")" || return 1;
    tmp=$(mktemp "${out}.build.XXXXXX") || return 1;
    sorted=$(mktemp "${out}.sort.XXXXXX") || { 
        rm -f -- "$tmp";
        return 1
    };
    chmod 0600 "$tmp" "$sorted" 2> /dev/null || { 
        rm -f -- "$tmp" "$sorted";
        return 1
    };
    for file in "$@";
    do
        test -f "$file" && test ! -L "$file" || { 
            rc=1;
            break
        };
        if test -e "$file.sha256"; then
            test -f "$file.sha256" && test ! -L "$file.sha256" && ( cd "$(dirname -- "$file")" && sha256sum -c "$(basename -- "$file").sha256" > /dev/null 2>&1 ) || { 
                rc=1;
                break
            };
        fi;
        source=${file##*/};
        [[ "$source" =~ ^[A-Za-z0-9._-]+$ ]] || { 
            rc=1;
            break
        };
        while IFS= read -r line || test -n "$line"; do
            test -n "$line" || continue;
            test "$(awk -F'|' '{print NF}' <<< "$line")" = 2 || { 
                rc=1;
                break
            };
            IFS='|' read -r pkg wanted extra <<< "$line";
            _eex3_package_name_valid "$pkg" && _eex3_package_allowed "$pkg" && [[ "$wanted" =~ ^[01]$ ]] || { 
                rc=1;
                break
            };
            rows=$((rows + 1));
            if test "${seen[$pkg]+set}" = set; then
                if test "${wants[$pkg]}" != "$wanted"; then
                    _eex3_cf_error "软件包目标冲突：pkg=$pkg first=${wants[$pkg]} next=$wanted source=$source";
                    rc=1;
                    break;
                fi;
                case ",${sources[$pkg]}," in 
                    *",$source,"*)

                    ;;
                    *)
                        sources[$pkg]="${sources[$pkg]},$source"
                    ;;
                esac;
            else
                seen[$pkg]=1;
                wants[$pkg]=$wanted;
                sources[$pkg]=$source;
            fi;
        done < "$file";
        test "$rc" -eq 0 || break;
    done;
    if test "$rc" -eq 0; then
        for pkg in "${!seen[@]}";
        do
            printf '%s|%s|%s\n' "$pkg" "${wants[$pkg]}" "${sources[$pkg]}" >> "$tmp" || { 
                rc=1;
                break
            };
        done;
    fi;
    test "$rc" -ne 0 || LC_ALL=C sort -t'|' -k1,1 "$tmp" > "$sorted" || rc=1;
    test "$rc" -ne 0 || mv -f -- "$sorted" "$out" || rc=1;
    rm -f -- "$tmp" "$sorted";
    test "$rc" -eq 0
}
# EEX3-FUNCTION release_e266 _eex3_package_plan_self_test
_eex3_package_plan_self_test() {
    ( local d="" plan="" rc=0;
    d=$(mktemp -d /tmp/eex3-package-plan-test.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    function error () 
    { 
        :
    };
    printf 'fail2ban|0\nnftables|1\n' > "$d/a-packages.before";
    printf 'fail2ban|0\n' > "$d/b-packages.before";
    _eex3_package_plan_build "$d/plan" "$d/a-packages.before" "$d/b-packages.before" || rc=1;
    grep -qx 'fail2ban|0|a-packages.before,b-packages.before' "$d/plan" || rc=1;
    printf 'fail2ban|1\n' > "$d/b-packages.before";
    _eex3_package_plan_build "$d/plan" "$d/a-packages.before" "$d/b-packages.before" > /dev/null 2>&1 && rc=1 || true;
    return "$rc" )
}
# EEX3-FUNCTION release_e266 _eex3_pkg_install_manual
_eex3_pkg_install_manual() {
    test "$#" -gt 0 || return 0;
    local os_id rc=0;
    os_id=$(detect_os 2> /dev/null || echo unknown);
    install -d -m 0700 "$E152_DIAG_DIR" 2> /dev/null || true;
    { 
        echo "[$(date -Is 2> /dev/null || date)] os=$os_id packages=$*";
        export DEBIAN_FRONTEND=noninteractive;
        case "$os_id" in 
            debian | ubuntu)
                apt-get -o DPkg::Lock::Timeout=120 -o Acquire::Retries=3 update -y || rc=$?;
                test "$rc" -ne 0 || apt-get -o DPkg::Lock::Timeout=120 -o Acquire::Retries=3 install -y -- "$@" || rc=$?
            ;;
            centos | rhel | fedora | rocky | almalinux)
                if command -v dnf > /dev/null 2>&1; then
                    dnf -y install "$@" || rc=$?;
                else
                    if command -v yum > /dev/null 2>&1; then
                        yum -y install "$@" || rc=$?;
                    else
                        rc=127;
                    fi;
                fi
            ;;
            *)
                rc=2
            ;;
        esac;
        echo "result=$rc"
    } >> "$E152_PACKAGE_LOG" 2>&1;
    if test "$rc" -ne 0; then
        error "软件包安装失败；日志：$E152_PACKAGE_LOG";
        tail -n 40 "$E152_PACKAGE_LOG" 2> /dev/null | sed 's/^/    /' 1>&2 || true;
        return "$rc";
    fi
}
# EEX3-FUNCTION release_e266 _eex3_post_upgrade_status
_eex3_post_upgrade_status() {
    local rc=0 name fn;
    for name in workflow item28 small-bbr mtu buffer xray recovery ssh;
    do
        case "$name" in 
            workflow)
                fn=_eex3_workflow_verify
            ;;
            item28)
                fn=_eex3_item28_components_verify
            ;;
            small-bbr)
                fn=_eex3_mode3f2_verify
            ;;
            mtu)
                fn=_eex3_mtu_final_verify
            ;;
            buffer)
                fn=_eex3_buffer_status_verify
            ;;
            xray)
                fn=_eex7_xray_live_verify
            ;;
            recovery)
                fn=_eex7_recovery_status_verify
            ;;
            ssh)
                fn=_eex3_ssh_readonly_audit
            ;;
        esac;
        if "$fn" > /dev/null 2>&1; then
            printf '%s=PASS\n' "$name";
        else
            printf '%s=FAIL\n' "$name";
            rc=1;
        fi;
    done;
    printf 'external_ssh_connection=not-testable-from-local-probe\n';
    printf 'external_proxy_connection=not-testable-from-local-probe\n';
    return "$rc"
}
