# EEX3-FUNCTION release_e266 _eex3_restore_service_all
_eex3_restore_service_all() {
    local unit="$1" enabled="$2" active="$3" rc=0 now;
    case "$enabled" in 
        enabled | enabled-runtime | linked | linked-runtime | alias | indirect)
            systemctl enable "$unit" > /dev/null 2>&1 || rc=1
        ;;
