# EEX3-FUNCTION release_e266 _eex3_retention_e214_prune_root
_eex3_retention_e214_prune_root() {
    local requested_root="$1" marker="${2:-}" keep="${XRAY_E214_TX_KEEP:-12}";
    local root real row pid expected actual backup child rc=0 marker_refs=0;
    local marker_lines=0 marker_bad=0;
    local protected=' ';
    [[ "$keep" =~ ^[0-9]+$ ]] && ((keep >= 12 && keep <= 100)) || keep=12;
    root=$(readlink -f -- "$requested_root" 2> /dev/null || true);
    test -n "$root" && test -d "$root" || return 0;
    if test -n "$marker" && { 
        test -e "$marker" || test -L "$marker"
    }; then
        test -f "$marker" && test ! -L "$marker" && test -r "$marker" && test -s "$marker" || { 
            warn "恢复标记异常，停止清理整个事务根：$marker" 1>&2;
            return 1
        };
        while IFS= read -r backup; do
            marker_lines=$((marker_lines + 1));
            real=$(readlink -f -- "$backup" 2> /dev/null || true);
            case "$real" in 
                "$root"/*)
                    child=${real#"$root"/};
                    child=${child%%/*};
                    if test -n "$child"; then
                        protected+="$root/$child ";
                        marker_refs=$((marker_refs + 1));
                    else
                        marker_bad=1;
                    fi
                ;;
                *)
                    marker_bad=1
                ;;
            esac;
        done < <(sed -n 's/^backup=//p' "$marker" 2> /dev/null);
        test "$marker_lines" -gt 0 && test "$marker_bad" -eq 0 && test "$marker_refs" -eq "$marker_lines" || { 
            warn "恢复标记含有空、越界或无效快照路径，停止清理：$marker" 1>&2;
            return 1
        };
    fi;
    while IFS='	' read -r _ row; do
        test -n "$row" || continue;
        real=$(readlink -f -- "$row" 2> /dev/null || true);
        case "$real" in 
            "$root"/*)

            ;;
            *)
                rc=1;
                continue
            ;;
        esac;
        [[ "$protected" == *" $real "* ]] && continue;
        if test -e "$real/.preserve.env" || test -L "$real/.preserve.env"; then
            if ! test -f "$real/.preserve.env" || test -L "$real/.preserve.env" || ! test -r "$real/.preserve.env" || ! test -s "$real/.preserve.env"; then
                warn "事务保护标记异常，保守保留快照：$real/.preserve.env" 1>&2;
                rc=1;
            fi;
            continue;
        fi;
        if test -e "$real/.active.env" || test -L "$real/.active.env"; then
            if ! test -f "$real/.active.env" || test -L "$real/.active.env" || ! test -r "$real/.active.env" || ! test -s "$real/.active.env"; then
                warn "活动事务标记异常，保守保留快照：$real/.active.env" 1>&2;
                rc=1;
                continue;
            fi;
            pid=$(awk -F= '$1=="pid"{print substr($0,index($0,"=")+1); exit}' "$real/.active.env" 2> /dev/null || true);
            expected=$(awk -F= '$1=="start"{print substr($0,index($0,"=")+1); exit}' "$real/.active.env" 2> /dev/null || true);
            if [[ ! "$pid" =~ ^[1-9][0-9]*$ || ! "$expected" =~ ^[0-9]+$ ]]; then
                warn "活动事务标记字段无效，保守保留快照：$real/.active.env" 1>&2;
                rc=1;
                continue;
            fi;
            if kill -0 "$pid" 2> /dev/null; then
                actual=$(_e214_proc_start_time "$pid" || true);
                if [[ ! "$actual" =~ ^[0-9]+$ ]]; then
                    warn "无法确认活动事务进程起始时间，保守保留快照：$real" 1>&2;
                    rc=1;
                    continue;
                fi;
                test "$actual" != "$expected" || continue;
            fi;
        fi;
        rm -rf -- "${real:?}" 2> /dev/null || rc=1;
    done < <(find "$root" -mindepth 1 -maxdepth 1 -type d -printf '%T@\t%p\n' 2> /dev/null | LC_ALL=C sort -nr | awk -F '\t' -v keep="$keep" 'NR>keep{print $1 "\t" $2}');
    return "$rc"
}
