# EEX3-FUNCTION release_e266 _eex3_route_plan_capture
_eex3_route_plan_capture() {
    local out="${1:-}" client="" family=4 tuple="";
    _eex3_ssh_tuple_validate || { 
        error 'SSH_CONNECTION格式无效；尚未修改MTU。';
        return 1
    };
    test -n "$out" && test ! -L "$out" || return 1;
    tuple=$(_eex3_route_tuple 4 1.1.1.1) || return 1;
    printf '4|1.1.1.1|%s\n' "$tuple" > "$out" || return 1;
    if test -n "${SSH_CONNECTION:-}"; then
        read -r client _ <<< "${SSH_CONNECTION:-}";
        [[ "$client" != *:* ]] || family=6;
        tuple=$(_eex3_route_tuple "$family" "$client") || return 1;
        printf '%s|%s|%s\n' "$family" "$client" "$tuple" >> "$out" || return 1;
    fi;
    chmod 0600 "$out"
}
# EEX3-FUNCTION release_e266 _eex3_route_plan_verify
_eex3_route_plan_verify() {
    local file="${1:-}" family address tuple now count=0;
    test -s "$file" && test -f "$file" && test ! -L "$file" || return 1;
    while IFS='|' read -r family address tuple; do
        case "$family" in 
            4 | 6)

            ;;
            *)
                return 1
            ;;
        esac;
        now=$(_eex3_route_tuple "$family" "$address") || return 1;
        test "$now" = "$tuple" || { 
            error "返回路由发生变化：family=$family address=$address";
            return 1
        };
        count=$((count+1));
    done < "$file";
    test "$count" -gt 0
}
# EEX3-FUNCTION release_e266 _eex3_route_tuple
_eex3_route_tuple() {
    local family="${1:-4}" address="${2:-1.1.1.1}" raw="";
    case "$family" in 
        4 | 6)

        ;;
        *)
            return 1
        ;;
    esac;
    [[ "$address" =~ ^[0-9A-Fa-f:.]+$ ]] || return 1;
    raw=$(ip "-$family" route get "$address" 2> /dev/null) || return 1;
    awk '
      NR==1 {
        if($1 ~ /^(blackhole|unreachable|prohibit|throw|local|broadcast|multicast)$/) exit 1
        dev=""; via="-"; src="-"; table="main"
        for(i=1;i<=NF;i++) {
          if($i=="dev") {dev=$(i+1); n++}
          if($i=="via") via=$(i+1)
          if($i=="src") src=$(i+1)
          if($i=="table") table=$(i+1)
        }
        if(n!=1 || dev !~ /^[A-Za-z0-9_.:@-]+$/ || dev=="lo") exit 1
        printf "%s|%s|%s|%s\n",dev,via,src,table
        ok=1
      }
      END{if(!ok)exit 1}
    ' <<< "$raw"
}
# EEX3-FUNCTION release_e266 _eex3_scoped_archive_self_test
_eex3_scoped_archive_self_test() {
    ( local d names rc=0 EEX3_PRESERVE_SSH=1;
    d=$(mktemp -d /tmp/eex3-tar-scope.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    mkdir -p "$d/src/etc/ssh" "$d/src/etc/sysctl.d" "$d/src/etc/systemd/system/sockets.target.wants" "$d/dst";
    printf 'old-ssh\n' > "$d/src/etc/ssh/sshd_config";
    printf 'network\n' > "$d/src/etc/sysctl.d/99-test.conf";
    ln -s /lib/systemd/system/ssh.socket "$d/src/etc/systemd/system/sockets.target.wants/ssh.socket";
    tar -C "$d/src" -czf "$d/files.tar" etc || return 1;
    names=$(_eex3_scoped_tar -tf "$d/files.tar") || return 1;
    if grep -E 'sshd_config|ssh.socket' <<< "$names"; then
        rc=1;
    fi;
    grep -Fq etc/sysctl.d/99-test.conf <<< "$names" || rc=1;
    _eex3_scoped_tar -C "$d/dst" -xpf "$d/files.tar" || rc=1;
    test ! -e "$d/dst/etc/ssh/sshd_config" || rc=1;
    test "$(< "$d/dst/etc/sysctl.d/99-test.conf")" = network || rc=1;
    return "$rc" )
}
# EEX3-FUNCTION release_e266 _eex3_scoped_tar
_eex3_scoped_tar() {
    local pattern;
    local -a filters=();
    if _eex3_ssh_control_preserved; then
        while IFS= read -r pattern; do
            filters+=("--exclude=$pattern" "--exclude=./$pattern");
        done < <(_eex3_ssh_tar_patterns);
    fi;
    command tar "${filters[@]}" "$@"
}
# EEX3-FUNCTION release_e266 _eex3_script_entries_install
_eex3_script_entries_install() {
    ( local source="${1:-$SCRIPT_PATH}" tx="${2:-}" target snap tmp="" fixed ready=0 committed=0 rollback_rc=0;
    local -a targets=();
    shift 2 || return 1;
    targets=("$@");
    test "${#targets[@]}" -gt 0 && test -r "$source" && test -d "$tx" && test ! -L "$tx" || return 1;
    _eex6_release_artifact_verify "$source" || return 1;
    fixed="$tx/release-source.sh";
    install -m 0755 "$source" "$fixed" && bash -n "$fixed" || return 1;
    for target in "${targets[@]}";
    do
        [[ "$target" == /* && "$target" != / && "$target" != *'/../'* ]] || return 1;
        if test -e "$target" || test -L "$target"; then
            test -f "$target" || test -L "$target" || return 1;
        fi;
        snap="$tx/$(printf '%s' "$target" | sha256sum | awk '{print $1}')";
        _e135_snapshot_file "$target" "$snap" || return 1;
    done;
    ready=1;
    function _eex3_entry_exit () 
    { 
        local status="${1:-1}" dst snap;
        trap - EXIT HUP INT TERM;
        test -z "$tmp" || rm -f -- "$tmp";
        if test "$ready" = 1 && test "$committed" != 1; then
            for dst in "${targets[@]}";
            do
                snap="$tx/$(printf '%s' "$dst" | sha256sum | awk '{print $1}')";
                _e135_restore_file "$dst" "$snap" || rollback_rc=1;
                _e214_snapshot_matches "$dst" "$snap" || rollback_rc=1;
            done;
            if test "$rollback_rc" != 0; then
                _e214_mark_critical self-install "$tx" 'EEX3 script entry rollback failed' || true;
            fi;
            test "$status" -ne 0 || status=1;
        fi;
        exit "$status"
    };
    trap '_eex3_entry_exit $?' EXIT;
    trap 'exit 129' HUP;
    trap 'exit 130' INT;
    trap 'exit 143' TERM;
    for target in "${targets[@]}";
    do
        _e214_ensure_parent_dir "$target" || return 1;
        tmp=$(mktemp --tmpdir="${target%/*}" '.eex3-entry.XXXXXX') || return 1;
        install -o 0 -g 0 -m 0755 "$fixed" "$tmp" || return 1;
        bash -n "$tmp" || return 1;
        mv -fT -- "$tmp" "$target" || return 1;
        tmp="";
        _eex3_script_entry_verify "$fixed" "$target" || return 1;
    done;
    committed=1;
    trap - EXIT HUP INT TERM )
}
# EEX3-FUNCTION release_e266 _eex3_script_entry_verify
_eex3_script_entry_verify() {
    local source="${1:-}" target="${2:-}" metadata;
    test -n "$source" || source=$(_eex6_release_source) || return 1;
    test -f "$target" && test ! -L "$target" && test -x "$target" || { 
        error "入口类型或执行权限错误：$target";
        return 1
    };
    metadata=$(stat -c '%a:%u:%g' "$target") || return 1;
    test "$metadata" = 755:0:0 || { 
        error "入口权限错误：file=$target actual=$metadata expected=755:0:0";
        return 1
    };
    cmp -s "$source" "$target" || { 
        error "入口字节校验失败：$target";
