# EEX3-FUNCTION release_e266 _eex3_service_plan_validate
_eex3_service_plan_validate() {
    local plan="$1" line unit load enabled active sources prior='' count=0;
    test -f "$plan" && test ! -L "$plan" && test -s "$plan" || return 1;
    if grep -Eq '^#EEX5-SERVICE-PLAN-NOOP\|scope=(all|e202)$' "$plan"; then
        test "$(wc -l < "$plan")" -eq 1;
        return;
    fi;
    while IFS= read -r line; do
        test "$(awk -F'|' '{print NF}' <<< "$line")" = 5 || return 1;
        IFS='|' read -r unit load enabled active sources <<< "$line";
        _eex3_unit_name_valid "$unit" && _eex3_service_load_normalize "$load" > /dev/null && _eex3_service_enabled_normalize "$enabled" > /dev/null || return 1;
        case "$active" in 
            active | inactive)

            ;;
            *)
                return 1
            ;;
        esac;
        [[ "$sources" =~ ^[A-Za-z0-9._-]+(,[A-Za-z0-9._-]+)*$ ]] || return 1;
        test -z "$prior" || LC_ALL=C test "$prior" \< "$unit" || return 1;
        prior=$unit;
        count=$((count + 1));
    done < "$plan";
    test "$count" -gt 0
}
