# EEX3-FUNCTION release_e266 _eex3_ssh_policy_digest
_eex3_ssh_policy_digest() {
    local p;
    { 
        printf '%s\n' 'EEX3-SSH-POLICY-V1';
        for p in /etc/fail2ban /etc/ufw /etc/iptables /etc/firewalld;
        do
            if test -d "$p"; then
                find "$p" -xdev -type f -print0 2> /dev/null | sort -z | xargs -0 -r sha256sum 2> /dev/null || return 1;
            else
                if test -e "$p" || test -L "$p"; then
                    return 1;
                else
                    printf 'absent:%s\n' "$p";
                fi;
            fi;
        done;
        for p in /etc/nftables.conf /etc/default/ssh /etc/pam.d/sshd;
        do
            if test -f "$p"; then
                sha256sum "$p" || return 1;
            else
                if test -e "$p" || test -L "$p"; then
                    return 1;
                else
                    printf 'absent:%s\n' "$p";
                fi;
            fi;
        done
    } | _eex3_hash_stream
