    local unit raw;
    for unit in ssh.service sshd.service ssh.socket sshd.socket fail2ban.service nftables.service firewalld.service ufw.service netfilter-persistent.service;
    do
        printf '%s|' "$unit";
        raw=$(systemctl show "$unit" -p LoadState -p ActiveState -p UnitFileState --value 2> /dev/null || true);
        test -n "$raw" || return 1;
        printf '%s' "$raw" | tr '\n' ' ';
