# EEX3-FUNCTION release_e266 _eex3_upgrade_classify
_eex3_upgrade_classify() {
    local version="${1:-}" release="${2:-}" generation known;
    [[ "$version" =~ ^(198|199)e[1-9][0-9]{0,2}$ ]] || { 
        printf 'unsupported\n';
        return 1
    };
    if test -n "$release"; then
        test "$version" = "$EEX3_ABI_VERSION" || { 
            printf 'unsupported\n';
            return 1
        };
        if test "$release" = "$EEX3_BUILD_ID"; then
            printf 'current\n';
            return 0;
        fi;
        for known in "${EEX9_COMPAT_RELEASES[@]}";
        do
            if test "$release" = "$known"; then
                printf 'upgrade\n';
                return 0;
            fi;
        done;
        printf 'unsupported\n';
        return 1;
    fi;
    generation=${version##*e};
    if ((generation <= 262)) || test "$version" = "$EEX3_ABI_VERSION"; then
        printf 'upgrade\n';
        return 0;
    fi;
    printf 'unsupported\n';
