            test "$stage" = none || rc=1;
            grep -qx committed "$order" || rc=1;
            if grep -qx rollback "$order"; then
                rc=1;
            fi;
            awk '/^snapshot$/{s=NR}/^hot$/{h=NR}/^item28$/{a=NR}/^mode3f2$/{b=NR}/^mtu1350$/{m=NR}/^final$/{f=NR}/^committed$/{c=NR}END{exit !(s<h&&h<b&&b<a&&a<m&&m<f&&f<c)}' "$order" || rc=1;
        else
            test "$stage" != none || { 
                printf 'success-path failed\n';
                rc=1
            };
            test "$(grep -c '^rollback$' "$order")" = 1 || rc=1;
            if grep -qx committed "$order"; then
                rc=1;
            fi;
        fi;
        test "$(grep -c '^close$' "$order")" = 1 || rc=1;
        if grep -q UNEXPECTED "$order"; then
            rc=1;
        fi;
    done;
    return "$rc" )
}
# EEX3-FUNCTION release_eex5 _eex5_boot_state_restore_self_test
_eex5_boot_state_restore_self_test() {
