    EEX5_RESTORE_SERVICE_PLAN="$d/plan";
    _eex3_service_plan_build "$d/system" "$EEX5_RESTORE_SERVICE_PLAN" e202 || return 1;
    function systemctl () 
    { 
        case "$1" in 
            show)
                printf '%s\n' "$mock_unit_load"
            ;;
            is-enabled)
                printf '%s\n' "$mock_unit_enabled"
            ;;
            is-active)
                printf '%s\n' "$mock_unit_active"
            ;;
