    _e159_restore_service xray-small-bbr-e202.service enabled inactive || rc=1;
    test "$(wc -l < "$d/calls")" = 1 || rc=1;
    EEX5_RESTORE_SERVICE_PLAN='';
    mock_unit_load=not-found;
    mock_unit_enabled=disabled;
    mock_unit_active=active;
    _e266_service_state_apply vanished.service not-found disabled inactive || rc=1;
    test "$mock_unit_active" = inactive || rc=1;
    grep -Fxq 'stop vanished.service' "$d/calls" || rc=1;
    ! grep -q UNEXPECTED "$d/calls" || rc=1;
    return "$rc" )
}
