    test ! -e "$d/writes" || rc=1;
    printf '%s\n' 'xray-network-e159.service||inactive' 'xray-accel-e125.service||inactive' > "$tx/services.before";
    ( cd "$tx" && sha256sum paths.tsv services.before "files/$id.absent" > seal.sha256 ) || return 1;
    function systemctl () 
    { 
        case "$1" in 
            show)
                printf 'loaded\n'
            ;;
            is-enabled)
                printf 'enabled\n'
            ;;
            is-active)
                printf 'active\n'
            ;;
            *)
                printf '%s\n' "$*" >> "$d/writes";
                return 99
            ;;
        esac
    };
    if _eex3_network_restore_scoped "$tx" > "$d/diag" 2>&1; then
