# EEX3-FUNCTION release_eex5 _eex5_network_service_plan
_eex5_network_service_plan() {
    local tx="$1" plan="$2" guard="$3" p id line unit enabled active fields load n=0;
    local -A paths=() seen=();
    _e159_network_tx_verify "$tx" || return 1;
    _eex5_network_receipt_member "$tx" paths.tsv && _eex5_network_receipt_member "$tx" services.before || return 1;
    : > "$plan";
    : > "$guard";
    while IFS='|' read -r p id; do
        test -n "$p" || continue;
        [[ "$p" == /* && "$id" =~ ^[0-9a-f]{64}$ ]] || return 1;
        test "$id" = "$(printf '%s' "$p" | sha256sum | awk '{print $1}')" || return 1;
        test "${paths[$p]+set}" != set || return 1;
        paths[$p]=$id;
    done < "$tx/paths.tsv";
    while IFS= read -r line || test -n "$line"; do
        n=$((n+1));
        test -n "$line" || continue;
        fields=${line//[^|]/};
        test "${#fields}" = 2 && [[ "$line" != *$'\r'* ]] || return 1;
        IFS='|' read -r unit enabled active <<< "$line";
        case "$unit" in 
            xray-network-e159.service | xray-network-e159.timer | xray-network-e156.service | xray-network-e156.timer | xray-network-e154.service | xray-network-e154.timer | xray-network-e152.service | xray-network-e152.timer | xray-hw-tweaks.service | xray-accel-e125.service | xray-accel-e126.service)

            ;;
            *)
                _eex5_service_error "$tx" services.before "$n" "$unit" scope unsupported-network-unit;
                return 1
            ;;
        esac;
        test "${seen[$unit]+set}" != set || return 1;
        seen[$unit]=1;
        active=$(_eex3_service_active_normalize "$active") || return 1;
        load='';
        if test -z "$enabled"; then
            test "$active" = inactive || return 1;
            p="/etc/systemd/system/$unit";
            id=${paths[$p]-};
            if test -n "$id"; then
                _eex5_network_receipt_member "$tx" "files/$id.absent" && test ! -e "$tx/files/$id.present" && test ! -L "$tx/files/$id.present" || { 
                    _eex5_service_error "$tx" services.before "$n" "$unit" enabled ambiguous-network-empty;
                    return 1
                };
                load=not-found;
                enabled=disabled;
            else
                case "$unit" in 
                    xray-accel-e125.service | xray-accel-e126.service)

                    ;;
                    *)
                        return 1
                    ;;
                esac;
                _eex5_unit_missing_now "$unit" || { 
                    _eex5_service_error "$tx" services.before "$n" "$unit" enabled uncaptured-unit-not-missing;
                    return 1
                };
                printf '%s\n' "$unit" >> "$guard" || return 1;
                continue;
            fi;
        else
            _eex3_service_enabled_normalize "$enabled" > /dev/null || return 1;
            if test "$enabled" = not-found; then
                load=not-found;
                enabled=disabled;
                test "$active" = inactive || return 1;
            fi;
        fi;
        printf '%s|%s|%s|%s|services.before\n' "$unit" "$load" "$enabled" "$active" >> "$plan" || return 1;
    done < "$tx/services.before";
    test "${#seen[@]}" -gt 0 || return 1;
    test -s "$plan" || printf '#EEX5-SERVICE-PLAN-NOOP|scope=all\n' > "$plan";
    LC_ALL=C sort -o "$plan" "$plan" && chmod 0600 "$plan" "$guard" && _eex3_service_plan_validate "$plan"
}
