# EEX3-FUNCTION release_eex5 _eex5_service_file_checked
_eex5_service_file_checked() {
    local root="$1" base="$2" seal line hash path actual found=0;
    test -f "$root/$base" && test ! -L "$root/$base" && test -r "$root/$base" || return 1;
    if test "$base" != files.tar; then
        test "$(stat -c %s "$root/$base")" -le 2097152 || return 1;
    fi;
    case "$base" in 
        services.env | present.list | absent.list | runtime-sysctl.env)
            seal=control.sha256
        ;;
        e214-mtu-services.env)
            seal=e214-mtu-runtime.sha256
        ;;
        e5-services.env)
            seal=e5-services.sha256
        ;;
        *-services.env)
            seal="${base%.env}.sha256"
        ;;
        files.tar)
            seal=archive.sha256
        ;;
        *)
            return 1
        ;;
    esac;
    test -f "$root/$seal" && test ! -L "$root/$seal" && test -r "$root/$seal" || return 1;
    actual=$(sha256sum -- "$root/$base") || return 1;
    actual=${actual%% *};
    while IFS= read -r line || test -n "$line"; do
        [[ "$line" =~ ^([a-fA-F0-9]{64})[[:space:]][\ \*](.+)$ ]] || continue;
        hash=${BASH_REMATCH[1]};
        path=${BASH_REMATCH[2]};
        test "${path##*/}" = "$base" || continue;
        test "${hash,,}" = "$actual" || return 1;
        found=$((found + 1));
    done < "$root/$seal";
    test "$found" -eq 1
}
