# EEX3-FUNCTION release_eex6 _eex6_step
_eex6_step() {
    local stage="$1" action="$2" code=0;
    shift 2;
    _eex6_step_record BEGIN "$stage" 0 "$action" || { 
        error "无法记录子步骤，未执行：$stage";
        return 1
    };
    if "$action" "$@"; then
        _eex6_step_record OK "$stage" 0 "$action" || { 
            error "无法记录子步骤结果：$stage";
            return 1
        };
        return 0;
    else
        code=$?;
    fi;
    _eex6_step_record FAIL "$stage" "$code" "$action" || true;
    return "$code"
}
# EEX3-FUNCTION release_eex6 _eex6_step_record
_eex6_step_record() {
    local event="$1" stage="$2" code="$3" fn="$4" path="${EEX6_TRACE_LOG:-}" line;
    [[ "$event" =~ ^(BEGIN|OK|FAIL)$ && "$stage" =~ ^[a-z0-9][a-z0-9-]{0,79}$ && "$code" =~ ^[0-9]{1,3}$ && "$fn" =~ ^[A-Za-z_][A-Za-z_0-9-]*$ ]] || return 1;
    line="time=$(date -Is)|release=$EEX3_BUILD_ID|event=$event|stage=$stage|rc=$code|function=$fn";
    if test -n "$path"; then
        test -f "$path" && test ! -L "$path" && test -w "$path" && test "$(stat -c %u "$path")" = "$EUID" || return 1;
        printf '%s\n' "$line" >> "$path" || return 1;
    fi;
    case "$event" in 
        BEGIN)
            info "子步骤：$stage"
        ;;
        FAIL)
            error "子步骤失败：stage=$stage function=$fn rc=$code；日志=${path:-当前终端}"
        ;;
    esac;
    return 0
}
# EEX3-FUNCTION release_eex6 _eex6_upgrade_diagnose
_eex6_upgrade_diagnose() {
    local source path unit;
    source=$(_eex6_release_source) || return 1;
    printf '[release]\n';
    sha256sum -- "$source";
    _eex6_entry_check || return 1;
    printf 'installed_abi=%s installed_release=%s\n' "$(_e242_installed_version 2> /dev/null || true)" "$(_eex3_installed_release_readonly 2> /dev/null || true)";
    printf '[system]\n';
    uname -srmo;
    sed -n '/^\(ID\|VERSION_ID\|PRETTY_NAME\)=/p' /etc/os-release;
    bash --version | sed -n '1p';
    systemctl --version | sed -n '1p' || true;
    printf '[services]\n';
    systemctl --no-pager show ssh.service sshd.service ssh.socket fail2ban.service xray.service xray-small-bbr-e202.service xray-mtu-e214.service xray-mtu-e214.timer xray-network-e159.service xray-network-e159.timer -p Id -p LoadState -p UnitFileState -p ActiveState -p SubState -p Result -p ExecMainStatus || true;
    printf '[recovery-markers]\n';
    for path in "$E214_CRITICAL_MARKER" "$E202_CRITICAL_MARKER";
    do
        printf 'file=%s\n' "$path";
        if test -f "$path" && test ! -L "$path"; then
            sed -n '/^\(version\|time\|operation\|backup\|restore_snapshot\|reason\)=/p' "$path";
        else
            printf 'absent\n';
        fi;
    done;
    printf '[stage-logs]\n';
    for path in "$E242_AUTO_LOG" "$E214_HOT_LOG";
    do
        printf 'file=%s\n' "$path";
        if test -f "$path" && test ! -L "$path"; then
            tail -n 140 "$path";
        else
            printf 'absent\n';
        fi;
    done;
    printf '[disk]\n';
    df -h / || true;
    df -i / || true
}
