            enabled)
                mock_load=loaded;
                mock_enabled=enabled;
                mock_active=active
            ;;
            static)
                mock_load=loaded;
                mock_enabled=static;
                mock_active=inactive
            ;;
        esac;
        _eex3_service_plan_build "$d/system" "$d/plan" all || return 1;
        grep -Fq "vnstat.service|$mock_load|$mock_enabled|$mock_active|services.env,e8-optional-preserve" "$d/plan" || return 1;
        local EEX5_RESTORE_SERVICE_PLAN="$d/plan";
        _e266_service_state_apply vnstat.service '' '' inactive || return 1;
    done;
    mock_active=active;
    if _e266_service_state_apply vnstat.service '' '' inactive; then
        return 1;
    fi;
    cp "$d/plan" "$d/sentinel" || return 1;
    mock_error=1;
    if _eex3_service_plan_build "$d/system" "$d/plan" all; then
        return 1;
    fi;
    cmp -s "$d/plan" "$d/sentinel" || return 1;
    mock_error=0;
    printf 'etc/vnstat.conf\n' >> "$d/system/present.list";
    _eex8_test_seal "$d/system" || return 1;
    if _eex3_service_plan_build "$d/system" "$d/plan" all; then
        return 1;
    fi;
    cmp -s "$d/plan" "$d/sentinel" && test ! -e "$d/forbidden" )
}
# EEX3-FUNCTION release_eex8 _eex8_plan_archive_index
_eex8_plan_archive_index() {
    local root="$1" work="$2";
