    : > "$work/archive.verbose";
    if test -s "$root/files.tar"; then
        _eex5_service_file_checked "$root" files.tar || return 1;
        LC_ALL=C tar -tf "$root/files.tar" --quoting-style=literal > "$work/archive.names" || return 1;
        LC_ALL=C tar -tvf "$root/files.tar" --numeric-owner --full-time --quoting-style=literal > "$work/archive.verbose" || return 1;
        test "$(wc -l < "$work/archive.names")" = "$(wc -l < "$work/archive.verbose")" || return 1;
    fi;
    : > "$work/archive.ready"
}
# EEX3-FUNCTION release_eex8 _eex8_service_plan_apply_base
_eex8_service_plan_apply_base() {
    local plan="$1" unit load enabled active sources rc=0;
    _eex3_service_plan_validate "$plan" || return 1;
    grep -q '^#EEX5-SERVICE-PLAN-NOOP|' "$plan" && return 0;
    systemctl daemon-reload > /dev/null 2>&1 || return 1;
    while IFS='|' read -r unit load enabled active sources; do
        if ! _e266_service_state_apply "$unit" "$load" "$enabled" "$active"; then
            error "EEX5服务恢复读回失败：unit=$unit load=$load enabled=$enabled active=$active sources=$sources";
            rc=1;
        fi;
    done < "$plan";
    return "$rc"
}
# EEX3-FUNCTION release_eex8 _eex8_service_plan_build_base
_eex8_service_plan_build_base() {
