        _eex5_service_file_checked "$root" "$base" || { 
            _eex5_service_error "$root" "$base" 0 - checksum missing-or-invalid-receipt;
            return 1
        };
        n=0;
        while IFS= read -r line || test -n "$line"; do
            n=$((n + 1));
            test -n "$line" || continue;
            [[ "$line" != *$'\r'* ]] || { 
                _eex5_service_error "$root" "$base" "$n" - row CRLF;
                return 1
            };
            fields=${line//[^|]/};
            unit=;
            load=;
            enabled=;
            active=;
