                3)
                    IFS='|' read -r unit load enabled active <<< "$line"
                ;;
                *)
                    _eex5_service_error "$root" "$base" "$n" - row unsupported-column-count;
                    return 1
                ;;
            esac;
            _eex3_unit_name_valid "$unit" || { 
                _eex5_service_error "$root" "$base" "$n" "$unit" name invalid-unit;
                return 1
            };
