            enableds[$unit]='';
            actives[$unit]='';
            sources[$unit]='';
            firsts[$unit]="$base:$n";
        fi;
        for path in load enabled active;
        do
            case "$path" in 
                load)
                    normalized=$load;
                    old=${loads[$unit]};
                    test "$normalized" != unspecified || continue;
                    test "$old" != unspecified || old=''
                ;;
                enabled)
                    normalized=$enabled;
                    old=${enableds[$unit]}
                ;;
                active)
                    normalized=$active;
                    old=${actives[$unit]}
