            esac;
            test -n "$normalized" || continue;
            if test -n "$old" && test "$old" != "$normalized"; then
                _eex5_service_error "$root" "$base" "$n" "$unit" "$path" "contradiction(first=${field_sources[$unit:$path]:-${firsts[$unit]}}:$old next=$normalized)";
                return 1;
            fi;
            test -n "$old" || field_sources[$unit:$path]="$base:$n";
            case "$path" in 
                load)
                    loads[$unit]=$normalized
                ;;
                enabled)
                    enableds[$unit]=$normalized
                ;;
                active)
                    actives[$unit]=$normalized
                ;;
            esac;
        done;
        case ",${sources[$unit]}," in 
            *",$base,"*)

            ;;
            *)
                sources[$unit]="${sources[$unit]:+${sources[$unit]},}$base"
            ;;
        esac;
    done;
    : > "$work/plan";
    for unit in "${!firsts[@]}";
    do
        load=${loads[$unit]};
        enabled=${enableds[$unit]};
        active=${actives[$unit]};
        if test -z "$enabled"; then
            if test "$load" = not-found; then
                enabled=disabled;
            else
