        fi;
        if test "${blank_enabled[$unit]+set}" = set && [[ ",${sources[$unit]}," != *,e8-optional-preserve,* ]]; then
            test "$enabled" = disabled && test "$load" = not-found || { 
                _eex5_service_error "$root" "${firsts[$unit]}" 0 "$unit" enabled ambiguous-empty-state;
                return 1
            };
        fi;
        if test -z "$active"; then
            test "$load" = not-found && test "$enabled" = disabled || { 
                _eex5_service_error "$root" "${firsts[$unit]}" 0 "$unit" active unproven-empty;
                return 1
            };
            active=inactive;
        fi;
        if test "$load" = not-found; then
            test "$enabled" = disabled && test "$active" = inactive || { 
                _eex5_service_error "$root" "${firsts[$unit]}" 0 "$unit" load contradictory-not-found;
                return 1
            };
        fi;
        if test "$load" = masked; then
            case "$enabled:$active" in 
                masked:inactive | masked-runtime:inactive)

                ;;
                *)
                    _eex5_service_error "$root" "${firsts[$unit]}" 0 "$unit" load contradictory-mask;
                    return 1
                ;;
            esac;
        fi;
        if test "${oneshot_proof[$unit]:-0}" = 1 && test "$load" != not-found; then
            sources[$unit]="${sources[$unit]},e8-sealed-oneshot";
        fi;
        test "$load" != unspecified || load='';
        printf '%s|%s|%s|%s|%s\n' "$unit" "$load" "$enabled" "$active" "${sources[$unit]}" >> "$work/plan" || return 1;
        eligible=$((eligible + 1));
    done;
    if test "$eligible" -eq 0; then
        printf '#EEX5-SERVICE-PLAN-NOOP|scope=%s\n' "$scope" > "$work/plan";
    fi;
