# EEX3-FUNCTION release_eex8 _eex8_service_snapshot_observe
_eex8_service_snapshot_observe() {
    local unit="$1" load enabled active;
    load=$(systemctl show "$unit" -p LoadState --value 2> /dev/null) || return 1;
    enabled=$(systemctl is-enabled "$unit" 2> /dev/null || true);
    active=$(systemctl is-active "$unit" 2> /dev/null || true);
    case "$load" in 
        not-found)
            enabled=disabled;
            case "$active" in 
                inactive | failed | unknown)
                    active=inactive
                ;;
                *)
                    return 1
                ;;
            esac
        ;;
        loaded | masked)
            _eex3_service_enabled_normalize "$enabled" > /dev/null && _eex3_service_active_normalize "$active" > /dev/null || return 1
        ;;
        *)
            return 1
        ;;
    esac;
    printf '%s|%s|%s|%s\n' "$unit" "$load" "$enabled" "$active"
}
# EEX3-FUNCTION release_eex8 _eex8_service_state_apply_base
_eex8_service_state_apply_base() {
    local unit="$1" load="${2:-}" enabled="${3:-}" active="${4:-}" row ignored source;
    _eex3_ssh_control_preserved && _eex3_ssh_unit_protected "$unit" && return 0;
    if test -n "${EEX5_RESTORE_SERVICE_GUARD:-}" && grep -Fxq "$unit" "$EEX5_RESTORE_SERVICE_GUARD"; then
        _eex5_unit_missing_now "$unit";
        return;
    fi;
