        row=$(awk -F'|' -v u="$unit" '$1==u{print;n++}END{if(n!=1)exit 1}' "$EEX5_RESTORE_SERVICE_PLAN") || return 1;
        IFS='|' read -r ignored load enabled active source <<< "$row";
    fi;
    if test "$enabled" = not-found; then
        case "$load" in 
            '' | not-found)
                load=not-found;
                enabled=disabled
            ;;
            *)
                return 1
            ;;
        esac;
    fi;
    test -n "$enabled" || { 
        error "EEX5拒绝无已验证服务计划的空状态恢复：$unit";
        return 1
    };
    active=$(_eex3_service_active_normalize "$active") || return 1;
    _eex3_service_state_apply_all "$unit" "$load" "$enabled" "$active"
}
# EEX3-FUNCTION release_eex8 _eex8_snapshot_row
_eex8_snapshot_row() {
    local unit="$1" cache="${EEX8_CAPTURE_CACHE:-}" row file load enabled active;
    _eex3_unit_name_valid "$unit" || return 1;
    if test -n "$cache"; then
        test -d "$cache" && test ! -L "$cache" || return 1;
        file="$cache/$unit.row";
        if test -f "$file" && test ! -L "$file"; then
            cat -- "$file";
            return;
        fi;
    fi;
    row=$(_eex8_service_snapshot_observe "$unit") || { 
        test -z "$cache" || : > "$cache/failed";
        return 1
    };
    if test -n "$cache"; then
        printf '%s\n' "$row" > "$file" && chmod 0600 "$file" || { 
            : > "$cache/failed";
            return 1
        };
    fi;
    printf '%s\n' "$row"
}
# EEX3-FUNCTION release_eex8 _eex8_system_snapshot_capture_base
_eex8_system_snapshot_capture_base() {
    _eex5_snapshot_capture_abi "$1" && _eex5_snapshot_catalog_capture "$1"
}
# EEX3-FUNCTION release_eex8 _eex8_test_reported_snapshot
_eex8_test_reported_snapshot() {
    local root="$1" kind="$2" unit;
    case "$kind" in 
        vnstat)
            _eex5_test_snapshot "$root" before || return 1;
            printf 'vnstat.service||inactive\n' >> "$root/services.env";
            _eex8_test_seal "$root"
        ;;
        network)
            unit=xray-network-e159.service;
            _eex5_test_snapshot "$root" before || return 1;
            sed -i 's/xray-network-e159.service|enabled|inactive/xray-network-e159.service|enabled|active/' "$root/e159-services.env";
            _eex8_test_unit_archive "$root" "$unit"
        ;;
        mtu)
            unit=xray-mtu-e214.service;
            _eex5_test_snapshot "$root" outer || return 1;
            printf '%s|loaded|enabled|inactive\n' "$unit" >> "$root/e204-services.env";
            printf '%s|loaded|enabled|inactive\n' "$unit" > "$root/e214-mtu-services.env";
            printf '%s|loaded|enabled|active\n' "$unit" > "$root/e5-services.env";
            _eex8_test_unit_archive "$root" "$unit"
        ;;
        *)
            return 1
        ;;
    esac
}
# EEX3-FUNCTION release_eex8 _eex8_test_seal
_eex8_test_seal() {
    ( local f;
    cd "$1" || return 1;
    sha256sum present.list absent.list runtime-sysctl.env services.env > control.sha256 || return 1;
    for f in e159-services.env e202-services.env e204-services.env e5-services.env;
    do
        test ! -f "$f" || sha256sum "$f" > "${f%.env}.sha256" || return 1;
    done;
    test ! -f e214-mtu-services.env || sha256sum e214-mtu-services.env > e214-mtu-runtime.sha256 || return 1;
    test ! -s files.tar || sha256sum files.tar > archive.sha256 )
}
# EEX3-FUNCTION release_eex8 _eex8_test_unit_archive
_eex8_test_unit_archive() {
    local root="$1" unit="$2" type="${3:-oneshot}" remain="${4:-no}" tree="$1/tree" member;
    member="etc/systemd/system/$unit";
    mkdir -p "$tree/etc/systemd/system" || return 1;
    printf '[Unit]\nDescription=fixture\n[Service]\nType=%s\nRemainAfterExit=%s\nExecStart=/bin/true\n[Install]\nWantedBy=multi-user.target\n' "$type" "$remain" > "$tree/$member";
    printf '%s\n' "$member" > "$root/present.list";
    tar -C "$tree" -czpf "$root/files.tar" -- "$member" || return 1;
    _eex8_test_seal "$root"
}
# EEX3-FUNCTION release_eex8 _eex8_transient_snapshots_self_test
_eex8_transient_snapshots_self_test() {
    ( local d kind unit scope before after;
    d=$(mktemp -d /tmp/eex8-transient.XXXXXX) || return 1;
    trap 'rm -rf -- "$d"' EXIT;
    function _eex3_ssh_control_preserved () 
    { 
        return 1
    };
    function systemctl () 
    { 
        printf '%s\n' "$*" >> "$d/forbidden";
        return 99
    };
    for kind in network mtu;
    do
        _eex8_test_reported_snapshot "$d/$kind" "$kind" || return 1;
        if test "$kind" = network; then
            unit=xray-network-e159.service;
        else
            unit=xray-mtu-e214.service;
        fi;
        before=$(sha256sum "$d/$kind/"*.env "$d/$kind/"*.sha256 "$d/$kind/files.tar") || return 1;
        for scope in all e202;
        do
            _eex3_service_plan_build "$d/$kind" "$d/$kind.$scope" "$scope" || return 1;
            _eex3_service_plan_validate "$d/$kind.$scope" || return 1;
        done;
        grep -Eq "^$unit[|]loaded[|]enabled[|]inactive[|].*,e8-sealed-oneshot$" "$d/$kind.all" || return 1;
        after=$(sha256sum "$d/$kind/"*.env "$d/$kind/"*.sha256 "$d/$kind/files.tar") || return 1;
        test "$before" = "$after" || return 1;
    done;
    test ! -e "$d/forbidden" )
