# >>> EEX3 MODULE: release_eex10
# Module globals

# Module functions
# EEX3-FUNCTION release_eex10 _eex10_brutal_menu
_eex10_brutal_menu() {
    local choice='' target='' rate='' confirm=''
    while true; do
        title '菜单 31：TCP Brutal v2.0.0（手动 / 客户端自动管理）'
        printf '%s\n' \
            '  服务器向客户端发送的数据可使用 Brutal；不自动探测可用带宽。' \
            '  同公网 IP 的全部 TCP 共享速率，包括 SSH；新增/删除只影响新连接。' \
            '  1) 安装 / 升级官方 v2.0.0（DKMS；不启用目标、不重启）' \
            '  2) 添加手动目标 / 调整总速率（持久化）' \
            '  3) 查看手动规则、实际选路与开机恢复状态' \
            '  4) 删除一个手动目标' \
            '  5) 停止全部受管目标（自动 + 手动；不卸载模块）' \
            '  6) 重放手动规则 / 检查漂移' \
            '  7) 恢复未完成的手动事务' \
            '  8) 开启 / 调整客户端自动模式（失活 24 小时清理）' \
            '  9) 查看自动模式状态、客户端和规则验证' \
            ' 10) 关闭自动模式并清理自动记录 / 规则 / 路由' \
            ' 11) 恢复未完成的自动模式事务' \
            '  0) 返回'
        IFS= read -r -p '请选择: ' choice || return 0
        case "$choice" in
            1)
                printf '%s\n' '将下载并校验官方固定提交，安装当前内核 headers、编译工具及 DKMS。'
                IFS= read -r -p '输入 INSTALL-BRUTAL-2.0.0 安装: ' confirm || return 0
                if test "$confirm" = INSTALL-BRUTAL-2.0.0; then _eex10_brutal_run install || true; fi
                ;;
            2)
                IFS= read -r -p '客户端公网 IPv4（单个 IP 或 /32）: ' target || return 0
                IFS= read -r -p '该目标所有连接共享的实测可用带宽（Mbps，无默认值）: ' rate || return 0
                if _eex10_brutal_run plan "$target" "$rate"; then
                    IFS= read -r -p '确认该目标包含 SSH 在内的全部 TCP 受影响，输入 ALL-TCP: ' confirm || return 0
                    if test "$confirm" = ALL-TCP; then _eex10_brutal_run add "$target" "$rate" "$confirm" || true; fi
                fi
                ;;
            3) _eex10_brutal_run status || true ;;
            4)
                IFS= read -r -p '删除哪个手动 IPv4 目标: ' target || return 0
                _eex10_brutal_run del "$target" || true
                ;;
            5)
                IFS= read -r -p '输入 y 停止全部受管目标（外部规则保持原样）: ' confirm || return 0
                if test "$confirm" = y; then _eex10_brutal_run disable || true; fi
                ;;
            6) _eex10_brutal_run reconcile || true ;;
            7) _eex10_brutal_run recover || true ;;
            8)
                printf '%s\n' \
                    '仅支持本脚本的 VLESS + Reality + TCP/raw 公网 IPv4 客户端。' \
                    '通过 Xray GetUsersStats 认证统计与实际连接交叉核对；旧版 Xray 接口不兼容会拒绝。' \
                    '先用选项 1 安装 Brutal v2；本项可能安装 python3-grpcio 并重启一次 Xray。' \
                    '首次发现之后的新建连接生效；不主动换运营商 IP、不强制断线、不改小BBR。' \
                    '约 10 秒检测一次，最多 64 个 IP；/run 内存记录，失活 24 小时清理。' \
                    '同 IP 下所有设备、用户及 SSH 共用该速率；不要填高于实际可用带宽的数值。'
                IFS= read -r -p '每个新公网 IP 统一使用的总速率 Mbps（无默认值）: ' rate || return 0
                IFS= read -r -p '确认上述影响，输入 AUTO-BRUTAL 开启: ' confirm || return 0
                if test "$confirm" = AUTO-BRUTAL; then _eex10_brutal_run auto-enable "$rate" "$confirm" || true; fi
                ;;
            9) _eex10_brutal_run auto-status || true ;;
            10) _eex10_brutal_run auto-disable || true ;;
            11) _eex10_brutal_run auto-recover || true ;;
            0|'') return 0 ;;
            *) warn '无效选项。' ;;
        esac
    done
}
# EEX3-FUNCTION release_eex10 _eex10_brutal_run
_eex10_brutal_run() {
    test -x /usr/bin/python3 || { error '菜单 31 需要 /usr/bin/python3。'; return 1; }
    _eex10_brutal_source | /usr/bin/python3 -c '
import sys
source = sys.stdin.read()
exec(compile(source, "<EEX11-Brutal>", "exec"), {"__name__": "__main__", "EMBEDDED_SOURCE": source})
' "$@"
}
# EEX3-FUNCTION release_eex10 _eex10_brutal_source
_eex10_brutal_source() {
cat <<'EEX10_BRUTAL_PY'
#!/usr/bin/env python3
# EEX10 managed TCP Brutal helper
"""Optional TCP Brutal v2 manager. No global sysctl, SSH or firewall writes.

Control protocol: https://github.com/HyNetworks/tcp-brutal/tree/v2.0.0
The upstream module is named 'brutal', not 'tcp_brutal'. Host destinations
only; /0 and subnet rules intentionally are not exposed by this manager.
"""
import copy
import fcntl
import hashlib
import ipaddress
import json
import os
from pathlib import Path
import re
import shlex
import shutil
import signal
import subprocess
import sys
import tarfile
import tempfile
import time
import urllib.request

VERSION = "2.0.0"
COMMIT = "04e4dc7ae13a4852f0bfe0c8d353e621e429e22e"
SOURCE_SHA256 = "e93a2491d743f4c62f82b04be3e7a52af960b383a01b368e3c63843e8e1ce768"
SOURCE_URL = "https://github.com/HyNetworks/tcp-brutal/archive/" + COMMIT + ".tar.gz"
ROOT = Path("/var/lib/xray-brutal-eex10")
HELPER = Path("/usr/local/libexec/xray-brutal-eex10.py")
UNIT = "xray-brutal-eex10"
UNIT_DIR = Path("/etc/systemd/system")
PROTO, METRIC = 233, 42731
EMPTY = {"schema": 1, "rules": {}}
NOTICE = ("新增/删除只改变新连接的算法选择；旧连接不会被强制断开，删除后仍可能使用旧 Brutal 组。"
          "同一目标 IP 的 SSH 和其他 TCP 流量也在该组内；限速是总和，不是每连接。")


class Refuse(RuntimeError):
    pass


def host_prefix(value):
    try:
        net = ipaddress.ip_network(value, strict=True)
    except ValueError as e:
        raise Refuse("目标必须是单个 IPv4 地址或 /32。") from e
    if net.version != 4 or net.prefixlen != 32:
        raise Refuse("菜单 31 当前只管理单个 IPv4 /32；不接管网段、默认路由或 IPv6。")
    ip = net.network_address
    if ip.is_loopback or ip.is_unspecified or ip.is_multicast or ip.is_link_local or ip.is_reserved:
        raise Refuse("不能使用本地、组播、链路本地或保留地址。")
    return str(net)


def rate_bytes(value):
    # Decimal Mbps, at most three decimals. Match the kernel's real limits.
    if not re.fullmatch(r"(?:0|[1-9][0-9]{0,6})(?:\.[0-9]{1,3})?", str(value)):
        raise Refuse("速率须为 0.5–1000000 Mbps 的十进制数字，最多三位小数。")
    from decimal import Decimal
    rate = int(Decimal(str(value)) * 125000)
    if not 62500 <= rate <= 125000000000:
        raise Refuse("速率超出 Brutal v2 范围：0.5–1000000 Mbps。")
    return rate


def run(args, *, capture=True, timeout=30, check=True, strict_stderr=False):
    env = dict(os.environ, LC_ALL="C", PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin")
    p = subprocess.run(args, text=True, stdout=subprocess.PIPE if capture else None,
                       stderr=subprocess.PIPE if capture else None, env=env, timeout=timeout)
    if check and (p.returncode or (strict_stderr and (p.stderr or "").strip())):
        raise Refuse("命令失败：" + shlex.join(args) + "\n" + (p.stderr or "")[-3000:])
    return (p.stdout or "").strip() if capture else p.returncode


def secure_file(path):
    path = Path(path)
    for p in [path, *path.parents]:
        if p.is_symlink():
            raise Refuse("拒绝符号链接路径：" + str(p))
        if p.exists() and (p.stat().st_uid != 0 or p.stat().st_mode & 0o022):
            raise Refuse("路径必须归 root 所有且不可被其他用户写入：" + str(p))


def atomic(path, data, mode=0o600, gid=0):
    path = Path(path)
    secure_file(path)
    fd, name = tempfile.mkstemp(prefix=".new-", dir=path.parent)
    try:
        os.fchown(fd, 0, gid)
        os.fchmod(fd, mode)
        with os.fdopen(fd, "wb") as f:
            f.write(data.encode() if isinstance(data, str) else data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(name, path)
        d = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(d)
        finally:
            os.close(d)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def pack(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=False, indent=2) + "\n"


def route_parse(line):
    """Parse only unicast IPv4 routes whose attributes can be copied exactly.

    iproute2 JSON omits RTAX_LOCK and uses metrics[].congestion. Text parsing
    here deliberately preserves 'mtu lock', initcwnd/initrwnd and other metrics.
    Unknown attributes, ECMP, encapsulation and expiring routes are rejected.
    """
    tokens = shlex.split(line)
    if not tokens:
        raise Refuse("空路由。")
    dst = tokens.pop(0)
    if dst == "default":
        dst = "0.0.0.0/0"
    try:
        dst = str(ipaddress.IPv4Network(dst, strict=False))
    except ValueError as e:
        raise Refuse("非普通单播路由。") from e
    fields = {}
    simple = {"via", "dev", "src", "proto", "scope", "metric", "pref"}
    numeric = {"mtu", "advmss", "rtt", "rttvar", "window", "cwnd", "ssthresh",
               "reordering", "hoplimit", "initcwnd", "initrwnd", "rto_min", "quickack", "fastopen_no_cookie"}
    while tokens:
        key = tokens.pop(0)
        if key == "onlink":
            fields[key] = []
            continue
        if key in fields or key not in simple | numeric | {"congctl", "features"}:
            raise Refuse("路由含未支持或重复属性：" + key)
        val = []
        if tokens and tokens[0] == "lock" and key in numeric | {"congctl"}:
            val.append(tokens.pop(0))
        if not tokens:
            raise Refuse("路由属性缺值：" + key)
        val.append(tokens.pop(0))
        if key in numeric and not re.fullmatch(r"[0-9]+(?:\.[0-9]+)?(?:ms|s)?", val[-1]):
            raise Refuse("路由数值无法安全复制：" + key)
        if key in {"via", "src"}:
            try:
                ipaddress.IPv4Address(val[-1])
            except ValueError as e:
                raise Refuse("无效路由地址。") from e
        if key == "dev" and not re.fullmatch(r"[A-Za-z0-9_.:-]{1,15}", val[-1]):
            raise Refuse("无法识别接口名。")
        if key == "features" and val != ["ecn"]:
            raise Refuse("未支持的路由 features。")
        fields[key] = val
    if "dev" not in fields:
        raise Refuse("路由缺少出口接口。")
    # ip prints scope global/proto boot implicitly; normalize both forms.
    fields.setdefault("scope", ["global"])
    fields.setdefault("proto", ["3"])
    fields.setdefault("metric", ["0"])
    return {"dst": dst, "fields": fields}


def route_args(route):
    out = [route["dst"]]
    for k in sorted(route["fields"]):
        out += [k] + route["fields"][k]
    return out


class Host:
    def rules(self):
        path = Path("/proc/net/tcp_brutal/rules")
        if not path.exists():
            return {}
        result = {}
        for line in path.read_text().splitlines():
            values = dict(x.split("=", 1) for x in line.split())
            dst = str(ipaddress.ip_network(values.pop("dst")))
            result[dst] = {k: int(v) for k, v in values.items()}
        return result

    def write_rule(self, prefix, rule):
        if rule is None:
            text = "del " + prefix + "\n"
        else:
            text = "add %s rate=%s gain=%s%s\n" % (
                prefix, rule["rate"], rule.get("gain", 20), "" if rule.get("lock", 1) else " nolock")
        fd = os.open("/proc/net/tcp_brutal/rules", os.O_WRONLY)
        try:
            data = text.encode()
            if os.write(fd, data) != len(data):
                raise Refuse("Brutal 控制文件短写。")
        finally:
            os.close(fd)

    def routes(self):
        return json.loads(run(["ip", "-4", "-j", "-N", "route", "show", "table", "all"]))

    def exact(self, prefix):
        matches = [r for r in self.routes() if r.get("dst") not in (None, "default") and
                   str(ipaddress.ip_network(r["dst"], strict=False)) == prefix]
        if not matches:
            return None
        if len(matches) != 1 or str(matches[0].get("table", "254")) not in ("254", "main"):
            raise Refuse("目标已有多条或非主表主机路由；不覆盖。")
        lines = run(["ip", "-4", "-o", "-N", "route", "show", "table", "main", "exact", prefix]).splitlines()
        if len(lines) != 1:
            raise Refuse("主机路由读回不唯一。")
        return route_parse(lines[0])

    def base(self, prefix):
        addr = ipaddress.IPv4Network(prefix).network_address
        candidates = []
        for r in self.routes():
            if str(r.get("table", "254")) not in ("254", "main"):
                continue
            net = ipaddress.IPv4Network("0.0.0.0/0" if r.get("dst") == "default" else r.get("dst", "0.0.0.0/0"), strict=False)
            if net.prefixlen < 32 and addr in net:
                if r.get("type", "unicast") != "unicast":
                    raise Refuse("目标被非单播/阻断路由覆盖；不通过新增主机路由绕过它。")
                candidates.append((net.prefixlen, -int(r.get("metric", 0)), str(net), r))
        if not candidates:
            raise Refuse("没有可继承的普通 IPv4 路由。")
        candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
        best = candidates[0]
        if len(candidates) > 1 and best[:2] == candidates[1][:2]:
            raise Refuse("等价多路径路由需要专门方案。")
        lines = run(["ip", "-4", "-o", "-N", "route", "show", "table", "main", "exact", best[2]]).splitlines()
        parsed = [route_parse(line) for line in lines]
        parsed = [r for r in parsed if int(r["fields"]["metric"][0]) == -best[1]]
        if len(parsed) != 1:
            raise Refuse("基线路由读回不唯一。")
        route = parsed[0]
        dev = route["fields"]["dev"][0]
        link = json.loads(run(["ip", "-d", "-j", "link", "show", "dev", dev]))
        if len(link) != 1 or link[0].get("linkinfo", {}).get("info_kind") in {"tun", "wireguard", "gre", "ipip", "vxlan", "vrf"} or dev == "lo":
            raise Refuse("隧道、VRF 或本地出口不能套用普通 Brutal 主机路由。")
        route["dst"] = prefix
        route["fields"]["proto"] = [str(PROTO)]
        route["fields"]["metric"] = [str(METRIC)]
        route["fields"]["congctl"] = ["lock", "brutal"]
        return route

    def route_change(self, verb, route):
        run(["ip", "-4", "route", verb] + route_args(route))

    def ready(self):
        loaded = Path("/sys/module/brutal/version")
        if not loaded.exists() or loaded.read_text().strip() != VERSION:
            raise Refuse("当前内核未加载 Brutal 2.0.0；先用菜单 31 安装，再检查磁盘/已加载版本。")
        if not Path("/proc/net/tcp_brutal/rules").exists():
            raise Refuse("内核缺少 v2 规则接口。")

    def environment(self):
        self.ready()
        rules = json.loads(run(["ip", "-4", "-j", "-N", "rule", "show"]))
        expected = {(0, "255"), (32766, "254"), (32767, "253")}
        aliases = {"local": "255", "main": "254", "default": "253"}
        seen = set()
        for r in rules:
            key = (r.get("priority"), aliases.get(str(r.get("table")), str(r.get("table"))))
            if key not in expected or key in seen or r.get("src", "all") not in ("all", "0.0.0.0/0") or set(r) - {"priority", "src", "table", "protocol"}:
                raise Refuse("检测到策略路由/WARP/VRF；菜单 31 不接管该路由拓扑。")
            seen.add(key)
        if seen != expected:
            raise Refuse("IPv4 路由规则不是标准 local/main/default 三表。")
        if run(["sysctl", "-n", "net.ipv4.tcp_congestion_control"]) == "brutal":
            raise Refuse("Brutal 已被外部设置为全局算法，请先恢复原全局配置。")
        cfg = Path("/usr/local/etc/xray/config.json")
        if cfg.exists():
            def walk(v):
                if isinstance(v, dict):
                    if v.get("tcpCongestion"):
                        raise Refuse("Xray 配置含显式 tcpCongestion，与锁定 Brutal 路由可能冲突；未修改配置。")
                    for x in v.values():
                        walk(x)
                elif isinstance(v, list):
                    for x in v:
                        walk(x)
            walk(json.loads(cfg.read_text()))

    def verify(self, prefix, entry):
        live = self.rules().get(prefix)
        if not live or any(live.get(k) != entry[k] for k in ("rate", "gain", "lock")):
            raise Refuse("Brutal 规则读回失败：" + prefix)
        if self.exact(prefix) != entry["route"]:
            raise Refuse("Brutal 主机路由读回失败：" + prefix)
        got = json.loads(run(["ip", "-4", "-j", "route", "get", prefix.split("/")[0]]))
        if len(got) != 1:
            raise Refuse("目标的实际选路不唯一。")
        metrics = got[0].get("metrics", [])
        if isinstance(metrics, dict):
            metrics = [metrics]
        if not any(m.get("congestion") == "brutal" for m in metrics):
            raise Refuse("目标的新连接实际选路未选中 Brutal。")
        fields = entry["route"]["fields"]
        if got[0].get("dev") != fields["dev"][0] or got[0].get("gateway", "") != fields.get("via", [""])[0]:
            raise Refuse("实际选路出口与基线不符。")


class Manager:
    def __init__(self, root=ROOT, host=None):
        self.root = Path(root)
        self.host = host or Host()
        self.state_path = self.root / "rules.json"
        self.pending_path = self.root / "pending.json"

    def load(self):
        if not self.state_path.exists():
            return copy.deepcopy(EMPTY)
        secure_file(self.state_path)
        state = json.loads(self.state_path.read_text())
        if state.get("schema") != 1 or set(state) != {"schema", "rules"} or not isinstance(state["rules"], dict) or len(state["rules"]) > 64:
            raise Refuse("受管规则文件格式错误。")
        for p, e in state["rules"].items():
            if host_prefix(p) != p or not isinstance(e.get("rate"), int) or not 62500 <= e["rate"] <= 125000000000 or e.get("gain") != 20 or e.get("lock") != 1 or e.get("ack") != "ALL-TCP":
                raise Refuse("受管条目内容错误。")
            if e.get("route", {}).get("dst") != p:
                raise Refuse("受管路由目标不一致。")
            if route_parse(" ".join(route_args(e["route"]))) != e["route"]:
                raise Refuse("受管路由不能往返解析。")
            f = e["route"]["fields"]
            if f.get("proto") != [str(PROTO)] or f.get("metric") != [str(METRIC)] or f.get("congctl") != ["lock", "brutal"]:
                raise Refuse("受管路由所有权错误。")
        return state

    def save(self, path, obj):
        atomic(path, pack(obj))

    def ownership(self, prefix, old):
        live = self.host.rules()
        for p in live:
            if ipaddress.ip_network(p).version == 4 and ipaddress.ip_network(prefix).overlaps(ipaddress.ip_network(p)) and p != prefix:
                raise Refuse("目标与外部 Brutal 网段规则重叠：" + p)
        route = self.host.exact(prefix)
        rule = live.get(prefix)
        if not old and (route or rule):
            raise Refuse("目标已有未登记的规则或主机路由；不覆盖、不自动接管。")
        if old:
            if route is not None and route != old["route"]:
                raise Refuse("受管路由被外部修改；停止写入并保留记录。")
            if rule and any(rule.get(k) != old[k] for k in ("rate", "gain", "lock")):
                raise Refuse("受管规则被外部修改；停止写入并保留记录。")
            # Within a boot, the group ID is the ownership receipt. A missing
            # rule may be replayed after a reboot; an externally recreated one
            # with the same rate is not silently adopted.
            if rule and (old.get("boot") != boot_id() or old.get("id") != rule.get("id")):
                raise Refuse("受管规则的组 ID 已变化；未自动接管。")
        return rule, route

    def clear_pending(self):
        self.pending_path.unlink(missing_ok=True)

    def restore_runtime(self, journal):
        p = journal["prefix"]
        before_rule, before_route = journal["runtime"]
        proposal = journal["proposal"]
        live_rule = self.host.rules().get(p)
        live_route = self.host.exact(p)
        candidates = [x for x in (before_rule, proposal) if x]
        if live_rule and (journal.get("boot") != boot_id() or not any(
                x.get("id") is not None and all(live_rule.get(k) == x.get(k)
                for k in ("rate", "gain", "lock", "id")) for x in candidates)):
            raise Refuse("回滚规则缺少同次开机的组 ID 凭据，或已被外部重建；保留 pending.json。")
        if live_route and live_route not in (before_route, proposal.get("route") if proposal else None):
            raise Refuse("回滚发现外部路由变化；保留 pending.json。")
        # Restore rule before reintroducing a route: never leave a new route
        # selecting Brutal without a matching rate (upstream fallback is 1Mbps).
        if before_rule:
            self.host.write_rule(p, before_rule)
        if live_route != before_route:
            if live_route:
                self.host.route_change("del", live_route)
            if before_route:
                if self.host.base(p) != before_route:
                    raise Refuse("基线路由已变，拒绝恢复过时出口。")
                self.host.route_change("add", before_route)
        if before_rule is None and self.host.rules().get(p):
            self.host.write_rule(p, None)
        now = self.host.rules().get(p)
        if bool(now) != bool(before_rule) or (now and any(now.get(k) != before_rule.get(k) for k in ("rate", "gain", "lock"))) or self.host.exact(p) != before_route:
            raise Refuse("回滚读回未通过；保留 pending.json。")

    def recover(self):
        if not self.pending_path.exists():
            print("没有未完成的 Brutal 事务。")
            return
        secure_file(self.pending_path)
        j = json.loads(self.pending_path.read_text())
        if j.get("schema") != 1 or host_prefix(j["prefix"]) != j["prefix"]:
            raise Refuse("未完成事务格式错误。")
        state = self.load()
        if state not in (j["before"], j["after"]):
            raise Refuse("规则文件与事务日志不一致；保留现场。")
        if j.get("boot") != boot_id():
            if self.host.rules().get(j["prefix"]) or self.host.exact(j["prefix"]):
                raise Refuse("事务跨越了重启，且目标已有运行态；不接管，保留 pending。")
            self.clear_pending()
            print("事务跨越重启，已核实目标无残留运行态并保留已提交配置；请使用菜单 31→6 重放。")
            return
        if state == j["after"]:
            e = state["rules"].get(j["prefix"])
            if e:
                self.ownership(j["prefix"], e)
                self.host.verify(j["prefix"], e)
            elif self.host.rules().get(j["prefix"]) or self.host.exact(j["prefix"]):
                raise Refuse("删除事务的运行态不符；保留 pending。")
        elif state == j["before"]:
            self.restore_runtime(j)
            # A deleted then restored rule receives a new group ID.
            e = state["rules"].get(j["prefix"])
            if e and self.host.rules().get(j["prefix"]):
                e.update(id=self.host.rules()[j["prefix"]]["id"], boot=boot_id())
                self.save(self.state_path, state)
        else:
            raise Refuse("规则文件与事务日志不一致；保留现场。")
        self.clear_pending()
        print("Brutal 事务已完成读回/恢复。" + NOTICE)

    def change(self, prefix, rate=None, ack="", replay=False):
        p = host_prefix(prefix)
        if self.pending_path.exists():
            raise Refuse("存在未完成事务，请先运行 --brutal-recover。")
        state = self.load()
        old = state["rules"].get(p)
        if rate is not None:
            if not replay and ack != "ALL-TCP":
                raise Refuse("启用必须确认该目标所有 TCP（含 SSH）均受影响：ALL-TCP。")
            self.host.environment()
        before_rule, before_route = self.ownership(p, old)
        proposal = None
        if rate is not None:
            proposal = {"rate": rate_bytes(rate), "gain": 20, "lock": 1, "ack": "ALL-TCP",
                        "route": self.host.base(p), "boot": boot_id()}
            if old and old["route"] != proposal["route"]:
                raise Refuse("出口或路由参数已变化；先删除旧条目，再按新基线添加。")
            if old and before_rule and before_route and old["rate"] == proposal["rate"]:
                self.host.verify(p, old)
                return
            if len(state["rules"]) >= 64 and not old:
                raise Refuse("最多管理 64 个单独目标。")
        elif not old:
            raise Refuse("该目标不是菜单 31 登记的条目。")
        after = copy.deepcopy(state)
        if proposal:
            after["rules"][p] = proposal
        else:
            after["rules"].pop(p)
        journal = {"schema": 1, "boot": boot_id(), "prefix": p, "before": state, "after": after,
                   "proposal": proposal, "runtime": [before_rule, before_route]}
        # Durable reservation precedes EVERY kernel/route write.
        self.save(self.pending_path, journal)
        try:
            if proposal:
                self.host.write_rule(p, proposal)
                live = self.host.rules().get(p)
                if not live:
                    raise Refuse("写入后没有读到 Brutal 规则。")
                proposal["id"] = live["id"]
                self.save(self.pending_path, journal)
                if before_route is None:
                    self.host.route_change("add", proposal["route"])
                self.host.verify(p, proposal)
            else:
                # Stop selecting Brutal before deleting its rate group.
                if before_route:
                    self.host.route_change("del", before_route)
                if before_rule:
                    self.host.write_rule(p, None)
                if self.host.exact(p) or self.host.rules().get(p):
                    raise Refuse("删除后的规则/路由读回不为空。")
            self.save(self.state_path, after)
        except Exception as original:
            try:
                self.restore_runtime(journal)
                if old and self.host.rules().get(p):
                    old.update(id=self.host.rules()[p]["id"], boot=boot_id())
                self.save(self.state_path, state)
                self.clear_pending()
            except Exception as restore_error:
                raise Refuse("操作失败且回滚未完成：%s；原错误：%s；保留 %s" %
                             (restore_error, original, self.pending_path)) from original
            raise Refuse("操作失败，已恢复原规则/路由：" + str(original)) from original
        self.clear_pending()

    def reconcile(self):
        if self.pending_path.exists():
            raise Refuse("存在未完成事务；自动恢复暂停，请使用 --brutal-recover。")
        state = self.load()
        if not state["rules"]:
            return
        if not Path("/proc/net/tcp_brutal/rules").exists():
            run(["modprobe", "brutal"])
        for p, e in state["rules"].items():
            self.change(p, format(e["rate"] / 125000, ".3f").rstrip("0").rstrip("."), replay=True)

    def status(self):
        def read(path):
            p = Path(path)
            return p.read_text().strip() if p.exists() else "absent"
        print("target_version=" + VERSION + " loaded_version=" + read("/sys/module/brutal/version"))
        print("global_cc=" + run(["sysctl", "-n", "net.ipv4.tcp_congestion_control"], check=False))
        print("persistence=" + run(["systemctl", "is-enabled", UNIT + ".timer"], check=False))
        print("pending=" + str(self.pending_path.exists()).lower())
        print(NOTICE)
        state = self.load()
        live = self.host.rules()
        print("目标\tMbps总和\t新连接规则/选路\t成员连接\t归属")
        failed = self.pending_path.exists()
        for p, e in state["rules"].items():
            try:
                self.ownership(p, e)
                self.host.verify(p, e)
                check = "PASS"
            except (Refuse, OSError) as exc:
                check = "FAIL: " + str(exc).replace("\n", " ")
                failed = True
            print("%s\t%g\t%s\t%s\t菜单31" % (p, e["rate"] / 125000, check, live.get(p, {}).get("members", 0)))
        for p, e in live.items():
            if p not in state["rules"]:
                print("%s\t%g\t未接管\t%s\t外部" % (p, e["rate"] / 125000, e.get("members", 0)))
        print("实际代理吞吐/外部新SSH连接：需客户端测试；上面的 PASS 仅验证本机规则和选路。")
        return 1 if failed else 0


def boot_id():
    return Path("/proc/sys/kernel/random/boot_id").read_text().strip()


def install():
    release = os.uname().release
    match = re.match(r"(\d+)\.(\d+)", release)
    if not match or tuple(map(int, match.groups())) < (5, 10):
        raise Refuse("TCP Brutal v2 需要 Linux 5.10 或更新版本。")
    if not re.fullmatch(r"[A-Za-z0-9._+-]+", release):
        raise Refuse("内核版本字符串无效。")
    if not shutil.which("apt-get"):
        raise Refuse("此安装入口支持 Debian/Ubuntu；其他发行版可按官方方法安装 v2.0.0 后使用菜单管理。")
    for directory in ("/", "/usr/src", "/var/lib"):
        if shutil.disk_usage(directory).free < 1024 ** 3:
            raise Refuse("安装/编译前要求至少 1 GiB 可用空间：" + directory + "；不会自动清理快照。")
    if Manager().pending_path.exists():
        raise Refuse("先恢复未完成的菜单 31 事务。")
    loaded_file = Path("/sys/module/brutal/version")
    loaded = loaded_file.read_text().strip() if loaded_file.exists() else ""
    if loaded and not re.fullmatch(r"[12]\.0\.[0-9]+", loaded):
        raise Refuse("检测到未知或较新模块版本，拒绝覆盖。")
    if loaded.startswith("2.") and loaded != VERSION:
        raise Refuse("当前版本较新；不自动降级。")
    if shutil.which("modinfo"):
        disk_version = run(["modinfo", "-F", "version", "brutal"], check=False)
        if disk_version and disk_version != VERSION and not re.fullmatch(r"1\.0\.[0-9]+", disk_version):
            raise Refuse("磁盘已有未知或较新模块版本 " + disk_version + "；不自动降级。")
    print("安装官方 v2.0.0 固定提交源码；不会卸载正在使用的模块、重启 VPS 或启用任何目标。", flush=True)
    with tempfile.TemporaryDirectory(prefix="eex10-brutal-install-") as tmp:
        temp = Path(tmp)
        request = urllib.request.Request(SOURCE_URL, headers={"User-Agent": "EEX10-TCP-Brutal"})
        with urllib.request.urlopen(request, timeout=60) as response:
            data = response.read(4 * 1024 * 1024 + 1)
        if hashlib.sha256(data).hexdigest() != SOURCE_SHA256:
            raise Refuse("官方源码 SHA-256 不匹配；未执行源码或安装软件包。")
        archive = temp / "source.tar.gz"
        archive.write_bytes(data)
        with tarfile.open(archive) as tar:
            top = "tcp-brutal-" + COMMIT
            for member in tar.getmembers():
                parts = Path(member.name).parts
                if not parts or parts[0] != top or ".." in parts or member.name.startswith("/") or not (member.isdir() or member.isfile()):
                    raise Refuse("源码归档路径或文件类型不符合预期。")
            tar.extractall(temp)
        source = temp / top
        env_before = {k: os.environ.get(k) for k in ("DEBIAN_FRONTEND", "NEEDRESTART_MODE")}
        os.environ.update(DEBIAN_FRONTEND="noninteractive", NEEDRESTART_MODE="l")
        try:
            run(["apt-get", "update"], capture=False, timeout=600)
            packages = ["dkms", "build-essential", "kmod", "iproute2"]
            if not Path("/lib/modules", release, "build/Makefile").exists():
                packages.append("linux-headers-" + release)
            run(["apt-get", "install", "-y", "--no-remove", "--no-install-recommends"] + packages, capture=False, timeout=1200)
        finally:
            for k, v in env_before.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
        if not Path("/lib/modules", release, "build/Makefile").exists():
            raise Refuse("当前运行内核的 headers 不完整；未尝试替换内核。")
        dkms = source / "dkms.conf"
        # Same DKMS contract as upstream mkdkmsconf.sh, with an explicit release.
        dkms.write_text('PACKAGE_NAME="tcp-brutal"\nPACKAGE_VERSION="2.0.0"\nMAKE[0]="make KERNEL_DIR=${kernel_source_dir} all"\nCLEAN="make KERNEL_DIR=${kernel_source_dir} clean"\nBUILT_MODULE_NAME[0]="brutal"\nDEST_MODULE_LOCATION[0]="/extra"\nAUTOINSTALL="yes"\n')
        dest = Path("/usr/src/tcp-brutal-" + VERSION)
        secure_file(dest)
        if dest.exists():
            for f in ("brutal.h", "brutal_cc.c", "brutal_rules.c", "brutal_sockopt.c", "Makefile", "tools/brutalctl.c"):
                if not (dest / f).is_file() or (dest / f).read_bytes() != (source / f).read_bytes():
                    raise Refuse("现有 /usr/src 源码与官方 v2.0.0 不一致；未覆盖。")
        else:
            shutil.copytree(source, dest)
        status = run(["dkms", "status", "-m", "tcp-brutal", "-v", VERSION])
        if not status:
            run(["dkms", "add", "-m", "tcp-brutal", "-v", VERSION], capture=False, timeout=120)
        run(["dkms", "build", "-m", "tcp-brutal", "-v", VERSION, "-k", release], capture=False, timeout=1200)
        run(["dkms", "install", "-m", "tcp-brutal", "-v", VERSION, "-k", release], capture=False, timeout=300)
        tool = temp / "brutalctl"
        run(["cc", "-O2", "-Wall", "-o", str(tool), str(source / "tools/brutalctl.c")], capture=False, timeout=120)
        atomic(Path("/usr/local/bin/brutalctl"), tool.read_bytes(), 0o755)
        run(["depmod", "-a", release], capture=False, timeout=120)
        if not loaded:
            run(["modprobe", "brutal"], capture=False)
        if run(["modinfo", "-F", "version", "brutal"]) != VERSION:
            raise Refuse("磁盘模块版本读回不符。")
        if loaded and loaded != VERSION:
            raise Refuse("v2.0.0 已安装到磁盘，但内核仍运行 " + loaded + "；未强制卸载。请安排重启后再启用目标。")
        Host().ready()
        print("TCP Brutal v2.0.0 安装及内核版本读回通过；尚未新增任何规则。")


def persistence():
    """Independent of the xrv symlink: survives script replacement/old ABI restore."""
    source = globals().get("EMBEDDED_SOURCE")
    if source is None:
        source = Path(__file__).read_text()
    service = ("# EEX10 TCP Brutal manager\n[Unit]\nDescription=EEX10 managed TCP Brutal destination replay\n"
               "Wants=network-online.target\nAfter=network-online.target\n[Service]\nType=oneshot\n"
               "ExecStart=/usr/bin/python3 " + str(HELPER) + " reconcile\nTimeoutStartSec=120\nUMask=0077\n")
    timer = ("# EEX10 TCP Brutal manager\n[Unit]\nDescription=Replay checked EEX10 Brutal rules\n"
             "[Timer]\nOnBootSec=60s\nOnUnitInactiveSec=300s\nUnit=" + UNIT + ".service\n"
             "[Install]\nWantedBy=timers.target\n")
    files = [(HELPER, source, 0o700), (UNIT_DIR / (UNIT + ".service"), service, 0o644),
             (UNIT_DIR / (UNIT + ".timer"), timer, 0o644)]
    before = {}
    # Prove ownership of ALL files before replacing even the helper.
    for path, text, mode in files:
        secure_file(path)
        marker = ("#!/usr/bin/env python3\n# EEX10 managed TCP Brutal helper\n" if path == HELPER
                  else "# EEX10 TCP Brutal manager\n")
        if path.exists() and not path.read_text().startswith(marker):
            raise Refuse("同名文件属于外部配置；未覆盖：" + str(path))
        before[path] = (path.read_bytes(), path.stat().st_mode & 0o777) if path.exists() else None
        if path != HELPER:
            dropin = path.with_name(path.name + ".d")
            if dropin.exists() and any(dropin.iterdir()):
                raise Refuse("同名 systemd 单元有额外 drop-in；未覆盖。")
            fragment = run(["systemctl", "show", path.name, "-p", "FragmentPath", "--value"], check=False)
            if fragment and fragment != str(path):
                raise Refuse("同名 systemd 单元来自其他路径；未覆盖。")
    was_enabled = run(["systemctl", "is-enabled", UNIT + ".timer"], check=False)
    was_active = run(["systemctl", "is-active", UNIT + ".timer"], check=False)
    if was_enabled not in ("", "disabled", "not-found", "enabled") or was_active not in ("", "inactive", "failed", "active", "unknown"):
        raise Refuse("现有开机恢复状态无法安全接管。")
    changed = []
    try:
        HELPER.parent.mkdir(parents=True, exist_ok=True)
        for path, text, mode in files:
            changed.append(path)  # atomic() can fail after rename.
            atomic(path, text, mode)
        run(["systemctl", "daemon-reload"])
        run(["systemctl", "enable", "--now", UNIT + ".timer"])
        if run(["systemctl", "is-enabled", UNIT + ".timer"]) != "enabled" or run(["systemctl", "is-active", UNIT + ".timer"]) != "active":
            raise Refuse("开机恢复定时器读回失败。")
    except Exception as original:
        try:
            run(["systemctl", "disable", "--now", UNIT + ".timer"], check=False)
            for path in reversed(changed):
                if before[path] is None:
                    path.unlink(missing_ok=True)
                else:
                    atomic(path, *before[path])
            run(["systemctl", "daemon-reload"])
            if was_enabled == "enabled":
                run(["systemctl", "enable", UNIT + ".timer"])
            if was_active == "active":
                run(["systemctl", "start", UNIT + ".timer"])
        except Exception as rollback:
            raise Refuse("开机恢复配置失败，文件/定时器回退未完成：%s；原错误：%s" % (rollback, original)) from original
        raise Refuse("开机恢复配置失败，已回退文件并请求恢复原定时器状态；本次尚未新增目标：" + str(original)) from original


def lock():
    if os.geteuid() != 0:
        raise Refuse("修改需要 root 权限。")
    secure_file(ROOT)
    ROOT.mkdir(mode=0o700, parents=True, exist_ok=True)
    # Share the existing upgrade's lock: a timer cannot change routing during
    # an E266/EEX outer transaction. Keep both descriptors alive until exit.
    paths = [Path("/var/backups/xray-e214/.e266-auto-upgrade.lock"), ROOT / "manager.lock"]
    fds = []
    for p in paths:
        secure_file(p)
        p.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        fd = os.open(p, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
        fds.append(fd)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as e:
            raise Refuse("升级或菜单 31 事务正在运行，稍后重试。") from e
    return fds


def manual_main(args):
    if not args:
        raise Refuse("缺少 Brutal 管理操作。")
    op = args[0]
    m = Manager()
    if op == "status" and len(args) == 1:
        return m.status()
    if op == "plan" and len(args) == 3:
        p, rate = host_prefix(args[1]), rate_bytes(args[2])
        m.host.environment()
        m.ownership(p, m.load()["rules"].get(p))
        print(pack({"target": p, "total_mbps": rate / 125000, "route": m.host.base(p)}))
        print(NOTICE)
        return 0
    arities = {"install": 1, "add": 4, "del": 2, "disable": 1, "reconcile": 1, "recover": 1}
    if op not in arities or len(args) != arities[op]:
        raise Refuse("操作或参数个数错误。")
    # Validate input before creating directories/enabling persistence.
    if op == "add":
        host_prefix(args[1]); rate_bytes(args[2])
        if args[3] != "ALL-TCP":
            raise Refuse("需要 ALL-TCP 确认目标包含 SSH 在内的全部 TCP 流量。")
    if op == "del":
        host_prefix(args[1])
    fds = lock()
    try:
        if op == "install":
            install()
        elif op == "add":
            m.host.environment()
            m.ownership(host_prefix(args[1]), m.load()["rules"].get(host_prefix(args[1])))
            m.host.base(host_prefix(args[1]))
            if m.pending_path.exists():
                raise Refuse("先恢复 pending 事务。")
            persistence()
            m.change(args[1], args[2], args[3])
            print("目标规则、主机路由及持久记录已读回。" + NOTICE)
        elif op == "del":
            m.change(args[1])
            print("已删除该受管目标；其他目标/外部规则保持原样。" + NOTICE)
        elif op == "disable":
            if m.pending_path.exists():
                raise Refuse("存在未完成事务，请先运行 --brutal-recover。")
            timer_path = UNIT_DIR / (UNIT + ".timer")
            secure_file(timer_path)
            if timer_path.exists() and not timer_path.read_text().startswith("# EEX10 TCP Brutal manager\n"):
                raise Refuse("同名定时器属于外部配置；未停用。")
            # Per-target commits. On failure, retain all remaining receipts.
            for p in list(m.load()["rules"]):
                m.change(p)
                print("已删除受管目标 " + p)
            if timer_path.exists():
                run(["systemctl", "disable", "--now", UNIT + ".timer"])
                if run(["systemctl", "is-enabled", UNIT + ".timer"], check=False) in ("enabled", "enabled-runtime") or run(["systemctl", "is-active", UNIT + ".timer"], check=False) == "active":
                    raise Refuse("受管目标已删除，但开机恢复定时器仍在启用/运行。")
            print("已停止所有受管目标的新连接匹配；未卸载共享内核模块。" + NOTICE)
        elif op == "recover":
            m.recover()
        else:
            m.reconcile()
    finally:
        for fd in fds:
            os.close(fd)
    return 0



# EEX11 automatic client manager; embedded after the unchanged manual manager.
# Native API schema: XTLS/Xray-core app/stats/command/command.proto.
import contextlib
import threading

AUTO_ROOT = Path('/run/xray-brutal-eex11')
AUTO_SETTINGS = ROOT / 'auto-config.json'
AUTO_SETUP = ROOT / 'auto-setup.json'
AUTO_HELPER = Path('/usr/local/libexec/xray-brutal-eex11.py')
AUTO_UNIT = 'xray-brutal-eex11-auto.service'
AUTO_UNIT_PATH = UNIT_DIR / AUTO_UNIT
AUTO_CONFIG = Path('/usr/local/etc/xray/config.json')
AUTO_XRAY = Path('/usr/local/bin/xray')
AUTO_TTL, AUTO_INTERVAL, AUTO_CAP = 86400, 10, 64
AUTO_API = '127.0.0.1:19131'
AUTO_MARKER = '# EEX11 authenticated-client TCP Brutal automation\n'
AUTO_ERRORS = (Refuse, OSError, ValueError, KeyError, TypeError, subprocess.SubprocessError)


def checked_json(path, maximum=4 * 1024 * 1024):
    secure_file(path)
    if path.stat().st_size > maximum:
        raise Refuse('配置/状态文件超过大小上限。')
    def unique(pairs):
        obj = {}
        for k, v in pairs:
            if k in obj:
                raise Refuse('JSON 含重复键；不自动改写。')
            obj[k] = v
        return obj
    return json.loads(path.read_text(), object_pairs_hook=unique)


@contextlib.contextmanager
def auto_locked():
    """Same lock order as manual management/upgrade; no descriptor leaks."""
    if os.geteuid() != 0:
        raise Refuse('自动管理需要 root 权限。')
    fds = []
    try:
        for p in (Path('/var/backups/xray-e214/.e266-auto-upgrade.lock'), ROOT / 'manager.lock'):
            secure_file(p)
            p.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            fd = os.open(p, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
            fds.append(fd)
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as e:
                raise Refuse('升级或菜单 31 正在操作；本轮不更改规则。') from e
        yield
    finally:
        for fd in reversed(fds):
            os.close(fd)


def auto_memory_dir():
    # tmpfs is required, not merely an assumption about /run. No disk fallback.
    secure_file(AUTO_ROOT)
    probe = AUTO_ROOT if AUTO_ROOT.exists() else AUTO_ROOT.parent
    mount = run(['findmnt', '-n', '-o', 'FSTYPE', '-T', str(probe)])
    if mount.strip() != 'tmpfs':
        raise Refuse('/run 必须是 tmpfs；拒绝把自动客户端记录改存硬盘。')
    secure_file(AUTO_ROOT)
    AUTO_ROOT.mkdir(mode=0o700, parents=False, exist_ok=True)
    if AUTO_ROOT.stat().st_mode & 0o077:
        raise Refuse('自动记录目录权限须为 0700。')


def proto_fields(data):
    """Bounded protobuf wire reader. Only bytes and integer fields are used."""
    if len(data) > 4 * 1024 * 1024:
        raise Refuse('Xray API 响应过大。')
    pos = 0
    def varint():
        nonlocal pos
        value = 0
        for i in range(10):
            if pos >= len(data):
                raise Refuse('Xray API 响应截断。')
            b = data[pos]
            pos += 1
            if i == 9 and b > 1:
                raise Refuse('Xray API 整数溢出。')
            value |= (b & 127) << (i * 7)
            if not b & 128:
                return value
        raise Refuse('Xray API 整数格式错误。')
    count = 0
    while pos < len(data):
        count += 1
        if count > 65536:
            raise Refuse('Xray API 字段过多。')
        tag = varint()
        n, wire = tag >> 3, tag & 7
        if not 0 < n < 2 ** 29:
            raise Refuse('Xray API 字段编号错误。')
        if wire == 0:
            value = varint()
        elif wire in (1, 2, 5):
            size = varint() if wire == 2 else (8 if wire == 1 else 4)
            if size > len(data) - pos:
                raise Refuse('Xray API 字段长度错误。')
            value = data[pos:pos + size]
            pos += size
        else:
            raise Refuse('Xray API 不支持的 wire type。')
        yield n, wire, value


def users_stats_decode(data):
    result = {}
    for n, wire, user in proto_fields(data):
        if (n, wire) != (1, 2):
            continue
        email, ips = '', {}
        for field, kind, value in proto_fields(user):
            if (field, kind) == (1, 2):
                email = value.decode('utf-8')
                if len(email) > 512:
                    raise Refuse('Xray 用户标签过长。')
            elif (field, kind) == (2, 2):
                ip, seen = '', 0
                for f, k, v in proto_fields(value):
                    if (f, k) == (1, 2):
                        ip = v.decode('ascii')
                    elif (f, k) == (2, 0):
                        seen = v
                if ip and 0 < seen < 2 ** 63:
                    ips[ip] = max(seen, ips.get(ip, 0))
        if email:
            if email in result:
                raise Refuse('Xray API 返回重复用户标签。')
            result[email] = ips
        if len(result) > 4096:
            raise Refuse('用户数量超过自动模式上限。')
    return result


def stats_query(endpoint):
    try:
        import grpc
    except ImportError as e:
        raise Refuse('缺少 python3-grpcio；请重新运行自动模式启用入口。') from e
    options = [('grpc.max_receive_message_length', 4 * 1024 * 1024),
               ('grpc.enable_http_proxy', 0)]
    try:
        with grpc.insecure_channel(endpoint, options=options) as channel:
            call = channel.unary_unary('/xray.app.stats.command.StatsService/GetUsersStats',
                                      request_serializer=lambda x: x,
                                      response_deserializer=lambda x: x)
            # Empty request means no traffic counters and no reset.
            return users_stats_decode(call(b'', timeout=4))
    except grpc.RpcError as e:
        raise Refuse('Xray GetUsersStats 调用失败（%s）；需要提供此原生接口的 Xray 版本，'
                     '不会降级成扫描端口或读取未认证连接。' % e.code().name) from e


def reality_users(config, require_stats=False):
    users, levels, all_emails, ports = {}, set(), set(), set()
    inbounds = config.get('inbounds', [])
    if not isinstance(inbounds, list):
        raise Refuse('Xray inbounds 格式不符。')
    for inbound in inbounds:
        stream = inbound.get('streamSettings', {})
        selected = (inbound.get('protocol') == 'vless' and
                    stream.get('security') == 'reality' and
                    stream.get('network', 'tcp') in ('tcp', 'raw'))
        for client in inbound.get('settings', {}).get('clients', []):
            email = client.get('email', '')
            if email:
                if not isinstance(email, str) or len(email) > 512 or email in all_emails:
                    raise Refuse('客户端 email 必须是唯一标签；不自动修改身份或订阅。')
                all_emails.add(email)
            if not selected:
                continue
            port = inbound.get('port')
            if type(port) is not int or not 1 <= port <= 65535:
                raise Refuse('自动模式要求 Reality 入站使用单个数字端口。')
            if not email or '>>>' in email or any(ord(c) < 32 for c in email):
                raise Refuse('Reality 用户需要有效且唯一的 email 标签才能进行认证统计。')
            level = client.get('level', 0)
            if type(level) is not int or not 0 <= level <= 2 ** 32 - 1:
                raise Refuse('客户端 level 无效。')
            if require_stats:
                p = config.get('policy', {}).get('levels', {}).get(str(level), {})
                if any(p.get(k) is not True for k in ('statsUserOnline', 'statsUserUplink', 'statsUserDownlink')):
                    raise Refuse('用户统计配置发生变化；请重新启用自动模式。')
            users[email] = port
            levels.add(str(level))
            ports.add(port)
    if not users or len(users) > 4096 or len(ports) > 64:
        raise Refuse('未找到受支持的 Reality/TCP 用户，或用户/端口超过上限。')
    return users, levels


def api_endpoint(config):
    api = config.get('api', {})
    value = api.get('listen', '')
    if not isinstance(value, str) or not re.fullmatch(r'127\.0\.0\.1:[1-9][0-9]{0,4}', value):
        raise Refuse('自动模式只复用直接监听 127.0.0.1 的 Xray API；不改写外部/旧式 API。')
    if int(value.rsplit(':', 1)[1]) > 65535 or 'StatsService' not in api.get('services', []):
        raise Refuse('Xray API 缺少 StatsService 或端口无效。')
    return value


def auto_candidate(config):
    result = copy.deepcopy(config)
    users, levels = reality_users(result)
    if not result.get('api'):
        tags = {i.get('tag') for i in result.get('inbounds', []) + result.get('outbounds', [])}
        if 'eex11-brutal-api' in tags:
            raise Refuse('API tag 已被现有入站/出站占用。')
        result['api'] = {'tag': 'eex11-brutal-api', 'listen': AUTO_API, 'services': ['StatsService']}
    endpoint = api_endpoint(result)
    if int(endpoint.rsplit(':', 1)[1]) in users.values():
        raise Refuse('API 与 Reality 入站端口冲突。')
    result.setdefault('stats', {})
    policy = result.setdefault('policy', {}).setdefault('levels', {})
    for level in levels:
        p = policy.setdefault(level, {})
        for field in ('statsUserOnline', 'statsUserUplink', 'statsUserDownlink'):
            p[field] = True
    return result, endpoint


def xray_pid():
    if run(['systemctl', 'is-active', 'xray.service'], check=False) != 'active':
        raise Refuse('Xray 未处于 active 状态；暂停自动检测。')
    value = run(['systemctl', 'show', 'xray.service', '-p', 'MainPID', '--value'])
    if not re.fullmatch('[1-9][0-9]*', value):
        raise Refuse('无法验证 Xray 主进程。')
    proc = Path('/proc') / value
    if (proc / 'exe').resolve() != AUTO_XRAY.resolve():
        raise Refuse('Xray 主进程与受支持的二进制路径不符。')
    args = (proc / 'cmdline').read_bytes().decode().strip('\0').split('\0')
    configs = []
    for i, arg in enumerate(args):
        if arg in ('-confdir', '--confdir') or arg.startswith(('-confdir=', '--confdir=')):
            raise Refuse('自动模式暂不支持多配置目录启动。')
        if arg in ('-c', '-config', '--config') and i + 1 < len(args):
            configs.append(args[i + 1])
        elif arg.startswith(('-c=', '-config=', '--config=')):
            configs.append(arg.split('=', 1)[1])
    if configs != [str(AUTO_CONFIG)]:
        raise Refuse('当前 Xray 不是使用本脚本 config.json 启动；拒绝修改其他实例。')
    return int(value)


def ss_rows(text):
    if len(text) > 16 * 1024 * 1024:
        raise Refuse('TCP 连接表超过自动检测上限。')
    for line in text.splitlines():
        fields = line.split()
        if fields and fields[0] in ('ESTAB', 'LISTEN'):
            fields = fields[1:]
        if len(fields) >= 5:
            yield fields[2], fields[3], ' '.join(fields[4:])


def api_owner(endpoint, pid):
    port = endpoint.rsplit(':', 1)[1]
    listing = run(['ss', '-H', '-4', '-ltnp', 'sport', '=', ':' + port], strict_stderr=True, timeout=15)
    for local, peer, details in ss_rows(listing):
        if local == endpoint and re.search(r'\bpid=' + str(pid) + r'\b', details):
            return
    raise Refuse('统计 API 监听者不是当前 Xray 进程。')


def inbound_sockets(pid, ports):
    pairs = {}
    listing = run(['ss', '-H', '-4', '-tnpe', 'state', 'established'], strict_stderr=True, timeout=15)
    for local, peer, details in ss_rows(listing):
        if not re.search(r'\bpid=' + str(pid) + r'\b', details):
            continue
        try:
            port = int(local.rsplit(':', 1)[1])
            addr = ipaddress.IPv4Address(peer.rsplit(':', 1)[0])
        except ValueError:
            continue
        inode = re.search(r'\bino:([1-9][0-9]*)\b', details)
        if port not in ports or not addr.is_global or addr.is_multicast or not inode:
            continue
        key = (str(addr) + '/32', port)
        values = pairs.setdefault(key, set())
        if len(values) < 256:
            values.add(str(pid) + ':' + inode.group(1))
    return pairs


def auto_observe():
    config = checked_json(AUTO_CONFIG)
    users, levels = reality_users(config, require_stats=True)
    endpoint = api_endpoint(config)
    pid = xray_pid()
    api_owner(endpoint, pid)
    stats = stats_query(endpoint)
    sockets = inbound_sockets(pid, set(users.values()))
    if xray_pid() != pid:
        raise Refuse('检测过程中 Xray 已重启；本轮不使用旧统计。')
    fresh = {}
    for email, port in users.items():
        for value, seen in stats.get(email, {}).items():
            # Current upstream OnlineMap is reference-counted: an API entry
            # exists while authenticated connections are open. last_seen is
            # the last AddIP timestamp, NOT the last traffic timestamp. Never
            # discard an active long connection just because that value is old.
            try:
                addr = ipaddress.IPv4Address(value)
            except ValueError:
                continue
            if not addr.is_global or addr.is_multicast:
                continue
            p = str(addr) + '/32'
            matched = sockets.get((p, port), set())
            if matched:
                fresh.setdefault(p, set()).update(matched)
    live = {}
    for (p, port), values in sockets.items():
        live.setdefault(p, set()).update(values)
    return fresh, live


class AutoEngine:
    """IP ledger and route receipts live only on tmpfs; no history append."""
    def __init__(self, root=AUTO_ROOT, host=None):
        self.root = Path(root)
        self.manager = Manager(root, host)
        self.seen_path = self.root / 'seen.json'

    def load(self, now):
        if not self.seen_path.exists():
            return {}
        obj = checked_json(self.seen_path)
        if obj.get('schema') != 1 or obj.get('boot') != boot_id() or not isinstance(obj.get('clients'), dict):
            raise Refuse('自动记录格式或启动标识不符。')
        clients = obj['clients']
        if len(clients) > AUTO_CAP:
            raise Refuse('自动客户端数量超过上限。')
        for p, value in clients.items():
            if host_prefix(p) != p or not ipaddress.ip_network(p).network_address.is_global:
                raise Refuse('自动记录含非公网 IPv4。')
            stamp = value.get('seen')
            checked = value.get('checked', 0)
            ids = value.get('sockets')
            if type(stamp) not in (float, int) or not 0 <= stamp <= now + 1:
                raise Refuse('自动记录时间不符。')
            if type(checked) not in (float, int) or not 0 <= checked <= now + 1:
                raise Refuse('自动记录验证时间不符。')
            if not isinstance(ids, list) or len(ids) > 256 or any(not re.fullmatch(r'[1-9][0-9]*:[1-9][0-9]*', x) for x in ids):
                raise Refuse('自动连接标识格式不符。')
        return clients

    def save(self, clients):
        atomic(self.seen_path, pack({'schema': 1, 'boot': boot_id(), 'clients': clients}))

    def tick(self, fresh, live, rate, now, manual=(), diagnostic=False):
        m = self.manager
        if m.pending_path.exists():
            raise Refuse('自动规则存在未完成事务；请运行自动恢复。')
        clients = self.load(now)
        # Crash after rule commit but before seen commit: retain, then expire
        # after a complete TTL unless authenticated again. Never lose ownership.
        for p in m.load()['rules']:
            clients.setdefault(p, {'seen': now, 'sockets': []})
        added = expired = skipped = failed = 0
        desired = rate_bytes(rate)
        for p, value in list(clients.items()):
            authenticated = fresh.get(p, set())
            retained = set(value['sockets']) & live.get(p, set())
            if authenticated or retained:
                value.update(seen=now, sockets=sorted(authenticated | retained)[:256])
            else:
                value['sockets'] = []
            if now - value['seen'] >= AUTO_TTL:
                if p in m.load()['rules']:
                    m.change(p)
                del clients[p]
                expired += 1
        # Persist TTL refresh before route changes; a crash cannot forget liveness.
        self.save(clients)
        for p, ids in sorted(fresh.items()):
            host_prefix(p)
            if not ipaddress.ip_network(p).network_address.is_global:
                continue
            if p in manual:
                skipped += 1
                continue
            if p not in clients and len(clients) >= AUTO_CAP:
                skipped += 1
                continue
            try:
                entry = m.load()['rules'].get(p)
                existed = entry is not None
                checked = clients.get(p, {}).get('checked', 0)
                if not existed or entry['rate'] != desired or now - checked >= 300:
                    m.change(p, rate, 'ALL-TCP')
                    checked = now
                clients[p] = {'seen': now, 'sockets': sorted(ids)[:256], 'checked': checked}
                self.save(clients)
                added += int(not existed)
            except AUTO_ERRORS as exc:
                failed += 1
                if diagnostic:
                    print('[WARN] 自动目标 %s 未应用：%s' % (p, exc))
                if m.pending_path.exists():
                    raise
        # Keep rate changes/replay working for retained long-lived connections.
        for p in set(clients) - set(fresh):
            entry = m.load()['rules'].get(p)
            if not entry:
                continue
            try:
                if entry['rate'] != desired or now - clients[p].get('checked', 0) >= 300:
                    m.change(p, rate, 'ALL-TCP')
                    clients[p]['checked'] = now
                    self.save(clients)
            except AUTO_ERRORS as exc:
                failed += 1
                if diagnostic:
                    print('[WARN] 自动目标 %s 未更新：%s' % (p, exc))
                if m.pending_path.exists():
                    raise
        return {'clients': len(clients), 'added': added, 'expired': expired,
                'skipped': skipped, 'failed': failed}


def auto_settings():
    if not AUTO_SETTINGS.exists():
        return None
    obj = checked_json(AUTO_SETTINGS, 16384)
    if obj.get('schema') != 1 or type(obj.get('enabled')) is not bool or obj.get('ack') != 'AUTO-BRUTAL':
        raise Refuse('自动模式设置格式错误。')
    rate_bytes(obj['mbps'])
    return obj


def auto_unit_check():
    secure_file(AUTO_UNIT_PATH)
    if AUTO_UNIT_PATH.exists() and not AUTO_UNIT_PATH.read_text().startswith(AUTO_MARKER):
        raise Refuse('同名自动服务不属于本脚本；未接管。')
    drop = AUTO_UNIT_PATH.with_name(AUTO_UNIT + '.d')
    if drop.exists() and any(drop.iterdir()):
        raise Refuse('自动服务存在额外 drop-in；未接管。')
    fragment = run(['systemctl', 'show', AUTO_UNIT, '-p', 'FragmentPath', '--value'], check=False)
    if fragment and fragment != str(AUTO_UNIT_PATH):
        raise Refuse('自动服务来自外部路径；未接管。')


def auto_unit_text():
    return (AUTO_MARKER + '[Unit]\nDescription=Authenticated Reality clients TCP Brutal manager\n'
            'Wants=network-online.target xray.service\nAfter=network-online.target xray.service\n'
            '[Service]\nType=simple\nExecStart=/usr/bin/python3 ' + str(AUTO_HELPER) + ' auto-daemon\n'
            'Restart=on-failure\nRestartSec=30\nTimeoutStopSec=90\nUMask=0077\n'
            'StandardOutput=null\nStandardError=null\n'
            '[Install]\nWantedBy=multi-user.target\n')


def auto_tick(diagnostic=False):
    with auto_locked():
        settings = auto_settings()
        if not settings or not settings['enabled']:
            return False
        if AUTO_SETUP.exists() or Manager().pending_path.exists():
            raise Refuse('配置/手动管理事务未完成；暂停自动模式。')
        auto_memory_dir()
        fresh, live = auto_observe()  # Failure is not interpreted as all offline.
        if not Path('/proc/net/tcp_brutal/rules').exists():
            if run(['modinfo', '-F', 'version', 'brutal']) != VERSION:
                raise Refuse('当前内核未安装 Brutal v2.0.0。')
            run(['modprobe', 'brutal'])
        Host().environment()
        result = AutoEngine().tick(fresh, live, settings['mbps'], time.monotonic(), Manager().load()['rules'], diagnostic)
        result.update(state='ok' if not result['failed'] else 'partial-rule-conflict', epoch=int(time.time()))
        atomic(AUTO_ROOT / 'status.json', pack(result))
        return True


def auto_daemon():
    stop = threading.Event()
    for sig in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP):
        signal.signal(sig, lambda signum, frame: stop.set())
    while not stop.is_set():
        try:
            if not auto_tick():
                return 0
        except AUTO_ERRORS as exc:
            # No IPs, user emails, command output, or append-only logs here.
            try:
                if AUTO_ROOT.exists():
                    atomic(AUTO_ROOT / 'status.json', pack({'state': 'paused',
                           'error_type': type(exc).__name__, 'epoch': int(time.time())}))
            except AUTO_ERRORS:
                pass
        stop.wait(AUTO_INTERVAL)
    return 0


def snapshot(path):
    secure_file(path)
    return {'hex': path.read_bytes().hex(), 'mode': path.stat().st_mode & 0o777,
            'gid': path.stat().st_gid} if path.exists() else None


def file_hash(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None


def auto_setup_restore():
    if not AUTO_SETUP.exists():
        return
    j = checked_json(AUTO_SETUP, 16 * 1024 * 1024)
    allowed = {str(p) for p in (AUTO_CONFIG, AUTO_SETTINGS, AUTO_HELPER, AUTO_UNIT_PATH)}
    if j.get('schema') != 1 or set(j.get('files', {})) != allowed:
        raise Refuse('自动启用事务日志格式错误；保留现场。')
    auto_unit_check()
    for name, entry in j['files'].items():
        p = Path(name)
        secure_file(p)
        before = entry['before']
        old_hash = hashlib.sha256(bytes.fromhex(before['hex'])).hexdigest() if before else None
        if file_hash(p) not in (old_hash, entry['after']):
            raise Refuse('自动启用事务文件已被外部修改；不覆盖，保留现场。')
    if AUTO_UNIT_PATH.exists():
        run(['systemctl', 'disable', '--now', AUTO_UNIT])
    for name, entry in reversed(list(j['files'].items())):
        path, before = Path(name), entry['before']
        if before is None:
            path.unlink(missing_ok=True)
        else:
            atomic(path, bytes.fromhex(before['hex']), before['mode'], gid=before['gid'])
    run(['systemctl', 'daemon-reload'])
    if j['config_changed']:
        run(['systemctl', 'restart', 'xray.service'], timeout=60)
        xray_pid()
    if j['enabled']:
        run(['systemctl', 'enable', AUTO_UNIT])
    if j['active']:
        run(['systemctl', 'start', AUTO_UNIT])
    enabled = run(['systemctl', 'is-enabled', AUTO_UNIT], check=False)
    active = run(['systemctl', 'is-active', AUTO_UNIT], check=False)
    if (enabled in ('enabled', 'enabled-runtime')) != j['enabled'] or (active == 'active') != j['active']:
        raise Refuse('自动服务回退状态读回不符；保留事务日志。')
    AUTO_SETUP.unlink()


def auto_probe(endpoint):
    last = None
    for attempt in range(10):
        try:
            pid = xray_pid()
            api_owner(endpoint, pid)
            return stats_query(endpoint)
        except AUTO_ERRORS as exc:
            last = exc
            if 'UNIMPLEMENTED' in str(exc):
                raise
            if attempt != 9:
                time.sleep(0.5)
    raise Refuse('Xray 重启后统计接口未就绪：' + str(last))


def auto_enable(rate, ack):
    rate_bytes(rate)
    if ack != 'AUTO-BRUTAL':
        raise Refuse('需确认首次可能重启 Xray、安装依赖、每 IP 全部 TCP 共享速率：AUTO-BRUTAL。')
    with auto_locked():
        auto_memory_dir()
        auto_unit_check()
        if AUTO_SETUP.exists() or AutoEngine().manager.pending_path.exists() or Manager().pending_path.exists():
            raise Refuse('存在未完成事务；先使用菜单 31 的恢复入口。')
        Host().environment()
        secure_file(AUTO_XRAY)
        xray_pid()
        current = checked_json(AUTO_CONFIG)
        candidate, endpoint = auto_candidate(current)
        config_changed = candidate != current
        try:
            import grpc
        except ImportError:
            if not shutil.which('apt-get'):
                raise Refuse('请为 /usr/bin/python3 安装 grpcio 后重试。')
            print('安装 Debian/Ubuntu 的 python3-grpcio；不升级 Xray 或内核。', flush=True)
            previous = {k: os.environ.get(k) for k in ('DEBIAN_FRONTEND', 'NEEDRESTART_MODE')}
            os.environ.update(DEBIAN_FRONTEND='noninteractive', NEEDRESTART_MODE='l')
            try:
                run(['apt-get', 'install', '-y', '--no-remove', '--no-install-recommends', 'python3-grpcio'],
                    capture=False, timeout=600)
            finally:
                for k, v in previous.items():
                    if v is None:
                        os.environ.pop(k, None)
                    else:
                        os.environ[k] = v
            import importlib
            importlib.invalidate_caches()
            try:
                import grpc
            except ImportError as e:
                raise Refuse('grpcio 仍不可用；请确认使用 /usr/bin/python3。') from e
        # Test without touching the active config; do not expose private keys.
        with tempfile.TemporaryDirectory(prefix='config-test-', dir=AUTO_ROOT) as tmp:
            trial = Path(tmp) / 'config.json'
            atomic(trial, pack(candidate))
            run([str(AUTO_XRAY), 'run', '-test', '-config', str(trial)], timeout=30)
        source = globals().get('EMBEDDED_SOURCE')
        if source is None:
            source = Path(__file__).read_text()
        secure_file(AUTO_HELPER)
        if AUTO_HELPER.exists() and not AUTO_HELPER.read_text().startswith('#!/usr/bin/env python3\n# EEX10 managed TCP Brutal helper\n'):
            raise Refuse('自动 helper 路径已被其他程序占用。')
        before_enabled = run(['systemctl', 'is-enabled', AUTO_UNIT], check=False)
        before_active = run(['systemctl', 'is-active', AUTO_UNIT], check=False)
        if before_enabled not in ('', 'enabled', 'disabled', 'not-found') or before_active not in ('', 'active', 'inactive', 'failed', 'unknown'):
            raise Refuse('自动服务状态不支持安全接管。')
        settings = {'schema': 1, 'enabled': True, 'mbps': str(rate), 'ack': ack}
        files = [(AUTO_CONFIG, pack(candidate).encode() if config_changed else AUTO_CONFIG.read_bytes(),
                  AUTO_CONFIG.stat().st_mode & 0o777, AUTO_CONFIG.stat().st_gid),
                 (AUTO_HELPER, source.encode(), 0o700, 0), (AUTO_UNIT_PATH, auto_unit_text().encode(), 0o644, 0),
                 (AUTO_SETTINGS, pack(settings).encode(), 0o600, 0)]
        journal = {'schema': 1, 'files': {}, 'config_changed': config_changed,
                   'enabled': before_enabled == 'enabled', 'active': before_active == 'active'}
        for p, data, mode, gid in files:
            journal['files'][str(p)] = {'before': snapshot(p), 'after': hashlib.sha256(data).hexdigest()}
        atomic(AUTO_SETUP, pack(journal))
        try:
            if AUTO_UNIT_PATH.exists():
                run(['systemctl', 'stop', AUTO_UNIT], timeout=90)
            AUTO_HELPER.parent.mkdir(mode=0o755, parents=True, exist_ok=True)
            for p, data, mode, gid in files:
                atomic(p, data, mode, gid=gid)
            run(['systemctl', 'daemon-reload'])
            if config_changed:
                print('启用认证统计，重启一次 Xray；UUID、Reality 密钥及 bufferSize 保持不变。', flush=True)
                run(['systemctl', 'restart', 'xray.service'], timeout=60)
            auto_probe(endpoint)
            run(['systemctl', 'enable', '--now', AUTO_UNIT], timeout=60)
            if run(['systemctl', 'is-enabled', AUTO_UNIT]) != 'enabled' or run(['systemctl', 'is-active', AUTO_UNIT]) != 'active':
                raise Refuse('自动服务启用读回失败。')
        except Exception as original:
            try:
                auto_setup_restore()
            except Exception as rollback:
                raise Refuse('自动启用失败且回退未完成；保留 auto-setup.json，请运行 --brutal-auto-recover。'
                             ' 原因：%s；回退：%s' % (original, rollback)) from original
            raise Refuse('自动启用失败，已恢复原配置/服务；未新增自动目标。原因：' + str(original)) from original
        AUTO_SETUP.unlink()
    # Full first detection is synchronous and visible; service is already ready.
    print('自动服务已启用：每轮后间隔 10 秒，失活 24 小时清理，最多 64 个公网 IPv4；记录仅存 /run。')
    print('等待客户端认证流量；首次识别后新建的 TCP 连接才会匹配 Brutal。' + NOTICE)
    try:
        auto_tick(diagnostic=True)
    except AUTO_ERRORS as exc:
        print('[WARN] 服务已启用，但首次检测未通过：' + str(exc))


def auto_disable():
    with auto_locked():
        auto_unit_check()
        if AUTO_SETUP.exists():
            raise Refuse('自动启用事务未完成；先运行 --brutal-auto-recover。')
        settings = auto_settings()
        if settings:
            settings['enabled'] = False
            atomic(AUTO_SETTINGS, pack(settings))
        if AUTO_UNIT_PATH.exists():
            run(['systemctl', 'disable', '--now', AUTO_UNIT], timeout=90)
            if (run(['systemctl', 'is-active', AUTO_UNIT], check=False) == 'active' or
                run(['systemctl', 'is-enabled', AUTO_UNIT], check=False) in ('enabled', 'enabled-runtime')):
                raise Refuse('自动服务尚未停止；不清理运行中规则。')
        m = AutoEngine().manager
        if m.pending_path.exists():
            raise Refuse('自动规则事务未完成；服务已暂停，请运行 --brutal-auto-recover 后再次关闭。')
        for p in list(m.load()['rules']):
            m.change(p)
        for name in ('seen.json', 'rules.json', 'status.json'):
            path = AUTO_ROOT / name
            secure_file(path)
            path.unlink(missing_ok=True)
    print('已停止自动模式并清理其记录、规则和路由；手动目标不受影响。')
    print('本地 StatsService 配置保留，未再次重启 Xray；未更改原有访问日志配置。' + NOTICE)


def auto_status():
    settings = auto_settings()
    print('自动模式：' + ('未配置' if not settings else ('开启' if settings['enabled'] else '关闭')))
    print('每轮后间隔 10 秒；失活 24 小时清理；最多 64 个 IPv4；记录在 /run（重启后重新识别）。')
    service = run(['systemctl', 'is-active', AUTO_UNIT], check=False)
    print('service=' + service)
    print('setup_pending=' + str(AUTO_SETUP.exists()).lower())
    if settings:
        print('每个公网 IP 全部 TCP 共享 Mbps=' + settings['mbps'])
    status = AUTO_ROOT / 'status.json'
    observation = None
    if status.exists():
        observation = checked_json(status, 16384)
        print(pack(observation).strip())
    engine = AutoEngine()
    now = time.monotonic()
    seen = engine.load(now)
    bad = AUTO_SETUP.exists() or engine.manager.pending_path.exists()
    if settings and settings['enabled']:
        bad = bad or service != 'active' or not observation
        if observation:
            bad = bad or observation.get('state') != 'ok' or time.time() - observation.get('epoch', 0) > 600
    print('目标\t失活秒数\t规则/路由')
    for p, entry in engine.manager.load()['rules'].items():
        try:
            engine.manager.ownership(p, entry)
            engine.manager.host.verify(p, entry)
            valid = '已验证（不代表测速已达标）'
        except AUTO_ERRORS as exc:
            valid, bad = str(exc), True
        idle = int(max(0, now - seen[p]['seen'])) if p in seen else '待校准'
        print('%s\t%s\t%s' % (p, idle, valid))
    print('检测异常时暂停新增/过期清理；使用 --brutal-auto-tick 获取具体原因。')
    return 1 if bad else 0


def main(args):
    if args and args[0].startswith('auto-'):
        op = args[0]
        arities = {'auto-enable': 3, 'auto-status': 1, 'auto-disable': 1,
                   'auto-tick': 1, 'auto-recover': 1, 'auto-daemon': 1}
        if op not in arities or len(args) != arities[op]:
            raise Refuse('自动模式参数错误。')
        if op == 'auto-status':
            return auto_status()
        if op == 'auto-enable':
            auto_enable(args[1], args[2])
        elif op == 'auto-disable':
            auto_disable()
        elif op == 'auto-tick':
            if not auto_tick(diagnostic=True):
                raise Refuse('自动模式未开启。')
            return auto_status()
        elif op == 'auto-daemon':
            return auto_daemon()
        else:
            with auto_locked():
                auto_setup_restore()
                AutoEngine().manager.recover()
            print('自动事务恢复检查完成；关闭意图不会被自动重新开启。')
        return 0
    if args == ['disable'] and (AUTO_SETTINGS.exists() or AUTO_UNIT_PATH.exists() or AUTO_ROOT.exists()):
        auto_disable()
    return manual_main(args)


if __name__ == "__main__":
    def interrupted(signum, frame):
        raise Refuse("收到信号 %s；由事务恢复逻辑处理，未完成时保留 pending.json。" % signum)
    signal.signal(signal.SIGTERM, interrupted)
    signal.signal(signal.SIGHUP, interrupted)
    try:
        sys.exit(main(sys.argv[1:]))
    except (Refuse, OSError, ValueError, KeyError, TypeError, subprocess.SubprocessError) as exc:
        print("[ERROR] TCP Brutal: " + str(exc), file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("[ERROR] TCP Brutal: 已中断；如存在 pending.json 请运行 --brutal-recover。", file=sys.stderr)
        sys.exit(130)
EEX10_BRUTAL_PY
}
